import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {
    addClientsToGroup,
    fetchClientGroups,
    fetchClientsFromGroup,
    fetchUngroupedClients,
    fetchUngroupedCount,
    moveClientToGroup
} from "../../store/client-group/clientGroupReducer";
import {
    selectClientGroupGroupClientsLoading,
    selectClientGroupGroupsLoading,
    selectClientGroupMutationLoading,
    selectClientGroupUngroupedLoading,
    selectClientGroups,
    selectGroupClients,
    selectUngroupedClients,
    selectUngroupedPagination
} from "../../store/client-group/clientGroupSelector";
import {useEffect, useMemo, useState} from "react";
import Modal from "react-bootstrap/Modal";
import {ErrorMessage, Form, Formik} from "formik";
import * as Yup from "yup";
import LoadingBlock from "../../components/loader/LoadingBlock";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import clientEnUS from "../client/locales/en-us.json";
import clientPtBR from "../client/locales/pt-br.json";
import clientEsES from "../client/locales/es-es.json";
import clientPtPT from "../client/locales/pt-pt.json";
import CardButton from "../../components/card/CardButton";
import he from "he";
import EmptySet from "../../components/empty-set/EmptySet";
import Pagination from "../../components/pagination/Pagination";
import Avatar from "../../components/avatar/Avatar";
import ClientRemoteMultiSelect from "../../components/client/ClientRemoteMultiSelect";

const ClientGroup = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id} = useParams();

    const isUngroupedView = id === "ungrouped";
    const clientGroupList = useSelector(selectClientGroups);
    const groupClients = useSelector(selectGroupClients);
    const ungroupedClients = useSelector(selectUngroupedClients);
    const ungroupedPagination = useSelector(selectUngroupedPagination);
    const groupsLoading = useSelector(selectClientGroupGroupsLoading);
    const groupClientsLoading = useSelector(selectClientGroupGroupClientsLoading);
    const ungroupedLoading = useSelector(selectClientGroupUngroupedLoading);
    const mutationLoading = useSelector(selectClientGroupMutationLoading);

    const [showAddModal, setShowAddModal] = useState(false);
    const [selectedClientToMove, setSelectedClientToMove] = useState(null);
    const [destinationGroupId, setDestinationGroupId] = useState("");
    const [searchTerm, setSearchTerm] = useState("");
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
    const [page, setPage] = useState(1);

    useComponentTranslations("clientGroup", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    useComponentTranslations("client", {"en-US": clientEnUS, "pt-BR": clientPtBR, "es-ES": clientEsES, "pt-PT": clientPtPT});

    const currentGroup = useMemo(() => {
        if (isUngroupedView) {
            return {
                id: "ungrouped",
                nome: t("client:ungrouped")
            };
        }

        return clientGroupList?.find((clientGroup) => clientGroup.id === Number(id)) || null;
    }, [clientGroupList, id, isUngroupedView, t]);

    const currentGroupTitle = useMemo(() => {
        if (!currentGroup) {
            return t("client:groupsTab");
        }

        if (currentGroup.idUser === 0 && currentGroup.nome_i18n) {
            return t(`client:${currentGroup.nome_i18n}`);
        }

        return currentGroup.nome;
    }, [currentGroup, t]);

    const displayedClients = useMemo(() => {
        if (isUngroupedView) {
            return ungroupedClients || [];
        }

        return groupClients || [];
    }, [groupClients, isUngroupedView, ungroupedClients]);

    const groupOptions = useMemo(() => {
        const baseGroups = (clientGroupList || [])
            .filter((clientGroup) => clientGroup.id !== Number(id))
            .map((clientGroup) => ({
                value: clientGroup.id,
                label: clientGroup.idUser === 0 ? t(`client:${clientGroup.nome_i18n}`) : clientGroup.nome
            }));

        if (isUngroupedView) {
            return baseGroups;
        }

        return [...baseGroups, {
            value: "ungrouped",
            label: t("client:ungrouped")
        }];
    }, [clientGroupList, id, isUngroupedView, t]);

    const validationSchema = Yup.object().shape({
        clients: Yup.array().min(1, `${t("clientGroup:oneClientIsRequired")}`).required(`${t("clientGroup:requiredField")}`)
    });

    const handleGoBack = () => {
        navigate("/user/client/list?tab=groups");
    };

    const handleSubmit = (values) => {
        if (!currentGroup || isUngroupedView) {
            return;
        }

        dispatch(addClientsToGroup({
            clients: values.clients,
            id: currentGroup.id
        }));
        setShowAddModal(false);
    };

    const handleMoveClient = () => {
        if (!selectedClientToMove || !destinationGroupId) {
            return;
        }

        dispatch(moveClientToGroup({
            clientId: selectedClientToMove.id,
            toGroupId: destinationGroupId === "ungrouped" ? 0 : Number(destinationGroupId),
            sourceGroupId: isUngroupedView ? "ungrouped" : currentGroup?.id
        }));

        setSelectedClientToMove(null);
        setDestinationGroupId("");
    };

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 300);

        return () => clearTimeout(handler);
    }, [searchTerm]);

    useEffect(() => {
        setSearchTerm("");
        setDebouncedSearchTerm("");
        setPage(1);
    }, [id]);

    useEffect(() => {
        if (!clientGroupList) {
            dispatch(fetchClientGroups());
        }
    }, [clientGroupList, dispatch]);

    useEffect(() => {
        if (isUngroupedView) {
            dispatch(fetchUngroupedClients({
                page,
                pageSize: 20,
                search: debouncedSearchTerm
            }));
            return;
        }

        if (id) {
            dispatch(fetchClientsFromGroup(Number(id)));
        }
    }, [debouncedSearchTerm, dispatch, id, isUngroupedView, page]);

    useEffect(() => {
        if (isUngroupedView) {
            dispatch(fetchUngroupedCount());
        }
    }, [dispatch, isUngroupedView]);

    const isPageLoading = groupsLoading || (isUngroupedView ? ungroupedLoading : groupClientsLoading);

    return (
        <Page title={currentGroupTitle} goBackLink={handleGoBack} mt={"mt-n5"}>
            <div className={"card card-body"}>
                {!isUngroupedView && (
                    <div className={"row justify-content-center d-flex"}>
                        <div className={"col-12"}>
                            <CardButton
                                handleClick={() => setShowAddModal(true)}
                                icon={"fa-regular fa-users"}
                                text={t("clientGroup:addClients")}
                                ps={"ps-1"}
                            />
                        </div>
                    </div>
                )}

                {isUngroupedView && (
                    <div className={"row mt-2"}>
                        <div className={"col-12"}>
                            <div className={"input-group"}>
                                <input
                                    className={"form-control"}
                                    value={searchTerm}
                                    onChange={(event) => {
                                        setSearchTerm(event.target.value);
                                        setPage(1);
                                    }}
                                    placeholder={t("client:searchClient")}
                                />
                                <span className={"input-group-text bg-white"}>
                                    <i className={"fa-regular fa-magnifying-glass"}></i>
                                </span>
                            </div>
                        </div>
                    </div>
                )}

                <div className={"row justify-content-center d-flex mt-3"}>
                    <div className={"col-12 mb-2"}>
                        <span className={"fw-semibold"}>
                            {isUngroupedView ? t("client:clientsWithoutGroup") : t("clientGroup:clientsOnThisGroup")}
                        </span>
                    </div>

                    {isPageLoading && <LoadingBlock height={"200px"}/>}

                    {!isPageLoading && displayedClients.length === 0 && (
                        <div className={"col-12"}>
                            <EmptySet
                                icon={debouncedSearchTerm ? "fa-magnifying-glass" : "fa-users"}
                                message={debouncedSearchTerm ? t("client:emptySearchResult") : t("client:noClientsInGroup")}
                            />
                        </div>
                    )}

                    {!isPageLoading && displayedClients.length > 0 && (
                        <div className={"col-12"}>
                            <ul className={"list-group"}>
                                {displayedClients.map((client) => (
                                    <li key={client.id} className={"list-group-item border-0 bg-white border-bottom rounded-0 mb-2"}>
                                        <div className={"d-flex align-items-center gap-3"}>
                                            <div className={"flex-shrink-0 text-center"}>
                                                <Avatar url={client.profileUrl} maxWidth={"44px"}/>
                                            </div>
                                            <div className={"flex-grow-1 text-break"}>
                                                <span className={"d-block fw-semibold"}>{he.decode(client.nome)} {he.decode(client.sobrenome || "")}</span>
                                                {client.grupo?.nome && !isUngroupedView && (
                                                    <span className={"small text-secondary"}>{client.grupo.nome}</span>
                                                )}
                                            </div>
                                            <div className={"flex-shrink-0 text-end "}>
                                                <button
                                                    className={"btn btn-link btn-sm text-decoration-none fw-semibold p-0 text-nowrap"}
                                                    onClick={() => {
                                                        setSelectedClientToMove(client);
                                                        setDestinationGroupId("");
                                                    }}
                                                >
                                                    {t("client:changeGroup")}
                                                </button>
                                            </div>
                                        </div>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {!isPageLoading && isUngroupedView && ungroupedPagination.totalItems > ungroupedPagination.pageSize && (
                        <div className={"col-12 pt-3"}>
                            <Pagination
                                currentPage={page}
                                totalItems={ungroupedPagination.totalItems}
                                itemsPerPage={ungroupedPagination.pageSize}
                                onPageChange={setPage}
                                pagesToShow={5}
                            />
                        </div>
                    )}
                </div>
            </div>

            <Modal centered show={showAddModal} onHide={() => setShowAddModal(false)}>
                <Modal.Body>
                    <div className={"row"}>
                        <div className={"col-12"}>
                            <span className={"fw-semibold fs-5"}>
                                {t("clientGroup:addClients")}
                            </span>
                        </div>
                        <div className={"col-12 pt-4"}>
                            <Formik
                                key={`${currentGroup?.id || "group"}-${showAddModal}`}
                                initialValues={{clients: []}}
                                validationSchema={validationSchema}
                                onSubmit={handleSubmit}
                            >
                                {({setFieldValue, values}) => (
                                    <Form>
                                        <div>
                                            <label htmlFor={"clients"} className={"form-label fw-semibold"}>{t("client:clientsTab")}</label>
                                            <ClientRemoteMultiSelect
                                                valueIds={values.clients}
                                                onChangeIds={(clientIds) => setFieldValue("clients", clientIds)}
                                                scope={"active"}
                                                placeholder={t("client:select")}
                                                noOptionsMessage={() => t("client:emptySearchResult")}
                                                disabled={mutationLoading}
                                            />
                                            <ErrorMessage name={"clients"} component={"div"} className={"error-message"}/>
                                        </div>
                                        <div className={"d-grid"}>
                                            <button type={"submit"} className={"btn btn-primary mt-3"} disabled={mutationLoading}>{t("clientGroup:submit")}</button>
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>

            <Modal centered show={Boolean(selectedClientToMove)} onHide={() => setSelectedClientToMove(null)}>
                <Modal.Body>
                    <div className={"row"}>
                        <div className={"col-12 pb-2"}>
                            <span className={"fw-semibold fs-5"}>{t("client:moveToGroup")}</span>
                        </div>
                        <div className={"col-12"}>
                            <label className={"form-label fw-semibold"}>{selectedClientToMove ? `${he.decode(selectedClientToMove.nome)} ${he.decode(selectedClientToMove.sobrenome || "")}` : ""}</label>
                            <select
                                className={"form-control"}
                                value={destinationGroupId}
                                onChange={(event) => setDestinationGroupId(event.target.value)}
                            >
                                <option value={""}>{t("client:select")}</option>
                                {groupOptions.map((option) => (
                                    <option key={option.value} value={option.value}>
                                        {option.label}
                                    </option>
                                ))}
                            </select>
                        </div>
                        <div className={"col-12 d-grid mt-3"}>
                            <button className={"btn btn-primary"} disabled={!destinationGroupId || mutationLoading} onClick={handleMoveClient}>
                                {t("client:save")}
                            </button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </Page>
    );
};

export default ClientGroup;
