import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    summarizedAnamnesis: null,
    generatedWorkout: null,
    aiPush: null,
    aiError: false,
    evaluationAnalysis: null,
    waiting: false,
    loading: false,
}

export const slice = createSlice({
    name: "aiActions",
    initialState,
    reducers: {
        generateWorkout(state) {
            state.waiting = true;
        },
        setGeneratedWorkout(state, action) {
            state.generatedWorkout = action.payload;
            state.waiting = false;
        },
        summarizeAnamnesis(state) {
            state.waiting = true;
        },
        setSummarizedAnamnesis(state, action) {
            state.summarizedAnamnesis = action.payload;
            state.waiting = false;
        },
        generateAiPush(state) {
            state.waiting = true;
            state.aiPush = null;
            state.aiError = false;
        },
        setAiPush(state, action) {
            state.aiPush = action.payload;
            state.waiting = false;
        },
        clearAiPush(state) {
            state.aiPush = null;
        },
        setAiError(state, action) {
          state.aiError = action.payload;
          state.waiting = false;
          state.loading = false;
        },
        evaluationAnalysis(state) {
            state.waiting = true;
        },
        setEvaluationAnalysis(state, action) {
            state.evaluationAnalysis = action.payload;
            state.waiting = false;
        },
        onError(state) {
            state.loading = false;
            state.waiting = false;
        }
    }
})

export const {
    summarizeAnamnesis,
    setSummarizedAnamnesis,
    generateAiPush, setAiPush, clearAiPush,
    generateWorkout,
    setGeneratedWorkout,
    setEvaluationAnalysis,
    evaluationAnalysis,
    setAiError,
    onError
} = slice.actions;

export const aiActionsReducer = slice.reducer;
