import RoundedIcon from "../rounded-icon/RoundedIcon";
import WorkoutLibraryCreateModal from "./WorkoutLibraryCreateModal";
import {useDispatch, useSelector} from "react-redux";
import {
    selectCurrentFolder,
    selectCurrentFolderLoading,
    selectFoldersList,
    selectFoldersListLoading
} from "../../store/workout-library/workoutLibrarySelector";
import _ from "lodash";
import LoadingBlock from "../loader/LoadingBlock";
import WorkoutLibraryItem from "./WorkoutLibraryItem";
import {useEffect, useState} from "react";
import {
    fetchCurrentFolder,
    fetchFoldersList,
    setCurrentFolder,
    setFoldersList
} from "../../store/workout-library/workoutLibraryReducer";
import WorkoutLibrarySearchModal from "./WorkoutLibrarySearchModal";
import WorkoutLibraryWorkoutItem from "./WorkoutLibraryWorkoutItem";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Pagination from "../../components/pagination/Pagination";

const WorkoutLibraryRoutines = ({type}) => {
    const {t} = useTranslation()
    const dispatch = useDispatch();
    const folderList = useSelector(selectFoldersList);
    const isFolderListLoading = useSelector(selectFoldersListLoading);
    const folder = useSelector(selectCurrentFolder);
    const isFolderLoading = useSelector(selectCurrentFolderLoading);
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [showSearchBox, setShowSearchBox] = useState(false);

    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(10);
    const pagesToShow = 5;

    useComponentTranslations('trainingLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleShowSearchBox = () => {
        setShowSearchBox(prevState => !prevState)
    }

    const handleShowCreateModal = () => {
        setShowCreateModal(prevState => !prevState)
    }

    useEffect(() => {
        dispatch(fetchFoldersList(type))
        dispatch(fetchCurrentFolder({id: 0, type: type}))
        return () => {
            dispatch(setFoldersList(null))
            dispatch(setCurrentFolder(null))
        }
    }, [dispatch, type]);

    const sortedFolders = folderList?.slice().sort((a, b) => a.name.localeCompare(b.name));

    const totalItems = folder?.treinos?.length || 0;
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentItems = folder?.treinos?.slice(indexOfFirstItem, indexOfLastItem);

    useEffect(() => {
        const totalPages = Math.ceil(totalItems / itemsPerPage);
        if (currentPage > totalPages && totalPages > 0) {
            setCurrentPage(totalPages);
        }
    }, [currentPage, totalItems, itemsPerPage]);

    return (
        <>
            {
                !isFolderListLoading && (folder?.treinos.length > 0 || folderList?.length > 0) &&
                <div className={'card card-body border-0 mt-3'}>
                    <div className={"row"}>
                        <div className={"col-12 mb-4"}>
                            <WorkoutLibraryCreateModal show={showCreateModal} onHide={handleShowCreateModal} type={type}/>
                        </div>
                        <div className={"col-12"}>
                            <div className={'card card-body py-2 bg-body clickable-element'} onClick={handleShowSearchBox}>
                                <div className={"row justify-content-between"}>
                                    <div className={'col-auto'}>
                                        <span>{t("trainingLibraryComponent:searchPlaceholder")}</span>
                                    </div>
                                    <div className={'col-auto'}>
                                        <i className={'fa-regular fa-magnifying-glass'}></i>
                                    </div>
                                </div>
                            </div>
                            <WorkoutLibrarySearchModal show={showSearchBox} handleShow={handleShowSearchBox} type={type}/>
                        </div>
                        {sortedFolders?.length > 0 && (
                            <div className={"col-12 mb-2 mt-3"}>
                                <span className={"fw-semibold"}>{t("trainingLibraryComponent:foldersLabel")}</span>
                            </div>
                        )}
                        <div className={"col-12"}>
                            {_.map(sortedFolders, (folderItem, index) => (
                                <WorkoutLibraryItem folder={folderItem} key={index}/>
                            ))}
                        </div>
                    </div>

                    {
                        folder?.treinos.length > 0 &&
                        <>
                            <div className={'row mb-2 mt-2'}>
                                <div className={'col-12'}>
                                    {type === 0 ?
                                        <span className={"fw-semibold"}>{t("trainingLibraryComponent:routinesLabel")}</span>
                                        :
                                        <span className={"fw-semibold"}>{t("trainingLibraryComponent:workoutsLabel")}</span>
                                    }
                                </div>
                            </div>
                            {_.map(currentItems, (workout, index) =>
                                <WorkoutLibraryWorkoutItem workout={workout} key={index} type={type}/>
                            )}

                            {
                                totalItems > itemsPerPage &&
                                <div className={'row justify-content-center mt-4'}>
                                    <div className={'col-auto'}>
                                        <Pagination
                                            currentPage={currentPage}
                                            totalItems={totalItems}
                                            itemsPerPage={itemsPerPage}
                                            onPageChange={setCurrentPage}
                                            pagesToShow={pagesToShow}
                                        />
                                    </div>
                                </div>
                            }
                        </>
                    }
                </div>
            }

            {(isFolderListLoading || isFolderLoading) &&
                <LoadingBlock height={"200px"}/>
            }

            {!isFolderLoading && !isFolderListLoading && folder?.treinos.length === 0 && folderList?.length === 0 &&
                <div className={'card card-body border-0 mt-3'}>
                    <div className={'row justify-content-center'}>
                        <div className={"col-auto"}>
                            {
                                type === 0 ?
                                    <RoundedIcon icon={"fa-dumbbell"} size={"xl"}/> :
                                    <RoundedIcon icon={"fa-running"} size={"xl"}/>
                            }
                        </div>
                        <div className={'col-12 pt-4'}>
                            <div className={'row justify-content-center'}>
                                <div className={'col-12 text-center'}>
                                    <span className={'fw-semibold fs-3 d-block'}>
                                         {
                                             type === 0 ?
                                                 t("trainingLibraryComponent:workoutRoutinesMainTitle") :
                                                 t("trainingLibraryComponent:workoutRunningMainTitle")
                                         }
                                    </span>
                                </div>
                            </div>
                            <div className={'row justify-content-center pt-3'}>
                                <div className={'col-auto'}>
                                    <ul>
                                        <li>{t("trainingLibraryComponent:createWorkoutsForFuture")}</li>
                                        <li>{t("trainingLibraryComponent:organizeWorkoutsInFolders")}</li>
                                        <li>{t("trainingLibraryComponent:cloneWorkoutsForClients")}</li>
                                    </ul>
                                </div>
                            </div>
                            <div className={'row justify-content-center'}>
                                <div className={'col-12 pt-3'}>
                                    <div className={"d-grid"}>
                                        <WorkoutLibraryCreateModal emptyList={true} show={showCreateModal} onHide={handleShowCreateModal} type={type}/>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </>
    )
}

export default WorkoutLibraryRoutines;
