import WorkoutStopwatchModal from "./WorkoutStopwatchModal";
import {useSelector} from "react-redux";
import {useState} from "react";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/workout-session/locales/en-us.json";
import ptBR from "../../pages/workout-session/locales/pt-br.json";
import esES from "../../pages/workout-session/locales/es-es.json";
import ptPT from "../../pages/workout-session/locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {getPreview} from "../../store/workout-session/workoutSessionSelector";

const WorkoutTimeSeries = ({serie}) => {
    const {t} = useTranslation();
    const preview = useSelector(getPreview);
    const [show, setShow] = useState(false);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const handleStopwatchOpen = () => {
        if (!preview)
            setShow(true)
    };
    const handleStopwatchClose = () => {
        setShow(false)
    };
    return (
        <div className={'row d-flex '}>
            <div className={"col-12"}>
                <span onClick={handleStopwatchOpen} className={'text-primary clickable-element'}><i
                    className="fa-regular fa-timer"></i> <span
                    className={'text-decoration-underline'}>{t("workout:time")}: {serie.tempo}s</span>
                </span>
            </div>
            {
                (serie.tempo | 0) && !preview &&
                <WorkoutStopwatchModal
                    initialTime={serie.tempo}
                    show={show}
                    handleClose={handleStopwatchClose}/>
            }
        </div>
    )

}

export default WorkoutTimeSeries;