import {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import Cropper from "react-easy-crop";
import getCroppedImg from "../../utils/image/cropImage";
import uploadFile from "../../utils/fileupload/s3FileUpload";
import {
    selectUser,
    selectUserProfilePictureUpdateErrorCode,
    selectUserProfilePictureUpdateLoading,
    selectUserProfilePictureUpdateSuccess
} from "../../store/user/userSelector";
import {
    clearUserProfilePictureUpdateState,
    updateUserProfilePicture
} from "../../store/user/userReducer";
import {addToast} from "../../store/toast/toastReducer";

const UserProfileImageCropper = ({handleClose, image, setImage, saveText, cancelText, setProcessingState}) => {
    const dispatch = useDispatch();
    const user = useSelector(selectUser);
    const profilePictureUpdateLoading = useSelector(selectUserProfilePictureUpdateLoading);
    const profilePictureUpdateSuccess = useSelector(selectUserProfilePictureUpdateSuccess);
    const profilePictureUpdateErrorCode = useSelector(selectUserProfilePictureUpdateErrorCode);
    const [crop, setCrop] = useState({x: 0, y: 0});
    const [zoom, setZoom] = useState(1);
    const [croppedAreaPixels, setCroppedAreaPixels] = useState(null);
    const [isSaving, setIsSaving] = useState(false);
    const controlsDisabled = isSaving || profilePictureUpdateLoading;

    const onCropComplete = (_, croppedAreaPixelsValue) => {
        setCroppedAreaPixels(croppedAreaPixelsValue);
    };

    useEffect(() => {
        dispatch(clearUserProfilePictureUpdateState());
        return () => {
            dispatch(clearUserProfilePictureUpdateState());
        };
    }, [dispatch]);

    useEffect(() => {
        if (!profilePictureUpdateSuccess || !isSaving) {
            return;
        }

        setIsSaving(false);
        setProcessingState?.(false);
        dispatch(clearUserProfilePictureUpdateState());
        setImage(null);
        handleClose();
    }, [dispatch, handleClose, isSaving, profilePictureUpdateSuccess, setImage, setProcessingState]);

    useEffect(() => {
        if (!profilePictureUpdateErrorCode || !isSaving) {
            return;
        }

        dispatch(addToast());
        setIsSaving(false);
        setProcessingState?.(false);
        dispatch(clearUserProfilePictureUpdateState());
    }, [dispatch, isSaving, profilePictureUpdateErrorCode, setProcessingState]);

    const saveCroppedImage = async () => {
        if (!user?.id || !image || !croppedAreaPixels || controlsDisabled) {
            return;
        }

        setIsSaving(true);
        setProcessingState?.(true);

        try {
            const croppedImage = await getCroppedImg(image, croppedAreaPixels);
            if (!croppedImage) {
                throw new Error("CROPPED_IMAGE_EMPTY");
            }

            const imgUrl = await uploadFile(croppedImage, user.id, 0, "profilepicture");
            if (!imgUrl) {
                throw new Error("PROFILE_PICTURE_URL_EMPTY");
            }

            dispatch(updateUserProfilePicture({url: imgUrl}));
        } catch {
            dispatch(addToast());
            setIsSaving(false);
            setProcessingState?.(false);
        }
    };

    const hideCroppedImage = () => {
        if (controlsDisabled) {
            return;
        }
        dispatch(clearUserProfilePictureUpdateState());
        setProcessingState?.(false);
        setImage(null);
        handleClose();
    };

    return (
        <div className={"d-flex flex-column flex-grow-1"}>
            <div className={"px-4"}>
                <div
                    className={"position-relative"}
                    style={{height: "50vh", backgroundColor: "#000"}}
                >
                    <Cropper
                        image={image}
                        crop={crop}
                        zoom={zoom}
                        aspect={1}
                        cropShape={"round"}
                        showGrid={false}
                        onCropChange={setCrop}
                        onCropComplete={onCropComplete}
                        onZoomChange={setZoom}
                    />
                </div>
            </div>
            <div className={"mt-auto px-4 pb-4 pt-4"}>
                <div className={"d-grid gap-2"}>
                    <button
                        className={`btn btn-primary py-2 ${controlsDisabled ? "disabled" : ""}`}
                        style={{fontWeight: 400}}
                        onClick={saveCroppedImage}
                        disabled={controlsDisabled}
                    >
                        {saveText}
                    </button>
                    <button
                        className={`btn btn-outline-primary py-2 ${controlsDisabled ? "disabled" : ""}`}
                        style={{fontWeight: 400}}
                        onClick={hideCroppedImage}
                        disabled={controlsDisabled}
                    >
                        {cancelText}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default UserProfileImageCropper;
