import {all, call, put, takeLatest} from 'redux-saga/effects';
import {
    fetchAllWorkouts,
    onError, setLoadingStatus,
} from "./workoutReducer";
import {setAerobics} from "../workout-aerobic/workoutAerobicReducer";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {getAllWorkoutsAPI} from "../../api/workout/workoutActions";
import {setWorkouts} from "../workout-routine/workoutRoutineReducer";

export function* fetchAllWorkoutsAsync(action) {
    try {
        const response = yield call(getAllWorkoutsAPI, action.payload)

        yield put(setAerobics(response.data.runningList))
        yield put(setWorkouts(response.data.routines))
        yield put(setLoadingStatus(false))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchAllWorkouts() {
    yield takeLatest(fetchAllWorkouts.type, fetchAllWorkoutsAsync);
}

export function* workoutSaga() {
    yield all([
        call(onFetchAllWorkouts)
    ])
}