import {isDesktop} from "react-device-detect";
import {Offcanvas} from "react-bootstrap";
import LoadingBlock from "../loader/LoadingBlock";
import React, {useState} from "react";
import {deleteExerciseFromSession} from "../../store/workout-prescription/workoutPrescriptionReducer";
import {useDispatch, useSelector} from "react-redux";
import {selectWorkoutExerciseLoading} from "../../store/workout-prescription/workoutPrescriptionSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import Text from "../utils/emoji/Text";
import {translateExerciseName} from "../../utils/workout/Exercise";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutPrescriptionQuickList = ({addedExercises, sessionId}) => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch()
    const [expand, setExpand] = useState(false)
    const exercsLoading = useSelector(selectWorkoutExerciseLoading)
    useComponentTranslations('workoutPrescriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleExpand = () => {
        setExpand(prevState => !prevState)
    }

    const removeExercise = (exerciseId, exercSessionId) => {
        dispatch(deleteExerciseFromSession({sessionId: sessionId, exercSessionId: exercSessionId}))
    };

    const getExerciseName = (exerciseArray) => {
        if (!exerciseArray || exerciseArray.length === 0) return "";
        const mainExercise = exerciseArray[0];

        if (mainExercise.isCombinado) {
            const names = mainExercise.series
                .filter(serie => serie.idExerc > 0)
                .map(serie => translateExerciseName(serie.exercicio, i18n.language));
            return names.join(" + ");
        }

        if (exerciseArray.length > 1) {
            return exerciseArray
                .map(ex => translateExerciseName(ex, i18n.language))
                .join(" / ");
        }

        return translateExerciseName(mainExercise, i18n.language);
    };

    return (
        <div className={"row fixed-bottom justify-content-center"} style={{bottom: !isDesktop ? "80px" : ""}}>
            <div className={"col-12 col-md-6 col-xl-4"}>
                {
                    !expand &&
                    <div className={"card card-body bg-secondary-subtle border-0"}>
                        <div className={"row justify-content-between"} onClick={handleExpand}>
                            <div className={"col-10 col-md-11"}>
                                <div className={"row"}>
                                    <div className={"col-auto align-self-center"}>
                                        <span className={"fw-semibold"}>{t("workoutPrescriptionComponent:addedExercises")}</span>
                                    </div>
                                    <div className={"col-auto align-self-center ps-0"}>
                                        <div className={"border border-2 border-default rounded-circle  text-center "}
                                             style={{height: "30px", width: "30px"}}>
                                            <span className="d-block text-center" style={{paddingTop: "2px"}}>{addedExercises.length}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className={"col-2 col-md-1 align-self-center text-center "}>
                                <i className={`fa-regular fs-4 fa-chevron-right`}></i>
                            </div>
                        </div>
                    </div>
                }
                <Offcanvas
                    show={expand}
                    onHide={handleExpand}
                    placement={"end"}
                    className={"bg-secondary-subtle"}
                >
                    <Offcanvas.Header>
                        <div className={"col-2 col-md-1 align-self-center text-center "} onClick={handleExpand}>
                            <i className={`fa-regular fs-4 fa-chevron-left`}></i>
                        </div>
                        <div className={"col-10 col-md-11"}>
                            <div className={"row"}>
                                <div className={"col-auto align-self-center"}>
                                    <span className={"fw-semibold"}>{t("workoutPrescriptionComponent:addedExercises")}</span>
                                </div>
                                <div className={"col-auto align-self-center ps-0"}>
                                    <div className={"border border-2 border-default rounded-circle  text-center "}
                                         style={{height: "30px", width: "30px"}}>
                                        <span className="d-block text-center" style={{paddingTop: "2px"}}>{addedExercises.length}</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </Offcanvas.Header>
                    <Offcanvas.Body className="overflow-auto">
                        {
                            exercsLoading &&
                            <LoadingBlock height={"200px"}/>
                        }
                        {
                            !exercsLoading &&
                            <div className="list-group list-group-flush">
                                {addedExercises.map((ex) => (
                                    <div
                                        key={ex.id}
                                        className="list-group-item d-flex justify-content-between align-items-center bg-secondary-subtle"
                                    >
                                            <span className="fw-semibold">
                                              <Text>{getExerciseName(ex.exerciseArray)}</Text>
                                            </span>
                                        <i
                                            className="fa-regular fa-trash text-danger "
                                            style={{cursor: "pointer"}}
                                            onClick={() => removeExercise(ex.exerciseArray[0].id, ex.exerciseArray[0].idExercSession)}
                                        />
                                    </div>
                                ))}
                            </div>
                        }
                    </Offcanvas.Body>
                </Offcanvas>
            </div>
        </div>

    )
}

export default WorkoutPrescriptionQuickList;