import AiTyping from "./AiTyping";
import {rateMessage} from "../../store/chat-bot/chatBotReducer";
import {useDispatch} from "react-redux";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const AiAssistantChat = ({msg, scrollToBottom}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    useComponentTranslations('ai', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleRating = (uuid, rating) => {
        dispatch(rateMessage({uuid, rating}));
    };

    return (
        <>
            <div className="d-flex  ">
                <div className={'col-1  text-center'}>
                    <i
                        className="fa-kit fa-mfit-ai fa-xl text-mfit-ai-gradient"
                    ></i>

                </div>
                <div className={'col-auto ms-3'}>
                    <span className="text-secondary">
                    {t("ai:thinkingTime", {time: msg.thinkingTime})}
                </span>
                </div>
            </div>
            <div style={{marginLeft: "34px"}} className={"mt-n2  "}>
                <div
                    className="d-inline-block p-2 text-default"
                    style={{maxWidth: "100%"}}
                >
                    {
                        msg.isNew
                            ? <AiTyping
                                uuid={msg.uuid}
                                initialHTML={msg.message}
                                onTypeCallback={scrollToBottom}
                            />
                            : <span
                                dangerouslySetInnerHTML={{
                                    __html: msg.message
                                }}
                            />
                    }
                </div>
                {
                    !msg.isNew &&
                    <div className={'d-flex flex-column justify-content-center align-items-center fw-semibold rounded p-2 mt-n3'}>
                        <span>{t("ai:wasThisResponseUseful")}</span>
                        <span className={"pt-2"}>
                            <span className={"pe-2 clickable-element"}
                                  onClick={() => handleRating(msg.uuid, "bad")}>
                                <i className={`fal fa-thumbs-down fa-xl ${msg.rating === "bad" && "text-danger"}`}></i>
                            </span>
                            <span
                                className={`ps-2 clickable-element ${msg.rating === "good" && "text-primary"}`}
                                onClick={() => handleRating(msg.uuid, "good")}>
                                <i className={"fal fa-thumbs-up fa-xl"}></i>
                            </span>
                        </span>
                        <br/>
                    </div>
                }
            </div>
        </>
    )
}
export default AiAssistantChat;