import RetentionInfoOffcanvas from "./RetentionInfoOffcanvas";
import {
    formatDelta,
    formatMetricValue,
    formatRetentionDateRange,
    getRetentionMetricMeta
} from "./retentionConfig";

const RetentionChartComparisonInfoOffcanvas = ({show, onHide, chart, metric, locale, t}) => {
    if (!chart?.hasComparisonData) {
        return null;
    }

    const metricMeta = getRetentionMetricMeta(metric, t);
    const currentRange = formatRetentionDateRange(chart?.referenceStart, chart?.referenceEnd, locale);
    const comparisonRange = formatRetentionDateRange(chart?.comparisonStart, chart?.comparisonEnd, locale);
    const currentValue = formatMetricValue(metric, chart?.value, locale);
    const comparisonValue = formatMetricValue(metric, chart?.comparisonValue, locale);
    const numericDelta = Number(chart?.deltaPct || 0);
    const deltaMagnitude = formatMetricValue("ENGAGEMENT", Math.abs(numericDelta), locale);

    const comparisonDescription = numericDelta > 0
        ? t("retention:chartComparisonIncreased", {
            metric: metricMeta.label,
            comparisonValue,
            currentValue,
            delta: deltaMagnitude
        })
        : numericDelta < 0
            ? t("retention:chartComparisonDecreased", {
                metric: metricMeta.label,
                comparisonValue,
                currentValue,
                delta: deltaMagnitude
            })
            : t("retention:chartComparisonUnchanged", {
                metric: metricMeta.label,
                currentValue
            });
    const intro = t("retention:chartComparisonHelpIntro", {
        metric: metricMeta.label,
        delta: formatDelta(chart?.deltaPct, locale)
    });

    const sections = [
        {
            key: "currentPeriod",
            icon: "fa-regular fa-calendar",
            title: t("retention:chartCurrentPeriod"),
            description: t("retention:chartCurrentPeriodResult", {
                range: currentRange === "-" ? t("retention:chartDateUnavailable") : currentRange,
                metric: metricMeta.label,
                value: currentValue
            })
        },
        {
            key: "previousPeriod",
            icon: "fa-regular fa-calendar",
            title: t("retention:chartPreviousEquivalentPeriod"),
            description: t("retention:chartPreviousPeriodResult", {
                range: comparisonRange === "-" ? t("retention:chartDateUnavailable") : comparisonRange,
                value: comparisonValue
            })
        },
        {
            key: "comparisonResult",
            icon: "fa-regular fa-chart-line-up",
            title: t("retention:chartComparisonResult"),
            description: comparisonDescription
        }
    ];

    return (
        <RetentionInfoOffcanvas
            show={show}
            onHide={onHide}
            title={t("retention:chartComparisonHelpTitle")}
            intro={intro}
            sections={sections}
            sectionVariant={"icon"}
        />
    );
};

export default RetentionChartComparisonInfoOffcanvas;
