import {Offcanvas} from "react-bootstrap";
import {useSelector} from "react-redux";
import {useTranslation} from "react-i18next";
import {selectUserLanguageUpdateLoading} from "../../store/user/userSelector";

const LANGUAGE_OPTIONS = [
    {
        language: "pt-BR",
        labelKey: "languageOptionPortuguese",
        flagUrl: "https://cdn.mfitpersonal.com.br/assets/flags/pt-BR.png"
    },
    {
        language: "pt-PT",
        labelKey: "languageOptionPortuguesePortugal",
        flagUrl: "https://cdn.mfitpersonal.com.br/assets/flags/pt-PT.png"
    },
    {
        language: "en-US",
        labelKey: "languageOptionEnglish",
        flagUrl: "https://cdn.mfitpersonal.com.br/assets/flags/en-US.png"
    },
    {
        language: "es-ES",
        labelKey: "languageOptionSpanish",
        flagUrl: "https://cdn.mfitpersonal.com.br/assets/flags/es-ES.png"
    }
];

const UserProfileLanguageOffcanvas = ({show, handleClose, currentLanguage, onLanguageSelectionStarted}) => {
    const loading = useSelector(selectUserLanguageUpdateLoading);
    const {t} = useTranslation();

    const normalizedCurrentLanguage = `${currentLanguage || ""}`.toLowerCase();

    const handleLanguageClick = (selectedLanguage) => {
        if (loading) {
            return;
        }

        if (selectedLanguage.toLowerCase() === normalizedCurrentLanguage) {
            handleClose();
            return;
        }

        onLanguageSelectionStarted?.(selectedLanguage);
    };

    return (
        <Offcanvas show={show} onHide={handleClose} placement={"end"}>
            <Offcanvas.Body className={"bg-body"}>
                <div className={"row justify-content-between align-items-center pb-3"}>
                    <div className={"col-10"}>
                        <span className={"fs-4"}>{t("userProfilePage:changeAppLanguageTitle")}</span>
                    </div>
                    <div className={"col-auto"}>
                        <button
                            type={"button"}
                            className={"no-style-btn"}
                            onClick={handleClose}
                            disabled={loading}
                            aria-label={t("userProfilePage:cancel")}
                        >
                            <i className={"fa-solid fa-xmark fs-4"}></i>
                        </button>
                    </div>
                </div>

                <ul className={"list-group"}>
                    {
                        LANGUAGE_OPTIONS.map((option) => {
                            const isSelected = option.language.toLowerCase() === normalizedCurrentLanguage;

                            return (
                                <li
                                    key={option.language}
                                    className={"list-group-item p-0"}
                                >
                                    <button
                                        type={"button"}
                                        className={"btn w-100 text-start rounded-0 border-0 py-2 px-3"}
                                        onClick={() => handleLanguageClick(option.language)}
                                        disabled={loading}
                                        aria-pressed={isSelected}
                                    >
                                        <div className={"row d-flex align-items-center"}>
                                            <div className={"col-2 align-self-center"}>
                                                <img
                                                    src={option.flagUrl}
                                                    alt={t(`userProfilePage:${option.labelKey}`)}
                                                    className={"img-fluid rounded-circle"}
                                                    style={{width: "34px", height: "34px", objectFit: "cover"}}
                                                />
                                            </div>
                                            <div className={"col-8 align-self-center ps-0"}>
                                                {t(`userProfilePage:${option.labelKey}`)}
                                            </div>
                                            <div className={"col-2 align-self-center text-end"}>
                                                {isSelected && <i className={"fa-solid fa-check"}></i>}
                                            </div>
                                        </div>
                                    </button>
                                </li>
                            );
                        })
                    }
                </ul>
            </Offcanvas.Body>
        </Offcanvas>
    );
};

export default UserProfileLanguageOffcanvas;
