export function getFileIcon(fileName) {
    const ext = fileName.split('.').pop().toLowerCase();
    const map = {
        pdf: 'fa-file-pdf',
        png: 'fa-image',
        jpg: 'fa-image',
        jpeg: 'fa-image',
        gif: 'fa-image',
    };
    return map[ext] || 'fa-file';
}

export function getFileType(fileName) {
    if (!fileName) return 'filesComponent:other';
    const ext = fileName.split('.').pop().toLowerCase();
    const typeMap = {
        pdf: 'filesComponent:pdf',
        png: 'filesComponent:image',
        jpg: 'filesComponent:image',
        jpeg: 'filesComponent:image',
        gif: 'filesComponent:image',
        doc: 'filesComponent:document',
        docx: 'filesComponent:document',
        xls: 'filesComponent:spreadsheet',
        xlsx: 'filesComponent:spreadsheet',
        csv: 'filesComponent:spreadsheet',
        txt: 'filesComponent:text',
        mp4: 'filesComponent:video',
        mov: 'filesComponent:video',
        avi: 'filesComponent:video',
        mp3: 'filesComponent:audio',
        wav: 'filesComponent:audio'
    };
    return typeMap[ext] || 'filesComponent:other';
}

