import WorkoutExerciseRegular from "./WorkoutExerciseRegular";
import WorkoutExerciseMultiple from "./WorkoutExerciseMultiple";

const WorkoutExercise = ({exerc}) => {

    switch (exerc.type) {
        case 0:
            return (
                <div className={'card card-body  card-no-border p-0'}>
                    <WorkoutExerciseRegular exerc={exerc} mainId={exerc.id}/>
                </div>
            )
        case 1:
            const showMultiples = exerc.exercises[0].series.filter(series => series.tipo === 6).length > 1;
            if (showMultiples){
                return (<WorkoutExerciseMultiple exerc={exerc} mainId={exerc.id}/>)
            }

            else {
                const ex = exerc.exercises[0].series.find(series => series.tipo === 6);
                const serie = exerc.exercises[0].series.filter(series => series.tipo !== 6);
                const newEx = {...ex?.exercicio};
                newEx.series = serie;
                const exs = [newEx];
                const newExerc = {
                    id: exerc.id,
                    order: exerc.order,
                    type: exerc.type,
                    exercises: exs
                };
                return (
                    <div className={'card card-body card-no-border p-0'}>
                        <WorkoutExerciseRegular exerc={newExerc} mainId={exerc.id}/>
                    </div>
                )
            }
        case 2:
            return (
                <div className={'card card-body card-no-border p-0'}>
                    <WorkoutExerciseRegular exerc={exerc.exercises} mainId={exerc.id} exercList={exerc.exercises}/>
                </div>
            )
        default:
            return "";

    }
}
export default WorkoutExercise;