import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import {
    getCustomLoading,
    selectCustomEvaluation, selectSubmitResult,
    selectImageUploading,
    selectSubmitLoading
} from "../../store/custom-evaluation/customEvaluationSelector";
import {
    answerCustom,
    getOneCustom, resetFormSent,
    setImageUploadingStatus
} from "../../store/custom-evaluation/customEvaluationReducer";
import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import enUS from "./locales/en-us.json";
import {fetchClient} from "../../store/client/clientReducer";
import {ErrorMessage, Field, Form, Formik} from "formik";
import {imageResizer} from "../../utils/imageresizer/imageResizer";
import uploadFile from "../../utils/fileupload/s3FileUpload";
import {addToast} from "../../store/toast/toastReducer";
import {useTranslation} from "react-i18next";
import {selectUser} from "../../store/user/userSelector";
import * as Yup from "yup";
import {calculateAge} from "../../utils/date/dateUtils";
import Text from "../../components/utils/emoji/Text";
import EvaluationSubmitButton from "../../components/evaluation-components/EvaluationSubmitButton";
import EvaluationSuccessCard from "../../components/evaluation-components/EvaluationSuccessCard";
import {
    buildCustomModelsRoute,
    buildCustomViewRoute
} from "../../utils/client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const CustomEvaluationCreate = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, customId} = useParams();
    const {t} = useTranslation();
    syncMomentLocale(i18n.language);
    const user = useSelector(selectUser);
    const selectedClient = useSelector(selectSelectedClient);
    const loadingClient = useSelector(isClientsLoading);
    const loadingCustom = useSelector(getCustomLoading);
    const customDetails = useSelector(selectCustomEvaluation);
    const uploadingImage = useSelector(selectImageUploading);
    const submitLoading = useSelector(selectSubmitLoading);
    const submitResult = useSelector(selectSubmitResult);
    const formSent = isMatchingSubmitSuccess(submitResult, {
        action: "create",
        flow: EVALUATION_FLOWS.CUSTOM_ANSWERED_CREATE,
        clientId: id
    });
    useComponentTranslations('customEvaluation', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        if (customId) {
            dispatch(getOneCustom(customId));
        }
    }, [dispatch, customId]);

    const handleGoBackPage = () => {
        navigate(buildCustomModelsRoute(id));
    };

    const handleGoView = () => {
        const targetId = submitResult?.entityId ?? customDetails?.id;
        if (!targetId) {
            return;
        }
        navigate(buildCustomViewRoute(id, targetId));
    }

    const today    = moment().format("YYYY-MM-DD");
    const nextEval = moment().add(90, 'days').format("YYYY-MM-DD");

    const validationSchema = Yup.object().shape({
        peso: Yup.number()
            .required(t("customEvaluation:weightRequired"))
            .positive(t("customEvaluation:weightPositve")),

        estatura: Yup.number()
            .required(t("customEvaluation:heightRequired"))
            .positive(t("customEvaluation:heightPositive")),

        idade: Yup.number()
            .required(t("customEvaluation:ageRequired"))
            .positive(t("customEvaluation:agePositive"))
            .integer(t("customEvaluation:ageInteger")),

        data: Yup.date()
            .required(t("customEvaluation:dateRequired")),

        proximaAvaliacao: Yup.date()
            .required(t("customEvaluation:nextEvaluationRequired")),
    });

    const idadeCalculada = selectedClient?.data_nascimento
        ? calculateAge(selectedClient.data_nascimento)
        : "";

    const initialValues = {
        peso:  "",
        estatura: "",
        idade:  idadeCalculada,
        data: today,
        imc:  "",
        tipo: customDetails?.tipo,
        observacao: "",
        proximaAvaliacao: nextEval,
        ...customDetails?.campos?.reduce((acc, f) => {
            acc[f.id] = f.valor ?? "";
            return acc;
        }, {})
    };

    const handleChangePicture = async (event, field, setFieldValue) => {
        const file = event.target.files[0];
        if (!file) return;

        dispatch(setImageUploadingStatus(true));

        try {
            const imgResized = await imageResizer(file);
            const imgUrl = await uploadFile(imgResized, id, customId, "customEvaluation");
            setFieldValue(field, imgUrl);
        } catch (error) {
            const toastPayload = {
                id: `toast-alert-${id}`,
                type: "warning",
                title: t("customEvaluation:errorLoadImage"),
                message: t("customEvaluation:tryAgain"),
                autohide: true,
                delay: 5000
            };
            dispatch(addToast(toastPayload));
        } finally {
            dispatch(setImageUploadingStatus(false));
        }
    };

    const handleSubmit = (values) => {
        const payload = {
            id: Number(customDetails.id),
            id_aluno: Number(id),
            id_professor: user.id,
            data: values.data,
            peso: values.peso,
            estatura: values.estatura,
            idade: values.idade,
            imc: values.imc,
            tipo:values.tipo,
            observacao: values.observacao,
            proximaAvaliacao: values.proximaAvaliacao,
            campos: customDetails.campos.map(f => ({
                id: f.id,
                id_avaliacao: Number(customDetails.id),
                campo: f.campo,
                tipo: f.tipo,
                valor: values[f.id] ?? "",
                status: 0
            }))
        };
        dispatch(answerCustom(payload, {
            flow: EVALUATION_FLOWS.CUSTOM_ANSWERED_CREATE,
            clientId: id
        }));
    };

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loadingCustom} pb={"pb-2"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        {!formSent ? (
                            <div className={"card card-body border-0"}>
                                <span className={"fw-semibold"}>
                                    <Text>{customDetails?.tipo}</Text>
                                </span>
                                <Formik initialValues={initialValues}
                                        enableReinitialize
                                        onSubmit={handleSubmit}
                                        validationSchema={validationSchema}
                                >
                                    {({errors, touched, setFieldValue}) => (
                                        <Form>
                                            <div className="mb-3">
                                                <label htmlFor="peso" className="fw-semibold">{t("customEvaluation:weight")}</label>
                                                <Field
                                                    id="peso"
                                                    name="peso"
                                                    type="number"
                                                    className={`form-control ${
                                                        errors.peso && touched.peso ? "is-invalid" : ""
                                                    }`}
                                                    placeholder={"Ex: 62.5"}
                                                />
                                                <ErrorMessage
                                                    name="peso"
                                                    component="div"
                                                    className="invalid-feedback"
                                                />
                                            </div>
                                            <div className="mb-3">
                                                <label htmlFor="estatura" className="fw-semibold">{t("customEvaluation:height")}</label>
                                                <Field
                                                    id="estatura"
                                                    name="estatura"
                                                    type="number"
                                                    className={`form-control ${
                                                        errors.estatura && touched.estatura ? "is-invalid" : ""
                                                    }`}
                                                    placeholder={"Ex: 1.75"}
                                                />
                                                <ErrorMessage
                                                    name="estatura"
                                                    component="div"
                                                    className="invalid-feedback"
                                                />
                                            </div>
                                            <div className="mb-3">
                                                <label htmlFor="idade" className="fw-semibold">{t("customEvaluation:age")}</label>
                                                <Field
                                                    id="idade"
                                                    name="idade"
                                                    type="number"
                                                    className={`form-control ${
                                                        errors.idade && touched.idade ? "is-invalid" : ""
                                                    }`}
                                                />
                                                <ErrorMessage
                                                    name="idade"
                                                    component="div"
                                                    className="invalid-feedback"
                                                />
                                            </div>
                                            <div className={"mb-3"}>
                                                <label htmlFor={"data"} className={"fw-semibold"}>{t("customEvaluation:date")}</label>
                                                <Field
                                                    id="data"
                                                    name="data"
                                                    type="date"
                                                    className={`form-control ${
                                                        errors.data && touched.data ? "is-invalid" : ""
                                                    }`}
                                                />
                                                <ErrorMessage
                                                    name="data"
                                                    component="div"
                                                    className="invalid-feedback"
                                                />
                                            </div>
                                            <div className="mb-3">
                                                <label htmlFor="observacao" className="fw-semibold">{t("customEvaluation:observation")}</label>
                                                <Field
                                                    as="textarea"
                                                    id="observacao"
                                                    name="observacao"
                                                    className="form-control"
                                                />
                                            </div>

                                            <div className="mb-3">
                                                <label htmlFor="proximaAvaliacao" className="fw-semibold">
                                                    {t("customEvaluation:nextEvaluation")}
                                                </label>
                                                <Field
                                                    id="proximaAvaliacao"
                                                    name="proximaAvaliacao"
                                                    type="date"
                                                    className={`form-control ${
                                                        errors.proximaAvaliacao && touched.proximaAvaliacao
                                                            ? "is-invalid"
                                                            : ""
                                                    }`}
                                                />
                                                <ErrorMessage
                                                    name="proximaAvaliacao"
                                                    component="div"
                                                    className="invalid-feedback"
                                                />
                                            </div>
                                            {customDetails?.campos?.map(field => (
                                                <div key={field.id} className={"my-3"}>
                                                    <label className={"fw-semibold"} htmlFor={field.id}>
                                                        <Text>{field.campo}</Text>
                                                    </label>
                                                    {field.tipo === 2 ? (
                                                        <>
                                                            {initialValues[field.id] && (
                                                                <img
                                                                    src={initialValues[field.id]}
                                                                    alt={field.campo}
                                                                    className={"img-fluid mb-2 rounded"}
                                                                />
                                                            )}
                                                            <input
                                                                id={field.id}
                                                                name={field.id}
                                                                type="file"
                                                                disabled={uploadingImage}
                                                                accept="image/*"
                                                                onChange={(e) =>
                                                                    handleChangePicture(e, field.id, setFieldValue)
                                                                }
                                                                className={"form-control"}
                                                            />
                                                        </>
                                                    ) : (
                                                        field.campo === "Objetivo" ? (
                                                            <Field
                                                                as="textarea"
                                                                id={field.id}
                                                                name={field.id}
                                                                className={"form-control"}
                                                                rows={4}
                                                            />
                                                        ) : (
                                                            <>
                                                                <Field
                                                                id={field.id}
                                                                name={field.id}
                                                                type={field.tipo === 1 ? "number" : "text"}
                                                                className={`form-control ${
                                                                    errors[field.id] && touched[field.id] ? "is-invalid" : ""
                                                                }`}
                                                                />
                                                                <ErrorMessage
                                                                    name={field.id}
                                                                    component="div"
                                                                    className="invalid-feedback"
                                                                />
                                                            </>
                                                        ))}
                                                </div>
                                            ))}
                                            <EvaluationSubmitButton
                                                label={t("customEvaluation:saveEvaluation")}
                                                loadingLabel={t("customEvaluation:sending")}
                                                isSubmitting={submitLoading}
                                                disabled={uploadingImage}
                                            />
                                        </Form>
                                    )}
                                </Formik>
                            </div>
                        ) : (
                            <div className={"row justify-content-center d-flex "}>
                                <div className={"col-12"}>
                                    <EvaluationSuccessCard
                                        title={t("customEvaluation:answeredSuccessfully")}
                                        primaryLabel={t("customEvaluation:showEvaluation")}
                                        secondaryLabel={t("customEvaluation:return")}
                                        onPrimary={handleGoView}
                                        onSecondary={handleGoBackPage}
                                    />
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </Page>
        </>
    )
}

export default CustomEvaluationCreate;
