import {Link} from "react-router-dom";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {formatElapsedTime, getFeedbackIntensity} from "../../utils/workout/Workout";
import Text from "../utils/emoji/Text";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Avatar from "../avatar/Avatar";
import {useMemo} from "react";

const ResolvedFeedbackCard = ({resolvedFeedback}) => {
    const {t, i18n} = useTranslation();
    syncMomentLocale(i18n.language);
    useComponentTranslations('feedbackComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoToClientClick = `/user/client/${resolvedFeedback.idAluno}`

    const exec = resolvedFeedback.dataExecucao;
    const execMoment = useMemo(() => moment({
        year:  exec.date.year,
        month: exec.date.month - 1,
        day:   exec.date.day,
        hour:  exec.time.hour,
        minute:exec.time.minute,
        second:exec.time.second
    }), [exec]);

    const startDate = moment({
        day: resolvedFeedback.workoutStartTime?.date.day,
        month: resolvedFeedback.workoutStartTime?.date.month - 1,
        year: resolvedFeedback.workoutStartTime?.date.year,
        hour: resolvedFeedback.workoutStartTime?.time.hour,
        minute: resolvedFeedback.workoutStartTime?.time.minute,
        second: resolvedFeedback.workoutStartTime?.time.second
    });

    const endDate = moment({
        day: resolvedFeedback.workoutEndTime?.date.day,
        month: resolvedFeedback.workoutEndTime?.date.month - 1,
        year: resolvedFeedback.workoutEndTime?.date.year,
        hour: resolvedFeedback.workoutEndTime?.time.hour,
        minute: resolvedFeedback.workoutEndTime?.time.minute,
        second: resolvedFeedback.workoutEndTime?.time.second
    });

    return (
        <div className={"card card-body border-0 mb-3"}>
            <div className={"row justify-content-between"}>
                <div className={"col-2 me-n5 mx-n2"}>
                    <Avatar maxWidth={"24px"} url={resolvedFeedback?.clientProfileUrl}/>
                </div>
                <div className={"col-6"}>
                    <Link to={handleGoToClientClick}
                          className={'fw-semibold text-decoration-none text-default '}><Text>{resolvedFeedback.clientName}</Text></Link>
                </div>
                <div className={'col-4 text-end align-self-center'}>
                    <span className={'badge rounded-pill border border-primary bg-white text-primary'}>
                        {
                            resolvedFeedback.fonteFeedback === 0 && t("feedbackComponent:training")
                        }
                        {
                            resolvedFeedback.fonteFeedback === 1 && t("feedbackComponent:aerobic")
                        }
                        {
                            resolvedFeedback.fonteFeedback === 2 && t("feedbackComponent:extraTraining")
                        }
                    </span>
                </div>
            </div>
            <div className={"row justify-content-center mt-2"}>
                <div className={'col-12 text-md align-self-center'}>
                    <span className={'pe-3'}>
                        <i className={'fa-regular fa-calendar me-1'}/>
                        {execMoment.format("L")}
                    </span>
                    <span>
                        <i className={"fa-regular fa-clock me-1"}/>{execMoment.format("HH:mm")}
                    </span>
                </div>

                <div className={'col-12 text-md mt-2'}>
                    <span
                        className={'fw-semibold'}>{t("feedbackComponent:intensity")}: </span>
                    {t(`feedbackComponent:${getFeedbackIntensity(resolvedFeedback.borgNota)}`)}
                </div>
                <div className={'col-12 mt-2 text-md'}>
                    <span className={"fw-semibold"}>{t("feedbackComponent:feedback")}: </span>
                    {
                        resolvedFeedback.feedback !== "" ?
                            <Text>{resolvedFeedback.feedback}</Text> :
                            <span>{t("feedbackComponent:clientDidntLeaveComments")}</span>
                    }
                </div>
                <div className={"col-12 mt-2 text-md"}>
                    <span className={"fw-semibold"}>Resposta: </span>
                        {
                            resolvedFeedback.resposta !== "" ?
                                <Text>{resolvedFeedback.resposta}</Text> :
                                <span>Feedback sem resposta</span>
                        }
                </div>
                {
                    resolvedFeedback.workoutStartTime &&
                    <>
                        <div className={'col-11 text-md bg-secondary-subtle mt-3 rounded-2 p-2 ps-4 pe-4'}>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto '}>
                                    <span className={'fw-semibold  text-md'}>{t("feedbackComponent:start")}:</span>
                                </div>
                                <div className={'col-auto text-end'}>
                                    <span className={"text-md"}>
                                        {moment(startDate).format("DD/MM/YYYY HH:mm")}
                                    </span>
                                </div>
                            </div>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold text-md'}>{t("feedbackComponent:end")}:</span>
                                </div>
                                <div className={'col-auto text-end'}>
                                    <span className={'text-md '}>
                                        {moment(endDate).format("DD/MM/YYYY HH:mm")}
                                    </span>
                                </div>
                            </div>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold'}>{t("feedbackComponent:trainingTime")}:</span>
                                </div>
                                <div className={'col-auto  text-end'}>
                                    <span className={' fw-semibold'}>
                                        {formatElapsedTime(endDate.diff(startDate, 'seconds'))}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </>
                }
            </div>
        </div>
    )
}

export default ResolvedFeedbackCard;