import {useCallback, useEffect, useRef} from "react"

const FOCUSABLE_SELECTOR = [
    "a[href]",
    "area[href]",
    "button:not([disabled])",
    "input:not([disabled]):not([type='hidden'])",
    "select:not([disabled])",
    "textarea:not([disabled])",
    "iframe",
    "[contenteditable='true']",
    "[tabindex]:not([tabindex='-1'])"
].join(",")

const isHTMLElement = (value) => value instanceof HTMLElement

const isFocusableElement = (element) => {
    if (!isHTMLElement(element) || element.hasAttribute("disabled") || element.getAttribute("aria-hidden") === "true") {
        return false
    }

    const tabIndex = typeof element.tabIndex === "number" ? element.tabIndex : -1
    const focusableTags = ["A", "BUTTON", "INPUT", "SELECT", "TEXTAREA", "IFRAME"]

    return tabIndex >= 0 || focusableTags.includes(element.tagName) || element.isContentEditable
}

const getFocusableElementsWithin = (root) => {
    if (!isHTMLElement(root)) {
        return []
    }

    return Array.from(root.querySelectorAll(FOCUSABLE_SELECTOR)).filter(isFocusableElement)
}

const uniqueElements = (elements) => {
    return [...new Set(elements.filter(Boolean))]
}

const useGuidedTourFocusScope = ({
    isOpen,
    stepId,
    cardRef,
    primaryActionRef,
    targetElement,
    allowTargetInteraction = false
}) => {
    const wasOpenRef = useRef(false)
    const previouslyFocusedElementRef = useRef(null)

    const restoreFocus = useCallback(() => {
        const previousElement = previouslyFocusedElementRef.current
        previouslyFocusedElementRef.current = null

        if (!isHTMLElement(previousElement) || !previousElement.isConnected) {
            return
        }

        window.setTimeout(() => {
            if (previousElement.isConnected) {
                previousElement.focus()
            }
        }, 0)
    }, [])

    const focusPrimaryAction = useCallback(() => {
        const primaryAction = primaryActionRef.current

        if (isHTMLElement(primaryAction) && primaryAction.isConnected) {
            primaryAction.focus()
            return
        }

        cardRef.current?.focus()
    }, [cardRef, primaryActionRef])

    const getAllowedFocusRoots = useCallback(() => {
        const roots = [cardRef.current]

        if (allowTargetInteraction && isHTMLElement(targetElement)) {
            roots.push(targetElement)
        }

        return roots.filter(Boolean)
    }, [allowTargetInteraction, cardRef, targetElement])

    const getAllowedFocusableElements = useCallback(() => {
        const roots = getAllowedFocusRoots()
        const focusableElements = roots.flatMap((root) => {
            const elements = []

            if (isFocusableElement(root)) {
                elements.push(root)
            }

            return [...elements, ...getFocusableElementsWithin(root)]
        })

        return uniqueElements(focusableElements)
    }, [getAllowedFocusRoots])

    const isInsideAllowedRoots = useCallback((node) => {
        if (!(node instanceof Node)) {
            return false
        }

        return getAllowedFocusRoots().some((root) => root === node || root.contains(node))
    }, [getAllowedFocusRoots])

    useEffect(() => {
        if (typeof document === "undefined") {
            return
        }

        if (isOpen && !wasOpenRef.current) {
            previouslyFocusedElementRef.current = isHTMLElement(document.activeElement)
                ? document.activeElement
                : null
            wasOpenRef.current = true
        }

        if (!isOpen && wasOpenRef.current) {
            wasOpenRef.current = false
            restoreFocus()
        }
    }, [isOpen, restoreFocus])

    useEffect(() => {
        if (!isOpen || typeof document === "undefined") {
            return
        }

        const timeoutId = window.setTimeout(() => {
            focusPrimaryAction()
        }, 0)

        const handleKeyDown = (event) => {
            if (event.key !== "Tab") {
                return
            }

            const focusableElements = getAllowedFocusableElements()

            if (focusableElements.length === 0) {
                event.preventDefault()
                focusPrimaryAction()
                return
            }

            const firstElement = focusableElements[0]
            const lastElement = focusableElements[focusableElements.length - 1]
            const activeElement = document.activeElement
            const isActiveInsideScope = focusableElements.includes(activeElement)

            if (event.shiftKey) {
                if (!isActiveInsideScope || activeElement === firstElement) {
                    event.preventDefault()
                    lastElement.focus()
                }

                return
            }

            if (!isActiveInsideScope || activeElement === lastElement) {
                event.preventDefault()
                firstElement.focus()
            }
        }

        const handleFocusIn = (event) => {
            if (isInsideAllowedRoots(event.target)) {
                return
            }

            focusPrimaryAction()
        }

        document.addEventListener("keydown", handleKeyDown, true)
        document.addEventListener("focusin", handleFocusIn, true)

        return () => {
            window.clearTimeout(timeoutId)
            document.removeEventListener("keydown", handleKeyDown, true)
            document.removeEventListener("focusin", handleFocusIn, true)
        }
    }, [focusPrimaryAction, getAllowedFocusableElements, isInsideAllowedRoots, isOpen, stepId])

    useEffect(() => {
        return () => {
            if (wasOpenRef.current) {
                wasOpenRef.current = false
                restoreFocus()
            }
        }
    }, [restoreFocus])
}

export default useGuidedTourFocusScope
