import {apiUrl as url, getToken} from "../api";
import axios from "axios";

const apiUrl = url + "/v2"
export const getAllByTypeClientAPI = async (type, clientId) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/neuromotor/all?type=${type}&clientId=${clientId}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 8000
    })

}

