import {createSelector} from "reselect";

const reducer = state => state.workoutRoutine;

export const selectWorkoutRoutines = createSelector([reducer], slice => slice.workouts)
export const selectWorkoutRoutineLoading = createSelector([reducer], slice => slice.loading)
export const selectWorkoutRoutineChangingStatus = createSelector([reducer], slice => slice.changingStatus)
export const selectWorkoutRoutine = createSelector([reducer], slice => slice.workout)
export const selectWorkoutRoutineDeleted = createSelector([reducer], slice => slice.routineDeleted)
export const selectWorkoutRoutineUpdate = createSelector([reducer], slice => slice.routineUpdated)
export const selectWorkoutRoutineSessionCreated = createSelector([reducer], slice => slice.sessionCreated)
export const selectWorkoutRoutineSessionCreating = createSelector([reducer], slice => slice.sessionCreating)
export const selectWorkoutRoutineSessionUpdated = createSelector([reducer], slice => slice.sessionUpdated)
export const selectWorkoutRoutineSessionUpdating = createSelector([reducer], slice => slice.sessionUpdating)
export const selectWorkoutRoutineSessionCloned = createSelector([reducer], slice => slice.sessionCloned)
export const selectWorkoutCreated = createSelector([reducer], slice => slice.routineCreated)
export const selectWorkoutRoutineFeedbacks = createSelector([reducer], slice => slice.feedbacks)
export const selectWorkoutRoutineProgress = createSelector([reducer], slice => slice.workoutProgress)