import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutRoutineCloned = () => {
    const {t} = useTranslation();
    const {type, clientId, to} = useParams();
    const navigate = useNavigate();
    useComponentTranslations('trainingLibrary', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {

        if (!clientId)
            navigate(`/user/workout-library/${Number(type) + 1}`)
        else
            navigate(`/user/client/${clientId}/workout/${Number(type) + 1}`)
    }

    const onClickGoToClient = () => {
        navigate(`/user/client/${to}/workout/${Number(type) + 1}`)
    }

    return (
        <Page title={t("trainingLibrary:clonedWorkoutsTitle")} pb={"pb-2"} goBackLink={handleGoBack}>
            <div className={'row'}>
                <div className={"col-12"}>
                    <div className={'card card-body border-0'}>
                        <div className={'row justify-content-center'}>
                            <div className={'col-6 text-center'}>
                                <div className={"rounded-circle avatar avatar-xl text-success"}>
                                    <i className={`fa-regular fa-circle-check`}></i>
                                </div>
                            </div>
                            <div className={'col-12 text-center mt-2'}>
                                <span className={"fw-semibold fs-4 lh-1 d-block"}>
                                    {t("trainingLibrary:clonedWorkoutsProcessTitle")}
                                </span>
                                <span className={"d-block mt-3"}>
                                    {t("trainingLibrary:clonedWorkoutsProcessDescription")}
                                </span>
                            </div>
                            <div className={'col-12 text-center pt-4'}>
                                {
                                    to && to !== "null" && (
                                        <div className={'d-grid mb-2'}>
                                            <button className={"btn btn-primary"} onClick={onClickGoToClient}>
                                                {t("trainingLibrary:viewClientWorkouts")}
                                            </button>
                                        </div>
                                    )
                                }
                                <div className={'d-grid'}>
                                    <button className={`btn ${clientId ? "btn-primary" : "btn-outline-primary"}`} onClick={handleGoBack}>
                                        {t("trainingLibrary:backButton")}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </Page>
    )
}
export default WorkoutRoutineCloned;