import WorkoutPdfExerciseCard from "./WorkoutPdfExerciseCard";
import WorkoutPdfMultipleExercises from "./WorkoutPdfMultipleExercises";


const WorkoutPdfExercise = ({exerc, showImages}) => {

    switch (exerc.type) {
        case 0:
            return (
                <div className={"border rounded-1 px-4"}>
                    <WorkoutPdfExerciseCard showImages={showImages} exerc={exerc} mainId={exerc.id}/>
                </div>
            )
        case 1:

            const showMultiples = exerc.exercises[0].series.filter(series => series.tipo === 6).length > 1;
            if (showMultiples) {
                return (
                    <div className={"border rounded-1 px-4"}>
                        <WorkoutPdfMultipleExercises showImages={showImages}   exerc={exerc} mainId={exerc.id}/>
                    </div>
                )
            } else {
                const ex = exerc.exercises[0].series.find(series => series.tipo === 6);
                const serie = exerc.exercises[0].series.filter(series => series.tipo !== 6);
                const newEx = {...ex?.exercicio};
                newEx.series = serie;
                const exs = [newEx];
                const newExerc = {
                    id: exerc.id,
                    order: exerc.order,
                    type: exerc.type,
                    exercises: exs
                };
                return (
                    <div className={"border rounded-1 px-4"}>
                        <WorkoutPdfExerciseCard exerc={newExerc} showImages={showImages} mainId={exerc.id}/>
                    </div>
                )
            }


        case 2:
            return (
                <div className={"border rounded-1 px-4"}>
                    <WorkoutPdfExerciseCard exerc={exerc.exercises} showImages={showImages} mainId={exerc.id} exercList={exerc.exercises}/>
                </div>
            )
        default:
            return "";
    }

}
export default WorkoutPdfExercise;