import {apiUrl, apiUrlV2, getToken} from "../api";
import axios from "axios";

export const checkPendingCsatAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/check/csat`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

