export const USER_EXPERIENCE_CACHE_PREFIX = "mfit:user-experience-cache:v1"
export const USER_EXPERIENCE_CACHE_TTL_MS = 30 * 24 * 60 * 60 * 1000

export const USER_EXPERIENCE_EVENTS = {
    STARTED: "STARTED",
    COMPLETED: "COMPLETED",
    DISMISSED: "DISMISSED"
}

const hasWindow = () => typeof window !== "undefined"

const getUserExperienceCacheKey = (userId) => `${USER_EXPERIENCE_CACHE_PREFIX}:${userId}`

const parseCachePayload = (rawValue) => {
    if (!rawValue) {
        return {}
    }

    try {
        const parsedValue = JSON.parse(rawValue)
        return parsedValue && typeof parsedValue === "object" ? parsedValue : {}
    } catch (error) {
        return {}
    }
}

const readUserExperienceCachePayload = (userId) => {
    if (!hasWindow() || !userId) {
        return {}
    }

    try {
        return parseCachePayload(window.localStorage.getItem(getUserExperienceCacheKey(userId)))
    } catch (error) {
        return {}
    }
}

const writeUserExperienceCachePayload = (userId, payload) => {
    if (!hasWindow() || !userId) {
        return false
    }

    try {
        window.localStorage.setItem(getUserExperienceCacheKey(userId), JSON.stringify(payload))
        return true
    } catch (error) {
        return false
    }
}

const normalizeCacheEntry = (entry) => {
    if (!entry || typeof entry !== "object") {
        return null
    }

    if (typeof entry.experienceId !== "string" || !entry.experienceId.trim()) {
        return null
    }

    return {
        ...entry,
        experienceId: entry.experienceId.trim(),
        cachedAt: Number(entry.cachedAt) || Date.now()
    }
}

export const readUserExperienceCacheEntry = (userId, experienceId) => {
    if (!experienceId) {
        return null
    }

    const payload = readUserExperienceCachePayload(userId)
    return normalizeCacheEntry(payload?.[experienceId]) || null
}

export const writeUserExperienceCacheEntry = (userId, state) => {
    const normalizedState = normalizeCacheEntry(state)
    if (!normalizedState) {
        return false
    }

    const payload = readUserExperienceCachePayload(userId)
    return writeUserExperienceCachePayload(userId, {
        ...payload,
        [normalizedState.experienceId]: {
            ...normalizedState,
            cachedAt: Date.now()
        }
    })
}

export const isUserExperienceCacheEntryStale = (entry) => {
    if (!entry) {
        return true
    }

    return (Date.now() - Number(entry.cachedAt || 0)) > USER_EXPERIENCE_CACHE_TTL_MS
}

export const applyUserExperienceEventToState = (currentState, {experienceId, event, now = new Date().toISOString()}) => {
    const normalizedCurrentState = normalizeCacheEntry(currentState)
    const seenCount = Math.max(Number(normalizedCurrentState?.seenCount) || 0, 0)
    const nextState = {
        ...(normalizedCurrentState || {}),
        experienceId,
        updatedAt: now
    }

    switch (event) {
        case USER_EXPERIENCE_EVENTS.STARTED:
            nextState.firstStartedAt = normalizedCurrentState?.firstStartedAt || now
            nextState.lastStartedAt = now
            nextState.seenCount = seenCount + 1
            nextState.status = normalizedCurrentState?.status || USER_EXPERIENCE_EVENTS.STARTED
            return nextState
        case USER_EXPERIENCE_EVENTS.COMPLETED:
            nextState.firstStartedAt = normalizedCurrentState?.firstStartedAt || now
            nextState.lastStartedAt = normalizedCurrentState?.lastStartedAt || now
            nextState.completedAt = normalizedCurrentState?.completedAt || now
            nextState.seenCount = Math.max(seenCount, 1)
            nextState.status = USER_EXPERIENCE_EVENTS.COMPLETED
            return nextState
        case USER_EXPERIENCE_EVENTS.DISMISSED:
            nextState.dismissedAt = normalizedCurrentState?.dismissedAt || now
            nextState.seenCount = Math.max(seenCount, 1)
            nextState.status = normalizedCurrentState?.status === USER_EXPERIENCE_EVENTS.COMPLETED
                ? USER_EXPERIENCE_EVENTS.COMPLETED
                : USER_EXPERIENCE_EVENTS.DISMISSED
            return nextState
        default:
            return nextState
    }
}

export const captureUserExperienceCacheEntries = () => {
    if (!hasWindow()) {
        return []
    }

    try {
        return Object.keys(window.localStorage)
            .filter((key) => key.startsWith(USER_EXPERIENCE_CACHE_PREFIX))
            .map((key) => ({
                key,
                value: window.localStorage.getItem(key)
            }))
    } catch (error) {
        return []
    }
}

export const restoreUserExperienceCacheEntries = (entries = []) => {
    if (!hasWindow()) {
        return
    }

    try {
        entries.forEach(({key, value}) => {
            if (typeof key === "string" && key.startsWith(USER_EXPERIENCE_CACHE_PREFIX) && typeof value === "string") {
                window.localStorage.setItem(key, value)
            }
        })
    } catch (error) {
    }
}
