import Page from "../../components/page/Page";
import {useEffect} from "react";
import {useNavigate, useParams, useSearchParams} from "react-router-dom";
import SubscriptionPlanCard from "../../components/subscription/SubscriptionPlanCard";
import {useDispatch, useSelector} from "react-redux";
import {selectSubPlanList, selectSubPlanLoading} from "../../store/subscription/subscriptionSelector";
import {fetchSubPlanList, setCoupon} from "../../store/subscription/subscriptionReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";


const SubscriptionPlan = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const {type} = useParams();
    const navigate = useNavigate();
    const subPlanList = useSelector(selectSubPlanList)
    const loadingSubPlan = useSelector(selectSubPlanLoading)
    const [searchParams] = useSearchParams();
    useComponentTranslations('subscriptionPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const goBackTo = searchParams.get("goBackTo");

    const handleGoBack = () => {
        if (goBackTo === "subscriptionAddTime") {
            navigate("/user/subscription")
        } else
            navigate(`/subscription?step=1${goBackTo ? `&goBackTo=${goBackTo}` : ""}`)
    }
    useEffect(() => {
        if (Number(type) !== 1000) {
            navigate(`/subscription/purchase/${type}${goBackTo ? `?goBackTo=${goBackTo}` : ""}`)
        }
    }, [type, navigate, goBackTo])

    useEffect(() => {
        if (!subPlanList)
            dispatch(fetchSubPlanList());
    }, [subPlanList, dispatch]);

    useEffect(() => {
        dispatch(setCoupon(null))
    }, [dispatch])


    return (
        <Page mt={"mt-n4"} contentHeader={true} loading={loadingSubPlan} goBackLink={handleGoBack}>
            <div className={"card card-body border-0"}>
                <div className={"row  mt-2"}>
                    <div className={"col-12"}>
                        <span className={"fs-1 fst-italic d-block lh-1  fw-light"}>
                            {t("subscriptionPage:planUnlimitedHeadingLine1")}
                        </span>
                        <span className={"fs-1 fst-italic  fw-semibold d-block"}>
                           {t("subscriptionPage:planUnlimitedHeadingLine2")}
                        </span>
                    </div>
                    <div className={"col-6"}>
                        <hr/>
                    </div>
                </div>
                {
                    subPlanList &&
                    <div className={"row mt-1"}>
                        <div className={"col-12"}>
                            <SubscriptionPlanCard subPlan={subPlanList.find(s => s.id === 1000)}/>
                        </div>
                        <div className={"col-12 mt-3"}>
                            <SubscriptionPlanCard subPlan={subPlanList.find(s => s.id === 1001)}/>
                        </div>
                        <div className={"col-12  mt-3"}>
                            <SubscriptionPlanCard subPlan={subPlanList.find(s => s.id === 1002)}/>
                        </div>
                        <div className={"col-12  mt-3"}>
                            <SubscriptionPlanCard subPlan={subPlanList.find(s => s.id === 1003)}/>
                        </div>
                    </div>
                }
            </div>
        </Page>
    )
}
export default SubscriptionPlan;
