import React, {useEffect, useMemo, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {Form, Formik} from "formik";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import EmptySet from "../../components/empty-set/EmptySet";
import EvaluationCompareTableComponent from "../../components/evaluation-components/EvaluationCompareTableComponent";
import {fetchClient} from "../../store/client/clientReducer";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {compareCustom,} from "../../store/custom-evaluation/customEvaluationReducer";
import {
    getCustomLoading,
    selectCompareCustom,
    selectCustomEvaluation,
} from "../../store/custom-evaluation/customEvaluationSelector";
import {customFields} from "../../utils/evaluationComponents/fields";
import i18n from "i18next";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import enUS from "./locales/en-us.json";
import {calculateIMC, formatIMC} from "../../utils/physicalEvaluation/imcFormula";
import Text from "../../components/utils/emoji/Text";
import he from "he";
import {formatRQC} from "../../utils/physicalEvaluation/rqcFormula";
import {buildClientCustomRoute} from "../../utils/client/evaluationRoutes";

export default function CustomEvaluationCompare() {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, customIds} = useParams();
    const {t} = useTranslation("customEvaluation");
    const selectedClient = useSelector(selectSelectedClient);
    const loadingClient = useSelector(isClientsLoading);
    const loadingCustom = useSelector(getCustomLoading);
    const compareCustomList = useSelector(selectCompareCustom) || [];
    const customDetail = useSelector(selectCustomEvaluation);
    useComponentTranslations('customEvaluation', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})
    syncMomentLocale(i18n.language);

    const [detailValues, setDetailValues] = useState({});
    const [currentSelectedId, setCurrentSelectedId] = useState(null);

    const isComparing = currentSelectedId === null;
    const noAnswerLabel = "—";

    const unitDefaults = {
        peso: "kg",
        estatura: "cm",
        idade: "anos",
        circ_torax: "cm",
        circ_be: "cm",
        circ_bd: "cm",
        circ_ce: "cm",
        circ_cin: "cm",
        circ_abd: "cm",
        circ_quad: "cm",
        circ_pe: "cm",
        circ_pd: "cm",
        circ_punho: "cm",
        per_gord: "%",
        pes_gord: "kg",
        magra: "kg",
    };

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        const idsArray = customIds?.split(",") || [];
        dispatch(compareCustom({ids: idsArray}));
        setCurrentSelectedId(null);
    }, [dispatch, customIds]);

    const handleGoBackPage = () => {
        navigate(buildClientCustomRoute(id));
    };

    const handleSelectCustom = (idStr) => {
        if (currentSelectedId === idStr) {
            setCurrentSelectedId(null);
            setDetailValues({});
        } else {
            setCurrentSelectedId(idStr);
            const item = compareCustomList
                .find(it => String(it.id) === idStr);

            const rawImc = item.imc != null
                ? item.imc
                : (item.peso && item.estatura)
                    ? calculateIMC(item.peso, item.estatura)
                    : null;

            const imcFormatted = rawImc != null
                ? formatIMC(rawImc, t)
                : noAnswerLabel;

            const base = {
                idade: item.idade,
                peso: item.peso,
                estatura: item.estatura,
                observacao: item.observacao != null
                    ? he.decode(item.observacao)
                    : noAnswerLabel,
                data: item.data,
                imc: imcFormatted,
                proximaAvaliacao: item.proximaAvaliacao
                    ? moment(item.proximaAvaliacao).format("L")
                    : noAnswerLabel,
            };

            (item.campos || [])
                .filter(c => c.tipo !== 2)
                .forEach(c => {
                    const key = c.campo.trim();
                    base[key] = c.valor != null
                        ? he.decode(c.valor)
                        : noAnswerLabel;
                });

            setDetailValues(base);
        }
    };

    const tableFormatters = useMemo( () => ({
        rcq: raw => formatRQC(raw, selectedClient?.sexo, t),
        imc: (_raw, row) => {
            const value = row.imc != null
                ? row.imc
                : calculateIMC(row.peso, row.estatura);
            return formatIMC(value, t);
        }
    }),[selectedClient, t]);

    const unionMap = new Map(
        customFields.map((cf) => [String(cf.id), {id: String(cf.id), label: cf.label, unit:cf.unit}])
    );

    compareCustomList.forEach(item =>
        (item?.campos || [])
            .filter(c => c.tipo !== 2)
            .forEach(c => {
                const key = c.campo.trim();
                if (!unionMap.has(key)) {
                    const def = customFields.find(cf => String(cf.id) === key);
                    unionMap.set(key,
                        {
                            id: key,
                            label: c.campo,
                            unit:  def?.unit ?? unitDefaults[key],
                        });
                }
            })
    );

    (customDetail?.campos || [])
        .filter(c => c.tipo !== 2)
        .forEach(c => {
            const key = c.campo.trim();
            if (!unionMap.has(key)) {
                const def = customFields.find(cf => String(cf.id) === key);
                unionMap.set(key, {id: key, label: c.campo, unit: def?.unit});
            }
        });

    const unionCampos = Array.from(unionMap.values());

    const tableData = compareCustomList.map((item) => {
        const row = {
            ...item,
            observacao: item.observacao != null
                ? he.decode(item.observacao)
                : noAnswerLabel,
            proximaAvaliacao: item.proximaAvaliacao
                ? moment(item.proximaAvaliacao).format("L")
                : noAnswerLabel,
        };
        (item?.campos || [])
            .filter(c => c.tipo !== 2)
            .forEach(c => {
                const key = c.campo.trim();
                row[key] = c.valor != null
                        ? he.decode(c.valor)
                        : noAnswerLabel;
            });
        return row;
    });


    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className="pb-4 pt-2"
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />

            <Page contentHeader={false} loading={loadingCustom} pb="pb-2">
                <div className="row justify-content-center">
                    <div className="col-12">
                        <div className="card card-body border-0">
                            {compareCustomList.length === 0 && (
                                <EmptySet
                                    icon="fa-empty-set"
                                    message={t("customEvaluation:emptySetCompare")}
                                />
                            )}
                            {isComparing && unionCampos.length > 0 && tableData.length > 0 && (
                                <>
                                    <div className="col-12 pb-2">
                                        <span className="fw-semibold fs-5 d-block">
                                            {t("customEvaluation:customEvaluation")}
                                        </span>
                                    </div>
                                    <span>{t("customEvaluation:result")}</span>
                                    <EvaluationCompareTableComponent
                                        fields={unionCampos}
                                        data={tableData}
                                        noAnswerLabel={noAnswerLabel}
                                        firstColumnTitle={t("customEvaluation:fields")}
                                        fieldFormatters={tableFormatters}
                                        showComparison
                                        comparisonLabel={t("customEvaluation:compareTitle")}
                                    />
                                </>
                            )}
                            {!isComparing && (
                                <Formik
                                    enableReinitialize
                                    initialValues={detailValues}
                                    onSubmit={() => {
                                    }}
                                >
                                    {({values}) => (
                                        <Form>
                                            <span className="fw-semibold fs-5 d-block mb-2">
                                              {t("customEvaluation:customDetails")}
                                            </span>
                                            {unionCampos.map(field => (
                                                <div key={field.id} className="row my-2">
                                                    <label htmlFor={field.id} className="fw-semibold">
                                                        <Text>{field.label}</Text>
                                                    </label>
                                                    {["data", "proximaAvaliacao", "imc"].includes(field.id) ? (
                                                        <span className={"bg-white border-0 text-wrap d-block text-break"}>
                                                            {values[field.id] || "—"}
                                                            {field.unit ? `${field.unit}` : ""}
                                                        </span>
                                                    ) : field.id === "observacao" ? (
                                                        <div
                                                            id={field.id}
                                                            className="form-control-plaintext bg-white border-0 d-block p-2 text-wrap text-break"
                                                        >
                                                            <Text>{values[field.id] || noAnswerLabel}</Text>
                                                        </div>
                                                    ) : (
                                                        <span className="bg-white border-0 text-wrap d-block text-break">
                                                            {(values[field.id] || noAnswerLabel)}
                                                            {field.unit ? `${field.unit}` : ""}
                                                        </span>
                                                    )}
                                                </div>
                                            ))}
                                        </Form>
                                    )}
                                </Formik>
                            )}
                            <button
                                className={`btn ${
                                    !isComparing ? "btn-outline-primary" : "btn-primary"
                                } my-2`}
                                onClick={() => setCurrentSelectedId(null)}
                            >
                                {t("customEvaluation:compareTitle")}
                            </button>
                            <div className={"d-flex flex-column gap-2"}>
                                {compareCustomList.map((custom) => {
                                    const idStr = String(custom.id);
                                    const isActive = currentSelectedId === idStr;
                                    return (
                                        <button
                                            key={idStr}
                                            className={`btn ${
                                                isActive ? "btn-primary" : "btn-outline-primary"
                                            }`}
                                            onClick={() => handleSelectCustom(idStr)}
                                        >
                                            {custom.data
                                                ? moment(custom.data).format("L")
                                                : t("customEvaluation:noAnswer")}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
}
