import ContentHeader from "../contentheader/ContentHeader";
import LoadingBlock from "../loader/LoadingBlock";
import React from "react";

const Page = ({
                  title,
                  goBackLink,
                  showGoBack,
                  children,
                  xs = "12",
                  md = "6",
                  lg = "6",
                  xl = "4",
                  contentHeader = true,
                  mt = "mt-n4-5",
                  pb,
                  loading = false
              }) => {
    return (
        <>
            {
                contentHeader &&
                <ContentHeader showGoBack={showGoBack} goBackLink={goBackLink} title={title} xs={xs} md={md} lg={lg} xl={xl} pb={pb}/>
            }

            <div className={'container-fluid bg-body'}>
                <div className={'row justify-content-center '}>
                    <div className={`col-${xs} col-md-${md} col-lg-${lg} col-xl-${xl} ${mt}`}>
                        {
                            loading &&
                            <div className={"card card-body border-0"}>
                                <LoadingBlock/>
                            </div>
                        }
                        {
                            !loading &&
                            <>
                                {children}
                            </>
                        }
                    </div>
                </div>
            </div>


        </>
    )
}
export default Page;