import Modal from "react-bootstrap/Modal";
import {useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {deleteClientGroup, updateClientGroup} from "../../store/client-group/clientGroupReducer";
import {selectClientGroupMutationLoading} from "../../store/client-group/clientGroupSelector";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ClientGroupCreateModal from "./ClientGroupCreateModal";
import DeleteModal from "../modal/DeleteModal";

const ClientGroupCard = ({clientGroup}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const [showActionModal, setShowActionModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const loading = useSelector(selectClientGroupMutationLoading);

    useComponentTranslations('clientGroupComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoToClientGroup = () => {
        setShowActionModal(false);
        navigate(`/user/client/list/group/${clientGroup.id}`)
    }

    const handleDeleteGroup = () => {
        dispatch(deleteClientGroup(clientGroup.id))
        setShowDeleteModal(false)
        setShowActionModal(false)
    }

    const handleFormSubmit = (values) => {
        dispatch(updateClientGroup({
            formData: values,
            id: clientGroup.id
        }))
        setShowEditModal(false)
        setShowActionModal(false)
    }

    return (
        <div className={'col-12  mb-2'}>
            <div className={`card card-body text-default clickable-element`} onClick={() => setShowActionModal(true)}>
                <div className={'row d-flex'}>
                    <div className='col-12 align-self-center'>
                        <span
                            className={'fw-semibold d-block text-primary'}>{clientGroup.idUser === 0 ? t(`clientGroupComponent:${clientGroup.nome_i18n}`) : clientGroup.nome}</span>
                        {
                            clientGroup.clientCount > 1 &&
                            <span className={'d-block small'}>
                                {clientGroup.clientCount} {t("clientGroupComponent:clientsInThisGroup")}
                            </span>
                        }
                        {
                            clientGroup.clientCount === 1 &&
                            <span className={'d-block small'}>
                                {clientGroup.clientCount} {t("clientGroupComponent:clientInThisGroup")}
                            </span>
                        }
                        {
                            clientGroup.clientCount === 0 &&
                            <span className={'d-block small'}>
                                {t("clientGroupComponent:noClientsInThisGroup")}
                            </span>
                        }
                    </div>
                </div>
            </div>

            <Modal centered show={showActionModal} onHide={() => setShowActionModal(false)}>
                <Modal.Body>
                    <div className={'row justify-content-between'}>
                        <div className={"col-auto pb-2"}>
                            <span className={'fw-semibold'}>{t("clientGroupComponent:whatYouWannaDo")}</span>
                        </div>
                        <div className={'col-auto'}>
                            <i
                                className="fa-regular fa-xmark cursor-pointer"
                                onClick={() => setShowActionModal(false)}
                                role="button"
                                aria-label={t("clientGroupComponent:close")}
                            />
                        </div>
                        <div className={"col-12"}>
                            <div className={'d-grid mb-2'}>
                                <button className={'btn btn-outline-primary'}
                                        onClick={handleGoToClientGroup}>{t("clientGroupComponent:openGroup")}</button>
                            </div>
                            {
                                clientGroup.idUser > 0 &&
                                <>
                                    <div className={'d-grid mb-2'}>
                                        <button
                                            className={'btn btn-outline-primary'}
                                            onClick={() => {
                                                setShowActionModal(false);
                                                setShowEditModal(true);
                                            }}
                                        >
                                            {t("clientGroupComponent:edit")}
                                        </button>
                                    </div>
                                    <div className={'d-grid mb-2'}>
                                        <button
                                            className={'btn btn-outline-danger'}
                                            onClick={() => {
                                                setShowActionModal(false);
                                                setShowDeleteModal(true);
                                            }}
                                        >
                                            {t("clientGroupComponent:delete")}
                                        </button>
                                    </div>
                                </>
                            }
                        </div>
                    </div>
                </Modal.Body>
            </Modal>

            <ClientGroupCreateModal
                show={showEditModal}
                onHide={() => setShowEditModal(false)}
                onSubmit={handleFormSubmit}
                title={t("clientGroupComponent:editGroup")}
                label={t("clientGroupComponent:groupName")}
                submitText={t("clientGroupComponent:save")}
                cancelText={t("clientGroupComponent:close")}
                loading={loading}
                requiredMessage={t("clientGroupComponent:requiredField")}
                minLengthMessage={t("clientGroupComponent:nameMustHave3letters")}
                maxLengthMessage={t("clientGroupComponent:max245Characters")}
                initialName={clientGroup.nome}
            />

            <DeleteModal
                show={showDeleteModal}
                onClose={() => setShowDeleteModal(false)}
                onConfirm={handleDeleteGroup}
                deleteTitle={t("clientGroupComponent:groupDeleteConfirmationTitle")}
                deleteSubtitle={t("clientGroupComponent:groupDeleteConfirmationSubtitle")}
                confirmLabel={t("clientGroupComponent:confirmDelete")}
                closeLabel={t("clientGroupComponent:close")}
            />
        </div>
    )
}

export default ClientGroupCard;
