import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useCallback, useEffect, useMemo} from "react";
import Page from "../../components/page/Page";
import {getCustomLoading, selectCustomEvaluation} from "../../store/custom-evaluation/customEvaluationSelector";
import {fetchClient} from "../../store/client/clientReducer";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "../custom-evaluation/locales/es-es.json";
import ptPT from "../custom-evaluation/locales/pt-pt.json";
import ptBR from "../custom-evaluation/locales/pt-br.json";
import enUS from "../custom-evaluation/locales/en-us.json";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {getOneCustom} from "../../store/custom-evaluation/customEvaluationReducer";
import ImageCarousel from "../../utils/imagecarousel/ImageCarousel";
import {useTranslation} from "react-i18next";
import {useCustomActions} from "../../utils/customEvaluation/useCustomActions";
import CustomEvaluationActionsButtons from "../../components/custom-evaluation/CustomEvaluationActionsButtons";
import {calculateIMC, formatIMC} from "../../utils/physicalEvaluation/imcFormula";
import {isDesktop} from "react-device-detect";
import Text from "../../components/utils/emoji/Text";
import {formatGender} from "../../utils/gender/formatGender";
import {buildClientCustomRoute} from "../../utils/client/evaluationRoutes";

const CustomEvaluationView = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, customId} = useParams();
    const {t} = useTranslation("customEvaluation");
    const loadingCustom = useSelector(getCustomLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const customDetails = useSelector(selectCustomEvaluation);
    syncMomentLocale(i18n.language);
    useComponentTranslations('customEvaluation', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})

    const {state: {showDeleteModal, currentCustom, deleteSubmitting}, handlers} = useCustomActions();
    const {setCurrentCustom} = handlers;

    const computedIMC = useMemo(() => {
        return calculateIMC(customDetails?.peso, customDetails?.estatura);
    }, [customDetails?.peso, customDetails?.estatura]);

    const imcToShow = customDetails?.imc ?? computedIMC;

    const imcFormatted = imcToShow != null
        ? formatIMC(imcToShow, t)
        : "-";

    const campos = customDetails?.campos || [];

    const imageItems = useMemo(() => {
        return (customDetails?.campos ?? [])
            .filter(field => field.tipo === 2 && field.valor?.trim())
            .map(field => ({
                id: field.id,
                url: field.valor
            }));
    }, [customDetails?.campos]);

    const genderLabel = useMemo(
        () => formatGender(selectedClient?.sexo, t),
        [selectedClient?.sexo, t]
    );

    const handleGoBackPage = useCallback(() => {
        navigate(buildClientCustomRoute(id));
    }, [navigate, id]);

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(getOneCustom(customId));
    }, [dispatch, customId]);

    useEffect(() => {
        if (customDetails) {
            setCurrentCustom(customDetails);
        }
    }, [customDetails, setCurrentCustom]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loadingCustom} pb={"pb-2"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            {!customDetails && loadingCustom &&
                                <div className={"text-center mt-4"}>
                                    <LoadingBlock/>
                                </div>
                            }
                            <span className={"fw-semibold fs-5 d-block"}>
                                <Text>{customDetails?.tipo}</Text>
                            </span>
                            {customDetails?.data && (
                                <span className={"text-md"}>
                                    {moment(customDetails.data).format('LL')}
                                </span>
                            )}
                            <div className={"border-0 p-0 pt-2"}>
                                <div>
                                    <span className="fw-semibold d-block">{t("customEvaluation:age")}</span>
                                    <span>{customDetails?.idade}</span>
                                </div>
                                <div>
                                    <span className="fw-semibold d-block">{t("customEvaluation:height")}</span>
                                    <span
                                    >{customDetails?.estatura}cm</span>
                                </div>
                                <div>
                                    <span className="fw-semibold d-block">{t("customEvaluation:weight")}</span>
                                    <span>{customDetails?.peso}kgs</span>
                                </div>
                                <div>
                                    <span className="fw-semibold  d-block">{t("customEvaluation:gender")}</span>
                                    <span>{genderLabel}</span>
                                </div>
                                {campos
                                    .filter((field) => field.tipo !== 2)
                                    .map((field) => (
                                        <div key={field.id}>
                                            <div className={"fw-semibold mt-2"}>
                                                <Text>{field.campo}</Text>
                                            </div>
                                            <div>
                                                <span>
                                                    <Text>{field.valor}</Text>
                                                </span>
                                            </div>
                                        </div>
                                    ))}
                                <div className={"py-2"}>
                                    <span className={"fw-semibold"}>{t("customEvaluation:result")}</span>
                                </div>
                                {customDetails?.imc != null && (
                                    <>
                                        <label
                                            className={"fw-semibold"}>{t("customEvaluation:imc.label")}</label>
                                        <span>{imcFormatted}</span>
                                    </>
                                )}
                                <div>
                                    <span className="fw-semibold d-block">{t("customEvaluation:observation")}</span>
                                    <span>
                                        <Text>{customDetails?.observacao}</Text>
                                    </span>
                                </div>
                                {imageItems.length > 0 && (
                                    <div className="my-3">
                                        <ImageCarousel images={imageItems}/>
                                    </div>
                                )}
                            </div>
                        </div>
                        <div className={"card card-body border-0 mt-2 d-print-none"}>
                            <div className={isDesktop ? "row my-2" : ""}>
                                {isDesktop && (
                                    <div className={"col-12"}>
                                        <button
                                            type={"button"}
                                            className={"btn btn-primary w-100 no-print"}
                                            onClick={() => {
                                                setTimeout(() => window.print(), 500)
                                            }}>
                                            {t("customEvaluation:print")}
                                        </button>
                                    </div>
                                )}
                            </div>
                            <button
                                className={"btn btn-outline-primary w-100"}
                                onClick={handleGoBackPage}>
                                {t("customEvaluation:back")}
                            </button>
                            <button className={"btn btn-outline-primary w-100 mt-2"}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handlers.goEdit();
                                    }}>{t("customEvaluation:edit")}
                            </button>
                            <button className={"btn btn-outline-danger w-100 mt-2"}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handlers.openDeleteModal();
                                    }}
                            >{t("customEvaluation:delete")}
                            </button>
                        </div>
                    </div>
                </div>
            </Page>
            <CustomEvaluationActionsButtons
                state={{showDeleteModal, currentCustom, deleteSubmitting}}
                handlers={handlers}
            />
        </>
    )
}

export default CustomEvaluationView;
