import {createSelector} from "reselect";

const reducer = state => state.updates

export const selectUpdatesCount = createSelector(reducer, state => state.updatesCount)
export const selectUpdatesLoading = createSelector(reducer, state => state.loading)
export const selectUpdateCountByType = createSelector(reducer, state => state.updateCountByType)
export const selectUpdates = createSelector(reducer, state => state.updates)
 export const selectResolveAllUpdatesStatus = createSelector(reducer, state => state.resolveAllUpdatesStatus)
export const selectResolveAllUpdatesContext = createSelector(reducer, state => state.resolveAllUpdatesContext)
export const selectIndividualUpdateLoading = createSelector(
    [reducer, (_, updateId) => updateId],
    (state, updateId) => Boolean(state.loadingByUpdateId?.[updateId])
)
