import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    loading: false,
    weeklyFrequency: null,
    monthlyFrequency: null,
    yearlyFrequency: null
};
export const slice = createSlice({
    name: "frequencyTraining",
    initialState,
    reducers: {
        fetchWeeklyFrequency(state) {
            state.loading = true;
        },
        setWeeklyFrequency(state, action) {
            state.weeklyFrequency = action.payload;
            state.loading = false;
        },
        fetchMonthlyFrequency(state) {
            state.loading = true;
        },
        setMonthlyFrequency(state, action) {
            state.monthlyFrequency = action.payload;
            state.loading = false;
        },
        fetchYearlyFrequency(state) {
            state.loading = true;
        },
        setYearlyFrequency(state, action) {
            state.yearlyFrequency = action.payload;
            state.loading = false;
        },
        onError(state) {
            state.loading = false;
        }
    }
})

export const {
    setWeeklyFrequency, fetchWeeklyFrequency, fetchMonthlyFrequency, fetchYearlyFrequency, setMonthlyFrequency, setYearlyFrequency, onError
} = slice.actions;

export const frequencyTrainingReducer = slice.reducer;