import React from "react";
import {formatCurrency, formatNumber} from "../../../utils/translation/localeUtils";

const CurrencyFormatter = ({value, language = "pt-BR", country = "BRL", symbol = true}) => {
    const formattedValue = symbol
        ? formatCurrency(value, language, country, {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
        })
        : formatNumber(value, language, {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
        });

    return <span>{formattedValue}</span>;
};

export default CurrencyFormatter;
