import {createSelector} from "reselect";

const reducer = state => state.frequencyTraining;


export const selectWeeklyFrequency= createSelector(reducer, (slice) => slice.weeklyFrequency);
export const selectMonthlyFrequency= createSelector(reducer, (slice) => slice.monthlyFrequency);
export const selectYearlyFrequency= createSelector(reducer, (slice) => slice.yearlyFrequency);
export const selectFrequencyTrainingLoading = createSelector(reducer, (slice) => slice.loading);
