import {useDispatch, useSelector} from "react-redux";
import {isPushSent, selectNotifications} from "../../store/push/pushSelector";
import {useEffect, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import PushRecurringEditForm from "../../components/push/PushRecurringEditForm";
import PushScheduleEditForm from "../../components/push/PushScheduleEditForm";
import {fetchNotifications} from "../../store/push/pushReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Page from "../../components/page/Page";


const PushEdit = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id, type} = useParams();
    const notifications = useSelector(selectNotifications);
    const [notification, setNotification] = useState(null);
    const sent = useSelector(isPushSent)
    useComponentTranslations('pushPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        if (sent) {
            navigate(`/user/push/sent/${type}`)
        }
    }, [sent, navigate, dispatch, type]);

    useEffect(() => {

        if (!notifications)
            dispatch(fetchNotifications(type));
    }, [dispatch, type, notifications]);

    useEffect(() => {
        if (notifications)
            setNotification(notifications?.find(n => n.id === Number(id)));

    }, [id, notifications, dispatch, type]);


    if (!notification) return null;

    return (
        <Page title={t(`pushPage:editNotification`)}>
            <div className={'card card-body'}>
                {
                    notification.type === "recurring" ?
                        <PushRecurringEditForm notification={notification}/> :
                        <PushScheduleEditForm notification={notification}/>
                }
            </div>
        </Page>
    );
};

export default PushEdit;
