import {apiUrl , getToken} from "../api";
import axios from "axios";

export const getWorkoutSessionByIdAPI = async (id) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/workout/prescription/?id=${id}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    });
}

