import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchWeeklyFrequencyAPI = async (id, startDate, endDate) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/training-frequency/week?id=${id}&startDate=${startDate}&endDate=${endDate}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

