import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    messages: [],
    waitingMessage: false,
    loading: false,
}

export const slice = createSlice({
    name: "chatbot",
    initialState,
    reducers: {
        setMessageAsNotNew(state, action) {
            const message = state.messages.find(msg => msg.uuid === action.payload);
            if (message) {
                message.isNew = false;
            }
        },
        rateMessage(state, action) {
            const {uuid, rating} = action.payload;
            const message = state.messages.find(msg => msg.uuid === uuid);
            if (message) {
                message.rating = rating;
            }
        },
        sendMessage(state, action) {
            state.messages.push(action.payload);
            state.waitingMessage = true;
        },
        messageReceived(state, action) {
            state.messages.push({...action.payload, isNew: true});
            state.waitingMessage = false;
        },
        fetchChatBotSession(state) {
            state.loading = true;
        },
        setChatBotSession(state, action) {
            state.messages = action.payload;
            state.loading = false;
        },
        onError(state) {
            state.loading = false;
            state.waitingMessage = false
        },
    },

})

export const {
    sendMessage,
    messageReceived,
    fetchChatBotSession,
    setChatBotSession,
    rateMessage,
    setMessageAsNotNew,
    onError
} = slice.actions;

export const chatBotReducer = slice.reducer;