import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import React, {useEffect, useMemo} from "react";
import Tabs from "../../components/tab/Tabs";
import {fetchClient} from "../../store/client/clientReducer";
import {getLoading} from "../../store/online-evaluation/evaluationOnlineSelector";
import {getAllOnline, getScheduled} from "../../store/online-evaluation/evaluationOnlineReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import OnlineEvaluation from "../../components/online-evaluation/OnlineEvaluation";
import OnlineEvaluationScheduled from "../../components/online-evaluation/OnlineEvaluationScheduled";
import {
    buildClientMorphologicalRoute,
    buildOnlineEvaluationsRoute
} from "../../utils/client/evaluationRoutes";

const OnlineEvaluations = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id, pg} = useParams();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const page = useMemo(() => pg ?? "1", [pg]);
    const {t} = useTranslation();
    useComponentTranslations('evaluationOnline', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBackPage = () => {
        navigate(buildClientMorphologicalRoute(id));
    };

    const changePages = (pageName) => {
        navigate(buildOnlineEvaluationsRoute(id, pageName));
    };

    useEffect(() => {
        dispatch(fetchClient(id));
        dispatch(getAllOnline({clientId: id, status: 0}));
    }, [dispatch, id]);

    useEffect(() => {
        if (page === "2") {
            dispatch(getScheduled(id));
        }
    }, [dispatch, id, page]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <Tabs
                    page={page}
                    buttonClick={changePages}
                    button1Text={t("evaluationOnline:evaluations")}
                    button2Text={t("evaluationOnline:scheduled")}
                    mt="mt-n4"
                />
                {
                    page === "1" ?
                        <OnlineEvaluation id={id}/> :
                        <OnlineEvaluationScheduled id={id}/>
                }
            </Page>
        </>
    );
};

export default OnlineEvaluations;
