import WalletCardNotRegistered from "./WalletCardNotRegistered";
import WalletPendingCard from "./WalletPendingCard";
import WalletRejectedCard from "./WalletRejectedCard";
import WalletActiveCard from "./WalletActiveCard";
import WalletErrorCard from "./WalletErrorCard";
import {handleGoToWallet} from "../../utils/handlers/handler";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WalletStatus = ({walletRequest, loading}) => {
    const {t} = useTranslation();
    useComponentTranslations('wallet', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    return (
        <div className={'row pt-2 '}>
            <div className={'col-12'}>
                {
                    (!walletRequest || walletRequest.status === 0) && !loading &&
                    <WalletCardNotRegistered handleGoToWallet={handleGoToWallet}/>
                }
                {
                    walletRequest && (walletRequest.status === 1 || walletRequest.status === 2) &&
                    <WalletPendingCard title={t("wallet:infoBeingChecked")}
                                       message1={t("wallet:infoBeingCheckedMessage")}/>
                }
                {
                    walletRequest && walletRequest.status === 3 &&
                    <WalletPendingCard title={t("wallet:infoBeingChecked")}
                                       message1={t("wallet:infoBeingCheckedMessage")}
                                       message2={<>{t("wallet:infoBeingCheckedMessage2")} <span className={"fw-bold"}>{t("wallet:10Days")}</span></>}
                    />
                }
                {
                    (walletRequest && (walletRequest.status === 4)) &&
                    <WalletRejectedCard walletRequest={walletRequest}/>
                }
                {
                    walletRequest && walletRequest.status === 5 &&
                    <WalletActiveCard handleGoToWallet={handleGoToWallet} />
                }
                {
                    walletRequest && walletRequest.status === 7 &&
                    <WalletPendingCard title={t("wallet:missingInformation")}
                                       message1={t("wallet:missingInformationMessage")}
                                       handleGoToWallet={handleGoToWallet}
                    />
                }
                {
                    (walletRequest && (walletRequest.status === 8)) &&
                    <WalletErrorCard/>
                }
            </div>
        </div>
    )
}
export default WalletStatus