import React, {useEffect} from "react";
import {Formik, Form, Field, ErrorMessage} from "formik";
import * as Yup from "yup";
import {useDispatch, useSelector} from "react-redux";
import {isWorkoutAerobicLoading, selectNameUpdated} from "../../store/workout-aerobic/workoutAerobicSelector";
import {updateName, updateNameSuccess} from "../../store/workout-aerobic/workoutAerobicReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from "he"

const WorkoutAerobicNameForm = ({onClose, workout}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const loading = useSelector(isWorkoutAerobicLoading)
    const isAerobicUpdated = useSelector(selectNameUpdated);
    useComponentTranslations('trainingLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object({
        name: Yup.string()
            .required(t("trainingLibraryComponent:required"))
            .min(2, t("trainingLibraryComponent:2chars"))
            .max(45, t("trainingLibraryComponent:nameTooBig")),
    });

    const initialValues = {
        name: he.decode(workout.nome),
    };

    const handleSubmit = (values) => {
        const payload = {
            id: workout.id,
            ...values
        }
        dispatch(updateName(payload))
    }

    useEffect(() => {
        if (isAerobicUpdated) {
            dispatch(updateNameSuccess(false));
            onClose()
        }
    }, [isAerobicUpdated, dispatch, onClose]);

    return (
        <Formik
            initialValues={initialValues}
            validationSchema={validationSchema}
            onSubmit={handleSubmit}
        >
            <Form className="needs-validation">
                <div className="mb-3">
                    <label htmlFor="name" className="form-label fw-semibold">
                        {t("trainingLibraryComponent:name")}
                    </label>
                    <Field
                        type="text"
                        name="name"
                        id="name"
                        className="form-control"
                        maxLength={45}
                    />
                    <ErrorMessage
                        name="name"
                        component="div"
                        className="invalid-feedback d-block"
                    />
                </div>
                <div className={'d-grid'}>
                    <button
                        type="submit"
                        className="btn btn-primary"
                        disabled={loading}
                    >
                        {t("trainingLibraryComponent:save")}
                    </button>
                </div>
            </Form>
        </Formik>
    );
};

export default WorkoutAerobicNameForm;
