import { all, call, put, takeLatest } from "redux-saga/effects";
import {
    enableDisableOnlineEvaluationAPI,
    getAllOnlineEvaluationAPI,
    saveOnlineEvaluationAPI,
    sendOnlineEvaluationAPI,
    getScheduledAPI,
    updateFrequencyOnlineAPI,
    getOneOnlineEvaluationAPI,
    recoverDeletedEvaluationAPI,
    getLastEvaluationAPI,
    compareOnlineEvaluationAPI
} from "../../api/evaluation-online/evaluationOnlineActions";
import { handleError } from "../../utils/error/sagaErrorHandling";
import {
    getAllOnline,
    setAllOnline,
    sendOnline,
    saveOnline,
    getScheduled,
    setScheduled,
    enableDisableStatus,
    setEnableDisableStatus,
    updateFrequencyOnline,
    onError,
    setEvaluationOnline,
    fetchEvaluationOnline,
    setRecoveredEvaluation,
    recoverEvaluation,
    setLastEvaluation,
    fetchLastEvaluation, setCompareEvaluation, compareEvaluation, setSubmitResult,
} from "./evaluationOnlineReducer";

export function* fetchOnlineEvaluationAsync(action) {
    try {
        const { clientId, status } = action.payload;
        const response = yield call(getAllOnlineEvaluationAPI, clientId, status);
        yield put(setAllOnline(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchOnlineEvaluation() {
    yield takeLatest(getAllOnline.type, fetchOnlineEvaluationAsync);
}

export function* sendOnlineEvaluationAsync(action) {
    try {
        const { ids, frequency, type } = action.payload;
        const response = yield call(sendOnlineEvaluationAPI, ids, frequency, type);
        yield put(setSubmitResult({
            action: "send",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? null
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onSendOnlineEvaluation() {
    yield takeLatest(sendOnline.type, sendOnlineEvaluationAsync);
}

export function* fetchOneEvaluationOnlineAsync(action) {
    try {
        const response = yield call(getOneOnlineEvaluationAPI, action.payload);
        yield put(setEvaluationOnline(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchOneEvaluationOnline() {
    yield takeLatest(fetchEvaluationOnline.type, fetchOneEvaluationOnlineAsync)
}

export function* fetchLastEvaluationAsync(action) {
    try {
        const clientId = action.payload?.clientId ?? action.payload;
        const response = yield call(getLastEvaluationAPI, clientId);
        yield put(setLastEvaluation({evaluation: response.data, clientId}));
    } catch (error){
        yield call(handleError, error, onError);
    }
}
export function* onFetchLastEvaluation(){
    yield takeLatest(fetchLastEvaluation.type, fetchLastEvaluationAsync)
}

export function* saveOnlineEvaluationAsync(action) {
    try {
        const response = yield call(saveOnlineEvaluationAPI, action.payload);
        yield put(setEvaluationOnline(response.data));
        yield put(setSubmitResult({
            action: action.payload?.id ? "update" : "create",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? action.payload?.idClient ?? null,
            entityId: response.data?.id ?? action.payload?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onSaveOnlineEvaluation() {
    yield takeLatest(saveOnline.type, saveOnlineEvaluationAsync);
}

export function* recoverEvaluationAsync(action) {
    try{
        const {id, status} = action.payload;
        const response = yield call(recoverDeletedEvaluationAPI, id, status);
        yield put(setRecoveredEvaluation(id));
        yield put(setSubmitResult({
            action: status === 1 ? "delete" : "recover",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onRecoverEvaluation() {
    yield takeLatest(recoverEvaluation.type, recoverEvaluationAsync);
}

export function* fetchScheduledEvaluationAsync(action) {
    try {
        const response = yield call(getScheduledAPI, action.payload);
        yield put(setScheduled(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchScheduledEvaluation() {
    yield takeLatest(getScheduled.type, fetchScheduledEvaluationAsync);
}

export function* enableDisableOnlineEvaluationAsync(action) {
    try {
        const { clientId, status } = action.payload;
        const response = yield call(enableDisableOnlineEvaluationAPI, clientId, status);
        yield put(setScheduled(response.data));
        yield put(setEnableDisableStatus({ clientId, status }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onEnableDisableOnlineEvaluation() {
    yield takeLatest(enableDisableStatus.type, enableDisableOnlineEvaluationAsync);
}

export function* updateOnlineEvaluationFrequencyAsync(action) {
    try {
        const { clientId, frequency } = action.payload;
        yield call(updateFrequencyOnlineAPI, clientId, frequency);
        yield put(getScheduled(clientId));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onUpdateOnlineEvaluationFrequency() {
    yield takeLatest(updateFrequencyOnline.type, updateOnlineEvaluationFrequencyAsync);
}

export function* compareEvaluationAsync(action) {
    try {
        const {clientId, ids} = action.payload;
        const response = yield call(compareOnlineEvaluationAPI, clientId, ids);
        yield put(setCompareEvaluation(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onCompareEvaluation() {
    yield takeLatest(compareEvaluation.type, compareEvaluationAsync);
}

export function* evaluationOnlineSaga() {
    yield all([
        call(onFetchOnlineEvaluation),
        call(onSaveOnlineEvaluation),
        call(onSendOnlineEvaluation),
        call(onFetchScheduledEvaluation),
        call(onEnableDisableOnlineEvaluation),
        call(onUpdateOnlineEvaluationFrequency),
        call(onFetchOneEvaluationOnline),
        call(onRecoverEvaluation),
        call(onFetchLastEvaluation),
        call(onCompareEvaluation)
    ]);
}
