import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';
import { selectUserExercises } from '../../store/exercise-library/exerciseLibrarySelector';
import { useTranslation } from 'react-i18next';
import useComponentTranslations from '../../utils/translation/useComponentTranslations';
import enUS from './locales/en-us.json';
import ptBR from './locales/pt-br.json';
import esES from './locales/es-es.json';
import ptPT from './locales/pt-pt.json';
import { getExerciseName } from '../../utils/workout/Exercise';
import SimpleExerciseSearchCard from './SimpleExerciseSearchCard';

const SimpleExerciseSearchResults = ({ query, onSelect, hits = [] }) => {
    const rawUserExercises = useSelector(selectUserExercises);
    const { t, i18n } = useTranslation();

    useComponentTranslations(
        'workoutPrescriptionComponent',
        { 'en-US': enUS, 'pt-BR': ptBR, 'es-ES': esES, 'pt-PT': ptPT }
    );

    const userHits = useMemo(() => {
        const list = Array.isArray(rawUserExercises) ? rawUserExercises : [];
        return list
            .filter((e) =>
                (e.nome || e.name || '')
                    .toLowerCase()
                    .includes(query.toLowerCase())
            )
            .map((e) => ({
                objectID: e.id,
                nome: e.nome || e.name,
                isUser: true,
            }));
    }, [rawUserExercises, query]);

    const backendHits = useMemo(() => {
        return hits.map((h) => ({
            ...h,
            isUser: false,
        }));
    }, [hits]);

    const combined = useMemo(() => {
        return [...userHits, ...backendHits].map((item) => ({
            ...item,
            displayName: item.isUser
                ? item.nome
                : getExerciseName(item, i18n.language),
        }));
    }, [userHits, backendHits, i18n.language]);

    return (
        <>
            {combined.length > 0 ? (
                combined.map((hit) => (
                    <SimpleExerciseSearchCard
                        key={hit.objectID}
                        hit={hit}
                        onSelect={onSelect}
                    />
                ))
            ) : (
                <li className="list-group-item text-muted">
                    {t('workoutPrescriptionComponent:noResults')}
                </li>
            )}
        </>
    );
};

export default SimpleExerciseSearchResults;
