import React, {useEffect, useMemo, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useLocation, useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import Page from "../../components/page/Page";
import WorkoutPresetForm from "../../components/workout-preset/WorkoutPresetForm";
import DeleteModal from "../../components/modal/DeleteModal";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {
    clearWorkoutPresetEvents,
    deleteWorkoutPreset,
    fetchWorkoutPresets,
    updateWorkoutPreset
} from "../../store/workout-preset/workoutPresetReducer";
import {
    selectLastDeletedWorkoutPresetId,
    selectLastUpdatedWorkoutPreset,
    selectWorkoutPresetLoading,
    selectWorkoutPresets
} from "../../store/workout-preset/workoutPresetSelector";

const WorkoutPresetEdit = () => {
    const {t} = useTranslation();
    const {presetId} = useParams();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const location = useLocation();
    const presets = useSelector(selectWorkoutPresets);
    const loading = useSelector(selectWorkoutPresetLoading);
    const updatedPreset = useSelector(selectLastUpdatedWorkoutPreset);
    const deletedPresetId = useSelector(selectLastDeletedWorkoutPresetId);
    const backTo = location.state?.backTo || "/user";
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [hasRequestedPreset, setHasRequestedPreset] = useState(false);

    useComponentTranslations("workoutPresetPage", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        setHasRequestedPreset(true);
        dispatch(fetchWorkoutPresets());
    }, [dispatch]);

    useEffect(() => {
        if (updatedPreset?.id) {
            dispatch(clearWorkoutPresetEvents());
            navigate("/user/workout-presets", {
                state: {
                    backTo
                }
            });
        }
    }, [backTo, updatedPreset, dispatch, navigate]);

    useEffect(() => {
        if (deletedPresetId === Number(presetId)) {
            setShowDeleteModal(false);
            dispatch(clearWorkoutPresetEvents());
            navigate("/user/workout-presets", {
                state: {
                    backTo
                }
            });
        }
    }, [backTo, deletedPresetId, dispatch, navigate, presetId]);

    const preset = useMemo(
        () => presets.find((item) => item.id === Number(presetId)),
        [presets, presetId]
    );
    const wasDeleted = deletedPresetId === Number(presetId);
    const isResolvingPreset = !hasRequestedPreset || loading;

    if (wasDeleted) {
        return <Page title={t("workoutPresetPage:title")} loading={true}/>;
    }

    if (!preset) {
        return (
            <Page title={t("workoutPresetPage:title")} goBackLink={() => navigate("/user/workout-presets", {
                state: {
                    backTo
                }
            })} loading={isResolvingPreset}>
                {!isResolvingPreset && (
                    <div className="card card-body border-0">
                        <span className="text-secondary">{t("workoutPresetPage:presetNotFound")}</span>
                    </div>
                )}
            </Page>
        );
    }

    if (Number(preset.userId) === 0) {
        return (
            <Page title={t("workoutPresetPage:title")} goBackLink={() => navigate("/user/workout-presets", {
                state: {
                    backTo
                }
            })}>
                <div className="card card-body border-0">
                    <span className="text-secondary">{t("workoutPresetPage:systemPresetReadonly")}</span>
                </div>
            </Page>
        );
    }

    return (
        <>
            <Page title={t("workoutPresetPage:title")} goBackLink={() => navigate("/user/workout-presets", {
                state: {
                    backTo
                }
            })}>
                <div className="card card-body border-0">
                    <WorkoutPresetForm
                        initialPreset={preset}
                        initialPresetKey={`edit-${preset.id}`}
                        loading={loading}
                        submitLabel={t("workoutPresetPage:update")}
                        deleteLabel={t("workoutPresetPage:deletePreset")}
                        onDeleteClick={() => setShowDeleteModal(true)}
                        onCancel={() => navigate("/user/workout-presets", {
                            state: {
                                backTo
                            }
                        })}
                        onSubmit={(payload) => dispatch(updateWorkoutPreset({...payload, id: preset.id}))}
                    />
                </div>
            </Page>
            <DeleteModal
                show={showDeleteModal}
                onClose={() => setShowDeleteModal(false)}
                onConfirm={() => dispatch(deleteWorkoutPreset(preset.id))}
                deleteTitle={t("workoutPresetPage:deletePresetModalTitle")}
                deleteSubtitle={t("workoutPresetPage:deletePresetModalDescription")}
                confirmLabel={t("workoutPresetPage:deletePreset")}
                closeLabel={t("workoutPresetComponent:cancel")}
                isSubmitting={loading}
                loadingLabel={t("workoutPresetPage:deletePreset")}
            />
        </>
    );
};

export default WorkoutPresetEdit;
