import Modal from "react-bootstrap/Modal";
import {useState} from "react";
import CardButtonAdd from "../card/CardButtonAdd";
import WorkoutFolderCreateForm from "./WorkoutFolderCreateForm";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {useNavigate} from "react-router-dom";

const WorkoutLibraryCreateModal = ({type, emptyList = false, show, onHide}) => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const [showCreateFolder, setShowCreateFolder] = useState(false);
    useComponentTranslations('trainingLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleShowCreateFolder = () => {
        setShowCreateFolder(prevState => !prevState)
    }

    const handleTrainingClick = () => {
        if (type === 0) {
            navigate("/user/client/0/workout/routine/create")
        } else {
            navigate(`/user/client/0/workout/aerobic/create`)
        }
    }

    return (
        <>
            {
                emptyList ?
                    <button className={'btn btn-primary'} onClick={onHide}>{t("trainingLibraryComponent:startNow")}</button> :
                    <CardButtonAdd handleClick={onHide} text={t("trainingLibraryComponent:add")}/>
            }
            <Modal centered show={show} onHide={onHide}>
                <Modal.Body>
                    {
                        showCreateFolder &&
                        <WorkoutFolderCreateForm type={type} setShowCreateFolder={setShowCreateFolder} closeModal={onHide}/>
                    }
                    {
                        !showCreateFolder && (
                            <>
                                <div className={'row justify-content-between'}>
                                    <div className={'col-auto'}>
                                        <span className={"fw-semibold"}>
                                            {t("trainingLibraryComponent:whatDoYouWantToDo")}
                                        </span>
                                    </div>
                                    <div className={'col-auto clickable-element'} onClick={onHide}>
                                        <i className={'fa-regular fa-times'}></i>
                                    </div>
                                </div>
                                <div className={"row mt-3"}>
                                    <div className={'col-12'}>
                                        <div className={'d-grid'}>
                                            <button
                                                className={'btn btn-outline-primary clickable-element'}
                                                onClick={handleTrainingClick}
                                            >
                                                {t("trainingLibraryComponent:addNewWorkout")}
                                            </button>
                                        </div>
                                        <div className={'d-grid mt-2'}>
                                            <button
                                                className={'btn btn-outline-primary clickable-element'}
                                                onClick={handleShowCreateFolder}
                                            >
                                                {t("trainingLibraryComponent:addNewFolder")}
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </>
                        )
                    }
                </Modal.Body>
            </Modal>
        </>
    )
}
export default WorkoutLibraryCreateModal;