import axios from "axios";
import {apiUrl, getToken} from "../api";

export const getWorkoutSessionByIdAPI = async (sessionId) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/session/?id=${sessionId}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    });
}

export const getWorkoutSessionByIdNoAuthAPI = async (sessionId) => {
    return await axios.get(`${apiUrl}/user/session/?id=${sessionId}`, {
        headers: {
            'Content-Type': 'application/json',
        },
        timeout: 20000
    });
}

export const updateSeriesAPI = async (formData, seriesId) => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/user/session/series?id=${seriesId}`, formData, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    });
}