import React, {useState, useRef, useEffect, useCallback, useMemo} from "react";
import Image from "react-bootstrap/Image";
import Modal from "react-bootstrap/Modal";
import Overlay from "react-bootstrap/Overlay";
import Popover from "react-bootstrap/Popover";
import {useDispatch} from "react-redux";
import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import {deleteCreditCard, setInstallments} from "../../store/subscription/subscriptionReducer";
import {normalizeInstallmentMap} from "../../utils/installments/zoopInstallments";
import creditCardType from "credit-card-type";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const SubscriptionCreditCardCard = ({
                                        cc,
                                        handlePaymentMethod,
                                        subPlan,
                                        autoOpen,
                                        installmentOptions
                                    }) => {
    const [showModal, setShowModal] = useState(false);
    const [selectedInstallment, setSelectedInstallment] = useState("");
    const [showPopover, setShowPopover] = useState(false);
    const selectBtnRef = useRef(null);
    const dispatch = useDispatch();
    const {t} = useTranslation();

    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const normalizedInstallments = useMemo(
        () => normalizeInstallmentMap(installmentOptions ?? subPlan?.installments),
        [installmentOptions, subPlan]
    );

    const availableInstallments = useMemo(() => {
        if (!normalizedInstallments) {
            return [];
        }

        return Object.keys(normalizedInstallments)
            .map(Number)
            .filter((key) => Number.isFinite(key) && key >= 1)
            .filter((key) => {
                if (!subPlan?.month) {
                    return true;
                }
                return key <= Number(subPlan.month);
            })
            .sort((a, b) => a - b)
            .map((key) => ({
                key,
                total: normalizedInstallments[key]
            }));
    }, [normalizedInstallments, subPlan]);

    const returnImgUrl = () => {
        const hasImg = creditCardType(cc.card.first4_digits)[0]?.type;
        if (hasImg) {
            return `https://cdn.mfitpersonal.com.br/assets/credit_card_brand/${hasImg}.svg`
        }
    }

    const handleDeleteCard = () => {
        dispatch(deleteCreditCard(cc.id))
    }

    const handleShowModal = useCallback(() => {
        setSelectedInstallment(subPlan.month > 1 ? "" : "1");
        setShowPopover(false);
        setShowModal((prev) => !prev);
    }, [subPlan]);

    useEffect(() => {
        if (autoOpen) {
            handleShowModal();
        }
    }, [autoOpen, handleShowModal]);

    useEffect(() => {
        if (showPopover) {
            const timer = setTimeout(() => setShowPopover(false), 2000);
            return () => clearTimeout(timer);
        }
    }, [showPopover]);

    const handleConfirm = (e) => {
        if (!selectedInstallment) {
            e.preventDefault();
            setShowPopover(true);
            return;
        }
        const installmentCount = Number(selectedInstallment);
        dispatch(setInstallments(installmentCount));
        const payload = {
            installments: installmentCount,
            ...cc
        }
        handlePaymentMethod(payload);
        setShowModal(false);
    };

    const CreditCardCard = ({small}) => (
        <div className="row justify-content-between">
            <div className="col-2 align-self-center p-0 m-0">
                <Image src={returnImgUrl()} fluid/>
            </div>
            <div className="col-7">
                <span className="fw-semibold d-block">
                  {cc.card.card_brand} **** {cc.card.last4_digits}
                </span>
                <span className="d-block small">
                  {cc.card.expiration_month}/ {`${cc.card.expiration_year}`.replace("20", "")}
                </span>
            </div>
            {
                cc.defaultCard && !small ?
                    <div className={"col-3 align-self-center"}>
                    <span className="small badge rounded-5 bg-primary-subtle text-primary border border-primary fw-semibold">
                        {t('subscriptionComponent:subscriptionCreditCardCard.defaultBadge')}
                    </span>
                    </div> :
                    <div className={"col-3 align-self-center"}></div>
            }
        </div>
    );

    return (
        <>
            <div
                className="card card-body   clickable-element"
                onClick={handleShowModal}
            >
                <CreditCardCard/>
            </div>
            <Modal centered show={showModal} onHide={handleShowModal}>
                <Modal.Body>
                    <div className="row">
                        <div className="col-12 pb-3">
                            <div className={"row justify-content-between"}>
                                <div className={"col-auto"}><span
                                    className="fw-semibold  fs-5">{t('subscriptionComponent:subscriptionCreditCardCard.selectTitle')}</span></div>
                                <div className={"col-auto clickable-element align-self-center"} onClick={handleShowModal}><i
                                    className={"fa-regular fa-times  "}></i></div>
                            </div>
                        </div>
                        <div className="col-12">
                            <div className="card card-body">
                                <CreditCardCard small/>
                            </div>
                        </div>
                        <div
                            className="col-12 mt-4 overflow-auto"
                            style={{maxHeight: "300px"}}
                        >
                            {availableInstallments.map(({key, total}) => (
                                <div className="row mb-2" key={key}>
                                    <div className="col-12">
                                        <div className="card card-body border-0">
                                            <div className="row justify-content-between align-items-center">
                                                <div className="col-6">
                                                    <div className="form-check">
                                                        <input
                                                            type="radio"
                                                            name="installment"
                                                            value={String(key)}
                                                            id={`installment-${key}`}
                                                            className="form-check-input border-primary-subtle"
                                                            checked={
                                                                selectedInstallment === String(key)
                                                            }
                                                            onChange={() =>
                                                                setSelectedInstallment(String(key))
                                                            }
                                                        />
                                                        <label
                                                            htmlFor={`installment-${key}`}
                                                            className="form-check-label fw-semibold ps-2"
                                                        >
                                                            {key}x{" "}
                                                            <CurrencyFormatter
                                                                value={total / key}
                                                            />
                                                        </label>
                                                    </div>
                                                </div>
                                                {key > 1 &&
                                                    <label className="col-6 text-end">
                                                        {
                                                            subPlan.interestFree ?
                                                                <span className="text-success-lighter">
                                                                      {t('subscriptionComponent:subscriptionCreditCardCard.interestFree')}
                                                                    </span>
                                                                :
                                                                <span className="d-block text-secondary">
                                                                        <CurrencyFormatter value={total}/>
                                                                    </span>
                                                        }
                                                    </label>
                                                }
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </Modal.Body>
                <Modal.Footer className="d-flex justify-content-between">
                    <button
                        ref={selectBtnRef}
                        type="button"
                        className="btn btn-primary w-100 me-1"
                        onClick={handleConfirm}
                    >
                        {t('subscriptionComponent:subscriptionCreditCardCard.select')}
                    </button>
                    {
                        !cc.defaultCard &&
                        <button
                            type="button"
                            className="btn btn-outline-danger w-100 ms-1"
                            onClick={handleDeleteCard}
                        >
                            {t('subscriptionComponent:subscriptionCreditCardCard.delete')}
                        </button>
                    }
                    <Overlay
                        target={selectBtnRef.current}
                        show={showPopover}
                        placement="top"
                    >
                        <Popover id="installment-error-popover">
                            <Popover.Body>{t('subscriptionComponent:subscriptionCreditCardCard.installmentError')}</Popover.Body>
                        </Popover>
                    </Overlay>
                </Modal.Footer>
            </Modal>
        </>
    );
};

export default SubscriptionCreditCardCard;
