import {useParams} from "react-router-dom";
import React, {useEffect, useState} from "react";
import _ from "lodash";
import WorkoutPdfExercise from "../../components/workout/WorkoutPdfExercise";
import {Image, Navbar} from "react-bootstrap";
import {getWorkoutSessionByIdNoAuthAPI} from "../../api/workout-session/workoutSessionActions";
import {getWorkoutRoutineNoAuthAPI} from "../../api/workout-routine/workoutRoutineActions";
import {fetchClientNoAuthAPI} from "../../api/client/clientActions";
import Avatar from "../../components/avatar/Avatar";
import {getDifficulty, getObjective} from "../../utils/workout/Workout";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import Text from "../../components/utils/emoji/Text";

const WorkoutPdf = () => {
    const {t, i18n} = useTranslation();
    const {sessionId, type} = useParams();
    const [session, setSession] = useState(null);
    const [workout, setWorkout] = useState(null);
    const [client, setClient] = useState(null);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        const loadSession = async () => {
            try {
                const response = await getWorkoutSessionByIdNoAuthAPI(sessionId)
                setSession(response.data);
            } catch (err) {
                console.error("Failed to fetch session:", err);
            }
        };
        loadSession().then();
        const loadWorkout = async () => {
            try {
                const response = await getWorkoutRoutineNoAuthAPI(sessionId)
                setWorkout(response.data);
            } catch (err) {
                console.error("Failed to fetch session:", err);
            }
        };
        loadWorkout().then();
    }, [sessionId]);

    useEffect(() => {
        if (session?.client_id) {
            const loadClient = async () => {
                try {
                    const response = await fetchClientNoAuthAPI(session.client_id)
                    setClient(response.data);
                } catch (err) {
                    console.error("Failed to fetch session:", err);
                }
            };
            loadClient().then();
        }
    }, [session]);

    useEffect(() => {
        if (client) {
            i18n.changeLanguage(client.language).then();
        }
    }, [client, i18n]);

    return (
        <>
            {
                session && workout &&
                <>
                    <Navbar bg="default" className="justify-content-center navbar text-white " style={{paddingTop: "1.9rem"}}>
                        <div className={'row justify-content-center'}>
                            <div className={'col-12'}>
                                <Image fluid={true} style={{height: "33px"}}
                                       src={`https://cdn.mfitpersonal.com.br/assets/logo/logo-horizontal.svg`}/>
                            </div>
                        </div>
                    </Navbar>
                    <div className={"container-fluid"} id={"session-ready"}>
                        <div className={"row bg-default text-white "}>
                            <div style={{height: "20px"}}></div>
                            <div className={"col-12"}>
                                <div className={"row  "}>
                                    <div className={"col-3  ps-4 align-self-center"}>
                                        <div className={"d-inline-block border border-3 border-primary-400 rounded-circle p-0"}>
                                            <Avatar url={client?.avatar} maxWidth={"60px"}/>
                                        </div>
                                    </div>
                                    <div className={"col-9  align-self-center"}>
                                        <div className={"row"}>
                                            <div className={"col-12"}>
                                                <span className={" fw-semibold fs-5"}>{client?.name} {client?.lastName}</span>
                                            </div>
                                            <div className={"col-12"}>
                                                <span>Rotina: <Text>{workout.nome}</Text></span>
                                            </div>
                                            <div className={"col-12 small"}>
                                                <span><i className={"fa-regular fa-clipboard-list"}></i> {t(`workout:${getObjective(workout.objetivo)}`)}</span>
                                            </div>
                                            <div className={"col-12 small"}>
                                                <span><i
                                                    className={"fa-regular fa-clipboard-user"}></i> {t(`workout:${getDifficulty(workout.dificuldade)}`)}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div style={{height: "20px"}}></div>
                        </div>
                        <div style={{height: "20px"}}></div>
                        <div className={"row small  align-items-start "}>
                            <div className={"col-12"}>
                                <div className={" bg-white pt-1   rounded-1"}>
                                    <div className={"row align-items-start m-2 "}>
                                        <div className={"col-12"}>
                                        <span className={"fw-semibold fs-5"}>
                                           {session?.nome}
                                        </span>
                                        </div>
                                        <div className={"col-12  "}>
                                            {
                                                _.map(session?.exercs, (exerc, index) => (
                                                    <div key={exerc.id} className={'row justify-content-center  align-items-start'}>
                                                        <div className="col-12 pt-2  ">
                                                            <WorkoutPdfExercise showImages={type === "full"} index={index} exerc={exerc}/>
                                                        </div>
                                                    </div>
                                                ))
                                            }
                                        </div>
                                    </div>
                                    <div style={{height: "20px"}}></div>
                                </div>
                            </div>
                        </div>
                    </div>
                </>
            }
        </>
    )
}

export default WorkoutPdf;