import RoundedIcon from "../rounded-icon/RoundedIcon";
import Modal from "react-bootstrap/Modal";
import React, {useCallback, useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {
    selectFoldersList,
    selectFoldersListLoading, selectLoadingDeleteRoutine, selectLoadingDuplicateRoutine, selectRoutineDeleted,
    selectRoutineDuplicated
} from "../../store/workout-library/workoutLibrarySelector";
import LoadingBlock from "../loader/LoadingBlock";
import _ from "lodash";
import CardButtonAdd from "../card/CardButtonAdd";
import Text from "../utils/emoji/Text";
import WorkoutFolderCreateForm from "./WorkoutFolderCreateForm";
import {
    deleteRoutine,
    duplicateRoutine,
    fetchCurrentFolder,
    fetchFoldersList,
    routineDuplicated, setRoutineDeleted,
    updateRoutineFolder
} from "../../store/workout-library/workoutLibraryReducer";
import WorkoutIcon from "../rounded-icon/WorkoutIcon";
import {getObjective} from "../../utils/workout/Workout";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import WorkoutRoutineClone from "../workout-clone/WorkoutRoutineClone";
import WorkoutAerobicClone from "../workout-clone/WorkoutAerobicClone";
import WorkoutAerobicNameForm from "./WorkoutAerobicNameForm";
import {useNavigate} from "react-router-dom";
import {Dropdown} from "react-bootstrap";
import DropdownMenuPortal from "../utils/dropdown/DropdownMenuPortal";

const WorkoutLibraryWorkoutItem = ({workout, type, closeBackgroundModal}) => {
    const {t} = useTranslation();
    const navigate = useNavigate()
    const [modalOpen, setModalOpen] = useState(false)
    const dispatch = useDispatch();
    const folderList = useSelector(selectFoldersList);
    const folderListLoading = useSelector(selectFoldersListLoading);
    const [showCreateFolder, setShowCreateFolder] = useState(false);
    const sortedFolders = folderList?.slice().sort((a, b) => a.name.localeCompare(b.name));
    const [actionToShow, setActionToShow] = useState(null);
    const isRoutineDuplicated = useSelector(selectRoutineDuplicated)
    const isRoutineDuplicating = useSelector(selectLoadingDuplicateRoutine)
    const isRoutineDeleted = useSelector(selectRoutineDeleted)
    const isRoutineDeleteLoading = useSelector(selectLoadingDeleteRoutine);
    useComponentTranslations('trainingLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const openActionModal = useCallback((action) => {
        setActionToShow(action);
        setModalOpen(true);
        if (closeBackgroundModal)
            closeBackgroundModal(true);
    }, [closeBackgroundModal])

    const closeModal = useCallback(() => {
        setModalOpen(false)
        setActionToShow(null)
        if (closeBackgroundModal)
            closeBackgroundModal(false);
    }, [closeBackgroundModal])

    const handleChangeFolder = (folderId) => {
        dispatch(updateRoutineFolder({folderId, routineId: workout.id, type}))
        closeModal();
    }

    const handleDeleteRoutine = () => {
        dispatch(deleteRoutine({id: workout.id, type}))
    }

    const handleDuplicateRoutine = () => {
        dispatch(duplicateRoutine({id: workout.id, type}))
    }


    const handleGoToWorkout = () => {
        if (Number(type === 1)) {
            navigate(`/user/client/0/workout/aerobic/view/${workout.id}`)
        }
        if (Number(type === 0)) {
            navigate(`/user/client/0/workout/routine/${workout.id}`)
        }
    }

    useEffect(() => {
        if (actionToShow === 'changeFolder')
            dispatch(fetchFoldersList(type))
    }, [actionToShow, dispatch, type]);

    useEffect(() => {
        if (isRoutineDuplicated) {
            const timer = setTimeout(() => {
                dispatch(routineDuplicated(false));
                dispatch(fetchCurrentFolder({id: workout.path, type}));
                closeModal();
            }, 2500);

            return () => clearTimeout(timer);
        }
    }, [isRoutineDuplicated, dispatch, workout, type, closeModal]);

    useEffect(() => {
        if (isRoutineDeleted) {
            dispatch(setRoutineDeleted(false));
            closeModal();
        }
    }, [isRoutineDeleted, dispatch, closeModal]);

    const renderContent = () => {
        switch (actionToShow) {
            case 'changeFolder':
                return <div>
                    {showCreateFolder && (
                        <div className={"mb-2"}>
                            <WorkoutFolderCreateForm type={type} setShowCreateFolder={setShowCreateFolder}/>
                        </div>
                    )}
                    {!showCreateFolder && (
                        <>
                            <div className={'row justify-content-between mb-2'}>
                                <div className={'col-auto'}>
                                    <span className={"fw-semibold fs-5"}>{t("trainingLibraryComponent:chooseFolder")}</span>
                                </div>
                                <div className={'col-auto clickable-element'} onClick={() => setActionToShow(null)}>
                                    <span className={"fw-semibold fs-5"}><i className={"fa-regular fa-times"}></i></span>
                                </div>
                            </div>
                            <div className={"row mb-4"}>
                                <div className={"col-12"}>
                                    <CardButtonAdd text={t("trainingLibraryComponent:createFolder")} handleClick={() => setShowCreateFolder(true)}/>
                                </div>
                            </div>
                            {folderListLoading && <LoadingBlock/>}
                            {!folderListLoading && folderList && _.map(sortedFolders, ((folder, index) =>
                                    <React.Fragment key={index}>
                                        <div className={'row clickable-element'} onClick={() => handleChangeFolder(folder.id)}>
                                            <div className={'col-auto col-md-auto'}>
                                                <RoundedIcon icon={"fa-folder"} size={"sm"}/>
                                            </div>
                                            <div className={'col-auto col-auto align-self-center ps-0'}>
                                        <span className={"text-default fw-semibold"}>
                                           <Text>{folder.name}</Text>
                                        </span>
                                            </div>
                                        </div>
                                        <hr className={"text-secondary my-2"}/>
                                    </React.Fragment>
                            ))}
                        </>
                    )}
                </div>
            case 'showDuplicate':
                return <div className={'row'}>
                    <div className={'col-12 mb-3'}>
                        <span className={"fw-semibold fs-5"}>{t("trainingLibraryComponent:duplicateWorkoutTitle")}</span>
                    </div>

                    {(isRoutineDuplicating || isRoutineDuplicated) ?
                        <LoadingBlock height={"200px"}/>
                        :
                        <>
                            <div className={"col-12 mb-3"}>
                            <span>
                                {t("trainingLibraryComponent:duplicateWorkoutDescription")}
                            </span>
                            </div>
                            <div className={'col-12'}>
                                <div className={"d-grid"}>
                                    <button className={'btn btn-primary'} onClick={handleDuplicateRoutine}>
                                        {t("trainingLibraryComponent:duplicate")}
                                    </button>
                                </div>
                                <div className={"d-grid mt-2"}>
                                    <button className={'btn btn-outline-primary'} onClick={() => setActionToShow(null)}>
                                        {t("trainingLibraryComponent:cancel")}
                                    </button>
                                </div>
                            </div>
                        </>
                    }
                </div>
            case "showDelete":
                return <div className={"row"}>
                    <div className={'col-12 text-center mb-3 mt-2'}>
                        <i className={"fa-regular fa-exclamation-circle text-danger"} style={{fontSize: "3rem"}}></i>
                    </div>
                    <div className={'col-12 text-center mb-4'}>
                        <span className={"fw-semibold fs-5 d-block"}>
                            {t("trainingLibraryComponent:areYouSureToDelete")}
                        </span>
                        <span>
                            {t("trainingLibraryComponent:actionCannotBeUndone")}
                        </span>
                    </div>
                    <div className={'col-12'}>
                        <div className={'d-grid mb-2'}>
                            <button className={"btn btn-danger"} disabled={isRoutineDeleteLoading} onClick={handleDeleteRoutine}>
                                {t("trainingLibraryComponent:yesDelete")}
                            </button>
                        </div>
                        <div className={'d-grid mb-2'}>
                            <button className={"btn btn-outline-danger"} onClick={() => setActionToShow(null)}>
                                {t("trainingLibraryComponent:cancel")}
                            </button>
                        </div>
                    </div>
                </div>
            case "editName":
                return <div className={"row"}>
                    <div className={'col-12'}>
                        <WorkoutAerobicNameForm workout={workout} onClose={closeModal}/>
                    </div>
                </div>
            default:
                return null;
        }
    }

    const handleActionSelect = (event, action) => {
        event?.stopPropagation();
        openActionModal(action);
    }

    return (
        <>
            <div className="card card-body   mb-2">
                <div className="row align-items-center">
                    <div className="col-10 clickable-element" onClick={handleGoToWorkout} role="button">
                        <div className="row">
                            <div className={'col-3 col-md-2 text-center align-self-center'}>
                                <WorkoutIcon obj={workout.objetivo}/>
                            </div>
                            <div className={'col-9 col-md-10 align-self-center ps-0'}>
                            <span className={'fw-semibold d-block '}>
                                <Text className={"d-block text-break"}>{workout.nome}</Text>
                            </span>
                                {workout.objetivo && (
                                    <span>
                                    {t(`trainingLibraryComponent:${getObjective(workout.objetivo)}`)}
                                </span>
                                )}
                            </div>
                        </div>
                    </div>
                    <div className="col-2 text-end" onClick={event => event.stopPropagation()}>
                        <Dropdown align="end">
                            <Dropdown.Toggle
                                as="button"
                                className="btn btn-link border-0 text-dark p-1 dropdown-toggle-no-caret"
                            >
                                <i className="fa-regular fa-ellipsis-vertical"/>
                            </Dropdown.Toggle>
                            <Dropdown.Menu as={DropdownMenuPortal}>
                                {Number(type) === 1 && (
                                    <Dropdown.Item as="button" onClick={event => handleActionSelect(event, "editName")}>
                                        <i className="fa-regular fa-pen-to-square me-2"/> Editar nome
                                    </Dropdown.Item>
                                )}

                                    {Number(type) === 0 ? (
                                        <WorkoutRoutineClone type={type} workout={workout}/>
                                    ) : (
                                        <WorkoutAerobicClone type={type} workout={workout}/>
                                    )}

                                <Dropdown.Item as="button" onClick={event => handleActionSelect(event, "showDuplicate")}>
                                    <i className="fa-regular fa-copy me-2"/> {t("trainingLibraryComponent:duplicate")}
                                </Dropdown.Item>
                                <Dropdown.Item as="button" onClick={event => handleActionSelect(event, "changeFolder")}>
                                    <i className="fa-regular fa-folder-tree me-2"/> {t("trainingLibraryComponent:changeFolder")}
                                </Dropdown.Item>
                                <Dropdown.Divider/>
                                <Dropdown.Item as="button" className="text-danger" onClick={event => handleActionSelect(event, "showDelete")}>
                                    <i className="fa-regular fa-trash-can me-2"/> {t("trainingLibraryComponent:deleteAction")}
                                </Dropdown.Item>
                            </Dropdown.Menu>
                        </Dropdown>
                    </div>
                </div>
            </div>
            <Modal centered show={modalOpen && Boolean(actionToShow)} onHide={closeModal}>
                <Modal.Body>
                    {actionToShow && renderContent(actionToShow)}
                </Modal.Body>
            </Modal>
        </>
    )

}
export default WorkoutLibraryWorkoutItem;