import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import Page from "../../components/page/Page";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useEffect, useMemo, useState} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {fetchClientGroups} from "../../store/client-group/clientGroupReducer";
import {isFilesLoading, selectEditSuccess, selectOneFile} from "../../store/files/filesSelector";
import {clearEditFile, editFile, fetchOneFile} from "../../store/files/filesReducer";
import * as Yup from "yup";
import {selectClientGroups} from "../../store/client-group/clientGroupSelector";
import {Formik, Form, Field, ErrorMessage} from "formik";
import Select from "react-select";
import ClientRemoteMultiSelect from "../../components/client/ClientRemoteMultiSelect";
import {
    hasRecipientSelection,
    shouldShowRecipientSelectionError
} from "../../utils/form/recipientSelection";

const FilesEditForm = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {clientId, fileId} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const clientGroupList = useSelector(selectClientGroups);
    const file = useSelector(selectOneFile);
    const editSuccess = useSelector(selectEditSuccess);
    const [previewUrl, setPreviewUrl] = useState(null);
    const [hasUnresolvedClientSelections, setHasUnresolvedClientSelections] = useState(false);
    const [hasClientResolveError, setHasClientResolveError] = useState(false);
    const fileLoading = useSelector(isFilesLoading)
    useComponentTranslations("files", {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR})

    useEffect(() => {
        dispatch(fetchClient(clientId));
        dispatch(fetchClientGroups());
    }, [dispatch, clientId]);

    useEffect(() => {
        dispatch(fetchOneFile({id: clientId, fileId}));
    }, [dispatch, fileId, clientId]);

    useEffect(() => {
        if (file && file.url) {
            const isImage = /\.(jpe?g|png|gif|bmp|webp)$/i.test(file.url);
            if (isImage) {
                setPreviewUrl(file.url);
            } else {
                setPreviewUrl(null);
            }
        } else {
            setPreviewUrl(null);
        }
    }, [file]);


    useEffect(() => {
        if (editSuccess) {
            navigate(`/user/client/${clientId}/files`);
            dispatch(clearEditFile());
        }
    }, [editSuccess, navigate, dispatch, clientId]);


    const handleGoBackPage = () => navigate(`/user/client/${clientId}/files`);
    const groupOptions = useMemo(
        () => (clientGroupList || []).map(g => ({ value: g.id, label: g.nome })),
        [clientGroupList]
    );

    const initialValues = useMemo(() => ({
        fileName: file?.nome || "",
        clients: Array.isArray(file?.clients) ? file.clients.map(Number) : [],
        groups: [],
    }), [file]);

    const validationSchema = Yup.object({
        fileName: Yup.string().required(t("files:validation.fileNameRequired")),
        clients: Yup.array().notRequired(),
        groups: Yup.array().notRequired(),
    });

    const handleSubmit = (values) => {
        const payload = {
            fileId,
            nome: values.fileName,
            clients: values.clients || [],
            groups: values.groups || [],
        };

        dispatch(editFile(payload));
    };

    return (
        <>
            <AvatarHeader showGoBack={handleGoBackPage} className={"pb-4 pt-2"}
                          text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                          url={selectedClient?.profileUrl}
            />
            <Page contentHeader={false}>
                <div className={"row justify-content-center d-flex"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            <Formik
                                enableReinitialize
                                initialValues={initialValues}
                                validationSchema={validationSchema}
                                validateOnMount
                                onSubmit={handleSubmit}
                            >
                                {({ values, setFieldValue, touched, setFieldTouched, submitCount, isValid }) => {
                                    const hasSelection = hasRecipientSelection({
                                        clients: values.clients,
                                        groups: values.groups,
                                        showRecipients: true
                                    });
                                    const recipientSelectionError = shouldShowRecipientSelectionError({
                                        touchedClients: touched.clients,
                                        touchedGroups: touched.groups,
                                        submitCount,
                                        hasRecipientSelection: hasSelection,
                                        showRecipients: true
                                    }) ? t("files:validation.selectAtLeastOne") : null;
                                    const isClientSelectionBlocked = hasUnresolvedClientSelections || hasClientResolveError;
                                    const isSubmitDisabled = fileLoading || !isValid || isClientSelectionBlocked || !hasSelection;

                                    return (
                                        <Form>
                                            <div>
                                                <label htmlFor="fileName" className={"fw-semibold"}>
                                                    {t("files:fileName")}
                                                </label>
                                                <Field name="fileName">
                                                    {({ field, form, meta }) => (
                                                        <input
                                                            id="fileName"
                                                            type="text"
                                                            className={`form-control ${meta.touched && meta.error ? "is-invalid" : ""}`}
                                                            value={field.value ?? ""}
                                                            onChange={(e) => form.setFieldValue("fileName", e.target.value.normalize("NFC"))}
                                                            onBlur={field.onBlur}
                                                        />
                                                    )}
                                                </Field>
                                                <ErrorMessage
                                                    name="fileName"
                                                    component="div"
                                                    className="text-red-600 text-sm mt-1"
                                                />
                                                <div className="form-group mt-2">
                                                    <label className="fw-semibold">
                                                        {t("files:selectClients")}
                                                    </label>
                                                    <ClientRemoteMultiSelect
                                                        valueIds={values.clients}
                                                        onChangeIds={(clientIds) => {
                                                            setFieldValue("clients", clientIds, false);
                                                            setFieldTouched("clients", true, false);
                                                        }}
                                                        onBlur={() => setFieldTouched("clients", true, false)}
                                                        onSelectionStateChange={({ unresolvedIds, hasResolveError }) => {
                                                            setHasUnresolvedClientSelections((unresolvedIds || []).length > 0);
                                                            setHasClientResolveError(Boolean(hasResolveError));
                                                        }}
                                                        searchScope={"active"}
                                                        resolveScope={"nonDeleted"}
                                                        placeholder={t("files:select")}
                                                        disabled={fileLoading}
                                                    />
                                                    {isClientSelectionBlocked && (
                                                        <div className="form-text text-danger">
                                                            {t("files:validation.loadSelectedClientsBeforeSave")}
                                                        </div>
                                                    )}
                                                </div>
                                                <div className="form-group mt-2">
                                                    <label className="fw-semibold">
                                                        {t("files:selectGroup")}
                                                    </label>
                                                    <Select
                                                        isMulti
                                                        name="groups"
                                                        options={groupOptions}
                                                        className={"basic-multi-select"}
                                                        classNamePrefix="basic-multi-select"
                                                        placeholder={t("files:select")}
                                                        onChange={opts => {
                                                            const nextGroups = opts ? opts.map((opt) => opt.value) : [];
                                                            setFieldValue("groups", nextGroups, false);
                                                            setFieldTouched("groups", true, false);
                                                        }}
                                                        onBlur={() => setFieldTouched("groups", true, false)}
                                                        value={groupOptions.filter((option) => values.groups.includes(option.value))}
                                                    />
                                                    <div className="form-text">
                                                        {t("files:groupSelectionHelper")}
                                                    </div>
                                                    {recipientSelectionError && (
                                                        <div className="text-danger text-sm mt-1">
                                                            {recipientSelectionError}
                                                        </div>
                                                    )}
                                                </div>
                                                {values.groups.length > 0 && (
                                                    <div className={"text-danger pt-2 text-md"}>
                                                        <span className={"fw-semibold me-1"}>{t("files:attention")}</span>
                                                        <span>{t("files:clonedFile")}</span>
                                                        <span className={"fw-semibold mx-1"}>{t("files:allCaps")}</span>
                                                        <span>{t("files:clientGroups")}</span>
                                                    </div>
                                                )}
                                                {previewUrl && (
                                                    <div className="text-center my-3">
                                                        <img
                                                            src={previewUrl}
                                                            alt="preview"
                                                            className="img-fluid rounded"
                                                            style={{ maxHeight: "200px" }}
                                                        />
                                                    </div>
                                                )}
                                                {!previewUrl && file && (
                                                    <p className="text-md mt-3">
                                                        {t("files:selectedFile")}: <strong>{file.nome}</strong>
                                                    </p>
                                                )}
                                            </div>
                                            <div className="d-grid mt-3 pb-2">
                                                <button type="submit" className="btn btn-primary" disabled={isSubmitDisabled}>
                                                    {t("files:update")}
                                                </button>
                                            </div>
                                        </Form>
                                    );
                                }}
                            </Formik>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
}

export default FilesEditForm;
