import {getMainDomain} from "../../utils/cookie/cookieUtils";
import Cookies from "js-cookie";
import {useEffect, useState} from "react";
import {isDesktop, isTablet} from "react-device-detect";

const Banner = ({banner, handleShowBanner}) => {
    const [link, setLink] = useState(null);

    const handleBannerClick = () => {
        if (banner.bannerLink.includes("mfitdeouro")) {
            window.open(banner.bannerLink, "_blank")
        } else if (banner.bannerLink.includes("mfitpersonal.com.br")) {
            window.location.href = banner.bannerLink;
        } else
            window.open(banner.bannerLink, "_blank")
    }

    const handleHideBanner = () => {
        const mainDomain = getMainDomain();
        Cookies.set("hideBanner", true, {domain: `.${mainDomain}`})
        handleShowBanner()
    }

    useEffect(() => {
        if (isDesktop || isTablet) {
            setLink(banner.bannerUrlDesktop)
        } else {
            setLink(banner.bannerUrlMobile)
        }
    }, [banner]);

    return (
        <div className={"position-fixed bottom-0 w-100  pb-3"} style={{display: "flex", justifyContent: "center", zIndex:"1100"}}>
            <div className={"position-relative"}>
                <div
                    className={
                        "position-absolute bg-white rounded-circle px-1 fs-5 clickable-element"
                    }
                    onClick={handleHideBanner}
                    style={{top: "0.5rem", right: "1rem"}}
                >
              <span className={"d-block lh-1"}>
                <i className={"fa-regular fa-times"}></i>
              </span>
                </div>
                <span className={"clickable-element"} onClick={handleBannerClick}>
                    <img
                        src={link}
                        className={"img-fluid"}
                        alt={`Banner ${banner.id}`}
                    />
                </span>
            </div>
        </div>

    )
}

export default Banner;