import React, { useState } from 'react';
import { Dropdown, DropdownToggle, DropdownMenu, DropdownItem } from 'react-bootstrap';
import { useTranslation } from 'react-i18next';
import useComponentTranslations from '../../utils/translation/useComponentTranslations';
import enUS from './locales/en-us.json';
import ptBR from './locales/pt-br.json';
import esES from './locales/es-es.json';
import ptPT from './locales/pt-pt.json';

export default function ExerciseLibraryActionButtons({
                                                         show,
                                                         onFavoritesClick,
                                                         onAllClick,
                                                         onUserExercisesClick,
                                                         onGroupFilterClick,
                                                         onCategoryFilterClick,
                                                         groupFilter,
                                                         categoryFilter
                                                     }) {
    const { t } = useTranslation();
    useComponentTranslations('exerciseLibraryComponent', {
        'en-US': enUS,
        'pt-BR': ptBR,
        'es-ES': esES,
        'pt-PT': ptPT,
    });

    const groupMapping = {
        'group:1': t('exerciseLibraryComponent:chest'),
        'group:2': t('exerciseLibraryComponent:back'),
        'group:3': t('exerciseLibraryComponent:biceps'),
        'group:4': t('exerciseLibraryComponent:triceps'),
        'group:5': t('exerciseLibraryComponent:lowerBody'),
        'group:6': t('exerciseLibraryComponent:shoulder'),
        'group:7': t('exerciseLibraryComponent:abs'),
        'group:8': t('exerciseLibraryComponent:forearm'),
    };

    const categoryMapping = {
        'category:1': t('exerciseLibraryComponent:weightlifting'),
        'category:2': t('exerciseLibraryComponent:aerobic'),
        'category:3': t('exerciseLibraryComponent:functional'),
        'category:4': t('exerciseLibraryComponent:stretching'),
        'category:5': t('exerciseLibraryComponent:homeTraining'),
        'category:6': t('exerciseLibraryComponent:mobility'),
        'category:7': t('exerciseLibraryComponent:rubberBand'),
        'category:8': t('exerciseLibraryComponent:pilates'),
        'category:9': t('exerciseLibraryComponent:officeExercise'),
    };

    const [selectedGroup, setSelectedGroup] = useState(
        groupFilter ? groupMapping[groupFilter] : ''
    );
    const [selectedCategory, setSelectedCategory] = useState(
        categoryFilter ? categoryMapping[categoryFilter] : ''
    );

    const handleGroup = (key) => {
        setSelectedGroup(groupMapping[key]);
        onGroupFilterClick(key);
    };

    const handleCategory = (key) => {
        setSelectedCategory(categoryMapping[key]);
        onCategoryFilterClick(key);
    };

    const handleReset = () => {
        setSelectedGroup('');
        setSelectedCategory('');
        onAllClick();
    };

    const backendModes = ['all', 'group', 'category'];

    return (
        <>
            <div className="row gap-2 mt-3 justify-content-center">
                <div className="col-auto p-0">
                    <button
                        className={
                            `btn btn-sm ${
                                show === 'favorites'
                                    ? 'btn-primary-lighter'
                                    : 'btn-primary-subtle text-primary'
                            }`
                        }
                        onClick={onFavoritesClick}
                    >
                        {t('exerciseLibraryComponent:favorites')}
                    </button>
                </div>
                <div className="col-auto p-0">
                    <button
                        className={
                            `btn btn-sm ${
                                backendModes.includes(show)
                                    ? 'btn-primary-lighter'
                                    : 'btn-primary-subtle text-primary'
                            }`
                        }
                        onClick={handleReset}
                    >
                        {t('exerciseLibraryComponent:appExercises')}
                    </button>
                </div>
                <div className="col-auto p-0">
                    <button
                        className={
                            `btn btn-sm ${
                                show === 'user'
                                    ? 'btn-primary-lighter'
                                    : 'btn-primary-subtle text-primary'
                            }`
                        }
                        onClick={onUserExercisesClick}
                    >
                        {t('exerciseLibraryComponent:yourExercises')}
                    </button>
                </div>
            </div>

            {backendModes.includes(show) && (
                <div className="row gap-2  mt-2 justify-content-center">
                    <div className="col-auto p-0">
                        <Dropdown onSelect={handleGroup}>
                            <DropdownToggle
                                size="sm"
                                variant={`${selectedGroup ? " bg-success-subtle text-success" : "secondary-subtle text-primary"}`}
                            >
                                {selectedGroup || t('exerciseLibraryComponent:muscleGroups')}
                            </DropdownToggle>
                            <DropdownMenu className="border-0">
                                {Object.entries(groupMapping).map(([k, v]) => (
                                    <DropdownItem key={k} eventKey={k}>
                                        {v}
                                    </DropdownItem>
                                ))}
                            </DropdownMenu>
                        </Dropdown>
                    </div>
                    <div className="col-auto p-0">
                        <Dropdown onSelect={handleCategory}>
                            <DropdownToggle
                                size="sm"
                                variant={`${selectedCategory ? " bg-success-subtle text-success" : "secondary-subtle text-primary"}`}
                            >
                                {selectedCategory || t('exerciseLibraryComponent:categories')}
                            </DropdownToggle>
                            <DropdownMenu className="border-0">
                                {Object.entries(categoryMapping).map(([k, v]) => (
                                    <DropdownItem key={k} eventKey={k}>
                                        {v}
                                    </DropdownItem>
                                ))}
                            </DropdownMenu>
                        </Dropdown>
                    </div>
                    <div className="col-auto p-0">
                        <button className="btn btn-link btn-sm" onClick={handleReset}>
                            {t('exerciseLibraryComponent:clear')}
                        </button>
                    </div>
                </div>
            )}
        </>
    );
}
