import {Image} from "react-bootstrap";
import React, {useCallback, useEffect, useState} from "react";
import Page from "../../components/page/Page";
import AiEvaluationAnalysis from "../../components/ai/AiEvaluationAnalysis";
import {ErrorMessage, Field, Form, Formik} from "formik";
import moment from "moment/moment";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {
    getEvaluation,
    getLoading,
    getSubmitLoading,
    getSubmitResult
} from "../../store/online-evaluation/evaluationOnlineSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import * as Yup from "yup";
import {calculateAge} from "../../utils/date/dateUtils";
import {
    fetchEvaluationOnline,
    resetFormSent,
    saveOnline
} from "../../store/online-evaluation/evaluationOnlineReducer";
import {fetchClient} from "../../store/client/clientReducer";
import EvaluationImageUpload from "../../utils/imageupdate/EvaluationImageUpload";
import he from "he";
import EvaluationSubmitButton from "../../components/evaluation-components/EvaluationSubmitButton";
import {
    buildOnlineEvaluationEndRoute,
    buildOnlineEvaluationsRoute
} from "../../utils/client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const OnlineEvaluationEdit = () => {
    const {id, evaluationId} = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const selectedClient = useSelector(selectSelectedClient);
    const evaluationData = useSelector(getEvaluation);
    const loading = useSelector(getLoading);
    const submitLoading = useSelector(getSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const [isExpanded, setIsExpanded] = useState(false);
    const {t} = useTranslation();
    useComponentTranslations("evaluationOnline", {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT,
    });
    const today = moment().format("YYYY-MM-DD");
    const currentClientId = Number(id);

    const initialValues = {
        goal: he.decode(evaluationData?.goal ?? ""),
        idade: evaluationData?.idade ?? "",
        answerDate: evaluationData?.answerDate ?? today,
        height: evaluationData?.height ?? "",
        weight: evaluationData?.weight ?? "",
        chest: evaluationData?.chest ?? "",
        biceps: evaluationData?.biceps ?? "",
        forearm: evaluationData?.forearm ?? "",
        waist: evaluationData?.waist ?? "",
        abs: evaluationData?.abs ?? "",
        hip: evaluationData?.hip ?? "",
        thigh: evaluationData?.thigh ?? "",
        pictureFront: evaluationData?.pictureFront ?? "",
        pictureSide: evaluationData?.pictureSide ?? "",
        pictureBack: evaluationData?.pictureBack ?? "",
    };

    const fieldMapping = {
        goal: t("evaluationOnline:goal"),
        idade: t("evaluationOnline:age"),
        answerDate: t("evaluationOnline:answered"),
        height: t("evaluationOnline:height"),
        weight: t("evaluationOnline:weight"),
        chest: t("evaluationOnline:chest"),
        biceps: t("evaluationOnline:biceps"),
        forearm: t("evaluationOnline:forearm"),
        waist: t("evaluationOnline:waist"),
        abs: t("evaluationOnline:abs"),
        hip: t("evaluationOnline:hip"),
        thigh: t("evaluationOnline:thigh"),
    };

    const validationSchema = Yup.object(
        Object.keys(initialValues).reduce((acc, key) => {
            const value = initialValues[key];

            if (typeof value === "number") {
                acc[key] = Yup.number()
                    .typeError(t("evaluationOnline:invalidValue"))
                    .moreThan(0, t("evaluationOnline:invalidValue"))
                    .required(t("evaluationOnline:requiredField"));
            }
            return acc;
        }, {})
    );

    if (selectedClient && selectedClient.data_nascimento) {
        initialValues.idade = calculateAge(selectedClient.data_nascimento);
    }

    const handleSubmit = async (values) => {
        const data = {
            id: evaluationId,
            idClient: id,
            ...values,
        };
        dispatch(saveOnline(data, {
            flow: EVALUATION_FLOWS.ONLINE_EDIT,
            clientId: currentClientId
        }));
    };

    const handleGoBack = useCallback(() => {
        navigate(buildOnlineEvaluationsRoute(id, "1"));
    }, [navigate, id]);

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        if (evaluationId) {
            dispatch(fetchEvaluationOnline(evaluationId));
        }
    }, [dispatch, evaluationId]);

    useEffect(() => {
        if (isMatchingSubmitSuccess(submitResult, {
            action: "update",
            flow: EVALUATION_FLOWS.ONLINE_EDIT,
            clientId: currentClientId
        })) {
            navigate(buildOnlineEvaluationEndRoute(id, submitResult.entityId ?? evaluationId));
        }
    }, [submitResult, navigate, id, evaluationId, currentClientId]);

    return (
        <>
            <div className={"bg-default text-center text-white pt-2 d-none d-print-block"}>
                <div className={"row justify-content-center "}>
                    <div className={'col-12'}>
                        <Image fluid={true} style={{height: "33px"}}
                               className={"clickable-element"}
                               src={`https://cdn.mfitpersonal.com.br/assets/logo/logo-horizontal.svg`}/>
                    </div>
                </div>
            </div>
            <Page title={t("evaluationOnline:onlineEvaluation")} goBackLink={handleGoBack} loading={loading}>
                <div className="row justify-content-center">
                    <div className="col-12">
                        {evaluationData?.answerDate && (
                            <div className="card card-body border-0 mb-2 d-print-block">
                                <AiEvaluationAnalysis
                                    id={evaluationId}
                                    aiAnalysis={evaluationData.aiAnalysis}
                                    isExpanded={isExpanded}
                                    setIsExpanded={setIsExpanded}
                                />
                            </div>
                        )}
                        {evaluationData && (
                            <Formik
                                initialValues={initialValues}
                                validationSchema={validationSchema}
                                enableReinitialize
                                onSubmit={handleSubmit}
                                validateOnChange
                                validateOnBlur
                            >
                                {({values, setFieldValue}) => (
                                    <Form className={"card card-body border-0"}>
                                        {Object.entries(initialValues).map(([fieldName, fieldValue]) => {
                                            let inputType = "text";
                                            if (fieldName.toLowerCase().includes("date")) {
                                                inputType = "date";
                                            } else if (typeof fieldValue === "number") {
                                                inputType = "number";
                                            }
                                            return !["pictureFront", "pictureSide", "pictureBack"].includes(fieldName) ? (
                                                <div key={fieldName} className="mb-3">
                                                    <label htmlFor={fieldName} className="fw-semibold">
                                                        {fieldMapping[fieldName] || fieldName}
                                                    </label>
                                                    <Field
                                                        id={fieldName}
                                                        name={fieldName}
                                                        type={inputType}
                                                        className="form-control mt-1"
                                                    />
                                                    <ErrorMessage name={fieldName} component="div"
                                                                  className="text-danger"/>
                                                </div>
                                            ) : null;
                                        })}
                                        <>
                                            <div className="mt-6">
                                                <h5 className="font-semibold mb-3">{t("evaluationOnline:evaluationPhotos")}</h5>
                                                <EvaluationImageUpload
                                                    slots={3}
                                                    existingImages={[values.pictureFront, values.pictureSide, values.pictureBack]}
                                                    user={{id}}
                                                    selectedClient={selectedClient}
                                                    basePath="onlineevaluation"
                                                    onImagesUpload={(urls) => {
                                                        setFieldValue("pictureFront", urls[0]);
                                                        setFieldValue("pictureSide", urls[1]);
                                                        setFieldValue("pictureBack", urls[2]);
                                                    }}
                                                    Anexar={t("evaluationOnline:attach")}
                                                />
                                            </div>
                                            <div className="row mt-3">
                                                <div className="col-12">
                                                    <EvaluationSubmitButton
                                                        label={t("evaluationOnline:save")}
                                                        loadingLabel={t("evaluationOnline:saving")}
                                                        isSubmitting={submitLoading}
                                                    />
                                                </div>
                                            </div>
                                            <div
                                                className={"d-flex align-items-center  justify-content-center pt-2"}>
                                                <button className={"btn btn-outline-primary w-100"}
                                                        type="button"
                                                        onClick={handleGoBack}>
                                                    {t("evaluationOnline:backEvaluations")}
                                                </button>
                                            </div>
                                        </>
                                    </Form>
                                )}
                            </Formik>
                        )}
                    </div>
                </div>
            </Page>
        </>
    )
}

export default OnlineEvaluationEdit;
