import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    csat: null,
    permission: null,
    chargeback: null,
    spointUser: null,
    blocked: null,
    badPassword: null,
    loading: false
}

export const slice = createSlice({
    name: "check",
    initialState,
    reducers: {
        checkBadPassword(){
        },
        setBadCheckPassword(state, action){
            state.badPassword = action.payload;
        },
        checkPermission() {
        },
        setPermission(state, action) {
            state.permission = action.payload
        },
        skipCsat(state) {
            state.loading = true
        },
        answerCsat(state) {
            state.loading = true
        },
        csatAnswered(state) {
            state.csat = null
            state.loading = false
        },
        checkPendingChargeback() {
        },
        setPendingChargeback(state, action) {
            state.chargeback = action.payload
        },
        checkSpointUser() {
        },
        setSpointUser(state, action) {
            state.spointUser = action.payload
        },
        checkPendingCsat() {
        },
        setPendingCsat(state, action) {
            state.csat = action.payload
        },
        checkUserBlocked(){
        },
        setBlocked(state, action) {
            state.blocked = action.payload
        },
        onError(state) {
            state.loading = false
        }
    }
})

export const {
    checkPendingCsat,
    setPendingCsat,
    checkPendingChargeback,
    setPendingChargeback,
    checkSpointUser,
    setSpointUser,
    answerCsat,
    csatAnswered,
    setPermission,
    checkPermission,
    skipCsat,
    checkUserBlocked,
    checkBadPassword,
    setBadCheckPassword,
    setBlocked,
    onError
} = slice.actions;

export const checkReducer = slice.reducer;
