import RoundedIcon from "../rounded-icon/RoundedIcon";
import Modal from "react-bootstrap/Modal";
import {useState} from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutRoutineEmpty = ({create}) => {
    const {t} = useTranslation();
    const [showVideo, setShowVideo] = useState(false);
    useComponentTranslations('routineWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleShowVideo = () => {
        setShowVideo(prevState => !prevState)
    }

    return (
        <div className={"row mt-5"}>
            <div className={"col-12 text-center"}>
                <RoundedIcon icon={"fa-dumbbell"} size={"xl"}/>
            </div>
            <div className={"col-12 text-center mt-3"}>
                <span className={"fw-semibold fs-5"}>{t("routineWorkoutComponent:createRoutineMessage")}</span>
            </div>
            <div className={"col-12 text-center mt-3"}>
                <div className={'d-grid'}>
                    <button className={"btn btn-primary"} onClick={create}>{t("routineWorkoutComponent:createRoutine")}</button>
                </div>
                <div className={'d-grid mt-2'}>
                    <button className={"btn btn-outline-primary"} onClick={handleShowVideo}>{t("routineWorkoutComponent:watchTutorial")}</button>
                </div>
            </div>
            <Modal show={showVideo} onHide={handleShowVideo} centered size={"lg"}>
                <Modal.Body>
                    <div className={"row"}>
                        <div className={"col-12"}>
                            <span className={"fw-semibold fs-4"}>{t("routineWorkoutComponent:tutorial")}</span>
                        </div>
                        <div className={"col-12  mt-2"} >
                            <div className="ratio ratio-4x3">
                                <iframe src="https://www.youtube.com/embed/lJl_SOXPqLw?rel=0" title="YouTube video" allowFullScreen></iframe>
                            </div>
                        </div>
                        <div className={'d-grid mt-4'}>
                            <button className={"btn btn-primary"} onClick={create}>{t("routineWorkoutComponent:createRoutine")}</button>
                        </div>
                        <div className={'d-grid mt-2'}>
                            <button className={"btn btn-outline-primary"} onClick={handleShowVideo}>{t("routineWorkoutComponent:close")}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </div>
    )
}
export default WorkoutRoutineEmpty