import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useNavigate, useParams} from "react-router-dom";
import {useEffect, useState} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import Tabs from "../../components/tab/Tabs";
import WorkoutRoutine from "../../components/workout-routine/WorkoutRoutine";
import WorkoutAerobic from "../../components/workout-aerobic/WorkoutAerobic";
import {isWorkoutLoading} from "../../store/workout/workoutSelector";
import {fetchAllWorkouts} from "../../store/workout/workoutReducer";
import {selectAerobics} from "../../store/workout-aerobic/workoutAerobicSelector";
import {selectWorkoutRoutines} from "../../store/workout-routine/workoutRoutineSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const Workout = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const {clientId, type} = useParams()
    const [page, setPage] = useState(type ?? "1");
    const navigate = useNavigate();
    const workouts = useSelector(selectWorkoutRoutines)
    const aerobics = useSelector(selectAerobics)
    const workoutLoading = useSelector(isWorkoutLoading);
    const client = useSelector(selectSelectedClient)
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const changePages = (pageName) => {
        setPage(pageName);
    };

    const handleGoBack = () => {
        navigate(`/user/client/${client.id}`)
    }

    useEffect(() => {
        if (Number(clientId) > 0)
            dispatch(fetchClient(clientId));
    }, [dispatch, clientId]);

    useEffect(() => {
        dispatch(fetchAllWorkouts(clientId))
    }, [dispatch, clientId]);

    return (
        <>
            <AvatarHeader className={"pb-4 pt-2"}
                          text={`${client?.nome} ${client?.sobrenome}`}
                          showGoBack={handleGoBack}
                          url={client?.profileUrl}/>
            <Page contentHeader={false} loading={workoutLoading}>
                {
                    !workoutLoading && (workouts || aerobics) &&
                    <>
                        <Tabs page={page} button1Text={t("workout:workoutPlans")} button2Text={t("workout:aerobic")} mt={"mt-n4"} buttonClick={changePages}/>
                        {
                            page === "1" ?
                                <WorkoutRoutine/> :
                                <WorkoutAerobic/>
                        }
                    </>
                }
            </Page>
        </>
    )
}
export default Workout;