import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/extra-training/locales/en-us.json";
import esES from "../../pages/extra-training/locales/es-es.json";
import ptPT from "../../pages/extra-training/locales/pt-pt.json";
import ptBR from "../../pages/extra-training/locales/pt-br.json";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import Dropdown from "react-bootstrap/Dropdown";
import DropdownMenuPortal from "../utils/dropdown/DropdownMenuPortal";
import Player from "../utils/videoplayer/Player";
import Text from "../utils/emoji/Text";

const ExtraTrainingCard = ({extraTraining, onEdit, onSend, onDelete, onExecute}) => {
    const {t, i18n} = useTranslation();

    useComponentTranslations("extraTrainingUser", {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR});

    syncMomentLocale(i18n.language);

    const executeDate = moment({
        year: extraTraining.executeAt.year,
        month: extraTraining.executeAt.month - 1,
        day: extraTraining.executeAt.day
    }).format("L");

    return (
        <div className="card card-body border-0 mb-2">
            <div className="row align-items-start">
                <div className="col-10">
                    <span className="fw-semibold fs-5 d-block">{extraTraining.atividade}</span>
                    <span className="fw-semibold me-1">{t("extraTrainingUser:executeDate")}</span>
                    <span>{executeDate}</span>
                </div>
                <div className="col-2 text-end">
                    <Dropdown align="end">
                        <Dropdown.Toggle as="button" className="btn btn-link border-0 text-dark p-0 dropdown-toggle-no-caret">
                            <i className="fa-regular fa-ellipsis-vertical"/>
                        </Dropdown.Toggle>
                        <Dropdown.Menu as={DropdownMenuPortal}>
                            <Dropdown.Item as="button" onClick={onExecute}>
                                <i className="fa-regular fa-check me-2"/> {t("extraTrainingUser:markAsExecuted")}
                            </Dropdown.Item>
                            <Dropdown.Item as="button" onClick={onSend}>
                                <i className="fa-regular fa-share-from-square me-2"/> {t("extraTrainingUser:sendTo")}
                            </Dropdown.Item>
                            <Dropdown.Item as="button" onClick={onEdit}>
                                <i className="fa-regular fa-pen-to-square me-2"/> {t("extraTrainingUser:edit")}
                            </Dropdown.Item>
                            <Dropdown.Divider/>
                            <Dropdown.Item as="button" className="text-danger" onClick={onDelete}>
                                <i className="fa-regular fa-trash-can me-2"/> {t("extraTrainingUser:delete")}
                            </Dropdown.Item>
                        </Dropdown.Menu>
                    </Dropdown>
                </div>
            </div>
            {extraTraining.instructions && (
                <div className="mt-2">
                    <div style={{whiteSpace: "pre-wrap"}}>
                        <Text>{extraTraining.instructions}</Text>
                    </div>
                </div>
            )}
            <span className="text-primary mt-2">{t("extraTrainingUser:notExecuted")}</span>
            {extraTraining.url && (
                <div className="mt-3">
                    <Player
                        type="youtube"
                        src={`https://www.youtube.com/embed/${extraTraining.url}?&theme=dark&autohide=2&modestbranding=1&showinfo=0&rel=0`}
                    />
                </div>
            )}
        </div>
    );
};

export default ExtraTrainingCard;
