import {useState} from "react";
import Modal from "react-bootstrap/Modal";
import ExercisePlayer from "../utils/videoplayer/ExercisePlayer";

const WorkoutVideo = ({exercise = false, showSeries}) => {
    const [show, setShow] = useState(false);
    const handleMediaClick = () => {
        setShow(prevShow => !prevShow)
    }
    return (
        <>
            <div
                className={` hide-me col-4 text-center position-relative clickable-element ${showSeries? 'ps-0': ''} align-self-stretch`}
                onClick={handleMediaClick}
                style={{ display: 'flex', alignItems: 'stretch', flex: '1 1 0%' ,maxHeight:  '180px' }}>
                <div style={{ position: 'relative', flexGrow: 1, overflow: 'hidden', height: '100%' }}>
                    <img src={exercise.urlPoster} alt="" className={'rounded-1'} style={{ objectFit: 'cover', objectPosition: 'center', height: '100%', width: '100%' }} />
                    <div className="position-absolute" style={{ top: '50%', left: '50%', transform: 'translate(-50%, -50%)' }}>
                        <i className={'fa-duotone fa-circle-play fa-2xl text-default'} style={{"--fa-secondary-color": "#fff"}}></i>
                    </div>
                </div>
            </div>
            <Modal centered show={show} onHide={handleMediaClick} contentClassName={"bg-transparent border-0"}>
                <Modal.Body style={{padding: 0}}>
                    <ExercisePlayer src={exercise.urlMedia} poster={exercise.urlPoster}
                                    handleMediaClose={handleMediaClick}/>
                </Modal.Body>
            </Modal>
        </>
    )
}
export default WorkoutVideo;
