import falknerFields from './falknerFields';
import pollock7Fields from './pollock7Fields';
import pollock3Fields from './pollock3Fields';
import siriBrozekFields from './siriBrozekFields';
import yuhaszFields from './yuhaszFields';
import petroskiFields from './petroskiFields';
import guedes2Fields from './guedes2Fields';
import guedes3Fields from './guedes3Fields';
import penroeFields from './penroeFields';
import weltmanFields from './weltmanFields';
import bioimpedanceFields from "../bioimpedanceEvaluation/bioimpedanceFields";

const buildProtocolData = (gender = 'male') => [
    { id: 0, name: 'Faulkner, 1968 - 4 Dobras', fields: falknerFields, translationKey: 'falkner_1968_4dobras'},
    { id: 1, name: 'Pollock, 1984 - 7 Dobras', fields: pollock7Fields, translationKey: 'pollock_1984_7dobras'},
    { id: 2, name: 'Pollock, 1984 - 3 Dobras', fields: pollock3Fields[gender], translationKey: 'pollock_1984_3dobras'},
    { id: 3, name: 'Siri & Brozek - 4 Dobras', fields: siriBrozekFields, translationKey: 'siri_brozek_4dobras' },
    { id: 4, name: 'Yuhasz - 6 Dobras', fields: yuhaszFields, translationKey: 'yuhasz_6dobras'},
    { id: 9, name: 'Petroski, 1995 - 4 Dobras', fields: petroskiFields[gender], translationKey: 'petroski_4dobras'},
    { id: 10, name: 'Guedes, 1994 - 3 Dobras', fields: guedes3Fields[gender], translationKey: 'guedes_3dobras'},
    { id: 7, name: 'Guedes - 2 Dobras - Crianças e Adolescentes', fields: guedes2Fields[gender], translationKey: 'guedes_2dobras'},
    { id: 5, name: 'Penroe, Nelson e Fischer, 1985 e Coté e Wilmore - 2 Medidas', fields: penroeFields[gender], translationKey: 'penroe_cote_2medidas'},
    { id: 6, name: 'Weltman e col. - Para pessoas obesas - 2 Medidas', fields: weltmanFields, translationKey: 'weltman_2medidas'}
];

export const getProtocolData = buildProtocolData;
export const protocolData = buildProtocolData();

export const getProtocolMap = (gender = 'male') => {
    return buildProtocolData(gender).reduce((map, protocolo) => {
        map[protocolo.id] = protocolo;
        return map;
    }, {});
};

export const protocolMap = getProtocolMap();

export const bioProtocol = [
    { id: 8, name: 'Inserção Manual ou Bioimpendância', fields: bioimpedanceFields, translationKey: 'manual_bioimpedancia'},
];