import {useNavigate} from "react-router-dom";
import React, {useState} from "react";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import FeedbackResolved from "./FeedbackResolved";
import FeedbackList from "./FeedbackList";
import Tabs from "../../components/tab/Tabs";

const Feedback = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const [page, setPage] = useState("1")
    useComponentTranslations('feedbackList', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate("/user")
    }

    const changePages = (pageName) => {
        setPage(pageName)
    }

    return (
        <>
            <div className={"row justify-content-center bg-default text-white  pt-1 ms-0 me-0"}>
                <div className={"col-12 col-md-6 col-lg-6 col-xl-4"}>
                    <div className={"row"}>
                        <div className={"col-12 col-md-6 col-lg-6 col-xl-4"}>
                            <span className={'small clickable-element'} onClick={handleGoBack}>
                               <i className={"fa-regular fa-chevron-left me-1"}/>{t("feedbackList:back")}
                           </span>
                        </div>
                    </div>
                    <div className={"col-12 col-md-6 col-lg-6 col-xl-4 mt-4 mb-2"}>
                        <span className={'fs-5 d-block lh-1'}>{t("feedbackList:feedBacks")}</span>
                    </div>
                </div>
            </div>
            <div className={"row justify-content-evenly bg-default m-0"}>
                <div className={"col-12 col-md-6 col-lg-6 col-xl-4"}>
                    <Tabs page={page} button1Text={"Feedbacks"} button2Text={t("feedbackList:resolved")} buttonClick={changePages}/>
                </div>
            </div>
            <Page contentHeader={false} mt={"mt-n2"}>
                {
                    page === "1" ? <FeedbackList/> : <FeedbackResolved/>
                }
            </Page>
        </>
    )
}
export default Feedback;