import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {Formik, Field, Form, ErrorMessage} from "formik";
import * as Yup from "yup";
import React, {useCallback, useEffect, useState} from "react";
import {getVideoDimensions} from "../../utils/video/videoUtils";
import uploadFile from "../../utils/fileupload/s3FileUpload";
import {imageResizer} from "../../utils/imageresize/imageResizer";
import uploadFileUS from "../../utils/fileupload/s3FileUploadUS";
import {useDispatch, useSelector} from "react-redux";
import {
    selectExercise, selectExerciseCategories, selectExerciseGroups, selectExerciseSaved,
    selectLibraryLoading,
} from "../../store/exercise-library/exerciseLibrarySelector";
import {
    fetchExercise,
    fetchExerciseCategories,
    fetchExerciseGroups, setExercise, setExerciseAsSaved, updateExercise,
} from "../../store/exercise-library/exerciseLibraryReducer";
import {selectUser} from "../../store/user/userSelector";
import ExercisePlayer from "../../components/utils/videoplayer/ExercisePlayer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from 'he';
import {selectWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionSelector";
import {fetchWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionReducer";

const ExerciseEdit = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id, clone, sessionId} = useParams();
    const [uploadProgress, setUploadProgress] = useState(0);
    const [isUploading, setIsUploading] = useState(false);
    const loading = useSelector(selectLibraryLoading);
    const categories = useSelector(selectExerciseCategories);
    const muscleGroups = useSelector(selectExerciseGroups);
    const exercise = useSelector(selectExercise);
    const user = useSelector(selectUser);
    const exerciseSaved = useSelector(selectExerciseSaved);
    const session = useSelector(selectWorkoutSession)
    useComponentTranslations('exerciseLibrary', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        dispatch(fetchExerciseGroups());
        dispatch(fetchExerciseCategories());
        dispatch(fetchExercise(id));
    }, [dispatch, id]);


    const initialValues = {
        name: he.decode(exercise?.name || ""),
        media: exercise?.mediaType,
        photo: exercise?.mediaType === 1 ? exercise?.urlMedia : null,
        video: exercise?.mediaType === 3 ? exercise?.urlMedia : null,
        link:
            exercise?.mediaType === 0
                ? `https://www.youtube.com/watch?v=${exercise?.urlMedia}`
                : "",
        muscleGroup: exercise?.exerciseGroup?.id
            ? exercise?.exerciseGroup.id.toString()
            : "",
        newMuscleGroup: "",
        category: exercise?.exerciseCategory?.id
            ? exercise.exerciseCategory.id.toString()
            : "",
        newCategory: "",
        addToFavorites: "false",
        videoWidth: "",
        videoHeight: "",
        removeAudio: true,
    };

    const validationSchema = Yup.object().shape({
        name: Yup.string()
            .max(245, t("exerciseLibrary:maxChars245"))
            .required(t("exerciseLibrary:required")),
        photo: Yup.mixed().nullable().when("media", {
            is: 1,
            then: (schema) => schema.required(t("exerciseLibrary:required")),
            otherwise: (schema) => schema,
        }),
        video: Yup.mixed().nullable().when("media", {
            is: 3,
            then: (schema) => schema.required(t("exerciseLibrary:required")),
            otherwise: (schema) => schema,
        }),
        link: Yup.string().when('media', {
            is: '0',
            then: (schema) =>
                schema
                    .required(t("exerciseLibrary:required"))
                    .matches(
                        /^(https?:\/\/)?(www\.)?(youtube\.com|youtu\.?be)\/.+$/,
                        t("exerciseLibrary:invalidURL")
                    ),
            otherwise: (schema) => schema,
        }),
        muscleGroup: Yup.string().required(t("exerciseLibrary:required")),
        newMuscleGroup: Yup.string().when("muscleGroup", {
            is: "create",
            then: (schema) => schema.required(t("exerciseLibrary:required")),
            otherwise: (schema) => schema,
        }),
        category: Yup.string().required(t("exerciseLibrary:required")),
        newCategory: Yup.string().when("category", {
            is: "create",
            then: (schema) => schema.required(t("exerciseLibrary:required")),
            otherwise: (schema) => schema,
        }),
        addToFavorites: Yup.string().required(t("exerciseLibrary:required")),
    });

    const handleSubmit = async (values) => {
        try {

            const videoChanged = values.media === 3 && typeof values.video !== "string";

            if (values.media === 1 && values.photo && typeof values.photo !== "string") {
                setIsUploading(true);
                const resizedImageFile = await imageResizer(values.photo);
                const imageUrl = await uploadFile(
                    resizedImageFile,
                    user.id,
                    0,
                    "exercicios"
                );
                values.photo = imageUrl;
            }

            if (videoChanged) {
                setIsUploading(true);
                const dimensions = await getVideoDimensions(values.video);
                const videoUrl = await uploadFileUS(
                    values.video,
                    user.id,
                    (evt) => {
                        const progress = Math.round((evt.loaded / evt.total) * 100);
                        setUploadProgress(progress);
                    }
                );
                values.video = videoUrl;
                values.videoWidth = dimensions.width;
                values.videoHeight = dimensions.height;
            }

            setIsUploading(false);

            const payload = {
                id: exercise.id,
                name: values.name,
                mediaType: values.media, // numeric value
                urlMedia:
                    values.media === 1
                        ? values.photo
                        : values.media === 3
                            ? values.video
                            : values.link,
                urlPoster:
                    values.media === 3 && typeof values.video !== "string"
                        ? ""
                        : exercise.urlPoster,
                exerciseGroup:
                    values.muscleGroup === "create"
                        ? {nome: values.newMuscleGroup}
                        : {id: values.muscleGroup},
                exerciseCategory:
                    values.category === "create"
                        ? {name: values.newCategory}
                        : {id: values.category},
                addToFavorites: values.addToFavorites === "true",
                videoWidth: values.videoWidth,
                videoHeight: values.videoHeight,
                removeAudio: values.media === 3 ? values.removeAudio : true,
                videoChanged,
            };
            dispatch(updateExercise(payload));
        } catch (error) {
            setIsUploading(false);
            console.error("Error updating exercise:", error);
        }
    };

    const handleGoBack = useCallback(() => {
        dispatch(setExercise(null))
        if (sessionId > 0) {
            navigate(`/user/client/${session.idAluno}/workout/routine/${session.idRoutine}/session/${session.id}/exercise-list/user`);
        } else
            navigate(`/user/exercise-library/user`);
    }, [sessionId, navigate, session, dispatch]);

    useEffect(() => {
        if (sessionId > 0) {
            dispatch(fetchWorkoutSession(sessionId))
        }
    }, [dispatch, sessionId]);

    useEffect(() => {
        if (exerciseSaved) {
            dispatch(setExercise(null))
            dispatch(setExerciseAsSaved(false));
            if (session?.id > 0) {
                navigate(`/user/client/${session.idAluno}/workout/routine/${session.idRoutine}/session/${session.id}/exercise-list/type/user/exercise/${id}`);
            } else
                handleGoBack()
        }
    }, [dispatch, exerciseSaved, handleGoBack, session, id, navigate]);

    return (
        <Page
            title={t("exerciseLibrary:editExercise")}
            goBackLink={handleGoBack}
            pb={"pb-2"}
            loading={!exercise || !muscleGroups || !categories}
        >
            <div className="row justify-content-center">
                <div className="col-12">
                    <div className="card card-body border-0">
                        {
                            clone &&
                            <div className={"row justify-content-center"}>
                                <div className={"col-12"}>
                                    <div className={'card card-body bg-primary-subtle border-0 text-primary'}>
                                        <div className={'row'}>
                                            <div className={"col-2 align-self-center"}>
                                                <i className={'fa-regular fa-exclamation-circle fa-2x'}></i>
                                            </div>
                                            <div className={"col-10 align-self-center ps-0"}>
                                                <span>{t("exerciseLibrary:customExerciseSaved")}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        }

                        <Formik
                            initialValues={initialValues}
                            validationSchema={validationSchema}
                            onSubmit={handleSubmit}
                            enableReinitialize={true}
                        >
                            {({values, setFieldValue}) => (
                                <Form>
                                    <div className="row justify-content-center">
                                        <div className="col-12">
                                            <div className="mb-3">
                                                <label htmlFor="name" className="form-label fw-semibold">
                                                    {t("exerciseLibrary:name")}
                                                </label>
                                                <Field name="name" type="text" className="form-control"/>
                                                <ErrorMessage name="name" component="div" className="text-danger"/>
                                            </div>
                                        </div>
                                        <div className="col-12">
                                            <div className="mb-3">
                                                <label htmlFor="media" className="form-label fw-semibold">
                                                    {t("exerciseLibrary:media")}
                                                </label>
                                                <Field
                                                    as="select"
                                                    name="media"
                                                    className="form-control form-select"
                                                    onChange={(e) =>
                                                        setFieldValue("media", parseInt(e.target.value))
                                                    }
                                                >
                                                    <option value="99">{t("exerciseLibrary:noMedia")}</option>
                                                    <option value="1">{t("exerciseLibrary:photoGif")}</option>
                                                    <option value="3">{t("exerciseLibrary:mobileVideo")}</option>
                                                    <option value="0">{t("exerciseLibrary:youtubeLink")}</option>
                                                </Field>
                                                <ErrorMessage name="media" component="div" className="text-danger"/>
                                            </div>
                                        </div>
                                        {values.media !== 99 && values.media === initialValues.media && (
                                            <div className="col-12">
                                                <div className="mb-3">
                                                    <label className="form-label fw-semibold">{t("exerciseLibrary:currentMedia")}</label>
                                                    <div className="row justify-content-center">
                                                        <div className={`col-${values.media === 0 ? "auto" : "6"}`}>
                                                            {values.media === 1 && (
                                                                <img
                                                                    src={
                                                                        typeof values.photo === "string"
                                                                            ? values.photo
                                                                            : values.photo
                                                                                ? URL.createObjectURL(values.photo)
                                                                                : ""
                                                                    }
                                                                    alt="Current Media"
                                                                    className="img img-fluid"
                                                                />
                                                            )}
                                                            {values.media === 3 && (
                                                                <>
                                                                    {typeof values.video === "string" ? (
                                                                        <ExercisePlayer
                                                                            src={values.video}
                                                                            poster={exercise.urlPoster}
                                                                            hideCloseBtn={true}
                                                                        />
                                                                    ) : (
                                                                        values.video && (
                                                                            <video
                                                                                src={URL.createObjectURL(values.video)}
                                                                                controls
                                                                                className="img-fluid"
                                                                            />
                                                                        )
                                                                    )}
                                                                </>
                                                            )}
                                                            {values.media === 0 && (
                                                                <div className="embed-responsive">
                                                                    <iframe
                                                                        className="embed-responsive-item"
                                                                        src={`https://www.youtube.com/embed/${exercise.urlMedia}`}
                                                                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                                                        allowFullScreen
                                                                        title="YouTube video preview"
                                                                    ></iframe>
                                                                </div>
                                                            )}
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        )}
                                        {values.media === 1 && (
                                            <div className="mb-3">
                                                <label htmlFor="photo" className="form-label fw-semibold">
                                                    {t("exerciseLibrary:selectNewImage")}
                                                </label>
                                                <input
                                                    id="photo"
                                                    name="photo"
                                                    type="file"
                                                    accept="image/*"
                                                    className="form-control"
                                                    onChange={(event) =>
                                                        setFieldValue("photo", event.currentTarget.files[0])
                                                    }
                                                />
                                                <ErrorMessage name="photo" component="div" className="text-danger"/>
                                            </div>
                                        )}
                                        {values.media === 3 && (
                                            <>
                                                <div className="mb-3">
                                                    <label htmlFor="video" className="form-label fw-semibold">
                                                        {t("exerciseLibrary:selectNewVideo")}
                                                    </label>
                                                    <input
                                                        id="video"
                                                        name="video"
                                                        type="file"
                                                        accept="video/*"
                                                        className="form-control"
                                                        onChange={(event) =>
                                                            setFieldValue("video", event.currentTarget.files[0])
                                                        }
                                                    />
                                                    <ErrorMessage name="video" component="div" className="text-danger"/>
                                                </div>
                                                <div className="mb-3">
                                                    <div className="form-check">
                                                        <Field
                                                            type="checkbox"
                                                            name="removeAudio"
                                                            className="form-check-input"
                                                            id="removeAudio"
                                                        />
                                                        <label htmlFor="removeAudio" className="form-check-label">
                                                            {t("exerciseLibrary:removeAudio")}
                                                        </label>
                                                    </div>
                                                </div>
                                            </>
                                        )}
                                        {values.media === 0 && (
                                            <div className="mb-3">
                                                <label htmlFor="link" className="form-label fw-semibold">
                                                    {t("exerciseLibrary:youtubeURL")}
                                                </label>
                                                <Field name="link" type="text" className="form-control"/>
                                                <ErrorMessage name="link" component="div" className="text-danger"/>
                                            </div>
                                        )}
                                        <div className="mb-3">
                                            <label htmlFor="muscleGroup" className="form-label fw-semibold">
                                                {t("exerciseLibrary:muscleGroup")}
                                            </label>
                                            <Field as="select" name="muscleGroup" className="form-control form-select">
                                                <option value="">{t("exerciseLibrary:selectMuscleGroup")}</option>
                                                <option value="create">{t("exerciseLibrary:createNewGroup")}</option>
                                                {muscleGroups?.map((group) => (
                                                    <option key={group.id} value={group.id}>
                                                        {
                                                            group.idUser > 0 ? group.nome :
                                                                t(`exerciseLibrary:${group.alias}`)
                                                        }
                                                    </option>
                                                ))}
                                            </Field>
                                            <ErrorMessage name="muscleGroup" component="div" className="text-danger"/>
                                        </div>
                                        {values.muscleGroup === "create" && (
                                            <div className="mb-3">
                                                <label htmlFor="newMuscleGroup" className="form-label fw-semibold">
                                                    {t("exerciseLibrary:newMuscleGroup")}
                                                </label>
                                                <Field name="newMuscleGroup" type="text" className="form-control"/>
                                                <ErrorMessage name="newMuscleGroup" component="div" className="text-danger"/>
                                            </div>
                                        )}
                                        <div className="mb-3">
                                            <label htmlFor="category" className="form-label fw-semibold">
                                                {t("exerciseLibrary:category")}
                                            </label>
                                            <Field as="select" name="category" className="form-control form-select">
                                                <option value="">{t("exerciseLibrary:selectCategory")}</option>
                                                <option value="create">{t("exerciseLibrary:createNewCategory")}</option>
                                                {categories?.map((cat) => (
                                                    <option key={cat.id} value={cat.id}>
                                                        {
                                                            cat.userId > 0 ? cat.name :
                                                                t(`exerciseLibrary:${cat.name}`)
                                                        }
                                                    </option>
                                                ))}
                                            </Field>
                                            <ErrorMessage name="category" component="div" className="text-danger"/>
                                        </div>
                                        {values.category === "create" && (
                                            <div className="mb-3">
                                                <label htmlFor="newCategory" className="form-label fw-semibold">
                                                    {t("exerciseLibrary:newCategory")}
                                                </label>
                                                <Field name="newCategory" type="text" className="form-control"/>
                                                <ErrorMessage name="newCategory" component="div" className="text-danger"/>
                                            </div>
                                        )}
                                        <div className="mb-3">
                                            <label className="form-label d-block fw-semibold">{t("exerciseLibrary:addToFavorites")}</label>
                                            <div className="form-check form-check-inline">
                                                <Field
                                                    type="radio"
                                                    name="addToFavorites"
                                                    value="true"
                                                    className="form-check-input"
                                                    id="favSim"
                                                />
                                                <label htmlFor="favSim" className="form-check-label">
                                                    {t("exerciseLibrary:yes")}
                                                </label>
                                            </div>
                                            <div className="form-check form-check-inline">
                                                <Field
                                                    type="radio"
                                                    name="addToFavorites"
                                                    value="false"
                                                    className="form-check-input"
                                                    id="favNao"
                                                />
                                                <label htmlFor="favNao" className="form-check-label">
                                                    {t("exerciseLibrary:no")}
                                                </label>
                                            </div>
                                            <ErrorMessage name="addToFavorites" component="div" className="text-danger"/>
                                        </div>
                                        {isUploading && (
                                            <div className="mb-3">
                                                <label className="form-label">
                                                    {t("exerciseLibrary:uploading")} {uploadProgress}%
                                                </label>
                                                <div className="progress">
                                                    <div
                                                        className="progress-bar"
                                                        role="progressbar"
                                                        style={{width: `${uploadProgress}%`}}
                                                        aria-valuenow={uploadProgress}
                                                        aria-valuemin="0"
                                                        aria-valuemax="100"
                                                    />
                                                </div>
                                            </div>
                                        )}
                                        <div className="d-grid">
                                            <button type="submit" className="btn btn-primary" disabled={isUploading || loading}>
                                                {t("exerciseLibrary:save")}
                                            </button>
                                        </div>
                                    </div>
                                </Form>
                            )}
                        </Formik>
                    </div>
                </div>
            </div>
        </Page>
    );
};

export default ExerciseEdit;
