import {createSelector} from "reselect";


const reducer = state => state.aiActions

export const getSummarizedAnamnesis = createSelector(reducer, state => state.summarizedAnamnesis)
export const getWaiting = createSelector(reducer, state => state.waiting)
export const getAiPush = createSelector(reducer, state => state.aiPush)
export const getGeneratedWorkout = createSelector(reducer, state => state.generatedWorkout)
export const getAiEvaluationAnalysis = createSelector(reducer, state => state.evaluationAnalysis)
export const getAiError = createSelector(reducer, state => state.aiError)