import RoundedIcon from "../rounded-icon/RoundedIcon";
import moment from "moment";
import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import {useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const SubscriptionCard = ({isLimited, automatic, paymentType}) => {
    const {t} = useTranslation();
    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const user = useSelector(selectUser)

    return (
        <div className={"row justify-content-center mt-3"}>
            <div className={"col-12 text-center"}>
                {!isLimited ?
                    <RoundedIcon icon={"fa-infinity"} size={"lg"}/> :
                    <RoundedIcon icon={"fa-users"} size={"lg"}/>
                }
            </div>
            <div className={"col-12 text-center mt-3"}>
                <span className={"d-block fw-bold fs-5"}>{isLimited ? t('subscriptionComponent:subscriptionCard.limitedClients', {count: 3}) : t('subscriptionComponent:subscriptionCard.unlimitedClients')}</span>
            </div>
            <div className={"col-12 mt-3"}>
                <div className={"row justify-content-between"}>
                    <div className={"col-6"}>
                        <span className={"fw-semibold"}>{t('subscriptionComponent:subscriptionCard.paymentMethod')}</span>
                    </div>
                    <div className={"col-6 text-end"}>
                        {
                            paymentType === "credit" &&
                            <span className={"fw-semibold text-primary"}><i className={"fa-regular fa-credit-card"}></i> {t('subscriptionComponent:subscriptionCard.creditCard')}</span>
                        }
                        {
                            paymentType === "boleto" &&
                            <span className={"fw-semibold text-primary"}><i className={"fa-regular fa-barcode"}></i> {t('subscriptionComponent:subscriptionCard.boleto')}</span>
                        }
                        {
                            paymentType === "pix" &&
                            <span className={"fw-semibold text-primary"}><i className={"fa-brands fa-pix text-success"}></i> {t('subscriptionComponent:subscriptionCard.pix')}</span>
                        }
                        {
                            paymentType === "wallet" &&
                            <span className={"fw-semibold text-primary"}><i className={"fa-regular fa-wallet"}></i> {t('subscriptionComponent:subscriptionCard.wallet')}</span>
                        }
                    </div>
                </div>
                {
                    user.sub.status === 0 &&
                    <div className={"row justify-content-between mt-2"}>
                        <div className={"col-6"}>
                            <span className={"fw-semibold"}>{t('subscriptionComponent:subscriptionCard.nextPayment')}</span>
                        </div>
                        <div className={"col-6 text-end"}>
                            {moment.utc(user.sub.nextInvoice).format("L")}
                        </div>
                    </div>
                }
                <div className={"row justify-content-between mt-2"}>
                    <div className={"col-6"}>
                        <span className={"fw-semibold"}>{t('subscriptionComponent:subscriptionCard.renewal')}</span>
                    </div>
                    <div className={"col-6 text-end"}>
                        {automatic ? t('subscriptionComponent:subscriptionCard.automatic') : t('subscriptionComponent:subscriptionCard.manual')}
                    </div>
                </div>
                <div className={"row justify-content-between mt-2"}>
                    <div className={"col-6"}>
                        <span className={"fw-semibold"}>{t('subscriptionComponent:subscriptionCard.amount')}</span>
                    </div>
                    <div className={"col-6 text-end"}>
                        <span className={"fw-semibold"}><CurrencyFormatter value={user.subPlan.amount-user.subPlan.discount}/></span>
                    </div>
                </div>
            </div>
        </div>
    )
}
export default SubscriptionCard;