import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import React, {useCallback} from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../bioimpedance-evaluation/locales/en-us.json";
import ptBR from "../bioimpedance-evaluation/locales/pt-br.json";
import esES from "../bioimpedance-evaluation/locales/es-es.json";
import ptPT from "../bioimpedance-evaluation/locales/pt-pt.json";

const BioimpedanceCard = ({
                              bioimpedance,
                              isComparing,
                              isSelected,
                              onToggle,
                              onCompare,
                              onCardClick
                          }) => {
    const {t} = useTranslation();
    syncMomentLocale(i18n.language);
    useComponentTranslations('bioimpedanceEvaluationComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT})

    const handleCompare = useCallback(
        e => {
            e.stopPropagation();
            onCompare(bioimpedance.id);
        },
        [onCompare, bioimpedance.id]
    );

    const handleRowClick = useCallback(() => {
            if (isComparing) {
                onToggle(bioimpedance.id);
            } else {
                onCardClick(bioimpedance);
            }
        },
        [isComparing, onToggle, onCardClick, bioimpedance]
    );
    return (
        <div className={"row pb-2"}>
            <div className={"card"}>
                <div className={`row d-flex align-items-center py-3 ${!isComparing ? 'clickable-element' : ''}`}
                     onClick={handleRowClick}
                >
                    <div className={"col-10 lh-1 pb-1 align-items-center"}>
                        <span className={"fw-semibold d-block"}>{t("bioimpedanceEvaluationComponent:bioimpedanceTitle")}</span>
                        <span className={"text-md fw-semibold me-1"}>{t("bioimpedanceEvaluationComponent:created")}</span>
                        <span className={"text-md"}>{moment(bioimpedance.data).format('L')}</span>
                    </div>
                    <div className={"col-2 d-flex justify-content-end align-items-center"}>
                        {isComparing ? (
                            bioimpedance.data ? (
                                <input
                                    type={"checkbox"}
                                    className={"form-check-input"}
                                    checked={isSelected}
                                    onChange={() => {}}
                                />
                            ) : (
                                <i className={"fa-regular fa-chevron-right"}/>
                            )
                        ) : (
                            <i className={"fa-regular fa-chevron-right"}/>
                        )}
                    </div>
                </div>
                <hr className={"text-secondary my-n1"}/>
                <div className={"col-12 clickable-element"} onClick={handleCompare}>
                    <button className={"btn btn-link text-md ps-0 fw-semibold my-n1"}>
                        {t("bioimpedanceEvaluationComponent:compare")}
                    </button>
                </div>
            </div>
        </div>
    )
}

export default BioimpedanceCard;