export const getImage = (obj, gender) => {
    switch (obj) {
        case 1:
            return `fa-hipertrofia-${gender}`;
        case 2:
            return `fa-reducao-${gender}`;
        case 3:
            return `fa-reducao-hipertrofia-${gender}`;
        case 4:
            return `fa-definicao-${gender}`;
        case 5:
            return `fa-condicionamento-${gender}`;
        case 6:
            return `fa-qualidade-${gender}`;
        case 7:
            return `fa-definicao-${gender}`;
        default:
            return `fa-qualidade-${gender}`;
    }
}
export const getWeekSessionName = (type) => {
    switch (type) {
        case 1:
            return "sunday";
        case 2:
            return "monday";
        case 3:
            return "tuesday";
        case 4:
            return "wednesday";
        case 5:
            return "thursday";
        case 6:
            return "friday";
        case 7:
            return "saturday";
        default:
            return "";
    }
}
