export const getDifficulty = (dif) => {
    switch (dif) {
        case 1:
            return "starter";
        case 2:
            return "intermediate";
        case 3:
            return "advanced";
        case 4:
            return "adaptation";
        default:
            return "adaptation";
    }
}

