export const formatElapsedTime = (totalSeconds) => {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds.toString()}s`;
};
export const getExerciseName = (exercise, i18n) => {
    if (exercise.idUser === 0) {
        switch (i18n.language) {
            case 'pt_PT':
            case 'pt-PT':
            case 'pt-BR':
            case 'pt_BR':
                return exercise.name;
            case "en-US":
            case  "en_US":
                return exercise.name_en_US;
            case "es-ES":
            case "es_ES":
                return exercise.name_es_ES;
            default:
                return exercise.name;
        }
    } else {
        return exercise.name;
    }
}