import React from "react";
import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import {useNavigate, useParams, useSearchParams} from "react-router-dom";
import {Trans, useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionPlanCard = ({subPlan, disableClick}) => {
    const {couponName} = useParams();
    const {t} = useTranslation();
    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();

    const goBackTo = searchParams.get("goBackTo");
    const handleGoToPurchasePage = () => {
        if (!disableClick)
            navigate(`/subscription/purchase/${subPlan.id}${couponName ? `/coupon/${couponName}` : ''}${goBackTo ? `?goBackTo=${goBackTo}` : ""}`)
    }

    return (
        <div className="card card-body border-secondary-subtle pb-1 clickable-element" onClick={handleGoToPurchasePage}>
            {
                subPlan.month > 3 ?
                    <div className={"row justify-content-between"}>
                        <div className={"col-auto"}>
                            <span className={"badge bg-primary-subtle text-primary fw-semibold rounded-4"}>
                                {t('subscriptionComponent:subscriptionPlanCard.discountBadge', {
                                    discount: subPlan.month === 6 ? 10 : 15
                                })}
                            </span>
                        </div>
                        <div className={"col-auto"}>
                            {
                                subPlan.month > 3 &&
                                <span className={"d-block small   text-decoration-line-through fw-light text-secondary "}><CurrencyFormatter
                                    value={subPlan.amount}/></span>
                            }
                        </div>
                    </div> :
                    <div className={"row"}>
                        <div className={"col-12 m-2"}></div>
                    </div>
            }
            <div className="row justify-content-between   ">
                <div className="col-auto align-self-center mt-2">
                    <span className="fw-semibold fs-5 ">{t('subscriptionComponent:subscriptionPlanCard.months', {count: subPlan.month})}</span>
                </div>
                <div className="col-auto text-end  align-self-center ">

                    <span className={"d-block lh-1 fw-semibold"}>
                        <span className={" fs-4"}>
                            <CurrencyFormatter value={subPlan.amount - subPlan.discount}/>
                        </span>
                    </span>
                    {
                        subPlan.month === 1 &&
                        <span className={"d-block small fw-light text-secondary "}>{t('subscriptionComponent:subscriptionPlanCard.perMonth')}</span>
                    }
                    {
                        subPlan.month === 3 &&
                        <span className={"d-block small  fw-light text-secondary "}>
                            <Trans
                                i18nKey={'subscriptionComponent:subscriptionPlanCard.installments'}
                                components={{amount: <CurrencyFormatter value={subPlan.amount / subPlan.month}/>}}
                            />
                        </span>
                    }
                    {
                        subPlan.month > 3 &&
                        <span className={"d-block small   fw-light text-secondary "}>{t('subscriptionComponent:subscriptionPlanCard.payInFull')}</span>
                    }
                </div>
                <hr className="border-secondary mt-2 mb-1"/>
                <div className="col-12 text-center small">
                    <span>
                        <Trans
                            i18nKey={'subscriptionComponent:subscriptionPlanCard.summary'}
                            count={subPlan.month}
                            values={{count: subPlan.month}}
                            components={{duration: <span className="fw-semibold"/>, clients: <span className="fw-semibold"/>}}
                        />
                    </span>
                </div>
            </div>
        </div>
    )
}

export default SubscriptionPlanCard;
