import React, {useState} from 'react';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useDispatch, useSelector} from "react-redux";
import {deleteDay, updateAerobicDay} from "../../store/workout-aerobic/workoutAerobicReducer";
import Modal from "react-bootstrap/Modal";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import TextareaAutosize from "react-textarea-autosize";
import moment from "moment";
import {resolveMomentLocale, syncMomentLocale} from "../../utils/translation/localeUtils";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from "he";
import WorkoutFeedbackCard from "../workout/WorkoutFeedbackCard";
import {selectUpdatingDay} from "../../store/workout-aerobic/workoutAerobicSelector";

const WorkoutAerobicDay = ({runningDay}) => {
    const {i18n, t} = useTranslation();
    const locale = resolveMomentLocale(i18n.language);
    const dispatch = useDispatch();
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const isDate = runningDay.diaNumero === 0;
    const count = runningDay?.feedbacks?.length || 0;
    const [showFeedbackModal, setShowFeedbackModal] = useState(false)
    const updatingDayId = useSelector(selectUpdatingDay)
    const dayUpdating = updatingDayId === runningDay.id
    syncMomentLocale(i18n.language);
    useComponentTranslations('aerobicWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleFeedbackClick = () => {
        setShowFeedbackModal(prevState => !prevState)
    }

    const initialValues = {
        id: runningDay.id || '',
        runningId: runningDay.idCorrida || '',
        instructions: he.decode(runningDay.descricao || ''),
        dayOff: false
    };

    const validationSchema = Yup.object({
        instructions: Yup.string().required(t("aerobicWorkoutComponent:required")),
    });

    const handleDeleteModal = () => {
        setShowDeleteModal(prev => !prev);
    };

    const handleDeleteDay = () => {
        dispatch(deleteDay({id: runningDay.id, runningId: runningDay.idCorrida}));
        handleDeleteModal();
    };

    return (
        <div className={'card card-body border-0'}>
            <div className={"row justify-content-between"}>
                <div className={"col-auto"}>
                    {!isDate ? (
                        <span className={"fw-semibold"}>{t("aerobicWorkoutComponent:workout")} {runningDay.diaNumero}</span>
                    ) : (
                        <>
                            <span className={"fw-semibold text-capitalize d-block"}>{moment(runningDay.dia).format("dddd")}</span>
                            <span className={'d-block'}>
                                <span
                                    className={"fw-semibold"}>{t("aerobicWorkoutComponent:date")}:</span> {moment(runningDay.dia).format(locale === "en" ? "MM/DD" : "DD/MM")}
                            </span>
                        </>
                    )}
                </div>
                <div className={"col-auto"}>
                    {runningDay.executado && !runningDay.dayoff && (
                        <span className={"badge bg-success"}>{t("aerobicWorkoutComponent:finalized")}</span>
                    )}
                </div>
            </div>
            {
                count > 0 ?
                    <div className={"row "}>
                        <div className={"col-12 clickable-element"} onClick={handleFeedbackClick}>
                            <span className={"fw-semibold   small "}>Execuções: </span> <span className={"fw-semibold small text-primary"}>{count}</span>
                        </div>
                        <Modal show={showFeedbackModal} centered onHide={handleFeedbackClick}>
                            <Modal.Body>
                                <div className={"row"}>
                                    <div className={"col-12"}>
                                        <span className={"fw-semibold fs-5"}>{t("aerobicWorkoutComponent:feedbacks")}</span>
                                    </div>
                                    <div className={"col-12 mt-3 "}>
                                        <div className={"card card-body border-0"}>
                                            {
                                                runningDay?.feedbacks?.map((feedback, idx, arr) => (
                                                    <WorkoutFeedbackCard feedback={feedback} key={feedback.id} isLast={idx === arr.length - 1}/>
                                                ))
                                            }
                                        </div>
                                    </div>
                                </div>
                            </Modal.Body>
                        </Modal>
                    </div> :
                    <span className={" small text-primary"}>{t("aerobicWorkoutComponent:notExecuted")}</span>
            }
            <div className={"row justify-content-center"}>
                <div className={"col-12 mt-2"}>
                    <Formik
                        initialValues={initialValues}
                        validationSchema={validationSchema}
                        onSubmit={values => dispatch(updateAerobicDay(values))}
                    >
                        {({errors, touched, setFieldValue}) => (
                            <Form>
                                <div className="form-group">
                                    <Field name="instructions">
                                        {({field}) => (
                                            <TextareaAutosize
                                                {...field}
                                                minRows={4}
                                                style={{
                                                    transition: "height 0.2s ease",
                                                    overflow: "hidden",
                                                }}
                                                className={
                                                    "form-control " +
                                                    (errors.instructions && touched.instructions
                                                        ? "is-invalid"
                                                        : "")
                                                }
                                            />
                                        )}
                                    </Field>
                                    <ErrorMessage
                                        name="instructions"
                                        component="div"
                                        className="text-danger"
                                    />
                                </div>
                                <div className={"row justify-content-between mt-3"}>
                                    <div className={`${isDate ? "col-4" : "col-8"} pe-0`}>
                                        <button type="submit" className="btn btn-primary w-100"
                                                id="submitButton"
                                                disabled={dayUpdating}>
                                            {
                                                dayUpdating ?
                                                    <span><i className={"fa-regular fa-spin fa-spinner"}></i> {t("aerobicWorkoutComponent:wait")}</span> :
                                                    t("aerobicWorkoutComponent:save")
                                            }

                                        </button>
                                    </div>
                                    {isDate && (
                                        <div className="col-4 pe-0">
                                            <button
                                                type="button"
                                                className="btn btn-outline-primary w-100"
                                                onClick={() => {
                                                    setFieldValue('instructions', 'Day Off');
                                                    dispatch(updateAerobicDay({
                                                        id: runningDay.id,
                                                        runningId: runningDay.idCorrida,
                                                        dayOff: true,
                                                        instructions: `${t("aerobicWorkoutComponent:dayOff")}`
                                                    }));
                                                }}
                                                disabled={dayUpdating}
                                            >
                                                {
                                                    dayUpdating ?
                                                        <span>{t("aerobicWorkoutComponent:wait")}</span> :
                                                        t("aerobicWorkoutComponent:dayOff")
                                                }
                                            </button>
                                        </div>
                                    )}
                                    <div className={"col-4"}>
                                        <button
                                            type="button"
                                            className="btn btn-outline-danger w-100"
                                            onClick={handleDeleteModal}
                                        >
                                            <i className={"fa-regular fa-trash-can"}></i>
                                        </button>
                                    </div>
                                </div>
                            </Form>
                        )}
                    </Formik>
                </div>
                <Modal show={showDeleteModal} centered onHide={handleDeleteModal}>
                    <Modal.Body>
                        <ChangeStatus
                            icon={"fa-regular fa-circle-exclamation"}
                            iconColor={"text-danger"}
                            title={t("aerobicWorkoutComponent:areYouSure")}
                            subtitle={t("aerobicWorkoutComponent:actionCantBeUndone")}
                        />
                        <div className="row mt-3 justify-content-center">
                            <div className="col-12">
                                <div className="d-grid">
                                    <button className="btn btn-danger" onClick={handleDeleteDay}>{t("aerobicWorkoutComponent:delete")}</button>
                                </div>
                                <div className="d-grid mt-2">
                                    <button className="btn btn-outline-danger" onClick={handleDeleteModal}>{t("aerobicWorkoutComponent:close")}</button>
                                </div>
                            </div>
                        </div>
                    </Modal.Body>
                </Modal>
            </div>
        </div>
    );
};

export default WorkoutAerobicDay;
