import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchExerciseFavoritesAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/exercise-library/favorites`,
        {
            headers: {
                'Content-Type': 'application/json',
                'Authorization': token
            },
            timeout: 20000
        }
    )
};

