import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Page from "../../components/page/Page";
import {isAnamnesisLoading, selectAnamnesis} from "../../store/anamnesis/anamnesisSelector";
import {useEffect} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {clearAnamnesis, getAnamnesisModel} from "../../store/anamnesis/anamnesisReducer";
import {useTranslation} from "react-i18next";
import {getTranslatedQuestion} from "../../utils/anamnesis/questionUtils";
import {buildAnamnesisNewRoute} from "../../utils/client/evaluationRoutes";

const AnamnesisViewModel = () => {
    const {t, i18n} = useTranslation()
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {clientId, modelId} = useParams();
    const anamnesisData = useSelector(selectAnamnesis);
    const loading = useSelector(isAnamnesisLoading);
    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate(buildAnamnesisNewRoute(clientId))
    };

    useEffect(() => {
        if (modelId) {
            dispatch(clearAnamnesis());
            dispatch(getAnamnesisModel(modelId));
        }
        dispatch(fetchClient(clientId));
        return () => {
            dispatch(clearAnamnesis());
        }
    }, [dispatch, modelId, clientId]);


    return (
        <Page
            title={anamnesisData?.name === "Padrão" || anamnesisData?.name === "PAR-Q" ? t(`anamnesisComponent:${anamnesisData?.name}`) : anamnesisData?.name}
            loading={loading}
            goBackLink={handleGoBack}
        >
            <div className="row justify-content-center d-flex mt-n4">
                <div className="col-12">
                    <div className="card card-body border-0">
                        <ol className="pt-2">
                            {anamnesisData?.questions?.map((question) => (
                                <li key={question.id} className="px-2 pt-2 pb-2 mb-2">
                                    <span>{getTranslatedQuestion(question, i18n.language)}</span>
                                </li>
                            ))}
                        </ol>
                    </div>
                </div>
            </div>
        </Page>
    )
}

export default AnamnesisViewModel;
