import {useCallback} from "react";
import {useDispatch, useStore} from "react-redux";
import {baseApi} from "../api/baseApi";
import {dispatchApiErrorToast} from "../../utils/error/apiErrorToast";
import {
    RETENTION_CHART_TTL_SECONDS,
    RETENTION_CLIENTS_TTL_SECONDS,
    RETENTION_SUMMARY_TTL_SECONDS,
    normalizeRetentionChartFilters,
    normalizeRetentionClientFilters,
    normalizeRetentionSummaryPeriod
} from "./retentionFilters";

const buildQueryOptions = (ttlSeconds, options = {}) => ({
    refetchOnMountOrArgChange: ttlSeconds,
    ...options
});

const normalizeRetentionClientStatus = (status) => normalizeRetentionClientFilters({status}).status;

const buildPagination = (responseData = {}, normalizedFilters) => ({
    page: responseData.page ?? normalizedFilters.page,
    pageSize: responseData.pageSize ?? normalizedFilters.pageSize,
    totalItems: responseData.totalItems ?? 0,
    totalPages: responseData.totalPages ?? 0,
    statusCounts: responseData.statusCounts || {}
});

const toastOnQueryError = async (dispatch, queryFulfilled) => {
    try {
        await queryFulfilled;
    } catch ({error}) {
        dispatchApiErrorToast(dispatch, error);
    }
};

export const retentionApi = baseApi.injectEndpoints({
    endpoints: (build) => ({
        getRetentionSummary: build.query({
            query: (period) => ({
                url: "/user/retention/summary",
                params: {
                    period: normalizeRetentionSummaryPeriod(period)
                }
            }),
            serializeQueryArgs: ({queryArgs}) => normalizeRetentionSummaryPeriod(queryArgs),
            keepUnusedDataFor: RETENTION_SUMMARY_TTL_SECONDS,
            onQueryStarted(_, {dispatch, queryFulfilled}) {
                return toastOnQueryError(dispatch, queryFulfilled);
            }
        }),
        getRetentionChart: build.query({
            query: (filters) => {
                const normalizedFilters = normalizeRetentionChartFilters(filters);

                return {
                    url: "/user/retention/chart",
                    params: normalizedFilters
                };
            },
            serializeQueryArgs: ({queryArgs}) => normalizeRetentionChartFilters(queryArgs),
            keepUnusedDataFor: RETENTION_CHART_TTL_SECONDS,
            onQueryStarted(_, {dispatch, queryFulfilled}) {
                return toastOnQueryError(dispatch, queryFulfilled);
            }
        }),
        getRetentionClients: build.query({
            query: (filters) => {
                const normalizedFilters = normalizeRetentionClientFilters(filters);

                return {
                    url: "/user/retention/clients",
                    params: normalizedFilters
                };
            },
            serializeQueryArgs: ({queryArgs}) => normalizeRetentionClientFilters(queryArgs),
            transformResponse: (responseData, _, queryArg) => {
                const normalizedFilters = normalizeRetentionClientFilters(queryArg);

                return {
                    clients: responseData?.clients || [],
                    pagination: buildPagination(responseData, normalizedFilters)
                };
            },
            keepUnusedDataFor: RETENTION_CLIENTS_TTL_SECONDS,
            onQueryStarted(_, {dispatch, queryFulfilled}) {
                return toastOnQueryError(dispatch, queryFulfilled);
            }
        }),
        getRetentionClientIds: build.query({
            query: (status) => ({
                url: "/user/retention/client-ids",
                params: {
                    status: normalizeRetentionClientStatus(status)
                }
            }),
            serializeQueryArgs: ({queryArgs}) => normalizeRetentionClientStatus(queryArgs),
            transformResponse: (responseData) => responseData?.clientIds || [],
            keepUnusedDataFor: RETENTION_CLIENTS_TTL_SECONDS,
            onQueryStarted(_, {dispatch, queryFulfilled}) {
                return toastOnQueryError(dispatch, queryFulfilled);
            }
        }),
        createRetentionNotificationLog: build.mutation({
            query: (payload) => ({
                url: "/user/retention/actions/notify",
                method: "post",
                data: payload
            })
        }),
        registerRetentionAccess: build.mutation({
            query: () => ({
                url: "/user/retention/actions/access",
                method: "post"
            })
        }),
        logRetentionClientAction: build.mutation({
            query: (payload) => ({
                url: "/user/retention/actions/log",
                method: "post",
                data: payload
            }),
            onQueryStarted(_, {dispatch, queryFulfilled}) {
                return toastOnQueryError(dispatch, queryFulfilled);
            }
        })
    })
});

const {
    useGetRetentionSummaryQuery,
    useGetRetentionChartQuery,
    useGetRetentionClientsQuery,
    useCreateRetentionNotificationLogMutation,
    useRegisterRetentionAccessMutation,
    useLogRetentionClientActionMutation
} = retentionApi;

export const useRetentionSummaryQuery = (period, options = {}) => (
    useGetRetentionSummaryQuery(
        normalizeRetentionSummaryPeriod(period),
        buildQueryOptions(RETENTION_SUMMARY_TTL_SECONDS, options)
    )
);

export const useRetentionChartQuery = (filters, options = {}) => (
    useGetRetentionChartQuery(
        normalizeRetentionChartFilters(filters),
        buildQueryOptions(RETENTION_CHART_TTL_SECONDS, options)
    )
);

export const useRetentionClientsQuery = (filters, options = {}) => (
    useGetRetentionClientsQuery(
        normalizeRetentionClientFilters(filters),
        buildQueryOptions(RETENTION_CLIENTS_TTL_SECONDS, options)
    )
);

export const useResolveRetentionClientIds = () => {
    const dispatch = useDispatch();
    const store = useStore();

    return useCallback(async (status) => {
        const normalizedStatus = normalizeRetentionClientStatus(status);
        const queryState = retentionApi.endpoints.getRetentionClientIds.select(normalizedStatus)(store.getState());
        const fulfilledTimeStamp = queryState?.fulfilledTimeStamp;
        const isFresh = Boolean(fulfilledTimeStamp)
            && ((Date.now() - fulfilledTimeStamp) / 1000) < RETENTION_CLIENTS_TTL_SECONDS;

        if (isFresh && Array.isArray(queryState?.data)) {
            return queryState.data;
        }

        const request = dispatch(retentionApi.endpoints.getRetentionClientIds.initiate(normalizedStatus, {
            forceRefetch: !isFresh
        }));

        try {
            return await request.unwrap();
        } finally {
            request.unsubscribe();
        }
    }, [dispatch, store]);
};

export {
    useCreateRetentionNotificationLogMutation,
    useRegisterRetentionAccessMutation,
    useLogRetentionClientActionMutation
};
