import {useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {handleSubscriptionButton} from "../../utils/handlers/handler";
import {useNavigate} from "react-router-dom";
import RoundedIcon from "../rounded-icon/RoundedIcon";

const LimitExceededWarning = ({total, handleClientDeleteClick}) => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const user = useSelector(selectUser);
    useComponentTranslations('exceededLimitComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const planLimit = Number(user?.plano ?? 0);

    return (

        <div className={'row justify-content-center'}>
            <div className={'col-6 text-center'}>
                <RoundedIcon icon={"fa-users-rays"} size={"lg"}/>
            </div>
            <div className={'col-12 text-center mt-2 pb-3'}>
                <span className={'fs-4 fw-bold'}>{t("exceededLimitComponent:itIsTimeToUpgrade")}</span>
            </div>
            <div className={'col-12 text-center  '}>
                <span>{t("exceededLimitComponent:yourSubAllows")} <strong>{user?.plano}</strong> {t("exceededLimitComponent:butYouHave", {count: planLimit})}
                    <strong> {total}</strong>
                </span>
            </div>
            <div className={'col-12 text-center pt-3'}>
                <div className={'d-grid'}>
                    <button className={'btn btn-primary-lighter'} onClick={() => handleSubscriptionButton(navigate, 1)}>{t("exceededLimitComponent:chooseSub")}
                    </button>
                </div>
                <div className={'d-grid mt-2'}>
                    <button className={"btn btn-outline-primary-lighter"} onClick={handleClientDeleteClick}>
                        {t("exceededLimitComponent:deleteClients")}
                    </button>
                </div>
            </div>
        </div>

    )
}
export default LimitExceededWarning;
