import {createSlice} from "@reduxjs/toolkit";


const initialState = {
    workouts: null,
    workout: null,
    feedbacks:null,
    workoutProgress: null,
    changingStatus: false,
    routineCreated: false,
    routineDeleted: false,
    routineUpdated: false,
    sessionCreating: false,
    sessionCreated: false,
    sessionUpdating: false,
    sessionUpdated: false,
    sessionCloned: false,
    loading: null,
};

export const slice = createSlice({
    name: "routine",
    initialState,
    reducers: {
        cloneSessionsToRoutine(state) {
            state.loading = true
        },
        cloneSessionsToRoutineSuccess(state, action) {
            state.loading = false
            state.sessionCloned = action.payload
        },
        fetchRoutinesToCloneSessions(state) {
            state.loading = true
        },
        changeWorkoutSessionOrder() {
        },
        setWorkoutSessionOrder(state, action) {
            state.workout.sessions = action.payload
        },
        createSession(state) {
            state.sessionCreating = true
        },
        sessionCreated(state, action) {
            state.sessionCreating = false
            state.sessionCreated = true
            state.workout.sessions = action.payload
        },
        setSessionCreated(state, action) {
            state.sessionCreated = action.payload
        },
        updateSession(state) {
            state.sessionUpdating = true
        },
        sessionUpdated(state, action) {
            state.sessionUpdating = false;
            state.sessionUpdated = true;
            const updatedSession = action.payload;
            if (state.workout && state.workout.sessions) {
                const index = state.workout.sessions.findIndex(session => session.id === updatedSession.id);
                if (index !== -1) {
                    state.workout.sessions[index] = updatedSession;
                }
            }
        },
        setSessionUpdated(state, action) {
            state.sessionUpdated = action.payload
        },
        deleteSession(state, action) {
            state.workout.sessions = state.workout.sessions.filter(session => session.id !== action.payload)
        },
        updateRoutine(state) {
            state.loading = true
        },
        updateRoutineSuccess(state, action) {
            state.loading = false
            state.routineUpdated = action.payload
        },
        fetchWorkoutRoutine(state) {
            state.loading = true;
        },
        createWorkoutRoutine(state) {
            state.loading = true
        },
        setWorkout(state, action) {
            state.loading = false
            state.workout = action.payload
        },
        setWorkoutCreated(state, action) {
            state.routineCreated = action.payload
        },
        fetchWorkoutRoutinesByStatus(state) {
            state.loading = true
        },
        setWorkouts(state, action) {
            state.loading = false
            state.workouts = action.payload
        },
        changeWorkoutRoutineStatus(state) {
            state.changingStatus = true;
        },
        changeWorkoutRoutineStatusSuccess(state, action) {
            state.changingStatus = false;
            state.routineDeleted = true;
            state.workouts = state.workouts.filter(workout => workout.id !== action.payload)
        },
        changeRoutineDeletedStatus(state, action) {
            state.routineDeleted = action.payload;
        },
        fetchFeedbacks(state){
            state.loading = true
        },
        setFeedbacks(state, action){
            state.loading = false
            state.feedbacks = action.payload
        },
        fetchWorkoutProgress(state){
            state.loading = true
        },
        setWorkoutProgress(state, action){
            state.loading = false
            state.workoutProgress = action.payload
        },
        onError(state) {
            state.loading = false
        }
    }
})

export const {
    fetchWorkoutRoutinesByStatus,
    setWorkouts,
    changeWorkoutRoutineStatus,
    changeWorkoutRoutineStatusSuccess,
    createWorkoutRoutine,
    setWorkout,
    fetchWorkoutRoutine,
    changeRoutineDeletedStatus,
    updateRoutine,
    updateRoutineSuccess,
    createSession,
    sessionCreated,
    setSessionCreated,
    updateSession,
    sessionUpdated,
    deleteSession,
    setSessionUpdated,
    changeWorkoutSessionOrder,
    setWorkoutSessionOrder,
    fetchRoutinesToCloneSessions,
    cloneSessionsToRoutine,
    cloneSessionsToRoutineSuccess,
    setWorkoutCreated,
    fetchFeedbacks,
    setFeedbacks,
    fetchWorkoutProgress,
    setWorkoutProgress,
    onError
} = slice.actions
export const workoutRoutineReducer = slice.reducer
