import {takeLatest, all, call, put} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {deleteFileAPI, editFileNameAPI, getAllFilesAPI, getOneFileAPI, saveFileAPI} from "../../api/files/filesActions";
import {
    fetchAllFiles,
    setAllFiles,
    onError,
    setOneFile,
    fetchOneFile,
    addFile,
    fileAdded,
    fileEdited, editFile, fileDeleted, deleteFile
} from "./filesReducer";

export function* fetchAllFilesAsync(action) {
    const clientId = action.payload
    try {
        const response = yield call(getAllFilesAPI, clientId)
        yield put(setAllFiles(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}
export function* onFetchAllFiles() {
    yield takeLatest(fetchAllFiles.type,fetchAllFilesAsync)
}

export function* fetchOneFileAsync(action) {
    try {
        const { id, fileId } = action.payload;
        const response = yield call(getOneFileAPI, id, fileId );
        yield put(setOneFile(response.data))
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchOneFile() {
    yield takeLatest(fetchOneFile.type, fetchOneFileAsync)
}

export function* saveFileAsync({payload}) {
    try{
        const response = yield call(saveFileAPI, payload);
        yield put(fileAdded(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onSaveFile() {
    yield takeLatest(addFile.type, saveFileAsync);
}

export function* editFileNameAsync(action) {
    try{
        const response = yield call(editFileNameAPI, action.payload)
        yield put(fileEdited(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onEditFileName() {
    yield takeLatest(editFile.type, editFileNameAsync);
}

export function* deleteFileAsync({ payload }) {
    try{
        const {fileId,id} = payload;
        yield call(deleteFileAPI, fileId,id);
        yield put(fileDeleted(payload))
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onDeleteFile() {
    yield takeLatest(deleteFile.type, deleteFileAsync);
}

export function* filesSaga() {
    yield all(
        [
            call(onFetchAllFiles),
            call(onFetchOneFile),
            call(onSaveFile),
            call(onEditFileName),
            call(onDeleteFile)
        ]
    )
}