import React, {useCallback, useEffect, useMemo, useState} from "react";
import {ErrorMessage, Field, Form, Formik} from "formik";
import Select from "react-select";
import {useDispatch, useSelector} from "react-redux";
import * as Yup from "yup";
import moment from "moment";
import {fetchSelectOptions} from "../../store/client/clientReducer";
import {selectSelectOptions} from "../../store/client/clientSelector";
import Modal from "react-bootstrap/Modal";
import InfoCard from "../info/InfoCard";
import {
    cloneRoutine,
    routineCloned,
    fetchFoldersList
} from "../../store/workout-library/workoutLibraryReducer";
import {
    selectLoadingCloneRoutine,
    selectRoutineCloned,
    selectFoldersList
} from "../../store/workout-library/workoutLibrarySelector";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from "he";
import {Dropdown} from "react-bootstrap";
import ClientRemoteMultiSelect from "../client/ClientRemoteMultiSelect";

const WorkoutAerobicClone = ({workout, type, clientId}) => {
    const {t} = useTranslation();
    const [show, setShow] = useState(false);
    const dispatch = useDispatch();
    const navigate = useNavigate();

    const loading = useSelector(selectLoadingCloneRoutine);
    const selectOptions = useSelector(selectSelectOptions);
    const folderList = useSelector(selectFoldersList);
    const isRoutineCloned = useSelector(selectRoutineCloned);

    const [uniqueClientId, setUniqueClientId] = useState(null);

    useComponentTranslations(
        "trainingCloneComponent",
        {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT}
    );

    const handleShow = useCallback(() => {
        setShow(s => !s);
    }, []);

    const shouldValidateDates = !!(workout.dataInicio && workout.dataFinal);
    let initialStart = null;
    let initialEnd = null;
    let originalDayOfWeek = null;
    let dayDifference = null;
    let dayName = "";

    if (shouldValidateDates) {
        originalDayOfWeek = moment(workout.dataInicio).day();
        dayName = moment().day(originalDayOfWeek).format("dddd");
        initialStart = moment().startOf("day");
        while (initialStart.day() !== originalDayOfWeek) {
            initialStart.add(1, "day");
        }
        dayDifference = moment(workout.dataFinal).diff(
            moment(workout.dataInicio),
            "days"
        );
        initialEnd = initialStart.clone().add(dayDifference, "days");
    }

    const validationSchema = Yup.object().shape({
        name: Yup.string()
            .required(t("trainingCloneComponent:fieldIsRequired"))
            .min(2, t("trainingCloneComponent:2chars"))
            .max(45, t("trainingCloneComponent:45chars")),
        sendTo: Yup.string().required(t("trainingCloneComponent:fieldIsRequired")),
        selectOption: Yup.array().when("sendTo", {
            is: val => val !== "library",
            then: schema =>
                schema.min(
                    1,
                    t("trainingCloneComponent:selectAtLeastOneOption")
                ),
            otherwise: schema => schema.notRequired(),
        }),
        folderId: Yup.string().when("sendTo", {
            is: "library",
            then: schema => schema.required(t("trainingCloneComponent:fieldIsRequired")),
            otherwise: schema => schema.notRequired(),
        }),
        startsAt: shouldValidateDates
            ? Yup.date()
                .typeError(t("trainingCloneComponent:invalidDate"))
                .min(
                    moment().startOf("day").toDate(),
                    t("trainingCloneComponent:dateCannotBeInThePast")
                )
                .required(t("trainingCloneComponent:fieldIsRequired"))
                .test(
                    "correct-day-of-week",
                    t("trainingCloneComponent:mustSelectADayName", {dayName}),
                    value => !!value && moment(value).day() === originalDayOfWeek
                )
            : Yup.mixed().notRequired(),
        endsAt: shouldValidateDates
            ? Yup.date()
                .typeError(t("trainingCloneComponent:invalidDate"))
                .required(t("trainingCloneComponent:fieldIsRequired"))
                .test(
                    "correct-gap",
                    t("trainingCloneComponent:endDateMustBeDaysAfterStart", {
                        dayDifference,
                    }),
                    function (value) {
                        const {startsAt} = this.parent;
                        return (
                            !!value &&
                            !!startsAt &&
                            moment(value).diff(moment(startsAt), "days") ===
                            dayDifference
                        );
                    }
                )
            : Yup.mixed().notRequired(),
    });

    const groupOptions = useMemo(
        () =>
            (selectOptions || []).map(item => ({
                value: item.id,
                label: item.label.includes("client_group")
                    ? t(`trainingCloneComponent:${item.label}`)
                    :  he.decode(item.label),
            })),
        [selectOptions, t]
    );

    const folderOptions = useMemo(
        () => [
            {value: "0", label: t(`trainingCloneComponent:noFolder`)},
            ...(folderList || []).map(f => ({
                value: f.id,
                label: he.decode(f.name),
            })),
        ],
        [folderList, t]
    );

    const loadGroupOptions = useCallback(
        sendToValue => {
            if (sendToValue === "groups") {
                dispatch(fetchSelectOptions("groups"));
            }
        },
        [dispatch]
    );

    const handleSubmitForm = values => {
        if (values.sendTo === "clients" && values.selectOption.length === 1) {
            setUniqueClientId(values.selectOption[0]);
        }
        dispatch(cloneRoutine(values));
    };

    useEffect(() => {
        if (isRoutineCloned) {
            dispatch(routineCloned(false));
            const path = clientId
                ? `/user/client/${clientId}/workout/cloned/${type}/to/${uniqueClientId}`
                : `/user/workout-library/cloned/${type}/to/${uniqueClientId ?? ""}`;
            navigate(path);
        }
    }, [isRoutineCloned, dispatch, navigate, type, uniqueClientId, clientId]);

    return (
        <>
            <Dropdown.Item onClick={handleShow}  >
                <i className="fa-regular fa-clone me-2"></i> {t("trainingCloneComponent:clone")}
            </Dropdown.Item>
            <Modal centered show={show} onHide={handleShow}>
                <Modal.Body>
                    <div className="row pb-2">
                        <div className="col-12">
                            <span className="fw-semibold fs-5">
                                {t("trainingCloneComponent:cloneRoutineForClientsOrGroups")}
                            </span>
                        </div>
                    </div>
                    <Formik
                        initialValues={{
                            workoutId: workout.id,
                            type,
                            name: he.decode(workout.nome),
                            sendTo: "",
                            selectOption: [],
                            folderId: 0,
                            ...(shouldValidateDates
                                ? {
                                    startsAt: initialStart.format("YYYY-MM-DD"),
                                    endsAt: initialEnd.format("YYYY-MM-DD"),
                                }
                                : {}),
                        }}
                        validationSchema={validationSchema}
                        onSubmit={handleSubmitForm}
                    >
                        {({setFieldValue, values, errors, touched}) => (
                            <Form>
                                <div className="form-group">
                                    <label className="fw-semibold">
                                        {t("trainingCloneComponent:cloneTo")}
                                    </label>
                                    <Field
                                        as="select"
                                        name="sendTo"
                                        className={`form-control ${
                                            touched.sendTo && errors.sendTo ? "is-invalid" : ""
                                        }`}
                                        onChange={e => {
                                            const v = e.target.value;
                                            setFieldValue("sendTo", v);
                                            setFieldValue("selectOption", []);
                                            if (v === "library") {
                                                dispatch(fetchFoldersList(type));
                                            } else {
                                                loadGroupOptions(v);
                                            }
                                        }}
                                    >
                                        <option value="">
                                            {t("trainingCloneComponent:select")}
                                        </option>
                                        <option value="clients">
                                            {t("trainingCloneComponent:specificStudents")}
                                        </option>
                                        <option value="groups">
                                            {t("trainingCloneComponent:specificGroups")}
                                        </option>
                                        <option value="library">
                                            {t("trainingCloneComponent:library")}
                                        </option>
                                    </Field>
                                    <ErrorMessage
                                        name="sendTo"
                                        component="div"
                                        className="invalid-feedback"
                                    />
                                </div>
                                {values.sendTo === "library" && (
                                    <div className="form-group mt-2">
                                        <label className="fw-semibold">
                                            {t("trainingCloneComponent:selectLibraryFolder")}
                                        </label>
                                        <Select
                                            name="folderId"
                                            options={folderOptions}
                                            placeholder={t("trainingCloneComponent:select")}
                                            isLoading={loading && !folderList}
                                            onChange={opt =>
                                                setFieldValue("folderId", opt?.value || "")
                                            }
                                            value={
                                                folderOptions.find(o => o.value === values.folderId) ||
                                                null
                                            }
                                        />
                                        {touched.folderId && errors.folderId && (
                                            <div className="invalid-feedback d-block">
                                                {errors.folderId}
                                            </div>
                                        )}
                                    </div>
                                )}
                                {values.sendTo && values.sendTo !== "library" && (
                                    <div className="form-group mt-2">
                                        <label className="fw-semibold">
                                            {values.sendTo === "clients"
                                                ? t("trainingCloneComponent:specificStudents")
                                                : t("trainingCloneComponent:specificGroups")}
                                        </label>
                                        {values.sendTo === "clients" ? (
                                            <ClientRemoteMultiSelect
                                                valueIds={values.selectOption}
                                                onChangeIds={(clientIds) => setFieldValue("selectOption", clientIds)}
                                                searchScope={"active"}
                                                resolveScope={"nonDeleted"}
                                                placeholder={t("trainingCloneComponent:select")}
                                                noOptionsMessage={() => t("trainingCloneComponent:noOptionsAvailable")}
                                                loadingMessage={() => t("trainingCloneComponent:loading")}
                                                disabled={loading}
                                            />
                                        ) : (
                                            <Select
                                                isMulti
                                                name="selectOption"
                                                options={groupOptions}
                                                className="basic-multi-select"
                                                classNamePrefix="select"
                                                placeholder={t("trainingCloneComponent:select")}
                                                noOptionsMessage={() =>
                                                    t("trainingCloneComponent:noOptionsAvailable")
                                                }
                                                onChange={opts =>
                                                    setFieldValue(
                                                        "selectOption",
                                                        opts?.map(o => o.value) || []
                                                    )
                                                }
                                                value={values.selectOption.map(val => {
                                                    const found = groupOptions.find(o => o.value === val);
                                                    return found || {value: val, label: ""};
                                                })}
                                            />
                                        )}
                                        {touched.selectOption && errors.selectOption && (
                                            <div className="invalid-feedback d-block">
                                                {errors.selectOption}
                                            </div>
                                        )}
                                        {values.sendTo === "groups" && loading && !selectOptions && (
                                            <span className="small fw-semibold">
                                            <i className="fa-regular fa-exclamation-circle"/>{" "}
                                                {t("trainingCloneComponent:loading")}
                                          </span>
                                        )}
                                    </div>
                                )}
                                {values.sendTo !== "library" && (
                                    <>
                                        <div className="form-group mt-3">
                                            <label className="fw-semibold">
                                                {t("trainingCloneComponent:routineNameLabel")}
                                            </label>
                                            <Field
                                                name="name"
                                                type="text"
                                                className={`form-control ${
                                                    touched.name && errors.name ? "is-invalid" : ""
                                                }`}
                                            />
                                            <ErrorMessage
                                                name="name"
                                                component="div"
                                                className="invalid-feedback"
                                            />
                                        </div>
                                        {shouldValidateDates && (
                                            <>
                                                <div className="form-group mt-3">
                                                    <label className="fw-semibold">
                                                        {t("trainingCloneComponent:startsOnLabel")}
                                                        <span className="ms-2 text-muted">
                                                          {t("trainingCloneComponent:mustBeADayNameNote", {
                                                              dayName,
                                                          })}
                                                        </span>
                                                    </label>
                                                    <Field
                                                        name="startsAt"
                                                        type="date"
                                                        className={`form-control ${
                                                            touched.startsAt && errors.startsAt
                                                                ? "is-invalid"
                                                                : ""
                                                        }`}
                                                    />
                                                    <ErrorMessage
                                                        name="startsAt"
                                                        component="div"
                                                        className="invalid-feedback"
                                                    />
                                                </div>
                                                <div className="form-group mt-3">
                                                    <label className="fw-semibold">
                                                        {t("trainingCloneComponent:endsOnLabel")}
                                                    </label>
                                                    <Field
                                                        name="endsAt"
                                                        type="date"
                                                        className={`form-control ${
                                                            touched.endsAt && errors.endsAt
                                                                ? "is-invalid"
                                                                : ""
                                                        }`}
                                                    />
                                                    <ErrorMessage
                                                        name="endsAt"
                                                        component="div"
                                                        className="invalid-feedback"
                                                    />
                                                </div>
                                                <small className="text-muted">
                                                    {t(
                                                        "trainingCloneComponent:endDateExactDaysAfterStartNote",
                                                        {dayDifference}
                                                    )}
                                                </small>
                                            </>
                                        )}
                                        <div className="row mt-3">
                                            <div className="col-12">
                                                <InfoCard
                                                    title={t("trainingCloneComponent:attention")}
                                                    message1={t(
                                                        "trainingCloneComponent:replicateAllWorkoutsMessage",
                                                        {dayName}
                                                    )}
                                                />
                                            </div>
                                        </div>
                                    </>
                                )}
                                <div className="d-grid mt-3">
                                    <button
                                        type="submit"
                                        disabled={loading}
                                        className="btn btn-primary"
                                    >
                                        {t("trainingCloneComponent:clone")}
                                    </button>
                                </div>
                                <div className="d-grid mt-2">
                                    <button
                                        type="button"
                                        className="btn btn-outline-primary"
                                        onClick={handleShow}
                                    >
                                        {t("trainingCloneComponent:close")}
                                    </button>
                                </div>
                            </Form>
                        )}
                    </Formik>
                </Modal.Body>
            </Modal>
        </>
    );
};

export default WorkoutAerobicClone;
