const normalizeRangeValue = (value) =>
    String(value ?? "")
        .replace("cm", "")
        .trim();

export const matchesThresholdRange = (value, range) => {
    const normalizedRange = normalizeRangeValue(range);
    const numericValue = Number(value);

    if (Number.isNaN(numericValue) || !normalizedRange) {
        return false;
    }

    if (normalizedRange.includes("<")) {
        const max = Number(normalizedRange.split("<")[1]);
        return numericValue <= max;
    }

    if (normalizedRange.includes("-")) {
        const [min, max] = normalizedRange.split("-").map(Number);
        return numericValue >= min && numericValue <= max;
    }

    if (normalizedRange.includes("+")) {
        const min = Number(normalizedRange.split("+")[0]);
        return numericValue >= min;
    }

    return false;
};

const getAgeLowerBound = (ageRange) => {
    if (ageRange.includes("<")) {
        return parseFloat(ageRange.slice(1).split("-")[0]);
    }

    if (ageRange.includes("-")) {
        return parseFloat(ageRange.split("-")[0]);
    }

    if (ageRange.includes("+")) {
        return Number(ageRange.split("+")[0]);
    }

    return null;
};

export const matchesAgeRange = (age, ageRange) => {
    const numericAge = Number(age);

    if (Number.isNaN(numericAge) || !ageRange) {
        return false;
    }

    if (ageRange.includes("<")) {
        const threshold = parseFloat(ageRange.slice(1).split("-")[0]);
        return numericAge < threshold;
    }

    if (ageRange.includes("-")) {
        const [min, max] = ageRange.split("-").map(Number);
        return numericAge >= min && numericAge <= max;
    }

    if (ageRange.includes("+")) {
        const min = Number(ageRange.split("+")[0]);
        return numericAge >= min;
    }

    return false;
};

export const findAgeMatchedEntry = (completeTable, age) => {
    const entries = Object.entries(completeTable ?? {});

    let matchedEntry = entries.find(([, data]) => matchesAgeRange(age, data?.age));

    if (matchedEntry) {
        return matchedEntry;
    }

    let fallbackEntry = null;
    let minDiff = Infinity;

    entries.forEach((entry) => {
        const [, data] = entry;
        if (!data?.age) {
            return;
        }

        const lowerBound = getAgeLowerBound(data.age);
        if (lowerBound === null) {
            return;
        }

        const diff = lowerBound - Number(age);
        if (Number(age) < lowerBound && diff < minDiff) {
            minDiff = diff;
            fallbackEntry = entry;
        }
    });

    return fallbackEntry || entries[0];
};

export const findMatchingResultKey = (rows, value) => {
    const row = (rows ?? []).find(({value: rangeValue}) => matchesThresholdRange(value, rangeValue));
    return row?.key;
};

export const calculateRepMaxValues = (carga, reps) => {
    if (!carga || !reps) {
        return [];
    }

    const repMax = Number(reps) < 10
        ? Number(carga) / 0.75
        : Number(carga) / (1.0278 - 0.0278 * Number(reps));

    return [
        parseFloat(repMax.toFixed(2)),
        parseFloat((repMax * 0.50).toFixed(2)),
        parseFloat((repMax * 0.60).toFixed(2)),
        parseFloat((repMax * 0.70).toFixed(2)),
        parseFloat((repMax * 0.80).toFixed(2)),
        parseFloat((repMax * 0.90).toFixed(2)),
    ];
};
