import {useSelector} from "react-redux";
import CardButtonAdd from "../card/CardButtonAdd";
import WorkoutRoutineEmpty from "./WorkoutRoutineEmpty";
import _ from "lodash";
import {useNavigate} from "react-router-dom";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {selectWorkoutRoutines} from "../../store/workout-routine/workoutRoutineSelector";
import WorkoutCard from "../workout/WorkoutCard";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutRoutine = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const workouts = useSelector(selectWorkoutRoutines)
    const client = useSelector(selectSelectedClient)
    useComponentTranslations('routineWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoToDeleted = () => {
        navigate(`/user/client/${client.id}/workout/secondary/status/3/type/0`)
    }

    const handleGoToArchive = () => {
        navigate(`/user/client/${client.id}/workout/secondary/status/1/type/0`)
    }

    const handleCreateRoutine = () => {
        navigate(`/user/client/${client.id}/workout/routine/create`)
    }

    return (
        <div className={"row justify-content-center mt-3"}>
            <div className={'col-12'}>
                <div className={'card card-body border-0'}>
                    <div className={"row"}>
                        {
                            workouts?.length > 0 &&
                            <div className={"col-12 mt-2"}>
                                <CardButtonAdd text={"Criar rotina"} handleClick={handleCreateRoutine}/>
                            </div>
                        }
                        <div className={"col-6 mt-2 pe-1"}>
                            <div className={"d-grid"}>
                                <button className={"btn btn-feedback-primary text-primary fw-semibold border-0"}
                                        onClick={handleGoToArchive}>{t("routineWorkoutComponent:archived")}</button>
                            </div>
                        </div>
                        <div className={"col-6 mt-2 ps-1"}>
                            <div className={"d-grid"}>
                                <button className={"btn btn-feedback-primary text-primary fw-semibold border-0"}
                                        onClick={handleGoToDeleted}>{t("routineWorkoutComponent:deleted")}</button>
                            </div>
                        </div>
                    </div>
                    {
                        workouts &&
                        <div className={"row mt-3"}>
                            <div className={'col-12'}>
                                {_.map(workouts, (workout) => <WorkoutCard key={workout.id} workout={workout} type={0}/>)}
                            </div>
                        </div>
                    }
                    {
                        workouts?.length === 0 &&
                        <WorkoutRoutineEmpty create={handleCreateRoutine}/>
                    }
                </div>
            </div>
        </div>
    )
}
export default WorkoutRoutine;