import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchDataSelectorAPI = async (type) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/push/${type}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}
