import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import React, {useEffect, useState, useMemo} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {isWorkoutAerobicLoading, selectAerobic} from "../../store/workout-aerobic/workoutAerobicSelector";
import WorkoutAerobicInstructions from "../../components/workout-aerobic/WorkoutAerobicInstructions";
import {createAerobicDay, getAerobic} from "../../store/workout-aerobic/workoutAerobicReducer";
import _ from "lodash";
import WorkoutAerobicDay from "../../components/workout-aerobic/WorkoutAerobicDay";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import Modal from "react-bootstrap/Modal";
import * as Yup from "yup";
import {ErrorMessage, Field, Form, Formik} from "formik";
import Text from "../../components/utils/emoji/Text"
import LoadingBlock from "../../components/loader/LoadingBlock";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutAerobicSessions = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {clientId, aerobicId, goBackTo} = useParams()
    const isLibrary = Number(clientId) === 0;
    const client = useSelector(selectSelectedClient)
    const workoutLoading = useSelector(isWorkoutAerobicLoading)
    const aerobic = useSelector(selectAerobic)
    const [showAddWorkoutDay, setShowAddWorkoutDay] = useState(false)
    const isNumberField = aerobic && aerobic.numTreinos > 0;
    const backToUpdates = goBackTo === "updates";
    const backToArchived = goBackTo === "archived";
    const backToFeedbacks = goBackTo === "feedbacks";

    useComponentTranslations('aerobicWorkout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object({
        field: isNumberField
            ? Yup.number()
                .typeError(t("aerobicWorkout:mustBeNumber"))
                .min(1, t("aerobicWorkout:biggerThanZero"))
                .required(t("aerobicWorkout:required"))
            : Yup.date()
                .typeError(t("aerobicWorkout:invalidDate"))
                .required(t("aerobicWorkout:required")),
    });

    const initialValuesModal = {field: "", type: isNumberField ? "number" : "date", runningId: aerobicId};

    const handleAddDaySubmit = (values) => {
        dispatch(createAerobicDay(values))
        handleAddWorkoutDay()
    };

    const handleGoBack = () => {
        if (backToFeedbacks)
            navigate("/user/feedback")
        else if (backToUpdates)
            navigate("/user/update/list/9")
        else if (backToArchived) {
            navigate(`/user/client/${clientId}/workout/secondary/status/1/type/1`)
        } else if (isLibrary)
            navigate("/user/workout-library/2")
        else
            navigate(`/user/client/${clientId}/workout/2`)
    }

    const handleAddWorkoutDay = () => {
        setShowAddWorkoutDay(prevState => !prevState)
    }

    const sortedDays = useMemo(() => {
        if (!Array.isArray(aerobic?.days)) return []
        const list = [...aerobic.days]
        return isNumberField
            ? list.sort((a, b) => a.diaNumero - b.diaNumero)
            : list.sort((a, b) => new Date(a.dia) - new Date(b.dia))
    }, [aerobic?.days, isNumberField])

    const weeksData = useMemo(() => {
        const sortDays = (arr = []) =>
            [...arr].sort((a, b) => new Date(a.dia) - new Date(b.dia));

        if (aerobic?.weeksByYearWeek && typeof aerobic.weeksByYearWeek === 'object') {
            return Object.entries(aerobic.weeksByYearWeek)
                .sort(([a], [b]) => a.localeCompare(b))
                .map(([key, days]) => {
                    const [yearStr, weekStr] = key.split('-');
                    return {
                        key,
                        year: Number(yearStr),
                        week: Number(weekStr),
                        days: sortDays(days),
                    };
                });
        }

        if (aerobic?.weeks && typeof aerobic.weeks === 'object') {
            const keys = Array.isArray(aerobic.weeksOrder) && aerobic.weeksOrder.length
                ? aerobic.weeksOrder.map(String)
                : Object.keys(aerobic.weeks).sort((a, b) => Number(a) - Number(b));

            return keys.map((k) => ({
                key: k,
                year: null,
                week: Number(k),
                days: sortDays(aerobic.weeks[k]),
            }));
        }

        return [];
    }, [aerobic?.weeksByYearWeek, aerobic?.weeks, aerobic?.weeksOrder]);


    useEffect(() => {
        if (Number(clientId) > 0)
            dispatch(fetchClient(clientId));
    }, [dispatch, clientId]);

    useEffect(() => {
        dispatch(getAerobic(aerobicId));
    }, [dispatch, aerobicId]);

    if (!aerobic) {
        return <LoadingBlock/>
    }

    return (
        <>
            {
                !isLibrary &&
                <AvatarHeader className={"pb-4 pt-2"}
                              xl={"8"}
                              lg={"10"}
                              text={`${client?.nome} ${client?.sobrenome}`}
                              url={client?.profileUrl} showGoBack={handleGoBack}/>
            }
            <Page contentHeader={isLibrary} loading={workoutLoading} xl={"8"} lg={"10"} goBackLink={handleGoBack}>
                <div className={"row justify-content-center mt-3"}>
                    <div className={'col-12'}>
                        <div className={'card card-body border-0'}>
                            <div className={"row justify-content-center"}>
                                <div className={"col-12 "}>
                                    <span className={"fw-semibold fs-5"}>
                                        <Text>{aerobic?.nome}</Text>
                                    </span>
                                </div>
                                <div className={"col-12 mt-3"}>
                                    <CardButtonAdd text={t("aerobicWorkout:addWorkout")} handleClick={handleAddWorkoutDay}/>
                                </div>
                                <Modal show={showAddWorkoutDay} centered onHide={handleAddWorkoutDay}>
                                    <Modal.Body>
                                        <Formik
                                            initialValues={initialValuesModal}
                                            validationSchema={validationSchema}
                                            onSubmit={handleAddDaySubmit}
                                        >
                                            {() => (
                                                <Form>
                                                    <div className="form-group">
                                                        <label htmlFor="field" className={"fw-semibold"}>
                                                            {isNumberField ? t("aerobicWorkout:workoutNumberSingular") : t("aerobicWorkout:dateInterval")}
                                                        </label>
                                                        {isNumberField ? (
                                                            <Field
                                                                name="field"
                                                                type="number"
                                                                min="1"
                                                                className="form-control"
                                                            />
                                                        ) : (
                                                            <Field
                                                                name="field"
                                                                type="date"
                                                                className="form-control"
                                                            />
                                                        )}
                                                        <ErrorMessage name="field" component="div" className="text-danger"/>
                                                    </div>
                                                    <button type="submit" className="btn btn-primary mt-3 w-100">
                                                        {t("aerobicWorkout:send")}
                                                    </button>
                                                </Form>
                                            )}
                                        </Formik>
                                    </Modal.Body>
                                </Modal>
                            </div>
                            <div className={"row justify-content-center mt-4"}>
                                <div className={"col-12"}>
                                    <WorkoutAerobicInstructions aerobic={aerobic}/>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className={'col-12 mt-2'}>
                        <div className={"row "}>
                            {
                                _.map(sortedDays, (day) =>
                                    <div className={"col-12 col-lg-6 col-xl-4 mb-2"} key={day.id}>
                                        <WorkoutAerobicDay runningDay={day}/>
                                    </div>
                                )
                            }
                        </div>
                        <div className="row mb-2">
                            {weeksData.map((w, idx) => (
                                <div key={w.key} className="mb-3">
                                    <div className="col-12">
                                        <span className="fw-semibold fs-5 pb-2 d-block">
                                          {t("aerobicWorkout:week")} {idx + 1}
                                        </span>
                                    </div>
                                    <div className="row">
                                        {w.days.map(day => (
                                            <div className="col-12 col-xl-4 mb-2" key={day.id}>
                                                <WorkoutAerobicDay runningDay={day}/>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </Page>
        </>
    )
}
export default WorkoutAerobicSessions;