import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchContactsAPI = async ({startDate, endDate} = {}) => {
    const token = getToken();
    if (!token) return;
    const params = new URLSearchParams();
    if (startDate) {
        params.set("startDate", startDate);
    }
    if (endDate) {
        params.set("endDate", endDate);
    }
    const queryString = params.toString();
    const url = queryString ? `${apiUrl}/signup-link/contacts?${queryString}` : `${apiUrl}/signup-link/contacts`;
    return await axios.get(url, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}
export const convertContactToClientAPI = async (id) => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/signup-link/contact-to-client?id=${id}`, {},
        {
            headers: {
                'Content-Type':
                    'application/json',
                'authorization':
                token
            },
            timeout: 20000
        }
    )
}
export const deleteContactAPI = async (id) => {
    const token = getToken();
    if (!token) return;

    return await axios.delete(`${apiUrl}/signup-link/contact?id=${id}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

export const deleteAllContactsAPI = async () => {
    const token = getToken();
    if (!token) return;

    return await axios.delete(`${apiUrl}/signup-link/all`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}
