import Cookies from "js-cookie";

export const getMainDomain = () => {
    const hostname = window.location.hostname;
    const parts = hostname.split('.');
    if (parts.length > 1) {
        return parts.slice(1).join('.');
    }
    return hostname;
};

export const setUserTokenCookie = (token) => {
    const parsedToken = `${token || ""}`.trim();
    if (!parsedToken) {
        return false;
    }

    const cookieOptions = {
        expires: 400,
        path: "/"
    };

    const mainDomain = getMainDomain();

    try {
        Cookies.set("user_token", parsedToken, {...cookieOptions, domain: `.${mainDomain}`});
    } catch (error) {
    }

    if (Cookies.get("user_token") === parsedToken) {
        return true;
    }

    try {
        Cookies.set("user_token", parsedToken, cookieOptions);
    } catch (error) {
        return false;
    }

    return Cookies.get("user_token") === parsedToken;
};
