import {isDesktop, isTablet} from 'react-device-detect';
import NavbarMenuButton from "./NavbarMenuButton";
import NavBar from "./NavBar";
import {useDispatch, useSelector} from "react-redux";
import {toggleChatBot} from "../../store/menu/menuReducer";
import ChatBotOffCanvas from "../chat-bot/ChatBotOffCanvas";
import {chatBotSelector} from "../../store/menu/menuSelector";
import {matchPath, useLocation} from "react-router-dom";

const hiddenPaths = [
    '/user/mfit-ia',
    '/user/profile/*',
    '/blocked',
    '/chargeback',
    '/subscription/*'
];

const TopBar = ({showChildren = false}) => {
    const dispatch = useDispatch();
    const show = useSelector(chatBotSelector);
    const location = useLocation();

    const hideBasedOnPath = !hiddenPaths.some((path) =>
        matchPath({path, exact: true}, location.pathname)
    );
    const style = {
        bottom: (isDesktop || isTablet) ? '0' : "70px",
        display: "inline-flex"
    }

    const handleChatBot = () => {
        dispatch(toggleChatBot())
    }

    return (
        <NavBar>
            {
                showChildren &&
                <>
                    {
                        (isTablet || isDesktop) &&
                        <NavbarMenuButton/>
                    }
                </>
            }
            {
                hideBasedOnPath &&
                <button
                    type="button"
                    style={style}
                    onClick={handleChatBot}
                    className="btn bg-mfit-ai-gradient text-white rounded-circle position-fixed end-0 avatar avatar-md me-3 mb-3 shadow  border-0"
                >
                    <i className="fa-kit fa-mfit-ai fa-2xl  "></i>
                </button>
            }
            {
                show &&
                <ChatBotOffCanvas/>
            }
        </NavBar>
    )
}

export default TopBar;
