const PARCELS_FEES = [ 0, 0, 4.53, 6.54, 7.54, 8.54, 9.54, 10.54, 11.54, 12.54, 13.54, 14.54, 15.00];

const EPSILON = 1e-8;

export const roundHalfEven = (value, decimals = 2) => {
    if (!Number.isFinite(value)) {
        return 0;
    }

    const factor = 10 ** decimals;
    const scaled = value * factor;
    const sign = Math.sign(scaled) || 1;
    const absScaled = Math.abs(scaled);
    const floor = Math.floor(absScaled);
    const fraction = absScaled - floor;

    let rounded;
    if (Math.abs(fraction - 0.5) < EPSILON) {
        rounded = floor % 2 === 0 ? floor : floor + 1;
    } else {
        rounded = Math.round(absScaled);
    }

    return (rounded * sign) / factor;
};

const calculateTotalAmount = (netSellerAmount, feePercentage, fixedFee) => {
    const denominator = 1 - feePercentage;
    if (denominator === 0) {
        return 0;
    }
    const totalBeforeFee = (netSellerAmount + fixedFee) / denominator;
    return roundHalfEven(totalBeforeFee, 2);
};

const normalizeSellerPlan = (value) => {
    if (value === null || value === undefined) {
        return undefined;
    }
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) {
        return undefined;
    }
    if (numeric === 30 || numeric === 1) {
        return 1;
    }
    if (numeric === 14 || numeric === 2) {
        return 2;
    }
    return numeric;
};

const parseBoolean = (value) => {
    if (typeof value === "boolean") {
        return value;
    }
    if (typeof value === "string") {
        if (value.toLowerCase() === "true") {
            return true;
        }
        if (value.toLowerCase() === "false") {
            return false;
        }
    }
    return undefined;
};

export const normalizeInstallmentMap = (installments) => {
    if (!installments) {
        return undefined;
    }

    return Object.entries(installments).reduce((acc, [key, value]) => {
        const numericKey = Number(key);
        const numericValue = Number(value);
        if (!Number.isFinite(numericKey) || !Number.isFinite(numericValue)) {
            return acc;
        }
        if (numericKey < 1) {
            return acc;
        }
        acc[numericKey] = roundHalfEven(numericValue, 2);
        return acc;
    }, {});
};

export const getInstallmentValue = (installments, key) => {
    if (!installments) {
        return undefined;
    }
    const numericKey = Number(key);
    if (!Number.isFinite(numericKey)) {
        return undefined;
    }
    const value = installments[numericKey];
    if (value !== undefined) {
        return Number(value);
    }
    const stringValue = installments[String(key)];
    if (stringValue !== undefined) {
        return Number(stringValue);
    }
    return undefined;
};

export const generateInstallments = (
    originalPrice,
    interestFree,
    sellerPlan = 1,
    ignoreFixedFees = false,
    limit = 12
) => {
    const normalizedPrice = Number(originalPrice);
    if (!Number.isFinite(normalizedPrice)) {
        return {};
    }
    let fixedFee = sellerPlan === 1 ? 0.5 : 1.0;
    let percentageFee = sellerPlan === 1 ? 0.0399 : 0.0499;
    let netSellerAmount = normalizedPrice * (1 - percentageFee) - fixedFee;

    if (ignoreFixedFees) {
        fixedFee = 0;
        netSellerAmount = normalizedPrice;
    }

    const installments = {};
    const safeLimit = Math.max(1, Math.min(12, Number(limit) || 12));

    for (let i = 1; i <= safeLimit; i += 1) {
        let totalAmount;
        if (i === 1) {
            totalAmount = normalizedPrice;
        } else {
            const feePercentage = interestFree ? 0 : (PARCELS_FEES[i] || 0) / 100;
            totalAmount = calculateTotalAmount(netSellerAmount, feePercentage, fixedFee);
        }
        installments[i] = roundHalfEven(totalAmount, 2);
    }

    return installments;
};

/**
 * Plain installments generator (no base fixed/percentage fees).
 * Applies only PARCELS_FEES[i] to the original price.
 * - interestFree: if true, returns original price for all parcels.
 * - limit: caps the number of returned parcels (1..12).
 * - grossUp: if true, gross-up so seller net equals originalPrice after fee.
 */
export const generatePlainInstallments = (
    originalPrice,
    interestFree,
    limit = 12,
    grossUp = false
) => {
    const normalizedPrice = Number(originalPrice);
    if (!Number.isFinite(normalizedPrice)) {
        return {};
    }

    const installments = {};
    const safeLimit = Math.max(1, Math.min(12, Number(limit) || 12));

    for (let i = 1; i <= safeLimit; i += 1) {
        let totalAmount;

        if (interestFree || i === 1) {
            totalAmount = normalizedPrice;
        } else {
            const feePct = (PARCELS_FEES[i] || 0) / 100;

            // add-on (default): buyer pays original + fee%
            // gross-up (optional): buyer pays original / (1 - fee%)
            const raw = grossUp
                ? (1 - feePct) === 0 ? 0 : normalizedPrice / (1 - feePct)
                : normalizedPrice * (1 + feePct);

            totalAmount = roundHalfEven(raw, 2);
        }

        installments[i] = roundHalfEven(totalAmount, 2);
    }

    return installments;
};

export const resolveInstallmentConfiguration = (subPlan, normalizedInstallments) => {
    const possibleSellerPlanKeys = [
        "sellerPlan",
        "seller_plan",
        "zoopSellerPlan",
        "zoop_seller_plan",
        "seller_plan_type"
    ];
    const possibleIgnoreKeys = [
        "ignoreFixedFees",
        "ignore_fixed_fees",
        "ignoreZoopFixedFees",
        "ignore_zoop_fixed_fees"
    ];

    let sellerPlan;
    let ignoreFixedFees;

    if (subPlan) {
        for (const key of possibleSellerPlanKeys) {
            if (subPlan[key] !== undefined) {
                sellerPlan = normalizeSellerPlan(subPlan[key]);
                break;
            }
        }
        for (const key of possibleIgnoreKeys) {
            if (subPlan[key] !== undefined) {
                const parsed = parseBoolean(subPlan[key]);
                if (parsed !== undefined) {
                    ignoreFixedFees = parsed;
                }
                break;
            }
        }
    }

    if (sellerPlan !== undefined && ignoreFixedFees !== undefined) {
        return {sellerPlan, ignoreFixedFees};
    }

    const normalized = normalizedInstallments || normalizeInstallmentMap(subPlan?.installments);
    const baseAmount = getInstallmentValue(normalized, 1);
    if (!normalized || !baseAmount) {
        return {
            sellerPlan: sellerPlan ?? 1,
            ignoreFixedFees: ignoreFixedFees ?? false
        };
    }

    const keys = Object.keys(normalized).map(Number).filter((value) => Number.isFinite(value) && value >= 1);
    if (!keys.length) {
        return {
            sellerPlan: sellerPlan ?? 1,
            ignoreFixedFees: ignoreFixedFees ?? false
        };
    }

    const combinations = [
        {sellerPlan: 1, ignoreFixedFees: false},
        {sellerPlan: 1, ignoreFixedFees: true},
        {sellerPlan: 2, ignoreFixedFees: false},
        {sellerPlan: 2, ignoreFixedFees: true}
    ];

    let bestMatch = {
        sellerPlan: sellerPlan ?? 1,
        ignoreFixedFees: ignoreFixedFees ?? false
    };
    let bestScore = Number.POSITIVE_INFINITY;

    combinations.forEach((config) => {
        const generated = generateInstallments(
            baseAmount,
            Boolean(subPlan?.interestFree),
            config.sellerPlan,
            config.ignoreFixedFees,
            Math.max(...keys)
        );

        const score = keys.reduce((acc, installmentKey) => {
            const original = normalized[installmentKey];
            const candidate = generated[installmentKey];
            if (original === undefined || candidate === undefined) {
                return acc + 1000;
            }
            return acc + Math.abs(original - candidate);
        }, 0);

        if (score < bestScore) {
            bestScore = score;
            bestMatch = config;
        }
    });

    return {
        sellerPlan: sellerPlan ?? bestMatch.sellerPlan,
        ignoreFixedFees: ignoreFixedFees ?? bestMatch.ignoreFixedFees
    };
};

export const recalculateInstallments = (
    subPlan,
    discountAdjustment = 0,
    normalizedInstallments,
    configuration
) => {
    const normalized = normalizedInstallments ?? normalizeInstallmentMap(subPlan?.installments);
    if (!normalized) {
        return undefined;
    }

    const keys = Object.keys(normalized)
        .map(Number)
        .filter((value) => Number.isFinite(value) && value >= 1);

    if (!keys.length) {
        return normalized;
    }

    const baseAmount = getInstallmentValue(normalized, 1);
    if (baseAmount === undefined) {
        return normalized;
    }

    if (!discountAdjustment) {
        return normalized;
    }

    const discountedTotal = roundHalfEven(Math.max(baseAmount - Number(discountAdjustment || 0), 0));

    const {sellerPlan, ignoreFixedFees} = configuration ?? resolveInstallmentConfiguration(subPlan, normalized);

    const generated = generateInstallments(
        discountedTotal,
        Boolean(subPlan?.interestFree),
        sellerPlan,
        ignoreFixedFees,
        Math.max(...keys)
    );

    return keys.reduce((acc, installmentKey) => {
        acc[installmentKey] = generated[installmentKey];
        return acc;
    }, {});
};
