import React, {useCallback, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ContentHeader from "../../components/contentheader/ContentHeader";
import Tabs from "../../components/tab/Tabs";
import UpdateList from "../../components/updates/UpdateList";

const UpdatesList = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const {redirect} = useParams();
    const [page, setPage] = useState("1")
    useComponentTranslations('update', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const changePages = (pageName) => {
        setPage(pageName)
    }

    const handleGoBack = useCallback(() => {
        if (redirect) {
            navigate("/user")
        } else
            navigate("/user/update")
    }, [navigate, redirect])



    return (
        <>
            <ContentHeader title={t("update:updatesTitle")} goBackLink={handleGoBack}/>
            <div className={`row justify-content-evenly bg-default m-0 mt-n5`}>
                <div className={'col-12 col-md-6  col-lg-6 col-xl-4'}>
                    <Tabs page={page} button1Text={t("update:pending")} button2Text={t("update:resolved")} buttonClick={changePages}/>
                </div>
            </div>
            <Page  contentHeader={false} mt={"mt-n2"}>
                {
                    page === "1" ? <UpdateList status={0}/> : <UpdateList status={1}/>
                }
            </Page>
        </>

    )
}

export default UpdatesList;
