import {ErrorMessage, Field, Form, Formik} from "formik";
import React, {useEffect} from "react";
import * as Yup from "yup";
import {useDispatch, useSelector} from "react-redux";
import {
    createSession,
    updateSession,
    setSessionCreated,
    setSessionUpdated,
} from "../../store/workout-routine/workoutRoutineReducer";
import {
    selectWorkoutRoutineSessionCreated,
    selectWorkoutRoutineSessionCreating,
    selectWorkoutRoutineSessionUpdated,
    selectWorkoutRoutineSessionUpdating,
} from "../../store/workout-routine/workoutRoutineSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from "he";
import moment from "moment";
import {useNavigate} from "react-router-dom";
import {selectSelectedClient} from "../../store/client/clientSelector";
import TextareaAutosize from 'react-textarea-autosize';

const WorkoutSessionCreateForm = ({workout, onClose, session}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const isWeekday = workout.diaTipo === 1;
    const client = useSelector(selectSelectedClient);
    const sessionCreating = useSelector(selectWorkoutRoutineSessionCreating);
    const sessionUpdating = useSelector(selectWorkoutRoutineSessionUpdating);
    const isSessionCreated = useSelector(selectWorkoutRoutineSessionCreated);
    const isSessionUpdated = useSelector(selectWorkoutRoutineSessionUpdated);
    const navigate = useNavigate();

    useComponentTranslations("routineWorkoutComponent", {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT,
    });

    const validationSchema = Yup.object().shape({
        training: isWeekday
            ? Yup.number()
                .typeError(t("routineWorkoutComponent:required"))
                .oneOf([1, 2, 3, 4, 5, 6, 7], t("routineWorkoutComponent:selectValidDay"))
                .required(t("routineWorkoutComponent:required"))
            : Yup.number()
                .typeError(t("routineWorkoutComponent:required"))
                .min(1, t("routineWorkoutComponent:minValue"))
                .required(t("routineWorkoutComponent:required")),
        name: Yup.string()
            .max(245, t("routineWorkoutComponent:maxChars"))
            .required(t("routineWorkoutComponent:required")),
        instructions: Yup.string(),
    });

    const initialValues = session
        ? {
            id: session.id,
            training: session.diaTipo || (isWeekday ? "" : 1),
            name: he.decode(session.nome || ""),
            instructions: he.decode(session.obs || ""),
            workoutId: session.idRoutine || workout.id,
            clientId: session.idAluno || workout.idAluno,
            status: session.status || 0,
        }
        : {
            id: 0,
            training: isWeekday ? "" : 1,
            name: "",
            instructions: "",
            workoutId: workout.id,
            clientId: workout.idAluno,
            status: 0,
            copyFrom: 0,
        };

    const handleSubmit = (values) => {
        if (session) {
            dispatch(updateSession(values));
        } else {
            dispatch(createSession(values));
        }
    };

    useEffect(() => {
        if (isSessionUpdated) {
            dispatch(setSessionUpdated(false));
            onClose();
        }
        if (isSessionCreated) {
            const sessionId = workout.sessions.at(-1).id;
            dispatch(setSessionCreated(false));
            navigate(`/user/client/${client?.id || 0}/workout/routine/${workout.id}/session/${sessionId}/prescribe`)
        }
    }, [isSessionCreated, isSessionUpdated, session, client, workout, navigate, dispatch, onClose]);

    return (
        <Formik
            initialValues={initialValues}
            validationSchema={validationSchema}
            onSubmit={handleSubmit}
            enableReinitialize
        >
            {({errors, touched}) => (
                <Form>
                    <div className="mb-3">
                        <label htmlFor="training" className="form-label fw-semibold">
                            {t("routineWorkoutComponent:workout")}
                        </label>
                        {isWeekday ? (
                            <Field
                                as="select"
                                name="training"
                                id="training"
                                className={`form-select ${
                                    errors.training && touched.training ? "is-invalid" : ""
                                }`}
                            >
                                <option value="">{t("routineWorkoutComponent:selectDay")}</option>
                                <option value="2">{t("routineWorkoutComponent:monday")}</option>
                                <option value="3">{t("routineWorkoutComponent:tuesday")}</option>
                                <option value="4">{t("routineWorkoutComponent:wednesday")}</option>
                                <option value="5">{t("routineWorkoutComponent:thursday")}</option>
                                <option value="6">{t("routineWorkoutComponent:friday")}</option>
                                <option value="7">{t("routineWorkoutComponent:saturday")}</option>
                                <option value="1">{t("routineWorkoutComponent:sunday")}</option>
                            </Field>
                        ) : (
                            <Field
                                type="number"
                                name="training"
                                id="training"
                                min="1"
                                className={`form-control ${
                                    errors.training && touched.training ? "is-invalid" : ""
                                }`}
                            />
                        )}
                        <ErrorMessage
                            name="training"
                            component="div"
                            className="invalid-feedback"
                        />
                    </div>
                    <div className="mb-3">
                        <label htmlFor="name" className="form-label fw-semibold">
                            {t("routineWorkoutComponent:name")}
                        </label>
                        <Field
                            type="text"
                            name="name"
                            id="name"
                            className={`form-control ${
                                errors.name && touched.name ? "is-invalid" : ""
                            }`}
                        />
                        <ErrorMessage name="name" component="div" className="invalid-feedback"/>
                    </div>
                    {!session && (
                        <div className="mb-3">
                            <label htmlFor="copyFrom" className="form-label fw-semibold">
                                {t("routineWorkoutComponent:copyFrom")}
                            </label>
                            <Field as="select" name="copyFrom" id="copyFrom" className="form-select">
                                <option value="0"></option>
                                {workout.sessions &&
                                    workout.sessions.map((s) => (
                                        <option key={s.id} value={s.id}>
                                            {workout.diaTipo === 2
                                                ? `${t("routineWorkoutComponent:workout")} ${s.diaTipo}`
                                                : moment().day(s.diaTipo - 1).format("dddd")}
                                        </option>
                                    ))}
                            </Field>
                        </div>
                    )}
                    <div className="mb-3">
                        <label htmlFor="instructions" className="form-label fw-semibold">
                            {t("routineWorkoutComponent:generalInstructions")}{" "}
                            <span className="small">({t("routineWorkoutComponent:optional")})</span>
                        </label>
                        <Field
                            name="instructions"
                        >
                            {({field}) => (
                                <TextareaAutosize
                                    {...field}
                                    className="form-control"
                                    rows={3}
                                    minRows={3}

                                />
                            )}
                        </Field>
                        <ErrorMessage
                            name="instructions"
                            component="div"
                            className="invalid-feedback"
                        />
                    </div>
                    <button
                        type="submit"
                        className="btn btn-primary w-100"
                        disabled={sessionCreating || sessionUpdating}
                    >
                        {t("routineWorkoutComponent:save")}
                    </button>
                    <span onClick={onClose} className="btn btn-outline-primary w-100 mt-2">
                        {t("routineWorkoutComponent:close")}
                    </span>
                </Form>
            )}
        </Formik>
    );
};

export default WorkoutSessionCreateForm;
