export function slugify(str) {
    return str
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .trim()
        .replace(/\s+/g, '_')
        .replace(/[^\w_]+/g, '');
}

export function mapCategoriesWithKey(categories = []) {
    return categories.map(cat => ({
        ...cat,
        key: cat.i18n
            ? cat.i18n.split('.').pop()
            : slugify(cat.nome)
    }));
}

export const DEFAULT_CATEGORIES = [
    { id:  1, key: "restaurant" },
    { id:  2, key: "supermarket" },
    { id:  3, key: "services" },
    { id:  4, key: "health" },
    { id:  5, key: "transportation" },
    { id:  6, key: "recreation" },
    { id:  7, key: "personal_training_services" },
    { id:  8, key: "food" },
    { id:  9, key: "travel" },
    { id: 10, key: "housing" },
    { id: 11, key: "others" }
];

export function getAllCategories(categoriesFromBackend = []) {
    const customCats = categoriesFromBackend.filter(cat => !cat.i18n);
    const mappedCustom = mapCategoriesWithKey(customCats);
    return [...DEFAULT_CATEGORIES, ...mappedCustom];
}