import moment from 'moment';

export function getDateRange({ daysBack = 6, inclusive = true } = {}) {
    const end   = inclusive
        ? moment().endOf('day')
        : moment().startOf('day');
    const start = moment()
        .subtract(daysBack, 'days')
        .startOf('day');
    return {
        start: start.valueOf(),
        end:   end.valueOf(),
    };
}
