import axios from "axios";
import {getToken} from "../api";

const normalizeViaCepResponse = (data) => ({
    cep: data?.cep,
    state: data?.uf,
    city: data?.localidade,
    neighborhood: data?.bairro,
    street: data?.logradouro,
    service: "viacep",
    erro: data?.erro,
});

export const getCep = async (cep) => {
    const token = getToken();
    if (!token) return;
    try {
        return await axios.get(`https://brasilapi.com.br/api/cep/v2/${cep}`, {
            headers: {
                'Content-Type': 'application/json',
            },
            timeout: 4000
        });
    } catch (error) {
        const fallbackResponse = await axios.get(`https://viacep.com.br/ws/${cep}/json/`, {
            headers: {
                'Content-Type': 'application/json',
            },
            timeout: 20000
        });
        return {
            ...fallbackResponse,
            data: normalizeViaCepResponse(fallbackResponse?.data),
        };
    }
}
