import {createSelector} from 'reselect';

const reducer = state => state.subscription;

export const selectBuyer = createSelector(
    [reducer],
    s => s.buyer
);
export const selectLoadingBuyer = createSelector(
    [reducer],
    s => s.loadingBuyer
)

export const selectedSubPlan = createSelector(
    [reducer],
    s => s.subPlan
);

export const selectSubPlanLoading = createSelector(
    [reducer],
    s => s.loadingSubPlan
)

export const selectSubPlanList = createSelector(
    [reducer],
    s => s.subPlanList
)

export const selectCreditCards = createSelector(
    [reducer],
    s => s.creditCards
)

export const selectCreditCardsLoading = createSelector(
    [reducer],
    s => s.loadingCreditCards
)

export const selectPaymentMethod = createSelector(
    [reducer],
    s => s.paymentMethod
)

export const selectInstallments = createSelector(
    [reducer],
    s => s.installments
)

export const selectCoupon = createSelector([reducer], s => s.coupon)
export const selectCouponLoading = createSelector([reducer], s => s.loadingCoupon)

export const selectTransaction = createSelector([reducer], s => s.transaction)
export const selectTransactionLoading = createSelector([reducer], s => s.loadingTransaction)

export const selectChangeSubLoading = createSelector([reducer], s => s.loadingSubChange)

export const selectFreePlanChanged = createSelector([reducer], s => s.freePlanChanged)

export const selectCreditCardError = createSelector([reducer], s => s.creditCardError)

export const selectCreditCardCreated = createSelector([reducer], s => s.creditCardCreated)

export const selectSubscriptionCanceled = createSelector([reducer], s => s.subscriptionCanceled)
export const selectLoadingSubscription = createSelector([reducer], s => s.loadingSubscription)
export const selectSubscriptionActivated = createSelector([reducer], s => s.subscriptionActivated)
export const selectPaymentMethodChanged = createSelector([reducer], s => s.paymentMethodChanged)
