import {createSelector} from "reselect";

const reducer = (state) => state.exerciseLibrary;

export const selectExerciseFavorites = createSelector(
    [reducer],
    (slice) => slice.favorites
)

export const selectUserExercises = createSelector(
    [reducer],
    (slice) => slice.userExercises
)

export const selectExerciseGroups = createSelector(
    [reducer],
    (slice) => slice.exerciseGroups
)

export const selectExerciseCategories = createSelector(
    [reducer],
    (slice) => slice.exerciseCategories
)

export const selectLibraryLoading = createSelector(
    [reducer],
    (slice) => slice.loading
)

export const selectExercise = createSelector(
    [reducer],
    (slice) => slice.exercise
)

export const selectExerciseSaved = createSelector(
    [reducer],
    (slice) => slice.exerciseSaved
)