// src/utils/workout/useExerciseSearch.js
import { useState, useEffect } from 'react';
import { apiUrl } from '../../api/api';

export function useExerciseSearch(
    query,
    locale = 'pt-BR',
    page = 1,
    hitsPerPage = 20,
    groupFilter = '',
    categoryFilter = ''
) {
    const [results, setResults]       = useState([]);
    const [loading, setLoading]       = useState(false);
    const [error, setError]           = useState(null);
    const [total, setTotal]           = useState(0);
    const [totalPages, setTotalPages] = useState(1);

    useEffect(() => {
        setResults([]);
        setTotal(0);
        setTotalPages(1);

        // Only skip fetch if there’s no query AND no filters
        if (query !== '*' && !query.trim() && !groupFilter && !categoryFilter) {
            setLoading(false);
            return;
        }

        setLoading(true);
        setError(null);

        const params = new URLSearchParams({
            locale,
            page: String(page),
            hitsPerPage: String(hitsPerPage),
        });
        params.append('q', query);
        if (groupFilter)    params.append('group',    groupFilter);
        if (categoryFilter) params.append('category', categoryFilter);

        fetch(`${apiUrl}/exercise/search?${params.toString()}`)
            .then(r => {
                if (!r.ok) throw new Error(`HTTP ${r.status}`);
                return r.json();
            })
            .then(data => {
                setResults(data.items || []);
                setTotal(data.total || 0);
                setTotalPages(data.totalPages || 1);
            })
            .catch(e => setError(e.message))
            .finally(() => setLoading(false));
    }, [query, locale, page, hitsPerPage, groupFilter, categoryFilter]);

    return { results, loading, error, page, hitsPerPage, total, totalPages };
}
