export const buildCreateAnamnesisPayload = (anamnesis, clientId) => ({
    id: Number.parseInt(anamnesis?.id, 10),
    idClient: Number.parseInt(clientId, 10),
    questions: (anamnesis?.questions || []).map((question) => ({
        id: question.id,
        question: question.question,
        answer: question.answer,
    })),
});
