import {useNavigate, useParams} from "react-router-dom";
import {useEffect} from "react";
import Cookies from 'js-cookie';
import {getMainDomain} from "../../utils/cookie/cookieUtils";

const Redirect = () => {
    const {token, version} = useParams();
    const navigate = useNavigate();
    useEffect(() => {
        const mainDomain = getMainDomain();
        Cookies.set('user_token', token, {expires: 400, path: '/', domain: `.${mainDomain}`})
        if (version === "12") {
            Cookies.set('isApple', true, {expires: 1, path: '/', domain: `.${mainDomain}`})
        }
        // else
        //     Cookies.remove('isApple', {path: '/', domain: `.${mainDomain}`});
        navigate('/user');
    }, [navigate, token, version])

    return (<></>)
}
export default Redirect;