import {apiUrl, getToken} from "../api";
import axios from "axios";

export const refreshUserTokenAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/auth/user/refresh-token`, {}, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}
