import {useDispatch, useSelector} from "react-redux";
import {fetchFeedbacks} from "../../store/workout-routine/workoutRoutineReducer";
import {useNavigate, useParams} from "react-router-dom";
import React, {useEffect} from "react";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {selectWorkoutRoutineFeedbacks, selectWorkoutRoutineLoading} from "../../store/workout-routine/workoutRoutineSelector";
import {fetchClient} from "../../store/client/clientReducer";
import Page from "../../components/page/Page";
import WorkoutFeedbackCard from "../../components/workout/WorkoutFeedbackCard";
import EmptySet from "../../components/empty-set/EmptySet";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutRoutineFeedbacks = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {sessionId, id, clientId} = useParams();
    const feedbacks = useSelector(selectWorkoutRoutineFeedbacks)
    const client = useSelector(selectSelectedClient)
    const loading = useSelector(selectWorkoutRoutineLoading)
    useComponentTranslations('workoutRoutine', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate(`/user/client/${client.id}/workout/routine/${id}`)
    };

    useEffect(() => {
        dispatch(fetchClient(clientId))
    }, [dispatch, clientId]);

    useEffect(() => {
        dispatch(fetchFeedbacks(sessionId))
    }, [dispatch, sessionId]);

    return (
        <Page contentHeader={true} loading={loading} title={t("workoutRoutine:workoutFeedback")} mt={"mt-n5"} goBackLink={handleGoBack}>
            <div className={"row justify-content-center"}>
                <div className={"col-12"}>
                    <div className={"card card-body border-0"}>
                        {
                            (!feedbacks || feedbacks.length === 0) &&
                            <div className={"row"}>
                                <div className={"col-12"}>
                                    <EmptySet icon={"fa-comments"} message={t("workoutRoutine:emptyFeedbackMessage")}/>
                                </div>
                            </div>
                        }
                        {
                            feedbacks?.map((feedback, idx, arr) => (
                                <WorkoutFeedbackCard feedback={feedback} key={feedback.id} isLast={idx === arr.length - 1}/>
                            ))
                        }
                    </div>
                </div>
            </div>
        </Page>
    )
}
export default WorkoutRoutineFeedbacks;