import {useNavigate, useParams, useSearchParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import React, {useEffect, useState} from "react";
import {changeStatus, fetchClient, setClient} from "../../store/client/clientReducer";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {selectClientCount, selectSelectedClient} from "../../store/client/clientSelector";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Tabs from "../../components/tab/Tabs";
import ClientStart from "../../components/client/ClientStart";
import ClientOptions from "../../components/client/ClientOptions";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import he from "he";
import {formatPhoneNumber} from "../../utils/phone/phoneFormatter";
import {handleWhatsAppClick} from "../../utils/handlers/handler";
import {useTranslation} from "react-i18next";
import {selectLoading, selectUser} from "../../store/user/userSelector";

const Client = () => {
    const {t} = useTranslation();
    const {id, type} = useParams()
    const dispatch = useDispatch()
    const navigate = useNavigate();
    const client = useSelector(selectSelectedClient)
    const user = useSelector(selectUser)
    const [searchParams] = useSearchParams();
    const [page, setPage] = useState(type ?? "1");
    const [limitReached, setLimitReached] = useState(false);
    const clientCount = useSelector(selectClientCount)
    const loading = useSelector(selectLoading)

    useComponentTranslations('clientComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleClientStatusChange = (status) => {
        const data = {
            id: client.id,
            status: status
        }
        dispatch(changeStatus(data))
    }

    const changePages = (pageName) => {
        setPage(pageName);
    };

    const handleGoBack = () => {
        if (searchParams.get("goBackTo") === "updates") {
            navigate("/user/update")
        } else
            navigate("/user/client/list")
    }

    useEffect(() => {
        dispatch(fetchClient(id))
    }, [id, dispatch]);

    useEffect(() => {
        if (user && clientCount) {
            if (user.tipoPlano !== 200 || !user.subPlan.unlimited) {
                const total = Number(clientCount.status_0 || 0) + Number(clientCount.status_1 || 0);
                if (total >= user.plano) {
                    setLimitReached(true)
                }
            }
        }
    }, [user, clientCount, dispatch])

    useEffect(() => {
        return () => dispatch(setClient(null))
    }, [dispatch])


    if (!client)
        return null;

    return (
        <>
            <AvatarHeader showGoBack={handleGoBack} md={"8"} lg={"6"} xl={"4"} className={"pb-4 pt-2 "}
                          text={`${client?.nome} ${client?.sobrenome}`}
                          url={client.profileUrl}>
                <span className={"d-block mt-n1 fw-lighter"}>{client.grupo?.nome}</span>
            </AvatarHeader>
            <Page contentHeader={false} loading={loading} md={"8"} lg={"6"} xl={"4"}>
                {
                    client.status === 2 &&
                    <>
                        <div className={'row '}>
                            <div className={'col-12'}>
                                <div className={'card card-body border-0'}>
                                    <div className={'row'}>
                                        <div className={"col-9"}>
                                            <span className={'fw-bold d-block fs-4'}>{he.decode(client.nome)}</span>
                                            <span className={'d-block'}><i className={"fa-regular fa-calendar"}></i> {client.mail}</span>
                                            {
                                                formatPhoneNumber(client.telefone) &&
                                                <span className={' d-block  clickable-element '}
                                                      onClick={() => handleWhatsAppClick(`${client.telefone}`)}><i
                                                    className={"fa-brands fa-whatsapp"}></i> {formatPhoneNumber(client.telefone)}</span>
                                            }
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className={'row pt-4'}>
                            <div className={'col-12'}>
                                <div className={'card card-body bg-danger-subtle border-0'}>
                                    <div className={'row'}>
                                        <div className={'col-2 text-center text-danger align-self-center'}>
                                            <span><i className={'fa-regular fa-circle-exclamation fa-2xl'}></i></span>
                                        </div>
                                        <div className={'col-10  ps-0'}>
                                            <span className={'fw-semibold d-block '}>
                                                {t("clientComponent:headsUp")}
                                            </span>
                                            <span className={' d-block'}>
                                                {t("clientComponent:clientDeleted")}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                                {
                                    user && (user.tipoPlano === 200 || user.tipoPlano >= 1000) && !limitReached &&
                                    <div className={'col-12 pt-3'}>
                                        <div className={'d-grid'}>
                                            <button className={'btn btn-primary-darker'}
                                                    onClick={() => handleClientStatusChange(0)}>{t("clientComponent:recoverClient")}</button>
                                        </div>
                                    </div>
                                }
                            </div>
                        </div>
                    </>
                }
                {
                    client.status !== 2 &&
                    <>
                        <Tabs page={page} button1Text={t("clientComponent:start")} button2Text={t("clientComponent:options")} mt={"mt-n4"}
                              buttonClick={changePages}/>
                        {
                            page === "1" ?
                                <ClientStart client={client}/> :
                                <ClientOptions client={client}/>
                        }
                    </>
                }
            </Page>
        </>
    )
}

export default Client;