import moment from "moment/moment";
import {useDispatch, useSelector} from "react-redux";
import {selectBanners, selectUser} from "../../store/user/userSelector";
import {useEffect, useMemo, useState} from "react";
import UserStart from "../../components/user/UserStart";
import UserFinances from "../../components/user/UserFinances";
import {useNavigate, useSearchParams} from "react-router-dom";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Tabs from "../../components/tab/Tabs";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {fetchBanners} from "../../store/user/userReducer";
import Cookies from "js-cookie";
import {getMainDomain} from "../../utils/cookie/cookieUtils";
import Banner from "../../components/banner/Banner";
import WootricWidget from "../../utils/wootric/WootricWidget";
import {setClient} from "../../store/client/clientReducer";
import ContestCountdown from "../../components/temp-components/ContestCountDown";

const User = () => {
    const {t} = useTranslation();
    const [searchParams] = useSearchParams();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const user = useSelector(selectUser)
    const [page, setPage] = useState("1")
    const banners = useSelector(selectBanners)
    const [showBanner, setShowBanner] = useState(false);

    useComponentTranslations('user', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const getCurrentSalutation = () => {
        const now = moment();
        const hour = now.hour();

        if (hour > 5 && hour < 13) {
            return t("user:goodMorning");
        }

        if (hour >= 13 && hour < 19) {
            return t("user:goodAfternoon");
        }

        if (hour >= 19 && hour <= 23) {
            return t("user:goodEvening");
        }

        return t("user:hello");
    }

    const formatFirstName = (fullName) => {
        if (!fullName)
            return '';
        const names = fullName.trim().split(' ');
        const firstName = names[0];
        if (!firstName)
            return '';
        return firstName.charAt(0).toUpperCase() + firstName.slice(1).toLowerCase();
    }

    const handleShowBanner = () => {
        setShowBanner(prev => !prev)
    }

    const randomBanner = useMemo(() => {
        if (!banners || banners.length === 0) return null;
        const randomIndex = Math.floor(Math.random() * banners.length);
        return banners[randomIndex];
    }, [banners]);

    const goToProfile = () => {
        navigate("/user/profile")
    }

    const changePages = (pageName) => {
        setPage(pageName)
    }

    useEffect(() => {
        if (!Cookies.get("bannerHidden")) {
            dispatch(fetchBanners())
        } else {
            const mainDomain = getMainDomain();
            Cookies.set("bannerHidden", true, {expires: 1 / 24, path: '/', domain: `.${mainDomain}`})
        }
    }, [dispatch]);

    useEffect(() => {
        if (randomBanner && !Cookies.get("hideBanner")) {
            handleShowBanner()
        }
    }, [randomBanner])


    useEffect(() => {
        if (searchParams.get("type")) {
            setPage(searchParams.get("type"))
        }
    }, [searchParams])

    useEffect(() => {
        dispatch(setClient(null))
    }, [dispatch]);

    return (
        <>
            <WootricWidget/>


            {/*{*/}
            {/*    user.tipoPlano >= 1000 && !user.language.includes("pt") &&*/}
            {/*    <div className={`row justify-content-evenly bg-default m-0`}>*/}
            {/*        <div className={'col-12 col-md-6  col-lg-6 col-xl-4'}>*/}
            {/*            <ExerciseNameCard language={user.language}/>*/}
            {/*        </div>*/}
            {/*    </div>*/}
            {/*}*/}
            {/*    <div className={`row justify-content-evenly bg-default m-0 pb-4 pt-2`}>*/}
            {/*        <div className={'col-12 col-md-6  col-lg-6 col-xl-4'}>*/}
            {/*            <div className={"card card-body bg-warning-subtle border-0"}>*/}
            {/*                <div className={"row"}>*/}
            {/*                    <div className={"col-2 text-center align-self-center"}>*/}
            {/*                        <RoundedIcon icon={"fa-regular fa-triangle-exclamation"} textColor={"text-warning"} bgColor={"bg-white"}/>*/}
            {/*                    </div>*/}
            {/*                    <div className={"col-10  "}>*/}
            {/*                        <span className={"d-block fw-semibold fs-5"}>Atenção!</span>*/}
            {/*                        <span className={"d-block text-md"}>O app está passando por uma <span className={"fw-semibold"}>instabilidade na parte de pagamentos</span>, por favor aguarde nossas atualizações</span>*/}
            {/*                    </div>*/}
            {/*                </div>*/}
            {/*            </div>*/}
            {/*        </div>*/}
            {/*    </div>*/}
            <ContestCountdown/>
            <AvatarHeader url={user.urlLogo} text={`${getCurrentSalutation()} ${formatFirstName(user.nome)}`} className={"pb-2"} avatarClick={goToProfile}/>

            <div className={`row justify-content-evenly bg-default m-0`}>
                <div className={'col-12 col-md-6  col-lg-6 col-xl-4'}>
                    <Tabs page={page} button1Text={t("user:button1Text")} button2Text={t("user:button2Text")} buttonClick={changePages}/>
                </div>
            </div>
            <Page contentHeader={false} mt={"mt-n2"}>
                {
                    page === "1" ?
                        <UserStart/> :
                        <UserFinances/>
                }
            </Page>
            {
                randomBanner && showBanner &&
                <Banner banner={randomBanner} handleShowBanner={handleShowBanner}/>
            }
        </>
    )
}
export default User;