import ItemListIcon from "../list/ItemListIcon";
import {mfitUrl} from "../../utils/handlers/handler";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {changeStatus, fetchClientInvoices, setClientInvoices} from "../../store/client/clientReducer";
import {useDispatch, useSelector} from "react-redux";
import {useSearchParams} from "react-router-dom";
import {selectClientInvoices} from "../../store/client/clientSelector";
import {useEffect, useState} from "react";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import 'moment/locale/pt-br';
import Cookies from "js-cookie";
import ClientLoginInformation from "./ClientLoginInformation";
import ClientNoteCard from "./ClientNoteCard";
import {selectWeeklyFrequency} from "../../store/frequency-training/frequencyTrainingSelector";
import {fetchWeeklyFrequency, setWeeklyFrequency} from "../../store/frequency-training/frequencyTrainingReducer";
import FrequencyTraining from "../frequency-training/FrequencyTraining";
import {
    buildClientEvaluationRoute,
    buildClientExtraTrainingRoute,
    buildClientFilesRoute,
    buildClientProgressRoute,
    buildClientWorkoutRoute
} from "../../utils/client/clientRoutes";

const ClientStart = ({client}) => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const invoices = useSelector(selectClientInvoices)
    const frequencyTraining = useSelector(selectWeeklyFrequency)
    const [show, setShow] = useState(false)
    const [showPassword, setShowPassword] = useState(false);
    const [searchParams, setSearchParams] = useSearchParams();
    syncMomentLocale(i18n.language);
    useComponentTranslations('clientComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoToTrainingClick = buildClientWorkoutRoute(client.id);

    const handleClientEvaluationClick = buildClientEvaluationRoute(client.id);

    const handleExtraTrainingClick = buildClientExtraTrainingRoute(client.id);

    const handleClientProgressClick = buildClientProgressRoute(client.id);

    const handleFinancialClick = `${mfitUrl}/index?acao=planosAluno&tipo=1&al=${client.id}&goBackToNewAppClient=${client.id}`

    const handleFilesClick = buildClientFilesRoute(client.id);

    const handleExpandCardClick = () => {
        setShow(prevState => !prevState)
    }

    const handleClientStatusChange = (status) => {
        const data = {
            id: client.id,
            status: status
        }
        dispatch(changeStatus(data))
    }

    const handleShowLoginInfo = () => {
        setShowPassword(prevState => !prevState)
    }


    useEffect(() => {
        const currentDate = moment();
        const start = currentDate.clone().startOf('isoWeek'); // 'isoWeek' starts on Monday
        const end = currentDate.clone().endOf('isoWeek');
        const formattedStart = start.format('YYYY-MM-DDTHH:mm:ss');
        const formattedEnd = end.format('YYYY-MM-DDTHH:mm:ss');

        const payload = {
            id: client.id,
            startDate: encodeURIComponent(formattedStart),
            endDate: encodeURIComponent(formattedEnd)
        }
        dispatch(fetchWeeklyFrequency(payload))
        return () => dispatch(setWeeklyFrequency(null))
    }, [dispatch, client]);

    useEffect(() => {
        if (client?.id) {
            dispatch(fetchClientInvoices(client.id))
        }
        return () => dispatch(setClientInvoices(null))
    }, [dispatch, client]);


    useEffect(() => {
        if (searchParams.get("showPassword")) {
            setShowPassword(true)
            const newSearchParams = new URLSearchParams(searchParams.toString());
            newSearchParams.delete("showPassword");
            setSearchParams(newSearchParams);
        }
    }, [searchParams, setSearchParams]);

    return (
        <>
            {
                Object.keys(invoices || {}).length > 0 &&
                <div className={"card card-body bg-secondary-subtle border-0 mt-3"}>
                    <div className={'row clickable-element'} onClick={handleExpandCardClick}>
                        <div className={'col-1'}>
                            <RoundedIcon size={"xs"} icon={"fa-bell-on"} bgColor={"bg-primary"} textColor={"text-white"}/>
                        </div>
                        <div className={"col-9 align-self-center ps-4"}>
                            <span className={"fw-semibold"}>{t("clientComponent:clientInvoices")}</span>
                        </div>
                        <div className={'col-2 text-center  align-self-center'}>
                            {
                                show ?
                                    <i className={'fa-regular fa-chevron-up'}></i> :
                                    <i className={'fa-regular fa-chevron-down'}></i>
                            }
                        </div>
                    </div>
                    {
                        show &&
                        <div className={"row mt-3 "}>
                            <div className={'col-12'}>
                                {
                                    invoices && Object.entries(invoices).map(([key, invoice]) => (
                                        <div key={key} className="card card-body mb-2 border-0 clickable-element" onClick={() => handleFinancialClick(client.id)}>
                                            <div className="row">
                                                <div className="col-2 align-self-center">
                                                    <RoundedIcon size="sm" icon="fa-wallet"/>
                                                </div>
                                                <div className="col-10 ps-0">
                                                    <div className="row">
                                                        <div className="col-12">
                                                            {
                                                                key === "0" ?
                                                                    <span className="fw-semibold d-block">{t("clientComponent:pastDueInvoice")}</span> :
                                                                    <span className="fw-semibold d-block">{t("clientComponent:expiringInvoice")}</span>
                                                            }
                                                        </div>
                                                        <div className="col-12">
                                                            <span className="fw-semibold">{t("clientComponent:amount")}: </span>
                                                            <CurrencyFormatter value={invoice.amount}/>
                                                        </div>
                                                        <div className="col-12">
                                                            <span className="fw-semibold">{t("clientComponent:dueDate")}: </span>
                                                            {moment({
                                                                year: invoice.dueDate.year,
                                                                month: invoice.dueDate.month - 1,
                                                                day: invoice.dueDate.day,
                                                            }).format('L')}
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                }
                            </div>
                        </div>
                    }
                </div>
            }
            <FrequencyTraining frequencyTraining={frequencyTraining} client={client}/>
            <div className={"card card-body mt-3 border-0 mb-3"}>
                <div className={'row  '}>
                    <div className={'col-12'}>
                        {
                            client.status === 1 &&
                            <div className={'card card-body bg-warning-subtle border-0 mb-4'}>
                                <div className={'row'}>
                                    <div className={'col-2 text-center text-warning-darker align-self-center'}>
                                        <span><i className={'fa-regular fa-circle-exclamation fa-2xl'}></i></span>
                                    </div>
                                    <div className={'col-10 ps-0'}>
                                        <span className={'fw-semibold d-block '}>
                                          {t("clientComponent:headsUp")}
                                        </span>
                                        <span className={' d-block'}>
                                            {t("clientComponent:thisClientDoesntHaveAccess")}
                                        </span>
                                    </div>
                                    <div className={"col-12"}>
                                        <hr className={"text-warning-darker m-2"}/>
                                    </div>
                                    <div className={'col-12  '}>
                                        <div className={'row justify-content-between'}>
                                            <div className={'col-auto ps-4'}>
                                                <span className={"fw-semibold"}>{t("clientComponent:status")}</span>
                                            </div>
                                            <div className={'col-auto text-center pe-4'}>
                                                <div className="form-check form-switch">
                                                    <input className="form-check-input" type="checkbox" id="flexSwitchCheckDefault"
                                                           onChange={() => handleClientStatusChange(0)}
                                                           defaultChecked={client.status === 0}
                                                    />
                                                    <label htmlFor="flexSwitchCheckDefault">{t("clientComponent:inactive")}</label>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                </div>
                <div className={'row'}>
                    <div className={'col-12'}>
                        <ItemListIcon icon={"fa-dumbbell"} size={"sm"} to={handleGoToTrainingClick} text={t("clientComponent:training")}/>
                        <ItemListIcon icon={"fa-clipboard-list"} size={"sm"} to={handleClientEvaluationClick}
                                      text={t("clientComponent:evaluations")}/>
                        {
                            !Cookies.get("isApple") &&
                            <ItemListIcon icon={"fa-dollar-sign"} size={"sm"} to={handleFinancialClick}
                                          text={t("clientComponent:finances")}/>
                        }
                        <ItemListIcon icon={"fa-clipboard-check"} size={"sm"} to={handleClientProgressClick}
                                      text={t("clientComponent:clientProgress")}/>
                        <ItemListIcon icon={"fa-file-plus"} size={"sm"} to={handleExtraTrainingClick}
                                      text={t("clientComponent:extraTraining")}/>
                        <ItemListIcon icon={"fa-box-archive"} size={"sm"} to={handleFilesClick} text={t("clientComponent:files")}/>
                    </div>
                </div>
            </div>
            <ClientNoteCard id={client.id}/>
            {
                showPassword &&
                <ClientLoginInformation client={client} handleShowLoginInfo={handleShowLoginInfo} showLoginInfo={showPassword}/>

            }
        </>
    )
}
export default ClientStart;
