import he from "he";
import {getRetentionStatusMeta} from "./retentionConfig";
import Avatar from "../avatar/Avatar";

const RetentionClientCard = ({
    client,
    expanded,
    onToggle,
    onNotify,
    onWhatsApp,
    onViewProfile,
    tourTarget,
    expandedTourTarget,
    t
}) => {
    const statusMeta = getRetentionStatusMeta(client.status, t);
    const clientName = he.decode(client.name || "");

    return (
        <div className={"card border mb-2"} data-tour={tourTarget}>
            <div className={"card-body p-3"}>
                <div className={"row g-2 align-items-center flex-nowrap"}>
                    <div className={"col-auto"}>
                        <Avatar url={client.profileUrl} maxWidth={"48px"} blueBorder={true} borderWidth={2}/>
                    </div>
                    <div className={"col overflow-hidden"}>
                        <span className={"d-block fw-semibold text-truncate"} title={clientName}>{clientName}</span>
                        {!expanded && (
                            <span className={"small text-secondary d-block mt-1"}>
                                {client.daysSinceLastWorkout} {t("retention:daysWithoutWorkout")}
                            </span>
                        )}
                    </div>
                    <div className={"col-auto"}>
                        <div className={"d-flex align-items-center justify-content-end gap-2"}>
                            <span className={`badge rounded-pill fw-normal ${statusMeta.badgeClass}`}>
                                {statusMeta.label}
                            </span>
                            <button className={"btn btn-link text-default text-decoration-none p-0"} onClick={() => onToggle(client.id)}>
                                <i className={`fa-regular ${expanded ? "fa-chevron-up" : "fa-chevron-down"}`}></i>
                            </button>
                        </div>
                    </div>
                </div>

                {expanded && (
                    <div className={"row g-2 mt-3"} data-tour={expandedTourTarget}>
                        <div className={"col-6"}>
                            <div className={"card card-body border-0 bg-secondary-subtle h-100 p-2"}>
                                <span className={"small text-secondary d-block"}>{t("retention:lastWorkout")}</span>
                                <span className={"fw-semibold"}>{client.daysSinceLastWorkout} {t("retention:days")}</span>
                            </div>
                        </div>
                        <div className={"col-6"}>
                            <div className={"card card-body border-0 bg-secondary-subtle h-100 p-2"}>
                                <span className={"small text-secondary d-block"}>{t("retention:averageFrequency")}</span>
                                <span className={"fw-semibold"}>{client.avgWeeklyWorkouts || 0}x {t("retention:perWeek")}</span>
                            </div>
                        </div>
                        <div className={"col-12 d-grid mt-2"}>
                            <button className={"btn btn-primary"} onClick={() => onNotify(client)}>
                                <i className={"fa-regular fa-paper-plane me-2"}></i>
                                {t("retention:sendNotification")}
                            </button>
                        </div>
                        <div className={"col-12 d-grid"}>
                            <button className={"btn btn-success-darker text-white"} onClick={() => onWhatsApp(client)}>
                                <i className={"fa-brands fa-whatsapp me-2"}></i>
                                {t("retention:chatOnWhatsApp")}
                            </button>
                        </div>
                        <div className={"col-12 text-center mt-2"}>
                            <button className={"btn btn-link fw-semibold text-decoration-none"} onClick={() => onViewProfile(client)}>
                                {t("retention:viewProfile")}
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default RetentionClientCard;
