import {all, call, put, takeLatest} from 'redux-saga/effects';
import {
    changeWorkoutRoutineStatusAPI,
    cloneSessionsToRoutinesAPI,
    createWorkoutRoutineAPI,
    createWorkoutSessionAPI,
    deleteWorkoutSessionAPI,
    fetchWorkoutRoutineByIdAPI,
    getAllWorkoutsRoutinesByStatusAPI,
    getFeedbacksFromRoutineAPI, getProgressBySessionAPI,
    getRoutinesToCloneSessionToAPI,
    updateWorkoutRoutineAPI,
    updateWorkoutSessionAPI,
    updateWorkoutSessionOrderAPI
} from "../../api/workout-routine/workoutRoutineActions";
import {
    fetchWorkoutRoutinesByStatus,
    setWorkouts,
    onError,
    changeWorkoutRoutineStatusSuccess,
    changeWorkoutRoutineStatus,
    createWorkoutRoutine,
    setWorkout,
    fetchWorkoutRoutine,
    updateRoutineSuccess,
    updateRoutine,
    sessionCreated,
    createSession,
    sessionUpdated,
    updateSession,
    deleteSession,
    changeWorkoutSessionOrder,
    fetchRoutinesToCloneSessions,
    cloneSessionsToRoutine,
    cloneSessionsToRoutineSuccess,
    setWorkoutCreated,
    setFeedbacks, fetchFeedbacks, fetchWorkoutProgress, setWorkoutProgress
} from "./workoutRoutineReducer";
import {handleError} from "../../utils/error/sagaErrorHandling";

export function* fetchWorkoutRoutinesByStatusAsync(action) {
    try {
        const {id, status} = action.payload
        const response = yield call(getAllWorkoutsRoutinesByStatusAPI, id, status)
        yield put(setWorkouts(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchWorkoutRoutinesByStatus() {
    yield takeLatest(fetchWorkoutRoutinesByStatus.type, fetchWorkoutRoutinesByStatusAsync)
}

export function* changeWorkoutRoutineStatusAsync(action) {
    try {
        const {id, status} = action.payload
        yield call(changeWorkoutRoutineStatusAPI, id, status)
        yield put(changeWorkoutRoutineStatusSuccess(id))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onChangeWorkoutRoutineStatus() {
    yield takeLatest(changeWorkoutRoutineStatus.type, changeWorkoutRoutineStatusAsync)
}

export function* fetchWorkoutRoutineAsync(action) {
    try {

        const response = yield call(fetchWorkoutRoutineByIdAPI, action.payload)
        yield put(setWorkout(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchWorkoutRoutine() {
    yield takeLatest(fetchWorkoutRoutine.type, fetchWorkoutRoutineAsync)
}

export function* updateWorkoutRoutineAsync(action) {
    try {
        yield call(updateWorkoutRoutineAPI, action.payload)
        yield put(updateRoutineSuccess(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateWorkoutRoutine() {
    yield takeLatest(updateRoutine.type, updateWorkoutRoutineAsync)
}

export function* createWorkoutRoutineAsync(action) {
    try {
        const response = yield call(createWorkoutRoutineAPI, action.payload)
        yield put(setWorkout(response.data))
        yield put(setWorkoutCreated(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreateWorkoutRoutine() {
    yield takeLatest(createWorkoutRoutine.type, createWorkoutRoutineAsync)
}

export function* createWorkoutSessionAsync(action) {
    try {
        const response = yield call(createWorkoutSessionAPI, action.payload)
        yield put(sessionCreated(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreateWorkoutSession() {
    yield takeLatest(createSession.type, createWorkoutSessionAsync)
}

export function* updateWorkoutSessionAsync(action) {
    try {
        const response = yield call(updateWorkoutSessionAPI, action.payload)
        yield put(sessionUpdated(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateWorkoutSession() {
    yield takeLatest(updateSession.type, updateWorkoutSessionAsync)
}


export function* deleteWorkoutSessionAsync(action) {
    try {
        yield call(deleteWorkoutSessionAPI, action.payload)
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDeleteWorkoutSession() {
    yield takeLatest(deleteSession.type, deleteWorkoutSessionAsync)
}

export function* updateWorkoutSessionOrderAsync(action) {
    try {
        yield call(updateWorkoutSessionOrderAPI, action.payload)
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onChangeWorkoutSessionOrder() {
    yield takeLatest(changeWorkoutSessionOrder.type, updateWorkoutSessionOrderAsync)
}

export function* fetchRoutinesToCloneSessionsAsync(action) {
    try {
        const {library, clientId} = action.payload
        const response = yield call(getRoutinesToCloneSessionToAPI, library, clientId)
        yield put(setWorkouts(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchRoutinesToCloneSessions() {
    yield takeLatest(fetchRoutinesToCloneSessions.type, fetchRoutinesToCloneSessionsAsync)
}


export function* cloneSessionsToRoutinesAsync(action) {
    try {
        yield call(cloneSessionsToRoutinesAPI, action.payload)
        yield put(cloneSessionsToRoutineSuccess(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCloneSessionsToRoutines() {
    yield takeLatest(cloneSessionsToRoutine.type, cloneSessionsToRoutinesAsync)
}

export function* fetchFeedbacksAsync(action) {
    try {
        const response = yield call(getFeedbacksFromRoutineAPI, action.payload)
        yield put(setFeedbacks(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchFeedbacks() {
    yield takeLatest(fetchFeedbacks.type, fetchFeedbacksAsync)
}

export function* fetchWorkoutProgressAsync(action) {
    try {
        const response = yield call(getProgressBySessionAPI, action.payload)
        yield put(setWorkoutProgress(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchWorkoutProgress() {
    yield takeLatest(fetchWorkoutProgress.type, fetchWorkoutProgressAsync)
}

export function* workoutRoutineSaga() {
    yield all([
        call(onFetchWorkoutRoutinesByStatus),
        call(onChangeWorkoutRoutineStatus),
        call(onCreateWorkoutRoutine),
        call(onFetchWorkoutRoutine),
        call(onUpdateWorkoutRoutine),
        call(onCreateWorkoutSession),
        call(onUpdateWorkoutSession),
        call(onDeleteWorkoutSession),
        call(onChangeWorkoutSessionOrder),
        call(onFetchRoutinesToCloneSessions),
        call(onCloneSessionsToRoutines),
        call(onFetchFeedbacks),
        call(onFetchWorkoutProgress)
    ])
}
