import {useNavigate, useParams} from "react-router-dom";
import React, {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {
    fetchSession,
    setPreview,
    setWorkoutStarted
} from "../../store/workout-session/workoutSessionReducer";

import Text from "../../components/utils/emoji/Text";
import WorkoutExercise from "../../components/workout-session/WorkoutExercise";
import _ from "lodash";
import Modal from "react-bootstrap/Modal";
import WorkoutSessionFeedbackForm from "../../components/workout-session/WorkoutSessionFeedbackForm";
import moment from "moment";
import WorkoutTimer from "../../components/workout-session/WorkoutTimer";
import {isMobile} from "react-device-detect";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json"
import {useTranslation} from "react-i18next";
import Page from "../../components/page/Page";
import {getPreview, isWorkoutLoading, selectWorkoutSession} from "../../store/workout-session/workoutSessionSelector";

const WorkoutSession = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const {sessionId} = useParams();
    const dispatch = useDispatch();
    const loading = useSelector(isWorkoutLoading);
    const session = useSelector(selectWorkoutSession);
    const isPreview = useSelector(getPreview);
    const [showModalEndTraining, setShowModalEndTraining] = useState(false);
    const [workoutStartedState, setWorkoutStartedState] = useState(null);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const goBack = () => {
        navigate(`/user/client/${session.client_id}/workout/routine/${session.routine_id}/session/${session.id}/prescribe`)
    }

    const restartTraining = () => {
        dispatch(setPreview(true));
        localStorage.removeItem("workoutStarted_" + session.id);
    }
    const handleStartTraining = () => {
        dispatch(setPreview(false));
        const workoutStarted = moment();
        localStorage.setItem("workoutStarted_" + sessionId, workoutStarted.toString());
        dispatch(setWorkoutStarted(workoutStarted.toString()));
        setWorkoutStartedState(workoutStarted);
    }

    const handleModalEndTraining = () => {
        setShowModalEndTraining(prevShowModalEndTraining => !prevShowModalEndTraining);
    }

    useEffect(() => {
        dispatch(fetchSession(sessionId));
        const storedWorkoutStarted = localStorage.getItem('workoutStarted_' + sessionId);
        const workoutStarted = storedWorkoutStarted ? moment(storedWorkoutStarted) : null;

        if (workoutStarted && workoutStarted.isValid()) {
            const maxEndDate = workoutStarted.clone().add(3, 'hours');
            const now = moment();
            if (now.isSameOrAfter(maxEndDate)) {
                localStorage.removeItem("workoutStarted_" + sessionId);
                setWorkoutStartedState(null);
                dispatch(setPreview(true));
            } else {
                setWorkoutStartedState(workoutStarted);
                dispatch(setPreview(false));
            }
        } else {
            dispatch(setPreview(true));
        }
    }, [dispatch, sessionId]);

    useEffect(() => {
        if (isPreview && isMobile) {
            const handleScroll = () => {
                const scrollTop = window.scrollY;
                const targetElement = document.getElementById("targetElement");

                if (scrollTop >= 80) {
                    targetElement?.classList.add("fixed-top");
                    targetElement?.classList.add("training-top");
                } else {
                    targetElement?.classList.remove("fixed-top");
                    targetElement?.classList.remove("training-top");
                }
            };

            window.addEventListener('scroll', handleScroll);

            return () => {
                window.removeEventListener('scroll', handleScroll);
            };
        }
    }, [isPreview]);


    return (
        <Page title={<Text className={'d-block fw-semibold'}>{session?.nome}</Text>} goBackLink={goBack} loading={loading}>
            {
                session &&
                <>
                    <div className={'row justify-content-center d-flex '}>
                        <div id={"targetElement"}>
                            {
                                isPreview &&
                                <div className={'row justify-content-center d-flex bg-primary '}>
                                    <div className={'col-10 pt-4 pb-2'}>
                                        <div className={'d-grid'}>
                                            <button className={'btn btn-success text-white   btn-sm-caps'}
                                                    onClick={handleStartTraining}>
                                                {t("workout:start")}
                                            </button>
                                        </div>
                                    </div>
                                    <div className={'col-12  fw-semibold text-white pb-4 pt-1'}>
                                        <span
                                            className={'d-block text-center small'}>{t("workout:workoutViewMode")}</span>
                                        <span
                                            className={'d-block text-center lh-1 small'}>{t("workout:trainingMode")}</span>
                                    </div>
                                </div>
                            }
                            {
                                !isPreview &&
                                <div className={'card card-body  card-no-border mb-2'}>
                                    <div className={'row justify-content-center d-flex'}>
                                        <div className={'col-12'}>
                                            <div className={'d-grid'}>
                                                <span className={'btn btn-default-darker   text-white '}>
                                                    <i className={'fa-regular fa-clock'}></i>&nbsp;
                                                    <WorkoutTimer
                                                        workoutStarted={workoutStartedState}/>
                                                </span>
                                            </div>
                                            <div className={'d-grid mt-2'}>
                                                <button className={'btn btn-outline-primary-darker '}
                                                        onClick={restartTraining}>{t("workout:restartTraining")} </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            }
                        </div>
                    </div>
                    {
                        _.map(session.exercs, (exerc, index) => (
                            <div key={exerc.id} className={'row justify-content-center d-flex'}>
                                <div className="col-12  pt-2">
                                    <WorkoutExercise index={index} exerc={exerc}/>
                                </div>
                            </div>
                        ))
                    }
                    {
                        !isPreview &&
                        <>
                            <div className={'row justify-content-center d-flex pt-4'}>
                                <div className="col-12 col-md-8 col-lg-6 col-xl-4 pt-2">
                                    <div className={'d-grid'}>
                                        <button className={'btn btn-primary-darker'} onClick={handleModalEndTraining}>
                                            {t("workout:endTraining")}
                                        </button>
                                    </div>
                                </div>
                            </div>
                            <Modal centered show={showModalEndTraining} onHide={handleModalEndTraining}>
                                <Modal.Body>
                                    <WorkoutSessionFeedbackForm
                                        handleModal={handleModalEndTraining}
                                        label1={t("workout:trainingStartDate")}
                                        label2={t("workout:trainingEndDate")}
                                        label3={t("workout:totalWorkoutTime")}
                                        session={session}
                                    />
                                </Modal.Body>
                            </Modal>
                        </>
                    }
                </>
            }
        </Page>
    )
}
export default WorkoutSession;