import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    session: null,
    seriesUpdating: false,
    seriesUpdated: false,
    exercisesLoading: false,
    loadingExerciseId: null,
    seriesReplicated: false,
    exerciseReplaced: false,
    descriptionUpdating: false,
    generatingWorkout: false,
    loading: false
};

export const slice = createSlice({
    name: "workoutPrescription",
    initialState,
    reducers: {
        generateWorkout(state) {
            state.generatingWorkout = true
        },
        setGeneratingWorkout(state, action) {
            state.generatingWorkout = action.payload
        },
        fetchWorkoutSession(state) {
            state.loading = true
        },
        setWorkoutSession(state, action) {
            state.loading = false
            state.session = action.payload
        },
        updateSessionDescription(state) {
            state.descriptionUpdating = true
        },
        sessionDescriptionUpdated(state, action) {
            state.descriptionUpdating = false
            state.session.obs = action.payload.obs
        },
        addAlternativeExercise(state, action) {
            state.exercisesLoading = true
            state.loadingExerciseId = action.payload?.newExerc || null
        },
        addAlternativeExerciseSuccess(state, action) {
            state.exercisesLoading = false
            state.loadingExerciseId = null
            state.session = action.payload
            state.exerciseReplaced = true
        },
        promoteExercise(state) {
            state.exercisesLoading = true
            state.loadingExerciseId = null
        },
        promoteExerciseSuccess(state, action) {
            state.exercisesLoading = false
            state.loadingExerciseId = null
            state.session = action.payload
        },
        replaceExerciseSerie(state, action) {
            state.exercisesLoading = true
            state.loadingExerciseId = action.payload?.newExerc || null
        },
        replaceExerciseSerieSuccess(state, action) {
            state.exercisesLoading = false
            state.loadingExerciseId = null
            state.session = action.payload
            state.exerciseReplaced = true
        },
        replaceExercise(state, action) {
            state.exercisesLoading = true
            state.loadingExerciseId = action.payload?.newExerc || null
        },
        replaceExerciseSuccess(state, action) {
            state.exercisesLoading = false
            state.loadingExerciseId = null
            state.session = action.payload
            state.exerciseReplaced = true
        },
        setExerciseReplaced(state, action) {
            state.exerciseReplaced = action.payload
        },
        splitExercises(state) {
            state.exercisesLoading = true
            state.loadingExerciseId = null
        },
        splitExercisesSuccess(state, action) {
            state.exercisesLoading = false
            state.loadingExerciseId = null
            state.session = action.payload
        },
        combineExercises(state) {
            state.exercisesLoading = true;
            state.loadingExerciseId = null;
        },
        combineExercisesSuccess(state, action) {
            state.exercisesLoading = false;
            state.loadingExerciseId = null;
            state.session = action.payload
        },
        changeExerciseOrder(state, action) {
            const {idExercSession, pos} = action.payload || {};
            if (!state.session?.exerciciosMontados) return;

            const map = state.session.exerciciosMontados;
            const entries = Object.entries(map);

            const oldIndex = entries.findIndex(([, arr]) =>
                arr[0]?.idExercSession === idExercSession
            );
            if (oldIndex === -1) return;

            const [moved] = entries.splice(oldIndex, 1);
            entries.splice(pos, 0, moved);

            state.session.exerciciosMontados = entries.reduce((acc, [k, v]) => {
                acc[k] = v;
                return acc;
            }, {});
        },
        replicateSeries(state) {
            state.seriesUpdating = true
        },
        replicateSeriesSuccess(state, action) {
            state.seriesReplicated = true
            state.seriesUpdating = false
            state.session = action.payload
        },
        setSeriesReplicated(state, action) {
            state.seriesReplicated = action.payload
        },
        createExerciseAsSerie(state) {
            state.seriesUpdating = true
        },
        createSerie(state) {
            state.seriesUpdating = true
        },
        createSerieSuccess(state, action) {
            const newSerie = action.payload;
            const map = state.session.exerciciosMontados;
            let targetExercise = null;
            for (const key of Object.keys(map)) {
                const exercise = map[key].find(
                    ex => ex.idExercSession === newSerie.idExercSession
                );
                if (exercise) {
                    targetExercise = exercise;
                    break;
                }
            }
            if (targetExercise) {
                if (!targetExercise.series) targetExercise.series = [];
                targetExercise.series.push(newSerie);
            } else {
                const sessionKey = `k${newSerie.idExercSession}`;
                map[sessionKey] = [
                    {
                        id: 0,
                        idExercSession: newSerie.idExercSession,
                        series: [newSerie],
                    },
                ];
            }
            state.seriesUpdating = false;
            state.seriesUpdated = true;
        },
        setSerieUpdated(state, action) {
            state.seriesUpdated = action.payload
        },
        changeSeriesOrder(state, action) {
            const {seriesId, pos} = action.payload || {};
            if (!state.session?.exerciciosMontados) return;

            const map = state.session.exerciciosMontados;
            for (const key of Object.keys(map)) {
                for (const ex of map[key]) {
                    const list = ex.series;
                    if (!Array.isArray(list)) continue;
                    const idx = list.findIndex(s => s.id === seriesId);
                    if (idx !== -1) {
                        const [moved] = list.splice(idx, 1);
                        list.splice(pos, 0, moved);
                        return;
                    }
                }
            }
        },
        updateSerie(state) {
            state.seriesUpdating = true
        },
        updateSerieSuccess(state, action) {
            state.seriesUpdating = false;
            const updated = action.payload;
            const oldMap = state.session.exerciciosMontados;

            const groupKey = Object.keys(oldMap).find(key =>
                oldMap[key].some(ex => ex.idExercSession === updated.idExercSession)
            );
            if (!groupKey) {
                return;
            }

            const newGroup = oldMap[groupKey].map(ex => {
                if (ex.idExercSession !== updated.idExercSession) {
                    return ex;
                }
                return {
                    ...ex,
                    series: ex.series.map(s =>
                        s.id === updated.id
                            ? {...s, ...updated}
                            : s
                    )
                };
            });
            state.session = {
                ...state.session,
                exerciciosMontados: {
                    ...oldMap,
                    [groupKey]: newGroup
                }
            };
            state.seriesUpdated = true;
        },
        deleteSerie(state) {
            state.seriesUpdating = true
        },
        deleteSerieSuccess(state, action) {
            const serieIdToRemove = action.payload;
            Object.values(state.session.exerciciosMontados).forEach(exerciseList => {
                exerciseList.forEach(exercise => {
                    exercise.series = exercise.series.filter(s => s.id !== serieIdToRemove);
                });
            });
            state.seriesUpdating = false
        },
        addExerciseToSession(state, action) {
            state.exercisesLoading = true
            state.loadingExerciseId = action.payload?.exercise || null
        },
        exerciseAddedToSession(state, action) {
            state.session = action.payload
            state.exercisesLoading = false
            state.loadingExerciseId = null
        },
        deleteMultipleExercises(state){
            state.exercisesLoading = true
            state.loadingExerciseId = null
        },
        deleteMultipleExercisesSuccess(state, action){
            const ids = action.payload || [];
            const map = state.session.exerciciosMontados;
            ids.forEach(deletedSessionId => {
                const key = `k${deletedSessionId}`;
                if (map[key]) {
                    delete map[key];
                } else {
                    for (const sessionKey of Object.keys(map)) {
                        const arr = map[sessionKey];
                        const idx = arr.findIndex(ex => ex.idExercSession === deletedSessionId);
                        if (idx !== -1) {
                            arr.splice(idx, 1);
                            if (arr.length === 0) {
                                delete map[sessionKey];
                            }
                            break;
                        }
                    }
                }
            });
            state.exercisesLoading = false;
            state.loadingExerciseId = null;
        },
        deleteExerciseFromSession(state) {
            state.exercisesLoading = true
            state.loadingExerciseId = null
        },
        exerciseDeletedFromSession(state, action) {
            const deletedSessionId = action.payload;
            const map = state.session.exerciciosMontados;
            const key = `k${deletedSessionId}`;
            if (map[key]) {
                delete map[key];
            } else {
                for (const sessionKey of Object.keys(map)) {
                    const arr = map[sessionKey];
                    const idx = arr.findIndex(ex => ex.idExercSession === deletedSessionId);
                    if (idx !== -1) {
                        arr.splice(idx, 1);
                        if (arr.length === 0) {
                            delete map[sessionKey];
                        }
                        break;
                    }
                }
            }
            state.exercisesLoading = false;
            state.loadingExerciseId = null;
        },
        onError(state) {
            state.generatingWorkout = false
            state.loading = false
        }
    },
});

export const workoutPrescriptionReducer = slice.reducer

export const {
    fetchWorkoutSession,
    setWorkoutSession,
    changeExerciseOrder,
    changeSeriesOrder,
    updateSerie,
    updateSerieSuccess,
    deleteSerie,
    deleteSerieSuccess,
    addExerciseToSession,
    exerciseAddedToSession,
    deleteExerciseFromSession,
    exerciseDeletedFromSession,
    createSerie,
    createSerieSuccess,
    setSerieUpdated,
    replicateSeries,
    replicateSeriesSuccess,
    setSeriesReplicated,
    combineExercises,
    combineExercisesSuccess,
    splitExercises,
    splitExercisesSuccess,
    replaceExercise,
    replaceExerciseSuccess,
    setExerciseReplaced,
    replaceExerciseSerie,
    replaceExerciseSerieSuccess,
    createExerciseAsSerie,
    addAlternativeExercise,
    addAlternativeExerciseSuccess,
    updateSessionDescription,
    sessionDescriptionUpdated,
    promoteExercise,
    promoteExerciseSuccess,
    deleteMultipleExercises,
    deleteMultipleExercisesSuccess,
    generateWorkout,
    setGeneratingWorkout,
    onError
} = slice.actions