import {apiUrl, getToken} from "../api";
import axios from "axios";

export const summarizeAnamnesisAPI = async (id) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/ai/summarize-anamnesis?id=${id}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 20000
        })
}

