import LoadingBlock from "../loader/LoadingBlock";
import EmptySet from "../empty-set/EmptySet";
import OnlineEvaluationSelectCard from "./OnlineEvaluationSelectCard";
import React, {useCallback, useEffect, useMemo, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate} from "react-router-dom";
import {getLoading, getOnlineList} from "../../store/online-evaluation/evaluationOnlineSelector";
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import OnlineEvaluationSendModal from "./OnlineEvaluationSendModal";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import {getAllOnline, recoverEvaluation} from "../../store/online-evaluation/evaluationOnlineReducer";
import {useTranslation} from "react-i18next";
import OnlineEvaluationStartModal from "./OnlineEvaluationStartModal";
import {addToast} from "../../store/toast/toastReducer";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EvaluationCompareBarComponent from "../evaluation-components/EvaluationCompareBarComponent";
import {
    buildOnlineEvaluationChartsRoute,
    buildOnlineEvaluationCompareRoute,
    buildOnlineEvaluationDeletedRoute,
    buildOnlineEvaluationEditRoute,
    buildOnlineEvaluationViewRoute,
    buildOnlineEvaluationsRoute
} from "../../utils/client/evaluationRoutes";

const OnlineEvaluation = ({id}) => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const loading = useSelector(getLoading);
    const onlineList = useSelector(getOnlineList);
    const [currentEvaluation, setCurrentEvaluation] = useState(null);
    const [showStartModal, setShowStartModal] = useState(false);
    const [showOptionsModal, setShowOptionsModal] = useState(false);
    const [showEvaluationSendModal, setShowEvaluationSendModal] = useState(false);
    const [showEvaluationDeleteModal, setShowEvaluationDeleteModal] = useState(false);
    const [selectedEvaluation, setSelectedEvaluation] = useState([]);
    const [isComparing, setIsComparing] = useState(false);
    const MAX_SELECTION = 3;
    useComponentTranslations('evaluationOnlineComponents', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const toggleComparison = useCallback(() => {
        setIsComparing((prev) => {
            const next = !prev;
            if (prev) setSelectedEvaluation([]);
            return next;
        });
    },[]);

    const toggleEvaluationSelection = useCallback((evaluationId) => {
        const evaluation = onlineList.find(item => item.id === evaluationId);
        if (!evaluation?.answerDate) return;

        setSelectedEvaluation((prev) =>
            (prev.includes(evaluationId))
            ? prev.filter(id => id !== evaluationId)
            : prev.length < 3 ? [...prev, evaluationId] : prev
        );
    },[onlineList]);

    const evaluationsToShow = useMemo(() => {
        if (!onlineList) return [];
        return isComparing
            ? onlineList.filter(ev => ev.answerDate)
            : onlineList;
    }, [onlineList, isComparing]);

    const handleGoCharts = () => {
        navigate(buildOnlineEvaluationChartsRoute(id));
    };

    const handleGoDeleted = () => {
        navigate(buildOnlineEvaluationDeletedRoute(id, "1"));
    };

    const handleOpenEvaluation = () => {
        if (currentEvaluation) {
            navigate(buildOnlineEvaluationViewRoute(id, currentEvaluation.id));
            handleOptionsModal();
        }
    };

    const handleSeeEdit = () => {
        navigate(buildOnlineEvaluationEditRoute(id, currentEvaluation.id));
    };

    const handleGoCompare = () => {
        if (selectedEvaluation.length < 2) {
            dispatch(addToast({
                id: `toast-alert-${id}`,
                type: "warning",
                title: t("evaluationOnlineComponents:toastTitle"),
                message: t("evaluationOnlineComponents:toastCompare"),
                autohide: true,
                delay: 5000
            }));
            return;
        }
        navigate(buildOnlineEvaluationCompareRoute(id, selectedEvaluation.join(",")));
    };

    const handleStartModal = () => {
        setShowStartModal(prevState => !prevState);
    };

    const handleOptionsModal = (evaluation) => {
        setShowOptionsModal(prevState => !prevState)
        setCurrentEvaluation(evaluation);
    };

    const handleDeleteModal = () => {
        setShowEvaluationDeleteModal(prevState => !prevState)
    };

    const handleSwitchToSendModal = () => {
        setShowStartModal(false);
        setShowEvaluationSendModal(true);
    };

    const handleCloseSendModal = (hasChanged) => {
        setShowEvaluationSendModal(false);
        if (hasChanged) {
            dispatch(getAllOnline({clientId: id, status: 0}));
        }
    };

    const handleDeleteEvaluation = () => {
        dispatch(recoverEvaluation({id: currentEvaluation.id, status: 1}))
        setShowEvaluationDeleteModal(false);
        setShowOptionsModal(false);
    };

    const handleConfirmDelete = () => {
        if (currentEvaluation && !onlineList.find(item => item.id === currentEvaluation.id)) {
            navigate(buildOnlineEvaluationsRoute(id, "1"));
        }
        handleDeleteEvaluation();
    };

    const checkEvaluationsCompare = () => {
        const answeredEvaluations = onlineList.filter(evaluation => evaluation.answerDate);
        if (answeredEvaluations.length < 2) {
            const toastPayload = {
                id: `toast-alert-${id}`,
                type: "warning",
                title: t("evaluationOnlineComponents:toastTitle"),
                message: t("evaluationOnlineComponents:toastCompare"),
                autohide: true,
                delay: 5000
            };
            dispatch(addToast(toastPayload));

        } else {
            toggleComparison();
        }
    };

    useEffect(() => {
        if (currentEvaluation && !onlineList.find(item => item.id === currentEvaluation.id)) {
            navigate(buildOnlineEvaluationsRoute(id, "1"));
        }
    }, [onlineList, currentEvaluation, id, navigate]);

    return (
        <>
            <div className={"card card-body border-0"}>
                {loading &&
                    <div className="text-center mt-4">
                        <LoadingBlock/>
                    </div>
                }
                <div className={"pt-2"}>
                    <div className={"btn btn-outline-primary w-100 py-4 clickable-element"}
                         onClick={handleStartModal}>
                        <i className={"fa-regular fa-plus pe-1"}/>
                        <span>{t("evaluationOnlineComponents:newEvaluation")}</span>
                    </div>
                </div>
                <div className={"row justify-content-center d-flex"}>
                    <div className={"row py-3"}>
                        <div className={"col-12 d-flex gap-2 ps-0 pe-0"}>
                            <button className={"btn btn-secondary-default w-100"} onClick={handleGoCharts}>
                                <span className={"text-primary"}>{t("evaluationOnlineComponents:charts")}</span>
                            </button>
                            <button className={"btn btn-secondary-default w-100"} onClick={handleGoDeleted}>
                                <span className={"text-primary"}>{t("evaluationOnlineComponents:excluded")}</span>
                            </button>
                        </div>
                    </div>
                </div>
                {
                    (!onlineList || onlineList.length === 0) &&
                    <>
                        <div className={"pt-3"}>
                            <span className={"fw-semibold"}>{t("evaluationOnlineComponents:previousEvaluations")}</span>
                        </div>
                        <EmptySet icon={"fa-regular fa-folder-open"}
                                  message={t("evaluationOnlineComponents:noEvaluationStudent")}/>
                    </>
                }
                {!loading && onlineList && onlineList.length > 0 && (
                    <div className={"row justify-content-center d-flex"}>
                        <div className={"col-12"}>
                            <div className={"px-2"}>
                                {evaluationsToShow.map((evaluation, index) => (
                                    <OnlineEvaluationSelectCard
                                        key={evaluation.id}
                                        title={`${t("evaluationOnlineComponents:onlineEvaluation")} ${evaluationsToShow.length - index}`}
                                        evaluation={evaluation}
                                        onClick={() => handleOptionsModal(evaluation)}
                                        isComparing={isComparing}
                                        isSelected={selectedEvaluation.includes(evaluation.id)}
                                        onToggle={() => toggleEvaluationSelection(evaluation.id)}
                                        onCompare={checkEvaluationsCompare}
                                    />
                                ))}
                            </div>
                        </div>
                    </div>
                )}
            </div>
            {isComparing &&
                <EvaluationCompareBarComponent
                    selectedCount={ selectedEvaluation.length}
                    maxSelection={ MAX_SELECTION }
                    onCompare={ handleGoCompare }
                    onClose={ toggleComparison }
                    compareLabel={t("evaluationOnlineComponents:compare")}
                    selectLabel={t("evaluationOnlineComponents:select")}
                />
            }
            <Modal show={showStartModal} onHide={handleStartModal} centered>
                <ModalBody>
                    <OnlineEvaluationStartModal id={id} onClose={handleStartModal}
                                                handleSwitchToSendModal={handleSwitchToSendModal}/>
                </ModalBody>
            </Modal>

            <Modal show={showOptionsModal} onHide={handleOptionsModal} centered>
                <Modal.Body>
                    <div className={"row"}>
                        <div className={"col-12"}>
                            <div className={"row justify-content-between"}>
                                <div className={"col-auto"}>
                                    <span
                                        className={"fw-semibold text-start"}>{t("evaluationOnlineComponents:whatYouWant")}</span>
                                </div>
                                <div className={"col-auto cursor-pointer"} onClick={handleOptionsModal}>
                                    <i className={"fa-regular fa-times"}/>
                                </div>
                            </div>
                            <div className={"d-grid gap-2 pt-3"}>
                                {currentEvaluation?.answerDate && (
                                    <button className={"btn btn-outline-primary"} onClick={handleOpenEvaluation}>
                                        {t("evaluationOnlineComponents:openEvaluation")}
                                    </button>
                                )}
                                <button className="btn btn-outline-primary" onClick={handleSeeEdit}>
                                    {t("evaluationOnlineComponents:seeEdit")}
                                </button>
                                <button className={"btn btn-outline-danger"}
                                        onClick={handleDeleteModal}>
                                    {t("evaluationOnlineComponents:delete")}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>

            <Modal show={showEvaluationSendModal} onHide={handleCloseSendModal} centered>
                <ModalBody>
                    <OnlineEvaluationSendModal onClose={handleCloseSendModal} clientId={id}/>
                </ModalBody>
            </Modal>

            <Modal show={showEvaluationDeleteModal} onHide={handleDeleteModal} centered>
                <ModalBody>
                    <div className={"row"}>
                        <div className={"col-12"}>
                            <ChangeStatus icon={"fa-regular fa-circle-exclamation"} iconColor={"text-danger"}
                                          title={t("evaluationOnlineComponents:areYouSure")}
                            />
                        </div>
                    </div>
                    <div className={"col-12 mt-3"}>
                        <div className={"d-grid"}>
                            <button className={"btn btn-danger mb-2"} onClick={handleConfirmDelete}>
                                {t("evaluationOnlineComponents:yesDelete")}
                            </button>
                            <button className={"btn btn-outline-danger"} onClick={handleDeleteModal}>
                                {t("evaluationOnlineComponents:close")}
                            </button>
                        </div>
                    </div>
                </ModalBody>
            </Modal>
        </>
    )
}

export default OnlineEvaluation;
