import React, {useState, useEffect} from 'react';
import {useDispatch} from 'react-redux';
import {fetchUserExercises} from '../../store/exercise-library/exerciseLibraryReducer';
import {useTranslation} from 'react-i18next';
import useComponentTranslations from '../../utils/translation/useComponentTranslations';
import enUS from './locales/en-us.json';
import ptBR from './locales/pt-br.json';
import esES from './locales/es-es.json';
import ptPT from './locales/pt-pt.json';
import SimpleExerciseSearchResults from './SimpleExerciseSearchResults';
import {useExerciseSearch} from "../../utils/workout/useExerciseSearch";
import he from "he"

const SimpleExerciseSearchModal = ({onSelect, exerciseName}) => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const [query, setQuery] = useState(exerciseName || '');
    const [page, setPage] = useState(1);
    const hitsPerPage = 50;

    useComponentTranslations(
        'workoutPrescriptionComponent',
        {'en-US': enUS, 'pt-BR': ptBR, 'es-ES': esES, 'pt-PT': ptPT}
    );

    const locale =
        i18n.language.startsWith('pt-PT') ? 'pt-PT' :
            i18n.language.startsWith('pt-BR') ? 'pt-BR' :
                i18n.language.startsWith('es') ? 'es-ES' :
                    'en-US';

    useEffect(() => {
        dispatch(fetchUserExercises());
    }, [dispatch]);

    useEffect(() => setPage(1), [query, locale]);

    const {results: backendHits, loading, error} =
        useExerciseSearch(query, locale, page, hitsPerPage);

    return (
        <div className="row justify-content-center mb-2">
            <div className="col-12">
                <input
                    type="search"
                    placeholder={t('workoutPrescriptionComponent:searchExercise')}
                    value={he.decode(query)}
                    onChange={e => setQuery(e.target.value)}
                    className="form-control mb-4 bg-white"
                />
            </div>
            <div className="overflow-auto" style={{height: 'calc(100vh - 350px)'}}>
                {loading && <p className="text-center">{t('workoutPrescriptionComponent:loading')}</p>}
                {error && <p className="text-danger text-center"></p>}
                {!loading && !error && (
                    <SimpleExerciseSearchResults
                        query={query}
                        onSelect={onSelect}
                        hits={backendHits}
                    />
                )}
            </div>
        </div>
    );
};

export default SimpleExerciseSearchModal;