import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import React from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const PhysicalEvaluationMenuModal = ({ show, onHide, subtitle, protocols, onSelect,}) => {
    const {t} = useTranslation();
    useComponentTranslations('physicalEvaluationsComponent', {
        'en-US': enUS,
        'pt-BR': ptBR,
        'es-ES': esES,
        'pt-PT': ptPT
    });
    return (
        <Modal show={show} onHide={onHide} centered>
            <ModalBody>
                <div className={"row"}>
                    <div className={"col-12"}>
                        <div className={"row justify-content-between"}>
                            <div className={"col-auto row"}>
                                <span className={"fw-semibold fs-5"}>{t("physicalEvaluationsComponent:skinfold")}</span>
                                <span>{t("physicalEvaluationsComponent:chooseFormula")}</span>
                            </div>
                            <div className={"col-auto cursor-pointer"} onClick={onHide}>
                                <i className={"fa-solid fa-xmark"}/>
                            </div>
                        </div>
                        <div className={"d-grid gap-2 pt-3"}>
                            <span>{subtitle}</span>
                            {protocols.map(({ id, name }) => (
                                <button
                                    key={id}
                                    type="button"
                                    className="card card-body clickable-element text-start"
                                    onClick={() => onSelect(id)}
                                >
                                    {name}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </ModalBody>
        </Modal>
    )
}

export default PhysicalEvaluationMenuModal;