export const hasRecipientSelection = ({
    clients = [],
    groups = [],
    enforceCurrentClient = false,
    showRecipients = false
}) => {
    if (enforceCurrentClient || !showRecipients) {
        return true;
    }

    return (clients?.length || 0) > 0 || (groups?.length || 0) > 0;
};

export const shouldShowRecipientSelectionError = ({
    touchedClients = false,
    touchedGroups = false,
    submitCount = 0,
    hasRecipientSelection: hasSelection,
    enforceCurrentClient = false,
    showRecipients = false
}) => {
    if (!showRecipients || enforceCurrentClient || hasSelection) {
        return false;
    }

    return Boolean(touchedClients || touchedGroups || submitCount > 0);
};
