import React, {useCallback} from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {formatDate as formatDateValue} from "../../utils/translation/localeUtils";


const OnlineEvaluationSelectCard = ({title, evaluation, onClick, isComparing, isSelected, onToggle, onCompare}) => {
    const {t, i18n} = useTranslation();
    useComponentTranslations('evaluationOnlineComponents', {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT
    });

    const handleCompare = useCallback(
        e => {
            e.stopPropagation();
            onCompare(evaluation.id);
        },
        [onCompare, evaluation.id]
    );

    const handleRowClick = useCallback(() => {
            if (isComparing) {
                if (!evaluation.answerDate) return;
                onToggle(evaluation.id);
            } else {
                onClick(evaluation.id);
            }
        },
        [isComparing, onToggle, onClick, evaluation.id, evaluation.answerDate]
    );

    return (
        <div className={"row pb-2"}>
            <div className={"card"}>
                <div className={`row d-flex align-items-center py-3 ${!isComparing ? 'clickable-element' : ''}`}
                     onClick={handleRowClick}
                >
                    <div className={"col-10 lh-1 pb-1"}>
                        <span className={"fw-semibold d-block"}>{title}</span>
                        <span className={"text-md fw-semibold me-1"}>{t("evaluationOnlineComponents:created")} </span>
                        <span className={"text-md"}>{formatDateValue(evaluation.sentDate, i18n.language)}</span>
                        <div>
                            <span
                                className={"text-md fw-semibold me-1"}>{t("evaluationOnlineComponents:answered")} </span>
                            <span
                                className={"text-md"}>
                                {evaluation.answerDate
                                    ? formatDateValue(evaluation.answerDate, i18n.language)
                                    : t("evaluationOnlineComponents:waiting")}
                            </span>
                        </div>
                    </div>
                    <div className={"col-2 d-flex justify-content-end align-items-center"}>
                        {isComparing ? (
                            evaluation.answerDate ? (
                                <input
                                    type={"checkbox"}
                                    className={"form-check-input"}
                                    checked={isSelected}
                                    onChange={() => {
                                    }}
                                />
                            ) : (
                                <i className={"fa-regular fa-chevron-right"}/>
                            )
                        ) : (
                            <i className={"fa-regular fa-chevron-right"}/>
                        )}
                    </div>
                </div>
                <hr className={"text-secondary my-n1"}/>
                <div className={"col-12 clickable-element"} onClick={handleCompare}>
                    <button className={"btn btn-link text-md ps-0 fw-semibold my-n1"}>
                        {t("evaluationOnlineComponents:compare")}
                    </button>
                </div>
            </div>
        </div>
    )
}

export default OnlineEvaluationSelectCard;
