import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect} from "react";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {fetchClient} from "../../store/client/clientReducer";
import {
    resetFormSent
} from "../../store/online-evaluation/evaluationOnlineReducer";
import EvaluationSuccessCard from "../../components/evaluation-components/EvaluationSuccessCard";
import {
    buildOnlineEvaluationViewRoute,
    buildOnlineEvaluationsRoute
} from "../../utils/client/evaluationRoutes";
import {
    isSuccessTargetReady,
} from "../../utils/evaluation/successFlow";

const OnlineEvaluationEnd = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, evaluationId} = useParams();
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const {t} = useTranslation();
    useComponentTranslations("evaluationOnline", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const targetEvaluationId = evaluationId ?? null;

    const handleGoBackPage = () => {
        navigate(buildOnlineEvaluationsRoute(id, "1"));
    };

    const handleView = () => {
        if (targetEvaluationId) {
            navigate(buildOnlineEvaluationViewRoute(id, targetEvaluationId));
        }
    };

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"}>
                <div className={"row justify-content-center d-flex "}>
                    <div className={"col-12"}>
                        <EvaluationSuccessCard
                            title={t("evaluationOnline:evaluationCompleted")}
                            primaryLabel={t("evaluationOnline:seeAnswers")}
                            secondaryLabel={t("evaluationOnline:backToTop")}
                            onPrimary={handleView}
                            onSecondary={handleGoBackPage}
                            primaryDisabled={!isSuccessTargetReady(targetEvaluationId)}
                        />
                    </div>
                </div>
            </Page>
        </>
    )
}

export default OnlineEvaluationEnd;
