import React, {useState} from "react";
import Modal from "react-bootstrap/Modal";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import {createCategory, deleteCategory} from "../../store/exercise-library/exerciseLibraryReducer";
import {useDispatch, useSelector} from "react-redux";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {selectExerciseCategories} from "../../store/exercise-library/exerciseLibrarySelector";
import * as Yup from "yup";
import {ErrorMessage, Field, Form, Formik} from "formik";

const ExerciseCategoryListItem = ({category}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const [showDelete, setShowDelete] = useState(false);
    const categories = useSelector(selectExerciseCategories);
    const [showEditCategory, setShowCategory] = useState(false);
    useComponentTranslations('exerciseLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const initialValues = {id: category.id, name: category.name};

    const validationSchema = Yup.object({
        name: Yup.string()
            .required(t("exerciseLibraryComponent:categoryNameRequired"))
            .test("unique", t("exerciseLibraryComponent:categoryExists"), function (value) {
                if (!value) return true;
                return !categories.some(
                    (cat) =>
                        cat.id !== category.id &&
                        cat.name &&
                        cat.name.toLowerCase() === value.toLowerCase()
                );
            }),
        id: Yup.mixed().required(),
    });

    const handleEditCategory = () => {
        if (category.userId > 0)
            setShowCategory(prevState => !prevState);
    };

    const handleShowModal = () => {
        setShowDelete(prevState => !prevState);
    };

    const handleDeleteGroup = () => {
        dispatch(deleteCategory(category.id));
    };

    const onSubmit = (values) => {
        dispatch(createCategory(values));
    };

    return (
        <>
            <li className={"fw-semibold border-bottom ps-2 pt-3 pb-3 border-secondary-subtle"}>
                <div className="row justify-content-between">
                    <div className={`col-auto align-self-center ${category.idUser > 0 && "clickable-element"}`} onClick={handleEditCategory}>
                        {
                            category.userId > 0 ? category.name :
                                t(`exerciseLibraryComponent:${category.name}`)
                        }
                    </div>
                    {category.userId > 0 && (
                        <div className="col-auto align-self-center clickable-element" onClick={handleShowModal}>
                            <i className="fa-regular fa-trash-can text-danger"></i>
                        </div>
                    )}
                </div>
            </li>
            <Modal show={showEditCategory} centered onHide={handleEditCategory}>
                <Modal.Body>
                    <div className="row justify-content-between">
                        <div className="col-auto">
                            <span className="fw-semibold">{t(`exerciseLibraryComponent:changeCategoryName`)}</span>
                        </div>
                        <div className="col-auto clickable-element" onClick={handleEditCategory}>
                            <span><i className="fa-regular fa-times"></i></span>
                        </div>
                        <div className={"col-12 mt-3"}>
                            <Formik
                                initialValues={initialValues}
                                validationSchema={validationSchema}
                                onSubmit={onSubmit}
                            >
                                {(formik) => (
                                    <Form>

                                        <Field type="hidden" id="id" name="id"/>
                                        <div className="mb-3">
                                            <label htmlFor="name" className="form-label fw-semibold">
                                                {t("exerciseLibraryComponent:categoryName")}
                                            </label>
                                            <Field
                                                type="text"
                                                id="name"
                                                name="name"
                                                className={`form-control ${
                                                    formik.errors.name && formik.touched.name ? "is-invalid" : ""
                                                }`}
                                            />
                                            <ErrorMessage name="name">
                                                {(msg) => <div className="invalid-feedback">{msg}</div>}
                                            </ErrorMessage>
                                        </div>
                                        <div className="d-grid">
                                            <button type="submit" className="btn btn-primary">
                                                {t("exerciseLibraryComponent:save")}
                                            </button>
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            <Modal show={showDelete} centered onHide={handleShowModal}>
                <Modal.Body>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation"}
                        iconColor={"text-danger"}
                        title={t("exerciseLibraryComponent:confirmDeleteCategory")}
                        subtitle={t("exerciseLibraryComponent:irreversibleAction")}
                    />
                    <div className="row mt-3 justify-content-center">
                        <div className="col-12">
                            <div className="d-grid">
                                <button className="btn btn-danger" onClick={handleDeleteGroup}>
                                    {t("exerciseLibraryComponent:delete")}
                                </button>
                            </div>
                            <div className="d-grid mt-2">
                                <button className="btn btn-outline-danger" onClick={handleShowModal}>
                                    {t("exerciseLibraryComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    );
};

export default ExerciseCategoryListItem;
