import axios from "axios";
import {apiUrl, getToken} from "../api";

const buildClientProgressApiConfig = () => {
    const token = getToken();
    if (!token) {
        return null;
    }

    return {
        headers: {
            "Content-Type": "application/json",
            authorization: token
        },
        timeout: 20000
    };
};

export const getAllClientProgressAPI = async (id) => {
    const config = buildClientProgressApiConfig();
    if (!config) return;
    return await axios.get(`${apiUrl}/user/progress/all?id=${id}`, config);
};

export const respondClientProgressAPI = async ({id, progressId, formData}) => {
    const config = buildClientProgressApiConfig();
    if (!config) return;
    return await axios.post(`${apiUrl}/user/progress/respond?id=${id}&progressId=${progressId}`, formData, config);
};

export const deleteClientProgressAPI = async (id, progressId) => {
    const config = buildClientProgressApiConfig();
    if (!config) return;
    return await axios.delete(`${apiUrl}/user/progress/?id=${id}&progressId=${progressId}`, config);
};
