import Spinner from "../loader/Spinner";
import {Link} from "react-router-dom";

const CardButtonLg = ({
                          to,
                          col,
                          handleClick,
                          text,
                          pe,
                          ps,
                          icon,
                          borderClass = "border border-primary-lighter  shadow-sm",
                          bgColor,
                          textColor,
                          count,
                          loading
                      }) => {
    return (
        <div className={`${col} ${pe} ${ps}`} onClick={handleClick}>
            <Link to={to} className={`${col} text-decoration-none`}>
                <div className={`card card-body ${borderClass} ${bgColor} h-100`}>
                    <div className={'row   '}>
                        <div className={'col-12  '}>
                            {
                                !loading && count > 0 &&
                                <span className="position-absolute top-10 translate-middle badge rounded-pill bg-danger fw-semibold" style={{right: "0"}}>
                                {count > 99 ? "99+" : count}
                            </span>
                            }
                            {
                                loading &&
                                <span className="position-absolute  " style={{right: "-11px", top: "4px"}}>
                                <Spinner height={"20px"}/>
                            </span>
                            }
                            <span className={`text-primary-lighter ${textColor}`}>
                                <i className={`fa-regular ${icon} fa-xl`}/>
                            </span>
                        </div>
                        <div className={`${col === "col-6" ? "col-10" : " col-6 col-md-4 col-lg-3"}  `}>
                            <span className={`d-block pt-3 fw-semibold lh-1 ${textColor}`}>{text}</span>
                        </div>
                    </div>
                </div>
            </Link>
        </div>

    )
}
export default CardButtonLg