import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {Formik, Field, Form, ErrorMessage} from "formik";
import * as Yup from "yup";
import {useCallback, useEffect, useState} from "react";
import {getVideoDimensions} from "../../utils/video/videoUtils";
import uploadFile from "../../utils/fileupload/s3FileUpload";
import uploadFileUS from "../../utils/fileupload/s3FileUploadUS";
import {useDispatch, useSelector} from "react-redux";
import {
    selectExercise, selectExerciseCategories, selectExerciseGroups,
    selectLibraryLoading
} from "../../store/exercise-library/exerciseLibrarySelector";
import {
    createExercise,
    fetchExerciseCategories,
    fetchExerciseGroups,
    setExercise
} from "../../store/exercise-library/exerciseLibraryReducer";
import {selectUser} from "../../store/user/userSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {getMuscle} from "../../utils/workout/Exercise";
import {selectWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionSelector";
import {fetchWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionReducer";

const ExerciseCreate = () => {
    const {t} = useTranslation();
    const {sessionId} = useParams();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const [uploadProgress, setUploadProgress] = useState(0);
    const [isUploading, setIsUploading] = useState(false);
    const loading = useSelector(selectLibraryLoading);
    const categories = useSelector(selectExerciseCategories);
    const muscleGroups = useSelector(selectExerciseGroups);
    const createdExercise = useSelector(selectExercise);
    const user = useSelector(selectUser);
    const session = useSelector(selectWorkoutSession)
    useComponentTranslations('exerciseLibrary', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = useCallback(() => {
        if (sessionId) {
            navigate(`/user/client/${session.idAluno}/workout/routine/${session.idRoutine}/session/${session.id}/exercise-list`);
        } else
            navigate("/user/exercise-library");
    }, [sessionId, session, navigate]);

    const initialValues = {
        name: '',
        media: '',
        photo: null,
        video: null,
        link: '',
        muscleGroup: '',
        newMuscleGroup: '',
        category: '',
        newCategory: '',
        addToFavorites: '',
        videoWidth: '',
        videoHeight: '',
        removeAudio: true,
    };

    const validationSchema = Yup.object().shape({
        name: Yup.string()
            .max(245, t("exerciseLibrary:maxChars245"))
            .required(t("exerciseLibrary:required")),
        photo: Yup.mixed()
            .nullable()
            .when('media', {
                is: '1',
                then: (schema) => schema.required(t("exerciseLibrary:required")),
                otherwise: (schema) => schema,
            }),
        video: Yup.mixed()
            .nullable()
            .when('media', {
                is: '3',
                then: (schema) => schema.required(t("exerciseLibrary:required")),
                otherwise: (schema) => schema,
            }),
        link: Yup.string().when('media', {
            is: '0',
            then: (schema) =>
                schema
                    .required(t("exerciseLibrary:required"))
                    .matches(
                        /^(https?:\/\/)?(www\.)?(youtube\.com|youtu\.?be)\/.+$/,
                        t("exerciseLibrary:invalidURL")
                    ),
            otherwise: (schema) => schema,
        }),
        muscleGroup: Yup.string().required(t("exerciseLibrary:required")),
        newMuscleGroup: Yup.string().when('muscleGroup', {
            is: 'create',
            then: (schema) => schema.required(t("exerciseLibrary:required")),
            otherwise: (schema) => schema,
        }),
        category: Yup.string().required(t("exerciseLibrary:required")),
        newCategory: Yup.string().when('category', {
            is: 'create',
            then: (schema) => schema.required(t("exerciseLibrary:required")),
            otherwise: (schema) => schema,
        }),
        addToFavorites: Yup.string().required(t("exerciseLibrary:required")),
    });

    const handleSubmit = async (values) => {
        try {
            if (values.media === '1' || values.media === '3') {
                setIsUploading(true);
            }

            if (values.media === '0') {

                values.urlMedia = values.link;
            }
            if (values.media === '1') {
                const imageUrl = await uploadFile(
                    values.photo,
                    user.id,
                    0,
                    "exercicios"
                );
                values.urlMedia = imageUrl;
            }

            if (values.media === '3') {
                const dimensions = await getVideoDimensions(values.video);
                const videoUrl = await uploadFileUS(
                    values.video,
                    user.id,
                    (evt) => {
                        const progress = Math.round((evt.loaded / evt.total) * 100);
                        setUploadProgress(progress);
                    }
                );
                values.urlMedia = videoUrl;
                values.videoWidth = dimensions.width;
                values.videoHeight = dimensions.height;
            }

            setIsUploading(false);

            const payload = {
                name: values.name,
                mediaType: values.media,
                urlMedia: values.urlMedia,
                urlPoster: "",
                exerciseGroup:
                    values.muscleGroup === 'create'
                        ? {nome: values.newMuscleGroup}
                        : {id: values.muscleGroup},
                exerciseCategory:
                    values.category === 'create'
                        ? {name: values.newCategory}
                        : {id: values.category},
                addToFavorites: values.addToFavorites === 'true',
                videoWidth: values.videoWidth,
                videoHeight: values.videoHeight,
                removeAudio: values.media === '3' ? values.removeAudio : true,
            };
            dispatch(createExercise(payload));
        } catch (error) {
            setIsUploading(false);
        }
    };

    useEffect(() => {
        dispatch(fetchExerciseGroups());
        dispatch(fetchExerciseCategories());
        if (sessionId)
            dispatch(fetchWorkoutSession(sessionId))
    }, [dispatch, sessionId]);

    useEffect(() => {
        if (createdExercise) {
            const idExerc = createdExercise.id;
            dispatch(setExercise(null));
            if (session?.id) {
                navigate(`/user/client/${session.idAluno}/workout/routine/${session.idRoutine}/session/${session.id}/exercise-list/type/user/exercise/${idExerc}`);
            } else
                handleGoBack()
        }
    }, [dispatch, createdExercise, handleGoBack, session, navigate]);

    return (
        <Page title={t("exerciseLibrary:createExercise")} goBackLink={handleGoBack} pb={"pb-2"} loading={loading || !muscleGroups || !categories}>
            <div className="row justify-content-center">
                <div className="col-12">
                    <div className="card card-body border-0">
                        <Formik
                            initialValues={initialValues}
                            validationSchema={validationSchema}
                            onSubmit={handleSubmit}
                        >
                            {({values, setFieldValue}) => (
                                <Form>
                                    <div className="mb-3">
                                        <label htmlFor="name" className="form-label fw-semibold">{t("exerciseLibrary:name")}</label>
                                        <Field name="name" type="text" className="form-control"/>
                                        <ErrorMessage name="name" component="div" className="text-danger"/>
                                    </div>

                                    <div className="mb-3">
                                        <label htmlFor="media" className="form-label fw-semibold">{t("exerciseLibrary:media")}</label>
                                        <Field as="select" name="media" className="form-control form-select">
                                            <option value="99">{t("exerciseLibrary:noMedia")}</option>
                                            <option value="1">{t("exerciseLibrary:photoGif")}</option>
                                            <option value="3">{t("exerciseLibrary:mobileVideo")}</option>
                                            <option value="0">{t("exerciseLibrary:youtubeLink")}</option>
                                        </Field>
                                        <ErrorMessage name="media" component="div" className="text-danger"/>
                                    </div>
                                    {values.media === '1' && (
                                        <div className="mb-3">
                                            <label htmlFor="photo" className="form-label fw-semibold">
                                                {t("exerciseLibrary:selectImageGif")}
                                            </label>
                                            <input
                                                id="photo"
                                                name="photo"
                                                type="file"
                                                accept="image/*"
                                                className="form-control"
                                                onChange={(event) =>
                                                    setFieldValue("photo", event.currentTarget.files[0])
                                                }
                                            />
                                            <ErrorMessage name="photo" component="div" className="text-danger"/>
                                        </div>
                                    )}

                                    {values.media === '3' && (
                                        <>
                                            <div className="mb-3">
                                                <label htmlFor="video" className="form-label fw-semibold">
                                                    {t("exerciseLibrary:mobileVideo")}
                                                </label>
                                                <input
                                                    id="video"
                                                    name="video"
                                                    type="file"
                                                    accept="video/*"
                                                    className="form-control"
                                                    onChange={(event) =>
                                                        setFieldValue("video", event.currentTarget.files[0])
                                                    }
                                                />
                                                <ErrorMessage name="video" component="div" className="text-danger"/>
                                            </div>
                                            <div className="mb-3">
                                                <div className="form-check">
                                                    <Field
                                                        type="checkbox"
                                                        name="removeAudio"
                                                        className="form-check-input"
                                                        id="removeAudio"
                                                    />
                                                    <label htmlFor="removeAudio" className="form-check-label">
                                                        {t("exerciseLibrary:removeAudio")}
                                                    </label>
                                                </div>
                                            </div>
                                        </>
                                    )}

                                    {values.media === '0' && (
                                        <div className="mb-3">
                                            <label htmlFor="link" className="form-label fw-semibold">
                                                {t("exerciseLibrary:youtubeLink")}
                                            </label>
                                            <Field name="link" type="text" className="form-control"/>
                                            <ErrorMessage name="link" component="div" className="text-danger"/>
                                        </div>
                                    )}

                                    <div className="mb-3">
                                        <label htmlFor="muscleGroup" className="form-label fw-semibold">{t("exerciseLibrary:muscleGroup")}</label>
                                        <Field as="select" name="muscleGroup" className="form-control form-select">
                                            <option value="">{t("exerciseLibrary:selectMuscleGroup")}</option>
                                            <option value="create">{t("exerciseLibrary:createMuscleGroup")}</option>
                                            {muscleGroups?.map((group) => (
                                                <option key={group.id} value={group.id}>
                                                    {
                                                        group.idUser > 0 ? group.nome :
                                                            t(`exerciseLibrary:${getMuscle(group.alias)}`)
                                                    }
                                                </option>
                                            ))}
                                        </Field>
                                        <ErrorMessage name="muscleGroup" component="div" className="text-danger"/>
                                    </div>

                                    {values.muscleGroup === 'create' && (
                                        <div className="mb-3">
                                            <label htmlFor="newMuscleGroup" className="form-label fw-semibold">{t("exerciseLibrary:newMuscleGroup")}</label>
                                            <Field name="newMuscleGroup" type="text" className="form-control"/>
                                            <ErrorMessage name="newMuscleGroup" component="div" className="text-danger"/>
                                        </div>
                                    )}

                                    <div className="mb-3">
                                        <label htmlFor="category" className="form-label fw-semibold">{t("exerciseLibrary:category")}</label>
                                        <Field as="select" name="category" className="form-control form-select">
                                            <option value="">{t("exerciseLibrary:selectCategory")}</option>
                                            <option value="create">{t("exerciseLibrary:createNewCategory")}</option>
                                            {categories?.map((cat) => (
                                                <option key={cat.id} value={cat.id}>
                                                    {
                                                        cat.userId > 0 ? cat.name :
                                                            t(`exerciseLibrary:${cat.name}`)
                                                    }
                                                </option>
                                            ))}
                                        </Field>
                                        <ErrorMessage name="category" component="div" className="text-danger"/>
                                    </div>

                                    {values.category === 'create' && (
                                        <div className="mb-3">
                                            <label htmlFor="newCategory" className="form-label fw-semibold">{t("exerciseLibrary:newCategory")}</label>
                                            <Field name="newCategory" type="text" className="form-control"/>
                                            <ErrorMessage name="newCategory" component="div" className="text-danger"/>
                                        </div>
                                    )}

                                    <div className="mb-3">
                                        <label className="form-label d-block fw-semibold">{t("exerciseLibrary:addToFavorites")}</label>
                                        <div className="form-check form-check-inline">
                                            <Field type="radio" name="addToFavorites" value="true" className="form-check-input" id="favSim"/>
                                            <label htmlFor="favSim" className="form-check-label">{t("exerciseLibrary:yes")}</label>
                                        </div>
                                        <div className="form-check form-check-inline">
                                            <Field type="radio" name="addToFavorites" value="false" className="form-check-input" id="favNao"/>
                                            <label htmlFor="favNao" className="form-check-label">{t("exerciseLibrary:no")}</label>
                                        </div>
                                        <ErrorMessage name="addToFavorites" component="div" className="text-danger"/>
                                    </div>

                                    {isUploading && (
                                        <div className="mb-3">
                                            <label className="form-label">{t("exerciseLibrary:uploading", {uploadProgress})}</label>
                                            <div className="progress">
                                                <div
                                                    className="progress-bar"
                                                    role="progressbar"
                                                    style={{width: `${uploadProgress}%`}}
                                                    aria-valuenow={uploadProgress}
                                                    aria-valuemin="0"
                                                    aria-valuemax="100"
                                                />
                                            </div>
                                        </div>
                                    )}

                                    <div className="d-grid">
                                        <button type="submit" className="btn btn-primary" disabled={isUploading}>
                                            {t("exerciseLibrary:save")}
                                        </button>
                                    </div>
                                </Form>
                            )}
                        </Formik>
                    </div>
                </div>
            </div>
        </Page>
    );
};

export default ExerciseCreate;
