import * as Yup from "yup";

export const buildValidationSchema = (fields, t) => {
    const translate = (key, fieldLabel) =>
        t
            ? t(key, {field: fieldLabel})
            : key === "neuromotors:fieldPositive"
                ? `${fieldLabel} must be positive`
                : `${fieldLabel} is required`;

    const shape = {};
    fields.forEach((field) => {
        if (field.type === 'number') {
            shape[field.name] = Yup.number()
                .required(translate("neuromotors:fieldRequired", field.label))
                .positive(translate("neuromotors:fieldPositive", field.label));
        } else if (field.type === 'date') {
            shape[field.name] = Yup.date().required(translate("neuromotors:fieldRequired", field.label));
        } else if (field.name !== 'resultado') {
            shape[field.name] = Yup.string()
                .required(translate("neuromotors:fieldRequired", field.label));
        }
    });
    return Yup.object().shape(shape);
};
