const Player = ({src, poster, autoplay, muted, maxHeight, type = "any"}) => {

    return (
        <>
            {type === "any" &&
                <video width={"100%"} height={maxHeight} controls controlsList="nodownload noplaybackrate"
                       autoPlay={autoplay}
                       muted={muted} poster={poster} disablePictureInPicture>
                    <source src={src}/>
                </video>
            }
            {type === "youtube" &&
                <div className="embed-responsive embed-responsive-16by9">
                    <iframe title={String(Math.random())}  className="embed-responsive-item"
                            src={src} >
                    </iframe>
                </div>
            }
        </>

    )

}
export default Player;