import React from "react";
import Modal from "react-bootstrap/Modal";
import {ErrorMessage, Field, Form, Formik} from "formik";
import * as Yup from "yup";
import moment from "moment";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const UpdateDateFilterModal = ({
    show,
    onClose,
    onApply,
    onClear,
    initialStartDate,
    initialEndDate
}) => {
    const {t} = useTranslation();
    useComponentTranslations('updateCardComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const maxSelectableDate = moment().add(7, "days").startOf("day");
    const maxSelectableDateValue = maxSelectableDate.format("YYYY-MM-DD");
    const maxSelectableDateMessage = t("updateCardComponent:maxDateLimit");

    const validationSchema = Yup.object().shape({
        startDate: Yup.date()
            .required(t("updateCardComponent:startDateRequired"))
            .max(maxSelectableDate.toDate(), maxSelectableDateMessage),
        endDate: Yup.date()
            .required(t("updateCardComponent:endDateRequired"))
            .max(maxSelectableDate.toDate(), maxSelectableDateMessage)
            .min(
                Yup.ref("startDate"),
                t("updateCardComponent:endDateAfterStartDate")
            )
            .test(
                "max-range",
                t("updateCardComponent:dateRangeTooLong"),
                function (value) {
                    const {startDate} = this.parent;
                    if (!startDate || !value) {
                        return true;
                    }
                    return moment(value).diff(moment(startDate), "days") <= 31;
                }
            )
    });

    return (
        <Modal show={show} onHide={onClose} centered>
            <div className="p-3">
                <div className="d-flex justify-content-between align-items-center mb-3">
                    <span className={'fs-5 fw-semibold'}>{t("updateCardComponent:filterByDate")}</span>
                </div>
                <Formik
                    enableReinitialize
                    initialValues={{
                        startDate: initialStartDate || "",
                        endDate: initialEndDate || ""
                    }}
                    validationSchema={validationSchema}
                    onSubmit={(values) => {
                        onApply(values);
                        onClose();
                    }}
                >
                    {({handleSubmit}) => (
                        <Form onSubmit={handleSubmit}>
                            <div className="row g-3">
                                <div className="col">
                                    <label className="form-label fw-semibold">
                                        {t("updateCardComponent:from")}
                                    </label>


                                        <Field
                                            type="date"
                                            name="startDate"
                                            className="form-control"
                                            max={maxSelectableDateValue}
                                        />

                                    <ErrorMessage
                                        name="startDate"
                                        component="div"
                                        className="text-danger small mt-1"
                                    />
                                </div>
                                <div className="col">
                                    <label className="form-label fw-semibold">
                                        {t("updateCardComponent:to")}
                                    </label>

                                        <Field
                                            type="date"
                                            name="endDate"
                                            className="form-control"
                                            max={maxSelectableDateValue}
                                        />

                                    <ErrorMessage
                                        name="endDate"
                                        component="div"
                                        className="text-danger small mt-1"
                                    />
                                </div>
                            </div>
                            <button type="submit" className="btn btn-primary w-100 mt-3">
                                {t("updateCardComponent:applyFilter")}
                            </button>
                            <button
                                type="button"
                                className="btn btn-link w-100 text-decoration-none"
                                onClick={() => {
                                    onClear();
                                    onClose();
                                }}
                            >
                                {t("updateCardComponent:clearFilter")}
                            </button>
                        </Form>
                    )}
                </Formik>
            </div>
        </Modal>
    );
};

export default UpdateDateFilterModal;
