import {createSlice} from "@reduxjs/toolkit";
import {
    DEFAULT_RETENTION_CHART_FILTERS,
    DEFAULT_RETENTION_DASHBOARD_FILTERS,
    normalizeRetentionChartFilters,
    normalizeRetentionClientFilters
} from "./retentionFilters";

const initialState = {
    dashboardFilters: {...DEFAULT_RETENTION_DASHBOARD_FILTERS},
    chartFilters: {...DEFAULT_RETENTION_CHART_FILTERS}
};

const slice = createSlice({
    name: "retention",
    initialState,
    reducers: {
        setRetentionDashboardFilters(state, action) {
            state.dashboardFilters = normalizeRetentionClientFilters({
                ...state.dashboardFilters,
                ...(action.payload || {})
            });
        },
        setRetentionDashboardPage(state, action) {
            state.dashboardFilters.page = Number(action.payload) > 0
                ? Number(action.payload)
                : DEFAULT_RETENTION_DASHBOARD_FILTERS.page;
        },
        setRetentionChartFilters(state, action) {
            state.chartFilters = normalizeRetentionChartFilters({
                ...state.chartFilters,
                ...(action.payload || {})
            });
        }
    }
});

export const {
    setRetentionDashboardFilters,
    setRetentionDashboardPage,
    setRetentionChartFilters
} = slice.actions;

export const retentionReducer = slice.reducer;
