import {createSlice} from "@reduxjs/toolkit";
import {
    createErrorSubmitResult,
    createPendingSubmitResult,
    createSubmitResult,
    createSuccessSubmitResult
} from "../../utils/evaluation/mutationState";

const initialState = {
    bioimpedanceList: [],
    compareList: [],
    oneBioimpedance: null,
    lastBioimpedance: null,
    selectedBioimpedance: null,
    initialLoading: false,
    submitLoading: false,
    submitResult: createSubmitResult(),
    error: null,
};

export const slice = createSlice({
    name: "bioimpedanceEvaluation",
    initialState,
    reducers:{
        getAllBioimpedance(state) {
            state.initialLoading = true;
        },
        setAllBioimpedance(state, action) {
            state.initialLoading = false;
            state.bioimpedanceList = action.payload;
        },
        clearAllBioimpedance(state) {
            state.bioimpedanceList = null;
            state.initialLoading = false;
        },
        fetchOneBioimpedance(state) {
            state.initialLoading = true;
        },
        setOneBioimpedance(state, action) {
            state.initialLoading = false;
            state.oneBioimpedance = action.payload;
        },
        fetchLastBioimpedance(state) {
            state.lastBioimpedance = null;
        },
        setLastBioimpedance(state, action) {
            state.lastBioimpedance = action.payload?.evaluation ?? null;
        },
        clearLastBioimpedance(state) {
            state.lastBioimpedance = null;
        },
        changeStatus: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: action.payload?.status === 1 ? "delete" : "recover",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        setStatusChanged(state, action) {
            state.bioimpedanceList = state.bioimpedanceList.filter(item => item.id !== action.payload.id);
        },
        saveBioimpedance: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "create",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        resetFormSent(state) {
            state.submitLoading = false;
            state.submitResult = createSubmitResult();
            state.error = null;
        },
        updateBioimpedance: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "update",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        compareBioimpedance(state) {
            state.initialLoading = true;
        },
        setCompareBioimpedance(state, action) {
            state.initialLoading = false;
            state.compareList = action.payload;
        },
        setSubmitResult(state, action) {
            state.submitLoading = false;
            state.submitResult = createSuccessSubmitResult(action.payload);
            state.error = null;
        },
        onError(state, action) {
            state.initialLoading = false;
            if (state.submitLoading) {
                state.submitResult = createErrorSubmitResult(state.submitResult, action.payload);
            }
            state.submitLoading = false;
            state.error = action.payload;
        }
    }
});

export const {
    getAllBioimpedance,
    setAllBioimpedance,
    clearAllBioimpedance,
    fetchOneBioimpedance,
    setOneBioimpedance,
    fetchLastBioimpedance,
    setLastBioimpedance,
    clearLastBioimpedance,
    changeStatus,
    setStatusChanged,
    saveBioimpedance,
    updateBioimpedance,
    compareBioimpedance,
    setCompareBioimpedance,
    setSubmitResult,
    onError,
    resetFormSent
} = slice.actions;

export const bioimpedanceEvaluationReducer = slice.reducer;
