import {takeLatest, all, call, put} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {fetchExerciseNameAPI, saveExerciseNameAPI} from "../../api/exercise-name/exerciseNameActions";
import {fetchExerciseName, setExerciseName, onError, setAnswered, saveExerciseName} from "./exerciseNameReducer";


export function* fetchExerciseToNameAsync() {
    try {
        const response = yield call(fetchExerciseNameAPI)
        yield put(setExerciseName(response.data))

    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchExerciseToName() {
    yield takeLatest(fetchExerciseName.type, fetchExerciseToNameAsync)
}

export function* onNameExerciseAsync(action) {
    try {
        yield call(saveExerciseNameAPI,  action.payload)
        yield put(setAnswered(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onNameExercise() {
    yield takeLatest(saveExerciseName.type, onNameExerciseAsync)
}

export function* exerciseNameSaga() {
    yield all(
        [
            call(onNameExercise),
            call(onFetchExerciseToName)
        ]
    );
}