import React, {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useLocation, useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import Page from "../../components/page/Page";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import EmptySet from "../../components/empty-set/EmptySet";
import Pagination from "../../components/pagination/Pagination";
import DeleteModal from "../../components/modal/DeleteModal";
import WorkoutPresetPreviewOffcanvas from "../../components/workout-preset/WorkoutPresetPreviewOffcanvas";
import WorkoutPresetCard from "../../components/workout-preset/WorkoutPresetCard";
import useWorkoutPresetSections from "../../components/workout-preset/useWorkoutPresetSections";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import componentEnUS from "../../components/workout-preset/locales/en-us.json";
import componentPtBR from "../../components/workout-preset/locales/pt-br.json";
import componentEsES from "../../components/workout-preset/locales/es-es.json";
import componentPtPT from "../../components/workout-preset/locales/pt-pt.json";
import {
    clearWorkoutPresetEvents,
    deleteWorkoutPreset,
    fetchWorkoutPresets
} from "../../store/workout-preset/workoutPresetReducer";
import {
    selectLastDeletedWorkoutPresetId,
    selectWorkoutPresetLoading,
    selectWorkoutPresets
} from "../../store/workout-preset/workoutPresetSelector";

const WorkoutPresetList = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const location = useLocation();
    const presets = useSelector(selectWorkoutPresets);
    const loading = useSelector(selectWorkoutPresetLoading);
    const deletedPresetId = useSelector(selectLastDeletedWorkoutPresetId);
    const backTo = location.state?.backTo || "/user";
    const [previewPreset, setPreviewPreset] = useState(null);
    const [deleteTargetPreset, setDeleteTargetPreset] = useState(null);
    const {
        searchQuery,
        setSearchQuery,
        normalizedQuery,
        filteredUserPresets,
        filteredSystemPresets,
        paginatedUserPresets,
        userPage,
        setUserPage,
        itemsPerPage,
        pagesToShow
    } = useWorkoutPresetSections(presets);

    useComponentTranslations("workoutPresetPage", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    useComponentTranslations("workoutPresetComponent", {"en-US": componentEnUS, "pt-BR": componentPtBR, "es-ES": componentEsES, "pt-PT": componentPtPT});

    useEffect(() => {
        dispatch(fetchWorkoutPresets());
    }, [dispatch]);

    useEffect(() => {
        if (!deleteTargetPreset || deletedPresetId !== deleteTargetPreset.id) {
            return;
        }

        setDeleteTargetPreset(null);
        setPreviewPreset(null);
        dispatch(clearWorkoutPresetEvents());
    }, [deleteTargetPreset, deletedPresetId, dispatch]);

    const hasSearchQuery = Boolean(normalizedQuery);
    const showUserSection = hasSearchQuery ? filteredUserPresets.length > 0 : true;
    const showSystemSection = hasSearchQuery ? filteredSystemPresets.length > 0 : true;
    const showEmptySearchState = hasSearchQuery && filteredUserPresets.length === 0 && filteredSystemPresets.length === 0;

    const handleOpenPreview = (preset) => {
        setPreviewPreset(preset);
    };

    const handleClosePreview = () => {
        setPreviewPreset(null);
    };

    const handleOpenDeleteModal = () => {
        if (!previewPreset || Number(previewPreset.userId) === 0) {
            return;
        }

        setDeleteTargetPreset(previewPreset);
    };

    const handleCloseDeleteModal = () => {
        setDeleteTargetPreset(null);
    };

    const handleEditPreset = (preset) => {
        handleClosePreview();

        if (Number(preset.userId) === 0) {
            navigate(`/user/workout-presets/create?sourcePresetId=${preset.id}`, {
                state: {
                    backTo,
                    sourcePreset: preset
                }
            });
            return;
        }

        navigate(`/user/workout-presets/edit/${preset.id}`, {
            state: {
                backTo
            }
        });
    };

    const renderPresetCard = (preset, isSystem = false) => (
        <WorkoutPresetCard
            key={preset.id}
            preset={preset}
            isSystem={isSystem}
            onOpen={handleOpenPreview}
        />
    );

    return (
        <>
            <Page title={t("workoutPresetPage:title")} goBackLink={() => navigate(backTo)} loading={loading}>
                <div className="card card-body border-0 gap-3">
                    <CardButtonAdd text={t("workoutPresetPage:createPreset")} handleClick={() => navigate("/user/workout-presets/create", {
                        state: {
                            backTo
                        }
                    })}/>

                    <div className="input-group">
                        <input
                            aria-label={t("workoutPresetPage:searchPlaceholder")}
                            className="form-control bg-white"
                            onChange={(event) => setSearchQuery(event.target.value)}
                            placeholder={t("workoutPresetPage:searchPlaceholder")}
                            type="search"
                            value={searchQuery}
                        />
                        <span className="input-group-text bg-white">
                            <i className="fa-regular fa-magnifying-glass"/>
                        </span>
                    </div>

                    {showEmptySearchState && (
                        <div className="card card-body border-0">
                            <EmptySet
                                icon={"fa-magnifying-glass"}
                                message={t("workoutPresetPage:noSearchResults")}
                            />
                        </div>
                    )}

                    {showUserSection && (
                        <div>
                            <span className="fw-semibold d-block">{t("workoutPresetPage:userPresets")}</span>
                            <div className="d-grid gap-2 mt-2">
                                {filteredUserPresets.length > 0
                                    ? paginatedUserPresets.map((preset) => renderPresetCard(preset))
                                    : <span className="text-secondary">{t("workoutPresetPage:noUserPresets")}</span>}
                            </div>
                            {filteredUserPresets.length > itemsPerPage && (
                                <Pagination
                                    className={"pt-3"}
                                    currentPage={userPage}
                                    totalItems={filteredUserPresets.length}
                                    itemsPerPage={itemsPerPage}
                                    onPageChange={setUserPage}
                                    pagesToShow={pagesToShow}
                                />
                            )}
                        </div>
                    )}

                    {showSystemSection && (
                        <div>
                            <span className="fw-semibold d-block">{t("workoutPresetPage:systemPresets")}</span>
                            <div className="d-grid gap-2 mt-2">
                                {filteredSystemPresets.length > 0
                                    ? filteredSystemPresets.map((preset) => renderPresetCard(preset, true))
                                    : <span className="text-secondary">{t("workoutPresetPage:noSystemPresets")}</span>}
                            </div>
                        </div>
                    )}
                </div>
            </Page>
            <WorkoutPresetPreviewOffcanvas
                show={Boolean(previewPreset)}
                preset={previewPreset}
                onHide={handleClosePreview}
                onEdit={() => previewPreset && handleEditPreset(previewPreset)}
                canDelete={Boolean(previewPreset) && Number(previewPreset.userId) !== 0}
                onDeleteClick={handleOpenDeleteModal}
            />
            <DeleteModal
                show={Boolean(deleteTargetPreset)}
                onClose={handleCloseDeleteModal}
                onConfirm={() => deleteTargetPreset && dispatch(deleteWorkoutPreset(deleteTargetPreset.id))}
                deleteTitle={t("workoutPresetPage:deletePresetModalTitle")}
                deleteSubtitle={t("workoutPresetPage:deletePresetModalDescription")}
                confirmLabel={t("workoutPresetPage:deletePreset")}
                closeLabel={t("workoutPresetComponent:cancel")}
                isSubmitting={loading}
                loadingLabel={t("workoutPresetPage:deletePreset")}
            />
        </>
    );
};

export default WorkoutPresetList;
