import React, {useState} from 'react';
import moment from 'moment';
import {useTranslation} from 'react-i18next';
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Modal from "react-bootstrap/Modal";
import AnamnesisOptionsModal from "./AnamnesisOptionsModal";
import {useNavigate} from "react-router-dom";
import {deleteAnamnesis} from "../../store/anamnesis/anamnesisReducer";
import {addToast} from "../../store/toast/toastReducer";
import {handleSendWhatsApp} from "../../utils/handlers/handler";
import {useDispatch} from "react-redux";
import {buildAnamnesisAnsweredRoute} from "../../utils/client/evaluationRoutes";

const AnamnesisListItem = ({anamnesis, selectedClient}) => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const [showModal, setShowModal] = useState(false);

    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handlePreviousAnamnesis = (anamnesisId, clientId) => {
        navigate(buildAnamnesisAnsweredRoute(clientId, anamnesisId));
    }

    const handleModal = () => {
        setShowModal(prevState => !prevState)
    }

    const handleDeleteAnamnesis = () => {
        dispatch(deleteAnamnesis(anamnesis.id));
        handleModal();
    };

    const handleCopyLink = () => {
        const link = generateAnamnesisLink();
        if (link) {
            navigator.clipboard.writeText(link)
                .then(() => dispatch(addToast(
                    {
                        type: "success",
                        message: `${t("anamnesis:copied")}`,
                        title: `${t("anamnesis:allDone")}`
                    }
                )))
                .catch(err => console.error(err));
        }
    }

    const handleSendWhatsAppLink = () => {
        const link = generateAnamnesisLink();
        if (link && selectedClient?.telefone) {
            const whatsappMessage = `${t("anamnesis:fillAnamnesis")}: ${link}`;
            handleSendWhatsApp(selectedClient.telefone, whatsappMessage);
        }
    }

    const generateAnamnesisLink = () => {
        if (selectedClient) {
            const data = `${selectedClient.idUser}:${selectedClient.id}:${anamnesis.id}`;
            return `https://client.mfitpersonal.com.br/out/anamnesis/${btoa(data)}`;
        }
        return '';
    }
    const link = generateAnamnesisLink();

    const getStatus = () => {
        if (anamnesis.answeredDate) {
            const date = moment({
                year: anamnesis.answeredDate.year,
                month: anamnesis.answeredDate.month - 1,
                day: anamnesis.answeredDate.day,
            });
            if (date.isValid()) {
                return {
                    text: `${t('anamnesisComponent:answered')} ${date.format('L')}`,
                    className: 'text-success text-md',
                };
            }
        }
        return {
            text: t('anamnesisComponent:waiting'),
            className: 'text-secondary text-md',
        };
    };

    const status = getStatus();

    return (
        <div className="row clickable-element px-2">
            <div className="card card-body clickable-element" onClick={handleModal}>
                <div className="row d-flex align-items-center">
                    <div className="col-8">
                        <span
                            className="fw-semibold d-block">{anamnesis.name === "Padrão" || anamnesis.name === "PAR-Q" ? t(`anamnesisComponent:${anamnesis.name}`) : anamnesis.name}</span>
                        <span className={status.className}>{status.text}</span>
                    </div>
                    <div className={"col-4 text-end"}>
                        <i className={"fa-regular fa-chevron-right"}/>
                    </div>
                </div>
            </div>
            <div className="pt-2"/>
            <Modal show={showModal} onHide={handleModal} centered>
                <Modal.Body>
                    <AnamnesisOptionsModal
                        onDelete={handleDeleteAnamnesis}
                        onCopyLink={handleCopyLink}
                        onViewEdit={() => handlePreviousAnamnesis(anamnesis.id, anamnesis.idClient)}
                        onSendWhatsAppLink={handleSendWhatsAppLink}
                        onClose={handleModal}
                        link={link}
                    />
                </Modal.Body>
            </Modal>
        </div>
    );
};

export default AnamnesisListItem;
