import {useNavigate, useParams} from "react-router-dom";
import {useEffect} from "react";
import {pushSent} from "../../store/push/pushReducer";
import {useDispatch} from "react-redux";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Page from "../../components/page/Page";

const Push = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {type} = useParams();
    useComponentTranslations('pushPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleCreatePush = () => {
        navigate(`/user/push/create/${type}`)
    }
    const handleGoBackToHome = () => {
        navigate(`/user/push/${type}`)
    }

    useEffect(() => {
        dispatch(pushSent(false))
    }, [dispatch]);

    return (
        <Page title={t(`pushPage:notifications`)} goBackLink={`/user/push/${type}`}>
            <div className={'card card-body'}>
                <div className={'row justify-content-center pt-4  '}>
                    <div className={'col-12'}>
                        <div className={' text-center'}>
                            <div className={' icon icon-shape text-success'}>
                                <i className={`fa-regular fa-circle-check`} style={{fontSize: "3rem"}}/>
                            </div>
                        </div>
                        {
                            type === "now" &&
                            <div className={'text-center pt-4 px-2'}>
                                <span className={'fw-bold'}>
                                    {t(`pushPage:pushSent`)}</span>
                            </div>
                        }
                        {
                            type === "scheduled" &&
                            <div className={'text-center pt-4 px-2'}>
                                <span
                                    className={'fw-bold'}>{t(`pushPage:pushScheduled`)}</span>
                            </div>
                        }
                        {
                            type === "recurring" &&
                            <div className={'text-center pt-4 px-2'}>
                                <span className={'fw-bold'}>{t(`pushPage:pushScheduledRecurring`)}</span>
                            </div>
                        }
                        <div className={' text-center pt-4 px-2'}>
                            <span className={'d-block'}>{t(`pushPage:nextSteps`)}</span>
                        </div>
                    </div>
                    <div className={'col-12 pt-4'}>
                        <div className={'d-grid'}>
                            <button className={'btn btn-primary-darker'} onClick={handleCreatePush}>
                                {
                                    type === "now" ? t(`pushPage:sendAnother`) : t(`pushPage:scheduledAnother`)
                                }
                            </button>
                        </div>
                        <div className={'d-grid pt-2'}>
                            <button className={'btn btn-outline-primary-darker'} onClick={handleGoBackToHome}>{t(`pushPage:goBackToStart`)}</button>
                        </div>
                    </div>
                </div>
            </div>
        </Page>
    )
}

export default Push;