import Modal from "react-bootstrap/Modal";
import {useState} from "react";
import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useDispatch, useSelector} from "react-redux";
import {generateAiPush} from "../../store/ai-actions/aiActionsReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {getWaiting} from "../../store/ai-actions/aiActionsSelector";

const AiPushGenerator = ( ) => {
    const {t} = useTranslation()
    const dispatch = useDispatch();
    const [show, setShow] = useState(false);
    const [aiRequest, setAiRequest] = useState(false);
    const waiting = useSelector(getWaiting)
    useComponentTranslations('ai', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object({
        description: Yup.string()
            .min(30, t("ai:minDescription"))
            .required(t("ai:requiredField")),
    });

    const handleShowModal = () => {
        setShow(prevState => !prevState)
    }

    const handleRetry = () => {
        dispatch(generateAiPush(aiRequest))
    }

    const onSubmit = (values) => {
        setAiRequest(values)
        dispatch(generateAiPush(values))
        handleShowModal()
    }

    return (
        <>
            <div className={"d-flex justify-content-end align-items-center gap-2 flex-wrap"}>
                {
                    aiRequest &&
                    <button
                        type={"button"}
                        className={"no-style-btn text-mfit-ai clickable-element flex-shrink-0"}
                        onClick={handleRetry}
                    >
                        <span className={"fa-light fa-rotate"} style={{fontSize: "1rem"}}></span>
                    </button>
                }
                <button
                    type={"button"}
                    className={"btn btn-sm text-mfit-ai border border-1 border-primary bg-mfit-ai-subtle"}
                    onClick={handleShowModal}
                >
                    {
                        !waiting ?
                            <>
                                {t("ai:createWithMfitAi")} <i className={"fa-kit fa-mfit-ai text-mfit-ai-gradient"}></i> <span
                                className={"fw-bold text-mfit-ai-gradient"}>MFIT</span> <span
                                className={"fw-light text-mfit-ai-gradient"}>IA</span>
                            </> :
                            <span className={"fa-regular fa-spinner fa-spin"}></span>
                    }
                </button>
            </div>


            <Modal show={show} onHide={handleShowModal} centered>
                <Modal.Body>
                    <div className={'row justify-content-end'}>
                        <div className={"col-auto clickable-element"} onClick={handleShowModal}>
                            <i className={"fa-regular fa-times"}></i>
                        </div>
                    </div>
                    <div className="row justify-content-center pt-2 pb-3">
                        <div className="col-auto">
                            <i
                                className="fa-kit fa-mfit-ai  text-mfit-ai-gradient"
                                style={{fontSize: "2rem"}}
                            ></i> <span className={"fw-bold text-mfit-ai-gradient"} style={{fontSize: "2rem"}}>MFIT</span> <span
                            className={"fw-light text-mfit-ai-gradient"}
                            style={{fontSize: "2rem"}}>IA</span>
                        </div>
                    </div>
                    <div className={'row'}>
                        <div className={'col-12'}>
                            <Formik
                                initialValues={{description: ''}}
                                validationSchema={validationSchema}
                                onSubmit={onSubmit}
                            >
                                <Form>
                                    <div className={"form-group"}>
                                        <label className={"fw-semibold"} htmlFor="description">{t("ai:descriptionLabel")}</label>
                                        <Field
                                            className="form-control border-primary"
                                            as="textarea"
                                            id="description"
                                            name="description"
                                            style={{height: '100px'}}
                                            placeholder={t("ai:descriptionPlaceholder")}
                                        />
                                        <ErrorMessage name="description" component="div" style={{color: 'red'}}/>
                                    </div>
                                    <div className={'d-grid pt-2'}>
                                        <button type="submit" className={"btn btn-link bg-mfit-ai text-white"}>
                                            {t("ai:createButton")}
                                        </button>
                                    </div>
                                </Form>
                            </Formik>
                        </div>
                        <div className={'row pt-2'}>
                            <div className={'col-12'}>
                                <span className="text-center small d-block text-mfit-ai">
                                    {t("ai:disclaimer")}
                                </span>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    )
}
export default AiPushGenerator;
