import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    clients: null,
    clientsPagination: {
        page: 1,
        pageSize: 20,
        totalItems: 0,
        totalPages: 0,
        search: ''
    },
    clientCreated: 0,
    clientCountLoading: false,
    clientCount: null,
    clientUpdated: false,
    clientAddress: null,
    pendingClientsCount: null,
    pendingClientsLoading: false,
    selectedClient: null,
    selectOptions: null,
    clientRecovered: false,
    passwordReset: false,
    notificationPreference: null,
    invoices: null,
    loading: false,
    note: null,
}

export const slice = createSlice({
    name: 'client',
    initialState,
    reducers: {
        setClientAddress(state, action) {
            state.loading = false
            state.clientAddress = action.payload
        },
        fetchClientAddress(state) {
            state.loading = true;
        },
        updateClientAddress(state) {
            state.loading = true
        },
        clientAddressUpdated(state, action) {
            state.loading = false
            state.clientUpdated = action.payload
        },
        fetchClientInvoices(state) {
            state.loading = true
        },
        setClientInvoices(state, action) {
            state.loading = false
            state.invoices = action.payload
        },
        fetchClientNotificationPreference(state) {
            state.loading = true
        },
        setClientNotificationPreference(state, action) {
            state.loading = false
            state.notificationPreference = action.payload
        },
        saveClientNotificationPreference(state) {
            state.loading = true
        },
        updateClient(state) {
            state.loading = true
        },
        clientUpdated(state, action) {
            state.loading = false
            state.clientUpdated = action.payload
        },
        createClient(state) {
            state.loading = true
        },
        clientCreated(state, action) {
            state.loading = false
            state.clientCreated = action.payload
        },
        resetPassword(state) {
            state.loading = true
        },
        passwordReset(state, action) {
            state.loading = false
            state.passwordReset = action.payload
        },
        fetchSelectOptions(state) {
            state.loading = true
            state.selectOptions = null
        },
        setSelectOptions(state, action) {
            state.loading = false
            state.selectOptions = action.payload
        },
        saveNote(state) {
            state.loading = true
        },
        saveNoteSuccess(state, action) {
            state.loading = false
            state.note.note = action.payload
        },
        fetchNotes(state) {
            state.loading = true
        },
        setNotes(state, action) {
            state.loading = false
            state.note = action.payload
        },
        fetchClient(state) {
            state.loading = true
        },
        setClient(state, action) {
            state.selectedClient = action.payload
            state.loading = false
        },
        changeStatus(state) {
            state.loading = true
        },
        statusChanged(state, action) {
            const {status} = action.payload;
            state.selectedClient.status = status;
            state.loading = false
        },
        deleteClient(state) {
            state.loading = true
        },
        clientDeleted(state, action) {
            state.clients = (state.clients || []).filter(client => client.id !== action.payload)
            const nextTotalItems = Math.max((state.clientsPagination?.totalItems || 0) - 1, 0);
            const pageSize = state.clientsPagination?.pageSize || 20;
            state.clientsPagination.totalItems = nextTotalItems;
            state.clientsPagination.totalPages = nextTotalItems > 0 ? Math.ceil(nextTotalItems / pageSize) : 0;
            state.loading = false
        },
        recoverClient(state) {
            state.loading = true
        },
        clientRecovered(state, action) {
            state.loading = false
            state.clientRecovered = action.payload
        },
        fetchClientsPaginated(state, action) {
            state.loading = true

            const defaultPayload = {status: 0, page: 1, pageSize: 20, search: ''};
            const payload = typeof action.payload === 'object' && action.payload !== null
                ? {...defaultPayload, ...action.payload}
                : {...defaultPayload, status: action.payload ?? defaultPayload.status};

            state.clientsPagination = {
                ...state.clientsPagination,
                page: payload.page ?? state.clientsPagination.page ?? defaultPayload.page,
                pageSize: payload.pageSize ?? state.clientsPagination.pageSize ?? defaultPayload.pageSize,
                search: payload.search ?? state.clientsPagination.search ?? defaultPayload.search,
            }
        },
        setClientsPaginated(state, action) {
            const payload = action.payload;

            if (payload === null || payload === undefined) {
                state.clients = payload;
                state.clientsPagination = {...initialState.clientsPagination};
                state.loading = false;
                return;
            }

            if (Array.isArray(payload)) {
                state.clients = payload;
                state.clientsPagination = {
                    ...state.clientsPagination,
                    page: 1,
                    pageSize: payload.length || state.clientsPagination.pageSize,
                    totalItems: payload.length,
                    totalPages: payload.length > 0 && (state.clientsPagination.pageSize || payload.length)
                        ? Math.max(1, Math.ceil(payload.length / (state.clientsPagination.pageSize || payload.length)))
                        : 0,
                };
                state.loading = false;
                return;
            }

            const {
                clients,
                items,
                data,
                page,
                currentPage,
                pageSize,
                perPage,
                totalItems,
                total,
                totalCount,
                totalPages,
                pages,
                search,
            } = payload;

            const normalizedClients = clients ?? items ?? data ?? [];
            const resolvedPageSize = pageSize ?? perPage ?? state.clientsPagination.pageSize ?? 20;
            const resolvedTotalItems = totalItems ?? total ?? totalCount ?? payload?.count ?? normalizedClients.length ?? 0;
            const resolvedPage = page ?? currentPage ?? state.clientsPagination.page ?? 1;
            const resolvedTotalPages = totalPages ?? pages ?? (resolvedPageSize ? Math.ceil(resolvedTotalItems / resolvedPageSize) : 0);

            state.clients = normalizedClients;
            state.clientsPagination = {
                page: resolvedPage,
                pageSize: resolvedPageSize,
                totalItems: resolvedTotalItems,
                totalPages: resolvedTotalPages,
                search: search ?? payload?.search ?? state.clientsPagination.search ?? ''
            };
            state.loading = false
        },
        setClientCount(state, action) {
            state.clientCount = action.payload;
            state.clientCountLoading = false;
        },
        fetchClientCount(state) {
            state.clientCountLoading = true;
        },
        fetchPendingClientCount(state) {
            state.pendingClientsLoading = true
        },
        setPendingClientCount(state, action) {
            state.pendingClientsCount = action.payload;
            state.pendingClientsLoading = false
        },
        updatedProfilePicture(state, action) {
            state.selectedClient.profileUrl = action.payload;
            state.loading = false;
        },
        updateProfileImage(state) {
            state.loading = true
        },
        onError(state) {
            state.loading = false
        }
    }
})

export const {
    setClientCount,
    fetchClientCount,
    setClient,
    fetchClient,
    statusChanged,
    changeStatus,
    fetchPendingClientCount,
    setPendingClientCount,
    fetchNotes,
    setNotes,
    saveNote,
    fetchSelectOptions,
    setSelectOptions,
    recoverClient,
    clientRecovered,
    deleteClient,
    clientDeleted,
    resetPassword,
    passwordReset,
    createClient,
    clientCreated,
    updateClient,
    clientUpdated,
    fetchClientNotificationPreference,
    setClientNotificationPreference,
    saveClientNotificationPreference,
    fetchClientInvoices,
    setClientInvoices,
    updateProfileImage,
    updatedProfilePicture,
    updateClientAddress,
    clientAddressUpdated,
    fetchClientAddress,
    setClientAddress,
    setClientsPaginated,
    fetchClientsPaginated,
    onError
} = slice.actions;

export const clientReducer = slice.reducer;
