import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import React, {useCallback} from "react";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import enUS from "./locales/en-us.json";
import {useTranslation} from "react-i18next";
import Text from "../../components/utils/emoji/Text";

const CustomEvaluationCard = ({
                                  custom,
                                  isComparing,
                                  isSelected,
                                  onToggle,
                                  onCompare,
                                  title,
                                  onCardClick
                              }) => {
    syncMomentLocale(i18n.language);
    const {t} = useTranslation();
    useComponentTranslations('customEvaluationComponent', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})

    const handleCompare = useCallback(
        e => {
            e.stopPropagation();
            onCompare(custom.id);
        },
        [onCompare, custom.id]
    );

    const handleRowClick = useCallback(() => {
            if (isComparing) {
                onToggle(custom.id);
            } else {
                onCardClick(custom.id);
            }
        },
        [isComparing, onToggle, onCardClick, custom]
    );

    return (

        <div className={"row pb-2"}>
            <div className={"card"}>
                <div className={`row d-flex align-items-center py-3 ${!isComparing ? 'clickable-element' : ''}`}
                     onClick={handleRowClick}
                >
                    <div className={"col-10 lh-1 pb-1"}>
                        <span className={"fw-semibold d-block"}>
                            <Text>{title}</Text>
                        </span>
                        <span className={"text-md fw-semibold me-1"}>{t("customEvaluationComponent:created")}</span>
                        <span className={"text-md"}>{moment(custom.data).format('L')}</span>
                    </div>
                    <div className={"col-2 d-flex justify-content-end align-items-center"}>
                        {isComparing ? (
                            custom.data ? (
                                <input
                                    type={"checkbox"}
                                    className={"form-check-input"}
                                    checked={isSelected}
                                    onChange={() => {
                                    }}
                                />
                            ) : (
                                <i className={"fa-regular fa-chevron-right"}/>
                            )
                        ) : (
                            <i className={"fa-regular fa-chevron-right"}/>
                        )}
                    </div>
                </div>
                <hr className={"text-secondary my-n1"}/>
                <div className={"col-12 clickable-element"} onClick={handleCompare}>
                    <button className={"btn btn-link text-md ps-0 fw-semibold my-n1"}>
                        {t("customEvaluationComponent:compare")}
                    </button>
                </div>
            </div>
        </div>
    )
}

export default CustomEvaluationCard;