import {useEffect, useState} from "react";
import {useSelector} from "react-redux";
import {ErrorMessage, Field, Form, Formik} from "formik";
import * as Yup from "yup";
import {Image} from "react-bootstrap";
import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import "moment/locale/pt-br";
import he from "he";
import {selectUser} from "../../store/user/userSelector";
import {
    selectClientProgressDeleteLoading,
    selectClientProgressRespondLoading
} from "../../store/client-progress/clientProgressSelector";
import ProgressPhotoPreview from "./ProgressPhotoPreview";

const ClientProgressCard = ({
                                progress,
                                client,
                                onRespond,
                                onDelete,
                                t,
                                locale
                            }) => {
    const user = useSelector(selectUser);
    const respondLoading = useSelector((state) => selectClientProgressRespondLoading(state, progress.id));
    const deleteLoading = useSelector((state) => selectClientProgressDeleteLoading(state, progress.id));
    const [isEditing, setIsEditing] = useState(false);

    useEffect(() => {
        if (progress?.resposta) {
            setIsEditing(false);
        }
    }, [progress?.resposta]);

    syncMomentLocale(locale);

    const sentAt = moment({
        year: progress.sentAt?.date?.year,
        month: (progress.sentAt?.date?.month || 1) - 1,
        day: progress.sentAt?.date?.day,
        hour: progress.sentAt?.time?.hour,
        minute: progress.sentAt?.time?.minute
    });
    const sentAtLabel = `${sentAt.format("DD/MM/YYYY")} ${sentAt.format("HH:mm")}`;
    const hasResponse = Boolean(progress?.resposta);
    const showForm = !hasResponse || isEditing;
    const validationSchema = Yup.object().shape({
        response: Yup.string()
            .trim()
            .required(t("clientProgressUser:responseRequired"))
            .max(250, t("clientProgressUser:responseMax"))
    });

    return (
        <div className={"pb-3  "}>
            <div className={"row"}>
                <div className={"col-10 text-start"}>
                    <span className={"fw-bold text-md align-self-center"}>
                        <i className="fa-regular fa-calendar me-1"></i>
                        {sentAt.format("DD/MM/YYYY")}
                    </span>
                    <span className={"fw-bold text-md align-self-center ms-2"}>
                        <i className="fa-regular fa-clock-seven me-1"></i>
                        {sentAt.format("HH:mm")}
                    </span>
                </div>
                <div className={"col-2 text-end"}>
                    <button
                        type={"button"}
                        className={"btn btn-link text-danger p-0"}
                        onClick={() => onDelete(progress)}
                        disabled={deleteLoading || respondLoading}
                    >
                        <i className="fa-regular fa-trash-can"></i>
                    </button>
                </div>
            </div>

            <div className={"row pt-3"}>
                <div className={"col-12 text-center"}>
                    <ProgressPhotoPreview
                        src={progress.url}
                        alt={he.decode(`${client?.nome || ""} ${client?.sobrenome || ""}`.trim())}
                        expandLabel={t("clientProgressUser:expandPhoto")}
                        minimizeLabel={t("clientProgressUser:minimizePhoto")}
                        collapsedHeight={154}
                        expandedHeight={480}
                        imageClassName={"rounded-1 w-100 h-100"}
                    />
                </div>
            </div>

            <div className={"row pt-4"}>
                <div className={"col-12"}>
                    <div className={"d-flex align-items-start gap-3"}>
                        <Image
                            fluid
                            className={"rounded-circle flex-shrink-0 avatar avatar-md"}
                            src={client?.profileUrl || "https://cdn.mfitpersonal.com.br/assets/user/user.jpg"}
                        />
                        <div className={"flex-grow-1 text-start"}>
                            <span className={"fw-semibold   d-block mb-1 lh-sm"}>
                                {he.decode(`${client?.nome || ""} ${client?.sobrenome || ""}`.trim())}
                            </span>
                            <span className={"d-block  lh-base text-default"}>
                                {he.decode(progress?.descricao || "")}
                            </span>
                            <span className={"small text-muted d-block mt-2"}>
                                {sentAtLabel}
                            </span>
                        </div>
                    </div>
                </div>
            </div>

            {hasResponse && !showForm && (
                <div className={"row pt-4"}>
                    <div className={"col-12"}>
                        <div className={"d-flex align-items-start gap-3"}>
                            <Image
                                fluid
                                className={"rounded-circle flex-shrink-0 avatar avatar-md"}
                                src={user?.urlLogo || "https://cdn.mfitpersonal.com.br/assets/user/user.jpg"}
                            />
                            <div className={"flex-grow-1 text-start"}>
                                <span className={"fw-semibold   d-block mb-1 lh-sm"}>
                                    {he.decode(`${user?.nome || ""} ${user?.sobrenome || ""}`.trim())}
                                </span>
                                <span className={"d-block   lh-base text-default"}>
                                    {he.decode(progress?.resposta || "")}
                                </span>
                                <div className={"d-flex align-items-center gap-2 flex-wrap mt-2"}>
                                    <span className={"small text-muted"}>
                                        {sentAtLabel}
                                    </span>
                                    <span className={"small text-muted"}>&bull;</span>
                                    <button
                                        type={"button"}
                                        className={"btn btn-link text-primary text-decoration-none fw-semibold p-0 border-0 btn-sm"}
                                        onClick={() => setIsEditing(true)}
                                        disabled={respondLoading || deleteLoading}
                                    >
                                        {t("clientProgressUser:editResponse")}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {showForm && (
                <div className={"row pt-4"}>
                    <div className={"col-12"}>
                        <Formik
                            enableReinitialize
                            initialValues={{response: progress?.resposta || ""}}
                            validationSchema={validationSchema}
                            onSubmit={(values) => onRespond(progress.id, values.response.trim())}
                        >
                            {({values}) => (
                                <Form>
                                    <div className={"d-flex justify-content-between align-items-center mb-2"}>
                                        <label htmlFor={`response-${progress.id}`} className={"form-label fw-semibold mb-0"}>
                                            {t("clientProgressUser:responseLabel")}
                                        </label>
                                        <span className={"small text-muted"}>{`${values.response.length}/250`}</span>
                                    </div>
                                    <Field
                                        as="textarea"
                                        id={`response-${progress.id}`}
                                        name="response"
                                        className="form-control"
                                        rows="4"
                                        placeholder={t("clientProgressUser:responsePlaceholder")}
                                        disabled={respondLoading || deleteLoading}
                                    />
                                    <ErrorMessage name="response" component="div" className="small text-danger mt-1"/>
                                    <div className={"d-grid gap-2 mt-3"}>
                                        <button
                                            className={"btn btn-primary"}
                                            type={"submit"}
                                            disabled={respondLoading || deleteLoading}
                                        >
                                            {hasResponse ? t("clientProgressUser:saveResponse") : t("clientProgressUser:respond")}
                                        </button>
                                        {hasResponse && (
                                            <button
                                                type={"button"}
                                                className={"btn btn-outline-primary"}
                                                onClick={() => setIsEditing(false)}
                                                disabled={respondLoading || deleteLoading}
                                            >
                                                {t("clientProgressUser:cancel")}
                                            </button>
                                        )}
                                    </div>
                                </Form>
                            )}
                        </Formik>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ClientProgressCard;
