import React, {useEffect, useMemo, useState} from "react";
import {useSelector, useDispatch} from "react-redux";
import {Formik, Form, Field, ErrorMessage} from "formik";
import {
    selectIsLoading,
    selectTestDeleted,
    selectTestSaved
} from "../../store/neuromotors/neuromotorsSelector";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {
    updateTest,
    deleteTest,
    testSaved,
    getAllTests,
    createTest, setTestDeleted,
} from "../../store/neuromotors/neuromotorsReducer";
import {getTestConfigurations} from "../../utils/neuromotors/testConfig";
import {buildValidationSchema} from "../../utils/neuromotors/validationSchema";
import TextareaAutosize from "react-textarea-autosize";
import i18n from "i18next";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import {calculateAge} from "../../utils/date/dateUtils";
import NeuromotorModal from "../../components/neuromotors/NeuromotorModal";
import {useNavigate} from "react-router-dom";
import Modal from "react-bootstrap/Modal";
import ChangeStatus from "../../components/utils/change-status/ChangeStatus";
import {buildNeuromotorTestRoute} from "../../utils/client/evaluationRoutes";
import {getNeuromotorPageFromType} from "../../utils/neuromotors/navigation";
import {
    calculateRepMaxValues,
    findAgeMatchedEntry,
    findMatchingResultKey
} from "../../utils/neuromotors/rangeUtils";

const getBibliographyContent = (t, testIdentifier) => {
    return (
        <div className={"row"}>
            <div className={"col-12 mb-2"}>
                <span
                    className="small pb-2"> {t(`neuromotors:source`)}: {t(`neuromotors:canadianTest`)}</span>
            </div>
            {i18n.exists(`neuromotors:objective_${testIdentifier}`) && (
                <div className="col-12">
                    <span className={"fw-semibold"}>{t('neuromotors:objective')}: </span>
                    <span>{t(`neuromotors:objective_${testIdentifier}`)}</span>
                </div>
            )}
            {i18n.exists(`neuromotors:materials_${testIdentifier}`) && (
                <div className="col-12">
                    <span className="fw-semibold">{t('neuromotors:materials')}: </span>
                    <span>{t(`neuromotors:materials_${testIdentifier}`)}</span>
                </div>
            )}
            <div className="col-12">
                <span className="fw-semibold">{t('neuromotors:protocol')}:</span>
            </div>
            {i18n.exists(`neuromotors:protocol_${testIdentifier}`) && (
                <span>{t(`neuromotors:protocol_${testIdentifier}`)}</span>
            )}
            {['a', 'b', 'c', 'd', 'e', 'f', 'g'].map(letter => {
                const key = `neuromotors:protocol_${letter}_${testIdentifier}`;
                if (i18n.exists(key)) {
                    return (
                        <div key={`protocol_${letter}`} className="col-12">
                            {letter !== 'g' ? (
                                <ol className={"list-with-bullets list-no-spacing"}>
                                    <li>{t(key)}</li>
                                </ol>
                            ) : (
                                <span>{t(key)}</span>
                            )}
                        </div>
                    );
                }
                return null;
            })}
        </div>
    )
}


const NeuromotorCreateUpdate = ({type = 1, initialValues, page, clientId}) => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const isTestLoading = useSelector(selectIsLoading)
    const isTestSaved = useSelector(selectTestSaved);
    const isTestDeleted = useSelector(selectTestDeleted);
    const selectedClient = useSelector(selectSelectedClient);
    const [highlightedRow, setHighlightedRow] = useState();
    const [overrideTableValues, setOverrideTableValues] = useState([]);
    const [watchedData, setWatchedData] = useState({});
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isBibliographyOpen, setIsBibliographyOpen] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const {t} = useTranslation();
    const numericType = Number(type);
    const currentPage = page ?? getNeuromotorPageFromType(numericType);

    useComponentTranslations('neuromotors', {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR})


    const pageConfig = useMemo(() => {
        const pageDefinition = getTestConfigurations(t)[numericType];
        const validations = buildValidationSchema(pageDefinition.fields, t);

        const age = calculateAge(selectedClient?.data_nascimento);
        const sexo = selectedClient?.sexo?.at(0)?.toLowerCase() || null;

        const completeTable =
            !sexo ? undefined : pageDefinition.tableData[sexo]?.[pageDefinition.testName] ?? pageDefinition.tableData;

        const completeEntries = Object.entries(completeTable ?? {});
        const hasAgeTable = Boolean(completeEntries[0]?.[1]?.age);
        const selectedEntry = hasAgeTable ? findAgeMatchedEntry(completeTable, age) : null;
        const [ageIndex, selectedTable] = selectedEntry ?? [];
        const rowsSource = hasAgeTable ? selectedTable : completeTable;
        const tableRows = Object.entries(rowsSource ?? {}).map(([key, value]) => ({key, value}));

        return {
            page: pageDefinition,
            validations,
            table: {
                complete: completeTable,
                completeRows: hasAgeTable ? completeEntries.map(([_key, data]) => data) : [],
                rows: tableRows,
                ageIndex,
            },
            showModal: Boolean(pageDefinition.showModal && hasAgeTable),
        };
    }, [numericType, selectedClient?.data_nascimento, selectedClient?.sexo, t]);


    const handleCreate = (values) => {
        const data = {
            idAluno: selectedClient.id,
            idProfessor: selectedClient.idUser,
            valor: values.valor,
            carga: parseFloat(values.carga || 0),
            reps: parseInt(values.reps || 0, 10),
            peso: values.peso,
            salto: values.salto,
            teste: numericType,
            data: values.data,
            resultado: values.resultado,
        };
        dispatch(createTest(data));
    };

    const handleUpdate = (values) => {
        const data = {
            id: initialValues.id,
            idAluno: selectedClient.id,
            idProfessor: selectedClient.idUser,
            valor: values.valor,
            carga: parseFloat(values.carga || 0),
            reps: parseInt(values.reps || 0, 10),
            peso: values.peso,
            salto: values.salto,
            teste: numericType,
            data: (values.data),
            resultado: values.resultado,
        };
        dispatch(updateTest(data));
    };

    const handleDelete = () => {
        dispatch(deleteTest({
            type: numericType,
            id: initialValues.id,
        }));
    };

    const onWatchedChange = (field, value) => {
        setWatchedData(prevState => ({
            ...prevState,
            [field.name]: value
        }))
    }

    useEffect(() => {
        if (initialValues) {
            setWatchedData(initialValues)
        }
    }, [initialValues]);

    useEffect(() => {
        if (!watchedData) return;
        if (pageConfig.page.calculateLogic === "rangeValor") {
            setHighlightedRow(findMatchingResultKey(pageConfig.table.rows, watchedData.valor));
            setOverrideTableValues([]);
        } else if (pageConfig.page.calculateLogic === "rangeSalto") {
            setHighlightedRow(findMatchingResultKey(pageConfig.table.rows, watchedData.salto));
            setOverrideTableValues([]);
        } else if (pageConfig.page.calculateLogic === "repMax") {
            setHighlightedRow(undefined);
            setOverrideTableValues(calculateRepMaxValues(watchedData.carga, watchedData.reps));
        } else {
            setHighlightedRow(undefined);
            setOverrideTableValues([]);
        }
    }, [watchedData, pageConfig.page.calculateLogic, pageConfig.table.rows]);

    useEffect(() => {
        if (isTestSaved) {
            dispatch(testSaved(false))
            navigate(buildNeuromotorTestRoute(numericType, clientId ?? selectedClient?.id, currentPage));
        }
    }, [clientId, currentPage, dispatch, isTestSaved, navigate, numericType, selectedClient])

    useEffect(() => {
        if (selectedClient) {
            dispatch(getAllTests({type, clientId: selectedClient.id}));
        }
    }, [dispatch, type, selectedClient]);

    useEffect(() => {
        if(isTestDeleted) {
            dispatch(setTestDeleted(false))
            navigate(buildNeuromotorTestRoute(numericType, clientId ?? selectedClient?.id, currentPage));
        }
    }, [clientId, currentPage, dispatch, isTestDeleted, navigate, numericType, selectedClient])


    return (
        <>
            <div className="neuromotor-form">
                <div className={"fw-semibold"}>{pageConfig.page.testTitle}</div>
                <div className={"text-muted mb-2"}>{pageConfig.page.testSubtitle}</div>
                <Formik
                    enableReinitialize
                    initialValues={initialValues ?? {
                        valor: "",
                        carga: "",
                        reps: "",
                        peso: "",
                        salto: "",
                        resultado: "",
                        data: "",
                    }}
                    validationSchema={pageConfig.validations}
                    onSubmit={(values) => {
                        if (initialValues?.id) {
                            handleUpdate(values)
                        } else {
                            handleCreate(values)
                        }
                    }
                    }
                >
                    {({handleChange, errors, touched}) => (
                        <Form>
                            {pageConfig.page.fields.map((field) => (
                                <div key={field.name} className="form-group pt-1">
                                    <label htmlFor={field.name} className={"fw-semibold"}>{field.label}</label>
                                    <Field
                                        id={field.name}
                                        name={field.name}
                                        type={field.type}
                                        className={`form-control ${
                                            errors[field.name] && touched[field.name] ? "is-invalid" : ""
                                        }`}
                                        placeholder={field.placeholder}
                                        as={field.type === "textarea" ? TextareaAutosize : "input"}
                                        {...(field.type === "textarea" ? {minRows: 4} : {})}
                                        {...(["flexões/minuto"].includes(field.unit) ? {step: "1", min: "0"} : {})}
                                        onChange={(e) => {
                                            handleChange(e);
                                            if (field.watch) {
                                                onWatchedChange(field, e.target.value);
                                            }
                                        }}
                                    />
                                    <ErrorMessage name={field.name} component="div" className="invalid-feedback"/>
                                </div>
                            ))}

                            <div className={"card card-body border-0 bg-primary-subtle mt-3"}>
                                <div className={"row d-flex align-items-center card-content"}>
                                    <button
                                        className={"btn d-flex align-items-center justify-content-between w-100 clickable-element "}
                                        onClick={() => setIsBibliographyOpen(!isBibliographyOpen)}
                                        aria-expanded={isBibliographyOpen}
                                        type="button"
                                    >
                                        <span className={"fw-semibold"}>{t('neuromotors:bibliography')}</span>
                                        <i className={`fa-regular ${
                                            isBibliographyOpen ? "fa-chevron-up" : "fa-chevron-down"
                                        } ms-2`}
                                        />
                                    </button>
                                </div>
                                {isBibliographyOpen && (
                                    <div className="row">
                                        <div className="col-12">
                                            {getBibliographyContent(t, pageConfig.page.testName)}
                                        </div>
                                    </div>
                                )}
                            </div>
                            <div className={"row"}>
                                <div className={"col-12"}>
                                    <button type="submit" className="btn btn-primary mt-3 w-100"
                                            disabled={isTestLoading}>
                                        {initialValues?.id ? t("neuromotors:update") : t("neuromotors:save")}
                                    </button>
                                </div>
                            </div>
                        </Form>
                    )}
                </Formik>

                {initialValues?.id && (
                    <button type="delete" className={"btn btn-outline-danger mt-2 w-100"}
                            onClick={() => {
                                setShowDeleteModal(true)
                            }}
                    >
                        {t("neuromotors:delete")}
                    </button>
                )}
                <Modal
                    show={showDeleteModal}
                    centered>
                    <Modal.Body>
                        <ChangeStatus
                            icon={"fa-regular fa-circle-exclamation"}
                            iconColor={"text-danger"}
                            title={t("neuromotors:areYouSure")}
                            subtitle={t("neuromotors:cannotBeUndone")}
                        />
                        <div className="row p-3 gap-2">
                            <button className="btn btn-danger" onClick={handleDelete}>
                                {t("neuromotors:yesDelete")}
                            </button>
                            <button className="btn btn-outline-danger" onClick={() => {
                                setShowDeleteModal(false);
                            }}>
                                {t("neuromotors:close")}
                            </button>
                        </div>
                    </Modal.Body>
                </Modal>
            </div>

            <div className="card mt-2">
                <div className="py-2">
                    {pageConfig.page.testTitle &&
                        <span className="card-title text-center fw-semibold px-2">{pageConfig.page.testTitle}</span>
                    }
                    <div className={"table-responsive"}>
                        <table
                            className={'table table-striped mt-2'}
                        >
                            <tbody className={"table-columns-border table-rows-border"}>
                            {pageConfig.table?.rows.map((row, index) => (
                                <tr key={row.key} className={highlightedRow === row.key ? "table-primary" : ""}>
                                    <th scope={"row"}>
                                        {t(`neuromotorsComponent:${row.key}`)}
                                    </th>
                                    <td>
                                        {overrideTableValues[index] ?? row.value}
                                    </td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {pageConfig.showModal && (
                <div className={"mt-2 pb-2"}>
                    <button
                        className={"btn btn-link p-0"}
                        onClick={() => setIsModalOpen(true)}
                        type="button"
                    >
                        {t('neuromotors:seeFullTable')}
                    </button>
                    <NeuromotorModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        pageConfig={pageConfig}
                    />
                </div>
            )}
        </>
    )
}

export default NeuromotorCreateUpdate;
