import {getExerciseName} from "../../utils/workout/Workout";
import {useTranslation} from "react-i18next";
import _ from "lodash";
import WorkoutSeries from "./WorkoutSeries";
import {useState} from "react";
import ExercisePlayerType from "../utils/videoplayer/ExercisePlayerType";

const WorkoutExerciseSubSingularListItem = ({exerc, handleCardClick}) => {
    const {i18n} = useTranslation();
    const [exercise] = useState(exerc.exercises ? exerc.exercises[0] : exerc.exercicio ? exerc.exercicio : exerc);
    return (
        <div className="row justify-content-center ps-3">
            <div className="col-9 clickable-element" onClick={()=>handleCardClick(exerc.id)}>
                <div className={'row justify-content-between d-flex pt-3'}>
                    <div className={`col-9  align-self-center`}>
                        <span className={'d-block fw-semibold  text-md'} style={{lineHeight: "1.1rem"}}>
                             {getExerciseName(exercise, i18n)}
                        </span>
                    </div>
                </div>
                <div className={'row d-flex pb-3 text-md  pt-1'}>
                    {exercise.series && exercise.series.length > 0 && (
                        <div className={`col-9   `}>
                            {_.map(exercise.series, (serie) => (
                                <WorkoutSeries key={serie.id}
                                               serie={serie}
                                               seriesLength={exercise.series.length}
                                               showEdit={false}
                                />
                            ))}
                        </div>
                    )}
                </div>

            </div>
            <ExercisePlayerType exercise={exercise}/>
        </div>
    )
}
export default WorkoutExerciseSubSingularListItem;