import {
    createFeedback,
    feedbackCreated, fetchAllUnreadFeedbacks, fetchResolvedFeedbacks, fetchUnreadFeedbacks,
    onError, resolveAllFeedbacks, resolveFeedback, resolveFeedbackSuccess,
    setFeedbackFormSent, setFeedbacks, setResolvedFeedbacks, setUnreadFeedbacks
} from "./feedbackReducer";
import {takeLatest, all, call, put} from 'redux-saga/effects';
import {
    getResolvedFeedbacksAPI,
    getUnreadFeedbackAPI,
    getUnreadFeedbackCountAPI,
    resolveAllFeedbacksAPI,
    resolveFeedbackAPI,
    saveFeedbackAPI
} from "../../api/feedback/feedbackActions";
import {handleError} from "../../utils/error/sagaErrorHandling";

export function* onFetchUnreadFeedbacksAsync() {
    try {
        const response = yield(call(getUnreadFeedbackCountAPI))
        yield put(setUnreadFeedbacks(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchUnreadFeedbacks() {
    yield takeLatest(fetchUnreadFeedbacks.type, onFetchUnreadFeedbacksAsync)
}

export function* onFetchResolvedFeedbacksAsync() {
    try {
        const response = yield(call(getResolvedFeedbacksAPI))
        yield put(setResolvedFeedbacks(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchResolvedFeedbacks() {
    yield takeLatest(fetchResolvedFeedbacks.type, onFetchResolvedFeedbacksAsync)
}

export function* createFeedbackAsync(action) {
    try {
        const {id, formData} = action.payload
        yield call(saveFeedbackAPI, id, formData)
        yield put(feedbackCreated());
        yield put(setFeedbackFormSent(true));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onCreateFeedback() {
    yield takeLatest(createFeedback.type, createFeedbackAsync)
}

export function* fetchAllUnreadFeedbacksAsync() {
    try {
        const response = yield(call(getUnreadFeedbackAPI))
        yield put(setFeedbacks(response.data))
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchAllUnreadFeedbacks() {
    yield takeLatest(fetchAllUnreadFeedbacks.type, fetchAllUnreadFeedbacksAsync)
}

export function* resolveFeedbackAsync(action) {
    try {
        const {id, formData} = action.payload
        yield call(resolveFeedbackAPI, id, formData);
        yield put(resolveFeedbackSuccess(id));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onResolveFeedbacks() {
    yield takeLatest(resolveFeedback.type, resolveFeedbackAsync)
}

export function* resolveAllFeedbacksAsync() {
    try {
        yield call(resolveAllFeedbacksAPI)
        yield put(setFeedbacks([]));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onResolveAllFeedbacks() {
    yield takeLatest(resolveAllFeedbacks.type, resolveAllFeedbacksAsync)
}

export function* feedbackSaga() {
    yield all(
        [
            call(onCreateFeedback),
            call(onFetchUnreadFeedbacks),
            call(onFetchAllUnreadFeedbacks),
            call(onResolveFeedbacks),
            call(onResolveAllFeedbacks),
            call(onFetchResolvedFeedbacks)
        ]
    );
}