import React, {useCallback, useEffect, useState} from "react";
import {getCategory, getExerciseName, getMuscle} from "../../utils/workout/Exercise";
import Modal from "react-bootstrap/Modal";
import ExercisePlayer from "../utils/videoplayer/ExercisePlayer";
import {motion} from "framer-motion";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {deleteExercise, removeExerciseAsFavorite, setExerciseAsFavorite} from "../../store/exercise-library/exerciseLibraryReducer";
import {useDispatch, useSelector} from "react-redux";
import {selectExerciseFavorites} from "../../store/exercise-library/exerciseLibrarySelector";
import Text from "../utils/emoji/Text";
import {useNavigate, useParams} from "react-router-dom";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import {selectWorkoutLoadingExerciseId, selectWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionSelector";


const ExerciseLibraryCard = ({hit, addedExercises, isReplace, handleReplace, isSerieReplace}) => {
    const {t, i18n} = useTranslation();
    const {idExerc} = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const [showVideoModal, setShowVideoModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const favorites = useSelector(selectExerciseFavorites);
    const [isFavorite, setIsFavorite] = useState(false);
    const [error, setError] = useState(false);
    const session = useSelector(selectWorkoutSession)
    const minHeight = session ? "100px" : "82px";
    const [isAdded, setIsAdded] = useState(false);
    const loadingExerciseId = useSelector(selectWorkoutLoadingExerciseId)

    useComponentTranslations("exerciseLibraryComponent", {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT,
    });

    const onError = () => {
        setError(true);
    };

    const handleEditExercise = () => {
        navigate(`/user/exercise-library/edit/${hit.objectID}/session/${session?.id || 0}`);
    };

    const handleCustomExercise = () => {
        navigate(`/user/exercise-library/edit/${hit.objectID}/session/${session?.id || 0}/clone`);
    };

    const handleDeleteExercise = () => {
        handleCloseVideo()
        setShowDeleteModal((prevState) => !prevState);
    };

    const handleOpenVideo = useCallback(() => setShowVideoModal(true), []);
    const handleCloseVideo = () => {
        setShowVideoModal(false);
        if (idExerc) {
            const newPath = window.location.pathname.replace(`/type/user/exercise/${idExerc}`, "/user");
            navigate(newPath, { replace: true });
        }
    };

    const handleFavoriteClick = () => {
        dispatch(setExerciseAsFavorite({exerciseId: hit.objectID}));
    };

    const handleRemoveFavoriteClick = () => {
        dispatch(removeExerciseAsFavorite(hit.objectID));
    };

    const handleDeleteExerciseClick = () => {
        dispatch(deleteExercise(hit.objectID));
    };

    const favoriteComponent = () => {
        return (
            <>
                {!isFavorite && (
                    <span className="clickable-element" onClick={handleFavoriteClick}>
                        <i className="fa-regular fa-star-circle"></i>
                    </span>
                )}
                {isFavorite && (
                    <span className="clickable-element" onClick={handleRemoveFavoriteClick}>
                        <i className="fa-regular fa-star-circle text-warning"></i>
                    </span>
                )}
            </>
        );
    };

    const tagsComponent = () => {
        return (
            <>
                <span className="badge bg-white me-1 text-default border rounded-5">
                  {typeof hit.group === "number"
                      ? t(`exerciseLibraryComponent:${getMuscle(hit.group)}`)
                      : hit.group}
                </span>
                <span className="badge bg-white me-1 text-default border rounded-5">
                  {typeof hit.category === "number"
                      ? t(`exerciseLibraryComponent:${getCategory(hit.category)}`)
                      : hit.category}
                </span>
            </>
        );
    };
    useEffect(() => {
        const targetId = Number(hit.objectID);
        const exists = addedExercises.some(wrapper =>
            wrapper.exerciseArray.some(ex => ex.id === targetId)
        );
        setIsAdded(exists);
    }, [addedExercises, hit.objectID]);

    useEffect(() => {
        if (favorites) {
            setIsFavorite(favorites.some((fav) => fav.id === Number(hit.objectID)));
        }
    }, [favorites, hit]);

    useEffect(() => {
        if (idExerc && Number(idExerc) === Number(hit.objectID)) {
            handleOpenVideo()
        }
    }, [idExerc, hit, handleOpenVideo]);

    return (
        <>
            <div className="card mb-2">
                <div className="row">
                    <div className="col-3 col-md-2 text-start" onClick={handleOpenVideo}>
                        <div
                            className="rounded-start"
                            style={{
                                minHeight: minHeight,
                                overflow: "hidden",
                                position: "relative",
                            }}
                        >
                            {(hit.mediaType === 0 || hit.mediaType === 3) && (
                                <>
                                    <img
                                        src={`${
                                            hit.mediaType === 0
                                                ? `https://img.youtube.com/vi/${hit.url_media}/0.jpg`
                                                : hit.url_poster
                                        }`}
                                        alt={t("exerciseLibraryComponent:centered")}
                                        style={{
                                            position: "absolute",
                                            top: "50%",
                                            left: "50%",
                                            transform: "translate(-50%, -50%) scale(0.3)",
                                            minWidth: "100%",
                                            minHeight: "100%",
                                            objectFit: "cover",
                                        }}
                                    />
                                    <div
                                        className="position-absolute"
                                        style={{
                                            top: "50%",
                                            left: "50%",
                                            transform: "translate(-50%, -50%)",
                                        }}
                                    >
                                        <i className="fa-solid fa-play fa-xl text-white-50"></i>
                                    </div>
                                </>
                            )}
                            {Number(hit.mediaType) === 1 && (
                                <>
                                    <img
                                        src={`${hit.url_media}`}
                                        alt={t("exerciseLibraryComponent:exercise")}
                                        style={{
                                            position: "absolute",
                                            minWidth: "100%",
                                            minHeight: "100%",
                                            objectFit: "cover",
                                        }}
                                    />
                                </>
                            )}
                        </div>
                    </div>
                    <div className="col-9 col-md-10 ps-0">
                        <div className="card-body p-0 pt-2 pe-3 d-flex flex-column justify-content-between h-100">
                            <div className="d-flex justify-content-between">
                                <div className="col-11 clickable-element" onClick={handleOpenVideo}>
                                    <h6 className="fw-semibold mb-1">
                                        <Text>{getExerciseName(hit, i18n.language)}</Text>
                                    </h6>
                                    {tagsComponent()}
                                </div>
                                <div className="col-1 text-end">{favoriteComponent()}</div>
                            </div>
                            {
                                session &&
                                <div className={"d-flex border-top"}>
                                    {
                                        loadingExerciseId === hit.objectID &&
                                        <div className={"col-12 text-center"}>
                                            <span className={"fw-semibold small"}><i
                                                className={"fa-regular fa-spinner fa-spin"}></i> {t("exerciseLibraryComponent:pleaseWait")}...</span>
                                        </div>
                                    }
                                    {
                                        (loadingExerciseId !== hit.objectID) &&
                                        <div className={"col-12 text-center"}>
                                            {
                                                !isReplace && !isSerieReplace && !isAdded &&
                                                <span className={"fw-semibold small text-primary clickable-element"}
                                                      onClick={() => handleReplace(hit.objectID)}><i
                                                    className={"fa-regular fa-plus-circle"}></i> {t("exerciseLibraryComponent:addToWorkout")}</span>
                                            }
                                            {
                                                isAdded && !isReplace && !isSerieReplace &&
                                                <div className={"row justify-content-evenly"}>
                                                    <div className={"col-auto "}>
                                                      <span className={"fw-semibold small"}>
                                                          {t("exerciseLibraryComponent:alreadyAdded")} <i className={"fa-regular fa-check-circle"}></i></span>
                                                    </div>
                                                    |
                                                    <div className={"col-auto"}>
                                                        <span className={"fw-semibold small text-primary clickable-element "}
                                                              onClick={() => handleReplace(hit.objectID)}><i
                                                            className={"fa-regular fa-plus-circle"}></i> {t("exerciseLibraryComponent:add")}</span>
                                                    </div>
                                                </div>
                                            }
                                            {
                                                (isReplace || isSerieReplace) &&
                                                <span className={"fw-semibold small text-primary clickable-element"}
                                                      onClick={() => handleReplace(hit.objectID)}><i
                                                    className={"fa-solid fa-right-left"}></i> {t("exerciseLibraryComponent:replace")}</span>
                                            }
                                        </div>
                                    }

                                </div>
                            }
                        </div>
                    </div>
                </div>
            </div>
            <Modal show={showVideoModal} onHide={handleCloseVideo} centered>
                <Modal.Body className="pt-2">
                    <motion.div
                        drag="y"
                        dragConstraints={{top: 0, bottom: 0}}
                        dragElastic={0.3}
                        onDragEnd={(event, info) => {
                            const threshold = 100;
                            if (Math.abs(info.offset.y) > threshold) {
                                handleCloseVideo();
                            }
                        }}
                        style={{cursor: "grab"}}
                    >
                        <div className="row justify-content-center">
                            <div className="col-12 mb-2">
                                <div className="row">
                                    <div className="col-10">
                                        <span className="fs-5 fw-semibold d-block">
                                          <Text>
                                              {getExerciseName(hit, i18n.language)}
                                          </Text>
                                        </span>
                                    </div>
                                    <div className="col-2 text-end">{favoriteComponent()}</div>
                                </div>
                                <div className="row">
                                    <div className="col-12">{tagsComponent()}</div>
                                </div>
                            </div>
                            <div className={`${hit.mediaType === 0 || error ? "col-12" : "col-8"}`}>
                                {hit.mediaType === 0 && (
                                    <div className="row justify-content-center d-block">
                                        <div className="col-12 text-center">
                                            <div className="embed-responsive">
                                                <iframe
                                                    title={hit.name}
                                                    className="embed-responsive-item"
                                                    src={`https://www.youtube.com/embed/${hit.url_media}?rel=0`}
                                                    allowFullScreen
                                                ></iframe>
                                            </div>
                                        </div>
                                    </div>
                                )}
                                {hit.mediaType === 1 && (
                                    <div className="row justify-content-center d-block">
                                        <div className="col-12 text-center">
                                            <img
                                                alt={t("exerciseLibraryComponent:exercise")}
                                                src={hit.url_media}
                                                className="img-fluid"
                                            />
                                        </div>
                                    </div>
                                )}
                                {hit.mediaType === 3 && (
                                    <>
                                        {error ? (
                                            <div className="row">
                                                <div className="col-12">
                                                    <div className="row justify-content-center d-block">
                                                        <div className="col-12 text-center">
                                                            <div className="alert bg-primary-subtle">
                                                                <span className="d-block mb-2">
                                                                  <i className="fa-regular fa-3x fa-exclamation-circle text-primary"></i>
                                                                </span>
                                                                <h5 className="fw-semibold">
                                                                    {t("exerciseLibraryComponent:videoProcessing")}
                                                                </h5>
                                                                <span>
                                                                  {t("exerciseLibraryComponent:pleaseWait")}{" "}
                                                                    <span className="fw-semibold">
                                                                    {t("exerciseLibraryComponent:fiveMinutes")}
                                                                  </span>{" "}
                                                                    {t("exerciseLibraryComponent:orTryCreatingExerciseAgain")}
                                                                </span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        ) : (
                                            <ExercisePlayer
                                                src={hit.url_media}
                                                handleMediaClose={handleCloseVideo}
                                                poster={hit.url_poster}
                                                hideCloseBtn={true}
                                                onError={onError}
                                            />
                                        )}
                                    </>
                                )}
                            </div>
                            {
                                session ?
                                    <div className="d-grid mt-2 mb-2 ">
                                        <button className="btn btn-default" onClick={() => {
                                            handleReplace(hit.objectID)
                                            handleCloseVideo()
                                        }}>
                                            {
                                                !isReplace && !isSerieReplace &&
                                                <span>{t("exerciseLibraryComponent:addToWorkout")}</span>
                                            }
                                            {
                                                (isReplace || isSerieReplace) &&
                                                <span>{t("exerciseLibraryComponent:replace")}</span>
                                            }
                                        </button>
                                    </div> :
                                    <div className="d-grid mt-2 mb-2 "></div>
                            }
                            {
                                !isReplace && !isSerieReplace &&
                                <>
                                    {
                                        hit.userId > 0 ? (
                                            <div className="col-12 mb-2  ">
                                                <div className="d-grid mb-2 ">
                                                    <button className="btn btn-primary" onClick={handleEditExercise}>
                                                        {t("exerciseLibraryComponent:edit")}
                                                    </button>
                                                </div>
                                                <div className="d-grid">
                                                    <button className="btn btn-outline-danger" onClick={handleDeleteExercise}>
                                                        {t("exerciseLibraryComponent:delete")}
                                                    </button>
                                                </div>
                                            </div>
                                        ) : (
                                            <div className="col-12   mb-2">
                                                <div className="d-grid">
                                                    <button className="btn btn-primary" onClick={handleCustomExercise}>
                                                        {t("exerciseLibraryComponent:customizeExercise")}
                                                    </button>
                                                </div>
                                            </div>
                                        )
                                    }
                                </>
                            }
                            <div className="d-grid  ">
                                <button className="btn btn-outline-primary" onClick={handleCloseVideo}>
                                    {t("exerciseLibraryComponent:close")}
                                </button>
                            </div>
                        </div>
                    </motion.div>
                </Modal.Body>
            </Modal>
            <Modal show={showDeleteModal} onHide={handleDeleteExercise} centered>
                <Modal.Body>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation"}
                        iconColor={"text-danger"}
                        title={t("exerciseLibraryComponent:confirmDeleteCategory")}
                        subtitle={t("exerciseLibraryComponent:irreversibleAction")}
                    />
                    <div className="row mt-3 justify-content-center">
                        <div className="col-12">
                            <div className="d-grid">
                                <button className="btn btn-danger" onClick={handleDeleteExerciseClick}>
                                    {t("exerciseLibraryComponent:delete")}
                                </button>
                            </div>
                            <div className="d-grid mt-2">
                                <button className="btn btn-outline-danger" onClick={handleDeleteExercise}>
                                    {t("exerciseLibraryComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    );
};

export default ExerciseLibraryCard;
