import {useDispatch, useSelector} from "react-redux";
import {getAiEvaluationAnalysis, getWaiting} from "../../store/ai-actions/aiActionsSelector";
import {useEffect, useRef, useState} from "react";
import {evaluationAnalysis} from "../../store/ai-actions/aiActionsReducer";
import AiResponseWaiting from "./AiResponseWaiting";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import AiAssistantEvaluations from "./AiAssistantEvaluations";

export const AiEvaluationAnalysis = ({id, aiAnalysis, setIsExpanded, isExpanded}) => {
    const dispatch = useDispatch();
    const {t} = useTranslation();
    useComponentTranslations('ai', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const analysisData = useSelector(getAiEvaluationAnalysis);
    const analysisWaiting = useSelector(getWaiting);
    const analysis = analysisData || aiAnalysis;
    const messagesEndRef = useRef(null);
    const componentTopRef = useRef(null);
    const CHAR_LIMIT = 300;
    const [message, setMessage] = useState("");

    let showToggleButton = true;

    const handleAnalysisClick = () => {
        dispatch(evaluationAnalysis(id));
    };

    const handleCollapse = () => {
        setIsExpanded(false);
        componentTopRef.current?.scrollIntoView({behavior: "smooth", block: "start"});
    };

    useEffect(() => {
        if (analysis) {
            if (typeof analysis === 'object') {
                let truncatedMsg = analysis.message;
                if (!isExpanded && analysis.message.length > CHAR_LIMIT) {
                    truncatedMsg = analysis.message.substring(0, CHAR_LIMIT) + "...";
                }
                setMessage({...analysis, message: truncatedMsg});
            } else {
                let content = analysis;
                if (!isExpanded && content.length > CHAR_LIMIT) {
                    content = content.substring(0, CHAR_LIMIT) + "...";
                }
                setMessage(content);
            }
        }
    }, [analysis, isExpanded]);

    useEffect(() => {
        if (!aiAnalysis) {
            dispatch(evaluationAnalysis(id));
        }
    }, [aiAnalysis, dispatch, id])

    useEffect(() => {
        const handleBeforePrint = () => setIsExpanded(true);
        window.addEventListener("beforeprint", handleBeforePrint);
        return () => window.removeEventListener("beforeprint", handleBeforePrint);
    }, [setIsExpanded]);

    return (
        <div className={"text-center d-print-block"} ref={componentTopRef}>
            <div className={"row justify-content-center pt-2 pb-3"}>
                <div className={"col-auto"}>
                    <i className={"fa-kit fa-mfit-ai text-mfit-ai-gradient me-2"} style={{fontSize: "2rem"}}/>
                    <span className={"fw-bold text-mfit-ai-gradient me-2"} style={{fontSize: "2rem"}}>MFIT</span>
                    <span className={"fw-light text-mfit-ai-gradient"} style={{fontSize: "2rem"}}>IA</span>
                </div>
            </div>
            <div className={"row"}>
                <div className={"col-12"}>
                    {analysisWaiting &&
                        <>
                            <AiResponseWaiting/>
                            <br/>
                        </>
                    }
                    {analysis && !analysisWaiting && (
                        <>
                            <AiAssistantEvaluations msg={message}/>
                        </>
                    )}
                    <div ref={messagesEndRef}/>
                    {showToggleButton && !isExpanded &&
                        <button className={"btn btn-link text-mfit-ai fw-semibold d-print-none"}
                                onClick={() => setIsExpanded(true)}
                        >
                            {t("ai:seeMore")}
                        </button>
                    }
                    {isExpanded && (
                        <>
                            <div className={"row my-3"}>
                                <div className={"col-12"}>
                                    <hr className={"mt-0"}/>
                                    <span className={"text-center small d-block text-mfit-ai"}>
                                    {t("ai:disclaimerAnalysis")}
                                </span>
                                </div>
                            </div>
                            <div className={"mb-2"}>
                                <button
                                    className={"btn btn-sm text-mfit-ai border border-1 border-primary bg-mfit-ai-subtle"}
                                    disabled={analysisWaiting}
                                    onClick={handleAnalysisClick}
                                >
                                    {t("ai:generateAnalysis")} <i className={"fa-kit fa-mfit-ai me-1"}/>
                                    <span className={"fw-bold me-1"}>MFIT</span>
                                    <span className={"fw-light"}>IA</span>
                                </button>
                            </div>
                        </>
                    )}
                </div>
            </div>
            {showToggleButton && isExpanded && (
                <>
                    <button
                        className="btn btn-link text-mfit-ai fw-semibold d-print-none"
                        onClick={handleCollapse}
                    >
                        {t("ai:seeLess")}
                    </button>
                </>
            )}
        </div>
    );
};

export default AiEvaluationAnalysis;
