import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchLastVo2MaxAPI = async (clientId) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/evaluation/vo2max?id=${clientId}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'Authorization': token
            },
            timeout: 20000
        }
    )
};

