import Page from "../../components/page/Page";
import {useNavigate} from "react-router-dom";
import {useEffect, useState} from "react";
import {checkCoupon, setCoupon, setTransaction} from "../../store/subscription/subscriptionReducer";
import {useDispatch, useSelector} from "react-redux";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import {selectCoupon, selectCouponLoading} from "../../store/subscription/subscriptionSelector";
import Modal from "react-bootstrap/Modal";
import {fetchUser} from "../../store/user/userReducer";
import {selectUser} from "../../store/user/userSelector";
import {Trans, useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionPaymentSuccess = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const coupon = useSelector(selectCoupon);
    const couponLoading = useSelector(selectCouponLoading);
    const upgradeCoupon = "PKQSBSWZ"
    const [sendOffer, setSendOffer] = useState(false);
    const [showOffer, setShowOffer] = useState(false);
    const user = useSelector(selectUser)
    useComponentTranslations('subscriptionPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const style = {
        backgroundImage: 'linear-gradient(185deg, rgba(12,146,235,1) 3.97%, rgba(23,35,49,1) 96.03%)',
    }

    const handleGoToOfferClick = () => {
        navigate(`/subscription/purchase/1001/coupon/${upgradeCoupon}`)
    }

    const handleShowOffer = () => {
        setShowOffer(prevState => !prevState)
    }

    const goToApp = () => {
        dispatch(setCoupon(null))
        navigate("/user")

    }
    const handleGoToAppClick = () => {
        if(!couponLoading) {
            if (!sendOffer)
                goToApp()
            else
                handleShowOffer()
        }
    }

    useEffect(() => {
        const payload = {coupon: upgradeCoupon, subPlan: 1001}
        dispatch(checkCoupon(payload))
        dispatch(setTransaction(null));
    }, [dispatch]);

    useEffect(() => {
        if (coupon && coupon.name === upgradeCoupon && !coupon.invalidCouponMessage && user.subPlan.id === 1000) {
            setSendOffer(true)
        } else {
            setSendOffer(false)
        }
    }, [coupon, user, user?.subPLan])

    useEffect(() => {
        dispatch(fetchUser())
    }, [dispatch])


    return (
        <Page mt="mt-n4" showGoBack={false} loading={couponLoading}>
            <div className={"row"}>
                <div className={"col-12"}>
                    <div className={"card card-body border-0"}>
                        <div className={"row justify-content-center"}>
                            <div className={"col-12 text-center mt-4 mb-4"}>
                                <RoundedIcon size={"lg"} icon={"fa-check"}/>
                            </div>
                            <div className={"col-12 text-center  "}>
                                <h2 className={"fw-semibold"}>{t("subscriptionPage:paymentApprovedTitle")}</h2>
                                <p className={"text-muted"}>{t("subscriptionPage:paymentApprovedDescription")}</p>
                            </div>
                            <div className={"col-12 text-center  "}>
                                <button className={"btn btn-primary-lighter w-100"} onClick={handleGoToAppClick}>{t("subscriptionPage:goToApp")}</button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <Modal show={showOffer} centered>
                <Modal.Body  style={style}>
                    <div className={"row justify-content-center"}>
                        <div className={"col-12 text-center mt-2 mb-2"}>
                            <i style={{fontSize: "3rem"}} className={"fa-solid fa-stars text-white"}></i>
                        </div>
                        <div className={"col-12 text-center  mt-2 mb-2"}>
                            <span className={"fw-semibold fs-5 text-white"}>{t("subscriptionPage:upgradeOfferYouWon")}</span>
                        </div>
                        <div className={"col-12 text-center   mb-2"}>
                            <span className={"fw-semibold fs-1 text-success-lighter"}>{t("subscriptionPage:upgradeOfferDiscount")}</span>
                        </div>
                        <div className={"col-12 text-center   mb-2"}>
                            <span className={"fw-semibold fs-5 text-white"}>{t("subscriptionPage:upgradeOfferAddMonths")}</span>
                        </div>
                    </div>
                    <div className={"row justify-content-center mt-3 text-white"}>
                        <div className={"col-12 text-center"}>
                            <span className={"fw-semibold "} style={{fontSize: "1.1rem"}}>
                                <Trans
                                    t={t}
                                    i18nKey="subscriptionPage:upgradeOfferSubheader"
                                    components={{bold: <span className={"text-success"}/>}}
                                />
                            </span>
                        </div>
                        <div className={"col-12  mt-4"}>
                            <div className={"row"}>
                                <div className={"col-2 align-self-center text-center"}>
                                    <i className={"fa-regular fa-check-circle fa-xl text-success"}></i>
                                </div>
                                <div className={"col-10 ps-0"}>
                                    <span className={"d-block "}
                                          style={{fontSize: "1.1rem", lineHeight: "1.3"}}>{t("subscriptionPage:upgradeOfferBenefitLibrary")}</span>
                                </div>
                            </div>
                            <div className={"row mt-2"}>
                                <div className={"col-2 align-self-center text-center"}>
                                    <i className={"fa-regular fa-check-circle fa-xl text-success"}></i>
                                </div>
                                <div className={"col-10 ps-0"}>
                                    <span className={"d-block "} style={{fontSize: "1.1rem", lineHeight: "1.3"}}>{t("subscriptionPage:upgradeOfferBenefitWallet")}</span>
                                </div>
                            </div>
                            <div className={"row mt-2"}>
                                <div className={"col-2 align-self-center text-center"}>
                                    <i className={"fa-regular fa-check-circle fa-xl text-success"}></i>
                                </div>
                                <div className={"col-10 ps-0"}>
                                    <span className={"d-block "}
                                          style={{fontSize: "1.1rem", lineHeight: "1.3"}}>{t("subscriptionPage:upgradeOfferBenefitAssessment")}</span>
                                </div>
                            </div>
                            <div className={"row mt-2"}>
                                <div className={"col-2 align-self-center text-center"}>
                                    <i className={"fa-regular fa-check-circle fa-xl text-success"}></i>
                                </div>
                                <div className={"col-10 ps-0"}>
                                    <span className={"d-block "} style={{fontSize: "1.1rem", lineHeight: "1.3"}}>{t("subscriptionPage:upgradeOfferBenefitCourses")}</span>
                                </div>
                            </div>
                            <div className={"row mt-3"}>
                                <div className={"col-12"}>
                                    <button className={"btn btn-primary w-100"} onClick={handleGoToOfferClick}>{t("subscriptionPage:upgradeOfferAccept")}</button>
                                </div>
                                <div className={"col-12 mt-3"}>
                                    <button className={"btn btn-link text-white w-100 fw-semibold"} onClick={goToApp}>{t("subscriptionPage:upgradeOfferDecline")}</button>
                                </div>
                            </div>
                        </div>
                    </div>

                </Modal.Body>
            </Modal>
        </Page>
    )
}
export default SubscriptionPaymentSuccess;
