import { handleError } from "../../utils/error/sagaErrorHandling";
import { all, call, put, takeLatest } from "redux-saga/effects";
import {
    changeStatusPhysicalAPI, comparePhysicalAPI,
    getAllPhysicalAPI,
    getOnePhysicalAPI, savePhysicalAPI, updatePhysicalAPI,lastPhysicalAPI
} from "../../api/evaluation-physical/physicalActions";
import {
    fetchOnePhysical,
    getAllPhysical,
    setAllPhysical,
    setOnePhysical,
    onError,
    setStatusChanged,
    changeStatus,
    savePhysical,
    setSubmitResult,
    updatePhysical,
    setComparePhysical,
    comparePhysical, setLastPhysical, fetchLastPhysical
} from "./physicalEvaluationReducer";

export function* fetchOnePhysicalAsync(action) {
    try {
        const {id} = action.payload;
        const response = yield call(getOnePhysicalAPI, id);
        yield put(setOnePhysical(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchOnePhysical() {
    yield takeLatest(fetchOnePhysical.type, fetchOnePhysicalAsync);
}

export function* fetchAllPhysicalAsync(action) {
    try {
        const {clientId, status, type} = action.payload;
        const response = yield call(getAllPhysicalAPI, clientId, status, type);
        yield put(setAllPhysical(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchAllPhysical () {
    yield takeLatest(getAllPhysical.type, fetchAllPhysicalAsync);
}

export function* changeStatusPhysicalAsync(action) {
    try {
        const {id, status} = action.payload;
        const response = yield call(changeStatusPhysicalAPI, id, status);
        yield put(setStatusChanged({id, status}));
        yield put(setSubmitResult({
            action: status === 1 ? "delete" : "recover",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onChangeStatusPhysical() {
    yield takeLatest(changeStatus.type, changeStatusPhysicalAsync);
}

export function* savePhysicalAsync(action) {
    try {
        const response = yield call(savePhysicalAPI, action.payload);
        yield put(setOnePhysical(response.data));
        yield put(setLastPhysical({
            evaluation: response.data,
            clientId: action.meta?.clientId ?? action.payload?.id_aluno ?? null
        }));
        yield put(setSubmitResult({
            action: "create",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? action.payload?.id_aluno ?? null,
            entityId: response.data?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onSavePhysical() {
    yield takeLatest(savePhysical.type, savePhysicalAsync);
}

export function* updatePhysicalAsync(action) {
    try {
        const response = yield call(updatePhysicalAPI, action.payload);
        yield put(setOnePhysical(response.data));
        yield put(setSubmitResult({
            action: "update",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? action.payload?.id_aluno ?? null,
            entityId: response.data?.id ?? action.payload?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onUpdatePhysical() {
    yield takeLatest(updatePhysical.type, updatePhysicalAsync);
}

export function* comparePhysicalAsync(action) {
    try {
        const {ids} = action.payload;
        const response = yield call(comparePhysicalAPI, ids);
        yield put(setComparePhysical(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onComparePhysical() {
    yield takeLatest(comparePhysical.type, comparePhysicalAsync);
}

export function* fetchLastPhysicalAsync(action) {
    try {
        const clientId = action.payload?.clientId ?? action.payload;
        const response = yield call(lastPhysicalAPI, clientId);
        yield put(setLastPhysical({evaluation: response.data, clientId}));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchLastPhysical() {
    yield takeLatest(fetchLastPhysical.type, fetchLastPhysicalAsync);
}

export function* physicalEvaluationSaga() {
    yield all ([
        call(onFetchOnePhysical),
        call(onFetchAllPhysical),
        call(onChangeStatusPhysical),
        call(onSavePhysical),
        call(onUpdatePhysical),
        call(onComparePhysical),
        call(onFetchLastPhysical)
    ])
}
