import pollock7Fields from './pollock7Fields';

const commonIds = [
    'idade',
    'data',
    'estatura',
    'peso',
    'circ_pesc',
    'circ_ombro',
    'circ_torax',
    'circ_be',
    'circ_bd',
    'circ_cin',
    'circ_abd',
    'circ_quad',
    'circ_ce',
    'circ_cd',
    'circ_pe',
    'circ_pd',
];

const otherIds = [
    'pesoIdeal',
    'proposta',
    'objetivo',
    'observacao',
    'proximaAvaliacao'
];

const pickFields = (ids) => pollock7Fields.filter(f => ids.includes(f.id));

const baseFields = pickFields(commonIds);
const suffixFields = pickFields(otherIds);

const male = [
    ...baseFields,
    ...pickFields(['peitoral', 'abdominal', 'coxa']),
    ...suffixFields,
];

const female = [
    ...baseFields,
    ...pickFields(['tricipital', 'supra', 'coxa']),
    ...suffixFields,
];

const pollock3Fields = { male, female };
export default pollock3Fields;
