import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const FrequencyTrainingDay = ({frequencyDay, day}) => {
    const {t} = useTranslation();
    useComponentTranslations('frequencyComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const getIcon = () => {
        const today = new Date();
        const dayNames = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];

        const adjustedDayIndex = (today.getDay() === 0) ? 6 : today.getDay() - 1;
        const currentDayName = dayNames[adjustedDayIndex];

        const currentHour = today.getHours();

        if (frequencyDay) {
            return 'fa-solid fa-check-circle text-primary';
        } else if (day === currentDayName) {
            if (currentHour >= 22) {
                return 'fa-light fa-circle-exclamation text-danger';
            } else if (currentHour >= 20) {
                return 'fa-light fa-circle-exclamation text-warning';
            } else {
                return 'fa-light fa-circle-exclamation text-primary';
            }
        } else {
            if (dayNames.indexOf(day) > dayNames.indexOf(currentDayName)) {
                return 'fa-light fa-circle text-primary';
            } else {
                return 'fa-light fa-times-circle text-secondary';
            }
        }
    }

    return (
        <div className="flex-fill text-center">
            <i className={`fa-2xl ${getIcon()}`}></i>
            <span className="pt-2 d-block fw-semibold">{t(`frequencyComponent:${day}Abbrev`)}</span>
        </div>
    )
}

export default FrequencyTrainingDay;
