import {normalizeAppLocale} from "./localeUtils";

const MEASUREMENT_VIDEO_BASE_URL = "https://vd.mfitpersonal.com.br/measurements";
const DEFAULT_MEASUREMENT_VIDEO_LOCALE = "pt-BR";
const AVAILABLE_MEASUREMENT_VIDEO_LOCALES = new Set(["pt-BR"]);

const MEASUREMENT_VIDEO_SLUGS = {
    chest: "peitoral",
    biceps: "biceps",
    forearm: "antebraco",
    waist: "cintura",
    abs: "abdomen",
    hip: "quadril",
    thigh: "coxa_medial",
};

export const resolveMeasurementVideoLocale = (locale) => {
    const normalizedLocale = normalizeAppLocale(locale);

    if (AVAILABLE_MEASUREMENT_VIDEO_LOCALES.has(normalizedLocale)) {
        return normalizedLocale;
    }

    return DEFAULT_MEASUREMENT_VIDEO_LOCALE;
};

export const getMeasurementVideoUrl = (fieldId, locale) => {
    const slug = MEASUREMENT_VIDEO_SLUGS[fieldId];

    if (!slug) {
        return null;
    }

    const resolvedLocale = resolveMeasurementVideoLocale(locale);
    return `${MEASUREMENT_VIDEO_BASE_URL}/${slug}_${resolvedLocale}.mp4`;
};
