import React, {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {
    selectResolveAllUpdatesStatus,
    selectUpdateCountByType,
    selectUpdatesLoading
} from "../../store/updates/updatesSelector";
import {clearResolveAllUpdatesStatus, fetchUpdateCountByType, resolveAllUpdates} from "../../store/updates/updatesReducer";
import {useNavigate} from "react-router-dom";
import Modal from "react-bootstrap/Modal";
import UpdateResolveAllModal from "../../components/updates/UpdateResolveAllModal";
import Page from "../../components/page/Page";
import RoundedCard from "../../components/rounded-icon/RoundedCard";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {updateCategories} from "../../components/updates/updateTypeRegistry";

const Updates = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const updateCountByType = useSelector(selectUpdateCountByType);
    const loading = useSelector(selectUpdatesLoading);
    const resolveAllStatus = useSelector(selectResolveAllUpdatesStatus);
    const [showResolveAllModal, setShowResolveAllModal] = useState(false);

    useComponentTranslations('update', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleResolveAllConfirmationClick = () => {
        dispatch(resolveAllUpdates(0));
    };

    const handleShowUpdates = (type) => {
        navigate(`/user/update/list/${type}`);
    };

    const handleResolveAllClick = () => {
        if (resolveAllStatus === "pending") {
            return;
        }
        setShowResolveAllModal(prevState => !prevState);
    };

    const handleGoBack = () => {
        navigate("/user");
    };

    useEffect(() => {
        dispatch(fetchUpdateCountByType());
    }, [dispatch]);

    useEffect(() => {
        if (resolveAllStatus === "success") {
            dispatch(fetchUpdateCountByType());
            setShowResolveAllModal(false);
            dispatch(clearResolveAllUpdatesStatus());
        }

        if (resolveAllStatus === "failure") {
            setShowResolveAllModal(false);
            dispatch(clearResolveAllUpdatesStatus());
        }
    }, [dispatch, resolveAllStatus]);

    const getCountForType = (type) => {
        const raw = updateCountByType?.[type] ?? updateCountByType?.[String(type)] ?? 0;
        return Number(raw) || 0;
    };

    const hasAnyUnread = updateCategories.some(c => getCountForType(c.type) > 0);


    return (
        <>
            <Page
                title={t("update:updatesTitle")} goBackLink={handleGoBack}
                mt={"mt-n5"}
                pb={0}
            >
                {
                    loading &&
                    <div className={'row  '}>
                        <div className={'col-12 pt-4'}>
                            <div className={"card card-body border-0"}>
                                <LoadingBlock/>
                            </div>
                        </div>
                    </div>
                }

                {!loading   &&
                    <>
                        <div className={'row'}>
                            <div className={'col-12 mt-3 pt-1 text-center'}>
                                <div className={'card card-body border-0 pb-4'}>
                                    <div className={'row row-gap-4 pt-2'}>
                                        {updateCategories.map((cat) => (
                                            <RoundedCard
                                                key={cat.type}
                                                text={t(cat.labelKey)}
                                                icon={cat.icon}
                                                col={"col-4"}
                                                unreadCount={getCountForType(cat.type)}
                                                textClass={"small"}
                                                handleClick={() => handleShowUpdates(cat.type)}
                                            />
                                        ))}
                                    </div>

                                    <div className={'row justify-content-center pt-4'}>
                                        <div className={'col-12'}>
                                            <div className={'d-grid mt-2'}>
                                                <button
                                                    disabled={!hasAnyUnread}
                                                    className={"btn btn-primary"}
                                                    onClick={handleResolveAllClick}
                                                >
                                                    {t("update:resolveAll")}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <Modal centered show={showResolveAllModal} onHide={handleResolveAllClick}>
                            <Modal.Body>
                                <UpdateResolveAllModal
                                    handleResolveAllClick={handleResolveAllClick}
                                    isLoading={resolveAllStatus === "pending" || loading}
                                    handleResolveAllConfirmationClick={handleResolveAllConfirmationClick}
                                />
                            </Modal.Body>
                        </Modal>
                    </>
                }
            </Page>
        </>

    );
};

export default Updates;
