import {Image} from "react-bootstrap";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {handleWhatsAppClick} from "../../utils/handlers/handler";
import he from "he";
import {Link} from "react-router-dom";

const ClientItemList = ({client, last}) => {
    const {t} = useTranslation();
    useComponentTranslations('clientComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const handleClientClickUrl = `/user/client/${client.id}`


    return (
        <>
            <li key={client.id} className={'list-group-item border-0 rounded-0 bg-white'}>
                <div className={'row '}>
                    <div className={'col-2 align-self-center clickable-element text-center'}>
                        <Link to={handleClientClickUrl} className={"text-decoration-none text-default"}>
                            <Image src={client.profileUrl ?? "https://cdn.mfitpersonal.com.br/assets/user/user.jpg"}
                                   className={"rounded-circle"} style={{width: "45px"}} fluid/>
                        </Link>
                    </div>
                    <div className={'col-8 align-self-center ps-0 clickable-element'}>
                        <Link to={handleClientClickUrl} className={"text-decoration-none text-default"}>
                            <span className={'d-block fw-semibold lh-1'}>{he.decode(client.nome)}</span>
                            {client.grupo?.id > 0 &&
                                <span
                                    className={'d-block small'}>{client.grupo?.idUser === 0 ? t(`clientComponent:${client.grupo?.nome_i18n}`) : client.grupo?.nome}</span>
                            }
                        </Link>
                    </div>
                    <div className={'col-2 align-self-center'}>
                        {
                            client.status === 0 &&
                            <button onClick={() => handleWhatsAppClick(client.telefone)}
                                    className={' no-style-btn text-success'}><i
                                className={'fa-brands fa-xl fa-whatsapp'}></i></button>
                        }
                    </div>
                </div>
            </li>
            {
                !last &&
                <hr className={"text-secondary my-1"}/>
            }
        </>

    )
}
export default ClientItemList