import React, {useState} from 'react';
import {useTranslation} from "react-i18next";
import ChangeStatus from "../../components/utils/change-status/ChangeStatus";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ShareComponent from "../utils/share/ShareComponent";

const AnamnesisOptionsModal = ({onDelete, onCopyLink, onViewEdit, onSendWhatsAppLink, onClose, link}) => {
    const {t} = useTranslation();
    const [modalContent, setModalContent] = useState('options');
    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleShowModalContent = (content) => {
        setModalContent(content);
    };

    const renderContent = () => {
        switch (modalContent) {
            case 'options':
                return (
                    <div className={"row pt-2"}>
                        <div className={"col-12"}>
                            <div className="position-absolute top-0 end-0 p-3" onClick={onClose}>
                                <i className="fa-regular fa-xmark cursor-pointer"/>
                            </div>
                            <span className={"fw-semibold text-start"}>{t("anamnesisComponent:whatDoYouWant")}</span>
                            <div className="row gap-2 px-2 pt-3">
                                <button className="btn btn-outline-primary" onClick={onViewEdit}>
                                    {t("anamnesisComponent:viewEdit")}
                                </button>
                                <button className="btn btn-outline-primary" onClick={() => handleShowModalContent('share')}>
                                    {t("anamnesisComponent:share")}
                                </button>
                                <button className="btn btn-outline-danger" onClick={() => handleShowModalContent('delete')}>
                                    {t("anamnesis:delete")}
                                </button>
                            </div>
                        </div>
                    </div>
                );
            case 'delete':
                return (
                    <div className={"row pt-2"}>
                        <div className={"col-12"}>
                            <ChangeStatus
                                icon={"fa-regular fa-circle-exclamation"}
                                iconColor={"text-danger"}
                                title={t("anamnesisComponent:areYouSure")}
                                subtitle={t("anamnesisComponent:actionCannotBeUndone")}
                            />
                        </div>
                        <div className={'col-12 mt-3'}>
                            <div className={'d-grid'}>
                                <button className="btn btn-danger mb-2" onClick={onDelete}>
                                    {t("anamnesisComponent:yesDelete")}
                                </button>
                                <button className="btn btn-outline-danger" onClick={onClose}>
                                    {t("anamnesisComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                );
            case 'share':
                return (
                    <ShareComponent link={link} handleClose={onClose} handleCopyLink={onCopyLink} handleWhatsAppLink={onSendWhatsAppLink}/>
                );
            default:
                return null;
        }
    };

    return renderContent();
};

export default AnamnesisOptionsModal;
