import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    updates: null,
    updatesCount: 0,
    updateCountByType: null,
    loadingIndividualUpdate: false,
    loading: false,
    resolveAllUpdatesStatus: 'idle',
    resolveAllUpdatesContext: null,
    resolveAllUpdatesError: null,
    loadingByUpdateId: {},

}

export const slice = createSlice({
    name: 'updates',
    initialState,
    reducers: {
        resolveAllUpdates(state, action) {
            state.loading = true
            state.resolveAllUpdatesStatus = 'pending'
            state.resolveAllUpdatesContext = action.payload?.context ?? null
            state.resolveAllUpdatesError = null
        },
        resolveAllUpdatesSuccess(state, action) {
            state.loading = false
            state.resolveAllUpdatesStatus = 'success'
            state.resolveAllUpdatesContext = action.payload?.context ?? state.resolveAllUpdatesContext
            state.resolveAllUpdatesError = null
            if (action.payload?.updates) {
                state.updates = action.payload.updates
            }
        },
        resolveAllUpdatesFailure(state, action) {
            state.loading = false
            state.resolveAllUpdatesStatus = 'failure'
            state.resolveAllUpdatesContext = action.payload?.context ?? state.resolveAllUpdatesContext
            state.resolveAllUpdatesError = action.payload?.error ?? null
        },
        clearResolveAllUpdatesStatus(state) {
            state.resolveAllUpdatesStatus = 'idle'
            state.resolveAllUpdatesContext = null
            state.resolveAllUpdatesError = null
        },
        respondMyProgressUpdate(state, action) {
            state.loadingByUpdateId[action.payload.id] = true
        },
        respondMyProgressUpdateSuccess(state, action) {
            delete state.loadingByUpdateId[action.payload]
            state.updates = state.updates.filter(update => update.id !== action.payload)
        },
        resolveUpdate(state, action) {
            state.loadingByUpdateId[action.payload] = true
        },
        resolveUpdateSuccess(state, action) {
            delete state.loadingByUpdateId[action.payload]
            state.loading = false
            state.updates = state.updates.filter(update => update.id !== action.payload)
        },
        fetchAllUpdatesByType(state) {
            state.loading = true;
        },
        setUpdatesByType(state, action) {
            state.updates = action.payload
            state.loading = false;
        },
        fetchUpdateCountByType(state) {
            state.loading = true;
        },
        setUpdateCountByType(state, action) {
            state.updateCountByType = action.payload
            state.loading = false
        },
        fetchUpdatesCount(state) {
            state.loading = true;
        },
        setUpdatesCount(state, action) {
            state.updatesCount = action.payload
            state.loading = false
        },
        onError(state) {
            state.loading = false
        }
    }
})

export const {
    fetchUpdatesCount,
    setUpdatesCount,
    fetchUpdateCountByType,
    setUpdateCountByType,
    fetchAllUpdatesByType,
    setUpdatesByType,
    resolveUpdate,
    resolveUpdateSuccess,
    respondMyProgressUpdate,
    respondMyProgressUpdateSuccess,
    resolveAllUpdates,
    resolveAllUpdatesSuccess,
    resolveAllUpdatesFailure,
    clearResolveAllUpdatesStatus,
    onError
} = slice.actions;
export const updatesReducer = slice.reducer;
