import {useCallback, useEffect, useMemo, useRef, useState} from "react";
import {ErrorMessage, Field, Form, Formik} from "formik";
import Select from "react-select";
import * as Yup from "yup";
import {useDispatch, useSelector} from "react-redux";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {isClientsLoading, selectSelectOptions} from "../../store/client/clientSelector";
import {fetchSelectOptions} from "../../store/client/clientReducer";
import {addToast} from "../../store/toast/toastReducer";
import {getAiPush, getWaiting} from "../../store/ai-actions/aiActionsSelector";
import {clearAiPush} from "../../store/ai-actions/aiActionsReducer";
import decodeHtmlEntities from "../../utils/text/decodeHtmlEntities";
import InfoCard from "../info/InfoCard";
import PushMessageFields from "./PushMessageFields";
import PushAudienceFields from "./PushAudienceFields";
import usePushSubmit from "./usePushSubmit";

const MODE_OPTIONS = ["now", "scheduled", "recurring"];

const PushComposerFlow = ({
    allowModeSwitch = true,
    compact = false,
    initialMode = "now",
    initialValues,
    lockedAudience,
    lockedAudiencePlacement = "top",
    modeSelectorVariant = "buttons",
    onSuccess,
    secondaryAction = null,
    showAiGenerator = true
}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const selectOptions = useSelector(selectSelectOptions);
    const loadingClientData = useSelector(isClientsLoading);
    const aiPush = useSelector(getAiPush);
    const waiting = useSelector(getWaiting);
    const {loading, submit} = usePushSubmit(onSuccess);
    const formikRef = useRef(null);
    const [mode, setMode] = useState(initialMode);
    const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;

    const translationsLoaded = useComponentTranslations("push", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        setMode(initialMode);
    }, [initialMode]);

    useEffect(() => {
        dispatch(clearAiPush());
    }, [dispatch]);

    const normalizeLabel = useCallback((label) => {
        if (!translationsLoaded) {
            return decodeHtmlEntities(label);
        }

        return label?.includes("client_group") ? t(`push:${label}`) : decodeHtmlEntities(label);
    }, [t, translationsLoaded]);

    const groupOptions = useMemo(() => {
        if (!translationsLoaded) {
            return [];
        }

        return [
            {value: 0, label: t("push:all")},
            ...(selectOptions?.map((item) => ({
                value: item.id,
                label: normalizeLabel(item.label)
            })) || [])
        ];
    }, [normalizeLabel, selectOptions, t, translationsLoaded]);

    const minDateTime = useMemo(() => {
        const now = new Date();
        const localDate = new Date(now.getTime() - (now.getTimezoneOffset() * 60000));
        localDate.setSeconds(0);
        localDate.setMilliseconds(0);
        return localDate.toISOString().slice(0, 16);
    }, []);

    const dayOptions = useMemo(() => {
        if (!translationsLoaded) {
            return [];
        }

        return [
            {value: "everyday", label: t("push:everyday")},
            {value: "monday", label: t("push:monday")},
            {value: "tuesday", label: t("push:tuesday")},
            {value: "wednesday", label: t("push:wednesday")},
            {value: "thursday", label: t("push:thursday")},
            {value: "friday", label: t("push:friday")},
            {value: "saturday", label: t("push:saturday")},
            {value: "sunday", label: t("push:sunday")}
        ];
    }, [t, translationsLoaded]);

    const validationSchema = useMemo(() => {
        if (!translationsLoaded) {
            return Yup.object({
                title: Yup.string().required(),
                message: Yup.string().required(),
                sendTo: lockedAudience ? Yup.string().default("clients") : Yup.string().required(),
                selectOption: Yup.array().of(Yup.number()).min(1).required()
            });
        }

        const schema = {
            title: Yup.string()
                .required(t("push:required"))
                .max(250, t("push:maxCharacters", {max: 250})),
            message: Yup.string()
                .required(t("push:required"))
                .max(250, t("push:maxCharacters", {max: 250})),
            sendTo: lockedAudience ? Yup.string().default("clients") : Yup.string().required(t("push:required")),
            selectOption: Yup.array()
                .of(Yup.number())
                .min(1, t("push:required"))
                .required(t("push:required"))
        };

        if (mode === "scheduled") {
            schema.dateTime = Yup.date()
                .min(new Date(), t("push:dateTimeInTheFuture"))
                .required(t("push:required"));
        }

        if (mode === "recurring") {
            schema.dateTime = Yup.string().required(t("push:required"));
            schema.daysOfWeek = Yup.array().min(1, t("push:required")).required(t("push:required"));
        }

        return Yup.object(schema);
    }, [lockedAudience, mode, t, translationsLoaded]);

    const formInitialValues = useMemo(() => ({
        title: initialValues?.title || "",
        message: initialValues?.message || "",
        sendTo: lockedAudience?.sendTo || "",
        selectOption: lockedAudience?.selectOption || [],
        daysOfWeek: [],
        dateTime: "",
        timeZone
    }), [initialValues, lockedAudience, timeZone]);

    useEffect(() => {
        if (!lockedAudience || !formikRef.current) {
            return;
        }

        formikRef.current.setFieldValue("sendTo", lockedAudience.sendTo, false);
        formikRef.current.setFieldValue("selectOption", lockedAudience.selectOption, false);
    }, [lockedAudience]);

    useEffect(() => {
        if (!aiPush || !formikRef.current) {
            return;
        }

        if (aiPush.title !== "error") {
            formikRef.current.setFieldValue("title", aiPush.title);
            formikRef.current.setFieldValue("message", aiPush.message);
        } else {
            dispatch(addToast({
                id: Date.now(),
                title: t("push:notificationNotGenerated"),
                message: t("push:aiNotificationRestriction")
            }));
        }

        dispatch(clearAiPush());
    }, [aiPush, dispatch, t]);

    const modeLabel = useCallback((currentMode) => {
        if (!translationsLoaded) {
            return currentMode;
        }

        if (currentMode === "scheduled") {
            return t("push:scheduledMode");
        }
        if (currentMode === "recurring") {
            return t("push:recurringMode");
        }
        return t("push:sendNowMode");
    }, [t, translationsLoaded]);

    const submitLabel = useMemo(() => {
        if (!translationsLoaded) {
            return mode === "recurring" ? "recurring" : mode === "scheduled" ? "scheduled" : "send";
        }

        if (mode === "scheduled") {
            return t("push:schedulePush");
        }
        if (mode === "recurring") {
            return t("push:saveRecurring");
        }
        return t("push:send");
    }, [mode, t, translationsLoaded]);

    const renderModeSelector = useCallback(() => {
        if (!allowModeSwitch) {
            return null;
        }

        if (modeSelectorVariant === "radios") {
            return (
                <div className={"mt-3"}>
                    <label className={"fw-semibold d-block mb-2"}>{t("push:chooseWhenToSend")}</label>
                    <div className={"d-grid gap-1"}>
                        {MODE_OPTIONS.map((option) => (
                            <label key={option} className={"d-flex align-items-center gap-2   m-0 clickable-element"}>
                                <input
                                    type={"radio"}
                                    className={"form-check-input m-0 position-static flex-shrink-0"}
                                    name={"push-mode"}
                                    checked={mode === option}
                                    onChange={() => setMode(option)}
                                />
                                <span>{modeLabel(option)}</span>
                            </label>
                        ))}
                    </div>
                </div>
            );
        }

        return (
            <div className={"btn-group w-100 mb-3"} role={"group"} aria-label={"push-mode"}>
                {MODE_OPTIONS.map((option) => (
                    <button
                        key={option}
                        type={"button"}
                        className={`btn ${mode === option ? "btn-primary" : "btn-outline-primary"}`}
                        onClick={() => setMode(option)}
                    >
                        {modeLabel(option)}
                    </button>
                ))}
            </div>
        );
    }, [allowModeSwitch, mode, modeLabel, modeSelectorVariant, t]);

    const handleSendToChange = useCallback((sendTo) => {
        if (sendTo === "groups") {
            dispatch(fetchSelectOptions("groups"));
        }
    }, [dispatch]);

    return (
        <Formik
            enableReinitialize
            innerRef={formikRef}
            initialValues={formInitialValues}
            validationSchema={validationSchema}
            onSubmit={async (values) => {
                const payload = {
                    title: values.title,
                    message: values.message,
                    sendTo: lockedAudience?.sendTo || values.sendTo,
                    selectOption: lockedAudience?.selectOption || values.selectOption
                };

                if (mode !== "now") {
                    payload.dateTime = values.dateTime;
                    payload.timeZone = values.timeZone;
                }

                if (mode === "recurring") {
                    payload.daysOfWeek = values.daysOfWeek;
                }

                await submit(mode, payload);
            }}
        >
            {({errors, setFieldValue, touched, values}) => (
                <Form>
                    {allowModeSwitch && modeSelectorVariant === "buttons" && renderModeSelector()}

                    <PushMessageFields
                        compact={compact}
                        errors={errors}
                        showAiGenerator={showAiGenerator}
                        t={t}
                        touched={touched}
                        waiting={waiting}
                    />

                    {allowModeSwitch && modeSelectorVariant === "radios" && renderModeSelector()}

                    {(!lockedAudience || lockedAudiencePlacement === "top") && (
                        <PushAudienceFields
                            lockedAudience={lockedAudience}
                            groupsLoading={!lockedAudience && values.sendTo === "groups" && loadingClientData && !selectOptions}
                            onSendToChange={handleSendToChange}
                            groupOptions={groupOptions}
                            setFieldValue={setFieldValue}
                            t={t}
                            touched={touched}
                            values={values}
                            errors={errors}
                        />
                    )}

                    {mode === "scheduled" && (
                        <div className={"form-group mt-2"}>
                            <label className={"fw-semibold"}>{t("push:scheduleTo")}</label>
                            <Field
                                name={"dateTime"}
                                type={"datetime-local"}
                                className={`form-control ${touched.dateTime && errors.dateTime ? "is-invalid" : ""}`}
                                min={minDateTime}
                            />
                            <ErrorMessage name={"dateTime"} component={"div"} className={"invalid-feedback"}/>
                        </div>
                    )}

                    {mode === "recurring" && (
                        <>
                            <div className={"form-group mt-2"}>
                                <label className={"fw-semibold"}>{t("push:recurrence")}</label>
                                <Field name={"daysOfWeek"}>
                                    {() => (
                                        <div>
                                            <Select
                                                isMulti
                                                name={"daysOfWeek"}
                                                options={dayOptions}
                                                className={"basic-multi-select"}
                                                classNamePrefix={"select"}
                                                placeholder={t("push:select")}
                                                noOptionsMessage={() => t("push:noOptions")}
                                                value={(values.daysOfWeek || []).map((value) => dayOptions.find((option) => option.value === value)).filter(Boolean)}
                                                onChange={(selectedOptions) => {
                                                    const hasEveryday = (selectedOptions || []).some((option) => option.value === "everyday");
                                                    if (hasEveryday && selectedOptions.length > 1) {
                                                        setFieldValue("daysOfWeek", ["everyday"]);
                                                        return;
                                                    }
                                                    setFieldValue("daysOfWeek", (selectedOptions || []).map((option) => option.value));
                                                }}
                                            />
                                            {touched.daysOfWeek && errors.daysOfWeek && (
                                                <div className={"invalid-feedback d-block"}>{errors.daysOfWeek}</div>
                                            )}
                                        </div>
                                    )}
                                </Field>
                            </div>
                            <div className={"form-group mt-2"}>
                                <label className={"fw-semibold"}>{t("push:scheduleTo")}</label>
                                <Field
                                    name={"dateTime"}
                                    type={"time"}
                                    className={`form-control ${touched.dateTime && errors.dateTime ? "is-invalid" : ""}`}
                                />
                                <ErrorMessage name={"dateTime"} component={"div"} className={"invalid-feedback"}/>
                            </div>
                        </>
                    )}

                    {mode !== "now" && (
                        <div className={"pt-2"}>
                            <InfoCard
                                title={t("push:beAware")}
                                message1={t("push:beAwareText1")}
                                message2={t("push:beAwareText2")}
                            />
                        </div>
                    )}

                    {lockedAudience && lockedAudiencePlacement === "bottom" && (
                        <PushAudienceFields
                            lockedAudience={lockedAudience}
                            groupsLoading={false}
                            onSendToChange={handleSendToChange}
                            groupOptions={groupOptions}
                            setFieldValue={setFieldValue}
                            t={t}
                            touched={touched}
                            values={values}
                            errors={errors}
                        />
                    )}

                    <div className={`d-grid ${compact ? "mt-3" : "mt-4"}`}>
                        <button type={"submit"} disabled={loading || waiting} className={"btn btn-primary"}>
                            {submitLabel}
                        </button>
                        {secondaryAction && (
                            <button
                                type={"button"}
                                className={"btn btn-outline-primary mt-2"}
                                onClick={secondaryAction.onClick}
                            >
                                {secondaryAction.label}
                            </button>
                        )}
                    </div>
                </Form>
            )}
        </Formik>
    );
};

export default PushComposerFlow;
