import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useDispatch, useSelector} from "react-redux";
import {getAiError, getGeneratedWorkout, getWaiting} from "../../store/ai-actions/aiActionsSelector";
import {generateWorkout as genIa, setAiError, setGeneratedWorkout} from "../../store/ai-actions/aiActionsReducer";
import React, {useCallback, useEffect, useState} from "react";
import _ from "lodash";
import WorkoutSessionAiExerciseCard from "./WorkoutSessionAiExerciseCard";
import {useParams} from "react-router-dom";
import {generateWorkout, setGeneratingWorkout} from "../../store/workout-prescription/workoutPrescriptionReducer";
import {selectWorkoutGenerating} from "../../store/workout-prescription/workoutPrescriptionSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutSessionAiForm = ({handleClose}) => {
    const {t} = useTranslation();
    useComponentTranslations('workoutPrescriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const dispatch = useDispatch();
    const {sessionId} = useParams();
    const waitingIa = useSelector(getWaiting);
    const [showFirst, setShowFirst] = useState(true);
    const [showSecond, setShowSecond] = useState(false);
    const generatedWorkout = useSelector(getGeneratedWorkout);
    const generatingWorkout = useSelector(selectWorkoutGenerating);
    const aiError = useSelector(getAiError)

    const borderStyle = {
        border: "1px solid #355DEA",
    }

    const validationSchema = Yup.object({
        muscleGroups: Yup.string()
            .required(t('workoutPrescriptionComponent:requiredField'))
            .min(4, t('workoutPrescriptionComponent:min4Characters'))
            .max(245, t('workoutPrescriptionComponent:max245Characters')),
        exerciseCount: Yup.number()
            .required(t('workoutPrescriptionComponent:requiredField'))
            .min(3, t('workoutPrescriptionComponent:min3Exercises'))
            .max(8, t('workoutPrescriptionComponent:max12Exercises')),
        description: Yup.string()
            .required(t('workoutPrescriptionComponent:requiredField'))
            .min(50, t('workoutPrescriptionComponent:min50Characters'))
            .max(500, t('workoutPrescriptionComponent:max500Characters')),
        exerciseType: Yup.string()
            .oneOf(
                ['0', '1', '2'],
                t('workoutPrescriptionComponent:selectValidType')
            )
            .required(t('workoutPrescriptionComponent:requiredField')),
    });

    const initialValues = {
        muscleGroups: '',
        exerciseCount: '',
        description: '',
        exerciseType: '1',
    };

    const handleSubmit = (values) => {
        dispatch(genIa(values))
    };

    const handleGenerateAgain = useCallback(() => {
        dispatch(setGeneratedWorkout(null))
    }, [dispatch])

    const handleGenerateWorkout = () => {
        const payload = {
            id: sessionId,
            data: generatedWorkout
        }
        dispatch(generateWorkout(payload))
    }

    const handleErrorTryAgain = () => {
        dispatch(setAiError(false))
        handleGenerateAgain()
    }

    useEffect(() => {
        if (generatingWorkout) {
            handleGenerateAgain()
            dispatch(setGeneratingWorkout(false))
            handleClose();
        }
    }, [generatingWorkout, dispatch, handleClose, handleGenerateAgain]);

    useEffect(() => {
        if (waitingIa) {
            const timer = setTimeout(() => {
                setShowSecond(true);
                setShowFirst(false);
            }, 3000);

            return () => {
                setShowSecond(false);
                setShowFirst(true);
                clearTimeout(timer)
            };
        }
    }, [waitingIa]);

    return (
        <>
            <div className={"row justify-content-center mt-3 mb-4"}>
                <div className={"col-auto text-mfit-ai-gradient pe-1"}>
                    <i
                        className="fa-kit fa-mfit-ai "
                        style={{fontSize: "4rem"}}
                    ></i>{' '}

                </div>
                <div className={"col-auto text-mfit-ai-gradient align-self-center ps-1"}>
                    <span className="fw-bold" style={{fontSize: "2rem"}}>MFIT</span>{' '}
                    <span className="fw-light" style={{fontSize: "2rem"}}>IA</span>
                </div>
            </div>
            {
                (waitingIa || generatingWorkout) && !aiError &&
                <div className={"row justify-content-center "}>
                    <div className={"col-12 text-center fs-5 fw-semibold"}>
                        {showFirst && !generatingWorkout && <span>{t('workoutPrescriptionComponent:readingInstructions')}</span>}
                        {showFirst && generatingWorkout && <span>{t('workoutPrescriptionComponent:wait')}</span>}
                        {showSecond && <span>{t('workoutPrescriptionComponent:buildingWorkout')}</span>}
                    </div>
                    <div className={"col-12 text-center mt-2 mb-2 "}>
                        <span>
                            {t('workoutPrescriptionComponent:mayTakeAWhile')}
                        </span>
                    </div>
                </div>
            }
            {
                !aiError && !waitingIa && generatedWorkout &&
                <div className={"row justify-content-center  "}>
                    <div className={"col-12 text-center"}>
                        <span className={"d-block fw-semibold fs-4"}>
                            {t('workoutPrescriptionComponent:workoutReady')}
                        </span>
                        <span className={"d-block mt-2 mb-1"}>
                            {t('workoutPrescriptionComponent:clickCreateToAdjust')}
                        </span>
                    </div>
                    <div className={"col-12  mt-3 "} style={{height: "350px", overflow: "auto"}}>
                        {
                            _.map(generatedWorkout, (ex =>
                                    <WorkoutSessionAiExerciseCard ex={ex} key={ex.id}/>
                            ))
                        }
                    </div>
                    <div className={"col-12 mt-2"}>
                        <div className={"d-grid mb-2"}>
                            <button className={"btn bg-mfit-ai text-white"} onClick={handleGenerateWorkout}>
                                {t('workoutPrescriptionComponent:createThisWorkout')}
                            </button>
                        </div>
                        <div className={"d-grid"}>
                            <button className={"btn   text-mfit-ai border border-1 border-primary bg-mfit-ai-subtle"} onClick={handleGenerateAgain}>
                                <i className={"fa-solid fa-refresh text-mfit-ai"}></i> {t('workoutPrescriptionComponent:generateAgain')}
                            </button>
                        </div>
                    </div>
                </div>
            }
            {
                !aiError && !waitingIa && !generatedWorkout &&
                <div className={"row justify-content-center"}>
                    <div className={"col-12 pb-2"}>
                        <span className={"fs-5 fw-semibold  "}>{t('workoutPrescriptionComponent:configureWorkout')}</span>
                    </div>
                    <div className={"col-12"}>
                        <Formik
                            initialValues={initialValues}
                            validationSchema={validationSchema}
                            onSubmit={handleSubmit}
                        >
                            {({isSubmitting}) => (
                                <Form>
                                    <div className="mb-3">
                                        <label htmlFor="muscleGroups" className="form-label fw-semibold">
                                            {t('workoutPrescriptionComponent:muscleGroups')}
                                        </label>
                                        <Field
                                            id="muscleGroups"
                                            name="muscleGroups"
                                            type="text"
                                            placeHolder={t("workoutPrescriptionComponent:iaFormPlaceHolder")}
                                            className="form-control"
                                            style={borderStyle}
                                        />
                                        <div className="text-danger">
                                            <ErrorMessage name="muscleGroups"/>
                                        </div>
                                    </div>
                                    <div className="mb-3">
                                        <label htmlFor="exerciseType" className="form-label fw-semibold">
                                            {t('workoutPrescriptionComponent:exerciseType')}
                                        </label>
                                        <Field
                                            as="select"
                                            id="exerciseType"
                                            name="exerciseType"
                                            className="form-select"
                                            style={borderStyle}
                                        >
                                            <option value="">{t('workoutPrescriptionComponent:select')}</option>
                                            <option value="0">{t('workoutPrescriptionComponent:all')}</option>
                                            <option value="1">
                                                {t('workoutPrescriptionComponent:onlyAppExercises')}
                                            </option>
                                            <option value="2">
                                                {t('workoutPrescriptionComponent:onlyMyExercises')}
                                            </option>
                                        </Field>
                                        <div className="text-danger">
                                            <ErrorMessage name="exerciseType"/>
                                        </div>
                                    </div>
                                    <div className="mb-3">
                                        <label htmlFor="exerciseCount" className="form-label  fw-semibold">
                                            {t('workoutPrescriptionComponent:exerciseCount')}
                                        </label>
                                        <Field
                                            id="exerciseCount"
                                            name="exerciseCount"
                                            type="number"
                                            className="form-control"
                                            style={borderStyle}
                                            placeHolder={5}
                                        />
                                        <div className="text-danger">
                                            <ErrorMessage name="exerciseCount"/>
                                        </div>
                                    </div>
                                    <div className="mb-3">
                                        <label htmlFor="description" className="form-label  fw-semibold">
                                            {t('workoutPrescriptionComponent:description')}
                                        </label>
                                        <Field
                                            id="description"
                                            name="description"
                                            as="textarea"
                                            className="form-control"
                                            placeholder={t('workoutPrescriptionComponent:aiPlaceholder')}
                                            style={borderStyle}
                                            rows={6}
                                        />
                                        <div className="text-danger">
                                            <ErrorMessage name="description"/>
                                        </div>
                                    </div>
                                    <div className={"d-grid"}>
                                        <button
                                            type="submit"
                                            className="btn bg-mfit-ai  text-white"
                                            disabled={isSubmitting}
                                        >
                                            {t('workoutPrescriptionComponent:generateWorkout')}
                                        </button>
                                    </div>
                                </Form>
                            )}
                        </Formik>
                    </div>
                </div>
            }
            {
                aiError &&
                <div className={"row"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0 bg-warning-subtle"}>
                            <div className={"row justify-content-center"}>
                                <div className={"col-12 text-center text-warning"}>
                                    <i className={"fa-regular fa-info-circle fa-xl"}></i>
                                </div>
                                <div className={"col-12 text-center text-warning pt-2"}>
                                    {t('workoutPrescriptionComponent:iaError1')}<br/>{t('workoutPrescriptionComponent:iaError2')}
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className={"col-12 pt-4"}>
                        <button
                            onClick={handleErrorTryAgain}
                            className="btn bg-mfit-ai  text-white w-100"
                        >
                            {t('workoutPrescriptionComponent:tryAgain')}
                        </button>
                    </div>
                </div>

            }
        </>
    )
}

export default WorkoutSessionAiForm;