import { createSlice } from "@reduxjs/toolkit";

const initialState = {
    vo2Max: null,
    vo2maxHistory: null,
    loading:false,
    loadingVo2Max:false,
    fcRep: null,
    loadingFcRep: false
};

export const slice = createSlice({
    name: 'evaluation',
    initialState,
    reducers: {
        fetchHistoryVo2: (state) => {
            state.loadingVo2Max = true;
        },
        setHistoryVo2: (state, action) => {
            state.loadingVo2Max = false;
            state.vo2maxHistory = action.payload;
        },
        fetchLastVo2Max: (state) => {
            state.loadingVo2Max = true;
        },
        setLastVo2Max: (state, action) => {
            state.loadingVo2Max = false;
            state.vo2Max = action.payload;
        },
        saveVo2Max: (state) => {
            state.loadingVo2Max = true;
        },
        saveFcRep: (state) => {
            state.loadingFcRep = false;
        },
        fetchFcRep: (state) => {
            state.loadingFcRep = true;
        },
        setFcRep: (state, action) => {
            state.loadingFcRep = false;
            state.fcRep = action.payload;
        },
        onError(state) {
            state.loadingFcRep = false;
            state.loadingVo2Max= false;
            state.loading = false;
        },
    },
});

export const {
    fetchHistoryVo2,
    fetchLastVo2Max,
    fetchFcRep,
    setHistoryVo2,
    setLastVo2Max,
    setFcRep,
    saveVo2Max,
    saveFcRep,
    onError,
} = slice.actions;

export const evaluationReducer = slice.reducer;
