import {useCallback, useEffect, useRef, useState} from "react"
import {driver} from "driver.js"
import "./guidedTourDriverShim.scss"
import {isConnectedElement, resolveConnectedTarget} from "./guidedTourDom"

const EMPTY_DRIVER_CONFIG = {}
const TARGET_RESOLUTION_RETRY_LIMIT = 8
const DEFAULT_DRIVER_CONFIG = {
    allowClose: true,
    overlayClickBehavior: "close",
    overlayColor: "#000",
    overlayOpacity: 0.7,
    showButtons: [],
    showProgress: false,
    smoothScroll: true,
    stagePadding: 12,
    stageRadius: 16
}

const getFrameScheduler = () => {
    if (typeof window === "undefined") {
        return {
            request: () => null,
            cancel: () => {
            }
        }
    }

    return {
        request: typeof window.requestAnimationFrame === "function"
            ? window.requestAnimationFrame.bind(window)
            : (callback) => window.setTimeout(callback, 16),
        cancel: typeof window.cancelAnimationFrame === "function"
            ? window.cancelAnimationFrame.bind(window)
            : (frameId) => window.clearTimeout(frameId)
    }
}

const getStoredTourState = (storageKey) => {
    if (typeof window === "undefined") {
        return {available: false, value: null}
    }

    try {
        return {
            available: true,
            value: window.localStorage.getItem(storageKey)
        }
    } catch (error) {
        return {available: false, value: null}
    }
}

const markTourAsSeen = (storageKey) => {
    if (typeof window === "undefined") {
        return false
    }

    try {
        window.localStorage.setItem(storageKey, "seen")
        return true
    } catch (error) {
        return false
    }
}

const normalizeSteps = (steps = []) => {
    return steps.filter((step) => step && typeof step === "object" && typeof step.id === "string" && step.id.trim())
}

const getNextStepIndex = (steps, currentIndex) => {
    const nextIndex = currentIndex + 1
    return nextIndex < steps.length ? nextIndex : -1
}

/**
 * Shared guided-tour controller that keeps Driver.js limited to spotlight behavior.
 *
 * @param {Object} params
 * @param {Array<{
 *   id: string,
 *   title: string,
 *   description: string,
 *   target?: string | Element | (() => Element | null),
 *   allowTargetInteraction?: boolean,
 *   preferredPlacement?: "auto" | "top" | "bottom" | "right" | "left",
 *   mobileBehavior?: "auto" | "sheet" | "popover"
 * }>} params.steps
 * @param {boolean} params.isReady
 * @param {string} params.storageKey
 * @param {{
 *   next: string,
 *   previous: string,
 *   done: string,
 *   skip: string,
 *   closeAriaLabel: string
 * }} params.labels
 * @param {boolean} [params.autoStart=true]
 * @param {boolean} [params.markSeenOnStart=true]
 * @param {Object} [params.driverConfig={}]
 * @returns {{
 *   isOpen: boolean,
 *   hasStarted: boolean,
 *   activeStep: Object | null,
 *   activeIndex: number,
 *   totalSteps: number,
 *   isFirstStep: boolean,
 *   isLastStep: boolean,
 *   canGoPrevious: boolean,
 *   canGoNext: boolean,
 *   activeTargetElement: HTMLElement | null,
 *   start: () => boolean,
 *   next: () => void,
 *   previous: () => void,
 *   close: () => void,
 *   skip: () => void,
 *   complete: () => void
 * }}
 */
const useGuidedTour = ({
    steps = [],
    isReady,
    storageKey,
    labels,
    autoStart = true,
    markSeenOnStart = true,
    driverConfig = EMPTY_DRIVER_CONFIG
}) => {
    const [resolvedSteps, setResolvedSteps] = useState([])
    const [activeIndex, setActiveIndex] = useState(0)
    const [isOpen, setIsOpen] = useState(false)
    const [hasStarted, setHasStarted] = useState(false)
    const [activeTargetElement, setActiveTargetElement] = useState(null)
    const [targetResolutionNonce, setTargetResolutionNonce] = useState(0)

    const driverRef = useRef(null)
    const autoStartFrameRef = useRef(null)
    const targetResolveFrameRef = useRef(null)
    const startedRef = useRef(false)
    const destroyingRef = useRef(false)
    const bodyOverflowRef = useRef(null)
    const driverConfigRef = useRef(driverConfig)

    driverConfigRef.current = driverConfig

    const clearAutoStartFrame = useCallback(() => {
        if (autoStartFrameRef.current === null) {
            return
        }

        const frameScheduler = getFrameScheduler()
        frameScheduler.cancel(autoStartFrameRef.current)
        autoStartFrameRef.current = null
    }, [])

    const clearTargetResolutionFrame = useCallback(() => {
        if (targetResolveFrameRef.current === null) {
            return
        }

        const frameScheduler = getFrameScheduler()
        frameScheduler.cancel(targetResolveFrameRef.current)
        targetResolveFrameRef.current = null
    }, [])

    const restoreBodyOverflow = useCallback(() => {
        if (typeof document === "undefined" || bodyOverflowRef.current === null) {
            return
        }

        document.body.style.overflow = bodyOverflowRef.current
        bodyOverflowRef.current = null
    }, [])

    const destroyActiveDriver = useCallback(() => {
        if (!driverRef.current) {
            return
        }

        destroyingRef.current = true
        driverRef.current.destroy()
        driverRef.current = null
    }, [])

    const closeTourState = useCallback(() => {
        clearTargetResolutionFrame()
        setIsOpen(false)
        setActiveIndex(0)
        setResolvedSteps([])
        setActiveTargetElement(null)
        setTargetResolutionNonce(0)
    }, [clearTargetResolutionFrame])

    const closeTour = useCallback(() => {
        closeTourState()
        destroyActiveDriver()
    }, [closeTourState, destroyActiveDriver])

    const createDriverInstance = useCallback(() => {
        if (driverRef.current) {
            return driverRef.current
        }

        const providedOnDestroyed = driverConfigRef.current?.onDestroyed
        const driverObject = driver({
            ...DEFAULT_DRIVER_CONFIG,
            ...driverConfigRef.current,
            onDestroyed: (element, step, opts) => {
                driverRef.current = null
                providedOnDestroyed?.(element, step, opts)

                if (destroyingRef.current) {
                    destroyingRef.current = false
                    return
                }

                closeTourState()
            }
        })

        driverRef.current = driverObject
        return driverObject
    }, [closeTourState])

    const start = useCallback(() => {
        const normalizedSteps = normalizeSteps(steps)

        if (normalizedSteps.length === 0) {
            return false
        }

        startedRef.current = true
        setResolvedSteps(normalizedSteps)
        setActiveIndex(0)
        setHasStarted(true)
        setIsOpen(true)

        if (markSeenOnStart) {
            markTourAsSeen(storageKey)
        }

        return true
    }, [markSeenOnStart, steps, storageKey])

    const next = useCallback(() => {
        setActiveIndex((currentIndex) => {
            return currentIndex < resolvedSteps.length - 1
                ? currentIndex + 1
                : currentIndex
        })
    }, [resolvedSteps.length])

    const previous = useCallback(() => {
        setActiveIndex((currentIndex) => currentIndex > 0 ? currentIndex - 1 : currentIndex)
    }, [])

    const close = useCallback(() => {
        closeTour()
    }, [closeTour])

    const skip = useCallback(() => {
        closeTour()
    }, [closeTour])

    const complete = useCallback(() => {
        closeTour()
    }, [closeTour])

    const rerunActiveTargetResolution = useCallback(() => {
        clearTargetResolutionFrame()
        setActiveTargetElement(null)
        destroyActiveDriver()
        setTargetResolutionNonce((currentNonce) => currentNonce + 1)
    }, [clearTargetResolutionFrame, destroyActiveDriver])

    useEffect(() => {
        if (typeof document === "undefined") {
            return
        }

        if (!isOpen) {
            restoreBodyOverflow()
            return
        }

        if (bodyOverflowRef.current === null) {
            bodyOverflowRef.current = document.body.style.overflow
        }

        document.body.style.overflow = "hidden"

        return () => {
            restoreBodyOverflow()
        }
    }, [isOpen, restoreBodyOverflow])

    useEffect(() => {
        if (!isOpen) {
            return
        }

        const activeStep = resolvedSteps[activeIndex]

        if (activeStep?.target) {
            return
        }

        const handleEscape = (event) => {
            if (event.key === "Escape") {
                closeTour()
            }
        }

        window.addEventListener("keydown", handleEscape)

        return () => {
            window.removeEventListener("keydown", handleEscape)
        }
    }, [activeIndex, closeTour, isOpen, resolvedSteps])

    useEffect(() => {
        clearTargetResolutionFrame()

        if (!isOpen) {
            setActiveTargetElement(null)
            destroyActiveDriver()
            return
        }

        const activeStep = resolvedSteps[activeIndex]

        if (!activeStep) {
            setActiveTargetElement(null)
            closeTour()
            return
        }

        if (!activeStep.target) {
            setActiveTargetElement(null)
            destroyActiveDriver()
            return
        }

        let cancelled = false
        const frameScheduler = getFrameScheduler()

        destroyActiveDriver()
        setActiveTargetElement(null)

        const resolveStepTarget = (attempt = 0) => {
            if (cancelled) {
                return
            }

            const resolvedTarget = resolveConnectedTarget(activeStep.target)

            if (resolvedTarget) {
                setActiveTargetElement(resolvedTarget)
                const driverObject = createDriverInstance()

                driverObject.highlight({
                    element: resolvedTarget,
                    disableActiveInteraction: !activeStep.allowTargetInteraction
                })

                return
            }

            if (attempt + 1 < TARGET_RESOLUTION_RETRY_LIMIT) {
                targetResolveFrameRef.current = frameScheduler.request(() => {
                    resolveStepTarget(attempt + 1)
                })
                return
            }

            const nextStepIndex = getNextStepIndex(resolvedSteps, activeIndex)

            if (nextStepIndex === -1) {
                closeTour()
                return
            }

            setActiveIndex(nextStepIndex)
        }

        resolveStepTarget()

        return () => {
            cancelled = true
            clearTargetResolutionFrame()
        }
    }, [
        activeIndex,
        clearTargetResolutionFrame,
        closeTour,
        createDriverInstance,
        destroyActiveDriver,
        isOpen,
        resolvedSteps,
        targetResolutionNonce
    ])

    useEffect(() => {
        if (typeof MutationObserver === "undefined" || typeof document === "undefined") {
            return
        }

        if (!isOpen || !activeTargetElement || !resolvedSteps[activeIndex]?.target) {
            return
        }

        if (!isConnectedElement(activeTargetElement)) {
            rerunActiveTargetResolution()
            return
        }

        const observer = new MutationObserver(() => {
            if (!isConnectedElement(activeTargetElement)) {
                observer.disconnect()
                rerunActiveTargetResolution()
            }
        })

        observer.observe(document.body, {
            childList: true,
            subtree: true
        })

        return () => {
            observer.disconnect()
        }
    }, [activeIndex, activeTargetElement, isOpen, rerunActiveTargetResolution, resolvedSteps])

    useEffect(() => {
        if (!autoStart || !isReady || startedRef.current) {
            return
        }

        const storedTourState = getStoredTourState(storageKey)

        if (!storedTourState.available || storedTourState.value === "seen") {
            return
        }

        const frameScheduler = getFrameScheduler()
        let cancelled = false

        autoStartFrameRef.current = frameScheduler.request(() => {
            if (cancelled || startedRef.current) {
                return
            }

            start()
        })

        return () => {
            cancelled = true
            clearAutoStartFrame()
        }
    }, [autoStart, clearAutoStartFrame, isReady, start, storageKey])

    useEffect(() => {
        return () => {
            clearAutoStartFrame()
            clearTargetResolutionFrame()
            destroyActiveDriver()
            restoreBodyOverflow()
        }
    }, [clearAutoStartFrame, clearTargetResolutionFrame, destroyActiveDriver, restoreBodyOverflow])

    const activeStep = isOpen ? resolvedSteps[activeIndex] || null : null
    const totalSteps = resolvedSteps.length
    const isFirstStep = totalSteps > 0 && activeIndex === 0
    const isLastStep = totalSteps > 0 && activeIndex === totalSteps - 1

    return {
        isOpen,
        hasStarted,
        activeStep,
        activeIndex,
        totalSteps,
        isFirstStep,
        isLastStep,
        canGoPrevious: activeIndex > 0,
        canGoNext: activeIndex < totalSteps - 1,
        activeTargetElement,
        start,
        next,
        previous,
        close,
        skip,
        complete,
        labels
    }
}

export default useGuidedTour
