import React, {useCallback} from "react";
import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams, useSearchParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import {selectedSubPlan} from "../../store/subscription/subscriptionSelector";
import { setPaymentMethod} from "../../store/subscription/subscriptionReducer";
import PaymentMethodSelector from "../../components/subscription/PaymentMethodSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionPlanPaymentMethod = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {subId} = useParams();
    const [searchParams] = useSearchParams();
    const subPlan = useSelector(selectedSubPlan);
    const goBackTo = searchParams.get("goBackTo");
    useComponentTranslations("subscriptionPage", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = useCallback(() => {
        navigate(`/subscription/purchase/${subId}${goBackTo ? `?goBackTo=${goBackTo}` : ""}`);
    }, [navigate, subId, goBackTo]);

    const handlePaymentMethodSelect = useCallback((payload) => {
        dispatch(setPaymentMethod(payload));
    }, [dispatch]);

    return (
        <Page mt={"mt-n5"} contentHeader={true} title={t("subscriptionPage:paymentMethodTitle")} goBackLink={handleGoBack}>
            <PaymentMethodSelector subPlan={subPlan} onPaymentMethodSelect={handlePaymentMethodSelect} onGoBack={handleGoBack}/>
        </Page>
    );
};

export default SubscriptionPlanPaymentMethod;

