import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    personalFinance: null,
    createSucceeded: false,
    updateSucceeded: false,
    financeCategory: null,
    financesCategoriesList: [],
    personalFinancesList: null,
    loading: false,
    error: null,
};

export const slice = createSlice({
    name:'personalFinances',
    initialState,
    reducers:{
        getAllCategories(state) {
          state.loading = true;
        },
        setAllCategories(state,action){
          state.financesCategoriesList = action.payload;
          state.loading = false;
        },
        createCategory(state){
          state.loading = true;
        },
        updateCategory(state){
          state.loading = true;
        },
        deleteCategory(state){
            state.loading = true;
        },
        categoryDeleted(state, action){
            state.loading = false;
            state.financesCategoriesList = state.financesCategoriesList
                .filter(financeCategory => financeCategory.id !== action.payload);
        },
        getAllFinances(state){
          state.loading = true;
        },
        setAllFinances(state, action){
            state.loading = false;
            state.personalFinancesList = action.payload;
        },
        getFinance(state){
          state.loading = true;
        },
        setFinance(state, action){
            state.loading = false;
            state.createSucceeded = true;
            state.personalFinance = action.payload;
            state.personalFinancesList.unshift(action.payload);
        },
        resetCreateSucceeded(state) {
            state.createSucceeded = false;
        },
        deletePersonalFinance(state){
          state.loading = true;
        },
        personalFinanceDeleted(state, action){
           state.loading = false;
           state.personalFinance = action.payload;
           state.personalFinancesList = state.personalFinancesList
                .filter(f => f.id !== action.payload);
        },
        editPersonalFinance(state){
          state.loading = true;
          state.updateSucceeded = false;
        },
        personalFinanceEdited(state, { payload: updatedItem }) {
            state.loading = false;
            state.updateSucceeded = true;
            state.personalFinance = updatedItem;
            state.personalFinancesList = state.personalFinancesList.map(item =>
                item.id === updatedItem.id
                    ? updatedItem
                    : item
            );
        },
        resetUpdateSucceeded(state) {
            state.updateSucceeded = false;
        },
        onError(state) {
            state.loading = false;
        }
    }
})

export const {
    getAllCategories, setAllCategories,
    createCategory,
    deleteCategory, categoryDeleted,
    updateCategory,
    getFinance, setFinance,
    deletePersonalFinance, personalFinanceDeleted,
    getAllFinances, setAllFinances,
    editPersonalFinance, personalFinanceEdited,
    resetCreateSucceeded, resetUpdateSucceeded,
    onError
} = slice.actions;

export const personalFinances = slice.reducer;