import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams, useSearchParams} from "react-router-dom";
import {
    selectFinancesCategories, selectPersonalFinancesList,
    selectPersonalFinancesLoading, selectUpdateSucceeded
} from "../../store/personal-finances/personalFinancesSelector";
import {
    editPersonalFinance, getAllCategories, getAllFinances, resetUpdateSucceeded,
} from "../../store/personal-finances/personalFinancesReducer";
import PersonalFinancesForm from "./PersonalFinancesForm";
import {useEffect} from "react";

const EditPersonalFinances = () => {
    const { id } = useParams();
    const [searchParams]  = useSearchParams();
    const startDate       = searchParams.get("startDate");
    const endDate         = searchParams.get("endDate");
    const dispatch        = useDispatch();
    const navigate        = useNavigate();
    const loading         = useSelector(selectPersonalFinancesLoading);
    const list            = useSelector(selectPersonalFinancesList);
    const categories      = useSelector(selectFinancesCategories);
    const updateOk        = useSelector(selectUpdateSucceeded);

    useEffect(() => {
        dispatch(getAllCategories());
        if (startDate && endDate) {
            dispatch(getAllFinances({ startDate, endDate }));
        }
    }, [dispatch, startDate, endDate]);

    useEffect(() => {
        if (updateOk) {
            navigate("/user/personal-finances");
            dispatch(resetUpdateSucceeded());
        }
    }, [updateOk, navigate, dispatch]);

    const finance = Array.isArray(list)
        ? list.find(f => f.id === Number(id))
        : null;

    const handleSubmit = (values) => {
        const payload = {
            id: Number(id),
            pago: values.jaPago === 'sim' ? 1 : 0,
            idUser: finance.idUser,
            valor: Number(values.valor),
            tipoConta: values.tipo === 'receita' ? 0 : 1,
            categoria: Number(values.categoria),
            dataFatura: values.dataVencimento,
            dataPagamento: values.jaPago === 'sim' ? values.quando : null,
            descricao: values.descricao,
            referencia: values.pagoPara,
            observacao: values.observacoes
        };
        dispatch(editPersonalFinance(payload));
    };

    return (
        <PersonalFinancesForm
            financeToEdit={finance}
            categories={categories}
            loading={loading}
            onSubmit={handleSubmit}
        />
    )
}

export default EditPersonalFinances;