import React, {useEffect, useState} from "react";
import {Formik, Form, Field, ErrorMessage} from "formik";
import {useDispatch} from "react-redux";
import * as Yup from "yup";
import {saveVo2Max} from "../../store/evaluation/evaluationReducer";
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {addToast} from "../../store/toast/toastReducer";

const PROTOCOL_COOPER_1970 = 1;
const PROTOCOL_WELTMAN_1989 = 2;

const Vo2Modal = ({show, handleCloseVo2Modal, clientId}) => {
    const dispatch = useDispatch();
    const {t} = useTranslation();
    const [selectedType, setSelectedType] = useState(null);
    useComponentTranslations('evaluationComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object().shape({
        type: Yup.number().required(t("evaluationComponent:selectAType")),
        distance: Yup.number().when('type', (typeValue, schema) => {
            const typeNumber = parseInt(typeValue, 10);
            if (typeNumber === PROTOCOL_COOPER_1970) {
                return schema.required(t("evaluationComponent:requiredField"))
                    .min(1, t("evaluationComponent:distanceBiggerThanZero"));
            } else {
                return schema.nullable();
            }
        }),
        time: Yup.number().when('type', (typeValue, schema) => {
            const typeNumber = parseInt(typeValue, 10);
            if (typeNumber === PROTOCOL_WELTMAN_1989) {
                return schema.required(t("evaluationComponent:requiredField"))
                    .min(1, t("evaluationComponent:timeBiggerThanZero"));
            } else {
                return schema.nullable();
            }
        }),
    });

    const calculateVo2Max = (type, distance, time) => {
        const typeValue = parseInt(type, 10);
        const distanceValue = parseFloat(distance) || 0;
        const timeValue = parseFloat(time) || 0;

        if (typeValue === PROTOCOL_COOPER_1970) {
            return (distanceValue - 504) / 45;
        } else if (typeValue === PROTOCOL_WELTMAN_1989) {
            return 118.4 - (4.774 * timeValue);
        }
        return 0;
    };

    const handleSubmit = (values) => {
        const vo2max = calculateVo2Max(values.type, values.distance, values.time);
        if (isNaN(vo2max)) {
            dispatch(addToast({
                message: t("evaluationComponent:alert"),
                type: "danger",
                title: t("evaluationComponent:somethingWentWrong")
            }))
            return;
        }
        const entry = {
            clientId,
            type: parseInt(values.type, 10),
            distance: values.distance ? parseFloat(values.distance) : 0,
            time: values.time ? parseFloat(values.time) : 0,
            vo2max: parseFloat(vo2max),
        };
        dispatch(saveVo2Max(entry));
        handleCloseVo2Modal();
    };

    useEffect(() => {
        if (show) {
            setSelectedType(null);
        }
    }, [show]);

    return (
        <Modal show={show} onHide={handleCloseVo2Modal} centered>
            <ModalBody>
                <div className="row">
                    <span className="fw-semibold h5">Vo2Máx</span>
                    <div className="pb-2">
                        <Formik
                            initialValues={{type: '', distance: '', time: '', vo2max: ''}}
                            validationSchema={validationSchema}
                            onSubmit={handleSubmit}
                        >
                            {({values, handleChange}) => (
                                <Form>
                                    <div className="mb-3">
                                        <label htmlFor="type" className="form-label fw-semibold">
                                            {t("evaluationComponent:selectType")}
                                        </label>
                                        <Field
                                            as="select"
                                            name="type"
                                            className="form-control"
                                            onChange={(e) => {
                                                handleChange(e);
                                                setSelectedType(parseInt(e.target.value, 10));
                                            }}
                                        >
                                            <option value="">{t("evaluationComponent:select")}</option>
                                            <option value={PROTOCOL_COOPER_1970}>Cooper, 1970</option>
                                            <option value={PROTOCOL_WELTMAN_1989}>Weltman, 1989</option>
                                        </Field>
                                        <ErrorMessage name="type" component="div" className="text-danger"/>
                                    </div>
                                    {
                                        selectedType === PROTOCOL_COOPER_1970 &&
                                        <>
                                            <div className="bg-primary-subtle rounded py-2 px-2 mb-3">
                                                <span
                                                    className="fw-bold">{t("evaluationComponent:instructions")}: </span>
                                                <span>
                                                    {t("evaluationComponent:theStudentMust")}
                                                    <span
                                                        className="fw-semibold"> {t("evaluationComponent:twelveMinutes")}</span>
                                                    {t("evaluationComponent:cooperExplanation")}
                                                </span>
                                            </div>
                                            <div className="mb-3">
                                                <label htmlFor="distance" className="form-label fw-semibold pt-2">
                                                    {t("evaluationComponent:distanceInMeters")}:
                                                </label>
                                                <Field
                                                    name="distance"
                                                    type="number"
                                                    placeholder="1000"
                                                    className="form-control"
                                                    step="1"
                                                    onKeyPress={(e) => {
                                                        if (e.key === '.' || e.key === ',') {
                                                            e.preventDefault();
                                                        }
                                                    }}
                                                    onChange={(e) => {
                                                        const sanitizedValue = e.target.value.replace(/[.,]/g, '');
                                                        e.target.value = sanitizedValue;
                                                        handleChange(e);
                                                    }}
                                                />
                                                <ErrorMessage name="distance" component="div" className="text-red-500"/>
                                            </div>
                                            <div className="bg-secondary-subtle rounded py-2 px-2 mb-3">
                                                <span className="fw-semibold">
                                                    {t("evaluationComponent:formula")}:
                                                </span>
                                                <span className={"d-block"}> Vo2Máx = ({values.distance || 0} - 504) / 45</span>
                                                <span className="fw-semibold d-block">
                                                    {t("evaluationComponent:result")}:</span>
                                                <span>{calculateVo2Max(values.type, parseFloat(values.distance), 0).toFixed(2)} ml/kg/min</span>
                                            </div>
                                        </>
                                    }
                                    {
                                        selectedType === PROTOCOL_WELTMAN_1989 &&
                                        <>
                                            <div className="bg-primary-subtle rounded py-2 px-2 mb-3">
                                                <span
                                                    className="fw-bold d-block">{t("evaluationComponent:instructions")}:</span>
                                                <span>{t("evaluationComponent:studentMustRun")}
                                                    <span
                                                        className="fw-semibold"> {t("evaluationComponent:3200meters")} </span>
                                                    {t("evaluationComponent:shorterTime")}.
                                                </span>
                                            </div>
                                            <div className="mb-3">
                                                <label htmlFor="time" className="form-label fw-semibold pt-2">
                                                    {t("evaluationComponent:timeInMinutes")}:
                                                </label>
                                                <Field
                                                    name="time"
                                                    type="number"
                                                    placeholder="30"
                                                    className="form-control"
                                                />
                                                <ErrorMessage name="time" component="div" className="text-red-500"/>
                                            </div>
                                            <div className="bg-secondary-subtle rounded py-2 px-2 mb-3">
                                                <span className="fw-semibold">{t("evaluationComponent:formula")}:</span>
                                                <span
                                                    className={"d-block"}>Vo2Máx = 118.4 - (4.774 * {values.time || 0})</span>
                                                <span
                                                    className="fw-semibold d-block">{t("evaluationComponent:result")}:</span>
                                                <span>{calculateVo2Max(values.type, 0, parseFloat(values.time)).toFixed(2)} ml/kg/min</span>
                                            </div>
                                        </>
                                    }
                                    <button
                                        type="submit"
                                        className={"btn btn-primary w-100 mb-2"}
                                    >
                                        {t("evaluationComponent:save")}
                                    </button>
                                </Form>
                            )}
                        </Formik>
                        <button className={"btn btn-outline-primary w-100"}
                                onClick={handleCloseVo2Modal}
                        >
                            {t("evaluationComponent:close")}
                        </button>
                    </div>
                </div>
            </ModalBody>
        </Modal>
    );
};

export default Vo2Modal;
