import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {selectWorkoutRoutineLoading, selectWorkoutRoutines} from "../../store/workout-routine/workoutRoutineSelector";
import {useEffect, useState} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {fetchWorkoutRoutinesByStatus, setWorkouts} from "../../store/workout-routine/workoutRoutineReducer";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import _ from "lodash";
import WorkoutCard from "../../components/workout/WorkoutCard";
import {isWorkoutAerobicLoading, selectAerobics} from "../../store/workout-aerobic/workoutAerobicSelector";
import {fetchAerobicsByStatus, setAerobics} from "../../store/workout-aerobic/workoutAerobicReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutSecondaryList = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {clientId, status, type} = useParams()
    const isAerobic = Number(type) === 1;
    const loadingAerobic = useSelector(isWorkoutAerobicLoading);
    const loadingWorkout = useSelector(selectWorkoutRoutineLoading);
    const client = useSelector(selectSelectedClient)
    const aerobics = useSelector(selectAerobics)
    const routines = useSelector(selectWorkoutRoutines);
    const [workoutsLocal, setWorkoutsLocal] = useState(false);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate(`/user/client/${client.id}/workout/${Number(type)+1}`)
    }

    useEffect(() => {
        if (Number(clientId) > 0)
            dispatch(fetchClient(clientId));
    }, [dispatch, clientId]);

    useEffect(() => {
        if (isAerobic)
            dispatch(fetchAerobicsByStatus({id:clientId, status}))
        else
            dispatch(fetchWorkoutRoutinesByStatus({id:clientId, status}))
        return () => {
            dispatch(setWorkouts(null))
            dispatch(setAerobics(null))
        }
    }, [dispatch, clientId, status, isAerobic])

    useEffect(() => {
        if (routines) {
            setWorkoutsLocal(routines)
        }
    }, [routines])

    useEffect(() => {
        if (aerobics) {
            setWorkoutsLocal(aerobics)
        }
    }, [aerobics])

    return (
        <>
            <AvatarHeader className={"pb-4 pt-2"}
                          text={`${client?.nome} ${client?.sobrenome}`}
                          url={client?.profileUrl} showGoBack={handleGoBack}/>
            <Page contentHeader={false} loading={loadingAerobic || loadingWorkout}>
                <div className={"row justify-content-center mt-3"}>
                    <div className={'col-12'}>
                        <div className={'card card-body border-0'}>
                            <div className={"row"}>
                                <div className={"col-12"}>
                                    {
                                        Number(status) === 1 &&
                                        <>
                                        {
                                            isAerobic ?
                                                <span className={"fw-semibold"}>{t("workout:archivedPlans")}</span> :
                                                <span className={"fw-semibold"}>{t("workout:archivedWorkouts")}</span>
                                        }
                                        </>
                                    }
                                    {
                                        Number(status) === 2 &&
                                        <span className={"fw-semibold"}>{t("workout:deletedPlans")}</span>
                                    }
                                    {
                                        Number(status) === 3 &&
                                        <span className={"fw-semibold"}>{t("workout:deletedWorkouts")}</span>
                                    }
                                </div>
                            </div>
                            {
                                (!workoutsLocal || workoutsLocal.length === 0) &&
                                <div className={"row"}>
                                    <div className={"col-12 text-center mt-4"}>
                                        <RoundedIcon icon={"fa-folder"} size={"xl"}/>
                                    </div>
                                    <div className={"col-12 text-center mt-3 mb-2"}>
                                        {
                                            Number(status) === 1 &&
                                            <>
                                                {
                                                    isAerobic ?
                                                        <span className={"fw-semibold"}>{t("workout:noArchivedPlans")}</span> :
                                                        <span className={"fw-semibold"}>{t("workout:noArchivedWorkouts")}</span>
                                                }
                                            </>
                                        }
                                        {
                                            Number(status) === 2 &&
                                            <span className={"fw-semibold"}>{t("workout:noDeletedPlans")}</span>
                                        }
                                        {
                                            Number(status) === 3 &&
                                            <span className={"fw-semibold"}>{t("workout:noDeletedWorkouts")}</span>
                                        }
                                    </div>
                                </div>
                            }
                            {
                                _.map(workoutsLocal, (workout) =>
                                    <WorkoutCard type={Number(type)} workout={workout} key={workout.id}/>
                                )
                            }
                        </div>
                    </div>
                </div>
            </Page>

        </>
    )
}
export default WorkoutSecondaryList;