import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useParams} from "react-router-dom";
import {getLoading} from "../../store/bioimpedance-evaluation/bioimpedanceSelector";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import EmptySet from "../../components/empty-set/EmptySet";
import {getBioimpedanceList} from "../../store/bioimpedance-evaluation/bioimpedanceSelector";
import BioimpedanceCard from "../../components/bioimpedance-evaluation/BioimpedanceCard";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EvaluationCompareBarComponent from "../../components/evaluation-components/EvaluationCompareBarComponent";
import {useBioimpedanceActions} from "../../utils/bioimpedanceEvaluation/useBioimpedanceActions";
import BioimpedanceActionsButtons from "../../components/bioimpedance-evaluation/BioimpedanceActionsButtons";
import {resetFormSent} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";
import {fetchClient} from "../../store/client/clientReducer";
import {getAllBioimpedance} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";

const Bioimpedance = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const {id} = useParams();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const bioimpedanceList = useSelector(getBioimpedanceList);
    useComponentTranslations('bioimpedanceEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT})

    const {
        state: { isComparing, selectedList, showOptions, showShare, showDelete, currentBio, deleteSubmitting },
        handlers,
        shareLink
    } = useBioimpedanceActions();
    const MAX_SELECTION = 3;

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        if (!selectedClient?.id && id) {
            dispatch(fetchClient(id));
        }
        if (id) {
            dispatch(getAllBioimpedance({clientId: id, status: 0, type: 1}));
        }
    }, [dispatch, id, selectedClient?.id]);

    return (
        <>
            <AvatarHeader
                showGoBack={handlers.goBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"card card-body border-0"}>
                    <div className={"pt-2"}>
                        <div className={"btn btn-outline-primary w-100 py-4 clickable-element"}
                             onClick={handlers.createNew}>
                            <i className={"fa-regular fa-plus pe-1"}/>
                            <span>{t("bioimpedanceEvaluation:newEvaluation")}</span>
                        </div>
                    </div>
                    <div className={"row justify-content-center d-flex"}>
                        <div className={"row py-3"}>
                            <div className={"col-12 d-flex gap-2 ps-0 pe-0"}>
                                <button className={"btn btn-secondary-default w-100"} onClick={handlers.goCharts}>
                                    <span className={"text-primary"}>{t("bioimpedanceEvaluation:charts")}</span>
                                </button>
                                <button className={"btn btn-secondary-default w-100"} onClick={handlers.goDeleted}>
                                    <span className={"text-primary"}>{t("bioimpedanceEvaluation:deleted")}</span>
                                </button>
                            </div>
                        </div>
                    </div>
                    {(!bioimpedanceList || bioimpedanceList.length === 0) && (
                        <div className={"pt-3"}>
                            <EmptySet
                                icon={"fa-regular fa-folder-open"}
                                message={t("bioimpedanceEvaluation:emptySet")}
                            />
                        </div>
                    )}
                    {!loading && bioimpedanceList && bioimpedanceList.length > 0 && (
                        <div className={"row justify-content-center d-flex"}>
                            <div className={"col-12"}>
                                <div className={"px-2"}>
                                    {bioimpedanceList.map((bio =>
                                        <BioimpedanceCard
                                            key={bio.id}
                                            bioimpedance={bio}
                                            isComparing={isComparing}
                                            isSelected={selectedList.includes(bio.id)}
                                            onCompare={handlers.toggleComparingMode}
                                            onToggle={handlers.toggleSelection}
                                            onCardClick={handlers.openOptionsModal}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}
                    {isComparing && (
                        <EvaluationCompareBarComponent
                            selectedCount={selectedList.length}
                            maxSelection={MAX_SELECTION}
                            onCompare={handlers.goCompare}
                            onClose={handlers.toggleComparingMode}
                            compareLabel={t("bioimpedanceEvaluation:compare")}
                            selectLabel={t("bioimpedanceEvaluation:select")}
                        />
                    )}
                </div>
            </Page>
            <BioimpedanceActionsButtons
                state={{ currentBio, showOptions, showShare, showDelete, deleteSubmitting, selectedList, isComparing }}
                handlers={{
                    closeOptionsModal: handlers.closeOptionsModal,
                    closeShareModal: handlers.closeShareModal,
                    closeDeleteModal: handlers.closeDeleteModal,
                    confirmDelete: handlers.confirmDelete,
                    copyLink: handlers.copyLink,
                    sendWhatsApp: handlers.sendWhatsApp,
                    goView: handlers.goView,
                    goEdit: handlers.goEdit,
                    openShareModal: handlers.openShareModal,
                    openDeleteModal: handlers.openDeleteModal
                }}
                shareLink={shareLink}
            />
        </>
    )
}

export default Bioimpedance;
