import {createSlice} from "@reduxjs/toolkit";
import {
    createErrorSubmitResult,
    createPendingSubmitResult,
    createSubmitResult,
    createSuccessSubmitResult
} from "../../utils/evaluation/mutationState";

const initialState = {
    onlineList: [],
    evaluation: null,
    lastEvaluation: null,
    lastEvaluationClientId: null,
    initialLoading: false,
    submitLoading: false,
    submitResult: createSubmitResult(),
    scheduledEvaluations: null,
    frequencyStatus: null,
    frequencyUpdate: null,
    savedResponse: null,
    imageLoading: false,
    error: null,
    frequencyLoading: false,
    compareList: []
};

export const slice = createSlice({
    name: "evaluationOnline",
    initialState,
    reducers: {
        getAllOnline(state) {
            state.initialLoading = true;
        },
        setAllOnline(state, action) {
            state.initialLoading = false;
            state.onlineList = action.payload;
        },
        clearAllOnline(state) {
            state.onlineList = null;
            state.initialLoading = false;
        },
        fetchEvaluationOnline(state) {
            state.initialLoading = true;
        },
        setEvaluationOnline(state, action) {
            state.evaluation = action.payload;
            state.initialLoading = false;
        },
        fetchLastEvaluation(state, action) {
            state.lastEvaluation = null;
            state.lastEvaluationClientId = action.payload?.clientId ?? null;
        },
        setLastEvaluation(state, action) {
            state.lastEvaluation = action.payload?.evaluation ?? null;
            state.lastEvaluationClientId = action.payload?.clientId ?? null;
        },
        clearLastEvaluation(state) {
            state.lastEvaluation = null;
            state.lastEvaluationClientId = null;
        },
        sendOnline: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "send",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        resetFormSent(state) {
            state.submitLoading = false;
            state.submitResult = createSubmitResult();
            state.error = null;
        },
        saveOnline: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: action.payload?.id ? "update" : "create",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        getScheduled(state) {
            state.initialLoading = true;
        },
        setScheduled(state, action) {
            state.initialLoading = false;
            state.scheduledEvaluations = action.payload;
        },
        enableDisableStatus(state) {
            state.frequencyLoading = true;
        },
        setEnableDisableStatus(state, action) {
            state.frequencyLoading = false;
            state.frequencyStatus = action.payload;

            const {clientId, status} = action.payload;
            if (state.scheduledEvaluations?.clientId === clientId) {
                state.scheduledEvaluations.status = status;
            }
        },
        updateFrequencyOnline(state) {
            state.frequencyLoading = true;
        },
        clearEvaluation(state) {
            state.evaluation = null;
            state.initialLoading = false;
        },
        recoverEvaluation: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: action.payload?.status === 1 ? "delete" : "recover",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        setRecoveredEvaluation(state, action) {
            state.onlineList = state.onlineList.filter(item => item.id !== action.payload);
        },
        setSubmitResult(state, action) {
            state.submitLoading = false;
            state.submitResult = createSuccessSubmitResult(action.payload);
            state.error = null;
        },
        onError(state, action) {
            state.initialLoading = false;
            if (state.submitLoading) {
                state.submitResult = createErrorSubmitResult(state.submitResult, action.payload);
            }
            state.submitLoading = false;
            state.frequencyLoading = false;
            state.error = action.payload;
        },
        compareEvaluation(state) {
            state.initialLoading = true;
        },
        setCompareEvaluation(state, action) {
            state.initialLoading = false;
            state.compareList = action.payload;
        }
    }
});

export const {
    getAllOnline,
    setAllOnline,
    clearAllOnline,
    fetchEvaluationOnline,
    setEvaluationOnline,
    fetchLastEvaluation,
    setLastEvaluation,
    clearLastEvaluation,
    sendOnline,
    resetFormSent,
    saveOnline,
    recoverEvaluation,
    setRecoveredEvaluation,
    setSubmitResult,
    getScheduled,
    setScheduled,
    enableDisableStatus,
    setEnableDisableStatus,
    updateFrequencyOnline,
    clearEvaluation,
    compareEvaluation,
    setCompareEvaluation,
    onError
} = slice.actions;
export const evaluationOnlineReducer = slice.reducer;
