import {useNavigate, useParams} from "react-router-dom";
import {useState} from "react";
import {useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";
import SignupLinkLink from "../../components/signup-link/SignupLinkLink";
import SignupLinkContacts from "../../components/signup-link/SignupLinkContacts";
import Page from "../../components/page/Page";
import Tabs from "../../components/tab/Tabs";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SignupLink = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const user = useSelector(selectUser);
    const {type} = useParams();
    const [page, setPage] = useState(type ?? "1");
    useComponentTranslations('signupLink', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const changePages = (pageName) => {
        setPage(pageName);
    };

    const handleGoBackLink = () => {
        navigate("/user");
    };

    return (
        <Page title={t("signupLink:signupLinkTitle")} mt={"mt-n5"} goBackLink={handleGoBackLink} contentHeader={true}>
            <Tabs page={page} button1Text={t("signupLink:button1Text")} mt={"mt-n0-1"} button2Text={t("signupLink:button2Text")} buttonClick={changePages}/>
            {
                page === "1" ?
                    <SignupLinkLink user={user}/> :
                    <SignupLinkContacts/>
            }
        </Page>
    );
};
export default SignupLink;
