import React, {useState} from "react";
import Modal from "react-bootstrap/Modal";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import {createGroup, deleteGroup} from "../../store/exercise-library/exerciseLibraryReducer";
import {useDispatch, useSelector} from "react-redux";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import * as Yup from "yup";
import {ErrorMessage, Field, Form, Formik} from "formik";
import {selectExerciseGroups} from "../../store/exercise-library/exerciseLibrarySelector";

const ExerciseGroupListItem = ({group}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const [showDelete, setShowDelete] = useState(false);
    const [showEditGroup, setShowEditGroup] = useState(false);
    const groups = useSelector(selectExerciseGroups);

    useComponentTranslations('exerciseLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const initialValues = { id: group.id, name: group.nome };

    const validationSchema = Yup.object({
        name: Yup.string()
            .required(t("exerciseLibraryComponent:groupNameRequired"))
            .test("unique", t("exerciseLibraryComponent:groupExists"), function (value) {
                if (!value) return true;
                return !groups.some(
                    (g) =>
                        g.id !== group.id &&
                        g.name &&
                        g.name.toLowerCase() === value.toLowerCase()
                );
            }),
        id: Yup.mixed().required(),
    });

    const handleEditGroup = () => {
        if (group.idUser > 0)
            setShowEditGroup(prevState => !prevState);
    };

    const handleShowModal = () => {
        setShowDelete(prevState => !prevState);
    };

    const handleDeleteGroup = () => {
        dispatch(deleteGroup(group.id));
    };
    const onSubmit = (values) => {
        dispatch(createGroup(values));
    };


    return (
        <>
            <li className={`fw-semibold border-bottom ps-2 pt-3 pb-3 border-primary-subtle"`}>
                <div className="row justify-content-between">
                    <div className={`col-auto align-self-center ${group.idUser > 0 && "clickable-element"}`} onClick={handleEditGroup}>
                        {
                            group.idUser > 0 ? group.nome :
                                t(`exerciseLibraryComponent:${group.alias}`)
                        }
                    </div>
                    {group.idUser > 0 && (
                        <div className="col-auto align-self-center clickable-element" onClick={handleShowModal}>
                            <i className="fa-regular fa-trash-can text-danger"></i>
                        </div>
                    )}
                </div>
            </li>
            <Modal show={showEditGroup} centered onHide={handleEditGroup}>
                <Modal.Body>
                    <div className="row justify-content-between">

                        <div className="col-auto">
                            <span className="fw-semibold">{t(`exerciseLibraryComponent:changeGroupName`)}</span>
                        </div>
                        <div className="col-auto clickable-element" onClick={handleEditGroup}>
                            <span><i className="fa-regular fa-times"></i></span>
                        </div>
                        <div className={"col-12 mt-3"}>
                            <Formik
                                initialValues={initialValues}
                                validationSchema={validationSchema}
                                onSubmit={onSubmit}
                            >
                                {(formik) => (
                                    <Form>

                                        <Field type="hidden" id="id" name="id" />
                                        <div className="mb-3">
                                            <label htmlFor="name" className="form-label fw-semibold">
                                                {t("exerciseLibrary:groupName")}
                                            </label>
                                            <Field
                                                type="text"
                                                id="name"
                                                name="name"
                                                className={`form-control ${
                                                    formik.errors.name && formik.touched.name ? "is-invalid" : ""
                                                }`}
                                            />
                                            <ErrorMessage name="name">
                                                {(msg) => <div className="invalid-feedback">{msg}</div>}
                                            </ErrorMessage>
                                        </div>
                                        <div className="d-grid">
                                            <button type="submit" className="btn btn-primary">
                                                {t("exerciseLibrary:save")}
                                            </button>
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>

            <Modal show={showDelete} centered onHide={handleShowModal}>
                <Modal.Body>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation"}
                        iconColor={"text-danger"}
                        title={t("exerciseLibraryComponent:confirmDeleteGroup")}
                        subtitle={t("exerciseLibraryComponent:irreversibleAction")}
                    />
                    <div className="row mt-3 justify-content-center">
                        <div className="col-12">
                            <div className="d-grid">
                                <button className="btn btn-danger" onClick={handleDeleteGroup}>
                                    {t("exerciseLibraryComponent:delete")}
                                </button>
                            </div>
                            <div className="d-grid mt-2">
                                <button className="btn btn-outline-danger" onClick={handleShowModal}>
                                    {t("exerciseLibraryComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    );
};

export default ExerciseGroupListItem;
