import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useCallback, useEffect, useMemo} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {useNavigate, useParams} from "react-router-dom";
import Page from "../../components/page/Page";
import {fetchOneBioimpedance, resetFormSent} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";
import {getLoading, getOneBioimpedance} from "../../store/bioimpedance-evaluation/bioimpedanceSelector";
import moment from "moment/moment";
import ImageCarousel from "../../utils/imagecarousel/ImageCarousel";
import {isDesktop} from "react-device-detect";
import {getBioimpedanceFields} from "../../utils/bioimpedanceEvaluation/bioimpedanceFieldsView";
import EvaluationChartsComponent from "../../components/evaluation-components/EvaluationChartsComponent";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {formatRQC} from "../../utils/physicalEvaluation/rqcFormula";
import BioimpedanceActionsButtons from "../../components/bioimpedance-evaluation/BioimpedanceActionsButtons";
import {useBioimpedanceActions} from "../../utils/bioimpedanceEvaluation/useBioimpedanceActions";
import {buildClientBioimpedanceRoute} from "../../utils/client/evaluationRoutes";

const BioimpedanceView = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, bioimpedanceId} = useParams();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const bioimpedanceDetails = useSelector(getOneBioimpedance);
    useComponentTranslations('bioimpedanceEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT})
    const {t} = useTranslation("bioimpedanceEvaluation");

    const {state: {showDelete, currentBio}, handlers,} = useBioimpedanceActions();
    const {setCurrentBio} = handlers;

    const percentualGordura = parseFloat((Number(bioimpedanceDetails?.per_gord) || 0).toFixed(2));
    const percentualMassaMagra = (100 - percentualGordura).toFixed(2);
    const massaGordaKg = bioimpedanceDetails?.pes_gord || 0;
    const massaMagraKg = bioimpedanceDetails?.magra || 0;

    const rcqFormatted = bioimpedanceDetails?.rcq != null && Number(bioimpedanceDetails.rcq) !== 0
        ? formatRQC(bioimpedanceDetails?.rcq, selectedClient?.sexo, t)
        : "";

    const currentFields = useMemo(() => {
        const raw = getBioimpedanceFields(bioimpedanceDetails?.protocolo);
        return raw.map(f => ({
            ...f,
            labelKey: f.labelKey ?? f.id,
            unit: f.unit ?? "",
        }));
    }, [bioimpedanceDetails]);

    const fieldsBySection = useMemo(() => {
        return currentFields.reduce((acc, field) => {
            const val = bioimpedanceDetails[field.id];
            if (val == null || (typeof val === "string" && !val.trim()) || (typeof val === "number" && val === 0)) {
                return acc;
            }
            (acc[field.section] ||= []).push(field);
            return acc;
        }, {});
    }, [currentFields, bioimpedanceDetails]);

    const handleGoBackPage = useCallback(() => {
        navigate(buildClientBioimpedanceRoute(id));
    }, [navigate, id]);

    useEffect(() => {
        dispatch(fetchClient(id));
        dispatch(fetchOneBioimpedance({id: bioimpedanceId}));
    }, [dispatch, id, bioimpedanceId]);

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        if (bioimpedanceDetails) {
            setCurrentBio(bioimpedanceDetails);
        }
    }, [bioimpedanceDetails, setCurrentBio]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            {!!bioimpedanceDetails && !loading && currentFields.length > 0 && (
                                <div className={"border-0 p-0"}>
                                    <span className={"fw-semibold mb-2 d-block fs-5"}>{t("bioimpedanceEvaluation:bioimpedanceTitle")}</span>
                                    {Object.entries(fieldsBySection)
                                        .map(([section, fields]) => (
                                            <div key={section} className="mb-4">
                                                {section !== "Pessoal" && (
                                                    <span className={"fw-semibold fs-5 pb-2"}> {t(`sections.${section}`)}</span>
                                                )}
                                                {fields.map(field => {
                                                    const raw = bioimpedanceDetails[field.id];
                                                    const display = field.id === "data" || field.id === "proximaAvaliacao"
                                                        ? moment(raw).format("L")
                                                        : raw;
                                                    return (
                                                        <div key={field.id} className="row">
                                                            <label htmlFor={field.id} className="fw-semibold">
                                                                {t(`fields.${field.labelKey}`)}
                                                            </label>
                                                            {["data", "proximaAvaliacao"].includes(field.id) ? (
                                                                <span>
                                                                    {moment(bioimpedanceDetails[field.id]).format("L")}
                                                                </span>
                                                            ) : field.id === "observacao" ? (
                                                                <div
                                                                    style={{whiteSpace: "pre-line"}}>
                                                                    {bioimpedanceDetails[field.id]}
                                                                </div>
                                                            ) : typeof field.formatter === "function" ? (
                                                                    <span>
                                                                        {field.formatter(bioimpedanceDetails[field.id])}
                                                                    </span>
                                                                ) :
                                                                field.id === "rcq" ? (
                                                                    <span>
                                                                        {t(`bioimpedanceEvaluation:${rcqFormatted}`)}
                                                                    </span>
                                                                ) : field.id === "objetivo" ? (
                                                                    <div style={{whiteSpace: "pre-line"}}>
                                                                        {bioimpedanceDetails[field.id]}
                                                                    </div>
                                                                ) : (
                                                                    <span style={{width: "auto"}}>
                                                                        {`${display}${field.unit || ""}`}
                                                                    </span>
                                                                )}
                                                        </div>
                                                    )
                                                })}
                                            </div>
                                        ))}
                                </div>
                            )}
                        </div>
                        <div className={"card card-body border-0 mt-4 no-page-break"}>
                            <EvaluationChartsComponent
                                chartTitle={t("bioimpedanceEvaluation:charts")}
                                percentualTitle={t("bioimpedanceEvaluation:fatPercentage")}
                                leanMassPercentageTitle={t("bioimpedanceEvaluation:leanMass")}
                                leanMassPercentageValue={percentualMassaMagra}
                                fatMassPercentageTitle={t("bioimpedanceEvaluation:fat")}
                                fatMassPercentageValue={percentualGordura}
                                doughnutValues={[percentualMassaMagra, percentualGordura]}
                                doughnutLabels={[t("bioimpedanceEvaluation:leanMass"), t("bioimpedanceEvaluation:fat")]}
                                leanFatMassTitle={t("bioimpedanceEvaluation:leanFatMass")}
                                leanMassTitle={t("bioimpedanceEvaluation:leanMass")}
                                leanMassValue={massaMagraKg}
                                fatMassTitle={t("bioimpedanceEvaluation:fatMass")}
                                fatMassValue={massaGordaKg}
                                barValues={[massaMagraKg, massaGordaKg]}
                                barLabels={['', '']}
                            />
                        </div>
                        {bioimpedanceDetails?.images?.length > 0 && (
                            <div className={"card card-body border-0 mt-4 d-print-none"}>
                                <h5 className={"fw-semibold text-center py-2"}>{t("bioimpedanceEvaluation:images")}</h5>
                                <ImageCarousel images={bioimpedanceDetails.images}/>
                            </div>
                        )}
                        <div className={"card card-body border-0 pt-2 mt-2 d-print-none"} >
                            <div className={isDesktop ? "row my-2" : ""}>
                                {isDesktop && (
                                    <div className={"col-12"}>
                                        <button
                                            type={"button"}
                                            className={"btn btn-primary w-100 no-print"}
                                            onClick={() => {
                                                setTimeout(() => window.print(), 500)
                                            }}>
                                            {t("bioimpedanceEvaluation:print")}
                                        </button>
                                    </div>
                                )}
                            </div>
                            <button
                                className={"btn btn-outline-primary w-100"}
                                onClick={handleGoBackPage}>{t("bioimpedanceEvaluation:return")}</button>
                            <button className={"btn btn-outline-primary w-100 mt-2"}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handlers.goEdit();
                                    }}>
                                {t("bioimpedanceEvaluation:edit")}
                            </button>
                            <button className={"btn btn-outline-danger w-100 mt-2"}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handlers.openDeleteModal();
                                    }}>
                                {t("bioimpedanceEvaluation:delete")}
                            </button>
                        </div>
                    </div>
                </div>
            </Page>
            <BioimpedanceActionsButtons
                state={{showDelete, currentBio}}
                handlers={{
                    openDeleteModal: handlers.openDeleteModal,
                    closeDeleteModal: handlers.closeDeleteModal,
                    confirmDelete: handlers.confirmDelete,
                    goEdit: handlers.goEdit,
                }}
            />
        </>
    )
}

export default BioimpedanceView;
