import {ErrorMessage, Field, Form, Formik} from "formik";
import LoadingBlock from "../loader/LoadingBlock";
import * as Yup from "yup";
import {createFolder, fetchFoldersList, folderCreated} from "../../store/workout-library/workoutLibraryReducer";
import {useDispatch, useSelector} from "react-redux";
import {useEffect} from "react";
import {selectFolderCreated, selectLoadingCreatingFolder} from "../../store/workout-library/workoutLibrarySelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const WorkoutFolderCreateForm = ({type, setShowCreateFolder, closeModal}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const isLoadingFolderCreation = useSelector(selectLoadingCreatingFolder)
    const isFolderCreated = useSelector(selectFolderCreated)
    useComponentTranslations('trainingLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object().shape({
        name: Yup.string().required(t("trainingLibraryComponent:folderNameIsRequired"))
            .max(45, t("trainingLibraryComponent:nameTooBig")),
    });

    const handleFormSubmit = (values) => {
        const payload = {
            type,
            ...values
        }
        dispatch(createFolder(payload))
    }
    useEffect(() => {
        if (isFolderCreated) {
            dispatch(folderCreated({folder: null, payload: false}));
            dispatch(fetchFoldersList(type));
            if (closeModal) {
                closeModal();
            }
            setShowCreateFolder(false)
        }
    }, [isFolderCreated, dispatch, closeModal, setShowCreateFolder, type]);

    return (
        <>
            <div className={'row justify-content-between'}>
                <div className={'col-auto'}>
                    <span className={"fw-semibold fs-5"}>{t("trainingLibraryComponent:addFolderTitle")}</span>
                </div>
                <div className={'col-auto clickable-element'} onClick={() => setShowCreateFolder(false)}>
                    <i className={'fa-regular fa-times fs-5'}></i>
                </div>
            </div>
            {!isLoadingFolderCreation && (
                <div className={"row mt-3"}>
                    <div className={'col-12'}>
                        <Formik
                            initialValues={{ name: '' }}
                            validationSchema={validationSchema}
                            onSubmit={handleFormSubmit}
                        >
                            {({errors, touched}) => (
                                <Form>
                                    <div className="mb-3">
                                        <label htmlFor="name" className="fw-semibold">
                                            {t("trainingLibraryComponent:folderNameLabel")}
                                        </label>
                                        <Field
                                            id="name"
                                            name="name"
                                            type="text"
                                            className={`form-control ${touched.name && errors.name ? 'is-invalid' : ''}`}
                                        />
                                        <ErrorMessage
                                            name="name"
                                            component="div"
                                            className="invalid-feedback d-block"
                                        />
                                    </div>
                                    <div className={'d-grid'}>
                                        <button type="submit" className="btn btn-primary">
                                            {t("trainingLibraryComponent:createFolder")}
                                        </button>
                                    </div>
                                </Form>
                            )}
                        </Formik>
                        <div className={'d-grid mt-2'}>
                            <button className={'btn btn-outline-primary clickable-element'} onClick={() => setShowCreateFolder(false)}>
                                {t("trainingLibraryComponent:back")}
                            </button>
                        </div>
                    </div>
                </div>
            )}
            {isLoadingFolderCreation && (
                <LoadingBlock height={"300px"}/>
            )}
        </>

    )
}

export default WorkoutFolderCreateForm;
