import {getExerciseName} from "../../utils/workout/Workout";
import {useTranslation} from "react-i18next";
import _ from "lodash";
import WorkoutSeries from "./WorkoutSeries";
import {useState} from "react";
import ExercisePlayerType from "../utils/videoplayer/ExercisePlayerType";

const WorkoutExerciseMultipleSingular = ({exerc, index, showSeries = true}) => {
    const {i18n} = useTranslation();
    const [exercise] = useState(exerc.exercises ? exerc.exercises[0] : exerc.exercicio ? exerc.exercicio : exerc);
    return (
        <div className="row justify-content-center d-flex">
            <div className="col-12 ">
                <div className={'row justify-content-between d-flex'}>
                    <div className={`col-10  align-self-center`}>
                        <span className={'d-block fw-bold  text-md'} style={{lineHeight: "1.1rem"}}>
                             {getExerciseName(exercise, i18n)}
                        </span>
                    </div>
                    <div className={`col-2  align-self-center ps-0   `} >
                        <span
                            style={{ width: "30px", height: "30px", display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                            className={'text-center   fs-5  fw-bold text-white rounded-circle bg-primary-darker '}>
                            <span>{String.fromCharCode(65 + index)}</span>
                        </span>
                    </div>
                </div>
                <div className={'row d-flex pb-3 text-md pt-3'}>
                    {showSeries && exercise.series && exercise.series.length > 0 && (
                        <div className={`col-8   `}>
                            {_.map(exercise.series, (serie) => (
                                <WorkoutSeries key={serie.id}
                                               serie={serie}
                                               seriesLength={exercise.series.length}
                                               isMultiple={true}
                                />
                            ))}
                        </div>
                    )}
                    <ExercisePlayerType showSeries={showSeries} exercise={exercise}/>
                </div>
            </div>
        </div>
    )
}
export default WorkoutExerciseMultipleSingular;