import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect, useMemo} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {getLoading} from "../../store/physical-evaluation/physicalEvaluationSelector";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {getBioimpedanceList} from "../../store/bioimpedance-evaluation/bioimpedanceSelector";
import {fetchClient} from "../../store/client/clientReducer";
import {getAllBioimpedance} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";
import Page from "../../components/page/Page";
import LoadingBlock from "../../components/loader/LoadingBlock";
import EmptySet from "../../components/empty-set/EmptySet";
import {chartFields} from "../../utils/evaluationComponents/chartFields";
import LineChart from "../../components/charts/LineChart";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {buildClientBioimpedanceRoute} from "../../utils/client/evaluationRoutes";
import {formatDate as formatDateValue} from "../../utils/translation/localeUtils";

const BioimpedanceCharts = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id} = useParams();
    const {t, i18n} = useTranslation();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const bioimpedanceList = useSelector(getBioimpedanceList);
    useComponentTranslations('bioimpedanceEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const sortedBioList = useMemo(() => {
        if (!bioimpedanceList || bioimpedanceList.length === 0) return [];
        return [...bioimpedanceList].sort((a, b) => new Date(a.data) - new Date(b.data));
    }, [bioimpedanceList]);

    const hasNoData = useMemo(() => {
        if (sortedBioList.length < 2) return true;
        return sortedBioList.every(bioimpedance => {
            if (!bioimpedance.data) return true;
            return chartFields.every(field => {
                const value = bioimpedance[field.id];
                return value === undefined || value === null || value === 0 || value === "";
            });
        });
    }, [sortedBioList]);

    const compositionFields = useMemo(() => {
        if (sortedBioList.length < 2) return [];
        return chartFields
            .filter(field => field.category === "composicao")
            .map(field => ({
                ...field,
                label: t(`bioimpedanceEvaluation:table.${field.labelKey}`)
            }));
    }, [sortedBioList, t]);

    const perimetryFields = useMemo(() => {
        if (sortedBioList.length < 2) return [];
        return chartFields
            .filter(field => field.category === "perimetria")
            .map(field => ({
                ...field,
                label: t(`bioimpedanceEvaluation:table.${field.labelKey}`)
            }));
    }, [sortedBioList, t]);

    const transformedData = useMemo(() => {
        if (sortedBioList.length === 0) return {};
        const data = {};
        chartFields.forEach(field => {
            data[field.id] = [];
        });
        sortedBioList.forEach(bioimpedance => {
            chartFields.forEach(field => {
                if (field.id === "percentage") {
                    data[field.id].push(bioimpedance.percentage ?? 0);
                } else {
                    data[field.id].push(bioimpedance[field.id] ?? 0);
                }
            });
        });
        return data;
    }, [sortedBioList]);

    const chartLabels = useMemo(() => {
        if (sortedBioList.length === 0) return [];
        return sortedBioList.map(bioimpedance => {
            const date = bioimpedance.data;
            return date
                ? formatDateValue(date, i18n.language, {day: "2-digit", month: "2-digit"})
                : '';
        });
    }, [i18n.language, sortedBioList]);

    const handleGoBackPage = () => {
        navigate(buildClientBioimpedanceRoute(id));
    };

    useEffect(() => {
        dispatch(fetchClient(id));
        dispatch(getAllBioimpedance({clientId:id, status: 0, type: 1}));
    }, [dispatch, id]);

    return (
        <>
            <AvatarHeader
                md={"12"} lg={"12"} xl={"8"}
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"} lg={"12"} md={"12"} xl={"8"}>
                <div className={"row"}>
                    <div className={"col-12"}>
                        {loading || loadingClient ? (
                            <div className={"text-center mt-4"}>
                                <LoadingBlock/>
                            </div>
                        ) : hasNoData ? (
                            <div className={"card card-body border-0"}>
                                <EmptySet
                                    icon={"fa-regular fa-folder-open"}
                                    message={t("bioimpedanceEvaluation:noCharts")}
                                />
                            </div>
                        ) : (
                            <>
                                <div className={"row"}>
                                    {compositionFields.map(field => (
                                        <div key={field.id} className={"col-md-6 mb-4"}>
                                            <div className={"card card-body"}>
                                                <span className={"card-title"}>{field.label}</span>
                                                <LineChart
                                                    key={field.id}
                                                    dataValues={transformedData[field.id] || []}
                                                    unit={field.unit}
                                                    chartLabels={chartLabels}
                                                />
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <span className={"mb-3 fs-5 fw-semibold"}>{t("bioimpedanceEvaluation:perimetry")}</span>
                                <div className={"row"}>
                                    {perimetryFields.map(field => (
                                        <div key={field.id} className={"col-md-6 mb-4 mt-2"}>
                                            <div className={"card card-body"}>
                                                <span className="card-title">{field.label}</span>
                                                <LineChart
                                                    key={field.id}
                                                    dataValues={transformedData[field.id] || []}
                                                    unit={field.unit}
                                                    chartLabels={chartLabels}
                                                />
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </>
                        )}
                    </div>
                </div>
            </Page>
        </>
    )
}

export default BioimpedanceCharts;
