function _formatIMC(imc, t) {
    let n;
    if (typeof imc === "string") {
        const match = imc.match(/[\d]+[.,]?\d*/);
        n = match ? parseFloat(match[0].replace(",", ".")) : NaN;
    } else {
        n = Number(imc);
    }
    if (isNaN(n)) return "";

    let key;
    if (n === 0.00)        key = "-";
    else if (n < 18.5)     key = "bellow_weight";
    else if (n <= 24.9)    key = "normal_weight";
    else if (n <= 29.9)    key = "above_weight";
    else if (n <= 34.9)    key = "obesity_1";
    else if (n <= 39.9)    key = "obesity_2";
    else                   key = "morbid_obesity";

    const formatted = n.toFixed(2).replace(".", ",");

    const nested = t(`imc.${key}`);
    if (nested && nested !== `imc.${key}`) {
        return `${formatted} ${nested}`;
    }
    const root = t(key);
    return `${formatted} ${root}`;
}

export const formatIMC       = (imc, t) => _formatIMC(imc, t);

export function calculateIMC(pesoKg, estaturaCm) {
    if (!pesoKg || !estaturaCm) return null;
    const alturaM = estaturaCm / 100;
    const imc = pesoKg / (alturaM * alturaM);
    return Number.isFinite(imc) ? imc : null;
}