import {apiUrl as url, getToken} from "../api";
import axios from "axios";

const apiUrl = url + "/v2"
export const getOnePhysicalAPI = async (id) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/physical-evaluation/?id=${id}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'Authorization': token
            },
            timeout: 20000
        }
    )
}

