import {useEffect, useRef, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useTranslation} from "react-i18next";
import {Offcanvas} from "react-bootstrap";
import {useNavigate} from "react-router-dom";
import Page from "../../components/page/Page";
import Avatar from "../../components/avatar/Avatar";
import {
    selectUser,
    selectUserLanguageUpdateErrorCode,
    selectUserLanguageUpdateLoading,
    selectUserLanguageUpdateSuccess,
    selectUserProfilePictureUpdateLoading
} from "../../store/user/userSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import UserProfileImageCropper from "../../components/user-profile/UserProfileImageCropper";
import UserProfileLanguageOffcanvas from "../../components/user-profile/UserProfileLanguageOffcanvas";
import {
    clearUserLanguageUpdateState,
    clearUserProfilePictureUpdateState,
    updateUserLanguage
} from "../../store/user/userReducer";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const ProfileOptionCard = ({title, subtitle, disabled = true, onClick}) => {
    const handleKeyDown = (event) => {
        if (disabled) {
            return;
        }

        if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            onClick?.();
        }
    };

    return (
        <div
            className={`card card-body border-secondary-subtle ${disabled ? "" : "clickable-element"}`}
            aria-disabled={disabled}
            role={disabled ? undefined : "button"}
            tabIndex={disabled ? -1 : 0}
            onClick={disabled ? undefined : onClick}
            onKeyDown={handleKeyDown}
        >
            <div className={"row align-items-center"}>
                <div className={"col-10"}>
                    <span className={"d-block fw-semibold "}>{title}</span>
                    <span className={"d-block text-default mt-1"}>{subtitle}</span>
                </div>
                <div className={"col-2 text-end"}>
                    <i className={"fa-regular fa-chevron-right"}/>
                </div>
            </div>
        </div>
    )
}

const UserProfile = () => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const user = useSelector(selectUser);
    const userLanguageUpdateLoading = useSelector(selectUserLanguageUpdateLoading);
    const userLanguageUpdateSuccess = useSelector(selectUserLanguageUpdateSuccess);
    const userLanguageUpdateErrorCode = useSelector(selectUserLanguageUpdateErrorCode);
    const userProfilePictureUpdateLoading = useSelector(selectUserProfilePictureUpdateLoading);
    const fileInputRef = useRef(null);
    const [showProfilePicture, setShowProfilePicture] = useState(false);
    const [image, setImage] = useState(null);
    const [showLanguageOffcanvas, setShowLanguageOffcanvas] = useState(false);
    const [pendingLanguage, setPendingLanguage] = useState(null);
    const [isProfilePictureProcessing, setIsProfilePictureProcessing] = useState(false);

    useComponentTranslations("userProfilePage", {
        "en-US": enUS.userProfilePage,
        "pt-BR": ptBR.userProfilePage,
        "es-ES": esES.userProfilePage,
        "pt-PT": ptPT.userProfilePage
    });

    const language = user?.language?.toLowerCase();

    const languageMap = {
        "pt-br": t("userProfilePage:languagePortuguese"),
        "pt-pt": t("userProfilePage:languagePortuguese"),
        "en-us": t("userProfilePage:languageEnglish"),
        "es-es": t("userProfilePage:languageSpanish")
    };

    const languageLabel = languageMap[language] || user?.language || "";

    const profileOptions = [
        {
            key: "personalData",
            title: t("userProfilePage:personalData"),
            subtitle: t("userProfilePage:personalDataSubtitle"),
            disabled: false,
            onClick: () => navigate("/user/profile/personal-information")
        },
        {
            key: "updatePassword",
            title: t("userProfilePage:updatePassword"),
            subtitle: t("userProfilePage:passwordPreview"),
            disabled: false,
            onClick: () => navigate("/user/profile/password")
        },
        {
            key: "language",
            title: t("userProfilePage:language"),
            subtitle: languageLabel,
            disabled: false,
            onClick: () => setShowLanguageOffcanvas(true)
        }
    ];

    const handleCloseProfilePictureUpdate = ({forceClose = false} = {}) => {
        if (!forceClose && (isProfilePictureProcessing || userProfilePictureUpdateLoading)) {
            return;
        }

        dispatch(clearUserProfilePictureUpdateState());
        setImage(null);
        setShowProfilePicture(false);
    };

    const handleCloseLanguageOffcanvas = () => {
        if (userLanguageUpdateLoading) {
            return;
        }

        setShowLanguageOffcanvas(false);
        setPendingLanguage(null);
        dispatch(clearUserLanguageUpdateState());
    };

    const handleLanguageSelectionStarted = (languageCode) => {
        setShowLanguageOffcanvas(true);
        setPendingLanguage(languageCode);
        dispatch(updateUserLanguage({language: languageCode}));
    };

    useEffect(() => {
        dispatch(clearUserLanguageUpdateState());
        dispatch(clearUserProfilePictureUpdateState());

        return () => {
            dispatch(clearUserLanguageUpdateState());
            dispatch(clearUserProfilePictureUpdateState());
        };
    }, [dispatch]);

    useEffect(() => {
        if (!pendingLanguage || !userLanguageUpdateSuccess) {
            return;
        }

        if (user?.language !== pendingLanguage) {
            return;
        }

        i18n.changeLanguage(pendingLanguage).finally(() => {
            setShowLanguageOffcanvas(false);
            setPendingLanguage(null);
            dispatch(clearUserLanguageUpdateState());
        });
    }, [dispatch, i18n, pendingLanguage, user?.language, userLanguageUpdateSuccess]);

    useEffect(() => {
        if (!pendingLanguage || !userLanguageUpdateErrorCode) {
            return;
        }

        setPendingLanguage(null);
        dispatch(clearUserLanguageUpdateState());
    }, [dispatch, pendingLanguage, userLanguageUpdateErrorCode]);

    const onFileButtonClick = () => {
        if (isProfilePictureProcessing || userProfilePictureUpdateLoading) {
            return;
        }

        if (!fileInputRef.current) {
            return;
        }

        fileInputRef.current.value = null;
        fileInputRef.current.click();
    };

    const readFile = (file) => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.addEventListener("load", () => resolve(reader.result), false);
            reader.readAsDataURL(file);
        });
    };

    const onFileChange = async (event) => {
        const file = event.target.files?.[0];
        if (!file) {
            return;
        }

        const imageDataUrl = await readFile(file);
        setImage(imageDataUrl);
        setShowProfilePicture(true);
    };

    return (
        <>
            <Page title={t("userProfilePage:title")} goBackLink={"/user"} mt={"mt-n3"}>
                <div className={"card card-body border-0 pt-5 position-relative"}>
                    <button
                        type={"button"}
                        className={"no-style-btn position-absolute start-50 translate-middle-x clickable-element"}
                        style={{top: "-42px"}}
                        onClick={onFileButtonClick}
                        disabled={isProfilePictureProcessing || userProfilePictureUpdateLoading}
                        aria-label={t("userProfilePage:editPhoto")}
                    >
                        <div className={"position-relative"} style={{width: "118px", height: "118px"}}>
                            <Avatar maxWidth={"118px"} url={user?.urlLogo} blueBorder={true}/>
                            <span
                                className={"position-absolute rounded-circle bg-dark"}
                                style={{inset: "4px", opacity: 0.35}}
                            />
                            <i className={"fa-regular fa-plus text-white fa-2x position-absolute top-50 start-50 translate-middle"}/>
                        </div>
                    </button>

                    <div className={"row justify-content-center"}>
                        <div className={"col-auto text-center pt-4"}>
                            <button
                                type={"button"}
                                className={"no-style-btn d-block pt-2 clickable-element"}
                                onClick={onFileButtonClick}
                                disabled={isProfilePictureProcessing || userProfilePictureUpdateLoading}
                            >
                                {t("userProfilePage:editPhoto")}
                            </button>
                            <input
                                type="file"
                                ref={fileInputRef}
                                className={"d-none"}
                                onChange={onFileChange}
                                accept="image/*"
                            />
                        </div>
                    </div>

                    <div className={"row mt-3"}>
                        <div className={"col-12 d-grid gap-2"}>
                            {
                                profileOptions.map((option) => (
                                    <ProfileOptionCard
                                        key={option.key}
                                        title={option.title}
                                        subtitle={option.subtitle}
                                        disabled={option.disabled}
                                        onClick={option.onClick}
                                    />
                                ))
                            }
                        </div>
                    </div>
                </div>
            </Page>
            <Offcanvas show={showProfilePicture} onHide={handleCloseProfilePictureUpdate} placement={"end"} className={"w-100"} style={{maxWidth: "100%"}}>
                <Offcanvas.Body className={"bg-body d-flex flex-column p-0"}>
                    <div className={"px-4 pt-4 pb-4"}>
                        <div className={"row align-items-center"}>
                            <div className={"col-4"}>
                                <button type={"button"} className={"no-style-btn clickable-element"} onClick={handleCloseProfilePictureUpdate}>
                                    <i className={"fa-regular fa-chevron-left"}></i> {t("userProfilePage:goBack")}
                                </button>
                            </div>
                            <div className={"col-4 text-center"}>
                                <span className={"text-title fw-semibold"}>{t("userProfilePage:pictureAdjust")}</span>
                            </div>
                            <div className={"col-4"}></div>
                        </div>
                    </div>
                    {
                        image &&
                        <UserProfileImageCropper
                            handleClose={() => handleCloseProfilePictureUpdate({forceClose: true})}
                            image={image}
                            setImage={setImage}
                            saveText={t("userProfilePage:save")}
                            cancelText={t("userProfilePage:cancel")}
                            setProcessingState={setIsProfilePictureProcessing}
                        />
                    }
                </Offcanvas.Body>
            </Offcanvas>
            <UserProfileLanguageOffcanvas
                show={showLanguageOffcanvas}
                handleClose={handleCloseLanguageOffcanvas}
                currentLanguage={user?.language}
                onLanguageSelectionStarted={handleLanguageSelectionStarted}
            />
        </>
    )
}

export default UserProfile;
