import React, {useState} from "react";
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import {useDispatch, useSelector} from "react-redux";
import {getFrequencyLoading, getLoading} from "../../store/online-evaluation/evaluationOnlineSelector";
import {enableDisableStatus, updateFrequencyOnline} from "../../store/online-evaluation/evaluationOnlineReducer";
import {addToast} from "../../store/toast/toastReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {Field, Formik} from "formik";
import moment from "moment";
import he from 'he'
const OnlineEvaluationScheduledCard = ({scheduledEvaluation, client}) => {
    const dispatch = useDispatch();
    const loading = useSelector(getLoading);
    const frequencyLoading = useSelector(getFrequencyLoading);
    const {frequency, nextEvaluation, status} = scheduledEvaluation;
    const formattedNextEvaluation = moment(nextEvaluation).format("L");
    const {t} = useTranslation();
    useComponentTranslations('evaluationOnlineComponents', {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT
    });

    const [showEditSchedule, setShowEditSchedule] = useState(false);

    const handleShowEdit = () => {
        setShowEditSchedule(prevState => !prevState);
    };

    const handleUpdate = (values) => {
        dispatch(
            updateFrequencyOnline({
                clientId: client.id,
                frequency: Number(values.newFrequency),
            })
        );
        setShowEditSchedule(false);
    }

    const handleToggleStatus = () => {
        const newStatus = status === 0 ? 1 : 0;
        dispatch(enableDisableStatus({clientId: client.id, status: newStatus}));

        const toastPayload = {
            id: `toast-status-${client.id}`,
            type: "success",
            title: newStatus === 1 ? `${t("evaluationOnlineComponents:programmingDisabled")}` : `${t("evaluationOnlineComponents:programmingActivated")}`,
            message: newStatus === 1 ? `${t("evaluationOnlineComponents:successfullyDeactivated")}` : `${t("evaluationOnlineComponents:successfullyActivated")}`,
            autohide: true,
            delay: 5000
        };
        dispatch(addToast(toastPayload));
    };

    return (
        <div className={"row px-2"}>
            <div className={"card"}>
                <div className={"col-12 pb-2 py-2"}>
                    <span
                        className={"fw-semibold d-block"}>{t("evaluationOnlineComponents:scheduledOnlineEvaluation")}</span>
                </div>
                <div className={"row"}>
                    <span className={"text-md fw-semibold"}>{t("evaluationOnlineComponents:sendTo")} </span>
                    <span className={"text-md"}>{`${he.decode(client?.nome)} ${he.decode(client?.sobrenome)}`}</span>
                    <span className={"text-md fw-semibold pt-2"}>{t("evaluationOnlineComponents:frequency")} </span>
                    <div>
                        <i className={"fa-regular fa-calendar me-2"}/>
                        <span
                            className={"text-md"}>{t("evaluationOnlineComponents:every")} {frequency} {t("evaluationOnlineComponents:days")}</span>
                    </div>
                    <span className={"text-md fw-semibold pt-2"}>{t("evaluationOnlineComponents:scheduleFor")} </span>
                    <div className={"pb-2"}>
                        <i className={"fa-regular fa-calendar me-2"}/>
                        <span className={"text-md pb-2"}>{formattedNextEvaluation}</span>
                    </div>
                </div>

                <hr className={"text-secondary my-n1 pb-1"}/>
                <div className={"row align-items-center"}>
                    <div className={"col-6 border-end cursor-pointer"}>
                        <button
                            className={"btn text-md fw-semibold w-100 d-flex justify-content-center align-items-center"}
                            onClick={handleShowEdit}
                        >
                            {t("evaluationOnlineComponents:edit")}
                        </button>
                    </div>
                    <div className={"col-6"}>
                        <button type="button"
                                className={"btn btn-link text-md fw-semibold w-100 d-flex justify-content-center align-items-center"}
                                onClick={handleToggleStatus} disabled={frequencyLoading}
                        >
                            {frequencyLoading ? t("evaluationOnlineComponents:processing") : status === 0 ? t("evaluationOnlineComponents:disable") : t("evaluationOnlineComponents:activate")}
                        </button>
                    </div>
                </div>
            </div>

            <Modal show={showEditSchedule} onHide={handleShowEdit} centered>
                <ModalBody>
                    <Formik
                        initialValues={{newFrequency: frequency}}
                        onSubmit={handleUpdate}
                    >
                        {({values, handleSubmit}) => (
                            <form onSubmit={handleSubmit}>
                                <div className="row">
                                    <div className="col-12">
                                        <div className="row justify-content-between">
                                            <div className="col-auto">
                                                    <span className="fw-semibold">
                                                      {t("evaluationOnlineComponents:editFrequency")}
                                                    </span>
                                            </div>
                                            <div
                                                className="col-auto cursor-pointer"
                                                onClick={handleShowEdit}
                                            >
                                                <i className="fa-regular fa-times"/>
                                            </div>
                                        </div>
                                        <div className="py-2 text-center">
                                            <Field name="newFrequency">
                                                {({field, form}) => (
                                                    <input
                                                        type="number"
                                                        min="1"
                                                        placeholder={t("evaluationOnlineComponents:daysInNumbers")}
                                                        className={"w-100 py-2 border rounded form-control"}
                                                        {...field}
                                                        onChange={(e) =>
                                                            form.setFieldValue(field.name, Number(e.target.value))
                                                        }
                                                    />
                                                )}
                                            </Field>
                                        </div>
                                        <button
                                            type="submit"
                                            className="btn btn-primary w-100"
                                            disabled={loading || Number(values.newFrequency) < 1}
                                        >
                                            {loading
                                                ? t("evaluationOnlineComponents:saving")
                                                : t("evaluationOnlineComponents:save")}
                                        </button>
                                    </div>
                                </div>
                            </form>
                        )}
                    </Formik>
                </ModalBody>
            </Modal>
        </div>
    )
}

export default OnlineEvaluationScheduledCard;
