import {useDispatch, useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";
import {useEffect, useState} from "react";
import {selectClientCount} from "../../store/client/clientSelector";
import {contactConverted, convertContactToClient} from "../../store/signup-link/signupLinkReducer";
import Modal from "react-bootstrap/Modal";
import {isContactConverted} from "../../store/signup-link/signupLinkSelector";
import {useNavigate} from "react-router-dom";
import {fetchClientCount} from "../../store/client/clientReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/signup-link/locales/en-us.json";
import ptBR from "../../pages/signup-link/locales/pt-br.json";
import esES from "../../pages/signup-link/locales/es-es.json";
import ptPT from "../../pages/signup-link/locales/pt-pt.json";
import {handleSubscriptionButton} from "../../utils/handlers/handler";

const ContactDetailModal = ({contact}) => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const user = useSelector(selectUser)
    const clientCount = useSelector(selectClientCount)
    const [limitReached, setLimitReached] = useState(false)
    const [showLimitReachedModal, setShowLimitReachedModal] = useState(false)
    const getContactConverted = useSelector(isContactConverted)
    useComponentTranslations('signupLinkComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleDeleteClient = () => {
        navigate("/user/client/list")
    }

    const handleShowLimitReachedModal = () => {
        setShowLimitReachedModal(prevState => !prevState)
    }
    useEffect(() => {
        if (limitReached)
            handleShowLimitReachedModal()
    }, [limitReached]);

    useEffect(() => {
        if (getContactConverted) {
            navigate(`/user/signup-link/converted/${contact.id}`)
            dispatch(contactConverted(false))
        }
    }, [getContactConverted, dispatch, navigate, contact.id])

    useEffect(() => {
        dispatch(fetchClientCount())
    }, [dispatch])

    useEffect(() => {

        if (user && clientCount) {

            if (user.tipoPlano !== 200 || !user.subPlan.unlimited) {

                const total = Number(clientCount.status_0 || 0) + Number(clientCount.status_1 || 0);
                if (total >= user.plano) {
                    setLimitReached(true)

                } else
                    dispatch(convertContactToClient(contact.id))
            } else
                dispatch(convertContactToClient(contact.id))
        }
    }, [user, clientCount, contact, dispatch])
    return (
        <>
            <Modal centered show={showLimitReachedModal} onHide={handleShowLimitReachedModal}>
                <Modal.Body>
                    <div className={'row'}>
                        <div className={"col-12 text-center"}>
                            <i className={'fa-regular fa-info-circle text-warning'} style={{fontSize: '4rem'}}></i>
                        </div>
                        <div className={'col-12 fw-semibold text-center mt-4'}>
                            <span className={'fs-5'}>{t("signupLinkComponent:youReachedYourLimit")}</span>
                        </div>
                        <div className={'col-12   text-center mt-2'}>
                            <span>{t("signupLinkComponent:limitReachedMessage")}</span>
                        </div>
                        <div className={'col-12 d-grid mt-3'}>
                            <button className={"btn btn-primary"} onClick={handleSubscriptionButton}>{t("signupLinkComponent:chooseSub")}</button>
                        </div>
                        <div className={'col-12 d-grid mt-2'}>
                            <button className={"btn btn-outline-danger"} onClick={handleDeleteClient}>{t("signupLinkComponent:deleteClients")}</button>
                        </div>
                        <div className={'col-12 d-grid mt-2'}>
                            <button className={"btn btn-link"} onClick={handleShowLimitReachedModal}>{t("signupLinkComponent:goBack")}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>

        </>
    )
}

export default ContactDetailModal;