import {apiUrl, getToken} from "../api";
import axios from "axios";

export const getAllCustomEvaluationAPI = async (clientId, status) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/custom-evaluation/all?clientId=${clientId}&status=${status}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'Authorization': token
            },
            timeout: 20000
        }
    )
}

