import {createSelector} from "reselect";

const reducer = state => state.check

export const selectPendingCsat = createSelector([reducer], slice => slice.csat)
export const selectPendingChargeback = createSelector([reducer], slice => slice.chargeback)
export const selectSpointUser = createSelector([reducer], slice => slice.spointUser)
export const selectSpointUserRejected = createSelector(
    [selectSpointUser],
    spointUser => Boolean(spointUser) && spointUser.status === "refused"
)
export const selectLoadingCheck = createSelector([reducer], slice => slice.loading)
export const selectPermission = createSelector([reducer], slice => slice.permission);
export const selectBlocked = createSelector([reducer], slice => slice.blocked);
export const selectBadPassword = createSelector([reducer], slice => slice.badPassword);
