import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchUserAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

