import {
    GUIDED_TOUR_MOBILE_BREAKPOINT,
    GUIDED_TOUR_VIEWPORT_GUTTER
} from "./guidedTourDom"

const VIEWPORT_GUTTER = GUIDED_TOUR_VIEWPORT_GUTTER
const TARGET_GAP = 16
const TARGET_VISIBLE_THRESHOLD = 0.6
const DESKTOP_POPOVER_MAX_WIDTH = 352
const TABLET_POPOVER_MAX_WIDTH = 320
const DESKTOP_BREAKPOINT = 992

const clamp = (value, min, max) => {
    if (max < min) {
        return min
    }

    return Math.min(Math.max(value, min), max)
}

const buildPlacementOrder = (preferredPlacement = "auto") => {
    const defaultPlacements = ["bottom", "top", "right", "left"]

    if (!preferredPlacement || preferredPlacement === "auto") {
        return defaultPlacements
    }

    return [preferredPlacement, ...defaultPlacements.filter((placement) => placement !== preferredPlacement)]
}

const getVisibleTargetRatio = (targetRect, viewport) => {
    const targetWidth = Math.max(targetRect.width || 0, 0)
    const targetHeight = Math.max(targetRect.height || 0, 0)
    const targetArea = targetWidth * targetHeight

    if (targetArea === 0) {
        return 1
    }

    const visibleWidth = Math.max(0, Math.min(targetRect.right, viewport.width) - Math.max(targetRect.left, 0))
    const visibleHeight = Math.max(0, Math.min(targetRect.bottom, viewport.height) - Math.max(targetRect.top, 0))

    return (visibleWidth * visibleHeight) / targetArea
}

const getRawCandidateRect = (placement, targetRect, cardSize) => {
    switch (placement) {
        case "top":
            return {
                top: targetRect.top - cardSize.height - TARGET_GAP,
                left: targetRect.left + (targetRect.width / 2) - (cardSize.width / 2)
            }
        case "right":
            return {
                top: targetRect.top + (targetRect.height / 2) - (cardSize.height / 2),
                left: targetRect.right + TARGET_GAP
            }
        case "left":
            return {
                top: targetRect.top + (targetRect.height / 2) - (cardSize.height / 2),
                left: targetRect.left - cardSize.width - TARGET_GAP
            }
        case "bottom":
        default:
            return {
                top: targetRect.bottom + TARGET_GAP,
                left: targetRect.left + (targetRect.width / 2) - (cardSize.width / 2)
            }
    }
}

const clampCrossAxis = (placement, rect, cardSize, viewport) => {
    if (placement === "top" || placement === "bottom") {
        const maxLeft = viewport.width - cardSize.width - VIEWPORT_GUTTER

        return {
            ...rect,
            left: clamp(rect.left, VIEWPORT_GUTTER, maxLeft)
        }
    }

    const maxTop = viewport.height - cardSize.height - VIEWPORT_GUTTER

    return {
        ...rect,
        top: clamp(rect.top, VIEWPORT_GUTTER, maxTop)
    }
}

const buildRectWithSize = (rect, cardSize) => ({
    top: rect.top,
    left: rect.left,
    right: rect.left + cardSize.width,
    bottom: rect.top + cardSize.height
})

const isPrimaryAxisValid = (placement, rect, cardSize, viewport) => {
    if (placement === "top" || placement === "bottom") {
        return rect.top >= VIEWPORT_GUTTER && rect.top + cardSize.height <= viewport.height - VIEWPORT_GUTTER
    }

    return rect.left >= VIEWPORT_GUTTER && rect.left + cardSize.width <= viewport.width - VIEWPORT_GUTTER
}

const fitsViewportWithGutters = (rect, viewport) => {
    return rect.top >= VIEWPORT_GUTTER
        && rect.left >= VIEWPORT_GUTTER
        && rect.right <= viewport.width - VIEWPORT_GUTTER
        && rect.bottom <= viewport.height - VIEWPORT_GUTTER
}

const rectanglesOverlap = (firstRect, secondRect) => {
    return !(
        firstRect.right <= secondRect.left
        || firstRect.left >= secondRect.right
        || firstRect.bottom <= secondRect.top
        || firstRect.top >= secondRect.bottom
    )
}

const getPrimarySpace = (placement, targetRect, viewport) => {
    switch (placement) {
        case "top":
            return targetRect.top - TARGET_GAP - VIEWPORT_GUTTER
        case "right":
            return viewport.width - targetRect.right - TARGET_GAP - VIEWPORT_GUTTER
        case "left":
            return targetRect.left - TARGET_GAP - VIEWPORT_GUTTER
        case "bottom":
        default:
            return viewport.height - targetRect.bottom - TARGET_GAP - VIEWPORT_GUTTER
    }
}

const getPrimaryOverflow = (placement, rect, cardSize, viewport) => {
    if (placement === "top" || placement === "bottom") {
        return Math.max(0, VIEWPORT_GUTTER - rect.top)
            + Math.max(0, rect.top + cardSize.height - (viewport.height - VIEWPORT_GUTTER))
    }

    return Math.max(0, VIEWPORT_GUTTER - rect.left)
        + Math.max(0, rect.left + cardSize.width - (viewport.width - VIEWPORT_GUTTER))
}

const evaluateCandidate = (placement, targetRect, cardSize, viewport) => {
    const rawRect = getRawCandidateRect(placement, targetRect, cardSize)
    const clampedRect = clampCrossAxis(placement, rawRect, cardSize, viewport)
    const candidateRect = buildRectWithSize(clampedRect, cardSize)
    const targetBounds = buildRectWithSize(targetRect, {
        width: targetRect.width,
        height: targetRect.height
    })
    const visibleTargetRatio = getVisibleTargetRatio(targetRect, viewport)
    const primarySpace = getPrimarySpace(placement, targetRect, viewport)
    const primaryOverflow = getPrimaryOverflow(placement, clampedRect, cardSize, viewport)
    const isValid = isPrimaryAxisValid(placement, clampedRect, cardSize, viewport)
        && fitsViewportWithGutters(candidateRect, viewport)
        && !rectanglesOverlap(candidateRect, targetBounds)
        && visibleTargetRatio >= TARGET_VISIBLE_THRESHOLD

    return {
        placement,
        rect: candidateRect,
        primarySpace,
        primaryOverflow,
        visibleTargetRatio,
        isValid,
        score: (primaryOverflow * 1000) - primarySpace
    }
}

export const getGuidedTourPopoverMaxWidth = (viewportWidth) => {
    const safeViewportWidth = Math.max(viewportWidth || 0, VIEWPORT_GUTTER * 2)
    const clampedViewportWidth = safeViewportWidth - (VIEWPORT_GUTTER * 2)

    if (safeViewportWidth >= DESKTOP_BREAKPOINT) {
        return Math.min(DESKTOP_POPOVER_MAX_WIDTH, clampedViewportWidth)
    }

    if (safeViewportWidth > GUIDED_TOUR_MOBILE_BREAKPOINT) {
        return Math.min(TABLET_POPOVER_MAX_WIDTH, clampedViewportWidth)
    }

    return clampedViewportWidth
}

export const computeGuidedTourLayout = ({
    step,
    targetRect,
    cardSize,
    viewport,
    isMobile,
    hasLargeTarget
}) => {
    if (!step?.target) {
        return {
            mode: "modal",
            placement: "center"
        }
    }

    const maxWidth = getGuidedTourPopoverMaxWidth(viewport.width)

    if (isMobile && step.mobileBehavior === "sheet") {
        return {
            mode: "sheet",
            placement: "bottom",
            maxWidth
        }
    }

    if (isMobile && hasLargeTarget && step.mobileBehavior !== "popover") {
        return {
            mode: "sheet",
            placement: "bottom",
            maxWidth
        }
    }

    const normalizedCardSize = {
        width: Math.min(cardSize.width || maxWidth, maxWidth),
        height: cardSize.height || 0
    }

    const candidates = buildPlacementOrder(step.preferredPlacement).map((placement) => {
        return evaluateCandidate(placement, targetRect, normalizedCardSize, viewport)
    })

    const validCandidate = candidates.find((candidate) => candidate.isValid)

    if (validCandidate) {
        return {
            mode: "popover",
            placement: validCandidate.placement,
            top: validCandidate.rect.top,
            left: validCandidate.rect.left,
            maxWidth
        }
    }

    if (isMobile) {
        return {
            mode: "sheet",
            placement: "bottom",
            maxWidth
        }
    }

    const fallbackCandidate = [...candidates].sort((firstCandidate, secondCandidate) => {
        if (firstCandidate.score !== secondCandidate.score) {
            return firstCandidate.score - secondCandidate.score
        }

        return secondCandidate.visibleTargetRatio - firstCandidate.visibleTargetRatio
    })[0]

    return {
        mode: "popover",
        placement: fallbackCandidate.placement,
        top: fallbackCandidate.rect.top,
        left: fallbackCandidate.rect.left,
        maxWidth
    }
}
