import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useCallback, useEffect, useMemo, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {getOnePhysical, selectCompareList, selectCompareLoading} from "../../store/physical-evaluation/physicalEvaluationSelector";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import {fetchClient} from "../../store/client/clientReducer";
import {comparePhysical, fetchOnePhysical} from "../../store/physical-evaluation/physicalEvaluationReducer";
import moment from "moment";
import {getProtocolData} from "../../utils/physicalEvaluation/protocolData";
import EmptySet from "../../components/empty-set/EmptySet";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EvaluationCompareTableComponent from "../../components/evaluation-components/EvaluationCompareTableComponent";
import {physicalFields} from "../../utils/evaluationComponents/fields";
import {formatIMC} from "../../utils/evaluationComponents/formatters";
import {formatRQC} from "../../utils/physicalEvaluation/rqcFormula";
import {buildClientPhysicalRoute} from "../../utils/client/evaluationRoutes";

const PhysicalEvaluationCompare = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, physicalIds} = useParams();
    const {t} = useTranslation('physicalEvaluation');
    const loading = useSelector(selectCompareLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const physicalDetail = useSelector(getOnePhysical);
    const compareData = useSelector(selectCompareList);
    const [currentSelectedId, setCurrentSelectedId] = useState(null);

    const studentGender = selectedClient?.sexo?.toUpperCase() === "F" ? "female" : "male";
    const protocols = useMemo(() => getProtocolData(studentGender), [studentGender]);

    useComponentTranslations('physicalEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const protoId = Number(physicalDetail?.protocolo);
    const currentProtocol =
        physicalDetail && !isNaN(protoId)
            ? protocols.find(p => p.id === protoId)
            : null;

    const imcFormatted = physicalDetail?.imc != null
        ? formatIMC(physicalDetail.imc, t)
        : "";

    const rcqFormatted = physicalDetail?.rcq != null && Number(physicalDetail.rcq) !== 0
        ? formatRQC(physicalDetail.rcq, selectedClient?.sexo, t)
        : "";

    const isFieldFilled = useCallback((field) => {
        const value = physicalDetail[field.id] ?? physicalDetail.skinColor;
        if (value === undefined || value === null) return false;
        if (typeof value === "string") return value.trim().length > 0;
        if (typeof value === "number") {
            if (field.id === "cor") return true;
            return value !== 0;
        }
        return true;
    }, [physicalDetail]);

    const anthropometrySum = useMemo(() => {
        if (!physicalDetail || !currentProtocol) return 0;
        const sum = currentProtocol.fields.reduce((sum, field) => {
            if (field.section === "Antropometria") {
                const value = parseFloat(physicalDetail[field.id]);
                return sum + (isNaN(value) ? 0 : value);
            }
            return sum;
        }, 0);
        return parseFloat(sum.toFixed(2));
    }, [physicalDetail, currentProtocol]);

    const perimetrySum = useMemo(() => {
        if (!physicalDetail || !currentProtocol) return 0;
        const sum = currentProtocol.fields.reduce((sum, field) => {
            if (field.section === "Perimetria") {
                const value = parseFloat(physicalDetail[field.id]);
                return sum + (isNaN(value) ? 0 : value);
            }
            return sum;
        }, 0);
        return parseFloat(sum.toFixed(2));
    }, [physicalDetail, currentProtocol]);

    const sectionKeyMap = {
        Pessoal: "personal",
        Perimetria: "perimetry",
        Antropometria: "anthropometry",
        Outros: "others",
    };

    const sections = useMemo(() => {
        if (!currentProtocol) return [];
        const grouped = [];
        currentProtocol.fields
            .filter((field) => isFieldFilled(field))
            .forEach((field) => {
                const sectionName = field.section || "Outros";
                let group = grouped.find((g) => g.section === sectionName);
                if (!group) {
                    group = {section: sectionName, fields: []};
                    grouped.push(group);
                }
                group.fields.push(field);
            });
        return grouped;
    }, [currentProtocol, isFieldFilled]);

    const tableFormatters = useMemo(() => ({
        rcq: raw => formatRQC(raw, selectedClient?.sexo, t),
        imc: raw => formatIMC(raw, t),
        sumPeri: raw => raw != null ? Number(raw).toFixed(2) : raw,
        sumAntro: raw => raw != null ? Number(raw).toFixed(2) : raw,
    }), [selectedClient, t]);

    const handleGoBackPage = () => {
        navigate(buildClientPhysicalRoute(id));
    };

    const handleSelectPhysical = (physicalId) => {
        if (currentSelectedId === physicalId) {
            setCurrentSelectedId(null);
        } else {
            setCurrentSelectedId(physicalId);
            dispatch(fetchOnePhysical({id: physicalId}));
        }
    };

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        const idsArray = physicalIds?.split(',') || [];
        dispatch(comparePhysical({ids: idsArray}));
        setCurrentSelectedId(null);
    }, [dispatch, physicalIds]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            {!compareData.length && (
                                <EmptySet
                                    icon={"fa-empty-set"}
                                    message={t("physicalEvaluation:compareEmpty")}/>
                            )}
                            {!currentSelectedId &&
                                <>
                                    <div className={"col-12 pb-2"}>
                                        <span className={"fw-semibold fs-5 d-block"}>{t("physicalEvaluation:comparisonTitle")}</span>
                                    </div>
                                    <EvaluationCompareTableComponent
                                        fields={physicalFields}
                                        data={compareData}
                                        fieldFormatters={tableFormatters}
                                        noAnswerLabel={t("physicalEvaluation:noAnswer")}
                                        showComparison
                                        comparisonLabel={t("physicalEvaluation:comparison")}
                                    />
                                </>
                            }
                            {currentSelectedId && physicalDetail && currentProtocol && (
                                <>
                                    <div className={"col-12 "}>
                                        <span className={"fw-semibold fs-5 d-block"}>{t("physicalEvaluation:evaluationDetails")}</span>
                                    </div>
                                    {sections.map(({section, fields}) => (
                                        <div key={section} className="mt-2">
                                            {section !== "Pessoal" && (
                                                <span className="fw-semibold d-block fs-5">
                                                    {t(`physicalEvaluation:${sectionKeyMap[section]}`)}
                                                </span>
                                            )}
                                            {fields.map((field) => {
                                                const raw = physicalDetail[field.id] ?? physicalDetail.skinColor;
                                                const display =
                                                    field.id === "data" || field.id === "proximaAvaliacao"
                                                        ? moment(raw).format("L")
                                                        : field.id === "cor"
                                                            ? (raw === 1 || raw === "1"
                                                                ? t("physicalEvaluation:skinColors.branco")
                                                                : raw === 0 || raw === "0"
                                                                    ? t("physicalEvaluation:skinColors.negro")
                                                                    : "")
                                                            : raw;
                                                return (
                                                    <div key={field.id} className="my-2 row">
                                                        <label htmlFor={field.id} className="fw-semibold">
                                                            {t(`fields.${field.labelKey}`)}
                                                        </label>
                                                        {field.id === "data" || field.id === "proximaAvaliacao" ? (
                                                            <div>
                                                                {physicalDetail[field.id] ? moment(physicalDetail[field.id]).format("L") : ""}
                                                            </div>
                                                        ) : field.id === "observacao" ? (
                                                            <div>{physicalDetail[field.id]}</div>
                                                        ) : field.id === "objetivo" ? (
                                                            <div>{physicalDetail[field.id]}</div>
                                                        ) : field.id === "cor" ? (
                                                            <div>{display}</div>
                                                        ) : (
                                                            <span className="d-inline-block" style={{width: 'auto'}}>
                                                                {`${display}${field.unit || ''}`}
                                                            </span>
                                                        )}
                                                    </div>
                                                );
                                            })}
                                            <hr className="border-primary-subtle"/>
                                        </div>
                                    ))}
                                    <span className={"fw-semibold fs-5"}>{t("physicalEvaluation:results")}</span>
                                    {imcFormatted && (
                                        <div className="mb-1 mt-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:IMC")} </span>
                                            {imcFormatted}
                                        </div>
                                    )}
                                    {rcqFormatted && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:RCQ")} </span>
                                            {rcqFormatted}
                                        </div>
                                    )}
                                    {physicalDetail?.per_gord != null && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:fields.per_gord")} </span>
                                            {physicalDetail.per_gord}%
                                        </div>
                                    )}
                                    {physicalDetail?.magra != null && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:fields.magra")} </span>
                                            {physicalDetail.magra}kgs
                                        </div>
                                    )}
                                    {physicalDetail?.pes_gord != null && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:fields.pes_gord")} </span>
                                            {physicalDetail.pes_gord}kgs
                                        </div>
                                    )}
                                    {perimetrySum !== 0 && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:perimetrySum")} </span>
                                            {perimetrySum.toFixed(2)}cm
                                        </div>
                                    )}
                                    {anthropometrySum !== 0 && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:anthropometricSum")} </span>
                                            {anthropometrySum.toFixed(2)}mm
                                        </div>
                                    )}
                                    {physicalDetail?.pesoIdeal !== 0 && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:fields.pesoIdeal")} </span>
                                            {physicalDetail.pesoIdeal}Kgs
                                        </div>
                                    )}
                                    {physicalDetail?.gordIdeal !== 0 && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:idealFat")} </span>
                                            {physicalDetail.gordIdeal}Kgs
                                        </div>
                                    )}
                                    {physicalDetail?.massaIdeal !== 0 && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:idealMass")} </span>
                                            {physicalDetail.massaIdeal}Kgs
                                        </div>
                                    )}
                                    {physicalDetail?.gordExc !== 0 && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:excessFat")} </span>
                                            {physicalDetail.gordExc}Kgs
                                        </div>
                                    )}
                                </>
                            )}
                            <button className={`btn ${!currentSelectedId ? "btn-primary" : "btn-outline-primary"} my-2`}
                                    onClick={() => setCurrentSelectedId(null)}
                            >
                                {t("physicalEvaluation:comparison")}
                            </button>
                            <div className={"d-flex flex-column gap-2"}>
                                {compareData.map((physical) => (
                                    <button
                                        key={physical.id}
                                        className={`btn ${
                                            currentSelectedId === String(physical.id)
                                                ? "btn-primary"
                                                : "btn-outline-primary"
                                        }`}
                                        onClick={() => handleSelectPhysical(String(physical.id))}
                                    >
                                        {physical.data && moment(physical.data).format("L")}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default PhysicalEvaluationCompare;
