import AWS from 'aws-sdk';
import mime from 'mime/lite';

const saCredentials = new AWS.CognitoIdentityCredentials({
    IdentityPoolId: 'sa-east-1:e5de3bb8-7a22-4f15-a33a-f98ed53c54ac'
}, {region: 'sa-east-1'});

const s3Client = new AWS.S3({
    region: 'sa-east-1',
    credentials: saCredentials
});

async function ensureCredentials() {
    return new Promise((resolve, reject) => {
        s3Client.config.credentials.get((err) => {
            if (err) {
                reject(err);
            } else {
                resolve();
            }
        });
    });
}

async function uploadFile(file, userId, clientId, base_path) {
    await ensureCredentials();

    const randomPart = Math.random().toString(36).substring(2);
    const extension = mime.getExtension(file.type) || 'bin';
    const fileName = `${randomPart}.${extension}`;
    const key = clientId > 0 ? `${userId}/client/${clientId}/${base_path}/${fileName}` : `${userId}/${base_path}/${fileName}`;
    const contentType = file.type || mime.getType(fileName) || 'application/octet-stream';

    const params = {
        Bucket: 'secureupload.mfitpersonal.com.br',
        Key: key,
        Body: file,
        ACL: 'public-read',
        StorageClass: 'STANDARD_IA',
        ContentType: contentType
    };
    const upload = new AWS.S3.ManagedUpload({
        params,
        service: s3Client
    });

    const data = await upload.promise();
    return data.Location.replace("s3.sa-east-1.amazonaws.com/", "");
}

export default uploadFile;
