import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {selectContacts} from "../../store/signup-link/signupLinkSelector";
import {useEffect, useState} from "react";
import {deleteContact, fetchContacts,} from "../../store/signup-link/signupLinkReducer";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import Modal from "react-bootstrap/Modal";
import {isClientsLoading} from "../../store/client/clientSelector";
import ContactDetailModal from "../../components/signup-link/ContactDetailModal";
import Page from "../../components/page/Page";
import ItemListIcon from "../../components/list/ItemListIcon";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import 'moment/locale/pt-br';
import {handleWhatsAppClick} from "../../utils/handlers/handler";
import ClientNoteCard from "../../components/client/ClientNoteCard";
import LoadingBlock from "../../components/loader/LoadingBlock";
import he from "he";

const ContactDetails = () => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id} = useParams()
    const [contact, setContact] = useState(null)
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [showNotesModal, setShowNotesModal] = useState(false);
    const [showClientChange, setShowClientChange] = useState(false);
    const contacts = useSelector(selectContacts)
    const loading = useSelector(isClientsLoading)
    syncMomentLocale(i18n.language);
    useComponentTranslations('signupLink', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleChangeToClient = () => {
        setShowClientChange(true)
    }

    const handleGoBackLink = () => {
        navigate("/user/signup-link/2")
    }

    const handleNotesModal = () => {
        setShowNotesModal(prevState => !prevState)
    }

    const handleDeleteContact = () => {
        dispatch(deleteContact(Number(id)))
        handleGoBackLink()
    }

    const handleDeleteModal = () => {
        setShowDeleteModal(prevState => !prevState)
    }


    useEffect(() => {
        if (!contacts)
            dispatch(fetchContacts())
    }, [contacts, dispatch])

    useEffect(() => {
        if (contacts) {
            const foundContact = contacts.find(c => c.id === Number(id));
            if (foundContact)
                setContact(foundContact)
            else
                navigate(`/user/client/${id}?goBackTo=updates`)
        }
    }, [contacts, dispatch, id, contact, navigate]);


    if (!contact)
        return <LoadingBlock/>

    return (
        <Page goBackLink={handleGoBackLink} mt={"mt-n4"}>
            <div className={'card card-body border-0 pt-4 mb-3'}>
                <div className={'row justify-content-evenly'}>
                    <div className={'col-12 col-lg-11 text-center text-md-start '}>
                        <span className={"fw-bold d-block fs-5"}>{he.decode(contact.nome)} {he.decode(contact.sobrenome)}</span>
                        <span className={'d-block'}><i className={'fa-regular fa-envelope'}></i> {contact.mail}</span>
                        <span className={'d-block'}><i className={'fa-brands fa-whatsapp'}></i> +{contact.telefone}</span>
                    </div>
                    {
                        contact.dataCadastro &&
                        <div className={'col-12 col-lg-11 pt-3 text-center text-md-start'}>
                            <span className={'fw-bold'}>{t("signupLink:signupAt")} {moment({
                                year: contact.dataCadastro.year,
                                month: contact.dataCadastro.month - 1,
                                day: contact.dataCadastro.day
                            }).format("L")}</span>
                        </div>
                    }
                    <div className={'col-12 col-lg-11 pt-4 '}>
                        <div className={"card card-body bg-warning-subtle border-0  text-center text-md-start"}>
                                <span><i
                                    className={'fa-regular text-warning-darker fa-circle-info fa-xl '}></i> {t("signupLink:clientHasNoAccess")}</span>
                        </div>
                    </div>
                    <div className={"col-12 col-lg-11 pt-4"}>
                        <ItemListIcon icon={"fa-brands fa-whatsapp"} handler={() => handleWhatsAppClick(`${contact.telefone}`)}
                                      text={t("signupLink:talk")} size={"sm"}/>
                        <ItemListIcon icon={"fa-notebook "} handler={handleNotesModal} text={t("signupLink:notes")} size={"sm"}/>
                    </div>
                    <div className={"col-12 col-lg-11 pt-4"}>
                        <div className={"d-grid"}>
                            <button className={'btn btn-primary'} disabled={loading} onClick={handleChangeToClient}>
                                {
                                    !loading ?
                                        t("signupLink:transformInToClient") :
                                        t("signupLink:wait")
                                }
                            </button>
                        </div>
                        <div className={"d-grid mt-2"}>
                            <button className={'btn btn-outline-danger '} onClick={handleDeleteModal}>{t("signupLink:deleteContact")}</button>
                        </div>
                    </div>
                </div>
            </div>
            <Modal centered show={showNotesModal} onHide={handleNotesModal}>
                <ClientNoteCard id={id} handleClose={handleNotesModal}/>
            </Modal>
            <Modal centered show={showDeleteModal} onHide={handleDeleteModal}>
                <Modal.Body>
                    <div className={'row'}>
                        <div className={"col-12 text-center"}>
                            <i className={'fa-regular fa-info-circle text-danger'} style={{fontSize: '4rem'}}></i>
                        </div>
                        <div className={'col-12 fw-semibold text-center mt-4'}>
                            <span className={'fs-5'}>{t("signupLink:deleteAllContacts")}</span>
                        </div>
                        <div className={'col-12   text-center mt-2'}>
                            <span>{t("signupLink:actionCantBeUndone")}</span>
                        </div>
                        <div className={'col-12 d-grid mt-3'}>
                            <button className={"btn btn-danger"} onClick={handleDeleteContact}>{t("signupLink:yesDelete")}</button>
                        </div>
                        <div className={'col-12 d-grid mt-2'}>
                            <button className={"btn btn-outline-danger"} onClick={handleDeleteModal}>{t("signupLink:goBack")}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>


            {
                showClientChange &&
                <ContactDetailModal contact={contact}/>
            }
        </Page>
    )
}

export default ContactDetails;