import React, {useCallback, useEffect} from "react";
import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate} from "react-router-dom";
import PaymentMethodSelector from "../../components/subscription/PaymentMethodSelector";
import {selectUser} from "../../store/user/userSelector";
import {changePaymentMethod, selectSubPlan} from "../../store/subscription/subscriptionReducer";
import {selectedSubPlan} from "../../store/subscription/subscriptionSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const UserSubscriptionPaymentMethod = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const user = useSelector(selectUser);
    const subPlan = useSelector(selectedSubPlan);

    useComponentTranslations("userSubscriptionPage", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});


    const handleGoBack = useCallback(() => {
        navigate("/user/subscription");
    }, [navigate]);

    const handlePaymentMethodSelect = useCallback((payload) => {
        dispatch(changePaymentMethod(payload));
    }, [dispatch]);

    useEffect(() => {
        dispatch(selectSubPlan(user.subPlan.id));
    }, [dispatch, user]);

    return (
        <Page mt={"mt-n5"} contentHeader={true} title={t("userSubscriptionPage:paymentMethodTitle")} goBackLink={handleGoBack}>
            <PaymentMethodSelector subPlan={subPlan} onPaymentMethodSelect={handlePaymentMethodSelect} onGoBack={handleGoBack} isChangeMethod={true} />
        </Page>
    );
};

export default UserSubscriptionPaymentMethod;

