import {takeLatest, all, call, put} from 'redux-saga/effects';
import {fetchBalance, fetchSeller, fetchWalletRequest, onError, setBalance, setSeller, setWalletRequest} from "./walletReducer";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {getBalanceAPI, getSellerAPI, getWalletRequestAPI} from "../../api/wallet/walletActions";

export function* fetchSellerAsync() {
    try {
        const response = yield call(getSellerAPI)
        yield put(setSeller(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchSeller() {
    yield takeLatest(fetchSeller.type, fetchSellerAsync);
}

export function* fetchWalletRequestAsync() {
    try {
        const response = yield call(getWalletRequestAPI)
        yield put(setWalletRequest(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchWalletRequest() {
    yield takeLatest(fetchWalletRequest.type, fetchWalletRequestAsync);
}

export function* fetchBalanceAsync() {
    try {
        const response = yield call(getBalanceAPI)
        yield put(setBalance(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchBalance() {
    yield takeLatest(fetchBalance.type, fetchBalanceAsync);
}

export function* walletSaga() {
    yield all([
        call(onFetchBalance),
        call(onFetchWalletRequest),
        call(onFetchSeller)
    ])
}