import {useEffect, useState} from "react";

const DEFAULT_BREAKPOINT = "(max-width: 767.98px)";

const useResponsiveOffcanvasPlacement = ({
    mobilePlacement = "bottom",
    desktopPlacement = "end",
    breakpoint = DEFAULT_BREAKPOINT
} = {}) => {
    const [placement, setPlacement] = useState(desktopPlacement);

    useEffect(() => {
        if (typeof window === "undefined") {
            return undefined;
        }

        const mediaQuery = window.matchMedia(breakpoint);
        const syncPlacement = (source = mediaQuery) => {
            setPlacement(source.matches ? mobilePlacement : desktopPlacement);
        };

        syncPlacement();

        if (mediaQuery.addEventListener) {
            mediaQuery.addEventListener("change", syncPlacement);
        } else {
            mediaQuery.addListener(syncPlacement);
        }

        return () => {
            if (mediaQuery.removeEventListener) {
                mediaQuery.removeEventListener("change", syncPlacement);
            } else {
                mediaQuery.removeListener(syncPlacement);
            }
        };
    }, [breakpoint, desktopPlacement, mobilePlacement]);

    return {
        placement,
        isMobileSheet: placement === mobilePlacement
    };
};

export default useResponsiveOffcanvasPlacement;
