import {createSelector} from "reselect";

const reducer = state => state.workoutPreset;
const getLoading = (slice) => slice.loading || {};
const isLoading = (slice, key) => {
    const loading = getLoading(slice);
    return typeof loading === "boolean" ? loading : Boolean(loading[key]);
};

export const selectWorkoutPresetLoading = createSelector(
    [reducer],
    slice => {
        const loading = getLoading(slice);
        return typeof loading === "boolean"
            ? loading
            : Object.values(loading).some(Boolean);
    }
);

export const selectWorkoutPresetFetchLoading = createSelector(
    [reducer],
    slice => isLoading(slice, "fetch")
);

export const selectWorkoutPresetCreateLoading = createSelector(
    [reducer],
    slice => isLoading(slice, "create")
);

export const selectWorkoutPresetUpdateLoading = createSelector(
    [reducer],
    slice => isLoading(slice, "update")
);

export const selectWorkoutPresetDeleteLoading = createSelector(
    [reducer],
    slice => isLoading(slice, "delete")
);

export const selectWorkoutPresetApplyLoading = createSelector(
    [reducer],
    slice => isLoading(slice, "apply")
);

export const selectWorkoutPresetSaveCurrentLoading = createSelector(
    [reducer],
    slice => isLoading(slice, "saveCurrent")
);

export const selectWorkoutPresets = createSelector(
    [reducer],
    slice => slice.presets || []
);

export const selectLastCreatedWorkoutPreset = createSelector(
    [reducer],
    slice => slice.lastCreatedPreset
);

export const selectLastUpdatedWorkoutPreset = createSelector(
    [reducer],
    slice => slice.lastUpdatedPreset
);

export const selectLastSavedCurrentWorkoutPreset = createSelector(
    [reducer],
    slice => slice.lastSavedCurrentPreset
);

export const selectLastDeletedWorkoutPresetId = createSelector(
    [reducer],
    slice => slice.lastDeletedPresetId
);

export const selectLastAppliedWorkoutPreset = createSelector(
    [reducer],
    slice => slice.lastAppliedPreset
);
