import React from 'react';
import {Modal} from 'react-bootstrap';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import 'moment/locale/pt-br';

const FrequencyDatePicker = ({show, onClose, onSelectDates, initialStartDate, initialEndDate}) => {
    const {t, i18n} = useTranslation();
    syncMomentLocale(i18n.language);
    useComponentTranslations('frequencyComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object().shape({
        startDate: Yup.date()
            .required(`${t("frequencyComponent:requiredField")}`),
        endDate: Yup.date()
            .required(`${t("frequencyComponent:requiredField")}`)
            .min(
                Yup.ref('startDate'),
                `${t("frequencyComponent:startDateAfterEndDate")}`
            )
    });

    return (
        <Modal show={show} onHide={onClose} centered>
            <div className="p-2 mx-2 pt-3">
                <div className="fw-bold h5">{t("frequencyComponent:selectPeriod")}</div>
            </div>
            <Formik
                initialValues={{
                    startDate: initialStartDate || '',
                    endDate: initialEndDate || ''
                }}
                validationSchema={validationSchema}
                onSubmit={(values) => {
                    const start = moment(values.startDate, 'YYYY-MM-DD').valueOf();
                    const end = moment(values.endDate, 'YYYY-MM-DD').valueOf();
                    onSelectDates(start, end);
                    onClose();
                }}
            >
                {({handleSubmit}) => (
                    <Form onSubmit={handleSubmit} className="p-3">
                        <div className="mb-3">
                            <span className="fw-bold d-block">{t("frequencyComponent:from")}:</span>
                            <div className="input-group">
                                <Field
                                    type="date"
                                    name="startDate"
                                    className="form-control text-center"
                                />
                            </div>
                            <ErrorMessage
                                name="startDate"
                                component="div"
                                className="text-danger"
                            />
                        </div>
                        <div className="pb-4">
                            <span className="fw-bold d-block">{t("frequencyComponent:to")}:</span>
                            <Field
                                type="date"
                                name="endDate"
                                className="form-control text-center"
                            />
                            <ErrorMessage
                                name="endDate"
                                component="div"
                                className="text-danger"
                            />
                        </div>
                        <button type="submit" className="btn btn-primary-lighter w-100">
                            {t("frequencyComponent:select")}
                        </button>
                    </Form>
                )}
            </Formik>
        </Modal>
    );
};

export default FrequencyDatePicker;
