import React, {useMemo} from "react";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {useTranslation} from "react-i18next";
import Text from "../../components/utils/emoji/Text";

export default function EvaluationCompareTableComponent({
                                                            fields,
                                                            data = [],
                                                            fieldFormatters = {},
                                                            dateKey = "data",
                                                            noAnswerLabel,
                                                            firstColumnTitle,
                                                            showComparison = false,
                                                            comparisonLabel = "Comparison",
                                                        }) {
    const {i18n} = useTranslation();
    syncMomentLocale(i18n.language);

    const sortedData = useMemo(() => {
        return [...data].sort((a, b) => {
            const aTime = moment(a[dateKey]).valueOf();
            const bTime = moment(b[dateKey]).valueOf();

            if (isNaN(aTime)) return 1;
            if (isNaN(bTime)) return -1;
            return aTime - bTime;
        });
    }, [data, dateKey]);

    const formatValue = (item, field) => {
        const formatter = fieldFormatters[field.id];

        let formatted;
        if (typeof formatter === "function") {
            formatted = formatter(item[field.id], item);
        } else if (formatter != null) {
            formatted = formatter;
        } else {
            formatted = item[field.id] != null ? item[field.id] : noAnswerLabel;
        }

        return field.unit ? `${formatted}${field.unit}` : formatted;
    };

    const parseNumeric = (value) => {
        if (typeof value === "number") return value;
        if (typeof value === "string") {
            const match = value.match(/-?\d+(\.\d+)?/);
            return match ? parseFloat(match[0]) : null;
        }
        return null;
    };

    const calcDiff = (field) => {
        if (sortedData.length < 2) return noAnswerLabel;
        const first = parseNumeric(sortedData[0]?.[field.id]);
        const last = parseNumeric(sortedData[sortedData.length - 1]?.[field.id]);
        if (first == null || last == null) return noAnswerLabel;
        const diff = last - first;
        const formatted = parseFloat(diff.toFixed(2));
        const sign = formatted > 0 ? "+" : "";
        return field.unit
            ? `${sign}${formatted}${field.unit}`
            : `${sign}${formatted}`;
    };


    return (
        <div className={"table-responsive"}>
            <table className={"table table-striped mt-2"}>
                <thead>
                <tr>
                    <th className={"fw-semibold text-compare-table"}>{firstColumnTitle}</th>
                    {sortedData.map((row, i) => (
                        <th key={i} className={"text-center fw-semibold text-compare-table"}>
                            {row[dateKey]
                                ? moment(row[dateKey]).format("L")
                                : {noAnswerLabel}}
                        </th>
                    ))}
                    {showComparison && (
                        <th className="text-center fw-semibold text-compare-table">
                            {comparisonLabel}
                        </th>
                    )}
                </tr>
                </thead>
                <tbody>
                {fields.map((field) => (
                    <tr key={field.id}>
                        <td
                            className={"sticky-column fw-semibold"}
                            style={{left: 0, zIndex: 1}}
                        >
                            <Text>{field.label}</Text>
                        </td>
                        {sortedData.map((row, i) => (
                            <td key={i} className={"p-2 text-center text-sm"}>
                                {formatValue(row, field)}
                            </td>
                        ))}
                        {showComparison && (
                            <td className="p-2 text-center text-sm fw-semibold">
                                {calcDiff(field)}
                            </td>
                        )}
                    </tr>
                ))}
                </tbody>
            </table>
        </div>
    );
}
