import {useNavigate, useParams} from "react-router-dom";
import {useEffect, useState} from "react";
import {Form, Formik} from "formik";
import * as Yup from "yup";
import {useDispatch, useSelector} from "react-redux";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import OnlineEvaluationQuestion from "../../components/online-evaluation/OnlineEvaluationQuestion";
import {evaluationFields} from "../../utils/onlineEvaluation/evaluationFields";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {fetchClient} from "../../store/client/clientReducer";
import {
    getLastEvaluationClientId,
    getLastEvaluation,
    getLoading,
    getSubmitLoading,
    getSubmitResult
} from "../../store/online-evaluation/evaluationOnlineSelector";
import {
    clearEvaluation,
    clearLastEvaluation,
    fetchLastEvaluation,
    resetFormSent,
    saveOnline
} from "../../store/online-evaluation/evaluationOnlineReducer";
import {selectUser} from "../../store/user/userSelector";
import {fetchUser} from "../../store/user/userReducer";
import {calculateAge} from "../../utils/date/dateUtils";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EvaluationSuccessCard from "../../components/evaluation-components/EvaluationSuccessCard";
import {
    buildOnlineEvaluationViewRoute,
    buildOnlineEvaluationsRoute
} from "../../utils/client/evaluationRoutes";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";

const OnlineEvaluationAnswerFlow = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id} = useParams();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const submitLoading = useSelector(getSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const user = useSelector(selectUser);
    const {t} = useTranslation();
    useComponentTranslations('evaluationOnline', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const [step, setStep] = useState(0);
    const lastEvaluation = useSelector(getLastEvaluation);
    const lastEvaluationClientId = useSelector(getLastEvaluationClientId);
    const currentClientId = Number(id);
    const showCompleteMessage = isMatchingSubmitSuccess(submitResult, {
        action: "create",
        flow: EVALUATION_FLOWS.ONLINE_ANSWER,
        clientId: currentClientId
    });
    const createdEvaluationId = showCompleteMessage ? submitResult?.entityId ?? null : null;

    const sentDate = new Date().toISOString().split("T")[0];

    const initialValues = evaluationFields.reduce((acc, field) => {
        acc[field.id] = "";
        return acc;
    }, {});
    if (selectedClient?.data_nascimento) {
        initialValues.idade = calculateAge(selectedClient.data_nascimento);
    }

    const shape = {};
    evaluationFields.forEach((field) => {
        if (!field.type.includes("image")) {
            if (field.isNumeric) {
                shape[field.id] = Yup.number()
                    .transform((value, originalValue) => {
                        if (typeof originalValue === "string") {
                            const normalized = originalValue.replace(",", ".").trim();
                            if (normalized === "") return undefined;
                            return Number(normalized);
                        }
                        return value;
                    })
                    .typeError(t("evaluationOnlineComponents:numericError"))
                    .required(t("evaluationOnline:fieldRequired"));
            } else {
                let validator = Yup.string().trim();
                if (field.id === "goal") {
                    validator = validator.max(255, t("evaluationOnlineComponents:maxLength255"));
                }
                shape[field.id] = validator.required(t("evaluationOnline:fieldRequired"));
            }
        }
    });

    const validationSchema = Yup.object().shape(shape);

    const moveForward = () => {setStep(step + 1)}
    const moveBackwards = () => {setStep(step - 1)}

    const handleGoBack = () => {
        dispatch(resetFormSent())
        dispatch(clearEvaluation());
        navigate(buildOnlineEvaluationsRoute(id, "1"))
    }

    const handleView = () => {
        if (!createdEvaluationId) {
            return;
        }
        dispatch(resetFormSent())
        navigate(buildOnlineEvaluationViewRoute(id, createdEvaluationId))
    }

    const handleSubmit = (values) => {
        const clientIdParsed = Number(id);
        const userIdParsed = user?.id ? Number(user.id) : null;
        const payload = {
            idUser: userIdParsed,
            idClient: clientIdParsed,
            sentDate: sentDate,
            ...values
        };
        dispatch(saveOnline(payload, {
            flow: EVALUATION_FLOWS.ONLINE_ANSWER,
            clientId: currentClientId
        }))
    };

    useEffect(() => {
        dispatch(fetchClient(id));
        dispatch(resetFormSent());
        dispatch(clearLastEvaluation());
    }, [dispatch, id]);

    useEffect(() => {
        if (!user) {
            dispatch(fetchUser());
        }
    }, [user, dispatch]);

    useEffect(() => {
        if (currentClientId && String(lastEvaluationClientId) !== String(currentClientId)) {
            dispatch(fetchLastEvaluation({clientId: currentClientId}));
        }
    }, [currentClientId, dispatch, lastEvaluationClientId]);

    useEffect(() => {
        return () => {
            dispatch(resetFormSent())
            dispatch(clearLastEvaluation());
        }
    }, [dispatch]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBack}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"} loading={loading}>
                {!showCompleteMessage &&
                    <Formik
                        initialValues={initialValues}
                        validationSchema={validationSchema}
                        onSubmit={handleSubmit}
                        enableReinitialize
                        validateOnChange={true}
                        validateOnBlur={true}
                    >
                        {() => (
                            <Form>
                                <div className={"row justify-content-center d-flex"}>
                                    <div className={"col-12"}>
                                        {evaluationFields.map((field, index) => (
                                            index === step &&
                                            <OnlineEvaluationQuestion
                                                key={field.id}
                                                field={field}
                                                moveForward={moveForward}
                                                moveBackwards={moveBackwards}
                                                currentStep={step}
                                                maxStep={evaluationFields.length - 1}
                                                user={user}
                                                selectedClient={selectedClient}
                                                lastEvaluation={lastEvaluation}
                                                evaluation={null}
                                                videoUrl={field.videoUrl}
                                                isSubmitting={submitLoading}
                                            />
                                        ))}
                                    </div>
                                </div>
                            </Form>
                        )}
                    </Formik>
                }
                {!loading && showCompleteMessage && (
                    <div className={"row justify-content-center d-flex "}>
                        <div className={"col-12"}>
                            <EvaluationSuccessCard
                                title={t("evaluationOnline:evaluationCompleted")}
                                primaryLabel={t("evaluationOnline:seeAnswers")}
                                secondaryLabel={t("evaluationOnline:backToTop")}
                                onPrimary={handleView}
                                onSecondary={handleGoBack}
                                primaryDisabled={!createdEvaluationId}
                            />
                        </div>
                    </div>
                )}
            </Page>
        </>

    )
}

export default OnlineEvaluationAnswerFlow;
