import Page from "../../components/page/Page";
import Tabs from "../../components/tab/Tabs";
import {useEffect, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import WorkoutLibraryRoutines from "../../components/workout-library/WorkoutLibraryRoutines";

const WorkoutLibrary = () => {
    const {t} = useTranslation();
    const {pg} = useParams();
    const navigate = useNavigate()
    const [page, setPage] = useState(pg ?? "1");
    const [trainingType, setTrainingType] = useState(0);
    useComponentTranslations('trainingLibrary', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate(`/user`)
    }
    const changePages = (pageName) => {
        setPage(pageName);
    };

    useEffect(() => {
        if (page === "1") {
            setTrainingType(0)
        } else {
            setTrainingType(1)
        }
    }, [page]);

    return (
        <Page title={t("trainingLibrary:trainingLibrary")} pb={"pb-2"} goBackLink={handleGoBack}>
            <Tabs page={page} button1Text={t("trainingLibrary:routines")} button2Text={t("trainingLibrary:aerobic")}
                  mt={"mt-n4"}
                  buttonClick={changePages}/>
            <WorkoutLibraryRoutines type={trainingType}/>
        </Page>
    )
}
export default WorkoutLibrary;