import Modal from "react-bootstrap/Modal";
import {Field, Form, Formik} from "formik";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectNotificationPreference} from "../../store/client/clientSelector";
import {useEffect, useState} from "react";
import {fetchClientNotificationPreference, saveClientNotificationPreference} from "../../store/client/clientReducer";
import LoadingBlock from "../loader/LoadingBlock";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const ClientNotificationPreferenceModal = ({show, handleNotificationPreferenceModal, client}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const clientNotificationPreference = useSelector(selectNotificationPreference)
    const [initialValues, setInitialValues] = useState({
        sendEmail: false,
        sendPush: false,
        replicateToAll: false,
    })
    const loading = useSelector(isClientsLoading)
    useComponentTranslations('client', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleSubmit = (values) => {
        dispatch(saveClientNotificationPreference({id: client.id, formData: values}))
        handleNotificationPreferenceModal()
    }

    useEffect(() => {
        if (client?.id)
            dispatch(fetchClientNotificationPreference(client.id))
    }, [client, dispatch]);

    useEffect(() => {
        if (clientNotificationPreference) {
            setInitialValues({
                sendEmail: clientNotificationPreference.enabledEmail || false,
                sendPush: clientNotificationPreference.enabledPush || false,
                replicateToAll: false,
            })
        }
    }, [clientNotificationPreference])


    return (
        <Modal centered show={show} onHide={handleNotificationPreferenceModal}>
            <Modal.Body>
                <div className={"row pb-2"}>
                    <div className={"col-12"}>
                        <span className={"fw-semibold"}>{t("client:clientNotificationPreference")}</span>
                    </div>
                </div>
                {
                    !loading &&
                    <>
                        <Formik
                            initialValues={initialValues}
                            enableReinitialize={true}
                            onSubmit={handleSubmit}
                        >
                            <Form>
                                <div className={'card card-body'}>
                                    <div className={'row justify-content-between'}>
                                        <div className={'col-10'}>
                                            <span className={"fw-semibold d-block"}>{t("client:email")}:</span>
                                            <span className={"small d-block"}>{t("client:emailText")}</span>
                                        </div>
                                        <div className={'col-2 align-self-center'}>
                                            <div className="form-group form-check form-switch">
                                                <Field
                                                    type="checkbox"
                                                    name="sendEmail"
                                                    className="form-check-input"
                                                    id="sendEmail"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className={'card card-body mt-2'}>
                                    <div className={'row justify-content-between'}>
                                        <div className={'col-10'}>
                                            <span className={"fw-semibold d-block"}>{t("client:push")}:</span>
                                            <span className={"small d-block"}>{t("client:pushText")}</span>
                                        </div>
                                        <div className={'col-2 align-self-center'}>
                                            <div className="form-group form-check form-switch">
                                                <Field
                                                    type="checkbox"
                                                    name="sendPush"
                                                    className="form-check-input"
                                                    id="sendPush"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className="form-group form-check mt-2">
                                    <Field
                                        type="checkbox"
                                        name="replicateToAll"
                                        className="form-check-input"
                                        id="replicateToAll"
                                    />
                                    <label className="form-check-label fw-semibold" htmlFor="replicateToAll">
                                        {t("client:applyToAll")}
                                    </label>
                                </div>
                                <div className={'d-grid mt-3'}>
                                    <button type="submit" className="btn btn-primary ">
                                        {t("client:submit")}
                                    </button>
                                </div>
                            </Form>
                        </Formik>
                        <div className={'d-grid mt-2'}>
                            <button type="submit" className="btn btn-outline-primary" onClick={handleNotificationPreferenceModal}>
                                {t("client:close")}
                            </button>
                        </div>
                    </>
                }
                {
                    loading &&
                    <LoadingBlock/>
                }
            </Modal.Body>
        </Modal>
    )
}
export default ClientNotificationPreferenceModal;