import React from 'react';
import ChangeStatus from "../utils/change-status/ChangeStatus";
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";

function DeleteModal({
    show,
    onClose,
    onConfirm,
    deleteTitle,
    deleteSubtitle,
    confirmLabel,
    closeLabel,
    isSubmitting = false,
    loadingLabel
}) {

    return (
        <Modal
            show={show}
            onHide={onClose}
            centered
            backdrop={isSubmitting ? "static" : true}
            keyboard={!isSubmitting}
        >
            <ModalBody>
                <ChangeStatus
                    icon="fa-regular fa-circle-exclamation"
                    iconColor="text-danger"
                    title={deleteTitle}
                    subtitle={deleteSubtitle}
                />
                <div className="mt-3 d-grid">
                    <button className="btn btn-danger mb-2" onClick={onConfirm} disabled={isSubmitting}>
                        {isSubmitting ? (loadingLabel || confirmLabel) : confirmLabel}
                    </button>
                    <button className="btn btn-outline-danger" onClick={onClose} disabled={isSubmitting}>
                        {closeLabel}
                    </button>
                </div>
            </ModalBody>
        </Modal>
    );
}

export default DeleteModal;
