import * as Yup from "yup";

export function buildPhysicalEvaluationSchema(currentProtocol) {
    if (!currentProtocol || !Array.isArray(currentProtocol.fields)) {
        return Yup.object();
    }

    const shape = Object.fromEntries(
        currentProtocol.fields
            .filter(
                ({ section, id }) =>
                    section === 'Antropometria' ||
                    (section === 'Pessoal' && ['estatura', 'peso'].includes(id))
            )
            .map(({ id, label }) => [
                id,
                Yup.number()
                    .typeError(`${label} deve ser um número`)
                    .required(`${label} é obrigatório`),
            ])
    );

    return Yup.object().shape(shape);
}
