import React, {useCallback, useEffect, useMemo, useState} from "react";
import Modal from "react-bootstrap/Modal";
import * as Yup from 'yup';
import {ErrorMessage, Field, Form, Formik} from "formik";
import InputMask from "react-input-mask";
import {useDispatch, useSelector} from "react-redux";
import _ from "lodash";
import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import SubscriptionCreditCardCard from "./SubscriptionCreditCardCard";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import LoadingBlock from "../loader/LoadingBlock";
import {GoogleReCaptchaProvider, useGoogleReCaptcha} from "react-google-recaptcha-v3";
import {
    selectCoupon,
    selectCreditCardCreated,
    selectCreditCardError,
    selectCreditCards,
    selectCreditCardsLoading
} from "../../store/subscription/subscriptionSelector";
import {
    createCreditCard, createCreditCardError,
    fetchCreditCards,
    setCreditCardCreated
} from "../../store/subscription/subscriptionReducer";
import {fetchBalance, fetchSeller} from "../../store/wallet/walletReducer";
import {selectBalance, selectSeller} from "../../store/wallet/walletSelector";
import {addToast} from "../../store/toast/toastReducer";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {
    normalizeInstallmentMap,
    recalculateInstallments,
    resolveInstallmentConfiguration
} from "../../utils/installments/zoopInstallments";

const PaymentMethodSelectorComponent = ({subPlan, onPaymentMethodSelect, onGoBack, isChangeMethod}) => {
    const {t} = useTranslation();
    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const dispatch = useDispatch();
    const loadingCreditCards = useSelector(selectCreditCardsLoading);
    const creditCards = useSelector(selectCreditCards);
    const seller = useSelector(selectSeller);
    const balance = useSelector(selectBalance);
    const creditCardError = useSelector(selectCreditCardError);
    const creditCardCreated = useSelector(selectCreditCardCreated);
    const {executeRecaptcha} = useGoogleReCaptcha();
    const [openCCForm, setOpenCCForm] = useState(false);
    const [showNoPixAvailable, setShowNoPixAvailable] = useState(false);
    const [newCardId, setNewCardId] = useState(null);
    const coupon = useSelector(selectCoupon);
    const rawCouponDiscount = Number(coupon?.calculatedDiscount ?? 0);
    const planDiscount = useMemo(
        () => Number(subPlan?.calculatedDiscountAmount ?? subPlan?.discount ?? 0),
        [subPlan]
    );
    const couponDiscount = rawCouponDiscount > 0 ? rawCouponDiscount : 0;
    const discountAdjustment = couponDiscount > 0 ? couponDiscount - planDiscount : 0;
    const appliedDiscount = couponDiscount > 0 ? couponDiscount : planDiscount;

    const normalizedInstallments = useMemo(
        () => normalizeInstallmentMap(subPlan?.installments),
        [subPlan]
    );

    const installmentConfiguration = useMemo(
        () => resolveInstallmentConfiguration(subPlan, normalizedInstallments),
        [subPlan, normalizedInstallments]
    );

    const recalculatedInstallments = useMemo(
        () => recalculateInstallments(subPlan, discountAdjustment, normalizedInstallments, installmentConfiguration),
        [subPlan, discountAdjustment, normalizedInstallments, installmentConfiguration]
    );

    const effectiveInstallments = recalculatedInstallments ?? normalizedInstallments;

    const validationSchema = useMemo(() => Yup.object({
        ccName: Yup.string()
            .required(t('subscriptionComponent:paymentMethodSelector.nameRequired')),
        ccNumber: Yup.string()
            .required(t('subscriptionComponent:paymentMethodSelector.numberRequired'))
            .test('test-cc-number', t('subscriptionComponent:paymentMethodSelector.numberInvalid'), value => {
                if (!value) return false;
                const digits = value.replace(/\D/g, '');
                let sum = 0;
                let shouldDouble = false;
                for (let i = digits.length - 1; i >= 0; i--) {
                    let digit = parseInt(digits.charAt(i), 10);
                    if (shouldDouble) {
                        digit *= 2;
                        if (digit > 9) digit -= 9;
                    }
                    sum += digit;
                    shouldDouble = !shouldDouble;
                }
                return sum % 10 === 0;
            }),
        ccExp: Yup.string()
            .required(t('subscriptionComponent:paymentMethodSelector.expirationRequired'))
            .matches(/^(0[1-9]|1[0-2])\/\d{2}$/, t('subscriptionComponent:paymentMethodSelector.expirationFormat')),
        ccCvc: Yup.string()
            .required(t('subscriptionComponent:paymentMethodSelector.cvcRequired'))
            .matches(/^[0-9]{3,4}$/, t('subscriptionComponent:paymentMethodSelector.cvcDigits')),
    }), [t]);


    const handleOtherPaymentMethodClick = () => {
        handleOpenCCForm()
        handleClearCardError();
    }

    const handleClearCardError = () => {
        dispatch(createCreditCardError(null))
    }

    const handleOpenCCForm = () => {
        setOpenCCForm(prev => !prev);
        handleClearCardError();
    };

    const handleShowNoPixAvailableModal = () => {
        setShowNoPixAvailable(prev => !prev);
    };

    const handlePaymentMethod = useCallback((cc) => {
        const payload = {
            type: "credit_card",
            ...cc
        };
        onPaymentMethodSelect(payload);
        setNewCardId(null);
        onGoBack();
    }, [onPaymentMethodSelect, onGoBack]);

    const handleAlternatePaymentMethod = (type) => {
        if (type === "pix") {
            if (subPlan?.showPix) {
                onPaymentMethodSelect({type});
                onGoBack();
            } else {
                handleShowNoPixAvailableModal();
            }
            return;
        }

        if (type === "wallet") {
            let totalPlanCost = Number(subPlan?.amount || 0);
            if (!isChangeMethod) {
                const creditAmount = Number(subPlan?.credit || 0);
                totalPlanCost = totalPlanCost - appliedDiscount - creditAmount;
            }

            if (balance.current_balance >= totalPlanCost) {
                onPaymentMethodSelect({type});
                onGoBack();
            } else {
                dispatch(addToast({
                    title: t('subscriptionComponent:paymentMethodSelector.insufficientBalanceTitle'),
                    message: t('subscriptionComponent:paymentMethodSelector.insufficientBalanceMessage')
                }));
            }
        }
    };

    const handleCreditCardSubmit = async (values) => {
        if (!executeRecaptcha) return;
        const recaptchaToken = await executeRecaptcha('create_credit_card');
        dispatch(createCreditCard({...values, recaptchaToken}));
    };

    useEffect(() => {
        if (creditCardCreated) {
            if (subPlan?.month > 1) {
                setNewCardId(creditCardCreated.id);
            } else {
                handlePaymentMethod(creditCardCreated);
            }
            dispatch(setCreditCardCreated(null));
        }
    }, [creditCardCreated, subPlan, dispatch, handlePaymentMethod]);

    useEffect(() => {
        if (seller) {
            if (seller.status === "enabled") {
                dispatch(fetchBalance());
            }
        } else {
            dispatch(fetchSeller());
        }
    }, [seller, dispatch]);

    useEffect(() => {
        dispatch(fetchCreditCards());
    }, [dispatch]);

    return (
        <>
            <div className={"card card-body border-0"}>
                {
                    loadingCreditCards ? (
                        <LoadingBlock/>
                    ) : (
                        <div className={"row justify-content-center"}>
                            {
                                _.map(creditCards, (cc =>
                                        <div className={"col-12 mt-2"} key={cc.id}>
                                            <SubscriptionCreditCardCard
                                                cc={cc}
                                                handlePaymentMethod={handlePaymentMethod}
                                                subPlan={subPlan}
                                                autoOpen={cc.id === newCardId}
                                                installmentOptions={effectiveInstallments}
                                            />
                                        </div>
                                ))
                            }
                            <div className={"col-12 mt-4 mb-4 text-primary text-center"}>
                                <span className={"  clickable-element "} onClick={handleOpenCCForm}>
                                    <i className={"fa-regular fa-plus fa-xl"}></i> <span
                                    className={" ps-2"}>{t('subscriptionComponent:paymentMethodSelector.addCreditCard')}</span>
                                </span>
                            </div>
                            {
                                Number(subPlan?.id) !== 1004 &&
                                <div className={"col-12 mt-2"}>
                                    <div className={"card card-body  clickable-element"} onClick={() => handleAlternatePaymentMethod("pix")}>
                                        <div className={"row"}>
                                            <div className={"col-auto align-self-center  "} style={{color: "#77B6A8"}}>
                                                <i className={"fa-brands fa-pix fa-2x"}></i>
                                            </div>
                                            <div className={"col-auto"}>
                                                <span className={"fw-semibold d-block"}>{t('subscriptionComponent:paymentMethodSelector.pix')}</span>
                                                <span>{t('subscriptionComponent:paymentMethodSelector.instantApproval')}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            }
                            {
                                seller && seller.status === "enabled" &&
                                <div className={"col-12 mt-2"}>
                                    <div className={"card card-body   clickable-element"}
                                         onClick={() => handleAlternatePaymentMethod("wallet")}>
                                        <div className={"row"}>
                                            <div className={"col-auto align-self-center"}>
                                                <i className={"fa-regular fa-wallet fa-2x"}></i>
                                            </div>
                                            <div className={"col-auto"}>
                                                <span className={"fw-semibold d-block"}>{t('subscriptionComponent:paymentMethodSelector.wallet')}</span>
                                                <span>{t('subscriptionComponent:paymentMethodSelector.balance')}</span> <span
                                                className={"fw-semibold text-primary-lighter"}><CurrencyFormatter
                                                value={balance?.current_balance}/></span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            }

                        </div>
                    )
                }
            </div>
            <Modal show={openCCForm} onHide={handleOpenCCForm} centered>
                <Modal.Body>
                    <div className={"row"}>
                        {
                            !creditCardError &&
                            <div className={"col-12 pb-2"}>
                                <div className={"row justify-content-between"}>
                                    <div className={"col-auto"}><span
                                        className="fw-semibold fs-5">{t('subscriptionComponent:paymentMethodSelector.addNewCardTitle')}</span></div>
                                    <div className={"col-auto clickable-element fs-5"} onClick={handleOpenCCForm}><i className={"fa-regular fa-times"}></i>
                                    </div>
                                </div>
                            </div>
                        }

                        <div className={"col-12"}>
                            {
                                !creditCardError && !loadingCreditCards &&
                                <Formik
                                    initialValues={{ccName: '', ccNumber: '', ccExp: '', ccCvc: ''}}
                                    validationSchema={validationSchema}
                                    onSubmit={handleCreditCardSubmit}
                                >
                                    {({errors, touched, handleChange}) => (
                                        <Form noValidate>
                                            <div className="mb-3 form-group">
                                                <label htmlFor="ccName"
                                                       className="form-label fw-semibold">{t('subscriptionComponent:paymentMethodSelector.nameLabel')}</label>
                                                <Field
                                                    id="ccName" name="ccName" type="text"
                                                    autoComplete="cc-name" placeholder={t('subscriptionComponent:paymentMethodSelector.fullNamePlaceholder')}
                                                    className={`form-control ${touched.ccName && errors.ccName ? 'is-invalid' : ''}`}
                                                />
                                                <ErrorMessage name="ccName" component="div" className="invalid-feedback"/>
                                            </div>

                                            <div className="mb-3 form-group">
                                                <label htmlFor="ccNumber"
                                                       className="form-label fw-semibold">{t('subscriptionComponent:paymentMethodSelector.numberLabel')}</label>
                                                <Field name="ccNumber">
                                                    {({field}) => (
                                                        <InputMask
                                                            {...field}
                                                            mask="9999 9999 9999 9999 9999"
                                                            maskChar=""
                                                            placeholder={t('subscriptionComponent:paymentMethodSelector.numberPlaceholder')}
                                                            autoComplete="cc-number"
                                                            className={`form-control ${touched.ccNumber && errors.ccNumber ? 'is-invalid' : ''}`}
                                                            onChange={handleChange}
                                                        >
                                                            {inputProps => <input {...inputProps} type="text"/>}
                                                        </InputMask>
                                                    )}
                                                </Field>
                                                <ErrorMessage name="ccNumber" component="div" className="invalid-feedback"/>
                                            </div>
                                            <div className={"row mb-3 justify-content-between"}>
                                                <div className={"col-6 pe-1"}>
                                                    <div className="form-group">
                                                        <label htmlFor="ccExp"
                                                               className="form-label fw-semibold">{t('subscriptionComponent:paymentMethodSelector.expirationLabel')}
                                                            <span
                                                                className={"small"}>{t('subscriptionComponent:paymentMethodSelector.expirationHelper')}</span></label>
                                                        <Field name="ccExp">
                                                            {({field}) => (
                                                                <InputMask
                                                                    {...field}
                                                                    mask="99/99"
                                                                    maskChar=""
                                                                    placeholder={t('subscriptionComponent:paymentMethodSelector.expirationPlaceholder')}
                                                                    autoComplete="cc-exp"
                                                                    className={`form-control ${touched.ccExp && errors.ccExp ? 'is-invalid' : ''}`}
                                                                    onChange={handleChange}
                                                                >
                                                                    {inputProps => <input {...inputProps} type="text"/>}
                                                                </InputMask>
                                                            )}
                                                        </Field>
                                                        <ErrorMessage name="ccExp" component="div" className="invalid-feedback"/>
                                                    </div>
                                                </div>
                                                <div className={"col-6 ps-1"}>
                                                    <div className=" form-group">
                                                        <label htmlFor="ccCvc"
                                                               className="form-label fw-semibold">{t('subscriptionComponent:paymentMethodSelector.cvcLabel')}</label>
                                                        <Field
                                                            id="ccCvc" name="ccCvc" type="text"
                                                            autoComplete="cc-csc" placeholder={t('subscriptionComponent:paymentMethodSelector.cvcPlaceholder')}
                                                            className={`form-control ${touched.ccCvc && errors.ccCvc ? 'is-invalid' : ''}`}
                                                        />
                                                        <ErrorMessage name="ccCvc" component="div" className="invalid-feedback"/>
                                                    </div>
                                                </div>
                                            </div>
                                            <button type="submit"
                                                    className="btn btn-primary w-100">{t('subscriptionComponent:paymentMethodSelector.saveCard')}</button>
                                        </Form>
                                    )}
                                </Formik>
                            }
                            {
                                creditCardError && !loadingCreditCards &&
                                <div className={"row"}>
                                    <div className={"col-12 text-center pt-2"}>
                                        <RoundedIcon icon={"fa-credit-card"} size={"lg"}/>
                                    </div>
                                    <div className={"col-12 text-center pt-2"}>
                                        <span className={"fw-semibold fs-5"}>{t('subscriptionComponent:paymentMethodSelector.cardNotAddedTitle')}</span>
                                    </div>
                                    <div className={"col-12 text-center pt-2"}>
                                        <span>{t('subscriptionComponent:paymentMethodSelector.cardNotAddedMessage')}</span>
                                    </div>
                                    <div className={"col-12 text-center pt-4"}>
                                        <button className={"btn btn-primary-lighter w-100"}
                                                onClick={handleClearCardError}>{t('subscriptionComponent:paymentMethodSelector.tryAgain')}</button>
                                    </div>
                                    <div className={"col-12 text-center pt-2"}>
                                        <button className={"btn btn-outline-primary-lighter w-100"}
                                                onClick={handleOtherPaymentMethodClick}>{t('subscriptionComponent:paymentMethodSelector.useAnotherMethod')}</button>
                                    </div>
                                </div>
                            }
                            {
                                loadingCreditCards &&
                                <LoadingBlock/>
                            }
                        </div>
                    </div>

                </Modal.Body>
            </Modal>
            <Modal show={showNoPixAvailable} onHide={handleShowNoPixAvailableModal} centered>
                <Modal.Body>
                    <div className={"row justify-content-center"}>
                        <div className={"col-12 text-center mt-2 mb-2"}>
                            <RoundedIcon brand={true} icon={"fa-pix"} size={"lg"} textColor={"text-warning"} bgColor={"bg-warning-subtle"}/>
                        </div>
                        <div className={"col-12 text-center mt-1 mb-2"}>
                            <span className={"fw-semibold fs-5  "}>{t('subscriptionComponent:paymentMethodSelector.pixUnavailableTitle')}</span>
                        </div>
                        <div className={"col-12 text-center mt-1 mb-2"}>
                            <span>{t('subscriptionComponent:paymentMethodSelector.pixUnavailableMessage')}</span>
                        </div>
                        <div className={"col-12 text-center mt-2"}>
                            <button className={"btn btn-warning w-100 text-white"}
                                    onClick={handleShowNoPixAvailableModal}>{t('subscriptionComponent:paymentMethodSelector.chooseAnother')}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    );
};

const PaymentMethodSelector = (props) => (
    <GoogleReCaptchaProvider reCaptchaKey={"6LexQ8crAAAAAIg_9Rhim7o3ekS1grpQF0KGMk6r"}>
        <PaymentMethodSelectorComponent {...props} />
    </GoogleReCaptchaProvider>
);

export default PaymentMethodSelector;

