import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchExerciseNameAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/exercise-name/`,
        {
            headers: {
                'Content-Type': 'application/json',
                'Authorization': token
            },
            timeout: 20000
        }
    )
};

export const saveExerciseNameAPI = async (data) => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/user/exercise-name/`, data,
        {
            headers: {
                'Content-Type': 'application/json',
                'Authorization': token
            },
            timeout: 20000
        }
    )
};