import AWS from 'aws-sdk';
import mime from 'mime/lite';

// Create US credentials with the region explicitly set
const usCredentials = new AWS.CognitoIdentityCredentials(
    {
        IdentityPoolId: 'us-east-1:9122c246-0e63-4ff0-9a0e-b35d3133bf6e'
    },
    { region: 'us-east-1' }
);

// Create an S3 client for US region using these credentials
const s3ClientUS = new AWS.S3({
    region: 'us-east-1',
    credentials: usCredentials
});

// Helper function to wait for credentials to load
async function ensureCredentialsUS() {
    return new Promise((resolve, reject) => {
        s3ClientUS.config.credentials.get((err) => {
            if (err) {
                reject(err);
            } else {
                resolve();
            }
        });
    });
}

async function uploadFileUS(file, userId, onProgress) {

    await ensureCredentialsUS();

    const randomPart = Math.random().toString(36).substring(2, 65);
    const extension = mime.getExtension(file.type) || 'bin';
    const fileName = `${randomPart}.${extension}`;

    const params = {
        Bucket: "mfit-video-source",
        Key: fileName,
        Body: file,
        ACL: 'public-read',
        StorageClass: 'STANDARD_IA'
    };

    const upload = new AWS.S3.ManagedUpload({
        params,
        service: s3ClientUS
    });

    if (onProgress && typeof onProgress === 'function') {
        upload.on('httpUploadProgress', (evt) => {
            onProgress(evt);
        });
    }
    const data = await upload.promise();
    return data.Location;
}

export default uploadFileUS;
