import Page from "../../components/page/Page";
import React, {useEffect, useMemo, useState} from "react";
import FrequencyDatePicker from "../../components/frequency-report/FrequencyDatePicker";
import PersonalFinancesCard from "../../components/personal-finances/PersonalFinancesCard";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import moment from "moment/moment";
import 'moment/locale/pt-br';
import {useDispatch, useSelector} from "react-redux";
import {
    selectPersonalFinancesList,
    selectPersonalFinancesLoading
} from "../../store/personal-finances/personalFinancesSelector";
import {getAllFinances, deletePersonalFinance} from "../../store/personal-finances/personalFinancesReducer";
import EmptySet from "../../components/empty-set/EmptySet";
import PersonalFinancesDetailCard from "../../components/personal-finances/PersonalFinancesDetailCard";
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import {formatCurrency as formatCurrencyValue, formatDate as formatDateValue} from "../../utils/translation/localeUtils";

const PersonalFinances = () => {
    const {t, i18n} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const loading = useSelector(selectPersonalFinancesLoading);
    const finances = useSelector(selectPersonalFinancesList);
    const [period, setPeriod] = useState({
        startDate: moment().startOf("month").toDate(),
        endDate: moment().endOf("month").toDate(),
    });
    const [showCalendar, setShowCalendar] = useState(false);
    const [filter, setFilter] = useState("all");
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [selectedFinanceId, setSelectedFinanceId] = useState(null);
    useComponentTranslations('personalFinances', {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR})

    const formatDate = d => moment(d).format("YYYY-MM-DD");

    const handleShowCalendar = () => {
        setShowCalendar(prevState => !prevState);
    };

    const handleGoCategories = () => {
        navigate(`/user/personal-finances/categories`)
    };

    const handleGoNew = () => {
        navigate(`/user/personal-finances/new`)
    };

    const handleDeleteModal = (id = null) => {
        setSelectedFinanceId(id);
        setShowDeleteModal(prev => !prev);
    };

    const handleDeleteFinance = (id) => {
        dispatch(deletePersonalFinance(id));
        handleDeleteModal();
    };

    const handleEditFinance = (finance) => {
        const sd = formatDate(period.startDate);
        const ed = formatDate(period.endDate);
        navigate(`/user/personal-finances/edit/${finance.id}?startDate=${sd}&endDate=${ed}`);
    };

    const handleApplyPeriod = (startValue, endValue) => {
        setPeriod({
            startDate: new Date(startValue),
            endDate: new Date(endValue),
        });
        setShowCalendar(false);
    };

    const formatCurrency = (value) => formatCurrencyValue(value, i18n.language);

    const {totalRevenue, totalWaste, balance} = useMemo(() => {
        const list = Array.isArray(finances) ? finances : [];

        let revenue = 0;
        let waste = 0;
        list.forEach(f => {
            const val = Number(f.valor) || 0;
            if (f.tipoConta === 0) revenue += val;
            else if (f.tipoConta === 1) waste += val;
        });
        return {
            totalRevenue: revenue,
            totalWaste: waste,
            balance: revenue - waste,
        };
    }, [finances]);

    const filteredFinances = useMemo(() => {
        const list = Array.isArray(finances) ? finances : [];
        if (filter === "revenue") return list.filter(f => f.tipoConta === 0);
        if (filter === "waste") return list.filter(f => f.tipoConta === 1);
        return list;
    }, [finances, filter]);

    useEffect(() => {
        dispatch(getAllFinances({
            startDate: formatDate(period.startDate),
            endDate: formatDate(period.endDate),
        }));
    }, [dispatch, period]);

    return (
        <Page title={t("personalFinances:personalFinances")} loading={loading}>
            <div className={"card card-body border-0 mt-n2"}>
                <div className={"col-12 text-center"}>
                    <button className={"bg-primary-subtle rounded clickable-element border-0 w-100 p-2 fw-semibold"}
                            onClick={handleShowCalendar}
                    >
                        <span>{formatDateValue(period.startDate, i18n.language)}</span>
                        <span className={"mx-2"}>-</span>
                        <span>{formatDateValue(period.endDate, i18n.language)}</span>
                    </button>
                    {showCalendar &&
                        <FrequencyDatePicker
                            show={showCalendar}
                            onClose={() => setShowCalendar(false)}
                            onSelectDates={handleApplyPeriod}
                            initialStartDate={moment(period.startDate).format("YYYY-MM-DD")}
                            initialEndDate={moment(period.endDate).format("YYYY-MM-DD")}
                        />
                    }
                </div>

                <div className={"row pt-2"}>
                    <div className={"col-6 pe-1"}>
                        <button className={"btn btn-primary-lighter w-100"}
                                onClick={handleGoNew}>{t("personalFinances:new")}</button>
                    </div>
                    <div className={"col-6 ps-1"}>
                        <button className={"btn btn-outline-primary w-100"}
                                onClick={handleGoCategories}>{t("personalFinances:categories")}</button>
                    </div>
                </div>
                <div className={"d-flex flex-row justify-content-center p-3 gap-2"}>
                    <button className={`btn ${filter === "all" ? "bg-primary-subtle text-primary" : "btn-outline-secondary"}`}
                            onClick={() => setFilter("all")}>
                        {t("personalFinances:total")}
                    </button>
                    <button className={`btn ${filter === "revenue" ? "bg-primary-subtle text-primary" : "btn-outline-secondary"}`}
                            onClick={() => setFilter("revenue")}>
                        {t("personalFinances:revenue")}
                    </button>
                    <button className={`btn ${filter === "waste" ? "bg-primary-subtle text-primary" : "btn-outline-secondary"}`}
                            onClick={() => setFilter("waste")}>
                        {t("personalFinances:waste")}
                    </button>
                </div>
                {filter !== "all" && filteredFinances?.length === 0 && (
                    <div className={"text-center"}>
                        <EmptySet message={t("personalFinances:noTransactions")}
                                  icon={"fa-regular fa-money-check-pen"}
                        />
                    </div>
                )}
                {filter === "all" &&
                    <div className={"d-flex flex-column gap-2"}>
                        <PersonalFinancesCard
                            title={t("personalFinances:revenuePeriod")}
                            subtitle={formatCurrency(totalRevenue)}
                            subtitleClassName={"text-success"}
                        />
                        <PersonalFinancesCard
                            title={t("personalFinances:wastePeriod")}
                            subtitle={formatCurrency(totalWaste)}
                            subtitleClassName={"text-danger"}
                        />
                        <PersonalFinancesCard
                            title={t("personalFinances:salePeriod")}
                            subtitle={formatCurrency(balance)}
                            subtitleClassName={"text-success"}
                        />
                    </div>
                }
                {(filter === "revenue" || filter === "waste") && filteredFinances.length > 0 && (
                    <>
                        <PersonalFinancesCard
                            title={`${filter === "revenue" ? t("personalFinances:revenuePeriod") : t("personalFinances:wastePeriod")}`}
                            subtitle={`${filter === "revenue" ? formatCurrency(totalRevenue) : formatCurrency(totalWaste)}`}
                            subtitleClassName={`${filter === "revenue" ? "text-success" : "text-danger"}`}
                        />
                        <span className={"fs-5 fw-semibold my-2"}>{t("personalFinances:details")}</span>
                        <div className={"d-grid gap-2"}>
                            {filteredFinances.map(f => {
                                const categoryName = f.personalFinanceCategory?.nome ?? t("personalFinances:unknownCategory");
                                return (
                                    <PersonalFinancesDetailCard
                                        key={f.id}
                                        title={categoryName}
                                        status={f.pago === 1 ? t("personalFinances:received") : t("personalFinances:pending")}
                                        date={formatDateValue(f.dataFatura, i18n.language)}
                                        receive={formatDateValue(f.dataPagamento, i18n.language)}
                                        value={formatCurrency(f.valor)}
                                        description={f.descricao}
                                        reference={f.referencia}
                                        onDelete={() => handleDeleteModal(f.id)}
                                        onEdit={() => handleEditFinance(f)}
                                    />
                                )
                            })}
                        </div>

                    </>
                )}
            </div>
            <Modal show={showDeleteModal} onHide={handleDeleteModal} centered>
                <ModalBody>
                    <div className={'row justify-content-center'}>
                        <div className={"col-12 text-center"}>
                            <i className={'fa-regular fa-circle-exclamation text-danger'}
                               style={{fontSize: '3rem'}}></i>
                        </div>
                        <div className={'col-12 fw-semibold text-center mt-2'}>
                            <span className={'fs-5'}>{t("personalFinances:areYouSure")}</span>
                        </div>
                        <div className={'col-12 text-center mt-2'}>
                            <span>{t("personalFinances:actionCantBeUndone")}</span>
                        </div>
                        <div className={'col-12 d-grid mt-3'}>
                            <button className={"btn btn-danger text-white"} onClick={() => {
                                handleDeleteFinance(selectedFinanceId);
                            }}
                            >{t("personalFinances:yesDelete")}</button>
                        </div>
                        <div className={'col-12 d-grid mt-2'}>
                            <button className={"btn btn-outline-danger"} onClick={handleDeleteModal}
                            >{t("personalFinances:goBack")}</button>
                        </div>
                    </div>
                </ModalBody>
            </Modal>
        </Page>
    )
}

export default PersonalFinances;
