import {all, call, put, takeLatest} from "redux-saga/effects";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    deleteClientProgressAPI,
    getAllClientProgressAPI,
    respondClientProgressAPI
} from "../../api/client-progress/clientProgressActions";
import {
    clientProgressListError,
    deleteClientProgress,
    deleteClientProgressSuccess,
    fetchClientProgressList,
    onError,
    respondClientProgress,
    respondClientProgressSuccess,
    setClientProgressList
} from "./clientProgressReducer";
import {fetchUpdateCountByType, fetchUpdatesCount} from "../updates/updatesReducer";

const resolveClientProgressErrorCode = (error) => (
    error?.response?.data?.errorMessage
    || error?.response?.data?.code
    || error?.errorMessage
    || error?.code
    || null
);

export function* fetchClientProgressListAsync(action) {
    try {
        const response = yield call(getAllClientProgressAPI, action.payload);
        yield put(setClientProgressList(response.data));
    } catch (error) {
        yield put(clientProgressListError(resolveClientProgressErrorCode(error)));
        yield call(handleError, error, onError);
    }
}

export function* onFetchClientProgressList() {
    yield takeLatest(fetchClientProgressList.type, fetchClientProgressListAsync);
}

export function* respondClientProgressAsync({payload}) {
    try {
        const normalizedResponse = (payload.formData?.response || "").trim();
        yield call(respondClientProgressAPI, payload);
        yield put(respondClientProgressSuccess({
            progressId: payload.progressId,
            response: normalizedResponse
        }));
        yield put(fetchUpdatesCount());
        yield put(fetchUpdateCountByType());
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onRespondClientProgress() {
    yield takeLatest(respondClientProgress.type, respondClientProgressAsync);
}

export function* deleteClientProgressAsync({payload}) {
    try {
        yield call(deleteClientProgressAPI, payload.id, payload.progressId);
        yield put(deleteClientProgressSuccess(payload.progressId));
        yield put(fetchUpdatesCount());
        yield put(fetchUpdateCountByType());
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onDeleteClientProgress() {
    yield takeLatest(deleteClientProgress.type, deleteClientProgressAsync);
}

export function* clientProgressSaga() {
    yield all([
        call(onFetchClientProgressList),
        call(onRespondClientProgress),
        call(onDeleteClientProgress)
    ]);
}
