import {useCallback} from "react";
import {useParams} from "react-router-dom";
import {
    changeStatus
} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";
import {
    getSubmitLoading,
    getSubmitResult
} from "../../store/bioimpedance-evaluation/bioimpedanceSelector";
import useComponentTranslations from "../translation/useComponentTranslations";
import ptBR from ".//locales/pt-br.json";
import ptPT from ".//locales/pt-pt.json";
import enUS from ".//locales/en-us.json";
import esES from ".//locales/es-es.json";
import {useMeasurementEvaluationActions} from "../measurementEvaluation/useMeasurementEvaluationActions";
import {
    buildBioimpedanceChartsRoute,
    buildBioimpedanceCompareRoute,
    buildBioimpedanceCreateRoute,
    buildBioimpedanceDeletedRoute,
    buildBioimpedanceEditRoute,
    buildBioimpedanceViewRoute,
    buildClientBioimpedanceRoute,
    buildClientMorphologicalRoute
} from "../client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../evaluation/flows";

export function useBioimpedanceActions() {
    const {id} = useParams();
    useComponentTranslations("utils", { "pt-BR": ptBR, "pt-PT": ptPT, "en-US": enUS, "es-ES": esES})
    const measurementActions = useMeasurementEvaluationActions({
        clientId: id,
        changeStatusAction: changeStatus,
        deleteFlow: EVALUATION_FLOWS.BIOIMPEDANCE_DELETE,
        selectSubmitResult: getSubmitResult,
        selectSubmitLoading: getSubmitLoading,
        routes: {
            goBack: () => buildClientMorphologicalRoute(id),
            createNew: () => buildBioimpedanceCreateRoute(id, 8),
            goView: (bioimpedanceId) => buildBioimpedanceViewRoute(id, bioimpedanceId),
            goEdit: (bioimpedanceId) => buildBioimpedanceEditRoute(id, bioimpedanceId),
            goCompare: (bioimpedanceIds) => buildBioimpedanceCompareRoute(id, bioimpedanceIds),
            goCharts: () => buildBioimpedanceChartsRoute(id),
            goDeleted: () => buildBioimpedanceDeletedRoute(id),
            goList: () => buildClientBioimpedanceRoute(id),
        },
    });
    const {setCurrentEvaluation} = measurementActions.handlers;
    const setBio = useCallback(
        (bio) => setCurrentEvaluation(bio),
        [setCurrentEvaluation]
    );

    return {
        state: {
            ...measurementActions.state,
            currentBio: measurementActions.state.currentEvaluation,
            showOptions: measurementActions.state.showOptions,
            showShare: measurementActions.state.showShare,
            showDelete: measurementActions.state.showDelete,
        },
        handlers: {
            ...measurementActions.handlers,
            setCurrentBio: setBio
        },
        shareLink: measurementActions.shareLink
    };
}
