import {closestCenter, DndContext, PointerSensor, useSensor, useSensors} from "@dnd-kit/core";
import {arrayMove, SortableContext, verticalListSortingStrategy} from "@dnd-kit/sortable";
import SortableItem from "./WorkoutSessionSortableItem";
import WorkoutSessionCard from "./WorkoutSessionCard";
import {useEffect, useState} from "react";
import {changeWorkoutSessionOrder, setWorkoutSessionOrder} from "../../store/workout-routine/workoutRoutineReducer";
import {useDispatch} from "react-redux";

const WorkoutSessionDraggableList = ({
                                         workout,
                                         isLibrary,
                                         onEditToggle,
                                         dragDisabled
                                     }) => {
    const dispatch = useDispatch();
    const [sessions, setSessions] = useState(workout.sessions || []);

    const sensors = useSensors(
        useSensor(PointerSensor, {activationConstraint: {distance: 5}})
    );

    const handleDragEnd = (event) => {
        const {active, over} = event;
        if (!over || active.id === over.id) return;

        const oldIndex = sessions.findIndex((i) => i.id === active.id);
        const newIndex = sessions.findIndex((i) => i.id === over.id);
        const newSessions = arrayMove(sessions, oldIndex, newIndex);

        setSessions(newSessions);
        dispatch(setWorkoutSessionOrder(newSessions));
        dispatch(
            changeWorkoutSessionOrder(
                newSessions.map((s, pos) => ({id: s.id, position: pos}))
            )
        );
    };

    useEffect(() => {
        setSessions(workout.sessions || []);
    }, [workout.sessions]);

    return (
        <DndContext
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
        >
            <SortableContext
                items={sessions}
                strategy={verticalListSortingStrategy}
            >
                {sessions.map((session) => (
                    <SortableItem id={session.id} key={session.id} disabled={dragDisabled}  >
                        <WorkoutSessionCard
                            workout={workout}
                            session={session}
                            isLibrary={isLibrary}
                            dragDisabled={dragDisabled}
                            onEditToggle={onEditToggle}
                        />
                    </SortableItem>
                ))}
            </SortableContext>
        </DndContext>
    );
};

export default WorkoutSessionDraggableList;
