import AppOffcanvasShell from "../offcanvas/AppOffcanvasShell";
import RoundedIcon from "../rounded-icon/RoundedIcon";

const RetentionInfoOffcanvas = ({
    show,
    onHide,
    title,
    intro,
    sections = [],
    sectionVariant = "icon"
}) => {
    return (
        <AppOffcanvasShell show={show} onHide={onHide}>
            <div className={"flex-grow-1 overflow-auto pt-4"}>
                <div className={"px-1"}>
                    <div className={"mb-4"}>
                        <h2 className={"fs-5 fw-semibold text-dark mb-2"}>
                            {title}
                        </h2>
                        <p className={"text-secondary mt-1 mb-0"}>
                            {intro}
                        </p>
                    </div>

                    <div className={"d-grid gap-3"}>
                        {sections.map((section) => (
                            <section key={section.key} className={"d-flex flex-column align-items-start"}>
                                {sectionVariant === "icon" && (
                                    <div className={"mb-3"}>
                                        <RoundedIcon icon={section.icon} size={"sm"}/>
                                    </div>
                                )}

                                {sectionVariant === "status" ? (
                                    <div className={"d-flex align-items-center gap-2 mb-1"}>
                                        <span
                                            className={`rounded-circle flex-shrink-0 ${section.dotClass}`}
                                            style={{width: "8px", height: "8px"}}
                                        ></span>
                                        <span className={"fw-semibold text-dark"}>
                                            {section.title}
                                        </span>
                                    </div>
                                ) : (
                                    <h3 className={"fs-5 fw-semibold text-dark mb-0"}>
                                        {section.title}
                                    </h3>
                                )}

                                <p className={`text-secondary ${sectionVariant === "icon" ? "mt-1" : "mt-0"} mb-0`}>
                                    {section.description}
                                </p>
                            </section>
                        ))}
                    </div>
                </div>
            </div>
        </AppOffcanvasShell>
    );
};

export default RetentionInfoOffcanvas;
