export const RETENTION_TOUR_EXPERIENCE_ID = "app-user:guided-tour:retention-dashboard:v1"
export const RETENTION_TOUR_STORAGE_KEY = RETENTION_TOUR_EXPERIENCE_ID

const TOUR_SELECTORS = {
    summary: '[data-tour="retention-summary"]',
    breakdown: '[data-tour="retention-breakdown"]',
    controls: '[data-tour="retention-clients-controls"]',
    notify: '[data-tour="retention-notify"]',
    firstClient: '[data-tour="retention-first-client"]',
    firstClientExpanded: '[data-tour="retention-first-client-expanded"]'
}

export const buildRetentionDashboardTourSteps = ({t, hasClients}) => {
    const steps = [
        {
            id: "intro",
            title: t("retention:tourIntroTitle"),
            description: t("retention:tourIntroDescription")
        },
        {
            id: "summary",
            target: TOUR_SELECTORS.summary,
            mobileBehavior: "sheet",
            title: t("retention:tourSummaryTitle"),
            description: t("retention:tourSummaryDescription")
        },
        {
            id: "breakdown",
            target: TOUR_SELECTORS.breakdown,
            mobileBehavior: "sheet",
            title: t("retention:tourBreakdownTitle"),
            description: t("retention:tourBreakdownDescription")
        },
        {
            id: "clients",
            target: TOUR_SELECTORS.controls,
            mobileBehavior: "sheet",
            title: t("retention:tourClientsTitle"),
            description: t("retention:tourClientsDescription")
        },
        {
            id: "notify",
            target: TOUR_SELECTORS.notify,
            mobileBehavior: "auto",
            title: t("retention:tourNotifyTitle"),
            description: t("retention:tourNotifyDescription")
        }
    ]

    if (hasClients) {
        steps.push({
            id: "client",
            target: TOUR_SELECTORS.firstClient,
            mobileBehavior: "auto",
            title: t("retention:tourClientTitle"),
            description: t("retention:tourClientDescription")
        }, {
            id: "client-actions",
            target: TOUR_SELECTORS.firstClientExpanded,
            mobileBehavior: "sheet",
            title: t("retention:tourClientActionsTitle"),
            description: t("retention:tourClientActionsDescription")
        })
    }

    return steps
}
