import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    exercise: null,
    userExercises: null,
    favorites: null,
    exerciseGroups: null,
    exerciseCategories: null,
    exerciseSaved: false,
    exerciseDeleteLoading: false,
    groupDeleteLoading: false,
    loading: false,
}

export const slice = createSlice({
    name: 'exerciseLibrary',
    initialState,
    reducers: {
        setExerciseAsSaved(state, action) {
            state.exerciseSaved = action.payload;
        },
        updateExercise(state) {
            state.loading = true
        },
        createExercise(state) {
            state.loading = true;
        },
        fetchExercise(state) {
            state.loading = true;
        },
        setExercise(state, action) {
            state.exercise = action.payload;
            state.loading = false;
        },
        fetchExerciseGroups(state) {
            state.loading = true;
        },
        setExerciseGroups(state, action) {
            state.exerciseGroups = action.payload;
            state.loading = false;
        },
        fetchExerciseCategories(state) {
            state.loading = true;
        },
        setExerciseCategories(state, action) {
            state.exerciseCategories = action.payload;
            state.loading = false;
        },
        fetchUserExercises(state) {
            state.loading = true;
        },
        setUserExercises(state, action) {
            state.userExercises = action.payload;
            state.loading = false
        },
        fetchExerciseFavorites(state) {
        },
        setExerciseFavorites(state, action) {
            state.favorites = action.payload;
        },
        setExerciseAsFavorite(state) {
        },
        removeExerciseAsFavorite(state) {
        },
        exerciseSetAsFavorite(state, action) {
            state.favorites.push(action.payload);
        },
        exerciseRemovedAsFavorite(state, action) {
            state.favorites = state.favorites.filter((exercise) => exercise.id !== Number(action.payload));
        },
        deleteExercise(state) {
            state.exerciseDeleteLoading = true;
        },
        deleteExerciseSuccess(state, action) {
            state.exerciseDeleteLoading = false;
            state.favorites = state.favorites.filter((exercise) => exercise.id !== Number(action.payload));
            state.userExercises = state.userExercises.filter((exercise) => exercise.id !== Number(action.payload));
        },
        deleteGroup(state){
            state.groupDeleteLoading = true
        },
        deleteGroupSuccess(state, action){
            state.groupDeleteLoading = false;
            state.exerciseGroups = state.exerciseGroups.filter((group) => group.id !== Number(action.payload));
        },
        deleteCategory(state){
            state.categoryDeleteLoading = true
        },
        deleteCategorySuccess(state, action){
            state.categoryDeleteLoading = false;
            state.exerciseCategories = state.exerciseCategories.filter((category) => category.id !== Number(action.payload));
        },
        createGroup(state) {
            state.loading = true;
        },
        createCategory(state){
            state.loading = true;
        },
        groupCreated(state, action){
            state.loading = false;
            state.exerciseGroups =  action.payload;
        },
        categoryCreated(state, action){
            state.loading = false;
            state.exerciseCategories = action.payload;
        },
        onError(state) {
            state.loading = false;
        }
    }
})

export const {
    fetchExerciseFavorites,
    setExerciseFavorites,
    setExerciseAsFavorite,
    removeExerciseAsFavorite,
    exerciseSetAsFavorite,
    exerciseRemovedAsFavorite,
    fetchUserExercises,
    setUserExercises,
    fetchExerciseGroups,
    setExerciseGroups,
    fetchExerciseCategories,
    setExerciseCategories,
    setExercise,
    createExercise,
    fetchExercise,
    updateExercise,
    setExerciseAsSaved,
    deleteExercise,
    deleteExerciseSuccess,
    deleteGroup,
    deleteGroupSuccess,
    createGroup,
    createCategory,
    groupCreated,
    categoryCreated,
    deleteCategory,
    deleteCategorySuccess,
    onError
} = slice.actions;

export const exerciseLibraryReducer = slice.reducer;