import AnamnesisModelModal from "./AnamnesisModelModal";
import {useState} from "react";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const AnamnesisModelListItem = ({model, clientId}) => {
    const {t} = useTranslation()
    const [showModal, setShowModal] = useState(false);
    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleModal = () => {
        setShowModal(prevState => !prevState)
    }

    return (
        <>
            <div className="row clickable-element pt-2">
                <div className="card card-body clickable-element py-4"
                     onClick={handleModal}>
                    <div className="row d-flex align-items-center">
                        <div className="col-10 clickable-element">
                            <span className="fw-semibold">{model.name === "Padrão" || model.name === "PAR-Q" ? t(`anamnesisComponent:${model.name}`) : model.name}</span>
                        </div>
                        <div className="col-2 text-end">
                            <i className="fa-regular fa-chevron-right"/>
                        </div>
                    </div>
                </div>
            </div>
            <AnamnesisModelModal
                model={model}
                onClose={handleModal}
                clientId={clientId}
                show={showModal}
            />

        </>
    )
}
export default AnamnesisModelListItem;