import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    routineList: null,
    currentFolder: null,
    loadingCurrentFolder: false,
    foldersList: null,
    folderCreated: false,
    folderUpdated: false,
    folderDeleted: false,
    routineDuplicated: false,
    routineDeleted: false,
    loadingRoutineList: false,
    loadingFoldersList: false,
    loadingCreatingFolder: false,
    loadingUpdatingFolder: false,
    loadingDeletingFolder: false,
    loadingRoutineUpdate: false,
    loadingDuplicateRoutine: false,
    loadingRoutineDelete: false,
    cloneLoading: false,
    cloneSuccess: false,
}

export const slice = createSlice({
    name: "workoutLibrary",
    initialState,
    reducers: {
        cloneRoutine(state) {
            state.cloneLoading = true
        },
        routineCloned(state, action) {
            state.cloneLoading = false
            state.cloneSuccess = action.payload
        },
        deleteRoutine(state) {
            state.loadingRoutineDelete = true
        },
        routineDeleted(state, action) {
            state.currentFolder.treinos = state.currentFolder.treinos.filter(r => r.id !== action.payload);
            state.loadingRoutineDelete = false
            state.routineDeleted = true
        },
        setRoutineDeleted(state, action) {
            state.routineDeleted = action.payload
        },
        duplicateRoutine(state) {
            state.loadingDuplicateRoutine = true
        },
        routineDuplicated(state, action) {
            state.routineDuplicated = action.payload
            state.loadingDuplicateRoutine = false;
        },
        updateRoutineFolder(state) {
            state.loadingRoutineUpdate = true
        },
        routineFolderUpdated(state, action) {
            state.currentFolder.treinos = state.currentFolder.treinos.filter(r => r.id !== action.payload);
            state.loadingRoutineUpdate = false;
        },
        setRoutineList(state, action) {
            state.routineList = action.payload
            state.loadingRoutineList = false
        },
        updateAerobicName(state, action) {
            const {id, name} = action.payload
            if(state.currentFolder){
                state.currentFolder.treinos = state.currentFolder?.treinos.map(r => {
                    if (r.id === id) {
                        return { ...r, nome: name };
                    }
                    return r
                })
            }

        },
        fetchRoutinesList(state) {
            state.loadingRoutineList = true
        },
        fetchCurrentFolder(state) {
            state.loadingCurrentFolder = true;
        },
        setCurrentFolder(state, action) {
            state.currentFolder = action.payload;
            state.loadingCurrentFolder = false;
        },
        fetchFoldersList(state) {
            state.loadingFoldersList = true;
        },
        setFoldersList(state, action) {
            state.foldersList = action.payload;
            state.loadingFoldersList = false;
        },
        createFolder(state) {
            state.loadingCreatingFolder = true
        },
        folderCreated(state, action) {
            const {payload} = action.payload;
            state.loadingCreatingFolder = false
            state.folderCreated = payload
        },
        folderUpdated(state, action) {
            const {payload, folder} = action.payload
            state.folderUpdated = payload;
            state.loadingUpdatingFolder = false;
            if (folder) {
                if (state.currentFolder) {
                    state.currentFolder.name = folder.name
                }
                if (state.foldersList) {
                    state.foldersList = state.foldersList.map(fd => {
                        if (fd.id === folder.id) {
                            return folder
                        }
                        return fd
                    })
                }
            }
        },
        updateFolder(state) {
            state.loadingUpdatingFolder = true
        },
        deleteFolder(state) {
            state.loadingDeletingFolder = true
        },
        folderDeleted(state, action) {
            const {payload, folderId} = action.payload
            state.loadingDeletingFolder = false
            state.folderDeleted = payload;
            if (folderId) {
                if (state.foldersList) {
                    state.foldersList = state.foldersList.filter(folder => folder.id !== folderId)
                }
            }
        },
        onError(state) {
            state.loading = false;
        }
    }
})

export const {

    fetchCurrentFolder,
    setCurrentFolder,
    fetchFoldersList,
    setFoldersList,
    createFolder,
    folderCreated,
    updateFolder,
    folderUpdated,
    deleteFolder,
    folderDeleted,
    fetchRoutinesList,
    setRoutineList,
    updateRoutineFolder,
    routineFolderUpdated,
    duplicateRoutine,
    routineDuplicated,
    deleteRoutine,
    routineDeleted,
    setRoutineDeleted,
    cloneRoutine,
    routineCloned,
    updateAerobicName,
    onError
}
    = slice.actions
export const workoutLibraryReducer = slice.reducer
