import {apiUrl, getToken} from "../api";
import axios from "axios";

export const checkVersion = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/version/`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    });
}