import {all, call, put, takeLatest} from "redux-saga/effects";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    applyWorkoutPreset,
    applyWorkoutPresetFailure,
    applyWorkoutPresetSuccess,
    createWorkoutPreset,
    createWorkoutPresetFailure,
    createWorkoutPresetSuccess,
    deleteWorkoutPreset,
    deleteWorkoutPresetFailure,
    deleteWorkoutPresetSuccess,
    fetchWorkoutPresets,
    fetchWorkoutPresetsFailure,
    saveCurrentWorkoutPreset,
    saveCurrentWorkoutPresetFailure,
    saveCurrentWorkoutPresetSuccess,
    setWorkoutPresets,
    updateWorkoutPreset,
    updateWorkoutPresetFailure,
    updateWorkoutPresetSuccess
} from "./workoutPresetReducer";
import {
    applyWorkoutPresetAPI,
    createWorkoutPresetAPI,
    deleteWorkoutPresetAPI,
    fetchWorkoutPresetsAPI,
    saveCurrentWorkoutPresetAPI,
    updateWorkoutPresetAPI
} from "../../api/workout-prescription/workoutPrescriptionActions";
import {setWorkoutSession} from "../workout-prescription/workoutPrescriptionReducer";

export function* fetchWorkoutPresetsAsync() {
    try {
        const response = yield call(fetchWorkoutPresetsAPI);
        yield put(setWorkoutPresets(response.data));
    } catch (error) {
        yield call(handleError, error, fetchWorkoutPresetsFailure);
    }
}

export function* onFetchWorkoutPresets() {
    yield takeLatest(fetchWorkoutPresets.type, fetchWorkoutPresetsAsync);
}

export function* createWorkoutPresetAsync(action) {
    try {
        const response = yield call(createWorkoutPresetAPI, action.payload);
        yield put(createWorkoutPresetSuccess(response.data));
    } catch (error) {
        yield call(handleError, error, createWorkoutPresetFailure);
    }
}

export function* onCreateWorkoutPreset() {
    yield takeLatest(createWorkoutPreset.type, createWorkoutPresetAsync);
}

export function* updateWorkoutPresetAsync(action) {
    try {
        const response = yield call(updateWorkoutPresetAPI, action.payload);
        yield put(updateWorkoutPresetSuccess(response.data));
    } catch (error) {
        yield call(handleError, error, updateWorkoutPresetFailure);
    }
}

export function* onUpdateWorkoutPreset() {
    yield takeLatest(updateWorkoutPreset.type, updateWorkoutPresetAsync);
}

export function* deleteWorkoutPresetAsync(action) {
    try {
        yield call(deleteWorkoutPresetAPI, action.payload);
        yield put(deleteWorkoutPresetSuccess(action.payload));
    } catch (error) {
        yield call(handleError, error, deleteWorkoutPresetFailure);
    }
}

export function* onDeleteWorkoutPreset() {
    yield takeLatest(deleteWorkoutPreset.type, deleteWorkoutPresetAsync);
}

export function* applyWorkoutPresetAsync(action) {
    try {
        const response = yield call(applyWorkoutPresetAPI, action.payload);
        yield put(setWorkoutSession(response.data));
        yield put(applyWorkoutPresetSuccess(action.payload));
    } catch (error) {
        yield call(handleError, error, applyWorkoutPresetFailure);
    }
}

export function* onApplyWorkoutPreset() {
    yield takeLatest(applyWorkoutPreset.type, applyWorkoutPresetAsync);
}

export function* saveCurrentWorkoutPresetAsync(action) {
    try {
        const response = yield call(saveCurrentWorkoutPresetAPI, action.payload);
        yield put(saveCurrentWorkoutPresetSuccess(response.data));
    } catch (error) {
        yield call(handleError, error, saveCurrentWorkoutPresetFailure);
    }
}

export function* onSaveCurrentWorkoutPreset() {
    yield takeLatest(saveCurrentWorkoutPreset.type, saveCurrentWorkoutPresetAsync);
}

export function* workoutPresetSaga() {
    yield all([
        call(onFetchWorkoutPresets),
        call(onCreateWorkoutPreset),
        call(onUpdateWorkoutPreset),
        call(onDeleteWorkoutPreset),
        call(onApplyWorkoutPreset),
        call(onSaveCurrentWorkoutPreset)
    ]);
}
