import {apiUrl as url, getToken} from "../api";
import axios from "axios";

const apiUrl = url + "/v2";
export const fetchClientCountAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/client/count`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

export const fetchClientNoAuthAPI = async (id) => {
    if (!id) return;
    return await axios.get(`${apiUrl}/user/client/?id=${id}`, {
        headers: {
            'Content-Type': 'application/json'
        },
        timeout: 20000
    })
}

export const fetchClientsByStatusPaginatedAPI = async (payload) => {
    const token = getToken();
    if (!token) return;

    const defaultParams = {
        status: 0,
        page: 1,
        pageSize: 20,
        search: ''
    };

    const params = typeof payload === 'object' && payload !== null
        ? {...defaultParams, ...payload}
        : {...defaultParams, status: payload ?? defaultParams.status};

    return await axios.get(`${apiUrl}/user/client/`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        params,
        timeout: 20000
    });
};

