import {Line} from "react-chartjs-2";
import {
    CategoryScale,
    Chart as ChartJS,
    Legend,
    LineElement,
    LinearScale,
    PointElement,
    Tooltip
} from "chart.js";
import ChartDataLabels from "chartjs-plugin-datalabels";
import {formatMetricValue} from "./retentionConfig";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend, ChartDataLabels);

const AXIS_TICK_COLOR = "rgba(15, 23, 42, 0.78)";
const GRID_COLOR = "rgba(15, 23, 42, 0.14)";
const PRIMARY_COLOR = "#0d8de8";

const RetentionLineChart = ({buckets = [], metric, locale}) => {
    const labels = buckets.map((bucket) => bucket.label);
    const values = buckets.map((bucket) => bucket.value);

    const data = {
        labels,
        datasets: [
            {
                data: values,
                borderColor: PRIMARY_COLOR,
                backgroundColor: "transparent",
                borderWidth: 3,
                pointBackgroundColor: PRIMARY_COLOR,
                pointBorderColor: PRIMARY_COLOR,
                pointBorderWidth: 2,
                pointRadius: 0,
                pointHoverRadius: 4,
                pointHoverBorderWidth: 2,
                pointHitRadius: 16,
                fill: false,
                tension: 0
            }
        ]
    };

    const options = {
        responsive: true,
        maintainAspectRatio: false,
        interaction: {
            mode: "index",
            intersect: false
        },
        layout: {
            padding: {
                top: 18,
                right: 8,
                bottom: 4,
                left: 4
            }
        },
        plugins: {
            legend: {
                display: false
            },
            datalabels: {
                display: true,
                formatter: (value) => formatMetricValue(metric, value, locale),
                align: (context) => Number(context.dataset.data?.[context.dataIndex] || 0) >= 0 ? "top" : "bottom",
                anchor: "end",
                offset: 6,
                clamp: true,
                clip: false,
                color: PRIMARY_COLOR,
                backgroundColor: null,
                borderRadius: 0,
                padding: 0,
                textStrokeColor: "rgba(255, 255, 255, 0.98)",
                textStrokeWidth: 4,
                font: {
                    size: 11,
                    weight: "500"
                }
            },
            tooltip: {
                displayColors: false,
                backgroundColor: "#ffffff",
                titleColor: "#0f172a",
                bodyColor: "#0f172a",
                borderColor: "rgba(15, 23, 42, 0.12)",
                borderWidth: 1,
                cornerRadius: 8,
                padding: 10,
                caretSize: 6,
                callbacks: {
                    label: (context) => formatMetricValue(metric, context.parsed.y, locale)
                }
            }
        },
        scales: {
            x: {
                grid: {
                    display: false,
                    drawTicks: false
                },
                border: {
                    display: false
                },
                ticks: {
                    color: AXIS_TICK_COLOR,
                    padding: 10,
                    font: {
                        size: 11,
                        weight: "500"
                    }
                }
            },
            y: {
                beginAtZero: true,
                border: {
                    display: false
                },
                grid: {
                    color: GRID_COLOR,
                    drawTicks: false
                },
                ticks: {
                    precision: 0,
                    maxTicksLimit: 5,
                    color: AXIS_TICK_COLOR,
                    padding: 8,
                    font: {
                        size: 11,
                        weight: "500"
                    }
                }
            }
        }
    };

    return (
        <div style={{height: "280px"}}>
            <Line data={data} options={options}/>
        </div>
    );
};

export default RetentionLineChart;
