import {useDispatch, useSelector} from "react-redux";
import {selectBalanceIsLoading, selectSeller, selectWalletRequest, selectWalletRequestLoading} from "../../store/wallet/walletSelector";
import {useEffect, useState} from "react";
import {fetchBalance, fetchSeller, fetchWalletRequest} from "../../store/wallet/walletReducer";
import LoadingBlock from "../loader/LoadingBlock";
import Modal from "react-bootstrap/Modal";
import {selectLoading, selectPaymentCountry} from "../../store/user/userSelector";
import {getPaymentCountry} from "../../store/user/userReducer";
import CardListItem from "../card/CardListItem";
import WalletDeniedCard from "../wallet/WalletDeniedCard";
import WalletStatus from "../wallet/WalletStatus";
import WalletSalesPageModalCard from "../wallet/WalletSalesPageModalCard";
import {handleFriendInvite, mfitUrl} from "../../utils/handlers/handler";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import CardButtonLgRounded from "../card/CardButtonLgRounded";
import {useNavigate} from "react-router-dom";
import RoundedIcon from "../rounded-icon/RoundedIcon";

const UserFinances = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const loadingBalance = useSelector(selectBalanceIsLoading);
    const loadingWalletRequest = useSelector(selectWalletRequestLoading)
    const seller = useSelector(selectSeller)
    const walletRequest = useSelector(selectWalletRequest)
    const userPaymentCountry = useSelector(selectPaymentCountry);
    const userLoading = useSelector(selectLoading)
    const [openDenied, setOpenDenied] = useState(false);
    const [openSalesPageModal, setOpenSalesPageModal] = useState(false);
    useComponentTranslations('user', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const blockedWallet =  walletRequest?.status === 10 || walletRequest?.status === 9


    const handlePersonalFinances = `/user/personal-finances`;

    const handlePlanManagerClick = `${mfitUrl}/index?acao=meusPlanos&tipo=1&goBackToNewAppFinances=true`;

    const handleSalesPageClickUrl = `${mfitUrl}/index?acao=salesPage&tipo=1&goBackToNewAppFinances=true`;

    const handleSalesPageModal = () => {
        setOpenSalesPageModal(prev => !prev)
    }

    const handleDeniedWalletClick = () => {
        setOpenDenied(prev => !prev)
    }

    useEffect(() => {
        if (userPaymentCountry === null) {
            dispatch(getPaymentCountry())
        }
    }, [userPaymentCountry, dispatch])

    useEffect(() => {
        dispatch(fetchWalletRequest())
    }, [dispatch]);

    useEffect(() => {
        if (walletRequest)
            dispatch(fetchSeller())
    }, [walletRequest, dispatch])

    useEffect(() => {
        if (seller && seller.status === "enabled")
            dispatch(fetchBalance());
    }, [dispatch, seller])

    return (
        <div className={'row pt-3'}>
            {
                (loadingWalletRequest || userLoading) &&
                <LoadingBlock/>
            }
            {
                (!loadingWalletRequest && !userLoading && (userPaymentCountry?.country === "BRA" || walletRequest || seller?.status === "enabled")) &&
                <>
                    <div className={'col-12'}>
                        <div className={'card card-body border-0'}>
                            <div className={'row  justify-content-between'}>
                                <div className={"col-10"}>
                                     <div className={"row"}>
                                         <div className={'col-2 text-center   align-self-center'}>
                                             <RoundedIcon icon={"fa-wallet"} bgColor={"bg-info-light"} size={"xs"}/>
                                         </div>
                                         <div className={'col-8 ps-0 align-self-center '}>
                                             <span className={'fw-semibold'}>{t("user:mfitWallet")}</span>
                                         </div>
                                     </div>
                                </div>
                                {
                                    (blockedWallet) &&
                                    <>
                                        <div className={'col-2 clickable-element align-self-center text-center'} onClick={handleDeniedWalletClick}>
                                            {
                                                openDenied ?
                                                    <i className={'fa-regular fa-chevron-up  '}></i> :
                                                    <i className={'fa-regular fa-chevron-down  '}></i>
                                            }
                                        </div>
                                        {
                                            openDenied &&
                                            <WalletDeniedCard status={walletRequest?.status}/>
                                        }
                                    </>
                                }
                            </div>
                            {
                                !loadingBalance && !blockedWallet &&
                                <WalletStatus walletRequest={walletRequest} loading={loadingBalance}/>
                            }
                            {
                                loadingBalance &&
                                <div className={'row pt-2'}>
                                    <div className={'card card-body border-0'}>
                                        <LoadingBlock height={"150px"}/>
                                    </div>
                                </div>
                            }
                        </div>
                    </div>
                    <div className={'col-12 pt-3'}>
                        <div className={' card card-body border-0 h-100 '}>
                            <div className={'row justify-content-evenly align-items-stretch'}>
                                {
                                    !blockedWallet &&
                                    <CardButtonLgRounded
                                        col={"col-6"}
                                        pe={"pe-1"}
                                        icon={"fa-globe-pointer"}
                                        text={t("user:yourSalesPages")}
                                        handleClick={walletRequest?.status === 5 ? undefined : handleSalesPageModal}
                                        to={walletRequest?.status === 5 && handleSalesPageClickUrl}
                                    />
                                }
                                <CardButtonLgRounded
                                    col={"col-6"}
                                    pe={`${blockedWallet ? "pt-2 pe-1" : "ps-1"}`}
                                    icon={"fa-money-check-dollar-pen"}
                                    text={t("user:planManager")}
                                    to={handlePlanManagerClick}
                                />
                                <CardButtonLgRounded
                                    col={"col-6"}
                                    pe={`${blockedWallet? "pt-2 ps-1" : " pt-2 pe-1"}`}
                                    icon={"fa-user-group"}
                                    text={t("user:inviteAFriend")}
                                    handleClick={() => handleFriendInvite(navigate)}
                                />
                                <CardButtonLgRounded
                                    col={`${!blockedWallet? 'col-6' : 'col-12'}`}
                                    ps={`${!blockedWallet && 'ps-1'} pt-2`}
                                    icon={"fa-chart-line-up"}
                                    text={t("user:personalFinances")}
                                    to={handlePersonalFinances}
                                />
                            </div>
                        </div>
                    </div>
                </>
            }
            {
                (userPaymentCountry?.country !== "BRA" && !seller) &&
                <div className={'col-12'}>
                    <CardListItem
                        icon={"fa-chart-line-up"}
                        text={t("user:personalFinances")}
                        to={handlePersonalFinances}
                    />
                </div>
            }
            <Modal centered onHide={handleSalesPageModal} show={openSalesPageModal}>
                <Modal.Body>
                    <WalletSalesPageModalCard walletRequest={walletRequest} handleClose={handleSalesPageModal}/>
                </Modal.Body>
            </Modal>
        </div>
    );
}

export default UserFinances;
