import {Line} from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    Legend,
    Tooltip,
    Title,
    PointElement,
    LineElement,
    Filler
} from 'chart.js';
import moment from "moment/moment";


const WorkoutProgressChart = ({wp}) => {
    ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend, Title, PointElement, LineElement, Filler);

    function getChartData(item) {
        const labels = item.dataView.map((entry) =>
            moment({
                year: entry.data.year,
                month: entry.data.month - 1,
                day: entry.data.day
            }).format('DD/MM')
        );

        const datasets = [];
        const maxCargas = getMaxCargas(item.dataView);

        if (maxCargas === 1) {
            const values = item.dataView.map((entry) => entry.cargas[0]);

            datasets.push({
                label: 'Kg',
                data: values,
                fill: false,
                backgroundColor: 'rgba(0, 0, 0, 0)',
                borderColor: '#0070B6',
                pointBackgroundColor: '#0070B6',
                pointRadius: 4
            });
        } else {
            const colors = generateColors(maxCargas);
            for (let i = 0; i < maxCargas; i++) {
                const values = item.dataView.map((entry) => entry.cargas[i]);
                const borderColor = colors[i];

                datasets.push({
                    label: `Carga ${i + 1}`,
                    data: values,
                    fill: false,
                    backgroundColor: 'rgba(0, 0, 0, 0)',
                    borderColor: borderColor,
                    pointBackgroundColor: borderColor,
                    pointRadius: 4
                });
            }
        }

        return {
            labels: labels,
            datasets: datasets,
        };
    }
    function generateColors(numColors) {
        const colors = [];

        for (let i = 0; i < numColors; i++) {
            colors.push(getRandomColor());
        }

        return colors;
    }

    function getRandomColor() {
        const blue = Math.floor(Math.random() * 256);
        const red = Math.floor(Math.random() * 256);
        const green = Math.floor(Math.random() * 256);

        return `rgba(${red}, ${green}, ${blue}, 1)`;
    }
    function getMaxCargas(dataView) {
        let maxCargas = 0;

        dataView.forEach((entry) => {
            if (entry.cargas.length > maxCargas) {
                maxCargas = entry.cargas.length;
            }
        });

        return maxCargas;
    }
    function getChartOptions(item) {
        const minCarga = Math.min(...item.dataView.map((entry) => entry.cargas[0])) * 0.9;
        const maxCarga = Math.max(...item.dataView.map((entry) => entry.cargas[0]));

        return {
            responsive: true,
            aspectRatio: 1,
            plugins: {
                legend: {
                    position: 'top',
                },
                title: {
                    display: true,
                    text: item.exerciseName.split("<br/>"),
                    font: {
                        size: 14,
                        family: "'Open Sans', sans-serif",
                        weight: 'bold',
                    },
                    padding: {
                        top: 5,
                    },
                },

            },
            scales: {
                y: {
                    suggestedMin: minCarga,
                    suggestedMax: maxCarga,
                    maxTicksLimit: 5,

                },
            },
        };
    }
    return (

        <Line data={getChartData(wp)} options={getChartOptions(wp)} />
    )
}
export default WorkoutProgressChart;