import OnlineEvaluationScheduledCard from "./OnlineEvaluationScheduledCard";
import EmptySet from "../empty-set/EmptySet";
import React, {useState} from "react";
import {useSelector} from "react-redux";
import {getScheduledEvaluations} from "../../store/online-evaluation/evaluationOnlineSelector";
import {useTranslation} from "react-i18next";
import {selectSelectedClient} from "../../store/client/clientSelector";
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import OnlineEvaluationSendModal from "./OnlineEvaluationSendModal";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const OnlineEvaluationScheduled = ({id}) => {
    const {t} = useTranslation();
    const selectedClient = useSelector(selectSelectedClient);
    const scheduledEvaluations = useSelector(getScheduledEvaluations);
    const [showEvaluationSendModal, setShowEvaluationSendModal] = useState(false);
    useComponentTranslations('evaluationOnlineComponents', {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT
    });

    const handleShowSendEvaluationModal = () => {
        setShowEvaluationSendModal(prevState => !prevState);
    };

    return (
        <div className={"card card-body border-0 mt-2"}>
            {Array.isArray(scheduledEvaluations) && scheduledEvaluations.length > 0 ? (
                scheduledEvaluations.map((evaluation) => (
                    <OnlineEvaluationScheduledCard
                        key={evaluation.id}
                        scheduledEvaluation={evaluation}
                        client={selectedClient}
                    />
                ))
            ) : scheduledEvaluations ? (
                <OnlineEvaluationScheduledCard
                    scheduledEvaluation={scheduledEvaluations}
                    client={selectedClient}
                />
            ) : (
                <>
                    <EmptySet
                        icon={"fa-regular fa-clipboard"}
                        message={t("evaluationOnlineComponents:noScheduleEvaluation")}
                    />
                    <button
                        className={"btn btn-primary w-100"}
                        onClick={handleShowSendEvaluationModal}
                    >
                        {t("evaluationOnlineComponents:createRecurrence")}
                    </button>
                </>
            )}
            <Modal show={showEvaluationSendModal} onHide={handleShowSendEvaluationModal} centered>
                <ModalBody>
                    <OnlineEvaluationSendModal
                        onClose={handleShowSendEvaluationModal}
                        clientId={id}
                    />
                </ModalBody>
            </Modal>
        </div>
    )
}

export default OnlineEvaluationScheduled