import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchUnreadUpdatesCountAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/updates/count`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

export const fetchUnreadUpdatesByTypeCountAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/updates/count-type`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

export const fetchAllUpdatesByTypeCountAPI = async ({type, status, startDate, endDate}) => {
    const token = getToken();
    if (!token) return;
    const params = new URLSearchParams();
    params.set("type", type);
    params.set("status", status);
    if (startDate) {
        params.set("startDate", startDate);
    }
    if (endDate) {
        params.set("endDate", endDate);
    }
    return await axios.get(`${apiUrl}/user/updates/all?${params.toString()}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

export const resolveUpdateAPI = async (id) => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/user/updates/resolve?id=${id}`, {}, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

export const resolveAllUpdatesAPI = async ({type, updateIds}) => {
    const token = getToken();
    if (!token) return;
    const headers = {
        'Content-Type': 'application/json',
        'authorization': token
    };

    if (Array.isArray(updateIds)) {
        return await axios.post(`${apiUrl}/user/updates/resolve-all`, {updateIds}, {
            headers,
            timeout: 20000
        });
    }

    return await axios.post(`${apiUrl}/user/updates/resolve-all?type=${type}`, {}, {
        headers,
        timeout: 20000
    });
}
