import ItemListIcon from "../list/ItemListIcon";
import {handleWhatsAppClick} from "../../utils/handlers/handler";
import {changeStatus, fetchClient, passwordReset} from "../../store/client/clientReducer";
import {addToast} from "../../store/toast/toastReducer";
import {useEffect, useState} from "react";
import {useTranslation} from "react-i18next";
import {useDispatch, useSelector} from "react-redux";
import {isPasswordReset} from "../../store/client/clientSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ClientNotificationPreferenceModal from "./ClientNotificationPreferenceModal";
import ClientLoginInformation from "./ClientLoginInformation";

const ClientOptions = ({client}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch()
    const [showLoginInfo, setShowLoginInfo] = useState(false)
    const [showNotificationPreferenceModal, setShowNotificationPreferenceModal] = useState(false)
    useComponentTranslations('client', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const passwordResetB = useSelector(isPasswordReset)

    const handleClientStatusChange = (status) => {
        const data = {
            id: client.id,
            status: status
        }
        dispatch(changeStatus(data))
        if (status === 0) {
            dispatch(addToast(
                {
                    type: "success",
                    message: `${t("client:clientActivated")}`,
                    title: `${t("client:allDone")}`
                }
            ))
        } else if (status === 1) {
            dispatch(addToast(
                {
                    type: "warning",
                    message: `${t("client:clientDisabled")}`,
                    title: `${t("client:allDone")}`
                }
            ))
        }
    }

    const handleNotificationPreferenceModal = () => {
        setShowNotificationPreferenceModal(prevState => !prevState)
    }

    const handleShowLoginInfo = () => {
        setShowLoginInfo(prevState => !prevState)
    }

    const handleEditClientClick = `/user/client/edit/${client.id}`


    useEffect(() => {
        if (passwordResetB && client?.id) {
            dispatch(passwordReset(false))
            dispatch(fetchClient(client.id))
        }
    }, [client, dispatch, passwordResetB])

    return (
        <div className={"card card-body mt-3 border-0"}>
            <div className={'row  '}>
                <div className={'col-12'}>
                    <ItemListIcon icon={"fa-brands fa-whatsapp"} size={"sm"} handler={() => handleWhatsAppClick(`${client.telefone}`)}
                                  text={t("client:talkTo")}/>
                    <ItemListIcon icon={"fa-info"} size={"sm"} handler={handleShowLoginInfo} text={t("client:loginInfo")}/>
                    <ItemListIcon icon={"fa-bell-on"} size={"sm"} handler={handleNotificationPreferenceModal} text={t("client:notificationPreference")}/>
                    <ItemListIcon icon={"fa-pencil"} size={"sm"} to={handleEditClientClick} text={t("client:clientEditTitle")}/>
                </div>
            </div>
            <div className={'row pt-2'}>
                <div className={'col-12'}>
                    <div className={'d-grid mt-2'}>
                        {
                            client.status === 1 &&
                            <button className={'btn btn-outline-primary'}
                                    onClick={() => handleClientStatusChange(0)}>{t("clientComponent:activateClient")}</button>
                        }
                        {
                            client.status === 0 &&
                            <button className={'btn btn-outline-primary'}
                                    onClick={() => handleClientStatusChange(1)}>{t("clientComponent:inactivateClient")}</button>
                        }
                    </div>
                    <div className={'d-grid mt-2'}>
                        <button className={'btn btn-outline-danger'}
                                onClick={() => handleClientStatusChange(2)}>{t("clientComponent:deleteClient")}</button>
                    </div>
                </div>
            </div>
            {
                showLoginInfo &&
                <ClientLoginInformation showLoginInfo={showLoginInfo} handleShowLoginInfo={handleShowLoginInfo} client={client}/>
            }
            {
                showNotificationPreferenceModal &&
                <ClientNotificationPreferenceModal client={client} handleNotificationPreferenceModal={handleNotificationPreferenceModal}
                                                   show={showNotificationPreferenceModal}/>
            }
        </div>
    )
}
export default ClientOptions;