import Page from "../../components/page/Page";
import {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {createCategory, getAllCategories} from "../../store/personal-finances/personalFinancesReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import {
    selectFinancesCategories,
    selectPersonalFinancesLoading
} from "../../store/personal-finances/personalFinancesSelector";
import PersonalFinancesCategories from "../../components/personal-finances/PersonalFinancesCategories";
import {ModalBody} from "react-bootstrap";
import {ErrorMessage, Field, Form, Formik} from "formik";
import Modal from "react-bootstrap/Modal";
import * as Yup from "yup";

const CategoriesPersonalFinances = () => {
    const { t } = useTranslation();
    const dispatch = useDispatch();
    const categories = useSelector(selectFinancesCategories);
    const loading = useSelector(selectPersonalFinancesLoading);
    const [showCreateCategory, setShowCreateCategory] = useState(false);
    useComponentTranslations('personalFinances', {"en-US":enUS, "es-ES":esES, "pt-PT":ptPT, "pt-BR":ptBR})

    const initialValues = {name: ''};
    const validationSchema = Yup.object({
        name: Yup.string()
            .required(t("personalFinancesComponent:nameRequired"))
            .test('unique',t("personalFinances:categoryExists"), function (value) {
                if (!value) return true;
                return !categories.some(category => category.name?.toLowerCase() === value.toLowerCase());
            })

    })

    const onSubmit = (name) => {
        dispatch(createCategory(name));
        setShowCreateCategory(prevState => !prevState);
    };

    useEffect(() => {
        dispatch(getAllCategories());
    }, [dispatch]);

    const handleCreateCategory = () => {
        setShowCreateCategory(prevState => !prevState);
    };

    return (
        <Page title={t("personalFinances:categories")} loading={loading}>
            <div className={"card card-body border-0 mt-n2"}>
                <div className={"col-12"}>
                    <CardButtonAdd text={t("personalFinances:addCategory")} handleClick={handleCreateCategory}/>
                </div>
                <div className={"col-12 mt-3"}>
                    <ul className={"list-unstyled"}>
                        {categories?.map((category) => (
                            <PersonalFinancesCategories
                                key={category.id}
                                category={category}
                            />
                        ))}
                    </ul>
                </div>
            </div>
            <Modal show={showCreateCategory} centered onHide={handleCreateCategory}>
                <ModalBody>
                    <div className={"row justify-content-between"}>
                        <div className={"col-auto"}>
                            <span className={"fw-semibold fs-5"}>{t("personalFinancesComponent:newCategory")}</span>
                        </div>
                        <div className={"col-12 mt-3"}>
                            <Formik initialValues={initialValues}
                                    onSubmit={onSubmit}
                                    validationSchema={validationSchema}
                            >
                                {(formik) => (
                                    <Form>
                                        <Field type={"hidden"} id={"id"} name={"id"}/>
                                        <div className={"mb-3"}>
                                            <label htmlFor="name" className={"form-label fw-semibold"}>
                                                {t("personalFinancesComponent:categoryName")}
                                            </label>
                                            <Field
                                                type={"text"}
                                                id={"name"}
                                                name={"name"}
                                                className={`form-control ${formik.errors.name && formik.touched.name ? "is-invalid" :""}`}
                                            />
                                            <ErrorMessage name={"name"}>
                                                {(msg) => <div className={"invalid-feedback"}>{msg}</div>}
                                            </ErrorMessage>
                                        </div>
                                        <div className={"d-grid"}>
                                            <button type={"submit"} className={"btn btn-primary"}>
                                                {t("personalFinancesComponent:save")}
                                            </button>
                                            <button className={"btn btn-outline-primary mt-2"} onClick={handleCreateCategory}>
                                                {t("personalFinancesComponent:close")}
                                            </button>
                                        </div>
                                    </Form>
                                )
                                }
                            </Formik>
                        </div>
                    </div>
                </ModalBody>
            </Modal>
        </Page>
    )
}

export default CategoriesPersonalFinances;