import WorkoutVideo from "../../workout-session/WorkoutVideo";
import WorkoutYoutube from "../../workout-session/WorkoutYoutube";
import WorkoutImage from "../../workout-session/WorkoutImage";
import WorkoutVideoLegacy from "../../workout-session/WorkoutVideoLegacy";

const ExercisePlayerType = ({exercise, showSeries}) => {

    switch (exercise.mediaType) {
        case 0:
            return (<WorkoutYoutube exercise={exercise} showSeries={showSeries}/>)
        case 1:
            return (<WorkoutImage exercise={exercise} showSeries={showSeries}/>)
        case 3:
            return (<WorkoutVideo exercise={exercise} showSeries={showSeries}/>)
        case 4:
            return(<WorkoutVideoLegacy exercise={exercise} showSeries={showSeries}/> );
        default:
            return "";

    }
}
export default ExercisePlayerType;