import {apiUrl as url, getToken} from "../api";
import axios from "axios";

const apiUrl = url + "/v3";

export const getAllPacesAPI = async (id) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/aerobic/pace?id=${id}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    });
}

