import {useDispatch, useSelector} from "react-redux";
import {
    selectCreateSucceeded,
    selectFinancesCategories,
    selectPersonalFinancesLoading
} from "../../store/personal-finances/personalFinancesSelector";
import {
    getAllCategories,
    getFinance,
    resetCreateSucceeded
} from "../../store/personal-finances/personalFinancesReducer";
import {useEffect} from "react";
import {useNavigate} from "react-router-dom";
import PersonalFinancesForm from "./PersonalFinancesForm";

const CreatePersonalFinances = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const loading = useSelector(selectPersonalFinancesLoading);
    const categories = useSelector(selectFinancesCategories);
    const createSucceeded = useSelector(selectCreateSucceeded);

    const handleSubmit = (values) => {
        const payload = {
            tipoConta: values.tipo === 'receita' ? 0 : 1,
            dataFatura: values.dataVencimento,
            dataPagamento: values.jaPago === 'sim' ? values.quando : null,
            pago: values.jaPago === 'sim' ? 1 : 0,
            valor: Number(values.valor),
            categoria: Number(values.categoria),
            descricao: values.descricao,
            referencia: values.pagoPara,
            observacao: values.observacoes
        };
        dispatch(getFinance(payload));
    }

    useEffect(() => {
        dispatch(getAllCategories());
    }, [dispatch]);

    useEffect(() => {
        if (createSucceeded) {
            navigate("/user/personal-finances");
            dispatch(resetCreateSucceeded());
        }
    }, [createSucceeded, navigate, dispatch]);

    return (
        <PersonalFinancesForm
            financeToEdit={null}
            categories={categories}
            loading={loading}
            onSubmit={handleSubmit}
        />
    )
}

export default CreatePersonalFinances;