import {apiUrl, getToken} from "../api";
import axios from "axios";


export const getAllWorkoutsRoutinesByStatusAPI = async (id, status) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/workout/routine/all?id=${id}&status=${status}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    });
}

