import React from "react";
import {useSortable} from "@dnd-kit/sortable";
import WorkoutPrescriptionExerciseListItem from "./WorkoutPrescriptionExerciseListItem";

const SortableWorkoutExerciseCard = ({
                                         id,
                                         exerciseArray,
                                         expanded,
                                         onToggleExpand,
                                         exercises,
                                         selected,
                                         toggleSelect,
                                         deselect,
                                     }) => {
    const {attributes, listeners, setNodeRef, transform, transition} = useSortable({id, animateLayoutChanges: () => false});

    const x = transform?.x ?? 0;
    const y = transform?.y ?? 0;

    const style = {
        transform: `translate3d(${x}px, ${y}px, 0)`,
        transition: transition,
        marginBottom: '0.5rem',
        touchAction: 'pan-y'
    };

    return (
        <div ref={setNodeRef} style={style}  {...attributes} className={"draggable-item"}>
            <div className={"card card-body p-0 m-0 border-0"}>
                <div className={"row  "}>
                    <div
                        className="col-1 align-self-center text-center    "
                        {...listeners}
                        style={{cursor: 'grab', touchAction: 'none'}}
                    >
                        <i className="fa-regular small fa-bars"/>
                    </div>
                    <div className={"col-11"}>
                        <WorkoutPrescriptionExerciseListItem
                            selected={selected}
                            toggleSelect={toggleSelect}
                            deselect={deselect}
                            exerciseArray={exerciseArray}
                            expanded={expanded}
                            onToggleExpand={onToggleExpand}
                            exercises={exercises}
                        />
                    </div>
                </div>
            </div>
            <hr className={"border-primary-subtle"}/>
        </div>
    )
}

export default SortableWorkoutExerciseCard;
