import {useEffect} from "react";
import {useDispatch, useSelector} from "react-redux";
import {selectPaymentCountry, selectUser} from "../../store/user/userSelector";
import {useNavigate} from "react-router-dom";
import {useLogout} from "../../utils/logout/logout";
import {handleCalendarClick, handleMfitPointsClick, handlePartnerClick, handleSubscriptionButton} from "../../utils/handlers/handler";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/user/locales/en-us.json";
import ptBR from "../../pages/user/locales/pt-br.json";
import esES from "../../pages/user/locales/es-es.json";
import ptPT from "../../pages/user/locales/pt-pt.json";
import {Offcanvas, OffcanvasBody} from "react-bootstrap";
import {ReactComponent as Logo} from '../../assets/img/logo/logo-horizontal.svg';
import Avatar from "../avatar/Avatar";
import UserMenuItem from "./UserMenuItem";
import {toggleUserMenu} from "../../store/menu/menuReducer";
import {userMenuSelector} from "../../store/menu/menuSelector";
import {getPaymentCountry} from "../../store/user/userReducer";
import {canUseSpointByCountry} from "../../utils/spoint/spointAccess";

const UserMenu = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const user = useSelector(selectUser)
    const userPaymentCountry = useSelector(selectPaymentCountry);
    const userMenu = useSelector(userMenuSelector);
    const {logout} = useLogout();
    const showMfitPointsMenuItem = canUseSpointByCountry(userPaymentCountry) && userPaymentCountry !== null;
    useComponentTranslations('navbar', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleUserMenu = () => {
        dispatch(toggleUserMenu(!userMenu))
    };

    const handleLogoutClick = () => {
        logout()
    };

    const handleSubscriptionClick = () => {
        handleUserMenu();
        setTimeout(() => {
            handleSubscriptionButton(navigate)
        }, 300);
    };

    const handleEditProfileClick = () => {
        handleUserMenu();
        setTimeout(() => {
            navigate("/user/profile");
        }, 300);
    };

    const goToFriendInvite = () => {
        handleUserMenu();
        setTimeout(() => {
            navigate("/user/friend-invite");
        }, 300);
    };

    const handleOpenMfitPoints = () => {
        handleUserMenu();
        setTimeout(() => {
            handleMfitPointsClick();
        }, 300);
    };

    useEffect(() => {
        if (userPaymentCountry === null) {
            dispatch(getPaymentCountry())
        }
    }, [dispatch, userPaymentCountry]);

    return (
        <Offcanvas show={userMenu} onHide={handleUserMenu} placement={"end"}>
            <OffcanvasBody className={"position-relative"}>
                <div className="row justify-content-center pt-2">
                    <div className="col-auto">
                        <Logo className={'text-default-darker'} style={{height: '33px'}}/>
                    </div>
                </div>
                <div className={'row justify-content-start pt-4'}>
                    <div className={'col-auto clickable-element'} onClick={handleUserMenu}>
                        <span className={"text-xs"}><i
                            className={'fa-regular fa-chevron-left'}/> {t("navbar:goBack")}</span>
                    </div>
                </div>
                <div className={"text-center"}>
                    <Avatar maxWidth={"110px"} url={user.urlLogo} blueBorder={true} padding={"pb-3"}/>
                </div>
                <div className={"text-center mb-4"}>
                    <span className={"fw-semibold text-title"}>{user.nome} {user.sobrenome}</span>
                </div>
                <div className={"card card-body border-0"}>
                    <div className={'row'}>
                        <div className={'col-12'}>
                            <UserMenuItem size={"sm"} icon={"fa-pencil"} text={t("navbar:editProfile")}
                                          handler={handleEditProfileClick}/>
                            <UserMenuItem size={"sm"} icon={"fa-dollar-circle"} text={t("navbar:subscription")}
                                          handler={handleSubscriptionClick}/>
                            <UserMenuItem size={"sm"} icon={"fa-calendar-clock"} text={t("navbar:schedule")}
                                          handler={handleCalendarClick}/>
                            <UserMenuItem size={"sm"} icon={"fa-user-group"} text={t("navbar:inviteFriend")}
                                          handler={goToFriendInvite}/>
                            <UserMenuItem size={"sm"} icon={"fa-handshake"} text={t("navbar:partners")}
                                          handler={handlePartnerClick} last={!showMfitPointsMenuItem}/>
                            {
                                showMfitPointsMenuItem &&
                                <UserMenuItem
                                    size={"sm"}
                                    icon={"fa-pontos-mfit"}
                                    text={t("navbar:mfitPoints")}
                                    handler={handleOpenMfitPoints}
                                    kit={true}
                                    last={true}
                                />
                            }
                        </div>
                    </div>
                </div>
                <div className={'row mt-4'}>
                    <div className={'col-12'}>
                        <button className="btn btn-primary w-100" onClick={handleLogoutClick}>
                            {t("navbar:exit")}
                        </button>
                    </div>
                </div>
            </OffcanvasBody>
        </Offcanvas>
    )
}
export default UserMenu;
