import {isDesktop} from "react-device-detect";
import React from "react";

const EvaluationCompareBarComponent = ({
                        selectedCount,
                        maxSelection,
                        onCompare,
                        onClose,
                        compareLabel,
                        selectLabel,
                        xs = "12",
                        md = "6",
                        lg = "6",
                        xl = "4",
                        mt = "mt-n4-5"
                    }) => {
    const bottomOffset = isDesktop ? '12px' : '82px';

    return (
        <div className={"fixed-bottom"}>
            <div className={"container-fluid"}>
                <div className={"row justify-content-center"}>
                    <div className={`col-${xs} col-md-${md} col-lg-${lg} col-xl-${xl} ${mt}`}>
                        <div className={"bg-secondary-subtle card card-body border-0"}
                             style={{
                                 bottom: bottomOffset,
                                 zIndex: 1100
                             }}
                        >
                            <div className={"d-flex justify-content-between align-items-center"}>
                                <div>
                                    <span className={"me-1"}>{selectLabel}</span>
                                    <span
                                        className={"fw-semibold"}>{selectedCount}/{maxSelection}</span>
                                </div>
                                <div>
                                    <button className={"btn btn-primary"}
                                            disabled={selectedCount === 0}
                                            onClick={onCompare}>
                                        {compareLabel}
                                    </button>
                                    <button className={"btn btn-link fw-semibold text-end"}
                                            onClick={onClose}>
                                        <i className={"fa-regular fa-xmark"}/>
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default EvaluationCompareBarComponent;