import {takeLatest, all, call, put} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    getAllByTypeClientAPI,
    saveTestAPI,
    deleteTestAPI,
    updateTestAPI
} from "../../api/neuromotors/neuromotorsAction";
import {
    getAllTests,
    setAllTests,
    createTest,
    deleteTest,
    testDeleted,
    updateTest,
    onError, testSaved, setTestDeleted
} from "./neuromotorsReducer";

export function* fetchTestsByTypeAsync(action) {
    try {
        const {type, clientId} = action.payload;
        const response = yield call(getAllByTypeClientAPI, type, clientId);
        yield put(setAllTests(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchTestsByType() {
    yield takeLatest(getAllTests.type, fetchTestsByTypeAsync);
}

export function* createTestAsync(action) {
    try {
        const {teste} = action.payload;
        yield call(saveTestAPI, teste, action.payload);
        yield put(testSaved(true));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreateTest() {
    yield takeLatest(createTest.type, createTestAsync);
}

export function* updateTestAsync(action) {
    try {
        const {teste} = action.payload;
        yield call(updateTestAPI, teste, action.payload);
        yield put(testSaved(true));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onUpdateTest() {
    yield takeLatest(updateTest.type, updateTestAsync);
}

export function* deleteTestAsync(action) {
    try {
        const {type, id} = action.payload;
        yield call(deleteTestAPI, type, id);
        yield put(testDeleted(action.payload));
        yield put(setTestDeleted(true));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onDeleteTest() {
    yield takeLatest(deleteTest.type, deleteTestAsync)
}

export function* neuromotorsSaga() {
    yield all([
        call(onFetchTestsByType),
        call(onCreateTest),
        call(onUpdateTest),
        call(onDeleteTest)
    ])
}