import RoundedIcon from "../rounded-icon/RoundedIcon";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {apiUrl} from "../../api/api";
import Modal from "react-bootstrap/Modal";
import React, {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {selectWorkoutRoutine} from "../../store/workout-routine/workoutRoutineSelector";
import {fetchWorkoutRoutine} from "../../store/workout-routine/workoutRoutineReducer";
import {addToast} from "../../store/toast/toastReducer";
import Spinner from "../loader/Spinner";
import ShareComponent from "../utils/share/ShareComponent";
import {handleSendWhatsApp} from "../../utils/handlers/handler";
import {selectSelectedClient} from "../../store/client/clientSelector";

const WorkoutSessionOptionCard = ({sessionId, clientId, id, handleShowIaModal}) => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const [includeImages, setIncludeImages] = useState(true);
    const [showDownload, setShowDownload] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);
    const [isGeneratingAll, setIsGeneratingAll] = useState(false);
    const workout = useSelector(selectWorkoutRoutine);
    const [downloadUrl, setDownloadUrl] = useState(null)
    const client = useSelector(selectSelectedClient)
    const show4 = Number(clientId) > 0;
    useComponentTranslations('workoutPrescriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});


    const handleCopyLink = () => {
        navigator.clipboard.writeText(downloadUrl)
            .then(() => dispatch(addToast(
                {
                    type: "success",
                    message: t("workoutPrescriptionComponent:copiedLinkTitle"),
                    title: t("workoutPrescriptionComponent:copiedLinkMessage")
                }
            )))
            .catch(err => console.error(err));

    }

    const handleSendWhatsAppLink = () => {
        const whatsappMessage = `${t("workoutPrescriptionComponent:workoutReadyWhatsAppMessage")} ${downloadUrl}`;
        handleSendWhatsApp(clientId > 0 ? client.telefone : null, whatsappMessage);
    }

    const handleClose = () => {
        setDownloadUrl(null)
        handleShowDownload()
    }

    const handleShowDownload = () => {
        if (!isGenerating && !isGeneratingAll)
            setShowDownload(prev => !prev)
    };

    const fetchPdfUrl = async (sessionIds) => {
        const response = await fetch(`${apiUrl}/workout-pdf/`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            timeout: 30000,
            body: JSON.stringify({
                id,
                sessionIds,
                clientId,
                showImages: includeImages
            })
        });
        if (!response.ok) throw new Error('Erro ao gerar PDF');
        const text = await response.text();
        try {
            const data = JSON.parse(text);
            return data.url || text;
        } catch (e) {
            return text;
        }
    };

    const dispatchPdfError = () => {
        dispatch(addToast({
            type: "danger",
            message: t("workoutPrescriptionComponent:pdfErrorMessage"),
            title: t("workoutPrescriptionComponent:pdfErrorTitle")
        }))

    }
    const handleGeneratePDF = async () => {
        setIsGenerating(true);
        try {
            const url = await fetchPdfUrl([sessionId]);
            setDownloadUrl(url);
        } catch (error) {
            dispatchPdfError();
        } finally {
            setIsGenerating(false);
        }
    };

    const handleDownloadAll = async () => {
        if (!workout?.sessions?.length) return;
        setIsGeneratingAll(true);
        try {
            const sessionIds = workout.sessions.map(sess => sess.id);
            const url = await fetchPdfUrl(sessionIds);
            setDownloadUrl(url);
        } catch (error) {
            dispatchPdfError();
        } finally {
            setIsGeneratingAll(false);
        }
    };

    const handleClientView = () => {
        navigate(`/user/session/${sessionId}`)
    };

    const handleGoToProgress = () => {
        navigate(`/user/client/${clientId}/workout/routine/${id}/session/${sessionId}/progress/true`);
    }
    useEffect(() => {
        if (!workout) dispatch(fetchWorkoutRoutine(id));
    }, [workout, id, dispatch]);

    return (
        <div className="card card-body border-0">
            <div className="row justify-content-evenly">
                <div className={`col-${show4 ? "3" : "4"} text-center ps-0 pe-0 clickable-element`} onClick={handleShowDownload}>
                    <RoundedIcon icon="fa-file-download"/>
                    <span className="d-block mt-2 " style={{lineHeight: "1.2"}}>{t("workoutPrescriptionComponent:pdfDownload")}</span>
                </div>
                <div className={`d-block col-${show4 ? "3" : "4"} text-center ps-0 pe-0 clickable-element`}
                     style={{lineHeight: "1.2"}} onClick={handleClientView}>
                    <RoundedIcon icon="fa-eye"/>
                    <span className="d-block mt-2" style={{lineHeight: "1.2"}}>{t("workoutPrescriptionComponent:clientView")}</span>
                </div>
                {
                    show4 &&
                    <div className="col-3 text-center ps-0 pe-0 clickable-element" onClick={handleGoToProgress}>
                        <RoundedIcon icon="fa-chart-mixed"/>
                        <span className="d-block mt-2" style={{lineHeight: "1.2"}}>{t("workoutPrescriptionComponent:weightEvolution")}</span>
                    </div>
                }
                <div className={`col-${show4 ? "3" : "4"} text-center ps-0 pe-0 clickable-element`} style={{lineHeight: "1.2"}} onClick={handleShowIaModal}>
                    <RoundedIcon icon="fa-mfit-ai" textColor={"text-mfit-ai"} kit={true}/>
                    <span className="d-block mt-2 text-mfit-ai " style={{lineHeight: "1.2"}}>{t("workoutPrescriptionComponent:prescribeWith")} <span className={"fw-semibold text-mfit-ai-gradient"}>MFIT</span><span className={"fw-light text-mfit-ai-gradient"}>IA</span></span>
                </div>
            </div>
            <Modal show={showDownload} centered onHide={handleShowDownload}>
                <Modal.Body>
                    {
                        (isGenerating || isGeneratingAll) && !downloadUrl &&
                        <div className={"row py-4 justify-content-center"}>
                            <div className={"col-3 col-md-2 text-center"}>
                                <Spinner/>
                            </div>
                            <div className={"col-12 text-center pt-3 "}>
                                <span className={"fs-5 fw-semibold"}>{t("workoutPrescriptionComponent:generatingPdf")}</span>
                                <span className={"d-block mt-2"}>{t("workoutPrescriptionComponent:thisCanTakeAWhile")}</span>
                            </div>
                        </div>
                    }
                    {
                        !isGenerating && !isGeneratingAll && !downloadUrl &&
                        <div className="row">
                            <div className={"col-12 mb-3"}>
                                <span className={"fw-semibold fs-5"}>{t("workoutPrescriptionComponent:exportWorkoutPDF")}</span>
                            </div>
                            <div className={"col-12 mb-3"}>
                                <div className={"card card-body border-0 bg-primary-subtle"}>
                                    <div className={"row justify-content-between"}>
                                        <div className={"col-10"}>
                                            <span className={"fw-semibold d-block"}>{t("workoutPrescriptionComponent:includeImage")}</span>
                                            <span className={"small d-block"}>{t("workoutPrescriptionComponent:includeImageWarning")}</span>
                                        </div>
                                        <div className={"col-2 col-md-auto align-self-center"}>
                                            <div className="form-check form-switch ">
                                                <input className="form-check-input" type="checkbox" role="switch" id="flexSwitchCheckChecked"
                                                       checked={includeImages}
                                                       onChange={() => setIncludeImages(v => !v)}/>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className="col-12 mb-2">
                                <div className={"row"}>
                                    <div className={"col-12"}>
                                        <div className={"card card-body bg-body "}>
                                            <span className={"fw-semibold d-block "}>
                                                {t("workoutPrescriptionComponent:currentWorkout")}
                                            </span>
                                            <span className={"d-block"}>{t("workoutPrescriptionComponent:currentWorkoutMessage")}</span>
                                            <div className={"d-grid mt-4"}>
                                                <button className="btn btn-primary" onClick={handleGeneratePDF}>
                                                    <i className={"fa-regular fa-arrow-down-to-bracket"}></i> {t("workoutPrescriptionComponent:downloadWorkoutPdf")}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className="col-12">
                                <div className={"row"}>
                                    <div className={"col-12"}>
                                        <div className={"card card-body bg-body "}>
                                            <span className={"fw-semibold d-block "}>
                                                {t("workoutPrescriptionComponent:completeWorkout")}
                                            </span>
                                            <span className={"d-block"}>{t("workoutPrescriptionComponent:completeWorkoutExport")}</span>
                                            <div className={"d-grid mt-4"}>
                                                <button className="btn btn-primary" onClick={handleDownloadAll}>
                                                    <i className={"fa-regular fa-arrow-down-to-bracket"}></i> {t("workoutPrescriptionComponent:downloadCompleteWorkoutPdf")}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className="col-12 mt-3">
                                <button className="btn btn-outline-primary w-100" onClick={handleShowDownload}>
                                    {t("workoutPrescriptionComponent:close")}
                                </button>
                            </div>
                        </div>
                    }
                    {
                        downloadUrl &&
                        <ShareComponent link={downloadUrl} handleCopyLink={handleCopyLink} handleWhatsAppLink={handleSendWhatsAppLink}
                                        handleClose={handleClose}>
                            <a className={"btn btn-default w-100 mt-2"} href={downloadUrl}> {t("workoutPrescriptionComponent:downloadPdf")}</a>
                        </ShareComponent>
                    }
                </Modal.Body>
            </Modal>
        </div>
    );
};

export default WorkoutSessionOptionCard;
