import {Outlet, useNavigate} from "react-router-dom";
import TopBar from "../components/navbar/TopBar";
import ToastComponent from "../components/toast/ToastComponent";
import {useDispatch, useSelector} from "react-redux";
import {selectUser} from "../store/user/userSelector";
import {useCallback, useEffect} from "react";
import Cookies from "js-cookie";
import {checkVersion} from "../api/version/versionCheck";
import {userVersion} from "../api/api";
import moment from "moment/moment";
import usePageVisibility from "../utils/browser/usePageVisibility";
import {useTranslation} from "react-i18next";
import {fetchUser, setDeviceInformation, setPaymentCountry, setPushId, setTimeZone, updateLoginToAc} from "../store/user/userReducer";
import LoadingPage from "../components/loader/LoadingPage";
import BottomBar from "../components/navbar/BottomBar";
import {deviceDetect, isMobile} from "react-device-detect";
import {
    checkBadPassword,
    checkPendingChargeback,
    checkPendingCsat,
    checkPermission,
    checkUserBlocked
} from "../store/check/checkReducer";
import {selectBadPassword, selectBlocked, selectPendingChargeback, selectPendingCsat, selectPermission} from "../store/check/checkSelector";
import FingerprintJS from '@fingerprintjs/fingerprintjs';
import {getMainDomain} from "../utils/cookie/cookieUtils";
import Clarity from "@microsoft/clarity";
import {useLogout} from "../utils/logout/logout";
import {getPersistableBrowserTimeZone} from "../utils/timezone/userTimeZone";
import {normalizeAppLocale} from "../utils/translation/localeUtils";

const UserRoute = () => {
    const {i18n} = useTranslation();
    const user = useSelector(selectUser)
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const isVisible = usePageVisibility()
    const pendingCsat = useSelector(selectPendingCsat)
    const pendingChargeback = useSelector(selectPendingChargeback)
    const mainDomain = getMainDomain();
    const permission = useSelector(selectPermission)
    const blockedUser = useSelector(selectBlocked)
    const badPassword = useSelector(selectBadPassword)
    const {logout} = useLogout();

    const check = useCallback(async () => {
        if (!Cookies.get("updateCheckUser")) {
            const currentVersion = await checkVersion();
            if (userVersion !== currentVersion.data.version) {
                const expirationDate = moment().add(10, 'minute');
                Cookies.set('updateCheckUser', 'true', {expires: expirationDate.toDate()})
                window.location.reload();
            } else {
                const expirationDate = moment().add(10, 'minute');
                Cookies.set('updateCheckUser', 'true', {expires: expirationDate.toDate()})
            }
            dispatch(checkPendingCsat())
        }
        dispatch(checkBadPassword())
        dispatch(checkPermission())
        dispatch(checkPendingChargeback())
        dispatch(checkUserBlocked())
    }, [dispatch]);

    useEffect(() => {
        if (badPassword) {
            logout();
        }
    }, [badPassword, logout, dispatch])

    useEffect(() => {
        if (blockedUser) {
            navigate("/blocked")
        }
    }, [blockedUser, navigate])

    useEffect(() => {
        if (pendingChargeback) {
            navigate("/chargeback")
        }
    }, [pendingChargeback, navigate])

    useEffect(() => {
        if (pendingCsat)
            navigate("/csat")
    }, [pendingCsat, navigate]);

    useEffect(() => {
        if (isVisible)
            check();
    }, [isVisible, check]);

    useEffect(() => {
        if (!user)
            dispatch(fetchUser())
        else {
            Clarity.identify(String(user.id));
            Clarity.setTag('id', user.id);
            Clarity.setTag('email', user.mail);
            Clarity.setTag('plan', user.sub?.subscriptionPlanId);
            Clarity.setTag('subscription', user.sub?.status);
            i18n.changeLanguage(normalizeAppLocale(user.language)).then();
        }
    }, [user, dispatch, i18n]);

    useEffect(() => {
        if (!Cookies.get("countryChecked")) {
            dispatch(setPaymentCountry())
            Cookies.set("countryChecked", true, {expires: 1 / 48, path: '/', domain: `.${mainDomain}`})
        }
    }, [dispatch, mainDomain])

    useEffect(() => {
        if (!Cookies.get("timeZone")) {
            const timezone = getPersistableBrowserTimeZone();
            Cookies.set("timeZone", true, {expires: 1, path: '/', domain: `.${mainDomain}`})
            if (timezone) {
                dispatch(setTimeZone({timeZone: timezone}))
            }
        }
    }, [dispatch, mainDomain])

    useEffect(() => {
        if (Cookies.get("onesignal_push_id") && Cookies.get("onesignal_push_id") !== "null" && Cookies.get("onesignal_push_id") != null && !Cookies.get("oneSignalCookieSet")) {
            Cookies.set("oneSignalCookieSet", true, {expires: 1 / 48, path: '/', domain: `.${mainDomain}`})
            dispatch(setPushId(Cookies.get("onesignal_push_id")))
        }
    }, [dispatch, mainDomain]);

    useEffect(() => {
        if (Cookies.get("firebase_push_id") && Cookies.get("firebase_push_id") !== "null" && Cookies.get("firebase_push_id") != null && !Cookies.get("fcmCookieSet")) {
            Cookies.set("fcmCookieSet", true, {expires: 1 / 48, path: '/', domain: `.${mainDomain}`})
            dispatch(setPushId(Cookies.get("firebase_push_id")))
        }
    }, [dispatch, mainDomain]);

    useEffect(() => {
        const getPersistentDeviceInfo = async () => {
            if (!Cookies.get("deviceInfo")) {
                const fp = await FingerprintJS.load();
                const result = await fp.get();
                const fingerprint = result.visitorId;
                const devInfo = deviceDetect();
                const formData = {
                    ...devInfo,
                    uuid: fingerprint
                };
                Cookies.set("deviceInfo", true, {expires: 1 / 48, path: '/', domain: `.${mainDomain}`})
                dispatch(setDeviceInformation(formData));
            }
        };
        getPersistentDeviceInfo();
    }, [dispatch, mainDomain])

    useEffect(() => {
        if (!Cookies.get("acLoginUpdate")) {
            Cookies.set("acLoginUpdate", true, {expires: 1, path: '/', domain: `.${mainDomain}`})
            dispatch(updateLoginToAc());
        }
    }, [dispatch, mainDomain])

    useEffect(() => {
        if (!permission)
            return;
        switch (permission) {
            case "TRIAL_ENDED":
                navigate("/block/trial-ended")
                break;
            case "NO_PAYMENT":
                navigate("/block/no-payment")
                break;
            case "NO_SUB":
                navigate("/block/no-sub")
                break;
            case "CANCELED_SUB":
                navigate("/block/canceled-sub")
                break;
            case "ALLOWED":
                break;
            default:
                window.location.href = "https://app.mfitpersonal.com.br/user"
                break;
        }
    }, [permission, navigate])


    useEffect(() => {
        const options = {domain: `.${mainDomain}`, path: '/'};
        Cookies.remove("goBackToNewAppFeedback", options)
        Cookies.remove("goBackToNewAppProfile", options)
        Cookies.remove("goBackToNewAppFinances", options)
        Cookies.remove("goBackToNewAppClientEval", options)
        Cookies.remove("goBackToNewAppClient", options)
        Cookies.remove("goBackToUpdates", options)
        Cookies.remove("goBackToTrainingLibrary", options)
        Cookies.remove("goBackToLib", options)
    }, [mainDomain])

    if (!user) {
        return <LoadingPage/>;
    }

    return (
        <>
            <ToastComponent/>
            <TopBar showChildren={true}/>
            <div style={{height: '79px'}}></div>
            <Outlet/>
            <div style={{height: '150px'}}></div>
            {
                isMobile &&
                <BottomBar/>
            }
        </>
    )
}

export default UserRoute;
