import {useCallback, useState} from "react";
import {useTranslation} from "react-i18next";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useNavigate} from "react-router-dom";
import {deleteModel} from "../../store/anamnesis/anamnesisReducer";
import AnamnesisSendModal from "../../components/anamnesis/AnamnesisSendModal";
import {useDispatch} from "react-redux";
import Modal from "react-bootstrap/Modal";
import {
    buildAnamnesisAnswerRoute,
    buildAnamnesisEditModelRoute,
    buildAnamnesisViewModelRoute
} from "../../utils/client/evaluationRoutes";

const AnamnesisModelModal = ({onClose, model, clientId, show}) => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const [modalContent, setModalContent] = useState('options');

    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoAnswerFlow = () => {
        navigate(buildAnamnesisAnswerRoute(clientId, model.id));
    };

    const handleGoNewModel = () => {
        navigate(buildAnamnesisEditModelRoute(clientId, model.id))
    };

    const handleGoViewModel = () => {
        navigate(buildAnamnesisViewModelRoute(clientId, model.id))
    }

    const handleDeleteModel = useCallback(async () => {
        dispatch(deleteModel(model.id));
        onClose();
    }, [dispatch, model, onClose]);

    const renderContent = () => {
        switch (modalContent) {
            case 'options':
                return (
                    <div className={"row"}>
                        <div className={"col-12"}>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto'}>
                                    <span className={"fw-semibold text-start"}>{t("anamnesisComponent:whatDoYouWant")}</span>
                                </div>
                                <div className={'col-auto  cursor-pointer'} onClick={onClose}>
                                    <i className="fa-regular fa-times"/>
                                </div>
                            </div>
                            <div className="row pt-4">
                                <div className={'col-12'}>
                                    <div className={'d-grid mb-2'}>
                                        <button className="btn btn-outline-primary" onClick={handleGoAnswerFlow}>
                                            {t("anamnesisComponent:iWillFill")}
                                        </button>
                                    </div>
                                    <div className={'d-grid mb-2'}>
                                        <button className="btn btn-outline-primary" onClick={() => setModalContent('send')}>
                                            {t("anamnesisComponent:myStudenWillFill")}
                                        </button>
                                    </div>
                                    {
                                        model.idUser === 0 ?
                                            <div className={'d-grid mb-2'}>
                                                <button className="btn btn-outline-primary"
                                                        onClick={handleGoViewModel}>
                                                    {t("anamnesisComponent:viewModel")}
                                                </button>
                                            </div>
                                            :
                                            <>
                                                <div className={'d-grid mb-2'}>
                                                    <button className={"btn btn-outline-primary"}
                                                            onClick={handleGoNewModel}>
                                                        {t("anamnesisComponent:viewEdit")}
                                                    </button>
                                                </div>
                                                <div className={'d-grid mb-2'}>
                                                    <button className={"btn btn-outline-danger"}
                                                            onClick={() => setModalContent('delete')}>
                                                        {t("anamnesisComponent:delete")}
                                                    </button>
                                                </div>
                                            </>
                                    }
                                </div>
                            </div>
                        </div>
                    </div>
                );
            case 'delete':
                return (
                    <div className={"row"}>
                        <div className={"col-12"}>
                            <ChangeStatus
                                icon={"fa-regular fa-circle-exclamation"}
                                iconColor={"text-danger"}
                                title={t("anamnesisComponent:areYouSure")}
                                subtitle={t("anamnesisComponent:actionCannotBeUndone")}
                            />
                            <div className="row mt-3 ">
                                <div className={"col-12"}>
                                    <div className={'d-grid'}>
                                        <button className="btn btn-danger" onClick={handleDeleteModel}>
                                            {t("anamnesisComponent:yesDelete")}
                                        </button>
                                        <button className="btn btn-outline-danger mt-2"
                                                onClick={() => setModalContent('options')}>
                                            {t("anamnesisComponent:close")}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                );
            case 'send':
                return (
                    <AnamnesisSendModal
                        clientId={clientId}
                        modelId={model.id}
                        onClose={() => setModalContent('options')}

                        show={true}
                    />
                );
            default:
                return null;
        }
    };

    return (
        <Modal show={show} onHide={onClose} centered>
            <Modal.Body>
                {renderContent()}
            </Modal.Body>
        </Modal>
    );
};

export default AnamnesisModelModal;
