import {useSortable} from "@dnd-kit/sortable";
import ExercisePlayerType from "../utils/videoplayer/ExercisePlayerType";
import WorkoutPrescriptionSerie from "./WorkoutPrescriptionSerie";
import {useNavigate} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {selectWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionSelector";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {Dropdown} from "react-bootstrap";
import BodyMenu from "./BodyMenu";
import React, {useState} from "react";
import {deleteSerie, replaceExerciseSerie} from "../../store/workout-prescription/workoutPrescriptionReducer";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {translateExerciseName} from "../../utils/workout/Exercise";
import Modal from "react-bootstrap/Modal";
import SimpleExerciseSearchModal from "./SimpleExerciseSearchModal";

const SortableSeriesRow = ({serie, listSize}) => {
    const {t, i18n} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const session = useSelector(selectWorkoutSession)
    const client = useSelector(selectSelectedClient)
    const [showAddExerciseModal, setShowAddExerciseModal] = useState(false)
    useComponentTranslations('workoutPrescriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleReplaceSerie = (id) => {
        const payload = {
            sessionId: session.id,
            serieId: serie.id,
            newExerc: id
        }
        dispatch(replaceExerciseSerie(payload))
        handleShowReplaceExercise();
    }

    const {attributes, listeners, setNodeRef, transform, transition} =
        useSortable({id: serie.id});

    const x = transform?.x ?? 0;
    const y = transform?.y ?? 0;

    const style = {
        transform: `translate3d(${x}px, ${y}px, 0)`,
        transition: transition,
        marginBottom: '0.5rem',
        touchAction: 'pan-y'
    };

    const handleDeleteSerieClick = () => {
        dispatch(deleteSerie(serie.id))
    }

    const handleShowReplaceExercise = () => {
        setShowAddExerciseModal(prevState => !prevState)
    }

    const handleReplaceSerieExerciseClick = () => {
        navigate(`/user/client/${client?.id || 0}/workout/routine/${session.idRoutine}/session/${session.id}/serie/${serie.id}`)
    }

    return (
        <div
            ref={setNodeRef}
            style={style}
            className="row mt-2 align-items-center ps-0 pe-0 "
            {...attributes}
        >
            {
                listSize > 1 &&
                <div className="col-2 pe-0 ps-0 text-center" {...listeners} style={{cursor: 'grab', touchAction: 'none'}}>
                    <span>
                        <i className="fa-regular small fa-bars"></i>
                    </span>
                </div>
            }
            <div className={`col-${listSize > 1 ? "10" : "12"}  `}>
                {
                    serie.idExerc !== 0 &&
                    <div className={"row   justify-content-between mt-2"}>
                        <ExercisePlayerType exercise={serie.exercicio}/>
                        <div className={"col-7 align-self-center ps-0"}>
                            <span className={"fw-semibold"}>{translateExerciseName(serie.exercicio, i18n.language)}</span>
                        </div>
                        <div className={"col-2 align-self-center text-center clickable-element"}>
                            <Dropdown onClick={e => e.stopPropagation()}>
                                <Dropdown.Toggle className={"no-style-btn text-default"}>
                                    <i className={"fa-regular fa-ellipsis-h "}> </i>
                                </Dropdown.Toggle>
                                <Dropdown.Menu as={BodyMenu}>
                                    <Dropdown.Item onClick={handleShowReplaceExercise}>{t("workoutPrescriptionComponent:replace")}</Dropdown.Item>
                                    <Dropdown.Divider/>
                                    <Dropdown.Item onClick={handleDeleteSerieClick}
                                                   className={"text-danger"}>{t("workoutPrescriptionComponent:delete")}</Dropdown.Item>
                                </Dropdown.Menu>
                            </Dropdown>
                        </div>
                    </div>
                }
                {
                    serie.idExerc === 0 &&
                    <div className={"row justify-content-between"}>
                        <div className={"col-12"}>
                            <WorkoutPrescriptionSerie serie={serie}/>
                        </div>
                    </div>
                }
            </div>
            <Modal centered show={showAddExerciseModal} onHide={handleShowReplaceExercise}>
                <Modal.Body>
                    <div className={"row justify-content-center mb-2"}>
                        <div className={"col-12"}>
                            <span className={"fw-semibold fs-5 d-block"}>{t("workoutPrescriptionComponent:replaceExercise")}</span>
                            <span>{t("workoutPrescriptionComponent:pickExercise")}</span>
                        </div>
                        <div className={"col-12  mt-3 mb-3 text-center"}>
                            <span className={"fw-semibold small text-primary clickable-element"}
                                  onClick={handleReplaceSerieExerciseClick}>{t("workoutPrescriptionComponent:goToLibrary")}</span>
                        </div>
                    </div>
                    {
                        serie.exercicio &&
                        <SimpleExerciseSearchModal
                            exerciseName={translateExerciseName(serie.exercicio, i18n.language)}
                            onSelect={item => {
                                const newExerc = Number(item.objectID);
                                handleReplaceSerie(newExerc);
                            }}
                        />
                    }
                </Modal.Body>
            </Modal>
        </div>
    );
};

export default SortableSeriesRow;