import React from "react";
import {useDispatch} from "react-redux";
import moment from "moment";
import {useTranslation} from "react-i18next";
import {addToast} from "../../store/toast/toastReducer";
import Text from "../../components/utils/emoji/Text";

const DeletedItemCard = ({
                             title,
                             item,
                             createdAt,
                             answeredAt,
                             onRecover,
                             recoverMessage,
                             i18nNamespace,
                         }) => {
    const dispatch = useDispatch();
    const {t} = useTranslation(i18nNamespace);

    const handleRecover = (e) => {
        e.stopPropagation();
        onRecover?.(item);

        dispatch(
            addToast({
                id: `toast-${item.id}`,
                type: "success",
                title: t("operationCompleted"),
                message: recoverMessage || t("itemSuccessfullyRecovered"),
                autohide: true,
                delay: 5000,
            })
        );
    };

    return (
        <div className="row pb-2" onClick={() => console.log("Item click", item)}>
            <div className="card">
                <div className="row d-flex align-items-center py-3">
                    <div className="col-10 lh-1">
                        <span className="fw-semibold d-block">
                            <Text>{title}</Text>
                        </span>
                        {item[createdAt] && (
                            <div>
                                <span className="text-md fw-semibold">
                                  {t("created")}{" "}
                                </span>
                                <span className="text-md">{moment(item[createdAt]).format("L")}</span>
                            </div>
                        )}
                        {answeredAt && item[answeredAt] !== undefined && (
                            <div>
                                <span className="text-md fw-semibold">{t("answered")} </span>
                                <span className="text-md">
                                  {item[answeredAt]
                                      ? moment(item[answeredAt]).format("L")
                                      : t("unansweredEvaluation")}
                                </span>
                            </div>
                        )}
                    </div>
                </div>
                <hr className="text-secondary my-n1"/>
                <div className="col-12 text-center clickable-element">
                    <button
                        className="btn btn-link text-md ps-0 fw-semibold mb-n1"
                        onClick={handleRecover}
                    >
                        {t("recoverEvaluation")}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default DeletedItemCard;
