import CardButtonAdd from "../card/CardButtonAdd";
import WorkoutAerobicEmpty from "./WorkoutAerobicEmpty";
import React, {useState} from "react";
import _ from "lodash";
import WorkoutAerobicPaceModal from "./WorkoutAerobicPaceModal";
import {useNavigate} from "react-router-dom";
import {useSelector} from "react-redux";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {selectAerobics} from "../../store/workout-aerobic/workoutAerobicSelector";
import WorkoutCard from "../workout/WorkoutCard";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutAerobic = () => {
    const {t} = useTranslation();
    const aerobics = useSelector(selectAerobics)
    const navigate = useNavigate();
    const client = useSelector(selectSelectedClient)
    const [showPace, setShowPace] = useState(false);
    useComponentTranslations('aerobicWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handlePace = () => {
        setShowPace(prevState => !prevState)
    }

    const handleGoToDeleted = () => {
        navigate(`/user/client/${client.id}/workout/secondary/status/2/type/1`)
    }

    const handleGoToArchive = () => {
        navigate(`/user/client/${client.id}/workout/secondary/status/1/type/1`)
    }

    const handleCreateAerobic = () => {
        navigate(`/user/client/${client.id}/workout/aerobic/create`)
    }

    return (
        <div className={"row justify-content-center mt-3"}>
            <div className={'col-12'}>
                <div className={'card card-body border-0'}>
                    <div className={"row"}>
                        <div className={"col-12 text-end"}>
                            <button className={"btn btn-primary btn-sm"} onClick={handlePace}>{t("aerobicWorkoutComponent:pace")}</button>
                            <WorkoutAerobicPaceModal handleModal={handlePace} show={showPace}/>
                        </div>
                        {
                            aerobics?.length > 0 &&
                            <div className={"col-12 mt-2"}>
                                <CardButtonAdd text={t("aerobicWorkoutComponent:plan")} handleClick={handleCreateAerobic}/>
                            </div>
                        }
                        <div className={"col-6 mt-2 pe-1"}>
                            <div className={"d-grid"}>
                                <button className={"btn btn-feedback-primary text-primary fw-semibold border-0"}
                                        onClick={handleGoToArchive}>{t("aerobicWorkoutComponent:archived")}</button>
                            </div>
                        </div>
                        <div className={"col-6 mt-2 ps-1"}>
                            <div className={"d-grid"}>
                                <button className={"btn btn-feedback-primary text-primary fw-semibold border-0"}
                                        onClick={handleGoToDeleted}>{t("aerobicWorkoutComponent:deleted")}</button>
                            </div>
                        </div>
                    </div>
                    {
                        aerobics &&
                        <div className={"row mt-3"}>
                            <div className={'col-12'}>
                                {
                                    _.map(aerobics, (aerobic) =>
                                        <WorkoutCard key={aerobic.id} workout={aerobic} type={1}/>
                                    )
                                }
                            </div>
                        </div>
                    }
                    {
                        aerobics?.length === 0 &&
                        <WorkoutAerobicEmpty create={handleCreateAerobic}/>
                    }
                </div>
            </div>
        </div>
    )
}

export default WorkoutAerobic;