import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {
    isFcRepLoading,
    isVo2MaxLoading,
    selectFcRep,
    selectLastVo2Max
} from "../../store/evaluation/evaluationSelector";
import {fetchFcRep, fetchLastVo2Max} from "../../store/evaluation/evaluationReducer";
import FcRepModal from "../../components/evaluation/FcRepModal";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import ItemListIcon from "../../components/list/ItemListIcon";
import {fetchClient} from "../../store/client/clientReducer";
import Vo2Modal from "../../components/evaluation/Vo2Modal";
import Vo2HistoryModal from "../../components/evaluation/Vo2HistoryModal";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {
    handlePosturalEvaluationClick
} from "../../utils/handlers/handler";
import Spinner from "../../components/loader/Spinner";
import {
    buildAnamnesisListRoute,
    buildClientMorphologicalRoute,
    buildClientNeuromotorsRoute
} from "../../utils/client/evaluationRoutes";
import {buildClientRoute} from "../../utils/client/clientRoutes";
import {calculateHeartRateDetails} from "../../utils/evaluation/heartRate";

const Evaluation = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {id} = useParams()
    const lastVo2Max = useSelector(selectLastVo2Max);
    const fcRep = useSelector(selectFcRep);
    const loadingVo2Max = useSelector(isVo2MaxLoading);
    const loadingFcRep = useSelector(isFcRepLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const [showRepModal, setShowRepModal] = useState(false);
    const [showVo2Modal, setShowVo2Modal] = useState(false);
    const [showVo2History, setShowVo2History] = useState(false);

    useComponentTranslations('evaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});


    const handleGoClientAnamnesisClick = buildAnamnesisListRoute(id);
    const handleGoClientMorphologicalClick = buildClientMorphologicalRoute(id);
    const handleGoNeuromotorClick = buildClientNeuromotorsRoute(id);

    const handleGoBack = () => {
        navigate(buildClientRoute(id))
    }
    const handleShowRepModal = () => {
        setShowRepModal(prevState => !prevState);
    }
    const handleOpenVo2Modal = () => {
        setShowVo2Modal(true);
    }
    const handleCloseVo2Modal = () => {
        setShowVo2Modal(false);
    };

    const handleShowVo2History = () => {
        setShowVo2History(prevState => !prevState);
    }

    const {age, fcMax, faixaMax, faixaMin, limiteMaximo} = calculateHeartRateDetails(selectedClient);

    useEffect(() => {
        dispatch(fetchClient(id));
        dispatch(fetchLastVo2Max(id));
        dispatch(fetchFcRep(id));
    }, [id, dispatch]);

    return (
        <>
            <AvatarHeader showGoBack={handleGoBack} className={"pb-4 pt-2"}
                          text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                          url={selectedClient?.profileUrl} />
            <Page contentHeader={false}
                  loading={loadingClient}>
                <div className={'row justify-content-center d-flex'}>
                    <div className={"col-12"}>
                        <div className={'card card-body border-0'}>
                            <div className={'row justify-content-center d-flex'}>
                                <div className={"col-12"}>

                                    <ItemListIcon size={"sm"} icon={"fa-clipboard-list"}
                                                  text={`${t("evaluation:morphological")}`}
                                                  to={handleGoClientMorphologicalClick}/>
                                    <ItemListIcon size={"sm"} icon={"fa-person-walking"} text={`${t("evaluation:neuromotor")}`}
                                                  to={handleGoNeuromotorClick}/>
                                    <ItemListIcon size={"sm"} icon={"fa-layer-group"} text={`${t("evaluation:postural")}`}
                                                  handler={() => handlePosturalEvaluationClick(id)}/>
                                    <ItemListIcon size={"sm"} icon={"fa-file-lines"}
                                                  text={`${t("evaluation:anamnesis")}`}
                                                  to={handleGoClientAnamnesisClick}/>
                                </div>
                                <div className={"col-12"}>
                                    <div className={"d-flex row justify-content-center "}>
                                        <div className={'col-12 mt-2 mb-2'}>
                                            <span className={"fw-bold   h5"}>{t("evaluation:details")}</span>
                                        </div>
                                        <div className={'col-12 mb-2'}>
                                            <div className={"card card-body bg-secondary-subtle py-2  border-0"}>
                                            <span className={"fw-semibold"}>
                                                {t("evaluation:age")}
                                            </span>
                                                <span>{age !== null ? `${age} ${t("evaluation:years")}` : t("evaluation:notInformed")}</span>
                                            </div>
                                        </div>
                                        <div className={'col-12'}>
                                            <div className={"card  card-body bg-secondary-subtle py-2 border-0"}>
                                            <span
                                                className={"fw-semibold  "}>
                                                {t("evaluation:vo2Max")}
                                            </span>
                                                <div className={"d-flex align-items-center"}>
                                                    {
                                                        !loadingVo2Max ?
                                                            <span>{`${lastVo2Max?.vo2max.toFixed(2) ?? 0} ml/kg/min`}</span> :
                                                            <Spinner width={"10px"}/>
                                                    }
                                                    <span className={"mx-2 text-primary clickable-element "}
                                                          onClick={handleOpenVo2Modal}>
                                                        {t("evaluation:update")}
                                                    </span>
                                                </div>
                                                <hr className={"text-secondary mt-1 mb-1"}/>
                                                <div className={"text-primary clickable-element   "}
                                                     onClick={handleShowVo2History}>
                                                    <span style={{fontSize: '12px'}}>
                                                        {t("evaluation:showHistory")}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <div className={"d-flex row justify-content-center   pt-4"}>
                                        <div className={'col-12 mb-2'}>
                                            <div className={"card card-body bg-secondary-subtle py-2 border-0"}>
                                                <span className={"fw-semibold "}>{t("evaluation:fcRep")}</span>
                                                <div className={"d-flex align-items-center"}>
                                                    {
                                                        !loadingFcRep ?
                                                            <span>{`${fcRep?.bpmRest ?? 0}`}</span> :
                                                            <Spinner width={"10px"}/>
                                                    }
                                                    <span className={"mx-2 text-primary clickable-element  "}
                                                          onClick={handleShowRepModal}>
                                                        {t("evaluation:change")}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className={'col-12 mb-2'}>
                                            <div className={"card card-body bg-secondary-subtle  py-2 border-0"}>
                                                <span className={"fw-semibold  "}>{t("evaluation:fcMax")}</span>
                                                <span>
                                                {fcMax !== null ? `${fcMax} ${t("evaluation:bpm")}` : `${t("evaluation:notAvailable")}`}
                                            </span>
                                            </div>
                                        </div>
                                        <div className={'col-12 mb-2'}>
                                            <div className={"card card-body bg-secondary-subtle py-2 border-0"}>
                                                <span className={"fw-semibold "}>
                                                    {t("evaluation:idealRange")}
                                                </span>
                                                <span>
                                                {faixaMin !== null && faixaMax !== null
                                                    ? `${faixaMin} ${t("evaluation:bpm")} - ${faixaMax} ${t("evaluation:bpm")}`
                                                    : `${t("evaluation:notAvailable")}`}
                                                </span>
                                            </div>
                                        </div>
                                        <div className={'col-12 mb-2'}>
                                            <div className={"card card-body bg-secondary-subtle py-2 border-0"}>
                                                <span className={"fw-semibold  "}>
                                                    {t("evaluation:maximumLimit")}
                                                </span>
                                                <span>
                                                    {limiteMaximo !== null ? `${limiteMaximo} ${t("evaluation:bpm")}` : t("evaluation:notInformed")}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <FcRepModal
                    show={showRepModal}
                    handleFcRepModal={handleShowRepModal}
                    clientId={id}
                />
                <Vo2Modal
                    show={showVo2Modal}
                    handleCloseVo2Modal={handleCloseVo2Modal}
                    clientId={id}
                />
                {
                    showVo2History &&
                    <Vo2HistoryModal
                        show={showVo2History}
                        clientId={id}
                        handleShowVo2History={handleShowVo2History}
                    />
                }
            </Page>
        </>
    )
}

export default Evaluation;
