import {Offcanvas} from "react-bootstrap";
import {useDispatch, useSelector} from "react-redux";
import {helpMenuSelector} from "../../store/menu/menuSelector";
import {toggleChatBot, toggleHelpMenu} from "../../store/menu/menuReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import {ReactComponent as Logo} from '../../assets/img/logo/logo-horizontal.svg';
import {selectUser} from "../../store/user/userSelector";
import AiButton from "./AiButton";
import WhatsAppButton from "./WhatsAppButton";

const HelpMenu = () => {
    const {t} = useTranslation();
    const helpMenu = useSelector(helpMenuSelector);
    const user = useSelector(selectUser);
    const dispatch = useDispatch();

    const getCurrentTimeGMT3 = () => {
        const now = new Date();
        const utc = now.getTime() + now.getTimezoneOffset() * 60000;
        return new Date(utc - 3 * 60 * 60000);
    };

    const isWithinWorkingHours = () => {
        const nowGMT3 = getCurrentTimeGMT3();
        const currentMinutes = nowGMT3.getHours() * 60 + nowGMT3.getMinutes();
        const startMinutes = 7 * 60 + 30;
        const endMinutes = 18 * 60 + 30;
        return currentMinutes >= startMinutes && currentMinutes < endMinutes;
    };

    useComponentTranslations('navBarComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleTrainerAppHelp = () => {
        window.open("https://www.youtube.com/playlist?list=PLo825NQLOa0qikV0MLOnVncZ8FtKZgF9j", "_blank")
    };
    const handleClientsAppHelp = () => {
        window.open("https://www.youtube.com/playlist?list=PLo825NQLOa0oLQkOBB0ZbWIT9Huhsri13", "_blank")
    };

    const handleTrainingAreaHelp = () => {
        window.open("https://www.youtube.com/playlist?list=PLo825NQLOa0oLQkOBB0ZbWIT9Huhsri13", "_blank")
    };

    const handleTrainingCloneHelp = () => {
        window.open("https://www.youtube.com/playlist?list=PLo825NQLOa0oLQkOBB0ZbWIT9Huhsri13", "_blank")
    };

    const handlePaymentHelp = () => {
        window.open("https://www.youtube.com/playlist?list=PLo825NQLOa0qU2LSWDWGIdkyWidB6EJCH", "_blank")
    };

    const handleClientAcquisitionHelp = () => {
        window.open("https://www.youtube.com/playlist?list=PLo825NQLOa0qU2LSWDWGIdkyWidB6EJCH", "_blank")
    };

    const handleWhatsAppRedirect = () => {
        window.open("https://whatsapp.mfitpersonal.com.br", "_blank")
    };

    const handleKnowledgeBaseRedirect = () => {
        window.open("https://ajuda.mfitpersonal.com.br/", "_blank")
    };

    const handleHelpMenu = () => {
        dispatch(toggleHelpMenu(!helpMenu))
    };

    const handleChatBot = () => {
        dispatch(toggleChatBot(true))
    };

    return (
        <Offcanvas show={helpMenu} onHide={handleHelpMenu} placement={'end'}>
            <Offcanvas.Body>
                <div className="row justify-content-center pt-2">
                    <div className="col-auto">
                        <Logo className={'text-default-darker'} style={{height: '33px'}}/>
                    </div>
                </div>
                <div className={'row justify-content-start pt-4'}>
                    <div className={'col-auto clickable-element'} onClick={handleHelpMenu}>
                        <span className={"text-xs"}><i
                            className={'fa-regular fa-chevron-left'}/> {t("navBarComponent:goBack")}</span>
                    </div>
                </div>
                <div className={"row pt-4 pe-3 text-title"}>
                    <span className={"fw-semibold"}>Olá, {user.nome} {user.sobrenome}</span>
                    <span>{t("navBarComponent:howCanWeHelp")}</span>
                </div>
                <div className={"row pt-3"}>
                    <div className={"col-12"}>
                        {isWithinWorkingHours() ? (
                            <div className={"card card-body border-0 mt-2 clickable-element"}>
                                <WhatsAppButton handleWhatsAppRedirect={handleWhatsAppRedirect}/>
                                <hr className={"border-primary-subtle"}/>
                                <AiButton   handleChatBot={handleChatBot}/>
                            </div>
                        ) : (
                            <div className={"card card-body border-0 mt-2 clickable-element"}>
                                <AiButton handleChatBot={handleChatBot}/>
                                <hr className={"border-primary-subtle"}/>
                                <WhatsAppButton handleWhatsAppRedirect={handleWhatsAppRedirect}/>
                            </div>
                        )}
                    </div>
                </div>
                <div className={"card card-body border-0 mt-2 clickable-element"}>
                    <div className={"row"}>
                        <div className={"d-flex pb-2"}>
                            <div className={"col-2 align-self-center"}>
                                <RoundedIcon icon="fa-circle-play"/>
                            </div>
                            <div className={"col-10 ps-2 align-self-center"}>
                                <span className={"fw-semibold d-block"}>
                                    {t("navBarComponent:tutorialHeader")}
                                </span>
                            </div>
                        </div>
                        <div className={"row px-4 align-self-center align-items-center"}>
                            <span className={"text-primary btn btn-link text-start"} style={{fontSize: '14px'}}
                                    onClick={handleTrainerAppHelp}>{t("navBarComponent:trainerApp")}</span>
                            <hr className={"border-primary-subtle m-0"}/>
                            <span className={"text-primary btn btn-link text-start"} style={{fontSize: '14px'}}
                                    onClick={handleClientsAppHelp}>{t("navBarComponent:clientApp")}</span>
                            <hr className={"border-primary-subtle m-0"}/>
                            <span className={"text-primary btn btn-link text-start"} style={{fontSize: '14px'}}
                                    onClick={handleTrainingAreaHelp}>{t("navBarComponent:workoutArea")}</span>
                            <hr className={"border-primary-subtle m-0"}/>
                            <span className={"text-primary btn btn-link text-start"} style={{fontSize: '14px'}}
                                    onClick={handleTrainingCloneHelp}>{t("navBarComponent:cloneWorkout")}</span>
                            <hr className={"border-primary-subtle m-0"}/>
                            <span className={"text-primary btn btn-link text-start"} style={{fontSize: '14px'}}
                                    onClick={handlePaymentHelp}>{t("navBarComponent:payments")}</span>
                            <hr className={"border-primary-subtle m-0"}/>
                            <span className={"text-primary btn btn-link text-start"} style={{fontSize: '14px'}}
                                    onClick={handleClientAcquisitionHelp}>{t("navBarComponent:clientAcquisition")}</span>
                        </div>
                    </div>
                </div>
                <div className={"card card-body border-0 mt-2 clickable-element"}
                     onClick={handleKnowledgeBaseRedirect}>
                    <div className={"row"}>
                        <div className={"d-flex"}>
                            <div className={"col-2 align-self-center"}>
                                <RoundedIcon icon="fa-info-circle"/>
                            </div>
                            <div className={"col-10 ps-2 align-self-center"}>
                                <span className={"fw-semibold d-block text-subtitle"}>
                                    {t("navBarComponent:seeFrequentQuestions")}
                                </span>
                            </div>
                        </div>
                    </div>
                </div>
            </Offcanvas.Body>
        </Offcanvas>
    )
}
export default HelpMenu