import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useDispatch, useSelector} from "react-redux";
import {updateAerobicInstructions} from "../../store/workout-aerobic/workoutAerobicReducer";
import {selectAerobicInstructionsLoading} from "../../store/workout-aerobic/workoutAerobicSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from 'he';
import TextareaAutosize from "react-textarea-autosize";

const WorkoutAerobicInstructions = ({aerobic}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const loading = useSelector(selectAerobicInstructionsLoading);

    const initialValues = {
        instructions: he.decode(aerobic?.orientacoes || "")
    };

    useComponentTranslations(
        "aerobicWorkoutComponent",
        {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT}
    );

    const validationSchema = Yup.object({
        instructions: Yup.string().required(t("aerobicWorkoutComponent:required"))
    });

    const handleSubmit = (values) => {
        dispatch(updateAerobicInstructions({id: aerobic?.id, data: values}));

    };

    return (
        <Formik
            initialValues={initialValues}
            validationSchema={validationSchema}
            onSubmit={handleSubmit}
        >
            {() => (
                <Form>
                    <div className="form-group">
                        <label htmlFor="instructions" className="fw-semibold">
                            {t("aerobicWorkoutComponent:generalInstruction")}
                        </label>
                        <Field name="instructions">
                            {({field}) => (
                                <TextareaAutosize
                                    {...field}
                                    id="instructions"
                                    className="form-control"
                                    minRows={3}
                                    style={{
                                        transition: "height 0.2s ease, max-height 0.2s ease",
                                        overflow: "hidden"
                                    }}
                                />
                            )}
                        </Field>
                        <ErrorMessage
                            name="instructions"
                            component="div"
                            className="text-danger"
                        />
                    </div>
                    <button
                        type="submit"
                        id="submitButton"
                        className="btn btn-primary mt-3 w-100"
                        disabled={loading}
                    >
                        {
                            loading ?
                                <span><i className={"fa-regular fa-spin fa-spinner"}></i> {t("aerobicWorkoutComponent:wait")}</span> :
                                t("aerobicWorkoutComponent:save")
                        }

                    </button>
                </Form>
            )}
        </Formik>
    );
};

export default WorkoutAerobicInstructions;
