import moment from "moment";
import React, {useState} from "react";
import Modal from "react-bootstrap/Modal";
import WorkoutSessionCreateForm from "./WorkoutSessionCreateForm";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import {deleteSession} from "../../store/workout-routine/workoutRoutineReducer";
import {useDispatch} from "react-redux";
import {Link, useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Text from "../utils/emoji/Text";
import {Dropdown} from "react-bootstrap";
import DropdownMenuPortal from "../utils/dropdown/DropdownMenuPortal";

const WorkoutSessionCard = ({session, workout, isLibrary, onEditToggle, dragDisabled, listeners}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const [showObs, setShowObs] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const count = session?.feedback?.length || 0;

    useComponentTranslations('routineWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoToSessionClick = `/user/client/${workout.idAluno}/workout/routine/${workout.id}/session/${session.id}/prescribe`

    const handleCloneSession = () => {
        navigate(`/user/client/${workout.idAluno}/workout/routine/${workout.id}/session/${session.id}/clone`)
    }

    const handleFeedbackClick = () => {
        navigate(`/user/client/${workout.idAluno}/workout/routine/${workout.id}/session/${session.id}/feedback`)
    }

    const handleProgressClick = () => {
        navigate(`/user/client/${workout.idAluno}/workout/routine/${workout.id}/session/${session.id}/progress`)
    }

    const closeAfterSave = () => {
        setShowEditModal(prevState => !prevState)
    }

    const handleOpenEdit = () => {
        setShowEditModal(true);
        onEditToggle?.(true);

    };

    const handleCloseEdit = () => {
        setShowEditModal(false);
        onEditToggle?.(true);
    };

    const handleShowObs = () => {
        setShowObs(prevState => !prevState)
    }

    const handleDeleteModal = () => {
        setShowDeleteModal(prevState => !prevState)
    }

    const handleChangeWorkoutStatus = () => {
        dispatch(deleteSession(session.id))
    }

    return (
        <div className={"card card-body border-0 mb-2"} style={{overflow: 'visible'}}>
            <div className={"row justify-content-between"}>
                {
                    !dragDisabled &&
                    <div className="col-2 text-center align-self-center" {...listeners} style={{cursor: 'grab', touchAction: 'none'}}>
                        <span>
                            <i className="fa-regular small fa-bars"></i>
                        </span>
                    </div>
                }
                <div className={dragDisabled ? "col-9" : "col-10"}>
                    <Link to={handleGoToSessionClick} className={"text-decoration-none text-default"} style={{pointerEvents: !dragDisabled ? 'none' : 'auto'}}>
                        <div className={"row"}>
                            <div className={"col-12"}>
                                {
                                    workout.diaTipo === 2 ?
                                        <span className={"fw-semibold"}>{t("routineWorkoutComponent:workout")} {session.diaTipo}</span> :
                                        <span className={"fw-semibold text-capitalize"}>{moment().day(session.diaTipo - 1).format('dddd')}</span>
                                }
                            </div>
                            <div className={"col-12"}>
                                <Text>{session.nome}</Text>
                            </div>
                        </div>
                    </Link>
                </div>
                {
                    dragDisabled &&
                    <div className={"col-3 align-self-center"}>
                        <div className={"row justify-content-end"}>
                            <div className={"col-auto text-center"}>
                                <Dropdown align="end">
                                    <Dropdown.Toggle
                                        as="button"
                                        className="btn btn-link border-0 text-dark p-1 dropdown-toggle-no-caret"
                                        aria-label={t("routineWorkoutComponent:optionsAria") || "Opções da sessão"}
                                    >
                                        <i className="fa-regular fa-ellipsis-vertical"></i>
                                    </Dropdown.Toggle>
                                    <Dropdown.Menu as={DropdownMenuPortal}>
                                        <Dropdown.Item as="button" onClick={handleCloneSession}  >
                                            <i className="fa-regular fa-clone me-2"/> {t("routineWorkoutComponent:clone")}
                                        </Dropdown.Item>
                                        <Dropdown.Item as="button" onClick={handleOpenEdit}>
                                            <i className="fa-regular fa-pen-to-square me-2"/> {t("routineWorkoutComponent:edit")}
                                        </Dropdown.Item>
                                        <Dropdown.Divider/>
                                        <Dropdown.Item as="button" className="text-danger" onClick={handleDeleteModal}>
                                            <i className="fa-regular fa-trash-can me-2"/> {t("routineWorkoutComponent:delete")}
                                        </Dropdown.Item>
                                    </Dropdown.Menu>
                                </Dropdown>
                            </div>

                        </div>
                    </div>
                }
                {
                    session.obs && dragDisabled &&
                    <div className={"col-12 mt-2"}>
                        <div className={"card card-body border-0 bg-secondary-subtle py-2"}>
                            <div className={"row justify-content-between"}>
                                <div className={"col-auto small fw-semibold clickable-element"} onClick={handleShowObs}>
                                    {t("routineWorkoutComponent:generalInstructions")}
                                </div>
                                <div className={"col-auto small clickable-element"} onClick={handleShowObs}>
                                    <i className={`fa-regular ${!showObs ? "fa-eye" : "fa-eye-slash"}`}></i>
                                </div>
                                {
                                    showObs &&
                                    <div className={"col-12"}>
                                        <pre className={"mb-0"}><Text className={"small"}>{session.obs}</Text></pre>
                                    </div>
                                }
                            </div>
                        </div>
                    </div>
                }
                {
                    !isLibrary && dragDisabled &&
                    <div className={"col-12 mt-2"}>
                        {
                            session.feedback && session.feedback.length > 0 ?
                                <div className={'col-12 mb-2'}>
                                    <span
                                        className={' small text-primary-darker '}> {t(count > 1 ? 'routineWorkoutComponent:executed_plural' : 'routineWorkoutComponent:executed', {count})}, {t('routineWorkoutComponent:lastExecution')}&nbsp;
                                        {
                                            moment({
                                                day: session.feedback[0]?.dataExecucao.date.day,
                                                month: session.feedback[0]?.dataExecucao.date.month - 1,
                                                year: session.feedback[0]?.dataExecucao.date.year
                                            }).format('L')
                                        }
                                    </span>
                                </div> :
                                <div className={'col-12  mb-2'}>
                                    <span
                                        className={'d-block small text-primary-darker '}>{t("routineWorkoutComponent:notCompleted")}
                                    </span>
                                </div>
                        }
                        <div className={"row justify-content-between"}>
                            <div className={"col-6 pe-1"}>
                                <button className={"btn btn-primary w-100"} onClick={handleProgressClick}><i
                                    className={"fa-regular fa-chart-line-up"}></i> {t("routineWorkoutComponent:progress")}
                                </button>
                            </div>
                            <div className={"col-6 ps-1"}>
                                <button className={"btn btn-outline-primary w-100"} onClick={handleFeedbackClick}><i
                                    className={"fa-regular fa-clipboard-check"}></i> {t("routineWorkoutComponent:feedbacks")}
                                </button>
                            </div>
                        </div>
                    </div>
                }
            </div>
            <Modal centered show={showEditModal} onHide={handleCloseEdit}>
                <Modal.Body>
                    <WorkoutSessionCreateForm workout={workout} session={session} onClose={closeAfterSave}/>
                </Modal.Body>
            </Modal>
            <Modal show={showDeleteModal} centered onHide={handleDeleteModal}>
                <Modal.Body>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation"}
                        iconColor={"text-danger"}
                        title={t("routineWorkoutComponent:deleteConfirmationMessage")}
                        subtitle={t("routineWorkoutComponent:cannotBeUndone")}
                    />
                    <div className="row mt-3 justify-content-center">
                        <div className="col-12">
                            <div className="d-grid">
                                <button className="btn btn-danger" onClick={handleChangeWorkoutStatus}>
                                    {t("routineWorkoutComponent:delete")}
                                </button>
                            </div>
                            <div className="d-grid mt-2">
                                <button className="btn btn-outline-danger" onClick={handleDeleteModal}>
                                    {t("routineWorkoutComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </div>
    )
}

export default WorkoutSessionCard;