import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    loading: false,
    frequency: null,
};

export const slice = createSlice({
    name: 'frequency',
    initialState,
    reducers: {
        fetchFrequency(state) {
            state.loading = true;
        },
        setFrequency(state, action) {
            state.frequency = action.payload;
            state.loading = false;
        },
        onError(state) {
            state.loading = false;
        }
    }
})

export const {
    setFrequency, fetchFrequency, onError
} = slice.actions;

export const frequencyReducer = slice.reducer;