import React, {useEffect} from "react";
import {Formik, Form, FieldArray, Field, ErrorMessage} from "formik";
import AnamnesisQuestionField from "./AnamnesisQuestionField";
import * as Yup from 'yup';
import {useNavigate, useParams} from "react-router-dom";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {fetchClient} from "../../store/client/clientReducer";
import {useDispatch, useSelector} from "react-redux";
import {getSubmitResult, isSubmitLoading} from "../../store/anamnesis/anamnesisSelector";
import {buildAnamnesisNewRoute} from "../../utils/client/evaluationRoutes";
import EvaluationSubmitButton from "../evaluation-components/EvaluationSubmitButton";
import EvaluationSuccessCard from "../evaluation-components/EvaluationSuccessCard";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const AnamnesisModelForm = ({onSave}) => {
    const {t} = useTranslation();
    const {clientId} = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const submitLoading = useSelector(isSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const isSubmitted = isMatchingSubmitSuccess(submitResult, {
        action: "create",
        flow: EVALUATION_FLOWS.ANAMNESIS_MODEL_CREATE,
        clientId
    });
    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object().shape({
        name: Yup.string().required(t("anamnesisComponent:modalNameRequire")),
        questions: Yup.array().of(
            Yup.object().shape({
                question: Yup.string().required(t("anamnesisComponent:questionRequire"))
            })
        )
    });

    const initialValues = {
        name: '',
        questions: [{question: ''}]
    };

    const handleSubmit = (values) => {
        onSave(values);
    };
    const handleGoBack = () => {
        navigate(buildAnamnesisNewRoute(clientId))
    }

    useEffect(() => {
        dispatch(fetchClient(clientId));
    }, [dispatch, clientId]);

    if (isSubmitted) {
        return (
            <div className={'row justify-content-center d-flex'}>
                <div className={"col-12"}>
                    <EvaluationSuccessCard
                        title={t("anamnesisComponent:modelCreated")}
                        primaryLabel={t("anamnesisComponent:backToTop")}
                        secondaryLabel={t("anamnesisComponent:backToTop")}
                        onPrimary={handleGoBack}
                        onSecondary={handleGoBack}
                    />
                </div>
            </div>
        );
    }

    return (
        <Formik
            initialValues={initialValues}
            validationSchema={validationSchema}
            onSubmit={handleSubmit}
        >
            {({values}) => (
                <div className={"row"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            <Form>
                                <div className={"row"}>
                                    <div className={"col-12"}>
                                        <div className="form-group">
                                            <div className="fw-semibold">{t("anamnesisComponent:modelName")}:</div>
                                            <Field
                                                name="name"
                                                type="text"
                                                className="w-100 mb-1 border rounded py-2 form-control"
                                            />
                                            <ErrorMessage name="name" component="div" className="text-danger"/>
                                        </div>
                                    </div>
                                </div>
                                <div className={"row"}>
                                    <div className={"col-12"}>
                                        <div className="row justify-content-center d-flex">
                                            <FieldArray name="questions">
                                                {({remove, push}) => (
                                                    <>
                                                        {values.questions.map((q, index) => (
                                                            <AnamnesisQuestionField
                                                                key={index}
                                                                question={q}
                                                                index={index}
                                                                onDelete={() => remove(index)}
                                                            />
                                                        ))}

                                                        <div className="form-group clickable-element pt-2">
                                                            <div
                                                                className="card card-body clickable-element py-2 bg-secondary-subtle"
                                                                onClick={() => push({question: ''})}>
                                                                <div
                                                                    className="row d-flex align-items-center clickable-element">
                                                                    <div className="col-10">
                                                                        <span className="fw-semibold">
                                                                            {t("anamnesisComponent:addQuestion")}
                                                                        </span>
                                                                    </div>
                                                                    <div className="col-2 text-end">
                                                                        <i className="fa-regular fa-circle-plus text-primary"/>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </>
                                                )}
                                            </FieldArray>
                                        </div>
                                    </div>
                                </div>
                                <div className="row pt-3">
                                    <div className={"col-12"}>
                                        <EvaluationSubmitButton
                                            label={t("anamnesisComponent:save")}
                                            loadingLabel={t("anamnesisComponent:saving")}
                                            isSubmitting={submitLoading}
                                        />
                                    </div>
                                </div>
                            </Form>
                        </div>
                    </div>
                </div>
            )}
        </Formik>

    );
};

export default AnamnesisModelForm;
