import {Image} from "react-bootstrap";
import {useDispatch, useSelector} from "react-redux";
import {selectWorkoutRoutineLoading, selectWorkoutRoutines} from "../../store/workout-routine/workoutRoutineSelector";
import Modal from "react-bootstrap/Modal";
import Spinner from "../loader/Spinner";
import _ from "lodash";
import WorkoutRoutineCardSimple from "./WorkoutRoutineCardSimple";
import EmptySet from "../empty-set/EmptySet";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import React, {useState} from "react";
import {fetchRoutinesToCloneSessions, setWorkouts} from "../../store/workout-routine/workoutRoutineReducer";
import he from 'he';

const WorkoutSessionClientItemList = ({client, handleCloneSessionClick, onToggle, selectedWorkoutIds}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const loading = useSelector(selectWorkoutRoutineLoading)
    const workouts = useSelector(selectWorkoutRoutines)
    const [showModal, setShowModal] = useState(false);
    useComponentTranslations('routineWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleCloneClick = () => {
        handleCloneSessionClick();
        handleCloseModal()

    }

    const handleShowModal = (id) => {
        setShowModal(true);
        fetchWorkouts(id)
    };
    const handleCloseModal = () => {
        setShowModal(false);
        dispatch(setWorkouts(null))
    };

    const fetchWorkouts = (id) => {
        dispatch(fetchRoutinesToCloneSessions({library: false, clientId: id}));
    };
    return (
        <>
            <div className="row" onClick={() => handleShowModal(client.id)}>
                <div className="col-2 text-center">
                    <Image
                        src={
                            client.profileUrl ??
                            "https://cdn.mfitpersonal.com.br/assets/user/user.jpg"
                        }
                        className="rounded-circle"
                        width="45"
                        fluid
                    />
                </div>
                <div className="col-10 align-self-center ps-0">
                    <span className="fw-semibold">
                        {he.decode(client.nome)}
                    </span>
                </div>
            </div>
            <Modal show={showModal} centered onHide={handleCloseModal}>
                <Modal.Body>
                    <div className={"row justify-content-between"}>
                        <div className={"col-auto"}>
                            <span className={"fw-semibold"}>{t("routineWorkoutComponent:clientWorkouts")}</span>
                        </div>
                        <div className={"col-auto clickable-element"} onClick={handleCloseModal}>
                            <i className={"fa-regular fa-times"}></i>
                        </div>
                        <div className="col-12 mt-2 mb-2 text-center">
                            <span
                                className={"fst-italic"}>{t("workoutRoutine:selectRoutineToClone")}</span>
                        </div>
                    </div>
                    <div className={"row overflow-auto"} style={{minHeight: "500px", maxHeight: "500px"}}>
                        {loading &&
                            <div className={"col-12 "}>
                                <Spinner/>
                            </div>
                        }
                        {
                            !loading && workouts?.length === 0 &&
                            <EmptySet icon={"fa-folder-open"} message={t("routineWorkoutComponent:noWorkouts")}/>
                        }
                        {
                            !loading &&
                            _.map(workouts, (workout =>
                                    <div className={"col-12 mt-2"} key={workout.id}>
                                        <WorkoutRoutineCardSimple workout={workout} handleCloneSessionClick={handleCloneClick} onToggle={onToggle}
                                                                  selected={selectedWorkoutIds.includes(workout.id)} gender={client?.sexo}/>
                                    </div>
                            ))
                        }
                    </div>
                    {selectedWorkoutIds.length > 0 && (
                        <div className="col-12 text-center mb-2 mt-4">
                            <button
                                className="btn btn-primary w-100"
                                onClick={() => handleCloneClick(0)}
                                disabled={selectedWorkoutIds.length === 0}
                            >
                                {t("workoutRoutine:cloneWorkoutSession")}
                            </button>
                            <button className="btn btn-outline-primary w-100 mt-2" onClick={handleCloseModal}>{t("workoutRoutine:close")}</button>
                        </div>
                    )}
                </Modal.Body>
            </Modal>
        </>
    )
}
export default WorkoutSessionClientItemList;