import {baseApi} from "../api/baseApi"

export const USER_EXPERIENCE_RESOLVE_TTL_SECONDS = 15 * 60

export const normalizeUserExperienceIds = (experienceIds = []) => (
    [...new Set(
        (Array.isArray(experienceIds) ? experienceIds : [])
            .filter((experienceId) => typeof experienceId === "string" && experienceId.trim())
            .map((experienceId) => experienceId.trim())
    )].sort()
)

const buildResolvedStateMap = (responseData = {}) => {
    const states = Array.isArray(responseData?.states) ? responseData.states : []

    return states.reduce((resolvedStates, state) => {
        if (!state || typeof state.experienceId !== "string" || !state.experienceId.trim()) {
            return resolvedStates
        }

        resolvedStates[state.experienceId] = state
        return resolvedStates
    }, {})
}

export const userExperienceApi = baseApi.injectEndpoints({
    endpoints: (build) => ({
        resolveUserExperiences: build.query({
            query: (experienceIds) => ({
                url: "/user/experience/resolve",
                method: "post",
                data: {
                    experienceIds: normalizeUserExperienceIds(experienceIds)
                }
            }),
            serializeQueryArgs: ({queryArgs}) => normalizeUserExperienceIds(queryArgs).join("|"),
            transformResponse: (responseData) => buildResolvedStateMap(responseData),
            keepUnusedDataFor: USER_EXPERIENCE_RESOLVE_TTL_SECONDS
        }),
        recordUserExperience: build.mutation({
            query: ({experienceId, event}) => ({
                url: "/user/experience/record",
                method: "post",
                data: {experienceId, event}
            }),
            transformResponse: (responseData) => responseData?.state || null
        })
    })
})

export const {
    useLazyResolveUserExperiencesQuery,
    useRecordUserExperienceMutation
} = userExperienceApi
