import {getRetentionStatusMeta} from "./retentionConfig";
import RetentionInfoOffcanvas from "./RetentionInfoOffcanvas";

const SECTION_ORDER = [
    "ENGAGED",
    "OSCILLATING",
    "AT_RISK",
    "ABANDONED",
    "RECOVERED"
];

const DESCRIPTION_KEYS = {
    ENGAGED: "retention:classificationEngaged",
    OSCILLATING: "retention:classificationOscillating",
    AT_RISK: "retention:classificationAtRisk",
    ABANDONED: "retention:classificationAbandoned",
    RECOVERED: "retention:classificationRecovered"
};

const RetentionClassificationInfoOffcanvas = ({show, onHide, t}) => {
    const sections = SECTION_ORDER.map((status) => {
        const meta = getRetentionStatusMeta(status, t);

        return {
            key: status,
            title: meta.label,
            description: t(DESCRIPTION_KEYS[status]),
            dotClass: meta.dotClass
        };
    });

    return (
        <RetentionInfoOffcanvas
            show={show}
            onHide={onHide}
            title={t("retention:understandClassification")}
            intro={t("retention:classificationInfoText")}
            sections={sections}
            sectionVariant={"status"}
        />
    );
};

export default RetentionClassificationInfoOffcanvas;
