import {useTranslation} from "react-i18next";
import {useDispatch} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {useSelector} from 'react-redux';
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useCallback, useEffect, useMemo, useState} from "react";
import {syncMomentLocale} from "../translation/localeUtils";
import i18n from "i18next";
import {
    changeStatus,
} from "../../store/custom-evaluation/customEvaluationReducer";
import {handleSendWhatsApp} from "../handlers/handler";
import {addToast} from "../../store/toast/toastReducer";
import {buildShareUrl, createShareToken} from "../sharelink/shareLink";
import {
    buildClientMorphologicalRoute,
    buildClientCustomRoute,
    buildCustomCompareRoute,
    buildCustomCreateModelRoute,
    buildCustomDeletedRoute,
    buildCustomEditRoute,
    buildCustomViewRoute
} from "../client/evaluationRoutes";
import {
    selectSubmitLoading,
    selectSubmitResult
} from "../../store/custom-evaluation/customEvaluationSelector";
import {isMatchingSubmitError, isMatchingSubmitSuccess} from "../evaluation/successFlow";
import {EVALUATION_FLOWS} from "../evaluation/flows";

export function useCustomActions() {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const submitLoading = useSelector(selectSubmitLoading);
    const submitResult = useSelector(selectSubmitResult);

    const [currentCustom, setCurrentCustom] = useState(null);
    const [showOptionsModal, setShowOptionsModal] = useState(false);
    const [showShareModal, setShowShareModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [deleteRequested, setDeleteRequested] = useState(false);
    const [isComparing, setIsComparing] = useState(false);
    const [selectedList, setSelectedList] = useState([]);
    syncMomentLocale(i18n.language);

    const isSyntheticEvent = useCallback(
        value => Boolean(value && typeof value === "object" && typeof value.preventDefault === "function"),
        []
    );

    const setCustom = useCallback(custom => setCurrentCustom(custom), []);

    const openOptionsModal = useCallback((id) => {
        setCurrentCustom(id);
        setShowOptionsModal(true);
    }, []);
    const closeOptionsModal = useCallback(() => setShowOptionsModal(false), []);

    const openShareModal = useCallback(() => {
        if (currentCustom) setShowShareModal(true);
    }, [currentCustom]);
    const closeShareModal = useCallback(() => setShowShareModal(false), []);

    const openDeleteModal = useCallback(() => setShowDeleteModal(true), []);
    const closeDeleteModal = useCallback(() => {
        setShowDeleteModal(false);
        setDeleteRequested(false);
    }, []);

    const handleConfirmDelete = useCallback(() => {
        if (currentCustom) {
            dispatch(changeStatus(
                {id: currentCustom.id, status: 1},
                {flow: EVALUATION_FLOWS.CUSTOM_ANSWERED_DELETE, clientId: id}
            ));
            setDeleteRequested(true);
        }
    }, [dispatch, currentCustom, id]);

    useEffect(() => {
        if (!deleteRequested) {
            return;
        }

        if (isMatchingSubmitSuccess(submitResult, {
            action: "delete",
            flow: EVALUATION_FLOWS.CUSTOM_ANSWERED_DELETE,
            clientId: id
        })) {
            setShowDeleteModal(false);
            setShowOptionsModal(false);
            setDeleteRequested(false);
            navigate(buildClientCustomRoute(id));
        }

        if (isMatchingSubmitError(submitResult, {
            action: "delete",
            flow: EVALUATION_FLOWS.CUSTOM_ANSWERED_DELETE,
            clientId: id
        })) {
            setDeleteRequested(false);
        }
    }, [deleteRequested, submitResult, navigate, id]);

    const shareWhatsLink = useMemo(() => {
        if (!selectedClient || !currentCustom) return '';
        const token = createShareToken(
            selectedClient.idUser,
            selectedClient.id,
            1,
            currentCustom.id
        );
        return buildShareUrl(token);
    }, [selectedClient, currentCustom]);

    const copyLink = useCallback(() => {
        if (shareWhatsLink) {
            navigator.clipboard.writeText(shareWhatsLink)
                .then(() => dispatch(addToast({
                    type: 'success',
                    title: t("utils:toastTitle"),
                    message: t("utils:linkCopied")
                })));
        }
    }, [shareWhatsLink, dispatch, t]);

    const sendWhatsApp = useCallback(() => {
        if (shareWhatsLink && selectedClient?.telefone) {
            const message = `${t("utils:checkHere")} ${shareWhatsLink}`;
            handleSendWhatsApp(selectedClient.telefone, message);
        }
    }, [shareWhatsLink, selectedClient, t]);

    const comparingMode = useCallback(() => {
        setIsComparing((prev) => {
            const next = !prev;
            if (prev) setSelectedList([]);
            return next;
        });
    }, []);

    const toggleSelection = useCallback((customId) => {
        setSelectedList((prev) =>
            prev.includes(customId)
                ? prev.filter((id) => id !== customId)
                : prev.length < 3 ? [...prev, customId] : prev
        );
    }, []);

    const goBackPage = useCallback(
        () => navigate(buildClientMorphologicalRoute(id)),
        [navigate, id]
    );

    const createNew = useCallback(
        () => navigate(buildCustomCreateModelRoute(id)),
        [navigate, id]
    );

    const goDeleted = useCallback(
        () => navigate(buildCustomDeletedRoute(id)),
        [navigate, id]
    );

    const goView = useCallback((customOrId = currentCustom?.id) => {
        const targetId = isSyntheticEvent(customOrId) ? currentCustom?.id : customOrId;
        if (!targetId) return;
        navigate(buildCustomViewRoute(id, targetId));
        setShowOptionsModal(false);
    }, [navigate, id, currentCustom, isSyntheticEvent]);

    const goEdit = useCallback((customOrId = currentCustom) => {
        const normalizedInput = isSyntheticEvent(customOrId) ? currentCustom : customOrId;
        const nextCustom = typeof normalizedInput === "object" ? normalizedInput : currentCustom;
        const nextId = typeof normalizedInput === "object" ? normalizedInput?.id : normalizedInput;
        if (!nextId) return;

        if (nextCustom) {
            setCurrentCustom(nextCustom);
        }

        navigate(buildCustomEditRoute(id, nextId));
        setShowOptionsModal(false);
    }, [navigate, id, currentCustom, isSyntheticEvent]);

    const goCompare = useCallback(() => {
        if (selectedList.length >= 2)
            navigate(buildCustomCompareRoute(id, selectedList.join(',')));
    }, [navigate, selectedList, id]);

    return {
        state: {
            currentCustom,
            showOptionsModal,
            showShareModal,
            showDeleteModal,
            deleteSubmitting: deleteRequested && submitLoading,
            isComparing,
            selectedList
        },
        handlers: {
            openOptionsModal,
            closeOptionsModal,
            openShareModal,
            closeShareModal,
            openDeleteModal,
            closeDeleteModal,
            handleConfirmDelete,
            copyLink,
            sendWhatsApp,
            comparingMode,
            toggleSelection,
            goBackPage,
            createNew,
            goView,
            goEdit,
            goDeleted,
            goCompare,
            setCurrentCustom: setCustom
        },
        shareWhatsLink
    };
}
