import {all, call, put, takeLatest} from "redux-saga/effects";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    answerCustomEvaluationAPI,
    changeStatusCustomEvaluationAPI, createCustomModelAPI, editAnsweredCustomEvaluationAPI, editCustomModelAPI,
    getAllCustomEvaluationAPI,
    getAllCustomModelsAPI, getCompareCustomEvaluationAPI,
    getCustomEvaluationAPI
} from "../../api/custom-evaluation/customEvaluationActions";
import {
    getAllCustom,
    setAllCustom,
    onError,
    setAllCustomModels,
    getAllCustomModels,
    setOneCustom,
    getOneCustom,
    setCompareCustom,
    compareCustom,
    setChangeCustomStatus,
    changeCustomStatus,
    saveCustom,
    editModel,
    setEditModel,
    answerCustom,
    setAnswerCustom,
    setEditAnsweredCustom,
    editAnsweredCustom,
    setOneModel, getOneModel, setChangeStatus, changeStatus, setSubmitResult
} from "./customEvaluationReducer";

export function* fetchCustomEvaluationAsync(action) {
    try {
        const {clientId, status} = action.payload;
        const response = yield call(getAllCustomEvaluationAPI, clientId, status);
        yield put(setAllCustom(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchCustomEvaluation() {
    yield takeLatest(getAllCustom.type, fetchCustomEvaluationAsync);
}

export function* fetchCustomModelsAsync() {
    try {
        const response = yield call(getAllCustomModelsAPI);
        yield put(setAllCustomModels(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchCustomModels() {
    yield takeLatest(getAllCustomModels.type, fetchCustomModelsAsync);
}

export function* getOneCustomEvaluationAsync(action) {
    try {
        const response = yield call(getCustomEvaluationAPI, action.payload);
        yield put(setOneCustom(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchOneCustomEvaluation() {
    yield takeLatest(getOneCustom.type, getOneCustomEvaluationAsync);
}

export function* compareCustomEvaluationAsync(action) {
    try {
        const ids = action.payload.ids;
        const response = yield call(getCompareCustomEvaluationAPI, ids.join(','));
        yield put(setCompareCustom(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onCompareCustomEvaluation() {
    yield takeLatest(compareCustom.type, compareCustomEvaluationAsync);
}

export function* changeCustomAsync(action) {
    try {
        const {id, status} = action.payload;
        const response = yield call(changeStatusCustomEvaluationAPI, id, status);
        yield put(setChangeCustomStatus(id));
        yield put(setSubmitResult({
            action: status === 1 ? "delete" : "recover",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onChangeCustomEvaluation() {
    yield takeLatest(changeCustomStatus.type, changeCustomAsync);
}

export function* changeCustomEvaluationAsync(action) {
    try {
        const{id, status} = action.payload;
        const response = yield call (changeStatusCustomEvaluationAPI, id, status);
        yield put(setChangeStatus(id));
        yield put(setSubmitResult({
            action: status === 1 ? "delete" : "recover",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onChangeCustom() {
    yield takeLatest(changeStatus.type, changeCustomEvaluationAsync);
}

export function* saveCustomAsync(action) {
    try {
        const response = yield call(createCustomModelAPI, action.payload);
        yield put(setOneModel(response.data));
        yield put(setSubmitResult({
            action: "create",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response.data?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onSaveCustomEvaluation() {
    yield takeLatest(saveCustom.type, saveCustomAsync);
}

