export function* customEvaluationSaga() {
    yield all([
        call(onFetchCustomEvaluation),
        call(onFetchCustomModels),
        call(onFetchOneCustomEvaluation),
        call(onCompareCustomEvaluation),
        call(onChangeCustomEvaluation),
        call(onSaveCustomEvaluation),
        call(onEditCustomModel),
        call(onAnswerCustom),
        call(onEditAnsweredCustom),
        call(onFetchOneCustomModel),
        call(onChangeCustom)
    ]);
}
