import React, {useEffect, useRef, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {selectRoutineList} from "../../store/workout-library/workoutLibrarySelector";
import {fetchRoutinesList} from "../../store/workout-library/workoutLibraryReducer";
import Modal from "react-bootstrap/Modal";
import WorkoutLibraryWorkoutItem from "./WorkoutLibraryWorkoutItem";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import Pagination from "../../components/pagination/Pagination";

const WorkoutLibrarySearchModal = ({show, handleShow, type}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const routineList = useSelector(selectRoutineList);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredRoutines, setFilteredRoutines] = useState([]);
    const [hideBg, setHideBg] = useState("block");
    const input = useRef();
    useComponentTranslations('trainingLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(5);
    const pagesToShow = 5;

    const handleBg = (val) => {
        setHideBg(val ? "none" : "block");
    };

    useEffect(() => {
        if (show) {
            dispatch(fetchRoutinesList(type));
        }
    }, [dispatch, show, type]);

    useEffect(() => {
        if (show) {
            input.current && input.current.focus();
        }
    }, [show]);

    useEffect(() => {
        const normalizeString = (str) => {
            return str.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
        };
        const query = normalizeString(searchQuery);
        let filtered;
        if (!searchQuery) {
            filtered = routineList;
        } else {
            filtered = routineList.filter((routine) => {
                const name = normalizeString(routine.nome);
                return name.includes(query);
            });
        }
        setFilteredRoutines(filtered);
        setCurrentPage(1);
    }, [searchQuery, routineList]);

    const totalItems = filteredRoutines?.length || 0;
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentItems = filteredRoutines?.slice(indexOfFirstItem, indexOfLastItem);

    useEffect(() => {
        const totalPages = Math.ceil(totalItems / itemsPerPage);
        if (currentPage > totalPages && totalPages > 0) {
            setCurrentPage(totalPages);
        }
    }, [currentPage, totalItems, itemsPerPage]);

    return (
        <Modal
            centered
            show={show}
            onHide={handleShow}
            onEntered={() => input.current && input.current.focus()}
        >
            <Modal.Body style={{display: hideBg}}>
                <div className="row justify-content-center mb-3">
                    <div className="col-12">
                        <input
                            ref={input}
                            className="form-control"
                            placeholder={t("trainingLibraryComponent:searchPlaceholder")}
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                </div>
                {totalItems === 0 ? (
                    <div className="text-center">
                        {t("trainingLibraryComponent:noRoutinesFound")}
                    </div>
                ) : (
                    <>
                        {currentItems?.map((routine, index) => (
                            <WorkoutLibraryWorkoutItem
                                workout={routine}
                                type={type}
                                key={index}
                                closeBackgroundModal={handleBg}
                            />
                        ))}
                        {totalItems > itemsPerPage && (
                            <div className="row justify-content-center mt-3">
                                <div className="col-auto">
                                    <Pagination
                                        currentPage={currentPage}
                                        totalItems={totalItems}
                                        itemsPerPage={itemsPerPage}
                                        onPageChange={setCurrentPage}
                                        pagesToShow={pagesToShow}
                                    />
                                </div>
                            </div>
                        )}
                    </>
                )}
            </Modal.Body>
        </Modal>
    );
};

export default WorkoutLibrarySearchModal;
