import React, {useEffect, useMemo, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useLocation, useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import Page from "../../components/page/Page";
import WorkoutPresetForm from "../../components/workout-preset/WorkoutPresetForm";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {
    clearWorkoutPresetEvents,
    createWorkoutPreset,
    fetchWorkoutPresets
} from "../../store/workout-preset/workoutPresetReducer";
import {
    selectLastCreatedWorkoutPreset,
    selectWorkoutPresetLoading,
    selectWorkoutPresets
} from "../../store/workout-preset/workoutPresetSelector";

const getSourcePresetId = (search) => {
    const value = new URLSearchParams(search).get("sourcePresetId");
    const parsedValue = Number(value);
    return Number.isInteger(parsedValue) && parsedValue > 0 ? parsedValue : null;
};

const normalizeName = (name) => (name || "").trim().toLowerCase();

const buildUniqueCopyName = (presets, sourcePreset, copySuffix) => {
    const baseName = `${(sourcePreset?.name || "Preset").trim() || "Preset"} (${copySuffix})`;
    const existingNames = new Set(
        (presets || [])
            .filter((preset) => Number(preset.userId) !== 0)
            .map((preset) => normalizeName(preset.name))
    );

    if (!existingNames.has(normalizeName(baseName))) {
        return baseName;
    }

    let suffix = 2;
    while (existingNames.has(normalizeName(`${baseName} ${suffix}`))) {
        suffix++;
    }

    return `${baseName} ${suffix}`;
};

const WorkoutPresetCreate = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const location = useLocation();
    const presets = useSelector(selectWorkoutPresets);
    const loading = useSelector(selectWorkoutPresetLoading);
    const createdPreset = useSelector(selectLastCreatedWorkoutPreset);
    const backTo = location.state?.backTo || "/user";
    const sourcePresetId = useMemo(() => getSourcePresetId(location.search), [location.search]);
    const sourcePresetFromState = location.state?.sourcePreset;
    const [hasRequestedSourcePreset, setHasRequestedSourcePreset] = useState(false);

    useComponentTranslations("workoutPresetPage", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const sourcePreset = useMemo(() => {
        if (!sourcePresetId) {
            return null;
        }

        if (sourcePresetFromState && Number(sourcePresetFromState.id) === sourcePresetId) {
            return sourcePresetFromState;
        }

        return presets.find((preset) => preset.id === sourcePresetId) || null;
    }, [presets, sourcePresetFromState, sourcePresetId]);

    const initialPreset = useMemo(() => {
        if (!sourcePreset || Number(sourcePreset.userId) !== 0) {
            return null;
        }

        return {
            name: buildUniqueCopyName(presets, sourcePreset, t("workoutPresetPage:copySuffix")),
            series: sourcePreset.series || []
        };
    }, [presets, sourcePreset, t]);

    const isInvalidSourcePreset = Boolean(sourcePresetId && sourcePreset && Number(sourcePreset.userId) !== 0);
    const isResolvingSourcePreset = Boolean(sourcePresetId && !sourcePreset && (!hasRequestedSourcePreset || loading));
    const initialPresetKey = sourcePresetId ? `source-${sourcePresetId}` : "create";

    useEffect(() => {
        if (createdPreset?.id) {
            dispatch(clearWorkoutPresetEvents());
            navigate("/user/workout-presets", {
                state: {
                    backTo
                }
            });
        }
    }, [backTo, createdPreset, dispatch, navigate]);

    useEffect(() => {
        if (!sourcePresetId || sourcePreset || hasRequestedSourcePreset) {
            return;
        }

        setHasRequestedSourcePreset(true);
        dispatch(fetchWorkoutPresets());
    }, [dispatch, hasRequestedSourcePreset, sourcePreset, sourcePresetId]);

    useEffect(() => {
        if (!isInvalidSourcePreset) {
            return;
        }

        navigate("/user/workout-presets", {
            replace: true,
            state: {
                backTo
            }
        });
    }, [backTo, isInvalidSourcePreset, navigate]);

    useEffect(() => {
        if (!sourcePresetId || !hasRequestedSourcePreset || loading || sourcePreset) {
            return;
        }

        navigate("/user/workout-presets", {
            replace: true,
            state: {
                backTo
            }
        });
    }, [backTo, hasRequestedSourcePreset, loading, navigate, sourcePreset, sourcePresetId]);

    return (
        <Page title={t("workoutPresetPage:title")} goBackLink={() => navigate("/user/workout-presets", {
            state: {
                backTo
            }
        })} loading={isResolvingSourcePreset}>
            <div className="card card-body border-0">
                <WorkoutPresetForm
                    initialPreset={initialPreset}
                    initialPresetKey={initialPresetKey}
                    loading={loading}
                    submitLabel={t("workoutPresetPage:save")}
                    onCancel={() => navigate("/user/workout-presets", {
                        state: {
                            backTo
                        }
                    })}
                    onSubmit={(payload) => dispatch(createWorkoutPreset(payload))}
                />
            </div>
        </Page>
    );
};

export default WorkoutPresetCreate;
