import {ProgressBar} from "react-bootstrap";
import {useDispatch} from "react-redux";
import {useEffect, useRef, useState} from "react";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import {useTranslation} from "react-i18next";
import {setAnamnesis} from "../../store/anamnesis/anamnesisReducer";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {getTranslatedQuestion} from "../../utils/anamnesis/questionUtils";

const AnamnesisQuestion = ({
                               question,
                               moveBackwards,
                               moveForward,
                               currentStep,
                               maxStep,
                               anamnesis,
                               handleFormSubmit,
                               isSubmitting = false
                           }) => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const [answer, setAnswer] = useState(question.answer ?? '');
    const [error, setError] = useState(false);
    const textareaRef = useRef(null);
    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        setAnswer(question.answer ?? "");
    }, [question.answer, question.id]);

    const handleOnChange = (event) => {
        setAnswer(event.target.value);
    };

    const handleClickYes = () => {
        const yesAnswer = `${t("anamnesisComponent:yes")}`;
        setAnswer(yesAnswer);
        if (textareaRef.current) {
            textareaRef.current.focus();
        }
    };

    const handleClickNo = () => {
        const noAnswer = `${t("anamnesisComponent:no")}`;
        setAnswer(noAnswer);
        handleNextClick(noAnswer);
    };

    const handleNextClick = (overrideAnswer) => {
        const answerToUse = overrideAnswer || answer;
        setError(false);
        if (!answerToUse) {
            setError(true);
            return;
        }
        const questionAnswered = {
            ...question,
            answer: answerToUse
        };
        const updatedQuestions = anamnesis.questions.map(q => q.id === question.id ? questionAnswered : q);

        const newAnamnesis = {
            ...anamnesis,
            questions: updatedQuestions
        };
        dispatch(setAnamnesis(newAnamnesis));

        if (currentStep === maxStep) {
            handleFormSubmit(newAnamnesis);
        } else moveForward();
    };

    return (
        <div className={"card card-body "}>
            <div className={"row justify-content-center d-flex "}>
                <div className={"col-12 pb-4"}>
                    <span className={"d-block  pb-1 small fw-semibold"}>
                        {isNaN((currentStep / maxStep) * 100)
                            ? 0
                            : parseFloat((currentStep / maxStep) * 100).toFixed(0)}%
                    </span>
                    <ProgressBar
                        now={currentStep}
                        max={maxStep}
                        variant={"primary-lighter"}
                        style={{height: "12px"}}
                    />
                </div>
                <div className={"col-12  pt-2  "}>
                    <span
                        className={"fs-5 d-block fw-semibold text-center"}
                        style={{lineHeight: "1.5rem"}}
                    >
                    {getTranslatedQuestion(question, i18n.language)}
                    </span>
                    <textarea
                        ref={textareaRef}
                        className={"form-control mt-4"}
                        style={{height: "60px"}}
                        value={answer}
                        onChange={handleOnChange}
                    />
                    {error && (
                        <span className={"d-block text-danger"}>
                            {t("anamnesisComponent:emptyFieldError")}
                        </span>
                    )}
                </div>
                <div className={"col-12 pt-3"}>
                    <div className={"row"}>
                        <div className={"col-auto"}>
                            <span
                                className={"badge rounded-pill bg-primary-subtle  text-primary clickable-element"}
                                onClick={handleClickYes}
                                style={{fontSize: "0.9rem"}}
                            >
                                {t("anamnesisComponent:yes")}
                            </span>
                        </div>
                        <div className={"col-auto ps-0"}>
                            <span className={"badge rounded-pill bg-primary-subtle  text-primary clickable-element"}
                                  onClick={handleClickNo}
                                  style={{fontSize: "0.9rem"}}
                            >
                                {t("anamnesisComponent:no")}
                            </span>
                        </div>
                    </div>
                </div>
                <div className={"col-12 pt-4"}>
                    <div className={"row justify-content-between"}>
                        <div className={`col-6 pe-1`}>
                            {currentStep > 0 && (
                                <div className={"d-grid"}>
                                    <button
                                        className={"btn btn-primary-lighter text-white"}
                                        onClick={moveBackwards}
                                    >
                                        {t("anamnesisComponent:goBack")}
                                    </button>
                                </div>
                            )}
                        </div>
                        <div className={`col-${currentStep === 0 ? 12 : "6 ps-1 "} `}>
                            <div className={"d-grid"}>
                                <button
                                    className={"btn btn-primary-darker"}
                                    disabled={currentStep === maxStep && isSubmitting}
                                    onClick={() => handleNextClick()}
                                >
                                    {currentStep === maxStep && isSubmitting && (
                                        <i className={"fa-regular fa-loader fa-spin me-2"}/>
                                    )}
                                    {t("anamnesisComponent:goForward")}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AnamnesisQuestion;
