import {apiUrl as url, getToken} from "../api";
import axios from "axios";

const apiUrl = url + "/v2"
export const getAllByTypeAPI = async (type) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/anamnesis/models?type=${type}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

