import {ErrorMessage, Field, Form, Formik} from "formik";
import Select from "react-select";
import {useCallback, useEffect, useMemo} from "react";
import {updatePush} from "../../store/push/pushReducer";
import {useDispatch, useSelector} from "react-redux";
import {isPushLoading} from "../../store/push/pushSelector";
import * as Yup from "yup";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {selectSelectOptions} from "../../store/client/clientSelector";
import {fetchSelectOptions} from "../../store/client/clientReducer";
import decodeHtmlEntities from "../../utils/text/decodeHtmlEntities";
import ClientRemoteMultiSelect from "../client/ClientRemoteMultiSelect";

const PushRecurringEditForm = ({notification}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const loading = useSelector(isPushLoading);
    const selectOptions = useSelector(selectSelectOptions);
    const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const time = `${String(notification.timePart.hour).padStart(2, '0')}:${String(notification.timePart.minute).padStart(2, '0')}`;
    const daysOfWeek = notification.daysOfWeek.split(',').map(day => day.trim());
    const sendTo = notification.sendToClients ? 'clients' : 'groups';
    const normalizeLabel = useCallback((label) => (
        label?.includes("client_group") ? t(`push:${label}`) : decodeHtmlEntities(label)
    ), [t]);

    useComponentTranslations('push', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object({
        title: Yup.string().required(t("push:required")),
        message: Yup.string().required(t("push:required")),
        sendTo: Yup.string().required(t("push:required")),
        selectOption: Yup.array().required(t("push:required")),
        daysOfWeek: Yup.array().required(t("push:required")),
        dateTime: Yup.string().required(t("push:required"))
    });

    const initialValues = {
        title: notification.title,
        message: notification.message,
        sendTo: sendTo,
        selectOption: notification.sendToClients ? notification.sendToClients.split(',').map(Number) : notification.sendToGroups.split(",").map(Number),
        daysOfWeek: daysOfWeek,
        dateTime: time,
        timeZone: timeZone,
        type: notification.type
    };

    const daysOfWeekOptions = [
        {value: 'everyday', label: t("push:everyday")},
        {value: 'monday', label: t("push:monday")},
        {value: 'tuesday', label: t("push:tuesday")},
        {value: 'wednesday', label: t("push:wednesday")},
        {value: 'thursday', label: t("push:thursday")},
        {value: 'friday', label: t("push:friday")},
        {value: 'saturday', label: t("push:saturday")},
        {value: 'sunday', label: t("push:sunday")}
    ];

    const groupOptions = useMemo(() => [
        {value: 0, label: t("push:all")},
        ...(selectOptions ? selectOptions.map(opt => ({
            value: opt.id,
            label: normalizeLabel(opt.label)
        })) : [])
    ], [normalizeLabel, selectOptions, t]);

    useEffect(() => {
        if (sendTo === "groups") {
            dispatch(fetchSelectOptions("groups"));
        }
    }, [sendTo, dispatch]);


    const minDateTime = useMemo(() => {
        const now = new Date();
        const localDate = new Date(now.getTime() - (now.getTimezoneOffset() * 60000));
        localDate.setSeconds(0);
        localDate.setMilliseconds(0);
        return localDate.toISOString().slice(0, 16);
    }, []);


    const handleSubmitForm = (values) => {
        const payload = {
            id: notification.id,
            formData: values
        }
        dispatch(updatePush(payload));
    };

    return (
        <Formik
            initialValues={initialValues}
            validationSchema={validationSchema}
            onSubmit={handleSubmitForm}
            enableReinitialize={true}
        >
            {({setFieldValue, values, errors, touched}) => (
                <Form>
                    <div className="form-group">
                        <label className={'fw-semibold'}>{t("push:title")}</label>
                        <Field name="title" type="text" className={`form-control ${touched.title && errors.title ? 'is-invalid' : ''}`}/>
                        <ErrorMessage name="title" component="div" className="invalid-feedback"/>
                    </div>
                    <Field type="hidden" name="timeZone"/>
                    <Field type="hidden" name="type"/>
                    <div className="form-group mt-2">
                        <label className={'fw-semibold'}>{t("push:message")}</label>
                        <Field name="message" type="text" className={`form-control ${touched.message && errors.message ? 'is-invalid' : ''}`}/>
                        <ErrorMessage name="message" component="div" className="invalid-feedback"/>
                    </div>
                    <div className="form-group mt-2">
                        <label className={'fw-semibold'}>{t("push:sendTo")}</label>
                        <Field as="select" name="sendTo" className={`form-control ${touched.sendTo && errors.sendTo ? 'is-invalid' : ''}`}
                               onChange={e => {
                                   const nextValue = e.target.value;
                                   setFieldValue("sendTo", nextValue);
                                   setFieldValue("selectOption", []);
                                   if (nextValue === "groups") {
                                       dispatch(fetchSelectOptions("groups"));
                                   }
                               }}>
                            <option value={""}>{t("push:select")}</option>
                            <option value="clients">{t("push:clients")}</option>
                            <option value="groups">{t("push:groups")}</option>
                        </Field>
                        <ErrorMessage name="sendTo" component="div" className="invalid-feedback"/>
                    </div>
                    {values.sendTo &&
                        <div className="form-group mt-2">
                            {
                                values.sendTo === "clients" ?
                                    <label className={'fw-semibold'}>{t("push:selectOneOrMoreClients")}</label> :
                                    <label className={'fw-semibold'}>{t("push:selectOneOrMoreGroups")}</label>
                            }
                            {values.sendTo === "clients" ? (
                                <ClientRemoteMultiSelect
                                    valueIds={values.selectOption}
                                    onChangeIds={(clientIds) => {
                                        if (clientIds.includes(0) && clientIds.length > 1) {
                                            setFieldValue("selectOption", [0]);
                                            return;
                                        }

                                        setFieldValue("selectOption", clientIds);
                                    }}
                                    searchScope={"active"}
                                    resolveScope={"nonDeleted"}
                                    specialOptions={[{value: 0, label: t("push:all")}]}
                                    placeholder={t("push:select")}
                                    noOptionsMessage={() => t("push:noOptions")}
                                    loadingMessage={() => t("push:loading")}
                                    disabled={loading}
                                />
                            ) : (
                                <>
                                    <Select
                                        isMulti
                                        name="selectOption"
                                        options={groupOptions}
                                        className="basic-multi-select"
                                        classNamePrefix="select"
                                        placeholder={t("push:select")}
                                        required
                                        noOptionsMessage={() => t("push:noOptions")}
                                        onChange={opts => {
                                            const hasTodos = opts.some(opt => opt.value === 0);
                                            if (hasTodos && opts.length > 1) {
                                                setFieldValue('selectOption', [0]);
                                            } else {
                                                setFieldValue('selectOption', opts.map(opt => opt.value));
                                            }
                                        }}
                                        value={values.selectOption
                                            .map(val => {
                                                if (val === 0) {
                                                    return {value: val, label: t('push:all')};
                                                }
                                                return groupOptions.find(option => option.value === val) || null;
                                            })
                                            .filter(Boolean)}
                                    />
                                    {
                                        loading && !selectOptions &&
                                        <span className={'small fw-semibold'}><i className={'fa-regular fa-exclamation-circle'}></i> {t("push:loading")}</span>
                                    }
                                </>
                            )}

                        </div>
                    }
                    <div className="form-group mt-2">
                        <label className={'fw-semibold'}>{t("push:recurrence")}</label>
                        <Select
                            isMulti
                            name="daysOfWeek"
                            options={daysOfWeekOptions}
                            className="basic-multi-select"
                            classNamePrefix="select"
                            placeholder={t("push:select")}
                            required
                            noOptionsMessage={() => t("push:noOptions")}
                            onChange={opts => {
                                const hasEveryday = opts.some(opt => opt.value === 'everyday');
                                if (hasEveryday && opts.length > 1) {
                                    setFieldValue('daysOfWeek', ['everyday']);
                                } else {
                                    setFieldValue('daysOfWeek', opts.map(opt => opt.value));
                                }
                            }}
                            value={values.daysOfWeek.map(val => daysOfWeekOptions.find(option => option.value === val))}
                        />

                    </div>
                    <div className="form-group mt-2">
                        <label className={'fw-semibold'}>{t("push:scheduleTo")}</label>
                        <Field name="dateTime" type="time" className={`form-control ${touched.dateTime && errors.dateTime ? 'is-invalid' : ''}`}
                               min={minDateTime} value={values.dateTime}/>
                        <ErrorMessage name="dateTime" component="div" className="invalid-feedback"/>
                    </div>
                    <div className={'d-grid mt-3'}>
                        <button type="submit" disabled={loading} className="btn btn-primary">{t("push:save")}</button>
                    </div>
                </Form>
            )}
        </Formik>
    );
};

export default PushRecurringEditForm;
