import {takeLatest, all, call, put, select} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    addClientsToGroupAPI,
    createClientGroupAPI,
    deleteClientGroupAPI,
    fetchClientGroupsAPI,
    fetchClientsFromGroupAPI,
    fetchUngroupedClientsAPI,
    fetchUngroupedCountAPI,
    moveClientToGroupAPI,
    removeClientFromGroupAPI,
    updateClientGroupAPI
} from "../../api/client-group/clientGroupActions";
import {
    addClientsToGroup, addClientsToGroupSuccess,
    clearCreatedClientGroup,
    createClientGroup, createClientGroupSuccess, deleteClientGroup,
    deleteClientGroupSuccess,
    fetchClientGroups, fetchClientsFromGroup,
    fetchUngroupedClients,
    fetchUngroupedCount,
    moveClientToGroup,
    moveClientToGroupSuccess,
    onError, removeClientFromGroup, removeClientFromGroupSuccess,
    setClientGroups, setClientsFromGroup,
    setUngroupedClients,
    setUngroupedCount,
    updateClientGroup,
    updateClientGroupSuccess
} from "./clientGroupReducer";
import {selectUngroupedFilters} from "./clientGroupSelector";

export function* fetchClientGroupsAsync() {
    try {
        const response = yield call(fetchClientGroupsAPI);
        yield put(setClientGroups(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchClientGroups() {
    yield takeLatest(fetchClientGroups.type, fetchClientGroupsAsync);
}

export function* createClientGroupAsync(action) {
    try {
        yield put(clearCreatedClientGroup())
        const response = yield call(createClientGroupAPI, action.payload)
        yield put(createClientGroupSuccess(response.data))
        yield put(fetchClientGroups());
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreateClientGroup() {
    yield takeLatest(createClientGroup, createClientGroupAsync);
}

export function* onUpdateClientGroupAsync(action) {
    try {
        const {formData, id} = action.payload;
        const response = yield call(updateClientGroupAPI, formData, id);
        yield put(updateClientGroupSuccess(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateClientGroup() {
    yield takeLatest(updateClientGroup.type, onUpdateClientGroupAsync);
}

export function* deleteClientGroupAsync(action) {
    try {
        yield call(deleteClientGroupAPI, action.payload);
        yield put(deleteClientGroupSuccess(action.payload));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDeleteClientGroup() {
    yield takeLatest(deleteClientGroup.type, deleteClientGroupAsync);
}

export function* fetchClientsFromGroupAsync(action) {
    try {
        const response = yield call(fetchClientsFromGroupAPI, action.payload);
        yield put(setClientsFromGroup(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchClientsFromGroup() {
    yield takeLatest(fetchClientsFromGroup.type, fetchClientsFromGroupAsync);
}

export function* fetchUngroupedClientsAsync(action) {
    try {
        const response = yield call(fetchUngroupedClientsAPI, action.payload || {});
        yield put(setUngroupedClients(response?.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchUngroupedClients() {
    yield takeLatest(fetchUngroupedClients.type, fetchUngroupedClientsAsync);
}

export function* fetchUngroupedCountAsync() {
    try {
        const response = yield call(fetchUngroupedCountAPI);
        yield put(setUngroupedCount(response?.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchUngroupedCount() {
    yield takeLatest(fetchUngroupedCount.type, fetchUngroupedCountAsync);
}

export function* removeClientFromGroupAsync(action) {
    try {
        const clientId = typeof action.payload === "object" ? action.payload.clientId : action.payload;
        const sourceGroupId = typeof action.payload === "object" ? action.payload.sourceGroupId : null;
        yield call(removeClientFromGroupAPI, clientId);
        yield put(removeClientFromGroupSuccess(clientId));
        yield put(fetchClientGroups());
        yield put(fetchUngroupedCount());
        if (sourceGroupId) {
            yield put(fetchClientsFromGroup(sourceGroupId));
        }
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onRemoveClientFromGroup() {
    yield takeLatest(removeClientFromGroup.type, removeClientFromGroupAsync);
}

export function* addClientsToGroupAsync(action) {
    try {
        const {clients, id} = action.payload;
        yield call(addClientsToGroupAPI,  clients, id);
        yield put(addClientsToGroupSuccess());
        yield put(fetchClientsFromGroup(id));
        yield put(fetchClientGroups());
        yield put(fetchUngroupedCount());
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onAddClientsToGroup() {
    yield takeLatest(addClientsToGroup.type, addClientsToGroupAsync);
}

export function* moveClientToGroupAsync(action) {
    try {
        const {clientId, toGroupId, sourceGroupId} = action.payload;
        yield call(moveClientToGroupAPI, {clientId, toGroupId});
        yield put(moveClientToGroupSuccess());
        yield put(fetchClientGroups());
        yield put(fetchUngroupedCount());

        if (sourceGroupId === "ungrouped") {
            const filters = yield select(selectUngroupedFilters);
            yield put(fetchUngroupedClients(filters));
        } else if (sourceGroupId !== undefined && sourceGroupId !== null) {
            yield put(fetchClientsFromGroup(sourceGroupId));
        }
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onMoveClientToGroup() {
    yield takeLatest(moveClientToGroup.type, moveClientToGroupAsync);
}

export function* clientGroupSaga() {
    yield all([
        call(onFetchClientGroups),
        call(onCreateClientGroup),
        call(onUpdateClientGroup),
        call(onDeleteClientGroup),
        call(onFetchClientsFromGroup),
        call(onFetchUngroupedClients),
        call(onFetchUngroupedCount),
        call(onRemoveClientFromGroup),
        call(onAddClientsToGroup),
        call(onMoveClientToGroup)
    ]);
}
