import {useEffect, useState} from "react";
import Toast from "react-bootstrap/Toast";
import {useDispatch, useSelector} from "react-redux";
import {selectToasts} from "../../store/toast/toastSelector";
import {removeToast} from "../../store/toast/toastReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from './locales/pt-pt.json'
import {ToastContainer} from "react-bootstrap";
import {isDesktop, isTablet} from "react-device-detect";

export default function ToastComponent() {
    const dispatch = useDispatch();
    const toasts = useSelector(selectToasts);
    const {t} = useTranslation();
    const [position, setPosition] = useState("top-center")
    useComponentTranslations('toast', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const defaultToast = {
        autohide: true,
        delay: 5000,
        type: "danger",
        actionButton: false,
        title: t("toast:title"),
        message: t("toast:message"),
        handleClick: null
    };

    const getToastIcon = (type) => {
        switch (type) {
            case "primary":
                return <i className={`fa-regular fa-2x fa-info-circle text-${type}`}></i>;
            case "danger":
                return <i className={`fa-regular fa-2x fa-times-circle text-${type}`}></i>;
            case "warning":
                return <i className={`fa-regular fa-2x fa-exclamation-triangle text-${type}`}></i>;
            case "success":
                return <i className={`fa-regular fa-2x fa-check-circle text-${type}`}></i>;
            default:
                return null;
        }
    };

    useEffect(() => {
        if (!isDesktop && !isTablet) {
            setPosition("bottom-center")
        }
        toasts.forEach((toast) => {
            if (toast.autohide) {
                setTimeout(() => dispatch(removeToast(toast.id)), toast.delay);
            }
        });
    }, [toasts, dispatch]);

    return (
        <ToastContainer
            key={Math.random()}
            className="pt-3 pb-4 position-fixed"
            position={`${position}`}
        >
            {toasts.map((toast) => {
                const mergedToast = {...defaultToast, ...toast};
                return (
                    <Toast
                        key={Math.random()}
                        show={true}
                        onClose={() => dispatch(removeToast(mergedToast.id))}
                        delay={mergedToast.delay}
                        autohide={mergedToast.autohide}
                        className={` toast  toast-${mergedToast.type} fade-in-out`}
                        position="top-center"
                        title={mergedToast.title}
                    >
                        <Toast.Body>
                            <div className={"row d-flex"}>
                                <div className={"col-2 align-self-center"}>
                                    {getToastIcon(mergedToast.type)}
                                </div>
                                <div className={"col-10 ps-0"}>
                                    <div className={"row justify-content-between d-flex pb-1"}>
                                        <div className={"col-10 align-self-center "}>
                                            <span className="d-block fw-bold  text-md" style={{lineHeight: "1.1rem"}}>
                                              {mergedToast.title}
                                            </span>
                                        </div>
                                        <div className={"col-2 align-self-center"}>
                                            <button className={"no-style-btn"}
                                                    onClick={() => dispatch(removeToast(mergedToast.id))}>
                                                <i className={"fa-regular  fa-times   text-default"}
                                                   style={{fontSize: "1.1rem"}}></i>
                                            </button>
                                        </div>
                                    </div>
                                    <span className={"d-block text-md "} style={{lineHeight: "1.1rem"}}>
                                          {mergedToast.message}
                                        </span>
                                    {
                                        mergedToast.actionButton && (
                                            <span className={"d-block pt-2"}>
                                                <button onClick={mergedToast.handleClick}
                                                        className={"no-style-btn text-md text-primary-darker"}>
                                                    Clique aqui
                                                </button>
                                            </span>
                                        )
                                    }
                                </div>
                            </div>
                        </Toast.Body>
                    </Toast>
                );
            })}
        </ToastContainer>
    );
}
