export const NEUROMOTOR_RESISTANCE_TYPES = [2, 3];
export const NEUROMOTOR_IMPULSE_TYPES = [4, 5];

export const getNeuromotorPageFromType = (type) =>
    [3, 5].includes(Number(type)) ? "2" : "1";

export const isNeuromotorResistanceType = (type) =>
    NEUROMOTOR_RESISTANCE_TYPES.includes(Number(type));

export const isNeuromotorImpulseType = (type) =>
    NEUROMOTOR_IMPULSE_TYPES.includes(Number(type));

export const hasNeuromotorTabs = (type) =>
    isNeuromotorResistanceType(type) || isNeuromotorImpulseType(type);

export const resolveNeuromotorTypeForPage = (type, page) => {
    const numericType = Number(type);

    if (isNeuromotorResistanceType(numericType)) {
        return page === "2" ? 3 : 2;
    }

    if (isNeuromotorImpulseType(numericType)) {
        return page === "2" ? 5 : 4;
    }

    return numericType;
};
