import {Link, useNavigate} from "react-router-dom";
import {Image} from "react-bootstrap";
import {useTranslation} from "react-i18next";
import ptBR from './locales/pt-br.json';
import enUS from './locales/en-us.json';
import esES from './locales/es-es.json';
import ptPT from './locales/pt-pt.json'
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import {useDispatch, useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";
import {helpMenuSelector, userMenuSelector} from "../../store/menu/menuSelector";
import {toggleHelpMenu, toggleUserMenu} from "../../store/menu/menuReducer";
import {handleSubscriptionButton} from "../../utils/handlers/handler";
import HelpMenu from "./HelpMenu";
import UserMenu from "./UserMenu";

const BottomBar = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const user = useSelector(selectUser)
    const helpMenu = useSelector(helpMenuSelector)
    const userMenu = useSelector(userMenuSelector);

    useComponentTranslations('navbar', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleHelpMenu = () => {
        dispatch(toggleHelpMenu(!helpMenu))
    };

    const handleUserMenu = () => {
        dispatch(toggleUserMenu(!userMenu))
    };

    return (
        <>
            <nav
                className="navbar fixed-bottom   text-white navbar-dark bg-default z-1  "
                style={{height: "80px", paddingTop: "0.5rem"}}>
                <div className="col-12">
                    <div className=" justify-content-between hstack gap-2 px-4">
                        <div className="col-auto">
                            <Link className="text-white text-center no-style-btn" to={'/user'}>
                                <span className="d-block fs-4"><i className="fa-regular fa-house "></i></span>
                                <span className="small">{t("navbar:home")}</span>
                            </Link>
                        </div>
                        <div className="col-auto ">
                            <button className="text-white text-center no-style-btn"
                                    onClick={() => handleSubscriptionButton(navigate)}>
                                <span className="d-block fs-4"><i className="fa-regular fa-circle-dollar"></i></span>
                                <span className="small">{t("navbar:subscription")}</span>
                            </button>
                        </div>
                        <div className="col-auto">
                            <button className="text-white text-center no-style-btn"
                                    onClick={handleHelpMenu}>
                                <span className="d-block fs-4"><i className="fa-regular fa-comments"></i></span>
                                <span className="small">{t("navbar:help")}</span>
                            </button>
                        </div>
                        <div className="col-auto">
                            <button className="text-white text-center no-style-btn pt-1 " onClick={handleUserMenu}>
                                <Image roundedCircle={true} fluid
                                       src={user.urlLogo === "empty" || !user.urlLogo ? "https://cdn.mfitpersonal.com.br/assets/user/user.jpg" : user.urlLogo}
                                       className=" mx-auto d-block"
                                       style={{maxWidth: '26px'}}></Image>
                                <span className="small pt-2 d-block">{t("navbar:profile")}</span>
                            </button>
                        </div>
                    </div>
                </div>
            </nav>
            <HelpMenu/>
            <UserMenu/>
        </>
    )
}

export default BottomBar;