import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    exercise: null,
    answered: false,
    loading: false,

}
export const slice = createSlice({
    name: 'exerciseName',
    initialState,
    reducers: {
        fetchExerciseName(state) {
            state.loading = true;
        },
        setExerciseName(state, action) {
            state.exercise = action.payload;
            state.loading = false;
        },
        saveExerciseName(state) {
            state.loading = true
        },
        setAnswered(state, action) {
            state.answered = action.payload;
            state.loading = false
        },
        onError(state) {
            state.loading = false;
        }
    }
})
export const {fetchExerciseName, setExerciseName, setAnswered, saveExerciseName, onError} = slice.actions;
export const exerciseNameReducer = slice.reducer;