import {useEffect, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {isPushLoading, selectNotifications} from "../../store/push/pushSelector";
import {fetchNotifications} from "../../store/push/pushReducer";
import _ from "lodash";
import Spinner from "../../components/loader/Spinner";
import PushCard from "../../components/push/PushCard";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Page from "../../components/page/Page";
import CardButtonAdd from "../../components/card/CardButtonAdd";

const PushList = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {typeParam} = useParams();
    const [type, setType] = useState(typeParam === "recurring" ? "recurring" : "scheduled");
    const notifications = useSelector(selectNotifications)
    const loading = useSelector(isPushLoading)
    useComponentTranslations('pushPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const goBackLink = () => {
        navigate("/user")
    }

    const handleType = (type) => {
        setType(type);
    }

    const handleCreatePush = () => {
        navigate("/user/push/create")
    }

    useEffect(() => {
        dispatch(fetchNotifications(type))
    }, [dispatch, type])

    return (
        <Page title={t(`pushPage:notifications`)} goBackLink={goBackLink} loading={loading}>
            <div className={'card card-body'}>
                <div className={'row justify-content-center d-flex mb-2'}>
                    <div className={'col-12'}>
                        <CardButtonAdd handleClick={handleCreatePush} text={t(`pushPage:createNotification`)}/>
                    </div>
                </div>
                <div className={'row justify-content-center d-flex mb-2 pt-2'}>
                    <div className={'col-12'}>
                        <span className={'fw-semibold '}>{t(`pushPage:notificationList`)}</span>
                    </div>
                    <div className={'col-12 pt-1'}>
                        <div className={'row g-2'}>
                            <div className={'col-6'}>
                                <div className={'d-grid'}>
                                    <button onClick={() => handleType("scheduled")}
                                            className={`btn btn-${type === "scheduled" ? '' : 'outline-'}primary`}><i
                                        className={'fa-regular fa-calendar-lines-pen'}></i> {t(`pushPage:scheduled`)}
                                    </button>
                                </div>
                            </div>
                            <div className={'col-6'}>
                                <div className={'d-grid'}>
                                    <button onClick={() => handleType("recurring")}
                                            className={`btn btn-${type === "scheduled" ? 'outline-' : ''}primary`}><i
                                        className={'fa-regular fa-calendar-clock'}></i> {t(`pushPage:recurring`)}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div className={'row justify-content-center d-flex mb-2 pt-2'}>
                    <div className={'col-12  '}>
                        {
                            notifications && notifications.length > 0 &&
                            _.map(notifications, (notification) => (
                                <PushCard notification={notification} key={notification.id}/>
                            ))
                        }
                        {
                            (!notifications || notifications.length === 0) &&
                            <>
                                {
                                    type === "scheduled" ?
                                        <span>{t(`pushPage:emptyListScheduled`)}</span>
                                        :
                                        <span>{t(`pushPage:emptyListRecurring`)}</span>
                                }
                            </>
                        }
                        {
                            loading &&
                            <Spinner/>
                        }
                    </div>
                </div>
            </div>

        </Page>
    )
}

export default PushList;