import Modal from "react-bootstrap/Modal";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useRef, useState} from "react";

const MAX_SIZE = 20 * 1024 * 1024;

const SelectFilesModal = ({showModal, hideModal, onFileSelect}) => {
    const {t} = useTranslation();
    useComponentTranslations('filesComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const [error, setError] = useState(null);
    const inputRef = useRef();

    const onChoose = () => {
        setError(null);
        inputRef.current.click();
    };

    const handleChange = (e) => {
        const f = e.target.files[0];
        if (!f) return;

        if (f.size > MAX_SIZE) {
            setError(t("filesComponent:sizeExceeded"));
            return;
        }
        onFileSelect(f);
        hideModal();
    };

    const onClose = () => {
        setError(null);
        hideModal();
    };

    return (
        <Modal show={showModal} onHide={hideModal} centered>
            <Modal.Body>
                <div className={"row "}>
                    <div className={"col-12"}>
                        <input
                            type="file"
                            ref={inputRef}
                            hidden
                            onChange={handleChange}
                        />
                    </div>


                    <div className={"col-12"}>
                        <div className={'row justify-content-between pb-3'}>
                            <div className={'col-auto'}>
                                <span className={"fw-semibold text-start fs-5"}>{t("filesComponent:selectFile")}</span>
                            </div>
                            <div className={'col-auto cursor-pointer'} onClick={hideModal}>
                                <i className="fa-regular fa-times"/>
                            </div>
                        </div>
                        <div className={'row justify-content-between '}>
                            <div className={'col-12 text-center'}>
                                {
                                    error ?
                                        <span className={"text-danger"}>{error}</span> :
                                        <span>{t("filesComponent:sizeMax")}</span>
                                }
                            </div>
                        </div>
                        <div className={'row justify-content-between '}>
                            <div className={'col-12'}>
                                <button
                                    className={"btn btn-primary d-block w-100 mt-3"}
                                    onClick={onChoose}
                                >
                                    <i className={"fa-regular fa-upload me-1"}/>
                                    {t("filesComponent:chooseFile")}
                                </button>
                            </div>
                            <div className={'col-12'}>
                                <button className={"btn btn-outline-primary d-block w-100 mt-2"} onClick={onClose}>
                                    {t("filesComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </Modal.Body>
        </Modal>
    )
}
export default SelectFilesModal;