import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useCallback, useEffect, useState} from "react";
import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useLocation, useNavigate, useParams} from "react-router-dom";
import {fetchClient} from "../../store/client/clientReducer";
import {selectWorkoutGenerating, selectWorkoutSession, selectWorkoutSessionLoading} from "../../store/workout-prescription/workoutPrescriptionSelector";
import {changeExerciseOrder, combineExercises, fetchWorkoutSession, deleteMultipleExercises} from "../../store/workout-prescription/workoutPrescriptionReducer";
import WorkoutSessionOptionCard from "../../components/workout-prescription/WorkoutSessionOptionCard";
import WorkoutSessionInstructions from "../../components/workout-prescription/WorkoutSessionInstructions";
import {closestCenter, DndContext, PointerSensor, useSensor, useSensors} from "@dnd-kit/core";
import {arrayMove, SortableContext, verticalListSortingStrategy} from "@dnd-kit/sortable";
import SortableWorkoutExerciseCard from "../../components/workout-prescription/SortableWorkoutExerciseCard";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EmptySet from "../../components/empty-set/EmptySet";
import Modal from "react-bootstrap/Modal";
import WorkoutSessionAiForm from "../../components/workout-prescription/WorkoutSessionAiForm";
import {addToast} from "../../store/toast/toastReducer";
import Text from "../../components/utils/emoji/Text";
import LoadingBlock from "../../components/loader/LoadingBlock";
import moment from "moment/moment";
import {selectWorkoutRoutine} from "../../store/workout-routine/workoutRoutineSelector";
import {fetchWorkoutRoutine} from "../../store/workout-routine/workoutRoutineReducer";
import {getWaiting} from "../../store/ai-actions/aiActionsSelector";
import {setGeneratedWorkout} from "../../store/ai-actions/aiActionsReducer";
import {OverlayTrigger, Popover} from "react-bootstrap";

const WorkoutRoutinePrescription = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const location = useLocation();
    const {id, clientId, sessionId, feedbacks} = useParams()
    const isLibrary = Number(clientId) === 0;
    const client = useSelector(selectSelectedClient)
    const session = useSelector(selectWorkoutSession)
    const [exercises, setExercises] = useState([]);
    const loading = useSelector(selectWorkoutSessionLoading)
    const [expandAll, setExpandAll] = useState(false)
    const [expandedMap, setExpandedMap] = useState({})
    const [showOptions, setShowOptions] = useState(false);
    const [selectedSessions, setSelected] = useState([]);
    const [showIaModal, setShowIaModal] = useState(false);
    const waitingIa = useSelector(getWaiting);
    const generatingWorkout = useSelector(selectWorkoutGenerating);


    const removeSelected = id =>
        setSelected(prev => prev.filter(x => x !== id));
    const workout = useSelector(selectWorkoutRoutine);
    const [show, setShow] = useState(false);
    useComponentTranslations('trainingPrescription', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        if (feedbacks) {
            navigate("/user/feedback")
        } else
            navigate(`/user/client/${isLibrary ? 0 : clientId}/workout/routine/${id}`)
    }

    const handleAddExercise = useCallback(() => {
        navigate(`/user/client/${isLibrary ? 0 : clientId}/workout/routine/${id}/session/${sessionId}/exercise-list`)
    }, [navigate, clientId, id, isLibrary, sessionId])

    const handleGoToPresets = useCallback(() => {
        navigate("/user/workout-presets", {
            state: {
                backTo: `${location.pathname}${location.search}${location.hash}`
            }
        });
    }, [location.hash, location.pathname, location.search, navigate]);

    const handleExpandAll = () => {
        setExpandedMap(prev => {
            const allExpanded = Object.values(prev).every(v => v);
            const newValue = !allExpanded;
            const updated = {};
            Object.keys(prev).forEach(k => {
                updated[k] = newValue;
            });
            setExpandAll(newValue);
            return updated;
        });
    }

    const toggleExpanded = id => {
        setExpandedMap(prev => {
            const updated = {...prev, [id]: !prev[id]};
            setExpandAll(Object.values(updated).every(v => v));
            return updated;
        });
    }
    const handleShowIaModal = () => {
        dispatch(setGeneratedWorkout(null))
        setShowIaModal(prevState => !prevState)
    }

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 5,
            },
        })
    );

    const handleDragEnd = (event) => {
        const {active, over} = event;
        let newIndex = 0;
        let oldIndex = 0;
        if (!over) return;
        if (active.id !== over.id) {
            setExercises((items) => {
                oldIndex = items.findIndex((item) => item.id === active.id);
                newIndex = items.findIndex((item) => item.id === over.id);
                return arrayMove(items, oldIndex, newIndex);
            });
        }
        const payload = {
            session: session.id,
            idExercSession: exercises[oldIndex].exerciseArray[0].idExercSession,
            pos: newIndex,

        }
        dispatch(changeExerciseOrder(payload))
    };

    const handleDragStart = () => {
        if (expandAll)
            handleExpandAll()
    }


    const collapseAll = () => {
        setExpandedMap(prev => {
            const updated = {};
            Object.keys(prev).forEach(k => {
                updated[k] = false;
            });
            return updated;
        });
        setExpandAll(false);
    };


    const handleCombine = () => {
        if (selectedSessions.length > 1) {
            const payload = {
                sessionId: sessionId,
                targetSessions: selectedSessions
            }
            setSelected([])
            dispatch(combineExercises(payload));
        } else {
            dispatch(addToast({
                title: t("trainingPrescription:warning"),
                message: t("trainingPrescription:selectAtLeastTwo"),
                type: "warning"
            }))
        }
    };

    const handleDeleteSelected = () => {
        if (selectedSessions.length > 0) {
            const payload = {
                sessionId: sessionId,
                exercs: selectedSessions,
            };
            setSelected([]);
            dispatch(deleteMultipleExercises(payload));
        }
    };

    const pop = (
        <Popover id="combine-popover" className="bg-primary-subtle text-white border-primary-subtle">
            <Popover.Body className={"text-primary"} style={{padding: "6px 10px", fontSize: "0.875rem"}}>
                {t("trainingPrescription:alreadyCombined")}
            </Popover.Body>
        </Popover>
    );

    useEffect(() => {
        if ((!client || client.id !== Number(clientId)) && !isLibrary)
            dispatch(fetchClient(clientId))
    }, [dispatch, clientId, client, isLibrary]);

    useEffect(() => {
        if (!workout && session) {
            dispatch(fetchWorkoutRoutine(session.idRoutine))
        }
    }, [workout, dispatch, session]);

    useEffect(() => {
        dispatch(fetchWorkoutSession(sessionId))
    }, [dispatch, sessionId]);

    useEffect(() => {
        if (session?.exerciciosMontados) {
            const exercisesData = Array.isArray(session.exerciciosMontados)
                ? session.exerciciosMontados
                : Object.values(session.exerciciosMontados);

            const backendMap = {};
            exercisesData.forEach(exercise => {
                const id = exercise[0]?.idExercSession;
                if (id !== undefined) backendMap[id] = exercise;
            });

            const currentIds = exercises.map(item => item.exerciseArray[0]?.idExercSession);
            const backendIds = Object.keys(backendMap).map(id => Number(id));
            const sameIds =
                currentIds.length === backendIds.length &&
                currentIds.every(id => backendIds.includes(id));

            if (exercises.length === 0 || !sameIds) {
                const initialExercises = exercisesData.map((exercise, index) => ({
                    id: index.toString(),
                    exerciseArray: exercise,
                }));
                setExercises(initialExercises);
                const map = {};
                initialExercises.forEach(item => {
                    map[item.id] = expandAll;
                });
                setExpandedMap(map);
            } else {
                setExercises(prev =>
                    prev.map(item => ({
                        ...item,
                        exerciseArray:
                            backendMap[item.exerciseArray[0]?.idExercSession] || item.exerciseArray,
                    }))
                );
                setExpandedMap(prev => {
                    const map = {...prev};
                    exercisesData.forEach((_, index) => {
                        const id = index.toString();
                        if (!(id in map)) map[id] = expandAll;
                    });
                    return map;
                });
            }
        } else {
            setExercises([]);
            setExpandedMap({});
        }
        // eslint-disable-next-line
    }, [session?.exerciciosMontados]);

    useEffect(() => {
        setExpandedMap(prev => {
            const map = {...prev};
            exercises.forEach(item => {
                if (!(item.id in map)) map[item.id] = expandAll;
            });
            Object.keys(map).forEach(id => {
                if (!exercises.find(e => e.id === id)) delete map[id];
            });
            setExpandAll(Object.values(map).length > 0 && Object.values(map).every(v => v));
            return map;
        });
    }, [exercises, expandAll, setExpandAll]);

    useEffect(() => {
        setSelected(prev =>
            prev.filter(id =>
                exercises.some(item =>
                    item.exerciseArray.some(ex => ex.idExercSession === id)
                )
            )
        );
    }, [exercises]);

    useEffect(() => {
        if (selectedSessions && selectedSessions.length > 0) {
            setShowOptions(true)
            collapseAll()
        } else setShowOptions(false)

    }, [setShowOptions, selectedSessions])

    const selectedExercisesData = selectedSessions
        .map(idSel =>
            exercises.find(item =>
                item.exerciseArray.some(ex => ex.idExercSession === idSel)
            )
        )
        .filter(Boolean);

    const isAnySelectedCombined = selectedExercisesData.some(item =>
        item.exerciseArray.some(ex => ex?.isCombinado)
    );

    const canCombine =
        selectedSessions.length > 0 && !isAnySelectedCombined;

    return (
        <>
            {
                !isLibrary &&
                <AvatarHeader className={"pb-4 pt-2"}
                              xl={"5"}
                              text={`${client?.nome} ${client?.sobrenome}`}
                              url={client?.profileUrl} showGoBack={handleGoBack}/>
            }
            {
                !loading && !session &&
                <Page contentHeader={isLibrary} loading={loading} mt={"mt-n4"} xl={"5"} goBackLink={handleGoBack}>
                    <div className={"row justify-content-between"}>
                        <div className={"col-12"}>
                            <div className={"card card-body border-0"}>
                                <EmptySet icon={"fa-regular fa-trash-can"} message={t("trainingPrescription:deletedSession")}/>
                            </div>
                        </div>
                    </div>
                </Page>
            }
            {
                !loading && session &&
                <Page contentHeader={isLibrary} loading={loading} mt={"mt-n4"} xl={"5"} goBackLink={handleGoBack}>
                    <div className={"row justify-content-between"}>
                        <div className={"col-12"}>
                            <WorkoutSessionOptionCard sessionId={sessionId} id={id} clientId={clientId} handleShowIaModal={handleShowIaModal}/>
                        </div>
                        {
                            session?.obs &&
                            <div className={"col-12 mt-2"}>
                                <WorkoutSessionInstructions instructions={session?.obs} sessionId={sessionId}/>
                            </div>
                        }
                        <div className={"col-12 mt-2"}>
                            <div className={"row justify-content-end"}>
                                {
                                    showOptions &&
                                    <>
                                        <div className={"col-6 pe-1"}>
                                            <OverlayTrigger
                                                trigger={canCombine ? [] : "click"}
                                                placement="top"
                                                show={show}
                                                onToggle={setShow}
                                                overlay={pop}
                                                rootClose
                                            >
                                                <button
                                                    className={`btn btn-outline-primary w-100 `}
                                                    onClick={() => {
                                                        if (canCombine) {
                                                            handleCombine();
                                                        }
                                                    }}
                                                >
                                                    {t("trainingPrescription:combine")}
                                                </button>
                                            </OverlayTrigger>
                                        </div>
                                        <div className={`col-6 ps-1  `}>
                                            <button className={`btn btn-outline-danger  w-100`} onClick={handleDeleteSelected}>
                                                {t("trainingPrescription:delete")}
                                            </button>
                                        </div>

                                    </>
                                }
                                {
                                    !showOptions &&
                                    <>
                                        <div className={"col-6 pe-1"}>
                                            <button className={"btn btn-outline-primary w-100"} onClick={handleGoToPresets}>
                                                {t("trainingPrescription:presets")}
                                            </button>
                                        </div>
                                        <div className={"col-6 ps-1"}>
                                            <button className={"btn btn-primary w-100"} onClick={handleAddExercise}>{t("trainingPrescription:addExercise")}</button>
                                        </div>
                                    </>
                                }
                            </div>
                        </div>
                    </div>
                    <div className="row justify-content-center">
                        <div className={"col-12 pt-2"}>
                            {
                                workout?.diaTipo === 2 ?
                                    <span className={"fw-semibold"}>{t("trainingPrescription:workout")} {session.diaTipo} </span> :
                                    <span className={"fw-semibold text-capitalize"}>{moment().day(session.diaTipo - 1).format('dddd')} </span>
                            }
                        </div>
                        {
                            !loading && exercises.length !== 0 &&
                            <div className="col-12 pt-1">
                                <div className={'card card-body border-0'}>
                                    <div className={"row justify-content-between"}>
                                        <div className={"col-auto align-self-center"}>
                                        <span className={"fw-semibold"}>
                                            <Text>{session?.nome}</Text>
                                        </span>
                                        </div>
                                        <div className={"col-auto align-self-center clickable-element"} onClick={handleExpandAll}>
                                             <span className={"fw-semibold small text-primary"}>
                                                 {
                                                     expandAll &&
                                                     <span>{t("trainingPrescription:minimizeAll")} <i className={`fa-regular  fa-chevron-up `}></i></span>
                                                 }
                                                 {
                                                     !expandAll &&
                                                     <span>{t("trainingPrescription:expandAll")} <i className={`fa-regular  fa-chevron-down `}></i></span>
                                                 }
                                             </span>
                                        </div>
                                        <div className={"col-12 mt-4"}>
                                            <DndContext
                                                sensors={sensors}
                                                collisionDetection={closestCenter}
                                                onDragEnd={handleDragEnd}
                                                onDragPending={handleDragStart}
                                            >
                                                <SortableContext items={exercises} strategy={verticalListSortingStrategy}>
                                                    {exercises.map((item) =>
                                                        <SortableWorkoutExerciseCard
                                                            key={item.id}
                                                            id={item.id}
                                                            exerciseArray={item.exerciseArray}
                                                            expanded={!!expandedMap[item.id]}
                                                            onToggleExpand={() => toggleExpanded(item.id)}
                                                            exercises={exercises}
                                                            selected={selectedSessions.includes(
                                                                item.exerciseArray[0].idExercSession
                                                            )}
                                                            toggleSelect={sessionId =>
                                                                setSelected(prev =>
                                                                    prev.includes(sessionId)
                                                                        ? prev.filter(x => x !== sessionId)
                                                                        : [...prev, sessionId]
                                                                )
                                                            }
                                                            deselect={removeSelected}
                                                        />
                                                    )}
                                                </SortableContext>
                                            </DndContext>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        }
                        {
                            !loading && exercises.length === 0 &&
                            <div className={"col-12"}>
                                <div className={"card card-body border-0"}>
                                    <EmptySet icon={"fa-dumbbell"} message={t("trainingPrescription:startAddingExercises")}/>
                                    <div className={"row justify-content-center"}>
                                        <div className={"col-12"}>
                                            <div className={"d-grid"}>
                                                <button className={"btn btn-primary"} onClick={handleAddExercise}>
                                                    {t("trainingPrescription:addManually")}
                                                </button>
                                            </div>
                                        </div>
                                        <div className={"col-12 mt-2"}>
                                            <div className={"d-grid"}>
                                                <button className={"btn   text-mfit-ai border border-1 border-primary bg-mfit-ai-subtle"}
                                                        onClick={handleShowIaModal}>
                                                    {t("trainingPrescription:prescribeWith")} <i className={"fa-kit fa-mfit-ai text-mfit-ai-gradient"}></i>
                                                    <span
                                                        className={"fw-bold text-mfit-ai-gradient"}>MFIT</span><span
                                                    className={"fw-light text-mfit-ai-gradient"}>IA</span>
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        }
                        <Modal centered show={showIaModal}>
                            <Modal.Body>
                                <WorkoutSessionAiForm handleClose={handleShowIaModal}/>
                                {
                                    !generatingWorkout && !waitingIa &&
                                    <div className={"d-grid mt-2"}>
                                        <button className={"btn  btn-link  text-mfit-ai-gradient "} onClick={handleShowIaModal}>
                                            {t("trainingPrescription:close")}
                                        </button>
                                    </div>
                                }
                            </Modal.Body>
                        </Modal>
                    </div>
                </Page>
            }
            {
                loading &&
                <LoadingBlock/>
            }
        </>
    )
}

export default WorkoutRoutinePrescription;
