import {addToast} from "../../store/toast/toastReducer";
import i18n from "../../i18n";

export const ensureErrorResources = () => undefined;

const getTranslatedErrorMessage = (errorCode, fallbackMessage) => {
    if (errorCode && i18n.exists(`sagaError:${errorCode}`)) {
        return i18n.t(`sagaError:${errorCode}`);
    }

    if (fallbackMessage && i18n.exists(`sagaError:${fallbackMessage}`)) {
        return i18n.t(`sagaError:${fallbackMessage}`);
    }

    return fallbackMessage;
};

export const normalizeApiError = (error) => {
    const originalError = error?.originalError || error;
    const status = error?.status ?? originalError?.response?.status ?? null;
    const data = error?.data || originalError?.response?.data || {};
    const transportCode = error?.code || originalError?.code || null;
    const backendCode = data?.code || data?.errorCode || data?.errorMessage;
    const backendMessage = data?.message || data?.errorMessage;

    return {
        status,
        code: backendCode || transportCode || null,
        message: backendMessage || null,
        data,
        originalError
    };
};

export const buildApiErrorToastPayload = (error) => {
    const normalizedError = normalizeApiError(error);
    const {
        status,
        message,
        data,
        originalError
    } = normalizedError;
    const transportCode = originalError?.code;
    const backendCode = data?.code || data?.errorCode || data?.errorMessage;
    const backendMessage = message;

    if (transportCode === "ERR_NETWORK") {
        return {
            title: i18n.t("sagaError:internetErrorTitle"),
            message: i18n.t("sagaError:internetErrorMessage"),
            delay: 10000,
        };
    }

    if (transportCode === "ECONNABORTED") {
        return {
            title: i18n.t("sagaError:slowInternetTitle"),
            message: i18n.t("sagaError:slowInternetMessage"),
            delay: 10000,
        };
    }

    if (status === 413) {
        return {
            title: i18n.t("sagaError:genericErrorTitle"),
            message: i18n.t("sagaError:imageTooBig"),
            delay: 10000,
        };
    }

    if (status === 400) {
        return {
            title: i18n.t("sagaError:validationErrorTitle"),
            message: getTranslatedErrorMessage(backendCode, backendMessage) || i18n.t("sagaError:validationErrorMessage"),
            delay: 10000,
        };
    }

    if (status === 401 || status === 403) {
        return {
            title: i18n.t("sagaError:authorizationErrorTitle"),
            message: getTranslatedErrorMessage(backendCode, backendMessage) || i18n.t("sagaError:authorizationErrorMessage"),
            delay: 10000,
        };
    }

    if (status === 404) {
        return {
            title: i18n.t("sagaError:notFoundErrorTitle"),
            message: getTranslatedErrorMessage(backendCode, backendMessage) || i18n.t("sagaError:notFoundErrorMessage"),
            delay: 10000,
        };
    }

    if (status === 409) {
        return {
            title: i18n.t("sagaError:conflictErrorTitle"),
            message: getTranslatedErrorMessage(backendCode, backendMessage) || i18n.t("sagaError:conflictErrorMessage"),
            delay: 10000,
        };
    }

    return {
        title: i18n.t("sagaError:genericErrorTitle"),
        message: getTranslatedErrorMessage(backendCode, backendMessage) || i18n.t("sagaError:genericErrorMessage"),
        delay: 10000,
    };
};

export const dispatchApiErrorToast = (dispatch, error) => {
    dispatch(addToast(buildApiErrorToastPayload(error)));
};
