import {useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate} from "react-router-dom";
import Page from "../../components/page/Page";
import LoadingBlock from "../../components/loader/LoadingBlock";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {setRetentionChartFilters} from "../../store/retention/retentionReducer";
import {selectRetentionChartFilters} from "../../store/retention/retentionSelector";
import {
    RETENTION_METRIC_OPTIONS,
    RETENTION_PERIOD_OPTIONS,
    formatDelta,
    formatMetricValue,
    formatRetentionDateRange,
    getRetentionMetricMeta,
    getRetentionPeriodLabel
} from "../../components/retention/retentionConfig";
import RetentionLineChart from "../../components/retention/RetentionLineChart";
import RetentionChartComparisonInfoOffcanvas from "../../components/retention/RetentionChartComparisonInfoOffcanvas";
import useRetentionAccessEvent from "../../components/retention/useRetentionAccessEvent";
import {useRetentionChartQuery} from "../../store/retention/retentionApi";

const RetentionCharts = () => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();

    const chartFilters = useSelector(selectRetentionChartFilters);
    const [showComparisonInfo, setShowComparisonInfo] = useState(false);

    const locale = i18n.language || "pt-BR";
    const {metric, period} = chartFilters;
    const {data: chart, isLoading: loading} = useRetentionChartQuery(chartFilters);

    useComponentTranslations("retention", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    useRetentionAccessEvent();

    const metricMeta = getRetentionMetricMeta(metric, t);
    const showComparison = Boolean(chart?.hasComparisonData);

    const handleGoBack = () => {
        navigate("/user/retention");
    };

    return (
        <Page title={t("retention:charts")} goBackLink={handleGoBack} mt={"mt-n5"}>
            <div className={"card card-body border-0"}>
                <div className={"row"}>
                    <div className={"col-6"}>
                        <select className={"form-control"} value={metric} onChange={(event) => dispatch(setRetentionChartFilters({
                            metric: event.target.value
                        }))}>
                            {RETENTION_METRIC_OPTIONS.map((option) => (
                                <option key={option} value={option}>
                                    {getRetentionMetricMeta(option, t).label}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className={"col-6"}>
                        <select className={"form-control"} value={period} onChange={(event) => dispatch(setRetentionChartFilters({
                            period: event.target.value
                        }))}>
                            {RETENTION_PERIOD_OPTIONS.map((option) => (
                                <option key={option} value={option}>
                                    {getRetentionPeriodLabel(option, t)}
                                </option>
                            ))}
                        </select>
                    </div>
                </div>

                {loading && <LoadingBlock height={"320px"}/>}

                {!loading && chart && (
                    <>
                        <div className={"text-center mt-4"}>
                            <span className={"small text-secondary d-block"}>
                                <i className={`${metricMeta.icon} me-2`}></i>
                                {metricMeta.label}
                            </span>
                            <span className={"fw-bold fs-1 d-block mt-2"}>
                                {formatMetricValue(metric, chart.value, locale)}
                            </span>
                            {showComparison && (
                                <>
                                    <span className={"d-inline-flex align-items-center justify-content-center gap-2 mt-2"}>
                                    <span className={`fw-semibold ${Number(chart.deltaPct || 0) >= 0 ? "text-success" : "text-danger"}`}>
                                        {formatDelta(chart.deltaPct, locale)}
                                    </span>
                                    <button
                                        className={"btn btn-link text-decoration-none text-secondary p-0 border-0"}
                                        type={"button"}
                                        title={t("retention:chartComparisonHelpTitle")}
                                        aria-label={t("retention:chartComparisonHelpTitle")}
                                        onClick={() => setShowComparisonInfo(true)}
                                    >
                                        <i className={"fa-regular fa-circle-info"}></i>
                                    </button>
                                </span>
                                    <span className={"small text-secondary d-block mt-1"}>
                                        {t("retention:chartComparedToPreviousEquivalentPeriod")}
                                    </span>
                                </>
                            )}
                            <span className={`small text-secondary d-block ${showComparison ? "mt-2" : "mt-3"}`}>
                                {formatRetentionDateRange(chart.referenceStart, chart.referenceEnd, locale)}
                            </span>
                        </div>
                        <div className={"mt-4"}>
                            <RetentionLineChart
                                buckets={chart.buckets || []}
                                metric={metric}
                                locale={locale}
                            />
                        </div>
                    </>
                )}
            </div>

            <RetentionChartComparisonInfoOffcanvas
                show={showComparisonInfo}
                onHide={() => setShowComparisonInfo(false)}
                chart={chart}
                metric={metric}
                locale={locale}
                t={t}
            />
        </Page>
    );
};

export default RetentionCharts;
