import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import {selectTransaction} from "../../store/subscription/subscriptionSelector";
import {useEffect, useState} from "react";
import {setTransaction} from "../../store/subscription/subscriptionReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";


const SubscriptionPaymentFailed = () => {
    const {t} = useTranslation();
    const {couponName, subId} = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch()
    const transaction = useSelector(selectTransaction);
    const [cardError, setCardError] = useState(null);
    useComponentTranslations('subscriptionPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handlePixClick = () => {
        if (couponName)
            navigate(`/subscription/purchase/${subId}/type/pix/coupon/${couponName}`)
        else
            navigate(`/subscription/purchase/${subId}/type/pix`)
    }

    const goBackLink = () => {
        navigate(`/subscription/purchase/${subId}`)
    }
    const handleTryAnotherCard = () => {
        navigate(`/subscription/payment/${subId}`)
    }

    useEffect(() => {
        if (!cardError && transaction) {
            setCardError(transaction?.error?.message_display)
        } else {
            dispatch(setTransaction(null))
        }
    }, [cardError, transaction, dispatch]);

    return (
        <Page mt="mt-n4" goBackLink={goBackLink}>
            <div className={"row"}>
                <div className={"col-12"}>
                    <div className={"card card-body border-0"}>
                        <div className={"row justify-content-center"}>
                            <div className={"col-12 text-center mt-4 mb-4"}>
                                <RoundedIcon size={"lg"} icon={"fa-times"} bgColor={"bg-danger-subtle"} textColor={"text-danger"}/>
                            </div>
                            <div className={"col-12 text-center  "}>
                                <h2 className={"fw-semibold"}>{t("subscriptionPage:paymentDeclined")}</h2>
                                <p className={"d-block pt-2"}>{cardError}</p>
                            </div>
                            <div className={"col-12 text-center  "}>
                                <button className={"btn btn-primary-lighter w-100"} onClick={handlePixClick}>{t("subscriptionPage:payWithPix")}</button>
                            </div>
                            <div className={"col-12 text-center mt-2  "}>
                                <button className={"btn btn-outline-primary-lighter w-100"} onClick={handleTryAnotherCard}>{t("subscriptionPage:tryAnotherCard")}</button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </Page>
    )
}
export default SubscriptionPaymentFailed;