import {createSelector} from "reselect";

const reducer = state => state.anamnesis;

export const getModelsList = createSelector([reducer], slice => slice.modelsList);
export const getAnamnesisList = createSelector([reducer], slice => slice.anamnesisList);
export const selectAnamnesis = createSelector([reducer], slice => slice.anamnesis);
export const isAnamnesisLoading = createSelector([reducer], slice => slice.initialLoading);
export const isSubmitLoading = createSelector([reducer], slice => slice.submitLoading);
export const getSubmitResult = createSelector([reducer], slice => slice.submitResult);
