import React from 'react';
import {useTranslation} from "react-i18next";
import EvaluationOptionsModal from "../evaluation-components/EvaluationOptionsModal";
import ShareModal from "../modal/ShareModal";
import DeleteModal from "../modal/DeleteModal";
import {isDesktop} from "react-device-detect";
import PhysicalEvaluationMenuModal from "./PhysicalEvaluationMenuModal";
import {protocolData} from "../../utils/physicalEvaluation/protocolData";
import PhysicalEvaluationMenu from "./PhysicalEvaluationMenu";

export default function PhysicalActionsButtons({state, handlers, shareLink}) {
    const {t} = useTranslation();

    return (
        <>
            {isDesktop ? (
                <PhysicalEvaluationMenuModal show={state.showPhysicalMenu} onHide={handlers.closePhysicalMenu}
                                             protocols={protocolData}
                                             onSelect={handlers.createNew}
                />
            ) : (
                <PhysicalEvaluationMenu show={state.showPhysicalMenu} onHide={handlers.closePhysicalMenu}
                                        handleBack={handlers.goBackPage}
                                        handleGoForm={handlers.createNew}/>
            )}
            <EvaluationOptionsModal
                show={state.showOptions}
                onClose={handlers.closeOptionsModal}
                onOpen={handlers.goView}
                onShare={handlers.openShareModal}
                onEdit={handlers.goEdit}
                onDelete={handlers.openDeleteModal}
                title={t('physicalEvaluation:whatYouWant')}
                openLabel={t('physicalEvaluation:open')}
                shareLabel={t('physicalEvaluation:share')}
                editLabel={t('physicalEvaluation:edit')}
                deleteLabel={t('physicalEvaluation:delete')}
            />
            <ShareModal
                show={state.showShare}
                onClose={handlers.closeShareModal}
                link={shareLink}
                onSend={handlers.sendWhatsApp}
                onCopy={handlers.copyLink}
                shareTitle={t('physicalEvaluation:shareTitle')}
                sendLabel={t('physicalEvaluation:send')}
                copyLabel={t('physicalEvaluation:copyLink')}
                closeLabel={t('physicalEvaluation:close')}
            />
            <DeleteModal
                show={state.showDelete}
                onClose={handlers.closeDeleteModal}
                onConfirm={handlers.confirmDelete}
                deleteTitle={t('physicalEvaluation:deleteTitle')}
                confirmLabel={t('physicalEvaluation:confirm')}
                closeLabel={t('physicalEvaluation:close')}
                isSubmitting={state.deleteSubmitting}
            />
        </>
    );
}
