import {takeLatest, all, call, put} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    answerCsat, checkPendingChargeback, checkPendingCsat, csatAnswered, onError, setPendingChargeback, setPendingCsat, setPermission, checkPermission, skipCsat,
    setBlocked, checkUserBlocked, checkBadPassword, setBadCheckPassword, checkSpointUser, setSpointUser
} from "./checkReducer";
import {
    answerCsatAPI, checkBadPasswordAPI,
    checkBlockedUserAPI,
    checkPendingChargebackAPI,
    checkPendingCsatAPI,
    checkPermissionAPI,
    checkSpointUserAPI,
    skipCsatAPI
} from "../../api/check/checkActions";

export function* skipCsatAsync() {
    try {
        yield call(skipCsatAPI);
        yield put(csatAnswered())
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onSkipCsat() {
    yield takeLatest(skipCsat.type, skipCsatAsync);
}

export function* answerCsatAsync(action) {
    try {
        yield call(answerCsatAPI, action.payload);
        yield put(csatAnswered())
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onAnswerCsat() {
    yield takeLatest(answerCsat.type, answerCsatAsync);
}

export function* checkPendingCsatAsync() {
    try {
        const response = yield call(checkPendingCsatAPI);
        yield put(setPendingCsat(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCheckPendingCsat() {
    yield takeLatest(checkPendingCsat.type, checkPendingCsatAsync);
}

export function* checkPendingChargebackAsync() {
    try {
        const response = yield call(checkPendingChargebackAPI);
        yield put(setPendingChargeback(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCheckPendingChargeback() {
    yield takeLatest(checkPendingChargeback.type, checkPendingChargebackAsync);
}

export function* checkSpointUserAsync() {
    try {
        const response = yield call(checkSpointUserAPI);
        yield put(setSpointUser(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCheckSpointUser() {
    yield takeLatest(checkSpointUser.type, checkSpointUserAsync);
}

export function* checkPermissionAsync() {
    try {
        const response = yield call(checkPermissionAPI)
        yield put(setPermission(response.data))
    } catch (error) {
        yield put(setPermission("ERROR"));
    }
}

export function* onCheckPermission() {
    yield takeLatest(checkPermission.type, checkPermissionAsync);
}

export function* checkBlockedUserAsync() {
    try {
        const response = yield call(checkBlockedUserAPI)
        yield put(setBlocked(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCheckUserBlocked() {
    yield takeLatest(checkUserBlocked.type, checkBlockedUserAsync);
}

export function* onCheckBadPasswordAsync() {
    try {
        yield call(checkBadPasswordAPI)
        yield put(setBadCheckPassword(false))
    } catch (error) {
        console.log(error)
        if (error.response.status === 401) {
            yield put(setBadCheckPassword(true))
        } else
            yield call(handleError, error, onError)
    }
}

export function* onCheckBadPassword() {
    yield takeLatest(checkBadPassword.type, onCheckBadPasswordAsync)
}

export function* checkSaga() {
    yield all([
        call(onCheckPendingCsat),
        call(onCheckPendingChargeback),
        call(onCheckSpointUser),
        call(onAnswerCsat),
        call(onSkipCsat),
        call(onCheckPermission),
        call(onCheckUserBlocked),
        call(onCheckBadPassword)
    ]);
}
