import React, {useEffect, useMemo, useState} from "react";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useDispatch, useSelector} from "react-redux";
import {
    getLoading, getSubmitLoading, getSubmitResult, selectLastPhysical
} from "../../store/physical-evaluation/physicalEvaluationSelector";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {useNavigate, useParams} from "react-router-dom";
import Page from "../../components/page/Page";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {getProtocolData, getProtocolMap} from "../../utils/physicalEvaluation/protocolData";
import {ErrorMessage, Field, Form, Formik} from "formik";
import {
    fetchLastPhysical,
    resetFormSent,
    savePhysical
} from "../../store/physical-evaluation/physicalEvaluationReducer";
import {fetchClient} from "../../store/client/clientReducer";
import moment from "moment";
import EvaluationImageUpload from "../../utils/imageupdate/EvaluationImageUpload";
import {selectUser} from "../../store/user/userSelector";
import {formsPhysical} from "../../utils/physicalEvaluation/formsPhysical";
import {buildPhysicalEvaluationSchema} from "../../utils/physicalEvaluation/buildPhysicalEvaluationSchema";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import useScrollToError from "../../utils/scrolltoerror/scrollToError";
import {calculateAge} from "../../utils/date/dateUtils";
import EvaluationSubmitButton from "../../components/evaluation-components/EvaluationSubmitButton";
import {
    buildClientPhysicalRoute,
    buildPhysicalEndRoute
} from "../../utils/client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const PhysicalEvaluationCreate = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, protocol} = useParams();
    const {t} = useTranslation("physicalEvaluation");
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const user = useSelector(selectUser);
    const lastPhysical = useSelector(selectLastPhysical);
    const submitLoading = useSelector(getSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const [uploadedImages, setUploadedImages] = useState([]);
    const currentClientId = Number(id);

    const studentGender = selectedClient?.sexo?.toUpperCase() === "F" ? "female" : "male";
    const protocols = useMemo(() => getProtocolData(studentGender), [studentGender]);
    const protocolMap = useMemo(() => getProtocolMap(studentGender), [studentGender]);
    const currentProtocol = protocols.find((p) => p.id.toString() === protocol.toString());

    const translationsLoaded = useComponentTranslations('physicalEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const today = moment().format("YYYY-MM-DD");
    const nextEval = moment().add(90, 'days').format("YYYY-MM-DD");
    const scrollError = useScrollToError();
    const studentAge = useMemo(
        () =>
            selectedClient?.data_nascimento
                ? calculateAge(selectedClient.data_nascimento)
                : null,
        [selectedClient]
    );

    const initialValues = useMemo(() => {
        if (!currentProtocol) return {};

        const ageCalculated = studentAge ?? "";

        return currentProtocol.fields.reduce((acc, field) => {
            if (field.id === "data") {
                acc[field.id] = today;
            } else if (field.id === "proximaAvaliacao") {
                acc[field.id] = nextEval;
            } else if (field.id === "idade") {
                acc[field.id] = ageCalculated;
            } else if (field.id === "proposta") {
                acc[field.id] = studentGender === "male" ? 14 : 20;
            } else {
                acc[field.id] = "";
            }
            return acc;
        }, {});
    }, [currentProtocol, today, nextEval, studentAge, studentGender]);

    const validationSchema = useMemo(
        () => buildPhysicalEvaluationSchema(currentProtocol),
        [currentProtocol]
    );

    const currentForm = formsPhysical.find(f => f.id === currentProtocol.id);
    const genderBranch = currentForm?.genderSpecific
        ? currentForm.genderSpecific[studentGender]
        : {};

    const {
        formulaKey: branchFormulaKey,
        estimatedValueKey,
        densityKey,
        casesKey,
        skinColorDependentKey
    } = genderBranch || {};

    const fallbackFormulaKey =
        branchFormulaKey ||
        densityKey ||
        casesKey ||
        skinColorDependentKey ||
        currentForm.formulaKey;

    const formulaText = useMemo(() => {
        if (!translationsLoaded || !fallbackFormulaKey) return "";
        const data = t(`forms.${fallbackFormulaKey}`, {returnObjects: true});

        if (skinColorDependentKey && studentGender === "male") {
            const lines = [];
            Object.entries(data).forEach(([colorKey, value]) => {
                const ranges = value.ageRanges || [];
                const match = studentAge
                    ? ranges.find(r => {
                        const [min, max] = r.age.split("-").map(Number);
                        return studentAge >= min && studentAge <= max;
                    })
                    : null;

                if (match) {
                    lines.push(`${t(`skinColors.${colorKey}`)}: ${match.formula}`);
                } else {
                    ranges.forEach(r => {
                        lines.push(`${t(`skinColors.${colorKey}`)} (${r.age}): ${r.formula}`);
                    });
                }
            });
            return lines.join("\n");
        }

        const lines = [];

        const parseData = (node, path = []) => {
            if (!node) return;
            if (typeof node === "string") {
                lines.push([...path, node].filter(Boolean).join(" "));
                return;
            }
            if (Array.isArray(node)) {
                node.forEach(item => parseData(item, path));
                return;
            }
            if (typeof node === "object") {
                if (node.formula) {
                    const label = [...path, node.condition || node.age]
                        .filter(Boolean)
                        .join(" ");
                    lines.push(label ? `${label}: ${node.formula}` : node.formula);
                    return;
                }
                Object.entries(node).forEach(([key, value]) => {
                    const nextPath = key === "ageRanges" ? path : [...path, key];
                    parseData(value, nextPath);
                });
            }
        };

        parseData(data);
        return lines.join("\n");
    }, [
        translationsLoaded,
        fallbackFormulaKey,
        skinColorDependentKey,
        studentGender,
        studentAge,
        t
    ]);

    const estimatedValueText = useMemo(() => {
        if (!translationsLoaded || !estimatedValueKey) return "";
        return t(`forms.${estimatedValueKey}`);
    }, [translationsLoaded, estimatedValueKey, t]);

    const protocolo = protocolMap[currentProtocol.protocolo];

    const lastProtocol = lastPhysical
        ? protocolMap[Number(lastPhysical.protocolo)]
        : null;

    const handleSubmit = async (values, formikHelpers) => {
        const errors = await formikHelpers.validateForm(values);
        if (Object.keys(errors).length > 0) {
            scrollError(errors);
            return;
        }
        const {cor, ...restValues} = values;
        const mappedSkinColor =
            cor === "branco" ? 1 : cor === "negro" ? 0 : undefined;
        const payload = {
            ...restValues,
            ...(mappedSkinColor !== undefined && {cor: mappedSkinColor, skinColor: mappedSkinColor}),
            id_aluno: Number(id),
            gender: selectedClient.sexo,
            protocolo: Number(currentProtocol.id),
            idade: Number(values.idade),
            data: values.data,
            estatura: Number(values.estatura),
            peso: Number(values.peso),
            proximaAvaliacao: values.proximaAvaliacao,
            images: uploadedImages
        };
        dispatch(savePhysical(payload, {
            flow: EVALUATION_FLOWS.PHYSICAL_CREATE,
            clientId: currentClientId
        }));
    };

    const handleGoBackPage = () => {
        navigate(buildClientPhysicalRoute(id));
    };

    const handleImagesUpload = (urls) => {
        setUploadedImages(urls);
    };

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        if (selectedClient) {
            dispatch(fetchLastPhysical({clientId: currentClientId}));
        }
    }, [currentClientId, dispatch, selectedClient]);

    useEffect(() => {
        if (isMatchingSubmitSuccess(submitResult, {
            action: "create",
            flow: EVALUATION_FLOWS.PHYSICAL_CREATE,
            clientId: currentClientId
        })) {
            navigate(buildPhysicalEndRoute(id, submitResult.entityId));
        }
    }, [submitResult, navigate, id, currentClientId]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"card card-body border-0"}>
                    {loading &&
                        <div className={"text-center mt-4"}>
                            <LoadingBlock/>
                        </div>
                    }
                    {!loading && (
                        <>
                            <div className={"card card-body border-0 bg-secondary-subtle"}>
                                <div className={"text-center row"}>
                                    <span className={"fw-semibold pb-1 fs-5 "}>
                                         {protocolo ? t(`protocols.${protocolo.translationKey}`) : currentProtocol.name}
                                    </span>
                                    {formulaText && (
                                        <>
                                            <span className="fw-semibold">
                                              {t("physicalEvaluation:formula")}:
                                            </span>
                                            <span className="pb-2" style={{whiteSpace: 'pre-line'}}>
                                              {formulaText}
                                            </span>
                                        </>
                                    )}
                                    {estimatedValueText && (
                                        <>
                                            <span className="fw-semibold">
                                              {t("physicalEvaluation:estimatedValue")}:
                                            </span>
                                            <span className="pb-2">
                                              {estimatedValueText}
                                            </span>
                                        </>
                                    )}
                                    <hr className={"bg-secondary-subtle"}/>
                                    <span className={"fw-semibold"}>{t("physicalEvaluation:lastEvaluation")}</span>
                                    <span> {lastProtocol
                                        ? t(`protocols.${lastProtocol.translationKey}`)
                                        : lastPhysical?.tipo}
                                    </span>
                                </div>
                            </div>
                            <Formik
                                initialValues={initialValues}
                                onSubmit={handleSubmit}
                                validationSchema={validationSchema}
                                validateOnChange={true}
                                validateOnBlur={true}
                            >
                                {({errors, touched, setTouched, submitForm, validateForm}) => (
                                    <Form>
                                        <div className={"my-3"}>
                                            <label htmlFor="genero"
                                                   className="fw-semibold">{t("physicalEvaluation:gender")}</label>
                                            <Field
                                                id="genero"
                                                name="genero"
                                                type="text"
                                                value={
                                                    selectedClient?.sexo?.toUpperCase() === 'F'
                                                        ? t("physicalEvaluation:female")
                                                        : selectedClient?.sexo?.toUpperCase() === 'M'
                                                            ? t("physicalEvaluation:male")
                                                            : ''
                                                }
                                                className={"form-control"}
                                                readOnly
                                            />
                                            <span
                                                className={"text-md text-danger"}>{t("physicalEvaluation:genderMessage")}</span>
                                        </div>
                                        {Object.entries(
                                            currentProtocol.fields.reduce((acc, field) => {
                                                const section = field.section || "outros";
                                                if (!acc[section]) acc[section] = [];
                                                acc[section].push(field);
                                                return acc;
                                            }, {})
                                        ).map(([section, fields]) => (
                                            <div key={section} className={"my-2 row"}>
                                                <div className={"row"}>
                                                    {section !== "Pessoal" && (
                                                        <span className={"fw-semibold fs-5 pb-2"}>{section}</span>
                                                    )}
                                                    {section === "Antropometria" && (
                                                        <span
                                                            className={"text-md mb-2"}>{t("physicalEvaluation:anthropometryMessage")}</span>
                                                    )}
                                                </div>
                                                {fields.map((field) => {
                                                    const showError = Boolean(errors[field.id] && touched[field.id]);
                                                    return (
                                                        <div key={field.id} className={"mb-3"}>
                                                            <label htmlFor={field.id} className={"fw-semibold"}>
                                                                {t(`physicalEvaluation:fields.${field.labelKey}`)}
                                                            </label>
                                                            {field.id === "data" ? (
                                                                <Field name="data">
                                                                    {({field, form}) => {
                                                                        const err = form.errors.data && form.touched.data;
                                                                        return (
                                                                            <>
                                                                                <input
                                                                                    {...field}
                                                                                    id="data"
                                                                                    type="date"
                                                                                    className={`form-control${err ? " is-invalid" : ""}`}
                                                                                    onChange={(e) => {
                                                                                        const selectedDate = e.target.value;
                                                                                        form.setFieldValue("data", selectedDate);

                                                                                        const nextEvalDate = moment(selectedDate)
                                                                                            .add(90, "days")
                                                                                            .format("YYYY-MM-DD");
                                                                                        form.setFieldValue("proximaAvaliacao", nextEvalDate);
                                                                                    }}
                                                                                />
                                                                                <ErrorMessage
                                                                                    name="data"
                                                                                    component="div"
                                                                                    className={"invalid-feedback"}
                                                                                />
                                                                            </>
                                                                        )
                                                                    }}
                                                                </Field>
                                                            ) : field.id === "proximaAvaliacao" ? (
                                                                <Field name="proximaAvaliacao">
                                                                    {({field: inputField, form}) => {
                                                                        const err = form.errors.proximaAvaliacao && form.touched.proximaAvaliacao;
                                                                        return (
                                                                            <>
                                                                                <input
                                                                                    {...inputField}
                                                                                    id="proximaAvaliacao"
                                                                                    type="date"
                                                                                    className={`form-control${err ? " is-invalid" : ""}`}
                                                                                    onChange={e =>
                                                                                        form.setFieldValue("proximaAvaliacao", e.target.value)
                                                                                    }
                                                                                />
                                                                                <ErrorMessage
                                                                                    name="proximaAvaliacao"
                                                                                    component="div"
                                                                                    className="invalid-feedback"
                                                                                />
                                                                            </>
                                                                        );
                                                                    }}
                                                                </Field>
                                                            ) : field.type === "select" ? (
                                                                <>
                                                                    <Field as="select"
                                                                           id={field.id}
                                                                           name={field.id}
                                                                           className={`form-select${showError ? " is-invalid" : ""}`}
                                                                    >
                                                                        <option value="">{t("physicalEvaluation:select")}</option>
                                                                        {field.options.map(option => (
                                                                            <option key={option} value={option}>
                                                                                {t(`physicalEvaluation:skinColors.${option}`)}
                                                                            </option>
                                                                        ))}
                                                                    </Field>
                                                                    <ErrorMessage
                                                                        name={field.id}
                                                                        component="div"
                                                                        className={"invalid-feedback"}
                                                                    />
                                                                </>
                                                            ) : ['objetivo', 'observacao'].includes(field.id) ? (
                                                                <>
                                                                    <Field
                                                                        as="textarea"
                                                                        id={field.id}
                                                                        name={field.id}

                                                                        className={`form-control${showError ? " is-invalid" : ""}`}
                                                                    />
                                                                    <ErrorMessage
                                                                        name={field.id}
                                                                        component="div"
                                                                        className={"invalid-feedback"}
                                                                    />
                                                                </>
                                                            ) : field.id === "proposta" ? (
                                                                <Field name={"proposta"}
                                                                       type={"number"}
                                                                       className={`form-control${showError ? " is-invalid" : ""}`}
                                                                />
                                                            ) : (
                                                                <>
                                                                    <Field name={field.id}>
                                                                        {({field: inputField, form}) => {
                                                                            const errNum = form.errors[field.id] && form.touched[field.id];
                                                                            return (
                                                                                <>
                                                                                    <input
                                                                                        {...inputField}
                                                                                        id={field.id}
                                                                                        type="text"

                                                                                        className={`form-control${errNum ? " is-invalid" : ""}`}
                                                                                        min={0}
                                                                                        inputMode="decimal"
                                                                                        onKeyDown={(e) => {
                                                                                            if (e.key === '-') {
                                                                                                e.preventDefault();
                                                                                            }
                                                                                        }}
                                                                                        onChange={(e) => {
                                                                                            let value = e.target.value;
                                                                                            value = value.replace(',', '.');
                                                                                            if (!/^(\d+(\.\d*)?)?$/.test(value)) {
                                                                                                return;
                                                                                            }
                                                                                            form.setFieldValue(field.id, value);
                                                                                        }}
                                                                                    />
                                                                                    <ErrorMessage
                                                                                        name={field.id}
                                                                                        component="div"
                                                                                        className={"invalid-feedback"}
                                                                                    />
                                                                                </>
                                                                            )
                                                                        }}
                                                                    </Field>
                                                                </>
                                                            )}
                                                            {lastPhysical && lastPhysical[field.id] !== undefined && (
                                                                <span className={"text-md"}>
                                                            {t("physicalEvaluation:lastReview")} {field.id === "data" || field.id === "proximaAvaliacao"
                                                                    ? moment(lastPhysical[field.id]).locale("pt-br").format("L")
                                                                    : lastPhysical[field.id]}
                                                        </span>
                                                            )}
                                                        </div>
                                                    )
                                                })}
                                            </div>
                                        ))}
                                        <div className={"row"}>
                                            <span className={"fw-semibold mt-3"}>{t("physicalEvaluation:photos")}</span>
                                            <span className={"mb-3"}>{t("physicalEvaluation:addPhotos")}</span>
                                            <EvaluationImageUpload user={user}
                                                                   slots={4}
                                                                   basePath={"physicalevaluation"}
                                                                   selectedClient={selectedClient}
                                                                   onImagesUpload={handleImagesUpload}
                                                                   existingImages={[]}
                                                                   Anexar={t("physicalEvaluation:attach")}
                                            />
                                        </div>
                                        <div className={"mt-3"}>
                                            <EvaluationSubmitButton
                                                type="button"
                                                label={t("physicalEvaluation:save")}
                                                loadingLabel={t("physicalEvaluation:save")}
                                                isSubmitting={submitLoading}
                                                onClick={async () => {
                                                    const errs = await validateForm();
                                                    if (Object.keys(errs).length > 0) {
                                                        setTouched(
                                                            Object.keys(errs).reduce((t, key) => ({
                                                                ...t,
                                                                [key]: true
                                                            }), {}),
                                                            false
                                                        );
                                                        setTimeout(() => scrollError(errs), 0);
                                                    } else {
                                                        submitForm()
                                                    }
                                                }}
                                            />
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                        </>
                    )}
                </div>
            </Page>
        </>
    )
}

export default PhysicalEvaluationCreate;
