import {useNavigate, useParams} from "react-router-dom";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useDispatch, useSelector} from "react-redux";
import Page from "../../components/page/Page";
import {useEffect} from "react";
import {getModelsList, isAnamnesisLoading} from "../../store/anamnesis/anamnesisSelector";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {fetchClient} from "../../store/client/clientReducer";
import {getModels, resetFormSent} from "../../store/anamnesis/anamnesisReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import AnamnesisModelListItem from "../../components/anamnesis/AnamnesisModelListItem";
import {
    buildAnamnesisCreateModelRoute,
    buildAnamnesisListRoute
} from "../../utils/client/evaluationRoutes";


const AnamnesisModelList = () => {
    const dispatch = useDispatch();
    const {t} = useTranslation();
    const navigate = useNavigate();
    const {clientId} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const loadingAnamnesis = useSelector(isAnamnesisLoading);
    const modelsList = useSelector(getModelsList);
    const sortedModels = [...modelsList].sort((a, b) => (a.idUser ?? 0) - (b.idUser ?? 0));

    useComponentTranslations('anamnesis', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate(buildAnamnesisListRoute(clientId));
    };
    const handleGoNewModel = () => {
        navigate(buildAnamnesisCreateModelRoute(clientId))
    };

    useEffect(() => {
        dispatch(fetchClient(clientId));
        dispatch(resetFormSent());
        dispatch(getModels("models"));
    }, [dispatch, clientId]);
    return (
        <>
            <AvatarHeader showGoBack={handleGoBack} className={"pb-4 pt-2"}
                          text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                          url={selectedClient?.profileUrl}  />
            <Page contentHeader={false} loading={loadingAnamnesis}>
                <div className={'row justify-content-center d-flex'}>
                    <div className={"col-12"}>
                        <div className={'card card-body border-0'}>
                            <div className={"btn btn-outline-primary py-4 clickable-element"}
                                 onClick={handleGoNewModel}>
                                <i className={"fa-regular fa-plus"}/>
                                <span className={"px-1"}>{t("anamnesis:createNewModel")}</span>
                            </div>
                            <div className={"pt-3"}>
                                <div className={"fw-semibold fs-5"}>{t("anamnesis:readyModels")}</div>
                            </div>
                            <div className={'row justify-content-center d-flex'}>
                                {
                                    sortedModels.map((model, index) => (
                                        <AnamnesisModelListItem model={model} key={index} clientId={clientId}/>
                                    ))
                                }
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default AnamnesisModelList
