import React, {useCallback} from "react";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {protocolMap} from "../../utils/physicalEvaluation/protocolData";

const PhysicalEvaluationCard = ({physical, onCardClick, isComparing, onCompare, onToggle, isSelected}) => {
    syncMomentLocale(i18n.language);
    const {t} = useTranslation("physicalEvaluationsComponent");
    useComponentTranslations('physicalEvaluationsComponent', {
        'en-US': enUS,
        'pt-BR': ptBR,
        'es-ES': esES,
        'pt-PT': ptPT
    });
    const protocolo = protocolMap[physical.protocolo];

    const handleCompare = useCallback(
        e => {
            e.stopPropagation();
            onCompare(physical.id);
        },
        [onCompare, physical.id]
    );

    const handleRowClick = useCallback(() => {
            if (isComparing) {
                onToggle(physical.id);
            } else {
                onCardClick(physical.id);
            }
        },
        [isComparing, onToggle, onCardClick, physical.id]
    );

    return (
        <div className={"row pb-2"}>
            <div className={"card"}>
                <div className={`row d-flex align-items-center py-3 ${!isComparing ? 'clickable-element' : ''}`}
                     onClick={handleRowClick}
                >
                    <div className={"col-10 lh-1 pb-1"}>
                        <span
                            className={"fw-semibold d-block"}>{protocolo ? t(`protocols.${protocolo.translationKey}`) : physical.tipo}</span>
                        <span className={"text-md fw-semibold me-1"}>{t("physicalEvaluationsComponent:carryOut")}</span>
                        <span className={"text-md"}>{moment(physical.data).format('L')}</span>
                    </div>
                    <div className={"col-2 d-flex justify-content-end align-items-center"}>
                        {isComparing ? (
                            physical.data ? (
                                <input
                                    type={"checkbox"}
                                    className={"form-check-input"}
                                    checked={isSelected}
                                    onChange={() => {
                                    }}
                                />
                            ) : (
                                <i className={"fa-regular fa-chevron-right"}/>
                            )
                        ) : (
                            <i className={"fa-regular fa-chevron-right"}/>
                        )}
                    </div>
                </div>
                <hr className={"text-secondary my-n1"}/>
                <div className={"col-12 clickable-element"} onClick={handleCompare}>
                    <button className={"btn btn-link text-md ps-0 fw-semibold my-n1"}>
                        {t("physicalEvaluationsComponent:compare")}
                    </button>
                </div>

            </div>
        </div>
    );
}

export default PhysicalEvaluationCard;