import OnlineEvaluationUpdatePhoto from "./OnlineEvaluationUpdatePhoto";
import {useState} from "react";
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import {Field, useFormikContext} from 'formik';
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Text from "../utils/emoji/Text";
import {getPreviousOnlineEvaluationValue} from "../../utils/onlineEvaluation/valueUtils";
import {getMeasurementVideoUrl} from "../../utils/translation/measurementVideo";

const OnlineEvaluationQuestion = ({
                                field,
                                moveForward,
                                moveBackwards,
                                currentStep,
                                maxStep,
                                user,
                                selectedClient,
                                lastEvaluation,
                                isSubmitting = false
                            }) => {
    const {setFieldValue, setFieldTouched, validateForm, errors, touched} = useFormikContext();
    const {t, i18n} = useTranslation("evaluationOnlineComponents");
    useComponentTranslations('evaluationOnlineComponents', {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT
    });

    const progress = Math.round(((currentStep + 1) / (maxStep + 1)) * 100);
    const isImageField = field.type === "image";
    const isLastStep = currentStep === maxStep;

    const previousValue = getPreviousOnlineEvaluationValue(lastEvaluation, field.id, t("evaluationOnlineComponents:loading"));
    const [showVideoModal, setShowVideoModal] = useState(false);
    const measurementVideoUrl = getMeasurementVideoUrl(field.id, i18n.language);

    const handleOpenModal = () => {
        setShowVideoModal(true);
    };
    const handleCloseModal = () => {
        setShowVideoModal(false);
    };

    return (
        <div className={"card card-body"}>
            <div className={"text-md"}>{progress}%</div>
            <div className={"progress mb-3"} style={{height: "8px"}}>
                <div className={"progress-bar"} style={{width: `${progress}%`}}/>
            </div>
            <label htmlFor={field.id} className={"fs-5 d-block fw-semibold mt-2"}>{t(`fields.${field.labelKey}`)}</label>
            {isImageField ? (
                <div className={"upload-section"}>
                    <OnlineEvaluationUpdatePhoto
                        onImageUpload={(image) => setFieldValue(field.id, image)}
                        fieldName={field.id}
                        user={user}
                        selectedClient={selectedClient}
                    />
                </div>
            ) : (
                <div className={"my-2"}>
                    <Field name={field.id}>
                        {({field: f}) => (
                            <input
                                maxLength={255}
                                {...f}
                                id={field.id}
                                type={(field.type === "date" && "number") || "text"}
                                inputMode={field.isNumeric ? "decimal" : "text"}
                                placeholder={t(`placeholders.${field.placeholderKey}`)}
                                className={"form-control my-2"}
                                onChange={(e) => {
                                    let value = e.target.value;

                                    if (field.isNumeric) {
                                        value = value.replace(',', '.');
                                        if (!/^(\d+(\.\d*)?)?$/.test(value)) {
                                            return;
                                        }
                                    }

                                    setFieldValue(field.id, value);
                                }}
                                onBlur={() => setFieldTouched(field.id, true, true)}
                            />
                        )}
                    </Field>
                    {errors[field.id] && touched[field.id] && (
                        <div className="text-danger mt-1">
                            {errors[field.id]}
                        </div>
                    )}
                </div>
            )}
            <div className={"d-flex justify-content-between align-items-center"}>
                {!isImageField && (
                    <div className={"text-md"}>
                        <Text>
                            {field.id === "idade"
                                ? `${t("evaluationOnlineComponents:previousAge")} ${previousValue}`
                                : `${t("evaluationOnlineComponents:previousEvaluation")} ${previousValue}`}
                        </Text>
                    </div>
                )}
                {measurementVideoUrl && (
                    <button type={"button"} className={"btn btn-link text-md fw-semibold p-0"}
                            onClick={handleOpenModal}>
                        <i className={"fa-regular fa-clapperboard-play text-primary me-2"}/>
                        {t("evaluationOnlineComponents:seeHowMeasure")}
                    </button>
                )}
            </div>
            <div className={"col-12 pt-4"}>
                <div className={"row justify-content-between"}>
                    <div className={"col-6 pe-1"}>
                        {currentStep > 0 && (
                            <div className={"d-grid"}>
                                <button
                                    className={"btn btn-outline-primary text-primary"} onClick={moveBackwards}
                                >
                                    {t("evaluationOnlineComponents:back")}
                                </button>
                            </div>
                        )}
                    </div>
                    <div className={`col-${currentStep === 0 ? 12 : "6 ps-1"} `}>
                        <div className={"d-grid"}>
                            <button
                                type={isLastStep ? "submit" : "button"}
                                className={"btn btn-primary"}
                                disabled={isLastStep && isSubmitting}
                                onClick={async (e) => {
                                    if (!isLastStep) {
                                        e.preventDefault();
                                        setFieldTouched(field.id, true);
                                        const errs = await validateForm();
                                        if (!errs[field.id]) moveForward();
                                    }
                                }}
                            >
                                {isLastStep && isSubmitting && (
                                    <i className={"fa-regular fa-loader fa-spin me-2"}/>
                                )}
                                {isLastStep ? t("evaluationOnlineComponents:finish") : t("evaluationOnlineComponents:next")}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
            <Modal centered show={showVideoModal} onHide={handleCloseModal}>
                <ModalBody className={"text-center"}>
                    <div className={"row justify-content-between"}>
                        <div className={"col-auto"}>
                            <span className={"fw-semibold text-start"}>{t(`fields.${field.labelKey}`)}</span>
                        </div>
                        <div className={"col-auto cursor-pointer"} onClick={handleCloseModal}>
                            <i className={"fa-regular fa-times"}/>
                        </div>
                    </div>
                    <div className={"col-12 text-center mt-3"}>
                        <div className={"pt-2"}>
                            <video width="70%" controls>
                                <source src={measurementVideoUrl} type="video/mp4"/>
                                {t("evaluationOnlineComponents:notSupportVideos")}
                            </video>
                        </div>
                    </div>
                </ModalBody>
            </Modal>
        </div>
    );
};

export default OnlineEvaluationQuestion;
