import {useState} from "react";
import Modal from "react-bootstrap/Modal";
import formDataToJson from "../../utils/form/formDataToJson";
import {useDispatch} from "react-redux";
import {updateWorkoutSerie} from "../../store/workout-session/workoutSessionReducer";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/workout-session/locales/en-us.json";
import ptBR from "../../pages/workout-session/locales/pt-br.json";
import esES from "../../pages/workout-session/locales/es-es.json";
import ptPT from "../../pages/workout-session/locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const WorkoutSerieForm = ({val, unit, serieId, sessionId, preview, showEdit = true}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const [value, setValue] = useState(val || 0);
    const [showForm, setShowForm] = useState(false)
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleInputChange = (e) => {
        setValue(e.target.value);
    };
    const handleClose = () => {
        setValue(val || 0)
        setShowForm(false)
    };

    const handleSubmit = async () => {
        if (value) {
            const formData = new FormData();
            formData.append("weight", value);
            formData.append("id", serieId);
            formData.append('sessionId', sessionId);
            const fd = await formDataToJson(formData);
            const payload = {
                id: serieId,
                formData: fd
            }
            dispatch(updateWorkoutSerie(payload));
            setShowForm(false)
        }
    };
    const handleShowUpdate = () => {
        setShowForm(true)
    }
    return (
        <>
            {
                !preview ?
                    <span className=" clickable-element"
                          onClick={showEdit ? handleShowUpdate : null}
                    >
                        {(value | 0) > 0 ? value + unit : value.length === 0 ? 0 + unit : Number(value) === 0 ? value + unit : value}
                        &nbsp;{showEdit && <span className={'small fst-italic fw-semibold text-primary'}>{t("workout:edit")}</span>}
                    </span>
                    :
                    <span>
                      {(value | 0) > 0 ? value + unit : value.length === 0 ? 0 + unit : Number(value) === 0 ? value + unit : value}
                    </span>
            }
            <Modal centered show={showForm} onHide={handleClose}>
                <Modal.Body className={'pt-3 pb-4'}>
                    <div className={'row justify-content-center d-flex'}>
                        <div className={'col-12'}>
                            <label className={'pb-2'}>{t("workout:updateWeight")}</label>
                            <input
                                type="text" onChange={handleInputChange}
                                className={'form-control  '}
                                value={value}
                            />
                        </div>
                        <div className={'col-12 mt-3'}>
                            <div className={'d-grid'}>
                                <button className={"clickable-element btn btn-primary-darker"} onClick={handleSubmit}>
                                    {t("workout:update")}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    )
}
export default WorkoutSerieForm;