import {createSelector} from "@reduxjs/toolkit";

const extraTrainingReducer = (state) => state.extraTraining;

export const isExtraTrainingLoading = createSelector(
    [extraTrainingReducer],
    (slice) => slice.listLoading || slice.currentLoading
);
export const selectExtraTrainingList = createSelector([extraTrainingReducer], (slice) => slice.list);
export const selectCurrentExtraTraining = createSelector([extraTrainingReducer], (slice) => slice.current);
export const selectExtraTrainingListStatus = createSelector([extraTrainingReducer], (slice) => slice.listStatus);
export const selectCurrentExtraTrainingStatus = createSelector([extraTrainingReducer], (slice) => slice.currentStatus);
export const selectExtraTrainingListErrorCode = createSelector([extraTrainingReducer], (slice) => slice.listErrorCode);
export const selectCurrentExtraTrainingErrorCode = createSelector([extraTrainingReducer], (slice) => slice.currentErrorCode);
export const selectCreateExtraTrainingLoading = createSelector([extraTrainingReducer], (slice) => slice.createLoading);
export const selectEditExtraTrainingLoading = createSelector([extraTrainingReducer], (slice) => slice.editLoading);
export const selectSendExtraTrainingLoading = createSelector([extraTrainingReducer], (slice) => slice.sendLoading);
export const selectDeleteExtraTrainingLoading = createSelector([extraTrainingReducer], (slice) => slice.deleteLoading);
export const selectExecuteExtraTrainingLoading = createSelector([extraTrainingReducer], (slice) => slice.executeLoading);
export const selectCreateExtraTrainingSuccess = createSelector([extraTrainingReducer], (slice) => slice.createSuccess);
export const selectEditExtraTrainingSuccess = createSelector([extraTrainingReducer], (slice) => slice.editSuccess);
export const selectSendExtraTrainingSuccess = createSelector([extraTrainingReducer], (slice) => slice.sendSuccess);
export const selectDeleteExtraTrainingSuccess = createSelector([extraTrainingReducer], (slice) => slice.deleteSuccess);
export const selectExecuteExtraTrainingSuccess = createSelector([extraTrainingReducer], (slice) => slice.executeSuccess);
