import RoundedIcon from "./RoundedIcon";
import {Link} from "react-router-dom";

const RoundedCard = ({col, to, handleClick, unreadCount, bgColor = "bg-primary-subtle", textColor = "text-primary", icon, text, size = "md", textClass = "", kit}) => {

    return (
        <div className={`${col} text-center clickable-element  `} onClick={handleClick}  >
            <Link to={to} className={`${col} text-decoration-none `}>
                <RoundedIcon unreadCount={unreadCount} icon={icon} kit={kit} bgColor={bgColor} textColor={textColor} size={size}/>
                <span className={`${textClass} pt-2 d-block text-default   `}>{text}</span>
            </Link>
        </div>
    )
}

export default RoundedCard;