
export default function ExerciseLibraryPagination({
                                                      page,
                                                      totalPages,
                                                      onPageChange,
                                                      pagesToShow = 7
                                                  }) {
    const half = Math.floor(pagesToShow / 2);
    let start = Math.max(1, page - half);
    let end = start + pagesToShow - 1;
    if (end > totalPages) {
        end = totalPages;
        start = Math.max(1, end - pagesToShow + 1);
    }

    const visiblePages = [];
    for (let p = start; p <= end; p++) {
        visiblePages.push(p);
    }

    return (
        <nav aria-label="Pagination">
            <ul className="pagination justify-content-center flex-wrap bg-transparent">
                {page > 1 && (
                    <li className="page-item">
                        <button
                            className="btn btn-link text-primary-darker pt-1 pb-1"
                            onClick={() => onPageChange(page - 1)}
                        >
                            <i className={"fa-regular fa-chevron-left"}></i>
                        </button>
                    </li>
                )}

                {visiblePages.map(p => (
                    <li key={p} className="page-item">
                        <button
                            className={`btn ${p === page ? 'btn-primary' : 'btn-link'} border-0 rounded-2 pt-1 pb-1`}
                            onClick={() => onPageChange(p)}
                        >
                            {p}
                        </button>
                    </li>
                ))}
                {page < totalPages && (
                    <li className="page-item">
                        <button
                            className="btn btn-link text-primary-darker pt-1 pb-1"
                            onClick={() => onPageChange(page + 1)}
                        >
                            <i className={"fa-regular fa-chevron-right"}></i>
                        </button>
                    </li>
                )}
            </ul>
        </nav>
    );
}
