import {apiUrl as url, getToken} from "../api";
import axios from "axios";

const apiUrl = url + "/v2"
export const getAllOnlineEvaluationAPI = async (clientId, status) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/onlineevaluation/all?clientId=${clientId}&status=${status}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'Authorization': token
            },
            timeout: 20000
        }
    )
}

