import {useCallback, useState} from "react";
import {useParams} from "react-router-dom";
import {changeStatus} from "../../store/physical-evaluation/physicalEvaluationReducer";
import {
    getSubmitLoading,
    getSubmitResult
} from "../../store/physical-evaluation/physicalEvaluationSelector";
import useComponentTranslations from "../translation/useComponentTranslations";
import ptBR from ".//locales/pt-br.json";
import ptPT from ".//locales/pt-pt.json";
import enUS from ".//locales/en-us.json";
import esES from ".//locales/es-es.json";
import {useMeasurementEvaluationActions} from "../measurementEvaluation/useMeasurementEvaluationActions";
import {
    buildClientMorphologicalRoute,
    buildClientPhysicalRoute,
    buildPhysicalChartsRoute,
    buildPhysicalCompareRoute,
    buildPhysicalCreateRoute,
    buildPhysicalDeletedRoute,
    buildPhysicalEditRoute,
    buildPhysicalViewRoute
} from "../client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../evaluation/flows";

export function usePhysicalActions() {
    const {id} = useParams();
    useComponentTranslations("utils", { "pt-BR": ptBR, "pt-PT": ptPT, "en-US": enUS, "es-ES": esES})

    const [showPhysicalMenu, setShowPhysicalMenu] = useState(false);
    const measurementActions = useMeasurementEvaluationActions({
        clientId: id,
        changeStatusAction: changeStatus,
        deleteFlow: EVALUATION_FLOWS.PHYSICAL_DELETE,
        selectSubmitResult: getSubmitResult,
        selectSubmitLoading: getSubmitLoading,
        routes: {
            goBack: () => buildClientMorphologicalRoute(id),
            goCharts: () => buildPhysicalChartsRoute(id),
            goDeleted: () => buildPhysicalDeletedRoute(id),
            goView: (physicalId) => buildPhysicalViewRoute(id, physicalId),
            goEdit: (physicalId) => buildPhysicalEditRoute(id, physicalId),
            goCompare: (physicalIds) => buildPhysicalCompareRoute(id, physicalIds),
            createNew: (selectedProtocolId) => buildPhysicalCreateRoute(id, selectedProtocolId),
            goList: () => buildClientPhysicalRoute(id),
        },
    });

    const openPhysicalMenu = useCallback(
        () => setShowPhysicalMenu(true), []);
    const closePhysicalMenu = useCallback(() => setShowPhysicalMenu(false), []);

    return {
        state: {
            ...measurementActions.state,
            currentPhysical: measurementActions.state.currentEvaluation,
            showOptions: measurementActions.state.showOptions,
            showShare: measurementActions.state.showShare,
            showDelete: measurementActions.state.showDelete,
            showPhysicalMenu,
        },
        handlers: {
            ...measurementActions.handlers,
            openPhysicalMenu,
            closePhysicalMenu,
            setCurrentPhysical: measurementActions.handlers.setCurrentEvaluation,
        },
        shareLink: measurementActions.shareLink
    };
}
