import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    groups: null,
    groupClients: [],
    ungroupedClients: [],
    ungroupedFilters: {
        page: 1,
        pageSize: 20,
        search: ""
    },
    ungroupedPagination: {
        page: 1,
        pageSize: 20,
        totalItems: 0,
        totalPages: 0
    },
    ungroupedCount: 0,
    createdGroup: null,
    groupsLoading: false,
    groupClientsLoading: false,
    ungroupedLoading: false,
    mutationLoading: false
}

export const slice = createSlice({
    name: 'clientGroup',
    initialState,
    reducers: {
        addClientsToGroup(state) {
            state.mutationLoading = true
        },
        addClientsToGroupSuccess(state) {
            state.mutationLoading = false
        },
        moveClientToGroup(state) {
            state.mutationLoading = true
        },
        moveClientToGroupSuccess(state) {
            state.mutationLoading = false
        },
        removeClientFromGroup(state){
            state.mutationLoading = true
        },
        removeClientFromGroupSuccess(state, action){
            state.mutationLoading = false
            state.groupClients = state.groupClients.filter(g => g.id !== action.payload)
        },
        fetchClientsFromGroup(state) {
            state.groupClientsLoading = true
        },
        setClientsFromGroup(state, action) {
            state.groupClientsLoading = false
            state.groupClients = action.payload || []
        },
        fetchUngroupedClients(state, action) {
            state.ungroupedLoading = true
            state.ungroupedFilters = {
                ...state.ungroupedFilters,
                ...(action.payload || {})
            }
        },
        setUngroupedClients(state, action) {
            const payload = action.payload || {}
            state.ungroupedLoading = false
            state.ungroupedClients = payload.clients || []
            state.ungroupedPagination = {
                page: payload.page || state.ungroupedFilters.page || 1,
                pageSize: payload.pageSize || state.ungroupedFilters.pageSize || 20,
                totalItems: payload.totalItems || 0,
                totalPages: payload.totalPages || 0
            }
        },
        fetchUngroupedCount() {
        },
        setUngroupedCount(state, action) {
            state.ungroupedCount = Number(action.payload || 0)
        },
        deleteClientGroup(state) {
            state.mutationLoading = true
        },
        deleteClientGroupSuccess(state, action) {
            state.groups = (state.groups || []).filter(group => group.id !== action.payload)
            state.mutationLoading = false
        },
        updateClientGroup(state) {
            state.mutationLoading = true
        },
        updateClientGroupSuccess(state, action) {
            const updatedGroup = action.payload;
            const index = (state.groups || []).findIndex(group => group.id === updatedGroup.id);
            if (index !== -1) {
                state.groups[index] = updatedGroup;
            }
            state.mutationLoading = false;
        },
        createClientGroup(state) {
            state.mutationLoading = true
        },
        createClientGroupSuccess(state, action) {
            state.mutationLoading = false
            state.createdGroup = action.payload
            if (state.groups) {
                const alreadyExists = state.groups.find((group) => group.id === action.payload.id)
                if (!alreadyExists) {
                    state.groups = [...state.groups, action.payload]
                }
            }
        },
        clearCreatedClientGroup(state) {
            state.createdGroup = null
        },
        setClientGroups(state, action) {
            state.groupsLoading = false
            state.groups = action.payload
        },
        fetchClientGroups(state) {
            state.groupsLoading = true
        },
        onError(state) {
            state.groupsLoading = false
            state.groupClientsLoading = false
            state.ungroupedLoading = false
            state.mutationLoading = false
        }
    }
});

export const {
    setClientGroups,
    fetchClientGroups,
    createClientGroup,
    updateClientGroup,
    updateClientGroupSuccess,
    deleteClientGroup,
    deleteClientGroupSuccess,
    fetchClientsFromGroup,
    setClientsFromGroup,
    fetchUngroupedClients,
    setUngroupedClients,
    fetchUngroupedCount,
    setUngroupedCount,
    createClientGroupSuccess,
    clearCreatedClientGroup,
    removeClientFromGroup,
    removeClientFromGroupSuccess,
    addClientsToGroup,
    addClientsToGroupSuccess,
    moveClientToGroup,
    moveClientToGroupSuccess,
    onError
} = slice.actions;
export const clientGroup = slice.reducer;
