import {useTranslation} from "react-i18next";
import Page from "../../components/page/Page";
import {ErrorMessage, Field, Form, Formik} from "formik";
import * as Yup from "yup";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import moment from "moment";
import {getAllCategories} from "../../utils/personalfinances/categoryUtils";

export default function PersonalFinancesForm({
                                         financeToEdit,
                                         categories,
                                         loading,
                                         onSubmit
                                     }) {
    const {t} = useTranslation('personalFinances');
    useComponentTranslations('personalFinances', {"en-US":enUS, "es-ES":esES, "pt-PT":ptPT, "pt-BR":ptBR});
    const isEditing = Boolean(financeToEdit);
    const cats = getAllCategories(categories);

    const formattedFatura = isEditing && financeToEdit.dataFatura
        ? moment(financeToEdit.dataFatura).format('YYYY-MM-DD')
        : '';
    const formattedPagamento = isEditing && financeToEdit.dataPagamento
        ? moment(financeToEdit.dataPagamento).format('YYYY-MM-DD')
        : '';

    const initialValues = isEditing ? {
        tipo:        financeToEdit.tipoConta === 0 ? 'receita' : 'despesa',
        valor:       financeToEdit.valor.toString(),
        dataVencimento: formattedFatura ?? '',
        jaPago:      financeToEdit.pago === 1 ? 'sim' : 'nao',
        quando:      formattedPagamento ?? '',
        pagoPara:    financeToEdit.referencia,
        descricao:   financeToEdit.descricao,
        categoria:   financeToEdit.categoria.toString(),
        observacoes: financeToEdit.observacao,
    } : {
        tipo: 'receita',
        valor: '',
        dataVencimento: '',
        pagoPara: '',
        descricao: '',
        categoria: '',
        observacoes: '',
        jaPago: '',
        quando: ''
    };

    const validationSchema = Yup.object({
        tipo: Yup.string()
            .oneOf(['receita','despesa'], t('personalFinances:invalidType'))
            .required(t('personalFinances:required')),
        valor: Yup.number()
            .typeError(t('personalFinances:mustBeNumber'))
            .required(t('personalFinances:required')),
        dataVencimento: Yup.date()
            .required(t('personalFinances:required')),
        pagoPara: Yup.string()
            .required(t('personalFinances:required')),
        categoria: Yup.string()
            .transform((val, orig) => orig === '' ? null : val)
            .nullable()
            .required(t('personalFinances:required')),
        jaPago: Yup.string()
            .oneOf(['sim','nao'], t('personalFinances:selectYesNo'))
            .required(t('personalFinances:required')),
        quando: Yup.date()
            .transform((value, originalValue) =>
                originalValue === '' ? null : value
            )
            .nullable()
            .when('jaPago', {
                is: 'sim',
                then: schema =>
                    schema
                        .typeError(t('personalFinances:required'))
                        .required(t('personalFinances:required')),
                otherwise: schema => schema
            })
    });

    return (
        <Page title={ isEditing ? t("personalFinances:editFinance") : t("personalFinances:new") }
              loading={loading}
        >
            <Formik
                initialValues={initialValues}
                validationSchema={validationSchema}
                enableReinitialize
                onSubmit={onSubmit}
            >
                {({values, isSubmitting}) => (
                    <Form className="space-y-4">
                        <div className={"card card-body border-0 mt-n2"}>
                            <div className={"mb-3"}>
                                <label className={"fw-semibold"}>{t("personalFinances:type")}:</label>
                                <div className={"form-check"}>
                                    <Field
                                        type={"radio"}
                                        name={"tipo"}
                                        value={"receita"}
                                        className={"form-check-input"}
                                        id={"tipoReceita"}
                                    />
                                    <label htmlFor="tipoReceita">{t("personalFinances:revenue")}</label>
                                </div>
                                <div className={"form-check"}>
                                    <Field
                                        type={"radio"}
                                        name={"tipo"}
                                        value={"despesa"}
                                        className={"form-check-input"}
                                        id={"tipoDespesa"}
                                    />
                                    <label htmlFor="tipoDespesa">{t("personalFinances:waste")}</label>
                                </div>
                                <ErrorMessage name="tipo" component="div" className="text-danger small mt-1"/>
                            </div>
                            <div className={"mb-3"}>
                                <label className={"form-label fw-semibold"}>{t("personalFinances:value")}:</label>
                                <Field
                                    name="valor"
                                    type="number"
                                    id="valor"
                                    className="form-control"
                                />
                                <ErrorMessage name="valor" component="div" className="text-danger small mt-1"/>
                            </div>

                            <div className={"mb-3"}>
                                <label className={"form-label fw-semibold"}>
                                    {values.tipo === 'receita'
                                        ? t('personalFinances:dateReceived')
                                        : t('personalFinances:dueDate')}:
                                </label>
                                <Field
                                    name="dataVencimento"
                                    type="date"
                                    id="dataVencimento"
                                    className="form-control"
                                />
                                <ErrorMessage
                                    name="dataVencimento"
                                    component="div"
                                    className="text-danger small mt-1"
                                />
                            </div>
                            <div className={"mb-3"}>
                                <label
                                    className={"form-label fw-semibold"}>{values.tipo === 'receita' ? t("personalFinances:receivedFrom") : t("personalFinances:payFor")}:</label>
                                <Field
                                    name="pagoPara"
                                    type="text"
                                    id="pagoPara"
                                    className="form-control"
                                />
                                <ErrorMessage name="pagoPara" component="div" className="text-danger small mt-1"/>
                            </div>
                            <div className={"mb-3"}>
                                <label className={"form-label fw-semibold"}>{t("personalFinances:description")}:</label>
                                <Field
                                    as="textarea"
                                    name="descricao"
                                    id="descricao"
                                    className="form-control"
                                    rows={3}
                                />
                                <ErrorMessage name="descricao" component="div" className="text-danger small mt-1"/>
                            </div>
                            <div className={"mb-3"}>
                                <label className={"form-label fw-semibold"}>{t("personalFinances:category")}:</label>
                                <Field
                                    as="select"
                                    name="categoria"
                                    id="categoria"
                                    className="form-select"
                                >
                                    <option value="">{t("personalFinances:select")}</option>
                                    {cats.map(cat => (
                                        <option key={cat.id} value={cat.id}>
                                            {t(
                                                `personalFinances:categoryNames.${cat.key}`,
                                                { defaultValue: cat.nome }
                                            )}
                                        </option>
                                    ))}
                                </Field>
                                <ErrorMessage name="categoria" component="div" className="text-danger small mt-1"/>
                            </div>
                            <div className={"mb-3"}>
                                <label
                                    className={"form-label fw-semibold"}>{t("personalFinances:observations")}:</label>
                                <Field
                                    as="textarea"
                                    name="observacoes"
                                    id="observacoes"
                                    className="form-control"
                                    rows={2}
                                />
                            </div>
                            <div className={"mb-3"}>
                                <label className={"form-label fw-semibold"}>
                                    {values.tipo === 'receita' ? t("personalFinances:areYouReceive") : t("personalFinances:areYouPay")}
                                </label>
                                <div className="d-flex gap-3">
                                    <div className="form-check">
                                        <Field
                                            type="radio"
                                            name="jaPago"
                                            value="sim"
                                            className="form-check-input"
                                            id="jaPagoSim"
                                        />
                                        <label htmlFor="jaPagoSim" className="form-check-label">
                                            {t("personalFinances:yes")}
                                        </label>
                                    </div>
                                    <div className="form-check">
                                        <Field
                                            type="radio"
                                            name="jaPago"
                                            value="nao"
                                            className="form-check-input"
                                            id="jaPagoNao"
                                        />
                                        <label htmlFor="jaPagoNao" className="form-check-label">
                                            {t("personalFinances:no")}
                                        </label>
                                    </div>
                                    <ErrorMessage
                                        name="jaPago"
                                        component="div"
                                        className={"text-danger small mt-1"}
                                    />
                                </div>
                            </div>
                            {values.jaPago === 'sim' && (
                                <div className={"mb-3"}>
                                    <label className={"form-label fw-semibold"}>{t("personalFinances:when")}:</label>
                                    <Field
                                        name="quando"
                                        type="date"
                                        id="quando"
                                        className="form-control"
                                    />
                                    <ErrorMessage name="quando" component="div" className="text-danger small mt-1"/>
                                </div>
                            )}
                            <button
                                type="submit"
                                disabled={isSubmitting}
                                className={"btn btn-primary"}
                            >
                                {isSubmitting
                                    ? isEditing ? t("personalFinances:savingChanges") : t("personalFinances:creating")
                                    : isEditing ? t("personalFinances:saveChanges") : t("personalFinances:save")}
                            </button>
                        </div>
                    </Form>
                )}
            </Formik>
        </Page>
    )
}