import Cookies from "js-cookie";

const Tabs = ({button1Text, button2Text, buttonClick, page, mt = "mt-n3", style}) => {
    return (
        <div className={`row justify-content-evenly   ${mt} ms-0 me-0  pt-4 `} style={style}>
            <div className={'col-12   ps-0 pe-0'}>
                <div className={'row justify-content-evenly '}>
                    <div className={'col-6 text-center pe-1 '}>
                        <div className={'d-grid'}>
                            <button
                                className={`btn ${page === '1' ? 'bg-body' : 'btn-primary-lighter'}  border-bottom-0 rounded-bottom-0 `}
                                onClick={() => buttonClick("1")}>{button1Text}
                            </button>
                        </div>
                    </div>
                    {
                        !Cookies.get("isApple") &&
                        <div className={'col-6 text-center ps-1'}>
                            <div className={'d-grid'}>
                                <button
                                    className={`btn ${page === '2' ? 'bg-body' : 'btn-primary-lighter'}  border-bottom-0 rounded-bottom-0 `}
                                    onClick={() => buttonClick("2")}>{button2Text}
                                </button>
                            </div>
                        </div>
                    }
                </div>
            </div>
        </div>
    )
}

export default Tabs;