import {all, call, put, takeLatest} from "redux-saga/effects";
import {addToast} from "../toast/toastReducer";
import i18n from "../../i18n";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    deleteExtraTrainingAPI,
    editExtraTrainingAPI,
    executeExtraTrainingAPI,
    getAllExtraTrainingAPI,
    getOneExtraTrainingAPI,
    saveExtraTrainingAPI,
    sendExtraTrainingAPI
} from "../../api/extratraining/extraTrainingActions";
import {
    createExtraTraining,
    currentExtraTrainingError,
    deleteExtraTraining,
    editExtraTraining,
    executeExtraTraining,
    extraTrainingCreated,
    extraTrainingDeleted,
    extraTrainingEdited,
    extraTrainingExecuted,
    extraTrainingSent,
    extraTrainingListError,
    fetchExtraTrainingList,
    fetchOneExtraTraining,
    onError,
    sendExtraTraining,
    setCurrentExtraTraining,
    setExtraTrainingList
} from "./extraTrainingReducer";

const DETAIL_NOT_FOUND_ERROR_CODES = ["extraTrainingNotFound", "clientDoesNotExist"];

const resolveExtraTrainingErrorCode = (error) => (
    error?.response?.data?.errorMessage
    || error?.response?.data?.code
    || error?.errorMessage
    || error?.code
    || null
);

const resolveExtraTrainingErrorMessage = (error) => {
    const errorCode = resolveExtraTrainingErrorCode(error);
    if (!errorCode) {
        return error?.response?.data?.message || error?.message;
    }

    const translationKey = `errorMessages.${errorCode}`;
    if (i18n.exists(translationKey, {ns: "extraTrainingUser"})) {
        return i18n.t(translationKey, {ns: "extraTrainingUser"});
    }

    return error?.response?.data?.message || error?.message;
};

const resolveRecipientSummary = (responseData) => responseData?.recipientSummary || null;

const resolveCreatedExtraTraining = (responseData) => responseData?.extraTraining || responseData;

function* handleExtraTrainingError(error, {failureAction, showToast = true} = {}) {
    const errorCode = resolveExtraTrainingErrorCode(error);
    const shouldHandleWithFeatureToast = Boolean(error?.response?.data?.message || errorCode);

    if (failureAction) {
        yield put(failureAction(errorCode));
    }

    if (shouldHandleWithFeatureToast) {
        if (!failureAction) {
            yield put(onError());
        }
        if (showToast) {
            yield put(addToast({
                title: i18n.t("sagaError:invalidCpfTitle"),
                message: resolveExtraTrainingErrorMessage(error),
                delay: 10000
            }));
        }
        return;
    }

    yield call(handleError, error, onError);
}

function* maybeShowPartialRecipientWarning(responseData) {
    const recipientSummary = resolveRecipientSummary(responseData);
    if (!recipientSummary?.skippedCount) {
        return;
    }

    yield put(addToast({
        title: i18n.t("extraTrainingUser:partialRecipientWarningTitle"),
        message: i18n.t("extraTrainingUser:partialRecipientWarningMessage", {
            count: recipientSummary.skippedCount
        }),
        delay: 10000
    }));
}

export function* fetchExtraTrainingListAsync(action) {
    try {
        const response = yield call(getAllExtraTrainingAPI, action.payload);
        yield put(setExtraTrainingList(response.data));
    } catch (error) {
        yield call(handleExtraTrainingError, error, {failureAction: extraTrainingListError, showToast: true});
    }
}

export function* onFetchExtraTrainingList() {
    yield takeLatest(fetchExtraTrainingList.type, fetchExtraTrainingListAsync);
}

export function* fetchOneExtraTrainingAsync(action) {
    try {
        const {id, extraTrainingId} = action.payload;
        const response = yield call(getOneExtraTrainingAPI, id, extraTrainingId);
        yield put(setCurrentExtraTraining(response.data));
    } catch (error) {
        const errorCode = resolveExtraTrainingErrorCode(error);
        const showToast = !DETAIL_NOT_FOUND_ERROR_CODES.includes(errorCode);
        yield call(handleExtraTrainingError, error, {failureAction: currentExtraTrainingError, showToast});
    }
}

export function* onFetchOneExtraTraining() {
    yield takeLatest(fetchOneExtraTraining.type, fetchOneExtraTrainingAsync);
}

export function* createExtraTrainingAsync({payload}) {
    try {
        const response = yield call(saveExtraTrainingAPI, payload);
        yield call(maybeShowPartialRecipientWarning, response.data);
        yield put(extraTrainingCreated(resolveCreatedExtraTraining(response.data)));
    } catch (error) {
        yield call(handleExtraTrainingError, error);
    }
}

export function* onCreateExtraTraining() {
    yield takeLatest(createExtraTraining.type, createExtraTrainingAsync);
}

export function* editExtraTrainingAsync({payload}) {
    try {
        const response = yield call(editExtraTrainingAPI, payload);
        yield put(extraTrainingEdited(response.data));
    } catch (error) {
        yield call(handleExtraTrainingError, error);
    }
}

export function* onEditExtraTraining() {
    yield takeLatest(editExtraTraining.type, editExtraTrainingAsync);
}

export function* sendExtraTrainingAsync({payload}) {
    try {
        const response = yield call(sendExtraTrainingAPI, payload);
        yield call(maybeShowPartialRecipientWarning, response?.data);
        yield put(extraTrainingSent());
    } catch (error) {
        yield call(handleExtraTrainingError, error);
    }
}

export function* onSendExtraTraining() {
    yield takeLatest(sendExtraTraining.type, sendExtraTrainingAsync);
}

export function* deleteExtraTrainingAsync({payload}) {
    try {
        const {id, extraTrainingId} = payload;
        yield call(deleteExtraTrainingAPI, id, extraTrainingId);
        yield put(extraTrainingDeleted(payload));
    } catch (error) {
        yield call(handleExtraTrainingError, error);
    }
}

export function* onDeleteExtraTraining() {
    yield takeLatest(deleteExtraTraining.type, deleteExtraTrainingAsync);
}

export function* executeExtraTrainingAsync({payload}) {
    try {
        const {id, extraTrainingId} = payload;
        yield call(executeExtraTrainingAPI, id, extraTrainingId);
        yield put(extraTrainingExecuted(payload));
    } catch (error) {
        yield call(handleExtraTrainingError, error);
    }
}

export function* onExecuteExtraTraining() {
    yield takeLatest(executeExtraTraining.type, executeExtraTrainingAsync);
}

export function* extraTrainingSaga() {
    yield all([
        call(onFetchExtraTrainingList),
        call(onFetchOneExtraTraining),
        call(onCreateExtraTraining),
        call(onEditExtraTraining),
        call(onSendExtraTraining),
        call(onDeleteExtraTraining),
        call(onExecuteExtraTraining)
    ]);
}
