import React, {useEffect, useState} from "react";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {
    isClientsLoading,
    selectClients,
    selectClientsPagination,
    selectSelectedClient,
} from "../../store/client/clientSelector";
import {useNavigate, useParams} from "react-router-dom";
import {fetchClient, fetchClientsPaginated, setClientsPaginated} from "../../store/client/clientReducer";
import {
    selectWorkoutRoutineLoading,
    selectWorkoutRoutines, selectWorkoutRoutineSessionCloned,
} from "../../store/workout-routine/workoutRoutineSelector";
import {
    cloneSessionsToRoutine,
    cloneSessionsToRoutineSuccess,
    fetchRoutinesToCloneSessions,
    setWorkouts
} from "../../store/workout-routine/workoutRoutineReducer";
import _ from "lodash";
import WorkoutRoutineCardSimple from "../../components/workout-routine/WorkoutRoutineCardSimple";
import Spinner from "../../components/loader/Spinner";
import {selectUser} from "../../store/user/userSelector";
import {addToast} from "../../store/toast/toastReducer";
import WorkoutSessionClientItemList from "../../components/workout-routine/WorkoutSessionClientItemList";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Pagination from "../../components/pagination/Pagination";
import EmptySet from "../../components/empty-set/EmptySet";

const CLIENT_ITEMS_PER_PAGE = 20;

const WorkoutRoutineSessionClone = () => {
    const {t} = useTranslation();
    const client = useSelector(selectSelectedClient);
    const {clientId, id, sessionId} = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const clientOptions = useSelector(selectClients);
    const clientPagination = useSelector(selectClientsPagination);
    const workouts = useSelector(selectWorkoutRoutines);
    const workoutLoading = useSelector(selectWorkoutRoutineLoading);
    const optionsLoading = useSelector(isClientsLoading);
    const [library, setLibrary] = useState(null);
    const [clientSearchTerm, setClientSearchTerm] = useState("");
    const [debouncedClientSearchTerm, setDebouncedClientSearchTerm] = useState("");
    const [librarySearchTerm, setLibrarySearchTerm] = useState("");
    const [clientPage, setClientPage] = useState(1);
    const user = useSelector(selectUser)
    const [selectedWorkoutIds, setSelectedWorkoutIds] = useState([]);
    const loading = useSelector(selectWorkoutRoutineLoading);
    const isCloned = useSelector(selectWorkoutRoutineSessionCloned)
    const totalItems = clientPagination?.totalItems || 0;
    const pagesToShow = 5;

    const isLibrary = Number(clientId) === 0;
    useComponentTranslations('workoutRoutine', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const removeAccents = (str) => {
        return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    };

    const handleGoBack = () => {
        navigate(`/user/client/${clientId}/workout/routine/${id}`);
    };

    const getClientOptions = () => {
        setSelectedWorkoutIds([]);
        setClientSearchTerm("");
        setDebouncedClientSearchTerm("");
        setClientPage(1);
        dispatch(setWorkouts(null));
        dispatch(setClientsPaginated(null));
    };

    const getWorkouts = () => {
        dispatch(fetchRoutinesToCloneSessions({library: true, clientId: 0}));
        dispatch(setClientsPaginated(null));
        setSelectedWorkoutIds([]);
        setClientSearchTerm("");
        setDebouncedClientSearchTerm("");
        setClientPage(1);
    };

    const handleSelectorChange = (e) => {
        const value = e.target.value;
        const isLibrarySelected = value === "true";
        setLibrary(isLibrarySelected);
        setLibrarySearchTerm("");
        if (isLibrarySelected) {
            getWorkouts();
        } else {
            getClientOptions();
        }
    };

    const normalizedLibrarySearchTerm = removeAccents(librarySearchTerm.toLowerCase());
    const filteredClients = clientOptions || [];

    const filteredWorkouts =
        workouts &&
        workouts.filter((item) => {
            const normalizedNome = removeAccents((item.nome || "").toLowerCase());
            return normalizedNome.includes(normalizedLibrarySearchTerm);
        });

    const handleToggleWorkout = (workoutId, checked) => {
        setSelectedWorkoutIds((prev) => {
            if (checked) {
                return [...prev, workoutId];
            } else {
                return prev.filter((selectedId) => selectedId !== workoutId);
            }
        });
    };

    const handleCloneSessionClick = (workoutId) => {
        const payload = {
            sessionId,
            userId: user.id,
            routines: workoutId > 0 ? [workoutId] : selectedWorkoutIds,
        };
        dispatch(cloneSessionsToRoutine(payload));
    };

    useEffect(() => {
        if (Number(clientId) > 0) {
            dispatch(fetchClient(clientId));
        }
    }, [dispatch, clientId]);

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedClientSearchTerm(clientSearchTerm.trim());
        }, 300);

        return () => clearTimeout(handler);
    }, [clientSearchTerm]);

    useEffect(() => {
        if (library !== false) {
            return;
        }

        dispatch(fetchClientsPaginated({
            status: 0,
            page: clientPage,
            pageSize: CLIENT_ITEMS_PER_PAGE,
            search: debouncedClientSearchTerm
        }));
    }, [clientPage, debouncedClientSearchTerm, dispatch, library]);

    useEffect(() => {
        if (isCloned) {
            setSelectedWorkoutIds([])
            dispatch(cloneSessionsToRoutineSuccess(false))
            dispatch(addToast({
                type: "success",
                message: `${t("workoutRoutine:clonedSuccessMessage")}`,
                title: `${t("workoutRoutine:clonedSuccessTitle")}`
            }))
        }
    }, [dispatch, isCloned, t]);

    useEffect(() => {
        return () => {
            dispatch(setWorkouts(null));
            dispatch(setClientsPaginated(null));
            setLibrary(null);
        };
    }, [dispatch]);

    return (
        <>
            {!isLibrary &&
                <AvatarHeader
                    className="pb-4 pt-2"
                    text={`${client?.nome} ${client?.sobrenome}`}
                    url={client?.profileUrl}
                    showGoBack={handleGoBack}
                />}
            <Page contentHeader={isLibrary} goBackLink={handleGoBack}>
                <div className="row justify-content-center mt-3">
                    <div className="col-12">
                        <div className="card card-body border-0">
                            <div className="row">
                                <div className="col-12 mb-2">
                                    <span className="fw-semibold">{t("workoutRoutine:copyTo")}</span>
                                </div>
                                <div className="col-12">
                                    <div className="form-group">
                                        <select
                                            className="form-select"
                                            defaultValue=""
                                            onChange={handleSelectorChange}
                                        >
                                            <option value="" disabled>
                                                {t("workoutRoutine:select")}
                                            </option>
                                            <option value="false">{t("workoutRoutine:otherClientWorkout")}</option>
                                            <option value="true">{t("workoutRoutine:libraryWorkout")}</option>
                                        </select>
                                    </div>
                                </div>
                            </div>
                            {library !== null && (
                                <div className="row mt-2">
                                    <div className="col-12">
                                        <input
                                            type="text"
                                            className="form-control"
                                            placeholder={t("workoutRoutine:search")}
                                            value={library ? librarySearchTerm : clientSearchTerm}
                                            onChange={(e) => {
                                                if (library) {
                                                    setLibrarySearchTerm(e.target.value);
                                                } else {
                                                    setClientPage(1);
                                                    setClientSearchTerm(e.target.value);
                                                }
                                            }}
                                        />
                                    </div>
                                </div>
                            )}
                            <div className="row mt-1">
                                {((workoutLoading && !workouts) || (optionsLoading && !clientOptions)) && (
                                    <div className="col-12 mt-4">
                                        <Spinner/>
                                    </div>
                                )}
                                {(workouts || clientOptions) &&
                                    <>
                                        {library &&
                                            <div className="col-12 mt-2 mb-2 text-center">
                                                <span className={"fst-italic"}>{t("workoutRoutine:selectRoutineToClone")}</span>
                                            </div>
                                        }
                                        {!library && selectedWorkoutIds.length > 0 &&
                                            <div className="col-12 mt-2 mb-2 text-center">
                                                <span className={"fst-italic"}>{selectedWorkoutIds.length} {t("workoutRoutine:selectedWorkouts")}</span>
                                            </div>
                                        }
                                    </>
                                }
                                {selectedWorkoutIds.length > 0 && (
                                    <div className="col-12 text-center mb-2">
                                        <button
                                            className="btn btn-primary w-100"
                                            onClick={() => handleCloneSessionClick(0)}
                                            disabled={selectedWorkoutIds.length === 0}
                                        >
                                            {t("workoutRoutine:cloneWorkoutSession")}
                                        </button>
                                    </div>
                                )}
                                {!library && filteredClients.length > 0 &&
                                    _.map(filteredClients, (item) => (
                                        <div className="col-12 mt-4 clickable-element" key={item.id}>
                                            <WorkoutSessionClientItemList
                                                client={item}
                                                handleCloneSessionClick={handleCloneSessionClick}
                                                onToggle={handleToggleWorkout}
                                                selectedWorkoutIds={selectedWorkoutIds}
                                            />
                                            <hr className="border-primary-subtle mb-0"/>
                                        </div>
                                    ))}
                                {!library && clientOptions !== null && !optionsLoading && filteredClients.length === 0 && (
                                    <div className="col-12 mt-4">
                                        <EmptySet
                                            icon={"fa-users"}
                                            message={clientSearchTerm ? t("workoutRoutine:noClientsFoundSearch") : t("workoutRoutine:noClientsFound")}
                                        />
                                    </div>
                                )}
                                {library && loading &&
                                    <div className="col-12 mt-4">
                                        <Spinner/>
                                    </div>
                                }
                                {library &&
                                    filteredWorkouts &&
                                    _.map(filteredWorkouts, (item) => (
                                        <div className="col-12 mt-2" key={item.id}>
                                            <WorkoutRoutineCardSimple
                                                handleCloneSessionClick={handleCloneSessionClick}
                                                workout={item}
                                                onToggle={handleToggleWorkout}
                                                selected={selectedWorkoutIds.includes(item.id)}
                                                gender={client?.sexo}
                                            />
                                        </div>
                                    ))}
                                {!library && totalItems > CLIENT_ITEMS_PER_PAGE && (
                                    <div className="col-12 pt-3">
                                        <Pagination
                                            currentPage={clientPage}
                                            totalItems={totalItems}
                                            itemsPerPage={CLIENT_ITEMS_PER_PAGE}
                                            onPageChange={setClientPage}
                                            pagesToShow={pagesToShow}
                                        />
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default WorkoutRoutineSessionClone;
