import AiPushGenerator from "../ai/AiPushGenerator";
import OffcanvasCloseButton from "../offcanvas/OffcanvasCloseButton";
import PushComposerFlow from "./PushComposerFlow";

const PushComposePanel = ({
    title,
    initialMode = "now",
    initialValues,
    lockedAudience,
    onSuccess,
    secondaryAction = null,
    isMobileSheet = false,
    onClose = null,
    closeButtonAriaLabel = "Close"
}) => (
    <div className={"flex-grow-1 d-flex flex-column"}>
        <div className={"flex-grow-1 overflow-auto"}>
            <div className={"mb-4"}>
                {isMobileSheet ? (
                    <>
                        <span className={"fw-semibold fs-4 d-block mb-3"}>{title}</span>
                        <div className={"d-flex justify-content-end"}>
                            <div className={"col-auto"}>
                                <AiPushGenerator/>
                            </div>
                        </div>
                    </>
                ) : (
                    <div className={"d-flex justify-content-between align-items-start gap-3"}>
                        <span className={"fw-semibold fs-4 d-block flex-grow-1 min-w-0"}>{title}</span>
                        <div className={"d-flex align-items-center gap-2 flex-shrink-0"}>
                            <AiPushGenerator/>
                            {onClose && (
                                <OffcanvasCloseButton
                                    onClick={onClose}
                                    ariaLabel={closeButtonAriaLabel}
                                />
                            )}
                        </div>
                    </div>
                )}
            </div>

            <PushComposerFlow
                initialMode={initialMode}
                initialValues={initialValues}
                lockedAudience={lockedAudience}
                compact={true}
                showAiGenerator={false}
                modeSelectorVariant={"radios"}
                lockedAudiencePlacement={"bottom"}
                secondaryAction={secondaryAction}
                onSuccess={onSuccess}
            />
        </div>
    </div>
);

export default PushComposePanel;
