import {useCallback, useEffect, useRef, useState} from "react";

const ExercisePlayer = ({src, poster, handleMediaClose, hideCloseBtn, onError}) => {
    const [isPlaying, setIsPlaying] = useState(false);
    const [muted, setMuted] = useState(false);
    const [videoHasNoAudio, setVideoHasNoAudio] = useState(false);
    const [progress, setProgress] = useState(0);

    const videoRef = useRef(null);

    const progressBarStyle = {
        width: `${progress}%`,
        height: "3px",
        background: "white",
    }

    const progressStyle = {
        width: "100%",
        height: "100%",
        background: "grey"
    }



    const handleMuted = () => {
        setMuted(prevMuted => !prevMuted)
    }

    const play = () => {
        if (videoRef.current) {
            if (!isPlaying) {
                setIsPlaying(true)
                videoRef.current.play();
            } else {
                setIsPlaying(false)
                videoRef.current.pause();
            }
        }
    };

    const checkVideoMuted = useCallback(() => {
        setVideoHasNoAudio(videoRef.current.muted)
    }, [setVideoHasNoAudio])

    const seek = (event) => {
        const percent = event.nativeEvent.offsetX / event.currentTarget.offsetWidth;
        videoRef.current.currentTime = percent * videoRef.current.duration;
    };

    useEffect(() => {
        checkVideoMuted()
    }, [checkVideoMuted])

    useEffect(() => {
        const video = videoRef.current;
        const updateProgress = () => {
            if (video.duration > 0) {
                setProgress((video.currentTime / video.duration) * 100);
            }
        };
        video.addEventListener('timeupdate', updateProgress);
        return () => video.removeEventListener('timeupdate', updateProgress);
    }, []);

    useEffect(() => {
        setIsPlaying(true)
    }, []);



    return (
        <div className={'row'}>
            <div className={'col-12'}>
                {
                    !hideCloseBtn &&
                    <button className={'no-style-btn position-absolute text-white text-end'}
                            style={{zIndex: "1300", top: "12px", right: "10px"}} onClick={handleMediaClose}>
                        <i className="fa-duotone  fa-square-xmark fa-2xl text-default-darker"
                           style={{"--fa-secondary-color": "#fff"}}></i>
                    </button>
                }
            </div>
            <div className={'col-12 '}>
                <video controlsList="nodownload noplaybackrate track" height={'100%'} width={"100%"}
                       onClick={play}
                       autoPlay={true}
                       loop={true}
                       ref={videoRef}
                       playsInline
                       poster={poster}
                       disablePictureInPicture
                       className={'rounded'}
                >
                    <source src={src} onError={onError}/>
                </video>
            </div>
            {
                !isPlaying &&
                <div className={'col-12'}>
                    <i className={' position-absolute top-50 start-50 translate-middle fa-duotone fa-circle-play text-default-darker'}
                       style={{"--fa-secondary-color": "#fff", fontSize: "4rem"}}
                       onClick={play}
                    ></i>
                </div>
            }
            {
                isPlaying && !hideCloseBtn &&
                <div
                    className={'row justify-content-center rounded-1 bg-default-darker opacity-75 d-flex position-absolute p-3'}
                    style={{bottom: "0", left: "12px", zIndex: "1300"}}>
                    <div className={'col-12  text-white '}>
                        <div className={'row justify-content-between d-flex'}>
                            <div className={'col-6 small align-self-center'}>
                                <span
                                    className={'fw-bold'}>{videoRef.current.currentTime.toFixed(2)} / {videoRef.current.duration.toFixed(2)}</span>
                            </div>
                            <div className={'col-6  text-end '}>
                                {
                                    !videoHasNoAudio ?
                                        <button
                                            className={'no-style-btn text-white  rounded    px-1 py-0'}
                                        >
                                            <i className="fa-solid fa-volume-slash"
                                            ></i>
                                        </button>
                                        :
                                        <button
                                            className={'no-style-btn text-white  rounded    px-1 py-0'}
                                            onClick={handleMuted}>
                                            <i className={` fa-solid fa-${muted ? 'volume-xmark' : 'volume'}  `}
                                            ></i>
                                        </button>
                                }
                            </div>
                        </div>
                    </div>
                    <div className={'col-12 align-self-center  pt-2 pb-2'}>
                        <div style={progressStyle} className={'rounded-4'} onClick={seek}>
                            <div style={progressBarStyle} className={'rounded-4'} id="progress"></div>
                        </div>
                    </div>
                </div>
            }
        </div>
    )
}

export default ExercisePlayer;