import axios from "axios";
import {apiUrl as url, getToken} from "../api";

const apiUrl = url + "/v2"
export const getAllFilesAPI = async (id) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/files/all?id=${id}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 20000
        })
}

export const getOneFileAPI = async (id, fileId) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/files/?id=${id}&fileId=${fileId}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 20000
        })
}

export const editFileNameAPI = async ({fileId, nome, clients, groups}) => {
    const token = getToken();
    if (!token) return;

    return await axios.put(
        `${apiUrl}/user/files/?fileId=${fileId}`,
        {nome, clients, groups},
        {
            headers: {
                "Content-Type": "application/json",
                authorization: token
            },
            timeout: 20000
        }
    );
};

export const deleteFileAPI = async (fileId, id) => {
    const token = getToken();
    if (!token) return;
    return await axios.delete(`${apiUrl}/user/files/?fileId=${fileId}&id=${id}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 20000
        })
}

export const saveFileAPI = async ({fileId, id, nome, url, clients, groups}) => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/user/files/?fileId=${fileId}&id=${id}`, {nome, url, clients, groups},
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 80000
        })
}
