import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {selectExerciseCategories, selectLibraryLoading} from "../../store/exercise-library/exerciseLibrarySelector";
import React, {useEffect, useState} from "react";
import {createCategory, fetchExerciseCategories} from "../../store/exercise-library/exerciseLibraryReducer";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import Modal from "react-bootstrap/Modal";
import * as Yup from "yup";
import {ErrorMessage, Field, Form, Formik} from "formik";
import ExerciseCategoryListItem from "../../components/exercise-library/ExerciseCategoryListItem";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import _ from "lodash";
import {selectWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionSelector";
import {fetchWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionReducer";

const ExerciseLibraryCategory = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {sessionId} = useParams();
    const loading = useSelector(selectLibraryLoading);
    const categories = useSelector(selectExerciseCategories);
    const [showCreateCategory, setShowCreateCategory] = useState(false);
    const [searchTerm, setSearchTerm] = useState("");
    const session = useSelector(selectWorkoutSession)
    useComponentTranslations('exerciseLibrary', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        if (sessionId) {
            navigate(`/user/client/${session.idAluno}/workout/routine/${session.idRoutine}/session/${session.id}/exercise-list`);
        } else
            navigate("/user/exercise-library");
    };

    const handleCreateCategory = () => {
        setShowCreateCategory(prevState => !prevState);
    };

    const initialValues = {name: ''};

    const validationSchema = Yup.object({
        name: Yup.string()
            .required(t("exerciseLibrary:categoryNameRequired"))
            .test('unique', t("exerciseLibrary:categoryExists"), function (value) {
                if (!value) return true;
                return !categories.some(category => category.name?.toLowerCase() === value.toLowerCase());
            }),
    });

    const onSubmit = (values) => {
        dispatch(createCategory(values));
    };

    useEffect(() => {
        dispatch(fetchExerciseCategories());
        if (sessionId)
            dispatch(fetchWorkoutSession(sessionId))
    }, [dispatch, sessionId]);

    useEffect(() => {
        if (!loading) {
            setShowCreateCategory(false);
        }
    }, [loading]);

    const normalizeString = (str) => {
        return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
    };

    const filteredCategories = categories?.filter(category =>
        normalizeString(category.name).includes(normalizeString(searchTerm))
    );

    return (
        <Page title={t("exerciseLibrary:categories")} goBackLink={handleGoBack} pb={"pb-2"} loading={loading}>
            <div className="row justify-content-center">
                <div className="col-12">
                    <div className="card card-body border-0">
                        <div className="row justify-content-end">
                            <div className="col-12">
                                <CardButtonAdd text={t("exerciseLibrary:createCategory")} handleClick={handleCreateCategory}/>
                            </div>
                            <div className="col-12 mt-3">
                                <input
                                    type="search"
                                    placeholder={t("exerciseLibrary:searchCategories")}
                                    className="form-control"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                            <div className="col-12 mt-3">
                                <ul className="list-unstyled">
                                    {_.map(filteredCategories, (cat) => (
                                        <ExerciseCategoryListItem key={cat.id} category={cat}/>
                                    ))}
                                </ul>
                                <Modal show={showCreateCategory} centered onHide={handleCreateCategory}>
                                    <Modal.Body>
                                        <div className="row justify-content-between">
                                            <div className="col-auto">
                                                <span className="fw-semibold">{t("exerciseLibrary:createNewCategoryTitle")}</span>
                                            </div>
                                            <div className="col-auto clickable-element" onClick={handleCreateCategory}>
                                                <span><i className="fa-regular fa-times"></i></span>
                                            </div>
                                            <div className="col-12 mt-3">
                                                <Formik
                                                    initialValues={initialValues}
                                                    validationSchema={validationSchema}
                                                    onSubmit={onSubmit}
                                                >
                                                    {formik => (
                                                        <Form>
                                                            <div className="mb-3">
                                                                <label htmlFor="name" className="form-label fw-semibold">
                                                                    {t("exerciseLibrary:categoryName")}
                                                                </label>
                                                                <Field
                                                                    type="text"
                                                                    id="name"
                                                                    name="name"
                                                                    className={`form-control ${formik.errors.name && formik.touched.name ? 'is-invalid' : ''}`}
                                                                />
                                                                <ErrorMessage name="name">
                                                                    {msg => <div className="invalid-feedback">{msg}</div>}
                                                                </ErrorMessage>
                                                            </div>
                                                            <div className="d-grid">
                                                                <button type="submit" className="btn btn-primary">
                                                                    {t("exerciseLibrary:save")}
                                                                </button>
                                                            </div>
                                                        </Form>
                                                    )}
                                                </Formik>
                                            </div>
                                        </div>
                                    </Modal.Body>
                                </Modal>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </Page>
    );
};

export default ExerciseLibraryCategory;
