import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectClientAddress, selectClientUpdated} from "../../store/client/clientSelector";
import {useEffect} from "react";
import {clientUpdated, fetchClientAddress, setClientAddress, updateClientAddress} from "../../store/client/clientReducer";
import {addToast} from "../../store/toast/toastReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const ClientAddress = ({client}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const loading = useSelector(isClientsLoading)
    const clientAddress = useSelector(selectClientAddress)
    const isClientUpdated = useSelector(selectClientUpdated)
    useComponentTranslations('client', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object({
        street: Yup.string().required(t("client:required")),
        number: Yup.string().required(t("client:required")),
        neighborhood: Yup.string().required(t("client:required")),
        city: Yup.string().required(t("client:required")),
        state: Yup.string().required(t("client:required")),
        cep: Yup.string().required(t("client:required")),
    });

    const initialValues = {
        street: clientAddress?.address || "",
        number: clientAddress?.number || "",
        complement: clientAddress?.complement || "",
        neighborhood: clientAddress?.neighborhood || "",
        city: clientAddress?.city || "",
        state: clientAddress?.state || "",
        cep: clientAddress?.cep || "",
    };

    const handleSubmit = (values) => {
        const payload = {
            id: client.id,
            formData: values
        }
        dispatch(updateClientAddress(payload))
    };

    useEffect(() => {
        if (client?.id)
            dispatch(fetchClientAddress(client.id))
        return () => {
            dispatch(setClientAddress(null))
        }
    }, [client, dispatch]);

    useEffect(() => {
        if (isClientUpdated) {
            dispatch(addToast(
                {
                    type: "success",
                    message: `${t("client:informationUpdate")}`,
                    title: `${t("client:allGood")}`
                }))
            dispatch(clientUpdated(false))
        }
    }, [dispatch, isClientUpdated, t])

    return (
        <div className={'card card-body border-0 mt-4'}>
            <Formik
                initialValues={initialValues}
                validationSchema={validationSchema}
                enableReinitialize={true}
                onSubmit={handleSubmit}
            >

                <Form className="needs-validation">
                    <div className="mb-3">
                        <label htmlFor="street" className=" fw-semibold">{t("client:address")}</label>
                        <Field
                            type="text"
                            id="street"
                            name="street"
                            className="form-control"
                        />
                        <ErrorMessage name="street" component="div" className="text-danger"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="number" className=" fw-semibold">{t("client:addressNumber")}</label>
                        <Field
                            type="text"
                            id="number"
                            name="number"
                            className="form-control"
                        />
                        <ErrorMessage name="number" component="div" className="text-danger"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="complement" className=" fw-semibold">{t("client:complement")}</label>
                        <Field
                            type="text"
                            id="complement"
                            name="complement"
                            className="form-control"
                        />
                    </div>

                    <div className="mb-3">
                        <label htmlFor="neighborhood" className=" fw-semibold">{t("client:neighborhood")}</label>
                        <Field
                            type="text"
                            id="neighborhood"
                            name="neighborhood"
                            className="form-control"
                        />
                        <ErrorMessage name="neighborhood" component="div" className="text-danger"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="city" className=" fw-semibold">{t("client:city")}</label>
                        <Field
                            type="text"
                            id="city"
                            name="city"
                            className="form-control"
                        />
                        <ErrorMessage name="city" component="div" className="text-danger"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="state" className="  fw-semibold">{t("client:state")}</label>
                        <Field
                            type="text"
                            id="state"
                            name="state"
                            className="form-control"
                        />
                        <ErrorMessage name="state" component="div" className="text-danger"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="cep" className=" fw-semibold">{t("client:cep")}</label>
                        <Field
                            type="text"
                            id="cep"
                            name="cep"
                            className="form-control"
                        />
                        <ErrorMessage name="cep" component="div" className="text-danger"/>
                    </div>
                    <div className={"d-grid"}>
                        <button type="submit" className="btn btn-primary" disabled={loading}>
                            {t("client:save")}
                        </button>
                    </div>
                </Form>
            </Formik>
        </div>
    )

}
export default ClientAddress