import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {selectLoading, selectPaymentCountry, selectUser} from "../../store/user/userSelector";
import {useCallback, useEffect, useState} from "react";
import {fetchUser, getPaymentCountry} from "../../store/user/userReducer";
import {useNavigate, useSearchParams} from "react-router-dom";
import {isDesktop} from "react-device-detect";
import {selectChangeSubLoading, selectFreePlanChanged} from "../../store/subscription/subscriptionSelector";
import Modal from "react-bootstrap/Modal";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import {changeUserSubscriptionToFreePlan, setLoadingSubChange} from "../../store/subscription/subscriptionReducer";
import {selectClientCount} from "../../store/client/clientSelector";
import {fetchClientCount} from "../../store/client/clientReducer";
import {Trans, useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {getToken} from "../../api/api";

const Subscription = () => {
    const {t} = useTranslation();
    const user = useSelector(selectUser)
    const userLoading = useSelector(selectLoading)
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const [searchParams] = useSearchParams();
    const step = searchParams.get("step");
    const goBackTo = searchParams.get("goBackTo");
    const [screenToShow, setScreenToShow] = useState(Number(step) || 0)
    const [showFreePlan, setShowFreePlan] = useState(false);
    const loadingSubPlan = useSelector(selectChangeSubLoading);
    const changedSubPlan = useSelector(selectFreePlanChanged);
    const [showClientPlanExceeded, setShowClientPlanExceeded] = useState(false);
    const clientCount = useSelector(selectClientCount)
    const totalCount = Number((clientCount?.status_0 || 0) + (clientCount?.status_1 || 0));
    const allowShowPlans = searchParams.get("showPlans");
    const paymentCountry = useSelector(selectPaymentCountry)

    useComponentTranslations('subscriptionPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const subCardStyle = {
        paddingTop: "2.2rem",
        paddingBottom: "2.2rem",
    }

    const handleShowClientLimitExceeded = () => {
        setShowClientPlanExceeded(prevState => !prevState);
    }

    const handleGoBack = () => {
        if (goBackTo === "subscription")
            navigate("/user/subscription")
        else
            navigate("/user")
    }

    const handleGoToClientList = () => {
        navigate("/exceeded-limit?deleteClient=true")
    }

    const handleFreePlanClick = () => {
        dispatch(changeUserSubscriptionToFreePlan())
    }

    const handleShowFrePlan = () => {
        if (totalCount > 1) {
            setShowFreePlan(false)
            handleShowClientLimitExceeded()
        } else
            setShowFreePlan(prevState => !prevState)
    }

    const handleSubClick = (type) => {
        if (totalCount > 3 && Number(type) === 1004) {
            setShowFreePlan(false)
            handleShowClientLimitExceeded()
        } else
            navigate(`/subscription/type/${type}${goBackTo ? `?goBackTo=${goBackTo}` : ""}`)
    }

    const handleNextScreen = useCallback(() => {
        setScreenToShow(1)
    }, [])

    useEffect(() => {
        if (!user)
            dispatch(fetchUser())
    }, [user, dispatch])

    useEffect(() => {
        if (!paymentCountry) {
            dispatch(getPaymentCountry())
        }
    },[dispatch, paymentCountry])

    useEffect(() => {
        dispatch(fetchClientCount())
    }, [dispatch]);

    useEffect(() => {
        if (user && (user?.subPlan.id >= 1000 || user.subPlan.id === 199)) {
            handleNextScreen()
        }
    }, [user, handleNextScreen])

    useEffect(() => {
        if (changedSubPlan) {
            dispatch(fetchUser())
            dispatch(setLoadingSubChange({changed: false, loading: false}));
            navigate("/user")
        }
    }, [changedSubPlan, navigate, dispatch])


    useEffect(() => {
        if (paymentCountry && user) {
            if (paymentCountry.country === "BRA") {
                if (user.subPlan.id >= 1000 || (user.subPlan.id === 199 && !allowShowPlans))
                    navigate("/user/subscription")
            } else {
                const token = getToken()
                window.location.href = `https://payments.mfitpersonal.com.br/redirect/${token}`
            }
        }
    }, [user, navigate, paymentCountry, allowShowPlans])

    return (
        <Page mt={"mt-n4"} contentHeader={true} goBackLink={handleGoBack}  loading={userLoading}>
            {
                screenToShow === 0 &&
                <div className={"card card-body border-0"}>
                    <div className={"row  mt-2"}>
                        <div className={"col-12"}>
                            <span className={"fs-1 fst-italic d-block lh-1  fw-light"}>
                                {t("subscriptionPage:heroLine1")}
                            </span>
                            <span className={"fs-1 fst-italic  fw-semibold d-block"}>
                                {t("subscriptionPage:heroLine2")}
                            </span>
                        </div>
                        <div className={"col-12 mt-2"}>
                            <span className={"fw-light"}>{t("subscriptionPage:heroDescription")}</span>
                        </div>
                        <div className={"col-6"}>
                            <hr/>
                        </div>
                    </div>
                    <div className={"row mt-4  mb-2"}>
                        <div className={"col-2 text-center align-self-center"}>
                            <RoundedIcon icon={"fa-dumbbell"}/>
                        </div>
                        <div className={"col-10 align-self-center"}>
                            <span className={"d-block"}>
                                <Trans t={t} i18nKey="subscriptionPage:bulletPrescribe" components={{bold: <span className={"fw-semibold"}/>}}/>
                            </span>
                        </div>
                    </div>
                    <div className={"row mt-4  mb-2"}>
                        <div className={"col-2 text-center align-self-center"}>
                            <RoundedIcon icon={"fa-video"}/>
                        </div>
                        <div className={"col-10 align-self-center"}>
                            <span className={"d-block"}>
                                <Trans t={t} i18nKey="subscriptionPage:bulletLibrary" components={{bold: <span className={"fw-semibold"}/>}}/>
                            </span>
                        </div>
                    </div>
                    <div className={"row mt-4  mb-2"}>
                        <div className={"col-2 text-center align-self-center"}>
                            <RoundedIcon icon={"fa-hand-holding-circle-dollar"}/>
                        </div>
                        <div className={"col-10 align-self-center"}>
                            <span className={"d-block"}>
                                <Trans t={t} i18nKey="subscriptionPage:bulletPayments" components={{bold: <span className={"fw-semibold"}/>}}/>
                            </span>
                        </div>
                    </div>
                    <div className={"row mt-4 mb-3"}>
                        <div className={"col-2 text-center align-self-center"}>
                            <RoundedIcon icon={"fa-headset"}/>
                        </div>
                        <div className={"col-10 align-self-center"}>
                            <span className={"d-block"}>
                                <Trans t={t} i18nKey="subscriptionPage:bulletSupport" components={{bold: <span className={"fw-semibold"}/>}}/>
                            </span>
                        </div>
                    </div>
                    <div className={"row mt-4  "}>
                        <div className={"col-12"}>
                            <button className={"btn btn-primary-lighter w-100"} onClick={handleNextScreen}>
                                {t("subscriptionPage:explorePlans")}
                            </button>
                        </div>
                    </div>
                </div>
            }
            {
                screenToShow === 1 &&
                <div className={"card card-body border-0"}>
                    <div className={"row  mt-2"}>
                        <div className={"col-12"}>
                            <span className={"fs-1 fst-italic d-block lh-1  fw-light"}>
                                {t("subscriptionPage:planIntroLine1")}
                            </span>
                            <span className={"fs-1 fst-italic  fw-semibold d-block"}>
                                {t("subscriptionPage:planIntroLine2")}
                            </span>
                        </div>
                        <div className={"col-12 mt-2"}>
                            <span
                                className={"fw-light"}>{t("subscriptionPage:interactInstruction", {action: isDesktop ? t("subscriptionPage:clickAction") : t("subscriptionPage:tapAction")})}</span>
                        </div>
                        <div className={"col-6"}>
                            <hr/>
                        </div>
                    </div>
                    <div className={"row"}>
                        <div className={"col-12 mt-2"}>
                            <div className={"card card-body clickable-element border-secondary-subtle"} style={subCardStyle}
                                 onClick={() => handleSubClick(1000)}>
                                <div className={"row justify-content-between"}>
                                    <div className={"col-auto align-self-center"}>
                                        <span className={"fw-semibold text-primary-lighter"}>{t("subscriptionPage:planUnlimitedTitle")}</span>
                                    </div>
                                    <div className={"col-auto text-end align-self-center"}>
                                        <span className={"d-block lh-1"}>
                                             <span className={"fw-semibold small"}>
                                                 <Trans t={t} i18nKey="subscriptionPage:planUnlimitedPrice" components={{price: <span className={"fs-4"}/>}}/>
                                             </span><span
                                            className={"small"}>{t("subscriptionPage:perMonth")}</span>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className={"col-12 mt-2"}>
                            <div className={"card card-body clickable-element border-secondary-subtle"} style={subCardStyle}
                                 onClick={() => handleSubClick(1004)}>
                                <div className={"row justify-content-between"}>
                                    <div className={"col-auto align-self-center"}>
                                        <span className={"fw-semibold text-primary-lighter"}>{t("subscriptionPage:planLimitedTitle")}</span>
                                    </div>
                                    <div className={"col-auto text-end align-self-center"}>
                                       <span className={"d-block lh-1"}>
                                             <span className={"fw-semibold small"}>
                                                 <Trans t={t} i18nKey="subscriptionPage:planLimitedPrice" components={{price: <span className={"fs-4"}/>}}/>
                                             </span><span
                                           className={"small"}>{t("subscriptionPage:perMonth")}</span>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className={"col-12 mt-2"}>
                            <div className={"card card-body clickable-element border-secondary-subtle"} style={subCardStyle} onClick={handleShowFrePlan}>
                                <div className={"row justify-content-between"}>
                                    <div className={"col-8 align-self-center"}>
                                        <span className={"fw-semibold text-primary-lighter"}>{t("subscriptionPage:planFreeTitle")}</span>
                                    </div>
                                    <div className={"col-4 text-end align-self-center"}>
                                        <span className={"d-block lh-1 fw-semibold "}>
                                            {t("subscriptionPage:free")}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            }
            <Modal show={showFreePlan} onHide={handleShowFrePlan} centered>
                <Modal.Body>
                    <div className={"row justify-content-center"}>
                        <div className={"col-12 text-center mt-2 mb-2"}>
                            <RoundedIcon size={"lg"} icon={"fa-regular fa-user-lock"}/>
                        </div>
                        <div className={"col-12 text-center mt-2 mb-2"}>
                            <span className={" fs-1"}>
                                <Trans t={t} i18nKey="subscriptionPage:freePlanTitle" components={{bold: <span className={"fw-semibold"}/>}}/>
                            </span>
                        </div>
                        <div className={"col-12 text-center   mb-3"}>
                            <span className={"fs-5"}>
                                <Trans t={t} i18nKey="subscriptionPage:freePlanDescription" components={{bold: <span className={"fw-semibold"}/>}}/>
                            </span>
                        </div>
                        <div className={"col-12 text-center   mb-2"}>
                            <button className={"btn btn-outline-primary w-100"} onClick={handleFreePlanClick}
                                    disabled={loadingSubPlan}>{t("subscriptionPage:acceptFreePlan")}
                            </button>
                        </div>
                        <div className={"col-12 text-center   mb-2"}>
                            <button className={"btn btn-primary w-100"} onClick={handleShowFrePlan}>{t("subscriptionPage:chooseAnotherPlan")}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            <Modal show={showClientPlanExceeded} onHide={handleShowClientLimitExceeded} centered>
                <Modal.Body>
                    <div className={"row justify-content-center"}>
                        <div className={"col-12 text-center mt-2 mb-2"}>
                            <RoundedIcon size={"lg"} icon={"fa-regular fa-info-circle"}/>
                        </div>
                        <div className={"col-12 text-center mt-2 mb-2"}>
                            <span className={" fs-1"}>
                                <Trans t={t} i18nKey="subscriptionPage:freePlanLimitTitle" components={{bold: <span className={"fw-semibold"}/>}}/>
                            </span>
                        </div>
                        <div className={"col-12 text-center   mb-3"}>
                            <span className={"fs-5"}>
                                <Trans t={t} i18nKey="subscriptionPage:freePlanLimitDescription" components={{bold: <span className={"fw-semibold"}/>}}
                                       values={{count: totalCount}}/>
                            </span>
                        </div>
                        <div className={"col-12 text-center   mb-2"}>
                            <button className={"btn btn-primary w-100"}
                                    onClick={handleShowClientLimitExceeded}>{t("subscriptionPage:chooseAnotherPlan")}</button>
                        </div>
                        <div className={"col-12 text-center   mb-2"}>
                            <button className={"btn btn-outline-danger w-100"} onClick={handleGoToClientList}>{t("subscriptionPage:removeClients")}
                            </button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </Page>
    )
}

export default Subscription;