import {all, call, put, takeLatest} from 'redux-saga/effects';
import {updateAerobicName} from "../workout-library/workoutLibraryReducer";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    createAerobicAPI, createAerobicDayAPI,
    createPaceAPI, deleteDayAPI,
    deletePaceAPI, getAerobicByIdAPI,
    getAerobicsByStatusAPI,
    getAllPacesAPI, updateAerobicInstructionAPI,
    updateAerobicNameAPI,
    updateAerobicStatusAPI, updateWorkoutAerobicDayAPI
} from "../../api/workout-aerobic/workoutAerobicActions";
import {
    createPace,
    createPaceSuccess,
    deletePace,
    deletePaceSuccess,
    fetchAerobicsByStatus,
    fetchAllPaces,
    setPaces,
    updateName,
    updateNameSuccess,
    onError,
    changeAerobicStatus,
    changeStatusSuccess,
    setAerobics,
    createAerobic,
    aerobicInstructionsUpdated,
    updateAerobicInstructions,
    setAerobic,
    getAerobic,
    updateAerobicDay,
    deleteDay,
    aerobicDayCreated,
    createAerobicDay,
    setCreateAerobicStatus,
    updateAerobicWorkoutName,
    setAerobicDayUpdated
} from "./workoutAerobicReducer";


export function* updateAerobicNameAsync(action) {
    try {
        yield call(updateAerobicNameAPI, action.payload);
        yield put(updateNameSuccess(true))
        yield put(updateAerobicName(action.payload))
        yield put(updateAerobicWorkoutName(action.payload))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateAerobicName() {
    yield takeLatest(updateName.type, updateAerobicNameAsync);
}

export function* fetchAllPacesAsync(action) {
    try {
        const response = yield call(getAllPacesAPI, action.payload)
        yield put(setPaces(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchAllPaces() {
    yield takeLatest(fetchAllPaces.type, fetchAllPacesAsync);
}

export function* deletePaceAsync(action) {
    try {
        yield call(deletePaceAPI, action.payload)
        yield put(deletePaceSuccess(action.payload))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDeletePace() {
    yield takeLatest(deletePace.type, deletePaceAsync);
}

export function* createPaceAsync(action) {
    try {
        const response = yield call(createPaceAPI, action.payload)
        yield put(createPaceSuccess(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreatePace() {
    yield takeLatest(createPace.type, createPaceAsync);
}

export function* fetchAerobicsByStatusAsync(action) {
    try {
        const {id, status} = action.payload
        const response = yield call(getAerobicsByStatusAPI, id, status)
        yield put(setAerobics(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchAerobicsByStatus() {
    yield takeLatest(fetchAerobicsByStatus.type, fetchAerobicsByStatusAsync);
}

export function* changeAerobicStatusAsync(action) {
    try {
        const {id, status} = action.payload
        yield call(updateAerobicStatusAPI, id, status)
        yield put(changeStatusSuccess(id))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onChangeAerobicStatus() {
    yield takeLatest(changeAerobicStatus.type, changeAerobicStatusAsync);
}

export function* onCreateAerobicAsync(action) {
    try {
        const response = yield call(createAerobicAPI, action.payload)
        yield put(setCreateAerobicStatus(true))
        yield put(setAerobic(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreateAerobic() {
    yield takeLatest(createAerobic.type, onCreateAerobicAsync);
}

export function* onUpdateAerobicInstructionAsync(action) {
    try {
        const {id, data} = action.payload
        yield call(updateAerobicInstructionAPI, id, data)
        yield put(aerobicInstructionsUpdated())
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateAerobicInstruction() {
    yield takeLatest(updateAerobicInstructions.type, onUpdateAerobicInstructionAsync);
}


export function* onGetAerobicByIdAsync(action) {
    try {
        const response = yield call(getAerobicByIdAPI, action.payload)
        yield put(setAerobic(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onGetAerobicById() {
    yield takeLatest(getAerobic.type, onGetAerobicByIdAsync);
}

export function* updateAerobicDayAsync(action) {
    try {
        yield call(updateWorkoutAerobicDayAPI, action.payload)
        yield put(setAerobicDayUpdated())
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateAerobicDay() {
    yield takeLatest(updateAerobicDay.type, updateAerobicDayAsync);
}

export function* onDeleteAerobicDayAsync(action) {
    try {
        const {id, runningId} = action.payload;
        yield call(deleteDayAPI, id, runningId)
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDeleteAerobicDay() {
    yield takeLatest(deleteDay.type, onDeleteAerobicDayAsync);
}

export function* createAerobicDayAsync(action) {

    try {
        const response = yield call(createAerobicDayAPI, action.payload)
        yield put(aerobicDayCreated(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreateAerobicDay() {
    yield takeLatest(createAerobicDay.type, createAerobicDayAsync);
}

export function* workoutAerobicSaga() {
    yield all([
        call(onUpdateAerobicName),
        call(onFetchAllPaces),
        call(onDeletePace),
        call(onCreatePace),
        call(onFetchAerobicsByStatus),
        call(onChangeAerobicStatus),
        call(onCreateAerobic),
        call(onUpdateAerobicInstruction),
        call(onGetAerobicById),
        call(onUpdateAerobicDay),
        call(onDeleteAerobicDay),
        call(onCreateAerobicDay)
    ]);
}