import React, {useMemo} from 'react';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import 'react-international-phone/style.css';
import {PhoneInput} from "react-international-phone";
import {useDispatch, useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";
import {saveBuyerInfo} from "../../store/subscription/subscriptionReducer";
import InputMask from "react-input-mask";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const validateCPF = (cpf) => {
    if (!cpf) return false;
    const digits = cpf.replace(/\D/g, '');
    if (!/^\d{11}$/.test(digits)) return false;
    if (/^(\d)\1{10}$/.test(digits)) return false;
    const calculateCheckDigit = (base) => {
        let sum = 0;
        for (let i = 0; i < base.length; i++) {
            sum += Number(base.charAt(i)) * ((base.length + 1) - i);
        }
        const result = (sum * 10) % 11;
        return result === 10 ? 0 : result;
    };
    const base = digits.substring(0, 9);
    const digit1 = calculateCheckDigit(base);
    const digit2 = calculateCheckDigit(base + digit1);
    return digit1 === Number(digits.charAt(9)) && digit2 === Number(digits.charAt(10));
};

const SubscriptionUserInfo = () => {
    const {t} = useTranslation();
    const translationsLoaded = useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const dispatch = useDispatch();
    const user = useSelector(selectUser);

    const validationSchema = useMemo(() => Yup.object().shape({
        fullName: Yup.string()
            .test('two-names', t('subscriptionComponent:subscriptionUserInfo.errors.twoNames'), value =>
                value && value.trim().split(/\s+/).length >= 2
            )
            .required(t('subscriptionComponent:subscriptionUserInfo.errors.fullNameRequired')),
        cpf: Yup.string()
            .required(t('subscriptionComponent:subscriptionUserInfo.errors.cpfRequired'))
            .test('valid-cpf', t('subscriptionComponent:subscriptionUserInfo.errors.invalidCpf'), value => validateCPF(value)),
        phone: Yup.string()
            .required(t('subscriptionComponent:subscriptionUserInfo.errors.phoneRequired')),
        // eslint-disable-next-line
    }), [t, translationsLoaded]);

    const initialValues = user ? {
        fullName: `${user.nome} ${user.sobrenome}`,
        cpf: user.cpf ?? "",
        phone: user.waId ?? ""
    } : {
        fullName: ``,
        cpf: '',
        phone: ''
    };

    const handleSubmit = (values) => {
        dispatch(saveBuyerInfo(values));
    };

    if (!translationsLoaded) {
        return null;
    }

    return (
        <Formik
            initialValues={initialValues}
            validationSchema={validationSchema}
            enableReinitialize={true}
            onSubmit={handleSubmit}
        >
            {({touched, errors, setFieldValue, values, setFieldTouched}) => (
                <Form>
                    <div className="form-group mt-2">
                        <label htmlFor="fullName" className="fw-semibold">{t('subscriptionComponent:subscriptionUserInfo.fields.fullName')}</label>
                        <Field
                            id="fullName"
                            name="fullName"
                            className={`form-control ${touched.fullName && errors.fullName ? 'is-invalid' : ''}`}
                        />
                        <ErrorMessage name="fullName" component="div" className="invalid-feedback"/>
                    </div>
                    <div className="form-group mt-2">
                        <label htmlFor="cpf" className="fw-semibold">{t('subscriptionComponent:subscriptionUserInfo.fields.cpf')}</label>
                        <Field name="cpf">
                            {({ field, form }) => (
                                <InputMask
                                    mask="999.999.999-99"
                                    maskChar={null}
                                    value={field.value}
                                    onChange={e => form.setFieldValue(field.name, e.target.value)}
                                    onBlur={() => form.setFieldTouched(field.name, true)}
                                >
                                    {(inputProps) => (
                                        <input
                                            {...inputProps}
                                            id="cpf"
                                            className={`form-control ${form.touched.cpf && form.errors.cpf ? 'is-invalid' : ''}`}
                                        />
                                    )}
                                </InputMask>
                            )}
                        </Field>
                        <ErrorMessage name="cpf" component="div" className="invalid-feedback"/>
                    </div>
                    <div className="form-group mt-2">
                        <label htmlFor="phone" className="fw-semibold">{t('subscriptionComponent:subscriptionUserInfo.fields.phone')}</label>
                        <Field name="phone">
                            {() => (
                                <PhoneInput
                                    defaultCountry="br"
                                    value={values.phone}
                                    onChange={value => setFieldValue('phone', value)}
                                    onBlur={() => setFieldTouched('phone', true)}
                                    inputClassName={`form-control ${touched.phone && errors.phone ? 'is-invalid' : ''}`}
                                />
                            )}
                        </Field>
                        <ErrorMessage name="phone" component="div" className="invalid-feedback"/>
                    </div>
                    <button type="submit" className="btn btn-primary mt-3 w-100">{t('subscriptionComponent:next')}</button>
                </Form>
            )}
        </Formik>
    );
};

export default SubscriptionUserInfo;
