import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {useEffect} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {isWorkoutAerobicLoading, selectAerobic, selectCreateAerobicStatus} from "../../store/workout-aerobic/workoutAerobicSelector";
import * as Yup from "yup";
import {ErrorMessage, Field, Form, Formik} from "formik";
import {createAerobic, setCreateAerobicStatus} from "../../store/workout-aerobic/workoutAerobicReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutAerobicCreate = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {clientId} = useParams()
    const isLibrary = Number(clientId) === 0;
    const client = useSelector(selectSelectedClient)
    const workoutLoading = useSelector(isWorkoutAerobicLoading)
    const aerobic = useSelector(selectAerobic)
    const aerobicCreated = useSelector(selectCreateAerobicStatus)
    useComponentTranslations('aerobicWorkout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        if (clientId > 0) {
            navigate(`/user/client/${clientId}/workout/2`)
        } else {
            navigate(`/user/workout-library/2`)
        }

    }

    const initialValues = {
        name: '',
        type: '',
        workoutCount: '',
        start: '',
        clientId: clientId || 0,
        end: '',
    };
    const validationSchema = Yup.object().shape({
        name: Yup.string()
            .min(2, t("aerobicWorkout:2chars"))
            .max(45, t("aerobicWorkout:maxCharsAerobic"))
            .required(t("aerobicWorkout:required")),
        type: Yup.string().required(t("aerobicWorkout:required")),
        workoutCount: Yup.number()
            .nullable()
            .transform((value, originalValue) => {
                if (typeof originalValue === "string" && originalValue.trim() === "") {
                    return null;
                }
                return value;
            })
            .when(['type'], ([type], schema) => {
                return type === 'numberOfWorkouts'
                    ? schema
                        .required(t("aerobicWorkout:required"))
                        .min(1, t("aerobicWorkout:minWorkout"))
                        .max(31, t("aerobicWorkout:maxWorkout"))
                    : schema;
            }),
        start: Yup.date()
            .nullable()
            .transform((value, originalValue) =>
                originalValue === '' ? null : value
            )
            .when(['type'], ([type], schema) => {
                return type === 'dateInterval'
                    ? schema.required(t("aerobicWorkout:required"))
                    : schema;
            }),
        end: Yup.date()
            .nullable()
            .transform((value, originalValue) =>
                originalValue === '' ? null : value
            )
            .when(['type'], ([type], schema) => {
                return type === 'dateInterval'
                    ? schema
                        .required(t("aerobicWorkout:required"))
                        .min(Yup.ref('start'), t("aerobicWorkout:startDateEndDate"))
                    : schema;
            }),
    });

    const handleSubmit = (values) => {
        dispatch(createAerobic(values))
    };

    useEffect(() => {
        if ((!client || client.id !== Number(clientId)) && !isLibrary)
            dispatch(fetchClient(clientId));

    }, [dispatch, clientId, client, isLibrary]);

    useEffect(() => {
        if (aerobicCreated) {
            dispatch(setCreateAerobicStatus(false))
            navigate(`/user/client/${clientId}/workout/aerobic/view/${aerobic?.id}`)
        }
    }, [aerobic, navigate, clientId, dispatch, aerobicCreated]);

    return (
        <>
            {
                !isLibrary &&
                <AvatarHeader className={"pb-4 pt-2"}
                              text={`${client?.nome} ${client?.sobrenome}`}
                              url={client?.profileUrl} showGoBack={handleGoBack}/>
            }
            <Page contentHeader={isLibrary} loading={workoutLoading} goBackLink={handleGoBack} mt={`${isLibrary ? "mt-n5" : "mt-n4"}`}
                  title={`${isLibrary && t("aerobicWorkout:createPlan")}`}>
                <div className={"row justify-content-center "}>
                    <div className={'col-12'}>
                        <div className={'card card-body border-0'}>
                            <Formik
                                initialValues={initialValues}
                                validationSchema={validationSchema}
                                onSubmit={handleSubmit}
                            >
                                {({values}) => (
                                    <Form>
                                        <div className="form-group">
                                            <label htmlFor="name" className={"fw-semibold"}>{t("aerobicWorkout:name")}</label>
                                            <Field name="name" className="form-control"/>
                                            <ErrorMessage name="name" component="div" className="text-danger"/>
                                        </div>
                                        <div className="form-group mt-2">
                                            <label className={"fw-semibold"}>{t("aerobicWorkout:type")}</label>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="type"
                                                    value="numberOfWorkouts"
                                                    className="form-check-input"
                                                    id="numberOfWorkouts"
                                                />
                                                <label className="form-check-label" htmlFor="numberOfWorkouts">
                                                    {t("aerobicWorkout:workoutNumber")}
                                                </label>
                                            </div>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="type"
                                                    value="dateInterval"
                                                    className="form-check-input"
                                                    id="dateInterval"
                                                />
                                                <label className="form-check-label" htmlFor="dateInterval">
                                                    {t("aerobicWorkout:dateInterval")}
                                                </label>
                                            </div>
                                            <ErrorMessage name="type" component="div" className="text-danger"/>
                                        </div>

                                        {values.type === 'numberOfWorkouts' && (
                                            <div className="form-group mt-2">
                                                <label htmlFor="workoutCount" className={"fw-semibold"}>{t("aerobicWorkout:workoutNumber")}</label>
                                                <Field
                                                    name="workoutCount"
                                                    type="number"
                                                    className="form-control"
                                                    min="1"
                                                    max="31"
                                                />
                                                <ErrorMessage name="workoutCount" component="div" className="text-danger"/>
                                            </div>
                                        )}

                                        {values.type === 'dateInterval' && (
                                            <>
                                                <div className="form-group mt-2">
                                                    <label htmlFor="start" className={"fw-semibold"}>{t("aerobicWorkout:start")}</label>
                                                    <Field name="start" type="date" className="form-control"/>
                                                    <ErrorMessage name="start" component="div" className="text-danger"/>
                                                </div>
                                                <div className="form-group">
                                                    <label htmlFor="end">{t("aerobicWorkout:end")}</label>
                                                    <Field name="end" type="date" className="form-control"/>
                                                    <ErrorMessage name="end" component="div" className="text-danger"/>
                                                </div>
                                            </>
                                        )}
                                        <button type="submit" className="btn btn-primary mt-3 w-100" disabled={workoutLoading}>
                                            {t("aerobicWorkout:save")}
                                        </button>
                                    </Form>
                                )}
                            </Formik>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    )
}
export default WorkoutAerobicCreate;
