import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import React from "react";
import {useSelector} from "react-redux";
import {selectBalance} from "../../store/wallet/walletSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionWalletSelected = ({handleChangePaymentMethod}) => {
    const {t} = useTranslation();
    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const balance = useSelector(selectBalance)
    if(!balance)
        return null;
    return (
        <div className={"card card-body "}>
            <div className={"row "}>
                <div className={"col-2 text-center  align-self-center"}>
                    <i className={"fa-regular fa-wallet fa-xl"}></i>
                </div>
                <div className={"col-10 ps-1 justify-content-between align-self-center"}>
                    <div className={"row"}>
                        <div className={"col-8"}>
                            <span className={"fw-semibold d-block "}>{t('subscriptionComponent:paymentMethodSelector.wallet')}</span>
                            <span className={"small"}>{t('subscriptionComponent:paymentMethodSelector.balance')}</span> <span className={" text-primary fw-semibold"}><CurrencyFormatter
                            value={balance.current_balance}/></span>
                        </div>
                        <div className={"col-4 align-self-center text-end"}>
                            <span className={"fw-semibold text-primary clickable-element"} onClick={handleChangePaymentMethod}>{t('subscriptionComponent:changePaymentMethod')}</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default SubscriptionWalletSelected;