import React from 'react';
import {Carousel} from "react-bootstrap";

const ImageCarousel = ({images}) => {
    if (!images || images.length === 0) {
        return null;
    }

    return (
        <Carousel>
            {images.map((imgObj) => (
                <Carousel.Item key={imgObj.id}>
                    <img
                        className="d-block w-100"
                        src={imgObj.url}
                        alt={`Slide ${imgObj.id}`}
                    />
                </Carousel.Item>
            ))}
        </Carousel>
    );
}

export default ImageCarousel;