const normalizeComparableId = (value) => {
    if (value === null || value === undefined || value === "") {
        return null;
    }

    return String(value);
};

export const createSubmitResult = ({
    status = "idle",
    action = null,
    flow = null,
    entityId = null,
    clientId = null,
    error = null,
} = {}) => ({
    status,
    action,
    flow,
    entityId,
    clientId,
    error,
});

export const createPendingSubmitResult = ({
    action = null,
    flow = null,
    entityId = null,
    clientId = null,
} = {}) => createSubmitResult({
    status: "pending",
    action,
    flow,
    entityId,
    clientId,
});

export const createSuccessSubmitResult = ({
    action = null,
    flow = null,
    entityId = null,
    clientId = null,
} = {}) => createSubmitResult({
    status: "success",
    action,
    flow,
    entityId,
    clientId,
});

export const createErrorSubmitResult = (submitResult, error = null) =>
    createSubmitResult({
        status: "error",
        action: submitResult?.action ?? null,
        flow: submitResult?.flow ?? null,
        entityId: submitResult?.entityId ?? null,
        clientId: submitResult?.clientId ?? null,
        error,
    });

export const matchesSubmitResult = (submitResult, criteria = {}) => {
    if (!submitResult) {
        return false;
    }

    if (criteria.status && submitResult.status !== criteria.status) {
        return false;
    }

    if (criteria.action && submitResult.action !== criteria.action) {
        return false;
    }

    if (criteria.flow && submitResult.flow !== criteria.flow) {
        return false;
    }

    if (criteria.clientId !== undefined && criteria.clientId !== null) {
        if (normalizeComparableId(submitResult.clientId) !== normalizeComparableId(criteria.clientId)) {
            return false;
        }
    }

    return true;
};

export const isSubmitSuccessful = (submitResult) => submitResult?.status === "success";
