import React, {useCallback, useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {
    selectCurrentFolder,
    selectCurrentFolderLoading,
    selectFolderDeleted,
    selectLoadingDeletingFolder,
} from "../../store/workout-library/workoutLibrarySelector";
import WorkoutFolderEditModal from "../../components/workout-library/WorkoutFolderEditModal";
import EmptySet from "../../components/empty-set/EmptySet";
import {useNavigate, useParams} from "react-router-dom";
import {
    deleteFolder,
    fetchCurrentFolder,
    folderDeleted,
    setCurrentFolder,
} from "../../store/workout-library/workoutLibraryReducer";
import {addToast} from "../../store/toast/toastReducer";
import Text from "../../components/utils/emoji/Text";
import Page from "../../components/page/Page";
import WorkoutLibraryWorkoutItem from "../../components/workout-library/WorkoutLibraryWorkoutItem";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import Pagination from "../../components/pagination/Pagination";

const WorkoutLibraryFolder = () => {
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {folderId, type} = useParams();
    const folder = useSelector(selectCurrentFolder);
    const [showEditFolder, setShowEditFolder] = useState(false);
    const folderLoading = useSelector(selectCurrentFolderLoading);
    const dispatch = useDispatch();
    const loadingFolderDelete = useSelector(selectLoadingDeletingFolder);
    const isFolderDeleted = useSelector(selectFolderDeleted);
    const [searchQuery, setSearchQuery] = useState("");
    const [filteredRoutines, setFilteredRoutines] = useState([]);
    useComponentTranslations('trainingLibrary', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(10);
    const pagesToShow = 5;

    const handleGoBack = useCallback(() => {
        navigate(`/user/workout-library/${Number(type) + 1}`);
    }, [navigate, type]);

    const handleEditFolder = () => {
        setShowEditFolder((prevState) => !prevState);
    };

    const handleDeleteFolder = () => {
        if (!folder?.treinos || folder?.treinos.length === 0) {
            dispatch(deleteFolder(folder?.id));
        } else {
            dispatch(
                addToast({
                    type: "warning",
                    message: t("trainingLibrary:needRemoveRoutinesBeforeDelete"),
                    title: t("trainingLibrary:deleteNotPerformed"),
                    delay: 5000,
                })
            );
        }
    };

    useEffect(() => {
        if (folderId)
            dispatch(fetchCurrentFolder({id: folderId, type: Number(type)}));
        return () => {
            dispatch(setCurrentFolder(null));
        };
    }, [folderId, dispatch, type]);

    useEffect(() => {
        if (isFolderDeleted) {
            dispatch(folderDeleted({folderId: null, payload: false}));
            handleGoBack();
        }
    }, [isFolderDeleted, dispatch, handleGoBack]);

    useEffect(() => {
        if (!folder || !folder.treinos) {
            setFilteredRoutines([]);
            return;
        }
        const normalizeString = (str) => {
            return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
        };
        const query = normalizeString(searchQuery);
        let filtered;
        if (!searchQuery) {
            filtered = folder.treinos;
        } else {
            filtered = folder.treinos.filter((routine) => {
                const name = normalizeString(routine.nome);
                return name.includes(query);
            });
        }
        setFilteredRoutines(filtered);
    }, [searchQuery, folder]);

    const totalItems = filteredRoutines?.length || 0;
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentItems = filteredRoutines?.slice(indexOfFirstItem, indexOfLastItem);

    useEffect(() => {
        const totalPages = Math.ceil(totalItems / itemsPerPage);
        if (currentPage > totalPages && totalPages > 0) {
            setCurrentPage(totalPages);
        }
    }, [currentPage, totalItems, itemsPerPage]);

    return (
        <Page
            title={<Text>{folder?.name}</Text>}
            pb={"pb-2"}
            goBackLink={handleGoBack}
            loading={folderLoading}
        >
            {folder && folder.id > 0 && (
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            {folder.treinos && folder.treinos.length > 0 && (
                                <>
                                    {folder.treinos.length > 5 && (
                                        <div className={"col-12 mb-3"}>
                                            <input
                                                className={"form-control"}
                                                placeholder={t("trainingLibrary:searchPlaceholder")}
                                                value={searchQuery}
                                                onChange={(e) => {
                                                    setCurrentPage(1);
                                                    setSearchQuery(e.target.value);
                                                }}
                                            />
                                        </div>
                                    )}
                                    {filteredRoutines.length === 0 ? (
                                        <div className="alert alert-info">
                                            {t("trainingLibrary:noRoutinesFound")}
                                        </div>
                                    ) : (
                                        <>
                                            <div className={"row mb-2"}>
                                                <div className={"col-12"}>
                                                    <span className={"fw-semibold"}>
                                                        {t("trainingLibrary:routinesLabel")}
                                                    </span>
                                                </div>
                                            </div>
                                            {currentItems.map((workout, index) => (
                                                <WorkoutLibraryWorkoutItem
                                                    workout={workout}
                                                    key={index}
                                                    type={Number(type)}
                                                />
                                            ))}
                                            {totalItems > itemsPerPage && (
                                                <div className={'row justify-content-center mt-3'}>
                                                    <div className={'col-auto'}>
                                                        <Pagination
                                                            currentPage={currentPage}
                                                            totalItems={totalItems}
                                                            itemsPerPage={itemsPerPage}
                                                            onPageChange={setCurrentPage}
                                                            pagesToShow={pagesToShow}
                                                        />
                                                    </div>
                                                </div>
                                            )}
                                        </>
                                    )}
                                </>
                            )}
                            {(!folder.treinos || folder.treinos.length === 0) && (
                                <EmptySet
                                    icon={"fa-folder-open"}
                                    message={t("trainingLibrary:folderEmpty")}
                                />
                            )}
                            <div className={"row justify-content-between pt-3"}>
                                <div className={"col-12"}>
                                    <div className={"d-grid mb-2"}>
                                        <button
                                            className={"btn btn-outline-primary"}
                                            onClick={handleEditFolder}
                                        >
                                            {t("trainingLibrary:editFolder")}
                                        </button>
                                    </div>
                                    <div className={"d-grid"}>
                                        <button
                                            className={"btn btn-outline-danger"}
                                            onClick={handleDeleteFolder}
                                            disabled={loadingFolderDelete}
                                        >
                                            {t("trainingLibrary:deleteFolder")}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <WorkoutFolderEditModal
                        folder={folder}
                        showModal={showEditFolder}
                        handleShowModal={handleEditFolder}
                    />
                </div>
            )}
        </Page>
    );
};

export default WorkoutLibraryFolder;
