import _ from "lodash";
import {useNavigate, useParams} from "react-router-dom";
import {useEffect, useState} from "react";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import {
    getSubmitResult,
    isAnamnesisLoading,
    isSubmitLoading,
    selectAnamnesis
} from "../../store/anamnesis/anamnesisSelector";
import {
    clearAnamnesis, createAnamnesis, getAnamnesisModel, resetFormSent
} from "../../store/anamnesis/anamnesisReducer";
import {fetchClient} from "../../store/client/clientReducer";
import AnamnesisQuestion from "../../components/anamnesis/AnamnesisQuestion";
import {useTranslation} from "react-i18next";
import {useDispatch, useSelector} from "react-redux";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Page from "../../components/page/Page";
import EvaluationSuccessCard from "../../components/evaluation-components/EvaluationSuccessCard";
import {
    buildAnamnesisAnsweredRoute,
    buildAnamnesisListRoute
} from "../../utils/client/evaluationRoutes";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {buildCreateAnamnesisPayload} from "../../utils/anamnesis/createPayload";

const AnamnesisAnswerFlow = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {clientId, modelId} = useParams();
    const anamnesis = useSelector(selectAnamnesis);
    const loading = useSelector(isAnamnesisLoading);
    const submitLoading = useSelector(isSubmitLoading);
    const submitResult = useSelector(getSubmitResult)
    const currentClientId = Number(clientId);

    useComponentTranslations('anamnesis', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const [step, setStep] = useState(0);
    const showCompletionMessage = isMatchingSubmitSuccess(submitResult, {
        action: "create",
        flow: EVALUATION_FLOWS.ANAMNESIS_ANSWER,
        clientId: currentClientId
    });
    const createdAnamnesisId = showCompletionMessage ? submitResult?.entityId ?? null : null;

    const moveForward = () => {
        setStep((currentStep) => currentStep + 1)
    }
    const moveBackwards = () => {
        setStep((currentStep) => currentStep - 1)
    }

    const goBackToApp = () => {
        dispatch(resetFormSent())
        dispatch(clearAnamnesis());
        navigate(buildAnamnesisListRoute(clientId));
    }

    const handleFormSubmit = async (finalAnamnesis) => {
        const payload = buildCreateAnamnesisPayload(finalAnamnesis, clientId);
        dispatch(createAnamnesis(payload, {
            flow: EVALUATION_FLOWS.ANAMNESIS_ANSWER,
            clientId: currentClientId
        }));
    };

    const handlePreviousAnamnesis = () => {
        if (!createdAnamnesisId) {
            return;
        }
        navigate(buildAnamnesisAnsweredRoute(clientId, createdAnamnesisId));
    };

    useEffect(() => {
        dispatch(fetchClient(clientId));
        dispatch(resetFormSent());
        dispatch(clearAnamnesis());
        if (modelId) {
            dispatch(getAnamnesisModel(modelId));
        }
    }, [dispatch, modelId, clientId]);

    useEffect(() => {
        return () => {
            dispatch(clearAnamnesis())
            dispatch(resetFormSent())
        }
    }, [dispatch])

    return (
        <Page
            title={anamnesis?.name}
            loading={loading}
            goBackLink={goBackToApp}
            mt={"mt-n5"}
        >
            {
                anamnesis && !showCompletionMessage &&
                <div className={'row justify-content-center d-flex'}>
                    <div className={"col-12"}>
                        {_.map(anamnesis.questions, (question, index) => (
                            index === step &&
                            <AnamnesisQuestion
                                key={question.id}
                                moveForward={moveForward}
                                moveBackwards={moveBackwards}
                                maxStep={anamnesis.questions.length - 1}
                                currentStep={step}
                                anamnesis={anamnesis}
                                question={question}
                                handleFormSubmit={handleFormSubmit}
                                isSubmitting={submitLoading}
                            />
                        ))}
                    </div>
                </div>
            }
            {
                !loading && showCompletionMessage &&
                <div className={'row justify-content-center d-flex'}>
                    <div className={"col-12"}>
                        <EvaluationSuccessCard
                            title={t("anamnesis:anamnesisCompleted")}
                            primaryLabel={t("anamnesis:seeAnswers")}
                            secondaryLabel={t("anamnesis:backToTop")}
                            onPrimary={handlePreviousAnamnesis}
                            onSecondary={goBackToApp}
                            primaryDisabled={!createdAnamnesisId}
                        />
                    </div>
                </div>
            }
        </Page>
    )

}
export default AnamnesisAnswerFlow;
