import {all, takeLatest, call, put} from 'redux-saga/effects';
import {changeStatusAPI, createPushAPI, fetchNotificationsAPI, sendPushAPI, updatePushAPI} from "../../api/push/pushActions";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    changePushStatus,
    fetchNotifications,
    onError,
    pushSent,
    pushStatusChanged,
    schedulePush,
    sendPush,
    setNotifications,
    updatePush
} from "./pushReducer";

export function* updatePushAsync(action) {
    try {
        const {id, formData} = action.payload;
        yield call(updatePushAPI, formData, id)
        yield put(pushSent(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}
export function* onUpdatePush() {
    yield takeLatest(updatePush.type,updatePushAsync)
}

export function* changeNotificationStatusAsync(action) {
    try {
        yield call(changeStatusAPI, action.payload)
        yield put(pushStatusChanged(action.payload))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onNotificationStatusChange() {
    yield takeLatest(changePushStatus, changeNotificationStatusAsync)
}

export function* fetchNotificationsByTypeAsync(action) {
    try {
        const response = yield call(fetchNotificationsAPI, action.payload)
        yield put(setNotifications(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchNotifications() {
    yield takeLatest(fetchNotifications, fetchNotificationsByTypeAsync)
}


export function* schedulePushAsync(action) {
    try {
        yield call(createPushAPI, action.payload);
        yield put(pushSent(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onSchedulePush() {
    yield takeLatest(schedulePush, schedulePushAsync)
}

export function* sendPushAsync(action) {
    try {
        yield call(sendPushAPI, action.payload)
        yield put(pushSent(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onSendPush() {
    yield takeLatest(sendPush, sendPushAsync)
}

export function* pushSaga() {
    yield all([

        call(onSendPush),
        call(onSchedulePush),
        call(onFetchNotifications),
        call(onNotificationStatusChange),
        call(onUpdatePush)
    ])
}