import React, {useEffect} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {getCustomLoading} from "../../store/custom-evaluation/customEvaluationSelector";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {resetFormSent} from "../../store/custom-evaluation/customEvaluationReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import enUS from "./locales/en-us.json";
import EvaluationSuccessCard from "../../components/evaluation-components/EvaluationSuccessCard";
import {
    buildCustomEditModelRoute,
    buildCustomModelsRoute
} from "../../utils/client/evaluationRoutes";

const CustomEvaluationEnd = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, customId} = useParams();
    const {t} = useTranslation("customEvaluation");
    const loading = useSelector(getCustomLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    useComponentTranslations('customEvaluation', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})
    const targetCustomId = customId ?? null;

    const handleGoBackPage = () => {
        navigate(buildCustomModelsRoute(id));
    };

    const handleGoEdited = () => {
        if (!targetCustomId) {
            navigate(buildCustomModelsRoute(id));
            return;
        }
        navigate(buildCustomEditModelRoute(id, targetCustomId));
    };

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"row justify-content-center d-flex "}>
                    <div className={"col-12"}>
                        <EvaluationSuccessCard
                            title={t("customEvaluation:editedSucessfully")}
                            primaryLabel={t("customEvaluation:showModel")}
                            secondaryLabel={t("customEvaluation:return")}
                            onPrimary={handleGoEdited}
                            onSecondary={handleGoBackPage}
                            primaryDisabled={!targetCustomId}
                        />
                    </div>
                </div>
            </Page>
        </>
    )
}

export default CustomEvaluationEnd;
