import React, {useCallback, useEffect, useMemo, useRef, useState} from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {
    getWorkoutPresetNameValidationError,
    normalizeWorkoutPresetName
} from "./workoutPresetValidation";

const createClientId = () => `preset-serie-${Date.now()}-${Math.random().toString(16).slice(2)}`;

const createEmptySerie = (tipo = 0) => ({
    clientId: createClientId(),
    tipo,
    repeticao: "",
    carga: "",
    tempo: "",
    velocidade: "",
    distancia: "",
    pace: "",
    intervalo: 0,
    obs: "",
    inclinacao: "",
    cadencia: ""
});

const createTouchedState = () => ({
    name: false,
    series: {}
});

const withClientIds = (series = []) => {
    if (!series.length) return [createEmptySerie()];
    return series.map((serie) => ({
        ...createEmptySerie(serie.tipo ?? 0),
        ...serie,
        clientId: serie.clientId || createClientId()
    }));
};

const WorkoutPresetForm = ({
    initialPreset = null,
    initialPresetKey,
    onSubmit,
    onCancel,
    onDeleteClick,
    deleteLabel,
    submitLabel,
    loading = false
}) => {
    const {t} = useTranslation();
    const [name, setName] = useState(initialPreset?.name || "");
    const [series, setSeries] = useState(withClientIds(initialPreset?.series));
    const [submitAttempted, setSubmitAttempted] = useState(false);
    const [touched, setTouched] = useState(createTouchedState());
    const nameInputRef = useRef(null);
    const fieldRefs = useRef({});
    const hydratedPresetKeyRef = useRef(null);
    const resolvedInitialPresetKey = initialPresetKey || (initialPreset?.id ? `preset-${initialPreset.id}` : "empty");

    useComponentTranslations("workoutPresetComponent", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        if (hydratedPresetKeyRef.current === resolvedInitialPresetKey) {
            return;
        }

        hydratedPresetKeyRef.current = resolvedInitialPresetKey;
        setName(initialPreset?.name || "");
        setSeries(withClientIds(initialPreset?.series));
        setTouched(createTouchedState());
        setSubmitAttempted(false);
    }, [initialPreset, resolvedInitialPresetKey]);

    const tipoOptions = useMemo(() => ([
        {value: 0, label: t("workoutPresetComponent:repsWeight")},
        {value: 1, label: t("workoutPresetComponent:repsWeightTime")},
        {value: 2, label: t("workoutPresetComponent:repsTime")},
        {value: 7, label: t("workoutPresetComponent:timeInclination")},
        {value: 3, label: t("workoutPresetComponent:running")},
        {value: 5, label: t("workoutPresetComponent:obs")},
        {value: 8, label: t("workoutPresetComponent:cadence")}
    ]), [t]);

    const hasValue = useCallback((value) => `${value ?? ""}`.trim() !== "", []);
    const normalizeIntervalInput = useCallback((value) => `${value ?? ""}`.replace(/\D/g, ""), []);
    const toSafeIntervalNumber = useCallback((value) => {
        const normalizedValue = normalizeIntervalInput(value);

        if (!normalizedValue) {
            return 0;
        }

        const interval = Number(normalizedValue);
        return Number.isFinite(interval) ? interval : 0;
    }, [normalizeIntervalInput]);

    const markNameTouched = () => {
        setTouched((prev) => prev.name ? prev : {...prev, name: true});
    };

    const markSerieFieldTouched = (clientId, field) => {
        setTouched((prev) => ({
            ...prev,
            series: {
                ...prev.series,
                [clientId]: {
                    ...(prev.series?.[clientId] || {}),
                    [field]: true
                }
            }
        }));
    };

    const getSerieErrors = useCallback((serie) => {
        const serieErrors = {};

        switch (Number(serie.tipo ?? 0)) {
            case 0:
            case 1:
            case 2:
            case 4:
                if (!hasValue(serie.repeticao)) {
                    serieErrors.repeticao = t("workoutPresetComponent:requiredField");
                }
                break;
            case 3:
                if (![serie.tempo, serie.velocidade, serie.distancia, serie.pace].some(hasValue)) {
                    serieErrors.runningGroup = t("workoutPresetComponent:runningRequired");
                }
                break;
            case 5:
                if (!hasValue(serie.obs)) {
                    serieErrors.obs = t("workoutPresetComponent:requiredField");
                }
                break;
            case 7:
                if (!hasValue(serie.tempo)) {
                    serieErrors.tempo = t("workoutPresetComponent:requiredField");
                }
                break;
            case 8:
                if (!hasValue(serie.cadencia)) {
                    serieErrors.cadencia = t("workoutPresetComponent:requiredField");
                }
                break;
            default:
                break;
        }

        return serieErrors;
    }, [hasValue, t]);

    const validationErrors = useMemo(() => {
        const nextErrors = {
            name: "",
            form: "",
            series: {}
        };

        nextErrors.name = getWorkoutPresetNameValidationError(name, t);

        if (!series.length) {
            nextErrors.form = t("workoutPresetComponent:addAtLeastOneSerie");
        }

        series.forEach((serie) => {
            const serieErrors = getSerieErrors(serie);
            if (Object.keys(serieErrors).length > 0) {
                nextErrors.series[serie.clientId] = serieErrors;
            }
        });

        return nextErrors;
    }, [getSerieErrors, name, series, t]);

    const hasValidationErrors = useMemo(() => {
        return Boolean(
            validationErrors.name
            || validationErrors.form
            || Object.keys(validationErrors.series).length
        );
    }, [validationErrors]);

    const updateSerie = (clientId, patch) => {
        setSeries((prev) => prev.map((serie) => serie.clientId === clientId ? {...serie, ...patch} : serie));
    };

    const addSerie = () => {
        setSeries((prev) => [...prev, createEmptySerie()]);
    };

    const removeSerie = (clientId) => {
        setSeries((prev) => {
            if (prev.length === 1) {
                return [createEmptySerie()];
            }
            return prev.filter((serie) => serie.clientId !== clientId);
        });
    };

    const moveSerie = (clientId, direction) => {
        setSeries((prev) => {
            const index = prev.findIndex((serie) => serie.clientId === clientId);
            if (index === -1) return prev;
            const targetIndex = index + direction;
            if (targetIndex < 0 || targetIndex >= prev.length) return prev;
            const next = [...prev];
            const [item] = next.splice(index, 1);
            next.splice(targetIndex, 0, item);
            return next;
        });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setSubmitAttempted(true);

        if (hasValidationErrors) {
            const focusNextFrame = window.requestAnimationFrame || ((callback) => setTimeout(callback, 0));
            focusNextFrame(() => {
                if (validationErrors.name) {
                    nameInputRef.current?.focus();
                    return;
                }

                for (const serie of series) {
                    const serieErrors = validationErrors.series[serie.clientId];
                    if (!serieErrors) {
                        continue;
                    }

                    if (serieErrors.repeticao) {
                        fieldRefs.current[`${serie.clientId}:repeticao`]?.focus();
                        return;
                    }
                    if (serieErrors.tempo) {
                        fieldRefs.current[`${serie.clientId}:tempo`]?.focus();
                        return;
                    }
                    if (serieErrors.obs) {
                        fieldRefs.current[`${serie.clientId}:obs`]?.focus();
                        return;
                    }
                    if (serieErrors.cadencia) {
                        fieldRefs.current[`${serie.clientId}:cadencia`]?.focus();
                        return;
                    }
                    if (serieErrors.runningGroup) {
                        fieldRefs.current[`${serie.clientId}:tempo`]?.focus();
                        return;
                    }
                }
            });
            return;
        }

        onSubmit?.({
            name: normalizeWorkoutPresetName(name),
            series: series.map((serie, index) => ({
                tipo: Number(serie.tipo ?? 0),
                repeticao: serie.repeticao ?? "",
                carga: serie.carga ?? "",
                tempo: serie.tempo ?? "",
                velocidade: serie.velocidade ?? "",
                distancia: serie.distancia ?? "",
                pace: serie.pace ?? "",
                intervalo: toSafeIntervalNumber(serie.intervalo),
                obs: serie.obs ?? "",
                inclinacao: serie.inclinacao ?? "",
                cadencia: serie.cadencia ?? "",
                ordenacao: index + 1
            }))
        });
    };

    return (
        <form onSubmit={handleSubmit}>
            <div className="row gy-2 gx-0">
                <div className="col-12">
                    <label className="form-label fw-semibold mb-2">{t("workoutPresetComponent:name")}</label>
                    <input
                        ref={nameInputRef}
                        className={`form-control ${(submitAttempted || touched.name) && validationErrors.name ? "is-invalid" : ""}`}
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        onBlur={markNameTouched}
                        placeholder={t("workoutPresetComponent:namePlaceholder")}
                    />
                    {(submitAttempted || touched.name) && validationErrors.name && (
                        <div className="invalid-feedback">
                            {validationErrors.name}
                        </div>
                    )}
                </div>
                {validationErrors.form && submitAttempted && (
                    <div className="col-12">
                        <span className="text-danger small">{validationErrors.form}</span>
                    </div>
                )}
                <div className="col-12 pt-2">
                    <span className="fw-semibold d-block">{t("workoutPresetComponent:settings")}</span>
                </div>
                {series.map((serie, index) => (
                    <div key={serie.clientId} className="col-12">
                        <div className="card border bg-white shadow-none">
                            <div className="card-body">
                                {(() => {
                                    const serieErrors = validationErrors.series[serie.clientId] || {};
                                    const touchedSerieFields = touched.series?.[serie.clientId] || {};
                                    const showSerieRepError = Boolean(serieErrors.repeticao) && (submitAttempted || touchedSerieFields.repeticao);
                                    const showTempoError = Boolean(serieErrors.tempo) && (submitAttempted || touchedSerieFields.tempo);
                                    const showObsError = Boolean(serieErrors.obs) && (submitAttempted || touchedSerieFields.obs);
                                    const showCadenciaError = Boolean(serieErrors.cadencia) && (submitAttempted || touchedSerieFields.cadencia);
                                    const showRunningError = Boolean(serieErrors.runningGroup) && (
                                        submitAttempted
                                        || touchedSerieFields.tempo
                                        || touchedSerieFields.velocidade
                                        || touchedSerieFields.distancia
                                        || touchedSerieFields.pace
                                    );
                                    return (
                                        <>
                                <div className="d-flex justify-content-between align-items-center mb-3">
                                    <div className="d-flex align-items-center gap-4">
                                        <button
                                            type="button"
                                            className="btn btn-link text-dark text-decoration-none p-0"
                                            disabled={index === series.length - 1}
                                            aria-label={t("workoutPresetComponent:moveSerieDown")}
                                            onClick={() => moveSerie(serie.clientId, 1)}
                                        >
                                            <i className="fa-regular fa-arrow-down"/>
                                        </button>
                                        <button
                                            type="button"
                                            className="btn btn-link text-dark text-decoration-none p-0"
                                            disabled={index === 0}
                                            aria-label={t("workoutPresetComponent:moveSerieUp")}
                                            onClick={() => moveSerie(serie.clientId, -1)}
                                        >
                                            <i className="fa-regular fa-arrow-up"/>
                                        </button>
                                    </div>
                                    <button
                                        type="button"
                                        className="btn btn-link text-danger text-decoration-none p-0"
                                        aria-label={t("workoutPresetComponent:removeSerie")}
                                        onClick={() => removeSerie(serie.clientId)}
                                    >
                                        <i className="fa-regular fa-trash-can"/>
                                    </button>
                                </div>
                                <div className="row gy-2 gx-0">
                                    <div className="col-12">
                                        <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:type")}</label>
                                        <select
                                            className="form-select"
                                            value={serie.tipo}
                                            onChange={(e) => updateSerie(serie.clientId, {tipo: Number(e.target.value)})}
                                        >
                                            {tipoOptions.map((option) => (
                                                <option key={option.value} value={option.value}>{option.label}</option>
                                            ))}
                                        </select>
                                    </div>

                                    {(serie.tipo === 0 || serie.tipo === 1 || serie.tipo === 2 || serie.tipo === 4) && (
                                        <div className="col-12">
                                            <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:serieRep")}</label>
                                            <input
                                                ref={(element) => {
                                                    fieldRefs.current[`${serie.clientId}:repeticao`] = element;
                                                }}
                                                className={`form-control ${showSerieRepError ? "is-invalid" : ""}`}
                                                value={serie.repeticao}
                                                onChange={(e) => updateSerie(serie.clientId, {repeticao: e.target.value})}
                                                onBlur={() => markSerieFieldTouched(serie.clientId, "repeticao")}
                                            />
                                            {showSerieRepError && (
                                                <div className="invalid-feedback">
                                                    {serieErrors.repeticao}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                    {(serie.tipo === 0 || serie.tipo === 1 || serie.tipo === 4) && (
                                        <div className="col-12">
                                            <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:weight")}</label>
                                            <input className="form-control" value={serie.carga} onChange={(e) => updateSerie(serie.clientId, {carga: e.target.value})}/>
                                        </div>
                                    )}
                                    {(serie.tipo === 1 || serie.tipo === 2 || serie.tipo === 3 || serie.tipo === 7) && (
                                        <div className="col-12">
                                            <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:time")}</label>
                                            <input
                                                ref={(element) => {
                                                    fieldRefs.current[`${serie.clientId}:tempo`] = element;
                                                }}
                                                className={`form-control ${showTempoError || showRunningError ? "is-invalid" : ""}`}
                                                value={serie.tempo}
                                                onChange={(e) => updateSerie(serie.clientId, {tempo: e.target.value})}
                                                onBlur={() => markSerieFieldTouched(serie.clientId, "tempo")}
                                            />
                                            {showTempoError && (
                                                <div className="invalid-feedback">
                                                    {serieErrors.tempo}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                    {serie.tipo === 7 && (
                                        <div className="col-12">
                                            <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:inclination")}</label>
                                            <input className="form-control" value={serie.inclinacao} onChange={(e) => updateSerie(serie.clientId, {inclinacao: e.target.value})}/>
                                        </div>
                                    )}
                                    {serie.tipo === 3 && (
                                        <>
                                            <div className="col-12">
                                                <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:speed")}</label>
                                                <input
                                                    ref={(element) => {
                                                        fieldRefs.current[`${serie.clientId}:velocidade`] = element;
                                                    }}
                                                    className={`form-control ${showRunningError ? "is-invalid" : ""}`}
                                                    value={serie.velocidade}
                                                    onChange={(e) => updateSerie(serie.clientId, {velocidade: e.target.value})}
                                                    onBlur={() => markSerieFieldTouched(serie.clientId, "velocidade")}
                                                />
                                            </div>
                                            <div className="col-12">
                                                <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:distance")}</label>
                                                <input
                                                    ref={(element) => {
                                                        fieldRefs.current[`${serie.clientId}:distancia`] = element;
                                                    }}
                                                    className={`form-control ${showRunningError ? "is-invalid" : ""}`}
                                                    value={serie.distancia}
                                                    onChange={(e) => updateSerie(serie.clientId, {distancia: e.target.value})}
                                                    onBlur={() => markSerieFieldTouched(serie.clientId, "distancia")}
                                                />
                                            </div>
                                            <div className="col-12">
                                                <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:pace")}</label>
                                                <input
                                                    ref={(element) => {
                                                        fieldRefs.current[`${serie.clientId}:pace`] = element;
                                                    }}
                                                    className={`form-control ${showRunningError ? "is-invalid" : ""}`}
                                                    value={serie.pace}
                                                    onChange={(e) => updateSerie(serie.clientId, {pace: e.target.value})}
                                                    onBlur={() => markSerieFieldTouched(serie.clientId, "pace")}
                                                />
                                            </div>
                                            {showRunningError && (
                                                <div className="col-12">
                                                    <div className="invalid-feedback d-block">
                                                        {serieErrors.runningGroup}
                                                    </div>
                                                </div>
                                            )}
                                        </>
                                    )}
                                    {![5, 8].includes(serie.tipo) && (
                                        <div className="col-12">
                                            <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:interval")}</label>
                                            <input
                                                className="form-control"
                                                inputMode="numeric"
                                                value={serie.intervalo}
                                                onChange={(e) => updateSerie(serie.clientId, {intervalo: normalizeIntervalInput(e.target.value)})}
                                            />
                                        </div>
                                    )}
                                    {serie.tipo === 8 && (
                                        <div className="col-12">
                                            <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:cadence")}</label>
                                            <input
                                                ref={(element) => {
                                                    fieldRefs.current[`${serie.clientId}:cadencia`] = element;
                                                }}
                                                className={`form-control ${showCadenciaError ? "is-invalid" : ""}`}
                                                value={serie.cadencia}
                                                onChange={(e) => updateSerie(serie.clientId, {cadencia: e.target.value})}
                                                onBlur={() => markSerieFieldTouched(serie.clientId, "cadencia")}
                                            />
                                            {showCadenciaError && (
                                                <div className="invalid-feedback">
                                                    {serieErrors.cadencia}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                    {serie.tipo === 5 && (
                                        <div className="col-12">
                                            <label className="form-label small fw-semibold mb-1">{t("workoutPresetComponent:obs")}</label>
                                            <textarea
                                                ref={(element) => {
                                                    fieldRefs.current[`${serie.clientId}:obs`] = element;
                                                }}
                                                className={`form-control ${showObsError ? "is-invalid" : ""}`}
                                                rows={3}
                                                value={serie.obs}
                                                onChange={(e) => updateSerie(serie.clientId, {obs: e.target.value})}
                                                onBlur={() => markSerieFieldTouched(serie.clientId, "obs")}
                                            />
                                            {showObsError && (
                                                <div className="invalid-feedback">
                                                    {serieErrors.obs}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                                        </>
                                    );
                                })()}
                            </div>
                        </div>
                    </div>
                ))}
                <div className="col-12">
                    <div className="d-flex justify-content-center py-3">
                        <button
                            type="button"
                            className="btn btn-link text-primary text-decoration-none p-0 d-inline-flex align-items-center gap-2"
                            onClick={addSerie}
                        >
                            <i className="fa-regular fa-circle-plus"/>
                            <span className="fw-semibold">{t("workoutPresetComponent:addSerie")}</span>
                        </button>
                    </div>
                </div>
                <div className="col-12">
                    <button type="submit" className="btn btn-primary w-100" disabled={loading}>
                        {submitLabel || t("workoutPresetComponent:savePreset")}
                    </button>
                </div>
                {onCancel && (
                    <div className="col-12">
                        <button type="button" className="btn btn-outline-primary w-100" onClick={onCancel} disabled={loading}>
                            {t("workoutPresetComponent:cancel")}
                        </button>
                    </div>
                )}
                {onDeleteClick && (
                    <div className="col-12 pt-2">
                        <div className="d-flex justify-content-center">
                            <button
                                type="button"
                                className="btn btn-link text-danger text-decoration-none p-0"
                                onClick={onDeleteClick}
                                disabled={loading}
                            >
                                {deleteLabel || t("workoutPresetComponent:deletePreset")}
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </form>
    );
};

export default WorkoutPresetForm;
