import React from "react";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {changeStatus} from "../../store/physical-evaluation/physicalEvaluationReducer";
import {addToast} from "../../store/toast/toastReducer";
import {useDispatch} from "react-redux";
import i18n from "i18next";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const PhysicalEvaluationDeletedCard = ({title, physical}) => {
    const dispatch = useDispatch();
    syncMomentLocale(i18n.language);
    const {t} = useTranslation();
    useComponentTranslations('physicalEvaluationsComponent', {
        'en-US': enUS,
        'pt-BR': ptBR,
        'es-ES': esES,
        'pt-PT': ptPT
    });

    const handleUpdate = () => {
        dispatch(changeStatus({id: physical.id, status: 0}));

        const toastPayload = {
            id: `toast` + physical.id,
            type: "success",
            title: t("physicalEvaluationsComponent:allVeryWell"),
            message: t("physicalEvaluationsComponent:recoverEvaluation"),
            autohide: true,
            delay: 5000
        };
        dispatch(addToast(toastPayload));
    }

    return (
        <div className={"row pb-2"}>
            <div className={"card"}>
                <div className={`row d-flex align-items-center py-3`}>
                    <div className={"col-10 lh-1 pb-1"}>
                        <span className={"fw-semibold d-block"}>{title}</span>
                        <span className={"text-md fw-semibold me-1"}>{t("physicalEvaluationsComponent:carryOut")}</span>
                        <span className={"text-md"}>{moment(physical.data).format('L')}</span>
                    </div>
                </div>
                <hr className={"text-secondary my-n1"}/>
                <div className={"col-12 clickable-element text-center"}>
                    <button className={"btn btn-link text-md ps-0 fw-semibold mb-n1"} onClick={handleUpdate}>
                        {t("physicalEvaluationsComponent:recover")}
                    </button>
                </div>
            </div>
        </div>
    )
}

export default PhysicalEvaluationDeletedCard;