import Modal from "react-bootstrap/Modal";
import {ErrorMessage, Field, Form, Formik} from "formik";
import * as Yup from "yup";
import {useDispatch, useSelector} from "react-redux";
import {useEffect} from "react";
import {selectSelectedClient} from "../../store/client/clientSelector";
import _ from "lodash";
import WorkoutAerobicPaceCard from "./WorkoutAerobicPaceCard";
import {selectPaceLoading, selectPaces} from "../../store/workout-aerobic/workoutAerobicSelector";
import {createPace, fetchAllPaces} from "../../store/workout-aerobic/workoutAerobicReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutAerobicPaceModal = ({handleModal, show}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const client = useSelector(selectSelectedClient)
    const paces = useSelector(selectPaces)
    const paceLoading = useSelector(selectPaceLoading)
    useComponentTranslations('aerobicWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const initialValues = {
        distance: '',
        time: '',
        clientId: client?.id
    };

    const validationSchema = Yup.object({
        distance: Yup.number()
            .typeError(t("aerobicWorkoutComponent:required"))
            .required(t("aerobicWorkoutComponent:required"))
            .positive(t("aerobicWorkoutComponent:biggerThanZero")),
        time: Yup.number()
            .typeError(t("aerobicWorkoutComponent:required"))
            .required(t("aerobicWorkoutComponent:required"))
            .positive(t("aerobicWorkoutComponent:biggerThanZero"))
    });

    const calculatePace = (time, distance) => {
        const numTime = Number(time);
        const numDistance = Number(distance);
        if (!Number.isFinite(numDistance) || numDistance === 0 || !Number.isFinite(numTime)) return '0.00';
        const pace = numTime / (numDistance / 1000);
        return pace.toFixed(2);
    };


    const handleSubmit = (values, {resetForm}) => {
        dispatch(createPace(values))
        resetForm();
    }

    useEffect(() => {
        if (client)
            dispatch(fetchAllPaces(client.id))
    }, [client, dispatch])

    return (
        <Modal show={show} centered onHide={handleModal} scrollable>
            <Modal.Body>
                <div className={"row d-flex justify-content-between"}>
                    <div className={'col-auto'}>
                        <span className={"fw-semibold fs-5"}>{t("aerobicWorkoutComponent:clientPace")}</span>
                    </div>
                    <div className={'col-auto align-self-center clickable-element'} onClick={handleModal}>
                        <i className={"fs-5 fa-solid fa-times"}></i>
                    </div>
                </div>
                <div className={"row mt-3"}>
                    <div className={"col-12"}>
                        <Formik
                            initialValues={initialValues}
                            validationSchema={validationSchema}
                            onSubmit={handleSubmit}
                        >
                            {({values}) => (
                                <Form>
                                    <div className="mb-3">
                                        <label htmlFor="distance" className="form-label fw-semibold">
                                            {t("aerobicWorkoutComponent:distance")} <span className={"small"}>({t("aerobicWorkoutComponent:inMeters")})</span>
                                        </label>
                                        <Field
                                            name="distance"
                                            type="number"
                                            className="form-control"
                                            placeholder={t("aerobicWorkoutComponent:insertDistance")}
                                        />
                                        <ErrorMessage name="distance">
                                            {(msg) => <div className="text-danger">{msg}</div>}
                                        </ErrorMessage>
                                    </div>
                                    <div className="mb-3">
                                        <label htmlFor="time" className="form-label fw-semibold">
                                            {t("aerobicWorkoutComponent:time")} <span className={"small"}>({t("aerobicWorkoutComponent:inMinutes")})</span>
                                        </label>
                                        <Field
                                            name="time"
                                            type="number"
                                            className="form-control"
                                            placeholder={t("aerobicWorkoutComponent:insertTime")}
                                        />
                                        <ErrorMessage name="time">
                                            {(msg) => <div className="text-danger">{msg}</div>}
                                        </ErrorMessage>
                                    </div>
                                    <div className="mb-3 card card-body border-0 bg-secondary-subtle">
                                        <div className={'row'}>
                                            <div className={'col-12'}>
                                                <span className={"fw-semibold d-block"}>{t("aerobicWorkoutComponent:formula")}:</span>
                                                <span
                                                    className={"d-block "}>{t("aerobicWorkoutComponent:pace")} = {values.time || 0} / ({values.distance || 0}/1000)</span>
                                            </div>
                                            <div className={'col-12 mt-2'}>
                                                <span className={"fw-semibold d-block"}>{t("aerobicWorkoutComponent:result")}:</span>
                                                <span className={"d-block "}>{calculatePace(values.time, values.distance)} min/km</span>
                                            </div>
                                        </div>
                                    </div>
                                    <div className={'d-grid'}>
                                        <button type="submit" className={"btn btn-primary"} disabled={paceLoading}>
                                            {t("aerobicWorkoutComponent:save")}
                                        </button>
                                    </div>
                                </Form>
                            )}
                        </Formik>
                    </div>
                    {
                        paces && paces.length > 0 &&
                        <div className={"col-12 mt-2"}>
                            <span className={"fw-semibold fs-5"}>{t("aerobicWorkoutComponent:history")}</span>
                            {
                                _.map(paces, (pace =>
                                        <WorkoutAerobicPaceCard pace={pace} key={pace.id}/>
                                ))
                            }
                        </div>
                    }
                </div>
            </Modal.Body>
        </Modal>
    )
}
export default WorkoutAerobicPaceModal;