export const WORKOUT_PRESET_NAME_MAX_LENGTH = 145;
const TRUNCATED_PRESET_NAME_SUFFIX = "...";

export const normalizeWorkoutPresetName = (value) => `${value ?? ""}`.trim();

export const getWorkoutPresetNameLength = (value) => Array.from(normalizeWorkoutPresetName(value)).length;

export const getWorkoutPresetNameValidationError = (value, t) => {
    const normalizedName = normalizeWorkoutPresetName(value);

    if (!normalizedName) {
        return t("workoutPresetComponent:nameRequired");
    }

    if (getWorkoutPresetNameLength(normalizedName) > WORKOUT_PRESET_NAME_MAX_LENGTH) {
        return t("workoutPresetComponent:nameMaxLength", {max: WORKOUT_PRESET_NAME_MAX_LENGTH});
    }

    return "";
};

export const createWorkoutPresetDefaultName = (value) => {
    const normalizedName = normalizeWorkoutPresetName(value);

    if (getWorkoutPresetNameLength(normalizedName) <= WORKOUT_PRESET_NAME_MAX_LENGTH) {
        return normalizedName;
    }

    const availableLength = WORKOUT_PRESET_NAME_MAX_LENGTH - TRUNCATED_PRESET_NAME_SUFFIX.length;
    return `${Array.from(normalizedName).slice(0, availableLength).join("").trimEnd()}${TRUNCATED_PRESET_NAME_SUFFIX}`;
};
