import {useCallback, useState} from "react";
import {useDispatch} from "react-redux";
import {addToast} from "../../store/toast/toastReducer";
import {createPushAPI, sendPushAPI} from "../../api/push/pushActions";

const usePushSubmit = (onSuccess) => {
    const dispatch = useDispatch();
    const [loading, setLoading] = useState(false);

    const submit = useCallback(async (mode, formData) => {
        setLoading(true);
        try {
            const response = mode === "now"
                ? await sendPushAPI(formData)
                : await createPushAPI({
                    ...formData,
                    type: mode === "recurring" ? "recurring" : "scheduled"
                });

            const responseBody = response?.data || {};
            if (onSuccess) {
                await onSuccess(responseBody, mode, formData);
            }
            return responseBody;
        } catch (error) {
            dispatch(addToast({id: Date.now()}));
            throw error;
        } finally {
            setLoading(false);
        }
    }, [dispatch, onSuccess]);

    return {loading, submit};
};

export default usePushSubmit;
