import React from 'react';
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";

function EvaluationOptionsModal({
                                    show,
                                    onClose,
                                    onOpen,
                                    onShare,
                                    onEdit,
                                    onDelete,
                                    openLabel, shareLabel, editLabel, deleteLabel
                                }) {
    return (
        <Modal show={show} onHide={onClose} centered>
            <ModalBody>
                <div className="d-grid gap-2">
                    <button className="btn btn-outline-primary" onClick={onOpen}>
                        {openLabel}
                    </button>
                    <button className="btn btn-outline-primary" onClick={onShare}>
                        {shareLabel}
                    </button>
                    <button className="btn btn-outline-primary" onClick={onEdit}>
                        {editLabel}
                    </button>
                    <button className="btn btn-outline-danger" onClick={onDelete}>
                        {deleteLabel}
                    </button>
                </div>
            </ModalBody>
        </Modal>
    );
}

export default EvaluationOptionsModal;
