import React from 'react';
import {ErrorMessage, Field} from "formik";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import {useTranslation} from "react-i18next";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const AnamnesisQuestionField = ({ question, index, onDelete }) => {
    const {t} = useTranslation();
    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    return (
        <div className="row clickable-element pt-2">
            <div className="card card-body">
                <div className="fw-semibold pb-1">
                    {t('anamnesisComponent:writeHere')}:
                </div>
                <Field
                    name={`questions[${index}].question`}
                    className="w-100 mb-1 border rounded py-2 form-control"
                />
                <ErrorMessage name={`questions[${index}].question`} component="div" className="text-danger" />
                <hr/>
                <div
                    className="btn btn-link p-0 text-xs text-danger"
                    onClick={() => onDelete(question.id)}
                >
                    {t('anamnesisComponent:deleteQuestion')}
                </div>
            </div>
        </div>
    );
};

export default AnamnesisQuestionField;