import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Page from "../../components/page/Page";
import PushComposerFlow from "../../components/push/PushComposerFlow";

const PushSend = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const {type} = useParams();
    useComponentTranslations('pushPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const initialMode = type === "scheduled" || type === "recurring" ? type : "now";

    return (
        <Page title={t(`pushPage:notifications`)}>
            <div className={'card card-body'}>
                <div className={'row'}>
                    <div className={'col-12'}>
                        <PushComposerFlow
                            initialMode={initialMode}
                            allowModeSwitch={false}
                            onSuccess={() => navigate(`/user/push/sent/${initialMode}`)}
                        />
                    </div>
                </div>
            </div>
        </Page>
    )
}
export default PushSend;
