import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {Image} from "react-bootstrap";
import android from "../../assets/img/push/notification-android.png";
import iOS from "../../assets/img/push/notification-iphone.png";
import {isAndroid, isIOS} from "react-device-detect";
import Cookies from "js-cookie";
import {getMainDomain} from "../../utils/cookie/cookieUtils";
import Page from "../../components/page/Page";

const PushList = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    useComponentTranslations('pushPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const goBackLink = () => {
        navigate("/user")
    }

    const handleStartButtonClick = () => {
        const mainDomain = getMainDomain();
        Cookies.set('first_time', false, {expires: 400, path: '/', domain: `.${mainDomain}`})
        navigate("/user/push")
    }

    return (
        <Page title={t(`pushPage:notifications`)} goBackLink={goBackLink}>
            <div className={'card card-body'}>
                <div className={'row justify-content-center d-flex mb-2'}>
                    <div className={'col-12 pb-4 text-center'}>
                        <span className={'fw-bold fs-5'}>{t(`pushPage:firstTimePushTitle`)}</span>
                    </div>
                    <div className={'col-8 col-md-6 text-center'}>
                        {
                            isAndroid &&
                            <Image fluid src={android}/>
                        }
                        {
                            isIOS &&
                            <Image fluid src={iOS}/>
                        }
                        {
                            !isIOS && !isAndroid &&
                            <Image fluid src={iOS}/>
                        }
                    </div>
                    <div className={'col-12 text-center pt-4'}>
                        {t(`pushPage:firstTimePushText`)}
                    </div>
                    <div className={'d-grid pt-4'}>
                        <button className={'btn btn-primary-darker'} onClick={handleStartButtonClick}>{t(`pushPage:firstTimePushStart`)}</button>
                    </div>
                </div>
            </div>
        </Page>
    )
}

export default PushList;