import {useCallback, useEffect, useMemo, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate} from "react-router-dom";
import {addToast} from "../../store/toast/toastReducer";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {buildShareUrl, createShareToken} from "../sharelink/shareLink";
import {handleSendWhatsApp} from "../handlers/handler";
import {useTranslation} from "react-i18next";
import {isMatchingSubmitError, isMatchingSubmitSuccess} from "../evaluation/successFlow";

export const useMeasurementEvaluationActions = ({
    clientId,
    changeStatusAction,
    routes,
    deleteFlow,
    selectSubmitResult,
    selectSubmitLoading,
}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const selectedClient = useSelector(selectSelectedClient);
    const submitResult = useSelector(selectSubmitResult);
    const submitLoading = useSelector(selectSubmitLoading);

    const [currentEvaluation, setCurrentEvaluation] = useState(null);
    const [showOptions, setShowOptions] = useState(false);
    const [showShare, setShowShare] = useState(false);
    const [showDelete, setShowDelete] = useState(false);
    const [deleteRequested, setDeleteRequested] = useState(false);
    const [isComparing, setIsComparing] = useState(false);
    const [selectedList, setSelectedList] = useState([]);

    const openOptionsModal = useCallback((evaluation) => {
        setCurrentEvaluation(evaluation);
        setShowOptions(true);
    }, []);

    const closeOptionsModal = useCallback(() => setShowOptions(false), []);

    const openShareModal = useCallback(() => {
        if (currentEvaluation) {
            setShowShare(true);
        }
    }, [currentEvaluation]);

    const closeShareModal = useCallback(() => setShowShare(false), []);

    const openDeleteModal = useCallback(() => setShowDelete(true), []);
    const closeDeleteModal = useCallback(() => {
        setShowDelete(false);
        setDeleteRequested(false);
    }, []);

    const confirmDelete = useCallback(() => {
        if (!currentEvaluation) {
            return;
        }

        dispatch(changeStatusAction(
            {id: currentEvaluation.id, status: 1},
            {flow: deleteFlow, clientId}
        ));
        setDeleteRequested(true);
    }, [changeStatusAction, clientId, currentEvaluation, deleteFlow, dispatch]);

    useEffect(() => {
        if (!deleteRequested) {
            return;
        }

        if (isMatchingSubmitSuccess(submitResult, {
            action: "delete",
            flow: deleteFlow,
            clientId
        })) {
            setShowDelete(false);
            setShowOptions(false);
            setDeleteRequested(false);
        }

        if (isMatchingSubmitError(submitResult, {
            action: "delete",
            flow: deleteFlow,
            clientId
        })) {
            setDeleteRequested(false);
        }
    }, [clientId, deleteFlow, deleteRequested, submitResult]);

    const shareLink = useMemo(() => {
        if (!selectedClient || !currentEvaluation) {
            return "";
        }

        const token = createShareToken(
            selectedClient.idUser,
            selectedClient.id,
            1,
            currentEvaluation.id
        );

        return buildShareUrl(token);
    }, [selectedClient, currentEvaluation]);

    const copyLink = useCallback(() => {
        if (!shareLink) {
            return;
        }

        navigator.clipboard.writeText(shareLink)
            .then(() => dispatch(addToast({
                type: "success",
                title: t("utils:toastTitle"),
                message: t("utils:linkCopied"),
            })));
    }, [dispatch, shareLink, t]);

    const sendWhatsApp = useCallback(() => {
        if (!shareLink || !selectedClient?.telefone) {
            return;
        }

        const message = `${t("utils:checkHere")} ${shareLink}`;
        handleSendWhatsApp(selectedClient.telefone, message);
    }, [selectedClient, shareLink, t]);

    const toggleComparingMode = useCallback(() => {
        setIsComparing((previousValue) => {
            const nextValue = !previousValue;
            if (previousValue) {
                setSelectedList([]);
            }
            return nextValue;
        });
    }, []);

    const toggleSelection = useCallback((evaluationId) => {
        setSelectedList((previousValue) =>
            previousValue.includes(evaluationId)
                ? previousValue.filter((id) => id !== evaluationId)
                : previousValue.length < 3
                    ? [...previousValue, evaluationId]
                    : previousValue
        );
    }, []);

    const goTo = useCallback((builder) => {
        if (!builder) {
            return;
        }

        navigate(builder());
    }, [navigate]);

    const goView = useCallback(() => {
        if (!currentEvaluation || !routes.goView) {
            return;
        }

        navigate(routes.goView(currentEvaluation.id));
        setShowOptions(false);
    }, [currentEvaluation, navigate, routes]);

    const goEdit = useCallback(() => {
        if (!currentEvaluation || !routes.goEdit) {
            return;
        }

        navigate(routes.goEdit(currentEvaluation.id));
        setShowOptions(false);
    }, [currentEvaluation, navigate, routes]);

    const goCompare = useCallback(() => {
        if (selectedList.length < 2 || !routes.goCompare) {
            return;
        }

        navigate(routes.goCompare(selectedList.join(",")));
    }, [navigate, routes, selectedList]);

    const setCurrent = useCallback((evaluation) => setCurrentEvaluation(evaluation), []);

    return {
        state: {
            currentEvaluation,
            showOptions,
            showShare,
            showDelete,
            deleteSubmitting: deleteRequested && submitLoading,
            isComparing,
            selectedList,
        },
        handlers: {
            openOptionsModal,
            closeOptionsModal,
            openShareModal,
            closeShareModal,
            openDeleteModal,
            closeDeleteModal,
            confirmDelete,
            copyLink,
            sendWhatsApp,
            toggleComparingMode,
            toggleSelection,
            goBackPage: () => goTo(routes.goBack),
            createNew: routes.createNew ? (...args) => navigate(routes.createNew(...args)) : undefined,
            goView,
            goEdit,
            goCompare,
            goCharts: () => goTo(routes.goCharts),
            goDeleted: () => goTo(routes.goDeleted),
            goList: () => goTo(routes.goList),
            setCurrentEvaluation: setCurrent,
        },
        shareLink,
    };
};
