import React from "react";
import moment from "moment";
import {calculateIMC} from "../../utils/physicalEvaluation/imcFormula";
import {formatIMC} from "../../utils/evaluationComponents/formatters";
import {formatRQC} from "../../utils/physicalEvaluation/rqcFormula";

const BioimpedanceDetailFields = ({fields, detail, clientSexo, t}) => {
    const formatValue = (field) => {
        const raw = detail[field.id];

        if (field.id === "imc") {
            const imc = detail.imc ?? (detail.peso && detail.estatura
                ? calculateIMC(detail.peso, detail.estatura)
                : null);
            return imc != null ? formatIMC(imc, t) : "-";
        }
        if (field.id === "rcq") {
            return raw && Number(raw) !== 0
                ? formatRQC(raw, clientSexo, t)
                : "-";
        }
        if (field.type === "date") {
            return raw ? moment(raw).format("L") : "-";
        }
        if (typeof field.formatter === "function") {
            return field.formatter(raw);
        }
        if (raw == null || raw === "") {
            return "-";
        }
        return `${raw}${field.unit || ""}`.trim();
    };

    return (
        <div className="row">
            {fields.map((field) => (
                <div key={field.id} className="col-12 ">
                    <label htmlFor={field.id} className=" fw-semibold d-block">
                        {t(`fields.${field.labelKey}`)}
                    </label>
                    {formatValue(field)}
                </div>
            ))}
        </div>
    );
};

export default BioimpedanceDetailFields;
