import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect, useMemo} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {useTranslation} from "react-i18next";
import {
    getCustomLoading,
    selectCustomEvaluation, selectSubmitResult,
    selectImageUploading,
    selectSubmitLoading
} from "../../store/custom-evaluation/customEvaluationSelector";
import {
    editAnsweredCustom,
    getOneCustom, resetFormSent,

} from "../../store/custom-evaluation/customEvaluationReducer";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import enUS from "./locales/en-us.json";
import Page from "../../components/page/Page";
import {Field, Form, Formik} from "formik";
import {fetchClient} from "../../store/client/clientReducer";
import {selectUser} from "../../store/user/userSelector";
import EvaluationImageUpload from "../../utils/imageupdate/EvaluationImageUpload";
import Text from "../../components/utils/emoji/Text";
import he from "he";
import {formatGender} from "../../utils/gender/formatGender";
import EvaluationSubmitButton from "../../components/evaluation-components/EvaluationSubmitButton";
import EvaluationSuccessCard from "../../components/evaluation-components/EvaluationSuccessCard";
import {
    buildClientCustomRoute,
    buildCustomViewRoute
} from "../../utils/client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const CustomEvaluationEdit = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, customId} = useParams();
    const {t} = useTranslation("customEvaluation");
    const user = useSelector(selectUser)
    const loadingCustom = useSelector(getCustomLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const customDetails = useSelector(selectCustomEvaluation);
    const uploadingImage = useSelector(selectImageUploading);
    const submitLoading = useSelector(selectSubmitLoading);
    const submitResult = useSelector(selectSubmitResult);
    const formSent = isMatchingSubmitSuccess(submitResult, {
        action: "update",
        flow: EVALUATION_FLOWS.CUSTOM_ANSWERED_EDIT,
        clientId: id
    });
    syncMomentLocale(i18n.language);
    useComponentTranslations('customEvaluation', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})

    useEffect(() => {dispatch(resetFormSent());}, [dispatch])
    useEffect(() => {dispatch(fetchClient(id));}, [dispatch, id]);
    useEffect(() => {
        if (customId) {
            dispatch(getOneCustom(customId));
        }
    }, [dispatch, customId]);

    const campos = customDetails?.campos ?? [];
    const genderLabel = useMemo(
        () => formatGender(selectedClient?.sexo, t),
        [selectedClient?.sexo, t]
    );

    const initialValues = {
        idade: customDetails?.idade,
        estatura: customDetails?.estatura,
        peso: customDetails?.peso,
        tipo: customDetails?.tipo,
        imc: customDetails?.imc,
        observacao:
            customDetails?.observacao != null
                ? he.decode(customDetails.observacao)
                : "",
        proximaAvaliacao: customDetails?.proximaAvaliacao,
        ...campos.reduce((acc, f) => {
            acc[f.id] = f.valor != null
                ? he.decode(f.valor)
                : "";
            return acc;
        }, {})
    };

    const handleGoBackPage = () => {
        navigate(buildClientCustomRoute(id));
    };

    const handleGoView = () => {
        const targetId = submitResult?.entityId ?? customDetails?.id;
        if (!targetId) {
            return;
        }
        navigate(buildCustomViewRoute(id, targetId));
    };

    const handleSubmit = (values) => {
        const payload = {
            id: Number(customDetails.id),
            id_aluno: Number(id),
            id_professor: user.id,
            data: customDetails.data,
            peso: values.peso,
            estatura: values.estatura,
            idade: values.idade,
            imc: values.imc,
            tipo: values.tipo,
            observacao: values.observacao,
            proximaAvaliacao: values.proximaAvaliacao,
            campos: campos.map(f => ({
                id: f.id,
                id_avaliacao: Number(customDetails.id),
                campo: f.campo,
                tipo: f.tipo,
                valor: values[f.id] ?? "",
                status: 0
            }))
        };
        dispatch(editAnsweredCustom(payload, {
            flow: EVALUATION_FLOWS.CUSTOM_ANSWERED_EDIT,
            clientId: id
        }));
    };

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loadingCustom} pb={"pb-2"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        {!formSent ? (
                            <div className={"card card-body border-0"}>
                                <span className={"fw-semibold"}>
                                    <Text>{customDetails?.tipo}</Text>
                                </span>
                                {customDetails?.data && (
                                    <span className={"text-md"}>
                                        {moment(customDetails?.data).format('LL')}
                                    </span>
                                )}
                                <Formik initialValues={initialValues} enableReinitialize={true} onSubmit={handleSubmit}>
                                    {({values, setFieldValue}) => (
                                        <Form>
                                        <div className="mb-3">
                                            <label htmlFor="idade"
                                                   className="fw-semibold">{t("customEvaluation:age")}</label>
                                            <Field
                                                id="idade"
                                                name="idade"
                                                type="number"
                                                className="form-control"
                                            />
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="estatura"
                                                   className="fw-semibold">{t("customEvaluation:height")}</label>
                                            <Field
                                                id="estatura"
                                                name="estatura"
                                                type="number"
                                                className="form-control"
                                            />
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="peso"
                                                   className="fw-semibold">{t("customEvaluation:weight")}</label>
                                            <Field
                                                id="peso"
                                                name="peso"
                                                type="number"
                                                className="form-control"
                                            />
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="gender" className="fw-semibold">{t("customEvaluation:gender")}</label>
                                            <span className="form-control-plaintext bg-white border-0 mb-n2">
                                                {genderLabel}
                                            </span>
                                            <span className={"text-md text-danger mt-n3"}>*{t("customEvaluation:changeGender")}</span>
                                        </div>

                                        <div className="mb-3">
                                        <label htmlFor="observacao"
                                                   className="fw-semibold">{t("customEvaluation:observation")}</label>
                                            <Field
                                                as="textarea"
                                                id="observacao"
                                                name="observacao"
                                                className="form-control"
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="proximaAvaliacao"
                                                   className="fw-semibold">{t("customEvaluation:nextEvaluation")}</label>
                                            <Field
                                                id="proximaAvaliacao"
                                                name="proximaAvaliacao"
                                                type="date"
                                                className="form-control"
                                            />
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="resultado"
                                                   className="fw-semibold">{t("customEvaluation:result")}</label>
                                            <div className={"pt-2 row"}>
                                                <label htmlFor={"IMC"}
                                                       className={"fw-semibold"}>{t("customEvaluation:imc.label")}</label>
                                                <Field name="imc">
                                                    {({field}) => (
                                                        <input
                                                            {...field}
                                                            readOnly
                                                            id="imc"
                                                            className="border-0 bg-white"
                                                            value={
                                                                field.value != null && !isNaN(field.value)
                                                                    ? Number(field.value).toFixed(2)
                                                                    : ""
                                                            }
                                                        />
                                                    )}
                                                </Field>
                                            </div>

                                        </div>
                                        <span className={"fw-semibold"}>{t("customEvaluation:fields")}</span>
                                        {campos.map(field => (
                                            <div key={field.id} className={"my-3"}>
                                                <label className={"fw-semibold"} htmlFor={field.id}>
                                                    <Text>{field.campo}</Text>
                                                </label>
                                                {field.tipo === 2 ? (
                                                    <>
                                                        <EvaluationImageUpload
                                                            slots={1}
                                                            existingImages={values[field.id] ? [values[field.id]] : []}
                                                            user={user}
                                                            selectedClient={selectedClient}
                                                            basePath="customEvaluation"
                                                            onImagesUpload={(urls) => setFieldValue(field.id, urls[0] || "")}
                                                            Anexar={t("customEvaluation:attach")}
                                                        />
                                                    </>
                                                ) : (
                                                    field.campo === "Objetivo" ? (
                                                        <Field
                                                            as="textarea"
                                                            id={field.id}
                                                            name={field.id}
                                                            className="form-control"
                                                            rows={4}
                                                        />
                                                    ) : (
                                                        <Field
                                                            id={field.id}
                                                            name={field.id}
                                                            type={field.tipo === 1 ? "number" : "text"}
                                                            className="form-control"
                                                        />
                                                    ))}
                                            </div>
                                        ))}
                                            <EvaluationSubmitButton
                                                label={t("customEvaluation:save")}
                                                loadingLabel={t("customEvaluation:sending")}
                                                isSubmitting={submitLoading}
                                                disabled={uploadingImage}
                                            />
                                        </Form>
                                    )}
                                </Formik>
                            </div>
                        ) : (
                            <EvaluationSuccessCard
                                title={t("customEvaluation:evaluationUpdatedSuccessfully")}
                                primaryLabel={t("customEvaluation:showEvaluation")}
                                secondaryLabel={t("customEvaluation:back")}
                                onPrimary={handleGoView}
                                onSecondary={handleGoBackPage}
                            />
                        )}
                    </div>
                </div>
            </Page>
        </>
    )
}

export default CustomEvaluationEdit;
