import React, {useEffect} from "react";
import {useSelector, useDispatch} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import Page from "../../components/page/Page";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import {selectTestList} from "../../store/neuromotors/neuromotorsSelector";
import {getAllTests} from "../../store/neuromotors/neuromotorsReducer";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {fetchClient} from "../../store/client/clientReducer";
import {getTestConfigurations} from "../../utils/neuromotors/testConfig";
import NeuromotorCreateUpdate from "./NeuromotorCreateUpdate";
import {useTranslation} from "react-i18next";
import {buildNeuromotorTestRoute} from "../../utils/client/evaluationRoutes";
import {getNeuromotorPageFromType} from "../../utils/neuromotors/navigation";

const NeuromotorEdit = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {clientId, type, id} = useParams();
    const {t} = useTranslation();
    const selectedClient = useSelector(selectSelectedClient);
    const config = getTestConfigurations(t)[Number(type)];
    const testId = Number(id);
    const tests = useSelector(selectTestList);
    const test = tests ? tests.find((item) => item.id === testId) : null;
    const page = getNeuromotorPageFromType(type);

    const initialValues = config.fields.reduce((acc, field) => {
        acc[field.name] = test ? test[field.name] || "" : "";
        return acc;
    }, {id: testId});

    const handleGoBackPage = () => {
        navigate(buildNeuromotorTestRoute(type, clientId, page));
    };

    useEffect(() => {
        dispatch(getAllTests({type, clientId}));
    }, [dispatch, type, clientId]);

    useEffect(() => {
        if (!selectedClient) {
            dispatch(fetchClient(clientId));
        }
    }, [clientId, dispatch, selectedClient]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className="pb-4 pt-2"
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
            />
            <Page contentHeader={false}>
                <div className="row">
                    <div className="col-12">
                        <div className="card card-body border-0 gap-2">
                            <div>
                                <NeuromotorCreateUpdate
                                    type={type}
                                    initialValues={initialValues}
                                    page={page}
                                    clientId={clientId}
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default NeuromotorEdit;
