import {createSelector} from "reselect";

const reducer = state => state.clientProgress;

export const selectClientProgressList = createSelector([reducer], slice => slice.list || []);
export const selectClientProgressListStatus = createSelector([reducer], slice => slice.listStatus);
export const selectClientProgressListErrorCode = createSelector([reducer], slice => slice.listErrorCode);
export const selectClientProgressLoading = createSelector([reducer], slice => slice.listLoading);
export const selectClientProgressRespondLoading = createSelector(
    [reducer, (_, progressId) => progressId],
    (slice, progressId) => Boolean(slice.respondLoadingById?.[progressId])
);
export const selectClientProgressDeleteLoading = createSelector(
    [reducer, (_, progressId) => progressId],
    (slice, progressId) => Boolean(slice.deleteLoadingById?.[progressId])
);
