import {createSlice} from "@reduxjs/toolkit";

const INITIAL_STATE = {
    paces: null,
    workouts: null,
    aerobics: null,
    loadingPace: false,
    loading: false
}

export const slice = createSlice({
    name: "workout",
    initialState: INITIAL_STATE,
    reducers: {
        fetchAllWorkouts(state) {
            state.loading = true
        },
        setLoadingStatus(state, action) {
            state.loading = action.payload;
        },
        onError(state) {
            state.loading = false;
        }
    }

})

export const {
    fetchAllWorkouts,
    setLoadingStatus,
    onError
} = slice.actions

export const workoutReducer = slice.reducer