import UpdateResolveAllModal from "./UpdateResolveAllModal";
import Modal from "react-bootstrap/Modal";
import Pagination from "../pagination/Pagination";
import React, {useCallback, useEffect, useMemo, useState} from "react";
import {
    selectResolveAllUpdatesContext,
    selectResolveAllUpdatesStatus,
    selectUpdates,
    selectUpdatesLoading
} from "../../store/updates/updatesSelector";
import {useDispatch, useSelector} from "react-redux";
import {
    clearResolveAllUpdatesStatus,
    fetchAllUpdatesByType,
    resolveAllUpdates
} from "../../store/updates/updatesReducer";
import {useNavigate, useParams} from "react-router-dom";
import _ from "lodash";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import moment from "moment";
import UpdateDateFilterModal from "./UpdateDateFilterModal";
import EmptySet from "../empty-set/EmptySet";
import LoadingBlock from "../loader/LoadingBlock";
import {addToast} from "../../store/toast/toastReducer";
import {updateCategories, updateTypeMap} from "./updateTypeRegistry";

const UpdateList = ({status}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const updates = useSelector(selectUpdates)
    const loading = useSelector(selectUpdatesLoading);
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(5);
    const [searchQuery, setSearchQuery] = useState("");
    const [showDateFilterModal, setShowDateFilterModal] = useState(false);
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const pagesToShow = 5;
    const [showResolveAllModal, setShowResolveAllModal] = useState(false);
    const {type} = useParams();
    const resolveAllStatus = useSelector(selectResolveAllUpdatesStatus);
    const resolveAllContext = useSelector(selectResolveAllUpdatesContext);
    useComponentTranslations('updateCardComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const [dateRange, setDateRange] = useState({startDate: "", endDate: ""});
    const updateTitle = updateCategories.find((c) => c.type === Number(type))?.labelKey;
    const normalizeSearchValue = useCallback((value) => {
        return (value ?? "")
            .toString()
            .toLowerCase()
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .replace(/[^\p{L}\p{N}\s]/gu, " ")
            .replace(/\s+/g, " ")
            .trim();
    }, []);

    const filteredUpdates = useMemo(() => {
        const normalizedQuery = normalizeSearchValue(searchQuery);
        if (!normalizedQuery) {
            return updates ?? [];
        }

        return (updates ?? []).filter((update) => {
            const firstName = update?.aluno?.nome ?? "";
            const lastName = update?.aluno?.sobrenome ?? "";
            const normalizedName = normalizeSearchValue(`${firstName} ${lastName}`);

            return normalizedName.includes(normalizedQuery);
        });
    }, [normalizeSearchValue, searchQuery, updates]);

    const currentItems = filteredUpdates.slice(indexOfFirstItem, indexOfLastItem);
    const totalItems = filteredUpdates.length;


    const handleResolveAllConfirmationClick = () => {
        if (hasActiveFilters) {
            const updateIds = filteredUpdates
                .map((update) => update?.id)
                .filter(Boolean);

            if (updateIds.length === 0) {
                handleResolveAllClick();
                return;
            }

            dispatch(resolveAllUpdates({
                payload: {updateIds},
                context: {shouldRefetch: true, fetchPayload}
            }));
            return;
        }

        dispatch(resolveAllUpdates({
            payload: {type: Number(type)},
            context: {shouldRefetch: false, navigateTo: "/user/update"}
        }))
    }

    const handleResolveAllClick = () => {
        if (resolveAllStatus === "pending") {
            return;
        }
        setShowResolveAllModal(prevState => !prevState)
    }

    const hasDateRange = Boolean(dateRange.startDate && dateRange.endDate);
    const hasActiveFilters = Boolean(searchQuery.trim() || hasDateRange);

    const fetchPayload = useMemo(() => {
        const payload = {
            type: Number(type),
            status: status
        };

        if (hasDateRange) {
            payload.startDate = `${dateRange.startDate}T00:00:00`;
            payload.endDate = `${dateRange.endDate}T23:59:59`;
        }

        return payload;
    }, [dateRange.endDate, dateRange.startDate, hasDateRange, status, type]);

    useEffect(() => {
        if (status === 1) {
            const endDate = moment().format("YYYY-MM-DD");
            const startDate = moment().subtract(30, "days").format("YYYY-MM-DD");
            setDateRange({startDate, endDate});
        } else {
            setDateRange({startDate: "", endDate: ""});
        }

        setSearchQuery("");
        setCurrentPage(1);
    }, [status]);
    useEffect(() => {
        dispatch(fetchAllUpdatesByType(fetchPayload));
    }, [dispatch, fetchPayload])

    useEffect(() => {
        const totalPages = Math.ceil(totalItems / itemsPerPage);
        if (currentPage > totalPages && totalPages > 0) {
            setCurrentPage(totalPages);
        }
    }, [currentPage, totalItems, itemsPerPage]);

    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery]);

    useEffect(() => {
        if (resolveAllStatus === "success") {
            dispatch(addToast({
                type: 'success',
                title: t("updateCardComponent:toastTitle"),
                message: t("updateCardComponent:resolveAllSuccess")
            }));

            if (resolveAllContext?.shouldRefetch) {
                dispatch(fetchAllUpdatesByType(resolveAllContext.fetchPayload ?? fetchPayload));
            } else {
                navigate(resolveAllContext?.navigateTo ?? "/user/update");
            }

            setShowResolveAllModal(false);
            dispatch(clearResolveAllUpdatesStatus());
        }

        if (resolveAllStatus === "failure") {
            dispatch(addToast({
                type: 'error',
                title: t("updateCardComponent:toastErrorTitle"),
                message: t("updateCardComponent:resolveAllFailure")
            }));
            setShowResolveAllModal(false);
            dispatch(clearResolveAllUpdatesStatus());
        }
    }, [dispatch, fetchPayload, navigate, resolveAllContext, resolveAllStatus, t]);

    return (
        <>
            <div className={"row pt-4"}>
                {
                    status === 0 &&
                    <div className={"col-12"}>
                        <button
                            className={'btn btn-primary w-100'}
                            onClick={handleResolveAllClick}
                            disabled={(hasActiveFilters && totalItems === 0) || updates?.length === 0}
                        >
                            {t("updateCardComponent:resolveAll")}
                        </button>
                    </div>
                }

                <div className={'col-12 mt-2 d-flex gap-1'}>
                    <div className={"input-group mx-auto"}>
                        <input
                            aria-label={t("updateCardComponent:searchClient")}
                            className={'form-control bg-white'}
                            onChange={(event) => setSearchQuery(event.target.value)}
                            placeholder={t("updateCardComponent:searchClient")}
                            type={'search'}
                            value={searchQuery}
                        />
                        <span className={'input-group-text bg-white'}>
                            <i className={'fa-regular fa-magnifying-glass'}/>
                        </span>
                    </div>
                    <button
                        className={`input-group-text   ${hasDateRange ? "btn btn-feedback-primary text-primary" : "bg-white"}`}
                        type="button"
                        onClick={() => setShowDateFilterModal(true)}
                        aria-label={t("updateCardComponent:filterByDate")}
                    >
                        <i className="fa-solid fa-sliders" aria-hidden="true"/>
                    </button>
                </div>
                {hasDateRange && (
                    <div className="col-12 mt-2">
                        <div className="d-flex flex-wrap align-items-center gap-2">
                            <span className="text-muted small">
                                {t("updateCardComponent:selectedPeriod")}
                            </span>
                            <span className="badge bg-primary-subtle text-primary fw-semibold d-inline-flex align-items-center gap-2">
                                {moment(dateRange.startDate).format("DD/MM/YYYY")} – {moment(dateRange.endDate).format("DD/MM/YYYY")}
                                <i className={"fa-regular fa-times clickable-element"} onClick={() => setDateRange({startDate: "", endDate: ""})}
                                   aria-label={t("updateCardComponent:clearFilter")}></i>
                            </span>
                        </div>
                    </div>
                )}
            </div>
            <div className={"row pt-2"}>
                <div className={"col-12"}>
                    <span className={"fw-semibold fs-5"}>{t(`${updateTitle}`)}</span>
                </div>
            </div>
            {
                totalItems === 0 && hasActiveFilters &&
                <div className={"row pt-2"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            <EmptySet icon={"fa-magnifying-glass"}  message={t("updateCardComponent:noResultsFound")}/>
                        </div>
                    </div>
                </div>
            }
            {
                loading &&
                <div className={"row pt-2"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            <LoadingBlock/>
                        </div>
                    </div>
                </div>
            }
            {
                !loading && updates?.length === 0 && !hasActiveFilters &&
                <div className={"row pt-2"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            <EmptySet
                                icon={"fa-calendar-lines-pen"}
                                message={
                                    status === 1
                                        ? t("updateCardComponent:noResolvedUpdates")
                                        : t("updateCardComponent:allResolved")
                                }
                                message2={t("updateCardComponent:noNewUpdatesMessageBody")}
                            />
                        </div>
                    </div>
                </div>
            }
            {
                !loading && updates?.length > 0 &&
                <div className={'row pt-2'}>
                    {_.map(currentItems, (update, index) => {
                        const Card = updateTypeMap[Number(update.tipo)];

                        if (!Card) {
                            return null;
                        }

                        return (
                            <div className={'col-12  '} key={index}>
                                <Card update={update}/>
                            </div>
                        );
                    })}
                    {
                        totalItems > itemsPerPage &&
                        <div className={'row justify-content-center '}>
                            <div className={'col-12'}>
                                <Pagination
                                    currentPage={currentPage}
                                    totalItems={totalItems}
                                    itemsPerPage={itemsPerPage}
                                    onPageChange={setCurrentPage}
                                    pagesToShow={pagesToShow}
                                />
                            </div>
                        </div>
                    }
                </div>
            }
            <Modal centered show={showResolveAllModal} onHide={handleResolveAllClick}>
                <Modal.Body>
                    <UpdateResolveAllModal handleResolveAllClick={handleResolveAllClick}
                                           isLoading={resolveAllStatus === "pending" || loading}
                                           handleResolveAllConfirmationClick={handleResolveAllConfirmationClick}/>
                </Modal.Body>
            </Modal>
            <UpdateDateFilterModal
                show={showDateFilterModal}
                onClose={() => setShowDateFilterModal(false)}
                onApply={(values) => setDateRange(values)}
                onClear={() => setDateRange({startDate: "", endDate: ""})}
                initialStartDate={dateRange.startDate}
                initialEndDate={dateRange.endDate}
            />
        </>
    )
}

export default UpdateList
