import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import React, {useEffect, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {fetchClient} from "../../store/client/clientReducer";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import CardMenu from "../../components/card/CardMenu";
import {
    getCustomLoading,
    selectAllCustomModels,
    selectSubmitLoading,
    selectSubmitResult
} from "../../store/custom-evaluation/customEvaluationSelector";
import EmptySet from "../../components/empty-set/EmptySet";
import {changeCustomStatus, getAllCustomModels, resetFormSent} from "../../store/custom-evaluation/customEvaluationReducer";
import {ModalBody} from "react-bootstrap";
import Modal from "react-bootstrap/Modal";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import enUS from "./locales/en-us.json";
import Text from "../../components/utils/emoji/Text";
import {
    buildClientCustomRoute,
    buildCustomCreateModelRoute,
    buildCustomEditModelRoute,
    buildCustomFillModelRoute
} from "../../utils/client/evaluationRoutes";
import DeleteModal from "../../components/modal/DeleteModal";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitError, isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const CustomModels = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id} = useParams();
    const {t} = useTranslation();
    const selectedClient = useSelector(selectSelectedClient);
    const loadingClient = useSelector(isClientsLoading);
    const customModels = useSelector(selectAllCustomModels);
    const loadingCustom = useSelector(getCustomLoading);
    const submitLoading = useSelector(selectSubmitLoading);
    const submitResult = useSelector(selectSubmitResult);
    const [selectedModel, setSelectedModel] = useState(null);
    const [showOptionsModal, setShowOptionsModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [deleteRequested, setDeleteRequested] = useState(false);
    syncMomentLocale(i18n.language);
    useComponentTranslations('customEvaluation', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(getAllCustomModels(id));
    }, [dispatch, id]);

    const handleGoBackPage = () => {
        navigate(buildClientCustomRoute(id));
    };

    const handleGoCreateModel = () => {
        navigate(buildCustomCreateModelRoute(id));
    };

    const handleGoFillEvaluation = () => {
        navigate(buildCustomFillModelRoute(id, selectedModel?.id))
    };

    const handleGoEditModel = () => {
        navigate(buildCustomEditModelRoute(id, selectedModel?.id));
    };

    const handleOptionsModal = (custom) => {
        setShowOptionsModal(prevState => !prevState)
        setSelectedModel(custom);
    };

    const handleDeleteModal = () => {
        setShowOptionsModal(false);
        setShowDeleteModal(prevState => !prevState);
        if (showDeleteModal) {
            setDeleteRequested(false);
        }
    };

    const handleConfirmDelete = () => {
        if (!selectedModel) {
            return;
        }
        setDeleteRequested(true);
        dispatch(changeCustomStatus(
            {id: selectedModel.id, status: 1},
            {flow: EVALUATION_FLOWS.CUSTOM_MODEL_DELETE, clientId: id}
        ));
    };

    useEffect(() => {
        if (!deleteRequested) {
            return;
        }

        if (isMatchingSubmitSuccess(submitResult, {
            action: "delete",
            flow: EVALUATION_FLOWS.CUSTOM_MODEL_DELETE,
            clientId: id
        })) {
            setShowDeleteModal(false);
            setDeleteRequested(false);
            setSelectedModel(null);
        }

        if (isMatchingSubmitError(submitResult, {
            action: "delete",
            flow: EVALUATION_FLOWS.CUSTOM_MODEL_DELETE,
            clientId: id
        })) {
            setDeleteRequested(false);
        }
    }, [deleteRequested, id, submitResult]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loadingCustom} pb={"pb-2"}>
                <div className={"card card-body border-0"}>
                    <span className={"fw-semibold"}>{t("customEvaluation:customEvaluationTitle")}</span>
                    <div className={"pt-2"}>
                        <CardButtonAdd
                            handleClick={handleGoCreateModel}
                            text={t("customEvaluation:createNewModel")}
                        />
                    </div>
                    <div className={"py-2"}>
                        <span className={"fw-semibold"}>{t("customEvaluation:models")}</span>
                        {(!customModels || customModels.length === 0) && (
                            <EmptySet icon={"fa-regular fa-folder-open"}
                                      message={t("customEvaluation:emptySetModels")}/>
                        )}
                        {!loadingCustom && customModels && customModels.length > 0 && (
                            <div className={"py-2"}>
                                {customModels.map((custom) => (
                                    <CardMenu
                                        key={custom.id}
                                        title={custom.tipo}
                                        onClick={() => handleOptionsModal(custom)}
                                    />
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </Page>
            {selectedModel && (
                <Modal show={showOptionsModal} onHide={handleOptionsModal} centered>
                    <ModalBody>
                        <div className={"row"}>
                            <div className={"col-12"}>
                                <div className={"row justify-content-between"}>
                                    <div className={"col-auto"}>
                                    <span className={"fw-semibold text-start"}>
                                        <Text>{selectedModel?.tipo}</Text>
                                    </span>
                                    </div>
                                    <div className={"col-auto cursor-pointer"} onClick={handleOptionsModal}>
                                        <i className={"fa-regular fa-times"}/>
                                    </div>
                                </div>
                                <div className={"d-grid gap-2 pt-3"}>
                                    <button className={"btn btn-outline-primary"}
                                            onClick={handleGoFillEvaluation}>{t("customEvaluation:fillEvaluation")}</button>
                                    <button className={"btn btn-outline-primary"}
                                            onClick={handleGoEditModel}>{t("customEvaluation:editModel")}</button>
                                    <button className={"btn btn-outline-danger"}
                                            onClick={handleDeleteModal}>{t("customEvaluation:deleteModel")}</button>
                                </div>
                            </div>
                        </div>
                    </ModalBody>
                </Modal>
            )}
            <DeleteModal
                show={showDeleteModal}
                onClose={handleDeleteModal}
                onConfirm={handleConfirmDelete}
                isSubmitting={deleteRequested && submitLoading}
                deleteTitle={t("customEvaluation:deleteTitle")}
                deleteSubtitle={t("customEvaluation:deleteSubtitle")}
                confirmLabel={t("customEvaluation:confirm")}
                closeLabel={t("customEvaluation:close")}
                loadingLabel={t("customEvaluation:confirm")}
            />
        </>
    )
}

export default CustomModels;
