import {ErrorMessage, Field} from "formik";
import Select from "react-select";
import ClientRemoteMultiSelect from "../client/ClientRemoteMultiSelect";

const mapSelectedGroupValues = (values, options, allLabel) => (
    (values || [])
        .map((value) => {
            if (value === 0) {
                return {value, label: allLabel};
            }

            return options.find((option) => option.value === value) || null;
        })
        .filter(Boolean)
);

const PushAudienceFields = ({
                                lockedAudience,
                                groupsLoading,
                                onSendToChange,
                                groupOptions,
                                setFieldValue,
                                t,
                                touched,
                                values,
                                errors
                            }) => {
    if (lockedAudience) {
        return (
            <div className={"mt-3"}>
                <label className={"fw-semibold d-block mb-2"}>{t("push:selectedAudience")}</label>
                <div className={"card border  rounded-3 shadow-none bg-white"}>
                    <div className={"card-body px-3 py-2"}>
                        <span className={"small text-secondary d-block"}>{lockedAudience.summaryLabel}</span>
                        <span className={"fw-semibold fs-5 d-block mt-1"}>
                            {lockedAudience.countLabel || t("push:lockedAudienceCount", {count: lockedAudience.summaryCount})}
                        </span>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <>
            <div className={"form-group mt-2"}>
                <label className={"fw-semibold"}>{t("push:sendTo")}</label>
                <Field
                    as={"select"}
                    name={"sendTo"}
                    value={values.sendTo}
                    className={`form-control ${touched.sendTo && errors.sendTo ? "is-invalid" : ""}`}
                    onChange={(event) => {
                        const nextValue = event.target.value;
                        setFieldValue("sendTo", nextValue);
                        setFieldValue("selectOption", []);
                        onSendToChange?.(nextValue);
                    }}
                >
                    <option value={""}>{t("push:select")}</option>
                    <option value={"clients"}>{t("push:clients")}</option>
                    <option value={"groups"}>{t("push:groups")}</option>
                </Field>
                <ErrorMessage name={"sendTo"} component={"div"} className={"invalid-feedback"}/>
            </div>

            {values.sendTo && (
                <div className={"form-group mt-2"}>
                    <label className={"fw-semibold"}>
                        {values.sendTo === "clients" ? t("push:selectOneOrMoreClients") : t("push:selectOneOrMoreGroups")}
                    </label>
                    {values.sendTo === "clients" ? (
                        <ClientRemoteMultiSelect
                            valueIds={values.selectOption}
                            onChangeIds={(clientIds) => {
                                if (clientIds.includes(0) && clientIds.length > 1) {
                                    setFieldValue("selectOption", [0]);
                                    return;
                                }

                                setFieldValue("selectOption", clientIds);
                            }}
                            searchScope={"active"}
                            resolveScope={"nonDeleted"}
                            specialOptions={[{value: 0, label: t("push:all")}]}
                            placeholder={t("push:select")}
                            noOptionsMessage={() => t("push:noOptions")}
                            loadingMessage={() => t("push:loading")}
                        />
                    ) : (
                        <>
                            <Select
                                isMulti
                                name={"selectOption"}
                                options={groupOptions}
                                required
                                className={"basic-multi-select"}
                                classNamePrefix={"select"}
                                placeholder={t("push:select")}
                                noOptionsMessage={() => t("push:noOptions")}
                                onChange={(selectedOptions) => {
                                    const hasAll = selectedOptions?.some((option) => option.value === 0);
                                    if (hasAll && selectedOptions.length > 1) {
                                        setFieldValue("selectOption", [0]);
                                        return;
                                    }

                                    setFieldValue("selectOption", (selectedOptions || []).map((option) => option.value));
                                }}
                                value={mapSelectedGroupValues(values.selectOption, groupOptions, t("push:all"))}
                            />
                            {groupsLoading && (
                                <span className={"small fw-semibold d-block mt-1"}>
                                    <i className={"fa-regular fa-exclamation-circle me-1"}></i>
                                    {t("push:loading")}
                                </span>
                            )}
                        </>
                    )}
                    {touched.selectOption && errors.selectOption && (
                        <div className={"invalid-feedback d-block"}>{errors.selectOption}</div>
                    )}
                </div>
            )}
        </>
    );
};

export default PushAudienceFields;
