import {createSelector} from "reselect";


const reducer = state => state.wallet;

export const selectBalance = createSelector([reducer], slice => slice.balance);
export const selectBalanceIsLoading = createSelector([reducer], slice => slice.balanceLoading);
export const selectWalletRequestLoading = createSelector([reducer], slice => slice.walletRequestLoading);
export const selectSellerLoading = createSelector([reducer], slice => slice.sellerLoading);
export const selectSeller = createSelector([reducer], slice => slice.seller);
export const selectWalletRequest = createSelector([reducer], slice => slice.walletRequest);