import {formatDelta, formatMetricValue, getRetentionMetricMeta} from "./retentionConfig";

const RetentionMetricCard = ({metric, card, locale, t}) => {
    const meta = getRetentionMetricMeta(metric, t);
    const deltaClass = Number(card?.deltaPct || 0) >= 0 ? "text-success" : "text-danger";

    return (
        <div className={"col-6"}>
            <div className={"card border h-100"}>
                <div className={"card-body p-3 d-flex flex-column justify-content-between"}>
                    <span className={"small text-secondary d-flex align-items-center text-uppercase"}>
                        <i className={`${meta.icon} me-2`}></i>
                        {meta.label}
                    </span>
                    <span className={"d-block fw-bold fs-3 lh-1 mt-3"}>
                        {formatMetricValue(metric, card?.value, locale)}
                    </span>
                    <span className={`small fw-semibold d-block mt-2 ${deltaClass}`}>
                        {formatDelta(card?.deltaPct, locale)}
                    </span>
                </div>
            </div>
        </div>
    );
};

export default RetentionMetricCard;
