import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useCallback, useEffect, useState} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {useDispatch, useSelector} from "react-redux";
import {
    updateAnamnesis,
    deleteAnamnesis,
    getAnamnesis,
    setAnamnesis, resetFormSent
} from "../../store/anamnesis/anamnesisReducer";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {
    isAnamnesisLoading,
    isSubmitLoading,
    getSubmitResult,
    selectAnamnesis
} from "../../store/anamnesis/anamnesisSelector";
import {Field, Form, Formik} from "formik";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {getTranslatedQuestion} from "../../utils/anamnesis/questionUtils";
import TextareaAutosize from 'react-textarea-autosize';
import {setSummarizedAnamnesis, summarizeAnamnesis} from "../../store/ai-actions/aiActionsReducer";
import {getSummarizedAnamnesis, getWaiting} from "../../store/ai-actions/aiActionsSelector";
import AiAnalysis from "../../components/ai/AiAnalysis";
import {buildAnamnesisListRoute} from "../../utils/client/evaluationRoutes";
import DeleteModal from "../../components/modal/DeleteModal";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitError, isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";


const AnamnesisAnswered = () => {
    const {t, i18n} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {clientId, anamnesisId, goBackTo} = useParams();
    const anamnesisData = useSelector(selectAnamnesis);
    const loading = useSelector(isAnamnesisLoading);
    const submitLoading = useSelector(isSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const [showModal, setShowModal] = useState(false);
    const [pendingDelete, setPendingDelete] = useState(false);
    const summarizedAnamnesis = useSelector(getSummarizedAnamnesis);
    const summarizationWaiting = useSelector(getWaiting);
    const backToUpdates = goBackTo === "updates";
    const currentClientId = Number(clientId);
    useComponentTranslations('anamnesis', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    syncMomentLocale(i18n.language);

    const answeredDate = anamnesisData?.answeredDate
        ? moment({
            year: anamnesisData.answeredDate.year,
            month: anamnesisData.answeredDate.month - 1,
            day: anamnesisData.answeredDate.day
        }).format("L")
        : null;

    const handleGoBack = useCallback(() => {
        if (backToUpdates) {
            navigate(`/user/update/list/8`);
        } else
            navigate(buildAnamnesisListRoute(clientId));
    }, [navigate, clientId, backToUpdates]);

    const handleDeleteModal = () => {
        setShowModal(true);
    };

    const handleCloseModal = () => {
        setShowModal(false);
        setPendingDelete(false);
    };

    const handleDeleteAnamnesis = useCallback(() => {
        setPendingDelete(true);
        dispatch(deleteAnamnesis(anamnesisId, {
            flow: EVALUATION_FLOWS.ANAMNESIS_DELETE,
            clientId: currentClientId
        }));
    }, [currentClientId, dispatch, anamnesisId]);


    const handleSubmit = async (values) => {
        const noAnswers = values.answers.every(answer => !answer.answer || answer.answer.trim() === "");
        if (noAnswers) {
            handleGoBack();
            return;
        }

        const data = {
            id: anamnesisId,
            idClient: clientId,
            questions: values.answers.map((answer) => ({
                id: answer.id,
                answer: answer.answer,
                question: answer.question,
            })),
        };
        dispatch(updateAnamnesis(data, {
            flow: EVALUATION_FLOWS.ANAMNESIS_EDIT,
            clientId: currentClientId
        }));
    }

    const handleSummarizeClick = () => {
        dispatch(summarizeAnamnesis(anamnesisData.id))
    }

    useEffect(() => {
        dispatch(fetchClient(clientId))
        dispatch(getAnamnesis(anamnesisId));
        dispatch(resetFormSent());
        return () => {
            dispatch(setAnamnesis(null))
            dispatch(resetFormSent())
        }
    }, [dispatch, clientId, anamnesisId]);

    useEffect(() => {
        if (anamnesisData && anamnesisData.blocked) {
            if (anamnesisData.aiAnalysis) {
                dispatch(setSummarizedAnamnesis(anamnesisData.aiAnalysis));
            } else {
                dispatch(summarizeAnamnesis(anamnesisData.id));
            }
        }
    }, [dispatch, anamnesisData]);

    useEffect(() => {
        if (isMatchingSubmitSuccess(submitResult, {
            action: "update",
            flow: EVALUATION_FLOWS.ANAMNESIS_EDIT,
            clientId: currentClientId
        })) {
            handleGoBack()
        }
    }, [currentClientId, submitResult, handleGoBack])

    useEffect(() => {
        if (!pendingDelete) {
            return;
        }

        if (isMatchingSubmitSuccess(submitResult, {
            action: "delete",
            flow: EVALUATION_FLOWS.ANAMNESIS_DELETE,
            clientId: currentClientId
        })) {
            setShowModal(false);
            setPendingDelete(false);
            handleGoBack();
        }

        if (isMatchingSubmitError(submitResult, {
            action: "delete",
            flow: EVALUATION_FLOWS.ANAMNESIS_DELETE,
            clientId: currentClientId
        })) {
            setPendingDelete(false);
        }
    }, [currentClientId, pendingDelete, submitResult, handleGoBack]);

    useEffect(() => {
        return () => {
            dispatch(setSummarizedAnamnesis(null))
        }
    }, [dispatch])

    return (
        <>
            <Page
                title={anamnesisData?.name === "Padrão" || anamnesisData?.name === "PAR-Q" ? t(`anamnesis:${anamnesisData?.name}`) : anamnesisData?.name}
                goBackLink={handleGoBack}
                loading={loading}
                mt={"mt-n5"}
            >
                <div className={'row justify-content-center d-flex'}>
                    <div className={"col-12"}>
                        {
                            answeredDate &&
                            <div className={"card card-body border-0 mb-3"}>
                                <div className={"row"}>
                                    <div className={"col-12"}>
                                        <AiAnalysis onGenerateAnalysis={handleSummarizeClick}
                                                    isWaiting={summarizationWaiting}
                                                    analysis={summarizedAnamnesis}
                                                    disclaimer={t("anamnesis:disclaimer")}
                                        />
                                    </div>
                                </div>
                            </div>
                        }
                        <div className={'card card-body border-0'}>
                            <div className={"row"}>
                                {answeredDate &&
                                    <div className={"col-12 pt-2 pb-4"}>
                                        <span className={"fw-semibold"}>{t("anamnesis:answeredIn")}</span>
                                        <span> {answeredDate}</span>
                                    </div>
                                }
                                <div className={'col-12'}>
                                    {anamnesisData?.questions &&
                                        <Formik
                                            initialValues={{
                                                answers: anamnesisData?.questions?.map((q) => ({
                                                    id: q.id,
                                                    answer: q.answer,
                                                    question: q.question,
                                                })) || [],
                                            }}
                                            onSubmit={handleSubmit}
                                            enableReinitialize
                                        >
                                            <Form>
                                                {anamnesisData?.questions?.map((question, index) => (
                                                    <div key={question.id}
                                                         className={"mb-2 align-items-center justify-content-center"}>
                                                        <span className={"fw-semibold"}>
                                                             {getTranslatedQuestion(question, i18n.language)}
                                                        </span>
                                                        <Field
                                                            as={TextareaAutosize}
                                                            className={"form-control mt-1"}
                                                            name={`answers[${index}].answer`}
                                                        />
                                                    </div>
                                                ))}
                                                <div className={"row mt-3 align-items-center justify-content-center"}>
                                                    <div className={"d-grid"}>
                                                        <button type="submit" className={"btn btn-primary"} disabled={loading || submitLoading}>
                                                            {submitLoading ? t("anamnesis:saving") : t("anamnesis:save")}</button>
                                                    </div>
                                                </div>
                                            </Form>
                                        </Formik>
                                    }
                                </div>
                                <div className={'col-12 mt-2'}>
                                    <div className={"d-grid"}>
                                        <button className={"btn btn-outline-danger"} onClick={handleDeleteModal}>
                                            {t("anamnesis:delete")}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
            <DeleteModal
                show={showModal}
                onClose={handleCloseModal}
                onConfirm={handleDeleteAnamnesis}
                isSubmitting={pendingDelete && submitLoading}
                deleteTitle={t("anamnesis:areYouSure")}
                deleteSubtitle={t("anamnesis:actionCannotBeUndone")}
                confirmLabel={t("anamnesis:yesDelete")}
                closeLabel={t("anamnesis:close")}
                loadingLabel={t("anamnesis:saving")}
            />
        </>
    );
};

export default AnamnesisAnswered;
