import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    helpMenu: false,
    chatbot: false,
    userMenu: false
}

export const slice = createSlice({
    name: 'menu',
    initialState,
    reducers: {
        toggleHelpMenu(state) {
            state.helpMenu = !state.helpMenu
        },
        toggleChatBot(state) {
            state.chatbot = !state.chatbot
        },
        toggleUserMenu(state) {
            state.userMenu = !state.userMenu
        }
    }
})

export const {
    toggleHelpMenu,
    toggleChatBot,
    toggleUserMenu
} = slice.actions

export const menuReducer = slice.reducer