import {createSelector} from 'reselect';

const reducer = state => state.signupLink;

export const selectContacts = createSelector(
    [reducer],
    s => s.contacts
);

export const selectSignupLoading = createSelector(
    [reducer],
    s => s.loading
);

export const isContactConverted = createSelector(
    [reducer],
    s => s.contactConverted
);