import {createSlice} from "@reduxjs/toolkit";

const INITIAL_STATE = {
    list: [],
    listLoading: false,
    listStatus: "idle",
    listErrorCode: null,
    respondLoadingById: {},
    deleteLoadingById: {}
};

export const clientProgressSlice = createSlice({
    name: "clientProgress",
    initialState: INITIAL_STATE,
    reducers: {
        fetchClientProgressList(state) {
            state.listLoading = true;
            state.listStatus = "loading";
            state.listErrorCode = null;
            state.list = [];
        },
        setClientProgressList(state, action) {
            state.listLoading = false;
            state.listStatus = "success";
            state.listErrorCode = null;
            state.list = action.payload || [];
        },
        clientProgressListError(state, action) {
            state.listLoading = false;
            state.listStatus = "error";
            state.listErrorCode = action.payload || null;
            state.list = [];
        },
        respondClientProgress(state, action) {
            state.respondLoadingById[action.payload.progressId] = true;
        },
        respondClientProgressSuccess(state, action) {
            const {progressId, response} = action.payload;
            delete state.respondLoadingById[progressId];
            state.list = (state.list || []).map((item) => (
                item.id === progressId
                    ? {
                        ...item,
                        resposta: response,
                        status: 1
                    }
                    : item
            ));
        },
        deleteClientProgress(state, action) {
            state.deleteLoadingById[action.payload.progressId] = true;
        },
        deleteClientProgressSuccess(state, action) {
            delete state.deleteLoadingById[action.payload];
            state.list = (state.list || []).filter(item => item.id !== action.payload);
        },
        onError(state) {
            state.listLoading = false;
            state.respondLoadingById = {};
            state.deleteLoadingById = {};
        }
    }
});

export const {
    fetchClientProgressList,
    setClientProgressList,
    clientProgressListError,
    respondClientProgress,
    respondClientProgressSuccess,
    deleteClientProgress,
    deleteClientProgressSuccess,
    onError
} = clientProgressSlice.actions;

export const clientProgressReducer = clientProgressSlice.reducer;
