import {useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";

const Avatar = ({url, maxWidth = "48px", blueBorder = false, borderWidth = 4, padding}) => {
    const user = useSelector(selectUser);

    const imageUrl =
        url === "empty" || !url
            ? "https://cdn.mfitpersonal.com.br/assets/user/user.jpg"
            : url;

    const borderUrl = "https://cdn.mfitpersonal.com.br/assets/mfit-de-ouro/border.png";

    const size = maxWidth;

    const hasGoldenBorder = user?.id === 42963;
    const wrapperClassName = padding || "";
    const wrapperStyle = {
        display: "inline-block"
    };
    const imageStyle = {
        width: "100%",
        height: "100%",
        objectFit: "cover",
        objectPosition: "center",
        display: "block"
    };
    const frameStyle = {
        display: "flex",
        width: size,
        height: size,
        borderRadius: "50%",
        overflow: "hidden",
        flexShrink: 0,
        boxSizing: "border-box",
        border: blueBorder ? `${borderWidth}px solid #0C92EB` : "none"
    };

    if (hasGoldenBorder) {
        return (
            <div className={wrapperClassName} style={wrapperStyle}>
                <div
                    style={{
                        position: "relative",
                        width: size,
                        height: size
                    }}
                    className="mx-auto d-block"
                >
                    <div
                        style={{
                            width: "100%",
                            height: "100%",
                            borderRadius: "50%",
                            overflow: "hidden",
                            position: "relative",
                            zIndex: 1
                        }}
                    >
                        <img
                            src={imageUrl}
                            alt=""
                            style={imageStyle}
                        />
                    </div>

                    <img
                        src={borderUrl}
                        alt=""
                        style={{
                            position: "absolute",
                            top: "-10%",
                            left: "-10%",
                            width: "120%",
                            height: "120%",
                            objectFit: "contain",
                            zIndex: 2,
                            pointerEvents: "none"
                        }}
                    />
                </div>

            </div>

        );
    }

    return (
        <div className={wrapperClassName} style={wrapperStyle}>
            <div
                className="mx-auto d-block"
                style={frameStyle}
            >
                <img
                    src={imageUrl}
                    alt=""
                    style={imageStyle}
                />
            </div>
        </div>
    );
};

export default Avatar;
