import React from "react";

const EvaluationSuccessCard = ({
                                   title,
                                   primaryLabel,
                                   secondaryLabel,
                                   onPrimary,
                                   onSecondary,
                                   primaryDisabled = false,
                                   withCard = true,
                               }) => {
    const content = (
        <div className={"py-2"}>
            <div className={"row justify-content-center d-flex"}>
                <div className={"col-auto pb-3 pt-2"}>
                    <span className={"text-white fs-2 d-block"}>
                        <i className={"fa-regular fa-2xl fa-circle-check text-success"}/>
                    </span>
                </div>
            </div>
            <div className={"row justify-content-center d-flex"}>
                <div className={"col-12 text-center pb-2 pb-lg-4"}>
                    <span className={"fs-4 fw-bold"}>
                        {title}
                    </span>
                </div>
            </div>
            <button
                className={"btn btn-primary w-100 "}
                onClick={onPrimary}
                disabled={primaryDisabled}
            >
                {primaryLabel}
            </button>
            {secondaryLabel && onSecondary && (
                <button className={"btn btn-outline-primary w-100 mt-2"} onClick={onSecondary}>
                    {secondaryLabel}
                </button>
            )}
        </div>
    );

    if (!withCard) {
        return content;
    }

    return (
        <div className={"card card-body border-0"}>
            {content}
        </div>
    );
};

export default EvaluationSuccessCard;
