import {calculateAge} from "../date/dateUtils";

export const calculateHeartRateDetails = (selectedClient) => {
    const age = calculateAge(selectedClient?.data_nascimento);
    const gender = selectedClient?.sexo;

    let fcMax = null;

    if (age !== null && gender) {
        if (gender === "m") {
            fcMax = 220 - age;
        } else if (gender === "f") {
            fcMax = 226 - age;
        }
    }

    const faixaMin = fcMax ? Math.round(fcMax * 0.6) : null;
    const faixaMax = fcMax ? Math.round(fcMax * 0.75) : null;
    const limiteMaximo = fcMax ? Math.round(fcMax * 0.9) : null;

    return {age, fcMax, faixaMin, faixaMax, limiteMaximo};
};
