import {useNavigate, useParams} from "react-router-dom";
import React, {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import FrequencyDatePicker from "../../components/frequency-report/FrequencyDatePicker";
import FrequencyTable from "../../components/frequency-report/FrequencyTable";
import {fetchFrequency} from "../../store/frequency-report/frequencyReducer";
import {selectFrequencyData, selectLoading} from "../../store/frequency-report/frequencySelector";
import _ from "lodash";
import Page from "../../components/page/Page";
import Pagination from "../../components/pagination/Pagination";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import 'moment/locale/pt-br';
import Tabs from "../../components/tab/Tabs";
import FrequencyHeader from "../../components/frequency-report/FrequencyHeader";
import {getDateRange} from "../../utils/date/dateRange";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";

const FrequencyReport = () => {
    const {t, i18n} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const frequencyData = useSelector(selectFrequencyData);
    const loading = useSelector(selectLoading);
    const {pg} = useParams();
    const pgParam = pg ?? "1";
    const [page, setPage] = useState(pgParam);
    const [type, setType] = useState(pgParam === "1" ? "workout" : "running");
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(6);
    const [startDate, setStartDate] = useState(null);
    const [endDate, setEndDate] = useState(null);
    const [showCalendar, setShowCalendar] = useState(false);
    const entriesArray = frequencyData?.entries
        ? _.sortBy(Object.entries(frequencyData.entries), [item => -item[1]])
        : [];
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentItems = entriesArray.slice(indexOfFirstItem, indexOfLastItem);
    const totalItems = entriesArray?.length || 0;
    const pagesToShow = 5;
    syncMomentLocale(i18n.language);
    useComponentTranslations('frequencyReport', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleShowCalendar = () => {
        setShowCalendar(prevState => !prevState);
    }

    const handleGoBack = () => {
        navigate("/user");
    }

    const handleSelectDates = (start, end) => {

        setStartDate(start);
        setEndDate(end);
        const selectedType = page === "1" ? "workout" : "running";

        dispatch(fetchFrequency({start, end, type: selectedType}));
    };

    const changePages = (pageName) => {
        setPage(pageName);
        navigate(`/user/frequency-report/${pageName}`);
    };

    useEffect(() => {
        setType(page === "1" ? "workout" : "running");
    }, [page]);

    useEffect(() => {
        const {start, end} = getDateRange({daysBack: 6, inclusive: true});
        setStartDate(start);
        setEndDate(end);
        dispatch(fetchFrequency({start, end, type}));

    }, [dispatch, type]);

    return (
        <>
            <FrequencyHeader title={"Relatório de frequência"} showGoBack={handleGoBack}/>
            <div className={`row justify-content-evenly bg-default m-0`}>
                <div className={'col-12 col-md-6  col-lg-6 col-xl-4 '}>
                    <Tabs page={page}
                          button1Text={"Rotinas de Treino"}
                          button2Text={"Aeróbico"}
                          buttonClick={changePages}
                    />
                </div>
            </div>
            <Page contentHeader={false} mt={"mt-n2"} loading={loading}>
                <div className={"row pt-3"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            <div className={"row justify-content-center d-flex"}>
                                <div className={"col-12 text-center"}>
                                    <button
                                        className={"bg-primary-subtle rounded clickable-element border-0 w-100 p-2 fw-semibold"}
                                        onClick={handleShowCalendar}>
                                        <span>{moment(startDate).format("L")}</span>
                                        <span className={"mx-2"}>-</span>
                                        <span>{moment(endDate).format("L")}</span>
                                    </button>
                                    {
                                        showCalendar &&
                                        <FrequencyDatePicker
                                            show={showCalendar}
                                            onClose={() => setShowCalendar(false)}
                                            onSelectDates={handleSelectDates}
                                            initialStartDate={moment(startDate).format('YYYY-MM-DD')}
                                            initialEndDate={moment(endDate).format('YYYY-MM-DD')}
                                        />
                                    }

                                    {currentItems?.length > 0 ? (
                                        <FrequencyTable
                                            currentItems={currentItems}
                                            totalAmount={frequencyData?.totalAccessAmount || 0}
                                        />
                                    ) : (
                                        currentItems?.length === 0 &&
                                        <div className={"pt-4"}>
                                            <div className={"d-inline-flex"}>
                                                <RoundedIcon icon={"fa-clipboard-check"} size={"lg"} iconClassName={"fa-2xl"}/>
                                            </div>
                                            <br/>
                                            <div className="pt-3">
                                                <span className="fw-semibold text-center">{t("frequencyReport:noAccess")}</span>
                                            </div>
                                        </div>
                                    )}
                                    {
                                        totalItems > itemsPerPage &&
                                        <div className={'row justify-content-center pt-3'}>
                                            <div className={'col-12'}>
                                                <Pagination
                                                    currentPage={currentPage}
                                                    totalItems={totalItems}
                                                    itemsPerPage={itemsPerPage}
                                                    onPageChange={setCurrentPage}
                                                    pagesToShow={pagesToShow}
                                                />
                                            </div>
                                        </div>
                                    }
                                </div>
                            </div>
                        </div>
                    </div>

                </div>
            </Page>
        </>
    )
}

export default FrequencyReport;
