import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {useDispatch, useSelector} from "react-redux";
import {resolveUpdate, respondMyProgressUpdate} from "../../store/updates/updatesReducer";
import {Image} from "react-bootstrap";
import {ErrorMessage, Field, Form, Formik} from "formik";
import {useState} from "react";
import {selectIndividualUpdateLoading} from "../../store/updates/updatesSelector";
import LoadingBlock from "../loader/LoadingBlock";
import 'moment/locale/pt-br';
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {Link} from "react-router-dom";
import he from "he";
import * as Yup from "yup";
import {selectUser} from "../../store/user/userSelector";
import ProgressPhotoPreview from "../client-progress/ProgressPhotoPreview";

const UpdateClientProgress = ({update}) => {
    const {t, i18n} = useTranslation();
    const user = useSelector(selectUser);
    const dispatch = useDispatch();
    const [expanded, setExpanded] = useState(false);
    const loading = useSelector((state) => selectIndividualUpdateLoading(state, update.id));
    syncMomentLocale(i18n.language);
    useComponentTranslations('updateCardComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const sentAt = moment({
        year: update.data?.date?.year,
        month: (update.data?.date?.month || 1) - 1,
        day: update.data?.date?.day,
        hour: update.data?.time?.hour,
        minute: update.data?.time?.minute
    });
    const sentAtLabel = `${sentAt.format('DD/MM/YYYY')} ${sentAt.format('HH:mm')}`;
    const validationSchema = Yup.object().shape({
        response: Yup.string()
            .trim()
            .required(t("updateCardComponent:responseRequired"))
            .max(250, t("updateCardComponent:maxResponseLength")),
    });

    const handleGoToClientClick = `/user/client/${update.aluno.id}`


    const handleAnswerButton = (values) => {
        if (expanded) {
            const payload = {
                id: update.id,
                clientId: update.aluno.id,
                progressId: update.idObjeto,
                formData: values
            }
            dispatch(respondMyProgressUpdate(payload));
        }
        setExpanded(prevState => !prevState)
    }

    const handleResolveUpdateClick = () => {
        dispatch(resolveUpdate(update.id))
    }

    return (
        <div className={'card card-body border-0 mb-2'}>
            <div className={'row'}>
                {
                    loading &&
                    <LoadingBlock height={"300px"}/>
                }
                {
                    !loading &&
                    <>
                        <div className={'col-12 pt-1 pb-1'}>
                            <div className={'row'}>
                                <div className={"col-12"}>
                                    <span className={'fw-semibold '}>{he.decode(update?.aluno?.nome)} {he.decode(update?.aluno?.sobrenome)}</span>
                                </div>
                                <div className={"col-12 small "}>
                                    <span className={"pe-2"}>
                                        <i className={'fa-regular fa-calendar'}></i> {moment({
                                        year: update.data.date.year,
                                        month: update.data.date.month - 1,
                                        day: update.data.date.day
                                    }).format('L')}
                                    </span>
                                    <span>
                                        <i className={'fa-regular fa-clock'}></i> {moment({
                                        hour: update.data.time.hour,
                                        minute: update.data.time.minute
                                    }).format('HH:mm')}
                                    </span>
                                </div>
                            </div>
                            <div className={'row pt-4'}>
                                <div className={"col-12 text-center"}>
                                    <ProgressPhotoPreview
                                        src={update.objeto.url}
                                        alt={he.decode(`${update?.aluno?.nome || ""} ${update?.aluno?.sobrenome || ""}`.trim())}
                                        expandLabel={t("updateCardComponent:expandPhoto")}
                                        minimizeLabel={t("updateCardComponent:minimizePhoto")}
                                        collapsedHeight={154}
                                        expandedHeight={480}
                                        imageClassName={"rounded-1 w-100 h-100"}
                                    />
                                </div>
                                <div className={"col-12 pt-4 ps-4"}>
                                    <div className={"d-flex align-items-start gap-3"}>
                                        <Image
                                            fluid
                                            className={"rounded-circle flex-shrink-0 avatar avatar-md"}
                                            src={update.aluno.profileUrl || "https://cdn.mfitpersonal.com.br/assets/user/user.jpg"}
                                        />
                                        <div className={"flex-grow-1 text-start"}>
                                            <Link
                                                to={handleGoToClientClick}
                                                className={"fw-semibold   text-decoration-none text-default d-inline-block mb-1 lh-sm"}
                                            >
                                                {he.decode(update.aluno.nome)} {he.decode(update.aluno.sobrenome)}
                                            </Link>
                                            <span className={"d-block   lh-base text-default"}>
                                                {he.decode(update.objeto.descricao || "")}
                                            </span>
                                            <span className={"small text-muted d-block mt-2"}>
                                                {sentAtLabel}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            {
                                update.objeto.resposta &&
                                <div className={'row pt-2'}>

                                    <div className={"col-12 pt-4 ps-4"}>
                                        <div className={"d-flex align-items-start gap-3"}>
                                            <Image
                                                fluid
                                                className={"rounded-circle flex-shrink-0 avatar avatar-md"}
                                                src={user.urlLogo || "https://cdn.mfitpersonal.com.br/assets/user/user.jpg"}
                                            />
                                            <div className={"flex-grow-1 text-start"}>
                                                <Link
                                                    to={handleGoToClientClick}
                                                    className={"fw-semibold   text-decoration-none text-default d-inline-block mb-1 lh-sm"}
                                                >
                                                    {he.decode(user.nome)} {he.decode(user.sobrenome)}
                                                </Link>
                                                <span className={"d-block  lh-base text-default"}>
                                                    {he.decode(update.objeto.resposta || "")}
                                                </span>
                                                <span className={"small text-muted d-block mt-2"}>
                                                    {sentAtLabel}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            }

                        </div>
                        {
                            expanded &&
                            <div className={"col-12 pt-4"}>
                                <Formik
                                    initialValues={{response: ''}}
                                    validationSchema={validationSchema}
                                    onSubmit={(values) => {
                                        handleAnswerButton(values);
                                    }}
                                >
                                    {({values}) => (
                                        <Form>
                                            <div className="mb-3">
                                                <label htmlFor="response" className="form-label fw-semibold">{t("updateCardComponent:response")}</label>
                                                <Field
                                                    as="textarea"
                                                    id="response"
                                                    name="response"
                                                    className="form-control"
                                                    rows="5"
                                                    placeholder={t("updateCardComponent:responsePlaceholder")}
                                                />
                                                <ErrorMessage name="response" component="div" className="small text-danger"/>
                                                <div className={"small text-muted text-end mt-1"}>{`${values.response.length}/250`}</div>
                                            </div>
                                            <div className={"d-grid "}>
                                                <button className={"btn btn-primary"} type={"submit"}>{t("updateCardComponent:respond")}</button>
                                            </div>
                                        </Form>
                                    )}
                                </Formik>
                            </div>
                        }
                        {
                            update.status === 0 &&
                            <div className={'col-12 pt-3'}>
                                {
                                    !expanded &&
                                    <div className={'d-grid pt-3'}>
                                        <button className={'btn btn-primary'} onClick={handleAnswerButton}>{t("updateCardComponent:respond")}</button>
                                    </div>
                                }
                                <div className={'d-grid mt-2'}>
                                    <button className={'btn btn-outline-primary'} onClick={handleResolveUpdateClick}>{t("updateCardComponent:resolve")}</button>
                                </div>
                            </div>
                        }
                    </>
                }
            </div>
        </div>
    )
}
export default UpdateClientProgress;
