import {all, call, put, takeLatest} from 'redux-saga/effects';
import {fetchSession, onError, setSession, updatedWorkoutSerie, updateWorkoutSerie} from "./workoutSessionReducer";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {getWorkoutSessionByIdAPI, updateSeriesAPI} from "../../api/workout-session/workoutSessionActions";

export function* fetchWorkoutSessionAsync(action) {
    try {
        const response = yield call(getWorkoutSessionByIdAPI, action.payload)


        yield put(setSession(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchWorkoutSession() {
    yield takeLatest(fetchSession.type, fetchWorkoutSessionAsync);
}

export function* updateSerieWeightAsync(action) {
    try {
        const {id, formData} = action.payload;
        const response = yield call(updateSeriesAPI, formData, id);
        yield put(updatedWorkoutSerie(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateSerieWeight() {
    yield takeLatest(updateWorkoutSerie.type, updateSerieWeightAsync);
}


export function* workoutSessionSaga() {
    yield all([
        call(onFetchWorkoutSession),
        call(onUpdateSerieWeight)
    ])
}