import {selectUser} from "../../store/user/userSelector";
import {useDispatch, useSelector} from "react-redux";
import {useEffect} from "react";
import {fetchUser} from "../../store/user/userReducer";
import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import 'moment/locale/pt-br';
import UserBlockedMessage from "../../components/block/UserBlockedMessage";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useNavigate} from "react-router-dom";
import {handleSubscriptionButton} from "../../utils/handlers/handler";

const NoPayment = () => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const user = useSelector(selectUser);
    const navigate = useNavigate();
    syncMomentLocale(i18n.language);
    useComponentTranslations('block', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        if (!user) {
            dispatch(fetchUser());
        }
    }, [dispatch, user]);

    return (
        <Page showGoBack={false} mt={"mt-n4"}>
            <>
                {
                    (user?.sub.paymentType === 2 || user?.sub.paymentType === 1) &&
                    <UserBlockedMessage
                        icon={"fa-info-circle"}
                        title={t("block:expiredSub")}
                        message={
                            <span>
                                {t("block:expiredSubText1")} <span className={'fw-semibold'}>{moment(user?.venc).format('L')}</span>, {t("block:expiredSubText2")}
                            </span>
                        }
                        buttonText={t("block:checkSubscriptions")}
                        buttonClick={() => handleSubscriptionButton(navigate)}
                    />
                }
                {
                    (user?.sub.paymentType === 0 || user?.sub.paymentType === 3) &&
                    <UserBlockedMessage
                        icon={"fa-info-circle"}

                        title={t("block:failedPayment")}
                        message={
                            <span>{t("block:failedPaymentText1")} <span className={'fw-semibold'}>{moment(user?.venc).format('L')}</span> {t("block:failedPaymentText2")}</span>
                        }
                        buttonText={t("block:updatePaymentMethod")}
                        buttonClick={() => handleSubscriptionButton(navigate)}
                    />
                }
            </>
        </Page>
    )
}
export default NoPayment;