import React, {useEffect} from "react";
import {useNavigate, useParams} from "react-router-dom";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import NeuromotorCard from "../../components/neuromotors/NeuromotorCard";
import {fetchClient} from "../../store/client/clientReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import {
    buildClientEvaluationHomeRoute,
    buildNeuromotorTestRoute
} from "../../utils/client/evaluationRoutes";

const Neuromotors = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {clientId} = useParams();
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    useComponentTranslations('neuromotors', {"en-US":enUS, "es-ES":esES, "pt-PT":ptPT, "pt-BR":ptBR})

    const handleGoBackPage = () => {
        navigate(buildClientEvaluationHomeRoute(clientId));
    }

    useEffect(() => {
        if (!selectedClient)
            dispatch(fetchClient(clientId));
    }, [dispatch, clientId, selectedClient]);

    return (
        <>
            <AvatarHeader showGoBack={handleGoBackPage} className={"pb-4 pt-2"}
                          text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                          url={selectedClient?.profileUrl}  />
            <Page contentHeader={false} loading={loadingClient}>
                <div className={"row"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0 gap-2"}>
                            <span className={"fs-4 fw-semibold"}>{t("neuromotors:neuromotorsFlexibility")}</span>
                            <NeuromotorCard
                                titulo={t("neuromotors:flexibility")}
                                subtitulo={t("neuromotors:wellsBank")}
                                to={buildNeuromotorTestRoute(1, clientId)}
                            />
                            <NeuromotorCard
                                titulo={t("neuromotors:resistance")}
                                subtitulo={t("neuromotors:abdominalArms")}
                                to={buildNeuromotorTestRoute(2, clientId, "1")}
                            />
                            <NeuromotorCard
                                titulo={t("neuromotors:impulse")}
                                subtitulo={t("neuromotors:horizontalVertical")}
                                to={buildNeuromotorTestRoute(4, clientId, "1")}
                            />
                            <NeuromotorCard
                                titulo={t("neuromotors:maximum")}
                                subtitulo={t("neuromotors:maximumRepetition")}
                                to={buildNeuromotorTestRoute(6, clientId)}/>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    )
}

export default Neuromotors;
