import {createSlice} from '@reduxjs/toolkit'

const initialState = {
    loading: false,
    contacts: null,
    contactConverted: false
}

const slice = createSlice({
    name: 'signupLink',
    initialState,
    reducers: {
        convertContactToClient(state){
            state.loading = true
        },
        contactConverted(state, action){
            state.loading = false
            state.contactConverted = action.payload
        },
        deleteAllContacts(state) {
            state.loading = true
        },
        removeContact(state, action) {
            state.loading = false
            state.contacts = state.contacts.filter(c => c.id !== action.payload)
        },
        deleteContact(state) {
            state.loading = true
        },
        fetchContacts(state) {
            state.loading = true
        },
        setContacts(state, action) {
            state.loading = false
            state.contacts = action.payload
        },
        onError(state) {
            state.loading = false
        }
    }
})


export const {fetchContacts, setContacts, deleteContact, deleteAllContacts, removeContact, contactConverted, convertContactToClient, setContactConverted, onError} = slice.actions
export const signupLinkReducer = slice.reducer