import {all, call, put, takeLatest} from 'redux-saga/effects';
import {
    cloneRoutineAPI,
    deleteFolderAPI, deleteRoutineAPI, duplicateRoutineAPI, fetchAllRoutinesAPI,
    fetchFolderByIdAPI,
    fetchFolderListAPI,
    saveFolderAPI,
    updateFolderAPI, updateRoutineFolderAPI
} from "../../api/workout-library/workoutLibrary";
import {
    onError,
    setFoldersList,
    fetchFoldersList,
    updateFolder,
    deleteFolder,
    folderUpdated,
    folderCreated,
    createFolder,
    folderDeleted,
    setCurrentFolder,
    fetchCurrentFolder,
    setRoutineList,
    fetchRoutinesList,
    routineFolderUpdated, updateRoutineFolder, routineDuplicated, duplicateRoutine, routineDeleted, deleteRoutine, routineCloned, cloneRoutine
} from "./workoutLibraryReducer";
import {handleError} from "../../utils/error/sagaErrorHandling";


export function* fetchFoldersListAsync(action) {
    try {
        const response = yield call(fetchFolderListAPI, action.payload)
        yield put(setFoldersList(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchFoldersList() {
    yield takeLatest(fetchFoldersList.type, fetchFoldersListAsync);
}

export function* saveFolderAsync(action) {
    try {
        const response = yield call(saveFolderAPI, action.payload)
        yield put(folderCreated({folder: response.data, payload: true}))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onSaveFolder() {
    yield takeLatest(createFolder.type, saveFolderAsync);
}

export function* updateFolderAsync(action) {
    try {
        yield call(updateFolderAPI, action.payload)
        yield put(folderUpdated({folder: action.payload, payload: true}))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateFolder() {
    yield takeLatest(updateFolder.type, updateFolderAsync);
}

function* deleteFolderAsync(action) {
    try {
        yield call(deleteFolderAPI, action.payload)
        yield put(folderDeleted({folderId: action.payload, payload: true}))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDeleteFolder() {
    yield takeLatest(deleteFolder.type, deleteFolderAsync);
}

export function* fetchCurrentFolderAsync(action) {
    try {
        const {id, type} = action.payload;
        const response = yield call(fetchFolderByIdAPI, id, type)
        yield put(setCurrentFolder(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchCurrentFolder() {
    yield takeLatest(fetchCurrentFolder.type, fetchCurrentFolderAsync);
}

function* fetchAllRoutinesAsync(action) {
    try {
        const response = yield call(fetchAllRoutinesAPI, action.payload)
        yield put(setRoutineList(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchRoutinesList() {
    yield takeLatest(fetchRoutinesList.type, fetchAllRoutinesAsync);
}

export function* updateRoutineFolderAsync(action) {
    try {
        const {folderId, routineId, type} = action.payload;
        yield call(updateRoutineFolderAPI, folderId, routineId, type)
        yield put(routineFolderUpdated(routineId))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateRoutineFolder() {
    yield takeLatest(updateRoutineFolder.type, updateRoutineFolderAsync);
}

export function* duplicateRoutineAsync(action) {
    try {
        const {id, type} = action.payload;
        yield call(duplicateRoutineAPI, id, type)
        yield put(routineDuplicated(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDuplicateRoutine() {
    yield takeLatest(duplicateRoutine.type, duplicateRoutineAsync);
}

export function* deleteRoutineAsync(action) {
    try {
        const {id, type} = action.payload;
        yield call(deleteRoutineAPI, id, type)
        yield put(routineDeleted(id))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDeleteRoutine() {
    yield takeLatest(deleteRoutine.type, deleteRoutineAsync);
}

export function* cloneRoutineAsync(action) {
    try {
        yield call(cloneRoutineAPI, action.payload)
        yield put(routineCloned(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCloneRoutine() {
    yield takeLatest(cloneRoutine.type, cloneRoutineAsync);
}

export function* workoutLibrarySaga() {
    yield all([
        call(onFetchFoldersList),
        call(onSaveFolder),
        call(onUpdateFolder),
        call(onDeleteFolder),
        call(onFetchCurrentFolder),
        call(onFetchRoutinesList),
        call(onUpdateRoutineFolder),
        call(onDuplicateRoutine),
        call(onDeleteRoutine),
        call(onCloneRoutine)
    ])
}