import React, {useEffect, useMemo, useState} from "react";
import Modal from "react-bootstrap/Modal";
import {useDispatch, useSelector} from "react-redux";
import {
    isVo2MaxLoading,
    selectHistoryVo2,
} from "../../store/evaluation/evaluationSelector";
import {fetchHistoryVo2} from "../../store/evaluation/evaluationReducer";
import EmptySet from "../empty-set/EmptySet";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import "moment/locale/pt-br";
import {ModalBody} from "react-bootstrap";
import LoadingBlock from "../loader/LoadingBlock";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const PROTOCOL_COOPER_1970 = 1;
const PROTOCOL_WELTMAN_1989 = 2;

const Vo2HistoryModal = ({show, handleShowVo2History, clientId}) => {
    const dispatch = useDispatch();
    const {t, i18n} = useTranslation();
    const vo2maxHistory = useSelector(selectHistoryVo2);
    const loading = useSelector(isVo2MaxLoading);
    const [selectedType, setSelectedType] = useState(null);
    const [protocolsAvailable, setProtocolsAvailable] = useState(null);
    syncMomentLocale(i18n.language);
    useComponentTranslations('evaluationComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const filteredHistory = useMemo(() => {
        return selectedType !== null
            ? vo2maxHistory.filter((entry) => entry.type === selectedType)
            : null;
    }, [selectedType, vo2maxHistory]);

    useEffect(() => {
        if (show) {
            dispatch(fetchHistoryVo2(clientId));
        }
    }, [dispatch, clientId, show]);

    useEffect(() => {
        if (vo2maxHistory?.length > 0) {
            const protocols = Array.from(
                new Set(vo2maxHistory.map((entry) => entry.type))
            );
            setProtocolsAvailable(protocols);
            if (protocols.length >= 1) {
                setSelectedType(protocols[0]);
            } else {
                setSelectedType(null);
            }
        } else {
            setSelectedType(null);
            setProtocolsAvailable(null);
        }
    }, [vo2maxHistory]);

    return (
        <Modal show={show} onHide={handleShowVo2History} centered>
            <ModalBody>
                <div className={'row justify-content-between'}>
                    <div className={'col-auto'}>
                        <span className="fw-semibold">{t("evaluationComponent:vo2History")}</span>
                    </div>
                </div>
                <div className="row">
                    {
                        protocolsAvailable?.length > 1 &&
                        <div className="mb-3 pt-2">
                            <label htmlFor="type" className="form-label fw-semibold">
                                {t("evaluationComponent:selectProtocol")}:
                            </label>
                            <select
                                name="type"
                                className="form-control"
                                value={selectedType}
                                onChange={(e) => setSelectedType(parseInt(e.target.value, 10))}
                            >
                                {
                                    protocolsAvailable.includes(PROTOCOL_COOPER_1970) &&
                                    <option value={PROTOCOL_COOPER_1970}>Cooper, 1970</option>
                                }
                                {
                                    protocolsAvailable.includes(PROTOCOL_WELTMAN_1989) &&
                                    <option value={PROTOCOL_WELTMAN_1989}>Weltman, 1989</option>
                                }
                            </select>
                        </div>
                    }
                    {
                        loading &&
                        <div className="text-center mt-4">
                            <LoadingBlock/>
                        </div>
                    }
                    {
                        !loading && (protocolsAvailable?.length === 0 || filteredHistory?.length === 0 || !filteredHistory || !protocolsAvailable) &&
                        <div className="text-center">
                            <EmptySet
                                icon={"fa-empty-set"}
                                message={`${t("evaluationComponent:thereIsNoHistory")}`}
                            />
                        </div>
                    }
                    {
                        !loading && filteredHistory &&
                        filteredHistory.map((entry, index) =>
                            <div
                                key={index}
                                className="card card-body border-0 bg-secondary-subtle mx-2 px-2 py-2 my-2"
                            >
                                <div className="d-flex">
                                    <span className="fw-semibold pe-1">{t("evaluationComponent:date")}:</span>
                                    <span>
                                        {moment({
                                            year: entry.createdAt.year,
                                            month: entry.createdAt.month - 1,
                                            day: entry.createdAt.day,
                                        }).format("L")}
                                    </span>
                                </div>
                                {
                                    selectedType === PROTOCOL_COOPER_1970 ?
                                        <div className="d-flex">
                                            <span
                                                className="fw-semibold pe-1">{t("evaluationComponent:distanceInMeters")}:</span>
                                            <span>{entry.distance || 'N/A'}</span>
                                        </div>
                                        :
                                        <div className="d-flex">
                                            <span className="fw-semibold pe-1">{t("evaluationComponent:time")}:</span>
                                            <span>{entry.time || "0"} min</span>
                                        </div>
                                }
                                <div className="d-flex">
                                    <span className="fw-semibold pe-1">{t("evaluationComponent:result")}:</span>
                                    <span>{entry.vo2max} ml/kg/min</span>
                                </div>
                            </div>
                        )
                    }
                </div>
                <div className={"row px-2 pt-2"}>
                    <button className={"btn btn-outline-primary"} onClick={handleShowVo2History}
                            aria-label="Fechar Modal">{t("evaluationComponent:close")}</button>
                </div>
            </ModalBody>
        </Modal>
    );
};

export default Vo2HistoryModal;
