import {Fragment, useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState} from "react"
import {createPortal} from "react-dom"
import {computeGuidedTourLayout, getGuidedTourPopoverMaxWidth} from "./guidedTourLayout"
import {
    getViewportMetrics,
    GUIDED_TOUR_VIEWPORT_GUTTER,
    isConnectedElement,
    isLargeTarget,
    isMobileViewport,
    resolveConnectedTarget
} from "./guidedTourDom"
import useGuidedTourFocusScope from "./useGuidedTourFocusScope"

const MODAL_CARD_MAX_WIDTH = "48rem"
const MODAL_CARD_MAX_HEIGHT = "calc(100vh - 2rem)"
const SHEET_MAX_HEIGHT = "min(56vh, 26rem)"
const DEFAULT_SPOTLIGHT_CARD_HEIGHT = 280

const shouldCorrectivelyScroll = ({layout, targetRect, viewport}) => {
    if (layout.mode === "sheet") {
        return targetRect.top < 56 || targetRect.top > (viewport.height * 0.42)
    }

    return targetRect.top < (viewport.height * 0.18) || targetRect.bottom > (viewport.height * 0.72)
}

const performCorrectiveScroll = ({targetRect, viewport, layoutMode}) => {
    if (typeof window === "undefined") {
        return false
    }

    const currentScrollTop = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0
    const desiredTargetTop = layoutMode === "sheet" ? viewport.height * 0.18 : viewport.height * 0.3
    const nextScrollTop = Math.max(0, currentScrollTop + targetRect.top - desiredTargetTop)

    if (Math.abs(nextScrollTop - currentScrollTop) < 8) {
        return false
    }

    if (typeof window.scrollTo === "function") {
        window.scrollTo({
            top: nextScrollTop,
            behavior: "auto"
        })
    } else {
        document.documentElement.scrollTop = nextScrollTop
    }

    return true
}

const getInitialSpotlightLayout = (step) => {
    const viewport = getViewportMetrics()
    const maxWidth = getGuidedTourPopoverMaxWidth(viewport.width)

    if (isMobileViewport(viewport.width) && step?.mobileBehavior === "sheet") {
        return {
            stepId: step?.id,
            mode: "sheet",
            placement: "bottom",
            maxWidth
        }
    }

    return {
        stepId: step?.id,
        mode: "popover",
        placement: "bottom",
        top: GUIDED_TOUR_VIEWPORT_GUTTER,
        left: GUIDED_TOUR_VIEWPORT_GUTTER,
        maxWidth
    }
}

const GuidedTourCloseButton = ({ariaLabel, onClose}) => (
    <button
        type={"button"}
        className={"btn btn-link text-default p-0 border-0 shadow-none text-decoration-none"}
        aria-label={ariaLabel}
        onClick={onClose}
    >
        <i className={"fa-regular fa-xmark"} aria-hidden={"true"}></i>
    </button>
)

const GuidedTourProgress = ({current, total}) => (
    <div className={"d-inline-flex align-items-center gap-1"}>
        <span className={"text-primary fw-semibold"}>{current}</span>
        <span className={"text-default"}>/</span>
        <span className={"text-default"}>{total}</span>
    </div>
)

const GuidedTourHeader = ({current, total, closeAriaLabel, onClose, compact = false, startAligned = false}) => (
    <div className={`d-flex justify-content-between ${startAligned ? "align-items-start gap-3 mb-3" : `align-items-center ${compact ? "mb-3" : "mb-4"}`}`}>
        {startAligned ? (
            <div>
                <GuidedTourProgress current={current} total={total}/>
            </div>
        ) : (
            <GuidedTourProgress current={current} total={total}/>
        )}
        <GuidedTourCloseButton ariaLabel={closeAriaLabel} onClose={onClose}/>
    </div>
)

const GuidedTourMessage = ({titleId, descriptionId, title, description, titleClassName}) => (
    <Fragment>
        <h2 id={titleId} className={titleClassName}>
            {title}
        </h2>

        <p id={descriptionId} className={"text-default mb-0 lh-base"}>
            {description}
        </p>
    </Fragment>
)

const GuidedTourFooter = ({
    variant,
    isFirstStep,
    isLastStep,
    labels,
    onSkip,
    onPrevious,
    onNext,
    primaryActionRef
}) => {
    const primaryLabel = isLastStep ? labels.done : labels.next

    const renderPrimaryButton = (className) => (
        <button
            ref={primaryActionRef}
            type={"button"}
            className={className}
            onClick={onNext}
        >
            {primaryLabel}
        </button>
    )

    switch (variant) {
        case "modal-mobile":
            return (
                <div className={"mt-5"}>
                    <div className={"d-grid"}>
                        {renderPrimaryButton("btn btn-primary w-100 text-nowrap")}
                    </div>

                    <div className={"text-center mt-3"}>
                        <button type={"button"} className={"btn btn-link text-primary text-nowrap px-0"} onClick={onSkip}>
                            {labels.skip}
                        </button>
                    </div>
                </div>
            )
        case "modal-desktop":
            return (
                <div className={"d-flex align-items-center justify-content-between gap-3 mt-5"}>
                    <button type={"button"} className={"btn btn-link text-primary text-nowrap px-0"} onClick={onSkip}>
                        {labels.skip}
                    </button>

                    <div className={"d-flex align-items-center gap-2 ms-auto flex-shrink-0"} style={{minWidth: 0}}>
                        {!isFirstStep && (
                            <button type={"button"} className={"btn btn-outline-primary px-4 text-nowrap"} onClick={onPrevious}>
                                {labels.previous}
                            </button>
                        )}

                        {renderPrimaryButton(`btn btn-primary ${isFirstStep ? "px-5" : "px-4"} text-nowrap`)}
                    </div>
                </div>
            )
        case "popover-compact":
            return (
                <div className={"mt-4"}>
                    <div className={"row g-2"}>
                        {!isFirstStep && (
                            <div className={"col-6 d-grid"}>
                                <button type={"button"} className={"btn btn-outline-primary w-100 text-nowrap"} onClick={onPrevious}>
                                    {labels.previous}
                                </button>
                            </div>
                        )}
                        <div className={isFirstStep ? "col-12 d-grid" : "col-6 d-grid"}>
                            {renderPrimaryButton("btn btn-primary w-100 text-nowrap")}
                        </div>
                    </div>

                    <div className={"text-center mt-3"}>
                        <button type={"button"} className={"btn btn-link text-primary text-nowrap px-0"} onClick={onSkip}>
                            {labels.skip}
                        </button>
                    </div>
                </div>
            )
        case "sheet":
            return (
                <div className={"mt-4"}>
                    {isFirstStep ? (
                        <div className={"d-grid"}>
                            {renderPrimaryButton("btn btn-primary w-100 text-nowrap")}
                        </div>
                    ) : (
                        <div className={"row g-2"}>
                            <div className={"col-6 d-grid"}>
                                <button type={"button"} className={"btn btn-outline-primary w-100 text-nowrap"} onClick={onPrevious}>
                                    {labels.previous}
                                </button>
                            </div>
                            <div className={"col-6 d-grid"}>
                                {renderPrimaryButton("btn btn-primary w-100 text-nowrap")}
                            </div>
                        </div>
                    )}

                    <div className={"text-center mt-3"}>
                        <button type={"button"} className={"btn btn-link text-primary text-nowrap px-0"} onClick={onSkip}>
                            {labels.skip}
                        </button>
                    </div>
                </div>
            )
        case "popover":
        default:
            return (
                <div className={"d-flex align-items-center justify-content-between gap-2 mt-4"}>
                    <button type={"button"} className={"btn btn-link text-primary text-nowrap px-0"} onClick={onSkip}>
                        {labels.skip}
                    </button>

                    <div className={"d-flex align-items-center gap-2 ms-2 flex-shrink-0"} style={{minWidth: 0}}>
                        {!isFirstStep && (
                            <button type={"button"} className={"btn btn-outline-primary px-3 text-nowrap"} onClick={onPrevious}>
                                {labels.previous}
                            </button>
                        )}

                        {renderPrimaryButton("btn btn-primary px-3 text-nowrap")}
                    </div>
                </div>
            )
    }
}

const GuidedTourCard = ({
    isOpen,
    step,
    current,
    total,
    isFirstStep,
    isLastStep,
    labels,
    onClose,
    onSkip,
    onPrevious,
    onNext,
    activeTarget = null
}) => {
    const titleId = useId()
    const descriptionId = useId()
    const cardRef = useRef(null)
    const primaryActionRef = useRef(null)
    const scrollAdjustmentRef = useRef({
        stepId: null,
        didScroll: false
    })
    const [spotlightLayout, setSpotlightLayout] = useState(null)
    const isModalStep = !step?.target

    const resolvedTarget = useMemo(() => {
        if (isConnectedElement(activeTarget)) {
            return activeTarget
        }

        return resolveConnectedTarget(step?.target)
    }, [activeTarget, step?.target])

    useGuidedTourFocusScope({
        isOpen,
        stepId: step?.id,
        cardRef,
        primaryActionRef,
        targetElement: resolvedTarget,
        allowTargetInteraction: Boolean(step?.allowTargetInteraction)
    })

    const initialSpotlightLayout = useMemo(() => {
        if (isModalStep || !step?.id) {
            return null
        }

        return getInitialSpotlightLayout(step)
    }, [isModalStep, step])

    const activeSpotlightLayout = !isModalStep && spotlightLayout?.stepId === step?.id
        ? spotlightLayout
        : null

    const resolvedLayout = isModalStep
        ? {
            mode: "modal",
            placement: "center"
        }
        : activeSpotlightLayout || initialSpotlightLayout

    const updateSpotlightLayout = useCallback(() => {
        if (isModalStep || !cardRef.current || typeof window === "undefined" || !step?.id) {
            setSpotlightLayout(null)
            return
        }

        const targetElement = isConnectedElement(activeTarget)
            ? activeTarget
            : resolveConnectedTarget(step.target)

        if (!targetElement) {
            setSpotlightLayout(null)
            return
        }

        const viewport = getViewportMetrics()
        const targetRect = targetElement.getBoundingClientRect()
        const maxWidth = getGuidedTourPopoverMaxWidth(viewport.width)
        const cardRect = cardRef.current.getBoundingClientRect()
        const nextLayout = computeGuidedTourLayout({
            step,
            targetRect,
            cardSize: {
                width: Math.min(cardRect.width || maxWidth, maxWidth),
                height: cardRect.height || DEFAULT_SPOTLIGHT_CARD_HEIGHT
            },
            viewport,
            isMobile: isMobileViewport(viewport.width),
            hasLargeTarget: isLargeTarget(targetRect, viewport)
        })

        setSpotlightLayout({
            stepId: step.id,
            ...nextLayout
        })

        const alreadyAdjusted = scrollAdjustmentRef.current.stepId === step.id && scrollAdjustmentRef.current.didScroll

        if (!alreadyAdjusted && shouldCorrectivelyScroll({layout: nextLayout, targetRect, viewport})) {
            const didScroll = performCorrectiveScroll({
                targetRect,
                viewport,
                layoutMode: nextLayout.mode
            })

            scrollAdjustmentRef.current = {
                stepId: step.id,
                didScroll
            }

            if (didScroll) {
                const scheduleFrame = typeof window.requestAnimationFrame === "function"
                    ? window.requestAnimationFrame.bind(window)
                    : (callback) => window.setTimeout(callback, 16)

                scheduleFrame(() => {
                    scheduleFrame(() => {
                        updateSpotlightLayout()
                    })
                })
            }

            return
        }

        scrollAdjustmentRef.current = {
            stepId: step.id,
            didScroll: alreadyAdjusted
        }
    }, [activeTarget, isModalStep, step])

    useEffect(() => {
        scrollAdjustmentRef.current = {
            stepId: step?.id || null,
            didScroll: false
        }
    }, [step?.id])

    useLayoutEffect(() => {
        if (!isOpen || isModalStep || typeof window === "undefined") {
            setSpotlightLayout(null)
            return
        }

        let frameOne = null
        let frameTwo = null

        const scheduleMeasure = () => {
            frameOne = window.requestAnimationFrame(() => {
                frameTwo = window.requestAnimationFrame(() => {
                    updateSpotlightLayout()
                })
            })
        }

        const handleViewportChange = () => {
            updateSpotlightLayout()
        }

        updateSpotlightLayout()
        scheduleMeasure()
        window.addEventListener("resize", handleViewportChange)
        window.addEventListener("scroll", handleViewportChange, true)
        window.visualViewport?.addEventListener?.("resize", handleViewportChange)
        window.visualViewport?.addEventListener?.("scroll", handleViewportChange)

        return () => {
            if (frameOne !== null) {
                window.cancelAnimationFrame(frameOne)
            }

            if (frameTwo !== null) {
                window.cancelAnimationFrame(frameTwo)
            }

            window.removeEventListener("resize", handleViewportChange)
            window.removeEventListener("scroll", handleViewportChange, true)
            window.visualViewport?.removeEventListener?.("resize", handleViewportChange)
            window.visualViewport?.removeEventListener?.("scroll", handleViewportChange)
        }
    }, [isModalStep, isOpen, step?.id, updateSpotlightLayout])

    if (!isOpen || !step || typeof document === "undefined") {
        return null
    }

    const viewportMetrics = getViewportMetrics()
    const isMobileViewportSize = isMobileViewport(viewportMetrics.width)
    const resolvedMode = resolvedLayout?.mode || "modal"
    const resolvedPlacement = resolvedLayout?.placement || "center"
    const isCompactPopover = resolvedMode === "popover" && isMobileViewportSize
    const useStackedModalActions = resolvedMode === "modal" && isMobileViewportSize
    const baseWrapperStyle = {
        zIndex: 10001,
        minWidth: 0,
        overflow: "hidden",
        overflowX: "hidden"
    }

    let wrapperClassName
    let wrapperStyle = {
        ...baseWrapperStyle
    }

    if (resolvedMode === "modal") {
        wrapperClassName = "app-guided-tour position-fixed top-50 start-50 translate-middle card border-0 rounded-4 shadow-sm bg-white"
        wrapperStyle = {
            ...wrapperStyle,
            width: `min(${MODAL_CARD_MAX_WIDTH}, calc(100vw - 2rem))`,
            maxWidth: MODAL_CARD_MAX_WIDTH,
            maxHeight: MODAL_CARD_MAX_HEIGHT
        }
    } else if (resolvedMode === "sheet") {
        wrapperClassName = "app-guided-tour position-fixed start-0 end-0 bottom-0 card border-0 rounded-0 shadow-sm bg-white"
        wrapperStyle = {
            ...wrapperStyle,
            width: "100%",
            maxWidth: "100%",
            maxHeight: SHEET_MAX_HEIGHT
        }
    } else {
        const maxWidth = resolvedLayout?.maxWidth || getGuidedTourPopoverMaxWidth(viewportMetrics.width)

        wrapperClassName = "app-guided-tour position-fixed card border-0 rounded-4 shadow-sm bg-white"
        wrapperStyle = {
            ...wrapperStyle,
            width: `min(${maxWidth}px, calc(100vw - 2rem))`,
            maxWidth: `${maxWidth}px`,
            maxHeight: MODAL_CARD_MAX_HEIGHT,
            top: `${resolvedLayout?.top ?? GUIDED_TOUR_VIEWPORT_GUTTER}px`,
            left: `${resolvedLayout?.left ?? GUIDED_TOUR_VIEWPORT_GUTTER}px`
        }
    }

    const bodyConfig = resolvedMode === "sheet"
        ? {
            bodyClassName: "card-body px-4 pt-3 pb-4",
            maxHeight: SHEET_MAX_HEIGHT,
            titleClassName: "fs-4 fw-semibold text-default-darker mb-2 lh-sm",
            footerVariant: "sheet",
            compactHeader: true,
            headerStartAligned: true
        }
        : resolvedMode === "popover"
            ? {
                bodyClassName: "card-body",
                maxHeight: MODAL_CARD_MAX_HEIGHT,
                titleClassName: "fs-4 fw-semibold text-default-darker mb-2 lh-sm",
                footerVariant: isCompactPopover ? "popover-compact" : "popover",
                compactHeader: true,
                headerStartAligned: false
            }
            : {
                bodyClassName: "card-body",
                maxHeight: MODAL_CARD_MAX_HEIGHT,
                titleClassName: "fs-2 fw-semibold text-default-darker mb-3 lh-sm",
                footerVariant: useStackedModalActions ? "modal-mobile" : "modal-desktop",
                compactHeader: false,
                headerStartAligned: false
            }

    return createPortal(
        <Fragment>
            {resolvedMode === "modal" && (
                <div
                    data-testid={"guided-tour-backdrop"}
                    className={"position-fixed top-0 start-0 w-100 h-100"}
                    style={{
                        backgroundColor: "rgba(0, 0, 0, 0.7)",
                        zIndex: 10000
                    }}
                    onClick={onClose}
                ></div>
            )}

            <div
                ref={cardRef}
                data-testid={"guided-tour-card"}
                data-guided-tour-mode={resolvedMode}
                data-guided-tour-placement={resolvedPlacement}
                className={wrapperClassName}
                style={wrapperStyle}
                role={"dialog"}
                aria-modal={"true"}
                aria-labelledby={titleId}
                aria-describedby={descriptionId}
                tabIndex={-1}
            >
                <div
                    className={bodyConfig.bodyClassName}
                    style={{
                        overflowY: "auto",
                        overflowX: "hidden",
                        maxHeight: bodyConfig.maxHeight
                    }}
                >
                    <GuidedTourHeader
                        current={current}
                        total={total}
                        closeAriaLabel={labels.closeAriaLabel}
                        onClose={onClose}
                        compact={bodyConfig.compactHeader}
                        startAligned={bodyConfig.headerStartAligned}
                    />

                    <GuidedTourMessage
                        titleId={titleId}
                        descriptionId={descriptionId}
                        title={step.title}
                        description={step.description}
                        titleClassName={bodyConfig.titleClassName}
                    />

                    <GuidedTourFooter
                        variant={bodyConfig.footerVariant}
                        isFirstStep={isFirstStep}
                        isLastStep={isLastStep}
                        labels={labels}
                        onSkip={onSkip}
                        onPrevious={onPrevious}
                        onNext={onNext}
                        primaryActionRef={primaryActionRef}
                    />
                </div>
            </div>
        </Fragment>,
        document.body
    )
}

export default GuidedTourCard
