import {handleError} from "../../utils/error/sagaErrorHandling";
import {all, call, put, takeLatest} from 'redux-saga/effects';
import {fetchMonthlyFrequencyAPI, fetchWeeklyFrequencyAPI, fetchYearlyFrequencyAPI} from "../../api/frequency-training/frequencyTrainingActions";
import {
    fetchMonthlyFrequency,
    fetchWeeklyFrequency,
    fetchYearlyFrequency,
    setMonthlyFrequency,
    setWeeklyFrequency,
    setYearlyFrequency,
    onError
} from "./frequencyTrainingReducer";

export function* fetchYearlyFrequencyAsync(action) {
    try {
        const {id, year} = action.payload;
        const response = yield call(fetchYearlyFrequencyAPI, id, year);
        yield put(setYearlyFrequency(response.data))
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchYearlyFrequency() {
    yield takeLatest(fetchYearlyFrequency.type, fetchYearlyFrequencyAsync);
}


export function* fetchMonthlyFrequencyAsync(action){
    try {
        const {id, month, year} = action.payload;
        const response = yield call(fetchMonthlyFrequencyAPI, id, month, year);
        yield put(setMonthlyFrequency(response.data))
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchMonthlyFrequency() {
    yield takeLatest(fetchMonthlyFrequency.type, fetchMonthlyFrequencyAsync);
}

export function* fetchWeeklyFrequencyAsync(action) {
    try {
        const {id, startDate, endDate} = action.payload;
        const response = yield call(fetchWeeklyFrequencyAPI, id, startDate, endDate);
        yield put(setWeeklyFrequency(response.data))
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchWeeklyFrequency() {
    yield takeLatest(fetchWeeklyFrequency.type, fetchWeeklyFrequencyAsync);
}


export function* frequencyTrainingSaga() {
    yield all([
        call(onFetchWeeklyFrequency),
        call(onFetchMonthlyFrequency),
        call(onFetchYearlyFrequency)
    ])
}