import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import MorphologicalListItem from "../../components/morphological/MorphologicalListItem";
import React, {useEffect} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {
    buildClientBioimpedanceRoute,
    buildClientCustomRoute,
    buildClientEvaluationHomeRoute,
    buildClientPhysicalRoute,
    buildOnlineEvaluationsRoute
} from "../../utils/client/evaluationRoutes";

const EvaluationProtocols = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id} = useParams();
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const {t} = useTranslation();
    useComponentTranslations('evaluationProtocols', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBackPage = () => {
        navigate(buildClientEvaluationHomeRoute(id))
    };

    const handleGoBioimpedance = () => {
        navigate(buildClientBioimpedanceRoute(id))
    };

    const handleGoPhysical = () => {
        navigate(buildClientPhysicalRoute(id))
    };

    const handleGoOnline = () => {
        navigate(buildOnlineEvaluationsRoute(id, "1"))
    };

    const handleGoCustom = () => {
        navigate(buildClientCustomRoute(id))
    }

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    return (
        <>
            <AvatarHeader showGoBack={handleGoBackPage} className={"pb-4 pt-2"}
                          text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                          url={selectedClient?.profileUrl} loading={loadingClient}/>
            <Page contentHeader={false}>
                <div className={'row justify-content-center d-flex'}>
                    <div className={"col-12"}>
                        <div className={'card card-body border-0'}>
                            <div className="row justify-content-center d-flex">
                                <div>
                                    <div className={"fw-semibold h5"}>
                                        <span>{t("evaluationProtocols:chooseProtocol")}</span>
                                    </div>
                                </div>
                                <div className={"d-flex flex-column gap-2 pt-2"}>
                                    <MorphologicalListItem
                                        title={t("evaluationProtocols:folds")}
                                        subtitle={t("evaluationProtocols:foldsSubtitle")}
                                        onClick={handleGoPhysical}
                                        icon={"fa-physical-evaluation"}
                                    />
                                    <MorphologicalListItem
                                        title={t("evaluationProtocols:online")}
                                        subtitle={t("evaluationProtocols:onlineSubtitle")}
                                        onClick={handleGoOnline}
                                        icon={"fa-online"}
                                    />
                                    <MorphologicalListItem
                                        title={t("evaluationProtocols:bioimpedance")}
                                        subtitle={t("evaluationProtocols:bioimpedanceSubtitle")}
                                        onClick={handleGoBioimpedance}
                                        icon={"fa-bioimpedance"}
                                    />
                                    <MorphologicalListItem
                                        title={t("evaluationProtocols:custom")}
                                        subtitle={t("evaluationProtocols:customSubtitle")}
                                        onClick={handleGoCustom}
                                        icon={"fa-custom-evaluation"}
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    )
}

export default EvaluationProtocols;
