import {useRef, useState} from "react";
import AiResponseWaiting from "./AiResponseWaiting";
import AiAssistantAnalysis from "./AiAssistantAnalysis";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {truncateContent} from "../../utils/truncatecontent/truncateContent";

const AiAnalysis = ({analysis, isWaiting, onGenerateAnalysis, disclaimer}) => {
    const {t} = useTranslation();
    const messagesEndRef = useRef(null);
    const CHAR_LIMIT = 300;
    const [isExpanded, setIsExpanded] = useState(false);
    const truncatedContent = truncateContent(analysis, isExpanded, CHAR_LIMIT);
    useComponentTranslations('ai', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleExpandedCard = () => {
        setIsExpanded(prevState => !prevState);
    }

    return (
        <>
            <div className={"row justify-content-center pt-2 pb-3"}>
                <div className={"col-auto"}>
                    <i className={"fa-kit fa-mfit-ai  text-mfit-ai-gradient"} style={{fontSize: "2rem"}}/> <span
                    className={"fw-bold text-mfit-ai-gradient"} style={{fontSize: "2rem"}}>MFIT</span> <span
                    className={"fw-light text-mfit-ai-gradient"}
                    style={{fontSize: "2rem"}}>IA</span>
                </div>
            </div>
            <div className={"row"}>
                <div className={"col-12"}>
                    {isWaiting &&
                        <>
                            <AiResponseWaiting/>
                            <br/>
                        </>
                    }
                    {analysis && !isWaiting &&
                        <AiAssistantAnalysis msg={truncatedContent}/>
                    }
                    <div ref={messagesEndRef}/>
                </div>
            </div>
            <div ref={messagesEndRef}/>
            <div className={"row justify-content-center pt-2  "}>
                <div className={"col-auto"}>
                    {!isExpanded &&
                        <button className={"btn btn-link text-mfit-ai fw-semibold"}
                                onClick={handleExpandedCard}>
                            {t("ai:seeMore")}
                        </button>
                    }
                    {isExpanded && (
                        <>
                            <div className={"row "}>
                                <div className={"col-12"}>
                                    <hr className={"mt-0"}/>
                                    <span className={"text-center small d-block text-mfit-ai"}>
                                        {disclaimer}
                                    </span>
                                </div>
                            </div>
                            <div className={"row justify-content-center mt-4"}>
                                <div className={"col-12 text-center"}>
                                    <button
                                        className={"btn btn-sm text-mfit-ai border border-1 border-primary bg-mfit-ai-subtle"}
                                        disabled={isWaiting}
                                        onClick={onGenerateAnalysis}
                                    >
                                        {t("ai:generateWithMfitAi")} <i className={"fa-kit fa-mfit-ai"}/>
                                        <span className={"fw-bold"}>MFIT</span>
                                        <span className={"fw-light"}>IA</span>
                                    </button>
                                </div>
                                <div className={"col-12 text-center mt-3"}>
                                    <button
                                        className="btn btn-link text-mfit-ai fw-semibold" onClick={handleExpandedCard}>
                                        {t("ai:hide")}
                                    </button>
                                </div>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </>
    )
}

export default AiAnalysis;