import {useNavigate} from "react-router-dom";
import ptBR from './locales/pt-br.json';
import enUS from './locales/en-us.json';
import esES from './locales/es-es.json';
import ptPT from './locales/pt-pt.json';
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";

const ContentHeader = ({title, goBackLink, md = "8", lg = "6", xl = "4", showGoBack = true, pb = "pb-4"}) => {
    const navigate = useNavigate();
    const {t} = useTranslation();

    const handleClick = () => {
        if (goBackLink)
            if (typeof goBackLink === 'string') {
                navigate(goBackLink)
            } else {
                goBackLink();
            }
        else
            navigate(-1);
    }
    useComponentTranslations('contHeader', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    return (
        <div className={'content-fluid'}>
            <div className={'bg-default pb-4 text-white pt-sm-4'}>
                {
                    showGoBack ?
                        <div className={'row justify-content-center m-0 d-print-none'}>
                            <div className={`col-12  col-md-${md} col-lg-${lg} col-xl-${xl} ps-3 pb-3`}>
                                    <span className={'small clickable-element'} onClick={handleClick}>
                                        <i className={"fa-regular  fa-chevron-left "}></i>&nbsp;&nbsp;{t("contHeader:goBack")}
                                    </span>
                            </div>
                        </div> :
                        <div className={'pt-3'}></div>
                }
                {
                    title &&
                    <div className={'row justify-content-center m-0 pb-3'}>
                        <div className={`col-12 col-md-${md} col-lg-${lg} col-xl-${xl} ps-3 ${pb}`}>
                            <div className={'row justify-content-between d-flex'}>
                                <div className={`col-'12'}`}>
                                    <span className={'fs-5 fw-semibold'}>{title}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                }
            </div>
        </div>
    )
}
export default ContentHeader;