import {takeLatest, all, call, put} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    createExerciseAPI, createExerciseCategoryAPI, createExerciseGroupAPI, deleteCategoryAPI, deleteExerciseAPI, deleteGroupAPI,
    fetchExerciseCategoriesAPI,
    fetchExerciseFavoritesAPI, fetchExerciseGroupsAPI, fetchUserExerciseAPI, getExerciseAPI,
    removeExerciseAsFavoriteAPI,
    setExerciseAsFavoriteAPI, updateExerciseAPI
} from "../../api/exercise-library/exerciseLibraryActions";
import {
    exerciseRemovedAsFavorite,
    exerciseSetAsFavorite,
    fetchExerciseFavorites,
    removeExerciseAsFavorite,
    setExerciseAsFavorite,
    setExerciseFavorites,
    onError,
    setUserExercises,
    fetchUserExercises,
    setExerciseGroups,
    fetchExerciseGroups,
    setExerciseCategories,
    fetchExerciseCategories,
    createExercise,
    setExercise,
    fetchExercise,
    updateExercise,
    setExerciseAsSaved,
    deleteExercise,
    deleteExerciseSuccess,
    deleteGroupSuccess,
    deleteGroup,
    createGroup, groupCreated, categoryCreated, createCategory, deleteCategorySuccess, deleteCategory
} from "./exerciseLibraryReducer";


export function* fetchExerciseFavoritesAsync() {
    try {
        const response = yield call(fetchExerciseFavoritesAPI)
        yield put(setExerciseFavorites(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* watchFetchExerciseFavorites() {
    yield takeLatest(fetchExerciseFavorites.type, fetchExerciseFavoritesAsync)
}

