export function* exerciseLibrarySaga() {
    yield all([
        call(watchFetchExerciseFavorites),
        call(watchSetExerciseAsFavorite),
        call(watchRemoveExerciseAsFavorite),
        call(watchFetchUserExercise),
        call(watchFetchExerciseGroups),
        call(watchFetchExerciseCategories),
        call(watchCreateExercise),
        call(watchFetchExercise),
        call(watchUpdateExercise),
        call(watchDeleteExercise),
        call(watchDeleteGroup),
        call(watchCreateGroup),
        call(watchCreateCategory),
        call(watchDeleteCategory)
    ])
}
