export const GUIDED_TOUR_VIEWPORT_GUTTER = 16
export const GUIDED_TOUR_MOBILE_BREAKPOINT = 767.98

export const resolveTarget = (target) => {
    if (!target || typeof document === "undefined") {
        return null
    }

    try {
        if (typeof target === "string") {
            return document.querySelector(target)
        }

        if (typeof target === "function") {
            return target()
        }

        return target
    } catch (error) {
        return null
    }
}

export const isConnectedElement = (value) => value instanceof Element && value.isConnected

export const resolveConnectedTarget = (target) => {
    const resolvedTarget = resolveTarget(target)

    return isConnectedElement(resolvedTarget) ? resolvedTarget : null
}

export const getViewportMetrics = () => {
    if (typeof window === "undefined") {
        return {
            width: 1024,
            height: 768
        }
    }

    return {
        width: window.visualViewport?.width || window.innerWidth || 1024,
        height: window.visualViewport?.height || window.innerHeight || 768
    }
}

export const isMobileViewport = (viewportWidth) => viewportWidth <= GUIDED_TOUR_MOBILE_BREAKPOINT

export const isLargeTarget = (targetRect, viewport) => {
    if (!targetRect || !viewport) {
        return false
    }

    return targetRect.height >= (viewport.height * 0.28)
        || targetRect.width >= (viewport.width * 0.82)
}
