import {useCallback, useEffect, useRef} from "react"
import {useSelector} from "react-redux"
import {selectUser} from "../../store/user/userSelector"
import {
    useLazyResolveUserExperiencesQuery,
    useRecordUserExperienceMutation
} from "../../store/user-experience/userExperienceApi"
import {
    applyUserExperienceEventToState,
    isUserExperienceCacheEntryStale,
    readUserExperienceCacheEntry,
    USER_EXPERIENCE_EVENTS,
    writeUserExperienceCacheEntry
} from "../../store/user-experience/userExperienceCache"
import useGuidedTour from "./useGuidedTour"

const usePersistentGuidedTour = ({
    experienceId,
    steps = [],
    isReady,
    labels,
    autoStart = true,
    driverConfig
}) => {
    const user = useSelector(selectUser)
    const userId = user?.id || null
    const [resolveUserExperiences] = useLazyResolveUserExperiencesQuery()
    const [recordUserExperience] = useRecordUserExperienceMutation()
    const autoStartDecisionRef = useRef(false)
    const resolutionRequestRef = useRef(null)

    const tour = useGuidedTour({
        steps,
        isReady: false,
        storageKey: experienceId,
        labels,
        autoStart: false,
        markSeenOnStart: false,
        driverConfig
    })

    const persistLocalState = useCallback((nextState) => {
        if (!userId || !nextState) {
            return nextState
        }

        writeUserExperienceCacheEntry(userId, nextState)
        return nextState
    }, [userId])

    const syncEvent = useCallback((event) => {
        if (!userId || !experienceId) {
            return
        }

        const nextState = persistLocalState(applyUserExperienceEventToState(
            readUserExperienceCacheEntry(userId, experienceId),
            {experienceId, event}
        ))

        recordUserExperience({experienceId, event})
            .unwrap()
            .then((resolvedState) => {
                if (resolvedState) {
                    persistLocalState(resolvedState)
                } else if (nextState) {
                    persistLocalState(nextState)
                }
            })
            .catch(() => undefined)
    }, [experienceId, persistLocalState, recordUserExperience, userId])

    const start = useCallback(() => {
        const didStart = tour.start()

        if (didStart) {
            autoStartDecisionRef.current = true
            syncEvent(USER_EXPERIENCE_EVENTS.STARTED)
        }

        return didStart
    }, [syncEvent, tour])

    const complete = useCallback(() => {
        if (tour.isOpen) {
            syncEvent(USER_EXPERIENCE_EVENTS.COMPLETED)
        }

        tour.complete()
    }, [syncEvent, tour])

    const dismiss = useCallback((closeAction) => {
        if (tour.isOpen) {
            syncEvent(USER_EXPERIENCE_EVENTS.DISMISSED)
        }

        closeAction()
    }, [syncEvent, tour.isOpen])

    const close = useCallback(() => {
        dismiss(tour.close)
    }, [dismiss, tour.close])

    const skip = useCallback(() => {
        dismiss(tour.skip)
    }, [dismiss, tour.skip])

    useEffect(() => {
        autoStartDecisionRef.current = false
        resolutionRequestRef.current = null
    }, [experienceId, userId])

    useEffect(() => {
        if (!autoStart || !isReady || !experienceId || !userId || autoStartDecisionRef.current || tour.hasStarted) {
            return
        }

        const cachedState = readUserExperienceCacheEntry(userId, experienceId)
        const refreshCachedState = () => {
            const request = resolveUserExperiences([experienceId], true)
            resolutionRequestRef.current = request

            request.unwrap()
                .then((resolvedStates) => {
                    const resolvedState = resolvedStates?.[experienceId]
                    if (resolvedState) {
                        persistLocalState(resolvedState)
                    }
                })
                .catch(() => undefined)
                .finally(() => {
                    if (resolutionRequestRef.current === request) {
                        resolutionRequestRef.current = null
                    }
                })
        }

        if (cachedState) {
            autoStartDecisionRef.current = true

            if (isUserExperienceCacheEntryStale(cachedState) && !resolutionRequestRef.current) {
                refreshCachedState()
            }

            return
        }

        const request = resolveUserExperiences([experienceId], true)
        resolutionRequestRef.current = request
        let cancelled = false

        request.unwrap()
            .then((resolvedStates) => {
                if (cancelled) {
                    return
                }

                const resolvedState = resolvedStates?.[experienceId] || null
                autoStartDecisionRef.current = true

                if (resolvedState) {
                    persistLocalState(resolvedState)
                    return
                }

                start()
            })
            .catch(() => {
                if (!cancelled) {
                    autoStartDecisionRef.current = true
                }
            })
            .finally(() => {
                if (resolutionRequestRef.current === request) {
                    resolutionRequestRef.current = null
                }
            })

        return () => {
            cancelled = true
        }
    }, [
        autoStart,
        experienceId,
        isReady,
        persistLocalState,
        resolveUserExperiences,
        start,
        tour.hasStarted,
        userId
    ])

    return {
        ...tour,
        start,
        close,
        skip,
        complete
    }
}

export default usePersistentGuidedTour
