import React, {useCallback, useEffect, useState} from "react";
import {useNavigate, useParams, useSearchParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import Page from "../../components/page/Page";
import {
    fetchExerciseFavorites,
    fetchUserExercises,
} from "../../store/exercise-library/exerciseLibraryReducer";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import ExerciseInstantSearch from "../../components/exercise-library/ExerciseInstantSearch";
import {selectWorkoutExerciseReplaced, selectWorkoutSeriesUpdated, selectWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionSelector";
import {
    addAlternativeExercise,
    addExerciseToSession, createExerciseAsSerie,
    fetchWorkoutSession,
    replaceExercise,
    replaceExerciseSerie,
    setExerciseReplaced, setSerieUpdated, setWorkoutSession
} from "../../store/workout-prescription/workoutPrescriptionReducer";

import WorkoutPrescriptionQuickList from "../../components/workout-prescription/WorkoutPrescriptionQuickList";
import WorkoutPresetPickerOffcanvas from "../../components/workout-preset/WorkoutPresetPickerOffcanvas";
import {
    clearWorkoutPresetEvents,
    createWorkoutPreset,
    fetchWorkoutPresets
} from "../../store/workout-preset/workoutPresetReducer";
import {
    selectLastCreatedWorkoutPreset,
    selectWorkoutPresetLoading,
    selectWorkoutPresets
} from "../../store/workout-preset/workoutPresetSelector";

const PRESET_PICKER_PARAM = "presetPicker";
const PRESET_EXERCISE_PARAM = "presetExercise";

const ExerciseLibrary = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();
    const dispatch = useDispatch();
    const {type, id, sessionId, clientId, idExercSession, serieId, idExercSessionToAdd, idExercMain} = useParams();
    const session = useSelector(selectWorkoutSession)
    const [addedExercises, setAddedExercises] = useState([]);
    const isReplace = idExercSession !== undefined && idExercSession !== "";
    const isSerieReplace = serieId !== undefined && serieId !== "";
    const isAddExerciseAsSerie = idExercSessionToAdd !== undefined && idExercSessionToAdd !== "";
    const isAddAlternative = idExercMain !== undefined && idExercMain !== "";
    const serieUpdated = useSelector(selectWorkoutSeriesUpdated);
    const exerciseReplaced = useSelector(selectWorkoutExerciseReplaced)
    const presets = useSelector(selectWorkoutPresets);
    const presetLoading = useSelector(selectWorkoutPresetLoading);
    const lastCreatedPreset = useSelector(selectLastCreatedWorkoutPreset);
    const [pendingExerciseId, setPendingExerciseId] = useState(null);
    const [showPresetPicker, setShowPresetPicker] = useState(false);
    const [creatingPresetForPendingExercise, setCreatingPresetForPendingExercise] = useState(false);
    useComponentTranslations('exerciseLibrary', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleReplace = (id) => {
        if (isAddExerciseAsSerie) return handleAddExerciseAsSerie(id);
        if (serieId) return handleReplaceSerie(id);
        if (isReplace) return handleReplaceExerc(id);
        if (isAddAlternative) return handleAddAlternative(id);
        return addExercise(id);

    }

    const handleAddAlternative = (id) => {
        const payload = {
            idMainExerc: idExercMain,
            newExerc: id,
            sessionId: sessionId
        }
        dispatch(addAlternativeExercise(payload))
    }


    const handleAddExerciseAsSerie = (id) => {
        const payload = {
            idExercSession: idExercSessionToAdd,
            newExerc: id
        }
        dispatch(createExerciseAsSerie(payload))
    }

    const handleReplaceSerie = (id) => {
        const payload = {
            sessionId: session.id,
            serieId: serieId,
            newExerc: id
        }
        dispatch(replaceExerciseSerie(payload))
    }
    const handleReplaceExerc = (id) => {
        const payload = {
            idExercSession: idExercSession,
            newExerc: id
        }
        dispatch(replaceExercise(payload))
    }

    const addExercise = (id) => {
        if (!sessionId) return;
        const nextSearchParams = new URLSearchParams(searchParams);
        nextSearchParams.set(PRESET_PICKER_PARAM, "1");
        nextSearchParams.set(PRESET_EXERCISE_PARAM, String(id));
        setSearchParams(nextSearchParams);
    };

    const closePresetPicker = useCallback(() => {
        const nextSearchParams = new URLSearchParams(searchParams);
        nextSearchParams.delete(PRESET_PICKER_PARAM);
        nextSearchParams.delete(PRESET_EXERCISE_PARAM);
        setSearchParams(nextSearchParams, {replace: true});
        setCreatingPresetForPendingExercise(false);
        dispatch(clearWorkoutPresetEvents());
    }, [dispatch, searchParams, setSearchParams]);

    const handleAddExerciseWithPreset = useCallback((presetId = null) => {
        if (!pendingExerciseId || !sessionId) return;
        const payload = {
            session: sessionId,
            exercise: pendingExerciseId
        };
        if (presetId) {
            payload.presetId = presetId;
        }
        dispatch(addExerciseToSession(payload));
        closePresetPicker();
    }, [closePresetPicker, dispatch, pendingExerciseId, sessionId]);

    const handleCreatePreset = (payload) => {
        setCreatingPresetForPendingExercise(true);
        dispatch(clearWorkoutPresetEvents());
        dispatch(createWorkoutPreset(payload));
    };

    const handleGoBack = useCallback(() => {
        if (clientId) {
            navigate(`/user/client/${clientId}/workout/routine/${id}/session/${sessionId}/prescribe`);
        } else
            navigate("/user");
    }, [clientId, id, sessionId, navigate]);

    const handleGoToGroups = () => {
        if (session) {
            navigate(`/user/exercise-library/groups/session/${sessionId}`);
        } else
            navigate("/user/exercise-library/groups");
    };

    const handleGoToCategories = () => {
        if (sessionId) {
            navigate(`/user/exercise-library/categories/session/${sessionId}`);

        } else
            navigate("/user/exercise-library/categories");
    };

    const handleGoToCreateExercise = () => {
        if (sessionId) {
            navigate(`/user/exercise-library/create/session/${sessionId}`);
        } else {
            navigate("/user/exercise-library/create");
        }
    };

    useEffect(() => {
        dispatch(fetchUserExercises());
        dispatch(fetchExerciseFavorites());
    }, [dispatch]);

    useEffect(() => {
        if (sessionId)
            dispatch(fetchWorkoutSession(sessionId))
        else dispatch(setWorkoutSession(null))
    }, [sessionId, dispatch]);

    useEffect(() => {
        if (exerciseReplaced) {
            dispatch(setExerciseReplaced(false))
            handleGoBack();
        }
    }, [exerciseReplaced, dispatch, handleGoBack]);

    useEffect(() => {
        if (serieUpdated) {
            dispatch(setSerieUpdated(false))
            handleGoBack();
        }
    }, [serieUpdated, dispatch, handleGoBack]);

    useEffect(() => {
        const shouldOpenPresetPicker = searchParams.get(PRESET_PICKER_PARAM) === "1";
        const exerciseId = Number(searchParams.get(PRESET_EXERCISE_PARAM));

        if (shouldOpenPresetPicker && Number.isFinite(exerciseId) && exerciseId > 0) {
            setPendingExerciseId(exerciseId);
            setShowPresetPicker(true);
            dispatch(fetchWorkoutPresets());
            return;
        }

        setPendingExerciseId(null);
        setShowPresetPicker(false);
    }, [dispatch, searchParams]);

    useEffect(() => {
        if (creatingPresetForPendingExercise && lastCreatedPreset?.id && pendingExerciseId) {
            handleAddExerciseWithPreset(lastCreatedPreset.id);
            setCreatingPresetForPendingExercise(false);
            dispatch(clearWorkoutPresetEvents());
        }
    }, [creatingPresetForPendingExercise, dispatch, handleAddExerciseWithPreset, lastCreatedPreset, pendingExerciseId]);


    useEffect(() => {
        if (session?.exerciciosMontados) {
            const exercisesData = Array.isArray(session.exerciciosMontados)
                ? session.exerciciosMontados
                : Object.values(session.exerciciosMontados);

            const initialExercises = exercisesData.map((exercise, index) => ({
                id: index.toString(),
                exerciseArray: exercise,
            }));
            setAddedExercises(initialExercises);

        }
    }, [session?.exerciciosMontados]);

    return (
        <Page title={t("exerciseLibrary:libraryTitle")} goBackLink={handleGoBack} pb={"pb-2"}>
            <div className="row justify-content-center">
                <div className="col-12">
                    <div className={"card card-body border-0  "}>
                        {
                            (!session || !isReplace) &&
                            <>
                                <div className={'row justify-content-center  '}>
                                    <div className={"col-12"}>
                                        <CardButtonAdd text={t("exerciseLibrary:createExercise")} handleClick={handleGoToCreateExercise}/>
                                    </div>
                                    <div className={"col-6 mt-2 pe-1"}>
                                        <div className={"d-grid"}>
                                            <button className={"btn btn-primary-subtle text-primary"}
                                                    onClick={handleGoToGroups}> {t("exerciseLibrary:muscleGroups")}</button>
                                        </div>
                                    </div>
                                    <div className={"col-6 mt-2  ps-1"}>
                                        <div className={"d-grid"}>
                                            <button className={"btn btn-primary-subtle text-primary"}
                                                    onClick={handleGoToCategories}> {t("exerciseLibrary:categories")}</button>
                                        </div>
                                    </div>
                                </div>
                                <hr className={"mt-3 mb-3 border-primary-subtle"}/>
                            </>
                        }
                        <ExerciseInstantSearch type={type}
                                               isReplace={isReplace}
                                               isSerieReplace={isSerieReplace}
                                               handleReplace={handleReplace}
                                               addedExercises={addedExercises}/>
                    </div>
                </div>
            </div>
            {
                session && !isReplace && !isSerieReplace && !isAddExerciseAsSerie &&
                <WorkoutPrescriptionQuickList addedExercises={addedExercises} sessionId={session.id}/>
            }
            <WorkoutPresetPickerOffcanvas
                show={showPresetPicker}
                onHide={closePresetPicker}
                presets={presets}
                loading={presetLoading}
                onSelectPreset={(preset) => handleAddExerciseWithPreset(preset.id)}
                onAddWithoutPreset={() => handleAddExerciseWithPreset()}
                onCreatePreset={handleCreatePreset}
            />
        </Page>
    );
};

export default ExerciseLibrary;
