import Avatar from "./Avatar";
import he from "he";
const AvatarHeader = ({avatarClick, url, text, className, showGoBack, xs = "12", md = "6", lg = "6", xl = "4", children}) => {


    return (
        <div className={`row justify-content-center  bg-default text-white  pt-1 ms-0 me-0   ${className}`}>
            {
                showGoBack &&
                <div className={`col-${xs} col-md-${md} col-lg-${lg} col-xl-${xl} pb-2 ps-4`}>
                        <span className={'small clickable-element'} onClick={showGoBack}>
                            <i className={"fa-regular  fa-chevron-left "}></i>&nbsp;&nbsp;Voltar
                        </span>
                </div>
            }
            <div className={`col-12 ${className}`}>
                <div className={'row justify-content-center'}>
                    <div className={`col-${xs} col-md-${md} col-lg-${lg} col-xl-${xl}`}>
                        <div className={'row '}>
                            <div className={'col-2 col-md-auto  clickable-element align-self-center '} onClick={avatarClick}>
                                <Avatar url={url}/>
                            </div>
                            <div className={'col-10 col-md-auto  align-self-center ps-lg-0'}>
                                <div className={'row '}>
                                    <div className={'col-12 mb-2'}>
                                        <span className={'fs-5 d-block lh-1'}>{text !== "undefined undefined" && he.decode(text)}</span>
                                    </div>
                                    {children}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default AvatarHeader;