import WorkoutPrescriptionExerciseCard from "./WorkoutPrescriptionExerciseCard";
import React, {useState} from "react";

const WorkoutPrescriptionExerciseListItem = ({exerciseArray, expanded, onToggleExpand, exercises, selected, toggleSelect, deselect}) => {
    const [position, setPosition] = useState(0);

    const handleNextExercise = () => {
        setPosition((prev) => (prev + 1) % exerciseArray.length);
    }

    const handlePreviousExercise = () => {
        setPosition((prev) => (prev - 1 + exerciseArray.length) % exerciseArray.length);
    }
    return (
        <>
            {
                exerciseArray.length > 1 &&
                <WorkoutPrescriptionExerciseCard
                    key={exerciseArray[position].idExercSession}
                    mainExerc={exerciseArray[0].idExercSession}
                    ex={exerciseArray[position]}
                    expand={expanded}
                    onToggleExpand={onToggleExpand}
                    exercises={exercises}
                    handleNextExercise={handleNextExercise}
                    handlePreviousExercise={handlePreviousExercise}
                    showPrevious={position > 0}
                    showNext={position < exerciseArray.length - 1}
                    hasAlternative={true}
                    selected={selected}
                    toggleSelect={toggleSelect}
                    deselect={deselect}
                />
            }
            {
                exerciseArray.length === 1 && exerciseArray.map((ex) => (
                    <WorkoutPrescriptionExerciseCard
                        selected={selected}
                        toggleSelect={toggleSelect}
                        deselect={deselect}
                        ex={ex} key={ex.id}
                        mainExerc={ex.idExercSession}
                        exercises={exercises}
                        expand={expanded}
                        onToggleExpand={onToggleExpand}/>
                ))
            }
        </>
    )
}

export default WorkoutPrescriptionExerciseListItem;
