import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    balance: null,
    seller: null,
    walletRequest: null,
    walletRequestLoading: null,
    sellerLoading: null,
    balanceLoading: null,
    loading: false
}

export const slice = createSlice({
    name: "wallet",
    initialState,
    reducers: {
        fetchWalletRequest(state) {
            state.walletRequestLoading = true;
        },
        setWalletRequest(state, action) {
            state.walletRequest = action.payload;
            state.walletRequestLoading = false;
        },
        fetchSeller(state) {
            state.sellerLoading = true;
        },
        setSeller(state, action) {
            state.seller = action.payload;
            state.sellerLoading = false;
        },
        fetchBalance(state) {
            state.balanceLoading = true
        },
        setBalance(state, action) {
            state.balance = action.payload
            state.balanceLoading = false
        },
        onError(state) {
            state.balanceLoading = false
            state.walletRequestLoading = false
            state.loading = false
        }
    }
})

export const {setBalance, fetchBalance, fetchSeller, setSeller, fetchWalletRequest, setWalletRequest, onError} = slice.actions;
export const walletReducer = slice.reducer;