import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import Spinner from "../loader/Spinner";
import {useSelector} from "react-redux";
import {selectBalance} from "../../store/wallet/walletSelector";
import {handleWithdrawClick} from "../../utils/handlers/handler";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WalletActiveCard = ({loading, handleGoToWallet}) => {
    const {t} = useTranslation();
    const balance = useSelector(selectBalance)
    useComponentTranslations('wallet', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    return (
        <>
            <div className={'card card-body bg-primary-darker'}>
                {
                    !loading && balance ?
                        <div className={'row text-white '}>
                            <div className={'col-12 text-center fw-semibold'}>
                                <i className={'fa-regular fa-coins'}></i> <span
                                className={'fw-semibold'}>{t("wallet:balance")}</span>
                            </div>
                            <div className={'col-12 text-center'}>
                                <span className={'fw-bold '} style={{fontSize: "2.5rem"}}><CurrencyFormatter
                                    value={balance.current_balance}/>
                                </span>
                            </div>
                            {
                                balance.account_balance > 0 &&
                                <div className={'col-12 text-center'}>
                                    <span className={'text-warning fw-bold'}>{t("wallet:youHave")} <CurrencyFormatter
                                        value={balance.account_balance}/> {t("wallet:pending")}</span>
                                </div>
                            }
                        </div> :
                        <Spinner width={"25px"} height={"25px"}/>
                }
            </div>
            <div className={'col-12 pt-2'}>
                {
                    balance && balance.current_balance > 0 &&
                    <div className={'d-grid'}>
                        <button className={'btn btn-primary-lighter'} onClick={handleWithdrawClick}>{t("wallet:withdraw")}</button>
                    </div>
                }
                <div className={'d-grid pt-2'}>
                    <button className={'btn btn-outline-primary-darker'} onClick={handleGoToWallet}>{t("wallet:goToWallet")}
                    </button>
                </div>
            </div>
        </>
    )
}
export default WalletActiveCard;