import {createSelector} from "reselect";

const reducer = state => state.evaluationOnline;

export const getOnlineList = createSelector([reducer], slice => slice.onlineList);

export const getLoading = createSelector([reducer], slice => slice.initialLoading);

export const getFrequencyLoading = createSelector([reducer], slice => slice.frequencyLoading);

export const getSubmitLoading = createSelector([reducer], slice => slice.submitLoading);

export const getSubmitResult = createSelector([reducer], slice => slice.submitResult);

export const getEvaluation = createSelector([reducer], slice => slice.evaluation);

export const getScheduledEvaluations = createSelector([reducer], slice => slice.scheduledEvaluations);

export const getLastEvaluation = createSelector([reducer], slice => slice.lastEvaluation);

export const getLastEvaluationClientId = createSelector([reducer], slice => slice.lastEvaluationClientId);

export const getCompareEvaluationList = createSelector([reducer], slice => slice.compareList);
