import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect, useState} from "react";
import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {fetchClient} from "../../store/client/clientReducer";
import {useNavigate, useParams} from "react-router-dom";
import {
    selectWorkoutRoutine,
    selectWorkoutRoutineChangingStatus,
    selectWorkoutRoutineDeleted,
    selectWorkoutRoutineLoading
} from "../../store/workout-routine/workoutRoutineSelector";
import {changeRoutineDeletedStatus, changeWorkoutRoutineStatus, fetchWorkoutRoutine} from "../../store/workout-routine/workoutRoutineReducer";
import WorkoutIcon from "../../components/rounded-icon/WorkoutIcon";
import Text from "../../components/utils/emoji/Text";
import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {getDifficulty, getObjective} from "../../utils/workout/Workout";
import LoadingBlock from "../../components/loader/LoadingBlock";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import Modal from "react-bootstrap/Modal";
import ChangeStatus from "../../components/utils/change-status/ChangeStatus";
import WorkoutSessionCreateForm from "../../components/workout-routine/WorkoutSessionCreateForm";
import {useTranslation} from "react-i18next";
import WorkoutSessionDraggableList from "../../components/workout-routine/WorkoutSessionDraggableList";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {Dropdown} from "react-bootstrap";

const WorkoutRoutineView = () => {
        const {t, i18n} = useTranslation()
        const dispatch = useDispatch();
        const navigate = useNavigate();
        const {clientId, id, goBackTo} = useParams();
        const client = useSelector(selectSelectedClient);
        const workout = useSelector(selectWorkoutRoutine);
        const workoutLoading = useSelector(selectWorkoutRoutineLoading);
        const [showFullDescription, setShowFullDescription] = useState(false);
        const [showDeleteModal, setShowDeleteModal] = useState(false);
        const isRoutineStatusChanging = useSelector(selectWorkoutRoutineChangingStatus)
        const isRoutineDeleted = useSelector(selectWorkoutRoutineDeleted)
        const [showAddSession, setShowAddSession] = useState(false);
        const isLibrary = Number(clientId) === 0;
        const backToUpdates = goBackTo === "updates";
        const backToArchived = goBackTo === "archived";
        const [dragDisabled, setDragDisabled] = useState(true);
        useComponentTranslations('workoutRoutine', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

        syncMomentLocale(i18n.language);

        const handleEnableDragging = () => {
            setDragDisabled(prevState => !prevState)
        }

        const handleAddSession = () => {
            setShowAddSession(prevState => !prevState)
        }

        const handleShowFullDescription = () => {
            setShowFullDescription(prevState => !prevState)
        }

        const handleShowDeleteModal = () => {
            setShowDeleteModal(prevState => !prevState)
        }

        const handleChangeWorkoutStatus = () => {
            dispatch(changeWorkoutRoutineStatus({id: workout.id, status: 3}))
        }
        const handleGoBack = () => {
            if (backToUpdates) {
                navigate(`/user/update/list/1`);
            } else if (backToArchived) {
                navigate(`/user/client/${client?.id || 0}/workout/secondary/status/1/type/0`);
            } else if (isLibrary)
                navigate(`/user/workout-library`);
            else
                navigate(`/user/client/${client?.id || 0}/workout`);

        };

        const handleEditRoutine = () => {
            navigate(`/user/client/${client?.id || 0}/workout/routine/${workout.id}/update`);
        }

        useEffect(() => {
            if (isRoutineDeleted) {
                dispatch(changeRoutineDeletedStatus(false))
                navigate(`/user/client/${client?.id}/workout`)
            }
        }, [isRoutineDeleted, dispatch, navigate, client])

        useEffect(() => {
            dispatch(fetchWorkoutRoutine(id));
        }, [dispatch, id]);

        useEffect(() => {
            if (Number(clientId) > 0)
                dispatch(fetchClient(clientId));
        }, [dispatch, clientId]);

        if (!workout) {
            return <LoadingBlock/>;
        }

        return (
            <>
                {
                    !isLibrary &&
                    <AvatarHeader className={"pb-4 pt-2"}
                                  text={`${client?.nome} ${client?.sobrenome}`}
                                  url={client?.profileUrl} showGoBack={handleGoBack}/>
                }
                <Page contentHeader={isLibrary} loading={workoutLoading} goBackLink={handleGoBack}>
                    <div className={"row justify-content-center mt-3"}>
                        <div className="col-12">
                            <div className="card card-body border-0">
                                <div className="row d-flex justify-content-between">
                                    <div className="col-2 col-md-3 col-lg-2 text-center align-self-center ">
                                        <WorkoutIcon obj={workout.objetivo} gender={client?.sexo}/>
                                    </div>
                                    <div className="col-7 col-md-8 col-lg-8 align-self-center ps-0 ps-lg-1 ">
                                        <span className="fw-semibold d-block">
                                            <Text>{workout.nome}</Text>
                                        </span>
                                        {
                                            !isLibrary &&
                                            <span className="d-block text-md">
                                            <i className="fa-regular fa-calendar-lines "></i>&nbsp;&nbsp;
                                                {moment(workout.dataInicio).format("L")} - {moment(workout.dataFim).format("L")}
                                        </span>
                                        }
                                        <div className="row justify-content-center d-flex mt-1">
                                            <div className="col-12">
                                                <div className="row d-flex text-muted small">
                                                    <div className="col-auto">
                                                        {t(`workoutRoutine:${getObjective(workout.objetivo)}`)} | {t(`workoutRoutine:${getDifficulty(workout.dificuldade)}`)}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="col-2 align-self-center clickable-element text-center">
                                        <Dropdown align={"end"}>
                                            <Dropdown.Toggle
                                                as={"button"}
                                                className={"btn btn-link border-0 text-dark p-1 dropdown-toggle-no-caret"}
                                                aria-label={"Opções do treino"}
                                            >
                                                <i className={"fa-regular fa-ellipsis-vertical"}></i>
                                            </Dropdown.Toggle>
                                            <Dropdown.Menu>
                                                <Dropdown.Item
                                                    className="text-dark  dropdown-toggle-no-caret"
                                                    onClick={handleEditRoutine}
                                                >
                                                    <i className="fa-regular fa-pen-to-square me-2"/> {t("workoutRoutine:editWorkout")}
                                                </Dropdown.Item>
                                                <Dropdown.Divider/>
                                                <Dropdown.Item
                                                    className="text-danger dropdown-toggle-no-caret"
                                                    onClick={handleShowDeleteModal}
                                                >
                                                    <i className="fa-regular fa-trash-can me-2"/> {t("workoutRoutine:deleteWorkout")}
                                                </Dropdown.Item>
                                            </Dropdown.Menu>
                                        </Dropdown>
                                    </div>
                                    <Modal show={showDeleteModal} centered onHide={handleShowDeleteModal}>
                                        <Modal.Body>
                                            <ChangeStatus
                                                icon={"fa-regular fa-circle-exclamation"}
                                                iconColor={"text-danger"}
                                                title={t("workoutRoutine:deleteConfirmationMessage")}
                                            />
                                            <div className="row mt-3 justify-content-center">
                                                <div className="col-12">
                                                    <div className="d-grid">
                                                        <button className="btn btn-danger" disabled={isRoutineStatusChanging} onClick={handleChangeWorkoutStatus}>
                                                            {t("workoutRoutine:delete")}
                                                        </button>
                                                    </div>
                                                    <div className="d-grid mt-2">
                                                        <button className="btn btn-outline-danger" onClick={handleShowDeleteModal}>
                                                            {t("workoutRoutine:close")}
                                                        </button>
                                                    </div>
                                                </div>
                                            </div>
                                        </Modal.Body>
                                    </Modal>
                                </div>
                                <hr className="border-primary-subtle"/>
                                <div className="row d-flex">
                                    <div className="col-12">
                                        <span className="d-block fw-semibold">{t("workoutRoutine:workoutTypeLabel")}</span>
                                        <span className="fw-light">
                                        {workout.diaTipo === 1 ? t("workoutRoutine:weekDay") : t("workoutRoutine:numeric")}
                                    </span>
                                    </div>
                                    <div className="col-12 mt-2">
                                        <span className="d-block fw-semibold">{t("workoutRoutine:showClient")}</span>
                                        <span className="fw-light">
                                        {workout.mostrarNoInicio ? t("workoutRoutine:showAtStartDate") : t("workoutRoutine:always")}
                                    </span>
                                    </div>
                                    <div className="col-12 mt-2">
                                        <span className="d-block fw-semibold">{t("workoutRoutine:automaticallyArchive")}</span>
                                        <span className="fw-light">{workout.arquivar ? t("workoutRoutine:yes") : t("workoutRoutine:no")}</span>
                                    </div>
                                    {
                                        workout.descricao &&
                                        <div className="col-12 mt-2">
                                            <div className={"card card-body border-0 bg-secondary-subtle py-2"}>
                                                <div className={"row justify-content-between"}>
                                                    <div className={"col-auto fw-semibold  clickable-element"} onClick={handleShowFullDescription}>
                                                        {t("workoutRoutine:generalInstructions")}
                                                    </div>
                                                    <div className={"col-auto  clickable-element"} onClick={handleShowFullDescription}>
                                                        <i className={`fa-regular  ${!showFullDescription ? "fa-eye" : "fa-eye-slash"}`}></i>
                                                    </div>
                                                    {
                                                        showFullDescription &&
                                                        <div className={"col-12 mt-3"}>
                                                            <pre><Text>{workout.descricao}</Text></pre>
                                                        </div>
                                                    }
                                                </div>
                                            </div>
                                        </div>
                                    }

                                </div>
                            </div>
                            {workout.sessions?.length > 0 &&
                                <div className="row  mt-3  justify-content-evenly">
                                    <div className={"col-6  pe-1"}>
                                        {
                                            dragDisabled &&
                                            <button className={"btn btn-outline-primary w-100"} onClick={handleEnableDragging}>
                                                <i className={"fa-solid fa-sort"}></i> {t("workoutRoutine:reorderWorkout")}
                                            </button>
                                        }
                                        {
                                            !dragDisabled &&
                                            <button className={"btn btn-outline-success   w-100"} onClick={handleEnableDragging}>
                                                {t("workoutRoutine:reorderWorkoutFinalize")}
                                            </button>
                                        }
                                    </div>
                                    <div className={"col-6 ps-1 "}>
                                        <button className={"btn btn-primary w-100"} onClick={handleAddSession}>
                                            <i className={"fa-regular fa-plus"}></i> {t("workoutRoutine:addWorkout")}
                                        </button>
                                    </div>
                                </div>
                            }
                            {workout.sessions?.length > 0 &&
                                <div className="row d-flex mt-3">
                                    {
                                        !dragDisabled &&
                                        <div className={"col-12 text-center"}>
                                            <span className={"fst-italic text-default-lighter"}>{t("workoutRoutine:dragToOrder")}</span>
                                        </div>
                                    }

                                    <div className={"col-12 mt-2"}>
                                        <WorkoutSessionDraggableList dragDisabled={dragDisabled}
                                                                     onEditToggle={setDragDisabled}
                                                                     workout={workout} isLibrary={isLibrary}/>
                                    </div>
                                </div>
                            }
                            {workout.sessions?.length === 0 &&
                                <div className="row d-flex mt-3">
                                    <div className={"col-12"}>
                                        <div className={'card card-body border-0'}>
                                            <div className={'row justify-content-center mt-3'}>
                                                <div className={'col-12 text-center '}>
                                                    <RoundedIcon icon={"fa-dumbbell"} size={"xl"}/>
                                                </div>
                                                <div className={'col-11 col-md-8 text-center mt-3'}>
                                                    <span className={"fs-5 fw-semibold"}>
                                                       {t("workoutRoutine:noWorkout")}
                                                    </span>
                                                </div>
                                                <div className={"col-12 col-md-8 mt-4"}>
                                                    <div className={"d-grid"}>
                                                        <button className={"btn btn-primary"}
                                                                onClick={handleAddSession}>{t("workoutRoutine:addFirstWorkout")}</button>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            }
                            <Modal show={showAddSession} centered onHide={handleAddSession}>
                                <Modal.Body>
                                    <div className={"row justify-content-center"}>
                                        <div className={"col-12"}>
                                            <WorkoutSessionCreateForm workout={workout} onClose={handleAddSession}/>
                                        </div>
                                    </div>
                                </Modal.Body>
                            </Modal>
                        </div>
                    </div>
                </Page>
            </>
        );
    }
;

export default WorkoutRoutineView;
