    setLoadingSubChange,
    changeUserSubscriptionToFreePlan, walletPaymentStart,
    createCreditCardError, createCreditCardSuccess,
    createCreditCard, deleteCreditCard,
    removeCreditCardFromTheList, createPixTransaction, createCardTransaction, cancelSubscription, cancelSubscriptionSuccess, subActivated, activateSub,
    setChangedPaymentMethod, changePaymentMethod, setPaymentMethod, fetchPaymentMethod, changeUserToMonthlyPlan
