export function* fetchBuyerAsync(action) {
    try {
        const response = yield call(fetchBuyerAPI, action.payload)
        yield put(setBuyer(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchBuyer() {
    yield takeLatest(fetchBuyer.type, fetchBuyerAsync)
}

