export function* createCreditCardAsync(action) {
    try {
        const response = yield call(createCreditCardAPI, action.payload)
        yield put(createCreditCardSuccess(response.data))
    } catch (error) {
        if (error.response.status >= 400 && error.response.status < 500) {
            console.log(error.response.data.error)
            yield put(createCreditCardError(error.response.data.error))
        } else
            yield call(handleError, error, onError)
    }
}

export function* onCreateCreditCard() {
    yield takeLatest(createCreditCard.type, createCreditCardAsync)
}

