export function* createCardTransactionAsync(action) {
    try {
        const response = yield call(creditCardPurchaseAPI, action.payload)
        yield put(setTransaction(response.data))
    } catch (error) {
        if (error.response.status >= 400 && error.response.status < 500 && error.response.status !== 429) {
            if (error?.response?.data?.error?.category === "resource_not_found") {
                yield put(createCreditCardError(error.response.data))
            } else
                yield put(setTransaction(error.response.data))
        } else
            yield call(handleError, error, onError)
    }
}

export function* onCreateCardTransaction() {
    yield takeLatest(createCardTransaction.type, createCardTransactionAsync)
}

