export function* subscriptionSaga() {
    yield all([
        call(onFetchBuyer),
        call(onSelectSubPlan),
        call(onSaveBuyerInformation),
        call(onFetchSubPlanList),
        call(onCreateBuyer),
        call(onFetchAllCreditCards),
        call(onCheckCoupon),
        call(onCreatePixTransaction),
        call(onFetchTransactions),
        call(onChangeSubToFreePlan),
        call(onWalletPayment),
        call(onCreateCreditCard),
        call(onDeleteCreditCard),
        call(onCreateCardTransaction),
        call(onCancelSubscription),
        call(onActivateSub),
        call(onChangePaymentMethod),
        call(onFetchPaymentMethod),
        call(onChangeUserToMonthlyPlan)
    ])
}