import {useEffect, useMemo, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {Trans, useTranslation} from "react-i18next";
import {useNavigate, useParams} from "react-router-dom";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import PushComposeOffcanvas from "../../components/push/PushComposeOffcanvas";
import DeleteModal from "../../components/modal/DeleteModal";
import ClientProgressCard from "../../components/client-progress/ClientProgressCard";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import decodeHtmlEntities from "../../utils/text/decodeHtmlEntities";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import {fetchClient} from "../../store/client/clientReducer";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {
    deleteClientProgress,
    fetchClientProgressList,
    respondClientProgress
} from "../../store/client-progress/clientProgressReducer";
import {
    selectClientProgressList,
    selectClientProgressListErrorCode,
    selectClientProgressListStatus
} from "../../store/client-progress/clientProgressSelector";
import {addToast} from "../../store/toast/toastReducer";

const ClientProgress = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t, i18n} = useTranslation();
    const {clientId} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const progressList = useSelector(selectClientProgressList);
    const listStatus = useSelector(selectClientProgressListStatus);
    const listErrorCode = useSelector(selectClientProgressListErrorCode);

    const [selectedProgress, setSelectedProgress] = useState(null);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [showReminderModal, setShowReminderModal] = useState(false);

    const translationsLoaded = useComponentTranslations("clientProgressUser", {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR});

    useEffect(() => {
        dispatch(fetchClient(clientId));
        dispatch(fetchClientProgressList(clientId));
    }, [clientId, dispatch]);

    const emptyStateBenefits = [
        {icon: "fa-regular fa-camera", text: t("clientProgressUser:emptyBenefitPhotos")},
        {icon: "fa-regular fa-chart-line-up", text: t("clientProgressUser:emptyBenefitTrack")},
        {icon: "fa-regular fa-arrows-rotate", text: t("clientProgressUser:emptyBenefitCompare")},
        {icon: "fa-regular fa-bolt", text: t("clientProgressUser:emptyBenefitMotivate")}
    ];
    const selectedClientLabel = selectedClient
        ? decodeHtmlEntities(`${selectedClient.nome || ""} ${selectedClient.sobrenome || ""}`.trim())
        : (translationsLoaded ? t("clientProgressUser:selectedClient") : "");
    const lockedAudience = useMemo(() => ({
        sendTo: "clients",
        selectOption: [Number(clientId)],
        summaryLabel: selectedClientLabel,
        summaryCount: 1,
        countLabel: translationsLoaded ? t("clientProgressUser:selectedRecipientCount", {count: 1}) : ""
    }), [clientId, selectedClientLabel, t, translationsLoaded]);
    const reminderInitialValues = useMemo(() => ({
        title: translationsLoaded ? t("clientProgressUser:reminderTitle") : "",
        message: translationsLoaded ? t("clientProgressUser:reminderMessage") : ""
    }), [t, translationsLoaded]);
    const loading = listStatus === "idle" || listStatus === "loading";
    const showEmptyState = listStatus === "success" && progressList.length === 0;
    const showList = listStatus === "success" && progressList.length > 0;
    const showListError = listStatus === "error";
    const listErrorMessage = t(`clientProgressUser:errorMessages.${listErrorCode}`, {
        defaultValue: t("clientProgressUser:listLoadErrorText")
    });

    const handleGoBackPage = () => navigate(`/user/client/${clientId}`);
    const handleRetryList = () => dispatch(fetchClientProgressList(clientId));
    const handleOpenDeleteModal = (progress) => {
        setSelectedProgress(progress);
        setShowDeleteModal(true);
    };
    const handleCloseDeleteModal = () => {
        setShowDeleteModal(false);
        setSelectedProgress(null);
    };
    const handleConfirmDelete = () => {
        if (!selectedProgress) {
            return;
        }
        dispatch(deleteClientProgress({id: Number(clientId), progressId: selectedProgress.id}));
        handleCloseDeleteModal();
    };
    const handleRespond = (progressId, response) => {
        dispatch(respondClientProgress({
            id: Number(clientId),
            progressId,
            formData: {response}
        }));
    };
    const handleReminderSuccess = async (_responseBody, mode) => {
        setShowReminderModal(false);
        dispatch(addToast({
            id: Date.now(),
            title: t("clientProgressUser:reminderSuccessTitle"),
            message: t(`clientProgressUser:reminderSuccess${mode.charAt(0).toUpperCase()}${mode.slice(1)}`)
        }));
    };

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
            />
            <Page contentHeader={false} loading={loading}>
                <div className={"row justify-content-center d-flex"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            {showListError && (
                                <div className="row justify-content-center">
                                    <div className="col-12 col-lg-10">
                                        <div className="card border border-secondary-subtle rounded-4 shadow-sm bg-white">
                                            <div className="card-body px-4 py-4 px-md-5 py-md-5 text-center">
                                                <div className="d-flex justify-content-center mb-3">
                                                    <RoundedIcon
                                                        icon={"fa-circle-exclamation"}
                                                        size={"lg"}
                                                        bgColor={"bg-secondary-subtle"}
                                                        textColor={"text-secondary"}
                                                    />
                                                </div>
                                                <div className="d-flex flex-column gap-2">
                                                    <span className="d-block fw-semibold fs-4 lh-sm text-default">
                                                        {t("clientProgressUser:listLoadErrorTitle")}
                                                    </span>
                                                    <span className="d-block text-secondary fs-5 lh-base">
                                                        {listErrorMessage}
                                                    </span>
                                                </div>
                                                <div className="d-grid col-12 col-md-8 mx-auto mt-4">
                                                    <button className="btn btn-primary py-3 fw-semibold" onClick={handleRetryList}>
                                                        {t("clientProgressUser:retry")}
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                            {showEmptyState && (
                                <div className="row justify-content-center">
                                    <div className="col-12 col-lg-10">
                                        <div className="d-flex flex-column align-items-center gap-4">
                                            <RoundedIcon icon={"fa-clipboard-check"} size={"lg"}/>
                                            <div className="col-10 col-md-9">
                                                <span className="d-block fw-semibold fs-5 lh-sm text-center text-default">
                                                    <Trans
                                                        i18nKey="clientProgressUser:emptyTitleRich"
                                                        components={{highlight: <span className="text-primary"/>}}
                                                    />
                                                </span>
                                            </div>
                                            <div className="d-flex flex-column w-100 text-start">
                                                {emptyStateBenefits.map((benefit, index) => (
                                                    <div
                                                        key={benefit.text}
                                                        className={`d-flex align-items-center gap-2 py-2 ${index < emptyStateBenefits.length - 1 ? "border-bottom border-light-subtle" : ""}`}
                                                    >
                                                        <RoundedIcon icon={benefit.icon} size={"xs"} className="flex-shrink-0"/>
                                                        <span className="fw-semibold text-default">{benefit.text}</span>
                                                    </div>
                                                ))}
                                            </div>
                                            <div className="d-grid w-100">
                                                <button className="btn btn-primary w-100" onClick={() => setShowReminderModal(true)}>
                                                    {t("clientProgressUser:sendReminder")}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                            {showList && progressList.map((progress, index) => (
                                <div key={progress.id}>
                                    <ClientProgressCard
                                        progress={progress}
                                        client={selectedClient}
                                        onRespond={handleRespond}
                                        onDelete={handleOpenDeleteModal}
                                        t={t}
                                        locale={i18n.language}
                                    />
                                    {index < progressList.length - 1 && (
                                        <hr className={"my-4 border-secondary-subtle opacity-100 pb-2"}/>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </Page>

            <DeleteModal
                show={showDeleteModal}
                onClose={handleCloseDeleteModal}
                onConfirm={handleConfirmDelete}
                deleteTitle={t("clientProgressUser:deleteTitle")}
                deleteSubtitle={t("clientProgressUser:deleteSubtitle")}
                confirmLabel={t("clientProgressUser:deleteConfirm")}
                closeLabel={t("clientProgressUser:close")}
            />

            <PushComposeOffcanvas
                show={showReminderModal}
                onHide={() => setShowReminderModal(false)}
                title={t("clientProgressUser:reminderModalTitle")}
                initialMode={"now"}
                initialValues={reminderInitialValues}
                lockedAudience={lockedAudience}
                onSuccess={handleReminderSuccess}
                secondaryAction={{
                    label: t("clientProgressUser:close"),
                    onClick: () => setShowReminderModal(false)
                }}
            />
        </>
    );
};

export default ClientProgress;
