import LoadingBlock from "../loader/LoadingBlock";
import {folderUpdated, updateFolder} from "../../store/workout-library/workoutLibraryReducer";
import {useEffect} from "react";
import * as Yup from "yup";
import he from "he";
import {useDispatch, useSelector} from "react-redux";
import {selectFolderUpdated, selectLoadingUpdatingFolder} from "../../store/workout-library/workoutLibrarySelector";
import {ErrorMessage, Field, Form, Formik} from "formik";
import Modal from "react-bootstrap/Modal";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const WorkoutFolderEditModal = ({folder, showModal, handleShowModal}) => {
    const dispatch = useDispatch();
    const {t} = useTranslation();
    const isFolderUpdating = useSelector(selectLoadingUpdatingFolder);
    const isFolderUpdated = useSelector(selectFolderUpdated)
    useComponentTranslations('trainingLibraryComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const validationSchema = Yup.object().shape({
        name: Yup.string().required(t("trainingLibraryComponent:folderNameIsRequired"))
            .max(45, t("trainingLibraryComponent:nameTooBig")),
    });

    const decodedFolderName = he.decode(folder.name);

    const handleFormSubmit = (values) => {
        const payload = {
            id: folder.id,
            ...values
        }
        dispatch(updateFolder(payload))
    }

    useEffect(() => {
        if (isFolderUpdated) {
            dispatch(folderUpdated({folder: null, payload: false}))
            handleShowModal();
        }
    }, [isFolderUpdated, dispatch, handleShowModal]);

    return (
        <Modal centered show={showModal} onHide={handleShowModal}>
            <Modal.Body>
                <div className={'row justify-content-between'}>
                    <div className={'col-auto'}>
                        <span className={"fw-semibold fs-5"}>{t("trainingLibraryComponent:editFolder")}</span>
                    </div>
                    <div className={'col-auto clickable-element'} onClick={handleShowModal}>
                        <i className={'fa-regular fa-times fs-5'}></i>
                    </div>
                </div>
                {!isFolderUpdating && (
                    <div className={"row mt-3"}>
                        <div className={'col-12'}>
                            <Formik
                                initialValues={{ name: decodedFolderName }}
                                validationSchema={validationSchema}
                                onSubmit={handleFormSubmit}
                            >
                                {({errors, touched}) => (
                                    <Form>
                                        <div className="mb-3">
                                            <label htmlFor="name" className="fw-semibold">
                                                {t("trainingLibraryComponent:folderNameLabel")}
                                            </label>
                                            <Field
                                                id="name"
                                                name="name"
                                                type="text"
                                                className={`form-control ${touched.name && errors.name ? 'is-invalid' : ''}`}

                                            />
                                            <ErrorMessage
                                                name="name"
                                                component="div"
                                                className="invalid-feedback d-block"
                                            />
                                        </div>
                                        <div className={'d-grid'}>
                                            <button type="submit" className="btn btn-primary">
                                                {t("trainingLibraryComponent:save")}
                                            </button>
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                            <div className={'d-grid mt-2'}>
                                <button className={'btn btn-outline-primary clickable-element'} onClick={handleShowModal}>
                                    {t("trainingLibraryComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                )}
                {isFolderUpdating && <LoadingBlock height={"300px"}/>}
            </Modal.Body>
        </Modal>
    )
}
export default WorkoutFolderEditModal;
