import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useDispatch, useSelector} from "react-redux";
import React, {useEffect, useState} from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import LoadingBlock from "../../components/loader/LoadingBlock";
import Tabs from "../../components/tab/Tabs";
import ClientRegistrationData from "../../components/client/ClientRegistrationData";
import {fetchClient} from "../../store/client/clientReducer";
import ClientAddress from "../../components/client/ClientAddress";

const ClientEdit = () => {
    const {t} = useTranslation();
    const {id, type} = useParams();
    const navigate = useNavigate()
    const dispatch = useDispatch();
    const client = useSelector(selectSelectedClient);
    const [page, setPage] = useState(type ?? "1");
    useComponentTranslations('client', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});


    const handleGoBack = () => {
        navigate(`/user/client/${id}/2`)
    }

    const changePages = (pageName) => {
        setPage(pageName);
    };

    useEffect(() => {
        dispatch(fetchClient(id))
    }, [id, dispatch]);

    if (!client)
        return <LoadingBlock/>;

    return (
        <Page title={t("client:clientEditTitle")} pb={"pb-2"} goBackLink={handleGoBack}>
            <Tabs page={page} button1Text={t("client:registration")} button2Text={t("client:address")} mt={"mt-n4"} buttonClick={changePages}/>
            {
                page === "1" ?
                    <ClientRegistrationData client={client}/> : <ClientAddress client={client}/>
            }
        </Page>
    )
}
export default ClientEdit;