import {createSlice} from "@reduxjs/toolkit";

const INITIAL_STATE = {
    files: [],
    oneFile: null,
    loading: false,
    addFile: false,
    editSuccess: false
}

export const fileSlice = createSlice({
    name:"files",
    initialState: INITIAL_STATE,
    reducers:{
        fetchAllFiles(state) {
            state.loading = true;
        },
        setAllFiles(state,action) {
            state.loading = false;
            state.files = action.payload;
        },
        fetchOneFile(state){
          state.loading = true;
        },
        setOneFile(state, action){
            state.loading = false;
            state.oneFile = action.payload;
        },
        addFile(state){
            state.loading = true
        },
        fileAdded(state, action){
            state.loading = false;
            state.addFile = action.payload;
        },
        clearAddFile(state) {
            state.addFile = null;
        },
        deleteFile(state){
            state.loading = true;
        },
        fileDeleted(state, action){
            state.loading = false;
            state.files = state.files.filter(f => f.id !== action.payload.fileId);
            state.oneFile = action.payload;
        },
        selectFile(state, action) {
            state.selectedFile = action.payload;
        },
        clearSelectedFile(state) {
            state.selectedFile = null;
        },
        editFile(state){
            state.loading = true;
        },
        fileEdited(state, action){
            state.loading = false;
            state.oneFile = action.payload;
            state.editSuccess = true;
        },
        clearEditFile(state) {
            state.editSuccess = false;
        },
        onError(state) {
            state.loading = false
        },
    }
})

export const {
    fetchAllFiles, setAllFiles,
    fetchOneFile, setOneFile,
    addFile, fileAdded, clearAddFile,
    deleteFile, fileDeleted,
    editFile, fileEdited, clearEditFile,
    selectFile, clearSelectedFile,
    onError
} = fileSlice.actions;
export const filesReducer = fileSlice.reducer;