import {createSlice} from "@reduxjs/toolkit";

const INITIAL_STATE = {
    feedbacks: null,
    unreadFeedbackCount: null,
    loading: false,
    feedbackResolving: false,
    formSent: false,
    resolvedFeedbackList: null
}
export const feedbackSlice = createSlice({
    name: 'feedbacks',
    initialState: INITIAL_STATE,
    reducers: {
        resolveAllFeedbacks(state) {
            state.loading = true
        },
        resolveFeedback(state) {
            state.feedbackResolving = true
        },
        resolveFeedbackSuccess(state, action) {
            state.feedbacks = state.feedbacks.filter(feedback => feedback.id !== action.payload)
            state.feedbackResolving = false
        },
        fetchAllUnreadFeedbacks(state) {
            state.loading = true;
        },
        setFeedbacks(state, action) {
            state.feedbacks = action.payload
            state.loading = false
        },
        setUnreadFeedbacks(state, action) {
            state.unreadFeedbackCount = action.payload
            state.loading = false
        },
        fetchUnreadFeedbacks(state) {
            state.loading = true;
        },
        feedbackCreated(state) {
            state.loading = false;
        },
        createFeedback(state) {
            state.loading = true
        },
        setFeedbackFormSent(state, action) {
            state.formSent = action.payload;
        },
        onError(state) {
            state.loading = false
        },
        fetchResolvedFeedbacks(state) {
            state.loading = true
        },
        setResolvedFeedbacks(state, action) {
            state.resolvedFeedbackList = action.payload
            state.loading = false
        }
    }
})

export const {
    createFeedback,
    onError,
    feedbackCreated,
    setFeedbackFormSent,
    setUnreadFeedbacks,
    fetchUnreadFeedbacks,
    setFeedbacks,
    fetchAllUnreadFeedbacks,
    resolveFeedbackSuccess,
    resolveFeedback,
    resolveAllFeedbacks,
    setResolvedFeedbacks,
    fetchResolvedFeedbacks
} = feedbackSlice.actions;
export const feedbackReducer = feedbackSlice.reducer;