import {createSlice} from "@reduxjs/toolkit";
import {
    createErrorSubmitResult,
    createPendingSubmitResult,
    createSubmitResult,
    createSuccessSubmitResult
} from "../../utils/evaluation/mutationState";

const initialState = {
    physicalList: [],
    compareList: [],
    onePhysical: null,
    lastPhysical: null,
    selectedPhysical: null,
    initialLoading: false,
    submitLoading: false,
    submitResult: createSubmitResult(),
    error: null,
};

export const slice = createSlice({
    name: "physicalEvaluation",
    initialState,
    reducers: {
        getAllPhysical(state) {
            state.initialLoading = true;
        },
        setAllPhysical(state, action) {
            state.initialLoading = false;
            state.physicalList = action.payload;
        },
        clearAllPhysical(state) {
            state.physicalList = null;
            state.initialLoading = false;
        },
        fetchOnePhysical(state) {
            state.initialLoading = true;
        },
        setOnePhysical(state, action) {
            state.initialLoading = false;
            state.onePhysical = action.payload;
        },
        fetchLastPhysical(state) {
            state.lastPhysical = null;
        },
        setLastPhysical(state, action) {
            state.lastPhysical = action.payload?.evaluation ?? null;
        },
        clearLastPhysical(state) {
            state.lastPhysical = null;
        },
        changeStatus: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: action.payload?.status === 1 ? "delete" : "recover",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        setStatusChanged(state, action) {
            state.physicalList = state.physicalList.filter(item => item.id !== action.payload.id);
        },
        savePhysical: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "create",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        resetFormSent(state) {
            state.submitLoading = false;
            state.submitResult = createSubmitResult();
            state.error = null;
        },
        updatePhysical: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "update",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        comparePhysical(state) {
            state.initialLoading = true;
        },
        setComparePhysical(state, action) {
            state.initialLoading = false;
            state.compareList = action.payload;
        },
        setSubmitResult(state, action) {
            state.submitLoading = false;
            state.submitResult = createSuccessSubmitResult(action.payload);
            state.error = null;
        },
        onError(state, action) {
            state.initialLoading = false;
            if (state.submitLoading) {
                state.submitResult = createErrorSubmitResult(state.submitResult, action.payload);
            }
            state.submitLoading = false;
            state.error = action.payload;
        }
    }
});

export const {
    getAllPhysical,
    setAllPhysical,
    clearAllPhysical,
    fetchOnePhysical,
    setOnePhysical,
    fetchLastPhysical,
    setLastPhysical,
    clearLastPhysical,
    changeStatus,
    setStatusChanged,
    savePhysical,
    updatePhysical,
    comparePhysical,
    setComparePhysical,
    setSubmitResult,
    onError,
    resetFormSent
} = slice.actions;

export const physicalEvaluationReducer = slice.reducer;
