import ToastComponent from "../components/toast/ToastComponent";
import TopBar from "../components/navbar/TopBar";
import {Outlet} from "react-router-dom";
import {useEffect} from "react";
import {fetchUser, getPaymentCountry, setPaymentCountry} from "../store/user/userReducer";
import {useDispatch, useSelector} from "react-redux";
import {selectPaymentCountry, selectUser} from "../store/user/userSelector";
import {getToken} from "../api/api";
import LoadingBlock from "../components/loader/LoadingBlock";
import {fetchPaymentMethod} from "../store/subscription/subscriptionReducer";

const SubscriptionRoute = () => {
    const user = useSelector(selectUser)
    const dispatch = useDispatch();
    const paymentCountry = useSelector(selectPaymentCountry)

    useEffect(() => {
        dispatch(fetchPaymentMethod())
    }, [dispatch]);
    useEffect(() => {
        dispatch(setPaymentCountry())
    }, [dispatch]);

    useEffect(() => {
        if (!user)
            dispatch(fetchUser())
    }, [user, dispatch]);

    useEffect(() => {
        if (paymentCountry) {
            if (paymentCountry.country !== "BRA") {
                const token = getToken()
                window.location.href = `https://payments.mfitpersonal.com.br/redirect/${token}`
            }
        } else {
            dispatch(getPaymentCountry())
        }
    }, [paymentCountry, dispatch]);

    if (!paymentCountry) {
        return <LoadingBlock/>
    }
    return (
        <>
            <ToastComponent/>
            <TopBar/>
            <div style={{height: '79px'}}></div>
            <Outlet/>
        </>
    );
}

export default SubscriptionRoute