import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {selectUser} from "../../store/user/userSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import Page from "../../components/page/Page";
import {useEffect, useState} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import SelectFilesModal from "../../components/files/SelectFilesModal";
import {isFileAdd, isFilesLoading, selectAllFiles,} from "../../store/files/filesSelector";
import {addFile, clearAddFile, clearSelectedFile, fetchAllFiles} from "../../store/files/filesReducer";
import uploadFile from "../../utils/fileupload/s3FileUpload";
import FileCard from "../../components/files/FileCard";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";

const MAX_FILE_SIZE = 20 * 1024 * 1024;

const Files = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {clientId} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const user = useSelector(selectUser);
    const loadingFiles = useSelector(isFilesLoading);
    const filesList = useSelector(selectAllFiles);
    const addFileSuccess = useSelector(isFileAdd);
    const [showSelectFile, setShowSelectFile] = useState(false);

    const [isDownloading, setIsDownloading] = useState(false);

    useComponentTranslations("files", {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR})


    const handleGoBackPage = () => {
        navigate(`/user/client/${clientId}`);
    };


    const handleSelectModal = () => {
        setShowSelectFile(prevState => !prevState)
    }


    const handleDownloadFile = async (file) => {
        if (!file?.url) return;

        if (file.size > MAX_FILE_SIZE) {
            alert(`${t("files:alertLimit")} ${MAX_FILE_SIZE / (1024 * 1024)} MB.`);
            return;
        }

        setIsDownloading(true);

        try {
            const response = await fetch(file.url);
            if (!response.ok) return;
            const blob = await response.blob();

            const downloadUrl = window.URL.createObjectURL(blob);
            const link = document.createElement("a");
            link.href = downloadUrl;
            link.download = file.nome;
            document.body.appendChild(link);
            link.click();
            link.remove();
            window.URL.revokeObjectURL(downloadUrl);
            dispatch(clearSelectedFile());
        } catch (err) {
            console.error(err);
        } finally {
            setIsDownloading(false);
        }
    };

    const handleFileSelect = async (file) => {
        try {
            if (file.size > MAX_FILE_SIZE) {
                alert(`${t("files:alertLimit")} ${MAX_FILE_SIZE / (1024 * 1024)} MB.`);
                return;
            }
            const s3Url = await uploadFile(file, user.id, clientId, "arquivos");
            const fileId = s3Url.split("/").pop();
            const payload = {
                fileId,
                id: Number(clientId),
                nome: file.name,
                url: s3Url,
                clients: [Number(clientId)],
                groups: [],
            };
            dispatch(addFile(payload));
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        dispatch(fetchClient(clientId));
    }, [dispatch, clientId]);

    useEffect(() => {
        dispatch(fetchAllFiles(clientId));
    }, [dispatch, clientId]);

    useEffect(() => {
        if (addFileSuccess) {
            const newFileId = addFileSuccess.id || addFileSuccess.fileId;
            if (newFileId) {
                navigate(`/user/client/${clientId}/files/edit/${newFileId}`);
            }
            dispatch(clearAddFile());
        }
    }, [addFileSuccess, navigate, clientId, dispatch]);

    return (
        <>
            <AvatarHeader showGoBack={handleGoBackPage} className={"pb-4 pt-2"}
                          text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                          url={selectedClient?.profileUrl}/>
            <Page contentHeader={false} loading={loadingFiles}>
                <div className={"row justify-content-center d-flex"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            <button className={"btn btn-outline-primary py-4 clickable-element mb-2"} onClick={handleSelectModal}>
                                <i className={"text-primary fa-regular fa-plus"}/>
                                <span className={"px-1 clickable-element"}>
                                    {t("files:addFiles")}
                                </span>
                            </button>
                            {(!filesList || filesList.length === 0) &&
                                <div className={'row justify-content-center pt-4 mb-4 '}>
                                    <div className={'col-6 text-center'}>
                                        <RoundedIcon icon={"fa-file-plus"} size={"lg"}/>
                                    </div>
                                    <div className={'text-center mt-4 pt-2'}>
                                        <span className={"fw-semibold fs-4 lh-1"}>
                                           {t("files:filesTitle")}
                                        </span>
                                    </div>
                                    <div className={"text-center"}>
                                        <ul className={"pt-4 text-start d-inline-block"}>
                                            <li>{t("files:mealPlans")}</li>
                                            <li>{t("files:exams")}</li>
                                            <li>{t("files:planners")}</li>
                                            <li>{t("files:variousFiles")}</li>
                                        </ul>
                                    </div>
                                </div>
                            }
                            {
                                filesList && filesList.length > 0 && (
                                    <div className={"pt-2"}>
                                        <div className={"pb-2"}>
                                            <span className={"fw-semibold"}>{t("files:files")}</span>
                                        </div>
                                        {filesList.map(item => (
                                            <FileCard
                                                key={item.id}
                                                isDownloading={isDownloading}
                                                file={item}
                                                handleDownload={handleDownloadFile}
                                            />
                                        ))}
                                    </div>
                                )
                            }
                        </div>
                    </div>
                </div>
            </Page>
            <SelectFilesModal
                showModal={showSelectFile}
                hideModal={handleSelectModal}
                onFileSelect={handleFileSelect}
            />

        </>
    )
}

export default Files;
