import Avatar from "../avatar/Avatar";
import he from "he";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {parse, format} from "date-fns";
import {ErrorMessage, Field, Form, Formik} from "formik";
import Select from "react-select";
import {buildCountryData, defaultCountries, parseCountry, PhoneInput} from "react-international-phone";
import Modal from "react-bootstrap/Modal";
import ImageCropper from "./ImageCropper";
import React, {useEffect, useMemo, useRef, useState} from "react";
import * as Yup from "yup";
import {clientUpdated, fetchSelectOptions, updateClient} from "../../store/client/clientReducer";
import {getPaymentCountry} from "../../store/user/userReducer";
import {fetchSeller} from "../../store/wallet/walletReducer";
import {getModels} from "../../store/anamnesis/anamnesisReducer";
import {addToast} from "../../store/toast/toastReducer";
import {useDispatch, useSelector} from "react-redux";
import {selectPaymentCountry, selectUser} from "../../store/user/userSelector";
import {selectSeller} from "../../store/wallet/walletSelector";
import {isClientsLoading, selectClientUpdated, selectSelectOptions} from "../../store/client/clientSelector";
import {getModelsList} from "../../store/anamnesis/anamnesisSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {clearCreatedClientGroup, createClientGroup} from "../../store/client-group/clientGroupReducer";
import {selectClientGroupMutationLoading, selectCreatedClientGroup} from "../../store/client-group/clientGroupSelector";
import ClientGroupCreateModal from "../client-group/ClientGroupCreateModal";

const formatDate = (dateObj) => {
    if (!dateObj) return '';
    const {year, month, day} = dateObj;
    return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
};

const ClientRegistrationData = ({client}) => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const userPaymentCountry = useSelector(selectPaymentCountry);
    const seller = useSelector(selectSeller)
    const isClientUpdated = useSelector(selectClientUpdated)
    const [showProfilePicture, setShowProfilePicture] = useState(false);
    const [image, setImage] = useState(null)
    const fileInputRef = useRef(null);
    const loading = useSelector(isClientsLoading)
    const groupOptions = useSelector(selectSelectOptions);
    const userLanguage = i18n.language || 'en-US';
    const userLanguageFormated = userLanguage.split("-")[1]?.toLowerCase() || userLanguage;
    const modelsList = useSelector(getModelsList)
    const user = useSelector(selectUser)
    const createdGroup = useSelector(selectCreatedClientGroup);
    const groupLoading = useSelector(selectClientGroupMutationLoading);
    const groupFieldSetterRef = useRef(null);
    const [showCreateGroup, setShowCreateGroup] = useState(false);
    useComponentTranslations('client', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    syncMomentLocale(user?.language);

    const initialValues = {
        fullName: client
            ? `${he.decode(client.nome)} ${he.decode(client.sobrenome)}` : '',
        email: client ? client.mail : '',
        group: client ? client.grupo?.id : null,
        birthdate: client ? formatDate(client.data_nascimento) : '',
        phoneNumber: client ? `${client.telefone}` : '',
        gender: client ? client.sexo : '',
        blockAccess: client ? client.bloquearCobrancaVencida.toString() : '',
        country_iso: client ? client.paisIso : '',
        country: client ? client.pais.toString() : '',
        language: client ? client.language : '',
        timezone: client ? client.timeZone : ''
    };

    const validationSchema = Yup.object().shape({
        fullName: Yup.string()
            .required(`${t("client:requiredField")}`)
            .test('has-two-names', `${t("client:atLeastTwoNames")}`, (value) => {
                return value && value.trim().split(' ').length >= 2;
            }),
        email: Yup.string()
            .email(`${t("client:invalidEmail")}`)
            .matches(/^[^\s@]+@[^\s@]+\.[^\s@]+$/, `${t("client:invalidEmail")}`)
            .required(`${t("client:requiredField")}`),
        birthdate: Yup.string()
            .required(`${t("client:requiredField")}`)
            .test('valid-date', `${t("client:invalidDateFormat")}`, function (value) {
                const {path, createError} = this;
                const parsedDate = parse(value, 'yyyy-MM-dd', new Date());

                if (
                    isNaN(parsedDate.getTime()) ||
                    format(parsedDate, 'yyyy-MM-dd') !== value
                ) {
                    return createError({path, message: `${t("client:invalidDate")}`});
                }

                return true;
            }),
        phoneNumber: Yup.string()
            .required(`${t("client:requiredField")}`)
            .test(
                'isBrazilPhoneLength',
                `${t("client:invalidPhoneNumber")}`,
                (value) =>
                    !value.startsWith('+55') ||
                    (value.startsWith('+55') && value.replace(/[^0-9]/g, '').length === 13)
            ),
        gender: Yup.string().required(`${t("client:requiredField")}`),
        blockAccess:
            userPaymentCountry?.country === 'BRA' || seller !== null
                ? Yup.string().required(`${t("client:requiredField")}`)
                : Yup.string().notRequired().default('0'),
    });



    const getLocalizedCountryNames = (locale) => {
        if (typeof Intl.DisplayNames === 'function') {
            const regionNames = new Intl.DisplayNames([locale], {type: 'region'});
            return defaultCountries.reduce((acc, country) => {
                const {iso2} = parseCountry(country);
                acc[iso2.toUpperCase()] = regionNames.of(iso2.toUpperCase());
                return acc;
            }, {});
        }
        return defaultCountries.reduce((acc, country) => {
            const {iso2, name} = parseCountry(country);
            acc[iso2.toUpperCase()] = name;
            return acc;
        }, {});
    };

    const localizedCountryNames = useMemo(() => getLocalizedCountryNames(userLanguage), [userLanguage]);

    const modifiedCountries = useMemo(() => {
        const countries = defaultCountries.map((country) => {
            const parsedCountry = parseCountry(country);
            const translatedName =
                localizedCountryNames[parsedCountry.iso2.toUpperCase()] || parsedCountry.name || 'Unknown Country';
            if (parsedCountry.iso2 === 'ar') {
                const cfg =
                    typeof parsedCountry.format === 'string'
                        ? { default: parsedCountry.format }
                        : parsedCountry.format || { default: '.. .... ....' };

                parsedCountry.format = {
                    ...cfg,
                    '/^9/': `. ${cfg.default}`,
                };
            }
            return buildCountryData({
                ...parsedCountry,
                name: translatedName,
            });
        });

        return countries.sort((a, b) => a[0].localeCompare(b[0]));
    }, [localizedCountryNames]);



    const handleSubmit = (values) => {
        const parsedDate = parse(values.birthdate, 'yyyy-MM-dd', new Date());

        if (
            isNaN(parsedDate.getTime()) ||
            format(parsedDate, 'yyyy-MM-dd') !== values.birthdate
        ) {
            return;
        }

        dispatch(updateClient({id: client.id, formData: values}))
    };


    const onFileButtonClick = () => {
        fileInputRef.current.value = null;
        fileInputRef.current.click();
    };

    const onFileChange = async (e) => {
        const file = e.target.files[0]
        let imageDataUrl = await readFile(file)
        setImage(imageDataUrl);
        handleShowImageUpload()
    }

    function readFile(file) {
        return new Promise((resolve) => {
            const reader = new FileReader()
            reader.addEventListener('load', () => resolve(reader.result), false)
            reader.readAsDataURL(file)
        })
    }

    const handleShowImageUpload = () => {
        setShowProfilePicture(prev => !prev)
    }


    useEffect(() => {
        if (userPaymentCountry === null) {
            dispatch(getPaymentCountry())
        }
    }, [userPaymentCountry, dispatch])

    useEffect(() => {
        dispatch(fetchSeller())
    }, [dispatch])

    useEffect(() => {
        if (!modelsList)
            dispatch(getModels("models"))
    }, [modelsList, dispatch]);

    useEffect(() => {
        dispatch(fetchSelectOptions("groups"));
    }, [dispatch]);

    useEffect(() => {
        if (createdGroup && groupFieldSetterRef.current) {
            dispatch(fetchSelectOptions("groups"));
            groupFieldSetterRef.current("group", createdGroup.id);
            setShowCreateGroup(false);
            dispatch(clearCreatedClientGroup());
        }
    }, [createdGroup, dispatch]);

    useEffect(() => {
        if (isClientUpdated) {
            dispatch(addToast(
                {
                    type: "success",
                    message: `${t("client:informationUpdate")}`,
                    title: `${t("client:allGood")}`
                }))
            dispatch(clientUpdated(false))
        }
    }, [dispatch, isClientUpdated, t])

    return (

        <>
            <div className={"card card-body border-0 mt-4"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        <div className={"col-12 clickable-element text-center"} onClick={onFileButtonClick}>
                            <Avatar maxWidth={"74px"} url={image || client.profileUrl}/>
                            <span className={"small text-primary "}>{t("client:changePic")}</span>
                            <input type="file" id={"file-upload"} ref={fileInputRef}
                                   className={'d-none'}
                                   onChange={onFileChange}
                                   accept="image/*"/>
                        </div>
                    </div>
                    <div className={"col-12 text-center mt-2"}>
                        <span className={'fw-semibold'}>{he.decode(client.nome)} {he.decode(client.sobrenome)}</span>
                    </div>
                    {
                        client.dataCadastro &&
                        <div className={"col-12 text-center  "}>
                            <span className={'fw-semibold'}>{t("client:signUpDate")}: </span><span>{moment({
                            year: client.dataCadastro.year,
                            month: client.dataCadastro.month - 1,
                            day: client.dataCadastro.day
                        }).format('L')}</span>
                        </div>
                    }
                </div>
            </div>
            <div className="card border-0 mt-2">
                <div className="card-body  ">
                    <Formik
                        initialValues={initialValues}
                        validationSchema={validationSchema}
                        validateOnChange={true}
                        onSubmit={handleSubmit}
                        enableReinitialize={true}
                        context={{userPaymentCountry, seller}}
                    >
                        {({values, setFieldValue}) => (
                            <Form>
                                <div className="form-group">
                                    <label htmlFor="fullName" className={"fw-semibold"}>{t("client:fullName")}</label>
                                    <Field name="fullName" type="text" className="form-control"/>
                                    <ErrorMessage name="fullName" component="div" className="text-danger"/>
                                </div>
                                <div className="form-group mt-3">
                                    <label htmlFor="email" className={"fw-semibold"}>{t("client:email")}</label>
                                    <Field name="email" type="email" className="form-control"/>
                                    <ErrorMessage name="email" component="div" className="text-danger"/>
                                </div>
                                <div className="form-group mt-3">
                                    <label htmlFor="group" className={"fw-semibold"}>{t("client:selectAGroup")}</label>
                                    {groupFieldSetterRef.current = setFieldValue}
                                    <Select
                                        name="group"
                                        className="basic-multi-select"
                                        classNamePrefix="select"
                                        options={
                                            groupOptions
                                                ? [
                                                    ...groupOptions.map((opt) => ({
                                                        value: opt.id,
                                                        label: opt.label.includes("client_group") ? t(`client:${opt.label}`) : opt.label,
                                                    })),
                                                    {
                                                        value: "__create_new_group__",
                                                        label: t("client:createNewGroupOption")
                                                    }
                                                ] : []
                                        }
                                        value={
                                            groupOptions
                                                ? groupOptions
                                                    .map((opt) => ({
                                                        value: opt.id,
                                                        label: opt.label.includes("client_group") ? t(`client:${opt.label}`) : opt.label,
                                                    }))
                                                    .find(option => option.value === values.group)
                                                : null
                                        }
                                        onChange={(option) => {
                                            if (option?.value === "__create_new_group__") {
                                                setShowCreateGroup(true);
                                                return;
                                            }

                                            setFieldValue('group', option?.value)
                                        }}
                                    />
                                    <ErrorMessage name="group" component="div" className="text-danger"/>
                                </div>
                                <div className="form-group mt-3">
                                    <label htmlFor="birthdate" className={"fw-semibold"}>{t("client:birthdate")}</label>
                                    <Field name="birthdate" type="date" className="form-control"/>
                                    <ErrorMessage name="birthdate" component="div" className="text-danger"/>
                                </div>
                                <div className="form-group mt-3">
                                    <label htmlFor="phoneNumber" className={"fw-semibold"}>{t("client:whatsApp")}</label>
                                    <Field name={"phoneNumber"}>
                                        {({field, form}) => (
                                            <PhoneInput
                                                inputClassName="form-control"
                                                name="phoneNumber"
                                                forceDialCode={true}
                                                value={field.value}
                                                countries={modifiedCountries}
                                                onChange={(value, e) => {
                                                    setFieldValue("country_iso", e.country.iso2);
                                                    setFieldValue("country", e.country.dialCode);
                                                    switch (e.country.iso2) {
                                                        case "br":
                                                            setFieldValue("language", "pt-BR");
                                                            setFieldValue("timezone", "America/Sao_Paulo");
                                                            break;
                                                        case "pt":
                                                            setFieldValue("language", "pt-PT");
                                                            setFieldValue("timezone", "Europe/Lisbon");
                                                            break;
                                                        default:
                                                            setFieldValue("language", "en-US");
                                                            setFieldValue("timezone", "America/New_York");
                                                            break;
                                                    }
                                                    setFieldValue(field.name, value);
                                                }}
                                                onBlur={() => form.setFieldTouched(field.name, true)}
                                                defaultCountry={values.country_iso || userLanguageFormated}
                                            />
                                        )}
                                    </Field>
                                    <ErrorMessage name="phoneNumber" component="div" className="text-danger"/>
                                </div>
                                <div className="form-group mt-3">
                                    <label className={"fw-semibold"}>{t("client:gender")}</label>
                                    <Field
                                        as="select"
                                        name="gender"
                                        className="form-control"
                                        value={values.gender}
                                        onChange={(e) => setFieldValue('gender', e.target.value)}
                                    >
                                        <option value="" label={t("client:select")}/>
                                        <option value="m" label={t("client:male")}/>
                                        <option value="f" label={t("client:female")}/>
                                        <option value="o" label={t("client:other")}/>
                                    </Field>
                                    <ErrorMessage name="gender" component="div" className="text-danger"/>
                                </div>
                                {
                                    (userPaymentCountry?.country === 'BRA' || seller !== null) &&
                                    <div className="form-group mt-3">
                                        <label htmlFor={"blockAccess"} className={"fw-semibold"}>{t("client:blockPastDueInvoice")}</label>
                                        <Field
                                            as="select"
                                            name="blockAccess"
                                            className="form-control"
                                            value={values.blockAccess}
                                            onChange={(e) => setFieldValue('blockAccess', e.target.value)}
                                        >
                                            <option value="" label={t("client:select")}/>
                                            <option value="1" label={t("client:yes")}/>
                                            <option value="0" label={t("client:no")}/>
                                        </Field>
                                        <ErrorMessage name="blockAccess" component="div" className="text-danger"/>
                                    </div>
                                }
                                {
                                    values.blockAccess === "1" && seller === null &&
                                    <div className={'card card-body mt-2 py-2 px-3 border-0 bg-secondary-subtle small'}>
                                        <span><i className={"fa-regular fa-exclamation-circle"}></i> {t("client:blockPastDueMessage")}</span>
                                    </div>
                                }
                                <div className={'d-grid'}>
                                    <button type="submit" className="btn btn-primary mt-3" disabled={loading}>
                                        {t("client:save")}
                                    </button>
                                </div>
                            </Form>
                        )}
                    </Formik>
                </div>
            </div>
            {
                showProfilePicture &&
                <Modal centered show={showProfilePicture} onHide={handleShowImageUpload}>
                    <Modal.Body>
                        <ImageCropper image={image}
                                      setImage={setImage}
                                      saveText={t("client:save")}
                                      cancelText={t("client:cancel")}
                                      handleClose={handleShowImageUpload}
                                      client={client}/>
                    </Modal.Body>
                </Modal>
            }
            <ClientGroupCreateModal
                show={showCreateGroup}
                onHide={() => setShowCreateGroup(false)}
                onSubmit={(values) => dispatch(createClientGroup(values))}
                title={t("client:createNewGroupOption")}
                label={t("client:groupName")}
                submitText={t("client:save")}
                cancelText={t("client:cancel")}
                loading={groupLoading}
                requiredMessage={t("client:requiredField")}
                minLengthMessage={t("client:requiredField")}
                maxLengthMessage={t("client:max245Characters")}
            />

        </>
    )

}
export default ClientRegistrationData;
