import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchAllRoutinesAPI = async ( type) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/workout-library/routines-all?type=${type}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    });
}

