import {useNavigate, useParams, useSearchParams} from "react-router-dom";
import Page from "../../components/page/Page";
import SubscriptionSteps from "../../components/subscription/SubscriptionSteps";
import SubscriptionUserInfo from "../../components/subscription/SubscriptionUserInfo";
import {useDispatch, useSelector} from "react-redux";
import {selectBuyer, selectedSubPlan, selectLoadingBuyer, selectSubPlanLoading} from "../../store/subscription/subscriptionSelector";
import {useEffect} from "react";
import {fetchBuyer, selectSubPlan} from "../../store/subscription/subscriptionReducer";
import SubscriptionUserAddress from "../../components/subscription/SubscriptionUserAddress";
import SubscriptionPurchaseReview from "../../components/subscription/SubscriptionPurchaseReview";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionPlanPurchase = () => {
    const {t} = useTranslation();
    const {subId, couponName} = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const buyer = useSelector(selectBuyer);
    const subPlan = useSelector(selectedSubPlan)
    const loadingBuyer = useSelector(selectLoadingBuyer);
    const loadingSubPlan = useSelector(selectSubPlanLoading)
    const STEP = {NONE: 0, NEW: 1, EXISTING: 2};
    const [searchParams] = useSearchParams();
    useComponentTranslations('subscriptionPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const goBackTo = searchParams.get("goBackTo");

    const step =
        !buyer ? STEP.NONE :
            buyer.id ? STEP.EXISTING :
                STEP.NEW;

    useEffect(() => {
        dispatch(fetchBuyer())
        dispatch(selectSubPlan(subId))
    }, [dispatch, subId]);

    const handleGoBack = () => {
        if (goBackTo === "subscriptionRenew") {
            navigate("/user/subscription")
        } else if (Number(subId) !== 1004) {
            navigate(`/subscription/type/1000${couponName?`/coupon/${couponName}`:''}${goBackTo ? `?goBackTo=${goBackTo}` : ""}`)
        } else
            navigate(`/subscription?step=1${goBackTo ? `&goBackTo=${goBackTo}` : ""}`);
    }

    return (
        <Page mt={"mt-n5"} title={t("subscriptionPage:subscribeAppTitle")}
              goBackLink={handleGoBack}>
            <div className={"card card-body border-0"}>
                {
                    !loadingBuyer && !loadingSubPlan && subPlan &&
                    <div className={"row justify-content-center"}>
                        <SubscriptionSteps step={step}/>
                        <div className={"col-12"}>
                            {
                                step === STEP.NONE &&
                                <SubscriptionUserInfo/>
                            }
                            {
                                step === STEP.NEW &&
                                <SubscriptionUserAddress/>
                            }
                            {
                                step === STEP.EXISTING &&
                                <SubscriptionPurchaseReview subPlan={subPlan}/>
                            }
                        </div>
                    </div>
                }
                {
                    (loadingBuyer || loadingSubPlan) &&
                    <LoadingBlock/>
                }

            </div>
        </Page>
    )
}

export default SubscriptionPlanPurchase;
