import AppOffcanvasShell from "../offcanvas/AppOffcanvasShell";
import PushComposePanel from "./PushComposePanel";

const PushComposeOffcanvas = ({
    show,
    onHide,
    title,
    initialMode = "now",
    initialValues,
    lockedAudience,
    onSuccess,
    secondaryAction = null,
    closeButtonAriaLabel = "Close"
}) => (
    <AppOffcanvasShell
        show={show}
        onHide={onHide}
        showDesktopCloseButton={false}
        closeButtonAriaLabel={closeButtonAriaLabel}
    >
        {({isMobileSheet}) => (
            <PushComposePanel
                title={title}
                initialMode={initialMode}
                initialValues={initialValues}
                lockedAudience={lockedAudience}
                onSuccess={onSuccess}
                secondaryAction={secondaryAction}
                isMobileSheet={isMobileSheet}
                onClose={onHide}
                closeButtonAriaLabel={closeButtonAriaLabel}
            />
        )}
    </AppOffcanvasShell>
);

export default PushComposeOffcanvas;
