import React, {useEffect, useMemo} from 'react';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import Select from 'react-select';
import {useDispatch, useSelector} from 'react-redux';
import * as Yup from 'yup';
import {useTranslation} from 'react-i18next';
import {resetFormSent, sendAnamnesis} from '../../store/anamnesis/anamnesisReducer';
import {getSubmitResult, isSubmitLoading} from "../../store/anamnesis/anamnesisSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {selectClientGroups} from "../../store/client-group/clientGroupSelector";
import {fetchClientGroups} from "../../store/client-group/clientGroupReducer";
import ClientRemoteMultiSelect from "../client/ClientRemoteMultiSelect";
import EvaluationSubmitButton from "../evaluation-components/EvaluationSubmitButton";
import EvaluationSuccessCard from "../evaluation-components/EvaluationSuccessCard";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const AnamnesisSendModal = ({onClose, modelId, clientId}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const loadingSend = useSelector(isSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const clientGroupList = useSelector(selectClientGroups);
    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const sent = isMatchingSubmitSuccess(submitResult, {
        action: "send",
        flow: EVALUATION_FLOWS.ANAMNESIS_SEND,
        clientId
    });

    const validationSchema = Yup.object().shape({
        sendTo: Yup.string().required(t("anamnesisComponent:required")),
        selectOption: Yup.array().when('sendTo', (sendToValue, schema) => {
            if (sendToValue === 'clientsId' || sendToValue === 'groupsId') {
                return schema
                    .min(1, t('anamnesisComponent:selectAtLeastOne'))
                    .required(t('anamnesisComponent:selectAtLeastOne'));
            } else {
                return schema.notRequired();
            }
        }),
    });

    const groupOptions = useMemo(() => (
        (clientGroupList || []).map((group) => ({
            value: group.id,
            label: group.nome
        }))
    ), [clientGroupList]);

    const handleSubmit = async (values) => {
        const {sendTo, selectOption} = values;
        const idsToSend = sendTo === 'current'
            ? clientId
            : (selectOption || []).join(',');

        const payload = {
                modelId: modelId,
                idsToSend: idsToSend || 0,
                sendTo: sendTo === "current" ? "clientsId" : sendTo
            }
        ;
        dispatch(sendAnamnesis(payload, {
            flow: EVALUATION_FLOWS.ANAMNESIS_SEND,
            clientId
        }));
    };

    useEffect(() => {
        dispatch(resetFormSent());
        dispatch(fetchClientGroups());
    }, [dispatch]);

    useEffect(() => {
        return () => {
            dispatch(resetFormSent());
        }
    }, [dispatch]);

    return (
        <>
            <div className={"row"}>
                <div className={'col-12'}>
                    {sent ? (
                        <EvaluationSuccessCard
                            title={t("anamnesisComponent:sendSuccess")}
                            primaryLabel={t("anamnesisComponent:close")}
                            onPrimary={onClose}
                            withCard={false}
                        />
                    ) : (
                        <Formik
                            initialValues={{sendTo: 'current', selectOption: []}}
                            validationSchema={validationSchema}
                            onSubmit={values => handleSubmit(values)}
                        >
                            {({values, setFieldValue, errors, touched}) => (
                                <Form>
                                        <div className="form-group mt-2">
                                            <label className="fw-semibold">{t('anamnesisComponent:sendTo')}</label>
                                            <Field
                                                as="select"
                                                name="sendTo"
                                                className={`form-control ${touched.sendTo && errors.sendTo ? 'is-invalid' : ''}`}
                                                onChange={(e) => setFieldValue("sendTo", e.target.value)}
                                            >
                                                <option value="current">{t("anamnesisComponent:currentClient")}</option>
                                                <option value="clientsId">{t("anamnesisComponent:clients")}</option>
                                                <option value="groupsId">{t("anamnesisComponent:groups")}</option>
                                            </Field>
                                            <ErrorMessage name="sendTo" component="div" className="invalid-feedback"/>
                                        </div>
                                        {(values.sendTo === 'clientsId' || values.sendTo === 'groupsId') && (
                                            <div className="form-group mt-2">
                                                <label className={"fw-semibold"}>
                                                    {values.sendTo === 'clientsId'
                                                        ? t('anamnesisComponent:selectOneOrMoreStudents')
                                                        : t('anamnesisComponent:selectOneOrMoreGroups')}
                                                </label>
                                                {values.sendTo === 'clientsId' ? (
                                                    <ClientRemoteMultiSelect
                                                        valueIds={values.selectOption}
                                                        onChangeIds={(clientIds) => setFieldValue('selectOption', clientIds)}
                                                        searchScope={"nonDeleted"}
                                                        resolveScope={"nonDeleted"}
                                                        placeholder={t('anamnesisComponent:select')}
                                                        disabled={loadingSend}
                                                    />
                                                ) : (
                                                    <Select
                                                        isMulti
                                                        name="selectOption"
                                                        options={groupOptions}
                                                        required
                                                        className="basic-multi-select"
                                                        classNamePrefix="select"
                                                        placeholder={t('anamnesisComponent:select')}
                                                        onChange={(opts) => setFieldValue('selectOption', opts ? opts.map((option) => option.value) : [])}
                                                        value={groupOptions.filter((option) => values.selectOption.includes(option.value))}
                                                    />
                                                )}
                                                <ErrorMessage name="selectOption" component="div" className="invalid-feedback"/>
                                            </div>
                                        )}
                                        <div className="d-grid mt-3">
                                            <EvaluationSubmitButton
                                                label={t('anamnesisComponent:send')}
                                                loadingLabel={t('anamnesisComponent:send')}
                                                isSubmitting={loadingSend}
                                            />
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                    )}
                </div>
                {!sent && (
                    <div className={"col-12 mt-2"}>
                        <div className={'d-grid'}>
                            <button className={'btn btn-outline-primary'} onClick={onClose} disabled={loadingSend}>
                                {t('anamnesisComponent:close')}</button>
                        </div>
                    </div>
                )}
            </div>
        </>
    );
};

export default AnamnesisSendModal;
