import {useState} from "react";
import Cropper from "react-easy-crop";
import getCroppedImg from "../../utils/image/cropImage";
import {useDispatch, useSelector} from "react-redux";
import uploadFile from "../../utils/fileupload/s3FileUpload";
import {selectUser} from "../../store/user/userSelector";
import {updateProfileImage} from "../../store/client/clientReducer";
import {isClientsLoading} from "../../store/client/clientSelector";

const ImageCropper = ({handleClose, image, setImage, saveText, cancelText, client}) => {
    const dispatch = useDispatch();
    const user = useSelector(selectUser)
    const loading = useSelector(isClientsLoading)
    const [crop, setCrop] = useState({x: 0, y: 0})
    const [zoom, setZoom] = useState(1)
    const [croppedAreaPixels, setCroppedAreaPixels] = useState(null)

    const onCropComplete = (croppedArea, croppedAreaPixels) => {
        setCroppedAreaPixels(croppedAreaPixels)
    }

    const saveCroppedImage = async () => {
        try {
            const croppedImage = await getCroppedImg(
                image,
                croppedAreaPixels,
            )
            const imgUrl = await uploadFile(croppedImage, user.id, client.id, 'profilepicture');
            const payload = {
                id: client.id,
                url: imgUrl
            }
            dispatch(updateProfileImage(payload));
            setImage(null)
            handleClose();
        } catch (e) {
            console.error(e)
        }
    }
    const hideCroppedImage = () => {
        setImage(null);
        handleClose();
    }

    return (
        <>
            <div className={'row justify-content-center d-flex'}>
                <div className={'col-12'}>
                    <div className={"cropContainer"}>
                        <Cropper
                            image={image}
                            crop={crop}
                            zoom={zoom}
                            aspect={1}
                            cropShape="round"
                            onCropChange={setCrop}
                            onCropComplete={onCropComplete}
                            onZoomChange={setZoom}
                        />
                    </div>
                </div>
            </div>
            <div className={'row justify-content-center d-flex pt-4'}>
                <div className={'col-12'}>
                    <div className={"d-grid"}>
                        {
                            loading ?
                                <button className={'btn btn-primary-darker disabled'}>{saveText}</button>
                                :
                                <button className={'btn btn-primary-darker'} onClick={saveCroppedImage}>{saveText}</button>
                        }
                    </div>
                </div>
                <div className={'col-12 pt-2'}>
                    <div className={"d-grid"}>
                        {
                            loading ?
                                <button className={'btn btn-link disabled'}>{cancelText}</button>
                                :
                                <button className={'btn btn-link'} onClick={hideCroppedImage}>{cancelText}</button>
                        }
                    </div>
                </div>
            </div>
        </>
    )
}
export default ImageCropper;
