import React, {useEffect, useMemo, useState} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {selectUser} from "../../store/user/userSelector";
import {
    getLastBioimpedance,
    getLoading,
    getSubmitLoading,
    getSubmitResult
} from "../../store/bioimpedance-evaluation/bioimpedanceSelector";
import moment from "moment/moment";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import LoadingBlock from "../../components/loader/LoadingBlock";
import Page from "../../components/page/Page";
import * as Yup from "yup";
import {fetchLastBioimpedance, resetFormSent, saveBioimpedance} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";
import {ErrorMessage, Field, Form, Formik} from "formik";
import EvaluationImageUpload from "../../utils/imageupdate/EvaluationImageUpload";
import {bioProtocol} from "../../utils/physicalEvaluation/protocolData";
import {calculateAge} from "../../utils/date/dateUtils";
import useScrollToError from "../../utils/scrolltoerror/scrollToError";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EvaluationSubmitButton from "../../components/evaluation-components/EvaluationSubmitButton";
import {
    buildBioimpedanceEndRoute,
    buildClientBioimpedanceRoute
} from "../../utils/client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const BioimpedanceCreate = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id, protocol} = useParams();
    const {t} = useTranslation("bioimpedanceEvaluation");
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const user = useSelector(selectUser);
    const lastBioimpedance = useSelector(getLastBioimpedance);
    const submitLoading = useSelector(getSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const [uploadedImages, setUploadedImages] = useState([]);
    const currentClientId = Number(id);
    const studentGender = selectedClient?.sexo?.toUpperCase() === "F" ? "female" : "male";
    const currentProtocol = bioProtocol.find((p) => p.id.toString() === protocol.toString());
    useComponentTranslations('bioimpedanceEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT})

    const today = moment().format("YYYY-MM-DD");
    const nextEval = moment().add(90, "days").format("YYYY-MM-DD");
    const scrollToFirstError = useScrollToError();

    const lastProtocolo = useMemo(
        () => lastBioimpedance
            ? bioProtocol[Number(lastBioimpedance.protocolo)]
            : null,
        [lastBioimpedance]
    );

    const initialValues = useMemo(() => {
        if (!currentProtocol) return {};

        const idadeCalculada = selectedClient?.data_nascimento
            ? calculateAge(selectedClient.data_nascimento)
            : "";

        return currentProtocol.fields.reduce((acc, field) => {
            if (field.id === "data") {
                acc[field.id] = today;
            } else if (field.id === "proximaAvaliacao") {
                acc[field.id] = nextEval;
            } else if (field.id === "idade") {
                acc[field.id] = idadeCalculada;
            } else if (field.id === "proposta") {
                acc[field.id] = studentGender === "male" ? 14 : 20;
            } else {
                acc[field.id] = "";
            }
            return acc;
        }, {});
    }, [currentProtocol, today, nextEval, selectedClient, studentGender]);

    const validationSchema = useMemo(() => {
        if (!currentProtocol) return Yup.object();
        const fieldsSchema = currentProtocol.fields.reduce((acc, field) => {
            if (field.id === "data") {
                const fieldLabel = t(`bioimpedanceEvaluation:fields.${field.labelKey}`);
                acc[field.id] = Yup.string()
                    .required(`${fieldLabel} ${t("bioimpedanceEvaluation:isMandatory")}`)
                    .test(
                        "is-valid-date",
                        `${fieldLabel} ${t("bioimpedanceEvaluation:validDate")}`,
                        (value) => moment(value, "YYYY-MM-DD", true).isValid()
                    );
            } else if (field.section === "Pessoal") {
                const fieldLabel = t(`bioimpedanceEvaluation:fields.${field.labelKey}`);
                acc[field.id] = Yup.number()
                    .typeError(`${fieldLabel} ${t("bioimpedanceEvaluation:mustBeaNumber")}`)
                    .required(`${fieldLabel} ${t("bioimpedanceEvaluation:isMandatory")}`)
                    .positive(`${fieldLabel} ${t("bioimpedanceEvaluation:positiveValue")}`);
            }
            return acc;
        }, {});
        return Yup.object().shape(fieldsSchema);
    }, [currentProtocol, t]);

    const handleSubmit = async (values, formikHelpers) => {
        const errors = await formikHelpers.validateForm(values);
        if (Object.keys(errors).length > 0) {
            scrollToFirstError(errors);
            return;
        }

        const payload = {
            id_aluno: Number(id),
            gender: selectedClient.sexo,
            protocolo: 8,
            idade: Number(values.idade),
            data: values.data,
            estatura: Number(values.estatura),
            peso: Number(values.peso),
            proximaAvaliacao: values.proximaAvaliacao,
            images: uploadedImages,
            ...values
        };
        dispatch(saveBioimpedance(payload, {
            flow: EVALUATION_FLOWS.BIOIMPEDANCE_CREATE,
            clientId: currentClientId
        }));
    }

    const handleGoBackPage = () => {
        navigate(buildClientBioimpedanceRoute(id));
    };

    const handleImagesUpload = (urls) => {
        setUploadedImages(urls);
    };

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(fetchLastBioimpedance({clientId: currentClientId}));
    }, [currentClientId, dispatch]);

    useEffect(() => {
        if (isMatchingSubmitSuccess(submitResult, {
            action: "create",
            flow: EVALUATION_FLOWS.BIOIMPEDANCE_CREATE,
            clientId: currentClientId
        })) {
            navigate(buildBioimpedanceEndRoute(id, submitResult.entityId));
        }
    }, [submitResult, navigate, id, currentClientId]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"card card-body border-0"}>
                    {loading && !currentProtocol &&
                        <div className="text-center mt-4">
                            <LoadingBlock/>
                        </div>
                    }
                    {!loading && (
                        <>
                            <span className={"fw-semibold"}>{t("bioimpedanceEvaluation:bioimpedanceTitle")}</span>
                            <div>
                                <span className={"text-md me-1"}>{t("bioimpedanceEvaluation:lastBioimpedance")}</span>
                                <span className={"text-md"}>
                                {lastProtocolo
                                    ? t(`protocols.${lastProtocolo.translationKey}`)
                                    : lastBioimpedance?.tipo}
                            </span>
                            </div>
                            <Formik
                                initialValues={initialValues}
                                validationSchema={validationSchema}
                                onSubmit={handleSubmit}
                                validateOnChange={true}
                                validateOnBlur={true}
                            >
                                {({errors, touched, submitForm, setTouched, validateForm}) => (
                                    <Form>
                                        <div className={"my-3"}>
                                            <label htmlFor="genero"
                                                   className={"fw-semibold"}>{t("bioimpedanceEvaluation:gender")}</label>
                                            <Field
                                                id="genero"
                                                name="genero"
                                                type={"text"}
                                                value={
                                                    selectedClient?.sexo?.toUpperCase() === 'F'
                                                        ? t("bioimpedanceEvaluation:female")
                                                        : selectedClient?.sexo?.toUpperCase() === 'M'
                                                            ? t("bioimpedanceEvaluation:male")
                                                            : ''
                                                }
                                                className={"form-control bg-white"}
                                                readOnly
                                            />
                                            <span className={"text-md text-danger"}>{t("bioimpedanceEvaluation:changeGender")}</span>
                                        </div>
                                        {Object.entries(
                                            currentProtocol?.fields.reduce((acc, field) => {
                                                const section = field.section || "outros";
                                                if (!acc[section]) acc[section] = [];
                                                acc[section].push(field);
                                                return acc;
                                            }, {})
                                        ).map(([section, fields]) => (
                                            <div key={section} className={"my-2 row"}>
                                                <div className={"row"}>
                                                    {section !== "Pessoal" && (
                                                        <span className={"fw-semibold fs-5 pb-2"}>{section}</span>
                                                    )}
                                                    {section === "Antropometria" && (
                                                        <span
                                                            className={"text-md mb-2"}>{t("bioimpedanceEvaluation:requiredFields")}</span>
                                                    )}
                                                </div>
                                                {fields.map((field) => {
                                                    const showError = Boolean(errors[field.id] && touched[field.id]);
                                                    return (
                                                        <div key={field.id} className={"mb-3"}>
                                                            <label htmlFor={field.id} className={"fw-semibold"}>
                                                                {t(`bioimpedanceEvaluation:fields.${field.labelKey}`)}
                                                            </label>
                                                            {field.type === "number" ? (
                                                                <Field name={field.id}>
                                                                    {({field: inputField, form}) => {
                                                                        const errNum = form.errors[field.id] && form.touched[field.id];
                                                                        return (
                                                                            <>
                                                                                <input
                                                                                    {...inputField}
                                                                                    id={field.id}
                                                                                    type="text"
                                                                                    placeholder={t(`bioimpedanceEvaluation:placeholders.${field.placeholderKey}`)}
                                                                                    className={`form-control${errNum ? " is-invalid" : ""}`}
                                                                                    min={0}
                                                                                    inputMode="decimal"
                                                                                    onKeyDown={(e) => {
                                                                                        if (e.key === '-') {
                                                                                            e.preventDefault();
                                                                                        }
                                                                                    }}
                                                                                    onChange={(e) => {
                                                                                        let value = e.target.value;
                                                                                        value = value.replace(',', '.');
                                                                                        if (!/^(\d+(\.\d*)?)?$/.test(value)) {
                                                                                            return;
                                                                                        }
                                                                                        form.setFieldValue(field.id, value);
                                                                                    }}
                                                                                    onBlur={inputField.onBlur}
                                                                                />
                                                                                <ErrorMessage
                                                                                    name={field.id}
                                                                                    component="div"
                                                                                    className="invalid-feedback"
                                                                                />
                                                                            </>
                                                                        );
                                                                    }}
                                                                </Field>
                                                            ) : field.id === "data" ? (
                                                                <Field name="data">
                                                                    {({field, form}) => {
                                                                        const err = form.errors.data && form.touched.data;
                                                                        return (
                                                                            <>
                                                                                <input
                                                                                    {...field}
                                                                                    id="data"
                                                                                    type="date"
                                                                                    className={`form-control${err ? " is-invalid" : ""}`}
                                                                                    onChange={(e) => {
                                                                                        const selectedDate = e.target.value;
                                                                                        form.setFieldValue("data", selectedDate);

                                                                                        const nextEvalDate = moment(selectedDate)
                                                                                            .add(90, "days")
                                                                                            .format("YYYY-MM-DD");
                                                                                        form.setFieldValue("proximaAvaliacao", nextEvalDate);
                                                                                    }}
                                                                                />
                                                                                <ErrorMessage
                                                                                    name="data"
                                                                                    component="div"
                                                                                    className="invalid-feedback"
                                                                                />
                                                                            </>
                                                                        )
                                                                    }}
                                                                </Field>
                                                            ) : ['objetivo', 'observacao'].includes(field.id) ? (
                                                                <>
                                                                    <Field
                                                                        as="textarea"
                                                                        id={field.id}
                                                                        name={field.id}
                                                                        placeholder={t(`bioimpedanceEvaluation:placeholders.${field.placeholderKey}`)}
                                                                        className={`form-control${showError ? " is-invalid" : ""}`}
                                                                    />
                                                                    <ErrorMessage
                                                                        name={field.id}
                                                                        component="div"
                                                                        className="invalid-feedback"
                                                                    />
                                                                </>
                                                            ) : (
                                                                <Field
                                                                    id={field.id}
                                                                    name={field.id}
                                                                    type={field.type}
                                                                    placeholder={t(`bioimpedanceEvaluation:placeholders.${field.placeholderKey}`)}
                                                                    className={"form-control"}
                                                                    min={0}
                                                                    onKeyDown={(e) => {
                                                                        if (e.key === '-') {
                                                                            e.preventDefault();
                                                                        }
                                                                    }}
                                                                />
                                                            )}
                                                            {lastBioimpedance && lastBioimpedance[field.id] !== undefined && lastBioimpedance[field.id] !== 0 && lastBioimpedance[field.id] !== "" && (
                                                                <span className={"text-md"}>
                                                                 {t("bioimpedanceEvaluation:lastBioimpedance")}{" "}{["data", "proximaAvaliacao"].includes(field.id)
                                                                    ? moment(lastBioimpedance[field.id]).locale("pt-br").format("L")
                                                                    : lastBioimpedance[field.id]}
                                                            </span>
                                                            )}
                                                        </div>
                                                    )
                                                })}
                                            </div>
                                        ))}
                                        <div className={"row"}>
                                            <span
                                                className={"fw-semibold mt-3"}>{t("bioimpedanceEvaluation:photos")}</span>
                                            <span className={"mb-3"}>{t("bioimpedanceEvaluation:addPhotos")}</span>
                                            <EvaluationImageUpload user={user}
                                                                   slots={4}
                                                                   selectedClient={selectedClient}
                                                                   onImagesUpload={handleImagesUpload}
                                                                   existingImages={[]}
                                                                   basePath={"bioimpedanceEvaluation"}
                                                                   Anexar={t("bioimpedanceEvaluation:attach")}
                                            />
                                        </div>
                                        <div className={"mt-3"}>
                                            <EvaluationSubmitButton
                                                type="button"
                                                label={t("bioimpedanceEvaluation:save")}
                                                loadingLabel={t("bioimpedanceEvaluation:save")}
                                                isSubmitting={submitLoading}
                                                onClick={async () => {
                                                    const errs = await validateForm();
                                                    if (Object.keys(errs).length > 0) {
                                                        setTouched(
                                                            Object.keys(errs).reduce((t, key) => ({
                                                                ...t,
                                                                [key]: true
                                                            }), {}),
                                                            false
                                                        );
                                                        setTimeout(() => scrollToFirstError(errs), 0);
                                                    } else {
                                                        submitForm()
                                                    }
                                                }}
                                            />
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                        </>
                    )}
                </div>
            </Page>
        </>
    );
}

export default BioimpedanceCreate;
