import {useNavigate, useParams} from "react-router-dom";
import {useEffect} from "react";
import {useDispatch, useSelector} from "react-redux";
import {fetchClient, setClient} from "../../store/client/clientReducer";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {addToast} from "../../store/toast/toastReducer";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import {handleSendWhatsApp} from "../../utils/handlers/handler";

const ContactConverted = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const {id} = useParams();
    const navigate = useNavigate();
    const client = useSelector(selectSelectedClient)
    const loading = useSelector(isClientsLoading)
    useComponentTranslations('signupLink', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const message = `${t("signupLink:useThisInfo")}\n*${t("signupLink:login")}:* ${client?.mail}\n*${t("signupLink:password")}:* ${client?.senha}`;

    useEffect(() => {
        dispatch(fetchClient(Number(id)));
    }, [dispatch, id]);

    const handleGoBack = () => {
        dispatch(setClient(null))
        navigate("/user/signup-link/2")
    }
    const handleGoToClientClick = () => {
        navigate(`/user/client/${id}`)
    }

    const handleCopyInfo = () => {
        navigator.clipboard.writeText(message)
            .then(() => dispatch(addToast(
                {
                    type: "success",
                    message: `${t("signupLink:copied")}`,
                    title: `${t("signupLink:allDone")}`
                }
            )))
            .catch(err => console.error('Erro ao copiar informações: ', err));
    };

    return (
        <Page goBackLink={handleGoBack} mt={"mt-n4"} loading={loading}>
            {
                client &&

                    <div className={'card card-body'}>
                        <div className={'row justify-content-center'}>
                            <div className={'col-4 text-center '}>
                                <RoundedIcon icon={"fa-paper-plane"} size={"lg"}/>
                            </div>
                            <div className={'col-12 text-center mt-3'}>
                                <span className={"fw-semibold"}>{t("signupLink:informationSent")}</span>
                            </div>
                            <div className={'col-12 text-center mt-3'}>
                                <span>{t("signupLink:informationBellow")}</span>
                            </div>
                            <div className={'col-12 text-center mt-3'}>
                                <div className={'card card-body bg-secondary-subtle border-0 pb-2'}>
                                    <div className={'row justify-content-center'}>
                                        <div className={'col-12'}>
                                            <span className={"d-block"}><span className={"fw-semibold"}>{t("signupLink:login")}:</span> {client.mail}</span>
                                            <span className={"d-block"}><span className={"fw-semibold"}>{t("signupLink:password")}:</span> {client.senha}</span>
                                        </div>
                                        <div className={'col-12 '}>
                                            <button className={'btn btn-link fw-semibold '} onClick={handleCopyInfo}>{t("signupLink:copy")}</button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className={'col-12  mt-3'}>
                                <ul className={'list-group'}>
                                    <li className={'list-group-item border-0 rounded-0 clickable-element border-bottom  bg-white clickable-element'}
                                        onClick={()=>handleSendWhatsApp(client.telefone, message)}>
                                        <div className={'row pb-2'}>
                                            <div className={'col-2 col-lg-1 text-center'}>
                                                <RoundedIcon icon={"fa-whatsapp"} brand={true} size={"xs"}/>
                                            </div>
                                            <div className={'col-8 col-lg-10 align-self-center '}>
                                                <span className={'fw-semibold'}>{t("signupLink:sendToClient")}</span>
                                            </div>
                                            <div className={'col-2 col-lg-1 text-end align-self-center'}>
                                                <i className={'fa-regular fa-chevron-right fa-xl'}></i>
                                            </div>
                                        </div>
                                    </li>
                                    <li className={'list-group-item border-0  rounded-0 clickable-element bg-white clickable-element'}
                                        onClick={handleGoToClientClick}>
                                        <div className={'row pt-2 pb-2'}>
                                            <div className={'col-2 col-lg-1 text-center  '}>
                                                <RoundedIcon icon={"fa-user"} bgColor={"bg-info-light"} size={"xs"}/>
                                            </div>
                                            <div className={'col-8 col-lg-10 align-self-center  '}>
                                                <span className={'fw-semibold'}>{t("signupLink:clientProfile")}</span>
                                            </div>
                                            <div className={'col-2 col-lg-1 text-end align-self-center'}>
                                                <i className={'fa-regular fa-chevron-right fa-xl'}></i>
                                            </div>
                                        </div>
                                    </li>
                                </ul>
                            </div>
                        </div>
                    </div>

            }
        </Page>
    );
}

export default ContactConverted;
