import {takeLatest, all, call, put} from 'redux-saga/effects';

import {handleError} from "../../utils/error/sagaErrorHandling";
import {fetchChatBotSession, messageReceived, onError, rateMessage, sendMessage, setChatBotSession} from "./chatBotReducer";
import {fetchBotSessionAPI, rateMessageAPI, sendMessageToBotAPI} from "../../api/chat-bot/chatBotActions";

export function* fetchChatSessionAsync(action) {
    try {
        const response = yield call(fetchBotSessionAPI, action.payload);
        yield put(setChatBotSession(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchChatSession() {
    yield takeLatest(fetchChatBotSession.type, fetchChatSessionAsync);
}

export function* sendMessageAsync(action) {
    try {
        const response = yield call(sendMessageToBotAPI, action.payload);
        yield put(messageReceived(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onSendMessage() {
    yield takeLatest(sendMessage.type, sendMessageAsync);
}

export function* rateMessageAsync(action) {
    try {
        yield call(rateMessageAPI, action.payload);
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onRateMessage() {
    yield takeLatest(rateMessage.type, rateMessageAsync);
}

export function* chatBotSaga() {
    yield all([
        call(onFetchChatSession),
        call(onSendMessage),
        call(onRateMessage)
    ]);
}