import {useDispatch, useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";
import {
    isClientCountLoading,
    isClientsLoading,
    selectClientCount,
    selectClients,
    selectClientsPagination
} from "../../store/client/clientSelector";
import {useEffect, useState} from "react";
import {fetchUser} from "../../store/user/userReducer";
import {fetchClientCount, fetchClientsPaginated} from "../../store/client/clientReducer";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {useNavigate, useSearchParams} from "react-router-dom";
import ClientDeleteItemList from "../../components/client/ClientDeleteItemList";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import clientEnUS from "../client/locales/en-us.json";
import clientPtBR from "../client/locales/pt-br.json";
import clientEsES from "../client/locales/es-es.json";
import clientPtPT from "../client/locales/pt-pt.json";
import Pagination from "../../components/pagination/Pagination";
import LimitExceededWarning from "../../components/limit-exceeded/LimitExceededWarning";

const ExceededLimit = () => {
    const {t} = useTranslation();
    const [searchParams] = useSearchParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const user = useSelector(selectUser)
    const clients = useSelector(selectClients)
    const clientsPagination = useSelector(selectClientsPagination)
    const loading = useSelector(isClientsLoading);
    const clientCount = useSelector(selectClientCount)
    const clientCountLoading = useSelector(isClientCountLoading);
    const [total, setTotal] = useState(0);
    const [showClientDelete, setShowClientDelete] = useState(false)
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(5);
    const currentItems = clients || [];
    const totalItems = clientsPagination?.totalItems || 0;
    const totalPages = clientsPagination?.totalPages || 0;
    const pagesToShow = 5;
    useComponentTranslations('exceededLimit', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    useComponentTranslations('client', {"en-US": clientEnUS, "pt-BR": clientPtBR, "es-ES": clientEsES, "pt-PT": clientPtPT});

    const handleGoBack = () => {
        if (searchParams.get("deleteClient")) {
            navigate("/subscription?step=1")
        } else
            handleClientDeleteClick();
    }

    const handleSearchChange = (event) => {
        setSearchTerm(event.target.value);
        setCurrentPage(1);
    };

    const handleClientDeleteClick = () => {
        setShowClientDelete(prev => !prev)
    }

    useEffect(() => {
        if (searchParams.get("deleteClient")) {
            setShowClientDelete(true)
        }
    }, [searchParams]);

    useEffect(() => {
        dispatch(fetchUser())
    }, [dispatch]);

    useEffect(() => {
        if (!clientCount) {
            dispatch(fetchClientCount())
        }
    }, [clientCount, dispatch]);

    useEffect(() => {
        if (!user || clientCountLoading || !clientCount) {
            return;
        }

        const total = Number(clientCount.status_0 || 0) + Number(clientCount.status_1 || 0);
        if (total <= user.plano) {
            navigate("/user");
        }
    }, [clientCount, clientCountLoading, navigate, user]);

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 300);

        return () => clearTimeout(handler);
    }, [searchTerm]);

    useEffect(() => {
        if (clientCount) {
            const total = Number(clientCount.status_0 || 0) + Number(clientCount.status_1 || 0);
            setTotal(total)
        }
    }, [clientCount]);

    useEffect(() => {
        if (!showClientDelete) {
            return;
        }

        dispatch(fetchClientsPaginated({
            scope: "nonDeleted",
            page: currentPage,
            pageSize: itemsPerPage,
            search: debouncedSearchTerm
        }));
    }, [clientCount, currentPage, debouncedSearchTerm, dispatch, itemsPerPage, showClientDelete]);

    useEffect(() => {
        if (totalPages > 0 && currentPage > totalPages) {
            setCurrentPage(totalPages);
        } else if (totalPages === 0 && currentPage > 1) {
            setCurrentPage(1);
        }
    }, [currentPage, totalPages]);


    return (
        <Page
            goBackLink={handleGoBack}
            showGoBack={showClientDelete}
            title={t("exceededLimit:limitExceededTitle")}
            loading={!user}
            mt={"mt-n5"}
        >
            {
                !showClientDelete &&
                <div className={'card card-body '}>
                    <div className={'row justify-content-center d-flex '}>
                        <div className={'col-12  mt-4'}>
                            <LimitExceededWarning handleClientDeleteClick={handleClientDeleteClick} total={total}/>
                        </div>
                    </div>
                </div>
            }
            {
                showClientDelete &&
                <div className={'card card-body'}>
                    <div className={'row justify-content-center d-flex '}>
                        <div className={'col-12 col-md-8'}>
                            <div className={'row justify-content-center'}>
                                <div className={'col-12   pb-3'}>
                                    <span className={'fs-5 fw-semibold'}>{t("exceededLimit:currentClients")}</span>
                                </div>
                                <div className={'col-12'}>
                                    {
                                        loading && <LoadingBlock/>
                                    }
                                    {
                                        !loading && (totalItems > itemsPerPage || searchTerm) &&
                                        <div className={'row pb-2'}>
                                            <div className={'col-12'}>
                                                <div className={"input-group"}>
                                                    <input
                                                        className={'form-control'}
                                                        onChange={handleSearchChange}
                                                        value={searchTerm}
                                                        placeholder={t("client:searchClient")}
                                                    />
                                                    <span className={'input-group-text border-right-0'}>
                                                        <i className={'fa-regular fa-magnifying-glass'}></i>
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    }
                                    {
                                        !loading && currentItems.length > 0 &&

                                        <>
                                            <div className={'row '}>
                                                <div className={'col-12'}>
                                                    <ul className={' list-group'}>
                                                        {currentItems.map((client) => (
                                                            <ClientDeleteItemList client={client} key={client.id}/>
                                                        ))}
                                                    </ul>
                                                </div>
                                            </div>
                                        </>

                                    }
                                    {
                                        !loading && searchTerm && currentItems.length === 0 &&
                                        <div className={'row pt-2'}>
                                            <div className={'col-12 text-center text-secondary'}>
                                                <span>{t("client:emptySearchResult")}</span>
                                            </div>
                                        </div>
                                    }
                                </div>
                            </div>
                            {
                                totalItems > itemsPerPage &&
                                <div className={'row justify-content-center pt-3'}>
                                    <div className={'col-12'}>
                                        <Pagination
                                            currentPage={currentPage}
                                            totalItems={totalItems}
                                            itemsPerPage={itemsPerPage}
                                            onPageChange={setCurrentPage}
                                            pagesToShow={pagesToShow}
                                        />
                                    </div>
                                </div>
                            }
                        </div>
                    </div>
                </div>
            }
        </Page>
    )
}
export default ExceededLimit
