import {apiUrl as url, getToken} from "../api";
import axios from "axios";

const apiUrl = url + "/v2";

export const getAllWorkoutsAPI = async (id) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/workout/all?id=${id}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    });
}
