export const getTranslatedQuestion = (question, language) => {
    if (question.questionEnUs) {
        switch (language) {
            case "pt-BR":
                return question.question;
            case "pt-PT":
                return question.questionPtPt;
            case "es-ES":
                return question.questionEsEs;
            default:
                return question.questionEnUs;

        }
    }
    return question.question;

}