import {useEffect} from "react";
import {normalizeAppLocale, SUPPORTED_APP_LOCALES} from "./localeUtils";
import {hasRegisteredNamespace} from "./translationRegistry";

function useComponentTranslations(namespace, translations) {
    useEffect(() => {
        if (
            process.env.NODE_ENV !== "production"
            && namespace
            && !hasRegisteredNamespace(namespace)
        ) {
            console.warn(
                `Missing pre-registered translation namespace "${namespace}". ` +
                "Update the translation manifest generator before relying on this namespace."
            );
        }

        if (process.env.NODE_ENV !== "production" && translations && Object.keys(translations).length > 0) {
            const unexpectedLocales = Object.keys(translations).filter((language) => {
                const normalizedLanguage = normalizeAppLocale(language);
                return (
                    !SUPPORTED_APP_LOCALES.includes(normalizedLanguage)
                    || normalizedLanguage !== language
                );
            });

            if (unexpectedLocales.length > 0) {
                console.warn(`Unexpected translation locales for "${namespace}": ${unexpectedLocales.join(", ")}`);
            }
        }
    }, [namespace, translations]);

    return true;
}

export default useComponentTranslations;
