import {usePersistentGuidedTour} from "../guided-tour"
import {
    buildRetentionDashboardTourSteps,
    RETENTION_TOUR_EXPERIENCE_ID
} from "./retentionTourConfig"

const useRetentionDashboardTour = ({t, isReady, hasClients}) => {
    const labels = {
        next: t("retention:tourNext"),
        previous: t("retention:tourPrevious"),
        done: t("retention:tourDone"),
        skip: t("retention:tourSkip"),
        closeAriaLabel: t("retention:tourCloseAriaLabel")
    }

    const tour = usePersistentGuidedTour({
        experienceId: RETENTION_TOUR_EXPERIENCE_ID,
        steps: buildRetentionDashboardTourSteps({t, hasClients}),
        isReady,
        labels
    })

    return {
        ...tour,
        labels
    }
}

export default useRetentionDashboardTour
