import {useNavigate, useParams} from "react-router-dom";
import {useEffect} from "react";
import Cookies from "js-cookie";
import {getMainDomain} from "../../utils/cookie/cookieUtils";

const RedirectWorkout = () => {
    const {token, sessionId} = useParams();
    const navigate = useNavigate();

    useEffect(() => {
        const mainDomain = getMainDomain();
        Cookies.set('user_token', token, {expires: 400, path: '/', domain: `.${mainDomain}`})
        navigate(`/user/session/${sessionId}`);
    }, [navigate, token, sessionId])

    return (<></>)
}
export default RedirectWorkout;