import {apiUrl, getToken} from "../api";
import axios from "axios";

export const getAllPersonalFinancesAPI = async (startDate, endDate) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/personal-finances/?start_date=${startDate}&end_date=${endDate}`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 8000
    })
}

