import {createSelector} from "reselect";

const reducer = state => state.workoutPrescription;

export const selectWorkoutSession = createSelector(
    [reducer],
    slice => slice.session
)

export const selectWorkoutSessionLoading = createSelector(
    [reducer],
    slice => slice.loading
)

export const selectWorkoutExerciseLoading = createSelector([reducer], slice => slice.exercisesLoading)
export const selectWorkoutLoadingExerciseId = createSelector([reducer], slice => slice.loadingExerciseId)

export const selectWorkoutSeriesUpdating = createSelector([reducer], slice => slice.seriesUpdating)

export const selectWorkoutSeriesUpdated = createSelector([reducer], slice => slice.seriesUpdated)

export const selectWorkoutSeriesReplicated = createSelector([reducer], slice => slice.seriesReplicated)

export const selectWorkoutExerciseReplaced = createSelector([reducer], slice => slice.exerciseReplaced)

export const selectWorkoutDescriptionUpdating = createSelector([reducer], slice => slice.descriptionUpdating)
export const selectWorkoutGenerating = createSelector([reducer], slice=>slice.generatingWorkout)