import {useDispatch} from "react-redux";
import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import {addToast} from "../../store/toast/toastReducer";
import {changeStatus} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const BioimpedanceDeletedCard = ({title, bioimpedance}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    syncMomentLocale(i18n.language);
    useComponentTranslations('bioimpedanceEvaluationComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT})

    const handleUpdate = () => {
        dispatch(changeStatus({id: bioimpedance.id, status: 0}));

        const toastPayload = {
            id: `toast` + bioimpedance.id,
            type: "success",
            title: t("bioimpedanceEvaluationComponent:toastTitle"),
            message: t("bioimpedanceEvaluationComponent:recovered"),
            autohide: true,
            delay: 5000
        };
        dispatch(addToast(toastPayload));
    }

    return (
        <div className={"row pb-2"}>
            <div className={"card"}>
                <div className={"row d-flex align-items-center py-3"}>
                    <div className={"col-10 lh-1 pb-1"}>
                        <span className={"fw-semibold d-block"}>{title}</span>
                        <span className={"text-md fw-semibold me-1"}>{t("bioimpedanceEvaluationComponent:created")}</span>
                        <span className={"text-md"}>{moment(bioimpedance.data).format('L')}</span>
                    </div>
                </div>
                <hr className={"text-secondary my-n1"}/>
                <div className={"col-12 clickable-element text-center"}>
                    <button className={"btn btn-link text-md ps-0 fw-semibold mb-n1"} onClick={handleUpdate}>
                        {t("bioimpedanceEvaluationComponent:recover")}
                    </button>
                </div>
            </div>
        </div>
    )
}

export default BioimpedanceDeletedCard;