import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {ErrorMessage, Field} from "formik";
import React from "react";

const AnamnesisEditQuestion = ({index, onDelete, onUpdate}) => {
    const {t} = useTranslation();
    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    return (
        <div className="row clickable-element pt-2 px-2 ">
            <div className="card card-body">
                <div className="fw-semibold pb-1">{t("anamnesisComponent:viewOrEditQuestion")} {index + 1}:</div>
                <Field
                    name={`questions[${index}].question`}
                    placeholder={`${t('anamnesisComponent:type')}`}
                    className="w-100 mb-1 border rounded py-2 form-control"
                    onBlur={(event) => onUpdate(event.target.value)}
                />
                <ErrorMessage name={`questions[${index}].question`} component="div" className="text-danger"/>
                <hr/>
                <div className="btn btn-link p-0 text-xs text-danger"
                    onClick={() => onDelete(index)}>
                    {t('anamnesisComponent:deleteQuestion')}
                </div>
            </div>
        </div>
    );
};

export default AnamnesisEditQuestion;
