import {useEffect, useState} from "react";
import WorkoutPrescriptionSerie from "./WorkoutPrescriptionSerie";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutPrescriptionAddSerie = ({idExercSession, defaultTipo, isCombinado}) => {
    const {t} = useTranslation();
    useComponentTranslations('workoutPrescriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const [selectedTipo, setSelectedTipo] = useState(
        defaultTipo !== "" ? String(defaultTipo) : ""
    );
    const tipoOptions = [
        {value: 0, label: `${t("workoutPrescriptionComponent:repsWeight")}`},
        {value: 1, label: `${t("workoutPrescriptionComponent:repsWeightTime")}`},
        {value: 2, label: `${t("workoutPrescriptionComponent:repsTime")}`},
        {value: 7, label: `${t("workoutPrescriptionComponent:timeInclination")}`},
        {value: 3, label: `${t("workoutPrescriptionComponent:running")}`},
        {value: 5, label: `${t("workoutPrescriptionComponent:obs")}`},
        {value: 8, label: `${t("workoutPrescriptionComponent:cadence")}`},
        {value: 6, label: `${t("workoutPrescriptionComponent:exercise")}`},
    ];
    const filteredTipoOptions = isCombinado
        ? tipoOptions
        : tipoOptions.filter(opt => opt.value !== 6);

    const handleTipoChange = e => {
        setSelectedTipo(e.target.value);
    };

    const newSerie = {
        id: 0,
        idExercSession: Number(idExercSession),
        repeticao: "",
        carga: "",
        velocidade: "",
        distancia: "",
        tempo: "",
        cadencia: "",
        obs: "",
        intervalo: "",
        pace: "",
        inclinacao: "",
        idExerc: 0,
        tipo: Number(selectedTipo),
    };

    useEffect(() => {
        setSelectedTipo(defaultTipo !== "" ? String(defaultTipo) : "");
    }, [defaultTipo]);

    return (
        <div className={"row"}>
            <div className={"col-12"}>
                <select
                    id="tipoSerie"
                    className="form-select"
                    value={selectedTipo}
                    onChange={handleTipoChange}
                >
                    <option value="">Selecione</option>
                    {filteredTipoOptions.map((opt) => (
                        <option key={opt.value} value={opt.value}>
                            {opt.label}
                        </option>
                    ))}
                </select>
                {selectedTipo !== "" && (
                    <div className={"row justify-content-center mt-3"}>
                        <div className={"col-12"}>
                            <WorkoutPrescriptionSerie
                                serie={newSerie}
                                onSaved={() => {
                                    setSelectedTipo("");
                                }}
                            />
                        </div>
                    </div>
                )}
            </div>
        </div>
    )
}

export default WorkoutPrescriptionAddSerie;