
export const truncateContent = (content, isExpanded, charLimit) => {
    if (!content) return content;
    if (typeof content === 'object' && content.message) {
        const truncatedMessage =
            !isExpanded && content.message.length > charLimit
                ? content.message.substring(0, charLimit) + '...'
                : content.message;
        return { ...content, message: truncatedMessage };
    }
    if (typeof content === 'string') {
        return !isExpanded && content.length > charLimit
            ? content.substring(0, charLimit) + '...'
            : content;
    }
    return content;
};
