import {apiUrl, getToken} from "../api";
import axios from "axios";

export const fetchFrequencyAPI = async (start, end, type) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/client-report/?start=${start}&end=${end}&type=${type}`, {
        headers:{
            'Content-Type': "application/json",
            'authorization': token
        },
        timeout: 20000
    })
}
