import { createSlice } from "@reduxjs/toolkit";
import {
    createErrorSubmitResult,
    createPendingSubmitResult,
    createSubmitResult,
    createSuccessSubmitResult
} from "../../utils/evaluation/mutationState";

const initialState = {
    customEvaluation: null,
    customList: [],
    customModelsList: [],
    customModel: null,
    compareList: [],
    initialLoading: false,
    submitLoading: false,
    submitResult: createSubmitResult(),
    error: null,
    imageLoading: false
}

export const slice = createSlice( {
    name: "customEvaluation",
    initialState,
    reducers: {
        getAllCustom(state) {
            state.initialLoading = true;
        },
        setAllCustom(state, action) {
            state.initialLoading = false;
            state.customList = action.payload;
        },
        getAllCustomModels(state) {
            state.initialLoading = true;
        },
        setAllCustomModels(state, action) {
            state.customModelsList = action.payload;
            state.initialLoading = false;
        },
        getOneCustom(state) {
            state.initialLoading = true;
        },
        setOneCustom(state, action) {
            state.customEvaluation = action.payload;
            state.initialLoading = false;
        },
        compareCustom(state) {
            state.initialLoading = true;
        },
        setCompareCustom(state, action) {
            state.initialLoading = false;
            state.compareList = action.payload;
        },
        changeCustomStatus: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: action.payload?.status === 1 ? "delete" : "recover",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        setChangeCustomStatus(state, action) {
            state.customModelsList = state.customModelsList
                .filter(model => model.id !== action.payload);
        },
        changeStatus: {
            reducer(state, action){
          state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: action.payload?.status === 1 ? "delete" : "recover",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
          state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        setChangeStatus(state, action) {
            state.customList = state.customList
                .filter(custom => custom.id !== action.payload);
        },
        saveCustom: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "create",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        resetFormSent(state) {
            state.submitLoading = false;
            state.submitResult = createSubmitResult();
            state.error = null;
        },
        getOneModel(state) {
            state.initialLoading = true;
        },
        setOneModel(state, action) {
            state.customModel = action.payload;
            state.initialLoading = false;
        },
        editModel: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "update",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        setEditModel(state, action) {
            state.customEvaluation = action.payload;
        },
        answerCustom: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "create",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        setAnswerCustom(state, action) {
            state.customEvaluation = action.payload;
        },
        editAnsweredCustom: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "update",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        setEditAnsweredCustom(state, action) {
            state.customEvaluation = action.payload;
        },
        setSubmitResult(state, action) {
            state.submitLoading = false;
            state.submitResult = createSuccessSubmitResult(action.payload);
            state.error = null;
        },
        setImageUploadingStatus(state, action) {
            state.imageLoading = action.payload;
        },
        onError(state, action) {
            state.initialLoading = false;
            if (state.submitLoading) {
                state.submitResult = createErrorSubmitResult(state.submitResult, action.payload);
            }
            state.submitLoading = false;
            state.error = action.payload;
        }
    }
})

export const {
    getAllCustom,
    setAllCustom,
    getAllCustomModels,
    setAllCustomModels,
    getOneCustom,
    setOneCustom,
    compareCustom,
    setCompareCustom,
    changeCustomStatus,
    setChangeCustomStatus,
    changeStatus,
    setChangeStatus,
    saveCustom,
    getOneModel,
    setOneModel,
    editModel,
    setEditModel,
    answerCustom,
    setAnswerCustom,
    editAnsweredCustom,
    setEditAnsweredCustom,
    setSubmitResult,
    setImageUploadingStatus,
    onError,
    resetFormSent
} = slice.actions;

export const customEvaluationReducer = slice.reducer;
