import {apiUrl, getToken} from "../api";
import axios from "axios";

export const sendMessageToBotAPI = async (data) => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/user/chat/`, data,
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 20000
        })
}
export const rateMessageAPI = async (data) => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/user/chat/rate`, data,
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 20000
        })
}

export const fetchBotSessionAPI = async (sessionId) => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/chat/?sessionId=${sessionId}`,
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 20000
        })
}