import React, {useCallback, useEffect, useState} from "react";
import _ from "lodash";
import WorkoutSeries from "./WorkoutSeries";
import WorkoutExerciseCompleted from "./WorkoutExerciseCompleted";
import {useSelector} from "react-redux";
import moment from "moment/moment";
import Cookies from "js-cookie";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/workout-session/locales/en-us.json";
import ptBR from "../../pages/workout-session/locales/pt-br.json";
import esES from "../../pages/workout-session/locales/es-es.json";
import ptPT from "../../pages/workout-session/locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import WorkoutExerciseMultipleSingular from "./WorkoutExerciseMultipleSingular";
import Text from "../utils/emoji/Text";
import {getPreview} from "../../store/workout-session/workoutSessionSelector";

const WorkoutExerciseMultiple = ({exerc, mainId}) => {
    const {t} = useTranslation();
    const [exercise] = useState(exerc.exercises[0]);
    const [exercs, setExercs] = useState([]);
    const [distributedSeries, setDistributedSeries] = useState(false);
    const [lastExerc, setLastExerc] = useState(null)
    const [completed, setCompleted] = useState(null);
    const preview = useSelector(getPreview);
    const [standaloneObsSeries, setStandaloneObsSeries] = useState([]);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const handleCompleted = () => {
        setCompleted(prevCompleted => !prevCompleted);
    }

    const seriesMap = useCallback(() => {
        const newArray = [];
        let exerciseItem = null;
        const generalObservations = [];
        exercise.series.forEach((serie) => {
            if (serie.exercicio) {
                if (exerciseItem) {
                    newArray.push(exerciseItem);
                }
                exerciseItem = {...serie, exercicio: {...serie.exercicio, series: []}};
            } else if (serie.tipo === 5) {
                if (exerciseItem) {
                    exerciseItem.exercicio.series.push({...serie});
                } else {
                    generalObservations.push({...serie});
                }
            } else if (exerciseItem) {
                exerciseItem.exercicio.series.push({...serie});
            }
        });

        if (exerciseItem) {
            newArray.push(exerciseItem);
        }

        const distributed = newArray.some((exerc) => exerc.exercicio.series.length > 0);
        setDistributedSeries(distributed);
        setExercs(newArray);
        setStandaloneObsSeries(generalObservations);
    }, [exercise]);


    useEffect(() => {
        if (exercs.length === 0)
            seriesMap();
        else
            setLastExerc(exercs[exercs.length - 1])
    }, [seriesMap, exercs, setLastExerc])


    useEffect(() => {
        if (completed != null)
            if (completed) {
                const expirationDate = moment().add(2, 'hour');
                Cookies.set('exercise_' + mainId, 'true', {expires: expirationDate.toDate()});
            } else {
                Cookies.remove('exercise_' + mainId);
            }
    }, [completed, exercise, mainId]);

    useEffect(() => {
        if (Cookies.get('exercise_' + mainId))
            setCompleted(true)
    }, [mainId])
    return (
        <>
            {
                distributedSeries &&
                <div className={'card card-body card-no-border'}>
                    <div className={'row    d-flex  '}>
                        {
                            !preview &&
                            <div className={'col-1 align-self-center ps-2'}>
                                <WorkoutExerciseCompleted handleCompleted={handleCompleted}
                                                          completed={completed}/>
                            </div>
                        }
                        <div className={`col-${completed ? '11' : `10  `}  align-self-center `}>
                            <span className={'d-block fw-bold  text-md'} style={{lineHeight: "1.1rem"}}>
                                 {t("workout:combined")}
                            </span>
                            {
                                !completed &&
                                <span className={'d-block small'}>{t("workout:combinedMessage")}</span>
                            }
                        </div>
                    </div>
                    <div className={`pt-3 swipeable ${completed ? "d-none" : ''} `}>
                        {_.map(exercs, (exerc, index) => (
                            <div className={'col-10 card-swipeable  '} key={exerc.id}>
                                <div className={'card card-body   pb-0'} style={{height: "100%"}}>
                                    <WorkoutExerciseMultipleSingular exerc={exerc} index={index}/>
                                </div>
                            </div>
                        ))}
                    </div>
                    {
                        standaloneObsSeries.length > 0 &&
                        <div className={`pt-3 ${completed ? "d-none" : ''} `}>
                            <span className={'fw-semibold '}>{t("workout:instructions")}:</span>
                            {standaloneObsSeries.map((obsSerie) => (
                                <pre
                                    key={obsSerie.id}
                                    className={'mb-1 text-md '}
                                    style={{
                                        lineHeight: 1.2,
                                        height: "100%",
                                        overflow: "hidden"
                                    }}><Text enableAccessibility={true}>{obsSerie.obs?.trim()}</Text></pre>
                            ))}
                        </div>
                    }
                </div>
            }
            {
                !distributedSeries &&
                <div className={'card card-body card-no-border'}>
                    <div className={'row  d-flex'}>
                        {
                            !preview &&
                            <div className={'col-1 align-self-center ps-2'}>
                                <WorkoutExerciseCompleted handleCompleted={handleCompleted}
                                                          completed={completed}/>
                            </div>
                        }
                        <div className={`col-${completed ? '11' : `10  `}  align-self-center `}>
                            <span className={' fw-bold  d-block'}>{t("workout:combined")}</span>
                            {
                                !completed &&
                                <span className={'d-block  small fw-bold'}>{t("workout:combinedMessage")}</span>
                            }
                        </div>
                    </div>
                    <div className={`pt-3 swipeable ${completed ? 'd-none' : ''}`}>
                        {
                            _.map(exercs, (exerc, index) => (
                                exerc.exercicio &&
                                <div className={'col-10 card-swipeable'} key={exerc.id}>
                                    <div className={'card card-body   pb-0'}
                                         style={{height: "100%"}}>
                                        <WorkoutExerciseMultipleSingular showSeries={false}
                                                                         exerc={exerc}
                                                                         index={index}/>
                                    </div>
                                </div>
                            ))
                        }
                    </div>
                    <div className={`row justify-content-center d-flex pt-2 ${completed ? 'd-none' : ''}`}>
                        {_.map(lastExerc?.exercicio?.series, (serie, index) => (
                            <div className={'col-12'} key={serie.id}>
                                <WorkoutSeries serie={serie}/>
                                {
                                    lastExerc?.exercicio?.series.length - 1 !== index &&
                                    <hr className={'mb-1 mt-2 '}/>
                                }
                            </div>
                        ))}
                    </div>
                    {
                        standaloneObsSeries.length > 0 &&
                        <div className={`pt-3 ${completed ? "d-none" : ''} `}>
                            <span className={'fw-semibold '}>{t("workout:instructions")}:</span>
                            {standaloneObsSeries.map((obsSerie) => (
                                <pre
                                    key={obsSerie.id}
                                    className={'mb-1 text-md '}
                                    style={{
                                        lineHeight: 1.2,
                                        height: "100%",
                                        overflow: "hidden"
                                    }}><Text>{obsSerie.obs?.trim()}</Text></pre>
                            ))}
                        </div>
                    }
                </div>
            }
        </>
    )
}
export default WorkoutExerciseMultiple;