import React, {useState, useEffect} from 'react';
import {useTranslation} from 'react-i18next';
import {useSelector} from 'react-redux';
import {selectExerciseFavorites, selectUserExercises}
    from '../../store/exercise-library/exerciseLibrarySelector';
import {transformExercise} from '../../utils/workout/Exercise';
import ExerciseSearchBox from './ExerciseSearchBox';
import ExerciseLibraryActionButtons from './ExerciseLibraryActionButtons';
import ExerciseHit from './ExerciseHit';
import ExerciseLibraryPagination from './ExerciseLibraryPagination';
import SearchableExerciseList from './SearchableExerciseList';
import {useExerciseSearch} from "../../utils/workout/useExerciseSearch";
import EmptySet from "../empty-set/EmptySet";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";


export default function ExerciseInstantSearch({
                                                  type,
                                                  addedExercises,
                                                  isReplace,
                                                  isSerieReplace,
                                                  isAddExerciseAsSerie,
                                                  handleReplace
                                              }) {
    const {t, i18n} = useTranslation();
    const locale = i18n.language.startsWith('pt-PT') ? 'pt-PT'
        : i18n.language.startsWith('pt-BR') ? 'pt-BR'
            : i18n.language.startsWith('es') ? 'es-ES'
                : 'en-US';

    const [show, setShow] = useState('all');
    const [query, setQuery] = useState('');
    const [groupFilter, setGroupFilter] = useState('');
    const [categoryFilter, setCategoryFilter] = useState('');
    const [page, setPage] = useState(1);
    const hitsPerPage = 20;
    const favorites = useSelector(selectExerciseFavorites) || [];
    const userExercises = useSelector(selectUserExercises) || [];
    useComponentTranslations("exerciseLibraryComponent", {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT,
    });
    useEffect(() => {
        if (type === 'favorites') setShow('favorites');
        else if (type === 'user') setShow('user');
        else setShow('all');
    }, [type]);

    useEffect(() => setPage(1), [query, show, groupFilter, categoryFilter, locale]);

    const doBackend = ['all', 'group', 'category'].includes(show);

    const effectiveQuery =
        show === 'all' && query.trim() === ''
            ? '*'
            : query;

    const {
        results: backendHits,
        loading,
        totalPages
    } = useExerciseSearch(
        effectiveQuery,
        locale,
        page,
        hitsPerPage,
        groupFilter,
        categoryFilter
    );

    const normalize = str =>
        str.toLowerCase()
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .trim();

    const filteredFavorites = favorites.filter(ex => {
        const name = transformExercise(ex).nome || '';
        return normalize(name).includes(normalize(query));
    });

    const filteredUser = userExercises.filter(ex => {
        const name = transformExercise(ex).nome || '';
        return normalize(name).includes(normalize(query));
    });

    return (
        <>
            <div className="row justify-content-center mt-2" >
                <div className="col-12 overflow-auto h-100">
                    {doBackend ? (
                        <>
                            <div className="row justify-content-center">
                                <div className="col-12 mt-1">
                                    <ExerciseSearchBox
                                        value={query}
                                        onChange={setQuery}
                                    />
                                </div>
                                <div className="col-12 mb-3">
                                    <ExerciseLibraryActionButtons
                                        show={show}
                                        onFavoritesClick={() => {
                                            setShow('favorites');
                                            setGroupFilter('');
                                            setCategoryFilter('');
                                        }}
                                        onUserExercisesClick={() => {
                                            setShow('user');
                                            setGroupFilter('');
                                            setCategoryFilter('');
                                        }}
                                        onAllClick={() => {
                                            setShow('all');
                                            setGroupFilter('');
                                            setCategoryFilter('');
                                        }}
                                        onGroupFilterClick={f => {
                                            setShow('group');
                                            setGroupFilter(f);
                                        }}
                                        onCategoryFilterClick={c => {
                                            setShow('category');
                                            setCategoryFilter(c);
                                        }}
                                        groupFilter={groupFilter}
                                        categoryFilter={categoryFilter}
                                    />
                                </div>
                            </div>
                            {loading ? (
                                <></>
                            ) : backendHits.length ? (
                                backendHits.map(hit => (
                                    <ExerciseHit
                                        key={hit.objectID}
                                        hits={[hit]}
                                        addedExercises={addedExercises}
                                        handleReplace={handleReplace}
                                        isReplace={isReplace}
                                        isSerieReplace={isSerieReplace}
                                        isAddExerciseAsSerie={isAddExerciseAsSerie}
                                    />
                                ))
                            ) : (
                                <EmptySet icon={"fa-empty-set"} message={t("exerciseLibraryComponent:noHits")}/>
                            )}
                        </>
                    ) : show === 'favorites' ? (
                        <SearchableExerciseList
                            query={query}
                            onQueryChange={setQuery}
                            exercises={filteredFavorites}
                            show="favorites"
                            onFavoritesClick={() => setShow('favorites')}
                            onAllClick={() => setShow('all')}
                            onUserExercisesClick={() => setShow('user')}
                            onGroupFilterClick={() => setShow('group')}
                            onCategoryFilterClick={() => setShow('category')}
                            selectedGroup={groupFilter}
                            setSelectedGroup={setGroupFilter}
                            selectedCategory={categoryFilter}
                            setSelectedCategory={setCategoryFilter}
                            addedExercises={addedExercises}
                            handleReplace={handleReplace}
                            isReplace={isReplace}
                            isSerieReplace={isSerieReplace}
                            isAddExerciseAsSerie={isAddExerciseAsSerie}
                        />
                    ) : (
                        <SearchableExerciseList
                            query={query}
                            onQueryChange={setQuery}
                            exercises={filteredUser}
                            show="user"
                            onFavoritesClick={() => setShow('favorites')}
                            onAllClick={() => setShow('all')}
                            onUserExercisesClick={() => setShow('user')}
                            onGroupFilterClick={() => setShow('group')}
                            onCategoryFilterClick={() => setShow('category')}
                            selectedGroup={groupFilter}
                            setSelectedGroup={setGroupFilter}
                            selectedCategory={categoryFilter}
                            setSelectedCategory={setCategoryFilter}
                            addedExercises={addedExercises}
                            handleReplace={handleReplace}
                            isReplace={isReplace}
                            isSerieReplace={isSerieReplace}
                            isAddExerciseAsSerie={isAddExerciseAsSerie}
                        />
                    )}
                </div>
            </div>
            {doBackend &&  totalPages > 1 && (
                <div className="row justify-content-center mt-3">
                    <div className="col-12">
                        <ExerciseLibraryPagination
                            page={page}
                            totalPages={totalPages}
                            onPageChange={setPage}
                        />
                    </div>
                </div>
            )}
        </>
    );
}
