import {getToken} from "../../api/api";
import Cookies from "js-cookie";

export const mfitUrl = process.env.NODE_ENV === 'production' ? "https://www.mfitpersonal.com.br" : "http://localhost:8080/MFITPersonalWebApp/";

export const handleWhatsAppClick = (text) => {
    window.open(`https://api.whatsapp.com/send/?phone=${text.replace("+", "")}`, "_blank")
}

export const handleSubscriptionButton = (navigate, step) => {
    if (Cookies.get("isApple")) {
        window.location.href = `${mfitUrl}/index?acao=inAppPurchase`
    } else {
        navigate(`/subscription${step ? `?step=${step}` : ""}`);
    }
}

export const handleBlogClick = () => {
    window.open("https://blog.mfitpersonal.com.br/", '_blank');
}
