export const handleSendWhatsApp = (telefone, message) => {
    if (telefone)
        window.open(`https://api.whatsapp.com/send?phone=${telefone.replace("+", "")}&text=${encodeURIComponent(message)}`, '_blank');
    else
        window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`, '_blank');
}

export const handleGoToPhysicalEvaluationClick = (clientId) => {
    window.location.href = `${mfitUrl}/index?acao=physicalEvaluation&tipo=1&al=${clientId}&goBackToNewAppClientEval=${clientId}`
}

