import React, {useEffect} from 'react';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useNavigate, useParams} from "react-router-dom";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useDispatch, useSelector} from "react-redux";
import {fetchClient} from "../../store/client/clientReducer";
import {createWorkoutRoutine, setWorkoutCreated} from "../../store/workout-routine/workoutRoutineReducer";
import {selectWorkoutCreated, selectWorkoutRoutine, selectWorkoutRoutineLoading} from "../../store/workout-routine/workoutRoutineSelector";
import {useTranslation} from "react-i18next";
import TextareaAutosize from 'react-textarea-autosize';
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutRoutineCreate = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {clientId} = useParams();
    const client = useSelector(selectSelectedClient)
    const isLibrary = Number(clientId) === 0;
    const workoutCreated = useSelector(selectWorkoutCreated);
    const workout = useSelector(selectWorkoutRoutine)
    const loading = useSelector(selectWorkoutRoutineLoading)
    useComponentTranslations('workoutRoutine', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        if (clientId > 0) {
            navigate(`/user/client/${clientId}/workout`)
        } else {
            navigate(`/user/workout-library`)
        }
    }

    const schemaFields = {
        routineName: Yup.string().max(245, t("workoutRoutine:maxChars")).required(t("workoutRoutine:required")),
        trainingType: Yup.string().required(t("workoutRoutine:required")),
        goal: Yup.string().required(t("workoutRoutine:required")),
        difficulty: Yup.string().required(t("workoutRoutine:required")),
        allowPdfDownload: Yup.string().required(t("workoutRoutine:required")),
        showTrainingTime: Yup.string().required(t("workoutRoutine:required")),
    };

    if (!isLibrary) {
        schemaFields.startDate = Yup.date().required(t("workoutRoutine:required"));
        schemaFields.endDate = Yup.date().required(t("workoutRoutine:required"));
    }

    const validationSchema = Yup.object().shape(schemaFields);

    const handleSubmit = (values) => {
        dispatch(createWorkoutRoutine(values))
    }

    useEffect(() => {
        if ((!client || client.id !== Number(clientId)) && !isLibrary)
            dispatch(fetchClient(clientId));

    }, [dispatch, clientId, client, isLibrary]);

    useEffect(() => {
        if (workoutCreated) {
            dispatch(setWorkoutCreated(false))
            navigate(`/user/client/${clientId}/workout/routine/${workout?.id}`)
        }
    }, [workoutCreated, navigate, clientId, workout, dispatch]);


    return (
        <>
            {
                !isLibrary &&
                <AvatarHeader className={"pb-4 pt-2"}
                              text={`${client?.nome} ${client?.sobrenome}`}
                              url={client?.profileUrl} showGoBack={handleGoBack}/>
            }
            <Page contentHeader={isLibrary} title={`${isLibrary && t("workoutRoutine:createWorkout")}`} mt={`${isLibrary ? "mt-n5" : "mt-n4"}`}
                  goBackLink={handleGoBack}>
                <div className={"row justify-content-center"}>
                    <div className={'col-12'}>
                        <div className={'card card-body border-0'}>
                            <Formik
                                initialValues={{
                                    id: 0,
                                    status: 0,
                                    clientId: client?.id || 0,
                                    routineName: '',
                                    trainingType: '',
                                    goal: '',
                                    difficulty: '',
                                    instructions: '',
                                    allowPdfDownload: '',
                                    showTrainingTime: '',
                                    startDate: '',
                                    endDate: '',
                                    removeAfterExpiration: false,
                                    hideBeforeStart: false
                                }}
                                validationSchema={validationSchema}
                                onSubmit={handleSubmit}
                            >
                                {({errors, touched}) => (
                                    <Form>
                                        <div className="mb-3">
                                            <label htmlFor="routineName" className=" form-label  fw-semibold">{t("workoutRoutine:workoutName")}</label>
                                            <Field
                                                name="routineName"
                                                type="text"
                                                className={`form-control ${errors.routineName && touched.routineName ? 'is-invalid' : ''}`}
                                            />
                                            <ErrorMessage name="routineName" component="div" className="invalid-feedback"/>
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="trainingType" className=" form-label  fw-semibold">{t("workoutRoutine:workoutType")}</label>
                                            <Field
                                                as="select"
                                                name="trainingType"
                                                className={`form-control ${errors.trainingType && touched.trainingType ? 'is-invalid' : ''}`}
                                            >
                                                <option value="">{t("workoutRoutine:select")}</option>
                                                <option value="1">{t("workoutRoutine:weekDay")}</option>
                                                <option value="2">{t("workoutRoutine:numeric")}</option>
                                            </Field>
                                            <ErrorMessage name="trainingType" component="div" className="invalid-feedback"/>
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="goal" className=" form-label fw-semibold">{t("workoutRoutine:objective")}</label>
                                            <Field
                                                as="select"
                                                name="goal"
                                                className={`form-control ${errors.goal && touched.goal ? 'is-invalid' : ''}`}
                                            >
                                                <option value="">{t("workoutRoutine:select")}</option>
                                                <option value="1">{t("workoutRoutine:hypertrophy")}</option>
                                                <option value="2">{t("workoutRoutine:fatReduction")}</option>
                                                <option value="3">{t("workoutRoutine:fatReductionHypertrophy")}</option>
                                                <option value="4">{t("workoutRoutine:definition")}</option>
                                                <option value="5">{t("workoutRoutine:conditioning")}</option>
                                                <option value="6">{t("workoutRoutine:lifeQuality")}</option>
                                            </Field>
                                            <ErrorMessage name="goal" component="div" className="invalid-feedback"/>
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="difficulty" className=" form-label fw-semibold">{t("workoutRoutine:difficulty")}</label>
                                            <Field
                                                as="select"
                                                name="difficulty"
                                                className={`form-control ${errors.difficulty && touched.difficulty ? 'is-invalid' : ''}`}
                                            >
                                                <option value="">{t("workoutRoutine:select")}</option>
                                                <option value="4">{t("workoutRoutine:adaptation")}</option>
                                                <option value="1">{t("workoutRoutine:starter")}</option>
                                                <option value="2">{t("workoutRoutine:intermediary")}</option>
                                                <option value="3">{t("workoutRoutine:advanced")}</option>
                                            </Field>
                                            <ErrorMessage name="difficulty" component="div" className="invalid-feedback"/>
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="instructions" className=" form-label fw-semibold">{t("workoutRoutine:generalInstructions")}</label>

                                            <Field name="instructions">
                                                {({field}) => (
                                                    <TextareaAutosize
                                                        {...field}
                                                        className="form-control"
                                                        rows={3}
                                                        minRows={3}
                                                        placeholder={t("workoutRoutine:generalInstructions")}

                                                    />
                                                )}
                                            </Field>
                                        </div>
                                        <div className="mb-3">
                                            <label className=" form-label fw-semibold">{t("workoutRoutine:allowPdf")}</label>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="allowPdfDownload"
                                                    value="true"
                                                    id="allowPdfDownloadSim"
                                                    className="form-check-input"
                                                />
                                                <label htmlFor="allowPdfDownloadSim" className="form-check-label">{t("workoutRoutine:yes")}</label>
                                            </div>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="allowPdfDownload"
                                                    value="false"
                                                    id="allowPdfDownloadNao"
                                                    className="form-check-input"
                                                />
                                                <label htmlFor="allowPdfDownloadNao" className="form-check-label">{t("workoutRoutine:no")}</label>
                                            </div>
                                            <ErrorMessage name="allowPdfDownload" component="div" className="invalid-feedback d-block"/>
                                        </div>
                                        <div className="mb-3">
                                            <label className=" form-label fw-semibold">{t("workoutRoutine:showTimer")}</label>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="showTrainingTime"
                                                    value="true"
                                                    id="showTrainingTimeSim"
                                                    className="form-check-input"
                                                />
                                                <label htmlFor="showTrainingTimeSim" className="form-check-label">{t("workoutRoutine:yes")}</label>
                                            </div>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="showTrainingTime"
                                                    value="false"
                                                    id="showTrainingTimeNao"
                                                    className="form-check-input"
                                                />
                                                <label htmlFor="showTrainingTimeNao" className="form-check-label">{t("workoutRoutine:no")}</label>
                                            </div>
                                            <ErrorMessage name="showTrainingTime" component="div" className="invalid-feedback d-block"/>
                                        </div>
                                        {
                                            !isLibrary &&
                                            <>
                                                <div className="mb-3">
                                                    <label htmlFor="startDate" className=" form-label fw-semibold">{t("workoutRoutine:startsAt")}</label>
                                                    <Field
                                                        name="startDate"
                                                        type="date"
                                                        className={`form-control ${errors.startDate && touched.startDate ? 'is-invalid' : ''}`}
                                                    />
                                                    <ErrorMessage name="startDate" component="div" className="invalid-feedback"/>
                                                </div>
                                                <div className="mb-3">
                                                    <label htmlFor="endDate" className=" form-label fw-semibold">{t("workoutRoutine:endsAt")}</label>
                                                    <Field
                                                        name="endDate"
                                                        type="date"
                                                        className={`form-control ${errors.endDate && touched.endDate ? 'is-invalid' : ''}`}
                                                    />
                                                    <ErrorMessage name="endDate" component="div" className="invalid-feedback"/>
                                                </div>
                                                <div className="mb-3 form-check">
                                                    <Field
                                                        type="checkbox"
                                                        name="removeAfterExpiration"
                                                        id="removeAfterExpiration"
                                                        className="form-check-input"
                                                    />
                                                    <label htmlFor="removeAfterExpiration" className="form-check-label fw-semibold">
                                                        {t("workoutRoutine:removeExpired")}
                                                    </label>
                                                </div>
                                                <div className="mb-3 form-check">
                                                    <Field
                                                        type="checkbox"
                                                        name="hideBeforeStart"
                                                        id="hideBeforeStart"
                                                        className="form-check-input"
                                                    />
                                                    <label htmlFor="hideBeforeStart" className="form-check-label fw-semibold">
                                                        {t("workoutRoutine:showAtStart")}
                                                    </label>
                                                </div>
                                            </>
                                        }
                                        <button type="submit" className="btn btn-primary w-100" disabled={loading}>{t("workoutRoutine:save")}</button>
                                    </Form>
                                )}
                            </Formik>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default WorkoutRoutineCreate;
