import {createSelector} from "reselect";

const reducer = state => state.clientGroup;
export const selectClientGroups = createSelector([reducer], slice => slice.groups);
export const selectClientsFromGroup = createSelector([reducer], slice => slice.groupClients);
export const selectGroupClients = createSelector([reducer], slice => slice.groupClients);
export const selectUngroupedClients = createSelector([reducer], slice => slice.ungroupedClients);
export const selectUngroupedFilters = createSelector([reducer], slice => slice.ungroupedFilters);
export const selectUngroupedPagination = createSelector([reducer], slice => slice.ungroupedPagination);
export const selectUngroupedCount = createSelector([reducer], slice => slice.ungroupedCount);
export const selectCreatedClientGroup = createSelector([reducer], slice => slice.createdGroup);
export const selectClientGroupGroupsLoading = createSelector([reducer], slice => slice.groupsLoading);
export const selectClientGroupGroupClientsLoading = createSelector([reducer], slice => slice.groupClientsLoading);
export const selectClientGroupUngroupedLoading = createSelector([reducer], slice => slice.ungroupedLoading);
export const selectClientGroupMutationLoading = createSelector([reducer], slice => slice.mutationLoading);
export const selectClientGroupLoading = createSelector(
    [
        selectClientGroupGroupsLoading,
        selectClientGroupGroupClientsLoading,
        selectClientGroupUngroupedLoading,
        selectClientGroupMutationLoading
    ],
    (groupsLoading, groupClientsLoading, ungroupedLoading, mutationLoading) =>
        groupsLoading || groupClientsLoading || ungroupedLoading || mutationLoading
);
