import {useTranslation} from "react-i18next";
import AppOffcanvasShell from "../offcanvas/AppOffcanvasShell";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import WorkoutPresetPreviewContent from "./WorkoutPresetPreviewContent";
import pageEnUS from "../../pages/workout-preset/locales/en-us.json";
import pagePtBR from "../../pages/workout-preset/locales/pt-br.json";
import pageEsES from "../../pages/workout-preset/locales/es-es.json";
import pagePtPT from "../../pages/workout-preset/locales/pt-pt.json";

const WorkoutPresetPreviewOffcanvas = ({
    show,
    onHide,
    preset,
    onEdit,
    onDeleteClick,
    canDelete = false
}) => {
    const {t} = useTranslation();
    const canDeletePreset = Boolean(preset) && Number(preset.userId) !== 0 && canDelete;

    useComponentTranslations("workoutPresetPage", {"en-US": pageEnUS, "pt-BR": pagePtBR, "es-ES": pageEsES, "pt-PT": pagePtPT});

    return (
        <AppOffcanvasShell show={show} onHide={onHide} mobileSheetSizing="content">
            {({isMobileSheet}) => (
                <WorkoutPresetPreviewContent
                    preset={preset}
                    isMobileSheet={isMobileSheet}
                    primaryLabel={t("workoutPresetPage:editPreset")}
                    secondaryLabel={t("workoutPresetPage:back")}
                    deleteLabel={t("workoutPresetPage:deletePreset")}
                    onPrimary={onEdit}
                    onSecondary={onHide}
                    canDelete={canDeletePreset}
                    onDeleteClick={onDeleteClick}
                />
            )}
        </AppOffcanvasShell>
    );
};

export default WorkoutPresetPreviewOffcanvas;
