import {takeLatest, all, call, put} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    changeStatus,
    clientAddressUpdated,
    clientCreated,
    clientDeleted,
    clientRecovered,
    clientUpdated,
    createClient,
    deleteClient,
    fetchClient,
    fetchClientAddress,
    fetchClientCount,
    fetchClientInvoices,
    fetchClientNotificationPreference,
    fetchClientsPaginated,
    fetchNotes,
    fetchPendingClientCount,
    fetchSelectOptions,
    onError,
    passwordReset,
    recoverClient,
    resetPassword,
    saveClientNotificationPreference,
    saveNote,
    setClient,
    setClientAddress,
    setClientCount,
    setClientInvoices,
    setClientNotificationPreference,
    setClientsPaginated,
    setNotes,
    setPendingClientCount,
    setSelectOptions,
    statusChanged,
    updateClient,
    updateClientAddress,
    updatedProfilePicture,
    updateProfileImage
} from "./clientReducer";
import {
    changeClientStatusAPI, createClientAPI,
    fetchClientAddressAPI,
    fetchClientCountAPI,
    fetchClientsByStatusPaginatedAPI,
    fetchClientsPendingCountAPI, fetchSelectOptionsAPI,
    getClientAPI, getClientInvoicesAPI, getClientNotesAPI, getClientNotificationPreferenceAPI, resetClientPasswordAPI, updateClientAddressAPI,
    updateClientAPI, updateClientNotesAPI, updateClientNotificationPreferenceAPI, updateClientProfilePicAPI
} from "../../api/client/clientActions";

export function* fetchPendingClientCountAsync() {
    try {
        const response = yield call(fetchClientsPendingCountAPI);
        yield put(setPendingClientCount(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchPendingClientCount() {
    yield takeLatest(fetchPendingClientCount.type, fetchPendingClientCountAsync);
}

export function* changeClientStatusAsync(action) {
    try {
        yield call(changeClientStatusAPI, action.payload);
        yield put(statusChanged(action.payload));
        yield put(fetchClientCount())
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onChangeClientStatus() {
    yield takeLatest(changeStatus.type, changeClientStatusAsync);
}

export function* fetchClientsPaginatedAsync(action) {
    try {
        const defaultPayload = {status: 0, page: 1, pageSize: 20, search: ''};
        const payload = typeof action.payload === 'object' && action.payload !== null
            ? {...defaultPayload, ...action.payload}
            : {...defaultPayload, status: action.payload ?? defaultPayload.status};

        const response = yield call(fetchClientsByStatusPaginatedAPI, payload);
        yield put(setClientsPaginated(response?.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchClientsPaginated() {
    yield takeLatest(fetchClientsPaginated.type, fetchClientsPaginatedAsync);
}


