export function* clientSaga() {
    yield all([
        call(onFetchSelectOptions),
        call(onFetchClientCount),
        call(onChangeClientStatus),
        call(onFetchPendingClientCount),
        call(onFetchNotes),
        call(onSaveNotes),
        call(onFetchClient),
        call(onRecoverClient),
        call(onDeleteClient),
        call(onResetPassword),
        call(onCreateClient),
        call(onUpdateClient),
        call(onFetchClientNotificationPreference),
        call(onSaveClientNotificationPreference),
        call(onFetchClientInvoices),
        call(onUpdateClientProfilePicture),
        call(onUpdateClientAddress),
        call(onFetchClientAddress),
        call(onFetchClientsPaginated),
    ])
}
