import {createSlice} from "@reduxjs/toolkit";

const initialLoadingState = {
    fetch: false,
    create: false,
    update: false,
    delete: false,
    apply: false,
    saveCurrent: false
};

const initialState = {
    loading: initialLoadingState,
    presets: [],
    lastCreatedPreset: null,
    lastUpdatedPreset: null,
    lastSavedCurrentPreset: null,
    lastDeletedPresetId: null,
    lastAppliedPreset: null
};

export const slice = createSlice({
    name: "workoutPreset",
    initialState,
    reducers: {
        fetchWorkoutPresets(state) {
            state.loading.fetch = true;
        },
        setWorkoutPresets(state, action) {
            state.loading.fetch = false;
            state.presets = action.payload || [];
        },
        fetchWorkoutPresetsFailure(state) {
            state.loading.fetch = false;
        },
        createWorkoutPreset(state) {
            state.loading.create = true;
        },
        createWorkoutPresetSuccess(state, action) {
            state.loading.create = false;
            state.lastCreatedPreset = action.payload;
            state.presets = [...state.presets, action.payload];
        },
        createWorkoutPresetFailure(state) {
            state.loading.create = false;
        },
        updateWorkoutPreset(state) {
            state.loading.update = true;
        },
        updateWorkoutPresetSuccess(state, action) {
            state.loading.update = false;
            state.lastUpdatedPreset = action.payload;
            state.presets = state.presets.map((preset) => preset.id === action.payload.id ? action.payload : preset);
        },
        updateWorkoutPresetFailure(state) {
            state.loading.update = false;
        },
        deleteWorkoutPreset(state) {
            state.loading.delete = true;
        },
        deleteWorkoutPresetSuccess(state, action) {
            state.loading.delete = false;
            state.lastDeletedPresetId = action.payload;
            state.presets = state.presets.filter((preset) => preset.id !== action.payload);
        },
        deleteWorkoutPresetFailure(state) {
            state.loading.delete = false;
        },
        applyWorkoutPreset(state) {
            state.loading.apply = true;
        },
        applyWorkoutPresetSuccess(state, action) {
            state.loading.apply = false;
            state.lastAppliedPreset = action.payload;
        },
        applyWorkoutPresetFailure(state) {
            state.loading.apply = false;
        },
        saveCurrentWorkoutPreset(state) {
            state.loading.saveCurrent = true;
        },
        saveCurrentWorkoutPresetSuccess(state, action) {
            state.loading.saveCurrent = false;
            state.lastSavedCurrentPreset = action.payload;
            state.presets = [...state.presets, action.payload];
        },
        saveCurrentWorkoutPresetFailure(state) {
            state.loading.saveCurrent = false;
        },
        clearWorkoutPresetEvents(state) {
            state.lastCreatedPreset = null;
            state.lastUpdatedPreset = null;
            state.lastSavedCurrentPreset = null;
            state.lastDeletedPresetId = null;
            state.lastAppliedPreset = null;
        }
    }
});

export const workoutPresetReducer = slice.reducer;

export const {
    fetchWorkoutPresets,
    setWorkoutPresets,
    fetchWorkoutPresetsFailure,
    createWorkoutPreset,
    createWorkoutPresetSuccess,
    createWorkoutPresetFailure,
    updateWorkoutPreset,
    updateWorkoutPresetSuccess,
    updateWorkoutPresetFailure,
    deleteWorkoutPreset,
    deleteWorkoutPresetSuccess,
    deleteWorkoutPresetFailure,
    applyWorkoutPreset,
    applyWorkoutPresetSuccess,
    applyWorkoutPresetFailure,
    saveCurrentWorkoutPreset,
    saveCurrentWorkoutPresetSuccess,
    saveCurrentWorkoutPresetFailure,
    clearWorkoutPresetEvents
} = slice.actions;
