export function getBrowserDetails() {

    const now = new Date();

    return {
        user_agent: navigator.userAgent.split(" ")[0],
        color_depth: window.screen.colorDepth,
        type: 'BROWSER',
        java_enabled: navigator.javaEnabled(),
        language: navigator.languages[0],
        screen_height:500,
        screen_width: 500,
        time_zone_offset: Math.round(now.getTimezoneOffset() / 60)
    };

}

