import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const AiAssistantEvaluations = ({msg}) => {
    const {t} = useTranslation();
    useComponentTranslations('ai', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    return(
        <div className={"d-flex align-items-start text-start"}>
            <div
                className={"flex-shrink-0 d-flex align-items-center justify-content-center me-3"}
                style={{width: "28px", minHeight: "28px"}}
            >
                <i
                    className={"fa-kit fa-mfit-ai text-mfit-ai-gradient"}
                    style={{fontSize: "1.25rem", lineHeight: 1}}
                />
            </div>
            <div className={"flex-grow-1"}>
                {msg.thinkingTime && (
                    <div className={"mb-2"}>
                        <span className={"text-secondary"}>
                            {t("ai:thinkingTime", {time: msg.thinkingTime})}
                        </span>
                    </div>
                )}
                <div className={"p-2"} style={{maxWidth: "100%"}}>
                    <span
                        dangerouslySetInnerHTML={{
                            __html: msg.message || msg
                        }}
                    />
                </div>
            </div>
        </div>
    )
}

export default AiAssistantEvaluations;
