import {addToast} from "../../store/toast/toastReducer";
import {useDispatch} from "react-redux";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import {handleSendWhatsApp} from "../../utils/handlers/handler";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SignupLinkLink = ({user}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    useComponentTranslations('signupLinkComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const generateSignUpLink = () => {
        const idB64 = btoa(user.id);
        return `https://client.mfitpersonal.com.br/out/signup-link/${idB64}`;
    };

    const message = `${t("signupLinkComponent:clickBellowToSignup")}|\n${generateSignUpLink()}`;

    const handleCopyLink = () => {
        const signUpLink = generateSignUpLink();
        navigator.clipboard.writeText(signUpLink)
            .then(() => {
                dispatch(addToast(
                    {
                        type: "success",
                        message: `${t("signupLinkComponent:linkCopied")}`,
                        title: `${t("signupLinkComponent:allGood")}`
                    }
                ))
            })
            .catch(err => {
                console.error('Failed to copy: ', err);
            });
    };

    return (
        <div className={'card card-body border-0 mt-3'}>
            <div className={'row justify-content-center'}>
                <div className={"col-auto"}>
                    <RoundedIcon icon={" fa-link"} size={"lg"}/>
                </div>
                <div className={'col-11 pt-4 text-center'}>
                    <span className={'fw-semibold fs-3 d-block'}>{t("signupLinkComponent:signupLink")}</span>
                    <div className={' pt-3'}>
                        <span className={' d-block fw-bold'}>
                            {t("signupLinkComponent:useThisLink")}
                        </span>
                        <span className={'d-block pt-2'}>
                            {t("signupLinkComponent:facilitateSignup")}
                        </span>
                        <span className={"d-block"}>
                            {t("signupLinkComponent:linkInSocials")}
                        </span>
                    </div>
                </div>
                <div className={'col-11 pt-4 text-center'}>
                    <div className={"card card-body bg-secondary-subtle  border-0"}>
                        <span>{generateSignUpLink()}</span>
                    </div>
                </div>
                <div className={'col-11 pt-4 text-center'}>
                    <div className={'d-grid'}>
                        <button className={'btn btn-primary'} onClick={handleCopyLink}>
                            {t("signupLinkComponent:copyLink")}
                        </button>
                    </div>
                    <div className={'d-grid mt-2'}>
                        <button className={'btn btn-success text-white'} onClick={()=>handleSendWhatsApp(null, message)}>
                            <i className="fa-brands fa-whatsapp"></i>
                            &nbsp;{t("signupLinkComponent:shareOnWhatsApp")}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    )
}
export default SignupLinkLink;