import {createSlice} from '@reduxjs/toolkit'

const initialState = {
    loadingBuyer: false,
    loadingSubPlan: false,
    loadingCreditCards: false,
    loadingCoupon: false,
    loadingTransaction: false,
    loadingSubChange: false,
    loadingSubscription: false,
    subPlan: null,
    subPlanList: null,
    subscriptionCanceled: false,
    subscriptionActivated: false,
    creditCards: null,
    creditCardError: null,
    creditCardCreated: null,
    buyer: null,
    installments: 1,
    coupon: null,
    transaction: null,
    paymentMethod: null,
    paymentMethodChanged: false,
    freePlanChanged: false,
}
const slice = createSlice({
    name: 'subscription',
    initialState,
    reducers: {
        fetchPaymentMethod(state){
            state.loadingSubscription = true
        },
        changePaymentMethod(state){
            state.loadingSubscription = true
        },
        setChangedPaymentMethod(state, action) {
            state.paymentMethodChanged = action.payload
            state.loadingSubscription = false
        },
        activateSub(state){
            state.loadingSubscription = true
        },
        subActivated(state, action) {
            state.loadingSubscription = false
            state.subscriptionActivated = action.payload
        },
        cancelSubscription(state) {
            state.loadingSubscription = true
        },
        cancelSubscriptionSuccess(state) {
            state.loadingSubscription = false
            state.subscriptionCanceled = true
        },
        setSubscriptionCanceled(state, action) {
            state.subscriptionCanceled = action.payload
        },
        deleteCreditCard(state) {
            state.loadingCreditCards = true
        },
        removeCreditCardFromTheList(state, action) {
            state.creditCards = state.creditCards.filter(c => c.id !== action.payload);
            state.loadingCreditCards = false
        },
        createCreditCard(state) {
            state.loadingCreditCards = true
        },
        createCreditCardSuccess(state, action) {
            state.loadingCreditCards = false;
            const list = (state.creditCards ??= []);
            for (const c of list) c.defaultCard = false;
            const newCard = {...action.payload, defaultCard: true};
            const idx = list.findIndex(c => c.id === newCard.id);
            if (idx !== -1) list.splice(idx, 1);
            list.unshift(newCard);
            state.creditCardCreated = newCard;
        },
        setCreditCardCreated(state, action) {
            state.creditCardCreated = action.payload
        },
        createCreditCardError(state, action) {
            state.loadingCreditCards = false
            state.creditCardError = action.payload;
            state.loadingSubscription = false
            state.loadingTransaction = false
        },
        walletPaymentStart(state) {
            state.loadingTransaction = true
        },
        changeUserSubscriptionToFreePlan(state) {
            state.loadingSubChange = true
        },
        changeUserToMonthlyPlan(state) {
            state.loadingSubChange = true
        },
        setLoadingSubChange(state, action) {
            const {loading, changed} = action.payload
            state.loadingSubChange = loading
            state.freePlanChanged = changed
        },
        fetchTransaction(state) {
            state.loadingTransaction = true
        },
        createPixTransaction(state) {
            state.loadingTransaction = true
        },
        createCardTransaction(state) {
            state.loadingTransaction = true
        },

        setTransaction(state, action) {
            state.loadingTransaction = false
            state.transaction = action.payload
        },
        checkCoupon(state) {
            state.loadingCoupon = true
        },
        setCoupon(state, action) {
            state.coupon = action.payload
            state.loadingCoupon = false
        },
        setInstallments(state, action) {
            state.installments = action.payload
        },
        setPaymentMethod(state, action) {
            state.paymentMethod = action.payload
            state.loadingSubscription = false
        },
        fetchCreditCards(state) {
            state.loadingCreditCards = true
        },
        setCreditCards(state, action) {
            state.creditCards = action.payload
            state.loadingCreditCards = false
        },
        fetchSubPlanList(state) {
            state.loadingSubPlan = true
        },
        setSubPlanList(state, action) {
            state.loadingSubPlan = false
            state.subPlanList = action.payload
        },
        saveBuyerInfo(state) {
            state.loadingBuyer = true
        },
        selectSubPlan(state) {
            state.loadingSubPlan = true
        },
        setSubPlan(state, action) {
            state.loadingSubPlan = false
            state.subPlan = action.payload
        },
        createBuyer(state) {
            state.loadingBuyer = true
        },
        fetchBuyer(state) {
            state.loadingBuyer = true
        },
        setBuyer(state, action) {
            state.loadingBuyer = false
            state.buyer = action.payload
        },
        onError(state) {
            state.loadingBuyer = false
            state.loadingSubPlan = false
            state.loadingCreditCards = false
            state.loadingTransaction = false
            state.loadingSubChange = false
            state.loadingSubscription = false
        }
    }
})

export const {
    fetchBuyer,
    setBuyer,
    selectSubPlan,
    setSubPlan,
    saveBuyerInfo,
    setSubPlanList,
    fetchSubPlanList,
    createBuyer,
    fetchCreditCards,
    setCreditCards,
    setPaymentMethod,
    setInstallments,
    checkCoupon,
    setCoupon,
    createPixTransaction,
    createCardTransaction,
    setTransaction,
    fetchTransaction,
    changeUserSubscriptionToFreePlan,
    setLoadingSubChange,
    walletPaymentStart,
    createCreditCard,
    createCreditCardError,
    createCreditCardSuccess,
    setCreditCardCreated,
    deleteCreditCard,
    removeCreditCardFromTheList,
    cancelSubscription,
    cancelSubscriptionSuccess,
    setSubscriptionCanceled,
    activateSub,
    subActivated,
    changePaymentMethod,
    setChangedPaymentMethod,
    fetchPaymentMethod,
    changeUserToMonthlyPlan,
    onError
} = slice.actions

export const subscriptionReducer = slice.reducer
