import {useCallback, useEffect, useMemo, useRef, useState} from "react";
import {useDispatch} from "react-redux";
import he from "he";
import Avatar from "../avatar/Avatar";
import EmptySet from "../empty-set/EmptySet";
import AppOffcanvasShell from "../offcanvas/AppOffcanvasShell";
import Pagination from "../pagination/Pagination";
import PushComposePanel from "../push/PushComposePanel";
import {addToast} from "../../store/toast/toastReducer";
import {
    getRetentionStatusMeta,
    getRetentionSuggestedMessages
} from "./retentionConfig";
import Spinner from "../loader/Spinner";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import {
    useCreateRetentionNotificationLogMutation,
    useResolveRetentionClientIds,
    useRetentionClientsQuery
} from "../../store/retention/retentionApi";
import {normalizeRetentionClientFilters} from "../../store/retention/retentionFilters";

const STEP_CATEGORY = "category_select";
const STEP_CLIENTS = "client_select";
const STEP_TEMPLATES = "template_select";
const STEP_COMPOSE = "compose";
const STEP_SUCCESS = "success";

const RETENTION_CATEGORY_STEP_ORDER = [
    "AT_RISK",
    "OSCILLATING",
    "ABANDONED",
    "ENGAGED",
    "RECOVERED"
];
const CATEGORY_COUNTS_FILTERS = {
    status: "ALL",
    search: "",
    page: 1,
    pageSize: 1
};
const buildAudienceListFilters = (status, page = 1, pageSize = 20) => normalizeRetentionClientFilters({
    status,
    search: "",
    page,
    pageSize
});

const buildCategoryLabel = (status, t) => {
    const map = {
        ENGAGED: t("retention:categoryEngagedLabel"),
        OSCILLATING: t("retention:categoryOscillatingLabel"),
        AT_RISK: t("retention:categoryAtRiskLabel"),
        ABANDONED: t("retention:categoryAbandonedLabel"),
        RECOVERED: t("retention:categoryRecoveredLabel")
    };

    return map[status] || getRetentionStatusMeta(status, t).label;
};

const buildCategoryCaption = (status, t) => {
    const map = {
        ENGAGED: t("retention:categoryEngagedCaption"),
        OSCILLATING: t("retention:categoryOscillatingCaption"),
        AT_RISK: t("retention:categoryAtRiskCaption"),
        ABANDONED: t("retention:categoryAbandonedCaption"),
        RECOVERED: t("retention:categoryRecoveredCaption")
    };

    return map[status] || "";
};

const formatClientCount = (count, t) => {
    const clientLabel = count === 1
        ? t("retention:clientSingular")
        : t("retention:clientPlural");

    return `${count} ${clientLabel}`;
};

const formatCategoryCountSummary = (count, status, t) => {
    const clientLabel = count === 1
        ? t("retention:clientSingular")
        : t("retention:clientPlural");

    return t("retention:categoryCountSummary", {
        count,
        clients: clientLabel,
        status: (status || "").toLowerCase()
    });
};

const formatSelectedRecipientsCount = (count, t) => (
    count === 1
        ? t("retention:selectedRecipientsCountSingular", {count})
        : t("retention:selectedRecipientsCountPlural", {count})
);

const formatSuccessCount = (count, t) => (
    count === 1
        ? t("retention:notifySuccessCountSingular", {count})
        : t("retention:notifySuccessCountPlural", {count})
);

const getSuccessDescription = (mode, t) => {
    if (mode === "scheduled") {
        return t("retention:notifySuccessScheduled");
    }

    if (mode === "recurring") {
        return t("retention:notifySuccessRecurring");
    }

    return t("retention:notifySuccessNow");
};

const RetentionNotifyOffcanvas = ({
                                      show,
                                      onHide,
                                      onSuccess,
                                      initialClient,
                                      t
                                  }) => {
    const dispatch = useDispatch();
    const [step, setStep] = useState(STEP_CATEGORY);
    const [selectedStatus, setSelectedStatus] = useState(null);
    const [selectedStatusCount, setSelectedStatusCount] = useState(0);
    const [selectionMode, setSelectionMode] = useState("ALL");
    const [excludedClientIds, setExcludedClientIds] = useState([]);
    const [includedClientIds, setIncludedClientIds] = useState([]);
    const [resolvedClientIds, setResolvedClientIds] = useState([]);
    const [isResolvingClients, setIsResolvingClients] = useState(false);
    const [selectedTemplateKey, setSelectedTemplateKey] = useState(null);
    const [draftValues, setDraftValues] = useState({title: "", message: ""});
    const [successResult, setSuccessResult] = useState(null);
    const [audienceFilters, setAudienceFilters] = useState(() => buildAudienceListFilters("AT_RISK"));
    const allClientsCheckboxRef = useRef(null);
    const singleClientMode = Boolean(initialClient);
    const resolveClientIds = useResolveRetentionClientIds();
    const [createRetentionNotificationLog] = useCreateRetentionNotificationLogMutation();
    const shouldLoadCategoryCounts = show && !singleClientMode && step === STEP_CATEGORY;
    const shouldLoadAudienceList = show && !singleClientMode && step === STEP_CLIENTS && Boolean(selectedStatus);
    const {data: categoryAudienceData, isLoading: isCategoryLoading} = useRetentionClientsQuery(
        CATEGORY_COUNTS_FILTERS,
        {skip: !shouldLoadCategoryCounts}
    );
    const {data: audienceListData, isLoading: isAudienceLoading} = useRetentionClientsQuery(
        audienceFilters,
        {skip: !shouldLoadAudienceList}
    );

    const statusCounts = useMemo(
        () => categoryAudienceData?.pagination?.statusCounts || {},
        [categoryAudienceData?.pagination?.statusCounts]
    );
    const audienceClients = audienceListData?.clients || [];
    const audiencePagination = audienceListData?.pagination || {
        page: audienceFilters.page,
        pageSize: audienceFilters.pageSize,
        totalItems: 0,
        totalPages: 0,
        statusCounts: {}
    };
    const templates = useMemo(() => getRetentionSuggestedMessages(selectedStatus, t), [selectedStatus, t]);
    const selectedStatusLabel = useMemo(() => buildCategoryLabel(selectedStatus, t), [selectedStatus, t]);
    const selectedStatusCaption = useMemo(() => buildCategoryCaption(selectedStatus, t), [selectedStatus, t]);
    const selectedCount = useMemo(() => {
        if (selectionMode === "EXPLICIT") {
            return includedClientIds.length;
        }

        return Math.max(selectedStatusCount - excludedClientIds.length, 0);
    }, [excludedClientIds.length, includedClientIds.length, selectedStatusCount, selectionMode]);
    const allClientsSelected = selectedStatusCount > 0 && selectedCount === selectedStatusCount;
    const noClientsSelected = selectedCount === 0;
    const partiallySelected = !allClientsSelected && !noClientsSelected;
    const selectedStatusMeta = useMemo(
        () => getRetentionStatusMeta(selectedStatus || "ALL", t),
        [selectedStatus, t]
    );

    const resetFlowState = useCallback(() => {
        setStep(STEP_CATEGORY);
        setSelectedStatus(null);
        setSelectedStatusCount(0);
        setSelectionMode("ALL");
        setExcludedClientIds([]);
        setIncludedClientIds([]);
        setResolvedClientIds([]);
        setIsResolvingClients(false);
        setSelectedTemplateKey(null);
        setDraftValues({title: "", message: ""});
        setSuccessResult(null);
        setAudienceFilters(buildAudienceListFilters("AT_RISK"));
    }, []);

    const handleCloseModal = useCallback(() => {
        resetFlowState();
        onHide?.();
    }, [onHide, resetFlowState]);
    useEffect(() => {
        if (show) {
            return;
        }

        resetFlowState();
    }, [resetFlowState, show]);

    useEffect(() => {
        if (!show) {
            return;
        }

        setSelectionMode("ALL");
        setExcludedClientIds([]);
        setIncludedClientIds([]);
        setResolvedClientIds([]);
        setSelectedTemplateKey(null);
        setDraftValues({title: "", message: ""});
        setIsResolvingClients(false);
        setSuccessResult(null);
        setAudienceFilters(buildAudienceListFilters("AT_RISK"));

        if (singleClientMode) {
            const defaultStatus = initialClient?.status || "AT_RISK";
            const singleTemplates = getRetentionSuggestedMessages(defaultStatus, t);
            const singleDefaultTemplate = singleTemplates[0] || null;
            setSelectedStatus(defaultStatus);
            setSelectedStatusCount(1);
            setSelectionMode("EXPLICIT");
            setIncludedClientIds(initialClient?.id ? [initialClient.id] : []);
            setResolvedClientIds(initialClient?.id ? [initialClient.id] : []);
            setSelectedTemplateKey(singleDefaultTemplate?.key || null);
            setDraftValues({
                title: singleDefaultTemplate?.title || "",
                message: singleDefaultTemplate?.message || ""
            });
            setStep(STEP_COMPOSE);
            return;
        }

        setSelectedStatus(null);
        setSelectedStatusCount(0);
        setSelectionMode("ALL");
        setStep(STEP_CATEGORY);
    }, [initialClient, show, singleClientMode, t]);

    useEffect(() => {
        if (step !== STEP_CLIENTS || typeof audienceListData?.pagination?.totalItems !== "number") {
            return;
        }

        setSelectedStatusCount(audienceListData.pagination.totalItems);
    }, [audienceListData?.pagination?.totalItems, step]);

    useEffect(() => {
        if (!allClientsCheckboxRef.current) {
            return;
        }

        allClientsCheckboxRef.current.indeterminate = partiallySelected;
    }, [partiallySelected]);

    const handleBack = () => {
        if (step === STEP_CLIENTS) {
            setStep(STEP_CATEGORY);
            return;
        }

        if (step === STEP_TEMPLATES) {
            setStep(singleClientMode ? STEP_COMPOSE : STEP_CLIENTS);
            return;
        }

        if (step === STEP_COMPOSE) {
            setStep(STEP_TEMPLATES);
        }
    };

    const handleCategorySelect = (status) => {
        setSelectedStatus(status);
        setSelectedStatusCount(statusCounts?.[status] || 0);
        setSelectionMode("ALL");
        setExcludedClientIds([]);
        setIncludedClientIds([]);
        setResolvedClientIds([]);
        setSelectedTemplateKey(null);
        setDraftValues({title: "", message: ""});
        setStep(STEP_CLIENTS);
        setAudienceFilters(buildAudienceListFilters(status));
    };

    const handleToggleClient = (clientId) => {
        setResolvedClientIds([]);

        if (selectionMode === "ALL") {
            setExcludedClientIds((currentValue) => (
                currentValue.includes(clientId)
                    ? currentValue.filter((id) => id !== clientId)
                    : [...currentValue, clientId]
            ));
            return;
        }

        setIncludedClientIds((currentValue) => (
            currentValue.includes(clientId)
                ? currentValue.filter((id) => id !== clientId)
                : [...currentValue, clientId]
        ));
    };

    const handleToggleAllClients = () => {
        setResolvedClientIds([]);

        if (allClientsSelected) {
            setSelectionMode("EXPLICIT");
            setIncludedClientIds([]);
            setExcludedClientIds([]);
            return;
        }

        setSelectionMode("ALL");
        setExcludedClientIds([]);
        setIncludedClientIds([]);
    };

    const handleContinueToTemplates = async () => {
        if (!selectedStatus || selectedCount <= 0) {
            return;
        }

        if (selectionMode === "EXPLICIT") {
            setResolvedClientIds(includedClientIds);
            setStep(STEP_TEMPLATES);
            return;
        }

        setIsResolvingClients(true);
        try {
            const allClientIds = await resolveClientIds(selectedStatus);
            const nextResolvedClientIds = allClientIds.filter((clientId) => !excludedClientIds.includes(clientId));
            setResolvedClientIds(nextResolvedClientIds);
            setStep(STEP_TEMPLATES);
        } catch (error) {
            // The endpoint-level RTK Query handler shows the failure toast.
        } finally {
            setIsResolvingClients(false);
        }
    };

    const handleTemplateSelect = (template) => {
        setSelectedTemplateKey(template?.key || null);
        setDraftValues({
            title: template?.title || "",
            message: template?.message || ""
        });
        setStep(STEP_COMPOSE);
    };

    const handleCustomTemplate = () => {
        setSelectedTemplateKey(null);
        setDraftValues({title: "", message: ""});
        setStep(STEP_COMPOSE);
    };

    const handlePushSuccess = async (responseBody, mode, submittedValues) => {
        const payload = {
            clientIds: resolvedClientIds,
            categoryStatus: selectedStatus,
            templateKey: selectedTemplateKey,
            title: submittedValues.title,
            message: submittedValues.message,
            pushMode: mode.toUpperCase(),
            externalNotificationId: responseBody?.notificationId ? String(responseBody.notificationId) : null
        };

        try {
            const response = await createRetentionNotificationLog(payload).unwrap();
            const count = response?.count || resolvedClientIds.length;
            setSuccessResult({count, mode});
            setStep(STEP_SUCCESS);
            onSuccess?.({
                count
            });
        } catch (error) {
            dispatch(addToast({
                id: Date.now(),
                type: "warning",
                title: t("retention:notifySuccess"),
                message: t("retention:notifyLogWarning")
            }));
            setSuccessResult({
                count: resolvedClientIds.length,
                mode
            });
            setStep(STEP_SUCCESS);
            onSuccess?.({
                count: resolvedClientIds.length
            });
        }
    };

    const categoryCards = useMemo(() => (
        RETENTION_CATEGORY_STEP_ORDER.map((status) => {
            const meta = getRetentionStatusMeta(status, t);
            const count = statusCounts?.[status] || 0;

            return {
                status,
                meta,
                count,
                label: buildCategoryLabel(status, t),
                caption: buildCategoryCaption(status, t)
            };
        })
    ), [statusCounts, t]);

    const lockedAudience = useMemo(() => ({
        sendTo: "clients",
        selectOption: resolvedClientIds,
        summaryLabel: selectedStatusLabel,
        summaryCount: selectedCount,
        countLabel: formatSelectedRecipientsCount(selectedCount, t)
    }), [resolvedClientIds, selectedCount, selectedStatusLabel, t]);

    return (
        <AppOffcanvasShell
            show={show}
            onHide={handleCloseModal}
            showDesktopCloseButton={step !== STEP_COMPOSE}
        >
            {({isMobileSheet}) => (
                <>
                    {step === STEP_CATEGORY && (
                        <div className={`flex-grow-1 overflow-auto `}>
                            <div className={"mb-4"}>
                                <span className={"fw-semibold fs-4 d-block"}>{t("retention:notifyByCategoryTitle")}</span>
                                <span className={"text-secondary d-block mt-2"}>
                                {t("retention:notifyByCategorySubtitle")}
                            </span>
                            </div>

                            {isCategoryLoading ? (
                                <div className={"py-5 text-center"}>
                                    <Spinner/>
                                </div>
                            ) : (
                                <div className={"d-grid gap-3"}>
                                    {categoryCards.map((item) => (
                                        <button
                                            key={item.status}
                                            type={"button"}
                                            className={`btn text-start w-100 p-0 border-0 bg-transparent ${item.count === 0 ? "opacity-50" : ""}`}
                                            onClick={() => handleCategorySelect(item.status)}
                                            disabled={item.count === 0}
                                        >
                                            <div className={"card border rounded-3 shadow-none"}>
                                                <div className={"card-body px-3 py-3"}>
                                                    <div className={"d-flex justify-content-between align-items-center gap-3"}>
                                                        <div className={"flex-grow-1 min-w-0"}>
                                                            <div className={"d-flex align-items-center gap-2"}>
                                                                <span className={`rounded-circle flex-shrink-0 ${item.meta.dotClass}`}
                                                                      style={{width: "12px", height: "12px"}}></span>
                                                                <span className={"fw-semibold fs-5"}>{item.label}</span>
                                                            </div>
                                                            <span className={"small text-uppercase text-secondary d-block mt-2"}>
                                                            {item.caption}
                                                        </span>
                                                        </div>
                                                        <div className={"d-flex align-items-center gap-2 text-nowrap"}>
                                                        <span className={"small text-secondary"}>
                                                            {formatClientCount(item.count, t)}
                                                        </span>
                                                            <i className={"fa-regular fa-chevron-right text-dark"}></i>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {step === STEP_CLIENTS && (
                        <>
                            <div className={`flex-grow-1 overflow-auto`}>
                                <div className={"mb-4"}>
                                    <span className={"fw-semibold fs-4 d-block"}>{t("retention:selectClientsTitle")}</span>
                                    <span className={"text-secondary d-block mt-2"}>
                                    {t("retention:selectClientsSubtitle")}
                                </span>
                                </div>

                                <div className={"d-flex justify-content-between align-items-center gap-3"}>
                                    <div className={"d-flex align-items-center gap-2"}>
                                        <span className={`rounded-circle flex-shrink-0 ${selectedStatusMeta.dotClass}`}
                                              style={{width: "12px", height: "12px"}}></span>
                                        <span className={"fw-semibold fs-5"}>{selectedStatusLabel}</span>
                                    </div>
                                    <span className={"small text-uppercase text-secondary text-end"}>
                                    {selectedStatusCaption}
                                </span>
                                </div>

                                <hr className={"border-primary-subtle my-3"}/>

                                <div className={"d-flex justify-content-between align-items-center gap-3 mb-2"}>
                                <span className={"small fw-semibold text-default-darker"}>
                                    {formatCategoryCountSummary(selectedCount, selectedStatusLabel, t)}
                                </span>
                                    <label className={"d-flex align-items-center gap-2 clickable-element"}>
                                        <span className={"fw-semibold"}>{t("retention:allClientsToggle")}</span>
                                        <input
                                            ref={allClientsCheckboxRef}
                                            type={"checkbox"}
                                            className={"form-check-input m-0 border-primary-subtle"}
                                            checked={allClientsSelected}
                                            onChange={handleToggleAllClients}
                                        />
                                    </label>
                                </div>

                                {isAudienceLoading ? (
                                    <div className={"py-5 text-center"}>
                                        <Spinner/>
                                    </div>
                                ) : audienceClients.length === 0 ? (
                                    <EmptySet
                                        icon={"fa-users"}
                                        message={t("retention:noRecipientsAvailable")}
                                        message2={t("retention:emptyClientsMessage")}
                                    />
                                ) : (
                                    <div>
                                        {audienceClients.map((client, index) => {
                                            const clientName = he.decode(client.name || "");
                                            const checked = selectionMode === "ALL"
                                                ? !excludedClientIds.includes(client.id)
                                                : includedClientIds.includes(client.id);

                                            return (
                                                <div className={`${index === 0 ? "border-top" : ""} border-primary-subtle`} key={client.id}>
                                                    <div className={"d-flex align-items-center gap-3 py-3 border-bottom border-primary-subtle"}>
                                                        <Avatar url={client.profileUrl} maxWidth={"48px"} blueBorder={true} borderWidth={2}/>
                                                        <div className={"flex-grow-1 overflow-hidden"}>
                                                            <span className={"d-block fw-semibold fs-5 text-truncate"} title={clientName}>{clientName}</span>
                                                        </div>
                                                        <div className={"form-check m-0"}>
                                                            <input
                                                                type={"checkbox"}
                                                                className={"form-check-input m-0 border-primary-subtle"}
                                                                checked={checked}
                                                                onChange={() => handleToggleClient(client.id)}
                                                            />
                                                        </div>
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>

                            {audiencePagination?.totalItems > audiencePagination?.pageSize && (

                                <Pagination className={"pt-4"}
                                            currentPage={audiencePagination.page}
                                            totalItems={audiencePagination.totalItems}
                                            itemsPerPage={audiencePagination.pageSize}
                                            onPageChange={(nextPage) => setAudienceFilters((currentFilters) => ({
                                                ...currentFilters,
                                                page: nextPage
                                            }))}
                                            pagesToShow={isMobileSheet ? 3 : 5}
                                />

                            )}


                            <div className={"d-grid gap-2"}>
                                <button
                                    type={"button"}
                                    className={"btn btn-primary"}
                                    onClick={handleContinueToTemplates}
                                    disabled={selectedCount === 0 || isResolvingClients}
                                >
                                    {isResolvingClients ? t("retention:loadingRecipients") : t("retention:next")}
                                </button>
                                <button
                                    type={"button"}
                                    className={"btn btn-outline-primary"}
                                    onClick={handleBack}
                                >
                                    {t("retention:back")}
                                </button>
                            </div>

                        </>
                    )}

                    {step === STEP_TEMPLATES && (
                        <>
                            <div className={`flex-grow-1 overflow-auto  `}>
                                <div className={"mb-4"}>
                                    <span className={"fw-semibold fs-4 d-block"}>{t("retention:chooseMessageTitle")}</span>
                                    <span className={"text-secondary d-block mt-2"}>
                                        {t("retention:chooseMessageSubtitle")}
                                    </span>
                                </div>

                                <button
                                    type={"button"}
                                    className={"btn border-0 bg-transparent p-0 w-100 my-4 d-flex justify-content-center"}
                                    onClick={handleCustomTemplate}
                                >
                                    <div className={"d-inline-flex align-items-center justify-content-center gap-3 py-3"}>
                                        <RoundedIcon
                                            icon={"fa-plus"}
                                            bgColor={"bg-primary-subtle"}
                                            textColor={"text-primary"}
                                            className={"d-inline-flex align-items-center justify-content-center flex-shrink-0"}
                                            style={{width: "40px", height: "40px"}}
                                        />
                                        <span className={"fw-semibold fs-5"}>{t("retention:writeMessage")}</span>
                                    </div>
                                </button>

                                <div className={"d-grid gap-3"}>
                                    {templates.map((template) => (
                                        <button
                                            key={template.key}
                                            type={"button"}
                                            className={"btn text-start border rounded-3 bg-transparent p-0 shadow-none"}
                                            onClick={() => handleTemplateSelect(template)}
                                        >
                                            <div className={"p-3 d-flex align-items-center gap-3"}>
                                                <div className={"flex-grow-1 min-w-0"}>
                                                <span className={"fw-semibold   d-block text-dark"}>
                                                    {template.label}
                                                </span>
                                                    <span className={"text-secondary d-block mt-2"}>
                                                    {template.message}
                                                </span>
                                                </div>
                                                <i
                                                    className={"fa-regular fa-plus text-primary flex-shrink-0"}
                                                    style={{fontSize: "1.5rem"}}
                                                ></i>
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            </div>


                            <button
                                type={"button"}
                                className={"btn btn-outline-primary w-100"}
                                onClick={handleBack}
                            >
                                {t("retention:back")}
                            </button>

                        </>
                    )}

                    {step === STEP_COMPOSE && (
                        <PushComposePanel
                            title={t("retention:chooseMessageTitle")}
                            initialMode={"now"}
                            initialValues={draftValues}
                            lockedAudience={lockedAudience}
                            onSuccess={handlePushSuccess}
                            isMobileSheet={isMobileSheet}
                            onClose={handleCloseModal}
                            secondaryAction={{
                                label: t("retention:back"),
                                onClick: handleBack
                            }}
                        />
                    )}

                    {step === STEP_SUCCESS && (
                        <div className={`flex-grow-1 d-flex flex-column ${isMobileSheet ? "px-3 pt-3 pb-3" : "px-4 py-4"}`}>
                            <div className={"flex-grow-1 d-flex flex-column justify-content-center text-center"}>
                                <div className={"mb-4"}>
                                    <i className={"fa-regular fa-circle-check text-success"} style={{fontSize: "3.5rem"}}></i>
                                </div>

                                <span className={"fw-semibold fs-3 d-block"}>
                                {t("retention:notifySuccess")}
                            </span>

                                <span className={"text-secondary d-block mt-3"}>
                                {getSuccessDescription(successResult?.mode, t)}
                            </span>

                                <span className={"fw-semibold d-block mt-3"}>
                                {formatSuccessCount(successResult?.count || 0, t)}
                            </span>
                            </div>

                            <div className={isMobileSheet ? "pb-2" : ""}>
                                <button
                                    type={"button"}
                                    className={"btn btn-primary w-100"}
                                    onClick={handleCloseModal}
                                >
                                    {t("retention:done")}
                                </button>
                            </div>
                        </div>
                    )}
                </>
            )}
        </AppOffcanvasShell>
    );
};

export default RetentionNotifyOffcanvas;
