import axios from "axios";
import {apiUrl, getToken} from "../api";

const buildExtraTrainingApiConfig = () => {
    const token = getToken();
    if (!token) {
        const error = new Error("AUTH_REQUIRED");
        error.code = "AUTH_REQUIRED";
        error.errorMessage = "AUTH_REQUIRED";
        throw error;
    }

    return {
        headers: {
            "Content-Type": "application/json",
            authorization: token
        },
        timeout: 20000
    };
};

export const getAllExtraTrainingAPI = async (id) => {
    return await axios.get(`${apiUrl}/user/extratraining/all?id=${id}`, buildExtraTrainingApiConfig());
};

export const getOneExtraTrainingAPI = async (id, extraTrainingId) => {
    return await axios.get(`${apiUrl}/user/extratraining/?id=${id}&extraTrainingId=${extraTrainingId}`, buildExtraTrainingApiConfig());
};

export const saveExtraTrainingAPI = async ({id, formData}) => {
    return await axios.post(`${apiUrl}/user/extratraining/?id=${id}`, formData, buildExtraTrainingApiConfig());
};

export const editExtraTrainingAPI = async ({id, extraTrainingId, formData}) => {
    return await axios.put(`${apiUrl}/user/extratraining/?id=${id}&extraTrainingId=${extraTrainingId}`, formData, buildExtraTrainingApiConfig());
};

export const sendExtraTrainingAPI = async ({id, extraTrainingId, formData}) => {
    return await axios.post(`${apiUrl}/user/extratraining/send?id=${id}&extraTrainingId=${extraTrainingId}`, formData, buildExtraTrainingApiConfig());
};

export const deleteExtraTrainingAPI = async (id, extraTrainingId) => {
    return await axios.delete(`${apiUrl}/user/extratraining/?id=${id}&extraTrainingId=${extraTrainingId}`, buildExtraTrainingApiConfig());
};

export const executeExtraTrainingAPI = async (id, extraTrainingId) => {
    return await axios.post(`${apiUrl}/user/extratraining/execute?id=${id}&extraTrainingId=${extraTrainingId}`, {}, buildExtraTrainingApiConfig());
};
