import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WalletDeniedCard = ({status}) => {
    const {t} = useTranslation();
    useComponentTranslations('wallet', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    return (
        <div className={'col-12'}>
            <div className={'card card-body bg-info-subtle border-0 mt-3'}>
                <div className={'row'}>
                    <div className={'col-12 text-center'}>
                        {
                            status === 9 &&
                            <span className={'small text-primary-darker d-block'}>{t("wallet:walletDeniedMessage")} <span
                                className={"fw-bold"}>{t("wallet:180days")}</span>.</span>
                        }
                        {
                            status === 10 &&
                            <span className={'small text-primary-darker d-block'}>{t("wallet:walletBanned")}</span>
                        }
                    </div>
                </div>
            </div>
        </div>
    )
}

export default WalletDeniedCard;