import {ErrorMessage, Field} from "formik";
import AiPushGenerator from "../ai/AiPushGenerator";

const PushMessageFields = ({
    compact = false,
    errors,
    showAiGenerator = true,
    t,
    touched,
    waiting
}) => {
    const messageRows = compact ? 4 : 5;

    return (
        <>
            {showAiGenerator && (
                <div className={"row justify-content-end mb-2"}>
                    <div className={"col-auto"}>
                        <AiPushGenerator/>
                    </div>
                </div>
            )}

            <div className={"form-group"}>
                <label className={"fw-semibold"}>{t("push:title")}</label>
                {waiting ? (
                    <div
                        className={"card card-body p-0 ps-3 d-flex align-items-center justify-content-center bg-body border-secondary-subtle"}
                        style={{height: "46px"}}
                    >
                        <div className={"col-12"}>
                            <span className={"fa-fade"}>{t("push:thinking")}</span>
                        </div>
                    </div>
                ) : (
                    <Field
                        name={"title"}
                        type={"text"}
                        className={`form-control ${touched.title && errors.title ? "is-invalid" : ""}`}
                    />
                )}
                <ErrorMessage name={"title"} component={"div"} className={"invalid-feedback"}/>
            </div>

            <div className={"form-group mt-2"}>
                <label className={"fw-semibold"}>{t("push:message")}</label>
                {waiting ? (
                    <div
                        className={"card card-body p-0 ps-3 d-flex align-items-center justify-content-center bg-body border-secondary-subtle"}
                        style={{height: compact ? "96px" : "120px"}}
                    >
                        <div className={"col-12"}>
                            <span className={"fa-fade"}>{t("push:thinking")}</span>
                        </div>
                    </div>
                ) : (
                    <Field
                        name={"message"}
                        as={"textarea"}
                        rows={messageRows}
                        className={`form-control ${touched.message && errors.message ? "is-invalid" : ""}`}
                    />
                )}
                <ErrorMessage name={"message"} component={"div"} className={"invalid-feedback"}/>
            </div>
        </>
    );
};

export default PushMessageFields;
