import Text from "../utils/emoji/Text";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {useEffect, useState} from "react";
import Modal from "react-bootstrap/Modal";
import WorkoutIcon from "../rounded-icon/WorkoutIcon";
import {useDispatch, useSelector} from "react-redux";
import {selectChangingStatus} from "../../store/workout-aerobic/workoutAerobicSelector";
import {changeAerobicStatus} from "../../store/workout-aerobic/workoutAerobicReducer";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import {addToast} from "../../store/toast/toastReducer";
import {selectUser} from "../../store/user/userSelector";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {handleSendWhatsApp} from "../../utils/handlers/handler";
import ShareComponent from "../utils/share/ShareComponent";
import WorkoutAerobicClone from "../workout-clone/WorkoutAerobicClone";
import {Link, useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import {
    changeRoutineDeletedStatus,
    changeWorkoutRoutineStatus
} from "../../store/workout-routine/workoutRoutineReducer";
import WorkoutRoutineClone from "../workout-clone/WorkoutRoutineClone";
import {getDifficulty, getObjective} from "../../utils/workout/Workout";
import {
    selectWorkoutRoutineChangingStatus,
    selectWorkoutRoutineDeleted
} from "../../store/workout-routine/workoutRoutineSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import WorkoutAerobicNameForm from "../workout-library/WorkoutAerobicNameForm";
import {Dropdown} from "react-bootstrap";

const WorkoutCard = ({workout, type}) => {
    const {i18n, t} = useTranslation()
    const navigate = useNavigate();
    const isAerobic = type === 1;
    const [archivedModal, setArchivedModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [shareModal, setShareModal] = useState(false);
    const [showRecoverModal, setShowRecoverModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const isAerobicStatusChanging = useSelector(selectChangingStatus);
    const isRoutineStatusChanging = useSelector(selectWorkoutRoutineChangingStatus)
    const isRoutineDeleted = useSelector(selectWorkoutRoutineDeleted);
    const dispatch = useDispatch();
    const user = useSelector(selectUser);
    const client = useSelector(selectSelectedClient)

    syncMomentLocale(i18n.language);
    useComponentTranslations('workoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const link = `https://client.mfitpersonal.com.br/${isAerobic ? "aerobic" : "workout"}/${btoa(`${client?.id}-${workout?.id}-${user?.id}`)}`;
    const message = t("workoutComponent:linkMessage", {name: client?.nome, link: link});

    const handleCopyLink = () => {
        navigator.clipboard.writeText(message)
            .then(() => {
                dispatch(addToast({
                    type: "success",
                    message: t("workoutComponent:copiedLinkMessage"),
                    title: t("workoutComponent:copiedLink")
                }));
            })
            .catch(err => {
                console.error('Failed to copy: ', err);
            });
    };

    const handleRecoverModal = () => {
        setShowRecoverModal(prevState => !prevState)
    }

    const handleShareModal = () => {
        setShareModal(prevState => !prevState)
    }

    const handleShowDeleteModal = () => {
        setShowDeleteModal(prevState => !prevState)
    }

    const handleArchivedModal = () => {
        setArchivedModal(prevState => !prevState)
    }

    const handleEditModal = () => {
        setShowEditModal(prevState => !prevState)
    }

    const handleChangeWorkoutStatus = (status) => {
        if (isAerobic)
            dispatch(changeAerobicStatus({id: workout.id, status: status}))
        else
            dispatch(changeWorkoutRoutineStatus({id: workout.id, status: status}))
    }

    const handleGoToWorkout = isAerobic ?
        workout.status !== 2 ? `/user/client/${client?.id}/workout/aerobic/view/${workout?.id}${workout.status !== 0 ? "/archived" : ""}` : ""
        : workout.status !== 3 ? `/user/client/${client?.id}/workout/routine/${workout?.id}${workout.status !== 0 ? "/archived" : ""}` : ""

    const handleWorkoutRoutine = () => {
        navigate(`/user/client/${client?.id}/workout/routine/${workout?.id}/update`)
    }

    useEffect(() => {
        if (isRoutineDeleted) {
            dispatch(changeRoutineDeletedStatus(false))
        }
    }, [isRoutineDeleted, dispatch])

    return (
        <div className={`card card-body clickable-element mt-2`}>
            <div className={"row d-flex   justify-content-between"}>
                <div className={'col-2 col-md-3 col-lg-2 text-center align-self-center'}>
                    <Link to={handleGoToWorkout} className={"text-decoration-none text-default"}>
                        <WorkoutIcon obj={workout.objetivo} gender={client?.sexo}/>
                    </Link>
                </div>
                <div className={'col-8 col-md-7 col-lg-8 align-self-center ps-1 ps-lg-1  '}>
                    <Link to={handleGoToWorkout} className={"text-decoration-none text-default"}>
                    <span className={'fw-semibold d-block'}>
                        <Text>{workout.nome}</Text>
                    </span>
                        {
                            isAerobic && workout.dataInicio &&
                            <span className={'d-block text-md'}>
                                <i className="fa-regular fa-calendar-lines"></i>&nbsp;&nbsp;{moment(workout.dataInicio).format('L')} - {moment(workout.dataFinal).format('L')}
                            </span>
                        }
                        {
                            !isAerobic &&
                            <>
                                <span className={'d-block text-md'}>
                                    <i className="fa-regular fa-calendar-lines"></i>&nbsp;&nbsp;{moment(workout.dataInicio).format('L')} - {moment(workout.dataFim).format('L')}
                                </span>
                                <div className={'row justify-content-center d-flex  mt-1'}>
                                    <div className={'col-12'}>
                                        <div className={'row   d-flex text-muted small'}>
                                            <div className={'col-auto'}>
                                                {t(`workoutComponent:${getObjective(workout.objetivo)}`)} | {t(`workoutComponent:${getDifficulty(workout.dificuldade)}`)}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </>
                        }
                    </Link>
                </div>
                <div className={"col-1 col-md-2 clickable-element text-end ps-0"}>
                    <Dropdown align={"end"}>
                        <Dropdown.Toggle
                            as={"button"}
                            className={"btn btn-link border-0 text-dark p-1 dropdown-toggle-no-caret "}
                            aria-label={"Opções do treino"}
                            id={`workout-actions-${workout.id}`}
                        >
                            <i className={"fa-regular fa-ellipsis-vertical"}></i>
                        </Dropdown.Toggle>
                        <Dropdown.Menu>
                            <Dropdown.Item onClick={handleShareModal}>
                                <i className="fa-regular fa-share-nodes me-2"/> {t("workoutComponent:share")}
                            </Dropdown.Item>
                            {
                                isAerobic
                                    ? <WorkoutAerobicClone workout={workout} type={1} clientId={client?.id}/>
                                    : <WorkoutRoutineClone type={0} workout={workout} clientId={client?.id}/>
                            }
                            {isAerobic ? (
                                <Dropdown.Item onClick={handleEditModal}>
                                    <i className="fa-regular fa-pen-to-square me-2"/> {t("workoutComponent:edit")}
                                </Dropdown.Item>
                            ) : (
                                <Dropdown.Item onClick={handleWorkoutRoutine}>
                                    <i className="fa-regular fa-pen-to-square me-2"/> {t("workoutComponent:edit")}
                                </Dropdown.Item>
                            )}
                            {workout.status === 0 && (
                                <>
                                    <Dropdown.Item
                                        disabled={isAerobicStatusChanging || isRoutineStatusChanging}
                                        onClick={() => handleChangeWorkoutStatus(1)}
                                    >
                                        <i className="fa-regular fa-box-archive me-2"/> {t("workoutComponent:archive")}
                                    </Dropdown.Item>
                                    <Dropdown.Divider/>
                                    <Dropdown.Item className="text-danger" onClick={handleShowDeleteModal}>
                                        <i className="fa-regular fa-trash-can me-2"/> {t("workoutComponent:delete")}
                                    </Dropdown.Item>
                                </>
                            )}
                            {workout.status === 1 && (
                                <>
                                    <Dropdown.Item
                                        disabled={isAerobicStatusChanging || isRoutineStatusChanging}
                                        onClick={() => handleChangeWorkoutStatus(0)}
                                    >
                                        <i className="fa-regular fa-rotate-left me-2"/> {t("workoutComponent:reopen")}
                                    </Dropdown.Item>
                                    <Dropdown.Divider/>
                                    <Dropdown.Item className="text-danger" onClick={handleShowDeleteModal}>
                                        <i className="fa-regular fa-trash-can me-2"/> {t("workoutComponent:delete")}
                                    </Dropdown.Item>
                                </>
                            )}
                            {(workout.status === 2 || workout.status === 3) && (
                                <Dropdown.Item
                                    disabled={isAerobicStatusChanging || isRoutineStatusChanging}
                                    onClick={() => handleChangeWorkoutStatus(0)}
                                >
                                    <i className="fa-regular fa-rotate-left me-2"/> {t("workoutComponent:yesRecover")}
                                </Dropdown.Item>
                            )}
                        </Dropdown.Menu>
                    </Dropdown>
                </div>
            </div>
            <Modal show={shareModal} centered onHide={handleShareModal}>
                <Modal.Body>
                    <ShareComponent link={link} handleCopyLink={handleCopyLink} handleClose={handleShareModal}
                                    handleWhatsAppLink={() => handleSendWhatsApp(client?.telefone, message)}/>
                </Modal.Body>
            </Modal>
            <Modal show={showRecoverModal} centered onHide={handleRecoverModal}>
                <Modal.Body>
                    <div className={"row pt-2"}>
                        <div className={"col-12"}>
                            <ChangeStatus
                                icon={"fa-regular fa-circle-exclamation"}
                                iconColor={"text-warning"}
                                title={t("workoutComponent:recoverRoutineTitle")}
                                subtitle={t("workoutComponent:recoverRoutineSubTitle")}
                            />
                        </div>
                        <div className={'col-12 mt-3'}>
                            <div className={'d-grid'}>
                                <button className="btn btn-warning mb-2 text-white"
                                        disabled={isAerobicStatusChanging || isRoutineStatusChanging}
                                        onClick={() => handleChangeWorkoutStatus(0)}>
                                    {t("workoutComponent:yesRecover")}
                                </button>
                                <button className="btn btn-outline-warning" onClick={handleRecoverModal}>
                                    {t("workoutComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            <Modal show={showDeleteModal} centered onHide={handleShowDeleteModal}>
                <Modal.Body>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation"}
                        iconColor={"text-danger"}
                        title={t("workoutComponent:deleteRoutineTitle")}
                    />
                    <div className="row mt-3 justify-content-center">
                        <div className="col-12">
                            <div className="d-grid">
                                <button className="btn btn-danger"
                                        disabled={isAerobicStatusChanging || isRoutineStatusChanging}
                                        onClick={() => handleChangeWorkoutStatus(isAerobic ? 2 : 3)}>
                                    {t("workoutComponent:delete")}
                                </button>
                            </div>
                            <div className="d-grid mt-2">
                                <button className="btn btn-outline-danger" onClick={handleShowDeleteModal}>
                                    {t("workoutComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            <Modal show={archivedModal} onHide={handleArchivedModal} centered>
                <Modal.Body>
                    <div className={"row d-flex justify-content-between"}>
                        <div className={'col-auto'}>
                            <span className={"fw-semibold fs-5"}>{t("workoutComponent:whatYouWannaDo")}</span>
                        </div>
                        <div className={'col-auto align-self-center clickable-element'} onClick={handleArchivedModal}>
                            <i className={"fs-5 fa-solid fa-times"}></i>
                        </div>
                    </div>
                    <div className={"row d-flex justify-content-between"}>
                        <div className={'col-12 mt-2'}>
                            <div className={"d-grid"}>
                                {
                                    isAerobic ?
                                        <WorkoutAerobicClone workout={workout} type={1} clientId={client?.id}/> :
                                        <WorkoutRoutineClone type={0} workout={workout} clientId={client?.id}/>
                                }
                            </div>
                        </div>
                        <div className={'col-12 mt-2'}>
                            <button className={"btn btn-outline-primary w-100"}
                                    disabled={isAerobicStatusChanging || isRoutineStatusChanging}
                                    onClick={() => handleChangeWorkoutStatus(0)}>{t("workoutComponent:reopen")}
                            </button>
                        </div>
                        <div className={'col-12 mt-2'}>
                            <button className={"btn btn-outline-danger w-100"}
                                    onClick={handleShowDeleteModal}>{t("workoutComponent:delete")}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            <Modal show={showEditModal} centered onHide={handleEditModal}>
                <Modal.Body>
                    <WorkoutAerobicNameForm workout={workout} onClose={handleEditModal}/>
                </Modal.Body>
            </Modal>
        </div>
    );
}
export default WorkoutCard;