import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import {formatElapsedTime, getFeedbackIntensity} from "../../utils/workout/Workout";
import {useState} from "react";
import {Field, Form, Formik} from "formik";
import {useDispatch, useSelector} from "react-redux";
import {isFeedbackResolving} from "../../store/feedback/feedbackSelector";
import LoadingBlock from "../loader/LoadingBlock";
import {resolveFeedback} from "../../store/feedback/feedbackReducer";
import 'moment/locale/pt-br';
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Text from "../utils/emoji/Text";
import {Link} from "react-router-dom";
import Avatar from "../avatar/Avatar";

const FeedbackCard = ({feedback}) => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const loading = useSelector(isFeedbackResolving)
    const [expanded, setExpanded] = useState(false);
    syncMomentLocale(i18n.language);
    useComponentTranslations('feedbackComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleClickWorkout = `/user/client/${feedback.idAluno}/workout/routine/${feedback.idRoutine}/session/${feedback.idSession}/prescribe/feedbacks`

    const handleGoToAerobicTrainingClick = `/user/client/${feedback.idAluno}/workout/aerobic/view/${feedback.idRoutine}/feedbacks`

    const handleGoToClientClick = `/user/client/${feedback.idAluno}`

    const handleAnswerButton = (values) => {
        if (expanded) {
            const payload = {
                id: feedback.id,
                formData: values
            }
            dispatch(resolveFeedback(payload));
        }
        setExpanded(prevState => !prevState)
    }

    const handleResolveFeedback = () => {
        dispatch(resolveFeedback({id: feedback.id}))
    }

    const dataInicio = moment({
        day: feedback.workoutStartTime?.date.day,
        month: feedback.workoutStartTime?.date.month - 1,
        year: feedback.workoutStartTime?.date.year,
        hour: feedback.workoutStartTime?.time.hour,
        minute: feedback.workoutStartTime?.time.minute,
        second: feedback.workoutStartTime?.time.second
    });

    const dataFim = moment({
        day: feedback.workoutEndTime?.date.day,
        month: feedback.workoutEndTime?.date.month - 1,
        year: feedback.workoutEndTime?.date.year,
        hour: feedback.workoutEndTime?.time.hour,
        minute: feedback.workoutEndTime?.time.minute,
        second: feedback.workoutEndTime?.time.second
    });

    if (loading)
        return <LoadingBlock/>

    return (
        <div className={"card card-body border-0 mb-3"}>
            <div className={"row justify-content-between"}>
                <div className={"col-2 me-n5 mx-n2"}>
                    <Avatar maxWidth={"24px"} url={feedback?.clientProfileUrl}/>
                </div>
                <div className={"col-6"}>
                    <Link to={handleGoToClientClick}
                          className={'fw-semibold text-decoration-none text-default '}><Text>{feedback.clientName}</Text></Link>
                </div>
                <div className={'col-4 text-end align-self-center'}>
                    <span className={'badge rounded-pill border border-primary bg-white text-primary'}>
                        {
                            feedback.fonteFeedback === 0 && t("feedbackComponent:training")
                        }
                        {
                            feedback.fonteFeedback === 1 && t("feedbackComponent:aerobic")
                        }
                        {
                            feedback.fonteFeedback === 2 && t("feedbackComponent:extraTraining")
                        }
                    </span>
                </div>
            </div>
            <div className={'row justify-content-center mt-2 text-md'}>
                <div className={'col-12 text-md align-self-center'}>
                    <span className={'pe-3'}>
                        <i className={'fa-regular fa-calendar'}></i> {moment(dataFim.isValid() ? dataFim : {
                        year: feedback.dataExecucao.date.year,
                        month: feedback.dataExecucao.date.month - 1,
                        day: feedback.dataExecucao.date.day
                    }).format("L")}</span>
                    <span>
                        <i className={"fa-regular fa-clock"}></i> {moment(dataFim.isValid() ? dataFim : {
                        hour: feedback.dataExecucao.time.hour,
                        minute: feedback.dataExecucao.time.minute,
                    }).format("HH:mm")}
                    </span>
                </div>
                <div className={'col-12 mt-2 '}>
                    <span
                        className={'fw-semibold'}>{t("feedbackComponent:intensity")}: </span>
                    {t(`feedbackComponent:${getFeedbackIntensity(feedback.borgNota)}`)}
                </div>
                <div className={'col-12 mt-2'}>
                    <span className={"fw-semibold"}>{t("feedbackComponent:feedback")}: </span>
                    {
                        feedback.feedback !== "" ?
                            <Text>{feedback.feedback}</Text> :
                            <span>{t("feedbackComponent:clientDidntLeaveComments")}</span>
                    }
                </div>
                {
                    feedback.workoutStartTime &&
                    <>
                        <div className={'col-11 text-md bg-secondary-subtle mt-3 rounded-2 p-2  ps-4 pe-4'}>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto '}>
                                    <span className={'fw-semibold  text-md'}>{t("feedbackComponent:start")}:</span>
                                </div>
                                <div className={'col-auto text-end'}>
                                    <span className={"text-md"}>
                                        {moment(dataInicio).format("DD/MM/YYYY HH:mm")}
                                    </span>
                                </div>
                            </div>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold text-md'}>{t("feedbackComponent:end")}:</span>
                                </div>
                                <div className={'col-auto text-end'}>
                                    <span className={'text-md '}>
                                        {moment(dataFim).format("DD/MM/YYYY HH:mm")}
                                    </span>
                                </div>
                            </div>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold'}>{t("feedbackComponent:trainingTime")}:</span>
                                </div>
                                <div className={'col-auto  text-end'}>
                                    <span className={' fw-semibold'}>
                                        {formatElapsedTime(dataFim.diff(dataInicio, 'seconds'))}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </>
                }
                {
                    expanded ?
                        <div className={"col-12 pt-4"}>
                            <Formik
                                initialValues={{response: ''}}
                                onSubmit={(values) => {
                                    handleAnswerButton(values);
                                }}
                            >
                                {() => (
                                    <Form>
                                        <div className="mb-3">
                                            <label htmlFor="response" className="form-label fw-semibold">{t("feedbackComponent:response")}</label>
                                            <Field
                                                as="textarea"
                                                id="response"
                                                name="response"
                                                className="form-control"
                                                rows="5"
                                                style={{height: "100px"}}
                                            />
                                        </div>
                                        <div className={"d-grid mb-2"}>
                                            <button className={"btn btn-primary-lighter"} type={"submit"}>{t("feedbackComponent:respond")}</button>
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                        </div> :
                        <>
                            <div className={"col-12 pt-2 mb-2 text-center"}>
                                {
                                    feedback.fonteFeedback === 0 &&
                                    <Link className={"btn btn-link fw-semibold "} to={handleClickWorkout}
                                    >{t("feedbackComponent:seeWorkout")}</Link>
                                }
                                {
                                    feedback.fonteFeedback === 1 &&
                                    <Link className={"btn btn-link fw-semibold "} to={handleGoToAerobicTrainingClick}
                                    >{t("feedbackComponent:seeWorkout")}</Link>
                                }
                            </div>
                            <div className={"d-grid mb-2"}>
                                <button className={"btn btn-primary-lighter"} onClick={handleAnswerButton}>{t("feedbackComponent:respond")}</button>
                            </div>
                        </>
                }
                <div className={'col-12'}>
                    <div className={"d-grid"}>
                        <button className={"btn btn-outline-primary"} onClick={handleResolveFeedback}>{t("feedbackComponent:resolve")}</button>
                    </div>
                </div>
            </div>
        </div>
    )
}
export default FeedbackCard
