export const getRetentionStatusMeta = (status, t) => {
    const base = {
        label: t("retention:all"),
        badgeClass: "bg-secondary-subtle text-secondary",
        progressClass: "bg-secondary",
        dotClass: "bg-secondary-subtle"
    };

    const map = {
        ENGAGED: {
            label: t("retention:engaged"),
            badgeClass: "bg-success-subtle text-success",
            progressClass: "bg-success",
            dotClass: "bg-success"
        },
        OSCILLATING: {
            label: t("retention:oscillating"),
            badgeClass: "bg-warning-subtle text-warning",
            progressClass: "bg-warning",
            dotClass: "bg-warning-light"
        },
        AT_RISK: {
            label: t("retention:atRisk"),
            badgeClass: "bg-warning-subtle text-warning",
            progressClass: "bg-warning",
            dotClass: "bg-warning-darker"
        },
        ABANDONED: {
            label: t("retention:abandoned"),
            badgeClass: "bg-danger-subtle text-danger",
            progressClass: "bg-danger",
            dotClass: "bg-danger"
        },
        RECOVERED: {
            label: t("retention:recovered"),
            badgeClass: "bg-info-subtle text-primary",
            progressClass: "bg-primary",
            dotClass: "bg-primary"
        },
        ALL: base
    };

    return map[status] || base;
};

const TEMPLATE_PREFIX = {
    ENGAGED: "engaged",
    OSCILLATING: "oscillating",
    AT_RISK: "atRisk",
    ABANDONED: "abandoned",
    RECOVERED: "recovered"
};

const TEMPLATE_KEY_PREFIX = {
    ENGAGED: "engaged",
    OSCILLATING: "oscillating",
    AT_RISK: "at_risk",
    ABANDONED: "abandoned",
    RECOVERED: "recovered"
};

export const getRetentionSuggestedMessages = (status, t) => {
    const templatePrefix = TEMPLATE_PREFIX[status];
    const keyPrefix = TEMPLATE_KEY_PREFIX[status];

    if (!templatePrefix || !keyPrefix) {
        return [];
    }

    return Array.from({length: 3}, (_, index) => {
        const item = index + 1;
        const label = t(`retention:${templatePrefix}SuggestedMessage${item}Label`);
        return {
            key: `${keyPrefix}_${item}`,
            label,
            title: label,
            message: t(`retention:${templatePrefix}SuggestedMessage${item}Body`)
        };
    });
};

