export const getRetentionPeriodLabel = (period, t) => {
    const map = {
        LAST_3_MONTHS: t("retention:last3Months"),
        LAST_6_MONTHS: t("retention:last6Months"),
        CURRENT_YEAR: t("retention:currentYear"),
        PREVIOUS_YEAR: t("retention:previousYear"),
        ALL_TIME: t("retention:allTime")
    };

    return map[period] || period;
};

export const formatMetricValue = (metric, value, locale) => {
    const numericValue = Number(value || 0);

    if (metric === "ACTIVE_CLIENTS") {
        return new Intl.NumberFormat(locale, {maximumFractionDigits: 0}).format(numericValue);
    }

    return `${new Intl.NumberFormat(locale, {
        minimumFractionDigits: 0,
        maximumFractionDigits: 1
    }).format(numericValue)}%`;
};

export const formatDelta = (value, locale) => {
    const numericValue = Number(value || 0);
    const prefix = numericValue > 0 ? "+" : "";
    return `${prefix}${new Intl.NumberFormat(locale, {
        minimumFractionDigits: 0,
        maximumFractionDigits: 1
    }).format(numericValue)}%`;
};

const parseRetentionDate = (value) => {
    if (typeof value !== "string") {
        return null;
    }

    const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) {
        return null;
    }

    const parsedDate = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    return Number.isNaN(parsedDate.getTime()) ? null : parsedDate;
};

export const formatRetentionDate = (value, locale) => {
    const parsedDate = parseRetentionDate(value);
    if (!parsedDate) {
        return "-";
    }

    const formatter = new Intl.DateTimeFormat(locale, {
        day: "numeric",
        month: "short",
        year: "numeric"
    });
    const parts = formatter.formatToParts(parsedDate);
    const day = parts.find((part) => part.type === "day")?.value;
    const month = parts.find((part) => part.type === "month")?.value?.replace(/\.$/, "");
    const year = parts.find((part) => part.type === "year")?.value;

    if (!day || !month || !year) {
        return formatter.format(parsedDate);
    }

    return String(locale || "").toLowerCase().startsWith("en")
        ? `${month} ${day}, ${year}`
        : `${day} ${month} ${year}`;
};

export const formatRetentionDateRange = (start, end, locale) => {
    const formattedStart = formatRetentionDate(start, locale);
    const formattedEnd = formatRetentionDate(end, locale);

    if (formattedStart === "-" || formattedEnd === "-") {
        return "-";
    }

    return `${formattedStart} - ${formattedEnd}`;
};
