function* cleanCombinedExercises() {
    const session = yield select(selectWorkoutSession);
    if (!session?.exerciciosMontados) return;
    for (const arr of Object.values(session.exerciciosMontados)) {
        for (const ex of arr) {
            if (ex.isCombinado) {
                const hasExerciseSerie = Array.isArray(ex.series) && ex.series.some(s => s.tipo === 6 && s.idExerc > 0);
                if (!hasExerciseSerie) {
                    yield put(deleteExerciseFromSession({sessionId: session.id, exercSessionId: ex.idExercSession}));
                }
            }
        }
    }
}


export function* fetchWorkoutSessionAsync(action) {

    try {
        const response = yield call(getWorkoutSessionByIdAPI, action.payload)
        yield put(setWorkoutSession(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchWorkoutSession() {
    yield takeLatest(fetchWorkoutSession.type, fetchWorkoutSessionAsync)
}

