import {useState} from 'react';
import {useDispatch, useSelector} from 'react-redux';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from 'he';
import TextareaAutosize from "react-textarea-autosize";
import {updateSessionDescription} from "../../store/workout-prescription/workoutPrescriptionReducer";
import {selectWorkoutDescriptionUpdating} from "../../store/workout-prescription/workoutPrescriptionSelector";

const WorkoutSessionInstructions = ({instructions, sessionId}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const loading = useSelector(selectWorkoutDescriptionUpdating);
    const [isOpen, setIsOpen] = useState(false);
    useComponentTranslations('workoutPrescriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const initialValues = {
        description: he.decode(instructions || "")
    };

    const toggleInstructions = () => {
        setIsOpen(prevState => !prevState);
    };

    const handleSubmit = (values) => {
        dispatch(updateSessionDescription({id: sessionId, data: values}));
    };

    return (
        <div className="card card-body border-0">
            <div className="row justify-content-between" onClick={toggleInstructions} style={{cursor: 'pointer'}}>
                <div className="col-auto">
                    <span className={"fw-semibold"}>{t("workoutPrescriptionComponent:generalOrientation")}</span>
                </div>
                <div className="col-auto">
                    <span>
                        <i className={`fa-regular ${isOpen ? 'fa-chevron-up' : 'fa-chevron-down'}`}></i>
                    </span>
                </div>
            </div>
            {
                isOpen &&
                <div className="row mt-2">
                    <div className="col-12">
                        <Formik initialValues={initialValues}  onSubmit={handleSubmit}>
                            {() => (
                                <Form>
                                    <Field name="description">
                                        {({field}) => (
                                            <TextareaAutosize
                                                {...field}
                                                id="description"
                                                className="form-control"
                                                minRows={3}
                                                style={{transition: 'height 0.2s ease, max-height 0.2s ease', overflow: 'hidden'}}
                                            />
                                        )}
                                    </Field>
                                    <ErrorMessage name="description" component="div" className="text-danger"/>
                                    <button type="submit" className="btn btn-primary mt-3 w-100" disabled={loading}>
                                        {loading ?  t('workoutPrescriptionComponent:saving')  : t('workoutPrescriptionComponent:save')}
                                    </button>
                                </Form>
                            )}
                        </Formik>
                    </div>
                </div>
            }
        </div>
    );
};

export default WorkoutSessionInstructions;
