import _ from "lodash";
import {useTranslation} from "react-i18next";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import React, {useEffect, useState, useMemo} from "react";
import {selectWorkoutRoutineLoading, selectWorkoutRoutineProgress} from "../../store/workout-routine/workoutRoutineSelector";
import moment from "moment/moment";
import WorkoutProgressChart from "../../components/workout-routine/WorkoutProgressChart";
import {fetchWorkoutProgress} from "../../store/workout-routine/workoutRoutineReducer";
import Page from "../../components/page/Page";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EmptySet from "../../components/empty-set/EmptySet";

const WorkoutProgress = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const {sessionId, id, clientId, goBackToSession} = useParams();
    const dispatch = useDispatch();
    const workoutProgress = useSelector(selectWorkoutRoutineProgress);
    const loading = useSelector(selectWorkoutRoutineLoading);
    const [tabToShow, setTabToShow] = useState(0);
    useComponentTranslations('workoutRoutine', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        dispatch(fetchWorkoutProgress(sessionId));
    }, [dispatch, sessionId]);

    // Group pivoted views back into single superset objects
    const groupedProgress = useMemo(() => {
        if (!workoutProgress || workoutProgress.length === 0) return [];
        const byExerc = _.groupBy(workoutProgress, 'idExerc');
        return Object.values(byExerc).map(group => {
            if (group.length === 1) return group[0];
            // combine dataViews
            const dates = group[0].dataView.map(dv => dv.data);
            const combined = dates.map((date, idx) => ({
                data: date,
                cargas: group.map(v => (v.dataView[idx] && v.dataView[idx].cargas[0]) ?? null)
            }));
            return {...group[0], dataView: combined};
        });
    }, [workoutProgress]);

    const handleGoBack = () => {
        if (goBackToSession) {
            navigate(`/user/client/${clientId}/workout/routine/${id}/session/${sessionId}/prescribe`)
        } else {
            navigate(`/user/client/${clientId}/workout/routine/${id}`)
        }
    }

    return (
        <Page contentHeader={true} loading={loading} title={t("workoutRoutine:progress")} mt={"mt-n5"} goBackLink={handleGoBack} xl={"6"}>
            {
                groupedProgress.length > 0 &&
                <div className={'row justify-content-center d-flex'}>
                    <div className={"col-12 "}>

                        <div className={'card card-body'}>
                            <nav className={'pb-2'}>
                                <div className="nav nav-tabs" id="nav-tab" role="tablist">
                                    <button className={` nav-link ${tabToShow === 0 ? ' active' : ''}`} id="nav-home-tab"
                                            data-bs-toggle="tab" data-bs-target="#nav-home" type="button" role="tab" aria-controls="nav-home"
                                            onClick={() => setTabToShow(0)} aria-selected="true">{t("workoutRoutine:charts")}</button>
                                    <button className={` nav-link ${tabToShow === 1 ? ' active' : ''}`} id="nav-profile-tab"
                                            data-bs-toggle="tab" data-bs-target="#nav-profile" type="button" role="tab"
                                            onClick={() => setTabToShow(1)} aria-controls="nav-profile" aria-selected="false">{t("workoutRoutine:sheet")}</button>
                                </div>
                            </nav>
                            <div className="tab-content" id="nav-tabContent">
                                <div className={`tab-pane fade  ${tabToShow === 0 ? 'show active' : ''}`} id="nav-home"
                                     role="tabpanel" aria-labelledby="nav-home-tab" tabIndex="0">
                                    <div className={'row justify-content-center'}>
                                        {_.map(groupedProgress, (wp, index) => (
                                            <div key={index} className={'col-12 col-md-6 pt-2 pb-4'}>
                                                <WorkoutProgressChart wp={wp}/>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                                <div className={`tab-pane fade ${tabToShow === 1 ? 'show active' : ''}`} id="nav-profile"
                                     role="tabpanel" aria-labelledby="nav-profile-tab" tabIndex="0">
                                    <div className={"table-responsive"}>
                                        <table className={'table'}>
                                            <tbody>
                                            {_.map(groupedProgress, (wp, index) => (
                                                <tr key={index}>
                                                    <th className="align-self-center">
                                                        <pre className={'mb-0'} >
                                                           {wp.exerciseName?.replace(/<br\s*\/?>/gi, '\n').trim()}
                                                        </pre>
                                                    </th>
                                                    {_.map(wp.dataView, (dv, di) => (
                                                        <React.Fragment key={di + 9999}>
                                                            <td><i className='fa-regular fa-long-arrow-right fa-lg'></i></td>
                                                            <td className={'text-center'}>
                                                                <span className={'text-md mb-2 d-block'}>
                                                                    {moment({ year: dv.data.year, month: dv.data.month - 1, day: dv.data.day }).format('L')}
                                                                </span>
                                                                {_.map(dv.cargas, (cg, ci) => (
                                                                    <span className={'d-block font-weight-bold bg-primary-lighter text-white px-2 mb-1'}
                                                                          style={{borderRadius: "10px"}}
                                                                          key={ci + 999999}>{cg}kg</span>
                                                                ))}
                                                            </td>
                                                        </React.Fragment>
                                                    ))}
                                                </tr>
                                            ))}
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            }
            {
                !loading && groupedProgress.length === 0 &&
                <div className={"row "}>
                    <div className={"col-12 text-center"}>
                        <div className={"card card-body border-0"}>
                            <EmptySet icon={"fa-regular fa-chart-mixed"} message={t("workoutRoutine:emptyProgressMessage")}/>
                        </div>
                    </div>
                </div>
            }
        </Page>
    )
}

export default WorkoutProgress;
