import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import React from "react";
import Page from "../../components/page/Page";
import EmptySet from "../../components/empty-set/EmptySet";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import {selectAllCustom, getCustomLoading} from "../../store/custom-evaluation/customEvaluationSelector";
import CustomEvaluationCard from "../../components/custom-evaluation/CustomEvaluationCard";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import {useTranslation} from "react-i18next";
import CustomEvaluationActionsButtons from "../../components/custom-evaluation/CustomEvaluationActionsButtons";
import {useCustomActions} from "../../utils/customEvaluation/useCustomActions";
import EvaluationCompareBarComponent from "../../components/evaluation-components/EvaluationCompareBarComponent";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "../custom-evaluation/locales/es-es.json";
import ptPT from "../custom-evaluation/locales/pt-pt.json";
import ptBR from "../custom-evaluation/locales/pt-br.json";
import enUS from "../custom-evaluation/locales/en-us.json";
import {useNavigate, useParams} from "react-router-dom";
import {buildCustomModelsRoute} from "../../utils/client/evaluationRoutes";
import {fetchClient} from "../../store/client/clientReducer";
import {getAllCustom, resetFormSent} from "../../store/custom-evaluation/customEvaluationReducer";

const CustomEvaluation = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const loadingClient = useSelector(isClientsLoading);
    const customList = useSelector(selectAllCustom);
    const loadingCustom = useSelector(getCustomLoading);
    const {t} = useTranslation();
    syncMomentLocale(i18n.language);
    useComponentTranslations('customEvaluation', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})

    const {
        state: {isComparing, selectedList, showOptionsModal, showShareModal, showDeleteModal, currentCustom, deleteSubmitting},
        handlers,
        shareWhatsLink
    } = useCustomActions();
    const MAX_SELECTION = 3;

    const goCreateModel = () => {
        navigate(buildCustomModelsRoute(selectedClient.id));
    };

    React.useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    React.useEffect(() => {
        if (id) {
            dispatch(fetchClient(id));
            dispatch(getAllCustom({clientId: id, status: 0}));
        }
    }, [dispatch, id]);

    return (
        <>
            <AvatarHeader
                showGoBack={handlers.goBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loadingCustom} pb={"pb-2"}>
                <div className={"card card-body border-0"}>
                    {!loadingCustom && (
                        <>
                            <span className={"fw-semibold"}>{t("customEvaluation:customEvaluation")}</span>
                            <div className={"pt-2"}>
                                <CardButtonAdd
                                    text={t("customEvaluation:newEvaluation")}
                                    handleClick={goCreateModel}
                                />
                            </div>
                            <div className={"row justify-content-center d-flex"}>
                                <div className={"row py-3"}>
                                    <button className={"btn btn-secondary-default w-100"} onClick={handlers.goDeleted}>
                                        <span className={"text-primary"}>{t("customEvaluation:deleted")}</span>
                                    </button>
                                </div>
                            </div>
                            <span className={"fw-semibold"}>{t("customEvaluation:lastEvaluations")}</span>
                        </>
                    )}
                    {!loadingCustom && customList && customList.length === 0 && (
                        <EmptySet icon={"fa-regular fa-folder-open"}
                                  message={t("customEvaluation:emptySetCreated")}/>
                    )}
                    {!loadingCustom && customList && customList.length > 0 && (
                        <div className={"row justify-content-center d-flex"}>
                            <div className={"col-12"}>
                                <div className={"p-2"}>
                                    {customList.map((item) => (
                                        <CustomEvaluationCard
                                            key={item.id}
                                            custom={item}
                                            title={item.tipo}
                                            isComparing={isComparing}
                                            isSelected={selectedList.includes(item.id)}
                                            onCompare={handlers.comparingMode}
                                            onToggle={handlers.toggleSelection}
                                            onCardClick={() => handlers.openOptionsModal(item)}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}
                    {isComparing && (
                        <EvaluationCompareBarComponent
                            selectedCount={selectedList.length}
                            maxSelection={MAX_SELECTION}
                            onCompare={handlers.goCompare}
                            onClose={handlers.comparingMode}
                            compareLabel={t("customEvaluation:compare")}
                            selectLabel={t("customEvaluation:select")}
                        />
                    )}
                </div>
            </Page>
            <CustomEvaluationActionsButtons
                state={{
                    currentCustom,
                    showOptionsModal,
                    showShareModal,
                    showDeleteModal,
                    deleteSubmitting,
                    selectedList,
                    isComparing
                }}
                handlers={handlers}
                shareWhatsLink={shareWhatsLink}
            />
        </>
    )
}

export default CustomEvaluation;
