import WorkoutSerieForm from "./WorkoutSerieForm";
import WorkoutStopwatchModal from "./WorkoutStopwatchModal";
import {useState} from "react";
import {useSelector} from "react-redux";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/workout-session/locales/en-us.json";
import ptBR from "../../pages/workout-session/locales/pt-br.json";
import esES from "../../pages/workout-session/locales/es-es.json";
import ptPT from "../../pages/workout-session/locales/pt-pt.json";
import WorkoutTimeSeries from "./WorkoutTimeSeries";
import Text from "../utils/emoji/Text";
import {getPreview} from "../../store/workout-session/workoutSessionSelector";

const WorkoutSeries = ({serie, showEdit = true}) => {
    const {t} = useTranslation();
    const preview = useSelector(getPreview)
    const [show, setShow] = useState(false);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const handleStopwatchOpen = () => {
        if (!preview)
            setShow(true)
    };
    const handleStopwatchClose = () => {
        setShow(false)
    };

    const getType = () => {
        switch (serie.tipo) {
            case 4:
            case 0:
            case 1:
                return (
                    <>
                        {
                            serie.repeticao &&
                            <div className={'row d-flex'}>
                                <div className={'col-auto'}>
                                    <span
                                        className={'fw-semibold'}>{t("workout:series")}:</span> {(serie.repeticao | 0) > 0 ? serie.repeticao + " reps" : serie.repeticao}
                                </div>
                            </div>
                        }
                        <div className={'row d-flex '}>
                            <div className={'col-auto'}>
                                <span className={'fw-semibold'}>{t("workout:load")}:&nbsp; </span>
                                <WorkoutSerieForm sessionId={serie.idExercSession} unit={"kg"}
                                                  serieId={serie.id}
                                                  val={serie.carga}
                                                  preview={preview}
                                                  showEdit={showEdit}
                                />
                            </div>
                        </div>
                        {
                            serie.tempo &&
                            <WorkoutTimeSeries serie={serie}/>
                        }
                    </>
                )
            case 2:
                return (
                    <>
                        {
                            serie.repeticao &&
                            <div className={'row d-flex'}>
                                <div className={'col-auto'}>
                                    <span
                                        className={'fw-semibold'}>{t("workout:series")}:</span> {(serie.repeticao | 0) > 0 ? serie.repeticao + " reps" : serie.repeticao}
                                </div>
                            </div>
                        }
                        {
                            serie.tempo &&
                            <WorkoutTimeSeries serie={serie}/>
                        }
                    </>
                )
            case 3:
                return (
                    <>
                        {
                            serie.velocidade &&
                            <div className={'row d-flex'}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold'}>{t("workout:speed")}:</span> {serie.velocidade}
                                </div>
                            </div>
                        }
                        {
                            serie.distancia &&
                            <div className={'row d-flex '}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold'}>{t("workout:distance")}:</span> {serie.distancia}
                                </div>
                            </div>
                        }
                        {
                            serie.tempo &&
                            <WorkoutTimeSeries serie={serie}/>
                        }

                        {
                            serie.pace &&
                            <div className={'row d-flex '}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold'}>{t("workout:pace")}:</span> {serie.pace}
                                </div>
                            </div>
                        }
                    </>
                )
            case 5 :
                return (
                    <>
                        <span className={'fw-semibold '}>{t("workout:instructions")}:</span>
                        <pre className={'mb-2 text-md '}
                             style={{
                                 lineHeight: 1.2,
                                 height: "100%",
                                 overflow: "hidden"
                             }}><Text enableAccessibility={true}>{serie?.obs?.trim()}</Text></pre>
                    </>
                )
            case 7:
                return (
                    <>
                        {
                            serie.tempo &&
                            <WorkoutTimeSeries serie={serie}/>
                        }
                        {
                            serie.inclinacao &&
                            <div className={'row d-flex '}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold '}>{t("workout:incline")}:</span> {serie.inclinacao}
                                </div>
                            </div>
                        }
                    </>
                )
            case 8:
                return (
                    <>
                        {
                            serie.cadencia &&
                            <div className={'row d-flex '}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold '}>{t("workout:cadence")}:</span> {serie.cadencia}
                                </div>
                            </div>
                        }
                    </>
                )
            default:
                break;
        }
    }
    return (
        <div className={' '}>
            {getType()}
            {
                (((serie.intervalo | 0) > 0) && serie.type !== 5 && serie.type !== 8) &&
                <div className={'row d-flex pb-2'}>
                    <div className={"col-12"}>
                        <span onClick={handleStopwatchOpen} className={'text-primary clickable-element'}><i
                            className="fa-regular fa-timer"></i> <span
                            className={'text-decoration-underline'}>{t("workout:interval")}: {serie.intervalo}s</span></span>
                    </div>
                    <WorkoutStopwatchModal
                        initialTime={serie.intervalo}
                        show={show}
                        handleClose={handleStopwatchClose}/>
                </div>
            }
        </div>
    )
}
export default WorkoutSeries;