import React, {useEffect, useRef, useState} from 'react';
import {Formik, Form, Field, useFormikContext} from 'formik';
import {useDispatch, useSelector} from 'react-redux';
import {createSerie, deleteSerie, updateSerie} from '../../store/workout-prescription/workoutPrescriptionReducer';
import Modal from 'react-bootstrap/Modal';
import ChangeStatus from '../utils/change-status/ChangeStatus';
import {selectWorkoutSession} from '../../store/workout-prescription/workoutPrescriptionSelector';
import {selectSelectedClient} from '../../store/client/clientSelector';
import {useNavigate} from 'react-router-dom';
import {useTranslation} from 'react-i18next';
import useComponentTranslations from '../../utils/translation/useComponentTranslations';
import enUS from './locales/en-us.json';
import ptBR from './locales/pt-br.json';
import esES from './locales/es-es.json';
import ptPT from './locales/pt-pt.json';
import he from 'he';
import TextareaAutosize from 'react-textarea-autosize';

function useSmoothWidth(active, text) {
    const ref = useRef(null);
    const [origWidth, setOrigWidth] = useState(null);

    useEffect(() => {
        if (ref.current && origWidth === null) {
            setOrigWidth(ref.current.getBoundingClientRect().width);
        }
    }, [origWidth]);

    useEffect(() => {
        const el = ref.current;
        if (!el || origWidth === null) return;

        const shouldExpand = text != null && text.length > 7;
        el.style.transition = 'width 0.7s ease';

        const currentWidth = el.getBoundingClientRect().width;
        el.style.width = `${currentWidth}px`;
        void el.offsetWidth;

        if (shouldExpand && active) {
            el.style.width = '100%';
        } else {
            el.style.width = `${origWidth}px`;
        }
    }, [active, text, origWidth]);

    return ref;
}

function FormFields({serie, editingField, setEditingField, isDirty, setIsDirty, padding, outerColSize, handleShowDeleteModal, handleAddExercise, t}) {

    const {values} = useFormikContext();

    const velocidadeRef = useSmoothWidth(editingField === 'velocidade', values.velocidade);
    const repeticaoRef = useSmoothWidth(editingField === 'repeticao', values.repeticao);
    const cargaRef = useSmoothWidth(editingField === 'carga', values.carga);
    const distanciaRef = useSmoothWidth(editingField === 'distancia', values.distancia);
    const tempoRef = useSmoothWidth(editingField === 'tempo', values.tempo);
    const inclinacaoRef = useSmoothWidth(editingField === 'inclinacao', values.inclinacao);
    const paceRef = useSmoothWidth(editingField === 'pace', values.pace);
    const cadenciaRef = useSmoothWidth(editingField === 'cadencia', values.cadencia);
    const obsRef = useSmoothWidth(editingField === 'obs', values.obs);

    return (
        <Form>
            <div className="row">
                <div className={`col-${outerColSize}`}>
                    <div className="row">
                        {serie.tipo === 3 && (
                            <div ref={velocidadeRef} className={`col-4 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:speed')}
                                </span>
                                <Field
                                    name="velocidade"
                                    maxLength={35}
                                    onFocus={() => {
                                        setEditingField('velocidade');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {(serie.tipo === 0 || serie.tipo === 1 || serie.tipo === 2 || serie.tipo === 4) && (
                            <div ref={repeticaoRef} className={`col-4 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:serieRep')}
                                </span>
                                <Field
                                    name="repeticao"
                                    maxLength={145}
                                    onFocus={() => {
                                        setEditingField('repeticao');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}

                        {(serie.tipo === 0 || serie.tipo === 1 || serie.tipo === 4) && (
                            <div ref={cargaRef} className={`col-4 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:weight')}
                                </span>
                                <Field
                                    name="carga"
                                    maxLength={35}
                                    onFocus={() => {
                                        setEditingField('carga');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {serie.tipo === 3 && (
                            <div ref={distanciaRef} className={`col-4 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:distance')}
                                </span>
                                <Field
                                    name="distancia"
                                    maxLength={35}
                                    onFocus={() => {
                                        setEditingField('distancia');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {(serie.tipo === 1 || serie.tipo === 2 || serie.tipo === 3 || serie.tipo === 7) && (
                            <div ref={tempoRef} className={`col-3 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:time')}
                                </span>
                                <Field
                                    name="tempo"
                                    maxLength={35}
                                    onFocus={() => {
                                        setEditingField('tempo');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {serie.tipo === 7 && (
                            <div ref={inclinacaoRef} className={`col-3 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:inclination')}
                                </span>
                                <Field
                                    name="inclinacao"
                                    maxLength={35}
                                    onFocus={() => {
                                        setEditingField('inclinacao');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {serie.tipo === 3 && (
                            <div ref={paceRef} className={`col-4 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:pace')}
                                </span>
                                <Field
                                    name="pace"
                                    maxLength={35}
                                    onFocus={() => {
                                        setEditingField('pace');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {![5, 6, 8].includes(serie.tipo) && (
                            <div className={`col-4 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:interval')}
                                </span>
                                <Field
                                    name="intervalo"
                                    type="text"
                                    inputMode="numeric"
                                    step={1}
                                    maxLength={35}
                                    pattern="\d*"
                                    onInput={e => (e.currentTarget.value = e.currentTarget.value.replace(/[^0-9]/g, ''))}
                                    onFocus={() => {
                                        setEditingField('intervalo');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {serie.tipo === 8 && (
                            <div ref={cadenciaRef} className={`col-12 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:cadence')}
                                </span>
                                <Field
                                    name="cadencia"
                                    maxLength={35}
                                    onFocus={() => {
                                        setEditingField('cadencia');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {serie.tipo === 5 && (
                            <div ref={obsRef} className={`col-12 ${padding}`}>
                                <span className="d-grid fw-semibold small">
                                  {t('workoutPrescriptionComponent:obs')}
                                </span>
                                <Field
                                    name="obs"
                                    as={TextareaAutosize}
                                    minRows={3}
                                    onFocus={() => {
                                        setEditingField('obs');
                                        setIsDirty(true);
                                    }}
                                    onBlur={() => setEditingField(null)}
                                    className="form-control form-control-sm"
                                />
                            </div>
                        )}
                        {serie.tipo === 6 && (
                            <div className="col-12">
                                <button type="button" className="btn btn-primary d-grid" onClick={handleAddExercise}>
                                    {t('workoutPrescriptionComponent:chooseExercise')}
                                </button>
                            </div>
                        )}
                    </div>
                </div>
                {serie.id === 0 && serie.tipo !== 6 && (
                    <div className="col-12 mt-3">
                        <button type="submit" className="btn btn-primary w-100">
                            {t('workoutPrescriptionComponent:add')}
                        </button>
                    </div>
                )}
                {serie.id > 0 && (
                    <div className="col-1 text-end ps-1 pe-1 align-self-center mt-3">
                        {!isDirty ? (
                            <div className="clickable-element" onClick={handleShowDeleteModal}>
                                <i className="fa-regular fa-trash text-danger"/>
                            </div>
                        ) : (
                            <button type="submit" className="btn btn-success btn-sm text-white">
                                <i className="fa-solid fa-floppy-disk"/>
                            </button>
                        )}
                    </div>
                )}
            </div>
        </Form>
    );
}

const WorkoutPrescriptionSerie = ({serie}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const session = useSelector(selectWorkoutSession);
    const client = useSelector(selectSelectedClient);
    const [isDirty, setIsDirty] = useState(false);
    const [editingField, setEditingField] = useState(null);
    const [showDelete, setShowDelete] = useState(false);
    const padding = serie.id > 0 ? 'ps-1 pe-1' : '';

    useComponentTranslations('workoutPrescriptionComponent', {
        'en-US': enUS,
        'pt-BR': ptBR,
        'es-ES': esES,
        'pt-PT': ptPT,
    });

    const handleShowDeleteModal = () => setShowDelete(prev => !prev);
    const handleAddExercise = () => navigate(
        `/user/client/${client?.id || 0}/workout/routine/${session.idRoutine}/session/${session.id}/serie/${serie.idExercSession}/add`
    );

    const handleSubmit = values => {
        const fixed = {
            ...values,
            intervalo: values.intervalo === '' ? 0 : values.intervalo,
            carga: values.carga === '' ? 0 : values.carga
        };

        const keep = ['id', 'idExercSession', 'tipo'];
        const payload = Object.fromEntries(
            Object.entries(fixed).filter(
                ([k, v]) => keep.includes(k) || (v !== '' && v != null)
            )
        );

        if (serie.id > 0) {
            dispatch(updateSerie(payload));
        } else {
            dispatch(createSerie(payload));
        }
        setEditingField(null);
        setIsDirty(false);
    };

    const outerColSize = serie.id > 0 ? '11' : '12';

    return (
        <>
            <Formik
                enableReinitialize
                initialValues={{
                    id: serie.id,
                    idExercSession: serie.idExercSession,
                    repeticao: serie.repeticao ?? '',
                    carga: serie.carga ?? '',
                    velocidade: serie.velocidade ?? '',
                    distancia: serie.distancia ?? '',
                    tempo: serie.tempo ?? '',
                    cadencia: serie.cadencia ?? '',
                    pace: serie.pace ?? '',
                    obs: he.decode(serie.obs ?? ''),
                    intervalo: serie.intervalo ?? 0,
                    inclinacao: serie.inclinacao ?? '',
                    tipo: serie.tipo,
                }}
                onSubmit={handleSubmit}
            >
                <FormFields
                    serie={serie}
                    editingField={editingField}
                    setEditingField={setEditingField}
                    isDirty={isDirty}
                    setIsDirty={setIsDirty}
                    padding={padding}
                    outerColSize={outerColSize}
                    handleShowDeleteModal={handleShowDeleteModal}
                    handleAddExercise={handleAddExercise}
                    t={t}
                />
            </Formik>

            <Modal show={showDelete} onHide={handleShowDeleteModal} centered>
                <Modal.Body>
                    <ChangeStatus
                        icon="fa-regular fa-circle-exclamation"
                        iconColor="text-danger"
                        title={t('workoutPrescriptionComponent:areYouSure')}
                        subtitle={t('workoutPrescriptionComponent:cantBeUndone')}
                    />
                    <div className="row mt-3 justify-content-center">
                        <div className="col-12">
                            <div className="d-grid">
                                <button className="btn btn-danger" onClick={() => dispatch(deleteSerie(serie.id))}>
                                    {t('workoutPrescriptionComponent:delete')}
                                </button>
                            </div>
                            <div className="d-grid mt-2">
                                <button className="btn btn-outline-danger" onClick={handleShowDeleteModal}>
                                    {t('workoutPrescriptionComponent:close')}
                                </button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    );
}

export default WorkoutPrescriptionSerie;
