import moment from 'moment-timezone';

import {useState} from "react";
import Modal from "react-bootstrap/Modal";
import {useDispatch} from "react-redux";
import {changePushStatus} from "../../store/push/pushReducer";
import {useNavigate} from "react-router-dom";
import _ from "lodash";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import Text from "../utils/emoji/Text";

const PushCard = ({notification}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const [showModal, setShowModal] = useState(false);
    const [checked, setChecked] = useState(notification.status === 0)
    const days = notification.daysOfWeek?.split(",");
    useComponentTranslations('push', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const userTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

    const utcDate = moment.tz({
        year: notification.date.date.year,
        month: notification.date.date.month - 1,
        day: notification.date.date.day,
        hour: notification.date.time.hour,
        minute: notification.date.time.minute
    }, 'UTC');

    const isPast = utcDate.isBefore(moment());

    const handleCheckChange = (e) => {
        const check = e.target.checked
        setChecked(prevState => !prevState)
        const payload = {
            id: notification.id,
            status: check ? 0 : 1
        }
        dispatch(changePushStatus(payload))
    }

    const handleOpenModal = () => {
        setShowModal(prevState => !prevState)
    }

    const handleEditPush = () => {
        navigate(`/user/push/edit/${notification.id}/${notification.type}`)
    }

    const handleChangeStatus = (status) => {
        const payload = {
            id: notification.id,
            status: status
        }
        dispatch(changePushStatus(payload))
    }

    return (
        <>
            <div className={'card card-body mb-2'}>
                <div className={'row justify-content-between'}>
                    <div className={'col-8 clickable-element'} onClick={handleOpenModal}>
                        <div className={'row '}>
                            <div className={'col-12'}>
                                <span className={'fw-semibold'}> {notification.message.length > 55
                                    ? notification.message.substring(0, 35) + '...'
                                    : notification.message}</span>
                            </div>
                            <div className={'col-12 '}>
                                {
                                    notification.sendToClients !== "0" && notification.clients?.length > 1 &&
                                    <span
                                        className={'small'}><Text>{notification.clients[0].split(" ")[0]}</Text> {t(`push:andMore`)} {notification.clients.length - 1}</span>
                                }
                                {
                                    notification.sendToClients !== "0" && notification.clients?.length === 1 &&
                                    <span
                                        className={'small'}><Text>{notification.clients[0]}</Text></span>
                                }
                                {
                                    notification.sendToClients === "0" &&
                                    <span className={'small'}>{t(`push:everyActiveClient`)}</span>
                                }
                                {
                                    notification.sendToGroups !== "0" && notification.groups?.length > 1 &&
                                    <span
                                        className={'small'}><span
                                        className={'fw-semibold'}>{t(`push:groups`)}:</span> <Text>{notification.groups[0].nome}</Text> {t(`push:andMore`)} {notification.groups.length - 1}</span>
                                }
                                {
                                    notification.sendToGroups !== "0" && notification.groups?.length === 1 &&
                                    <span
                                        className={'small'}><span className={'fw-semibold'}>{t(`push:group`)}:</span><Text>{notification.groups[0].nome}</Text></span>
                                }
                                {
                                    notification.sendToGroups === "0" &&
                                    <span className={'small'}>{t(`push:everyGroup`)}</span>
                                }
                            </div>
                            <div className={'col-12'}>
                                {
                                    notification.type === "scheduled" ?
                                        <span className={'small'}>
                                            <i className={'fa-regular fa-calendar'}></i> {utcDate.tz(userTimezone).format('DD/MM/YYYY HH:mm')}
                                        </span> :
                                        <span className={"small"}>
                                            {_.map(days, (day, index) => {
                                                const translatedDay = days.length > 3 ? t(`push:${day}`).slice(0, 3) : t(`push:${day}`).split("-")[0];
                                                return index < days.length - 1 ? `${translatedDay}, ` : translatedDay;
                                            })}
                                        </span>
                                }
                            </div>
                        </div>
                    </div>
                    <div className={'col-auto align-content-center'}>
                        {
                            notification.type === "scheduled" ?
                                <>
                                    {
                                        notification.status === 0 &&
                                        <div className={'badge bg-secondary text-white'}>
                                            <span>{t(`push:pending`)}</span>
                                        </div>
                                    }
                                    {
                                        notification.status === 1 &&
                                        <div className={'badge bg-success text-white'}>
                                            <span>{isPast ? t(`push:sent`) : t(`push:scheduled`)}</span>
                                        </div>
                                    }
                                </> :
                                <div className="form-check form-switch">
                                    <input className="form-check-input" type="checkbox" role="switch"
                                           id="flexSwitchCheckChecked" checked={checked} onChange={handleCheckChange}/>
                                </div>
                        }
                    </div>
                </div>
            </div>
            <Modal show={showModal} onHide={handleOpenModal} centered>
                <Modal.Body>
                    <div className={'row justify-content-center'}>
                        <div className={'col-12'}>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto align-content-center'}>
                                    <span className={'fw-bold'}>{t(`push:notification`)}</span>
                                </div>
                                <div className={'col-auto align-content-center clickable-element'} onClick={handleOpenModal}>
                                    <i className={'fa-regular fa-times fa-xl'}></i>
                                </div>
                            </div>
                        </div>
                        <div className={'col-12 pt-2'}>
                            <div className={'card card-body bg-secondary-subtle'}>
                                <span className={'fw-bold d-block'}>{notification.title}</span>
                                <span className={'small d-block'}>{notification.message}</span>
                            </div>
                        </div>
                        <div className={'col-12 pt-3'}>
                            {
                                notification.sendToClients && notification.sendToClients === "0" &&
                                <>
                                    <span className={'fw-bold'}>{t(`push:sendTo`)}: </span>
                                    <span>{t(`push:everyActiveClient`)}</span>
                                </>
                            }
                            {
                                notification.sendToClients && notification.sendToClients !== "0" &&
                                <>
                                    <span className={'fw-bold'}>{t(`push:sendToClients`)}: </span>
                                    {
                                        notification.clients?.length < 10 &&
                                        notification.clients?.map((client, index) => (
                                            <span key={index} className={'d-block'}><Text>{client}</Text></span>
                                        ))
                                    }
                                    {
                                        notification.clients?.length >= 10 &&
                                        <>
                                            {
                                                notification.clients?.slice(0, 11).map((client, index) => (
                                                    <span key={index} className="d-block"><Text>{client}</Text></span>
                                                ))
                                            }
                                            <span>{t(`push:andMore`)} {notification.clients?.length - 10}</span>
                                        </>
                                    }
                                </>
                            }
                            {
                                notification.sendToGroups && notification.sendToGroups === "0" &&
                                <>
                                    <span className={'fw-bold'}>{t(`push:sendTo`)}: </span>
                                    <span>{t(`push:sendToGroups`)}</span>
                                </>
                            }
                            {
                                notification.sendToGroups && notification.sendToGroups !== "0" &&
                                <>
                                    <span className={'fw-bold'}>{t(`push:sendToGroups`)}: </span>
                                    {
                                        notification.groups?.length < 10 &&
                                        notification.groups?.map((group, index) => (
                                            <span key={index} className={'d-block'}><Text>{group.nome}</Text></span>
                                        ))
                                    }
                                    {
                                        notification.groups?.length >= 10 &&
                                        <>
                                            {
                                                notification.groups?.slice(0, 11).map((group, index) => (
                                                    <span key={index} className="d-block"><Text>{group.name}</Text></span>
                                                ))
                                            }
                                            <span>{t(`push:andMore`)} {notification.groups?.length - 10}</span>
                                        </>
                                    }
                                </>
                            }
                        </div>
                        <div className={'col-12 pt-2'}>
                            {
                                notification.status === 0 ?
                                    <span>{t(`push:notificationWillBeSentAt`)}<br/> {utcDate.tz(userTimezone).format('DD/MM/YYYY HH:mm')}</span> :
                                    <span className={'text-success-darker'}>
                                        {isPast ? t(`push:notificationSentAt`) : t(`push:notificationScheduledAt`)}
                                        <br/> {utcDate.tz(userTimezone).format('DD/MM/YYYY HH:mm')}</span>
                            }
                        </div>
                        <div className={'col-12 pt-3'}>
                            {
                                (notification.status === 0 || notification.type === "recurring") &&
                                <div className={"d-grid mb-2"}>
                                    <button className={'btn btn-outline-primary-darker'} onClick={handleEditPush}>{t(`push:editNotification`)}</button>
                                </div>
                            }
                            <div className={"d-grid  "}>
                                <button className={'btn btn-outline-danger'} onClick={() => handleChangeStatus(2)}>{t(`push:deleteNotification`)}</button>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    )
}

export default PushCard;