import Page from "../../components/page/Page";
import Spinner from "../../components/loader/Spinner";
import _ from "lodash";
import ClientItemList from "../../components/client/ClientItemList";
import Pagination from "../../components/pagination/Pagination";
import React, {useEffect, useMemo, useState} from "react";
import {useTranslation} from "react-i18next";
import {useNavigate, useSearchParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {
    isClientsLoading,
    selectClientCount,
    selectClients,
    selectClientsPagination
} from "../../store/client/clientSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import groupEnUS from "../client-group/locales/en-us.json";
import groupPtBR from "../client-group/locales/pt-br.json";
import groupEsES from "../client-group/locales/es-es.json";
import groupPtPT from "../client-group/locales/pt-pt.json";
import {fetchClientCount, fetchClientsPaginated, setClient} from "../../store/client/clientReducer";
import {selectUser} from "../../store/user/userSelector";
import {
    clearCreatedClientGroup,
    createClientGroup,
    fetchClientGroups,
    fetchUngroupedCount
} from "../../store/client-group/clientGroupReducer";
import {
    selectClientGroupGroupsLoading,
    selectClientGroupMutationLoading,
    selectClientGroupUngroupedLoading,
    selectClientGroups,
    selectCreatedClientGroup,
    selectUngroupedCount
} from "../../store/client-group/clientGroupSelector";
import ClientGroupCard from "../../components/client-group/ClientGroupCard";
import EmptySet from "../../components/empty-set/EmptySet";
import LoadingBlock from "../../components/loader/LoadingBlock";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import ClientGroupCreateModal from "../../components/client-group/ClientGroupCreateModal";
import Tabs from "../../components/tab/Tabs";

const ClientList = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();
    const dispatch = useDispatch();

    const requestedTab = searchParams.get("tab");
    const tab = requestedTab === "groups" ? "groups" : "clients";
    const clientCount = useSelector(selectClientCount);
    const clients = useSelector(selectClients);
    const clientsPagination = useSelector(selectClientsPagination);
    const loading = useSelector(isClientsLoading);
    const clientGroups = useSelector(selectClientGroups);
    const groupsLoading = useSelector(selectClientGroupGroupsLoading);
    const mutationLoading = useSelector(selectClientGroupMutationLoading);
    const ungroupedLoading = useSelector(selectClientGroupUngroupedLoading);
    const createdGroup = useSelector(selectCreatedClientGroup);
    const ungroupedCount = useSelector(selectUngroupedCount);
    const user = useSelector(selectUser);

    const [searchTerm, setSearchTerm] = useState("");
    const [groupSearchTerm, setGroupSearchTerm] = useState("");
    const [clientStatus, setClientStatus] = useState(0);
    const [currentPage, setCurrentPage] = useState(clientsPagination?.page || 1);
    const defaultItemsPerPage = 20;
    const itemsPerPage = clientsPagination?.pageSize || defaultItemsPerPage;
    const totalItems = clientsPagination?.totalItems || 0;
    const totalPagesFromStore = clientsPagination?.totalPages || 0;
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
    const [showCreateGroup, setShowCreateGroup] = useState(false);
    const pagesToShow = 5;

    useComponentTranslations("client", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    useComponentTranslations("clientGroup", {"en-US": groupEnUS, "pt-BR": groupPtBR, "es-ES": groupEsES, "pt-PT": groupPtPT});

    const handleGoBack = () => {
        dispatch(setClient(null));
        navigate("/user");
    };

    const handleAddClient = () => {
        navigate("/user/client/add?goBackTo=list");
    };

    const handleTabChange = (nextTab) => {
        const nextParams = new URLSearchParams(searchParams);
        nextParams.set("tab", nextTab);
        setSearchParams(nextParams);
    };

    const handleClientStatusChange = (status) => {
        setClientStatus(status);
        setCurrentPage(1);
    };

    const handleSearchChange = (event) => {
        setSearchTerm(event.target.value);
        setCurrentPage(1);
    };

    const handleCreateGroupSubmit = (values) => {
        dispatch(createClientGroup(values));
    };

    useEffect(() => {
        if (tab === "clients") {
            dispatch(fetchClientCount());
        }
    }, [dispatch, clientStatus, tab]);

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 300);

        return () => {
            clearTimeout(handler);
        };
    }, [searchTerm]);

    useEffect(() => {
        if (tab === "clients") {
            dispatch(fetchClientsPaginated({
                status: clientStatus,
                page: currentPage,
                pageSize: defaultItemsPerPage,
                search: debouncedSearchTerm
            }));
        }
    }, [dispatch, tab, clientStatus, currentPage, defaultItemsPerPage, debouncedSearchTerm]);

    useEffect(() => {
        if (tab === "groups") {
            dispatch(fetchClientGroups());
            dispatch(fetchUngroupedCount());
        }
    }, [dispatch, tab]);

    useEffect(() => {
        const totalPages = totalPagesFromStore || Math.ceil(totalItems / itemsPerPage);
        if (totalPages > 0 && currentPage > totalPages) {
            setCurrentPage(totalPages);
        } else if (currentPage < 1) {
            setCurrentPage(1);
        }
    }, [totalPagesFromStore, currentPage, totalItems, itemsPerPage]);

    useEffect(() => {
        if (createdGroup) {
            setShowCreateGroup(false);
            dispatch(clearCreatedClientGroup());
        }
    }, [createdGroup, dispatch]);

    const filteredGroups = useMemo(() => {
        const groups = clientGroups || [];
        const normalizedSearch = groupSearchTerm.trim().toLowerCase();

        if (!normalizedSearch) {
            return groups;
        }

        return groups.filter((group) => {
            const name = (group.idUser === 0 ? t(`client:${group.nome_i18n}`) : group.nome) || "";
            return name.toLowerCase().includes(normalizedSearch);
        });
    }, [clientGroups, groupSearchTerm, t]);

    const showUngroupedCard = useMemo(() => {
        if (!groupSearchTerm.trim()) {
            return true;
        }

        return t("client:ungrouped").toLowerCase().includes(groupSearchTerm.trim().toLowerCase());
    }, [groupSearchTerm, t]);

    return (
        <Page title={t("client:yourClients")} goBackLink={handleGoBack} mt={"mt-n4-5"}>
            <Tabs
                page={tab === "clients" ? "1" : "2"}
                button1Text={t("client:clientsTab")}
                button2Text={t("client:groupsTab")}
                mt={"mt-n4"}
                buttonClick={(page) => handleTabChange(page === "1" ? "clients" : "groups")}
            />

            <div className={"card card-body border-0 mt-3"}>

                {tab === "clients" && (
                    <>
                        <div className={"row"}>
                            <div className={"col-12"}>
                                <div className={"input-group"}>
                                    <input
                                        className={"form-control"}
                                        onChange={handleSearchChange}
                                        value={searchTerm}
                                        placeholder={t("client:searchClient")}
                                    />
                                    <span className={"input-group-text border-right-0"}>
                                        <i className={"fa-regular fa-magnifying-glass"}></i>
                                    </span>
                                </div>
                            </div>
                        </div>
                        <div className={"row justify-content-center pt-3"}>
                            <div className={"col-auto pe-0"}>
                                <span
                                    className={`badge rounded-pill border ${clientStatus === 0 ? "border-primary-lighter text-primary-lighter bg-info-subtle" : "bg-secondary-lighter border-secondary text-secondary"}`}
                                    onClick={() => handleClientStatusChange(0)}
                                >
                                    {t("client:actives")}: {clientCount?.status_0 ?? 0}
                                </span>
                            </div>
                            <div className={"col-auto pe-0"}>
                                <span
                                    className={`badge rounded-pill border ${clientStatus === 1 ? "border-warning-light text-warning-light bg-warning-subtle" : "bg-secondary-lighter border-secondary text-secondary"}`}
                                    onClick={() => handleClientStatusChange(1)}
                                >
                                    {t("client:inactives")}: {clientCount?.status_1 ?? 0}
                                </span>
                            </div>
                            {
                                user && (user.tipoPlano === 200 || (user.tipoPlano >= 1000 && user.tipoPlano < 1004)) &&
                                <div className={"col-auto"}>
                                    <span
                                        className={`badge rounded-pill border ${clientStatus === 2 ? "border-danger-lighter text-danger-lighter bg-danger-subtle" : "bg-secondary-lighter border-secondary text-secondary"}`}
                                        onClick={() => handleClientStatusChange(2)}
                                    >
                                        {t("client:deleted")}
                                    </span>
                                </div>
                            }
                        </div>
                        <div className={"row pt-3"}>
                            <div className={"col-12 text-center mt-3"}>
                                <span className={"fw-semibold text-primary clickable-element"} onClick={handleAddClient}>
                                    <i className={"fa-regular fa-user-plus"}></i> {t("client:addClient")}
                                </span>
                            </div>
                            <div className={"col-12 mt-4"}>
                                {loading && <div className={"pt-4"}><Spinner/></div>}
                                {!loading && clients?.length > 0 && (
                                    <ul className={"list-group"}>
                                        {_.map(clients, (client) => (
                                            <ClientItemList key={client.id} client={client}/>
                                        ))}
                                    </ul>
                                )}
                                {!loading && clients?.length === 0 && (
                                    <span className={"text-center d-block pt-4"}>
                                        {clientStatus === 0 && t("client:youDontHaveAnyActiveClients")}
                                        {clientStatus === 1 && t("client:youDontHaveInactiveClients")}
                                        {clientStatus === 2 && t("client:youDontHaveAnyDeletedClients")}
                                    </span>
                                )}
                            </div>
                        </div>
                        {totalItems > itemsPerPage && (
                            <div className={"row justify-content-center pt-3"}>
                                <div className={"col-12"}>
                                    <Pagination
                                        currentPage={currentPage}
                                        totalItems={totalItems}
                                        itemsPerPage={itemsPerPage}
                                        onPageChange={setCurrentPage}
                                        pagesToShow={pagesToShow}
                                    />
                                </div>
                            </div>
                        )}
                    </>
                )}

                {tab === "groups" && (
                    <>
                        <div className={"row"}>
                            <div className={"col-12"}>
                                <CardButtonAdd
                                    handleClick={() => setShowCreateGroup(true)}
                                    text={t("clientGroup:createNewGroup")}
                                />
                            </div>
                            <div className={"col-12 mt-3"}>
                                <div className={"input-group"}>
                                    <input
                                        className={"form-control"}
                                        value={groupSearchTerm}
                                        onChange={(event) => setGroupSearchTerm(event.target.value)}
                                        placeholder={t("client:groupSearch")}
                                    />
                                    <span className={"input-group-text bg-white"}>
                                        <i className={"fa-regular fa-magnifying-glass"}></i>
                                    </span>
                                </div>
                            </div>
                        </div>

                        {(groupsLoading || ungroupedLoading) && <LoadingBlock height={"220px"}/>}

                        {!groupsLoading && !ungroupedLoading && (
                            <div className={"row pt-3"}>
                                {showUngroupedCard && (
                                    <div className={"col-12 mb-2"}>
                                        <div
                                            className={"card card-body  clickable-element"}
                                            onClick={() => navigate("/user/client/list/group/ungrouped")}
                                        >
                                            <span className={"fw-semibold d-block text-primary "}>{t("client:ungrouped")}</span>
                                            <span className={"small"}>{ungroupedCount || 0} {t("client:clientsWithoutGroup").toLowerCase()}</span>
                                        </div>
                                    </div>
                                )}

                                {filteredGroups?.map((clientGroup) => (
                                    <ClientGroupCard clientGroup={clientGroup} key={clientGroup.id}/>
                                ))}

                                {(!filteredGroups || filteredGroups.length === 0) && !showUngroupedCard && (
                                    <div className={"col-12"}>
                                        <EmptySet
                                            icon={"fa-magnifying-glass"}
                                            message={t("client:noGroupsFound")}
                                        />
                                    </div>
                                )}

                                {(!clientGroups || clientGroups.length === 0) && Number(ungroupedCount || 0) === 0 && !groupSearchTerm.trim() && (
                                    <div className={"col-12"}>
                                        <EmptySet
                                            icon={"fa-folder"}
                                            message={t("client:noGroupsYet")}
                                        />
                                    </div>
                                )}
                            </div>
                        )}
                    </>
                )}
            </div>

            <ClientGroupCreateModal
                show={showCreateGroup}
                onHide={() => setShowCreateGroup(false)}
                onSubmit={handleCreateGroupSubmit}
                title={t("clientGroup:createNewGroup")}
                label={t("clientGroup:groupName")}
                submitText={t("clientGroup:submit")}
                cancelText={t("clientGroup:close")}
                loading={mutationLoading}
                requiredMessage={t("clientGroup:nameIsRequired")}
                minLengthMessage={t("clientGroup:nameMustBe3charactersLong")}
                maxLengthMessage={t("clientGroup:max245Characters")}
            />
        </Page>
    );
};

export default ClientList;
