import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect, useMemo, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import {getBioimpedanceList, getLoading, getOneBioimpedance} from "../../store/bioimpedance-evaluation/bioimpedanceSelector";
import {fetchOneBioimpedance, getAllBioimpedance} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";
import {fetchClient} from "../../store/client/clientReducer";
import moment from "moment/moment";
import {bioProtocol} from "../../utils/physicalEvaluation/protocolData";
import EvaluationCompareTableComponent from "../../components/evaluation-components/EvaluationCompareTableComponent";
import {bioimpedanceCompareFields} from "../../utils/evaluationComponents/fields";
import {formatRQC} from "../../utils/physicalEvaluation/rqcFormula";
import {formatIMC} from "../../utils/evaluationComponents/formatters";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {calculateIMC} from "../../utils/physicalEvaluation/imcFormula";
import BioimpedanceDetailFields from "../../components/bioimpedance-evaluation/BioimpedanceDetailFields";
import {getBioimpedanceFields} from "../../utils/bioimpedanceEvaluation/bioimpedanceFieldsView";
import {buildClientBioimpedanceRoute} from "../../utils/client/evaluationRoutes";

const BioimpedanceCompare = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, bioimpedanceIds} = useParams();
    const {t} = useTranslation("bioimpedanceEvaluation");

    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const allBioimpedances = useSelector(getBioimpedanceList);
    const bioimpedanceDetail = useSelector(getOneBioimpedance);
    const [currentSelectedId, setCurrentSelectedId] = useState(null);

    useComponentTranslations('bioimpedanceEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT})

    const selectedIds = useMemo(
        () => (bioimpedanceIds ? bioimpedanceIds.split(",") : []),
        [bioimpedanceIds]
    );

    const selectedBioimpedance = useMemo(() => {
        if (!Array.isArray(allBioimpedances)) {
            return [];
        }
        if (selectedIds.length === 0) {
            return allBioimpedances;
        }
        return allBioimpedances.filter((b) =>
            selectedIds.includes(String(b.id))
        );
    }, [allBioimpedances, selectedIds]);


    const currentProtocol = useMemo(
        () =>
            bioimpedanceDetail && bioimpedanceDetail.protocolo
                ? bioProtocol.find(p => p.id === bioimpedanceDetail.protocolo)
                : null,
        [bioimpedanceDetail]
    );

    const translatedFields = useMemo(
        () =>
            bioimpedanceCompareFields.map(field => ({
                ...field,
                label: t(`table.${field.labelKey}`)
            })),
        [t]
    );

    const detailFields = useMemo(() => {
        if (!currentProtocol) return [];
        return currentProtocol.fields.filter(f => {
            const v = bioimpedanceDetail?.[f.id];
            return v != null && !(typeof v === "string" && !v.trim());
        });
    }, [currentProtocol, bioimpedanceDetail]);


    const fieldsBySection = useMemo(() => {
        if (!currentProtocol) return {};
        return getBioimpedanceFields(currentProtocol.id)
            .map(f => ({...f, labelKey: f.labelKey ?? f.id}))
            .reduce((acc, field) => {
                const v = bioimpedanceDetail?.[field.id];
                if (v == null) return acc;
                (acc[field.section] ||= []).push(field);
                return acc;
            }, {});
    }, [currentProtocol, bioimpedanceDetail]);

    const isCompareMode = !currentSelectedId && selectedBioimpedance.length > 0;
    const isDetailMode = !!currentSelectedId && detailFields.length > 0;

    const tableFormatters = useMemo(() => ({
        rcq: raw => formatRQC(raw, selectedClient?.sexo, t),
        imc: (_raw, row) => {
            const value = row.imc != null
                ? row.imc
                : calculateIMC(row.peso, row.estatura);
            return formatIMC(value, t);
        },
        sumPeri: raw => (raw != null ? Number(raw).toFixed(2) : raw),
        sumAntro: raw => (raw != null ? Number(raw).toFixed(2) : raw),
    }), [selectedClient, t]);


    const handleGoBackPage = () => {
        navigate(buildClientBioimpedanceRoute(id));
    };

    const handleSelectBioimpedance = (bioimpedanceId) => {
        const idStr = String(bioimpedanceId);
        if (currentSelectedId === idStr) {
            setCurrentSelectedId(null);
        } else {
            setCurrentSelectedId(idStr);
            dispatch(fetchOneBioimpedance({id: idStr}));
        }
    };

    useEffect(() => {
        if (id) {
            dispatch(fetchClient(id));
            dispatch(getAllBioimpedance({clientId: id, status: 0, type: 1}));
            setCurrentSelectedId(null);
        }
    }, [dispatch, id]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            {isCompareMode &&
                                <>
                                    <div className={"col-12 pb-2"}>
                                        <span className={"fw-semibold fs-5 d-block"}>{t("bioimpedanceEvaluation:evaluationsCompare")}</span>
                                    </div>
                                    <EvaluationCompareTableComponent
                                        fields={translatedFields}
                                        data={selectedBioimpedance}
                                        fieldFormatters={tableFormatters}
                                        noAnswerLabel={t("bioimpedanceEvaluation:noAnswer")}
                                        showComparison
                                        comparisonLabel={t("bioimpedanceEvaluation:comparision")}
                                    />
                                </>
                            }
                            {isDetailMode && (
                                <div className="mb-4">
                                    <h5 className="fw-semibold fs-5 mb-3">
                                        {t("bioimpedanceEvaluation:evaluationDetails")}
                                    </h5>
                                    {Object.entries(fieldsBySection).map(([section, fields]) => (
                                        <div key={section} className="mb-4">
                                            {section !== "Pessoal" && (
                                                <span className="fw-semibold fs-5 d-block mb-2">
                                                  {t(`sections.${section}`)}
                                                </span>
                                            )}
                                            <BioimpedanceDetailFields
                                                fields={fields}
                                                detail={bioimpedanceDetail}
                                                clientSexo={selectedClient?.sexo}
                                                t={t}
                                            />
                                        </div>
                                    ))}
                                </div>
                            )}
                            <button className={`btn ${!currentSelectedId ? "btn-primary" : "btn-outline-primary"} my-2`}
                                    onClick={() => setCurrentSelectedId(null)}
                            >
                                {t("bioimpedanceEvaluation:comparision")}
                            </button>
                            <div className={"d-flex flex-column gap-2"}>
                                {selectedBioimpedance.map((bioimpedance) => {
                                    const idStr = String(bioimpedance.id);
                                    const isActive = currentSelectedId === idStr;
                                    return (
                                        <button
                                            key={idStr}
                                            className={`btn ${isActive ? "btn-primary" : "btn-outline-primary"}`}

                                            onClick={() => handleSelectBioimpedance((bioimpedance.id))}
                                        >
                                            {bioimpedance.data ? moment(bioimpedance.data).format("L") : t("bioimpedanceEvaluation:noAnswer")}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
}

export default BioimpedanceCompare;
