import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {
    selectTransaction, selectTransactionLoading
} from "../../store/subscription/subscriptionSelector";
import {fetchTransaction, setTransaction} from "../../store/subscription/subscriptionReducer";
import {isDesktop, isTablet} from "react-device-detect";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {Image} from "react-bootstrap";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import CopyField from "../../components/utils/copyfield/CopyField";
import CurrencyFormatter from "../../components/utils/currency/CurrencyFormatter";
import {Trans, useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionPaymentPix = () => {
    const {t} = useTranslation();
    const {transactionId, couponName, subId} = useParams();
    const transaction = useSelector(selectTransaction);
    const transactionLoading = useSelector(selectTransactionLoading);
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const [silentFetch, setSilentFetch] = useState(false);
    const [waitingFetch, setWaitingFetch] = useState(true);
    const [pixCode, setPixCode] = useState(null);
    const [amount, setAmount] = useState(0);
    useComponentTranslations('subscriptionPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        if(transaction && !pixCode){
            setAmount(transaction.amount)
            setPixCode( transaction?.payment_method?.qr_code?.emv)
        }
    }, [transaction, pixCode]);

    useEffect(() => {
        const timer = setTimeout(() => {
            dispatch(fetchTransaction(transactionId));
            setWaitingFetch(false);
        }, 3000);
        return () => clearTimeout(timer);
    }, [transactionId, dispatch]);

    useEffect(() => {
        if (waitingFetch || transaction?.status === "succeeded") return;
        const iv = setInterval(() => {
            setSilentFetch(true);
            dispatch(fetchTransaction(transactionId));
        }, 5000);
        return () => clearInterval(iv);
    }, [waitingFetch, transaction?.status, transactionId, dispatch]);

    useEffect(() => {
        if (!waitingFetch && transaction?.status === "succeeded") {
            navigate(`/subscription/purchase/success`);
        }
    }, [waitingFetch, transaction?.status, navigate, transaction]);

    const goBackLink = () => {
        dispatch(setTransaction(null));
        const base = `/subscription/purchase/${subId}`;
        navigate(couponName ? `${base}/coupon/${couponName}` : base);
    };
    const showLoader = waitingFetch || (transactionLoading && !silentFetch);

    if (showLoader) {
        return (
            <Page goBackLink={goBackLink} mt="mt-n4">
                <div className="card card-body border-0">
                    <LoadingBlock/>
                </div>
            </Page>
        );
    }

    return (
        <Page goBackLink={goBackLink} mt="mt-n4">
            <div className="card card-body border-0">

                <div className="row justify-content-center mt-4">
                    <div className="col-12 text-center mt-2">
                        <RoundedIcon brand icon="fa-pix" size="lg"/>
                    </div>
                    <div className="col-12 text-center mt-2">
                        <span className="fw-semibold fs-5">{t("subscriptionPage:pixCopyPasteTitle")}</span>
                    </div>
                </div>
                <div className="row justify-content-center mt-2">
                    <div className="col-12 text-center">
                        <span className="fw-semibold text-primary fs-5">
                          <CurrencyFormatter value={amount}/>
                        </span>
                    </div>
                </div>
                {(isDesktop || isTablet) && (
                    <>
                        <div className="row justify-content-center">
                            <div className="col-12 text-center mt-2">
                                <span>
                                    <Trans
                                        t={t}
                                        i18nKey="subscriptionPage:pixScanInstruction"
                                        components={{bold: <span className="fw-semibold"/>}}
                                    />
                                </span>
                            </div>
                        </div>
                        <div className="row justify-content-center mt-3">
                            <div className="col-8 col-md-6 text-center  ">
                                <Image
                                    fluid
                                    src={
                                        "https://api.mfitpersonal.com.br/qrcode/?data=" +
                                        encodeURIComponent(pixCode) +
                                        "&size=200"
                                    }
                                />
                            </div>
                        </div>

                        <hr className="border-primary-subtle"/>
                    </>
                )}
                <div className="row justify-content-center mt-2">
                    <div className="col-12">
                        <span className="d-block text-center">
                          <Trans
                              t={t}
                              i18nKey="subscriptionPage:pixCopyInstruction"
                              components={{bold: <span className="fw-semibold"/>}}
                          />
                        </span>
                    </div>
                </div>
                <div className="row justify-content-center mt-3">
                    <CopyField
                        text={pixCode}
                        button={t("subscriptionPage:pixCopyButton")}
                        toastTitle={t("subscriptionPage:pixCopyToastTitle")}
                        toastMessage={t("subscriptionPage:pixCopyToastMessage")}
                    />
                </div>
            </div>
        </Page>
    );
};

export default SubscriptionPaymentPix;
