import { useEffect, useState } from 'react';
import moment from 'moment';
import { formatElapsedTime } from "../../utils/workout/Workout";

const WorkoutTimer = ({ workoutStarted }) => {
    const [elapsedTime, setElapsedTime] = useState(0);
    const [isTimerRunning, setIsTimerRunning] = useState(false);

    useEffect(() => {
        let intervalId = null;

        if (workoutStarted) {
            setIsTimerRunning(true);

            intervalId = setInterval(() => {
                const now = moment();
                const elapsedMilliseconds = now.diff(workoutStarted);
                const elapsedSeconds = Math.floor(elapsedMilliseconds / 1000);
                setElapsedTime(elapsedSeconds);
            }, 1000);
        }

        return () => {
            clearInterval(intervalId);
        };
    }, [workoutStarted]);

    if (!isTimerRunning) {
        return formatElapsedTime(0); // Render null if the timer is not running yet
    }

    return formatElapsedTime(elapsedTime);
};

export default WorkoutTimer;
