import React, {useMemo} from "react";
import {useSelector} from "react-redux";
import {selectInstallments} from "../../store/subscription/subscriptionSelector";
import creditCardType from "credit-card-type";
import Image from "react-bootstrap/Image";
import {Trans, useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import {normalizeInstallmentMap} from "../../utils/installments/zoopInstallments";

const SubscriptionCreditCardSelected = ({paymentMethod, subPlan, handleChangePaymentMethod, installmentOptions}) => {
    const {t} = useTranslation();
    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const installments = useSelector(selectInstallments);
    const normalizedInstallments = useMemo(
        () => normalizeInstallmentMap(installmentOptions ?? subPlan?.installments),
        [installmentOptions, subPlan]
    );
    const installmentCount = Number(installments) || 1;
    const totalInstallmentValue = normalizedInstallments?.[installmentCount] ?? 0;
    const perInstallmentValue = installmentCount ? totalInstallmentValue / installmentCount : 0;
    const image = `https://cdn.mfitpersonal.com.br/assets/credit_card_brand/${creditCardType(paymentMethod.card.first4_digits)[0].type}.svg`

    return (
        <div className={"card card-body "}>
            <div className={"row "}>
                <div className={"col-2 text-center  align-self-center p-0 "}>
                    <Image src={image} fluid/>
                </div>
                <div className={"col-10 ps-1 justify-content-between align-self-center"}>
                    <div className={"row"}>
                        <div className={"col-8 align-self-center"}>
                            <span
                                className={"fw-semibold d-block"}>{paymentMethod.card.card_brand} **** {paymentMethod.card.last4_digits}</span>
                            <span className={"small"}>
                                 <Trans
                                     i18nKey={"subscriptionComponent:subscriptionCreditCardSelected.installments"}
                                     count={installments}
                                     values={{count: installments}}
                                     components={{amount: <CurrencyFormatter
                                             value={perInstallmentValue}/>}}
                                 />
                            </span>
                        </div>
                        <div className={"col-4 align-self-center text-end"}>
                            <span className={"fw-semibold text-primary clickable-element small"}
                                  onClick={handleChangePaymentMethod}>{t('subscriptionComponent:changePaymentMethod')}</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>

    )
}

export default SubscriptionCreditCardSelected;