function _formatRQC(rcqInput, gender, t) {

    if (typeof rcqInput === "string" && /[a-zA-Z]/.test(rcqInput)) {
        return rcqInput;
    }
    const rcq = typeof rcqInput === "number" ? rcqInput : parseFloat(rcqInput);
    if (isNaN(rcq)) {
        return rcqInput;
    }
    let key;

    if (gender && gender.toLowerCase() === "m") {
        if (rcq <= 0.95) key = "rcq_low";
        else if (rcq <= 1) key = "rcq_moderate";
        else key = "rcq_high";
    } else if (gender && gender.toLowerCase() === "f") {
        if (rcq <= 0.80) key = "rcq_low";
        else if (rcq <= 0.85) key = "rcq_moderate";
        else key = "rcq_high";

    }
    const formatted = rcq.toFixed(2);

    const nested = t(`rcq.${key}`);
    if (nested && nested !== `rcq.${key}`) {
        return `${formatted} ${nested}`;
    }
    const root = t(key);
    return `${formatted} ${root}`;
}

export const formatRQC = (rcqInput, gender, t) => _formatRQC(rcqInput, gender, t);

export const calculateRQC = (waistInput, hipInput) => {
    if (waistInput == null || hipInput == null) {
        return null;
    }
    const waistStr = String(waistInput).trim().replace(',', '.');
    const hipStr = String(hipInput).trim().replace(',', '.');

    const waist = parseFloat(waistStr);
    const hip = parseFloat(hipStr);

    if (isNaN(waist) || isNaN(hip) || hip === 0) {
        return null;
    }

    return waist / hip;
};
