import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import FrequencyTrainingDay from "./FrequencyTrainingDay";
import Spinner from "../loader/Spinner";

const FrequencyTraining = ({frequencyTraining, client}) => {
    const {t} = useTranslation();
    const navigate = useNavigate();

    useComponentTranslations('frequencyComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleTrainingFrequencyClick = () => {
        navigate(`/user/client/training-frequency/${client.id}/month`)
    }

    return (
        <>
            {
                frequencyTraining ?
                    <div className={"row justify-content-center mt-3 clickable-element"} onClick={handleTrainingFrequencyClick}>
                        <div className={"col-12"}>
                            <div className={'card card-body border-0 pt-2 '}>
                                <div className={'row mb-2'}>
                                    <div className={"col-12"}>
                                        <span className={"fw-semibold"}>{t("frequencyComponent:pageTitle")}</span>
                                    </div>
                                </div>
                                <div
                                    className="d-flex flex-nowrap gap-2 justify-content-between pt-2">
                                    <FrequencyTrainingDay frequencyDay={frequencyTraining.monday} day={"monday"}/>
                                    <FrequencyTrainingDay frequencyDay={frequencyTraining.tuesday} day={"tuesday"}/>
                                    <FrequencyTrainingDay frequencyDay={frequencyTraining.wednesday} day={"wednesday"}/>
                                    <FrequencyTrainingDay frequencyDay={frequencyTraining.thursday} day={"thursday"}/>
                                    <FrequencyTrainingDay frequencyDay={frequencyTraining.friday} day={"friday"}/>
                                    <FrequencyTrainingDay frequencyDay={frequencyTraining.saturday} day={"saturday"}/>
                                    <FrequencyTrainingDay frequencyDay={frequencyTraining.sunday} day={"sunday"}/>
                                </div>
                            </div>
                        </div>
                    </div> :
                    <div className={"row justify-content-center mt-3"}>
                        <div className={"col-12"}>
                            <div className={"card card-body border-0 pt-2"} style={{height: "120px"}}>
                                <Spinner/>
                            </div>
                        </div>
                    </div>
            }
        </>

    )
}

export default FrequencyTraining;