import {useEffect, useMemo, useRef, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import Page from "../../components/page/Page";
import Pagination from "../../components/pagination/Pagination";
import EmptySet from "../../components/empty-set/EmptySet";
import LoadingBlock from "../../components/loader/LoadingBlock";
import RetentionMetricCard from "../../components/retention/RetentionMetricCard";
import RetentionClientCard from "../../components/retention/RetentionClientCard";
import RetentionClassificationInfoOffcanvas from "../../components/retention/RetentionClassificationInfoOffcanvas";
import RetentionMetricsInfoOffcanvas from "../../components/retention/RetentionMetricsInfoOffcanvas";
import RetentionNotifyOffcanvas from "../../components/retention/RetentionNotifyOffcanvas";
import useRetentionAccessEvent from "../../components/retention/useRetentionAccessEvent";
import {GuidedTourCard} from "../../components/guided-tour";
import useRetentionDashboardTour from "../../components/retention/useRetentionDashboardTour";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {
    setRetentionDashboardFilters,
    setRetentionDashboardPage
} from "../../store/retention/retentionReducer";
import {selectRetentionDashboardFilters} from "../../store/retention/retentionSelector";
import {
    useLogRetentionClientActionMutation,
    useRetentionClientsQuery,
    useRetentionSummaryQuery
} from "../../store/retention/retentionApi";
import {
    getRetentionStatusMeta,
    RETENTION_STATUS_OPTIONS
} from "../../components/retention/retentionConfig";

const RetentionDashboard = () => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();

    const dashboardFilters = useSelector(selectRetentionDashboardFilters);
    const [searchInput, setSearchInput] = useState(() => dashboardFilters?.search || "");
    const [expandedClientId, setExpandedClientId] = useState(null);
    const [showMetricsInfo, setShowMetricsInfo] = useState(false);
    const [showClassificationInfo, setShowClassificationInfo] = useState(false);
    const [showNotifyModal, setShowNotifyModal] = useState(false);
    const [notifyClient, setNotifyClient] = useState(null);
    const tourWasOpenRef = useRef(false);
    const tourExpandedClientSnapshotRef = useRef(null);

    const locale = i18n.language || "pt-BR";
    const {
        status = "AT_RISK",
        search = "",
        page = 1,
        pageSize = 20
    } = dashboardFilters || {};
    const [logRetentionClientAction] = useLogRetentionClientActionMutation();
    const {data: summary, isLoading: loadingSummary} = useRetentionSummaryQuery("CURRENT_MONTH");
    const {data: clientsData, isLoading: loadingClients} = useRetentionClientsQuery(dashboardFilters);

    useComponentTranslations("retention", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    useRetentionAccessEvent();

    useEffect(() => {
        setSearchInput(search);
    }, [search]);

    useEffect(() => {
        const handler = setTimeout(() => {
            const normalizedSearch = searchInput.trim();

            if (normalizedSearch === search) {
                return;
            }

            dispatch(setRetentionDashboardFilters({
                search: normalizedSearch,
                status: normalizedSearch ? "ALL" : status,
                page: 1
            }));
        }, 300);

        return () => clearTimeout(handler);
    }, [dispatch, search, searchInput, status]);

    useEffect(() => {
        setExpandedClientId(null);
    }, [page, search, status]);

    const pagination = clientsData?.pagination || {
        page,
        pageSize,
        totalItems: 0,
        totalPages: 0,
        statusCounts: {}
    };
    const sortedClients = useMemo(() => {
        return [...(clientsData?.clients || [])].sort((first, second) => (first.name || "").localeCompare(second.name || "", locale, {
            sensitivity: "base"
        }));
    }, [clientsData?.clients, locale]);
    const hasClients = sortedClients.length > 0;
    const firstClientId = sortedClients[0]?.id || null;
    const isTourReady = Boolean(summary && clientsData) && !loadingSummary && !loadingClients;

    const cohortItems = summary?.cohorts || [];

    const retentionTour = useRetentionDashboardTour({
        t,
        isReady: isTourReady,
        hasClients
    });
    const activeTourStepId = retentionTour.activeStep?.id || null;

    const handleGoBack = () => {
        navigate("/user");
    };

    const handleSearchChange = (event) => {
        setSearchInput(event.target.value);
    };

    const handleCloseNotifyFlow = () => {
        setShowNotifyModal(false);
        setNotifyClient(null);
    };

    const handleOpenNotifyFlow = () => {
        setNotifyClient(null);
        setShowNotifyModal(true);
    };

    const handleSingleNotify = (client) => {
        setNotifyClient(client);
        setShowNotifyModal(true);
    };

    const handleWhatsApp = (client) => {
        logRetentionClientAction({
            clientId: client.id,
            actionType: "WHATSAPP_OPEN",
            filterStatus: status,
            searchTerm: search
        });

        if (client.whatsappLink) {
            window.open(client.whatsappLink, "_blank");
        }
    };

    const handleViewProfile = (client) => {
        navigate(`/user/client/${client.id}`);
    };

    useEffect(() => {
        if (retentionTour.isOpen && !tourWasOpenRef.current) {
            tourExpandedClientSnapshotRef.current = expandedClientId;
            tourWasOpenRef.current = true;
            return;
        }

        if (!retentionTour.isOpen && tourWasOpenRef.current) {
            const snapshotExpandedClientId = tourExpandedClientSnapshotRef.current ?? null;

            tourWasOpenRef.current = false;
            tourExpandedClientSnapshotRef.current = null;

            setExpandedClientId((currentExpandedClientId) => {
                return currentExpandedClientId === snapshotExpandedClientId
                    ? currentExpandedClientId
                    : snapshotExpandedClientId;
            });
        }
    }, [expandedClientId, retentionTour.isOpen]);

    useEffect(() => {
        if (!retentionTour.isOpen || !tourWasOpenRef.current) {
            return;
        }

        const nextExpandedClientId = activeTourStepId === "client"
            ? null
            : activeTourStepId === "client-actions"
                ? firstClientId
                : (tourExpandedClientSnapshotRef.current ?? null);

        setExpandedClientId((currentExpandedClientId) => {
            return currentExpandedClientId === nextExpandedClientId
                ? currentExpandedClientId
                : nextExpandedClientId;
        });
    }, [activeTourStepId, firstClientId, retentionTour.isOpen]);

    return (
        <>
            <Page title={t("retention:title")} goBackLink={handleGoBack} mt={"mt-n5"}>
                <div className={"card card-body border-0 "} data-tour={"retention-summary"}>
                    <div className={"d-flex justify-content-between align-items-center gap-2"}>
                        <span className={"fw-semibold fs-5"}>{t("retention:summary")}</span>
                        <button
                            className={"btn btn-link fw-semibold text-md  text-decoration-none p-0"}
                            onClick={() => navigate("/user/retention/charts")}
                        >
                            {t("retention:viewCharts")}
                        </button>
                    </div>

                    {loadingSummary && <LoadingBlock height={"200px"}/>}

                    {!loadingSummary && summary && (
                        <>
                            <div className={"row g-2 mt-2"}>
                                <RetentionMetricCard metric={"ACTIVE_CLIENTS"} card={summary.cards?.activeClients} locale={locale} t={t}/>
                                <RetentionMetricCard metric={"ENGAGEMENT"} card={summary.cards?.engagement} locale={locale} t={t}/>
                                <RetentionMetricCard metric={"GROWTH"} card={summary.cards?.growth} locale={locale} t={t}/>
                                <RetentionMetricCard metric={"RECOVERY"} card={summary.cards?.recovery} locale={locale} t={t}/>
                            </div>
                            <div className={"row mt-2"}>
                                <div className={"col-12 text-center"}>
                                    <button className={"btn btn-link text-decoration-none fw-semibold  text-md py-1"} onClick={() => setShowMetricsInfo(true)}>
                                        {t("retention:whatMetricsMean")}
                                    </button>
                                </div>
                            </div>
                        </>
                    )}
                </div>

                <div className={"card card-body border-0 mt-3"} data-tour={"retention-breakdown"}>
                    <span className={"fw-semibold fs-5"}>{t("retention:engagementBreakdown")}</span>
                    <span className={"text-secondary small mt-1"}>{t("retention:previousCompletedWeek")}</span>

                    <div className={"mt-3"}>
                        {cohortItems.map((cohort) => {
                            const statusMeta = getRetentionStatusMeta(cohort.status, t);
                            return (
                                <div className={"mb-3"} key={cohort.status}>
                                    <div className={"d-flex justify-content-between align-items-center mb-1"}>
                                        <span className={"fw-semibold"}>{statusMeta.label}</span>
                                        <span className={"small fw-semibold"}>{cohort.count} ({Number(cohort.percentage || 0).toFixed(0)}%)</span>
                                    </div>
                                    <div className={"progress rounded-5"} style={{height: "17px"}}>
                                        <div
                                            className={`progress-bar ${statusMeta.progressClass}`}
                                            style={{width: `${Number(cohort.percentage || 0)}%`}}
                                        ></div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    <div className={"text-center"}>
                        <button className={"btn btn-link text-decoration-none fw-semibold  text-md py-1"} onClick={() => setShowClassificationInfo(true)}>
                            {t("retention:understandClassification")}
                        </button>
                    </div>
                </div>

                <div className={"card card-body border-0 mt-3 "}>
                    <div className={"row g-2 align-items-center"} data-tour={"retention-clients-controls"}>
                        <div className={"col-12 pb-2"}>
                            <span className={"fw-semibold fs-5"}>{t("retention:clients")}</span>
                        </div>
                        <div className={"col-12"}>
                            <div className={"input-group"}>
                                <input
                                    className={"form-control"}
                                    value={searchInput}
                                    onChange={handleSearchChange}
                                    placeholder={t("retention:searchClients")}
                                />
                                <span className={"input-group-text bg-white"}>
                                    <i className={"fa-regular fa-magnifying-glass"}></i>
                                </span>
                            </div>
                        </div>
                        <div className={"col-6 mt-2"}>
                            <select className={"form-select"} value={status} onChange={(event) => {
                                dispatch(setRetentionDashboardFilters({
                                    status: event.target.value,
                                    page: 1
                                }));
                            }}>
                                {RETENTION_STATUS_OPTIONS.map((option) => (
                                    <option key={option} value={option}>
                                        {getRetentionStatusMeta(option, t).label}
                                    </option>
                                ))}
                            </select>
                        </div>
                        <div className={"col-6 mt-2 d-grid"}>
                            <button
                                className={"btn btn-primary w-100 h-100 d-flex align-items-center justify-content-center gap-2 text-nowrap"}
                                data-tour={"retention-notify"}
                                onClick={handleOpenNotifyFlow}
                            >
                                <i className={"fa-regular fa-paper-plane"}></i>
                                {t("retention:notifyClients")}
                            </button>
                        </div>
                    </div>

                    <div className={"mt-3"}>
                        {loadingClients && <LoadingBlock height={"220px"}/>}

                        {!loadingClients && sortedClients.length === 0 && (
                            <EmptySet
                                icon={"fa-magnifying-glass"}
                                message={t("retention:emptyClientsTitle")}
                                message2={t("retention:emptyClientsMessage")}
                            />
                        )}

                        {!loadingClients && sortedClients.map((client, index) => (
                            <RetentionClientCard
                                key={client.id}
                                client={client}
                                expanded={expandedClientId === client.id}
                                onToggle={(clientId) => setExpandedClientId((currentId) => currentId === clientId ? null : clientId)}
                                onNotify={handleSingleNotify}
                                onWhatsApp={handleWhatsApp}
                                onViewProfile={handleViewProfile}
                                tourTarget={index === 0 ? "retention-first-client" : undefined}
                                expandedTourTarget={index === 0 ? "retention-first-client-expanded" : undefined}
                                t={t}
                            />
                        ))}
                    </div>

                    {pagination.totalItems > pagination.pageSize && (
                        <div className={"pt-2"}>
                            <Pagination
                                currentPage={page}
                                totalItems={pagination.totalItems}
                                itemsPerPage={pagination.pageSize}
                                onPageChange={(nextPage) => dispatch(setRetentionDashboardPage(nextPage))}
                                pagesToShow={5}
                            />
                        </div>
                    )}
                </div>

                <RetentionMetricsInfoOffcanvas
                    show={showMetricsInfo}
                    onHide={() => setShowMetricsInfo(false)}
                    t={t}
                />

                <RetentionClassificationInfoOffcanvas
                    show={showClassificationInfo}
                    onHide={() => setShowClassificationInfo(false)}
                    t={t}
                />

                <RetentionNotifyOffcanvas
                    show={showNotifyModal}
                    onHide={handleCloseNotifyFlow}
                    initialClient={notifyClient}
                    t={t}
                />
            </Page>

            <GuidedTourCard
                isOpen={retentionTour.isOpen}
                step={retentionTour.activeStep}
                current={retentionTour.activeIndex + 1}
                total={retentionTour.totalSteps}
                isFirstStep={retentionTour.isFirstStep}
                isLastStep={retentionTour.isLastStep}
                labels={retentionTour.labels}
                onClose={retentionTour.close}
                onSkip={retentionTour.skip}
                onPrevious={retentionTour.previous}
                onNext={retentionTour.isLastStep ? retentionTour.complete : retentionTour.next}
                activeTarget={retentionTour.activeTargetElement}
            />
        </>
    );
};

export default RetentionDashboard;
