import {matchesSubmitResult} from "./mutationState";

export const normalizeRouteEntityId = (routeEntityId) =>
    routeEntityId !== null && routeEntityId !== undefined && routeEntityId !== ""
        ? String(routeEntityId)
        : null;

export const isSuccessTargetReady = (targetEntityId) =>
    normalizeRouteEntityId(targetEntityId) != null;

export const isMatchingSubmitSuccess = (submitResult, criteria) =>
    matchesSubmitResult(submitResult, {...criteria, status: "success"});

export const isMatchingSubmitError = (submitResult, criteria) =>
    matchesSubmitResult(submitResult, {...criteria, status: "error"});
