import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {getLoading, getOnePhysical} from "../../store/physical-evaluation/physicalEvaluationSelector";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import React, {useCallback, useEffect} from "react";
import {fetchOnePhysical, resetFormSent,} from "../../store/physical-evaluation/physicalEvaluationReducer";
import {fetchClient} from "../../store/client/clientReducer";
import {getProtocolData, getProtocolMap} from "../../utils/physicalEvaluation/protocolData";
import moment from "moment";
import {isDesktop} from "react-device-detect";
import ImageCarousel from "../../utils/imagecarousel/ImageCarousel";
import {formatIMC} from "../../utils/physicalEvaluation/imcFormula";
import {formatRQC} from "../../utils/physicalEvaluation/rqcFormula";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import EvaluationChartsComponent from "../../components/evaluation-components/EvaluationChartsComponent";
import {usePhysicalActions} from "../../utils/physicalEvaluation/usePhysicalActions";
import PhysicalActionsButtons from "../../components/physical-evaluation/PhysicalActionsButtons";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {buildClientPhysicalRoute} from "../../utils/client/evaluationRoutes";

const PhysicalEvaluationView = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, physicalId, goBackTo} = useParams();
    const {t} = useTranslation("physicalEvaluation");
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const physicalDetail = useSelector(getOnePhysical);
    const backToUpdates = goBackTo === "updates";
    const studentGender = selectedClient?.sexo?.toUpperCase() === "F" ? "female" : "male";
    const protocols = React.useMemo(() => getProtocolData(studentGender), [studentGender]);
    const protocolMap = React.useMemo(() => getProtocolMap(studentGender), [studentGender]);

    useComponentTranslations('physicalEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const currentProtocol =
        physicalDetail && physicalDetail.protocolo !== undefined && physicalDetail.protocolo !== null
            ? protocols.find((protocol) => protocol.id === physicalDetail.protocolo)
            : null;

    const isFieldFilled = useCallback((field) => {
        const value = physicalDetail[field.id] ?? physicalDetail.skinColor;
        if (value === undefined || value === null) return false;
        if (typeof value === "string") return value.trim().length > 0;
        if (typeof value === "number") {
            if (field.id === "cor") return true;
            return value !== 0;
        }
        return true;
    }, [physicalDetail]);


    const percentualGordura = parseFloat((Number(physicalDetail?.per_gord) || 0).toFixed(2));
    const percentualMassaMagra = (100 - percentualGordura).toFixed(2);
    const massaGordaKg = physicalDetail?.pes_gord || 0;
    const massaMagraKg = physicalDetail?.magra || 0;

    const imcFormatted = physicalDetail?.imc != null && Number(physicalDetail.imc) !== 0
        ? formatIMC(physicalDetail.imc, t)
        : "";

    const rcqFormatted = physicalDetail?.rcq != null && Number(physicalDetail.rcq) !== 0
        ? formatRQC(physicalDetail.rcq, selectedClient?.sexo, t)
        : "";

    const anthropometrySum = React.useMemo(() => {
        if (!physicalDetail || !currentProtocol) return 0;
        const sum = currentProtocol.fields.reduce((sum, field) => {
            if (field.section === "Antropometria") {
                const value = parseFloat(physicalDetail[field.id]);
                return sum + (isNaN(value) ? 0 : value);
            }
            return sum;
        }, 0);
        return parseFloat(sum.toFixed(2));
    }, [physicalDetail, currentProtocol]);

    const perimetrySum = React.useMemo(() => {
        if (!physicalDetail || !currentProtocol) return 0;
        const sum = currentProtocol.fields.reduce((sum, field) => {
            if (field.section === "Perimetria") {
                const value = parseFloat(physicalDetail[field.id]);
                return sum + (isNaN(value) ? 0 : value);
            }
            return sum;
        }, 0);
        return parseFloat(sum.toFixed(2));
    }, [physicalDetail, currentProtocol]);

    const protocolo = physicalDetail ? protocolMap[Number(physicalDetail.protocolo)] : null;

    const sectionKeyMap = {
        Pessoal: "personal",
        Perimetria: "perimetry",
        Antropometria: "anthropometry",
        Outros: "others",
    };

    const sections = React.useMemo(() => {
        if (!currentProtocol) return [];
        const grouped = [];
        currentProtocol.fields
            .filter((field) => isFieldFilled(field))
            .forEach((field) => {
                const sectionName = field.section || "Outros";
                let group = grouped.find((g) => g.section === sectionName);
                if (!group) {
                    group = {section: sectionName, fields: []};
                    grouped.push(group);
                }
                group.fields.push(field);
            });
        return grouped;
    }, [currentProtocol, isFieldFilled]);

    const handleGoBack = useCallback(() => {
        if (backToUpdates) {
            navigate(`/user/update/list/2`);
        } else
            navigate(buildClientPhysicalRoute(id));
    }, [backToUpdates, navigate, id]);

    const handleGoBackEval = () => {
        navigate(buildClientPhysicalRoute(id));
    };

    const {state: {showDelete, currentPhysical}, handlers} = usePhysicalActions();
    const {setCurrentPhysical} = handlers;

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(fetchOnePhysical({id: physicalId}));
    }, [dispatch, physicalId]);

    useEffect(() => {
        if (physicalDetail) {
            setCurrentPhysical(physicalDetail);
        }
    }, [physicalDetail, setCurrentPhysical]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBack}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        {!physicalDetail && loading &&
                            <div className={"text-center mt-4"}>
                                <LoadingBlock/>
                            </div>
                        }
                        {physicalDetail && currentProtocol && currentProtocol.fields && (
                            <>
                                <div className={"card card-body border-0"}>
                                    <span className={"fw-semibold fs-5"}>
                                        {protocolo && t(`protocols.${protocolo.translationKey}`)}
                                    </span>
                                    {sections.map(({section, fields}) => {
                                        return (
                                            <div key={section} className="mt-2">
                                                {
                                                    section !== "Pessoal" &&
                                                    <span className="fw-semibold d-block fs-5">{t(`physicalEvaluation:${sectionKeyMap[section]}`)}</span>
                                                }
                                                {fields.map((field) => {
                                                    const raw = physicalDetail[field.id] ?? physicalDetail.skinColor;
                                                    const display =
                                                        field.id === "data" || field.id === "proximaAvaliacao"
                                                            ? moment(raw).format("L")
                                                            : field.id === "cor"
                                                                ? (raw === 1 || raw === "1"
                                                                    ? t("physicalEvaluation:skinColors.branco")
                                                                    : raw === 0 || raw === "0"
                                                                        ? t("physicalEvaluation:skinColors.negro")
                                                                        : "")
                                                                : raw;
                                                    return (
                                                        <div key={field.id} className="my-2 row">
                                                            <label htmlFor={field.id} className={"fw-semibold  "}>
                                                                {t(`fields.${field.labelKey}`)}
                                                            </label>
                                                            {field.id === "data" || field.id === "proximaAvaliacao" ? (
                                                                <div>
                                                                    {physicalDetail[field.id] ? moment(physicalDetail[field.id]).format("L") : ""}
                                                                </div>
                                                            ) : field.id === "observacao" ? (
                                                                <div>
                                                                    {physicalDetail[field.id]}
                                                                </div>
                                                            ) : field.id === "objetivo" ? (
                                                                <div>
                                                                    {physicalDetail[field.id]}
                                                                </div>
                                                            ) : field.id === "cor" ? (
                                                                <div>{display}</div>
                                                            ) : (
                                                                <span className="d-inline-block  " style={{width: 'auto'}}>
                                                                        {`${display}${field.unit || ''}`}
                                                                    </span>
                                                            )}
                                                        </div>
                                                    );
                                                })}
                                                <hr className={"border-primary-subtle"}/>
                                            </div>

                                        );
                                    })}

                                    <span className={"fw-semibold fs-5"}>
                                        Resultados
                                    </span>
                                    {imcFormatted && (
                                        <div className=" mb-1  mt-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:IMC")} </span>
                                            {imcFormatted}
                                        </div>
                                    )}
                                    {rcqFormatted && (
                                        <div className=" mb-1 ">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:RCQ")} </span>
                                            {rcqFormatted}
                                        </div>
                                    )}
                                    {perimetrySum !== 0 && (
                                        <div className={"mb-1 "}>
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:perimetrySum")} </span>
                                            {perimetrySum.toFixed(2)}cm
                                        </div>
                                    )}
                                    {anthropometrySum !== 0 && (
                                        <div className={"mb-1 "}>
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:anthropometricSum")} </span>
                                            {anthropometrySum.toFixed(2)}mm
                                        </div>
                                    )}
                                    {physicalDetail?.gordIdeal !== 0 && (
                                        <div className={" mb-1"}>
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:idealFat")} </span>
                                            {physicalDetail.gordIdeal}Kgs
                                        </div>
                                    )}
                                    {physicalDetail?.massaIdeal !== 0 && (
                                        <div className={"mb-1"}>
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:idealMass")} </span>
                                            {physicalDetail.massaIdeal}Kgs
                                        </div>
                                    )}
                                    {physicalDetail?.pesoIdeal !== 0 && (
                                        <div className="mb-1">
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:fields.pesoIdeal")} </span>
                                            {physicalDetail.pesoIdeal}Kgs
                                        </div>
                                    )}
                                    {physicalDetail?.gordExc !== 0 && (
                                        <div className={"mb-1 "}>
                                            <span className={"fw-semibold"}>{t("physicalEvaluation:excessFat")} </span>
                                            {physicalDetail.gordExc}Kgs
                                        </div>
                                    )}
                                </div>
                            </>

                        )}

                        <div className={"card card-body border-0 mt-2 no-page-break"}>
                            <EvaluationChartsComponent
                                chartTitle={t("physicalEvaluation:charts")}
                                percentualTitle={t("physicalEvaluation:fatPercentage")}
                                leanMassPercentageTitle={t("physicalEvaluation:leanMass")}
                                leanMassPercentageValue={percentualMassaMagra}
                                fatMassPercentageTitle={t("physicalEvaluation:fat")}
                                fatMassPercentageValue={percentualGordura}
                                doughnutValues={[percentualMassaMagra, percentualGordura]}
                                doughnutLabels={[t("physicalEvaluation:leanMass"), t("physicalEvaluation:fat")]}
                                leanFatMassTitle={t("physicalEvaluation:leanMassxFatMass")}
                                leanMassTitle={t("physicalEvaluation:leanMass")}
                                leanMassValue={massaMagraKg}
                                fatMassTitle={t("physicalEvaluation:fatMass")}
                                fatMassValue={massaGordaKg}
                                barValues={[massaMagraKg, massaGordaKg]}
                                barLabels={['', '']}
                            />
                        </div>
                        {physicalDetail?.images?.length > 0 && (
                            <div className={"card card-body border-0 mt-4 d-print-none"}>
                                <h5 className={"fw-semibold text-center py-2"}>{t("physicalEvaluation:images")}</h5>
                                <ImageCarousel images={physicalDetail.images}/>
                            </div>
                        )}
                        <div className={"card card-body border-0 mt-2 d-print-none"}>
                            <div className={isDesktop ? "row mb-2" : ""}>
                                {isDesktop && (
                                    <div className={"col-12"}>
                                        <button
                                            type={"button"}
                                            className={"btn btn-primary w-100 no-print"}
                                            onClick={() => {
                                                setTimeout(() => window.print(), 500)
                                            }}>
                                            {t("physicalEvaluation:print")}
                                        </button>
                                    </div>
                                )}
                            </div>
                            <button className={"btn btn-outline-primary w-100"} onClick={handleGoBackEval}>
                                {t("physicalEvaluation:backEvaluations")}
                            </button>
                            <button className={"btn btn-outline-primary w-100 mt-2"}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handlers.goEdit();
                                    }}>{t("physicalEvaluation:editButton")}
                            </button>
                            <button className={"btn btn-outline-danger w-100 mt-2"}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handlers.openDeleteModal();
                                    }}>{t("physicalEvaluation:delete")}
                            </button>
                        </div>
                    </div>
                </div>

            </Page>
            <PhysicalActionsButtons
                state={{currentPhysical, showDelete}}
                handlers={handlers}
            />
        </>
    )
}

export default PhysicalEvaluationView;
