import moment from "moment/moment";
import React from "react";
import {useDispatch} from "react-redux";
import {recoverEvaluation} from "../../store/online-evaluation/evaluationOnlineReducer";
import {addToast} from "../../store/toast/toastReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from ".//locales/en-us.json";
import ptBR from ".//locales/pt-br.json";
import esES from ".//locales/es-es.json";
import ptPT from ".//locales/pt-pt.json";

const OnlineEvaluationDeletedCard = ({title, evaluation}) => {
    const dispatch = useDispatch();
    const {t} = useTranslation();
    useComponentTranslations('evaluationOnlineComponents', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleRecover = () => {
        dispatch(recoverEvaluation({id: evaluation.id, status: 0}))
        const toastPayload = {
            id: "toast-" + evaluation.id,
            type: "success",
            title: `${t("evaluationOnlineComponents:operationCompleted")}`,
            message: `${t("evaluationOnlineComponents:evaluationSuccessfullyRecovered")}`,
            autohide: true,
            delay: 5000
        };
        dispatch(addToast(toastPayload));
    }

    return (
        <div className={"row pb-2"}>
            <div className={"card"}>
                <div className={"row d-flex align-items-center py-3"}>
                    <div className={"col-10 lh-1 pb-1"}>
                        <span className={"fw-semibold d-block"}>{title}</span>
                        <span className={"text-md fw-semibold me-1"}>{t("evaluationOnlineComponents:created")}</span>
                        <span className={"text-md"}>{moment(evaluation.sentDate).format('L')}</span>
                        <div>
                            <span className={"text-md fw-semibold me-1"}>{t("evaluationOnlineComponents:answered")}</span>
                            <span className={"text-md"}>
                              {evaluation.answerDate ? moment(evaluation.answerDate).format('L') : t("evaluationOnlineComponents:unansweredEvaluation")}
                            </span>
                        </div>
                    </div>
                </div>
                <hr className={"text-secondary my-n1"}/>
                <div className={"col-12 text-center clickable-element"}>
                    <button className={"btn btn-link text-md ps-0 fw-semibold mb-n1"}
                            onClick={handleRecover}
                    >{t("evaluationOnlineComponents:recoverEvaluation")}</button>
                </div>
            </div>
        </div>
    )
}

export default OnlineEvaluationDeletedCard;
