import {handleError} from "../../utils/error/sagaErrorHandling";
import {all, call, put, takeLatest} from 'redux-saga/effects';
import {
    createFinanceCategorieAPI,
    deleteFinanceCategorieAPI,
    deleteFinancesAPI,
    editFinancesAPI,
    getAllFinancesCategoriesAPI,
    getAllPersonalFinancesAPI,
    saveFinancesAPI,
    updateFinanceCategoryAPI
} from "../../api/personal-finances/personalFinancesActions";

import {
    getFinance,
    setFinance,
    onError,
    getAllCategories,
    setAllCategories,
    createCategory,
    categoryDeleted,
    deleteCategory,
    deletePersonalFinance,
    personalFinanceDeleted,
    updateCategory,
    getAllFinances,
    setAllFinances,
    editPersonalFinance, personalFinanceEdited
} from "./personalFinancesReducer";

export function* fetchAllCategoriesAsync() {
    try {
        const response = yield call(getAllFinancesCategoriesAPI);
        yield put(setAllCategories(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}
export function* onFetchAllCategories() {
    yield takeLatest(getAllCategories.type, fetchAllCategoriesAsync);
}

export function* deleteCategoryAsync(action) {
    try {
        yield call(deleteFinanceCategorieAPI, action.payload);
        yield put(categoryDeleted(action.payload));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onDeleteCategory() {
    yield takeLatest(deleteCategory.type, deleteCategoryAsync)
}

export function* updateCategoryAsync(action) {
    try{
        const {id, name} = action.payload;
        yield call(updateFinanceCategoryAPI, { id, nome: name });
        const response = yield call(getAllFinancesCategoriesAPI);
        yield put(setAllCategories(response.data));
    } catch (error){
        yield call(handleError, error, onError);
    }
}
export function* onUpdatedCategory() {
    yield takeLatest(updateCategory.type, updateCategoryAsync);
}

export function* createCategoryAsync({ payload: { name } }) {
    try {
        const { data } = yield call(createFinanceCategorieAPI, { nome: name });
        yield put(setAllCategories(data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onCreatedCategory() {
    yield takeLatest(createCategory.type ,createCategoryAsync);
}

export function* fetchAllFinancesAsync(action) {
    try{
        const {startDate, endDate} = action.payload;
        const response = yield call(getAllPersonalFinancesAPI, startDate, endDate);
        yield put(setAllFinances(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchAllFinances() {
    yield takeLatest(getAllFinances.type, fetchAllFinancesAsync);
}

export function* createOneFinanceAsync({payload}) {
    try {
        const response = yield call(saveFinancesAPI, payload);
        yield put(setFinance(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onCreateOneFinance() {
    yield takeLatest(getFinance.type, createOneFinanceAsync);
}

export function* deletePersonalFinanceAsync(action) {
    try{
        yield call(deleteFinancesAPI, action.payload);
        yield put(personalFinanceDeleted(action.payload));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onDeletePersonalFinance() {
    yield takeLatest(deletePersonalFinance.type, deletePersonalFinanceAsync)
}

export function* editFinanceAsync(action){
    try{
        yield call(editFinancesAPI, action.payload);
        yield put(personalFinanceEdited(action.payload));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onEditFinance() {
    yield takeLatest(editPersonalFinance.type, editFinanceAsync);
}

export function* personalFinancesSaga() {
    yield all([
        call(onFetchAllCategories),
        call(onDeleteCategory),
        call(onUpdatedCategory),
        call(onCreatedCategory),
        call(onFetchAllFinances),
        call(onDeletePersonalFinance),
        call(onCreateOneFinance),
        call(onEditFinance)
    ])
}

