import {takeLatest, all, call, put} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    getAllByTypeAPI,
    getAllAnamnesisAPI,
    createNewAnamnesisModelAPI,
    deleteAnamnesisAPI,
    updateAnamnesisAPI,
    sendAnamnesisAPI, getAnamnesisAPI, getAnamnesisModelAPI, updateModelAPI, createAnamnesisIwillFillAPI,
} from "../../api/anamnesis/anamnesisActions";
import {
    getModels,
    setModels,
    getAllAnamnesisList,
    setAllAnamnesisList,
    onError,
    modelCreated,
    createModel,
    anamnesisDeleted,
    deleteAnamnesis,
    getAnamnesis,
    getAnamnesisModel,
    setAnamnesis,
    updateAnamnesis,
    sendAnamnesis,
    updateModel,
    createAnamnesis,
    anamnesisCreated, deleteModel, modelDeleted, setSubmitResult
} from "./anamnesisReducer";
import {normalizeAnamnesisTemplate} from "../../utils/anamnesis/templateModel";


export function* fetchAnamnesisByTypeAsync(action) {
    try {
        const response = yield call(getAllByTypeAPI, action.payload);

        yield put(setModels(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchAnamnesisByType() {
    yield takeLatest(getModels.type, fetchAnamnesisByTypeAsync);
}

export function* fetchAllAnamnesisAsync(action) {
    try {
        const response = yield call(getAllAnamnesisAPI, action.payload);
        yield put(setAllAnamnesisList(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchAllAnamnesis() {
    yield takeLatest(getAllAnamnesisList.type, fetchAllAnamnesisAsync);
}

export function* createAnamnesisModelAsync(action) {
    try {
        const response = yield call(createNewAnamnesisModelAPI, action.payload);
        yield put(modelCreated(response.data));
        yield put(setSubmitResult({
            action: "create",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response.data?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreateAnamnesisModel() {
    yield takeLatest(createModel.type, createAnamnesisModelAsync);
}

export function* updateModelsAsync(action) {
    try {
        const response = yield call(updateModelAPI, action.payload);
        yield put(setAnamnesis(response.data ?? action.payload));
        yield put(setSubmitResult({
            action: "update",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response.data?.id ?? action.payload?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateModels() {
    yield takeLatest(updateModel.type, updateModelsAsync);
}

export function* fetchAnamnesisAsync(action) {
    try {
        const response = yield call(getAnamnesisAPI, action.payload);
        yield put(setAnamnesis(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchAnamnesis() {
    yield takeLatest(getAnamnesis.type, fetchAnamnesisAsync);
}

export function* fetchAnamnesisModelAsync(action) {
    try {
        const response = yield call(getAnamnesisModelAPI, action.payload);
        yield put(setAnamnesis(normalizeAnamnesisTemplate(response.data)));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchAnamnesisModel() {
    yield takeLatest(getAnamnesisModel.type, fetchAnamnesisModelAsync);
}

export function* updateAnamnesisAsync(action) {
    try {
        const data = action.payload;
        const response = yield call(updateAnamnesisAPI, data);
        yield put(setAnamnesis(response.data ?? data));
        yield put(setSubmitResult({
            action: "update",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? data?.idClient ?? null,
            entityId: response.data?.id ?? data?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onUpdateAnamnesis() {
    yield takeLatest(updateAnamnesis.type, updateAnamnesisAsync);
}

export function* deleteAnamnesisAsync(action) {
    try {
        const response = yield call(deleteAnamnesisAPI, action.payload);
        yield put(anamnesisDeleted(action.payload));
        yield put(setSubmitResult({
            action: "delete",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? action.payload
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onDeleteAnamnesis() {
    yield takeLatest(deleteAnamnesis.type, deleteAnamnesisAsync);
}

export function* deleteModelAsync(action) {
    try {
        const response = yield call(deleteAnamnesisAPI, action.payload);
        yield put(modelDeleted(action.payload));
        yield put(setSubmitResult({
            action: "delete",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? action.payload
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onDeleteModel() {
    yield takeLatest(deleteModel.type, deleteModelAsync);
}

export function* sendAnamnesisAsync(action) {
    try {
        const {idsToSend, modelId, sendTo} = action.payload;
        const response = yield call(sendAnamnesisAPI, idsToSend, modelId, sendTo);
        yield put(setSubmitResult({
            action: "send",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? modelId
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onSendAnamnesis() {
    yield takeLatest(sendAnamnesis.type, sendAnamnesisAsync)
}

export function* createAnamnesisAsync(action) {
    try {
        const response = yield call(createAnamnesisIwillFillAPI, action.payload);
        yield put(anamnesisCreated(response.data));
        yield put(setSubmitResult({
            action: "create",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? action.payload?.idClient ?? null,
            entityId: response.data?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onCreateAnamnesis() {
    yield takeLatest(createAnamnesis.type, createAnamnesisAsync);
}

export function* anamnesisSaga() {
    yield all([
        call(onFetchAnamnesisByType),
        call(onFetchAllAnamnesis),
        call(onCreateAnamnesisModel),
        call(onFetchAnamnesis),
        call(onFetchAnamnesisModel),
        call(onUpdateAnamnesis),
        call(onDeleteAnamnesis),
        call(onSendAnamnesis),
        call(onUpdateModels),
        call(onCreateAnamnesis),
        call(onDeleteModel)
    ]);
}
