import {useDispatch, useSelector} from "react-redux";
import {selectContacts, selectSignupLoading} from "../../store/signup-link/signupLinkSelector";
import {useEffect, useState} from "react";
import {deleteAllContacts, fetchContacts} from "../../store/signup-link/signupLinkReducer";
import _ from "lodash";
import moment from "moment/moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import 'moment/locale/pt-br';
import LoadingBlock from "../loader/LoadingBlock";
import Modal from "react-bootstrap/Modal";
import {Link} from "react-router-dom";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from 'he';
import SignupLinkDateFilterModal from "./SignupLinkDateFilterModal";
import EmptySet from "../empty-set/EmptySet";

const SignupLinkContacts = () => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const contacts = useSelector(selectContacts)
    const loading = useSelector(selectSignupLoading)
    const [sortedAndFilteredClients, setSortedAndFilteredClients] = useState([]);
    const [showModal, setShowModal] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [showDateFilterModal, setShowDateFilterModal] = useState(false);
    const [dateRange, setDateRange] = useState({startDate: "", endDate: ""});
    const hasDateFilter = Boolean(dateRange.startDate && dateRange.endDate);

    syncMomentLocale(i18n.language);
    useComponentTranslations('signupLinkComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const removeAccents = (str) => {
        return str.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    };

    useEffect(() => {
        const normalizedSearchTerm = removeAccents(searchTerm.toLowerCase());
        const filteredClients = contacts?.filter((client) => {
            const normalizedNome = removeAccents(client.nome.toLowerCase());
            const normalizedMail = removeAccents(client.mail.toLowerCase());
            const telefone = client.telefone;

            return (
                normalizedNome?.includes(normalizedSearchTerm) ||
                normalizedMail?.includes(normalizedSearchTerm) ||
                telefone?.includes(normalizedSearchTerm)
            );
        });
        const sortedClients = filteredClients?.sort((a, b) =>
            a.nome.localeCompare(b.nome, undefined, {sensitivity: 'base'})
        );
        setSortedAndFilteredClients(sortedClients);
    }, [contacts, searchTerm]);

    const handleSearchChange = (event) => {
        setSearchTerm(event.target.value);
    };

    const handleDeleteAll = () => {
        dispatch(deleteAllContacts())
        setShowModal(false);
    }

    const handleDeleteAllModal = () => {
        setShowModal(prevState => !prevState)
    }

    useEffect(() => {
        const isFiltered = Boolean(dateRange.startDate && dateRange.endDate);
        const payload = isFiltered ? dateRange : undefined;
        dispatch(fetchContacts(payload))
    }, [dispatch, dateRange]);

    const handleClearDateFilter = () => {
        setDateRange({startDate: "", endDate: ""});
    };

    return (
        <div className={'card card-body border-0 mt-3'}>
            <div className={'row justify-content-center'}>
                <div className={"col-auto"}>
                    <RoundedIcon icon={"fa-users-medical"} size={"lg"}/>
                </div>
                <div className={'col-12 pt-4 text-center'}>
                    <span className={'fw-semibold fs-3 d-block'}>{t("signupLinkComponent:contacts")}</span>
                    <div className={' pt-3'}>
                        <span className={'d-block'}>
                            {t("signupLinkComponent:contactsDescription")}
                        </span>
                    </div>
                </div>
                {
                    !loading && contacts &&
                    <>
                        <div className={'col-12 mt-2 d-flex gap-1'}>
                            <div className={"input-group mx-auto"}>
                                <input
                                    aria-label={t("signupLinkComponent:searchClient")}
                                    className={'form-control bg-white'}
                                    onChange={handleSearchChange}
                                    placeholder={t("signupLinkComponent:searchClient")}
                                    type={'search'}
                                    value={searchTerm}
                                />
                                <span className={'input-group-text bg-white'}>
                                    <i className={'fa-regular fa-magnifying-glass'}/>
                                </span>
                            </div>
                            <button
                                className={`input-group-text ${hasDateFilter ? "btn btn-feedback-primary text-primary" : "bg-white"}`}
                                type="button"
                                onClick={() => setShowDateFilterModal(true)}
                                aria-label={t("signupLinkComponent:filterByDate")}
                            >
                                <i className="fa-solid fa-sliders" aria-hidden="true"/>
                            </button>
                        </div>
                        {hasDateFilter && (
                            <div className="col-12 mt-2">
                                <div className="d-flex flex-wrap align-items-center gap-2">
                                    <span className="text-muted small">
                                        {t("signupLinkComponent:selectedPeriod")}
                                    </span>
                                    <span className="badge bg-primary-subtle text-primary fw-semibold d-inline-flex align-items-center gap-2">
                                        {moment(dateRange.startDate).format("DD/MM/YYYY")} – {moment(dateRange.endDate).format("DD/MM/YYYY")}
                                        <i
                                            className={"fa-regular fa-times clickable-element"}
                                            onClick={handleClearDateFilter}
                                            aria-label={t("signupLinkComponent:clearFilter")}
                                        ></i>
                                    </span>
                                </div>
                            </div>
                        )}
                    </>
                }
                {
                    !loading && contacts && contacts.length > 0 &&
                    <>
                        {
                        !hasDateFilter &&
                        <div className={'col-12 pt-3 text-center '}>
                            <span className={'fw-bold text-danger clickable-element'} onClick={handleDeleteAllModal}>{t("signupLinkComponent:deleteAll")}</span>
                        </div>
                    }

                        <div className={'col-12 pt-4  '}>
                            <ul className={' list-group'}>
                                {
                                    _.map(sortedAndFilteredClients, (contact) => (
                                        <li key={contact.id}
                                            className={'list-group-item border-0  rounded-0 clickable-element border-bottom  bg-white'}
                                        >
                                            <Link to={`/user/signup-link/contact/${contact.id}`} className={"text-decoration-none text-default"}>
                                                <div className={"row justify-content-between"}>
                                                    <div className={'col-auto'}>
                                                        <span className={'d-block fw-bold'}>{he.decode(contact.nome)} {he.decode(contact.sobrenome)}</span>
                                                        {
                                                            contact.dataCadastro &&
                                                            <span
                                                                className={"small text-secondary"}>{t("signupLinkComponent:signupAt")}: {moment({
                                                                year: contact.dataCadastro.year,
                                                                month: contact.dataCadastro.month - 1,
                                                                day: contact.dataCadastro.day
                                                            }).format("L")}</span>
                                                        }
                                                    </div>
                                                </div>
                                            </Link>
                                        </li>
                                    ))
                                }
                            </ul>
                        </div>
                    </>
                }
                {
                    !loading && contacts && contacts.length === 0 && hasDateFilter &&
                    <div className="col-12 pt-4">
                        <EmptySet
                            icon={"fa-magnifying-glass"}
                            message={t("signupLinkComponent:noFilterResultsTitle")}
                            message2={t("signupLinkComponent:noFilterResultsMessage")}
                        />
                    </div>
                }
                {
                    !loading && contacts && contacts.length > 0 && sortedAndFilteredClients?.length === 0 && searchTerm &&
                    <div className="col-12 pt-4">
                        <EmptySet
                            icon={"fa-magnifying-glass"}
                            message={t("signupLinkComponent:noSearchResultsTitle")}
                            message2={t("signupLinkComponent:noSearchResultsMessage")}
                        />
                    </div>
                }
                {
                    loading &&
                    <LoadingBlock height={"200px"}/>
                }
            </div>
            <Modal centered show={showModal} onHide={handleDeleteAllModal}>
                <Modal.Body>
                    <div className={'row'}>
                        <div className={"col-12 text-center"}>
                            <i className={'fa-regular fa-info-circle text-danger'} style={{fontSize: '4rem'}}></i>
                        </div>
                        <div className={'col-12 fw-semibold text-center mt-4'}>
                            <span className={'fs-5'}>{t("signupLinkComponent:deleteAllWarning")}</span>
                        </div>
                        <div className={'col-12   text-center mt-2'}>
                            <span>{t("signupLinkComponent:actionCantBeUndone")}</span>
                        </div>
                        <div className={'col-12 d-grid mt-3'}>
                            <button className={"btn btn-danger"} onClick={handleDeleteAll}>{t("signupLinkComponent:yesDelete")}</button>
                        </div>
                        <div className={'col-12 d-grid mt-2'}>
                            <button className={"btn btn-outline-danger"} onClick={handleDeleteAllModal}>{t("signupLinkComponent:goBack")}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            <SignupLinkDateFilterModal
                show={showDateFilterModal}
                onClose={() => setShowDateFilterModal(false)}
                onApply={(values) => setDateRange(values)}
                onClear={handleClearDateFilter}
                initialStartDate={dateRange.startDate}
                initialEndDate={dateRange.endDate}
            />
        </div>
    )
}

export default SignupLinkContacts;
