import React, {useEffect, useMemo, useState} from "react";
import {Image} from "react-bootstrap";
import img from './mfitdeouro.png'
import bannerRegistration from './bannerOuro.png'

export default function ContestCountdown({
                                             target,
                                             subtitle = "As inscrições começam em breve.",
                                         }) {
    const [isVisible, setIsVisible] = useState(false);
    const [showBanner, setShowBanner] = useState(true);

    // Pre-window where you previously showed the countdown (adjust if you want)
    const countdownWindowStart = useMemo(
        () => new Date(2025, 10, 4, 0, 0, 0, 0).getTime(),
        []
    );
    const countdownWindowEnd = useMemo(
        () => new Date(2025, 10, 10, 0, 0, 0, 0).getTime(), // exclusive
        []
    );

    // NEW: Banner window (inclusive of Nov 21; end is exclusive at 22:00:00.000)
    const bannerWindowStart = useMemo(
        () => new Date(2025, 10, 10, 0, 0, 0, 0).getTime(),
        []
    );
    const bannerWindowEnd = useMemo(
        () => new Date(2025, 10, 22, 0, 0, 0, 0).getTime(), // exclusive => shows through Nov 21
        []
    );

    const targetTime = useMemo(() => {
        if (target) return new Date(target).getTime();
        return new Date(2025, 10, 10, 0, 0, 0, 0).getTime();
    }, [target]);

    const [{days, hours, mins, secs}, setTime] = useState(
        computeRemaining(targetTime)
    );

    useEffect(() => {
        const timer = setInterval(() => {
            setTime(computeRemaining(targetTime));
        }, 1000);
        return () => clearInterval(timer);
    }, [targetTime]);

    // Visibility + which mode to show (countdown vs banner)
    useEffect(() => {
        const check = () => {
            const now = Date.now();
            const inCountdown = now >= countdownWindowStart && now < countdownWindowEnd;
            const inBanner = now >= bannerWindowStart && now < bannerWindowEnd;

            // Visible if either window is active
            setIsVisible(inCountdown || inBanner);
            setShowBanner(inBanner);
        };
        check();
        const id = setInterval(check, 60 * 1000);
        return () => clearInterval(id);
    }, [countdownWindowStart, countdownWindowEnd, bannerWindowStart, bannerWindowEnd]);

    if (!isVisible) return null;

    // --- RENDER ---
    if (showBanner) {
        // Show the banner between Nov 10–21
        return (
            <section className="container-fluid d-flex align-items-center justify-content-center bg-default py-4 py-md-5">
                <a href="https://mfitdeouro.mfitpersonal.com.br" rel="noreferrer" target="_blank" aria-label="Conheça o concurso MFIT de Ouro">
                    <Image src={bannerRegistration} alt="MFIT de Ouro - Inscrições" fluid />
                </a>
            </section>
        );
    }

    // Else: fallback to your original countdown UI
    return (
        <section className="container-fluid d-flex align-items-center justify-content-center  bg-default py-4 py-md-5">
            <style>{`
        .countdown-hero { max-width: 720px; background: linear-gradient(112deg,#010101 0%, #022663 64.6%); }
        .rounded-4 { border-radius: 1rem; }
        .text-gold-gradient { background: linear-gradient(87deg, #8C6827 35.36%, #F9E271 106.72%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
        .count-row { gap: .5rem; }
        @media (min-width:768px){ .count-row { gap: .75rem; } }
        .countdown-tile { min-width: 68px; padding: 10px 8px; border-radius: 12px; background: rgba(255,255,255,.08); backdrop-filter: blur(2px); border: 1px solid rgba(255,255,255,.1); }
        @media (min-width:768px){ .countdown-tile { min-width: 84px; padding: 12px 10px; } }
        .cd-number { font-family: "Hartwell Alt Bold", sans-serif; font-size: 28px; line-height: 1; letter-spacing: 1px; }
        @media (min-width:768px){ .cd-number { font-size: 36px; } }
        .cd-label { font-size: 12px; opacity: 0.9; margin-top: 6px; }
        @media (min-width:768px){ .cd-label { font-size: 14px; } }
        .cd-sep { font-family: "Hartwell Alt Bold", sans-serif; font-size: 26px; line-height: 1; opacity: .9; margin: 0 2px; }
        @media (min-width:768px){ .cd-sep { font-size: 32px; margin: 0 6px; } }
      `}</style>
            <div className="countdown-hero card border-0 rounded-4 shadow-lg px-3 px-md-4 py-4 py-md- text-white">
                <div className="row justify-content-center pb-4">
                    <div className="col-6">
                        <Image src={img} fluid />
                    </div>
                </div>
                <div className="d-flex align-items-center justify-content-center count-row mb-3 mb-md-4"
                     aria-label="Contagem regressiva para 10 de novembro de 2025">
                    <Tile id="cd-days" value={days} label="dias"/>
                    <Separator/>
                    <Tile id="cd-hours" value={hours} label="horas"/>
                    <Separator/>
                    <Tile id="cd-mins" value={mins} label="min"/>
                    <Separator/>
                    <Tile id="cd-secs" value={secs} label="seg"/>
                </div>
                <p className="text-center text-lg-regular mb-0 pt-3">{subtitle}</p>
                <a href="https://mfitdeouro.mfitpersonal.com.br" rel="noreferrer" target="_blank"
                   className="text-center text-lg-regular text-gold-gradient pt-2 fw-semibold mb-0">
                    Conheça o concurso <i className="fa-regular fa-arrow-right"></i>
                </a>
            </div>
        </section>
    );
}

function Tile({id, value, label}) {
    return (
        <div className="countdown-tile text-center" role="group" aria-labelledby={`${id}-label`}>
            <div id={id} className="cd-number" aria-live="polite" aria-atomic="true">
                {pad2(value)}
            </div>
            <div id={`${id}-label`} className="cd-label">
                {label}
            </div>
        </div>
    );
}

function Separator() {
    return <div className="cd-sep" aria-hidden>:</div>;
}

function pad2(n) {
    return String(n).padStart(2, "0");
}

function computeRemaining(targetTime) {
    const now = Date.now();
    let ms = targetTime - now;
    if (ms <= 0) return {days: 0, hours: 0, mins: 0, secs: 0};

    const sec = 1000;
    const min = 60 * sec;
    const hr = 60 * min;
    const day = 24 * hr;

    const days = Math.floor(ms / day);
    ms %= day;
    const hours = Math.floor(ms / hr);
    ms %= hr;
    const mins = Math.floor(ms / min);
    ms %= min;
    const secs = Math.floor(ms / sec);

    return {days, hours, mins, secs};
}
