import _ from "lodash";
import React, {useCallback, useEffect, useState} from "react";
import {closestCenter, DndContext, PointerSensor, useSensor, useSensors} from "@dnd-kit/core";
import {arrayMove, SortableContext, verticalListSortingStrategy} from "@dnd-kit/sortable";
import SortableSeriesRow from "./SortableSeriesRow";
import ExercisePlayerType from "../utils/videoplayer/ExercisePlayerType";
import {useDispatch, useSelector} from "react-redux";
import {
    changeSeriesOrder, deleteExerciseFromSession, promoteExercise, replaceExercise,
    replicateSeries, setExerciseReplaced,
    setSeriesReplicated,
    setSerieUpdated,
    splitExercises
} from "../../store/workout-prescription/workoutPrescriptionReducer";
import Modal from "react-bootstrap/Modal";
import WorkoutPrescriptionAddSerie from "./WorkoutPrescriptionAddSerie";
import {
    selectWorkoutExerciseLoading, selectWorkoutExerciseReplaced,
    selectWorkoutSeriesReplicated,
    selectWorkoutSeriesUpdated,
    selectWorkoutSeriesUpdating,
    selectWorkoutSession
} from "../../store/workout-prescription/workoutPrescriptionSelector";
import LoadingBlock from "../loader/LoadingBlock";
import {Dropdown} from "react-bootstrap";
import BodyMenu from "./BodyMenu";
import {useNavigate, useSearchParams} from "react-router-dom";
import {selectSelectedClient} from "../../store/client/clientSelector";
import LoadingPageOpaque from "../loader/LoadingPageOpaque";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {translateExerciseName} from "../../utils/workout/Exercise";
import SimpleExerciseSearchModal from "./SimpleExerciseSearchModal";
import Text from "../../components/utils/emoji/Text";
import WorkoutPresetPickerOffcanvas from "../workout-preset/WorkoutPresetPickerOffcanvas";
import SaveCurrentPresetModal from "../workout-preset/SaveCurrentPresetModal";
import {
    applyWorkoutPreset,
    clearWorkoutPresetEvents,
    createWorkoutPreset,
    fetchWorkoutPresets,
    saveCurrentWorkoutPreset
} from "../../store/workout-preset/workoutPresetReducer";
import {
    selectLastAppliedWorkoutPreset,
    selectLastCreatedWorkoutPreset,
    selectLastSavedCurrentWorkoutPreset,
    selectWorkoutPresetApplyLoading,
    selectWorkoutPresetLoading,
    selectWorkoutPresets
} from "../../store/workout-preset/workoutPresetSelector";

const PRESET_PICKER_PARAM = "presetPicker";
const PRESET_EXERCISE_SESSION_PARAM = "presetExercSession";

const WorkoutPrescriptionExerciseCard = ({
                                             selected,
                                             toggleSelect,
                                             deselect,
                                             ex,
                                             exercises,
                                             handleNextExercise,
                                             handlePreviousExercise,
                                             hasAlternative,
                                             showPrevious,
                                             showNext,
                                             expand,
                                             mainExerc,
                                             onToggleExpand
                                         }) => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch()
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();
    const [seriesList, setSeriesList] = useState(ex.series);
    const [showSerieModal, setShowSerieModal] = useState(false);
    const serieLoading = useSelector(selectWorkoutSeriesUpdating);
    const seriesUpdated = useSelector(selectWorkoutSeriesUpdated);
    const [showReplicate, setShowReplicate] = useState(false);
    const [targets, setTargets] = useState([]);
    const session = useSelector(selectWorkoutSession)
    const seriesReplicated = useSelector(selectWorkoutSeriesReplicated)
    const client = useSelector(selectSelectedClient)
    const exercisesLoading = useSelector(selectWorkoutExerciseLoading)
    const [showAddExerciseModal, setShowAddExerciseModal] = useState(false)
    const exerciseReplaced = useSelector(selectWorkoutExerciseReplaced)
    const [showPresetModal, setShowPresetModal] = useState(false);
    const [showSavePresetModal, setShowSavePresetModal] = useState(false);
    const presets = useSelector(selectWorkoutPresets);
    const presetLoading = useSelector(selectWorkoutPresetLoading);
    const presetApplyLoading = useSelector(selectWorkoutPresetApplyLoading);
    const lastAppliedPreset = useSelector(selectLastAppliedWorkoutPreset);
    const lastCreatedPreset = useSelector(selectLastCreatedWorkoutPreset);
    const lastSavedCurrentPreset = useSelector(selectLastSavedCurrentWorkoutPreset);
    const [creatingPresetForCurrentExercise, setCreatingPresetForCurrentExercise] = useState(false);

    useComponentTranslations('workoutPrescriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleDeleteExercise = () => {
        deselect(ex.idExercSession)
        dispatch(deleteExerciseFromSession({sessionId: session.id, exercSessionId: ex.idExercSession}))
    }

    const handleAddAlternativeExercise = () => {
        navigate(`/user/client/${client ? client.id : 0}/workout/routine/${session.idRoutine}/session/${session.id}/alternative/${mainExerc}`)
    }

    const handleReplaceExercise = () => {
        setShowAddExerciseModal(prevState => !prevState)
    }

    const handleReplaceInLibrary = () => {
        navigate(`/user/client/${client ? client.id : 0}/workout/routine/${session.idRoutine}/session/${session.id}/replace/${ex.idExercSession}`)
    }

    const handleReplaceExerc = (id) => {
        const payload = {
            idExercSession: ex.idExercSession,
            newExerc: id
        }
        deselect(ex.idExercSession)
        dispatch(replaceExercise(payload))
        handleReplaceExercise();
    }


    const handlePromoteExercise = () => {
        deselect(ex.idExercSession)
        dispatch(promoteExercise({idMainExercSession: mainExerc, idMainExercSessionToBeMain: ex.idExercSession, sessionId: session.id}))
    }

    const handleSplitExercise = () => {
        const payload = {
            sessionId: session.id,
            combinedSessionId: ex.idExercSession
        }
        deselect(ex.idExercSession)
        dispatch(splitExercises(payload))

    }

    const handleReplicateModalOpen = () => {
        setShowReplicate(true);
    }

    const handleReplicateModalClose = () => {
        setShowReplicate(false);
        setTargets([]);
    };

    const toggleTarget = sessionId => {
        setTargets(prev =>
            prev.includes(sessionId)
                ? prev.filter(id => id !== sessionId)
                : [...prev, sessionId]
        );
    };

    const handleReplicateSerie = () => {
        const payload = {
            originSession: ex.idExercSession,
            targetSessions: targets,
            sessionId: session.id
        }
        deselect(ex.idExercSession)
        dispatch(replicateSeries(payload));
    }

    const handleSeriesDragEnd = ({active, over}) => {
        if (!over || active.id === over.id) return;
        let newIndex = 0;
        setSeriesList((items) => {
            const oldIndex = items.findIndex((i) => i.id === active.id);
            newIndex = items.findIndex((i) => i.id === over.id);
            return arrayMove(items, oldIndex, newIndex);
        });

        const payload = {
            seriesId: active.id,
            pos: newIndex
        }
        dispatch(changeSeriesOrder(payload))
    };

    const sensors = useSensors(
        useSensor(PointerSensor, {activationConstraint: {distance: 5}})
    );

    const handleAddSerieModal = () => {
        setShowSerieModal(prevState => !prevState)
    }

    const handleOpenPresetModal = () => {
        const nextSearchParams = new URLSearchParams(searchParams);
        nextSearchParams.set(PRESET_PICKER_PARAM, "1");
        nextSearchParams.set(PRESET_EXERCISE_SESSION_PARAM, String(ex.idExercSession));
        setSearchParams(nextSearchParams);
    };

    const handleClosePresetModal = useCallback(() => {
        const nextSearchParams = new URLSearchParams(searchParams);
        nextSearchParams.delete(PRESET_PICKER_PARAM);
        nextSearchParams.delete(PRESET_EXERCISE_SESSION_PARAM);
        setSearchParams(nextSearchParams, {replace: true});
        setCreatingPresetForCurrentExercise(false);
        dispatch(clearWorkoutPresetEvents());
    }, [dispatch, searchParams, setSearchParams]);

    const handleOpenSavePresetModal = () => {
        setShowSavePresetModal(true);
    };

    const handleCloseSavePresetModal = () => {
        setShowSavePresetModal(false);
    };

    const handleApplyPreset = (preset) => {
        dispatch(applyWorkoutPreset({idExercSession: ex.idExercSession, presetId: preset.id}));
    };

    const handleCreatePreset = (payload) => {
        setCreatingPresetForCurrentExercise(true);
        dispatch(clearWorkoutPresetEvents());
        dispatch(createWorkoutPreset(payload));
    };

    const handleSaveCurrentPreset = (name) => {
        dispatch(saveCurrentWorkoutPreset({idExercSession: ex.idExercSession, name}));
    };

    const handleExpand = () => {
        onToggleExpand()
    }

    const replicable = exercises
        .flatMap(wrapper =>
            wrapper.exerciseArray.map((exercise, index) => ({
                exercise,
                isAlternative: index > 0,
            }))
        )
        .filter(item =>
            item.exercise &&
            !item.exercise.isCombinado &&
            item.exercise.idExercSession !== ex.idExercSession
        );

    const replicableIds = replicable.map(item => item.exercise.idExercSession);

    useEffect(() => {
        if (exerciseReplaced) {
            dispatch(setExerciseReplaced(false))
        }
    }, [exerciseReplaced, dispatch]);

    useEffect(() => {
        if (seriesUpdated) {
            dispatch(setSerieUpdated(false))
            setShowSerieModal(false)
        }
    }, [seriesUpdated, dispatch]);

    useEffect(() => {
        if (seriesReplicated) {
            dispatch(setSeriesReplicated(false))
            handleReplicateModalClose()
        }
    }, [seriesReplicated, dispatch]);

    useEffect(() => {
        setSeriesList(ex.series);
    }, [ex.series]);

    useEffect(() => {
        const shouldOpenPresetModal =
            searchParams.get(PRESET_PICKER_PARAM) === "1" &&
            searchParams.get(PRESET_EXERCISE_SESSION_PARAM) === String(ex.idExercSession);

        if (shouldOpenPresetModal && !showPresetModal) {
            dispatch(fetchWorkoutPresets());
            setShowPresetModal(true);
            return;
        }

        if (!shouldOpenPresetModal && showPresetModal) {
            setShowPresetModal(false);
        }
    }, [dispatch, ex.idExercSession, searchParams, showPresetModal]);

    useEffect(() => {
        if (creatingPresetForCurrentExercise && lastCreatedPreset?.id) {
            dispatch(applyWorkoutPreset({idExercSession: ex.idExercSession, presetId: lastCreatedPreset.id}));
            setCreatingPresetForCurrentExercise(false);
        }
    }, [creatingPresetForCurrentExercise, dispatch, ex.idExercSession, lastCreatedPreset]);

    useEffect(() => {
        if (lastAppliedPreset?.idExercSession === ex.idExercSession) {
            handleClosePresetModal();
            dispatch(clearWorkoutPresetEvents());
        }
    }, [dispatch, ex.idExercSession, handleClosePresetModal, lastAppliedPreset]);

    useEffect(() => {
        if (lastSavedCurrentPreset?.id) {
            setShowSavePresetModal(false);
            dispatch(clearWorkoutPresetEvents());
        }
    }, [dispatch, lastSavedCurrentPreset]);

    const isMainExercise = ex.idExercSession === mainExerc;

    const handleCheckboxChange = () => {
        if (isMainExercise) {
            toggleSelect(mainExerc);
        }
    };

    return (
        <>

            <div className={"row"} key={ex.id}>
                <div className={"col-10 col-lg-11 d-flex flex-column"} style={{minWidth: 0}}>
                    {
                        ex.isCombinado &&
                        <div className={"row"}>
                            <div className={"col-1 align-self-center pe-4 "}>
                                    <input
                                    type="checkbox"
                                    className="form-check-input border-primary-subtle"
                                    checked={selected}
                                    onChange={handleCheckboxChange}
                                    disabled={!isMainExercise}
                                />
                            </div>
                            <div className={"col-10 p-0"}>
                                {
                                    _.map(ex.series, (serie) =>
                                        <React.Fragment key={serie.id}>
                                            <>
                                                {
                                                    serie.idExerc > 0 &&
                                                    <span
                                                        key={serie.id}
                                                        className={`d-block  ps-0  ${
                                                            expand ? "" : "text-truncate"
                                                        } fw-semibold clickable-element`}
                                                        style={{width: "100%", minWidth: 0}}
                                                        onClick={handleExpand}
                                                    >{translateExerciseName(serie?.exercicio, i18n.language)}</span>
                                                }
                                            </>
                                        </React.Fragment>
                                    )
                                }
                            </div>

                        </div>
                    }
                    {
                        !ex.isCombinado &&
                        <>
                            <div className={"row"}>
                                <div className={"col-1 pe-4"}>
                                    <input
                                        type="checkbox"
                                        className=" form-check-input border-primary-subtle"
                                        checked={selected}
                                        onChange={handleCheckboxChange}
                                        disabled={!isMainExercise}
                                    />
                                </div>
                                <div className={"col-10 p-0"}>
                                    <span className={`flex-grow-1 d-block ${expand ? "" : "text-truncate"} fw-semibold clickable-element`} style={{minWidth: 0}}
                                          onClick={handleExpand}>
                                             <Text>{translateExerciseName(ex, i18n.language)}</Text>
                                    </span>
                                </div>
                            </div>
                        </>
                    }
                </div>
                <div className={"col-2 col-lg-1 pe-0 ps-0 align-self-center"}>
                    <div className={"row justify-content-between"}>
                        <div className={"col-6    "}>
                            <Dropdown onClick={e => e.stopPropagation()}>
                                <Dropdown.Toggle
                                    className={"no-style-btn text-default"}>
                                    <i className={"fa-regular fa-ellipsis-h "}> </i>
                                </Dropdown.Toggle>
                                <Dropdown.Menu as={BodyMenu}>
                                    {
                                        ex.isCombinado &&
                                        <Dropdown.Item onClick={handleSplitExercise}>{t("workoutPrescriptionComponent:decombine")}</Dropdown.Item>
                                    }
                                    {
                                        !ex.isCombinado &&
                                        <>
                                            <Dropdown.Item onClick={handleReplaceExercise}>{t("workoutPrescriptionComponent:swapExercise")}</Dropdown.Item>
                                            <Dropdown.Item onClick={handleOpenPresetModal}>{t("workoutPrescriptionComponent:applyPreset")}</Dropdown.Item>
                                            <Dropdown.Item onClick={handleOpenSavePresetModal}>{t("workoutPrescriptionComponent:saveAsPreset")}</Dropdown.Item>
                                            {
                                                showPrevious &&
                                                <Dropdown.Item
                                                    onClick={handlePromoteExercise}>{t("workoutPrescriptionComponent:promoteExercise")}</Dropdown.Item>
                                            }
                                            <Dropdown.Item
                                                onClick={handleAddAlternativeExercise}>{t("workoutPrescriptionComponent:addAlternativeExercise")}</Dropdown.Item>
                                        </>
                                    }
                                    {
                                        ex.isCombinado &&
                                        <>
                                            <Dropdown.Item onClick={handleOpenPresetModal}>{t("workoutPrescriptionComponent:applyPreset")}</Dropdown.Item>
                                            <Dropdown.Item onClick={handleOpenSavePresetModal}>{t("workoutPrescriptionComponent:saveAsPreset")}</Dropdown.Item>
                                        </>
                                    }
                                    <Dropdown.Divider/>
                                    <Dropdown.Item onClick={handleDeleteExercise}
                                                   className={"text-danger"}>{t("workoutPrescriptionComponent:delete")}</Dropdown.Item>
                                </Dropdown.Menu>
                            </Dropdown>
                        </div>
                        <div className={"col-6 ps-0 clickable-element"} onClick={handleExpand}>
                            <i className={`fa-regular ${expand ? "fa-chevron-up" : "fa-chevron-down"} `}> </i>
                        </div>
                    </div>
                </div>
                {
                    expand &&
                    <div className={"row justify-content-center mt-4"}>
                        {
                            exercisesLoading &&
                            <LoadingPageOpaque/>
                        }
                        {
                            hasAlternative &&
                            <>
                                {
                                    showPrevious ?
                                        <div className={"col-1 align-self-center  clickable-element"} onClick={handlePreviousExercise}>
                                            <i className={"fa-regular fa-arrow-left text-primary-darker"}></i>
                                        </div> :
                                        <div className={"col-1 align-self-center"}></div>
                                }
                            </>
                        }
                        {
                            !ex.isCombinado &&
                            <div className={"col-9 pe-0"}>
                                <div className={"row "}>
                                    <ExercisePlayerType exercise={ex}/>
                                </div>
                            </div>
                        }
                        {
                            hasAlternative &&
                            <>
                                {
                                    showNext ?
                                        <div className={"col-1 align-self-center clickable-element ps-2 "} onClick={handleNextExercise}>
                                            <i className={"fa-regular fa-arrow-right text-primary-darker"}></i>
                                        </div> :
                                        <div className={"col-1 align-self-center"}>
                                        </div>
                                }
                            </>
                        }
                        <div className={`col-${hasAlternative ? "10" : "12"}`}>
                            <DndContext
                                sensors={sensors}
                                collisionDetection={closestCenter}
                                onDragEnd={handleSeriesDragEnd}
                            >
                                <SortableContext
                                    items={seriesList.map(({id}) => id)}
                                    strategy={verticalListSortingStrategy}
                                >
                                    {seriesList.map((serie) => (
                                        <SortableSeriesRow listSize={seriesList.length} key={serie.id} serie={serie}/>
                                    ))}
                                </SortableContext>
                            </DndContext>
                        </div>

                        <div className="col-12 mt-2">
                            <div className="row g-2">
                                <div className={`${ex.isCombinado ? "col-6 col-lg-6" : "col-6 col-lg-4"}`}>
                                    <button
                                        className={"btn btn-primary w-100 btn-sm"}
                                        onClick={handleAddSerieModal}
                                    >
                                        {t("workoutPrescriptionComponent:addSeries")}
                                    </button>
                                </div>
                                {!ex.isCombinado && (
                                    <div className="col-6 col-lg-4">
                                        <button
                                            className={"btn btn-outline-primary w-100 btn-sm"}
                                            onClick={handleReplicateModalOpen}
                                        >
                                            {t("workoutPrescriptionComponent:replicateSerie")}
                                        </button>
                                    </div>
                                )}
                                <div className={`${ex.isCombinado ? "col-12 col-lg-6" : "col-12 col-lg-4"}`}>
                                    <button
                                        className={"btn btn-outline-primary w-100 btn-sm"}
                                        onClick={handleOpenPresetModal}
                                    >
                                        {t("workoutPrescriptionComponent:applyPreset")}
                                    </button>
                                </div>
                                <div className="col-12">
                                    <div className="d-flex justify-content-center pt-1">
                                        <button
                                            className={"btn btn-link text-primary text-decoration-none fw-semibold btn-sm px-0"}
                                            onClick={handleOpenSavePresetModal}
                                        >
                                            {t("workoutPrescriptionComponent:saveAsPreset")}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <Modal show={showSerieModal} centered onHide={handleAddSerieModal}>
                            <Modal.Body>
                                {
                                    serieLoading &&
                                    <LoadingBlock height={"200px"}/>
                                }
                                {
                                    !serieLoading &&
                                    <>
                                        <div className={"row mb-3"}>
                                            <div className={"col-12"}>
                                                <span className={"fw-semibold"}>{t("workoutPrescriptionComponent:selectSerieType")}</span>
                                            </div>
                                        </div>
                                        <WorkoutPrescriptionAddSerie
                                            isCombinado={ex.isCombinado}
                                            defaultTipo={
                                                ex.series.length > 0
                                                    ? ex.series[ex.series.length - 1].tipo
                                                    : ""
                                            }
                                            idExercSession={ex.idExercSession}/>
                                    </>
                                }
                            </Modal.Body>
                        </Modal>
                        <Modal show={showReplicate} onHide={handleReplicateModalClose} centered>
                            <Modal.Body>
                                {
                                    serieLoading &&
                                    <LoadingBlock height={"200px"}/>
                                }
                                {
                                    !serieLoading &&
                                    <div className={"row"}>
                                        <div className={"col-12"}>
                                            <span className={"fw-semibold"}>{t("workoutPrescriptionComponent:selectTheExercisesToReplicateSeriesTo")}</span>
                                        </div>
                                        <div className="col-12  mb-2">
                                            <div className="form-check">
                                                <input
                                                    id="select-all"
                                                    type="checkbox"
                                                    className="form-check-input"
                                                    checked={
                                                        targets.length === replicableIds.length &&
                                                        replicableIds.length > 0
                                                    }
                                                    onChange={() =>
                                                        setTargets(
                                                            targets.length === replicableIds.length
                                                                ? []
                                                                : replicableIds
                                                        )
                                                    }
                                                />
                                                <label htmlFor="select-all" className="form-check-label">
                                                    {t("workoutPrescriptionComponent:selectAll")}
                                                </label>
                                            </div>
                                        </div>
                                        <div className={"col-12  "}>
                                            {replicable.map(({exercise: exObj, isAlternative}) => {
                                                const sessionId = exObj.idExercSession;
                                                const label = exObj.name;
                                                return (
                                                    <div className="form-check" key={sessionId}>
                                                        <input
                                                            id={`rep-${sessionId}`}
                                                            type="checkbox"
                                                            className="form-check-input"
                                                            checked={targets.includes(sessionId)}
                                                            onChange={() => toggleTarget(sessionId)}
                                                        />
                                                        <label
                                                            htmlFor={`rep-${sessionId}`}
                                                            className="form-check-label"
                                                        >
                                                            <Text>{label}</Text>
                                                            {isAlternative && (
                                                                <span className="badge bg-secondary-subtle text-secondary ms-1">
                                                                    {t('workoutPrescriptionComponent:alternative')}
                                                                </span>
                                                            )}
                                                        </label>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                        <div className={"col-12 mt-4"}>
                                            <div className={"d-grid"}>
                                                <button
                                                    className="btn btn-primary"
                                                    disabled={!targets.length}
                                                    onClick={handleReplicateSerie}
                                                >
                                                    {t("workoutPrescriptionComponent:confirm")}
                                                </button>
                                            </div>
                                            <div className={"d-grid mt-2"}>
                                                <button className="btn btn-outline-primary  " onClick={handleReplicateModalClose}>
                                                    {t("workoutPrescriptionComponent:cancel")}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                }
                            </Modal.Body>
                        </Modal>
                    </div>
                }
                <WorkoutPresetPickerOffcanvas
                    show={showPresetModal}
                    onHide={handleClosePresetModal}
                    presets={presets}
                    loading={presetLoading}
                    selectionLoading={presetApplyLoading}
                    title={t("workoutPrescriptionComponent:applyPreset")}
                    onSelectPreset={handleApplyPreset}
                    onCreatePreset={handleCreatePreset}
                />
                <SaveCurrentPresetModal
                    show={showSavePresetModal}
                    onHide={handleCloseSavePresetModal}
                    loading={presetLoading}
                    defaultName={translateExerciseName(ex, i18n.language)}
                    onSubmit={handleSaveCurrentPreset}
                />
                <Modal centered show={showAddExerciseModal} onHide={handleReplaceExercise}>
                    <Modal.Body>
                        <div className={"row justify-content-center mb-2"}>
                            <div className={"col-12"}>
                                <span className={"fw-semibold fs-5 d-block"}>{t("workoutPrescriptionComponent:replaceExercise")}</span>
                                <span>{t("workoutPrescriptionComponent:pickExercise")}</span>
                            </div>
                            <div className={"col-12  mt-3 mb-3 text-center"}>
                                <span className={"fw-semibold small text-primary clickable-element"}
                                      onClick={handleReplaceInLibrary}>{t("workoutPrescriptionComponent:goToLibrary")}</span>
                            </div>
                        </div>
                        <SimpleExerciseSearchModal
                            exerciseName={translateExerciseName(ex, i18n.language)}
                            onSelect={item => {
                                const newExerc = Number(item.objectID);
                                handleReplaceExerc(newExerc);
                            }}
                        />
                    </Modal.Body>
                </Modal>
            </div>
        </>
    )
}

export default WorkoutPrescriptionExerciseCard;
