import ExerciseLibraryCard from './ExerciseLibraryCard';
import EmptySet from '../empty-set/EmptySet';

export default function ExerciseHit({
                                        hits = [],
                                        addedExercises,
                                        isReplace,
                                        isSerieReplace,
                                        isAddExerciseAsSerie,
                                        handleReplace
                                    }) {
    if (!hits.length) {
        return <EmptySet icon="fa-empty-set" message="No results"/>;
    }
    return (
        <>
            {hits.map(hit => (
                <ExerciseLibraryCard
                    key={hit.objectID}
                    hit={hit}
                    addedExercises={addedExercises}
                    handleReplace={handleReplace}
                    isReplace={isReplace}
                    isSerieReplace={isSerieReplace}
                    isAddExerciseAsSerie={isAddExerciseAsSerie}
                />
            ))}
        </>
    );
}
