import {createSlice} from '@reduxjs/toolkit'

const initialState = {
    loading: false,
    pushSent: false,
    notifications: null,
}

const slice = createSlice({
    name: 'push',
    initialState,
    reducers: {
        sendPush(state) {
            state.loading = true
        },
        pushSent(state, action) {
            state.pushSent = action.payload
            state.loading = false
        },
        setNotifications(state, action) {
            state.notifications = action.payload
            state.loading = false
        },
        fetchNotifications(state) {
            state.loading = true
        },
        schedulePush(state) {
            state.loading = true
        },
        changePushStatus(state) {
            state.loading = true
        },
        pushStatusChanged(state, action) {
            if (action.payload.status === 2) {
                state.notifications = state.notifications.filter(n => n.id !== action.payload.id);
            } else {
                const notification = state.notifications.find(n => n.id === action.payload.id);
                if (notification) {
                    notification.status = action.payload.status;
                }
            }
            state.loading = false;
        },
        updatePush(state) {
            state.loading = true
        },
        onError(state) {
            state.loading = false
        }
    }
})

export const {
    sendPush,
    pushSent,
    schedulePush,
    setNotifications,
    fetchNotifications,
    changePushStatus,
    pushStatusChanged,
    updatePush,
    onError
} = slice.actions
export const pushReducer = slice.reducer

