import React, { useState } from 'react';
import {Modal, ModalBody, ModalHeader, ModalTitle} from 'react-bootstrap';
import LineChart from './LineChart';

export default function ChartCard({ field, dataValues, chartLabels, textButton }) {
    const [show, setShow] = useState(false);

    const open = () => setShow(true);
    const close = () => setShow(false);

    return (
        <>
            <div className="col-md-6 mb-4 mt-2">
                <div className="card card-body">
                    <div className="row justify-content-between align-items-center mb-2">
                        <div className="col-8">
                            <span className="card-title fw-semibold">{field.label}</span>
                        </div>
                        <div className="col-4 text-end d-none d-md-block">
                            <button
                                type="button"
                                className="btn btn-link p-0"
                                onClick={open}
                            >
                                {textButton}
                            </button>
                        </div>
                    </div>
                    <LineChart
                        dataValues={dataValues}
                        unit={field.unit}
                        chartLabels={chartLabels}
                    />
                </div>
            </div>
            <Modal show={show} onHide={close} size="lg" centered>
                <ModalHeader closeButton>
                    <ModalTitle id={`modal-${field.id}-title`}>
                        {field.label}
                    </ModalTitle>
                </ModalHeader>
                <ModalBody style={{ height: 400 }}>
                    <LineChart
                        dataValues={dataValues}
                        unit={field.unit}
                        chartLabels={chartLabels}
                    />
                </ModalBody>
            </Modal>
        </>
    );
}
