import RoundedIcon from "../rounded-icon/RoundedIcon";
import {useLogout} from "../../utils/logout/logout";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/block/locales/en-us.json";
import ptBR from "../../pages/block/locales/pt-br.json";
import esES from "../../pages/block/locales/es-es.json";
import ptPT from "../../pages/block/locales/pt-pt.json";
import {useTranslation} from "react-i18next";


const UserBlockedMessage = ({
                                icon,
                                iconColor = "text-primary",
                                title,
                                message,
                                buttonText,
                                buttonClick,
                                bgColor = "bg-primary-subtle",
                                btnClass = "btn-primary-lighter"
                            }) => {
    const {t} = useTranslation();
    const {logout} = useLogout();
    useComponentTranslations('block', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleLogoutClick = () => {
        logout()
    };

    return (
        <div className={"card card-body"}>
            <div className={'row justify-content-center pt-4 pb-4'}>

                <div className={'col-6 col-md-5 text-center'}>
                    <RoundedIcon icon={icon} size={"xl"} textColor={iconColor} bgColor={bgColor}/>
                </div>
            </div>
            {
                title &&
                <div className="row justify-content-center">
                    <div className="col-auto pb-3">
                        <span className={'fs-5 fw-bold d-block text-center'}>{title}</span>
                    </div>
                </div>
            }
            {
                message &&
                <div className={'row justify-content-center'}>
                    <div className={'col-12 text-center'}>
                        <span>{message}</span>
                    </div>
                </div>
            }
            <div className="row justify-content-center pt-4">
                <div className="col-12">
                    <div className={'d-grid'}>
                        <button className={`btn ${btnClass}`} onClick={buttonClick}>{buttonText}</button>
                    </div>
                    <div className={'d-grid pt-2'}>
                        <button className={`btn btn-link`} onClick={handleLogoutClick}>{t("block:exit")}</button>
                    </div>
                </div>
            </div>
        </div>
    )
}
export default UserBlockedMessage