import {useEffect, useState} from "react";
import {useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";
import {checkDateProximity} from "../../utils/date/dateUtils";
import Cookies from "js-cookie";
import {getMainDomain} from "../../utils/cookie/cookieUtils";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {handleSubscriptionButton} from "../../utils/handlers/handler";
import {useNavigate} from "react-router-dom";

const TrialEnding = () => {
    const {t} = useTranslation();
    const user = useSelector(selectUser)
    const [show, setShow] = useState(false)
    const navigate = useNavigate();
    useComponentTranslations('warning', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleCloseClick = () => {
        const mainDomain = getMainDomain();
        Cookies.set('trialEndingShown', true, {expires: 3600, path: '/', domain: `.${mainDomain}`});
        setShow(false)
    }

    useEffect(() => {
        if (user?.tipoPlano === 200 && !Cookies.get("trialEndingShown")) {
            setShow(checkDateProximity(user.venc))
        } else setShow(false)
    }, [user])

    if (!show)
        return;

    return (
        <div className={'row'}>
            <div className={'col-12'}>
                <div className={'card card-body bg-warning-subtle  border-0 mt-4'}>
                    <div className={'row'}>
                        <div className={'col-2 text-center align-self-center '}>
                            <i className={'fa-regular fa-dollar-circle fa-2xl'}></i>
                        </div>
                        <div className={'col-8 ps-0 align-self-center clickable-element'} onClick={() => handleSubscriptionButton(navigate)}>
                            <span className={'d-block   fw-semibold'}>{t("warning:trialExpiring")}</span>
                            <span className={'d-block'}>{t("warning:clickForMoreInformation")}</span>
                        </div>
                        <div className={'col-2 align-self-center text-center clickable-element'} onClick={handleCloseClick}>
                            <i className={'fa-regular fa-times '}></i>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )


}
export default TrialEnding;