import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { selectExerciseGroups, selectLibraryLoading } from "../../store/exercise-library/exerciseLibrarySelector";
import React, { useEffect, useState } from "react";
import { createGroup, fetchExerciseGroups } from "../../store/exercise-library/exerciseLibraryReducer";
import _ from "lodash";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import Modal from "react-bootstrap/Modal";
import * as Yup from "yup";
import { ErrorMessage, Field, Form, Formik } from "formik";
import ExerciseGroupListItem from "../../components/exercise-library/ExerciseGroupListItem";
import { useTranslation } from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {selectWorkoutSession} from "../../store/workout-prescription/workoutPrescriptionSelector";

const ExerciseLibraryGroups = () => {
    const { t } = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {sessionId} = useParams();
    const loading = useSelector(selectLibraryLoading);
    const groups = useSelector(selectExerciseGroups);
    const [showCreateGroup, setShowCreateGroup] = useState(false);
    const [searchTerm, setSearchTerm] = useState("");
    const session = useSelector(selectWorkoutSession)

    useComponentTranslations('exerciseLibrary', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        if (sessionId) {
            navigate(`/user/client/${session.idAluno}/workout/routine/${session.idRoutine}/session/${session.id}/exercise-list`);
        } else
            navigate("/user/exercise-library");
    };

    const handleCreateGroup = () => {
        setShowCreateGroup(prevState => !prevState);
    };

    const initialValues = { name: '' };

    const validationSchema = Yup.object({
        name: Yup.string()
            .required(t("exerciseLibrary:groupNameRequired"))
            .test('unique', t("exerciseLibrary:groupExists"), function (value) {
                if (!value) return true;
                return !groups.some(group => group.name?.toLowerCase() === value.toLowerCase());
            }),
    });

    const onSubmit = (values) => {
        dispatch(createGroup(values));
    };

    useEffect(() => {
        dispatch(fetchExerciseGroups());
    }, [dispatch]);

    useEffect(() => {
        if (!loading) {
            setShowCreateGroup(false);
        }
    }, [loading]);

    const normalizeString = (str) => {
        return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
    };

    const filteredGroups = groups?.filter(group =>
        normalizeString(group.nome).includes(normalizeString(searchTerm))
    );

    return (
        <Page title={t("exerciseLibrary:muscleGroups")} goBackLink={handleGoBack} pb={"pb-2"} loading={loading}>
            <div className="row justify-content-center">
                <div className="col-12">
                    <div className="card card-body border-0">
                        <div className="row justify-content-end">
                            <div className="col-12">
                                <CardButtonAdd text={t("exerciseLibrary:createMuscleGroup")} handleClick={handleCreateGroup} />
                            </div>
                            <div className="col-12 mt-3">
                                <input
                                    type="search"
                                    placeholder={t("exerciseLibrary:searchGroups")}
                                    className="form-control"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                            <div className="col-12 mt-3">
                                <ul className="list-unstyled">
                                    {_.map(filteredGroups, (group) => (
                                        <ExerciseGroupListItem key={group.id} group={group} />
                                    ))}
                                </ul>
                                <Modal show={showCreateGroup} centered onHide={handleCreateGroup}>
                                    <Modal.Body>
                                        <div className="row justify-content-between">
                                            <div className="col-auto">
                                                <span className="fw-semibold">{t("exerciseLibrary:createNewGroupTitle")}</span>
                                            </div>
                                            <div className="col-auto clickable-element" onClick={handleCreateGroup}>
                                                <span><i className="fa-regular fa-times"></i></span>
                                            </div>
                                            <div className="col-12 mt-3">
                                                <Formik
                                                    initialValues={initialValues}
                                                    validationSchema={validationSchema}
                                                    onSubmit={onSubmit}
                                                >
                                                    {formik => (
                                                        <Form>
                                                            <div className="mb-3">
                                                                <label htmlFor="name" className="form-label fw-semibold">
                                                                    {t("exerciseLibrary:groupName")}
                                                                </label>
                                                                <Field
                                                                    type="text"
                                                                    id="name"
                                                                    name="name"
                                                                    className={`form-control ${formik.errors.name && formik.touched.name ? 'is-invalid' : ''}`}
                                                                />
                                                                <ErrorMessage name="name">
                                                                    {msg => <div className="invalid-feedback">{msg}</div>}
                                                                </ErrorMessage>
                                                            </div>
                                                            <div className="d-grid">
                                                                <button type="submit" className="btn btn-primary">{t("exerciseLibrary:save")}</button>
                                                            </div>
                                                        </Form>
                                                    )}
                                                </Formik>
                                            </div>
                                        </div>
                                    </Modal.Body>
                                </Modal>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </Page>
    );
};

export default ExerciseLibraryGroups;
