import {apiUrl as url, getToken} from "../api";
import axios from "axios";

const apiUrl = url + "/v2"
export const fetchClientGroupsAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/client-group/count`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 20000
    })
}

