import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import useComponentTranslations from '../../utils/translation/useComponentTranslations';
import enUS from './locales/en-us.json';
import ptBR from './locales/pt-br.json';
import esES from './locales/es-es.json';
import ptPT from './locales/pt-pt.json';
import {useSelector} from 'react-redux';
import {selectUser} from '../../store/user/userSelector';


const WalletCardNotRegistered = ({handleGoToWallet}) => {
    const {t} = useTranslation();
    const user = useSelector(selectUser);
    useComponentTranslations(
        'wallet',
        {'en-US': enUS, 'pt-BR': ptBR, 'es-ES': esES, 'pt-PT': ptPT}
    );

    const slides = [1, 2, 3].map(i =>
        require(`../../assets/img/wallet/wallet-slide-${i}-${user.language}.png`)
    );

    const [activeIndex, setActiveIndex] = useState(0);
    useEffect(() => {
        const timer = setInterval(() => {
            setActiveIndex(i => (i + 1) % slides.length);
        }, 5000);

        return () => clearInterval(timer);
    }, [slides.length]);
    return (
        <div className="row pt-2 justify-content-center">
            <div className="col-12">
                <img
                    onClick={handleGoToWallet}
                    src={slides[activeIndex]}
                    className="img-fluid clickable-element"
                    alt={`slide ${activeIndex + 1}`}
                />
            </div>
            <div className="col-12 pt-2 text-center">
                {slides.map((_, idx) => (
                    <span
                        key={idx}
                        onClick={() => setActiveIndex(idx)}
                        style={{
                            display: 'inline-block',
                            width: 8,
                            height: 8,
                            margin: '0 6px',
                            borderRadius: '50%',
                            backgroundColor: idx === activeIndex ? '#172331' : '#ccc',
                            cursor: 'pointer'
                        }}
                    />
                ))}
            </div>
            <div className="col-12 pt-4">
                <div className="d-grid">
                    <button
                        className="btn btn-primary"
                        onClick={handleGoToWallet}
                    >
                        {t('wallet:signup')}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default WalletCardNotRegistered;
