import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {
    selectTransaction, selectTransactionLoading
} from "../../store/subscription/subscriptionSelector";
import {fetchTransaction} from "../../store/subscription/subscriptionReducer";
import LoadingBlock from "../../components/loader/LoadingBlock";
import Spinner from "../../components/loader/Spinner";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionPaymentProcessing = () => {
    const {t} = useTranslation();
    const {transactionId} = useParams();
    const transaction = useSelector(selectTransaction);
    const transactionLoading = useSelector(selectTransactionLoading);
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const [silentFetch, setSilentFetch] = useState(false);
    const [waitingFetch, setWaitingFetch] = useState(true);
    useComponentTranslations('subscriptionPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        const timer = setTimeout(() => {
            dispatch(fetchTransaction(transactionId));
            setWaitingFetch(false);
        }, 3000);
        return () => clearTimeout(timer);
    }, [transactionId, dispatch]);

    useEffect(() => {
        if (waitingFetch || transaction?.status === "succeeded") return;
        if (waitingFetch || transaction?.status === "failed") return;
        const iv = setInterval(() => {
            setSilentFetch(true);
            dispatch(fetchTransaction(transactionId));
        }, 5000);
        return () => clearInterval(iv);
    }, [waitingFetch, transaction?.status, transactionId, dispatch]);

    useEffect(() => {
        if (!waitingFetch && transaction?.status === "succeeded") {
            navigate(`/subscription/purchase/success`);
        }
    }, [waitingFetch, transaction?.status, navigate, transaction]);


    const showLoader = waitingFetch || (transactionLoading && !silentFetch);

    if (showLoader) {
        return (
            <Page showGoBack={false} mt="mt-n4">
                <div className="card card-body border-0">
                    <LoadingBlock/>
                </div>
            </Page>
        );
    }

    return (
        <Page showGoBack={false} mt="mt-n4">
            <div className="card card-body border-0">
                <div className="row justify-content-center mt-4">
                    <div className="col-12 text-center mt-2 mb-2">
                        <Spinner/>
                    </div>
                    <div className="col-12 text-center mt-4">
                        <span className="fw-semibold fs-5">{t("subscriptionPage:processingPaymentMessage")}</span>
                    </div>
                </div>
            </div>
        </Page>
    );
};

export default SubscriptionPaymentProcessing;
