import {buildClientRoute} from "./clientRoutes";

const appendOptionalSegment = (baseRoute, value) =>
    value !== undefined && value !== null && value !== ""
        ? `${baseRoute}/${value}`
        : baseRoute;

export const buildClientEvaluationHomeRoute = (clientId) => `/user/client/evaluation/${clientId}`;

