import {useMemo} from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const TYPE_LABEL_BY_ID = {
    0: "repsWeight",
    1: "repsWeightTime",
    2: "repsTime",
    3: "running",
    4: "repsWeight",
    5: "obs",
    7: "timeInclination",
    8: "cadence"
};

const hasValue = (value) => `${value ?? ""}`.trim() !== "";

const getSerieFieldRows = (serie, t) => {
    const rows = [];

    if ((serie.tipo === 0 || serie.tipo === 1 || serie.tipo === 2 || serie.tipo === 4) && hasValue(serie.repeticao)) {
        rows.push({label: t("workoutPresetComponent:serieRep"), value: serie.repeticao});
    }
    if ((serie.tipo === 0 || serie.tipo === 1 || serie.tipo === 4) && hasValue(serie.carga)) {
        rows.push({label: t("workoutPresetComponent:weight"), value: serie.carga});
    }
    if ((serie.tipo === 1 || serie.tipo === 2 || serie.tipo === 3 || serie.tipo === 7) && hasValue(serie.tempo)) {
        rows.push({label: t("workoutPresetComponent:time"), value: serie.tempo});
    }
    if (serie.tipo === 7 && hasValue(serie.inclinacao)) {
        rows.push({label: t("workoutPresetComponent:inclination"), value: serie.inclinacao});
    }
    if (serie.tipo === 3 && hasValue(serie.velocidade)) {
        rows.push({label: t("workoutPresetComponent:speed"), value: serie.velocidade});
    }
    if (serie.tipo === 3 && hasValue(serie.distancia)) {
        rows.push({label: t("workoutPresetComponent:distance"), value: serie.distancia});
    }
    if (serie.tipo === 3 && hasValue(serie.pace)) {
        rows.push({label: t("workoutPresetComponent:pace"), value: serie.pace});
    }
    if (serie.tipo === 8 && hasValue(serie.cadencia)) {
        rows.push({label: t("workoutPresetComponent:cadence"), value: serie.cadencia});
    }
    if (Number(serie.intervalo) > 0) {
        rows.push({label: t("workoutPresetComponent:interval"), value: serie.intervalo});
    }

    return rows;
};

const WorkoutPresetPreviewContent = ({
    preset,
    isMobileSheet = false,
    primaryLabel,
    secondaryLabel,
    deleteLabel,
    onPrimary,
    onSecondary,
    onDeleteClick,
    disabled = false,
    canDelete = false
}) => {
    const {t} = useTranslation();

    useComponentTranslations("workoutPresetComponent", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const normalizedSeries = useMemo(
        () => (preset?.series || []).filter((serie) => Number(serie.tipo) !== 6),
        [preset]
    );
    const showDeleteAction = Boolean(canDelete && onDeleteClick);

    return (
        <div className="d-flex flex-column flex-grow-1">
            <div className="flex-grow-1 overflow-y-auto overflow-x-hidden">
                <div className="mb-3">
                    <span className={`fw-semibold text-dark mb-0 ${isMobileSheet ? "fs-3" : "fs-5"}`}>
                        {preset?.name}
                    </span>
                </div>

                <div className="d-grid gap-3">
                    {normalizedSeries.map((serie, index) => {
                        if (Number(serie.tipo) === 5) {
                            return (
                                <div key={`${preset?.id || "preset"}-obs-${index}`} className="card border bg-white shadow-none">
                                    <div className="card-body">
                                        <span className="fw-semibold d-block mb-2">{t("workoutPresetComponent:obs")}</span>
                                        <span className="text-secondary d-block">
                                            {hasValue(serie.obs) ? serie.obs : "-"}
                                        </span>
                                    </div>
                                </div>
                            );
                        }

                        const fieldRows = getSerieFieldRows(serie, t);
                        const typeLabelKey = TYPE_LABEL_BY_ID[Number(serie.tipo)] || TYPE_LABEL_BY_ID[0];

                        return (
                            <div key={`${preset?.id || "preset"}-serie-${index}`} className="card border bg-white shadow-none">
                                <div className="card-body">
                                    <span className="fw-semibold d-block mb-3">
                                        {t(`workoutPresetComponent:${typeLabelKey}`)}
                                    </span>

                                    <div className="d-grid gap-2">
                                        {fieldRows.map((row) => (
                                            <div key={`${row.label}-${row.value}`}>
                                                <span className="fw-semibold me-1">{row.label}</span>
                                                <span className="text-secondary">{row.value}</span>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div className="mt-auto pt-3">
                <div className="d-grid gap-2">
                    <button
                        type="button"
                        className="btn btn-primary w-100"
                        disabled={disabled}
                        onClick={onPrimary}
                    >
                        {primaryLabel || t("workoutPresetComponent:addPreset")}
                    </button>
                    <button
                        type="button"
                        className="btn btn-outline-primary w-100"
                        disabled={disabled}
                        onClick={onSecondary}
                    >
                        {secondaryLabel || t("workoutPresetComponent:back")}
                    </button>
                </div>
                {showDeleteAction && (
                    <button
                        type="button"
                        className="btn btn-link text-danger text-decoration-none fw-semibold w-100 mt-2"
                        disabled={disabled}
                        onClick={onDeleteClick}
                    >
                        {deleteLabel || t("workoutPresetComponent:deletePreset")}
                    </button>
                )}
            </div>
        </div>
    );
};

export default WorkoutPresetPreviewContent;
