import {useState} from "react";
import Modal from "react-bootstrap/Modal";

const WorkoutYoutube = ({exercise, showSeries}) => {
    const [show, setShow] = useState(false);
    const handleModalClick = ()=>{
        setShow(prevShow => !prevShow);
    }
    return (
        <>
            <div
                className={`col-4 text-center position-relative clickable-element ${showSeries? 'ps-0': ''} align-self-stretch`}
                onClick={handleModalClick}
                style={{ display: 'flex', alignItems: 'stretch', flex: '1 1 0%' ,maxHeight:  '180px' }}>
                <div style={{ position: 'relative', flexGrow: 1, overflow: 'hidden', height: '100%' }}>
                    <img src={`https://img.youtube.com/vi/${exercise.urlMedia}/0.jpg`} alt="" className={'rounded-1'} style={{ objectFit: 'cover', objectPosition: 'center', height: '100%', width: '100%' }} />
                    <div className="position-absolute" style={{ top: '50%', left: '50%', transform: 'translate(-50%, -50%)' }}>
                        <i className={'fa-duotone fa-circle-play fa-2xl text-default'} style={{"--fa-secondary-color": "#fff"}}></i>
                    </div>
                </div>
            </div>
            <Modal show={show} centered onHide={handleModalClick}  >
                <Modal.Body >
                    <div className={'row justify-content-center d-block'}>
                        <div className={'col-auto'}>
                            <div className="embed-responsive">
                                <iframe title={exercise.name} className="embed-responsive-item"
                                        src={`https://www.youtube.com/embed/${exercise.urlMedia}?rel=0`}
                                        allowFullScreen></iframe>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    );
}
export default WorkoutYoutube;