const TEXTY_INPUT_RE = /^(text|search|url|tel|password)$/i;


export const sanitizeInput = (str) => {
    const normalized = str.normalize('NFC');
    return normalized.replace(/\p{C}/gu, (char) => {
        if (char === '\n' || char === '\r') {
            return char;
        }
        return '';
    });
};

function canUseSelectionAPIs(el) {
    return (
        el instanceof HTMLTextAreaElement ||
        (el instanceof HTMLInputElement && TEXTY_INPUT_RE.test(el.type || "text"))
    );
}

export const insertSanitized = (el, text) => {
    // 1) Preferred path: textareas & "texty" inputs
    if (canUseSelectionAPIs(el)) {
        try {
            const value = el.value ?? "";
            let start = value.length;
            let end = value.length;
            // Access inside try{} because Safari can throw on selectionStart reads in edge cases
            if (typeof el.selectionStart === "number" && typeof el.selectionEnd === "number") {
                start = el.selectionStart;
                end = el.selectionEnd;
            }
            if (typeof el.setRangeText === "function") {
                try {
                    el.setRangeText(text, start, end, "end");
                } catch {
                    // Fallback splice if setRangeText throws
                    el.value = value.slice(0, start) + text + value.slice(end);
                    el.setSelectionRange?.(start + text.length, start + text.length);
                }
            } else {
                // Old browsers: manual splice
                el.value = value.slice(0, start) + text + value.slice(end);
                el.setSelectionRange?.(start + text.length, start + text.length);
            }
            el.dispatchEvent(new Event("input", { bubbles: true }));
            return true;
        } catch {
            // If anything above threw, fall through to the non-selection path
        }
    }

    // 2) Unsupported types (email/number/date/etc.) — avoid selection APIs entirely.
    // Try to let the browser handle caret via execCommand('insertText').
    try {
        el.focus?.();
        const ok =
            typeof document.execCommand === "function" &&
            document.execCommand("insertText", false, text);
        if (ok) return true;
    } catch {
        // ignore and fall through
    }

    // 3) Last resort: append to end (we can’t safely know the caret)
    if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) {
        el.value = (el.value ?? "") + text;
        el.dispatchEvent(new Event("input", { bubbles: true }));
        return true;
    }

    // 4) contentEditable
    const sel = window.getSelection?.();
    if (sel && sel.rangeCount) {
        const range = sel.getRangeAt(0);
        range.deleteContents();
        range.insertNode(document.createTextNode(text));
        range.collapse(false);
        return true;
    }

    return false;
}

