import Modal from "react-bootstrap/Modal";
import LoadingBlock from "../loader/LoadingBlock";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import {handleSendWhatsApp} from "../../utils/handlers/handler";
import InfoCard from "../info/InfoCard";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading} from "../../store/client/clientSelector";
import {resetPassword} from "../../store/client/clientReducer";
import {addToast} from "../../store/toast/toastReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const ClientLoginInformation = ({client, handleShowLoginInfo, showLoginInfo}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const loading = useSelector(isClientsLoading)
    useComponentTranslations('client', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const message = `${t("client:useThisInfo")}\n*${t("client:login")}:* ${client?.mail}\n*${t("client:password")}:* ${client?.senha}\n${t("client:downloadTheAppAt")} https://www.mfitpersonal.com.br/download`;

    const handleResetPassword = () => {
        if (client?.id)
            dispatch(resetPassword(client.id))
    }
    const handleCopyInfo = () => {
        navigator.clipboard.writeText(message)
            .then(() => dispatch(addToast(
                {
                    type: "success",
                    message: `${t("client:copied")}`,
                    title: `${t("client:allDone")}`
                }
            )))
            .catch(err => console.error('Erro ao copiar informações: ', err));
    };
    return (
        <>
            <Modal show={showLoginInfo} centered onHide={handleShowLoginInfo}>
                <Modal.Body>
                    {
                        loading &&
                        <LoadingBlock height={"360px"}/>
                    }
                    {
                        !loading && client.senha &&
                        <div className={'row justify-content-center'}>
                            <div className={'col-4 text-center '}>
                                <RoundedIcon icon={"fa-paper-plane"} size={"lg"}/>
                            </div>
                            <div className={'col-12 text-center mt-3'}>
                                <span className={"fw-semibold"}>{t("client:sendThisInfo")}</span>
                            </div>
                            <div className={'col-12 text-center mt-3'}>
                                <div className={'card card-body bg-secondary-subtle border-0 pb-2'}>
                                    <div className={'row justify-content-center'}>
                                        <div className={'col-12'}>
                                            <span className={"d-block"}><span className={"fw-semibold"}>{t("client:login")}:</span> {client.mail}</span>
                                            <span className={"d-block"}><span
                                                className={"fw-semibold"}>{t("client:password")}:</span> {client.senha}</span>
                                        </div>
                                        <div className={'col-12 '}>
                                            <button className={'btn btn-link fw-semibold '} onClick={handleCopyInfo}>{t("client:copy")}</button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className={'col-12  mt-3'}>
                                <div className={"d-grid"}>
                                    <button className={"btn btn-success text-white"} onClick={() => handleSendWhatsApp(client.telefone, message)}><i
                                        className={"fa-brands fa-whatsapp"}></i> {t("client:shareOnWhatsapp")}
                                    </button>
                                </div>
                                <div className={"d-grid mt-2"}>
                                    <button className={"btn btn-outline-primary  "} onClick={handleShowLoginInfo}>
                                        {t("client:close")}
                                    </button>
                                </div>
                            </div>
                        </div>
                    }
                    {
                        !loading && !client.senha &&
                        <div className={'row justify-content-center'}>
                            <div className={'col-4 text-center '}>
                                <RoundedIcon icon={"fa-check"} size={"lg"}/>
                            </div>
                            <div className={'col-12 text-center mt-3'}>
                                <span className={"fw-semibold"}>{t("client:passwordChanged")}</span>
                            </div>
                            <div className={'col-12 text-center mt-3'}>
                                <span>{t("client:passwordChangedMessage")}</span>
                            </div>
                            <div className={'col-12  mt-3'}>
                                <InfoCard title={t("client:headsUp")}
                                          message1={t("client:passwordChangedWarning")}/>
                                <div className={"d-grid mt-2"}>
                                    <button className={"btn btn-primary"} onClick={handleResetPassword}>
                                        {t("client:resetPassword")}
                                    </button>
                                </div>
                            </div>
                        </div>
                    }
                </Modal.Body>
            </Modal>

        </>
    )
}

export default ClientLoginInformation;