import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Page from "../../components/page/Page";
import PushCreateCard from "../../components/push/PushCreateCard";


const PushCreate = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    useComponentTranslations('pushPage', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handlePushCreateClick = (type) => {
        navigate(`/user/push/create/${type}`)
    }

    return (
        <Page title={t(`pushPage:createNotification`)}>
            <div className={'card card-body gap-2'}>
                <PushCreateCard
                    handleClick={() => handlePushCreateClick("now")}
                    icon={"fa-regular fa-bell"}
                    text={t(`pushPage:sendNow`)}
                    subtext={t(`pushPage:sendNowDesc`)}
                />

                <PushCreateCard
                    handleClick={() => handlePushCreateClick("scheduled")}
                    icon={"fa-regular fa-calendar-lines-pen"}
                    text={t(`pushPage:schedule`)}
                    subtext={t(`pushPage:scheduleDesc`)}
                />

                <PushCreateCard
                    handleClick={() => handlePushCreateClick("recurring")}
                    icon={"fa-regular fa-calendar-clock "}
                    text={t(`pushPage:recurring`)}
                    subtext={t(`pushPage:recurringDesc`)}
                />
            </div>
        </Page>
    )
}
export default PushCreate;