import EmptySet from "../../components/empty-set/EmptySet";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import React, {useEffect} from "react";
import {clearAllOnline, getAllOnline} from "../../store/online-evaluation/evaluationOnlineReducer";
import Page from "../../components/page/Page";
import {fetchClient} from "../../store/client/clientReducer";
import {getLoading, getOnlineList} from "../../store/online-evaluation/evaluationOnlineSelector";
import OnlineEvaluationDeletedCard from "../../components/online-evaluation/OnlineEvaluationDeletedCard";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {buildOnlineEvaluationsRoute} from "../../utils/client/evaluationRoutes";

const OnlineEvaluationDeleted = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id} = useParams();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const onlineList = useSelector(getOnlineList);
    const {t} = useTranslation();
    useComponentTranslations('evaluationOnline', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate(buildOnlineEvaluationsRoute(id, "1"));
    };

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(clearAllOnline());
        dispatch(getAllOnline({clientId: id, status: 1}));
    }, [dispatch, id]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBack}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"}>
                <div className={"py-2"}>
                    <div className={"card card-body border-0"}>
                        <span className={"pb-2 fw-semibold"}>{t("evaluationOnline:deletedEvaluation")}</span>
                        {loading || loadingClient ? (
                            <div className="text-center mt-4">
                                <LoadingBlock/>
                            </div>
                        ) : (
                            <>
                                {(!onlineList || onlineList.length === 0) &&
                                    <EmptySet
                                        icon={"fa-regular fa-folder-open"}
                                        message={t("evaluationOnline:noDeletedEvaluations")}
                                    />
                                }
                            </>
                        )}
                        {onlineList && onlineList.length > 0 && (
                            <div className={"px-2"}>
                                {onlineList.map((evaluation) => (
                                    <OnlineEvaluationDeletedCard
                                        key={evaluation.id}
                                        title={t("evaluationOnline:onlineEvaluation")}
                                        evaluation={evaluation}
                                    />
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </Page>
        </>
    )
}

export default OnlineEvaluationDeleted;
