import {useCallback, useEffect, useMemo, useState} from "react";

export const WORKOUT_PRESET_ITEMS_PER_PAGE = 5;
export const WORKOUT_PRESET_PAGES_TO_SHOW = 5;

const sortByName = (presets = []) => [...presets].sort((a, b) => (a.name || "").localeCompare(b.name || ""));
const toSortableId = (id) => {
    const numericId = Number(id);
    return Number.isFinite(numericId) ? numericId : Number.MAX_SAFE_INTEGER;
};
const sortSystemPresets = (presets = []) => [...presets].sort((a, b) => {
    const idDiff = toSortableId(a.id) - toSortableId(b.id);
    return idDiff || (a.name || "").localeCompare(b.name || "");
});

export const normalizePresetSearchValue = (value) => {
    return (value ?? "")
        .toString()
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^\p{L}\p{N}\s]/gu, " ")
        .replace(/\s+/g, " ")
        .trim();
};

const paginate = (items, page, itemsPerPage) => {
    const startIndex = (page - 1) * itemsPerPage;
    return items.slice(startIndex, startIndex + itemsPerPage);
};

const useWorkoutPresetSections = (presets = [], itemsPerPage = WORKOUT_PRESET_ITEMS_PER_PAGE) => {
    const [searchQuery, setSearchQuery] = useState("");
    const [userPage, setUserPage] = useState(1);
    const [systemPage, setSystemPage] = useState(1);

    const normalizeSearchValue = useCallback(normalizePresetSearchValue, []);
    const normalizedQuery = useMemo(() => normalizeSearchValue(searchQuery), [normalizeSearchValue, searchQuery]);

    const filteredUserPresets = useMemo(() => {
        const userPresets = sortByName(presets.filter((preset) => Number(preset.userId) !== 0));

        if (!normalizedQuery) {
            return userPresets;
        }

        return userPresets.filter((preset) => normalizeSearchValue(preset.name).includes(normalizedQuery));
    }, [normalizeSearchValue, normalizedQuery, presets]);

    const filteredSystemPresets = useMemo(() => {
        const systemPresets = sortSystemPresets(presets.filter((preset) => Number(preset.userId) === 0));

        if (!normalizedQuery) {
            return systemPresets;
        }

        return systemPresets.filter((preset) => normalizeSearchValue(preset.name).includes(normalizedQuery));
    }, [normalizeSearchValue, normalizedQuery, presets]);

    useEffect(() => {
        setUserPage(1);
        setSystemPage(1);
    }, [searchQuery]);

    useEffect(() => {
        const totalPages = Math.max(1, Math.ceil(filteredUserPresets.length / itemsPerPage));
        if (userPage > totalPages) {
            setUserPage(totalPages);
        }
    }, [filteredUserPresets.length, itemsPerPage, userPage]);

    useEffect(() => {
        const totalPages = Math.max(1, Math.ceil(filteredSystemPresets.length / itemsPerPage));
        if (systemPage > totalPages) {
            setSystemPage(totalPages);
        }
    }, [filteredSystemPresets.length, itemsPerPage, systemPage]);

    const paginatedUserPresets = useMemo(
        () => paginate(filteredUserPresets, userPage, itemsPerPage),
        [filteredUserPresets, itemsPerPage, userPage]
    );

    const paginatedSystemPresets = useMemo(
        () => paginate(filteredSystemPresets, systemPage, itemsPerPage),
        [filteredSystemPresets, itemsPerPage, systemPage]
    );

    return {
        searchQuery,
        setSearchQuery,
        normalizedQuery,
        filteredUserPresets,
        filteredSystemPresets,
        paginatedUserPresets,
        paginatedSystemPresets,
        userPage,
        setUserPage,
        systemPage,
        setSystemPage,
        itemsPerPage,
        pagesToShow: WORKOUT_PRESET_PAGES_TO_SHOW
    };
};

export default useWorkoutPresetSections;
