import {call} from 'redux-saga/effects';
import {
    changeStatusPhysicalAPI, comparePhysicalAPI,
    getAllPhysicalAPI,
    getOnePhysicalAPI, lastPhysicalAPI, savePhysicalAPI, updatePhysicalAPI
} from "../../api/evaluation-physical/physicalActions";
import {put} from 'redux-saga/effects';
import {
    changeStatus, compareBioimpedance, fetchLastBioimpedance,
    fetchOneBioimpedance, getAllBioimpedance,
    onError, saveBioimpedance,
    setAllBioimpedance, setCompareBioimpedance, setLastBioimpedance,
    setOneBioimpedance,
    setStatusChanged, setSubmitResult, updateBioimpedance
} from "./bioimpedanceReducer";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {takeLatest} from 'redux-saga/effects';
import {all} from 'redux-saga/effects';

export function* fetchOneBioimpedanceAsync(action) {
    try {
        const {id} = action.payload;
        const response = yield call(getOnePhysicalAPI, id);
        yield put(setOneBioimpedance(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchOneBioimpedance() {
    yield takeLatest(fetchOneBioimpedance.type, fetchOneBioimpedanceAsync);
}

export function* fetchAllBioimpedanceAsync(action) {
    try {
        const {clientId, status, type} = action.payload;
        const response = yield call(getAllPhysicalAPI, clientId, status, type);
        yield put(setAllBioimpedance(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}
export function* onFetchAllBioimpedance() {
    yield takeLatest(getAllBioimpedance.type, fetchAllBioimpedanceAsync);
}

export function* changeStatusBioimpedanceAsync(action) {
    try {
        const {id, status} = action.payload;
        const response = yield call(changeStatusPhysicalAPI, id, status);
        yield put(setStatusChanged({id, status}));
        yield put(setSubmitResult({
            action: status === 1 ? "delete" : "recover",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? null,
            entityId: response?.data?.id ?? id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onChangeStatusPhysical() {
    yield takeLatest(changeStatus.type, changeStatusBioimpedanceAsync);
}

export function* saveBioimpedanceAsync(action) {
    try {
        const response = yield call(savePhysicalAPI, action.payload);
        yield put(setOneBioimpedance(response.data));
        yield put(setLastBioimpedance({
            evaluation: response.data,
            clientId: action.meta?.clientId ?? action.payload?.id_aluno ?? null
        }));
        yield put(setSubmitResult({
            action: "create",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? action.payload?.id_aluno ?? null,
            entityId: response.data?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onSaveBioimpedance() {
    yield takeLatest(saveBioimpedance.type, saveBioimpedanceAsync);
}

export function* updateBioimpedanceAsync(action) {
    try {
        const response = yield call(updatePhysicalAPI, action.payload);
        yield put(setOneBioimpedance(response.data));
        yield put(setSubmitResult({
            action: "update",
            flow: action.meta?.flow ?? null,
            clientId: action.meta?.clientId ?? action.payload?.id_aluno ?? null,
            entityId: response.data?.id ?? action.payload?.id
        }));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onUpdateBioimpedance() {
    yield takeLatest(updateBioimpedance.type, updateBioimpedanceAsync);
}

export function* compareBioimpedanceAsync(action) {
    try {
        const {ids} = action.payload;
        const response = yield call(comparePhysicalAPI, ids);
        yield put(setCompareBioimpedance(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onCompareBioimpedance() {
    yield takeLatest(compareBioimpedance.type, compareBioimpedanceAsync);
}

export function* fetchLastBioimpedanceAsync(action) {
    try {
        const clientId = action.payload?.clientId ?? action.payload;
        const response = yield call(lastPhysicalAPI, clientId);
        yield put(setLastBioimpedance({evaluation: response.data, clientId}));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchLastBioimpedance() {
    yield takeLatest(fetchLastBioimpedance.type, fetchLastBioimpedanceAsync);
}

export function* bioimpedanceSaga() {
    yield all ([
        call(onFetchOneBioimpedance),
        call(onFetchAllBioimpedance),
        call(onChangeStatusPhysical),
        call(onSaveBioimpedance),
        call(onUpdateBioimpedance),
        call(onCompareBioimpedance),
        call(onFetchLastBioimpedance)
    ])
}
