import React, { useEffect } from 'react';
import {useSelector} from "react-redux";
import {selectUser} from "../../store/user/userSelector";

const WootricWidget = () => {
    const user = useSelector(selectUser)

    useEffect(() => {
        const createdAtSeconds = Math.floor(new Date(user.createdAt).getTime() / 1000);

        window.wootricSettings = {
            email: `${user.mail}`,
            external_id: `${user.id}`,
            account_token: 'NPS-3fe72b82',
            ...(Number.isFinite(createdAtSeconds) ? { created_at: createdAtSeconds } : {}),
        };

        const script = document.createElement('script');
        script.type = 'text/javascript';
        script.src = 'https://cdn.wootric.com/wootric-sdk.js';
        script.async = true;


        script.onload = () => {
            if (window.wootric) {
                window.wootric('run');
            }
        };

        document.body.appendChild(script);

        return () => {
            document.body.removeChild(script);
        };
    }, [user]);

    return <div id="wootric-container"></div>;
};

export default WootricWidget;
