import EmptySet from "../../components/empty-set/EmptySet";
import _ from "lodash";
import FeedbackCard from "../../components/feedbacks/FeedbackCard";
import Pagination from "../../components/pagination/Pagination";
import Modal from "react-bootstrap/Modal";
import React, {useEffect, useState} from "react";
import {useTranslation} from "react-i18next";
import {useDispatch, useSelector} from "react-redux";
import {isFeedbackLoading, selectFeedbacks} from "../../store/feedback/feedbackSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {fetchAllUnreadFeedbacks, resolveAllFeedbacks} from "../../store/feedback/feedbackReducer";
import {getFeedbackIntensity} from "../../utils/workout/Workout";
import FeedbackFilterModal from "../../components/feedbacks/FeedbackFilterModal";

const FeedbackList = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const feedbacks = useSelector(selectFeedbacks)
    const loading = useSelector(isFeedbackLoading)
    const [showModal, setShowModal] = useState(false)
    const [showFeedbackModal, setShowFeedbackModal] = useState(false)
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(10);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredFeedbacks, setFilteredFeedbacks] = useState([]);
    const [filters, setFilters] = useState({
        feedbackSource: [],
        intensity: [],
        comments: [],
    })
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentItems = filteredFeedbacks?.slice(indexOfFirstItem, indexOfLastItem);
    const totalItems = filteredFeedbacks?.length || 0;
    const pagesToShow = 5;
    useComponentTranslations('feedbackList', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleResolveAllClick = () => {
        setShowModal(prevState => !prevState)
    }

    const handleResolveAllConfirmationClick = () => {
        dispatch(resolveAllFeedbacks())
        handleResolveAllClick()
    }

    const handleFeedbackModal = () => {
        setShowFeedbackModal(prevState => !prevState)
    }

    const selectFeedbackType = (type) => {
        setFilters((prevState) => {
            const alreadySelected = prevState.feedbackSource.includes(type);
            return {
                ...prevState,
                feedbackSource: alreadySelected
                    ? prevState.feedbackSource.filter((item) => item !== type)
                    : [...prevState.feedbackSource, type],
            };
        });
    };

    const selectIntensity = (intensity) => {
        setFilters((prevState) => {
            const isSelected = prevState.intensity.includes(intensity);
            return {
                ...prevState,
                intensity: isSelected
                    ? prevState.intensity.filter((item) => item !== intensity)
                    : [...prevState.intensity, intensity],
            };
        })
    }

    const toggleComment = (commentType) => {
        setFilters((prevState) => {
            const alreadySelected = prevState.comments.includes(commentType);
            return {
                ...prevState,
                comments: alreadySelected
                    ? prevState.comments.filter((item) => item !== commentType)
                    : [...prevState.comments, commentType]
            }
        });
    }

    const clearFilters = () => {
        setFilters({
            feedbackSource: [],
            intensity: [],
            comments: [],
        });
    };

    const areFiltersActive = () => {
        return (
            filters.feedbackSource.length > 0 ||
            filters.intensity.length > 0 ||
            filters.comments.length > 0
        );
    };

    useEffect(() => {
        setFilteredFeedbacks(feedbacks);
    }, [feedbacks]);

    useEffect(() => {
        dispatch(fetchAllUnreadFeedbacks())
    }, [dispatch]);

    useEffect(() => {
        const totalPages = Math.ceil(totalItems / itemsPerPage);
        if (currentPage > totalPages && totalPages > 0) {
            setCurrentPage(totalPages);
        }
    }, [feedbacks, currentPage, totalItems, itemsPerPage]);

    useEffect(() => {
        let filtered = feedbacks || [];

        if (searchQuery.trim() !== "") {
            filtered = filtered.filter(feedback =>
                feedback.clientName.toLowerCase().includes(searchQuery.toLowerCase())
            );
        }

        if (filters.feedbackSource.length > 0) {
            filtered = filtered.filter(feedback =>
                filters.feedbackSource.includes(feedback.fonteFeedback)
            );
        }

        if (filters.intensity.length > 0) {
            filtered = filtered.filter(feedback =>
                filters.intensity.includes(getFeedbackIntensity(feedback.borgNota))
            );
        }

        if (filters.comments.length > 0) {
            filtered = filtered.filter(feedback => {
                const hasComment = feedback.feedback && feedback.feedback.trim() !== "";
                if (filters.comments.includes("with") && filters.comments.includes("without")) {
                    return true;
                }
                if (filters.comments.includes("with")) {
                    return hasComment;
                }
                if (filters.comments.includes("without")) {
                    return !hasComment;
                }
                return false;
            });
        }

        setFilteredFeedbacks(filtered);
    }, [feedbacks, searchQuery, filters]);

    return (
        <>
            <>
                {
                    feedbacks && feedbacks.length === 0 && !loading &&
                    <div className={'row'}>
                        <div className={'col-12 pt-4'}>
                            <div className={'card card-body border-0'}>
                                <EmptySet icon={"fa-comments"} message={t("feedbackList:noFeedbacks")}/>
                            </div>
                        </div>
                    </div>
                }
                {
                    feedbacks && feedbacks.length > 0 && !loading &&
                    <>
                        <div className={'row'}>
                            {
                                feedbacks.length > 1 &&
                                <div className={'col-12 pt-4'}>
                                    <div className={'d-grid'}>
                                        <button className={"btn btn-primary-lighter"}
                                                onClick={handleResolveAllClick}>{t("feedbackList:resolveAll")}
                                        </button>
                                    </div>
                                </div>
                            }
                            {
                                feedbacks.length > 5 &&
                                <div className={'d-flex mt-1 pt-1 text-center'}>
                                    <div className={"input-group mx-auto"}>
                                        <input
                                            className={'form-control bg-white'}
                                            placeholder={t("feedbackList:searchByClient")}
                                            value={searchQuery}
                                            onChange={(e) => setSearchQuery(e.target.value)}
                                        />
                                        <span className={'input-group-text bg-white'}>
                                            <i className={'fa-regular fa-magnifying-glass'}/>
                                        </span>
                                    </div>
                                    <button className={`input-group-text ms-2 ${areFiltersActive() ? "text-primary btn-feedback-primary" : "bg-white"}`}
                                            onClick={handleFeedbackModal}>
                                        <i className="fa-regular fa-sliders-simple"/>
                                    </button>
                                </div>
                            }
                        </div>
                        {
                            filteredFeedbacks && filteredFeedbacks.length === 0 && !loading &&
                            <div className={'row'}>
                                <div className={'col-12 pt-4'}>
                                    <div className={'card card-body border-0'}>
                                        <EmptySet icon={"fa-comments"} message={t("feedbackList:noFeedbacksMatching")}/>
                                    </div>
                                </div>
                            </div>
                        }
                        <div className={'row justify-content-center d-flex mt-3'}>
                            <div className={'col-12'}>
                                {
                                    _.map(currentItems, (feedback) =>
                                        <FeedbackCard key={feedback.id} feedback={feedback}/>
                                    )
                                }
                                {
                                    totalItems > itemsPerPage &&
                                    <div className={'row justify-content-center'}>
                                        <div className={'col-12'}>
                                            <Pagination
                                                currentPage={currentPage}
                                                totalItems={totalItems}
                                                itemsPerPage={itemsPerPage}
                                                onPageChange={setCurrentPage}
                                                pagesToShow={pagesToShow}
                                            />
                                        </div>
                                    </div>
                                }
                            </div>
                        </div>
                    </>
                }
            </>
            <Modal show={showModal} onHide={handleResolveAllClick} centered>
                <Modal.Body>
                    <div className={'row justify-content-center'}>
                        <div className={"col-12 text-center"}>
                            <i className={'fa-regular fa-circle-exclamation text-warning'}
                               style={{fontSize: '3rem'}}></i>
                        </div>
                        <div className={'col-12 fw-semibold text-center mt-2'}>
                            <span className={'fs-5'}>{t("feedbackList:resolveAllConfirmation")}</span>
                        </div>
                        <div className={'col-12 text-center mt-2'}>
                            <span>{t("feedbackList:actionCantBeUndone")}</span>
                        </div>
                        <div className={'col-12 d-grid mt-3'}>
                            <button className={"btn btn-primary-lighter text-white"}
                                    onClick={handleResolveAllConfirmationClick}>{t("feedbackList:yesResolveAll")}</button>
                        </div>
                        <div className={'col-12 d-grid mt-2'}>
                            <button className={"btn btn-outline-primary"}
                                    onClick={handleResolveAllClick}>{t("feedbackList:goBack")}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            <FeedbackFilterModal
                isOpen={showFeedbackModal}
                onClose={handleFeedbackModal}
                title={t("feedbackList:filters")}
                filters={filters}
                onSelectTraining={() => selectFeedbackType(0)}
                onSelectAerobic={() => selectFeedbackType(1)}
                onSelectExtraTraining={() => selectFeedbackType(2)}
                onSelectIntensity={selectIntensity}
                onToggleComment={toggleComment}
                onApply={handleFeedbackModal}
                onClear={clearFilters}
                t={t}
            />
        </>
    )
}

export default FeedbackList;