import {createSelector} from "reselect";

const workoutReducer = state => state.session;
export const isWorkoutLoading = createSelector(
    [workoutReducer],
    slice => slice.loading
)
export const selectWorkoutSession = createSelector(
    [workoutReducer],
    slice => slice.session
)
export const getPreview = createSelector(
    [workoutReducer],
    slice => slice.preview
)

