import React from 'react';
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import RoundedIcon from "../rounded-icon/RoundedIcon";

function ShareModal({ show, onClose, link, onCopy, onSend, shareTitle, sendLabel, copyLabel, closeLabel}) {

    return (
        <Modal show={show} onHide={onClose} centered>
            <ModalBody>
                <div className={"text-center mb-3"}>
                    <div className={"mb-3 d-inline-flex"}>
                        <RoundedIcon icon={"fa-paper-plane-top"} size={"lg"}/>
                    </div>
                    <p className={"fw-semibold fs-5"}>{shareTitle}</p>
                    <div className="bg-secondary-subtle rounded py-2 px-3 text-break">
                        {link}
                    </div>
                </div>
                <div className={"d-grid gap-2"}>
                    <button className={"btn btn-success text-white"} onClick={onSend}>
                        {sendLabel}
                    </button>
                    <button className={"btn btn-primary"} onClick={onCopy}>
                        {copyLabel}
                    </button>
                    <button className={"btn btn-outline-primary"} onClick={onClose}>
                        {closeLabel}
                    </button>
                </div>
            </ModalBody>
        </Modal>
    );
}

export default ShareModal;
