export const RETENTION_SUMMARY_TTL_SECONDS = 1800;
export const RETENTION_CHART_TTL_SECONDS = 1800;
export const RETENTION_CLIENTS_TTL_SECONDS = 300;

export const DEFAULT_RETENTION_SUMMARY_PERIOD = "CURRENT_MONTH";
export const DEFAULT_RETENTION_CHART_FILTERS = {
    metric: "ENGAGEMENT",
    period: "LAST_3_MONTHS"
};
export const DEFAULT_RETENTION_DASHBOARD_FILTERS = {
    status: "AT_RISK",
    search: "",
    page: 1,
    pageSize: 20
};

export const normalizeRetentionSummaryPeriod = (period) => (
    period || DEFAULT_RETENTION_SUMMARY_PERIOD
);

export const normalizeRetentionChartFilters = (filters = {}) => ({
    metric: filters.metric || DEFAULT_RETENTION_CHART_FILTERS.metric,
    period: filters.period || DEFAULT_RETENTION_CHART_FILTERS.period
});

export const normalizeRetentionClientFilters = (filters = {}) => ({
    status: filters.status || DEFAULT_RETENTION_DASHBOARD_FILTERS.status,
    search: typeof filters.search === "string" ? filters.search.trim() : DEFAULT_RETENTION_DASHBOARD_FILTERS.search,
    page: Number(filters.page) > 0 ? Number(filters.page) : DEFAULT_RETENTION_DASHBOARD_FILTERS.page,
    pageSize: Number(filters.pageSize) > 0 ? Number(filters.pageSize) : DEFAULT_RETENTION_DASHBOARD_FILTERS.pageSize
});
