import {Image} from "react-bootstrap";
import Modal from "react-bootstrap/Modal";
import {useState} from "react";
import {deleteClient} from "../../store/client/clientReducer";
import {useDispatch} from "react-redux";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from "he";

const ClientDeleteItemList = ({client}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const [showModal, setShowModal] = useState(false);

    useComponentTranslations('clientComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleDeleteClientClick = () => {
        setShowModal(prev => !prev)
    }

    const handleDeleteClient = () => {
        const data = {
            id: client.id,
            status: 2
        }
        dispatch(deleteClient(data))
    }

    if (!client)
        return null;

    return (
        <>
            <li key={client.id}
                className={'list-group-item border-0  border-bottom bg-white rounded-0 clickable-element pb-3 pt-3'}>
                <div className={'row '}>
                    <div className={'col-2 align-self-center'}>
                        <Image
                            src={client.profileUrl ?? "https://cdn.mfitpersonal.com.br/assets/user/user.jpg"}
                            className={"rounded-circle"} fluid/>
                    </div>
                    <div className={'col-7 align-self-center ps-0'}>
                        <span className={'d-block fw-semibold'}>{he.decode(client.nome)}</span>
                        <span
                            className={'d-block small'}>{client.grupo?.idUser === 0 ? t(`clientComponent:${client.grupo?.nome_i18n}`) : client.grupo?.nome}</span>
                    </div>
                    <div className={'col-3 align-self-center clickable-element text-end'}
                         onClick={handleDeleteClientClick}>
                        {
                            client.status !== 2 &&
                            <span className={'small text-danger'}>{t("clientComponent:delete")}</span>
                        }
                    </div>
                </div>
            </li>
            <Modal show={showModal} onHide={handleDeleteClientClick} centered>
                <Modal.Body>
                    <div className={'row justify-content-center'}>
                        <div className={"col-12 text-center"}>
                            <i className={'fa-regular fa-info-circle text-danger'} style={{fontSize: '4rem'}}></i>
                        </div>
                        <div className={'col-12 fw-semibold text-center mt-4'}>
                            <span className={'fs-5 '}>{t("clientComponent:wantToDelete")}</span>
                        </div>
                        <div className={'col-12   text-center mt-2'}>
                            <span>{t("clientComponent:actionCantBeUndone")}</span>
                        </div>
                        <div className={'col-12 d-grid mt-3'}>
                            <button className={"btn btn-danger text-white"} onClick={handleDeleteClient}>{t("clientComponent:yesDelete")}</button>
                        </div>
                        <div className={'col-12 d-grid mt-2'}>
                            <button className={"btn btn-outline-danger"} onClick={handleDeleteClientClick}>{t("clientComponent:goBack")}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    )
}
export default ClientDeleteItemList