import React, {useEffect, useMemo} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import moment from "moment";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import 'moment/locale/pt-br';
import {useTranslation} from "react-i18next";
import _ from "lodash";
import {getTestConfigurations} from "../../utils/neuromotors/testConfig";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {selectIsLoading, selectTestList} from "../../store/neuromotors/neuromotorsSelector";
import {fetchClient} from "../../store/client/clientReducer";
import {getAllTests} from "../../store/neuromotors/neuromotorsReducer";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import LoadingBlock from "../../components/loader/LoadingBlock";
import NeuromotorCard from "../../components/neuromotors/NeuromotorCard";
import EmptySet from "../../components/empty-set/EmptySet";
import Tabs from "../../components/tab/Tabs";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import {
    buildClientNeuromotorsRoute,
    buildNeuromotorCreateRoute,
    buildNeuromotorEditRoute,
    buildNeuromotorTestRoute
} from "../../utils/client/evaluationRoutes";
import {
    getNeuromotorPageFromType,
    hasNeuromotorTabs,
    isNeuromotorImpulseType,
    isNeuromotorResistanceType,
    resolveNeuromotorTypeForPage
} from "../../utils/neuromotors/navigation";

const NeuromotorTest = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {clientId, type: routeType, pg} = useParams();
    const {i18n} = useTranslation();
    const {t} = useTranslation();
    const selectedClient = useSelector(selectSelectedClient);
    const loadingClient = useSelector(isClientsLoading);
    const isTestsLoading = useSelector(selectIsLoading);
    const tests = useSelector(selectTestList);
    const numericType = Number(routeType);
    const page = hasNeuromotorTabs(numericType)
        ? String(pg ?? getNeuromotorPageFromType(numericType))
        : "1";
    const type = resolveNeuromotorTypeForPage(numericType, page);
    const config = useMemo(() => getTestConfigurations(t)[type], [t, type]);
    const {testTitle, valorField, extraField} = config;
    syncMomentLocale(i18n.language);
    const isResistance = isNeuromotorResistanceType(type);
    const isImpulse = isNeuromotorImpulseType(type);
    useComponentTranslations('neuromotors', {"en-US":enUS, "es-ES":esES, "pt-PT":ptPT, "pt-BR":ptBR})

    const handleChangePage = (pageName) => {
        const newType = resolveNeuromotorTypeForPage(type, pageName);
        navigate(buildNeuromotorTestRoute(newType, clientId, pageName));
    };

    const navigateToCreate = () => {
        navigate(buildNeuromotorCreateRoute(clientId, type));
    };

    const navigateToEdit = (test) => {
        navigate(buildNeuromotorEditRoute(clientId, type, test.id));
    };

    const handleGoBackNeuromotor = () => {
        navigate(buildClientNeuromotorsRoute(clientId));
    };

    useEffect(() => {
        if (!selectedClient) dispatch(fetchClient(clientId));
    }, [dispatch, clientId, selectedClient]);

    useEffect(() => {
        if (!hasNeuromotorTabs(numericType)) {
            return;
        }

        if (type !== numericType || pg !== page) {
            navigate(buildNeuromotorTestRoute(type, clientId, page), {replace: true});
        }
    }, [clientId, navigate, numericType, page, pg, type]);

    useEffect(() => {
        dispatch(getAllTests({type, clientId}));
    }, [dispatch, type, clientId]);

    let displayValueKey = typeof valorField === 'object' ? valorField.name : (valorField || "valor");
    if (!tests?.[0]?.[displayValueKey]) {
        if (tests?.[0]?.valor !== undefined) {
            displayValueKey = "valor";
        } else if (tests?.[0]?.carga !== undefined) {
            displayValueKey = "carga";
        } else if (tests?.[0]?.salto !== undefined) {
            displayValueKey = "salto";
        } else if ((tests?.[0]?.peso !== undefined)){
            displayValueKey = "peso";
        }
    }

    const valorFieldLabel = typeof valorField === 'object' ? valorField.label : "";

    let extraFieldName, extraFieldLabel;
    if (extraField) {
        extraFieldName = typeof extraField === 'object' ? extraField.name : extraField;
        extraFieldLabel = typeof extraField === 'object' ? extraField.label : "";
    }

    const showTabs = hasNeuromotorTabs(type);

    const tabProps = {};
    if (isResistance) {
        tabProps.button1Text = t("neuromotors:abdominal")
        tabProps.button2Text = t("neuromotors:arms")
    } else if (isImpulse) {
        tabProps.button1Text = t("neuromotors:horizontal")
        tabProps.button2Text = t("neuromotors:vertical")
    }

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackNeuromotor}
                className="pb-4 pt-2"
                text={`${selectedClient?.nome ?? ""} ${selectedClient?.sobrenome ?? ""}`}
                url={selectedClient?.profileUrl}
            />
            <Page contentHeader={false} loading={isTestsLoading || loadingClient}>
                {
                    showTabs && (
                        <Tabs
                            page={page}
                            mt="mt-n4"
                            buttonClick={handleChangePage}
                            {...tabProps}
                        />
                    )
                }
                <div className="row">
                    <div className="col-12">
                        <div className="card card-body border-0 gap-2">
                            <span className="fw-semibold">{testTitle}</span>
                            <CardButtonAdd text={t('neuromotors:newTest')} handleClick={navigateToCreate}/>
                            {
                                isTestsLoading &&
                                <LoadingBlock height="200px"/>
                            }
                            {
                                !isTestsLoading && tests?.length > 0 && (
                                    <>
                                        <div className="pt-3">
                                            <div className="fw-semibold">{t('neuromotors:testsPerformed')}</div>
                                        </div>
                                        {_.map(tests, (test) => {
                                            const formattedDate = moment(test.data).format("L");
                                            const displayValue = test[displayValueKey] ?? "";
                                            const fieldConfig = config.fields.find(f => f.name === displayValueKey);
                                            const unit = fieldConfig?.unit ? ` ${fieldConfig.unit}` : "";

                                            const titulo = `${valorFieldLabel ? valorFieldLabel + ": " : ""}${displayValue}${unit}`;

                                            let extraInfo = null;
                                            if (extraFieldName && test[extraFieldName] !== undefined) {
                                                const eFieldConfig = config.fields.find(f => f.name === extraFieldName);
                                                const eValue = test[extraFieldName];
                                                const eUnit = eFieldConfig?.unit ? ` ${eFieldConfig.unit}` : "";
                                                extraInfo = (
                                                    <div>
                                                        {extraFieldLabel ? `${extraFieldLabel}: ` : ""}{eValue}{eUnit}
                                                    </div>
                                                );
                                            }

                                            return (
                                                <div
                                                    key={test.id}
                                                    className="clickable-element"
                                                    onClick={() => navigateToEdit(test)}
                                                >
                                                    <NeuromotorCard
                                                        test={test}
                                                        titulo={titulo}
                                                        subtitulo={formattedDate}
                                                        extraInfo={extraInfo}
                                                    />
                                                </div>
                                            );
                                        })}
                                    </>
                                )
                            }
                            {
                                !isTestsLoading && tests?.length === 0 && (
                                    <EmptySet
                                        icon="fa-regular fa-file-lines"
                                        message={t('neuromotors:anyTestForStudent')}
                                    />
                                )
                            }
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default NeuromotorTest;
