import {isDesktop} from "react-device-detect";
import {handleSubscriptionButton} from "../../utils/handlers/handler";
import {useDispatch, useSelector} from "react-redux";
import {helpMenuSelector, userMenuSelector} from "../../store/menu/menuSelector";
import {toggleHelpMenu, toggleUserMenu} from "../../store/menu/menuReducer";
import HelpMenu from "./HelpMenu";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {selectUser} from "../../store/user/userSelector";
import {Image} from "react-bootstrap";
import {useEffect} from "react";
import {fetchUser} from "../../store/user/userReducer";
import UserMenu from "./UserMenu";
import {useNavigate} from "react-router-dom";

const NavbarMenuButton = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const helpMenu = useSelector(helpMenuSelector)
    const userMenu = useSelector(userMenuSelector);
    const user = useSelector(selectUser)
    useComponentTranslations('navBarComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleHelpMenu = () => {
        dispatch(toggleHelpMenu(!helpMenu))
    };

    const handleUserMenu = () => {
        dispatch(toggleUserMenu(!userMenu))
    };

    const style = {
        position: "absolute",
        right: (isDesktop) ? "2%" : '5%'
    }

    useEffect(() => {
        if (!user) {
            dispatch(fetchUser())
        }
    }, [user, dispatch]);

    if (!user)
        return null;

    return (
        <>
            <div className={"row justify-content-center"} style={style}>
                <div className={'col-auto align-self-center pt-2 d-print-none'}>
                    <span className="text-white text-center clickable-element"
                          style={{lineHeight: 0.5}} onClick={() => handleSubscriptionButton(navigate)}>
                        <span className="d-block pb-2 "><i className="fa-regular  fa-usd-circle fa-xl"></i></span>
                        <span className={' small'}>{t("navBarComponent:subscription")}</span>
                    </span>
                </div>
                <div className={'col-auto align-self-center pt-2 d-print-none'}>
                    <span className="text-white text-center   clickable-element"
                          style={{lineHeight: 0.5}} onClick={handleHelpMenu}>
                        <span className="d-block pb-2 "><i className="fa-regular  fa-comment-alt fa-xl"></i></span>
                           <span className={' small'}>{t("navBarComponent:help")}</span>
                    </span>
                </div>
                <div className="col-auto align-self-center d-print-none">
                    <span className="text-white text-center  clickable-element " onClick={handleUserMenu}>
                        <Image roundedCircle={true} fluid={true}
                               src={user.urlLogo === "empty" || !user.urlLogo ? "https://cdn.mfitpersonal.com.br/assets/user/user.jpg" : user.urlLogo}
                               className="mx-auto d-block"
                               style={{maxWidth: '26px'}}></Image>
                        <span className="small ">Perfil</span>
                    </span>
                </div>
            </div>
            <HelpMenu/>
            <UserMenu/>
        </>
    )
}
export default NavbarMenuButton;