import {useDispatch, useSelector} from "react-redux";
import * as Yup from "yup";
import {selectFinancesCategories} from "../../store/personal-finances/personalFinancesSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptBR from "./locales/pt-br.json";
import ptPT from "./locales/pt-pt.json";
import {useState} from "react";
import {deleteCategory, updateCategory} from "../../store/personal-finances/personalFinancesReducer";
import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import {ErrorMessage, Field, Form, Formik} from "formik";
import ChangeStatus from "../utils/change-status/ChangeStatus";

const PersonalFinancesCategories = ({category}) => {
    const {t} = useTranslation("personalFinancesComponent");
    const dispatch = useDispatch();
    const [showDelete, setShowDelete] = useState(false);
    const [showEditCategory, setShowEditCategory] = useState(false);
    const categories = useSelector(selectFinancesCategories);
    useComponentTranslations('personalFinancesComponent', {"en-US": enUS, "pt-BR": ptBR, "pt-PT": ptPT, "es-ES": esES});

    const initialValues = { id: category.id, name: category.nome };

    const validationSchema = Yup.object({
        name:Yup.string()
            .required(t("personalFinancesComponent:nameRequired"))
            .test("unique", t("personalFinancesComponent:categoryExists"), function (value){
                if(!value) return true;
                return !categories.some(
                    (c) =>
                        c.id !== category.id &&
                        c.name &&
                        c.name.toLowerCase() === value.toLowerCase()
                );
            }),
        id: Yup.mixed().required(),
    })

    const label = category.i18n
        ? t(category.i18n)
        : category.nome;

    const handleEditCategory = () => {
        if (category.idUser > 0 )
            setShowEditCategory(prevState => !prevState);
    };
    const handleShowModal = () => {
        setShowDelete(prevState => !prevState);
    };
    const handleDeleteCategory = () => {
        dispatch(deleteCategory(category.id));
    };
    const onSubmit = (values) => {
        dispatch(updateCategory(values));
    };

    return(
        <>
            <li className={`fw-semibold border-bottom ps-2 pt-3 border-subtle`}>
                <div className={"row justify-content-between"}>
                    <div className={`col-auto align-self-center ${category.idUser > 0 && "clickable-element"}`} onClick={handleEditCategory}>
                        {label}
                    </div>
                    {category.idUser > 0 && (
                        <div className={"col-auto align-self-center clickable-element"} onClick={handleShowModal}>
                            <i className={"fa-regular fa-trash-can text-danger"}/>
                        </div>
                    )}
                </div>
            </li>
            <Modal show={showEditCategory} centered onHide={handleEditCategory}>
                <ModalBody>
                    <div className={"row justify-content-between"}>
                        <div className={"col-auto"}>
                            <span className={"fw-semibold"}>{t("personalFinancesComponent:newCategory")}</span>
                        </div>
                        <div className={"col-auto clickable-element"} onClick={handleEditCategory}>
                            <span><i className={"fa-regular fa-times"}/></span>
                        </div>
                        <div className={"col-12 mt-3"}>
                            <Formik initialValues={initialValues}
                                    onSubmit={onSubmit}
                                    validationSchema={validationSchema}
                            >
                                {(formik) => (
                                        <Form>
                                            <Field type={"hidden"} id={"id"} name={"id"}/>
                                            <div className={"mb-3"}>
                                                <label htmlFor="name" className={"form-label fw-semibold"}>
                                                    {t("personalFinancesComponent:categoryName")}
                                                </label>
                                                <Field
                                                    type={"text"}
                                                    id={"name"}
                                                    name={"name"}
                                                    className={`form-control ${formik.errors.name && formik.touched.name ? "is-invalid" :""}`}
                                                />
                                                <ErrorMessage name={"name"}>
                                                    {(msg) => <div className={"invalid-feedback"}>{msg}</div>}
                                                </ErrorMessage>
                                            </div>
                                            <div className={"d-grid"}>
                                                <button type={"submit"} className={"btn btn-primary"}>
                                                    {t("personalFinancesComponent:save")}
                                                </button>
                                            </div>
                                        </Form>
                                    )
                                }
                            </Formik>
                        </div>
                    </div>
                </ModalBody>
            </Modal>
            <Modal show={showDelete} centered onHide={handleShowModal}>
                <ModalBody>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation"}
                        iconColor={"text-danger"}
                        title={t("personalFinancesComponent:areYouSure")}
                        subtitle={t("personalFinancesComponent:actionCannot")}
                    />
                    <div className={"row mt-3 justify-content-center"}>
                        <div className={"col-12"}>
                            <div className={"d-grid"}>
                                <button className={"btn btn-danger"} onClick={handleDeleteCategory}>
                                    {t("personalFinancesComponent:yesDelete")}
                                </button>
                            </div>
                            <div className={"d-grid mt-2"}>
                                <button className={"btn btn-outline-danger"} onClick={handleShowModal}>
                                    {t("personalFinancesComponent:close")}
                                </button>
                            </div>
                        </div>
                    </div>
                </ModalBody>
            </Modal>
        </>
    )
}

export default PersonalFinancesCategories;
