import {Image, Navbar} from "react-bootstrap";
import {Link, useNavigate} from "react-router-dom";

const NavBar = ({children}) => {
    const navigate = useNavigate();
    const handleGotoStart = () => {
       navigate("/user")
    }
    return (
        <Navbar bg="default" fixed="top" className="justify-content-center navbar text-white " style={{paddingTop: "1.9rem" }}>
            <div className={'row justify-content-center'}>
                <div className={'col-12'}>
                    <Link to={"/user"}>
                        <Image fluid={true} style={{height: "33px"}} onClick={handleGotoStart} className={"clickable-element"}
                               src={`https://cdn.mfitpersonal.com.br/assets/logo/logo-horizontal.svg`}/>
                    </Link>
                </div>
            </div>
            {children}
        </Navbar>
    )
}

export default NavBar;