import {useEffect, useMemo, useRef} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import {fetchClient} from "../../store/client/clientReducer";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {
    clearCurrentExtraTraining,
    clearEditExtraTraining,
    editExtraTraining,
    fetchOneExtraTraining
} from "../../store/extratraining/extraTrainingReducer";
import {
    selectCurrentExtraTraining,
    selectCurrentExtraTrainingErrorCode,
    selectCurrentExtraTrainingStatus,
    selectEditExtraTrainingLoading,
    selectEditExtraTrainingSuccess
} from "../../store/extratraining/extraTrainingSelector";
import ExtraTrainingEditorForm from "../../components/extra-training/ExtraTrainingEditorForm";
import {addToast} from "../../store/toast/toastReducer";

const NOT_FOUND_ERROR_CODES = ["extraTrainingNotFound", "clientDoesNotExist"];

const ExtraTrainingEdit = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {clientId, extraTrainingId} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const currentExtraTraining = useSelector(selectCurrentExtraTraining);
    const currentStatus = useSelector(selectCurrentExtraTrainingStatus);
    const currentErrorCode = useSelector(selectCurrentExtraTrainingErrorCode);
    const editLoading = useSelector(selectEditExtraTrainingLoading);
    const editSuccess = useSelector(selectEditExtraTrainingSuccess);
    const hasHandledNotFoundRef = useRef(false);

    useComponentTranslations("extraTrainingUser", {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR});

    useEffect(() => {
        dispatch(fetchClient(clientId));
        dispatch(fetchOneExtraTraining({id: clientId, extraTrainingId}));
        return () => dispatch(clearCurrentExtraTraining());
    }, [clientId, dispatch, extraTrainingId]);

    useEffect(() => {
        if (editSuccess) {
            navigate(`/user/client/${clientId}/extratraining`);
            dispatch(clearEditExtraTraining());
        }
    }, [clientId, dispatch, editSuccess, navigate]);

    useEffect(() => {
        const shouldRedirectAfterNotFound = currentStatus === "error" && NOT_FOUND_ERROR_CODES.includes(currentErrorCode);
        if (!shouldRedirectAfterNotFound || hasHandledNotFoundRef.current) {
            return;
        }

        hasHandledNotFoundRef.current = true;
        dispatch(addToast({
            title: t("extraTrainingUser:detailLoadErrorTitle"),
            message: t(`extraTrainingUser:errorMessages.${currentErrorCode}`, {
                defaultValue: t("extraTrainingUser:detailLoadErrorText")
            }),
            delay: 10000
        }));
        navigate(`/user/client/${clientId}/extratraining`, {replace: true});
    }, [clientId, currentErrorCode, currentStatus, dispatch, navigate, t]);

    const handleGoBackPage = () => navigate(`/user/client/${clientId}/extratraining`);
    const handleRetry = () => dispatch(fetchOneExtraTraining({id: clientId, extraTrainingId}));
    const shouldRedirectAfterNotFound = currentStatus === "error" && NOT_FOUND_ERROR_CODES.includes(currentErrorCode);
    const pageLoading = currentStatus === "idle" || currentStatus === "loading" || shouldRedirectAfterNotFound;
    const showInlineError = currentStatus === "error" && !shouldRedirectAfterNotFound;
    const detailErrorMessage = t(`extraTrainingUser:errorMessages.${currentErrorCode}`, {
        defaultValue: t("extraTrainingUser:detailLoadErrorText")
    });

    const initialValues = useMemo(() => ({
        executeAt: currentExtraTraining?.executeAt
            ? `${currentExtraTraining.executeAt.year}-${String(currentExtraTraining.executeAt.month).padStart(2, "0")}-${String(currentExtraTraining.executeAt.day).padStart(2, "0")}`
            : "",
        atividade: currentExtraTraining?.atividade || "",
        instructions: currentExtraTraining?.instructions || "",
        url: currentExtraTraining?.url ? `https://youtu.be/${currentExtraTraining.url}` : "",
        notificar: Boolean(currentExtraTraining?.notificar),
        clients: [],
        groups: []
    }), [currentExtraTraining]);

    const handleSubmit = (values) => {
        dispatch(editExtraTraining({
            id: Number(clientId),
            extraTrainingId: Number(extraTrainingId),
            formData: {
                executeAt: values.executeAt,
                atividade: values.atividade,
                instructions: values.instructions,
                url: values.url,
                notificar: values.notificar,
                timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
            }
        }));
    };

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
            />
            <Page contentHeader={false} loading={pageLoading}>
                <div className="row justify-content-center d-flex">
                    <div className="col-12">
                        <div className="card card-body border-0">
                            <span className="fw-semibold fs-5">{t("extraTrainingUser:editExtraTraining")}</span>
                            {currentStatus === "success" && (
                                <div className="mt-3">
                                    <ExtraTrainingEditorForm
                                        initialValues={initialValues}
                                        onSubmit={handleSubmit}
                                        loading={editLoading}
                                        submitLabel={t("extraTrainingUser:saveExtraTraining")}
                                        showTrainingFields={true}
                                        showRecipients={false}
                                    />
                                </div>
                            )}
                            {showInlineError && (
                                <div className="mt-3">
                                    <div className="card card-body border-danger-subtle bg-danger-subtle text-center gap-3">
                                        <div className="text-danger fs-3">
                                            <i className="fa-regular fa-circle-exclamation"/>
                                        </div>
                                        <div>
                                            <span className="fw-semibold d-block">{t("extraTrainingUser:detailLoadErrorTitle")}</span>
                                            <span className="d-block text-muted">{detailErrorMessage}</span>
                                        </div>
                                        <div className="d-grid gap-2">
                                            <button className="btn btn-primary" onClick={handleRetry}>
                                                {t("extraTrainingUser:retry")}
                                            </button>
                                            <button className="btn btn-outline-primary" onClick={handleGoBackPage}>
                                                {t("extraTrainingUser:goBack")}
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default ExtraTrainingEdit;
