import React, {useCallback, useEffect} from 'react';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useNavigate, useParams} from 'react-router-dom';
import AvatarHeader from '../../components/avatar/AvatarHeader';
import Page from '../../components/page/Page';
import {useDispatch, useSelector} from 'react-redux';
import {fetchWorkoutRoutine, updateRoutine, updateRoutineSuccess} from '../../store/workout-routine/workoutRoutineReducer';
import {selectWorkoutRoutine, selectWorkoutRoutineLoading, selectWorkoutRoutineUpdate} from '../../store/workout-routine/workoutRoutineSelector';
import LoadingBlock from '../../components/loader/LoadingBlock';
import moment from "moment/moment";
import {fetchClient} from "../../store/client/clientReducer";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import he from 'he';
import TextareaAutosize from 'react-textarea-autosize';

const WorkoutRoutineUpdate = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, clientId} = useParams();
    const workout = useSelector(selectWorkoutRoutine);
    const workoutLoading = useSelector(selectWorkoutRoutineLoading);
    const workoutUpdated = useSelector(selectWorkoutRoutineUpdate);
    const client = useSelector(selectSelectedClient)
    const isLibrary = Number(clientId) === 0;

    useComponentTranslations('workoutRoutine', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        dispatch(fetchWorkoutRoutine(id));
    }, [dispatch, id]);

    const schemaFields = {
        routineName: Yup.string().max(245, t("workoutRoutine:maxChars")).required(t("workoutRoutine:required")),
        trainingType: Yup.string().required(t("workoutRoutine:required")),
        goal: Yup.string().required(t("workoutRoutine:required")),
        difficulty: Yup.string().required(t("workoutRoutine:required")),
        allowPdfDownload: Yup.string().required(t("workoutRoutine:required")),
        showTrainingTime: Yup.string().required(t("workoutRoutine:required")),
    };

    if (!isLibrary) {
        schemaFields.startDate = Yup.date().required(t("workoutRoutine:required"));
        schemaFields.endDate = Yup.date().required(t("workoutRoutine:required"));
    }

    const validationSchema = Yup.object().shape(schemaFields);

    const handleSubmit = (values) => {
        dispatch(updateRoutine(values));
    };

    const handleGoBack = useCallback(() => {
        navigate(`/user/client/${client?.id || 0}/workout/routine/${workout.id}`)
    }, [client, workout, navigate])

    useEffect(() => {
        if (workoutUpdated) {
            dispatch(updateRoutineSuccess(false))
            handleGoBack()
        }
    }, [workoutUpdated, dispatch, handleGoBack]);

    useEffect(() => {

        if (!isLibrary)
            dispatch(fetchClient(clientId));
    }, [dispatch, clientId, isLibrary]);

    if (!workout || workoutLoading) {
        return <LoadingBlock/>;
    }

    return (
        <>  {
            !isLibrary &&
            <AvatarHeader className={"pb-4 pt-2"}
                          text={`${client?.nome} ${client?.sobrenome}`}
                          url={client?.profileUrl} showGoBack={handleGoBack}/>
        }
            <Page contentHeader={isLibrary} title={`${isLibrary && t("workoutRoutine:editWorkout")}`} mt={`${isLibrary ? "mt-n5" : "mt-n4"}`}
                  goBackLink={handleGoBack}>
                <div className="row justify-content-center ">
                    <div className="col-12">
                        <div className="card card-body border-0">
                            <Formik
                                initialValues={{
                                    id: workout.id,
                                    status: workout.status || 0,
                                    clientId: workout.idAluno || 0,
                                    routineName: he.decode(workout.nome || ''),
                                    trainingType: workout.diaTipo ? workout.diaTipo.toString() : '',
                                    goal: workout.objetivo ? workout.objetivo.toString() : '',
                                    difficulty: workout.dificuldade ? workout.dificuldade.toString() : '',
                                    instructions: he.decode(workout.descricao || ''),
                                    allowPdfDownload: workout.allowPdf !== undefined ? workout.allowPdf.toString() : '',
                                    showTrainingTime: workout.allowTimer !== undefined ? workout.allowTimer.toString() : '',
                                    startDate: workout.dataInicio
                                        ? moment(workout.dataInicio).format("YYYY-MM-DD")
                                        : '',
                                    endDate: workout.dataFim
                                        ? moment(workout.dataFim).format("YYYY-MM-DD")
                                        : '',
                                    removeAfterExpiration: workout.arquivar || false,
                                    hideBeforeStart: workout.mostrarNoInicio || false,
                                }}
                                validationSchema={validationSchema}
                                onSubmit={handleSubmit}
                                enableReinitialize={true}
                            >
                                {({errors, touched}) => (
                                    <Form>
                                        <div className="mb-3">
                                            <label htmlFor="routineName" className="form-label fw-semibold">
                                                {t("workoutRoutine:workoutName")}
                                            </label>
                                            <Field
                                                name="routineName"
                                                type="text"
                                                className={`form-control ${
                                                    errors.routineName && touched.routineName ? 'is-invalid' : ''
                                                }`}
                                            />
                                            <ErrorMessage name="routineName" component="div" className="invalid-feedback"/>
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="trainingType" className="form-label fw-semibold">
                                                {t("workoutRoutine:workoutType")}
                                            </label>
                                            <Field
                                                as="select"
                                                name="trainingType"
                                                className={`form-control ${
                                                    errors.trainingType && touched.trainingType ? 'is-invalid' : ''
                                                }`}
                                            >
                                                <option value="">{t("workoutRoutine:select")}</option>
                                                <option value="1">{t("workoutRoutine:weekDay")}</option>
                                                <option value="2">{t("workoutRoutine:numeric")}</option>
                                            </Field>
                                            <ErrorMessage name="trainingType" component="div" className="invalid-feedback"/>
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="goal" className="form-label fw-semibold">
                                                {t("workoutRoutine:objective")}
                                            </label>
                                            <Field
                                                as="select"
                                                name="goal"
                                                className={`form-control ${errors.goal && touched.goal ? 'is-invalid' : ''}`}
                                            >
                                                <option value="">{t("workoutRoutine:select")}</option>
                                                <option value="1">{t("workoutRoutine:hypertrophy")}</option>
                                                <option value="2">{t("workoutRoutine:fatReduction")}</option>
                                                <option value="3">{t("workoutRoutine:fatReductionHypertrophy")}</option>
                                                <option value="4">{t("workoutRoutine:definition")}</option>
                                                <option value="5">{t("workoutRoutine:conditioning")}</option>
                                                <option value="6">{t("workoutRoutine:lifeQuality")}</option>
                                            </Field>
                                            <ErrorMessage name="goal" component="div" className="invalid-feedback"/>
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="difficulty" className="form-label fw-semibold">
                                                {t("workoutRoutine:difficulty")}
                                            </label>
                                            <Field
                                                as="select"
                                                name="difficulty"
                                                className={`form-control ${
                                                    errors.difficulty && touched.difficulty ? 'is-invalid' : ''
                                                }`}
                                            >
                                                <option value="">{t("workoutRoutine:select")}</option>
                                                <option value="4">{t("workoutRoutine:adaptation")}</option>
                                                <option value="1">{t("workoutRoutine:starter")}</option>
                                                <option value="2">{t("workoutRoutine:intermediary")}</option>
                                                <option value="3">{t("workoutRoutine:advanced")}</option>
                                            </Field>
                                            <ErrorMessage name="difficulty" component="div" className="invalid-feedback"/>
                                        </div>
                                        <div className="mb-3">
                                            <label htmlFor="instructions" className="form-label fw-semibold">
                                                {t("workoutRoutine:generalInstructions")} <span className={"small"}>({t("workoutRoutine:optional")})</span>
                                            </label>
                                            <Field
                                                name="instructions"
                                            >
                                                {({field}) => (
                                                    <TextareaAutosize
                                                        {...field}
                                                        className="form-control"
                                                        rows={3}
                                                        minRows={3}

                                                    />
                                                )}
                                            </Field>
                                        </div>
                                        <div className="mb-3">
                                            <label className="form-label fw-semibold">
                                                {t("workoutRoutine:allowPdf")}
                                            </label>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="allowPdfDownload"
                                                    value="true"
                                                    id="allowPdfDownloadSim"
                                                    className="form-check-input"
                                                />
                                                <label htmlFor="allowPdfDownloadSim" className="form-check-label">
                                                    {t("workoutRoutine:yes")}
                                                </label>
                                            </div>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="allowPdfDownload"
                                                    value="false"
                                                    id="allowPdfDownloadNao"
                                                    className="form-check-input"
                                                />
                                                <label htmlFor="allowPdfDownloadNao" className="form-check-label">
                                                    {t("workoutRoutine:no")}
                                                </label>
                                            </div>
                                            <ErrorMessage name="allowPdfDownload" component="div" className="invalid-feedback d-block"/>
                                        </div>
                                        <div className="mb-3">
                                            <label className="form-label fw-semibold">
                                                {t("workoutRoutine:showTimer")}
                                            </label>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="showTrainingTime"
                                                    value="true"
                                                    id="showTrainingTimeSim"
                                                    className="form-check-input"
                                                />
                                                <label htmlFor="showTrainingTimeSim" className="form-check-label">
                                                    {t("workoutRoutine:yes")}
                                                </label>
                                            </div>
                                            <div className="form-check">
                                                <Field
                                                    type="radio"
                                                    name="showTrainingTime"
                                                    value="false"
                                                    id="showTrainingTimeNao"
                                                    className="form-check-input"
                                                />
                                                <label htmlFor="showTrainingTimeNao" className="form-check-label">
                                                    {t("workoutRoutine:no")}
                                                </label>
                                            </div>
                                            <ErrorMessage name="showTrainingTime" component="div" className="invalid-feedback d-block"/>
                                        </div>
                                        {
                                            !isLibrary &&
                                            <>
                                                <div className="mb-3">
                                                    <label htmlFor="startDate" className="form-label fw-semibold">
                                                        {t("workoutRoutine:startsAt")}
                                                    </label>
                                                    <Field
                                                        name="startDate"
                                                        type="date"
                                                        className={`form-control ${
                                                            errors.startDate && touched.startDate ? 'is-invalid' : ''
                                                        }`}
                                                    />
                                                    <ErrorMessage name="startDate" component="div" className="invalid-feedback"/>
                                                </div>
                                                <div className="mb-3">
                                                    <label htmlFor="endDate" className="form-label fw-semibold">
                                                        {t("workoutRoutine:endsAt")}
                                                    </label>
                                                    <Field
                                                        name="endDate"
                                                        type="date"
                                                        className={`form-control ${
                                                            errors.endDate && touched.endDate ? 'is-invalid' : ''
                                                        }`}
                                                    />
                                                    <ErrorMessage name="endDate" component="div" className="invalid-feedback"/>
                                                </div>
                                                <div className="mb-3 form-check">
                                                    <Field
                                                        type="checkbox"
                                                        name="removeAfterExpiration"
                                                        id="removeAfterExpiration"
                                                        className="form-check-input"
                                                    />
                                                    <label htmlFor="removeAfterExpiration" className="form-check-label fw-semibold">
                                                        {t("workoutRoutine:removeExpired")}
                                                    </label>
                                                </div>
                                                <div className="mb-3 form-check">
                                                    <Field
                                                        type="checkbox"
                                                        name="hideBeforeStart"
                                                        id="hideBeforeStart"
                                                        className="form-check-input"
                                                    />
                                                    <label htmlFor="hideBeforeStart" className="form-check-label fw-semibold">
                                                        {t("workoutRoutine:showAtStart")}
                                                    </label>
                                                </div>
                                            </>
                                        }

                                        <button type="submit" className="btn btn-primary w-100">
                                            {t("workoutRoutine:save")}
                                        </button>
                                    </Form>
                                )}
                            </Formik>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default WorkoutRoutineUpdate;
