import {createSelector} from "reselect";

const reducer = state => state.chatbot

export const selectChatBotMessages = createSelector(
    [reducer], slice => slice.messages
)

export const selectChatBotLoading = createSelector(
    [reducer], slice => slice.loading
)

export const selectChatBotWaitingMessage = createSelector(
    [reducer], slice => slice.waitingMessage
)