import moment from "moment";
import "moment/locale/es";
import "moment/locale/pt";
import "moment/locale/pt-br";

export const DEFAULT_APP_LOCALE = "pt-BR";

export const SUPPORTED_APP_LOCALES = Object.freeze([
    "en-US",
    "es-ES",
    "pt-BR",
    "pt-PT",
]);

const APP_LOCALE_ALIASES = {
    en: "en-US",
    "en-us": "en-US",
    "en_us": "en-US",
    es: "es-ES",
    "es-es": "es-ES",
    "es_es": "es-ES",
    pt: "pt-BR",
    "pt-br": "pt-BR",
    "pt_br": "pt-BR",
    "pt-pt": "pt-PT",
    "pt_pt": "pt-PT",
    "eu-us": "en-US",
};

export const normalizeAppLocale = (locale) => {
    if (!locale || typeof locale !== "string") {
        return DEFAULT_APP_LOCALE;
    }

    const normalized = locale.trim().replace(/_/g, "-").toLowerCase();

    if (APP_LOCALE_ALIASES[normalized]) {
        return APP_LOCALE_ALIASES[normalized];
    }

    if (normalized.startsWith("en")) {
        return "en-US";
    }

    if (normalized.startsWith("es")) {
        return "es-ES";
    }

    if (normalized.startsWith("pt-pt")) {
        return "pt-PT";
    }

    if (normalized.startsWith("pt")) {
        return "pt-BR";
    }

    return DEFAULT_APP_LOCALE;
};

export const resolveMomentLocale = (locale) => {
    switch (normalizeAppLocale(locale)) {
        case "en-US":
            return "en";
        case "es-ES":
            return "es";
        case "pt-PT":
            return "pt";
        case "pt-BR":
        default:
            return "pt-br";
    }
};

export const syncMomentLocale = (locale) => {
    const nextMomentLocale = resolveMomentLocale(locale);
    moment.locale(nextMomentLocale);
    return nextMomentLocale;
};

export const resolveDocumentLanguage = (locale) => normalizeAppLocale(locale);

export const resolveTextDirection = () => "ltr";

export const syncDocumentLocale = (locale) => {
    if (typeof document === "undefined") {
        return null;
    }

    const nextLanguage = resolveDocumentLanguage(locale);
    const nextDirection = resolveTextDirection(locale);

    document.documentElement.lang = nextLanguage;
    document.documentElement.dir = nextDirection;

    return {lang: nextLanguage, dir: nextDirection};
};

export const formatDate = (value, locale, options) => {
    if (!value) {
        return "";
    }

    return new Intl.DateTimeFormat(normalizeAppLocale(locale), options).format(new Date(value));
};

export const formatNumber = (value, locale, options) => {
    const numericValue = Number(value);

    if (Number.isNaN(numericValue)) {
        return "";
    }

    return new Intl.NumberFormat(normalizeAppLocale(locale), options).format(numericValue);
};

export const formatCurrency = (value, locale, currency = "BRL", options = {}) => (
    formatNumber(value, locale, {style: "currency", currency, ...options})
);

export const getDateFormatParts = (locale) => (
    new Intl.DateTimeFormat(normalizeAppLocale(locale))
        .formatToParts(new Date())
        .map((part) => part.type)
        .filter((type) => ["day", "month", "year"].includes(type))
);

export const getDateFormatPattern = (locale) => (
    getDateFormatParts(locale)
        .map((part) => {
            if (part === "day") return "dd";
            if (part === "month") return "MM";
            return "yyyy";
        })
        .join("/")
);

export const getDateInputMask = (locale) => (
    getDateFormatParts(locale)
        .map((part) => (part === "year" ? "9999" : "99"))
        .join("/")
);

export const getDateInputPlaceholder = (locale) => (
    getDateFormatParts(locale)
        .map((part) => {
            if (part === "day") return "DD";
            if (part === "month") return "MM";
            return "YYYY";
        })
        .join("/")
);
