import React, {useCallback, useEffect, useMemo, useRef, useState} from "react";
import CurrencyFormatter from "../utils/currency/CurrencyFormatter";
import {useDispatch, useSelector} from "react-redux";
import {
    selectCoupon, selectCouponLoading,
    selectCreditCardsLoading,
    selectInstallments,
    selectPaymentMethod, selectTransaction, selectTransactionLoading
} from "../../store/subscription/subscriptionSelector";
import {
    checkCoupon,
    createCardTransaction,
    createPixTransaction,
    setCoupon, setInstallments,
    setPaymentMethod,
    walletPaymentStart
} from "../../store/subscription/subscriptionReducer";
import LoadingBlock from "../loader/LoadingBlock";
import {useNavigate, useParams, useSearchParams} from "react-router-dom";
import Overlay from "react-bootstrap/Overlay";
import Popover from "react-bootstrap/Popover";
import {selectBalance, selectSeller} from "../../store/wallet/walletSelector";
import {fetchBalance, fetchSeller} from "../../store/wallet/walletReducer";
import Modal from "react-bootstrap/Modal";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import {isDesktop} from "react-device-detect";
import {getBrowserDetails} from "../../utils/browser/browserPaymentInformation";
import Spinner from "../loader/Spinner";
import {addToast} from "../../store/toast/toastReducer";
import {selectUser} from "../../store/user/userSelector";
import {GoogleReCaptchaProvider, useGoogleReCaptcha} from "react-google-recaptcha-v3";
import {Form, Formik} from "formik";
import * as Yup from "yup";
import SubscriptionCreditCardSelected from "./SubscriptionCreditCardSelected";
import SubscriptionPixSelected from "./SubscriptionPixSelected";
import SubscriptionWalletSelected from "./SubscriptionWalletSelected";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {Trans, useTranslation} from "react-i18next";
import Cookies from "js-cookie";
import SubscriptionCreditCardNotChangedModal from "./SubscriptionCreditCardNotChangedModal";
import {
    getInstallmentValue,
    normalizeInstallmentMap,
    recalculateInstallments,
    resolveInstallmentConfiguration
} from "../../utils/installments/zoopInstallments";

const SubscriptionPurchaseReviewComponent = ({subPlan}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const user = useSelector(selectUser);
    const {couponName, paymentType} = useParams();
    const seller = useSelector(selectSeller);
    const loadingCreditCards = useSelector(selectCreditCardsLoading)
    const paymentMethod = useSelector(selectPaymentMethod)
    const coupon = useSelector(selectCoupon)
    const couponLoading = useSelector(selectCouponLoading)
    const rawCouponDiscount = Number(coupon?.calculatedDiscount ?? 0);
    const planDiscount = useMemo(
        () => Number(subPlan?.calculatedDiscountAmount ?? subPlan?.discount ?? 0),
        [subPlan]
    );
    const couponDiscount = rawCouponDiscount > 0 ? rawCouponDiscount : 0;
    const appliedDiscount = couponDiscount > 0 ? couponDiscount : planDiscount;
    const discountAdjustment = couponDiscount > 0 ? couponDiscount - planDiscount : 0;
    const credit = subPlan?.credit ?? 0;
    const [showCouponField, setShowCouponField] = useState(false);
    const balance = useSelector(selectBalance)

    const normalizedInstallments = useMemo(() => normalizeInstallmentMap(subPlan?.installments), [subPlan]);
    const installmentConfiguration = useMemo(
        () => resolveInstallmentConfiguration(subPlan, normalizedInstallments),
        [subPlan, normalizedInstallments]
    );
    const recalculatedInstallments = useMemo(
        () => recalculateInstallments(subPlan, discountAdjustment, normalizedInstallments, installmentConfiguration),
        [subPlan, discountAdjustment, normalizedInstallments, installmentConfiguration]
    );
    const effectiveInstallments = recalculatedInstallments ?? normalizedInstallments;
    const totalWithAdjustments = useMemo(() => {
        const total = getInstallmentValue(effectiveInstallments, 1);
        if (total !== undefined) {
            return total;
        }
        return subPlan?.amount - appliedDiscount - credit;
    }, [effectiveInstallments, appliedDiscount, subPlan, credit]);

    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const paymentMethodNotAllowed = useMemo(() => {
        if (!coupon || !paymentMethod) return false;
        switch (paymentMethod.type) {
            case "credit_card":
                return coupon.allowCreditCard === false;
            case "pix":
                return coupon.allowPix === false;
            default:
                return false;
        }
    }, [coupon, paymentMethod]);

    const isDisabled = !paymentMethod || paymentMethodNotAllowed;
    const [showPopover, setShowPopover] = useState(false);
    const buttonWrapperRef = useRef(null);
    const [showPixModal, setShowPixModal] = useState(false);
    const [showRecurringWarning, setShowRecurringWarning] = useState(false);
    const [showCouponMessage, setShowCouponMessage] = useState(false);
    const installments = useSelector(selectInstallments);
    const transactionLoading = useSelector(selectTransactionLoading)
    const transaction = useSelector(selectTransaction)
    const [searchParams] = useSearchParams();
    const {executeRecaptcha} = useGoogleReCaptcha();
    const goBackTo = searchParams.get("goBackTo");
    const mclid = Cookies.get('mclid') ?? null;

    const handleShowCouponMessage = useCallback(() => {
        setShowCouponMessage(false);
    }, [])

    const handleShowCouponField = () => {
        setShowCouponField(prevState => !prevState);
    }

    const handleShowPixModal = () => {
        setShowPixModal(prevState => !prevState);
    }

    const handleShowRecurringWarning = () => {
        if (!transactionLoading)
            setShowRecurringWarning(prevState => !prevState);
    }

    const handleClearCoupon = () => {
        setShowCouponMessage(false)
        dispatch(setCoupon(null))
    }

    const handleChangePaymentMethod = () => {
        navigate(`/subscription/payment/${subPlan.id}${goBackTo ? `?goBackTo=${goBackTo}` : ""}`)
    }

    const handleGeneratePix = () => {
        const payload = {
            coupon: coupon?.name,
            subPlan: subPlan.id,
            upgrade: false,
            mclid: encodeURIComponent(mclid)
        }
        dispatch(createPixTransaction(payload));
    }

    const handleCreditCardPurchase = async () => {
        const device = getBrowserDetails();
        if (!executeRecaptcha) return;
        const recaptchaToken = await executeRecaptcha('credit_card_purchase');
        const payload = {
            subPlan: subPlan.id,
            installments: installments,
            device: device,
            upgrade: false,
            coupon: coupon?.name,
            credit_card_token: paymentMethod,
            mclid: encodeURIComponent(mclid),
            recaptchaToken
        }

        dispatch(createCardTransaction(payload))
    }

    const handleRecurringPayment = async () => {
        if (paymentMethod?.type === "wallet") {
            handleWalletPayment();
        } else if (paymentMethod?.type === "credit_card") {
            await handleCreditCardPurchase()
        } else {
            handleShowRecurringWarning()
        }
    }

    const handleWalletPayment = () => {
        const payload = {
            coupon: coupon?.name,
            subPlan: subPlan.id,
            upgrade: false,
            mclid: encodeURIComponent(mclid)
        }
        dispatch(walletPaymentStart(payload))
    }

    const handleCouponSubmit = (values) => {
        const payload = {
            ...values,
            subPlan: subPlan.id
        }
        dispatch(checkCoupon(payload))
    }

    const initialValues = {coupon: coupon?.name || ""};

    const validationSchema = useMemo(() => Yup.object({
        coupon: Yup.string()
            .required(t("subscriptionComponent:couponRequired"))
    }), [t]);

    useEffect(() => {
        if (seller) {
            if (seller.status === "enabled") {
                dispatch(fetchBalance())
            }
        } else {
            dispatch(fetchSeller())
        }
    }, [seller, dispatch])


    const popoverMessage = useMemo(() => t(!paymentMethod ?
        "subscriptionComponent:selectPaymentMethod" :
        "subscriptionComponent:couponNotAllowed"), [t, paymentMethod]);

    const handleDisabledClick = (e) => {
        if (isDisabled) {
            e.preventDefault();
            e.stopPropagation();
            setShowPopover(true);
        }
    };

    const handleAssinarClick = () => {
        if (isDisabled) return;
        if (paymentMethod.type === "pix") {
            handleShowPixModal();
            return;
        }
        handleShowRecurringWarning();
    };

    useEffect(() => {
        if (paymentType) {
            dispatch(setPaymentMethod({"type": paymentType}))
        }
    }, [paymentType, dispatch]);

    useEffect(() => {
        if (couponName && subPlan) {
            const payload = {coupon: couponName, subPlan: subPlan.id}
            dispatch(checkCoupon(payload))
            setShowCouponField(true)
        }
    }, [couponName, dispatch, subPlan])

    useEffect(() => {
        if (coupon) {
            setShowCouponMessage(true);
        } else {
            setShowCouponMessage(false);
        }
    }, [coupon]);

    useEffect(() => {
        if (showPopover) {
            const t = setTimeout(() => setShowPopover(false), 2500);
            return () => clearTimeout(t);
        }
    }, [showPopover]);

    useEffect(() => {
        if (!isDisabled)
            setShowPopover(false);
    }, [isDisabled]);

    useEffect(() => {
        if (installments) {
            if (installments > subPlan?.month) {
                dispatch(setInstallments(subPlan?.month));
            }
        }
    }, [installments, subPlan, dispatch]);

    useEffect(() => {
        if (transaction) {
            switch (transaction.payment_type) {
                case "pix":
                    navigate(`/subscription/purchase/${subPlan.id}/transaction/${transaction.id}/type/pix${couponName ? `/coupon/${couponName}` : ""}`);
                    break;
                case "wallet":
                    if (transaction.status === "pending")
                        navigate(`/subscription/purchase/${subPlan.id}/transaction/${transaction.id}/type/wallet${couponName ? `/coupon/${couponName}` : ""}`)
                    else
                        dispatch(addToast({title: t("subscriptionComponent:errorTitle"), message: t("subscriptionComponent:tryAgainMessage")}))
                    break;
                case "credit":
                    if (transaction.status === "succeeded")
                        navigate(`/subscription/purchase/${subPlan.id}/transaction/${transaction.id}/type/card${couponName ? `/coupon/${couponName}` : ""}`)
                    else
                        navigate(`/subscription/purchase/${subPlan.id}/failed${couponName ? `/coupon/${couponName}` : ""}`);
                    break;
                default:
                    break;
            }
        }
    }, [transaction, couponName, subPlan, navigate, dispatch, t])

    useEffect(() => {
        if (user.subPlan.id >= 1000 && user.subPlan.id < 1004 && subPlan.id === 1004) {
            navigate(`/subscription/purchase/1000?goBackTo=subscriptionAddTime`)
        }
    }, [user, subPlan, navigate])

    useEffect(() => {
        if (paymentMethod?.type === "wallet" && balance) {
            const totalPlanCost = subPlan?.amount - appliedDiscount - Number(subPlan?.credit || 0);
            if (balance.current_balance < totalPlanCost) {
                dispatch(setPaymentMethod(null))
            }
        }
    }, [paymentMethod, balance, subPlan, appliedDiscount, dispatch]);

    useEffect(() => {
        if (paymentMethod?.type === "pix" && !subPlan.showPix) {
            dispatch(setPaymentMethod(null))
        }
    }, [paymentMethod, dispatch, subPlan]);


    if (loadingCreditCards)
        return <LoadingBlock/>

    return (
        <div className={"row justify-content-center"}>
            <div className={"col-12 mt-3"}>
                <div className={'row'}>
                    <div className={"col-12 "}>
                        {
                            paymentMethod?.card &&
                            <SubscriptionCreditCardSelected
                                handleChangePaymentMethod={handleChangePaymentMethod}
                                subPlan={subPlan}
                                paymentMethod={paymentMethod}
                                installmentOptions={effectiveInstallments}/>
                        }
                        {
                            paymentMethod?.type === "pix" &&
                            <SubscriptionPixSelected handleChangePaymentMethod={handleChangePaymentMethod}/>

                        }
                        {
                            paymentMethod?.type === "wallet" &&
                            <SubscriptionWalletSelected handleChangePaymentMethod={handleChangePaymentMethod}/>
                        }
                        {
                            !paymentMethod &&
                            <div className={"row"}>
                                <div className={"col-12"}>
                                    <div className={"card card-body  border-secondary-subtle clickable-element"} onClick={handleChangePaymentMethod}>
                                        <div className={"row justify-content-center"}>
                                            <div className={"col-auto text-center"}>
                                                <div className={"row justify-content-evenly"}>
                                                    <div className={"col-auto"}>
                                                        <i className={"fa-regular fa-credit-card fa-xl"}></i>
                                                    </div>
                                                    {
                                                        subPlan.id !== 1004 &&
                                                        <div className={"col-auto"}>
                                                            <i className={"fab fa-pix fa-xl"}></i>
                                                        </div>
                                                    }
                                                    <div className={"col-auto "}>
                                                        <i className={"fa-regular fa-wallet fa-xl"}></i>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        <div className={"row justify-content-center mt-2"}>
                                            <div className={"col-12 text-center"}>
                                                <span className={"fw-semibold"}>{t("subscriptionComponent:paymentMethod")}</span>
                                            </div>
                                            <div className={"col-12 text-center mt-1"}>
                                                <span className={"text-primary small"}>{t("subscriptionComponent:clickToChoose")}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                </div>
            </div>
            {
                subPlan.id !== 1004 &&
                <div className={"col-12 mt-4"}>
                    {
                        (showCouponField || coupon) &&
                        <div className={"row"}>
                            <div className={"col-12"}>
                                <Formik
                                    initialValues={initialValues}
                                    validationSchema={validationSchema}
                                    enableReinitialize={true}

                                    onSubmit={handleCouponSubmit}
                                >
                                    {({
                                          values,
                                          errors,
                                          touched,
                                          setFieldValue
                                      }) => (
                                        <Form noValidate autoComplete={"off"}>
                                            <div className="input-group mb-3 ">
                                                <span
                                                    className={`input-group-text ${coupon ? "border-primary text-primary" : "text-secondary"} bg-white  border-end-0`}><i
                                                    className={"fa-regular fa-tag"}></i></span>
                                                <input id="coupon"
                                                       name="coupon"
                                                       type="text"
                                                       value={values.coupon}
                                                       className={`form-control${touched.coupon && errors.coupon ? " is-invalid" : ""} bg-white border-start-0 border-end-0  ${coupon && "border-primary text-primary fw-semibold"}`}
                                                       placeholder={t("subscriptionComponent:couponPlaceholder")}
                                                       onChange={e => setFieldValue("coupon", e.target.value.toUpperCase())}
                                                />
                                                {
                                                    !coupon &&
                                                    <button
                                                        className={`btn   border-start-0 text-primary border-secondary-subtle`}
                                                        style={{fontSize: "14px"}} type="submit" disabled={couponLoading}>
                                                        {t("subscriptionComponent:apply")}
                                                    </button>
                                                }
                                                {
                                                    coupon &&
                                                    <span
                                                        className={`btn   border-start-0 text-primary border-primary clickable-element  `}
                                                        style={{fontSize: "14px", paddingTop: "9px"}} type="button" onClick={handleClearCoupon}>
                                                        <i className={"fa-regular fa-times"}></i>
                                                    </span>
                                                }
                                            </div>
                                        </Form>

                                    )}
                                </Formik>
                            </div>
                        </div>
                    }
                    {
                        !showCouponField &&
                        <div className={"row"}>
                            <div className={"col-12 text-center text-primary "}>
                                <span className={"clickable-element"} onClick={handleShowCouponField}><i
                                    className={"fa-regular fa-tag"}></i> {t("subscriptionComponent:addDiscountCoupon")}</span>
                            </div>
                        </div>
                    }
                </div>
            }
            <div className={"col-12 mt-4"}>
                <span className={"fw-semibold "}>{t("subscriptionComponent:purchaseSummary")}</span>
            </div>
            <div className={"col-12 mt-2"}>
                <div className={"card card-body border-0 bg-primary-subtle"}>
                    <div className={"row"}>
                        <div className={"col-12"}>
                            <span className={"fw-semibold d-block fs-6"}>{subPlan.name}</span>
                            {
                                subPlan.id < 1004 ?
                                    <span className={"text-md"}>
                                        <Trans
                                            i18nKey={"subscriptionComponent:unlimitedPlanDescription"}
                                            count={subPlan.month}
                                            components={{duration: <span className="fw-semibold"/>, clients: <span className="fw-semibold"/>}}
                                        />
                                    </span> :
                                    <span className={"text-md"}>
                                        <Trans
                                            i18nKey={"subscriptionComponent:limitedPlanDescription"}
                                            components={{duration: <span className="fw-semibold"/>, clients: <span className="fw-semibold"/>}}
                                        />
                                    </span>
                            }
                        </div>
                    </div>
                    <div className={"col-12 mt-3  "}>
                        <div className={"row justify-content-between fw-semibold"}>
                            <div className={"col-6"}>
                                <span>{t("subscriptionComponent:planValue")}</span>
                            </div>
                            <div className={"col-6 text-end"}>
                                <CurrencyFormatter value={subPlan.amount}/>
                            </div>
                        </div>
                        {
                            planDiscount > 0 && couponDiscount <= 0 &&
                            <div className={"row justify-content-between text-success  "}>
                                <div className={"col-6"}>
                                    <span>{t("subscriptionComponent:discount")}</span>
                                </div>
                                <div className={"col-6  text-end"}>
                                    -<CurrencyFormatter value={planDiscount}/>
                                </div>
                            </div>
                        }
                        {
                            subPlan.credit > 0 &&
                            <div className={"row justify-content-between text-success  "}>
                                <div className={"col-6"}>
                                    <span>{t("subscriptionComponent:currentPlanCredit")}</span>
                                </div>
                                <div className={"col-6  text-end"}>
                                    -<CurrencyFormatter value={subPlan.credit}/>
                                </div>
                            </div>
                        }
                        {
                            couponDiscount > 0 &&
                            <div className={"row justify-content-between text-primary  "}>
                                <div className={"col-6"}>
                                    <span>{t("subscriptionComponent:couponLabel")}</span>
                                </div>
                                <div className={"col-6  text-end"}>
                                    -<CurrencyFormatter value={couponDiscount}/>
                                </div>
                            </div>
                        }
                        <hr className={"border-primary mt-2 mb-2 "}/>
                        <div className={"row justify-content-between     fw-semibold"}>
                            <div className={"col-6"}>
                                <span>{t("subscriptionComponent:total")}</span>
                            </div>
                            <div className={"col-6 text-end"}>
                                <CurrencyFormatter value={totalWithAdjustments}/>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div className={"col-12 mt-3"}>
                <span
                    ref={buttonWrapperRef}
                    className="d-inline-block w-100"
                    onClick={handleDisabledClick}
                >
                    <button
                        className={"btn btn-primary w-100"}
                        disabled={isDisabled}
                        onClick={handleAssinarClick}
                        aria-disabled={isDisabled}
                    >
                        {t("subscriptionComponent:subscribe")}
                    </button>
                </span>

                <Overlay
                    target={buttonWrapperRef.current}
                    show={showPopover}
                    placement="top"
                >
                    {(props) => (
                        <Popover {...props}>
                            <Popover.Body>
                                {popoverMessage}
                            </Popover.Body>
                        </Popover>
                    )}
                </Overlay>
            </div>
            <Modal centered show={showPixModal} onHide={handleShowPixModal}>
                <Modal.Body>
                    <div className={"row justify-content-center"}>
                        <div className={"col-12 text-center mt-3 mb-2"}>
                            <RoundedIcon icon={"fa-pix"} brand={true} size={"lg"}/>
                        </div>
                        <div className={"col-12 text-center"}>
                            <span className={"fw-semibold fs-5"}>{t("subscriptionComponent:howToPayWithPix")}</span>
                        </div>
                        <div className={"col-12 mt-4"}>
                            <span><Trans i18nKey={"subscriptionComponent:pixStep1"}><span className={"fw-semibold"}/></Trans></span>
                        </div>
                        <div className={"col-12 mt-1"}>
                            <span><Trans i18nKey={"subscriptionComponent:pixStep2"}><span className={"fw-semibold"}/></Trans></span>
                        </div>
                        <div className={"col-12 mt-2"}>
                            <span><Trans i18nKey={"subscriptionComponent:pixStep3"}><span className={"fw-semibold"}/></Trans></span>
                        </div>
                        <div className={"col-12 mt-2"}>
                            <span><Trans i18nKey={"subscriptionComponent:pixStep4"}><span className={"fw-semibold"}/></Trans></span>
                        </div>
                        <div className={"col-12 mt-2"}>
                            <span><Trans i18nKey={"subscriptionComponent:pixStep5"}><span className={"fw-semibold"}/></Trans></span>
                        </div>
                        {
                            isDesktop &&
                            <>
                                <div className={"col-12 mt-4"}>
                                    <div className={"card card-body border-0 bg-primary-subtle text-center"}>
                                        <span className={"fw-semibold d-block"}>{t("subscriptionComponent:qrCodeTitle")}</span>
                                        <span>{t("subscriptionComponent:qrCodeDescription")}</span>
                                    </div>
                                </div>
                            </>
                        }
                        <div className={"col-12 mt-4"}>
                            <button className={"btn btn-primary-lighter w-100"} disabled={transactionLoading} onClick={handleGeneratePix}>
                                {t("subscriptionComponent:generateCode")}
                            </button>
                        </div>
                        <div className={"col-12 mt-2"}>
                            <button className={"btn btn-outline-primary-lighter w-100"} disabled={transactionLoading} onClick={handleShowPixModal}>
                                {t("subscriptionComponent:close")}
                            </button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            <Modal centered show={showRecurringWarning} onHide={handleShowRecurringWarning}>
                <Modal.Body>
                    {
                        transactionLoading &&
                        <div className={"row  mt-5 mb-5"}>
                            <div className={"col-12 text-center pb-3"}>
                                <Spinner/>
                            </div>
                            <div className={"col-12 text-center"}>
                                <span className={"   fw-semibold fs-5"}>{t("subscriptionComponent:pleaseWait")}</span>
                            </div>
                        </div>
                    }
                    {
                        !transactionLoading &&
                        <div className={"row justify-content-center"}>
                            <div className={"col-12 text-center mt-3 mb-2"}>
                                <RoundedIcon icon={"fa-repeat"} size={"lg"}/>
                            </div>
                            <div className={"col-12 text-center "}>
                                <span className={"fw-semibold fs-5"}>{t("subscriptionComponent:autoRenewal")}</span>
                            </div>
                            <div className={"col-12 text-center mt-2"}>
                                <span className={"d-block"}>{t("subscriptionComponent:autoRenewalDescription")}</span>
                                <span className={"fw-semibold  d-block mt-2"}>{t("subscriptionComponent:autoRenewalCancellation")}</span>
                            </div>
                            <div className={"col-12 text-center mt-2"}>
                                <button className={"btn btn-primary-lighter w-100"} disabled={transactionLoading} onClick={handleRecurringPayment}>
                                    {t("subscriptionComponent:subscribe")}
                                </button>
                            </div>
                            <div className={"col-12 text-center mt-2"}>
                                <button className={"btn btn-outline-primary-lighter w-100"} disabled={transactionLoading} onClick={handleShowRecurringWarning}>
                                    {t("subscriptionComponent:close")}
                                </button>
                            </div>
                        </div>
                    }

                </Modal.Body>
            </Modal>
            <Modal centered show={showCouponMessage}>
                <Modal.Body>
                    {
                        couponLoading &&
                        <div className={"row justify-content-center"}>
                            <div className={"col-12"}>
                                <LoadingBlock height={"250px"}/>
                            </div>
                        </div>
                    }
                    {
                        !couponLoading && coupon && coupon.invalidCouponMessage &&
                        <div className={"row justify-content-center mt-3 mb-1"}>
                            <div className={"col-12 text-center mb-2"}>
                                <RoundedIcon icon={"fa-ticket"} size={"lg"}/>
                            </div>
                            <div className={"col-12 text-center mb-2"}>
                                <span className={"fw-semibold fs-5 d-block"}>{t("subscriptionComponent:couponNotApplied")}</span>
                                <span>{t(`subscriptionComponent:${coupon.invalidCouponMessage}`)}</span>
                            </div>
                            <div className={"col-12 text-center mt-2"}>
                                <button className={"btn btn-primary-lighter w-100"} onClick={handleClearCoupon}>
                                    {t("subscriptionComponent:close")}
                                </button>
                            </div>
                        </div>
                    }
                    {
                        !couponLoading && coupon && !coupon.invalidCouponMessage &&
                        <div className={"row justify-content-center mt-3 mb-1"}>
                            <div className={"col-12 text-center mb-2"}>
                                <RoundedIcon icon={"fa-ticket"} size={"lg"}/>
                            </div>
                            <div className={"col-12 text-center mb-2"}>
                                <span className={"fw-semibold fs-5 d-block"}>{t("subscriptionComponent:couponSuccessTitle")}</span>
                                <span>{t("subscriptionComponent:couponSuccessDescription")}</span>
                            </div>

                            <div className={"col-12 text-center mt-2"}>
                                <button className={"btn btn-primary-lighter w-100"} onClick={handleShowCouponMessage}>
                                    {t("subscriptionComponent:continue")}
                                </button>
                            </div>
                        </div>
                    }
                </Modal.Body>
            </Modal>
            <SubscriptionCreditCardNotChangedModal closeModal={handleShowRecurringWarning} goToPaymentMethods={handleChangePaymentMethod}/>
        </div>
    )
}

