import Modal from "react-bootstrap/Modal";
import {ErrorMessage, Field, Form, Formik} from "formik";
import * as Yup from "yup";

const ClientGroupCreateModal = ({
    show,
    onHide,
    onSubmit,
    title,
    label,
    submitText,
    cancelText,
    loading,
    requiredMessage,
    minLengthMessage,
    maxLengthMessage,
    initialName = ""
}) => {
    const validationSchema = Yup.object().shape({
        name: Yup.string()
            .required(requiredMessage)
            .min(3, minLengthMessage)
            .max(245, maxLengthMessage)
    });

    return (
        <Modal centered show={show} onHide={onHide}>
            <Modal.Body>
                <div className={"row"}>
                    <div className={"col-12 d-flex justify-content-between align-items-start pb-2"}>
                        <span className={"fs-5 fw-semibold"}>{title}</span>
                        <i
                            className="fa-regular fa-xmark cursor-pointer"
                            onClick={onHide}
                            role="button"
                            aria-label="Close"
                        />
                    </div>
                    <div className={"col-12"}>
                        <Formik
                            initialValues={{name: initialName}}
                            enableReinitialize
                            validationSchema={validationSchema}
                            onSubmit={onSubmit}
                        >
                            <Form>
                                <label className={"form-label"}>{label}</label>
                                <Field type={"text"} className={"form-control"} name={"name"}/>
                                <ErrorMessage name={"name"} component={"div"} className={"text-danger"}/>
                                <div className={"d-grid mt-3"}>
                                    <button type={"submit"} className={"btn btn-primary"} disabled={loading}>
                                        {submitText}
                                    </button>
                                </div>
                                {cancelText && (
                                    <div className={"d-grid mt-2"}>
                                        <button type={"button"} className={"btn btn-link"} onClick={onHide}>
                                            {cancelText}
                                        </button>
                                    </div>
                                )}
                            </Form>
                        </Formik>
                    </div>
                </div>
            </Modal.Body>
        </Modal>
    );
};

export default ClientGroupCreateModal;
