import {useRef} from "react";
import {useDispatch} from "react-redux";
import {addToast} from "../../../store/toast/toastReducer";

const CopyField = ({text, button, toastTitle, toastMessage}) => {
    const dispatch = useDispatch();
    const textRef = useRef(null);
    const handleCopyButton = () => {
        try {
            navigator.clipboard.writeText(textRef.current.innerText)
                .then(() => {
                    dispatch(addToast({
                        type: "primary",
                        title: toastTitle,
                        message: toastMessage,
                    }));
                })
                .catch(() => {
                    const textArea = document.createElement("textarea");
                    textArea.value = textRef.current.innerText;
                    document.body.appendChild(textArea);
                    textArea.select();
                    document.execCommand('copy');
                    document.body.removeChild(textArea);

                    dispatch(addToast({
                        type: "primary",
                        title: toastTitle,
                        message: toastMessage,
                    }));
                });
        } catch (error) {
            console.error('Failed to copy text:', error);
        }
    };
    return (
        <div className={'row justify-content-center d-flex'}>
            <div className={'col-12'} onClick={handleCopyButton}>
                <div className={'card card-body border-0 bg-secondary-subtle text-center '}>
                    <span className={"d-block text-center fw-semibold "}><i className={"fa-regular fa-copy mb-3"}></i> Pix Copia e Cola</span>
                    <span ref={textRef} className={"small"}>
                        {text}
                    </span>
                </div>
            </div>
            <div className={"col-12 mt-3"}>
                <button onClick={handleCopyButton} className={"btn btn-primary-lighter w-100"}>{button}</button>
            </div>
        </div>
    );
}
export default CopyField;