import React from "react";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {buildOnlineEvaluationAnswerRoute} from "../../utils/client/evaluationRoutes";

const OnlineEvaluationStartModal = ({onClose, handleSwitchToSendModal, id}) => {
    const navigate = useNavigate();
    const {t} = useTranslation();
    useComponentTranslations('evaluationOnlineComponents', {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT
    });

    const handleGoIwillAnswer = () => {
        navigate(buildOnlineEvaluationAnswerRoute(id));
    };

    return (
        <div className={"row"}>
            <div className={"col-12"}>
                <div className={"row justify-content-between"}>
                    <div className={"col-auto"}>
                    <span className={"fw-semibold text-start"}>
                        {t("evaluationOnlineComponents:whatYouWant")}
                    </span>
                    </div>
                    <div className={"col-auto cursor-pointer"} onClick={onClose}>
                        <i className={"fa-regular fa-times"}/>
                    </div>
                </div>
                <div className={"d-grid gap-2 pt-3"}>
                    <button className={"btn btn-outline-primary"} onClick={handleGoIwillAnswer}>
                        {t("evaluationOnlineComponents:iWillFill")}
                    </button>
                    <button className={"btn btn-outline-primary"} onClick={handleSwitchToSendModal}>
                        {t("evaluationOnlineComponents:myStudentWillFill")}
                    </button>
                </div>
            </div>
        </div>
    )
}

export default OnlineEvaluationStartModal;
