import {createSelector} from "reselect";

const reducer = state => state.personalFinances;

export const selectPersonalFinancesList = createSelector([reducer], (slice) => slice.personalFinancesList);
export const selectFinancesCategories = createSelector( [reducer], (slice) => slice.financesCategoriesList);
export const selectPersonalFinancesLoading = createSelector([reducer], (slice) => slice.loading);
export const selectCreateSucceeded = createSelector([reducer], slice => slice.createSucceeded);
export const selectUpdateSucceeded = createSelector([reducer], slice => slice.updateSucceeded);
