import {Image} from "react-bootstrap";

const WorkoutPdfImageType = ({exercise}) => {


    switch (exercise.mediaType) {
        case 0:
            return (
                <div className={"col-5 align-self-center"}>
                    <Image src={`https://img.youtube.com/vi/${exercise.urlMedia}/0.jpg`} className={"rounded-1"} fluid/>
                </div>
            )
        case 1:
            return (
                <div className={"col-3 align-self-center"}>
                    <Image src={exercise.urlMedia} className={"rounded-1"} fluid/>
                </div>
            )
        case 3:
            return (
                <div className={"col-3 align-self-center"}>
                    <Image src={exercise.urlPoster} className={"rounded-1"} fluid/>
                </div>
            )
        default:
            return "";
    }


}
export default WorkoutPdfImageType;