import {createSlice} from "@reduxjs/toolkit";

const INITIAL_STATE = {
    list: [],
    current: null,
    listLoading: false,
    currentLoading: false,
    listStatus: "idle",
    currentStatus: "idle",
    listErrorCode: null,
    currentErrorCode: null,
    createLoading: false,
    editLoading: false,
    sendLoading: false,
    deleteLoading: false,
    executeLoading: false,
    createSuccess: false,
    editSuccess: false,
    sendSuccess: false,
    deleteSuccess: false,
    executeSuccess: false
};

export const extraTrainingSlice = createSlice({
    name: "extraTraining",
    initialState: INITIAL_STATE,
    reducers: {
        fetchExtraTrainingList(state) {
            state.listLoading = true;
            state.listStatus = "loading";
            state.listErrorCode = null;
            state.list = [];
        },
        setExtraTrainingList(state, action) {
            state.listLoading = false;
            state.listStatus = "success";
            state.listErrorCode = null;
            state.list = action.payload || [];
        },
        extraTrainingListError(state, action) {
            state.listLoading = false;
            state.listStatus = "error";
            state.listErrorCode = action.payload || null;
            state.list = [];
        },
        fetchOneExtraTraining(state) {
            state.currentLoading = true;
            state.currentStatus = "loading";
            state.currentErrorCode = null;
            state.current = null;
        },
        setCurrentExtraTraining(state, action) {
            state.currentLoading = false;
            state.currentStatus = action.payload ? "success" : "idle";
            state.currentErrorCode = null;
            state.current = action.payload;
        },
        currentExtraTrainingError(state, action) {
            state.currentLoading = false;
            state.currentStatus = "error";
            state.currentErrorCode = action.payload || null;
            state.current = null;
        },
        clearCurrentExtraTraining(state) {
            state.current = null;
            state.currentLoading = false;
            state.currentStatus = "idle";
            state.currentErrorCode = null;
        },
        createExtraTraining(state) {
            state.createLoading = true;
            state.createSuccess = false;
        },
        extraTrainingCreated(state) {
            state.createLoading = false;
            state.createSuccess = true;
        },
        clearCreateExtraTraining(state) {
            state.createSuccess = false;
        },
        editExtraTraining(state) {
            state.editLoading = true;
            state.editSuccess = false;
        },
        extraTrainingEdited(state, action) {
            state.editLoading = false;
            state.current = action.payload;
            state.list = (state.list || []).map(item => item.id === action.payload.id ? action.payload : item);
            state.editSuccess = true;
        },
        clearEditExtraTraining(state) {
            state.editSuccess = false;
        },
        sendExtraTraining(state) {
            state.sendLoading = true;
            state.sendSuccess = false;
        },
        extraTrainingSent(state) {
            state.sendLoading = false;
            state.sendSuccess = true;
        },
        clearSendExtraTraining(state) {
            state.sendSuccess = false;
        },
        deleteExtraTraining(state) {
            state.deleteLoading = true;
            state.deleteSuccess = false;
        },
        extraTrainingDeleted(state, action) {
            state.deleteLoading = false;
            state.deleteSuccess = true;
            state.list = (state.list || []).filter(item => item.id !== action.payload.extraTrainingId);
            if (state.current?.id === action.payload.extraTrainingId) {
                state.current = null;
            }
        },
        clearDeleteExtraTraining(state) {
            state.deleteSuccess = false;
        },
        executeExtraTraining(state) {
            state.executeLoading = true;
            state.executeSuccess = false;
        },
        extraTrainingExecuted(state, action) {
            state.executeLoading = false;
            state.executeSuccess = true;
            state.list = (state.list || []).filter(item => item.id !== action.payload.extraTrainingId);
            if (state.current?.id === action.payload.extraTrainingId) {
                state.current = null;
            }
        },
        clearExecuteExtraTraining(state) {
            state.executeSuccess = false;
        },
        clearExtraTrainingMutations(state) {
            state.createSuccess = false;
            state.editSuccess = false;
            state.sendSuccess = false;
            state.deleteSuccess = false;
            state.executeSuccess = false;
            state.createLoading = false;
            state.editLoading = false;
            state.sendLoading = false;
            state.deleteLoading = false;
            state.executeLoading = false;
        },
        onError(state) {
            state.createLoading = false;
            state.editLoading = false;
            state.sendLoading = false;
            state.deleteLoading = false;
            state.executeLoading = false;
        }
    }
});

export const {
    fetchExtraTrainingList,
    setExtraTrainingList,
    extraTrainingListError,
    fetchOneExtraTraining,
    setCurrentExtraTraining,
    currentExtraTrainingError,
    clearCurrentExtraTraining,
    createExtraTraining,
    extraTrainingCreated,
    clearCreateExtraTraining,
    editExtraTraining,
    extraTrainingEdited,
    clearEditExtraTraining,
    sendExtraTraining,
    extraTrainingSent,
    clearSendExtraTraining,
    deleteExtraTraining,
    extraTrainingDeleted,
    clearDeleteExtraTraining,
    executeExtraTraining,
    extraTrainingExecuted,
    clearExecuteExtraTraining,
    clearExtraTrainingMutations,
    onError
} = extraTrainingSlice.actions;

export const extraTrainingReducer = extraTrainingSlice.reducer;
