import React, {useCallback, useEffect, useMemo} from "react";
import * as Yup from "yup";
import {useDispatch, useSelector} from "react-redux";
import {ErrorMessage, Field, Form, Formik} from "formik";
import Select from "react-select";
import {fetchClientGroups} from "../../store/client-group/clientGroupReducer";
import {selectClientGroups} from "../../store/client-group/clientGroupSelector";
import {resetFormSent, sendOnline, setEvaluationOnline} from "../../store/online-evaluation/evaluationOnlineReducer";
import {getSubmitLoading, getSubmitResult} from "../../store/online-evaluation/evaluationOnlineSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ClientRemoteMultiSelect from "../client/ClientRemoteMultiSelect";
import EvaluationSubmitButton from "../evaluation-components/EvaluationSubmitButton";
import EvaluationSuccessCard from "../evaluation-components/EvaluationSuccessCard";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const OnlineEvaluationSendModal = ({onClose, clientId}) => {
    const dispatch = useDispatch();
    const submitLoading = useSelector(getSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const clientGroupList = useSelector(selectClientGroups);
    const {t} = useTranslation();
    useComponentTranslations('evaluationOnlineComponents', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const sent = isMatchingSubmitSuccess(submitResult, {
        action: "send",
        flow: EVALUATION_FLOWS.ONLINE_SEND,
        clientId
    });

    const validationSchema = Yup.object().shape({
        sendTo: Yup.string().required(t("evaluationOnlineComponents:requiredField")),
        selectOption: Yup.array().when("sendTo", {
            is: (value) => value === "clientsId" || value === "groupsId",
            then: (schema) =>
                schema
                    .min(1, t("evaluationOnlineComponents:selectAtLeastOne"))
                    .required(t("evaluationOnlineComponents:selectOption")),
            otherwise: (schema) => schema.notRequired(),
        }),
        schedule: Yup.string().required(t("evaluationOnlineComponents:selectOption")),
        frequency: Yup.number().when("schedule", {
            is: (value) => value === "yes",
            then: (schema) =>
                schema
                    .required(t("evaluationOnlineComponents:enterFrequency"))
                    .min(1, t("evaluationOnlineComponents:minValue")),
            otherwise: (schema) => schema.default(0),
        }),
    });

    const groupOptions = useMemo(() =>
            (clientGroupList || [])
                .map(g => ({ value: g.id, label: g.nome })),
        [clientGroupList]);


    const handleSubmit = (values) => {
        const {sendTo, selectOption, frequency} = values;
        const idsToSend =
            sendTo === "current"
                ? clientId
                : selectOption && selectOption.length > 0
                    ? selectOption
                    : 0;

        const payload = {
            frequency: frequency || 0,
        };

        if (sendTo === "current" || sendTo === "clientsId") {
            payload.type = "clientsId";
        } else {
            payload.type = sendTo;
        }
        payload.ids = idsToSend;
        dispatch(sendOnline(payload, {
            flow: EVALUATION_FLOWS.ONLINE_SEND,
            clientId
        }));
        dispatch(setEvaluationOnline(null));
    };

    const resetDependentFields = useCallback((value, setFieldValue) => {
        setFieldValue("selectOption", []);
        setFieldValue("schedule", "no");
        setFieldValue("frequency", 0);

        if (value === "groupsId") {
            dispatch(fetchClientGroups());
        }
    }, [dispatch]);

    useEffect(() => {
        return () => dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        dispatch(resetFormSent());
        dispatch(fetchClientGroups());
    }, [dispatch]);

    return (
        <>
            <div className="row">
                <div className="col-12">
                    {sent ? (
                        <EvaluationSuccessCard
                            title={t("evaluationOnlineComponents:evaluationSent")}
                            primaryLabel={t("evaluationOnlineComponents:close")}
                            onPrimary={onClose}
                            withCard={false}
                        />
                    ) : (
                            <Formik
                                initialValues={{
                                    sendTo: "current",
                                    selectOption: [],
                                    frequency: 0,
                                    schedule: "no",
                                }}
                                validationSchema={validationSchema}
                                onSubmit={handleSubmit}
                            >
                                {({values, setFieldValue, errors, touched}) => (
                                    <Form>
                                        <div className="form-group mt-2">
                                            <label
                                                className="fw-semibold">{t("evaluationOnlineComponents:currentStudent")}</label>
                                            <Field
                                                as="select"
                                                name="sendTo"
                                                className={`form-control ${
                                                    touched.sendTo && errors.sendTo ? "is-invalid" : ""
                                                }`}
                                                onChange={(e) => {
                                                    const value = e.target.value;
                                                    setFieldValue("sendTo", value);
                                                    resetDependentFields(value, setFieldValue);
                                                }}
                                            >
                                                <option
                                                    value="current">{t("evaluationOnlineComponents:currentStudent")}</option>
                                                <option
                                                    value="clientsId">{t("evaluationOnlineComponents:specificStudents")}</option>
                                                <option
                                                    value="groupsId">{t("evaluationOnlineComponents:studentGroups")}</option>
                                            </Field>
                                            <ErrorMessage name="sendTo" component="div" className="invalid-feedback"/>
                                        </div>
                                        {(values.sendTo === "clientsId" || values.sendTo === "groupsId") && (
                                            <div className="form-group mt-2">
                                                <label className="fw-semibold">
                                                    {values.sendTo === "clientsId" ? t("evaluationOnlineComponents:oneOrMore") : t("evaluationOnlineComponents:oneOrMoreGroups")}
                                                </label>
                                                {values.sendTo === "clientsId" ? (
                                                    <ClientRemoteMultiSelect
                                                        valueIds={values.selectOption}
                                                        onChangeIds={(clientIds) => setFieldValue("selectOption", clientIds)}
                                                        searchScope={"active"}
                                                        placeholder={t("evaluationOnlineComponents:selectOption")}
                                                        disabled={submitLoading}
                                                    />
                                                ) : (
                                                    <Select
                                                        isMulti
                                                        name="selectOption"
                                                        options={groupOptions}
                                                        className="basic-multi-select"
                                                        classNamePrefix="select"
                                                        onChange={(opts) => setFieldValue("selectOption", opts ? opts.map((opt) => opt.value) : [])}
                                                        value={groupOptions.filter((option) => values.selectOption.includes(option.value))}
                                                    />
                                                )}
                                                <ErrorMessage name="selectOption" component="div"
                                                              className="invalid-feedback"/>
                                            </div>
                                        )}
                                        <div className="pt-3">
                                            <span
                                                className="fw-semibold">{t("evaluationOnlineComponents:scheduleRecurrence")}</span>
                                            <div className="form-check pt-2">
                                                <input
                                                    className="form-check-input"
                                                    type="radio"
                                                    name="schedule"
                                                    id="scheduleYes"
                                                    value="yes"
                                                    onChange={() => {
                                                        setFieldValue("schedule", "yes");
                                                        setFieldValue("frequency", "");
                                                    }}
                                                />
                                                <label className="form-check-label" htmlFor="scheduleYes">
                                                    {t("evaluationOnlineComponents:yes")}
                                                </label>
                                            </div>
                                            <div className="form-check">
                                                <input
                                                    className="form-check-input"
                                                    type="radio"
                                                    name="schedule"
                                                    id="scheduleNo"
                                                    value="no"
                                                    onChange={() => {
                                                        setFieldValue("schedule", "no");
                                                        setFieldValue("frequency", 0);
                                                    }}
                                                    defaultChecked
                                                />
                                                <label className="form-check-label" htmlFor="scheduleNo">
                                                    {t("evaluationOnlineComponents:no")}
                                                </label>
                                            </div>
                                            <ErrorMessage name="schedule" component="div" className="invalid-feedback"/>
                                        </div>
                                        {values.schedule === "yes" && (
                                            <div className="pt-2">
                                                <label htmlFor="frequency" className="fw-semibold">
                                                    {t("evaluationOnlineComponents:frequencyDays")}
                                                </label>
                                                <Field
                                                    type="number"
                                                    name="frequency"
                                                    className="form-control mt-1"
                                                />
                                                <ErrorMessage name="frequency" component="div"
                                                              className="invalid-feedback"/>
                                            </div>
                                        )}
                                        <div className="d-grid mt-3 pb-2">
                                            <EvaluationSubmitButton
                                                label={t("evaluationOnlineComponents:send")}
                                                loadingLabel={t("evaluationOnlineComponents:send")}
                                                isSubmitting={submitLoading}
                                            />
                                        </div>
                                    </Form>
                                )}
                            </Formik>
                    )}
                </div>
                {!sent && (
                    <div className="col-12">
                        <div className="d-grid">
                            <button className="btn btn-outline-primary" onClick={onClose} disabled={submitLoading}>
                                {t("evaluationOnlineComponents:close")}
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </>
    );
};

export default OnlineEvaluationSendModal;
