import {useEffect, useMemo, useRef} from "react";
import {ErrorMessage, Field, Form, Formik} from "formik";
import * as Yup from "yup";
import {PhoneInput} from "react-international-phone";
import {isValidPhoneNumber} from "libphonenumber-js";
import {useDispatch, useSelector} from "react-redux";
import {useTranslation} from "react-i18next";
import 'react-international-phone/style.css';
import Page from "../../components/page/Page";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import {
    selectPersonalInformationUpdateErrorCode,
    selectPersonalInformationUpdateLoading,
    selectPersonalInformationUpdateSuccess,
    selectUser
} from "../../store/user/userSelector";
import {addToast} from "../../store/toast/toastReducer";
import {
    clearUserPersonalInformationUpdateState,
    updateUserPersonalInformation
} from "../../store/user/userReducer";
import {formatPhoneWithPlus, normalizeEmail, sanitizePhoneDigits} from "../../utils/user-profile/normalizers";
import decodeHtmlEntities from "../../utils/text/decodeHtmlEntities";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const UserProfilePersonalInformation = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const user = useSelector(selectUser);
    const formikRef = useRef(null);
    const personalInformationUpdateLoading = useSelector(selectPersonalInformationUpdateLoading);
    const personalInformationUpdateSuccess = useSelector(selectPersonalInformationUpdateSuccess);
    const personalInformationUpdateErrorCode = useSelector(selectPersonalInformationUpdateErrorCode);

    const translationsLoaded = useComponentTranslations("userPersonalInformationPage", {
        "en-US": enUS.userPersonalInformationPage,
        "pt-BR": ptBR.userPersonalInformationPage,
        "es-ES": esES.userPersonalInformationPage,
        "pt-PT": ptPT.userPersonalInformationPage
    });

    const defaultCountry = useMemo(() => {
        const language = `${user?.language || navigator.language || "pt-BR"}`.toLowerCase();
        const [, country] = language.split("-");
        return country || "br";
    }, [user?.language]);

    const validationSchema = Yup.object().shape({
        nome: Yup.string()
            .trim()
            .required(t("userPersonalInformationPage:requiredField")),
        sobrenome: Yup.string()
            .trim()
            .required(t("userPersonalInformationPage:requiredField")),
        email: Yup.string()
            .trim()
            .email(t("userPersonalInformationPage:invalidEmail"))
            .matches(/^[^\s@]+@[^\s@]+\.[^\s@]+$/, t("userPersonalInformationPage:invalidEmail"))
            .required(t("userPersonalInformationPage:requiredField")),
        whatsapp: Yup.string()
            .required(t("userPersonalInformationPage:requiredField"))
            .test(
                "isValidPhoneNumber",
                t("userPersonalInformationPage:invalidPhone"),
                (value) => (value ? isValidPhoneNumber(value) : false)
            ),
        cref: Yup.string().trim(),
        instagram: Yup.string().trim()
    });

    const initialValues = useMemo(() => ({
        nome: decodeHtmlEntities(user?.nome || ""),
        sobrenome: decodeHtmlEntities(user?.sobrenome || ""),
        email: user?.mail || "",
        whatsapp: formatPhoneWithPlus(user?.waId),
        cref: user?.registroCref || "",
        instagram: user?.instagramUser || user?.instagram || ""
    }), [user]);

    useEffect(() => {
        dispatch(clearUserPersonalInformationUpdateState());
        return () => {
            dispatch(clearUserPersonalInformationUpdateState());
        };
    }, [dispatch]);

    useEffect(() => {
        if (!personalInformationUpdateSuccess) {
            return;
        }

        dispatch(addToast({
            type: "success",
            title: t("userPersonalInformationPage:saveSuccessTitle"),
            message: t("userPersonalInformationPage:saveSuccessMessage")
        }));

        dispatch(clearUserPersonalInformationUpdateState());
    }, [dispatch, personalInformationUpdateSuccess, t]);

    useEffect(() => {
        if (!personalInformationUpdateErrorCode) {
            return;
        }

        if (personalInformationUpdateErrorCode === "TOKEN_REFRESH_FAILED") {
            dispatch(clearUserPersonalInformationUpdateState());
            return;
        }

        if (personalInformationUpdateErrorCode === "EMAIL_ALREADY_IN_USE") {
            formikRef.current?.setFieldTouched("email", true, false);
            formikRef.current?.setFieldError("email", t("userPersonalInformationPage:emailAlreadyInUse"));
            dispatch(clearUserPersonalInformationUpdateState());
            return;
        }

        dispatch(addToast({
            type: "danger",
            title: t("userPersonalInformationPage:saveErrorTitle"),
            message: t("userPersonalInformationPage:saveErrorMessage"),
            delay: 10000
        }));

        dispatch(clearUserPersonalInformationUpdateState());
    }, [dispatch, personalInformationUpdateErrorCode, t]);

    const handleSubmit = (values) => {
        const payload = {
            nome: values.nome.trim(),
            sobrenome: values.sobrenome.trim(),
            email: normalizeEmail(values.email),
            whatsapp: sanitizePhoneDigits(values.whatsapp),
            cref: values.cref.trim(),
            instagram: values.instagram.trim()
        };

        dispatch(updateUserPersonalInformation(payload));
    };

    if (!translationsLoaded) {
        return null;
    }

    return (
        <Page title={t("userPersonalInformationPage:title")} goBackLink={"/user/profile"} mt={"mt-n5"}>
            <div className={"card card-body border-0"}>
                <Formik
                    innerRef={formikRef}
                    initialValues={initialValues}
                    validationSchema={validationSchema}
                    enableReinitialize={true}
                    onSubmit={handleSubmit}
                >
                    {({touched, errors, setFieldTouched, setFieldValue}) => (
                        <Form noValidate={true}>
                            <div className={"form-group"}>
                                <label htmlFor={"nome"} className={"form-label fw-semibold"}>{t("userPersonalInformationPage:name")}</label>
                                <Field
                                    id={"nome"}
                                    name={"nome"}
                                    type={"text"}
                                    className={`form-control ${touched.nome && errors.nome ? "is-invalid" : ""}`}
                                />
                                <ErrorMessage name={"nome"} component={"div"} className={"invalid-feedback"}/>
                            </div>

                            <div className={"form-group mt-3"}>
                                <label htmlFor={"sobrenome"} className={"form-label fw-semibold"}>{t("userPersonalInformationPage:lastName")}</label>
                                <Field
                                    id={"sobrenome"}
                                    name={"sobrenome"}
                                    type={"text"}
                                    className={`form-control ${touched.sobrenome && errors.sobrenome ? "is-invalid" : ""}`}
                                />
                                <ErrorMessage name={"sobrenome"} component={"div"} className={"invalid-feedback"}/>
                            </div>

                            <div className={"form-group mt-3"}>
                                <label htmlFor={"email"} className={"form-label fw-semibold"}>{t("userPersonalInformationPage:email")}</label>
                                <Field
                                    id={"email"}
                                    name={"email"}
                                    type={"email"}
                                    className={`form-control ${touched.email && errors.email ? "is-invalid" : ""}`}
                                />
                                <ErrorMessage name={"email"} component={"div"} className={"invalid-feedback"}/>
                            </div>

                            <div className={"form-group mt-3"}>
                                <label htmlFor={"whatsapp"} className={"form-label fw-semibold"}>{t("userPersonalInformationPage:whatsapp")}</label>
                                <Field name={"whatsapp"}>
                                    {({field}) => (
                                        <PhoneInput
                                            fieldName={"whatsapp"}
                                            defaultCountry={defaultCountry}
                                            value={field.value}
                                            onChange={(value) => setFieldValue(field.name, value)}
                                            onBlur={() => setFieldTouched(field.name, true)}
                                            className={`form-control p-0 ${touched.whatsapp && errors.whatsapp ? "is-invalid" : ""}`}
                                            inputClassName={"border-0"}
                                            buttonClassName={"border-0"}
                                            forceDialCode={true}
                                        />
                                    )}
                                </Field>
                                {
                                    touched.whatsapp && errors.whatsapp &&
                                    <div className={"invalid-feedback d-block"}>{errors.whatsapp}</div>
                                }
                            </div>

                            <div className={"form-group mt-3"}>
                                <label htmlFor={"cref"} className={"form-label fw-semibold"}>{t("userPersonalInformationPage:cref")}</label>
                                <Field
                                    id={"cref"}
                                    name={"cref"}
                                    type={"text"}
                                    className={`form-control ${touched.cref && errors.cref ? "is-invalid" : ""}`}
                                />
                                <ErrorMessage name={"cref"} component={"div"} className={"invalid-feedback"}/>
                            </div>

                            <div className={"form-group mt-3"}>
                                <label htmlFor={"instagram"} className={"form-label fw-semibold"}>{t("userPersonalInformationPage:instagram")}</label>
                                <Field
                                    id={"instagram"}
                                    name={"instagram"}
                                    type={"text"}
                                    className={`form-control ${touched.instagram && errors.instagram ? "is-invalid" : ""}`}
                                />
                                <ErrorMessage name={"instagram"} component={"div"} className={"invalid-feedback"}/>
                            </div>

                            <div className={"d-grid mt-4"}>
                                <button type={"submit"} className={"btn btn-primary"} disabled={personalInformationUpdateLoading}>
                                    {
                                        personalInformationUpdateLoading
                                            ? <i className={"fa-regular fa-ellipsis fa-fade fa-2xl"}/>
                                            : t("userPersonalInformationPage:save")
                                    }
                                </button>
                            </div>
                        </Form>
                    )}
                </Formik>
            </div>
        </Page>
    );
};

export default UserProfilePersonalInformation;
