import {useNavigate, useParams} from "react-router-dom";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useDispatch, useSelector} from "react-redux";
import Page from "../../components/page/Page";
import {selectSelectedClient} from "../../store/client/clientSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useEffect} from "react";
import {getAllAnamnesisList} from "../../store/anamnesis/anamnesisReducer";
import {getAnamnesisList, isAnamnesisLoading} from "../../store/anamnesis/anamnesisSelector";
import {fetchClient} from "../../store/client/clientReducer";
import AnamnesisListItem from '../../components/anamnesis/AnamnesisListItem';
import {useTranslation} from "react-i18next";
import EmptySet from "../../components/empty-set/EmptySet";
import {
    buildAnamnesisNewRoute,
    buildClientEvaluationHomeRoute
} from "../../utils/client/evaluationRoutes";

const Anamnesis = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {clientId} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const loadingAnamnesis = useSelector(isAnamnesisLoading)
    const anamnesisList = useSelector(getAnamnesisList) || [];
    useComponentTranslations('anamnesis', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBackPage = () => {
        navigate(buildClientEvaluationHomeRoute(clientId));
    }
    const handleGoAnamnesisModel = () => {
        navigate(buildAnamnesisNewRoute(clientId))
    }

    const handleGoBack = () => {
        navigate("/user")
    }

    useEffect(() => {
        dispatch(fetchClient(clientId));
        dispatch(getAllAnamnesisList(clientId));
    }, [dispatch, clientId]);

    return (
        <>
            <AvatarHeader showGoBack={handleGoBackPage} className={"pb-4 pt-2"}
                          text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                          url={selectedClient?.profileUrl} />
            <Page contentHeader={false} loading={loadingAnamnesis} goBackLink={handleGoBack}>
                <div className={'row justify-content-center d-flex'}>
                    <div className={"col-12"}>
                        <div className={'card card-body border-0'}>
                            {
                                anamnesisList?.length > 0 &&
                                <>
                                    <div className={"btn btn-outline-primary py-4 clickable-element"}
                                         onClick={handleGoAnamnesisModel}>
                                        <i className={"fa-regular fa-plus"}/>
                                        <span className={"px-1 clickable-element"}>
                                            {t("anamnesis:newAnamnesis")}
                                        </span>
                                    </div>
                                    <div className={"pt-3"}>
                                        <div className={"fw-semibold h5"}>
                                            {t("anamnesis:sentAnamnesis")}
                                        </div>
                                    </div>
                                    <div className="row justify-content-center d-flex">
                                        <div className={"col-12"}>
                                            {
                                                anamnesisList.map((item) => (
                                                    <AnamnesisListItem
                                                        selectedClient={selectedClient}
                                                        key={item.id}
                                                        anamnesis={item}

                                                    />
                                                ))
                                            }
                                        </div>
                                    </div>
                                </>
                            }

                            {
                                (!anamnesisList || anamnesisList.length === 0) &&
                                <>
                                    <EmptySet icon={"fa-regular fa-file-lines"} message={t("anamnesis:noAnamnesis")}/>
                                    <div className={"btn btn-primary   clickable-element"}
                                         onClick={handleGoAnamnesisModel}>
                                        <span className={"px-1 clickable-element"}>
                                            {t("anamnesis:newAnamnesis")}
                                        </span>
                                    </div>
                                </>
                            }
                        </div>
                    </div>
                </div>
            </Page>

        </>
    )
}

export default Anamnesis;
