import React from 'react';


const Pagination = ({
                        currentPage,
                        totalItems,
                        itemsPerPage,
                        onPageChange,
                        pagesToShow = 5,
                        className = '',
                        disabledClassName = 'disabled',
                        activeClassName = 'active'
                    }) => {

    const maxPage = Math.ceil(totalItems / itemsPerPage);
    const startPage = Math.max(1, currentPage - Math.floor(pagesToShow / 2));
    const endPage = Math.min(maxPage, startPage + pagesToShow - 1);

    const handlePageChange = (page) => {
        if (page >= 1 && page <= maxPage) {
            onPageChange(page);
        }
    };

    return (
        <nav aria-label="Pagination" className={className}>
            <ul className="pagination justify-content-center flex-wrap bg-transparent">
                {
                    currentPage > 1 &&
                    <li className={`page-item ${currentPage === 1 ? disabledClassName : ''} align-self-center`}>
                        <button
                            className="btn btn-link text-primary-darker pt-1 pb-1 "
                            onClick={() => handlePageChange(currentPage - 1)}
                            disabled={currentPage === 1}
                        >
                            <i className={"fa-regular fa-chevron-left"}></i>
                        </button>
                    </li>
                }
                {Array.from({length: endPage - startPage + 1}, (_, i) => startPage + i).map(page => (
                    <li key={page} className={`page-item  ${currentPage === page ? activeClassName : ''}`}>
                        <button className="page-link border-0 rounded-2 pt-1 pb-1 " onClick={() => handlePageChange(page)}>
                            {page}
                        </button>
                    </li>
                ))}
                <li className={`page-item ${currentPage === maxPage ? disabledClassName : ''} align-self-center `}>
                    <button
                        className="btn btn-link text-primary-darker pt-1 pb-1 "
                        onClick={() => handlePageChange(currentPage + 1)}
                        disabled={currentPage === maxPage}
                    >
                        <i className={"fa-regular fa-chevron-right"}></i>
                    </button>
                </li>
            </ul>
        </nav>
    );
};


export default Pagination;
