import {useEffect, useRef, useState} from "react";
import {Field, Form, Formik} from "formik";
import * as Yup from "yup";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import {Modal} from "react-bootstrap";
import Page from "../../components/page/Page";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import {addToast} from "../../store/toast/toastReducer";
import {
    clearUserPasswordRecoveryState,
    clearUserPasswordUpdateState,
    recoverUserPassword,
    updateUserPassword
} from "../../store/user/userReducer";
import {
    selectPasswordRecoveryErrorCode,
    selectPasswordRecoveryLoading,
    selectPasswordRecoverySuccess,
    selectPasswordUpdateErrorCode,
    selectPasswordUpdateLoading,
    selectPasswordUpdateSuccess,
    selectUser
} from "../../store/user/userSelector";
import {normalizeEmail} from "../../utils/user-profile/normalizers";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const PasswordField = ({
                           id,
                           name,
                           label,
                           placeholder,
                           show,
                           onToggle,
                           touched,
                           errors,
                           forceError = false,
                           showPasswordAriaLabel,
                           hidePasswordAriaLabel
                       }) => {
    const hasError = Boolean(errors?.[name] && (touched?.[name] || forceError));

    return (
        <div className={"form-group mt-3"}>
            <label htmlFor={id} className={"form-label fw-semibold"}>{label}</label>
            <div className={`input-group rounded border ${hasError ? "border-danger" : "border-secondary-subtle"}`}>
                <Field
                    id={id}
                    name={name}
                    autoComplete={"off"}
                    type={show ? "text" : "password"}
                    className={"form-control border-0 shadow-none"}
                    placeholder={placeholder}
                />
                <button
                    type={"button"}
                    className={"input-group-text bg-white border-0 clickable-element"}
                    onClick={onToggle}
                    aria-label={show ? hidePasswordAriaLabel : showPasswordAriaLabel}
                >
                    <i className={`fa-regular ${show ? "fa-eye-slash" : "fa-eye"} ${hasError ? "text-danger" : "text-secondary"}`}></i>
                </button>
            </div>
            {
                hasError &&
                <div className={"text-danger small mt-1"}>
                    <i className={"fa-regular fa-circle-exclamation me-1"}></i>
                    {errors[name]}
                </div>
            }
        </div>
    );
};

const UserProfilePassword = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const passwordFormikRef = useRef(null);
    const recoveryFormikRef = useRef(null);
    const user = useSelector(selectUser);
    const passwordUpdateLoading = useSelector(selectPasswordUpdateLoading);
    const passwordUpdateSuccess = useSelector(selectPasswordUpdateSuccess);
    const passwordUpdateErrorCode = useSelector(selectPasswordUpdateErrorCode);
    const passwordRecoveryLoading = useSelector(selectPasswordRecoveryLoading);
    const passwordRecoverySuccess = useSelector(selectPasswordRecoverySuccess);
    const passwordRecoveryErrorCode = useSelector(selectPasswordRecoveryErrorCode);
    const [showPassword, setShowPassword] = useState({
        currentPassword: false,
        newPassword: false,
        confirmNewPassword: false
    });
    const [showRecoveryModal, setShowRecoveryModal] = useState(false);
    const [showRecoverySuccess, setShowRecoverySuccess] = useState(false);

    const translationsLoaded = useComponentTranslations("userProfilePasswordPage", {
        "en-US": enUS.userProfilePasswordPage,
        "pt-BR": ptBR.userProfilePasswordPage,
        "es-ES": esES.userProfilePasswordPage,
        "pt-PT": ptPT.userProfilePasswordPage
    });
    const normalizedUserMail = normalizeEmail(user?.mail);

    const validationSchema = Yup.object().shape({
        currentPassword: Yup.string()
            .required(t("userProfilePasswordPage:requiredField")),
        newPassword: Yup.string()
            .required(t("userProfilePasswordPage:requiredField"))
            .min(6, t("userProfilePasswordPage:passwordMinLength"))
            .test(
                "password-must-differ",
                t("userProfilePasswordPage:passwordMustDiffer"),
                (value, context) => {
                    if (!value || !context?.parent?.currentPassword) {
                        return true;
                    }
                    return value !== context.parent.currentPassword;
                }
            ),
        confirmNewPassword: Yup.string()
            .required(t("userProfilePasswordPage:requiredField"))
            .oneOf([Yup.ref("newPassword"), null], t("userProfilePasswordPage:passwordConfirmationMatching"))
    });
    const recoveryValidationSchema = Yup.object().shape({
        email: Yup.string()
            .trim()
            .email(t("userProfilePasswordPage:recoverInvalidEmail"))
            .required(t("userProfilePasswordPage:requiredField"))
            .test(
                "email-must-match-user",
                t("userProfilePasswordPage:recoverEmailMustMatchUser"),
                (value, context) => {
                    const normalizedValue = normalizeEmail(value);
                    if (!normalizedValue) {
                        return true;
                    }

                    if (!normalizedUserMail) {
                        return context.createError({
                            message: t("userProfilePasswordPage:recoverError_GENERIC")
                        });
                    }

                    return normalizedValue === normalizedUserMail;
                }
            )
    });

    useEffect(() => {
        dispatch(clearUserPasswordUpdateState());
        dispatch(clearUserPasswordRecoveryState());
        return () => {
            dispatch(clearUserPasswordUpdateState());
            dispatch(clearUserPasswordRecoveryState());
        };
    }, [dispatch]);

    useEffect(() => {
        if (!passwordUpdateSuccess) {
            return;
        }

        dispatch(addToast({
            type: "success",
            title: t("userProfilePasswordPage:saveSuccessTitle"),
            message: t("userProfilePasswordPage:saveSuccessMessage")
        }));

        dispatch(clearUserPasswordUpdateState());
        navigate("/user/profile");
    }, [dispatch, navigate, passwordUpdateSuccess, t]);

    useEffect(() => {
        if (!passwordUpdateErrorCode) {
            return;
        }

        if (passwordUpdateErrorCode === "TOKEN_REFRESH_FAILED") {
            dispatch(clearUserPasswordUpdateState());
            return;
        }

        if (passwordUpdateErrorCode === "CURRENT_PASSWORD_INVALID") {
            passwordFormikRef.current?.setFieldTouched("currentPassword", true, false);
            passwordFormikRef.current?.setFieldError("currentPassword", t("userProfilePasswordPage:error_CURRENT_PASSWORD_INVALID"));
            dispatch(clearUserPasswordUpdateState());
            return;
        }

        if (passwordUpdateErrorCode === "PASSWORD_INVALID") {
            passwordFormikRef.current?.setFieldTouched("newPassword", true, false);
            passwordFormikRef.current?.setFieldError("newPassword", t("userProfilePasswordPage:error_PASSWORD_INVALID"));
            dispatch(clearUserPasswordUpdateState());
            return;
        }

        const errorKey = `userProfilePasswordPage:error_${passwordUpdateErrorCode}`;
        const translatedMessage = t(errorKey);
        const message = translatedMessage === errorKey
            ? t("userProfilePasswordPage:error_GENERIC")
            : translatedMessage;

        dispatch(addToast({
            type: "danger",
            title: t("userProfilePasswordPage:title"),
            message,
            delay: 10000
        }));

        dispatch(clearUserPasswordUpdateState());
    }, [dispatch, passwordUpdateErrorCode, t]);

    useEffect(() => {
        if (!passwordRecoverySuccess) {
            return;
        }

        recoveryFormikRef.current?.setStatus(undefined);
        setShowRecoverySuccess(true);
        dispatch(clearUserPasswordRecoveryState());
    }, [dispatch, passwordRecoverySuccess]);

    useEffect(() => {
        if (!passwordRecoveryErrorCode) {
            return;
        }

        if (passwordRecoveryErrorCode === "EMAIL_REQUIRED" || passwordRecoveryErrorCode === "EMAIL_NOT_FOUND") {
            const errorMessageKey = passwordRecoveryErrorCode === "EMAIL_REQUIRED"
                ? "userProfilePasswordPage:recoverError_EMAIL_REQUIRED"
                : "userProfilePasswordPage:recoverError_EMAIL_NOT_FOUND";
            recoveryFormikRef.current?.setFieldTouched("email", true, false);
            recoveryFormikRef.current?.setFieldError("email", t(errorMessageKey));
            recoveryFormikRef.current?.setStatus(undefined);
            dispatch(clearUserPasswordRecoveryState());
            return;
        }

        const errorMessageKey = passwordRecoveryErrorCode === "PASSWORD_RECOVERY_SEND_FAILED"
            ? "userProfilePasswordPage:recoverError_PASSWORD_RECOVERY_SEND_FAILED"
            : "userProfilePasswordPage:recoverError_GENERIC";
        recoveryFormikRef.current?.setStatus({
            formError: t(errorMessageKey)
        });
        dispatch(clearUserPasswordRecoveryState());
    }, [dispatch, passwordRecoveryErrorCode, t]);

    const handleTogglePassword = (fieldName) => {
        setShowPassword((previousState) => ({
            ...previousState,
            [fieldName]: !previousState[fieldName]
        }));
    };

    const handleSubmit = (values, {setSubmitting}) => {
        dispatch(updateUserPassword({
            currentPassword: values.currentPassword,
            newPassword: values.newPassword
        }));
        setSubmitting(false);
    };
    const handleOpenRecoveryModal = () => {
        dispatch(clearUserPasswordRecoveryState());
        setShowRecoverySuccess(false);
        setShowRecoveryModal(true);
    };

    const handleCloseRecoveryModal = () => {
        if (passwordRecoveryLoading) {
            return;
        }
        setShowRecoveryModal(false);
        setShowRecoverySuccess(false);
        recoveryFormikRef.current?.resetForm();
        recoveryFormikRef.current?.setStatus(undefined);
        dispatch(clearUserPasswordRecoveryState());
    };

    const handleRecoverySubmit = (values, {setSubmitting, setStatus}) => {
        setStatus(undefined);
        dispatch(recoverUserPassword({
            email: normalizeEmail(values.email)
        }));
        setSubmitting(false);
    };

    if (!translationsLoaded) {
        return null;
    }

    return (
        <>
            <Page title={t("userProfilePasswordPage:title")} goBackLink={"/user/profile"} mt={"mt-n5"}>
                <div className={"card card-body border-0"}>
                    <Formik
                        innerRef={passwordFormikRef}
                        initialValues={{
                            currentPassword: "",
                            newPassword: "",
                            confirmNewPassword: ""
                        }}
                        validationSchema={validationSchema}
                        validateOnBlur={true}
                        validateOnChange={true}
                        onSubmit={handleSubmit}
                    >
                        {({errors, touched, isValid, dirty, values, submitCount}) => (
                            <Form noValidate={true}>
                                <PasswordField
                                    id={"currentPassword"}
                                    name={"currentPassword"}
                                    show={showPassword.currentPassword}
                                    touched={touched}
                                    errors={errors}
                                    forceError={Boolean(
                                        errors.currentPassword &&
                                        !values.currentPassword &&
                                        (values.newPassword || values.confirmNewPassword || submitCount > 0)
                                    )}
                                    label={t("userProfilePasswordPage:currentPassword")}
                                    placeholder={t("userProfilePasswordPage:currentPasswordPlaceholder")}
                                    onToggle={() => handleTogglePassword("currentPassword")}
                                    showPasswordAriaLabel={t("userProfilePasswordPage:showPasswordAria")}
                                    hidePasswordAriaLabel={t("userProfilePasswordPage:hidePasswordAria")}
                                />

                                <button
                                    type={"button"}
                                    className={"btn btn-link p-0 mt-2 text-decoration-none"}
                                    onClick={handleOpenRecoveryModal}
                                >
                                    {t("userProfilePasswordPage:forgotPassword")}
                                </button>

                                <PasswordField
                                    id={"newPassword"}
                                    name={"newPassword"}
                                    show={showPassword.newPassword}
                                    touched={touched}
                                    errors={errors}
                                    label={t("userProfilePasswordPage:newPassword")}
                                    placeholder={t("userProfilePasswordPage:newPasswordPlaceholder")}
                                    onToggle={() => handleTogglePassword("newPassword")}
                                    showPasswordAriaLabel={t("userProfilePasswordPage:showPasswordAria")}
                                    hidePasswordAriaLabel={t("userProfilePasswordPage:hidePasswordAria")}
                                />

                                <PasswordField
                                    id={"confirmNewPassword"}
                                    name={"confirmNewPassword"}
                                    show={showPassword.confirmNewPassword}
                                    touched={touched}
                                    errors={errors}
                                    label={t("userProfilePasswordPage:confirmNewPassword")}
                                    placeholder={t("userProfilePasswordPage:confirmNewPasswordPlaceholder")}
                                    onToggle={() => handleTogglePassword("confirmNewPassword")}
                                    showPasswordAriaLabel={t("userProfilePasswordPage:showPasswordAria")}
                                    hidePasswordAriaLabel={t("userProfilePasswordPage:hidePasswordAria")}
                                />

                                <div className={"d-grid mt-4"}>
                                    <button
                                        type={"submit"}
                                        className={"btn btn-primary"}
                                        disabled={!dirty || !isValid || passwordUpdateLoading}
                                    >
                                        {
                                            passwordUpdateLoading
                                                ? <i className={"fa-regular fa-ellipsis fa-fade fa-2xl"}/>
                                                : t("userProfilePasswordPage:saveNewPassword")
                                        }
                                    </button>
                                </div>
                            </Form>
                        )}
                    </Formik>
                </div>
            </Page>

            <Modal
                show={showRecoveryModal}
                onHide={handleCloseRecoveryModal}
                centered={true}
                backdrop={passwordRecoveryLoading ? "static" : true}
                keyboard={!passwordRecoveryLoading}
            >
                <Modal.Body className={"p-4"}>
                    {
                        showRecoverySuccess
                            ? (
                                <>
                                    <div className={"row justify-content-center mt-2"}>
                                        <div className={"col-auto"}>
                                            <i className={"fa-regular fa-circle-check text-success"} style={{fontSize: "58px"}}></i>
                                        </div>
                                    </div>
                                    <div className={"row mt-3"}>
                                        <div className={"col-12 text-center"}>
                                            <span className={"d-block fs-4 fw-semibold"}>{t("userProfilePasswordPage:recoverPasswordSuccessTitle")}</span>
                                            <span className={"d-block text-default mt-2"}>{t("userProfilePasswordPage:recoverPasswordSuccessMessage")}</span>
                                        </div>
                                    </div>
                                    <div className={"d-grid mt-4"}>
                                        <button
                                            type={"button"}
                                            className={"btn btn-primary"}
                                            onClick={handleCloseRecoveryModal}
                                        >
                                            {t("userProfilePasswordPage:recoverPasswordSuccessButton")}
                                        </button>
                                    </div>
                                </>
                            )
                            : (
                                <>
                                    <div className={"row justify-content-between align-items-start"}>
                                        <div className={"col-10"}>
                                            <span className={"fs-4 fw-semibold"}>{t("userProfilePasswordPage:recoverPasswordTitle")}</span>
                                        </div>
                                        <div className={"col-auto"}>
                                            <button
                                                type={"button"}
                                                className={"no-style-btn"}
                                                onClick={handleCloseRecoveryModal}
                                                disabled={passwordRecoveryLoading}
                                                aria-label={t("userProfilePasswordPage:recoverPasswordCloseAria")}
                                            >
                                                <i className={"fa-solid fa-xmark fs-4"}></i>
                                            </button>
                                        </div>
                                    </div>
                                    <div className={"row mt-2"}>
                                        <div className={"col-12"}>
                                            <span className={"d-block text-default"}>{t("userProfilePasswordPage:recoverPasswordDescription")}</span>
                                        </div>
                                    </div>
                                    <Formik
                                        innerRef={recoveryFormikRef}
                                        initialValues={{email: ""}}
                                        validationSchema={recoveryValidationSchema}
                                        validateOnBlur={true}
                                        validateOnChange={true}
                                        onSubmit={handleRecoverySubmit}
                                    >
                                        {({errors, touched, isValid, dirty, status}) => (
                                            <Form noValidate={true}>
                                                <div className={"form-group mt-3"}>
                                                    <label htmlFor={"recoveryEmail"} className={"form-label fw-semibold"}>
                                                        {t("userProfilePasswordPage:recoverEmailLabel")}
                                                    </label>
                                                    <Field
                                                        id={"recoveryEmail"}
                                                        name={"email"}
                                                        type={"email"}
                                                        className={`form-control ${touched.email && errors.email ? "is-invalid" : ""}`}
                                                        placeholder={t("userProfilePasswordPage:recoverEmailPlaceholder")}
                                                    />
                                                    {
                                                        touched.email && errors.email &&
                                                        <div className={"invalid-feedback d-block"}>{errors.email}</div>
                                                    }
                                                    {
                                                        status?.formError &&
                                                        <div className={"text-danger small mt-1"}>
                                                            <i className={"fa-regular fa-circle-exclamation me-1"}></i>
                                                            {status.formError}
                                                        </div>
                                                    }
                                                </div>

                                                <div className={"d-grid mt-4"}>
                                                    <button
                                                        type={"submit"}
                                                        className={"btn btn-primary"}
                                                        disabled={!dirty || !isValid || passwordRecoveryLoading}
                                                    >
                                                        {
                                                            passwordRecoveryLoading
                                                                ? <i className={"fa-regular fa-ellipsis fa-fade fa-2xl"}/>
                                                                : t("userProfilePasswordPage:recoverPasswordButton")
                                                        }
                                                    </button>
                                                </div>
                                            </Form>
                                        )}
                                    </Formik>
                                </>
                            )
                    }
                </Modal.Body>
            </Modal>
        </>
    );
};

export default UserProfilePassword;
