import React, {useEffect, useState, useCallback, useMemo} from "react";
import {useNavigate, useParams} from "react-router-dom";
import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import moment from "moment";
import AiEvaluationAnalysis from "../../components/ai/AiEvaluationAnalysis";
import {
    fetchEvaluationOnline, recoverEvaluation,
    resetFormSent
} from "../../store/online-evaluation/evaluationOnlineReducer";
import {fetchClient} from "../../store/client/clientReducer";
import {getEvaluation, getLoading, getSubmitLoading, getSubmitResult} from "../../store/online-evaluation/evaluationOnlineSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {calculateAge} from "../../utils/date/dateUtils";
import {Image} from "react-bootstrap";
import {isDesktop} from "react-device-detect";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EvaluationChartsComponent from "../../components/evaluation-components/EvaluationChartsComponent";
import ImageCarousel from "../../utils/imagecarousel/ImageCarousel";
import {calculateRQC, formatRQC} from "../../utils/physicalEvaluation/rqcFormula";
import DeleteModal from "../../components/modal/DeleteModal";
import {calculateIMC, formatIMC} from "../../utils/physicalEvaluation/imcFormula";
import he from "he";
import {
    buildOnlineEvaluationEditRoute,
    buildOnlineEvaluationsRoute
} from "../../utils/client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitError, isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const OnlineEvaluationView = () => {
    const {id, evaluationId, goBackTo} = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const selectedClient = useSelector(selectSelectedClient);
    const evaluationData = useSelector(getEvaluation);
    const loading = useSelector(getLoading);
    const submitLoading = useSelector(getSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const [isBibliographyOpen, setIsBibliographyOpen] = useState(false);
    const [showEvaluationDeleteModal, setShowEvaluationDeleteModal] = useState(false);
    const [deleteRequested, setDeleteRequested] = useState(false);
    const [isExpanded, setIsExpanded] = useState(false);
    const {t} = useTranslation("evaluationOnline");
    const backToUpdates = goBackTo === "updates";
    const currentClientId = Number(id);

    useComponentTranslations("evaluationOnline", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const percentualGordura = parseFloat((Number(evaluationData?.percentage) || 0).toFixed(2));
    const percentualMassaMagra = (100 - percentualGordura).toFixed(2);
    const massaGordaKg = evaluationData?.weightFat || 0;
    const massaMagraKg = evaluationData?.weightLean || 0;

    const photoImages = [
        evaluationData?.pictureFront && {id: 'front', url: evaluationData.pictureFront},
        evaluationData?.pictureSide && {id: 'side', url: evaluationData.pictureSide},
        evaluationData?.pictureBack && {id: 'back', url: evaluationData.pictureBack},
    ].filter(Boolean);

    const initialValues = useMemo(
        () => ({
            goal: evaluationData?.goal ?? "",
            idade: evaluationData?.idade ?? "",
            answerDate: evaluationData?.answerDate ?? "",
            height: evaluationData?.height ?? "",
            weight: evaluationData?.weight ?? "",
            chest: evaluationData?.chest ?? "",
            biceps: evaluationData?.biceps ?? "",
            forearm: evaluationData?.forearm ?? "",
            waist: evaluationData?.waist ?? "",
            abs: evaluationData?.abs ?? "",
            hip: evaluationData?.hip ?? "",
            thigh: evaluationData?.thigh ?? "",
        }),
        [evaluationData]
    );

    const fieldMapping = {
        goal: t("evaluationOnline:goal"),
        idade: t("evaluationOnline:age"),
        answerDate: t("evaluationOnline:answered"),
        height: t("evaluationOnline:height"),
        weight: t("evaluationOnline:weight"),
        chest: t("evaluationOnline:chest"),
        biceps: t("evaluationOnline:biceps"),
        forearm: t("evaluationOnline:forearm"),
        waist: t("evaluationOnline:waist"),
        abs: t("evaluationOnline:abs"),
        hip: t("evaluationOnline:hip"),
        thigh: t("evaluationOnline:thigh"),
    };

    const unitMapping = {
        height: "cm",
        weight: "kg",
        chest: "cm",
        biceps: "cm",
        forearm: "cm",
        waist: "cm",
        abs: "cm",
        hip: "cm",
        thigh: "cm",
    };

    const fieldSections = useMemo(
        () => ({
            goal: "evaluationDetails",
            idade: "evaluationDetails",
            height: "evaluationDetails",
            weight: "evaluationDetails",
            chest: "perimetry",
            biceps: "perimetry",
            forearm: "perimetry",
            waist: "perimetry",
            abs: "perimetry",
            hip: "perimetry",
            thigh: "perimetry",
        }), []);

    const sections = React.useMemo(() => {
        const grouped = [];
        Object.entries(initialValues).forEach(([id, value]) => {
            if (id === "answerDate") return;
            if (value === undefined || value === null || value === "") return;
            const section = fieldSections[id] || "evaluationDetails";
            let group = grouped.find((g) => g.section === section);
            if (!group) {
                group = {section, fields: []};
                grouped.push(group);
            }
            group.fields.push({id, value});
        });
        return grouped;
    }, [initialValues, fieldSections]);

    if (selectedClient && selectedClient.data_nascimento) {
        initialValues.idade = calculateAge(selectedClient.data_nascimento);
    }

    const rcqRaw = calculateRQC(
        evaluationData?.waist,
        evaluationData?.hip
    );

    const rcqFormatted = rcqRaw != null
        ? formatRQC(rcqRaw, selectedClient?.sexo, t)
        : "";

    const imcRaw = evaluationData?.imc != null
        ? evaluationData.imc
        : calculateIMC(evaluationData?.weight, evaluationData?.height);

    const imcFormatted = imcRaw != null
        ? formatIMC(imcRaw, t)
        : "";

    const hasPhotos =
        evaluationData?.pictureFront ||
        evaluationData?.pictureSide ||
        evaluationData?.pictureBack;

    const handleBibliography = () => {
        setIsBibliographyOpen(!isBibliographyOpen)
    };

    const handleGoBackPage = useCallback(() => {
        if (backToUpdates) {
            navigate(`/user/update/list/13`);
        } else
            navigate(buildOnlineEvaluationsRoute(id, "1"));
    }, [navigate, id, backToUpdates]);

    const handleSeeEdit = () => {
        navigate(buildOnlineEvaluationEditRoute(id, evaluationId));
    };

    const handleDeleteModal = () => {
        if (showEvaluationDeleteModal) {
            setDeleteRequested(false);
        }
        setShowEvaluationDeleteModal(prevState => !prevState)
    };

    const handleDeleteEvaluation = () => {
        dispatch(recoverEvaluation(
            {id: evaluationId, status: 1},
            {flow: EVALUATION_FLOWS.ONLINE_DELETE, clientId: currentClientId}
        ))
    };

    const handleConfirmDelete = () => {
        setDeleteRequested(true);
        handleDeleteEvaluation();
    };

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        if (evaluationId) {
            dispatch(fetchEvaluationOnline(evaluationId));
        }
    }, [dispatch, evaluationId]);

    useEffect(() => {
        if (deleteRequested && isMatchingSubmitSuccess(submitResult, {
            action: "delete",
            flow: EVALUATION_FLOWS.ONLINE_DELETE,
            clientId: currentClientId
        })) {
            setShowEvaluationDeleteModal(false);
            setDeleteRequested(false);
            handleGoBackPage();
        }
        if (deleteRequested && isMatchingSubmitError(submitResult, {
            action: "delete",
            flow: EVALUATION_FLOWS.ONLINE_DELETE,
            clientId: currentClientId
        })) {
            setDeleteRequested(false);
        }
    }, [currentClientId, deleteRequested, submitResult, handleGoBackPage]);

    return (
        <>
            <div className={"bg-default text-center text-white pt-2 d-none d-print-block"}>
                <div className={"row justify-content-center "}>
                    <div className={'col-12'}>
                        <Image fluid={true} style={{height: "33px"}}
                               className={"clickable-element"}
                               src={`https://cdn.mfitpersonal.com.br/assets/logo/logo-horizontal.svg`}/>
                    </div>
                </div>
            </div>
            <Page title={t("evaluationOnline:onlineEvaluation")} goBackLink={handleGoBackPage} loading={loading}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        {evaluationData?.answerDate && (
                            <div className={"card card-body border-0 mb-2 d-print-block"}>
                                <AiEvaluationAnalysis
                                    id={evaluationId}
                                    aiAnalysis={evaluationData.aiAnalysis}
                                    isExpanded={isExpanded}
                                    setIsExpanded={setIsExpanded}
                                />
                            </div>
                        )}
                        <div className={"card card-body border-0"}>
                            {evaluationData?.answerDate && (
                                <div className={"d-flex pb-2 row"}>
                                <span
                                    className={"fw-semibold me-2"}>{t("evaluationOnline:answered")}</span>
                                    <span>{moment(evaluationData.answerDate).format("L")}</span>
                                </div>
                            )}
                            {sections.map(({section, fields}) => (
                                <div key={section} className="mt-2">
                                    {section !== "evaluationDetails" && (
                                        <span className="fw-semibold d-block fs-5">
                                            {t(`evaluationOnline:${section}`)}
                                        </span>
                                    )}
                                    {fields.map(({id, value}) => {
                                        const isDate = id.toLowerCase().includes("date");
                                        const rawValue = isDate
                                            ? moment(value).format("L")
                                            : value;

                                        const displayValue =
                                            typeof rawValue === "string"
                                                ? he.decode(rawValue)
                                                : rawValue;
                                        return (
                                            <div key={id} className="mb-1 row">
                                                <label htmlFor={id} className="fw-semibold">
                                                    {fieldMapping[id] || id}
                                                </label>
                                                <span>
                                                   {displayValue}{unitMapping[id] || ""}
                                                </span>
                                            </div>
                                        );
                                    })}
                                    <hr className={"border-primary-subtle"}/>
                                </div>
                            ))}
                            <span className={"fw-semibold fs-5"}>
                               {t("evaluationOnline:result")}
                            </span>
                            {imcRaw != null && (
                                <div>
                                    <label className="fw-semibold">{t("evaluationOnline:imc")}</label>
                                    <div>
                                        {imcFormatted}
                                    </div>
                                </div>
                            )}
                            {rcqRaw != null && (
                                <div>
                                    <label className="fw-semibold">{t("evaluationOnline:rcq")}</label>
                                    <div>
                                        {rcqFormatted}
                                    </div>
                                </div>
                            )}
                            {evaluationData?.perimeterSum != null && (
                                <div>
                                    <label className="fw-semibold">{t("evaluationOnline:perimeterSum")}</label>
                                    <div>
                                        {evaluationData?.perimeterSum}cm
                                    </div>
                                </div>
                            )}
                            {evaluationData?.percentage && (
                                <div>
                                    <label className={"fw-semibold"}>{t("evaluationOnline:percentage")}</label>
                                    <div>
                                        {evaluationData.percentage}%
                                    </div>
                                </div>
                            )}
                            {evaluationData?.weightLean && (
                                <div>
                                    <span
                                        className={"fw-semibold"}>{t("evaluationOnline:weightLean")} </span>
                                    <div>
                                        {evaluationData.weightLean}Kgs
                                    </div>
                                </div>
                            )}
                            {evaluationData?.weightFat && (
                                <div>
                                    <span className={"fw-semibold"}>{t("evaluationOnline:weightFat")} </span>
                                    <div>
                                        {evaluationData.weightFat}Kgs
                                    </div>
                                </div>
                            )}
                        </div>
                        <div className={"p-1 bg-primary-subtle mt-3 rounded d-print-none"}>
                            <div className={"row d-flex align-items-center px-2"}>
                                <button
                                    className={"btn d-flex align-items-center justify-content-between w-100 clickable-element"}
                                    onClick={handleBibliography}
                                    aria-expanded={isBibliographyOpen}
                                    type="button"
                                >
                                    <span className={"fw-semibold"}>{t("evaluationOnline:bibliography")}</span>
                                    <i className={`fa-regular ${isBibliographyOpen ? "fa-chevron-up" : "fa-chevron-down"} ms-2`}/>
                                </button>
                            </div>
                            {isBibliographyOpen && (
                                <div className={"row"}>
                                    <div className={"col-12"}>
                                        <div className={"row p-2"}>
                                            <span>{t("evaluationOnline:bibliography1")}</span>
                                            <span className={"mt-2"}>{t("evaluationOnline:bibliography2")}</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <div className={"card card-body border-0 mt-4 no-page-break"}>
                            <EvaluationChartsComponent
                                chartTitle={t("evaluationOnline:charts")}
                                percentualTitle={t("evaluationOnline:fatPercentage")}
                                leanMassPercentageTitle={t("evaluationOnline:leanMass")}
                                leanMassPercentageValue={percentualMassaMagra}
                                fatMassPercentageTitle={t("evaluationOnline:fat")}
                                fatMassPercentageValue={percentualGordura}
                                doughnutValues={[percentualMassaMagra, percentualGordura]}
                                doughnutLabels={[t("evaluationOnline:leanMass"), t("evaluationOnline:fat")]}
                                leanFatMassTitle={t("evaluationOnline:leanFatMass")}
                                leanMassTitle={t("evaluationOnline:leanMass")}
                                leanMassValue={massaMagraKg}
                                fatMassTitle={t("evaluationOnline:fatMass")}
                                fatMassValue={massaGordaKg}
                                barValues={[massaMagraKg, massaGordaKg]}
                                barLabels={['', '']}
                            />
                        </div>
                        {hasPhotos && (
                            <div className="card card-body border-0 mt-4 d-print-none">
                                <h5 className="fw-semibold text-center">{t("evaluationOnline:evaluationPhotos")}</h5>
                                <ImageCarousel images={photoImages}/>
                            </div>
                        )}
                        <div className={"card card-body border-0 mt-2 d-print-none"}>
                            {isDesktop && (
                                <div className={"col-12 my-2 d-print-none"}>
                                    <button
                                        type={"button"}
                                        className={"btn btn-primary w-100 no-print"}
                                        onClick={() => {
                                            setIsExpanded(true);
                                            setTimeout(() => window.print(), 500)
                                        }}>
                                        {t("evaluationOnline:print")}
                                    </button>
                                </div>
                            )}
                            <button className={"btn btn-outline-primary w-100"} onClick={handleGoBackPage}>{t("evaluationOnline:backEvaluations")}</button>
                            <button className={"btn btn-outline-primary w-100 mt-2"} onClick={handleSeeEdit}>
                                {t("evaluationOnline:edit")}
                            </button>
                            <button className={"btn btn-outline-danger w-100 mt-2"} onClick={handleDeleteModal}>
                                {t("evaluationOnline:delete")}
                            </button>
                        </div>
                    </div>
                </div>
            </Page>
            <DeleteModal
                show={showEvaluationDeleteModal}
                onClose={handleDeleteModal}
                onConfirm={handleConfirmDelete}
                deleteTitle={t("evaluationOnlineComponents:areYouSure")}
                confirmLabel={t("evaluationOnlineComponents:yesDelete")}
                closeLabel={t("evaluationOnlineComponents:close")}
                isSubmitting={deleteRequested && submitLoading}
            />
        </>
    );
};

export default OnlineEvaluationView;
