import {useTranslation} from "react-i18next";
import ShareModal from "../modal/ShareModal";
import EvaluationOptionsModal from "../evaluation-components/EvaluationOptionsModal";
import DeleteModal from "../modal/DeleteModal";

export default function CustomEvaluationActionsButtons({state, handlers, shareWhatsLink}) {
    const {t} = useTranslation();

    return(
        <>
            <EvaluationOptionsModal
                show={state.showOptionsModal}
                onClose={handlers.closeOptionsModal}
                onOpen={() => handlers.goView()}
                onShare={handlers.openShareModal}
                onEdit={() => handlers.goEdit()}
                onDelete={handlers.openDeleteModal}
                title={t('customEvaluation:whatYouWant')}
                openLabel={t('customEvaluation:open')}
                shareLabel={t('customEvaluation:share')}
                editLabel={t('customEvaluation:edit')}
                deleteLabel={t('customEvaluation:delete')}
            />
            <ShareModal
                show={state.showShareModal}
                onClose={handlers.closeShareModal}
                link={shareWhatsLink}
                onSend={handlers.sendWhatsApp}
                onCopy={handlers.copyLink}
                shareTitle={t('customEvaluation:shareTitle')}
                sendLabel={t('customEvaluation:send')}
                copyLabel={t('customEvaluation:copyLink')}
                closeLabel={t('customEvaluation:close')}
            />
            <DeleteModal
                show={state.showDeleteModal}
                onClose={handlers.closeDeleteModal}
                onConfirm={handlers.handleConfirmDelete}
                deleteTitle={t('customEvaluation:deleteTitle')}
                confirmLabel={t('customEvaluation:confirm')}
                closeLabel={t('customEvaluation:close')}
                isSubmitting={state.deleteSubmitting}
            />
        </>
    )
}
