import {Field, useField} from "formik";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "../../components/custom-evaluation/locales/es-es.json";
import ptPT from "../../components/custom-evaluation/locales/pt-pt.json";
import ptBR from "../../components/custom-evaluation/locales/pt-br.json";
import enUS from "../../components/custom-evaluation/locales/en-us.json";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";

const defaultAnswerTypes = [
    {value: 'text', label: 'Campo de texto', labelKey: 'textField'},
    {value: 'number', label: 'Campo numérico', labelKey: 'numberField'},
    {value: 'image', label: 'Campo de imagem', labelKey: 'imageField'},
];

const CustomModelField = ({
                              questionName,
                              typeName,
                              valueName,
                              onRemove,
                              answerTypes = defaultAnswerTypes,
                              className = '',
                          }) => {
    const [questionField] = useField(questionName);
    const [valueMeta] = useField(valueName);
    const {t} = useTranslation();
    useComponentTranslations('customEvaluationComponent', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})
    syncMomentLocale(i18n.language);

    return (

        <div className={`card border my-2 ${className}`}>
            <div className="card-body">
                <div className="mb-3">
                    <label htmlFor={questionName} className="form-label fw-semibold">
                        {t("customEvaluationComponent:question")}
                    </label>
                    <input
                        {...questionField}
                        id={questionName}
                        type="text"
                        className={"form-control"}
                    />
                </div>
                <div className="mb-3">
                    <label htmlFor={typeName} className="form-label fw-semibold">
                        {t("customEvaluationComponent:responseType")}
                    </label>
                    <Field
                        as="select"
                        name={typeName}
                        id={typeName}
                        className={"form-select"}
                    >
                        {answerTypes.map((option) => (
                            <option key={option.value} value={option.value}>
                                {t(`customEvaluationComponent:type.${option.labelKey}`)}
                            </option>
                        ))}
                    </Field>
                </div>
                <div className="mb-3">
                    {valueMeta.touched && valueMeta.error && (
                        <div className={"text-danger mt-1 text-sm"}>
                            {valueMeta.error}
                        </div>
                    )}
                </div>
                <div className={"text-center"}>
                    <button
                        type="button"
                        className={"btn btn-link text-primary p-0"}
                        onClick={onRemove}
                    >
                        {t("customEvaluationComponent:deleteQuestion")}
                    </button>
                </div>
            </div>
        </div>
    )
}

export default CustomModelField;
