import {Offcanvas} from "react-bootstrap";
import OffcanvasCloseButton from "./OffcanvasCloseButton";
import OffcanvasSheetHandle from "./OffcanvasSheetHandle";
import useResponsiveOffcanvasPlacement from "./useResponsiveOffcanvasPlacement";

const AppOffcanvasShell = ({
    show,
    onHide,
    children,
    bodyClassName = "",
    className = "",
    showMobileChrome = true,
    showDesktopCloseButton = true,
    closeButtonAriaLabel = "Close",
    mobileSheetSizing = "fixed"
}) => {
    const {placement, isMobileSheet} = useResponsiveOffcanvasPlacement();
    const mobileSheetSizingClassName = mobileSheetSizing === "content"
        ? "app-offcanvas--sheet-fit-height"
        : "app-offcanvas--sheet-height";
    const shellClassName = `app-offcanvas ${
        isMobileSheet
            ? `app-offcanvas--sheet ${mobileSheetSizingClassName} app-offcanvas--sheet-rounded`
            : "app-offcanvas--panel app-offcanvas--width-md w-100"
    } ${className}`.trim();
    const offcanvasBodyClassName = `app-offcanvas__body ${bodyClassName}`.trim();

    return (
        <Offcanvas
            show={show}
            onHide={onHide}
            placement={placement}
            className={shellClassName}
        >
            <Offcanvas.Body className={offcanvasBodyClassName}>
                {isMobileSheet && showMobileChrome && (
                    <div className={"app-offcanvas__chrome"}>
                        <div className={"app-offcanvas__handle-wrap"}>
                            <OffcanvasSheetHandle/>
                        </div>
                        <div className={"app-offcanvas__close-overlay app-offcanvas__close-overlay--sheet"}>
                            <OffcanvasCloseButton onClick={onHide} ariaLabel={closeButtonAriaLabel}/>
                        </div>
                    </div>
                )}

                {!isMobileSheet && showDesktopCloseButton && (
                    <div className={"app-offcanvas__close-overlay app-offcanvas__close-overlay--panel"}>
                        <OffcanvasCloseButton onClick={onHide} ariaLabel={closeButtonAriaLabel}/>
                    </div>
                )}

                {typeof children === "function" ? children({isMobileSheet}) : children}
            </Offcanvas.Body>
        </Offcanvas>
    );
};

export default AppOffcanvasShell;
