import {useDispatch, useSelector} from "react-redux";
import {useEffect, useState, useRef} from "react";
import {fetchMonthlyFrequency, setMonthlyFrequency} from "../../store/frequency-training/frequencyTrainingReducer";
import {useNavigate, useParams} from "react-router-dom";
import {selectFrequencyTrainingLoading, selectMonthlyFrequency} from "../../store/frequency-training/frequencyTrainingSelector";
import FullCalendar from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/daygrid";
import interactionPlugin from "@fullcalendar/interaction";
import "./../../assets/css/calendar.scss";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import LoadingBlock from "../../components/loader/LoadingBlock";

const FrequencyTrainingMonth = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id, month, year} = useParams();
    const {t, i18n} = useTranslation();
    const monthlyFrequency = useSelector(selectMonthlyFrequency);
    const loading = useSelector(selectFrequencyTrainingLoading)
    const [totalDays, setTotalDays] = useState(0);
    const [currentDate, setCurrentDate] = useState(new Date());
    const calendarRef = useRef(null);
    const today = new Date();
    const currentYear = today.getFullYear();
    const currentMonth = today.getMonth();

    useComponentTranslations('frequencyTraining', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});


    const handleGoBack = () => {
        navigate(`/user/client/${id}`)
    }

    const handlePrevMonth = () => {
        const newDate = new Date(currentDate);
        newDate.setMonth(newDate.getMonth() - 1);
        setCurrentDate(newDate);
        dispatch(fetchMonthlyFrequency({
            id,
            year: newDate.getFullYear(),
            month: newDate.getMonth() + 1,
        }));
        if (calendarRef.current) {
            const calendarApi = calendarRef.current.getApi();
            calendarApi.gotoDate(newDate);
        }
    };

    const handleNextMonth = () => {
        const newDate = new Date(currentDate);
        newDate.setMonth(newDate.getMonth() + 1);
        setCurrentDate(newDate);
        dispatch(fetchMonthlyFrequency({
            id,
            year: newDate.getFullYear(),
            month: newDate.getMonth() + 1,
        }));
        if (calendarRef.current) {
            const calendarApi = calendarRef.current.getApi();
            calendarApi.gotoDate(newDate);
        }
    };

    const handleToday = () => {
        const today = new Date();
        setCurrentDate(today);
        dispatch(fetchMonthlyFrequency({
            id,
            year: today.getFullYear(),
            month: today.getMonth() + 1,
        }));
        if (calendarRef.current) {
            const calendarApi = calendarRef.current.getApi();
            calendarApi.gotoDate(today);
        }
    };

    const handleYearView = () => {
        navigate(`/user/client/training-frequency/${id}/year`);
    };

    useEffect(() => {
        if (month && year) {
            const date = new Date(Number(year), Number(month) - 1, 1);
            setCurrentDate(date);
            dispatch(fetchMonthlyFrequency({id, year: Number(year), month: Number(month)}));
        } else {
            const today = new Date();
            setCurrentDate(today);
            dispatch(fetchMonthlyFrequency({id, year: today.getFullYear(), month: today.getMonth() + 1}));
        }
        return () => dispatch(setMonthlyFrequency(null))
    }, [dispatch, id, month, year]);

    useEffect(() => {
        let totalHighlightedDays = 0;
        if (monthlyFrequency && monthlyFrequency.days) {
            totalHighlightedDays = Object.values(monthlyFrequency.days).filter(isHighlighted => isHighlighted).length;
        }
        setTotalDays(totalHighlightedDays);
    }, [monthlyFrequency]);

    return (
        <Page title={t("frequencyTraining:pageTitle")} goBackLink={handleGoBack} xl={"3"}>
            <div className={'card card-body mt-n3 border-0'}>
                <div className={"monthly-view"}>
                    <div className="calendar-navigation">
                        <div className="row justify-content-between pt-2 pb-4">
                            <div className="col-4 align-self-center">
                                <button onClick={handlePrevMonth} className={" no-style-btn text-primary"}>
                                    <i className={"fa-regular fa-chevron-left small"}></i> {t("frequencyTraining:previous")}
                                </button>
                            </div>
                            <div className="col-4 text-center" onClick={handleToday}>
                                <span className="d-block fw-bold fs-5 lh-1">{currentDate.getFullYear()}</span>
                                <span className={"text-capitalize"}>
                                    {currentDate.toLocaleString(i18n.language, {month: "long"})}
                                </span>
                            </div>
                            <div className="col-4 align-self-center text-end">
                                {
                                    !(currentDate.getFullYear() > currentYear ||
                                        (currentDate.getFullYear() === currentYear && currentDate.getMonth() >= currentMonth)) &&
                                    <button onClick={handleNextMonth} className={" no-style-btn text-primary"}>
                                        {t("frequencyTraining:next")} <i className={"fa-regular fa-chevron-right small"}></i>
                                    </button>
                                }
                            </div>
                        </div>
                    </div>
                    {
                        !loading ?
                            <FullCalendar
                                key={currentDate.toISOString()}
                                ref={calendarRef}
                                plugins={[dayGridPlugin, interactionPlugin]}
                                initialView="dayGridMonth"
                                initialDate={currentDate}
                                locale={i18n.language}
                                headerToolbar={false}
                                fixedWeekCount={false}
                                firstDay={1}
                                showNonCurrentDates={false}
                                dayCellClassNames={({date}) => {
                                    const day = date.getDate();
                                    if (monthlyFrequency?.days[day]) {
                                        return ['highlighted-day'];
                                    }
                                    return ['disabled-day'];
                                }}
                                selectable={false}
                                dateClick={(info) => info.jsEvent.preventDefault()}
                            /> :
                            <LoadingBlock height={"330px"}/>
                    }

                    <div className="row ">
                        <div className="col-12 text-end">
                            <button className={"no-style-btn text-primary"} onClick={handleYearView}>{t("frequencyTraining:seeFullYear")}</button>
                        </div>
                    </div>
                </div>
            </div>
            {
                totalDays > 0 &&
                <div className={"card card-body border-0 mt-3"}>
                    <div className={'row'}>
                        <div className={'col-auto'}>
                            <RoundedIcon icon={"fa-calendar-check"}/>
                        </div>
                        <div className={"col-auto text-default"}>
                            <span className={'d-block fw-semibold '}>{t("frequencyTraining:yourClientTrained")}</span>
                            <span className={"d-block lh-1"}>
                             <span className={"fw-semibold fs-3 text-primary"}>{totalDays}</span> <span
                                className={"text-primary"}>{totalDays === 1 ? t("frequencyTraining:dayThisMonth") : t("frequencyTraining:daysThisMonth")}</span>
                        </span>
                        </div>
                    </div>
                </div>
            }
        </Page>
    );
};

export default FrequencyTrainingMonth;
