import React, {useCallback, useEffect, useState} from "react";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {useDispatch, useSelector} from "react-redux";
import {isFeedbackLoading, selectResolvedFeedback} from "../../store/feedback/feedbackSelector";
import {fetchResolvedFeedbacks} from "../../store/feedback/feedbackReducer";
import EmptySet from "../../components/empty-set/EmptySet";
import ResolvedFeedbackCard from "../../components/feedbacks/ResolvedFeedbackCard";
import {getFeedbackIntensity} from "../../utils/workout/Workout";
import FeedbackFilterModal from "../../components/feedbacks/FeedbackFilterModal";
import Pagination from "../../components/pagination/Pagination";

const FeedbackResolved = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    useComponentTranslations('feedbackList', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const resolvedFeedbacks = useSelector(selectResolvedFeedback);

    const loading = useSelector(isFeedbackLoading);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredFeedbacks, setFilteredFeedbacks] = useState([]);
    const [showFeedbackModal, setShowFeedbackModal] = useState(false)
    const [filters, setFilters] = useState({
        feedbackSource: [],
        intensity: [],
        comments: [],
    })
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(10);
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentItems = filteredFeedbacks?.slice(indexOfFirstItem, indexOfLastItem);
    const totalItems = filteredFeedbacks?.length || 0;
    const pagesToShow = 5;
    const handleFeedbackModal = useCallback(() => setShowFeedbackModal(v => !v), []);

    const selectFeedbackType = (type) => {
        setFilters((prevState) => {
            const alreadySelected = prevState.feedbackSource.includes(type);
            return {
                ...prevState,
                feedbackSource: alreadySelected
                    ? prevState.feedbackSource.filter((item) => item !== type)
                    : [...prevState.feedbackSource, type],
            };
        });
    };

    const selectIntensity = (intensity) => {
        setFilters((prevState) => {
            const isSelected = prevState.intensity.includes(intensity);
            return {
                ...prevState,
                intensity: isSelected
                    ? prevState.intensity.filter((item) => item !== intensity)
                    : [...prevState.intensity, intensity],
            };
        })
    }

    const toggleComment = (commentType) => {
        setFilters((prevState) => {
            const alreadySelected = prevState.comments.includes(commentType);
            return {
                ...prevState,
                comments: alreadySelected
                    ? prevState.comments.filter((item) => item !== commentType)
                    : [...prevState.comments, commentType]
            }
        });
    }

    const clearFilters = () => {
        setFilters({
            feedbackSource: [],
            intensity: [],
            comments: [],
        });
    };

    const areFiltersActive = () => {
        return (
            filters.feedbackSource.length > 0 ||
            filters.intensity.length > 0 ||
            filters.comments.length > 0
        );
    };

    useEffect(() => {
        dispatch(fetchResolvedFeedbacks())
    }, [dispatch]);

    useEffect(() => {
        setFilteredFeedbacks(resolvedFeedbacks);
    }, [resolvedFeedbacks]);

    useEffect(() => {
        const totalPages = Math.ceil(totalItems / itemsPerPage);
        if (currentPage > totalPages && totalPages > 0) {
            setCurrentPage(totalPages);
        }
    }, [resolvedFeedbacks, currentPage, totalItems, itemsPerPage]);

    useEffect(() => {
        let filtered = resolvedFeedbacks || [];

        if (searchQuery.trim() !== "") {
            filtered = filtered.filter(resolvedFeedbacks =>
                resolvedFeedbacks.clientName.toLowerCase().includes(searchQuery.toLowerCase())
            );
        }

        if (filters.feedbackSource.length > 0) {
            filtered = filtered.filter(resolvedFeedbacks =>
                filters.feedbackSource.includes(resolvedFeedbacks.fonteFeedback)
            );
        }

        if (filters.intensity.length > 0) {
            filtered = filtered.filter(resolvedFeedbacks =>
                filters.intensity.includes(getFeedbackIntensity(resolvedFeedbacks.borgNota))
            );
        }

        if (filters.comments.length > 0) {
            filtered = filtered.filter(resolvedFeedbacks => {
                const hasComment = resolvedFeedbacks.feedback && resolvedFeedbacks.feedback.trim() !== "";
                if (filters.comments.includes("with") && filters.comments.includes("without")) {
                    return true;
                }
                if (filters.comments.includes("with")) {
                    return hasComment;
                }
                if (filters.comments.includes("without")) {
                    return !hasComment;
                }
                return false;
            });
        }

        setFilteredFeedbacks(filtered);
    }, [resolvedFeedbacks, searchQuery, filters]);

    return (
        <>
            <div className={"row"}>
                <div className={"col-12 pt-3"}>
                    <div className={"card card-body border-0 bg-primary-subtle d-flex align-items-start"}>
                        <div className={"row text-md fw-semibold"}>
                            <div className={"col-2 align-self-center "}>
                                <i className={"text-primary fa-regular fa-circle-exclamation flex-shrink-0 fa-2xl"}/>
                            </div>
                            <div className={"col-10 me-n5"}>
                                <span className={"text-primary flex-grow-1"}>{t("feedbackList:200feedbacks")}</span>
                            </div>
                        </div>
                    </div>
                    {resolvedFeedbacks && resolvedFeedbacks.length === 0 && !loading &&
                        <div className={"row"}>
                            <div className={"col-12 pt-4"}>
                                <div className={"card card-body border-0"}>
                                    <EmptySet icon={"fa-comments"} message={t("feedbackList:noResolvedFeedbacks")}/>
                                </div>
                            </div>
                        </div>
                    }
                    {resolvedFeedbacks && resolvedFeedbacks.length > 0 && !loading &&
                        <>
                            <div className={"row"}>
                                {resolvedFeedbacks.length > 5 &&
                                    <div className={"d-flex mt-1 pt-1 text-center"}>
                                        <div className={"input-group mx-auto"}>
                                            <input
                                                className={"form-control bg-white"}
                                                placeholder={t("feedbackList:searchByClient")}
                                                value={searchQuery}
                                                onChange={(e) => setSearchQuery(e.target.value)}
                                            />
                                            <span className={'input-group-text bg-white'}>
                                                <i className={'fa-regular fa-magnifying-glass'}/>
                                            </span>
                                        </div>
                                        <button
                                            className={`input-group-text ms-2 ${areFiltersActive() ? "text-primary btn-feedback-primary" : "bg-white"}`}
                                            onClick={handleFeedbackModal}>
                                            <i className="fa-regular fa-sliders-simple"/>
                                        </button>
                                    </div>
                                }
                            </div>
                        </>
                    }
                    {
                        filteredFeedbacks && filteredFeedbacks.length === 0 && !loading &&
                        <div className={'row'}>
                            <div className={'col-12 pt-4'}>
                                <div className={'card card-body border-0'}>
                                    <EmptySet icon={"fa-comments"} message={t("feedbackList:noFeedbacksMatching")}/>
                                </div>
                            </div>
                        </div>
                    }
                    <div className={"row justify-content-center d-flex mt-3"}>
                        <div className={"col-12"}>
                            {
                                currentItems.map((feedback) =>
                                    <ResolvedFeedbackCard
                                        key={feedback.id}
                                        resolvedFeedback={feedback}
                                     />
                                )
                            }
                        </div>
                    </div>
                    {
                        totalItems > itemsPerPage &&
                        <div className={"row justify-content-center"}>
                            <div className={"col-12"}>
                                <Pagination
                                    currentPage={currentPage}
                                    totalItems={totalItems}
                                    itemsPerPage={itemsPerPage}
                                    onPageChange={setCurrentPage}
                                    pagesToShow={pagesToShow}
                                />
                            </div>
                        </div>
                    }
                </div>
            </div>
            <FeedbackFilterModal
                isOpen={showFeedbackModal}
                onClose={handleFeedbackModal}
                title={t("feedbackList:filters")}
                filters={filters}
                onSelectTraining={() => selectFeedbackType(0)}
                onSelectAerobic={() => selectFeedbackType(1)}
                onSelectExtraTraining={() => selectFeedbackType(2)}
                onSelectIntensity={selectIntensity}
                onToggleComment={toggleComment}
                onApply={handleFeedbackModal}
                onClear={clearFilters}
                t={t}
            />
        </>
    )
}

export default FeedbackResolved;
