import {takeLatest, all, call, put} from 'redux-saga/effects';
import {generateAiPushAPI, getEvaluationAnalysisAiAPI, summarizeAnamnesisAPI, generateWorkoutAPI} from "../../api/ai-actions/aiActions";
import {handleError} from "../../utils/error/sagaErrorHandling";

import {
    summarizeAnamnesis,
    onError,
    setSummarizedAnamnesis,
    setAiPush,
    setGeneratedWorkout, generateWorkout,
    generateAiPush, evaluationAnalysis, setEvaluationAnalysis, setAiError
} from "./aiActionsReducer";


function* summarizeAnamnesisAsync(action) {
    try {
        const response = yield call(summarizeAnamnesisAPI, action.payload);
        yield put(setSummarizedAnamnesis(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onSummarizeAnamnesis() {
    yield takeLatest(summarizeAnamnesis.type, summarizeAnamnesisAsync);
}

export function* generateAiPushAsync(action) {

    try {
        const response = yield call(generateAiPushAPI, action.payload);
        yield put(setAiPush(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onGenerateAiPush() {
    yield takeLatest(generateAiPush.type, generateAiPushAsync);
}

export function* generateWorkoutAsync(action) {
    try {
        const response = yield call(generateWorkoutAPI, action.payload);
        yield put(setGeneratedWorkout(response.data));
    } catch (error) {
        yield put(setAiError(true));
        // yield call(handleError, error, onError)
    }
}

export function* fetchEvaluationAnalysisAsync(action) {
    try {
        const response = yield call(getEvaluationAnalysisAiAPI, action.payload);
        yield put(setEvaluationAnalysis(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onGenerateWorkout() {
    yield takeLatest(generateWorkout.type, generateWorkoutAsync);
}

export function* onFetchEvaluationAnalysis() {
    yield takeLatest(evaluationAnalysis.type, fetchEvaluationAnalysisAsync);
}

export function* aiActionsSaga() {
    yield all([
        call(onSummarizeAnamnesis),
        call(onGenerateAiPush),
        call(onFetchEvaluationAnalysis),
        call(onGenerateWorkout)
    ]);
}
