import {useEffect, useRef} from "react";
import {useRegisterRetentionAccessMutation} from "../../store/retention/retentionApi";

export const RETENTION_ACCESS_EVENT_STORAGE_KEY = "mfit:user:retention-access:last-dispatched-at:v1";
export const RETENTION_ACCESS_EVENT_THROTTLE_MS = 60 * 60 * 1000;

let pendingRetentionAccessRequest = null;

const readRetentionAccessTimestamp = () => {
    if (typeof window === "undefined") {
        return null;
    }

    try {
        const storedValue = window.localStorage.getItem(RETENTION_ACCESS_EVENT_STORAGE_KEY);
        const parsedValue = Number(storedValue);

        return Number.isFinite(parsedValue) && parsedValue > 0 ? parsedValue : null;
    } catch (error) {
        return null;
    }
};

const writeRetentionAccessTimestamp = (value) => {
    if (typeof window === "undefined") {
        return false;
    }

    try {
        window.localStorage.setItem(RETENTION_ACCESS_EVENT_STORAGE_KEY, String(value));
        return true;
    } catch (error) {
        return false;
    }
};

const isRetentionAccessEventDue = (lastDispatchedAt, now) => (
    !lastDispatchedAt || (now - lastDispatchedAt) >= RETENTION_ACCESS_EVENT_THROTTLE_MS
);

const useRetentionAccessEvent = () => {
    const [registerRetentionAccess] = useRegisterRetentionAccessMutation();
    const hasAttemptedRef = useRef(false);

    useEffect(() => {
        if (hasAttemptedRef.current) {
            return;
        }

        hasAttemptedRef.current = true;

        const now = Date.now();
        const lastDispatchedAt = readRetentionAccessTimestamp();

        if (!isRetentionAccessEventDue(lastDispatchedAt, now) || pendingRetentionAccessRequest) {
            return;
        }

        pendingRetentionAccessRequest = registerRetentionAccess()
            .unwrap()
            .then(() => {
                writeRetentionAccessTimestamp(Date.now());
            })
            .catch(() => undefined)
            .finally(() => {
                pendingRetentionAccessRequest = null;
            });
    }, [registerRetentionAccess]);
};

export default useRetentionAccessEvent;
