import Page from "../../components/page/Page";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import {useDispatch} from "react-redux";
import {addToast} from "../../store/toast/toastReducer";
import {useTranslation} from "react-i18next";
import {handleSendWhatsApp} from "../../utils/handlers/handler";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const FriendInvite = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const coupon = "VEMPRAMFIT";
    const message = t("friendInvite:couponMessage");
    useComponentTranslations('friendInvite', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleCopyLink = () => {
        navigator.clipboard.writeText(message)
            .then(() => {
                dispatch(addToast({
                    type: "success",
                    message: t("friendInvite:copySuccessMessage"),
                    title: t("friendInvite:copySuccessTitle")
                }));
            })
            .catch(err => {
                console.error('Failed to copy: ', err);
            });
    };

    return (
        <Page title={t("friendInvite:inviteFriend")} mt={"mt-n5"}>
            <div className={'card card-body'}>
                <div className={'row justify-content-center d-flex'}>
                    <div className={'col-12'}>
                        <div className={'row justify-content-center mt-2'}>
                            <div className={"col-auto"}>
                                <RoundedIcon icon={"fa-user-group"} size={"lg"}/>
                            </div>
                        </div>
                        <div className={"row mt-3"}>
                            <div className={"col-12 text-center"}>
                                <span className={"fs-4 fw-semibold"}>{t("friendInvite:inviteFriendTitle")}</span>
                            </div>
                            <div className={"col-12 text-center mt-2"}>
                                <span>{t("friendInvite:inviteDescription")}</span>
                            </div>
                            <div className={"col-12 text-center mt-4"}>
                                <div className={"card card-body bg-secondary-subtle border-0 p-2"}>
                                    <span className={"fw-semibold"}>{coupon}</span>
                                </div>
                            </div>
                            <div className={'col-12 pt-4 text-center'}>
                                <div className={'d-grid '}>
                                    <button className={'btn btn-success text-white'} onClick={() => handleSendWhatsApp(null, message)}>
                                        <i className="fa-brands fa-whatsapp"></i>
                                        &nbsp;{t("friendInvite:sendViaWhatsApp")}
                                    </button>
                                </div>
                                <div className={'d-grid mt-2'}>
                                    <button className={'btn btn-primary'} onClick={handleCopyLink}>
                                        {t("friendInvite:copy")}
                                    </button>
                                </div>
                            </div>
                            <div className={'col-12 pt-4 text-center'}>
                                <span>
                                    <span className={"fw-semibold"}>{t("friendInvite:attention")}</span> {t("friendInvite:couponRestriction")} <span className={"fw-semibold"}>{t("friendInvite:brazil")}</span>
                                </span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </Page>
    );
}

export default FriendInvite;
