import Modal from "react-bootstrap/Modal";
import {Field, Form, Formik} from "formik";
import {useEffect} from "react";
import {useDispatch, useSelector} from "react-redux";
import {fetchFcRep, saveFcRep} from "../../store/evaluation/evaluationReducer";
import {selectFcRep, isFcRepLoading} from "../../store/evaluation/evaluationSelector";
import {ModalBody} from "react-bootstrap";
import LoadingBlock from "../loader/LoadingBlock";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const FcRepModal = ({show, handleFcRepModal, clientId}) => {
    const dispatch = useDispatch();
    const {t} = useTranslation();
    const fcRep = useSelector(selectFcRep);
    const isLoading = useSelector(isFcRepLoading);
    useComponentTranslations('evaluationComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        if (!fcRep) {
           dispatch(fetchFcRep(clientId));
        }
    }, [fcRep, clientId, dispatch]);

    return (
        <Modal show={show} onHide={handleFcRepModal} centered>
            <ModalBody>
                <div className={"row"}>
                    <span className={"fw-semibold h5"}>
                        {t("evaluationComponent:addFrequency")}
                    </span>
                    <div className={"pb-2"}>
                        {
                            isLoading &&
                            <LoadingBlock/>
                        }
                        {
                            !isLoading &&
                            <Formik
                                initialValues={{frequencyInput: fcRep?.bpmRest ?? ''}}
                                enableReinitialize={true}
                                onSubmit={(values) => {
                                    const dataToSend = {clientId, bpmRest: values.frequencyInput};
                                    dispatch(saveFcRep(dataToSend));
                                    handleFcRepModal();
                                }}
                            >
                                <Form>
                                    <div className="bg-primary-subtle rounded py-2 px-2 mb-3">
                                        <span className={"fw-bold"}>{t("evaluationComponent:instructions")}:</span>
                                        <span className={"d-block"}>
                                                {t("evaluationComponent:theStudent")}
                                            <span className={"fw-semibold"}>
                                                {t("evaluationComponent:rest")}</span>, {t("evaluationComponent:restExplanation")}.
                                            </span>
                                        <span>
                                            {t("evaluationComponent:heartbeatExplanation")}
                                            <span className={"fw-semibold"}> {t("evaluationComponent:sixtySeconds")}</span>.
                                        </span>
                                    </div>
                                    <div className="mb-3">
                                        <label htmlFor="frequencyInput" className="form-label fw-semibold pt-2">
                                            {t("evaluationComponent:restingHeartRate")}
                                        </label>
                                        <Field
                                            name="frequencyInput"
                                            type="number"
                                            placeholder="120"
                                            className="form-control"
                                        />
                                    </div>
                                    <button type="submit"
                                            className="btn btn-primary w-100 mb-2"
                                            disabled={isLoading}
                                    >
                                        {t("evaluationComponent:save")}
                                    </button>
                                </Form>
                            </Formik>
                        }
                        <button className={"btn btn-outline-primary w-100"}
                                onClick={(e) => {
                                    e.preventDefault();
                                    handleFcRepModal();
                                }}
                        >
                            {t("evaluationComponent:close")}
                        </button>
                    </div>
                </div>
            </ModalBody>
        </Modal>
    );
}

export default FcRepModal;
