import {Offcanvas} from "react-bootstrap";
import {useDispatch, useSelector} from "react-redux";
import {chatBotSelector} from "../../store/menu/menuSelector";
import {toggleChatBot} from "../../store/menu/menuReducer";

import ChatBot from "./ChatBot";

const ChatBotOffCanvas = () => {
    const dispatch = useDispatch();
    const show = useSelector(chatBotSelector);

    const screenSize = () => {
        return window.innerHeight - 160 + "px";
    };
    const handleBot = () => {
        dispatch(toggleChatBot());
    };

    return (
        <Offcanvas show={show} placement={'end'} onHide={handleBot}>
            <Offcanvas.Body>
                <ChatBot show={show} onClose={handleBot} screenSize={screenSize}/>
            </Offcanvas.Body>
        </Offcanvas>
    );
};

export default ChatBotOffCanvas;
