import React from 'react';
import {Modal} from 'react-bootstrap';
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import ptPT from "./locales/pt-pt.json";
import esES from "./locales/es-es.json";

const NeuromotorModal = ({isOpen, onClose, pageConfig}) => {

    const {t} = useTranslation();
    useComponentTranslations('neuromotorsComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT})
    return (
        <Modal show={isOpen} onHide={onClose} size="lg" centered>
            <Modal.Body>
                <div className={"card mt-2"}>
                    <div className={"py-2"}>
                        {pageConfig.page.testTitle &&
                            <span className="card-title text-center fw-semibold px-2">{pageConfig.page.testTitle}</span>
                        }
                        <div className={"table-responsive"}>
                            <table
                                className={'table table-striped mt-2'}
                            >
                                <thead>
                                <tr className="text-center">
                                    <th scope="col"
                                        className="sticky-column bg-light text-center"
                                        style={{
                                            width: "70px",
                                            minWidth: "80px",
                                            left: 0,
                                            zIndex: 2
                                        }}>{t("neuromotorsComponent:age")}</th>

                                    {pageConfig.containsExtremes && (
                                        <th scope="col"
                                            className="text-nowrap">{t("neuromotorsComponent:very_weak")}</th>
                                    )}
                                    <th scope="col">{t("neuromotorsComponent:weak")}</th>
                                    <th scope="col"
                                        className="text-nowrap">{t("neuromotorsComponent:below_average")}</th>
                                    <th scope="col" className="text-nowrap">{t("neuromotorsComponent:average")}</th>
                                    <th scope="col"
                                        className="text-nowrap">{t("neuromotorsComponent:above_average")}</th>
                                    {pageConfig.containsExtremes && (
                                        <th scope="col"
                                            className="text-nowrap">{t("neuromotorsComponent:very_good")}</th>
                                    )}
                                    <th scope="col" className="text-nowrap">{t("neuromotorsComponent:excellent")}</th>
                                </tr>
                                </thead>
                                <tbody>
                                {pageConfig.table?.completeRows.map((data, index) => (
                                    <tr key={index}
                                        className={pageConfig.table.ageIndex === data.age ? 'table-primary' : ''}>
                                        <td
                                            className="text-nowrap sticky-column bg-white text-center"
                                            style={{left: 0, zIndex: 1}}
                                        >
                                            {data.age}
                                        </td>
                                        {pageConfig.containsExtremes && (
                                            <td className="text-nowrap">{data["very_weak"]}</td>
                                        )}
                                        <td className="text-nowrap text-center">{data.weak}</td>
                                        <td className="text-nowrap text-center">{data["below_average"]}</td>
                                        <td className="text-nowrap text-center">{data.average}</td>
                                        <td className="text-nowrap text-center">{data["above_average"]}</td>
                                        {pageConfig.containsExtremes && (
                                            <td className="text-nowrap">{data["very_good"]}</td>
                                        )}
                                        <td className="text-nowrap text-center">{data.excellent}</td>
                                    </tr>
                                ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                <div className={"pt-2"}>
                    <button className="btn btn-outline-primary w-100" onClick={onClose}>
                        <span>{t("neuromotorsComponent:close")}</span>
                    </button>
                </div>
            </Modal.Body>
        </Modal>
    );
};

export default NeuromotorModal;