import Modal from "react-bootstrap/Modal";
import React, {useEffect, useMemo, useRef, useState} from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {
    createWorkoutPresetDefaultName,
    getWorkoutPresetNameValidationError,
    normalizeWorkoutPresetName
} from "./workoutPresetValidation";

const SaveCurrentPresetModal = ({
    show,
    onHide,
    onSubmit,
    loading = false,
    defaultName = ""
}) => {
    const {t} = useTranslation();
    const [name, setName] = useState(() => createWorkoutPresetDefaultName(defaultName));
    const [submitAttempted, setSubmitAttempted] = useState(false);
    const [nameTouched, setNameTouched] = useState(false);
    const nameInputRef = useRef(null);

    useComponentTranslations("workoutPresetComponent", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        setName(createWorkoutPresetDefaultName(defaultName));
        setSubmitAttempted(false);
        setNameTouched(false);
    }, [defaultName, show]);

    const nameError = useMemo(() => getWorkoutPresetNameValidationError(name, t), [name, t]);
    const showNameError = Boolean(nameError) && (submitAttempted || nameTouched);

    const handleSubmit = () => {
        setSubmitAttempted(true);

        if (nameError) {
            nameInputRef.current?.focus();
            return;
        }

        onSubmit?.(normalizeWorkoutPresetName(name));
    };

    return (
        <Modal centered show={show} onHide={onHide}>
            <Modal.Body>
                <div className="row">
                    <div className="col-12">
                        <span className="fw-semibold fs-5 d-block">{t("workoutPresetComponent:saveCurrentAsPreset")}</span>
                        <span className="text-secondary">{t("workoutPresetComponent:saveCurrentDescription")}</span>
                    </div>
                    <div className="col-12 mt-3">
                        <label className="form-label fw-semibold">{t("workoutPresetComponent:name")}</label>
                        <input
                            ref={nameInputRef}
                            className={`form-control ${showNameError ? "is-invalid" : ""}`}
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            onBlur={() => setNameTouched(true)}
                            placeholder={t("workoutPresetComponent:namePlaceholder")}
                        />
                        {showNameError && (
                            <div className="invalid-feedback">
                                {nameError}
                            </div>
                        )}
                    </div>
                    <div className="col-12 mt-4">
                        <button type="button" className="btn btn-primary w-100" disabled={loading} onClick={handleSubmit}>
                            {t("workoutPresetComponent:savePreset")}
                        </button>
                    </div>
                    <div className="col-12 mt-2">
                        <button type="button" className="btn btn-outline-primary w-100" onClick={onHide}>
                            {t("workoutPresetComponent:cancel")}
                        </button>
                    </div>
                </div>
            </Modal.Body>
        </Modal>
    );
};

export default SaveCurrentPresetModal;
