import {useEffect, useMemo, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import Modal from "react-bootstrap/Modal";
import {Trans, useTranslation} from "react-i18next";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import {fetchClient} from "../../store/client/clientReducer";
import {fetchClientGroups} from "../../store/client-group/clientGroupReducer";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {selectClientGroups} from "../../store/client-group/clientGroupSelector";
import {
    clearDeleteExtraTraining,
    clearExecuteExtraTraining,
    clearExtraTrainingMutations,
    clearSendExtraTraining,
    deleteExtraTraining,
    executeExtraTraining,
    fetchExtraTrainingList,
    sendExtraTraining
} from "../../store/extratraining/extraTrainingReducer";
import {
    selectDeleteExtraTrainingLoading,
    selectDeleteExtraTrainingSuccess,
    selectExecuteExtraTrainingLoading,
    selectExecuteExtraTrainingSuccess,
    selectExtraTrainingListErrorCode,
    selectExtraTrainingList,
    selectExtraTrainingListStatus,
    selectSendExtraTrainingLoading,
    selectSendExtraTrainingSuccess
} from "../../store/extratraining/extraTrainingSelector";
import CardButtonAdd from "../../components/card/CardButtonAdd";
import ExtraTrainingCard from "../../components/extra-training/ExtraTrainingCard";
import ExtraTrainingEditorForm from "../../components/extra-training/ExtraTrainingEditorForm";
import ChangeStatus from "../../components/utils/change-status/ChangeStatus";

const ExtraTraining = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {clientId} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const clientGroups = useSelector(selectClientGroups);
    const extraTrainingList = useSelector(selectExtraTrainingList);
    const listStatus = useSelector(selectExtraTrainingListStatus);
    const listErrorCode = useSelector(selectExtraTrainingListErrorCode);
    const sendLoading = useSelector(selectSendExtraTrainingLoading);
    const deleteLoading = useSelector(selectDeleteExtraTrainingLoading);
    const executeLoading = useSelector(selectExecuteExtraTrainingLoading);
    const sendSuccess = useSelector(selectSendExtraTrainingSuccess);
    const deleteSuccess = useSelector(selectDeleteExtraTrainingSuccess);
    const executeSuccess = useSelector(selectExecuteExtraTrainingSuccess);

    const [selectedTraining, setSelectedTraining] = useState(null);
    const [showSendModal, setShowSendModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [showExecuteModal, setShowExecuteModal] = useState(false);

    useComponentTranslations("extraTrainingUser", {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR});

    useEffect(() => {
        dispatch(fetchClient(clientId));
        dispatch(fetchClientGroups());
        dispatch(fetchExtraTrainingList(clientId));
        return () => dispatch(clearExtraTrainingMutations());
    }, [clientId, dispatch]);

    useEffect(() => {
        if (sendSuccess) {
            setShowSendModal(false);
            setSelectedTraining(null);
            dispatch(clearSendExtraTraining());
        }
    }, [dispatch, sendSuccess]);

    useEffect(() => {
        if (deleteSuccess) {
            setShowDeleteModal(false);
            setSelectedTraining(null);
            dispatch(clearDeleteExtraTraining());
        }
    }, [deleteSuccess, dispatch]);

    useEffect(() => {
        if (executeSuccess) {
            setShowExecuteModal(false);
            setSelectedTraining(null);
            dispatch(clearExecuteExtraTraining());
        }
    }, [dispatch, executeSuccess]);

    const groupOptions = useMemo(
        () => (clientGroups || []).map(group => ({value: group.id, label: group.nome})),
        [clientGroups]
    );
    const emptyStateBenefits = [
        {icon: "fa-regular fa-dumbbell", text: t("extraTrainingUser:emptyBenefitRoutine")},
        {icon: "fa-regular fa-clipboard-list", text: t("extraTrainingUser:emptyBenefitInstructions")},
        {icon: "fa-regular fa-calendar-days", text: t("extraTrainingUser:emptyBenefitDate")},
        {icon: "fa-regular fa-chart-line-up", text: t("extraTrainingUser:emptyBenefitConsistency")}
    ];

    const timeZone = useMemo(() => Intl.DateTimeFormat().resolvedOptions().timeZone, []);
    const loading = listStatus === "idle" || listStatus === "loading";
    const showEmptyState = listStatus === "success" && extraTrainingList.length === 0;
    const showList = listStatus === "success" && extraTrainingList.length > 0;
    const showListError = listStatus === "error";
    const listErrorMessage = t(`extraTrainingUser:errorMessages.${listErrorCode}`, {
        defaultValue: t("extraTrainingUser:listLoadErrorText")
    });

    const handleGoBackPage = () => navigate(`/user/client/${clientId}`);
    const handleCreate = () => navigate(`/user/client/${clientId}/extratraining/create`);
    const handleRetryList = () => dispatch(fetchExtraTrainingList(clientId));

    const handleOpenSendModal = (extraTraining) => {
        setSelectedTraining(extraTraining);
        setShowSendModal(true);
    };

    const handleCloseSendModal = () => {
        if (!sendLoading) {
            setShowSendModal(false);
        }
    };

    const handleCloseDeleteModal = () => {
        if (!deleteLoading) {
            setShowDeleteModal(false);
        }
    };

    const handleCloseExecuteModal = () => {
        if (!executeLoading) {
            setShowExecuteModal(false);
        }
    };

    const handleDelete = () => {
        if (!selectedTraining) {
            return;
        }
        dispatch(deleteExtraTraining({id: Number(clientId), extraTrainingId: selectedTraining.id}));
    };

    const handleExecute = () => {
        if (!selectedTraining) {
            return;
        }
        dispatch(executeExtraTraining({id: Number(clientId), extraTrainingId: selectedTraining.id}));
    };

    const handleSendSubmit = (values) => {
        if (!selectedTraining) {
            return;
        }

        dispatch(sendExtraTraining({
            id: Number(clientId),
            extraTrainingId: selectedTraining.id,
            formData: {
                clients: values.clients,
                groups: values.groups,
                notificar: values.notificar,
                timeZone
            }
        }));
    };

    const sendInitialValues = useMemo(() => ({
        clients: [],
        groups: [],
        notificar: false
    }), []);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
            />
            <Page contentHeader={false} loading={loading}>
                <div className="row justify-content-center d-flex">
                    <div className="col-12">
                        <div className="card card-body border-0">
                            {showListError && (
                                <div className="row justify-content-center">
                                    <div className="col-12 col-lg-10">
                                        <div className="card card-body border-danger-subtle bg-danger-subtle text-center gap-3">
                                            <div className="text-danger fs-3">
                                                <i className="fa-regular fa-circle-exclamation"/>
                                            </div>
                                            <div>
                                                <span className="fw-semibold d-block">{t("extraTrainingUser:listLoadErrorTitle")}</span>
                                                <span className="d-block text-muted">{listErrorMessage}</span>
                                            </div>
                                            <div className="d-grid gap-2">
                                                <button className="btn btn-primary" onClick={handleRetryList}>
                                                    {t("extraTrainingUser:retry")}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                            {showEmptyState && (
                                <div className="row justify-content-center">
                                    <div className="col-12 col-lg-10">
                                        <div className="d-flex flex-column align-items-center gap-4">
                                            <RoundedIcon icon={"fa-file-plus"} size={"lg"}/>
                                            <div className="col-10 col-md-9">
                                                        <span className="d-block fw-semibold fs-5 lh-sm text-center text-default">
                                                            <Trans
                                                                i18nKey="extraTrainingUser:emptyTitleRich"
                                                                components={{highlight: <span className="text-primary"/>}}
                                                            />
                                                        </span>
                                            </div>
                                            <div className="d-flex flex-column w-100 text-start">
                                                {emptyStateBenefits.map((benefit, index) => (
                                                    <div
                                                        key={benefit.text}
                                                        className={`d-flex align-items-center gap-2 py-2 ${index < emptyStateBenefits.length - 1 ? "border-bottom border-light-subtle" : ""}`}
                                                    >
                                                        <RoundedIcon icon={benefit.icon} size={"xs"} className="flex-shrink-0"/>
                                                        <span className="fw-semibold text-default">{benefit.text}</span>
                                                    </div>
                                                ))}
                                            </div>
                                            <div className="d-grid w-100">
                                                <button className="btn btn-primary w-100" onClick={handleCreate}>
                                                    {t("extraTrainingUser:addExtraTraining")}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                            {showList && (
                                <>
                                    <CardButtonAdd text={t("extraTrainingUser:addExtraTraining")} handleClick={handleCreate}/>
                                    {extraTrainingList.map(item => (
                                        <ExtraTrainingCard
                                            key={item.id}
                                            extraTraining={item}
                                            onEdit={() => navigate(`/user/client/${clientId}/extratraining/edit/${item.id}`)}
                                            onSend={() => handleOpenSendModal(item)}
                                            onDelete={() => {
                                                setSelectedTraining(item);
                                                setShowDeleteModal(true);
                                            }}
                                            onExecute={() => {
                                                setSelectedTraining(item);
                                                setShowExecuteModal(true);
                                            }}
                                        />
                                    ))}
                                </>
                            )}
                        </div>
                    </div>
                </div>
            </Page>

            <Modal
                show={showSendModal}
                onHide={handleCloseSendModal}
                centered
                backdrop={sendLoading ? "static" : true}
                keyboard={!sendLoading}
            >
                <Modal.Body>
                    <div className="row justify-content-between align-items-center pb-3">
                        <div className="col-auto">
                            <span className="fw-semibold fs-5">{t("extraTrainingUser:sendTrainingTo")}</span>
                        </div>
                        <div className={`col-auto ${sendLoading ? "" : "clickable-element"}`} onClick={handleCloseSendModal}>
                            <i className="fa-regular fa-times"/>
                        </div>
                    </div>
                    <ExtraTrainingEditorForm
                        key={selectedTraining?.id || "send-extra-training"}
                        initialValues={sendInitialValues}
                        onSubmit={handleSendSubmit}
                        loading={sendLoading}
                        submitLabel={t("extraTrainingUser:save")}
                        showTrainingFields={false}
                        showRecipients={true}
                        groupOptions={groupOptions}
                        excludedClientId={Number(clientId)}
                        showCloseButton={true}
                        closeLabel={t("extraTrainingUser:close")}
                        onClose={handleCloseSendModal}
                    />
                </Modal.Body>
            </Modal>

            <Modal
                show={showDeleteModal}
                onHide={handleCloseDeleteModal}
                centered
                backdrop={deleteLoading ? "static" : true}
                keyboard={!deleteLoading}
            >
                <Modal.Body>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation pb-2 pt-2"}
                        iconColor={"text-danger"}
                        title={t("extraTrainingUser:deleteTitle")}
                        subtitle={t("extraTrainingUser:deleteSubtitle")}
                    />
                    <div className="d-grid gap-2 pt-3 ">
                        <button className="btn btn-danger" onClick={handleDelete} disabled={deleteLoading}>
                            {t("extraTrainingUser:deleteConfirm")}
                        </button>
                        <button className="btn btn-outline-danger" onClick={handleCloseDeleteModal} disabled={deleteLoading}>
                            {t("extraTrainingUser:close")}
                        </button>
                    </div>
                </Modal.Body>
            </Modal>

            <Modal
                show={showExecuteModal}
                onHide={handleCloseExecuteModal}
                centered
                backdrop={executeLoading ? "static" : true}
                keyboard={!executeLoading}
            >
                <Modal.Body>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation pb-2 pt-2"}
                        iconColor={"text-primary"}
                        title={t("extraTrainingUser:executeTitle")}
                        subtitle={t("extraTrainingUser:executeSubtitle")}
                    />
                    <div className="d-grid gap-2 pt-3">
                        <button className="btn btn-primary" onClick={handleExecute} disabled={executeLoading}>
                            {t("extraTrainingUser:executeConfirm")}
                        </button>
                        <button className="btn btn-outline-primary" onClick={handleCloseExecuteModal} disabled={executeLoading}>
                            {t("extraTrainingUser:close")}
                        </button>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    );
};

export default ExtraTraining;
