import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect, useMemo} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import LoadingBlock from "../../components/loader/LoadingBlock";
import EmptySet from "../../components/empty-set/EmptySet";
import {getLoading, getPhysicalList} from "../../store/physical-evaluation/physicalEvaluationSelector";
import {chartFields} from "../../utils/physicalEvaluation/chartFields";
import {fetchClient} from "../../store/client/clientReducer";
import {getAllPhysical} from "../../store/physical-evaluation/physicalEvaluationReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import 'chart.js/auto';
import ChartCard from "../../components/charts/ChartCard";
import {buildClientPhysicalRoute} from "../../utils/client/evaluationRoutes";
import {formatDate as formatDateValue} from "../../utils/translation/localeUtils";

const PhysicalEvaluationCharts = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id} = useParams();
    const { t, i18n } = useTranslation();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const physicalList = useSelector(getPhysicalList);
    useComponentTranslations('physicalEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const sortedPhysicalList = useMemo(() => {
        if (!physicalList || physicalList.length === 0) return [];
        return [...physicalList].sort((a, b) => {
            const da = new Date(a.data || a.sentDate);
            const db = new Date(b.data || b.sentDate);
            return da - db;
        });
    }, [physicalList]);

    const handleGoBack = () => {
        navigate(buildClientPhysicalRoute(id));
    }

    const hasNoData = useMemo(() => {
        if (!sortedPhysicalList || sortedPhysicalList.length < 2) return true;
        return sortedPhysicalList.every(physical => {
            if (!physical.data && !physical.sentDate) return true;
            return chartFields.every(field => {
                const value = physical[field.id];
                return value === undefined || value === null || value === 0 || value === "";
            });
        });
    }, [sortedPhysicalList]);

    const chartLabels = useMemo(() => {
        if (!sortedPhysicalList || sortedPhysicalList.length === 0) return [];
        return sortedPhysicalList.map(physical => {
            const date = physical.data || physical.sentDate;
            if (!date) return '';
            return formatDateValue(date, i18n.language);
        });
    }, [i18n.language, sortedPhysicalList]);

    const compositionFields = useMemo(() => {
        if (!sortedPhysicalList || sortedPhysicalList.length < 2) return [];
        return chartFields
            .filter(field => field.category === "composicao")
            .map(field => ({
                ...field,
                label: t(`physicalEvaluation:table.${field.labelKey}`)
            }))
    }, [sortedPhysicalList, t]);

    const perimetryFields = useMemo(() => {
        if (!sortedPhysicalList || sortedPhysicalList.length < 2) return [];
        return chartFields
            .filter(field => field.category === "perimetria")
            .map(field => ({
                ...field,
                label: t(`physicalEvaluation:table.${field.labelKey}`)
            }))
    }, [sortedPhysicalList, t]);

    const transformedData = useMemo(() => {
        if (!sortedPhysicalList || sortedPhysicalList.length === 0) return {};
        const data = {};
        chartFields.forEach(field => {
            data[field.id] = [];
        });
        sortedPhysicalList.forEach(physical => {
            chartFields.forEach(field => {
                if (field.id === "percentage") {
                    data[field.id].push(physical.percentage ?? 0);
                } else {
                    data[field.id].push(physical[field.id] ?? 0);
                }
            });
        });
        return data;
    }, [sortedPhysicalList]);

    useEffect(() => {
        dispatch(fetchClient(id));
        dispatch(getAllPhysical({clientId: id, status: 0, type: 0}));
    }, [dispatch, id]);

    return (
        <>
            <AvatarHeader
                md={"12"} lg={"12"} xl={"8"}
                showGoBack={handleGoBack}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"} lg={"12"} md={"12"} xl={"8"}>
                <div className={"row"}>
                    <div className={"col-12"}>
                        {loading || loadingClient ? (
                            <div className={"text-center mt-4"}>
                                <LoadingBlock/>
                            </div>
                        ) : hasNoData ? (
                            <div className={"card card-body border-0"}>
                                <EmptySet
                                    icon={"fa-regular fa-folder-open"}
                                    message={t("physicalEvaluation:chartsEmpty")}
                                />
                            </div>
                        ) : (
                            <>
                                <div className={"row pt-2"}>
                                    {compositionFields.map(field => (
                                        <ChartCard
                                            key={field.id}
                                            field={field}
                                            dataValues={transformedData[field.id] || []}
                                            chartLabels={chartLabels}
                                            textButton={""}
                                        />
                                    ))}
                                </div>
                                <span className={"mb-3 fs-5 fw-semibold"}>{t("physicalEvaluation:perimetry")}</span>
                                <div className={"row"}>
                                    {perimetryFields.map(field => (
                                        <ChartCard
                                            key={field.id}
                                            field={field}
                                            dataValues={transformedData[field.id] || []}
                                            chartLabels={chartLabels}
                                            textButton={""}
                                        />
                                    ))}
                                </div>
                            </>
                        )}
                    </div>
                </div>
            </Page>
        </>
    )
}

export default PhysicalEvaluationCharts;
