import {handleError} from "../../utils/error/sagaErrorHandling";
import {all, call, put, takeLatest} from 'redux-saga/effects';

import {
    fetchFrequency,
    setFrequency, onError
} from "./frequencyReducer";

import {
    fetchFrequencyAPI,
} from "../../api/frequency-report/frequencyActions";

export function* fetchFrequencyAsync(action) {
    try {
        const {start, end, type} = action.payload
        const response = yield call(fetchFrequencyAPI, start, end, type);
        yield put(setFrequency(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchFrequency() {
    yield takeLatest (fetchFrequency.type, fetchFrequencyAsync);
}


export function* frequencySaga() {
    yield all([
        call(onFetchFrequency),
    ])
}