import React from "react";
import {Offcanvas, OffcanvasBody} from "react-bootstrap";
import {protocolData} from "../../utils/physicalEvaluation/protocolData";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import ptPT from "./locales/pt-pt.json";
import esES from "./locales/es-es.json";

const PhysicalEvaluationMenu = ({show, onHide, handleBack, handleGoForm}) => {
    const {t} = useTranslation();
    useComponentTranslations('physicalEvaluationsComponent', {
        'en-US': enUS,
        'pt-BR': ptBR,
        'es-ES': esES,
        'pt-PT': ptPT
    });

    return (
        <Offcanvas show={show} onHide={onHide} placement={'bottom'} style={{height: "90vh", borderRadius: 0}}
                   className="h-screen">
            <OffcanvasBody>
                <div className={'row justify-content-start'}>
                    <div className={'col-auto clickable-element'}>
                        <span className={"text-xs"} onClick={handleBack}>
                            <i className={'fa-regular fa-chevron-left'}/>
                            {t("physicalEvaluationsComponent:back")}
                        </span>
                    </div>
                </div>
                <div className={"row px-1 pt-2 text-title"}>
                    <span className={"fw-semibold"}>{t("physicalEvaluationsComponent:skinfold")}</span>
                    <span>{t("physicalEvaluationsComponent:chooseFormula")}</span>
                </div>
                <div className={"row p-3 align-self-center align-items-center gap-2"}>
                    {protocolData.map(protocol => (
                        <React.Fragment key={protocol.id}>
                            <div className={"card card-body clickable-element"}
                                 onClick={() => handleGoForm(protocol.id)}>
                                <span>{protocol.name}</span>
                            </div>
                        </React.Fragment>
                    ))}
                    <hr className={"border-primary-subtle"}/>
                </div>
            </OffcanvasBody>
        </Offcanvas>
    )
}

export default PhysicalEvaluationMenu;