import WorkoutIcon from "../rounded-icon/WorkoutIcon";
import Text from "../utils/emoji/Text";
import moment from "moment/moment";
import {getDifficulty, getObjective} from "../../utils/workout/Workout";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";

const WorkoutRoutineCardSimple = ({workout, onToggle, selected, gender = "m"}) => {
    const {t} = useTranslation();
    useComponentTranslations('routineWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleToggleClick = () => {
        onToggle(workout.id, !selected);
    };

    return (
        <div className="card card-body">
            <div className="row d-flex">
                <div className="col-2   text-center align-self-center clickable-element" onClick={handleToggleClick}>
                    <WorkoutIcon obj={workout.objetivo} gender={gender}/>
                </div>
                <div className="col-8  align-self-center clickable-element" onClick={handleToggleClick}>
                    <span className="fw-semibold d-block">
                        <Text>{workout.nome}</Text>
                    </span>
                    <span className="d-block text-md">
                        <i className="fa-regular fa-calendar-lines"></i>&nbsp;&nbsp;
                        {moment(workout.dataInicio).format("L")} - {moment(workout.dataFim).format("L")}
                      </span>
                    <div className="row justify-content-center d-flex mt-1">
                        <div className="col-12">
                            <div className="row d-flex text-muted small">
                                <div className="col-auto">
                                    {t(`workoutRoutine:${getObjective(workout.objetivo)}`)} | {t(`workoutRoutine:${getDifficulty(workout.dificuldade)}`)}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div className={"col-2 align-self-center"}>
                    <input
                        className={"form-check"}
                        type="checkbox"
                        checked={selected}
                        onChange={(e) => onToggle(workout.id, e.target.checked)}
                    />
                </div>
            </div>
        </div>
    );
};

export default WorkoutRoutineCardSimple;
