import {useCallback, useEffect, useMemo, useRef, useState} from "react";
import {imageResizer} from "../imageresize/imageResizer";
import uploadFile from "../fileupload/s3FileUpload";

import RoundedIcon from "../../components/rounded-icon/RoundedIcon";

const EvaluationImageUpload = ({
                         onImagesUpload,
                         user,
                         selectedClient,
                         existingImages = [],
                         slots,
                         basePath,
                         Anexar
                     }) => {
    const initialPhotos = useMemo(
        () =>
            Array(slots)
                .fill(null)
                .map(() => ({ preview: null, loading: false, uploadedUrl: "" })),
        [slots]
    );

    const [photos, setPhotos] = useState(initialPhotos);

    const onImagesUploadRef = useRef(onImagesUpload);
    useEffect(() => {
        onImagesUploadRef.current = onImagesUpload;
    }, [onImagesUpload]);

    const lastUrlsRef = useRef("");
    useEffect(() => {
        const urls = photos.map(p => p.uploadedUrl).filter(Boolean);
        const signature = urls.join("|");
        if (signature !== lastUrlsRef.current) {
            lastUrlsRef.current = signature;
            onImagesUploadRef.current?.(urls);
        }
    }, [photos]);

    const getInitialPhotos = useCallback(() => {
        const newPhotos = [...initialPhotos];
        existingImages.slice(0, slots).forEach((img, idx) => {
            const url = img && (typeof img === "object" ? img.url : img);
            if (url) newPhotos[idx] = { preview: url, uploadedUrl: url, loading: false };
        });
        return newPhotos;
    }, [existingImages, initialPhotos, slots]);

    const existingUrls = useMemo(
        () =>
            (existingImages || [])
                .map(img => (typeof img === "object" ? img?.url : img))
                .filter(Boolean),
        [existingImages]
    );
    const existingSig = useMemo(() => existingUrls.join("|"), [existingUrls]);

    useEffect(() => {
        if (!existingSig) return;
        setPhotos(getInitialPhotos());
    }, [existingSig, getInitialPhotos]);

    const handleFileChange = useCallback(
        async (event, index) => {
            const file = event.target.files && event.target.files[0];
            if (!file) return;

            const localPreview = URL.createObjectURL(file);

            setPhotos(prev =>
                prev.map((p, i) =>
                    i === index ? { ...p, loading: true, preview: localPreview } : p
                )
            );

            try {
                const resized = await imageResizer(file);
                const uploadedUrl = await uploadFile(
                    resized,
                    user.id,
                    selectedClient.id,
                    basePath
                );

                setPhotos(prev =>
                    prev.map((p, i) =>
                        i === index
                            ? { preview: uploadedUrl, uploadedUrl, loading: false }
                            : p
                    )
                );

                URL.revokeObjectURL(localPreview);
            } catch (error) {
                console.error(error);
                setPhotos(prev =>
                    prev.map((p, i) =>
                        i === index ? { ...p, loading: false } : p
                    )
                );
            } finally {
                if (event.target) event.target.value = "";
            }
        },
        [user?.id, selectedClient?.id, basePath]
    );

    const removeImage = useCallback((index) => {
        setPhotos(prev => {
            const current = prev[index];
            if (current?.preview && String(current.preview).startsWith("blob:")) {
                try { URL.revokeObjectURL(current.preview); } catch {}
            }
            return prev.map((p, i) =>
                i === index ? { preview: null, uploadedUrl: "", loading: false } : p
            );
        });
    }, []);

    useEffect(() => {
        return () => {
            photos.forEach(p => {
                if (p?.preview && String(p.preview).startsWith("blob:")) {
                    try { URL.revokeObjectURL(p.preview); } catch {}
                }
            });
        };
    }, [photos]);

    return (
        <div className={"mt-2"}>
            <div className={"row"}>
                {photos.map((photo, index) => (
                    <div key={index} className={"col-6 col-sm-6 mb-3 align-self-center"}>
                        <div className={"d-flex flex-column align-items-center"}>
                            {photo.preview ? (
                                <div className={"position-relative"}>
                                    <img
                                        src={photo.preview}
                                        alt={`Preview ${index + 1}`}
                                        className={"img-thumbnail border-0"}
                                    />
                                    <button
                                        type={"button"}
                                        className={"btn btn-sm btn-danger position-absolute top-0 end-0"}
                                        onClick={() => removeImage(index)}
                                        disabled={photo.loading}
                                    >
                                        <i className={"fa fa-times"} />
                                    </button>
                                </div>
                            ) : (
                                <div className={"px-2 text-center"}>
                                    <div className={"my-3 d-inline-flex"}>
                                        <RoundedIcon icon={"fa-image"} size={"lg"} />
                                    </div>
                                    <label className={"btn btn-primary text-md mb-3 w-100"}>
                                        <i className={"fa-solid fa-upload me-2"} />
                                        {Anexar}
                                        <input
                                            type="file"
                                            className={"d-none"}
                                            accept="image/*"
                                            onChange={e => handleFileChange(e, index)}
                                            disabled={photo.loading}
                                        />
                                    </label>
                                </div>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default EvaluationImageUpload;
