import {createSlice} from "@reduxjs/toolkit";
import {
    createErrorSubmitResult,
    createPendingSubmitResult,
    createSubmitResult,
    createSuccessSubmitResult
} from "../../utils/evaluation/mutationState";

const initialState = {
    modelsList: [],
    anamnesis: null,
    anamnesisList: null,
    studentsList: [],
    groupsList: [],
    initialLoading: false,
    submitLoading: false,
    submitResult: createSubmitResult(),
    anamnesisAnswer: null,
    anamnesisDeleted: false,
    error: null,
}

export const slice = createSlice({
    name: "anamnesis",
    initialState,
    reducers: {
        getModels(state) {
            state.initialLoading = true
        },
        setModels(state, action) {
            state.modelsList = action.payload;
            state.initialLoading = false
        },
        getAllAnamnesisList(state) {
            state.initialLoading = true;
        },
        setAllAnamnesisList(state, action) {
            state.anamnesisList = action.payload;
            state.initialLoading = false;
        },
        createModel: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "create",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        modelCreated(state, action) {
            state.anamnesis = action.payload;
            state.submitLoading = false;
        },
        createAnamnesis: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "create",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        anamnesisCreated(state, action) {
            state.anamnesis = action.payload;
            state.submitLoading = false;
        },
        getAnamnesis(state) {
            state.initialLoading = true;
        },
        getAnamnesisModel(state) {
            state.initialLoading = true;
        },
        setAnamnesis(state, action) {
            state.anamnesis = action.payload;
            state.initialLoading = false;
        },
        deleteAnamnesis: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "delete",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        deleteModel: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "delete",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        modelDeleted(state, action) {
            state.modelsList = state.modelsList.filter((model) => model.id !== action.payload)
            state.submitLoading = false
        },
        anamnesisDeleted(state, action) {
            state.anamnesisDeleted = true
            state.anamnesisList = state.anamnesisList.filter((anamnesis) => anamnesis.id !== action.payload)
            state.submitLoading = false;
        },
        updateAnamnesis: {
            reducer: (state, action) => {
            state.submitLoading = true
                state.submitResult = createPendingSubmitResult({
                    action: "update",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        updateModel: {
            reducer: (state, action) => {
            state.submitLoading = true
                state.submitResult = createPendingSubmitResult({
                    action: "update",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.id ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        sendAnamnesis: {
            reducer(state, action) {
            state.submitLoading = true;
                state.submitResult = createPendingSubmitResult({
                    action: "send",
                    flow: action.meta?.flow ?? null,
                    clientId: action.meta?.clientId ?? null,
                    entityId: action.payload?.modelId ?? null,
                });
            state.error = null;
            },
            prepare(payload, meta = {}) {
                return {payload, meta};
            }
        },
        resetFormSent(state) {
            state.submitLoading = false;
            state.submitResult = createSubmitResult();
            state.error = null;
        },
        setSubmitResult(state, action) {
            state.submitLoading = false;
            state.submitResult = createSuccessSubmitResult(action.payload);
            state.error = null;
        },
        clearAnamnesis: (state) => {
            state.anamnesis = null;
            state.initialLoading = false
            state.submitLoading = false;
            state.submitResult = createSubmitResult();
        },
        onError(state, action) {
            state.initialLoading = false
            if (state.submitLoading) {
                state.submitResult = createErrorSubmitResult(state.submitResult, action.payload);
            }
            state.submitLoading = false;
            state.error = action.payload;
        },
    },
})

export const {
    getModels, setModels,
    deleteModel,
    modelDeleted,
    getAllAnamnesisList,
    setAllAnamnesisList,
    createModel, modelCreated,
    getAnamnesis, getAnamnesisModel, setAnamnesis,
    deleteAnamnesis, anamnesisDeleted,
    updateAnamnesis, sendAnamnesis,
    resetFormSent, clearAnamnesis, onError, updateModel, createAnamnesis, anamnesisCreated, setSubmitResult
} = slice.actions

export const anamnesisReducer = slice.reducer;
