import {createSlice} from "@reduxjs/toolkit";

const initialState = {
    test: null,
    testList: null,
    testSaved: false,
    loading: false,
    testDeleted: false,
}

export const slice = createSlice({
    name: "neuromotors",
    initialState,
    reducers: {
        getAllTests(state) {
            state.loading = true;
        },
        setAllTests(state, action) {
            state.testList = action.payload;
            state.loading = false;
        },
        createTest(state) {
            state.loading = true;
        },
        testSaved(state, action) {
            state.loading = false;
            state.testSaved = action.payload;
        },
        updateTest(state) {
            state.loading = true;
        },
        deleteTest(state) {
            state.loading = true;
        },
        testDeleted(state, action) {
            state.testList = state.testList.filter(test => test.id !== action.payload);
            state.loading = false;
        },
        setTestDeleted(state, action){
            state.testDeleted = action.payload;
        },
        onError(state) {
            state.loading = false;
        },
    }
})

export const {
    getAllTests, setAllTests, createTest, updateTest, testSaved, deleteTest, testDeleted, setTestDeleted, onError
} = slice.actions

export const neuromotorsReducer = slice.reducer