import {ErrorMessage, Field, Form, Formik} from "formik";
import {Button} from "react-bootstrap";
import {useTranslation} from "react-i18next";
import {useDispatch, useSelector} from "react-redux";
import {isFeedbackLoading, isFeedbackSent} from "../../store/feedback/feedbackSelector";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../feedbacks/locales/en-us.json";
import ptBR from "../feedbacks/locales/pt-br.json";
import esES from "../feedbacks/locales/es-es.json";
import ptPT from "../feedbacks/locales/pt-pt.json";
import * as Yup from "yup";
import {useEffect} from "react";
import {createFeedback, setFeedbackFormSent} from "../../store/feedback/feedbackReducer";
import {useNavigate} from "react-router-dom";
import {formatElapsedTime} from "../../utils/workout/Workout";
import moment from "moment/moment";
import Cookies from 'js-cookie';
import {addToast} from "../../store/toast/toastReducer";
import {setPreview} from "../../store/workout-session/workoutSessionReducer";

const WorkoutSessionFeedbackForm = ({session, label1, label2, label3, handleModal}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const feedbackSent = useSelector(isFeedbackSent);
    const loading = useSelector(isFeedbackLoading);
    const navigate = useNavigate();
    const horaInicio = moment(localStorage.getItem("workoutStarted_" + session.id));
    let horaFim = moment();
    useComponentTranslations('feedbacks', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const validationSchema = Yup.object().shape({
        borg_nota: Yup.string().required(t("feedbacks:requiredField")),
    });

    const handleSubmit = (values) => {
        const payload = {
            id: session.client_id,
            formData: values
        }
        dispatch(createFeedback(payload));
    }

    useEffect(() => {
        // eslint-disable-next-line
        horaFim = moment();
        if (feedbackSent) {
            dispatch(setFeedbackFormSent(false));
            localStorage.removeItem("workoutStarted_" + session.id);
            const allCookies = Cookies.get();
            Object.keys(allCookies).forEach((cookieName) => {
                if (cookieName.startsWith('exercise_')) {
                    Cookies.remove(cookieName);
                }
            });

            dispatch(setPreview(true))
            handleModal()
            dispatch(addToast({
                type:"success",
                message:t("feedbacks:concludedTraining"),
                title:t("feedbacks:allGood")
            }))

        }
    }, [dispatch, feedbackSent, navigate, session])

    return (
        <Formik
            initialValues={{
                borg_nota: '',
                feedback: '',
                trainingId: session.id,
                routineId: session.routine_id,
                type: 0,
                atividade: session.nome,
                horaInicio: horaInicio.toString(),
                horaFim: horaFim.toString()
            }}
            validationSchema={validationSchema}
            onSubmit={handleSubmit}
        >
            {() => (
                <div className={'row justify-content-center d-flex'}>
                    <div className={'col-12 text-center  text-center pt-3'}>
                        <div className={' icon icon-shape rounded-circle bg-primary-darker text-white '}
                             style={{height: "80px", width: "80px"}}>
                            <i className="fa-regular fa-medal  " style={{fontSize: "2.5rem"}}></i>
                        </div>
                    </div>
                    <div className={'row justify-content-center d-flex pb-3 pt-2'}>
                        <div className={'col-12 text-center'}>
                            <span className={'d-block fw-semibold  fs-5'}>{t("feedbacks:allGood")}</span>
                            <span className={'d-block text-md lh-1'}>{t("feedbacks:concludedTraining")}</span>
                        </div>
                    </div>
                    <div className={'row justify-content-center d-flex  pt-2'}>
                        <div className={'col-12  bg-secondary-subtle pt-2 pb-2'}>
                            <div className={'row justify-content-between d-flex  '}>
                                <div className={'col-auto '}>
                                    <span className={'fw-bold'}>{label1}: </span>
                                </div>
                                <div className={'col-auto  '}>
                                    {horaInicio.format("HH:mm")}
                                </div>
                            </div>
                            {
                                horaFim &&
                                <>
                                    <div className={'row justify-content-between'}>
                                        <div className={'col-auto'}>
                                            <span className={'fw-bold'}>{label2}: </span>
                                        </div>
                                        <div className={'col-auto text-end'}>
                                            {horaFim.format("HH:mm")}
                                        </div>
                                    </div>
                                    <div className={'row justify-content-between'}>
                                        <div className={'col-auto'}>
                                            <span className={'fw-bold'}>{label3}: </span>
                                        </div>
                                        <div className={'col-auto text-end'}>
                                            {formatElapsedTime((horaFim.diff(horaInicio, 'seconds')))}
                                        </div>
                                    </div>
                                </>
                            }
                        </div>
                    </div>
                    <div className={'col-12 pt-2'}>
                        <Form>
                            <div className="form-group pt-2">
                                <label htmlFor="borg_nota"
                                       className={' text-md'}>{t("feedbacks:feedbackQuestion")}</label>
                                <Field type="hidden" name="trainingId"/>
                                <Field type="hidden" name="type"/>
                                <Field type={"hidden"} name="atividade"/>
                                <Field name="borg_nota" as="select" className="form-control form-control-sm mt-1">
                                    <option value="">{t("feedbacks:select")}</option>
                                    <option value="1">{t("feedbacks:veryLight")}</option>
                                    <option value="2">{t("feedbacks:light")}</option>
                                    <option value="3">{t("feedbacks:moderated")}</option>
                                    <option value="4">{t("feedbacks:littleIntense")}</option>
                                    <option value="5">{t("feedbacks:intense")}</option>
                                    <option value="7">{t("feedbacks:veryIntense")}</option>
                                    <option value="9">{t("feedbacks:reallyIntense")}</option>
                                    <option value="10">{t("feedbacks:maxExhaustion")}</option>
                                </Field>
                                <ErrorMessage name="borg_nota" component="div" className="small text-danger"/>
                            </div>
                            <div className="form-group mt-3">
                                <label className={'text-md'}>{t("feedbacks:writeSomething")}</label>
                                <Field as="textarea" name="feedback" style={{minHeight: "100px"}}
                                       placeholder={t("feedbacks:yourCommentHere")}
                                       className="form-control form-control-sm" rows="4"></Field>
                            </div>
                            <div className={'d-grid mt-3'}>
                                <Button disabled={loading} type="submit" className="btn btn-primary-darker">
                                    {loading ?
                                        <i className="fa-regular fa-ellipsis fa-fade fa-2xl"></i> : t("feedbacks:send")}
                                </Button>
                            </div>
                        </Form>
                    </div>
                </div>

            )}
        </Formik>
    )
}

export default WorkoutSessionFeedbackForm;