import {createSelector} from "reselect";

const feedbacksReducer = (state) => state.feedbacks;

export const isFeedbackLoading = createSelector([feedbacksReducer], (feedbackSlice) => feedbackSlice.loading)
export const isFeedbackSent = createSelector([feedbacksReducer], (feedbackSlice) => feedbackSlice.formSent)
export const selectUnreadFeedbackCount = createSelector([feedbacksReducer], (feedbackSlice) => feedbackSlice.unreadFeedbackCount)
export const selectFeedbacks = createSelector([feedbacksReducer], (feedbackSlice) => feedbackSlice.feedbacks)
export const isFeedbackResolving = createSelector([feedbacksReducer], (feedbackSlice) => feedbackSlice.feedbackResolving)
export const selectResolvedFeedback = createSelector([feedbacksReducer], (feedbackSlice) => feedbackSlice.resolvedFeedbackList)