import React from 'react';
import _ from "lodash";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import Text from "../utils/emoji/Text";

const FrequencyTable = ({currentItems, totalAmount}) => {
    const {t} = useTranslation();
    useComponentTranslations('frequencyComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const sortedEntries = _.sortBy(currentItems, [item => -item[1]]);

    return (
        <div className={"table-responsive w-100"}>
            <table className={"table-light w-100"}>
                <thead>
                <tr className={"border-bottom"}>
                    <th className={"fw-semibold text-start pb-2 pt-4"}>
                        {t("frequencyComponent:client")}
                    </th>
                    <th className={"fw-semibold text-end pb-2 pt-4"}>
                        {t("frequencyComponent:finishedWorkout")}
                    </th>
                </tr>
                </thead>
                <tbody>
                {sortedEntries.map(([key, value]) => (
                    <tr key={key} className={"border-bottom"}>
                        <td className={"text-start py-2"}><Text>{key}</Text></td>
                        <td className={"fw-semibold py-2 text-end"}>{value}</td>
                    </tr>
                ))}
                </tbody>
                <tfoot>
                <tr>
                    <td className={"fw-semibold text-start pt-4"}>{t("frequencyComponent:finishedWorkoutTotal")}:</td>
                    <td className={"fw-semibold text-end pt-4"}>{totalAmount}</td>
                </tr>
                </tfoot>
            </table>
        </div>
    )
}

export default FrequencyTable;
