import React, { forwardRef } from 'react';
import { createPortal } from 'react-dom';

const BodyMenu = forwardRef(({ children, className, style, ...props }, ref) => {
    const { show, close, flip, offset, ...domProps } = props;

    return createPortal(
        <div
            ref={ref}
            className={className}
            style={{
                ...style,
                position: 'absolute',
                zIndex: 9999,
            }}
            {...domProps}    // now safe to spread only the remaining DOM props
        >
            {children}
        </div>,
        document.body
    );
});

export default BodyMenu;
