import Spinner from "../loader/Spinner";
import {useDispatch, useSelector} from "react-redux";
import {isClientCountLoading, isClientPendingLoading, selectClientCount, selectPendingClientCount} from "../../store/client/clientSelector";
import {selectUnreadFeedbackCount} from "../../store/feedback/feedbackSelector";
import {selectUpdatesCount} from "../../store/updates/updatesSelector";
import {useEffect, useState} from "react";
import {fetchClientCount, fetchPendingClientCount} from "../../store/client/clientReducer";
import {fetchUnreadFeedbacks} from "../../store/feedback/feedbackReducer";
import SubExpiring from "../warning/SubExpiring";
import TrialEnding from "../warning/TrialEnding";
import {Link, useNavigate} from "react-router-dom";
import logo from '../../assets/img/logo/logo-mfit-branco.png'
import {selectPaymentCountry, selectUser} from "../../store/user/userSelector";
import {selectPermission, selectSpointUserRejected} from "../../store/check/checkSelector";
import LoadingBlock from "../loader/LoadingBlock";
import Modal from "react-bootstrap/Modal";
import {fetchUpdatesCount} from "../../store/updates/updatesReducer";
import RoundedCard from "../rounded-icon/RoundedCard";
import EmptySetClients from "../empty-set/EmptySetClients";
import CardButtonLg from "../card/CardButtonLg";
import CardListItem from "../card/CardListItem";
import {
    handleBlogClick,
    handleExclusiveContentClick, handleInstagramClick,
    handleMfitPointsClick,
    handleMFITCursosClick, handleNewsletterClick, handleStoreClick,
    mfitUrl
} from "../../utils/handlers/handler";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {getPaymentCountry} from "../../store/user/userReducer";
import LimitExceededWarning from "../limit-exceeded/LimitExceededWarning";
import Cookies from "js-cookie";
import CardButtonLgRounded from "../card/CardButtonLgRounded";
import {checkSpointUser} from "../../store/check/checkReducer";
import {canUseSpointByCountry} from "../../utils/spoint/spointAccess";
import {useRetentionSummaryQuery} from "../../store/retention/retentionApi";

const UserStart = () => {
    const {t, i18n} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const user = useSelector(selectUser)
    const clientCountLoading = useSelector(isClientCountLoading);
    const clientCount = useSelector(selectClientCount)
    const unreadFeedbacks = useSelector(selectUnreadFeedbackCount)
    const updatesCount = useSelector(selectUpdatesCount);
    const pendingClientCount = useSelector(selectPendingClientCount);
    const loadingPendingClient = useSelector(isClientPendingLoading);
    const isSpointRejected = useSelector(selectSpointUserRejected);
    const [limitReached, setLimitReached] = useState(false)
    const [limitReachedModal, setLimitReachedModal] = useState(false);
    const [total, setTotal] = useState(0);
    const [showMore, setShowMore] = useState(false)
    const permission = useSelector(selectPermission)
    const userPaymentCountry = useSelector(selectPaymentCountry);
    const isPaymentCountryResolved = userPaymentCountry !== null;
    const hasSpointCountryAccess = canUseSpointByCountry(userPaymentCountry);
    const showMfitPoints = hasSpointCountryAccess && !isSpointRejected && isPaymentCountryResolved;
    const homeQuickActionsCol = showMfitPoints ? "3" : "4";
    const {
        retentionEngagementValue,
        retentionSummaryLoading
    } = useRetentionSummaryQuery("CURRENT_MONTH", {
        selectFromResult: ({data, isLoading}) => ({
            retentionEngagementValue: data?.cards?.engagement?.value,
            retentionSummaryLoading: isLoading
        })
    });
    const hasRetentionEngagementValue = retentionEngagementValue !== null && retentionEngagementValue !== undefined;
    useComponentTranslations('user', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleAddClientClick = "/user/client/add";
    const handleSignUpLink = "/user/signup-link";
    const handleFeedbackClick = "/user/feedback";
    const handleUpdatesClick = "/user/update";
    const handlePushClick = "/user/push";
    const handleFrequencyReportClick = "/user/frequency-report";
    const handleClientsClick = "/user/client/list?tab=clients";
    const handleRetentionClick = "/user/retention";
    const handleTrainingLibraryClick = `/user/workout-library`;

    const handleChallengeGroupClick = `${mfitUrl}/index?acao=challenge&tipo=0&goBackToNewApp=true`;
    const handleExerciseLibraryClick = `/user/exercise-library`;

    const navigateToAddClient = () => {
        navigate(handleAddClientClick)
    }

    const handleOpenClientsToDelete = () => {
        setLimitReachedModal(false)
        navigate(handleClientsClick);
    }

    const handleLimiReachedClick = () => {
        setLimitReachedModal(prevState => !prevState)
    }

    const handleMoreClick = () => {
        setShowMore(prev => !prev)
    }

    useEffect(() => {
        dispatch(fetchClientCount());
        dispatch(fetchPendingClientCount());
        dispatch(fetchUnreadFeedbacks());
        dispatch(fetchUpdatesCount());
    }, [dispatch]);

    useEffect(() => {
        if (hasSpointCountryAccess) {
            dispatch(checkSpointUser())
        }
    }, [dispatch, hasSpointCountryAccess]);

    useEffect(() => {
        if (userPaymentCountry === null) {
            dispatch(getPaymentCountry())
        }
    }, [userPaymentCountry, dispatch])

    useEffect(() => {
        if (!clientCountLoading && clientCount && user && permission === "ALLOWED") {
            if (user.tipoPlano !== 200 || !user.subPlan.unlimited) {
                const total = Number(clientCount.status_0 || 0) + Number(clientCount.status_1 || 0);
                setTotal(total)
                if (total > user.plano) {
                    navigate("/exceeded-limit")
                } else if (total === user.plano) {
                    setLimitReached(true)
                }
            }
        }
    }, [clientCountLoading, clientCount, user, navigate, permission]);

    return (
        <>
            <SubExpiring/>
            <TrialEnding/>
            <div className={'row pt-3'}>
                <div className={'col-12'}>
                    <div className={'card card-body border-0 ps-0 pe-1'}>
                        <div className={'row justify-content-evenly  '}>
                            <RoundedCard text={t("user:feedbacks")}
                                         icon={"fa-comments"}
                                         col={`col-${homeQuickActionsCol}`}
                                         textClass={showMfitPoints ? "small fw-semibold" : ""}
                                         unreadCount={unreadFeedbacks}
                                         to={handleFeedbackClick}/>
                            <RoundedCard text={t("user:updates")}
                                         icon={"fa-calendar-lines"}
                                         col={`col-${homeQuickActionsCol}`}
                                         textClass={showMfitPoints ? "small fw-semibold" : ""}
                                         unreadCount={updatesCount}
                                         to={handleUpdatesClick}/>
                            <RoundedCard text={t("user:push")}
                                         icon={"fa-paper-plane"}
                                         col={`col-${homeQuickActionsCol}`}
                                         textClass={showMfitPoints ? "small fw-semibold" : ""}
                                         to={handlePushClick}/>
                            {
                                showMfitPoints &&
                                <RoundedCard text={t("user:mfitPoints")}
                                             kit={true}
                                             icon={"fa-pontos-mfit"}
                                             col={`col-${homeQuickActionsCol}`}
                                             textClass={showMfitPoints ? "small fw-semibold" : ""}
                                             handleClick={handleMfitPointsClick}/>
                            }

                        </div>
                    </div>
                </div>
                {
                    !clientCount &&
                    <div className={'col-12 pt-3'}>
                        <div className={'card card-body border-0'}>
                            <LoadingBlock height={"300px"}/>
                        </div>
                    </div>
                }
                {
                    clientCount && Object.getOwnPropertyNames(clientCount).length === 0 &&
                    <div className={'col-12 pt-3'}>
                        <EmptySetClients img={logo} title={user.sexo === "f" ? t("user:welcomeF") : t("user:welcomeM")}
                                         message={t("user:addClientText")}
                                         btnText={t("user:addClient")}
                                         handleClick={navigateToAddClient}
                                         signUpLinkText={t("user:signupLink")}
                                         handleSignUpLink={handleSignUpLink}
                        />
                    </div>
                }
                {
                    clientCount && Object.getOwnPropertyNames(clientCount).length > 0 &&
                    <div className={'col-12 pt-3'}>
                        <div className={'card card-body border-0'}>
                            <div className={'row justify-content-evenly gap-2 '}>
                                <div className={'col-12 pb-3'}>
                                    <span className={'fw-semibold'}>{t("user:yourClients")}</span>
                                </div>
                                <div className={'row ps-0 pe-0'}>
                                    <CardButtonLg col={"col-6"}
                                                  pe={"pe-1"}
                                                  ps={"ps-1"}
                                                  icon={"fa-user-plus"}
                                                  bgColor={"bg-primary-lighter"}
                                                  borderClass={"border-0"}
                                                  textColor={"text-white"}
                                                  text={t("user:addClientR")}
                                                  to={!limitReached ? handleAddClientClick : undefined}
                                                  handleClick={limitReached ? handleLimiReachedClick : undefined}
                                    />
                                    {
                                        limitReached &&
                                        <Modal centered show={limitReachedModal} onHide={handleLimiReachedClick}>
                                            <Modal.Body className={"mt-3"}>
                                                <LimitExceededWarning total={total} handleClientDeleteClick={handleOpenClientsToDelete}/>
                                            </Modal.Body>
                                        </Modal>
                                    }
                                    <CardButtonLg col={"col-6"}
                                                  pe={"pe-1"}
                                                  ps={"ps-1"}
                                                  icon={"fa-link"}
                                                  bgColor={"bg-primary-lighter"}
                                                  borderClass={"border-0"}
                                                  textColor={"text-white"}
                                                  text={t("user:signupLink")}
                                                  count={pendingClientCount}
                                                  loading={loadingPendingClient}
                                                  to={handleSignUpLink}
                                    />
                                </div>
                                <div className={'row  ps-0 pe-0'}>
                                    <div className={'col-12  ps-1 pe-1'}>
                                        <div className={'card card-body card-bg-gradient rounded text-white '}>
                                            {
                                                (!clientCountLoading && clientCount) &&
                                                <Link to={handleClientsClick} className={"text-decoration-none text-white"}>
                                                    <div className={'row justify-content-between  '}>

                                                        <div className={'col-2 text-center align-self-center'}>
                                                            <i className={'fa-regular fa-users fa-2xl'}></i>
                                                        </div>
                                                        <div className={'col-8  align-self-center'}>
                                                            <span className={'fw-bold d-block  fs-6'}>{t("user:clients")}</span>
                                                            <span className={'badge rounded-pill me-2 text-success fw-bold bg-success-subtle'}
                                                            >{t("user:actives")}: {clientCount.status_0 ?? 0}</span>
                                                            <span className={'badge  rounded-pill text-warning fw-bold bg-warning-subtle'}
                                                            >{t("user:inactives")}: {clientCount.status_1 ?? 0}</span>
                                                        </div>
                                                        <div className={'col-2   align-self-center text-end'}>
                                                            <i className={'fa-regular fa-chevron-right fa-xl'}></i>
                                                        </div>
                                                    </div>
                                                </Link>
                                            }
                                            {
                                                clientCountLoading && <Spinner width={"25px"} height={"25px"}/>
                                            }
                                        </div>
                                    </div>
                                </div>
                                <div className={'row  ps-0 pe-0'}>
                                    <div className={'col-12 pe-1 ps-1  '}>
                                        <Link to={handleRetentionClick} className={"text-decoration-none"}>
                                            <div className={'card card-body border-0 bg-info-light'}>
                                                <div className={'row align-items-center'}>
                                                    <div className={'col-auto pe-0 text-primary-lighter'}>
                                                        <i className={'fa-regular fa-arrow-trend-up fa-lg'}></i>
                                                    </div>
                                                    <div className={'col'}>
                                                        <span className={'fw-semibold   text-primary-lighter'}>{t("user:retention")}</span>
                                                    </div>
                                                    <div className={'col-auto pe-0'}>
                                                        {
                                                            retentionSummaryLoading && !hasRetentionEngagementValue
                                                                ? (
                                                                    <span className={"placeholder-glow d-inline-flex align-items-center"} style={{minWidth: "10.5rem"}}>
                                                                        <span className={"placeholder bg-primary-subtle rounded-pill w-100"} style={{height: "1.1rem"}}></span>
                                                                    </span>
                                                                )
                                                                : (
                                                                    <span className={'text-md text-uppercase text-primary-lighter'}>
                                                                        {
                                                                            hasRetentionEngagementValue
                                                                                ? `${Number(retentionEngagementValue).toLocaleString(undefined, {
                                                                                    minimumFractionDigits: 0,
                                                                                    maximumFractionDigits: 1,
                                                                                })}% ${t("user:engagementRate")}`
                                                                                : `-- ${t("user:engagementRate")}`
                                                                        }
                                                                    </span>
                                                                )
                                                        }
                                                    </div>
                                                    <div className={'col-auto text-primary-lighter'}>
                                                        <i className={'fa-regular fa-chevron-right fa-lg'}></i>
                                                    </div>
                                                </div>
                                            </div>
                                        </Link>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                }
                {
                    (i18n.language.includes("pt") || userPaymentCountry?.country === "BRA" || userPaymentCountry?.country === "PRT") &&
                    <div className={'col-12 pt-3'}>
                        <div className={"card card-body border-0"}>
                            <div className={'row justify-content-evenly'}>
                                <RoundedCard text={t("user:mfitCursos")}
                                             icon={"fa-graduation-cap"}
                                             col={"col-4"}
                                             handleClick={handleMFITCursosClick}
                                             size={"xs"}
                                             textClass={"small"}
                                />
                                <RoundedCard text={t("user:content")}
                                             icon={"fa-medal"}
                                             col={"col-4"}
                                             handleClick={handleExclusiveContentClick}
                                             size={"xs"}
                                             textClass={"small"}
                                />
                                <RoundedCard text={t("user:more")}
                                             icon={"fa-ellipsis"}
                                             col={"col-4"}
                                             handleClick={handleMoreClick}
                                             size={"xs"}
                                             textClass={"small"}
                                />
                            </div>
                        </div>
                    </div>
                }
                <div className={'col-12 pt-3'}>
                    <div className={' card card-body border-0'}>
                        <div className={'row  gap-2'}>
                            <div className={'col-12 pb-3'}>
                                <span className={'fw-semibold '}>{t("user:workouts")}</span>
                            </div>
                            <div className={"col-12"}>
                                <div className={'row '}>
                                    <CardButtonLgRounded
                                        ps={"ps-1"}
                                        pe={"pe-1"}
                                        col={"col-6"}
                                        icon={"fa-books"}
                                        text={t("user:workoutLibrary")}
                                        to={handleTrainingLibraryClick}
                                    />
                                    <CardButtonLgRounded
                                        ps={"ps-1"}
                                        pe={"pe-1"}
                                        col={"col-6"}
                                        icon={"fa-users"}
                                        text={t("user:challengeGroup")}
                                        to={handleChallengeGroupClick}
                                    />
                                </div>
                            </div>
                            <div className={"col-12"}>
                                <div className={'row '}>
                                    <CardButtonLgRounded
                                        col={"col-6"}
                                        pe={"pe-1"}
                                        ps={"ps-1"}
                                        icon={"fa-clipboard-check"}
                                        text={t("user:frequencyReport")}
                                        to={handleFrequencyReportClick}
                                    />
                                    <CardButtonLgRounded
                                        col={"col-6"}
                                        ps={"ps-1"}
                                        pe={"pe-1"}
                                        icon={"fa-file-video"}
                                        text={t("user:exerciseLibrary")}
                                        to={handleExerciseLibraryClick}
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <Modal centered show={showMore} onHide={handleMoreClick}>
                <Modal.Body>
                    <div className={'row justify-content-between'}>
                        <div className={'col-auto pb-3'}>
                            <span className={'fw-semibold '}>{t("user:mfit")}</span>
                        </div>
                        <div className={'col-auto'}>
                            <i
                                className="fa-regular fa-xmark cursor-pointer"
                                onClick={handleMoreClick}
                                role="button"
                                aria-label="Fechar Modal"
                            />
                        </div>
                        <div className={'col-12 pb-3'}>
                            <div className={'row'}>
                                <div className={'col-12 d-grid gap-2'}>
                                    <CardListItem text={t("user:instagram")}
                                                  icon={"fa-brands fa-instagram"}
                                                  handleClick={handleInstagramClick}
                                    />
                                    <CardListItem text={t("user:mfitCursos")}
                                                  icon={"fa-graduation-cap"}
                                                  handleClick={handleMFITCursosClick}
                                    />
                                    <CardListItem text={t("user:exclusiveContent")}
                                                  icon={"fa-medal"}
                                                  handleClick={handleExclusiveContentClick}
                                    />
                                    <CardListItem text={t("user:newsletter")}
                                                  icon={"fa-newspaper"}
                                                  handleClick={handleNewsletterClick}
                                    />
                                    <CardListItem text={t("user:blog")}
                                                  icon={"fa-blog"}
                                                  handleClick={handleBlogClick}
                                    />
                                    {
                                        userPaymentCountry?.country === "BRA" && !Cookies.get("isApple") &&
                                        <CardListItem text={t("user:store")}
                                                      icon={"fa-bag-shopping"}
                                                      handleClick={handleStoreClick}
                                        />
                                    }
                                </div>
                            </div>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>

        </>
    )
}
export default UserStart;
