import Modal from "react-bootstrap/Modal";
import RoundedIcon from "../rounded-icon/RoundedIcon";
import React, {useCallback, useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {selectCreditCardError} from "../../store/subscription/subscriptionSelector";
import {createCreditCardError} from "../../store/subscription/subscriptionReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionCreditCardNotChangedModal = ({closeModal, goToPaymentMethods}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const creditCardError = useSelector(selectCreditCardError);
    const [showCreditCardNotAdded, setShowCreditCardNotAdded] = useState(false);
    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleShowCreditCardNotAdded = useCallback(() => {
        setShowCreditCardNotAdded(prevState => !prevState);
    }, [])

    useEffect(() => {
        if (creditCardError) {
            if (closeModal)
                closeModal();
            setShowCreditCardNotAdded(true)
            dispatch(createCreditCardError(null))
        }
    }, [creditCardError, dispatch, closeModal])

    return (
        <>
            <Modal centered show={showCreditCardNotAdded} onHide={handleShowCreditCardNotAdded}>
                <Modal.Body>
                    <div className={"row"}>
                        <div className={"col-12 text-center pt-2"}>
                            <RoundedIcon icon={"fa-credit-card"} size={"lg"}/>
                        </div>
                        <div className={"col-12 text-center pt-2"}>
                            <span className={"fw-semibold fs-5"}>{t('subscriptionComponent:creditCardNotChangedModal.title')}</span>
                        </div>
                        <div className={"col-12 text-center pt-2"}>
                            <span>{t('subscriptionComponent:creditCardNotChangedModal.message')}</span>
                        </div>
                        <div className={"col-12 text-center pt-4"}>
                            <button className={"btn btn-primary-lighter w-100"}
                                    onClick={goToPaymentMethods || handleShowCreditCardNotAdded}>{t('subscriptionComponent:creditCardNotChangedModal.tryAnotherCard')}</button>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>

        </>
    )
}
export default SubscriptionCreditCardNotChangedModal;