import {createSelector} from "reselect";

const filesReducer = (state) => state.files;

export const isFilesLoading = createSelector([filesReducer], (fileSlice) => fileSlice.loading);
export const selectAllFiles = createSelector([filesReducer], (fileSlice) => fileSlice.files);
export const selectOneFile = createSelector([filesReducer], (fileSlice) => fileSlice.oneFile);
export const isFileAdd = createSelector([filesReducer], (fileSlice) => fileSlice.addFile);
export const selectSelectedFile = createSelector([filesReducer], (fileSlice) => fileSlice.selectedFile);
export const selectEditSuccess = createSelector([filesReducer], (fileSlice) => fileSlice.editSuccess);