import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useParams} from "react-router-dom";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import LoadingBlock from "../../components/loader/LoadingBlock";
import EmptySet from "../../components/empty-set/EmptySet";
import {getLoading, getPhysicalList} from "../../store/physical-evaluation/physicalEvaluationSelector";
import PhysicalEvaluationCard from "../../components/physical-evaluation/PhysicalEvaluationCard";
import _ from "lodash";
import EvaluationCompareBarComponent from "../../components/evaluation-components/EvaluationCompareBarComponent";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import PhysicalActionsButtons from "../../components/physical-evaluation/PhysicalActionsButtons";
import {usePhysicalActions} from "../../utils/physicalEvaluation/usePhysicalActions";
import {resetFormSent} from "../../store/physical-evaluation/physicalEvaluationReducer";
import {fetchClient} from "../../store/client/clientReducer";
import {getAllPhysical} from "../../store/physical-evaluation/physicalEvaluationReducer";

const PhysicalEvaluation = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const {id} = useParams();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const physicalList = useSelector(getPhysicalList);
    const {
        state: {isComparing, selectedList, showOptions, showShare, showDelete, showPhysicalMenu, currentPhysical, deleteSubmitting},
        handlers, shareLink
    } = usePhysicalActions();
    const MAX_SELECTION = 3;
    useComponentTranslations('physicalEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        if (!selectedClient?.id && id) {
            dispatch(fetchClient(id));
        }
        if (id) {
            dispatch(getAllPhysical({clientId: id, status: 0, type: 0}));
        }
    }, [dispatch, id, selectedClient?.id]);

    return (
        <>
            <AvatarHeader
                showGoBack={handlers.goBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"card card-body border-0"}>
                    {loading &&
                        <div className={"text-center mt-4"}>
                            <LoadingBlock/>
                        </div>
                    }
                    <div className={"pt-2"}>
                        <div className={"btn btn-outline-primary w-100 py-4 clickable-element"}
                             onClick={handlers.openPhysicalMenu}>
                            <i className={"fa-regular fa-plus pe-1"}/>
                            <span>{t("physicalEvaluation:newEvaluation")}</span>
                        </div>
                    </div>
                    <div className={"row justify-content-center d-flex"}>
                        <div className={"row py-3"}>
                            <div className={"col-12 d-flex gap-2 ps-0 pe-0"}>
                                <button className={"btn btn-secondary-default w-100"} onClick={handlers.goCharts}>
                                    <span className={"text-primary"}>{t("physicalEvaluation:charts")}</span>
                                </button>
                                <button className={"btn btn-secondary-default w-100"} onClick={handlers.goDeleted}>
                                    <span className={"text-primary"}>{t("physicalEvaluation:deleted")}</span>
                                </button>
                            </div>
                        </div>
                    </div>
                    {(!physicalList || physicalList.length === 0) &&
                        <div className={"pt-3"}>
                            <EmptySet
                                icon={"fa-regular fa-folder-open"}
                                message={t("physicalEvaluation:emptyMessage")}
                            />
                        </div>
                    }
                    {!loading && physicalList && physicalList.length > 0 && (
                        <div className={"row justify-content-center d-flex"}>
                            <div className={"col-12"}>
                                <div className={"px-2"}>
                                    {_.map(physicalList, (physical =>
                                        <PhysicalEvaluationCard
                                            key={physical.id}
                                            physical={physical}
                                            onCardClick={() => handlers.openOptionsModal(physical)}
                                            isComparing={isComparing}
                                            isSelected={selectedList.includes(physical.id)}
                                            onToggle={handlers.toggleSelection}
                                            onCompare={handlers.toggleComparingMode}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}
                    {isComparing && (
                        <EvaluationCompareBarComponent
                            selectedCount={selectedList.length}
                            maxSelection={MAX_SELECTION}
                            onCompare={handlers.goCompare}
                            onClose={handlers.toggleComparingMode}
                            compareLabel={t("physicalEvaluation:compare")}
                            selectLabel={t("physicalEvaluation:select")}
                        />
                    )}
                </div>
            </Page>
            <PhysicalActionsButtons
                state={{
                    currentPhysical,
                    showOptions,
                    showShare,
                    showDelete,
                    deleteSubmitting,
                    isComparing,
                    selectedList,
                    showPhysicalMenu
                }}
                handlers={handlers}
                shareLink={shareLink}
            />

        </>
    );
}

export default PhysicalEvaluation;
