import Modal from "react-bootstrap/Modal";
import {ModalBody} from "react-bootstrap";
import React from "react";

const FeedbackFilterModal = ({
                                 isOpen,
                                 onClose,
                                 title,
                                 filters,
                                 onSelectTraining,
                                 onSelectAerobic,
                                 onSelectExtraTraining,
                                 onSelectIntensity,
                                 onToggleComment,
                                 onApply,
                                 onClear,
                                 t,
                                 intensityOptions = [
                                     "veryLight",
                                     "light",
                                     "moderated",
                                     "littleIntense",
                                     "intense",
                                     "veryIntense",
                                     "reallyIntense",
                                     "maxExhaustion"
                                 ]
                             }) => {

    return (
        <Modal show={isOpen} onHide={onClose} centered>
            <ModalBody>
                <div className={"row"}>
                    <div className={"col-12"}>
                        <div className="position-absolute top-0 end-0 p-3" onClick={onClose}>
                            <i className="fa-regular fa-xmark cursor-pointer"/>
                        </div>
                        <span className={"fw-semibold text-start fs-4"}>
                                {title}
                        </span>
                        <div className={"row"}>
                            <div className={"col-12 mt-2"}>
                                <span className={"fw-semibold"}>{t("feedbackList:type")}</span>
                            </div>
                            <div className={"col-12 mt-2"}>
                                <button
                                    className={`btn mx-1 ${filters.feedbackSource.includes(0) ? "btn-feedback-primary fw-semibold text-primary" : "btn-secondary-lighter"}`}
                                    onClick={onSelectTraining}
                                >{t("feedbackList:training")}
                                </button>
                                <button
                                    className={`btn ms-1 ${filters.feedbackSource.includes(1) ? "btn-feedback-primary fw-semibold text-primary" : "btn-secondary-lighter"}`}
                                    onClick={onSelectAerobic}
                                >{t("feedbackList:aerobic")}
                                </button>
                                <button
                                    className={`btn ms-1 ${filters.feedbackSource.includes(2) ? "btn-feedback-primary fw-semibold text-primary" : "btn-secondary-lighter"}`}
                                    onClick={onSelectExtraTraining}
                                >{t("feedbackList:extraTraining")}
                                </button>
                            </div>
                            <div className={"col-12 mt-2"}>
                                <span className={"fw-semibold"}>
                                    {t(`feedbackList:intensity`)}:
                                </span>
                            </div>
                            <div className={'col-12 mt-2'}>
                                {intensityOptions.map((item) => (
                                    <button
                                        key={item}
                                        className={`btn m-1 ${filters.intensity.includes(item) ? "btn-feedback-primary fw-semibold text-primary" : "btn-secondary-lighter"}`}
                                        onClick={() => onSelectIntensity(item)}
                                    >
                                        {t(`feedbackList:${item}`)}
                                    </button>
                                ))}
                            </div>
                            <div className={"col-12 mt-2"}>
                                <span className={"fw-semibold"}>
                                    {t(`feedbackList:comment`)}
                                </span>
                                {["without", "with"].map(val => (
                                    <div className={"form-check"} key={val}>
                                        <input
                                            type="checkbox"
                                            className={"form-checkbox me-2"}
                                            checked={filters.comments.includes(val)}
                                            onChange={() => onToggleComment(val)}
                                        />
                                        <label className={"form-check-label"}>
                                            {t(`feedbackList:${val === "without" ? "withOutComment" : "withComment"}`)}
                                        </label>
                                    </div>

                                ))}
                            </div>
                            <div className={'col-12 mt-3'}>
                                <div className={'d-grid '}>
                                    <button className={"btn btn-primary-lighter"}
                                            onClick={onApply}>
                                        {t(`feedbackList:filter`)}
                                    </button>
                                </div>
                                <div className={"d-grid pt-2"}>
                                    <button className={"btn btn-link fw-semibold"}
                                            onClick={onClear}>
                                        {t(`feedbackList:cleanFilter`)}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </ModalBody>
        </Modal>
    )
}

export default FeedbackFilterModal;