
export const formatIMC = (imc, t) => {
    if (imc == null) return "-";
    const num = typeof imc === "string"
        ? parseFloat(imc.match(/[\d.]+/)?.[0])
        : imc;
    const v = Number(num).toFixed(2);

    let classificationKey;
    if (num < 18.5) classificationKey = "bellow_weight";
    else if (num <= 24.9) classificationKey = "normal_weight";
    else if (num <= 29.9) classificationKey = "above_weight";
    else if (num <= 34.9) classificationKey = "obesity_1";
    else if (num <= 39.9) classificationKey = "obesity_2";
    else classificationKey = "morbid_obesity";

    return `${v} ${t(`imc.${classificationKey}`)}`;
};
