import {useNavigate, useParams} from "react-router-dom";
import React, {useEffect} from "react";
import AnamnesisModelForm from "../../components/anamnesis/AnamnesisModelForm";
import Page from "../../components/page/Page";
import {createModel, resetFormSent} from "../../store/anamnesis/anamnesisReducer";
import {useDispatch} from "react-redux";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {
    buildAnamnesisNewRoute
} from "../../utils/client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";

const AnamnesisCreateModel = () => {
    const dispatch = useDispatch();
    const {t} = useTranslation();
    const navigate = useNavigate();
    const {clientId} = useParams();
    useComponentTranslations('anamnesis', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    const handleGoBack = () => {
        navigate(buildAnamnesisNewRoute(clientId));
    };

    const handleSaveModel = (values) => {
        dispatch(createModel(values, {
            flow: EVALUATION_FLOWS.ANAMNESIS_MODEL_CREATE,
            clientId
        }));
    }

    return (
        <Page title={t("anamnesis:createModel")}
              goBackLink={handleGoBack}>
            <div className={"row justify-content-center d-flex mt-n4"}>
                <div className="col-12">
                    <AnamnesisModelForm onSave={handleSaveModel}/>
                </div>
            </div>
        </Page>
    );
}

export default AnamnesisCreateModel
