import {createSelector} from "reselect";

const reducer = state => state.customEvaluation;

export const selectCustomEvaluation = createSelector([reducer], slice => slice.customEvaluation);
export const getCustomLoading = createSelector([reducer], slice => slice.initialLoading);
export const selectAllCustom = createSelector([reducer], slice => slice.customList);
export const selectAllCustomModels = createSelector([reducer], slice => slice.customModelsList);
export const selectSubmitLoading = createSelector([reducer], slice => slice.submitLoading);
export const selectSubmitResult = createSelector([reducer], slice => slice.submitResult);
export const selectImageUploading = createSelector([reducer], slice => slice.imageLoading);
export const selectCompareCustom = createSelector([reducer], slice => slice.compareList);
export const selectCustomModel = createSelector([reducer], slice => slice.customModel);
