import _ from "lodash";
import ExerciseLibraryCard from "./ExerciseLibraryCard";
import {transformExercise} from "../../utils/workout/Exercise";
import ExerciseLibraryActionButtons from "./ExerciseLibraryActionButtons";
import React, {useCallback, useEffect, useMemo, useState} from "react";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {Dropdown, DropdownItem, DropdownMenu, DropdownToggle} from "react-bootstrap";
import {useTranslation} from "react-i18next";
import EmptySet from "../empty-set/EmptySet";
import Pagination from "../pagination/Pagination";

const SearchableExerciseList = ({
                                    query,
                                    onQueryChange,
                                    exercises,
                                    show,
                                    onFavoritesClick,
                                    onAllClick,
                                    onUserExercisesClick,
                                    searchBoxFocused,
                                    selectedGroup,
                                    setSelectedGroup,
                                    selectedCategory,
                                    setSelectedCategory,
                                    addedExercises,
                                    isReplace,
                                    handleReplace,
                                    isSerieReplace
                                }) => {
    const {t} = useTranslation();
    const [ex, setEx] = useState(exercises);
    const [selectedGroupName, setSelectedGroupName] = useState("");
    const [selectedCategoryName, setSelectedCategoryName] = useState("");
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(100);
    const pagesToShow = 5;

    useComponentTranslations("exerciseLibraryComponent", {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT,
    });

    const groups = useMemo(() => {
        if (!exercises) return [];
        return [
            ...new Map(exercises.map((item) => [item.exerciseGroup.id, item.exerciseGroup])).values(),
        ];
    }, [exercises]);

    const categories = useMemo(() => {
        if (!exercises) return [];
        return [
            ...new Map(exercises.map((item) => [item.exerciseCategory.id, item.exerciseCategory])).values(),
        ];
    }, [exercises]);

    const totalItems = ex?.length || 0;
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentItems = ex?.slice(indexOfFirstItem, indexOfLastItem);

    useEffect(() => {
        let filtered = exercises;
        if (selectedGroup) {
            filtered = filtered.filter(
                (exercise) => exercise.exerciseGroup.id === Number(selectedGroup)
            );
            const group = groups.find((g) => g.id === Number(selectedGroup));
            let groupName = group ? group.nome : t("exerciseLibraryComponent:defaultGroup");
            if (group && group.idUser === 0) {
                groupName = t(`exerciseLibraryComponent:${group.alias}`)
            }
            setSelectedGroupName(groupName)
        } else {
            setSelectedGroupName(t("exerciseLibraryComponent:defaultGroup"))
        }
        if (selectedCategory) {
            filtered = filtered.filter(
                (exercise) => exercise.exerciseCategory.id === Number(selectedCategory)
            );
            const cat = categories.find((c) => c.id === Number(selectedCategory));
            let catName = cat ? cat.name : t("exerciseLibraryComponent:defaultCategory");
            if (cat && cat.userId === 0) {
                catName = t(`exerciseLibraryComponent:${cat.name}`)
            }
            setSelectedCategoryName(catName);
        } else {
            setSelectedCategoryName(t("exerciseLibraryComponent:defaultCategory"))
        }
        setEx(filtered);
        setCurrentPage(1);
    }, [t, exercises, selectedGroup, selectedCategory, setSelectedGroupName, setSelectedCategoryName, categories, groups]);

    const handleClickGroup = (id) => {
        if (selectedGroup !== id && id > 0) {
            setSelectedGroup(id);
            const group = groups.find((g) => g.id === Number(id));
            let groupName = group ? group.nome : t("exerciseLibraryComponent:defaultGroup");
            if (group && group.idUser === 0) {
                groupName = t(`exerciseLibraryComponent:${group.alias}`)
            }
            setSelectedGroupName(groupName);
        } else {
            setSelectedGroup(null);
            setSelectedGroupName(t("exerciseLibraryComponent:defaultGroup"));
        }
    };

    const handleClickCategory = (id) => {
        if (selectedCategory !== id && id > 0) {
            setSelectedCategory(id);
            const cat = categories.find((c) => c.id === Number(id));
            let catName = cat ? cat.name : t("exerciseLibraryComponent:defaultCategory");
            if (cat && cat.userId === 0) {
                catName = t(`exerciseLibraryComponent:${cat.name}`)
            }
            setSelectedCategoryName(catName);
        } else {
            setSelectedCategory(null);
            setSelectedCategoryName(t("exerciseLibraryComponent:defaultCategory"));
        }
    };

    const handleResetAll = useCallback(() => {
        setSelectedGroup(null);
        setSelectedGroupName(t("exerciseLibraryComponent:defaultGroup"));
        setSelectedCategory(null);
        setSelectedCategoryName(t("exerciseLibraryComponent:defaultCategory"));
    }, [t, setSelectedGroupName, setSelectedCategoryName, setSelectedGroup, setSelectedCategory]);

    useEffect(() => {
        const totalPages = Math.ceil(totalItems / itemsPerPage);
        if (currentPage > totalPages && totalPages > 0) {
            setCurrentPage(totalPages);
        } else if (currentPage < 1) {
            setCurrentPage(1);
        }
    }, [ex, currentPage, totalItems, itemsPerPage]);

    return (
        <div className={"row "}>
            <div className="col-12">
                <input
                    type="search"
                    placeholder={t("exerciseLibraryComponent:searchExercises")}
                    className="form-control mt-1"
                    value={query}
                    onChange={(e) => onQueryChange(e.target.value)}
                />
            </div>
            <div className={`col-12 ${searchBoxFocused ? 'pt-5' : ''}`}>
                <ExerciseLibraryActionButtons
                    show={show}
                    onFavoritesClick={onFavoritesClick}
                    onAllClick={onAllClick}
                    onUserExercisesClick={onUserExercisesClick}
                />
            </div>
            <div className="col-12">
                <div className="row gap-2 mt-2 justify-content-center">
                    {groups && (
                        <div className="col-auto p-0">
                            <Dropdown onSelect={(e) => handleClickGroup(e)}>
                                <DropdownToggle
                                    size="sm"
                                    variant={`${selectedGroup ? " bg-success-subtle text-success" : "secondary-subtle text-primary"}`}
                                >
                                    {selectedGroupName}
                                </DropdownToggle>
                                <DropdownMenu className="border-0">
                                    <DropdownItem key={0} eventKey={0}>
                                        {t("exerciseLibraryComponent:allGroups")}
                                    </DropdownItem>
                                    {_.map(groups, (group) => (
                                        <DropdownItem key={group.id} eventKey={group.id}>
                                            {
                                                group.idUser > 0 ? group.nome :
                                                    t(`exerciseLibraryComponent:${group.alias}`)
                                            }
                                        </DropdownItem>
                                    ))}
                                </DropdownMenu>
                            </Dropdown>
                        </div>
                    )}
                    {categories && (
                        <div className="col-auto p-0">
                            <Dropdown onSelect={(e) => handleClickCategory(e)}>
                                <DropdownToggle
                                    size="sm"
                                    variant={`${selectedCategory ? " bg-success-subtle text-success" : "secondary-subtle text-primary"}`}
                                >
                                    {selectedCategoryName}
                                </DropdownToggle>
                                <DropdownMenu className="border-0">
                                    <DropdownItem key={0} eventKey={0}>
                                        {t("exerciseLibraryComponent:allCategories")}
                                    </DropdownItem>
                                    {_.map(categories, (cat) => (
                                        <DropdownItem key={cat.id} eventKey={cat.id}>
                                            {
                                                cat.userId > 0 ? cat.name :
                                                    t(`exerciseLibraryComponent:${cat.name}`)
                                            }
                                        </DropdownItem>
                                    ))}
                                </DropdownMenu>
                            </Dropdown>
                        </div>
                    )}
                    {(groups || categories) && (
                        <div className="col-auto p-0">
                            <button className="btn btn-link btn-sm" onClick={handleResetAll}>
                                {t("exerciseLibraryComponent:clear")}
                            </button>
                        </div>
                    )}
                </div>
            </div>
            <div className="col-12 mt-3 overflow-auto " style={{height:"500px"}}>
                {_.map(currentItems, (exercise) => (
                    <ExerciseLibraryCard key={exercise.id} hit={transformExercise(exercise)} addedExercises={addedExercises}
                                         isReplace={isReplace} handleReplace={handleReplace} isSerieReplace={isSerieReplace}/>
                ))}
                {
                    totalItems > itemsPerPage && (
                        <div className="row justify-content-center mt-3" >
                            <div className="col-auto overflow-auto">
                                <Pagination
                                    currentPage={currentPage}
                                    totalItems={totalItems}
                                    itemsPerPage={itemsPerPage}
                                    onPageChange={setCurrentPage}
                                    pagesToShow={pagesToShow}
                                />
                            </div>
                        </div>
                    )
                }
                {
                    (ex?.length === 0 || !ex) &&
                    <div className={"mt-3 mb-3"}>
                        {
                            show === "favorites" &&
                            <EmptySet icon={"fa-star"} message={t("exerciseLibraryComponent:noFavorites")}/>
                        }
                        {
                            show === "user" &&
                            <EmptySet icon={"fa-running"} message={t("exerciseLibraryComponent:noCustomExercises")}/>
                        }
                    </div>
                }
            </div>
        </div>
    );
};

export default SearchableExerciseList;
