import i18n from "i18next";
import {initReactI18next} from "react-i18next";
import LanguageDetector from "i18next-browser-languagedetector";
import {
    DEFAULT_APP_LOCALE,
    normalizeAppLocale,
    SUPPORTED_APP_LOCALES,
    syncDocumentLocale,
    syncMomentLocale
} from "./utils/translation/localeUtils";
import {getRegisteredNamespaces, translationResources} from "./utils/translation/translationRegistry";

i18n
    .use(LanguageDetector)
    .use(initReactI18next)
    .init({
        lng: DEFAULT_APP_LOCALE,
        fallbackLng: DEFAULT_APP_LOCALE,
        supportedLngs: SUPPORTED_APP_LOCALES,
        ns: getRegisteredNamespaces(),
        load: "currentOnly",
        resources: translationResources,
        interpolation: {
            escapeValue: false
        },
        detection: {
            order: ['localStorage', 'navigator'],
            caches: ['localStorage'],
            convertDetectedLanguage: (language) => normalizeAppLocale(language)
        }
    }).then(() => {
        const activeLanguage = i18n.resolvedLanguage || i18n.language;
        syncMomentLocale(activeLanguage);
        syncDocumentLocale(activeLanguage);
});

i18n.on("languageChanged", (language) => {
    syncMomentLocale(language);
    syncDocumentLocale(language);
});

export default i18n;
