import noWalletImage from "../../assets/img/wallet/sales-page.png";
import {handleGoToWallet} from "../../utils/handlers/handler";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WalletSalesPageModalCard = ({walletRequest,handleClose}) => {
    const {t} = useTranslation();
    useComponentTranslations('wallet', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});


    return (
        <div className={"row justify-content-center"}>
            <div className={'col-8  '}>
                <img src={`${noWalletImage}`} className={"img-fluid"} alt={""}/>
            </div>
            <div className={"col-12 text-center"}>
                <span className={"fw-semibold"} style={{fontSize: "1rem"}}>{t("wallet:createYour")} <span className={"text-primary"}>{t("wallet:salesPage")}</span> {t("wallet:andRaiseYourCareer")}</span>
            </div>
            {
                (!walletRequest || walletRequest?.status !== 5 || walletRequest?.status === 0) ?
                    <div className={"col-12 pt-2 "}>
                        <div className={'card card-body bg-info-lighter  border-0'}>
                            <div className={"row"}>
                                <div className={'col-2 align-self-center'}>
                                    <i className={'fa-regular fa-info-circle fa-2xl text-primary-darker'}></i>
                                </div>
                                <div className={"col-10 align-self-center ps-0"}>
                                    <span className={"small text-primary-darker fw-semibold d-block"}>{t("wallet:availableForMFITWallet")}</span>
                                </div>
                            </div>
                        </div>
                        <div className={"d-grid pt-2"}>
                            <button className={'btn btn-primary'} onClick={handleGoToWallet}>{t("wallet:createWallet")}</button>
                            <button className={'btn btn-outline-primary mt-2'} onClick={handleClose}>{t("wallet:close")}</button>
                        </div>
                    </div>
                    :
                    <div className={"col-12 pt-2 "}>
                        {
                            (walletRequest && walletRequest.status !== 9 && walletRequest.status !== 0) &&
                            <>
                                <div className={'card card-body bg-warning-subtle  border-0'}>
                                    <div className={"row"}>
                                        <div className={'col-2 align-self-center'}>
                                            <i className={'fa-regular fa-info-circle fa-2xl text-warning-darker'}></i>
                                        </div>
                                        <div className={"col-10 align-self-center ps-0"}>
                                            <span className={"small text-warning-darker fw-semibold"}>{t("wallet:walletAnalysis")}</span>
                                        </div>
                                    </div>
                                </div>
                                <div className={'d-grid pt-2'}>
                                    <button className={'btn btn-primary-darker'}>{t("wallet:checkStatus")}</button>
                                </div>
                            </>
                        }
                    </div>
            }
        </div>
    )

}

export default WalletSalesPageModalCard;