import React from 'react';
import { Bar } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    Tooltip,
    Legend
} from 'chart.js';
import ChartDataLabels from "chartjs-plugin-datalabels";

ChartJS.register(
    CategoryScale,
    LinearScale,
    BarElement,
    Tooltip,
    Legend,
    ChartDataLabels
);

const BarChart = ({ dataValues, labels }) => {
    const backgroundColors = ['#06A0FF', '#0070B6'];

    const data = {
        labels: labels,
        datasets: [
            {
                label: 'kg',
                data: dataValues,
                backgroundColor: backgroundColors,
                borderRadius: 4,
                borderSkipped: false,
                barThickness: 60,
            }
        ]
    };

    const options = {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true,
            }
        },
        plugins: {
            datalabels: {
                formatter: (value) => {
                  return value + 'kg';
                },
                color: '#fff',
                font: {
                    weight: '900',
                    size: 12,
                },
            },
            legend: {
                display: false,
            }
        }
    };

    return <Bar data={data} options={options} />;
};

export default BarChart;
