import {useState} from "react";
import {Image} from "react-bootstrap";

const ProgressPhotoPreview = ({
    src,
    alt = "",
    expandLabel,
    minimizeLabel,
    collapsedHeight = 154,
    expandedHeight = 480,
    imageClassName = "rounded-1 w-100 h-100",
    buttonClassName = "btn btn-link text-primary fw-semibold text-decoration-none p-0 small"
}) => {
    const [expanded, setExpanded] = useState(false);

    return (
        <div className={"d-flex flex-column align-items-center gap-2"}>
            <div
                className={"w-100 overflow-hidden rounded-1"}
                style={{height: expanded ? `${expandedHeight}px` : `${collapsedHeight}px`}}
            >
                <Image
                    src={src}
                    alt={alt}
                    fluid
                    className={imageClassName}
                    style={{objectFit: "cover"}}
                />
            </div>
            <button
                type={"button"}
                className={buttonClassName}
                onClick={() => setExpanded(prevState => !prevState)}
            >
                {expanded ? minimizeLabel : expandLabel}
            </button>
        </div>
    );
};

export default ProgressPhotoPreview;
