import * as Yup from "yup";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect, useMemo, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {selectUser} from "../../store/user/userSelector";
import {fetchClient} from "../../store/client/clientReducer";
import {
    fetchLastBioimpedance,
    fetchOneBioimpedance, resetFormSent,
    updateBioimpedance
} from "../../store/bioimpedance-evaluation/bioimpedanceReducer";
import {
    getLoading,
    getOneBioimpedance,
    getSubmitLoading,
    getSubmitResult
} from "../../store/bioimpedance-evaluation/bioimpedanceSelector";
import Page from "../../components/page/Page";
import moment from "moment";
import {bioProtocol} from "../../utils/physicalEvaluation/protocolData";
import {ErrorMessage, Field, Form, Formik} from "formik";
import EvaluationImageUpload from "../../utils/imageupdate/EvaluationImageUpload";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import useScrollToError from "../../utils/scrolltoerror/scrollToError";
import EvaluationSubmitButton from "../../components/evaluation-components/EvaluationSubmitButton";
import {
    buildBioimpedanceEndRoute,
    buildClientBioimpedanceRoute
} from "../../utils/client/evaluationRoutes";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const BioimpedanceEdit = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, bioimpedanceId} = useParams();
    const {t} = useTranslation("bioimpedanceEvaluation");
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const user = useSelector(selectUser);
    const bioimpedanceDetail = useSelector(getOneBioimpedance);
    const submitLoading = useSelector(getSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const [uploadedImages, setUploadedImages] = useState([]);
    const currentClientId = Number(id);
    useComponentTranslations('bioimpedanceEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT})

    const scrollToFirstError = useScrollToError();

    const currentProtocol = useMemo(() => {
        const protoId = Number(bioimpedanceDetail?.protocolo);
        return bioProtocol.find(p => Number(p.id) === protoId) ?? null;
    }, [bioimpedanceDetail]);

    const groupedFields = currentProtocol?.fields?.reduce((acc, field) => {
        const section = field.section || "Outros";
        if (!acc[section]) acc[section] = [];
        acc[section].push(field);
        return acc;
    }, {});

    const validationSchema = useMemo(() => {
        const requiredFields = [
            "data",
            "idade",
            "estatura",
            "peso"
        ];
        const shape = {};
        requiredFields.forEach((fid) => {
            const field = currentProtocol?.fields.find(f => f.id === fid);
            if (!field) return;

            if (fid === "data" || field.type === "date") {
                shape[fid] = Yup.date()
                    .typeError(
                        `${t(`bioimpedanceEvaluation:fields.${field.labelKey}`)} ${t("bioimpedanceEvaluation:validDate")}`
                    )
                    .required(
                        `${t(`bioimpedanceEvaluation:fields.${field.labelKey}`)} ${t("bioimpedanceEvaluation:isMandatory")}`
                    );
            } else if (field.type === "number") {
                shape[fid] = Yup.number()
                    .typeError(
                        `${t(`bioimpedanceEvaluation:fields.${field.labelKey}`)} ${t("bioimpedanceEvaluation:mustBeaNumber")}`
                    )
                    .positive(
                        `${t(`bioimpedanceEvaluation:fields.${field.labelKey}`)} ${t("bioimpedanceEvaluation:positiveValue")}`
                    )
                    .required(
                        `${t(`bioimpedanceEvaluation:fields.${field.labelKey}`)} ${t("bioimpedanceEvaluation:isMandatory")}`
                    );
            } else {
                shape[fid] = Yup.string()
                    .trim()
                    .required(
                        `${t(`bioimpedanceEvaluation:fields.${field.labelKey}`)} ${t("bioimpedanceEvaluation:isMandatory")}`
                    );
            }
        });
        return Yup.object().shape(shape);
    }, [currentProtocol, t]);

    const handleGoBackPage = () => {
        navigate(buildClientBioimpedanceRoute(id));
    };

    const handleImagesUpload = (urls) => {
        setUploadedImages(urls);
    };

    const handleSubmit = async (values, formikHelpers) => {
        const errors = await formikHelpers.validateForm(values);
        if (Object.keys(errors).length > 0) {
            formikHelpers.setTouched(
                Object.keys(errors).reduce((t, key) => ({...t, [key]: true}), {})
            );
            setTimeout(() => scrollToFirstError(errors), 0);
        }

        const validImages = (uploadedImages || []).filter(Boolean);
        const payload = {
            id: bioimpedanceId,
            id_aluno: Number(id),
            gender: selectedClient.sexo,
            protocolo: Number(currentProtocol.id),
            idade: Number(values.idade),
            data: bioimpedanceDetail.data,
            estatura: Number(values.estatura),
            peso: Number(values.peso),
            proximaAvaliacao: values.proximaAvaliacao,
            images: validImages,
            ...values
        };
        dispatch(updateBioimpedance(payload, {
            flow: EVALUATION_FLOWS.BIOIMPEDANCE_EDIT,
            clientId: currentClientId
        }));
    };

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(fetchOneBioimpedance({id: bioimpedanceId}))
    }, [dispatch, bioimpedanceId]);

    useEffect(() => {
        dispatch(fetchLastBioimpedance({clientId: currentClientId}));
    }, [currentClientId, dispatch]);

    useEffect(() => {
        if (isMatchingSubmitSuccess(submitResult, {
            action: "update",
            flow: EVALUATION_FLOWS.BIOIMPEDANCE_EDIT,
            clientId: currentClientId
        })) {
            navigate(buildBioimpedanceEndRoute(id, submitResult.entityId ?? bioimpedanceId));
        }
    }, [submitResult, navigate, id, bioimpedanceId, currentClientId]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} loading={loading} pb={"pb-2"}>
                <div className={"card card-body border-0"}>
                    {currentProtocol && groupedFields && (
                        <Formik enableReinitialize
                                initialValues={currentProtocol.fields.reduce((acc, field) => ({
                                    ...acc,
                                    [field.id]: bioimpedanceDetail ? bioimpedanceDetail[field.id] || "" : ""
                                }), {})}
                                validationSchema={validationSchema}
                                onSubmit={handleSubmit}
                                validateOnChange={true}
                                validateOnBlur={true}
                        >
                            {({errors, touched, submitForm, setTouched, validateForm }) => (
                                <Form><span
                                    className={"fw-semibold"}>{t("bioimpedanceEvaluation:bioimpedanceTitle")}</span>
                                    {Object.entries(groupedFields).map(([section, fields]) => (
                                        <div key={section} className={"my-2"}>
                                            {section !== "Pessoal" && (
                                                <span className={"fw-semibold fs-5 mb-2 pb-2"}>{section}</span>
                                            )}
                                            {fields.map((field) => {
                                                    const showError = Boolean(errors[field.id] && touched[field.id]);
                                                    return (
                                                        <div key={field.id} className={"mb-3"}>
                                                            <label htmlFor={field.id} className={"fw-semibold"}>
                                                                {t(`bioimpedanceEvaluation:fields.${field.labelKey}`)}
                                                            </label>
                                                            {field.type === "number" ? (
                                                                <Field name={field.id}>
                                                                    {({field: inputField, form}) => {
                                                                        const errNum = form.errors[field.id] && form.touched[field.id];
                                                                        return (
                                                                            <>
                                                                                <input
                                                                                    {...inputField}
                                                                                    id={field.id}
                                                                                    type="text"
                                                                                    placeholder={ t(`bioimpedanceEvaluation:placeholders.${field.placeholderKey}`) }
                                                                                    className={`form-control${errNum ? " is-invalid" : ""}`}
                                                                                    min={0}
                                                                                    inputMode="decimal"
                                                                                    onKeyDown={(e) => {
                                                                                        if (e.key === '-') {
                                                                                            e.preventDefault();
                                                                                        }
                                                                                    }}
                                                                                    onChange={(e) => {
                                                                                        let value = e.target.value;
                                                                                        value = value.replace(',', '.');
                                                                                        if (!/^(\d+(\.\d*)?)?$/.test(value)) {
                                                                                            return;
                                                                                        }
                                                                                        form.setFieldValue(field.id, value);
                                                                                    }}
                                                                                    onBlur={inputField.onBlur}
                                                                                />
                                                                                <ErrorMessage
                                                                                    name={field.id}
                                                                                    component="div"
                                                                                    className="invalid-feedback"
                                                                                />
                                                                            </>
                                                                        );
                                                                    }}
                                                                </Field>
                                                            ) : field.id === "data" ? (
                                                                <Field name="data">
                                                                    {({field, form}) => {
                                                                        const err = form.errors.data && form.touched.data;
                                                                        return (
                                                                            <>
                                                                                <input
                                                                                    {...field}
                                                                                    id="data"
                                                                                    type="date"
                                                                                    className={`form-control${err ? " is-invalid" : ""}`}
                                                                                    onChange={(e) => {
                                                                                        const selectedDate = e.target.value;
                                                                                        form.setFieldValue("data", selectedDate);
                                                                                        const nextEvalDate = moment(selectedDate)
                                                                                            .add(90, "days")
                                                                                            .format("YYYY-MM-DD");
                                                                                        form.setFieldValue("proximaAvaliacao", nextEvalDate);
                                                                                    }}
                                                                                />
                                                                                <ErrorMessage
                                                                                    name="data"
                                                                                    component="div"
                                                                                    className="invalid-feedback"
                                                                                />
                                                                            </>
                                                                        );
                                                                    }}
                                                                </Field>
                                                            ) : ['objetivo', 'observacao'].includes(field.id) ? (
                                                                <>
                                                                    <Field
                                                                        as="textarea"
                                                                        id={field.id}
                                                                        name={field.id}
                                                                        placeholder={ t(`bioimpedanceEvaluation:placeholders.${field.placeholderKey}`) }
                                                                        className={`form-control${showError ? " is-invalid" : ""}`}
                                                                    />
                                                                    <ErrorMessage
                                                                        name={field.id}
                                                                        component="div"
                                                                        className="invalid-feedback"
                                                                    />
                                                                </>
                                                            ) : (
                                                                <Field
                                                                    id={field.id}
                                                                    name={field.id}
                                                                    type={field.type}
                                                                    placeholder={ t(`bioimpedanceEvaluation:placeholders.${field.placeholderKey}`) }
                                                                    className={`form-control${showError ? " is-invalid" : ""}`}
                                                                />
                                                            )}
                                                        </div>
                                                    )
                                                })}
                                        </div>
                                    ))}
                                    <div className={"row"}>
                                        <span
                                            className={"fw-semibold mt-3"}>{t("bioimpedanceEvaluation:studentPhotos")}</span>
                                        <EvaluationImageUpload
                                            user={user}
                                            slots={4}
                                            selectedClient={selectedClient}
                                            onImagesUpload={handleImagesUpload}
                                            existingImages={bioimpedanceDetail.images || []}
                                            basePath="bioimpedanceevaluation"
                                            Anexar={t("bioimpedanceEvaluation:attach")}
                                        />
                                    </div>
                                    <div className="text-end mt-3">
                                        <EvaluationSubmitButton
                                            type="button"
                                            label={t("bioimpedanceEvaluation:save")}
                                            loadingLabel={t("bioimpedanceEvaluation:save")}
                                            isSubmitting={submitLoading}
                                            onClick={async () => {
                                                const errs = await validateForm();
                                                if (Object.keys(errs).length > 0) {
                                                    setTouched(
                                                        Object.keys(errs).reduce((t, key) => ({
                                                            ...t,
                                                            [key]: true
                                                        }), {}),
                                                        false
                                                    );
                                                    setTimeout(() => scrollToFirstError(errs), 0);
                                                } else {
                                                    submitForm()
                                                }
                                            }}
                                        />
                                    </div>
                                </Form>
                            )}
                        </Formik>
                    )}
                </div>
            </Page>
        </>
    )
}

export default BioimpedanceEdit;
