import {createSelector} from "reselect";

const reducer = state => state.bioimpedance;

export const getOneBioimpedance = createSelector([reducer], slice => slice.oneBioimpedance);

export const getBioimpedanceList = createSelector([reducer], slice => slice.bioimpedanceList);

export const getLoading = createSelector([reducer], slice => slice.initialLoading);

export const getLastBioimpedance = createSelector([reducer], slice => slice.lastBioimpedance);

export const getSubmitLoading = createSelector([reducer], slice => slice.submitLoading);

export const getSubmitResult = createSelector([reducer], slice => slice.submitResult);
