import axios from "axios";
import {apiUrl, getToken} from "../../api/api";

const DEFAULT_TIMEOUT_MS = 20000;

export const axiosBaseQuery = ({baseUrl = apiUrl} = {}) => async ({
    url,
    method = "get",
    data,
    params,
    headers,
    timeout = DEFAULT_TIMEOUT_MS
}, {signal}) => {
    const token = getToken();

    try {
        const result = await axios({
            url: `${baseUrl}${url}`,
            method,
            data,
            params,
            timeout,
            signal,
            headers: {
                "Content-Type": "application/json",
                ...(token ? {authorization: token} : {}),
                ...(headers || {})
            }
        });

        return {data: result.data};
    } catch (error) {
        return {
            error: {
                status: error.response?.status || error.code || "UNKNOWN_ERROR",
                data: error.response?.data,
                code: error.code,
                originalError: error
            }
        };
    }
};
