import {useEffect, useMemo} from "react";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {useTranslation} from "react-i18next";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import {fetchClient} from "../../store/client/clientReducer";
import {selectSelectedClient} from "../../store/client/clientSelector";
import {fetchClientGroups} from "../../store/client-group/clientGroupReducer";
import {selectClientGroups} from "../../store/client-group/clientGroupSelector";
import {
    clearCreateExtraTraining,
    createExtraTraining
} from "../../store/extratraining/extraTrainingReducer";
import {
    selectCreateExtraTrainingLoading,
    selectCreateExtraTrainingSuccess
} from "../../store/extratraining/extraTrainingSelector";
import ExtraTrainingEditorForm from "../../components/extra-training/ExtraTrainingEditorForm";

const ExtraTrainingCreate = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const {clientId} = useParams();
    const selectedClient = useSelector(selectSelectedClient);
    const clientGroups = useSelector(selectClientGroups);
    const createLoading = useSelector(selectCreateExtraTrainingLoading);
    const createSuccess = useSelector(selectCreateExtraTrainingSuccess);

    useComponentTranslations("extraTrainingUser", {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR});

    useEffect(() => {
        dispatch(fetchClient(clientId));
        dispatch(fetchClientGroups());
    }, [clientId, dispatch]);

    useEffect(() => {
        if (createSuccess) {
            navigate(`/user/client/${clientId}/extratraining`);
            dispatch(clearCreateExtraTraining());
        }
    }, [clientId, createSuccess, dispatch, navigate]);

    const handleGoBackPage = () => navigate(`/user/client/${clientId}/extratraining`);

    const groupOptions = useMemo(
        () => (clientGroups || []).map(group => ({value: group.id, label: group.nome})),
        [clientGroups]
    );

    const initialValues = useMemo(() => {
        const now = new Date();
        const localDate = new Date(now.getTime() - (now.getTimezoneOffset() * 60000)).toISOString().slice(0, 10);
        return {
            executeAt: localDate,
            atividade: "",
            instructions: "",
            url: "",
            notificar: false,
            clients: [],
            groups: []
        };
    }, []);

    const handleSubmit = (values) => {
        dispatch(createExtraTraining({
            id: Number(clientId),
            formData: {
                ...values,
                timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
            }
        }));
    };

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}

            />
            <Page contentHeader={false} loading={Boolean(createSuccess)} >
                <div className="row justify-content-center d-flex">
                    <div className="col-12">
                        <div className="card card-body border-0">
                            <span className="fw-semibold fs-5">{t("extraTrainingUser:configureExtraTraining")}</span>
                            <div className="mt-3">
                                <ExtraTrainingEditorForm
                                    initialValues={initialValues}
                                    onSubmit={handleSubmit}
                                    loading={createLoading}
                                    submitLabel={t("extraTrainingUser:saveExtraTraining")}
                                    showTrainingFields={true}
                                    showRecipients={true}
                                    groupOptions={groupOptions}
                                    enforceCurrentClient={true}
                                    excludedClientId={Number(clientId)}
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default ExtraTrainingCreate;
