import {createSlice} from "@reduxjs/toolkit";
import moment from "moment";

const INITIAL_STATE = {
    aerobic: null,
    paces: null,
    nameUpdated: false,
    aerobics: null,
    loadingPace: false,
    changingStatus: false,
    aerobicLoadingInstructions: false,
    updatingDay: null,
    loading: false
}

export const slice = createSlice({
    name: "aerobics",
    initialState: INITIAL_STATE,
    reducers: {
        createAerobicDay(state) {
            state.loading = true
        },
        aerobicDayCreated(state, action) {
            state.loading = false
            if (Array.isArray(action.payload)) {
                const days = [...action.payload]
                if (state.aerobic.weeks) {
                    // workout uses dates grouped by week
                    const weeks = {}
                    days.sort((a, b) => new Date(a.dia) - new Date(b.dia))
                        .forEach(day => {
                            const week = moment(day.dia).week().toString()
                            if (!weeks[week]) weeks[week] = []
                            weeks[week].push(day)
                        })
                    Object.keys(weeks).forEach(key => {
                        weeks[key].sort((a, b) => new Date(a.dia) - new Date(b.dia))
                    })
                    state.aerobic.weeks = weeks
                    state.aerobic.days = null
                } else {
                    // numeric based days
                    state.aerobic.days = days.sort((a, b) => a.diaNumero - b.diaNumero)
                }
            } else if (action.payload) {
                // response already grouped by weeks
                const weeks = {}
                Object.keys(action.payload)
                    .sort((a, b) => Number(a) - Number(b))
                    .forEach(key => {
                        weeks[key] = [...action.payload[key]]
                            .sort((d1, d2) => new Date(d1.dia) - new Date(d2.dia))
                    })
                state.aerobic.weeks = weeks
                state.aerobic.days = null
            }
        },
        deleteDay(state, action) {
            const {id} = action.payload;
            if (Array.isArray(state.aerobic.days)) {
                state.aerobic.days = state.aerobic.days.filter(day => day.id !== id);
            } else if (state.aerobic.weeks) {
                Object.keys(state.aerobic.weeks).forEach(weekKey => {
                    state.aerobic.weeks[weekKey] = state.aerobic.weeks[weekKey]
                        .filter(day => day.id !== id);
                });
            }
        },
        updateAerobicDay(state, action) {
            state.updatingDay = action.payload?.id ?? null
        },
        setAerobicDayUpdated(state) {
            state.updatingDay = null
        },
        getAerobic(state) {
            state.loading = true
        },
        setAerobic(state, action) {
            state.loading = false
            state.aerobic = action.payload
        },
        updateAerobicInstructions(state) {
            state.aerobicLoadingInstructions = true
        },
        aerobicInstructionsUpdated(state) {
            state.aerobicLoadingInstructions = false
        },
        createAerobic(state) {
            state.loading = true
        },
        setCreateAerobicStatus(state, action) {
            state.aerobicCreated = action.payload;
        },
        updateName(state) {
            state.loading = false
        },
        updateNameSuccess(state, action) {
            state.nameUpdated = action.payload;
        },
        updateAerobicWorkoutName(state, action) {
            const {id, name} = action.payload
            if (state.aerobics) {
                state.aerobics = state.aerobics?.map(aerobic => {
                    if (aerobic.id === id) {
                        return {...aerobic, nome: name};
                    }
                    return aerobic
                })
            }
        },
        changeAerobicStatus(state) {
            state.changingStatus = true;
        },
        changeStatusSuccess(state, action) {
            state.changingStatus = false;
            state.aerobics = state.aerobics.filter(aerobic => aerobic.id !== action.payload)
        },
        fetchAerobicsByStatus(state) {
            state.loading = true
        },
        setAerobics(state, action) {
            state.loading = false
            state.aerobics = action.payload
        },
        createPace(state) {
            state.loadingPace = true
        },
        createPaceSuccess(state, action) {
            state.loadingPace = false
            state.paces.push(action.payload)
        },
        deletePace(state, action) {
            state.paces = state.paces.filter(pace => pace.id !== action.payload)
        },
        deletePaceSuccess(state, action) {
        },
        fetchAllPaces(state) {
            state.loading = true
        },
        setPaces(state, action) {
            state.loading = false
            state.paces = action.payload
        },
        onError(state){
            state.loading = false
            state.updatingDay = null
        }
    }
})

export const {
    fetchAerobicsByStatus,
    createPace,
    createPaceSuccess,
    deletePace,
    deletePaceSuccess,
    fetchAllPaces,
    setPaces,
    updateName,
    updateNameSuccess,
    changeAerobicStatus,
    changeStatusSuccess,
    setAerobics,
    createAerobic,
    setCreateAerobicStatus,
    updateAerobicInstructions,
    aerobicInstructionsUpdated,
    getAerobic,
    setAerobic,
    updateAerobicDay,
    deleteDay,
    aerobicDayCreated,
    createAerobicDay,
    updateAerobicWorkoutName,
    setAerobicDayUpdated,
    onError
} = slice.actions

export const workoutAerobicReducer = slice.reducer
