import React, {useEffect, useMemo, useState} from 'react';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import * as Yup from 'yup';
import {useNavigate} from 'react-router-dom';
import SubscriptionPlanCard from "./SubscriptionPlanCard";
import {
    cancelSubscription,
    changeUserToMonthlyPlan,
    fetchSubPlanList,
    setLoadingSubChange,
    setSubscriptionCanceled
} from "../../store/subscription/subscriptionReducer";
import {useDispatch, useSelector} from "react-redux";
import {
    selectChangeSubLoading,
    selectFreePlanChanged,
    selectLoadingSubscription,
    selectSubPlanList,
    selectSubscriptionCanceled
} from "../../store/subscription/subscriptionSelector";
import {fetchUser} from "../../store/user/userReducer";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import {addToast} from "../../store/toast/toastReducer";

const SubscriptionCancellationForm = ({user, onClose}) => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {t} = useTranslation();
    useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const subPlanList = useSelector(selectSubPlanList)
    const [showOffer, setShowOffer] = useState(false);
    const loadingSubscription = useSelector(selectLoadingSubscription);
    const subscriptionCanceled = useSelector(selectSubscriptionCanceled);
    const subPlanLoading = useSelector(selectChangeSubLoading)
    const planChanged = useSelector(selectFreePlanChanged);

    const handleSubmit = (values) => {
        dispatch(cancelSubscription(values));
    }

    const handleDismissOffer = () => {
        setShowOffer(false)
    }

    const handleChangePlansClick = () => {
        dispatch(changeUserToMonthlyPlan())
    };

    const initialValues = {
        reason: '',
        comments: '',
    };

    const validationSchema = useMemo(() => Yup.object().shape({
        reason: Yup.string()
            .required(t('subscriptionComponent:subscriptionCancellationForm.reasonRequired')),
        comments: Yup.string()
            .when('reason', {
                is: 'other',
                then: schema => schema.required(t('subscriptionComponent:subscriptionCancellationForm.otherRequired')),
                otherwise: schema => schema.optional(),
            })
            .when('reason', {
                is: 'changedApp',
                then: schema => schema.required(t('subscriptionComponent:subscriptionCancellationForm.changedAppRequired')),
            }),
    }), [t]);

    useEffect(() => {
        setShowOffer(user.subPlan.id !== 1000 && user.subPlan.id !== 1004)
    }, [user]);

    useEffect(() => {
        if (!subPlanList)
            dispatch(fetchSubPlanList());
    }, [subPlanList, dispatch]);

    useEffect(() => {
        if (subscriptionCanceled) {
            dispatch(fetchUser())
            dispatch(setSubscriptionCanceled(false))
            onClose()
        }
    }, [subscriptionCanceled, dispatch, onClose]);

    useEffect(() => {
        if (planChanged) {
            dispatch(fetchUser())
            dispatch(addToast({
                title: t('subscriptionComponent:subscriptionCancellationForm.planChangedSuccessTitle'),
                message: t('subscriptionComponent:subscriptionCancellationForm.planChangedSuccessMessage'),
                type: "success"
            }))
            dispatch(setLoadingSubChange({loading: false, changed: false}))
            navigate('/subscription')
        }
    }, [t, planChanged, dispatch, navigate]);

    return (
        <div className="row">
            <div className="col-12">
                <Formik
                    initialValues={initialValues}
                    validationSchema={validationSchema}
                    onSubmit={handleSubmit}
                >
                    {({values}) => (
                        <Form>
                            <div className="mb-3">
                                <label htmlFor="reason"
                                       className="form-label fw-semibold">{t('subscriptionComponent:subscriptionCancellationForm.title')}</label>
                                <Field as="select" name="reason" id="reason" className="form-select">
                                    <option value="">{t('subscriptionComponent:subscriptionCancellationForm.selectOption')}</option>
                                    <option value="price">{t('subscriptionComponent:subscriptionCancellationForm.priceOption')}</option>
                                    <option value="noClients">{t('subscriptionComponent:subscriptionCancellationForm.noClientsOption')}</option>
                                    <option value="changedApp">{t('subscriptionComponent:subscriptionCancellationForm.changedAppOption')}</option>
                                    <option value="other">{t('subscriptionComponent:subscriptionCancellationForm.otherOption')}</option>
                                </Field>
                                <ErrorMessage name="reason" component="div" className="text-danger"/>
                            </div>

                            {values.reason === 'price' && showOffer && (
                                <div className="">
                                    <span className="fw-semibold text-center d-block mb-2">
                                        {t('subscriptionComponent:subscriptionCancellationForm.monthlyOfferHeadline')}
                                    </span>
                                    <SubscriptionPlanCard subPlan={subPlanList?.find(s => s.id === 1000)} disableClick={true}/>
                                    <div className="mt-4">
                                        <div className="row justify-content-between">
                                            <div className="col-12">
                                                <button
                                                    type="button"
                                                    className="btn btn-primary me-2 w-100"
                                                    onClick={handleChangePlansClick}
                                                    disabled={subPlanLoading}
                                                >
                                                    {t('subscriptionComponent:subscriptionCancellationForm.monthlyOfferCta')}
                                                </button>
                                            </div>
                                            <div className="col-12 mt-2">
                                                <button
                                                    type="submit"
                                                    className="btn btn-link text-danger w-100 fw-semibold"
                                                    onClick={handleDismissOffer}
                                                >
                                                    {t('subscriptionComponent:subscriptionCancellationForm.cancelAnyway')}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {values.reason === 'price' && !showOffer && (
                                <div className="mb-3">
                                    <label htmlFor="comments" className="form-label fw-semibold">
                                        {t('subscriptionComponent:subscriptionCancellationForm.priceQuestion')}
                                    </label>
                                    <Field
                                        as="textarea"
                                        name="comments"
                                        id="comments"
                                        className="form-control"
                                        rows={3}
                                    />
                                </div>
                            )}

                            {values.reason === 'noClients' && (
                                <div className="mb-3">
                                    <label htmlFor="comments" className="form-label fw-semibold">
                                        {t('subscriptionComponent:subscriptionCancellationForm.noClientsQuestion')}
                                    </label>
                                    <Field
                                        as="textarea"
                                        name="comments"
                                        id="comments"
                                        className="form-control"
                                        rows={3}
                                    />
                                </div>
                            )}

                            {values.reason === 'changedApp' && (
                                <div className="mb-3">
                                    <label htmlFor="comments" className="form-label fw-semibold">
                                        {t('subscriptionComponent:subscriptionCancellationForm.changedAppQuestion')}
                                    </label>
                                    <Field
                                        as="textarea"
                                        name="comments"
                                        id="comments"
                                        className="form-control"
                                        rows={3}
                                    />
                                    <ErrorMessage name="comments" component="div" className="text-danger"/>
                                </div>
                            )}

                            {values.reason === 'other' && (
                                <div className="mb-3">
                                    <label htmlFor="comments" className="form-label fw-semibold">
                                        {t('subscriptionComponent:subscriptionCancellationForm.otherQuestion')}
                                    </label>
                                    <Field
                                        as="textarea"
                                        name="comments"
                                        id="comments"
                                        className="form-control"
                                        rows={3}
                                    />
                                    <ErrorMessage name="comments" component="div" className="text-danger"/>
                                </div>
                            )}

                            {!(values.reason === 'price' && showOffer) && (
                                <button
                                    type="submit"
                                    className="btn btn-primary w-100"
                                    disabled={loadingSubscription}
                                >
                                    {t('subscriptionComponent:subscriptionCancellationForm.submit')}
                                </button>
                            )}
                        </Form>
                    )}
                </Formik>
            </div>

        </div>
    );
};

export default SubscriptionCancellationForm;
