import he from 'he';
import {useState} from "react";
import Modal from "react-bootstrap/Modal";

const Text = ({children, short, className, length = 30, style, enableAccessibility = false}) => {
    const [show, setShow] = useState(false)
    const handleModal = () => {
        setShow((prevState) => !prevState)
    }

    const isDecodable = typeof children === "string" || typeof children === "number";
    let text = isDecodable ? String(children) : "";
    if (short && isDecodable) {
        text = text.length > length ? text.slice(0, length) + "..." : text
    }

    return (
        <>
            <span style={style} className={className}
                  onClick={enableAccessibility ? handleModal : null}>
                {isDecodable ? he.decode(text) : children}
            </span>
            {
                enableAccessibility &&
                <Modal centered show={show} onHide={handleModal}>
                    <Modal.Body>
                        <span style={style} className={`${className} fs-5`}><pre
                            className={'mb-0'}>{isDecodable ? he.decode(text) : children}</pre></span>
                    </Modal.Body>
                </Modal>
            }
        </>
    )
}
export default Text;
