import translationManifest from "./translationManifest.generated.json";

export const translationResources = translationManifest;

const hasLeafTranslations = (value) => {
    if (value == null) {
        return false;
    }

    if (typeof value !== "object" || Array.isArray(value)) {
        return true;
    }

    return Object.values(value).some((child) => hasLeafTranslations(child));
};

export const getRegisteredNamespaces = () => {
    const namespaces = new Set();

    Object.values(translationResources).forEach((resourcesByNamespace) => {
        Object.keys(resourcesByNamespace || {}).forEach((namespace) => {
            if (hasLeafTranslations(resourcesByNamespace?.[namespace])) {
                namespaces.add(namespace);
            }
        });
    });

    return [...namespaces].sort((a, b) => a.localeCompare(b));
};

export const hasRegisteredNamespace = (namespace) => (
    Object.values(translationResources).some(
        (resourcesByNamespace) => hasLeafTranslations(resourcesByNamespace?.[namespace])
    )
);
