import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {selectPaymentCountry, selectUser} from "../../store/user/userSelector";
import React, {useEffect, useState} from "react";
import {fetchUser, getPaymentCountry} from "../../store/user/userReducer";
import SubscriptionCard from "../../components/subscription/SubscriptionCard";
import {useNavigate} from "react-router-dom";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import Modal from "react-bootstrap/Modal";
import moment from "moment/moment";
import SubscriptionCancellationForm from "../../components/subscription/SubscriptionCancellationForm";
import {
    selectLoadingSubscription,
    selectPaymentMethodChanged,
    selectSubscriptionActivated
} from "../../store/subscription/subscriptionSelector";
import {activateSub, setChangedPaymentMethod, subActivated} from "../../store/subscription/subscriptionReducer";
import {getToken} from "../../api/api";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {Trans, useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import SubscriptionCreditCardNotChangedModal from "../../components/subscription/SubscriptionCreditCardNotChangedModal";

const UserSubscription = () => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const user = useSelector(selectUser)
    const freePlan = user.subPlan.id === 199;
    const noPlan = user.subPlan.id === 0;
    const trial = user.subPlan.id === 200;
    const isLimited = user.subPlan.id === 1004;
    const automatic = user.sub.paymentType === 0 || user.sub.paymentType === 3 || user.sub.paymentType === 5;
    const [paymentType, setPaymentType] = useState(null);
    const [showCancelSubModal, setShowCancelSubModal] = useState(false)
    const [showCancelConfirmationModal, setShowCancelConfirmationModal] = useState(false);

    const loadingSubscription = useSelector(selectLoadingSubscription);
    const subscriptionActivated = useSelector(selectSubscriptionActivated)
    const paymentMethodChanged = useSelector(selectPaymentMethodChanged)
    const paymentCountry = useSelector(selectPaymentCountry)


    useComponentTranslations("userSubscriptionPage", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const goBackLink = () => {
        navigate("/user")
    }

    const handleRenewSubscription = () => {
        navigate(`/subscription/purchase/${user.subPlan.id}?goBackTo=subscriptionRenew`)
    }

    const handleActivateSub = () => {
        dispatch(activateSub())
    }

    const handleGoToAddTime = () => {
        navigate(`/subscription/type/1000?goBackTo=subscriptionAddTime`)
    }

    const handleChooseSubscription = () => {
        navigate("/subscription?step=1&goBackTo=subscription&showPlans=true")
    }

    const handleChangePaymentMethod = () => {
        navigate("/user/subscription/payment-method")
    }

    const handleShowCancelConfirmationModal = () => {
        setShowCancelConfirmationModal(true)
        setShowCancelSubModal(false)
    }
    const handleHideCancelConfirmationModal = () => {
        setShowCancelConfirmationModal(false)
        setShowCancelSubModal(false)
    }

    const handleShowCancelSubModal = () => {
        setShowCancelSubModal(prevState => !prevState)
    }

    useEffect(() => {
        if (subscriptionActivated) {
            dispatch(fetchUser())
            dispatch(subActivated(false))
            dispatch(setChangedPaymentMethod(false))
        }
    }, [subscriptionActivated, dispatch]);

    useEffect(() => {
        if (paymentMethodChanged) {
            dispatch(fetchUser())
            dispatch(setChangedPaymentMethod(false))
        }
    }, [dispatch, paymentMethodChanged]);

    useEffect(() => {
        if (paymentCountry) {
            if (paymentCountry.country === "BRA") {
                if (trial || noPlan)
                    navigate("/subscription")
            } else {
                const token = getToken()
                window.location.href = `https://payments.mfitpersonal.com.br/redirect/${token}`
            }
        }
    }, [trial, navigate, noPlan, paymentCountry])

    useEffect(() => {
        dispatch(fetchUser())
        dispatch(getPaymentCountry())
    }, [dispatch]);


    useEffect(() => {
        if (user) {
            switch (user.sub.paymentType) {
                case 1:
                    setPaymentType("boleto")
                    break;
                case 2:
                    setPaymentType("pix")
                    break;
                case 3:
                    setPaymentType("wallet")
                    break;
                default:
                    setPaymentType("credit")
                    break;
            }
        }
    }, [user]);

    if (!paymentCountry)
        return (
            <Page title={t("userSubscriptionPage:title")}
                  mt={"mt-n5"}>
                <LoadingBlock/>
            </Page>
        )
    return (
        <Page title={t("userSubscriptionPage:title")} mt={"mt-n5"} goBackLink={goBackLink} loading={loadingSubscription}>
            {
                freePlan &&
                <div className={"card card-body"}>
                    <div className={"row justify-content-center"}>
                        <div className={"col-12 text-center"}>
                            <RoundedIcon icon={"fa-user-lock"} size={"lg"}/>
                        </div>
                        <div className={"col-12 text-center mt-3"}>
                            <span className={"d-block fw-semibold fs-5"}>{t("userSubscriptionPage:freePlanHeading")}</span>
                        </div>
                        <div className={"col-12 mt-2 text-center"}>
                            <span>
                                <Trans t={t}
                                       i18nKey="userSubscriptionPage:freePlanDescription"
                                       values={{count: 1}}
                                       components={{bold: <span className={"fw-semibold"}/>}}
                                />
                            </span>
                        </div>
                        <div className={"col-12 mt-3"}>
                            <button className={"btn btn-primary w-100"}
                                    onClick={handleChooseSubscription}>{t("userSubscriptionPage:chooseSubscription")}</button>
                        </div>
                    </div>
                </div>
            }
            {
                !freePlan &&
                <>
                    <div className={"card card-body border-0"}>
                        <div className={"row"}>
                            <div className={"col-12"}>
                                <SubscriptionCard isLimited={isLimited} automatic={automatic} paymentType={paymentType}/>
                            </div>
                        </div>
                        {
                            user?.sub?.status === 2 &&
                            <div className={"row mt-3"}>
                                <div className={"col-12 mb-2"}>
                                    <div className={"card card-body border-0 bg-danger-subtle text-center text-danger"}>
                                        <span className={"d-block "}><i className={"fa-regular fa-info-circle fa-xl"}></i></span>
                                        <span className={"d-block mt-1 fw-semibold"}>{t("userSubscriptionPage:cancelledTitle")}</span>
                                        <span className={"d-block mt-2 "}>
                                            <Trans t={t}
                                                   i18nKey="userSubscriptionPage:cancelledUsage"
                                                   values={{date: moment.utc(user.sub.nextInvoice).format("L")}}
                                                   components={{bold: <span className={"fw-semibold"}/>}}
                                            />
                                        </span>
                                    </div>
                                </div>
                                <div className={"col-12"}>
                                    <button className={"btn btn-primary w-100"} onClick={handleActivateSub} disabled={loadingSubscription}>
                                        {t("userSubscriptionPage:reactivateSubscription")}
                                    </button>
                                </div>
                            </div>
                        }
                        {
                            user?.sub?.status === 1 &&
                            <div className={"row mt-3"}>
                                <div className={"col-12 mb-2"}>
                                    <div className={"card card-body border-0 bg-warning-subtle text-center text-default"}>
                                        <span className={"d-block "}><i className={"fa-regular fa-info-circle fa-xl"}></i></span>
                                        <span className={"d-block mt-1 fw-semibold"}>{t("userSubscriptionPage:cancelledTitle")}</span>
                                        <span className={"d-block mt-2 "}>
                                            <Trans t={t}
                                                   i18nKey="userSubscriptionPage:cancelledUsage"
                                                   values={{date: moment.utc(user.sub.nextInvoice).format("L")}}
                                                   components={{bold: <span className={"fw-semibold"}/>}}
                                            />
                                        </span>
                                    </div>
                                </div>
                                <div className={"col-12"}>
                                    <div className={"pt-2"}>
                                        <button className={"btn btn-primary w-100"}
                                                onClick={handleRenewSubscription}>{t("userSubscriptionPage:renewSubscription")}</button>
                                    </div>
                                </div>
                            </div>
                        }
                        {
                            user?.sub?.status === 0 &&
                            <div className={"row mt-3"}>
                                <div className={"col-12"}>
                                    {
                                        isLimited &&
                                        <div className={"col-12 mt-3"}>
                                            <button className={"btn btn-primary w-100"}
                                                    onClick={handleGoToAddTime}>{t("userSubscriptionPage:increaseSubscription")}</button>
                                        </div>
                                    }
                                    {
                                        !isLimited &&
                                        <div className={"col-12 mt-2"}>
                                            <button className={`btn btn-primary w-100`} onClick={handleGoToAddTime}>{t("userSubscriptionPage:addTime")}</button>
                                        </div>
                                    }
                                    <div className={"pt-2"}>
                                        <button className={"btn btn-outline-primary w-100"}
                                                onClick={handleChangePaymentMethod}>{t("userSubscriptionPage:changePaymentMethod")}
                                        </button>
                                    </div>


                                    <div className={"pt-2"}>
                                        <button className={"btn btn-link text-secondary fw-semibold w-100"}
                                                onClick={handleShowCancelSubModal}>{t("userSubscriptionPage:cancelSubscription")}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <Modal show={showCancelSubModal} centered onHide={handleShowCancelSubModal}>
                        <Modal.Body>
                            <div className={"row "}>
                                <div className={"col-12 text-center mt-4"}>
                                    <RoundedIcon icon={"fa-times"} bgColor={"bg-danger-subtle"} size={"lg"} textColor={"text-danger"}/>
                                </div>
                                <div className={"col-12 text-center mt-2"}>
                                    <span className={"fw-semibold "}>{t("userSubscriptionPage:cancelModalTitle")}</span>
                                </div>
                                <div className={"col-12 mt-2"}>
                                    <div className={"card card-body border-0 bg-primary-subtle text-center p-2 text-primary fw-semibold"}>
                                        <span><i
                                            className={"fa-regular fa-info-circle"}></i> <Trans t={t}
                                                                                                i18nKey="userSubscriptionPage:cancelModalUsageNotice"
                                                                                                values={{date: moment.utc(user.sub.nextInvoice).format("L")}}
                                                                                                components={{bold: <span className={"fw-semibold"}/>}}
                                        /></span>
                                    </div>
                                </div>
                                <div className={"col-12 mt-4 small text-center"}>
                                    <span className={"fw-semibold d-block "}>{t("userSubscriptionPage:cancelModalAttention")}</span>
                                    <span>{t("userSubscriptionPage:cancelModalWalletReminder")}</span>
                                </div>
                                <div className={"col-12 mt-4"}>
                                    <button className={"btn btn-danger w-100"}
                                            onClick={handleShowCancelConfirmationModal}>{t("userSubscriptionPage:cancelSubscription")}</button>
                                </div>
                                <div className={"col-12 mt-2"}>
                                    <button className={"btn btn-outline-primary w-100"}
                                            onClick={handleShowCancelSubModal}>{t("userSubscriptionPage:close")}</button>
                                </div>
                            </div>
                        </Modal.Body>
                    </Modal>
                    <Modal show={showCancelConfirmationModal} centered onHide={handleHideCancelConfirmationModal}>
                        <Modal.Body>
                            <div className={"row justify-content-between"}>
                                <div className={"col-12 text-end"}>
                                    <span className={"clickable-element"} onClick={handleHideCancelConfirmationModal}><i className={"fa-regular fa-times"}></i></span>
                                </div>
                                <div className={"col-12 text-center"}>
                                    <span className={"fw-semibold fs-5"}>{t("userSubscriptionPage:cancelReasonTitle")}</span>
                                </div>
                                <div className={"col-12 text-center mt-2 mb-4"}>
                                    <span>{t("userSubscriptionPage:cancelReasonDescription")}</span>
                                </div>
                            </div>
                            <SubscriptionCancellationForm user={user} onClose={handleHideCancelConfirmationModal}/>
                        </Modal.Body>
                    </Modal>
                    <SubscriptionCreditCardNotChangedModal goToPaymentMethods={handleChangePaymentMethod}/>
                </>
            }
        </Page>
    )
}

export default UserSubscription;