import AiAssistantChat from "../ai/AiAssistantChat";
import AiUserChat from "../ai/AiUserChat";
import AiResponseWaiting from "../ai/AiResponseWaiting";
import Spinner from "../loader/Spinner";
import {Field, Form, Formik} from "formik";
import {fetchChatBotSession, sendMessage} from "../../store/chat-bot/chatBotReducer";
import {useCallback, useEffect, useRef, useState} from "react";
import Cookies from "js-cookie";
import {getMainDomain} from "../../utils/cookie/cookieUtils";
import {useDispatch, useSelector} from "react-redux";
import {selectChatBotLoading, selectChatBotMessages, selectChatBotWaitingMessage} from "../../store/chat-bot/chatBotSelector";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const ChatBot = ({show, onClose, screenSize}) => {
    const {t, i18n} = useTranslation();
    const dispatch = useDispatch();
    const messages = useSelector(selectChatBotMessages);
    const isWaitingForResponse = useSelector(selectChatBotWaitingMessage);
    const loading = useSelector(selectChatBotLoading);
    const chatAreaRef = useRef(null);
    const [sessionId, setSessionId] = useState(false);

    useComponentTranslations('chatBot', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handlePreMadeMessage = (msg) => {
        handleSendMessage(msg);
    };

    const handleSendMessage = (finalMessage) => {
        if (finalMessage.trim() !== "") {
            const userMessage = {
                sessionId: sessionId,
                role: 'user',
                message: finalMessage,
                language: i18n.language,
                timestamp: new Date().toISOString(),
            };
            dispatch(sendMessage(userMessage));
        }
    };

    useEffect(() => {
        if (show) {
            let storedSessionId = Cookies.get("chat-bot-session-id");
            if (!storedSessionId) {
                const mainDomain = getMainDomain();
                storedSessionId = crypto.randomUUID();
                Cookies.set(
                    "chat-bot-session-id",
                    storedSessionId,
                    {expires: 4 / 24, domain: `.${mainDomain}`}
                );
            }
            setSessionId(storedSessionId);
            dispatch(fetchChatBotSession(storedSessionId));
        }
    }, [show, dispatch]);

    const scrollToBottom = useCallback(() => {
        if (chatAreaRef.current) {
            chatAreaRef.current.scrollTo({
                top: chatAreaRef.current.scrollHeight,
                behavior: 'smooth',
            });
        }
    }, []);

    useEffect(() => {
        scrollToBottom();
    }, [messages, scrollToBottom]);

    return (
        <>
            <div className={"d-flex justify-content-between"}>
                <div className="col-2  clickable-element" onClick={onClose}>
                        <span className="text-xs">
                          <i className="fa-regular fa-chevron-left"/> {t("chatBot:goBack")}
                        </span>
                </div>
                <div className={"col-auto text-mfit-ai-gradient"}>
                    <i
                        className="fa-kit fa-mfit-ai "
                        style={{fontSize: "1rem"}}
                    ></i>{' '}
                    <span className="fw-bold ">MFIT</span>{' '}
                    <span className="fw-light ">IA</span>
                </div>
                <div className={'col-2'}></div>
            </div>
            <div className="row justify-content-center pt-3">
                <div className="col-12 ms">
                    <div className="card card-body border-0">
                        <div className="row justify-content-center">
                            <div
                                className="card-body border-0"
                                style={{height: screenSize, overflowY: 'auto', minHeight: "400px"}}
                                ref={chatAreaRef}
                            >
                                {!loading && (
                                    <>
                                        {(!messages || messages.length === 0) && (
                                            <>
                                                <div
                                                    className="d-flex flex-column justify-content-center align-items-center"
                                                    style={{height: "100%"}}
                                                >
                                                        <span style={{fontSize: "5rem"}} className={"text-mfit-ai-gradient"}>
                                                          <i className="fa-kit fa-mfit-ai"></i>
                                                        </span>
                                                    <span
                                                        style={{fontSize: "1.5rem"}}
                                                        className="mt-n1 fw-semibold d-block text-center lh-1 text-mfit-ai"
                                                    >
                                                          {t("chatBot:howCanIHelp")}
                                                        </span>
                                                    <div className="row justify-content-center mt-5">
                                                        <div className="col-auto mb-1 mx-1">
                                                                <span
                                                                    className="badge bg-mfit-ai-subtle text-mfit-ai text-md clickable-element"
                                                                    onClick={() =>
                                                                        handlePreMadeMessage(t("chatBot:preMadeMessage1"))
                                                                    }
                                                                >
                                                                  {t("chatBot:preMadeMessage1")}
                                                                </span>
                                                        </div>
                                                        <div className="col-auto mb-1 mx-1">
                                                                <span
                                                                    className="badge  bg-mfit-ai-subtle text-mfit-ai text-md clickable-element"
                                                                    onClick={() =>
                                                                        handlePreMadeMessage(t("chatBot:preMadeMessage2"))
                                                                    }
                                                                >
                                                                  {t("chatBot:preMadeMessage2")}
                                                                </span>
                                                        </div>
                                                        <div className="col-auto mb-1 mx-1">
                                                                <span
                                                                    className="badge  bg-mfit-ai-subtle text-mfit-ai text-md clickable-element"
                                                                    onClick={() =>
                                                                        handlePreMadeMessage(t("chatBot:preMadeMessage3"))
                                                                    }
                                                                >
                                                                  {t("chatBot:preMadeMessage3")}
                                                                </span>
                                                        </div>
                                                        <div className="col-auto mb-1 mx-1">
                                                                <span
                                                                    className="badge  bg-mfit-ai-subtle text-mfit-ai text-md clickable-element"
                                                                    onClick={() =>
                                                                        handlePreMadeMessage(t("chatBot:preMadeMessage4"))
                                                                    }
                                                                >
                                                                  {t("chatBot:preMadeMessage4")}
                                                                </span>
                                                        </div>
                                                        <div className="col-auto mb-1 mx-1">
                                                                <span
                                                                    className="badge  bg-mfit-ai-subtle text-mfit-ai text-md clickable-element"
                                                                    onClick={() =>
                                                                        handlePreMadeMessage(t("chatBot:preMadeMessage5"))
                                                                    }
                                                                >
                                                                  {t("chatBot:preMadeMessage5")}
                                                                </span>
                                                        </div>
                                                        <div className="col-auto mb-1 mx-1">
                                                                <span
                                                                    className="badge  bg-mfit-ai-subtle text-mfit-ai text-md clickable-element"
                                                                    onClick={() =>
                                                                        handlePreMadeMessage(t("chatBot:preMadeMessage6"))
                                                                    }
                                                                >
                                                                  {t("chatBot:preMadeMessage6")}
                                                                </span>
                                                        </div>
                                                        <div className="col-auto mb-1 mx-1">
                                                                <span
                                                                    className="badge  bg-mfit-ai-subtle text-mfit-ai text-md clickable-element"
                                                                    onClick={() =>
                                                                        handlePreMadeMessage(t("chatBot:preMadeMessage7"))
                                                                    }
                                                                >
                                                                  {t("chatBot:preMadeMessage7")}
                                                                </span>
                                                        </div>
                                                    </div>
                                                    <div className="row justify-content-center mt-4">
                                                        <div className="col-12 p-0">
                                                            <hr className="text-secondary"/>
                                                            <div className="card card-body border-0">
                                                                    <span className="text-center small d-block text-mfit-ai">
                                                                      {t("chatBot:disclaimer")}
                                                                    </span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </>
                                        )}
                                        {messages &&
                                            messages.length > 0 &&
                                            messages.map((msg, index) => (
                                                <div
                                                    key={index}
                                                    className={`mb-4 ${msg.role === 'user' ? 'text-end' : 'text-start'}`}
                                                >
                                                    {msg.role === "assistant" && (
                                                        <AiAssistantChat msg={msg} scrollToBottom={scrollToBottom}/>
                                                    )}
                                                    {msg.role === "user" && <AiUserChat msg={msg}/>}
                                                </div>
                                            ))}
                                        {isWaitingForResponse && <AiResponseWaiting/>}
                                    </>
                                )}
                                {loading && (
                                    <div
                                        className="d-flex flex-column justify-content-center align-items-center"
                                        style={{height: "100%"}}
                                    >
                                          <span style={{fontSize: "5rem"}}>
                                              <Spinner/>
                                          </span>
                                    </div>
                                )}
                            </div>
                        </div>
                        <Formik
                            initialValues={{message: ''}}
                            onSubmit={(values, {resetForm}) => {
                                handleSendMessage(values.message);
                                resetForm();
                            }}
                        >
                            {({errors, touched, isSubmitting, values}) => (
                                <Form>
                                    <div className="input-group">
                                        <Field
                                            type="text"
                                            name="message"
                                            required={true}
                                            placeholder={t("chatBot:placeholderMessage")}
                                            className={`form-control bg-white border-end-0 ${
                                                errors.message && touched.message ? 'is-invalid' : ''
                                            }`}
                                            disabled={isWaitingForResponse || loading}
                                        />
                                        <button
                                            className="btn body-bg border-secondary-subtle border-start-0 text-mfit-ai-gradient"
                                            type="submit"
                                            disabled={
                                                isWaitingForResponse ||
                                                isSubmitting ||
                                                loading ||
                                                values.message.length === 0
                                            }
                                        >
                                            <i className="fa-regular fa-send fa-xl "></i>
                                        </button>
                                    </div>
                                </Form>
                            )}
                        </Formik>
                    </div>
                </div>
            </div>
        </>
    )
}

export default ChatBot;