import { all, call, put, takeLatest } from 'redux-saga/effects';
import { handleError } from "../../utils/error/sagaErrorHandling";
import {
    fetchHistoryVo2,
    setHistoryVo2,
    fetchLastVo2Max,
    setLastVo2Max,
    saveVo2Max,
    saveFcRep,
    fetchFcRep,
    setFcRep,
    onError
} from './evaluationReducer';
import {
    fetchFcRepAPI,
    fetchHistoryEvaluationAPI,
    fetchLastVo2MaxAPI,
    saveVo2MaxAPI,
    saveFcRepAPI
} from '../../api/evaluation/evaluationActions';

export function* fetchHistoryEvaluationSaga(action) {
    try {
        const response = yield call(fetchHistoryEvaluationAPI, action.payload);
        yield put(setHistoryVo2(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchHistoryEvaluation() {
    yield takeLatest(fetchHistoryVo2.type, fetchHistoryEvaluationSaga);
}

export function* fetchLastVo2MaxAsync(action) {
    try {
        const response = yield call(fetchLastVo2MaxAPI, action.payload);
        yield put(setLastVo2Max(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchLastVo2Max() {
    yield takeLatest(fetchLastVo2Max.type, fetchLastVo2MaxAsync);
}

function* saveVo2MaxAsync(action) {
    try {
        const response = yield call(saveVo2MaxAPI, action.payload);
        yield put(setLastVo2Max(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onSaveVo2Max() {
    yield takeLatest(saveVo2Max.type, saveVo2MaxAsync);
}

function* fetchFcRepAsync(action) {
    try {
        const response = yield call(fetchFcRepAPI, action.payload);
        yield put(setFcRep(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onFetchFcRep() {
    yield takeLatest(fetchFcRep.type, fetchFcRepAsync);
}

function* saveFcRepAsync(action) {
    try {
        const response = yield call(saveFcRepAPI, action.payload);
        yield put(setFcRep(response.data));
    } catch (error) {
        yield call(handleError, error, onError);
    }
}

export function* onSaveFcRep() {
    yield takeLatest(saveFcRep.type, saveFcRepAsync);
}

export function* evaluationSaga() {
    yield all([
        call(onFetchHistoryEvaluation),
        call(onFetchLastVo2Max),
        call(onSaveVo2Max),
        call(onFetchFcRep),
        call(onSaveFcRep)
    ]);
}
