import {createSelector} from "reselect";

const reducer = state => state.physicalEvaluation;

export const getOnePhysical = createSelector([reducer], slice => slice.onePhysical);

export const getPhysicalList = createSelector([reducer], slice => slice.physicalList);

export const getLoading = createSelector([reducer], slice => slice.initialLoading);

export const getSubmitLoading = createSelector([reducer], slice => slice.submitLoading);

export const getSubmitResult = createSelector([reducer], slice => slice.submitResult);

export const selectLastPhysical = createSelector([reducer], slice => slice.lastPhysical);

export const selectCompareList = createSelector([reducer], slice => slice.compareList);

export const selectCompareLoading = createSelector([reducer], slice => slice.initialLoading);
