import {createSelector} from "reselect";

const reducer = state => state.neuromotors;

export const selectTestList = createSelector([reducer], (slice) => slice.testList);
export const selectIsLoading = createSelector([reducer], (slice) => slice.loading);
export const selectTestSaved = createSelector([reducer], (slice) => slice.testSaved);
export const selectTestDeleted = createSelector([reducer], (slice) => slice.testDeleted);
