const RoundedIcon = ({
    unreadCount,
    icon,
    bgColor = "bg-primary-subtle",
    textColor = "text-primary",
    size = "md",
    kit = false,
    brand = false,
    solid = false,
    className = "",
    style,
    iconClassName = ""
}) => {
    const iconValue = String(icon || "").trim();
    const whatsApp = iconValue.includes("whatsapp");
    const hasExplicitPrefix = /\bfa-(kit|brands|regular|solid)\b/.test(iconValue);
    const resolvedTextColor = whatsApp ? "text-white" : textColor;
    const resolvedBgColor = whatsApp ? "bg-success-lighter" : bgColor;

    let prefix = "";
    if (!hasExplicitPrefix) {
        if (kit) {
            prefix = "fa-kit";
        } else if (brand || whatsApp) {
            prefix = "fa-brands";
        } else if (solid) {
            prefix = "fa-solid";
        } else {
            prefix = "fa-regular";
        }
    }

    const containerClassName = `${resolvedBgColor} ${resolvedTextColor} rounded-circle avatar avatar-${size} position-relative ${className}`.trim();
    const iconClasses = `${prefix} ${iconValue} ${iconClassName}`.trim();

    return (
        <div className={containerClassName} style={style}>
            {
                unreadCount > 0 &&
                <span className={`position-absolute translate-middle badge rounded-pill bg-danger`}
                      style={{top: "10px", left: "45px", fontSize: "0.75rem"}}>
                    <span className={"small fw-semibold"}>{unreadCount > 99 ? "99+" : unreadCount}</span>
                </span>
            }
            <i className={iconClasses}></i>
        </div>
    )
}

export default RoundedIcon;
