import React, { useEffect, useState, useRef } from 'react';
import { buildStyles, CircularProgressbarWithChildren } from 'react-circular-progressbar';
import 'react-circular-progressbar/dist/styles.css';
import { Howl } from 'howler';
import { useTranslation } from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/workout-session/locales/en-us.json";
import ptBR from "../../pages/workout-session/locales/pt-br.json";
import esES from "../../pages/workout-session/locales/es-es.json";
import ptPT from "../../pages/workout-session/locales/pt-pt.json";

const Stopwatch = ({ isRunning = false, initialTime = 0, handleClose }) => {
    const { t } = useTranslation();
    const [time, setTime] = useState(isRunning ? null : initialTime);
    const [timer, setTimer] = useState(null);
    const [sound, setSound] = useState(null);
    const [seconds, setSeconds] = useState(null);
    const [minutes, setMinutes] = useState(null);
    const [totalTime, setTotalTime] = useState(null);
    const audioPlayingRef = useRef(false);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const getTimeInMinutes = (e) => {
        const newMinutes = Number(e.target.value);
        setMinutes(newMinutes);
        const newTime = (newMinutes * 60) + (seconds || 0);
        setTime(newTime);
        setTotalTime(newTime);
    };

    const getTimeInSeconds = (e) => {
        const newSeconds = Number(e.target.value);
        setSeconds(newSeconds);
        const newTime = (minutes || 0) * 60 + newSeconds;
        setTime(newTime);
        setTotalTime(newTime);
    };

    useEffect(() => {
        const soundInstance = new Howl({
            src: ['https://cdn.mfitpersonal.com.br/assets/audio/Alarm.mp3'],
            volume: 0.7,
            preload: true,
            loop: false
        });

        soundInstance.once('load', () => {
            setSound(soundInstance);
        });

        return () => {
            soundInstance.unload();
        };
    }, [isRunning]);

    useEffect(() => {
        if (time === 0 && sound && !audioPlayingRef.current) {
            sound.play();
            audioPlayingRef.current = true;
        }
    }, [time, sound]);

    const startTimer = () => {
        if (timer) return;

        if (isRunning) {
            const totalSeconds = minutes * 60 + seconds;
            setTotalTime(totalSeconds);
            setTime(totalSeconds);
            audioPlayingRef.current = false;
        }

        const id = setInterval(() => {
            setTime((prevTime) => {
                if (prevTime <= 1) {
                    clearInterval(id);
                    setTimer(null);
                    return 0;
                }
                return prevTime - 1;
            });
        }, 1000);
        setTimer(id);
    };

    const pauseTimer = () => {
        if (!timer) return;
        clearInterval(timer);
        setTimer(null);
    };

    const resetTimer = () => {
        if (sound) sound.stop();
        audioPlayingRef.current = false;
        clearInterval(timer);
        setTime(isRunning ? totalTime : initialTime);
        setTimer(null);
    };
    const formatTime = (seconds) => {
        const min = Math.floor(seconds / 60);
        const sec = seconds % 60;
        return `${min.toString().padStart(2, '0')}:${sec.toString().padStart(2, '0')}`;
    };


    return (
        <div>
            {isRunning ? (
                <>
                    <div className={'row justify-content-center d-flex pb-4'}>
                        <hr/>
                        <div className={'col-12 pb-2'}>
                            <span className={'d-block fw-semibold'}>{t("workout:regressiveTimer")}</span>
                            <span className={'d-block small'}>{t("workout:runningTimerInstructions")}</span>
                        </div>
                        <div className={'col-6'}>
                            <label className={'form-label small'}>{t("workout:minutes")}</label>
                            <input onChange={getTimeInMinutes} disabled={!!timer} placeholder={'00'} className={'form-control form-control-sm'} />
                        </div>
                        <div className={'col-6'}>
                            <label className={'form-label small'}>{t("workout:seconds")}</label>
                            <input onChange={getTimeInSeconds} disabled={!!timer} placeholder={'00'} className={'form-control form-control-sm'} />
                        </div>
                    </div>
                </>
            ) : (
                <div className={'row justify-content-between d-flex pb-4'}>
                    <div className={'col-auto align-self-center'}>
                        <span className={'fw-semibold '}>{t("workout:stopWatch")} {t("workout:regressive")}</span>
                    </div>
                    <div className={'col-auto align-self-center'}>
                        <span onClick={handleClose} className={'clickable-element fs-5'}>
                            <i className={'fa-regular fa-times'}></i>
                        </span>
                    </div>
                </div>
            )}
            <div className={'row justify-content-center d-flex'}>
                <div className={'col-8'}>
                    <div className={'row'}>
                        <div className={'col-12'}>
                            <CircularProgressbarWithChildren
                                value={isRunning ? (time === null ? 0 : (time / totalTime) * 100) : 100 - (time / initialTime) * 100}
                                strokeWidth={6}
                                styles={buildStyles({
                                    pathColor: `rgba(0, 112, 182)`,
                                    trailColor: `rgba(214, 214, 214, 0.3)`
                                })}
                            >
                                <span className={'fs-1'}>{time === null ? "00:00" : formatTime(time)}</span>
                            </CircularProgressbarWithChildren>
                        </div>
                    </div>
                    <div className={'row justify-content-center d-flex pt-4 pb-3'}>
                        <div className={'col-4 text-center  '}>
                            <button onClick={!timer ? startTimer : pauseTimer} disabled={time === null || time === 0} className={'no-style-btn'}>
                                {!timer ? <i style={{fontSize: "3rem"}} className={`fa-regular fa-circle-play ${time !== null && time !== 0 ? 'text-primary-darker':'text-secondary-darker'}`}></i> :
                                    <i style={{fontSize: "3rem"}}  className="fa-regular fa-circle-pause text-primary-darker"></i>}
                            </button>
                        </div>
                        <div className={'col-4 text-center  '}>
                            <button className={'no-style-btn'}   onClick={resetTimer}>
                                <i style={{fontSize: "3rem"}} className={`fa-regular fa-circle-stop  ${!timer ? 'text-secondary-darker': 'text-primary-darker'}`}></i>
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default Stopwatch;
