import moment from "moment/moment";
import {useDispatch} from "react-redux";
import {deletePace} from "../../store/workout-aerobic/workoutAerobicReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutAerobicPaceCard = ({pace}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch();
    useComponentTranslations('aerobicWorkoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleDelete = () => {
        dispatch(deletePace(pace.id))
    }
    return (
        <div className={"card card-body border-0 bg-secondary-subtle mb-2"}>
            <div className={"row justify-content-between"}>
                <div className={"col-8"}>
                    <div className={"row small" }>
                        <div className={"col-12"}>
                            <span className={"fw-semibold"}>{t("aerobicWorkoutComponent:date")}:</span> {moment({
                            year: pace.dateAdded.year,
                            month: pace.dateAdded.month - 1,
                            day: pace.dateAdded.day
                        }).format("L")}
                        </div>
                        <div className={"col-12"}>
                            <span className={"fw-semibold"}>{t("aerobicWorkoutComponent:distance")}:</span> {pace.distance}m
                        </div>
                        <div className={"col-12"}>
                            <span className={"fw-semibold"}>{t("aerobicWorkoutComponent:time")}:</span> {pace.time}m
                        </div>
                        <div className={"col-12"}>
                            <span className={"fw-semibold"}>{t("aerobicWorkoutComponent:pace")}:</span> {pace.pace.toFixed(2)} min/km
                        </div>
                    </div>
                </div>
                <div className={"col-auto align-self-center text-danger clickable-element"} onClick={handleDelete}>
                    <i className={"fa-regular fa-trash-can fa-lg"}></i>
                </div>
            </div>
        </div>
    )
}
export default WorkoutAerobicPaceCard;