import {createSlice} from "@reduxjs/toolkit";

const INITIAL_STATE = {
    session: null,
    loading: false,
    preview: true
}

export const slice = createSlice({
    name: "session",
    initialState: INITIAL_STATE,
    reducers: {
        fetchSession(state) {
            state.loading = true
        },
        setSession(state, action) {
            state.loading = false
            state.session = action.payload
        },
        updateWorkoutSerie(state) {

        },
        updatedWorkoutSerie: (state, action) => {
            const {id, weight, sessionId} = action.payload;

            const sessionIndex = state.session.exercs.findIndex(e => e.id === Number(sessionId));
            if (sessionIndex === -1) return

            const session = state.session.exercs[sessionIndex];

            const exerciseIndex = session.exercises.findIndex(e => e.idExercSession === Number(sessionId));
            if (exerciseIndex === -1) return

            const exercise = session.exercises[exerciseIndex];

            exercise.series = exercise.series.map(serie => {
                if (serie.id === Number(id)) {
                    return {...serie, carga: weight};
                }
                return serie;
            });

            state.loading = false;
        },
        setPreview(state, action) {
            state.preview = action.payload;
        },
        setWorkoutStarted(state, action) {
            state.workoutStarted = action.payload;
        },
        setWorkoutProgress(state, action) {
            state.workoutProgress = action.payload;
            state.loading = false;
        },
        fetchWorkoutProgress(state) {
            state.loading = true;
        },
        onError(state) {
            state.loading = false;
        }
    }

})

export const {
    fetchSession, setSession, updateWorkoutSerie, updatedWorkoutSerie,
    setPreview, setWorkoutStarted, onError
} = slice.actions

export const workoutSessionReducer = slice.reducer