import {Field, Form, Formik} from "formik";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectNotes} from "../../store/client/clientSelector";
import {fetchNotes, saveNote, setNotes} from "../../store/client/clientReducer";
import {useTranslation} from "react-i18next";
import {useEffect} from "react";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const ClientNoteModal = ({id, handleClose}) => {
    const {t} = useTranslation();
    const dispatch = useDispatch()
    const note = useSelector(selectNotes)
    const loading = useSelector(isClientsLoading)
    useComponentTranslations('clientComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleSaveNote = (values) => {
        const payload = {
            id: Number(id),
            formData: values
        }
        dispatch(saveNote(payload))
        if (handleClose) {
            handleClose()
        }
    }

    useEffect(() => {
        if (id)
            dispatch(fetchNotes(id))
        return () => dispatch(setNotes(null))
    }, [dispatch, id]);

    return (
        <div className={'row '}>
            <div className={"col-12"}>
                <div className={'card card-body border-0'}>
                    <div className={'row'}>
                        <div className={"col-12"}>
                            <Formik
                                enableReinitialize={true}
                                initialValues={{notes: note?.note}}
                                onSubmit={(values) => {
                                    handleSaveNote(values);
                                }}
                            >
                                {({dirty}) => (
                                    <Form>
                                        <div className="mb-3">
                                            <label htmlFor="notes" className="form-label fw-semibold">{t("clientComponent:notes")}</label>
                                            <Field
                                                as="textarea"
                                                id="notes"
                                                name="notes"
                                                className="form-control"
                                                rows="5"
                                                style={{height: "200px"}}
                                            />
                                        </div>
                                        {
                                            dirty &&
                                            <div
                                                className={'d-grid mt-2'}>
                                                <button type="submit" disabled={loading} className="btn btn-primary">{t("clientComponent:submit")}</button>
                                            </div>
                                        }
                                    </Form>
                                )}
                            </Formik>

                        </div>
                    </div>

                </div>


            </div>
        </div>
    )
}
export default ClientNoteModal