import {useEffect, useState} from "react";
import _ from "lodash";
import WorkoutSeries from "./WorkoutSeries";
import WorkoutExerciseCompleted from "./WorkoutExerciseCompleted";
import {useSelector} from "react-redux";
import moment from "moment";
import Cookies from 'js-cookie';
import ExercisePlayerType from "../utils/videoplayer/ExercisePlayerType";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/workout-session/locales/en-us.json";
import ptBR from "../../pages/workout-session/locales/pt-br.json";
import esES from "../../pages/workout-session/locales/es-es.json";
import ptPT from "../../pages/workout-session/locales/pt-pt.json";
import {getExerciseName} from "../../utils/workout/Workout";
import WorkoutExerciseSubSingularList from "./WorkoutExerciseSubSingularList";
import {useTranslation} from "react-i18next";
import {getPreview} from "../../store/workout-session/workoutSessionSelector";

const WorkoutExerciseRegular = ({exerc, mainId, exercList}) => {
    const { i18n} = useTranslation();
    const [exercise, setExercise] = useState([{}]);
    const [completed, setCompleted] = useState(null);
    //const descriptionSeries = exercise.series?.find(s => s.tipo === 5);
    const preview = useSelector(getPreview);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const handleCompleted = () => {
        setCompleted(prevCompleted => !prevCompleted);
    }
    useEffect(() => {
        if (exercList) {
            setExercise(exercList[0])
        } else {
            setExercise(exerc.exercises ? exerc.exercises[0] : exerc.exercicio ? exerc.exercicio : exerc)
        }
    }, [exerc, exercList]);

    useEffect(() => {
        if (completed != null)
            if (completed) {
                const expirationDate = moment().add(2, 'hour');
                Cookies.set('exercise_' + mainId, 'true', {expires: expirationDate.toDate()});
            } else {
                Cookies.remove('exercise_' + mainId);
            }
    }, [completed, exercise, mainId]);

    useEffect(() => {
        if (Cookies.get('exercise_' + mainId))
            setCompleted(true)
    }, [mainId])

    return (
        <>
            <div className="row justify-content-center d-flex">
                <div className="col-12">
                    <div className={'row d-flex'}>
                        <div className={`col-${completed ? '12' : '8 '}  pt-3 ps-4 `}>
                            <div className={'row justify-content-between d-flex pb-1'}>
                                {
                                    !preview &&
                                    <div className={'col-1 align-self-center hide-me'}>
                                        <WorkoutExerciseCompleted handleCompleted={handleCompleted}
                                                                  completed={completed}/>
                                    </div>
                                }
                                <div
                                    className={`col-${completed ? '11' : `${preview ? '12' : '10 ps-0'}`}   align-self-center `}>
                                    <span className={'d-block fw-bold   '} style={{lineHeight: "1.1rem"}}>
                                        {getExerciseName(exercise, i18n)}
                                    </span>
                                </div>
                            </div>
                            {exercise.series && exercise.series.length > 0 && (
                                <div className={'row d-flex pb-3 text-md'}>
                                    {
                                        !preview &&
                                        <div className={'col-2 hide-me'}></div>
                                    }
                                    <div
                                        className={` ${preview ? 'col-12' : 'col-10 ps-0'}  ${completed && 'd-none'} `}>
                                        {
                                            _.map(exercise.series, (serie) => (
                                                <WorkoutSeries key={serie.id}
                                                               serie={serie}
                                                               seriesLength={exercise.series.length}
                                                               preview={preview}
                                                />
                                            ))
                                        }
                                    </div>
                                </div>
                            )}
                        </div>
                        {
                            !completed &&
                            <ExercisePlayerType exercise={exercise}/>
                        }
                    </div>
                </div>
            </div>
            {
                exercList && exercList.length > 1 && !completed &&
                <WorkoutExerciseSubSingularList setExercise={setExercise} exercsList={exercList}/>
            }
        </>

    )
}
export default WorkoutExerciseRegular;