import React from "react";

const EvaluationSubmitButton = ({
    label,
    loadingLabel,
    isSubmitting = false,
    disabled = false,
    type = "submit",
    className = "btn btn-primary w-100",
    onClick,
}) => {
    return (
        <button
            type={type}
            className={className}
            disabled={disabled || isSubmitting}
            onClick={onClick}
        >
            {isSubmitting && <i className={"fa-regular fa-loader fa-spin me-2"}/>}
            {isSubmitting ? (loadingLabel || label) : label}
        </button>
    );
};

export default EvaluationSubmitButton;
