import {Formik, Form, FieldArray, Field, ErrorMessage} from "formik";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import AnamnesisEditQuestion from "./AnamnesisEditQuestion";
import {resetFormSent, updateModel} from "../../store/anamnesis/anamnesisReducer";
import {useDispatch, useSelector} from "react-redux";
import {getSubmitResult, isSubmitLoading} from "../../store/anamnesis/anamnesisSelector";
import {buildAnamnesisNewRoute} from "../../utils/client/evaluationRoutes";
import EvaluationSubmitButton from "../evaluation-components/EvaluationSubmitButton";
import EvaluationSuccessCard from "../evaluation-components/EvaluationSuccessCard";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const AnamnesisEditModelForm = ({model, clientId}) => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const submitLoading = useSelector(isSubmitLoading);
    const submitResult = useSelector(getSubmitResult);
    const showSuccess = isMatchingSubmitSuccess(submitResult, {
        action: "update",
        flow: EVALUATION_FLOWS.ANAMNESIS_MODEL_EDIT,
        clientId
    });

    useComponentTranslations('anamnesisComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleUpdateQuestion = (index, newQuestionText, setFieldValue) => {
        setFieldValue(`questions[${index}].question`, newQuestionText);
    };

    const handleSave = async (values) => {
        const payload = {
            id: model.id,
            ...values
        }
        dispatch(updateModel(payload, {
            flow: EVALUATION_FLOWS.ANAMNESIS_MODEL_EDIT,
            clientId
        }));
    };

    const handleKeepEditing = () => {
        dispatch(resetFormSent());
    };

    const handleGoBack = () => {
        navigate(buildAnamnesisNewRoute(clientId));
    };

    return (
        <>
            {
                model &&
                <div className="row">
                    <div className="col-12">
                        {showSuccess ? (
                            <EvaluationSuccessCard
                                title={t("anamnesisComponent:modelUpdated")}
                                primaryLabel={t("anamnesisComponent:viewEdit")}
                                secondaryLabel={t("anamnesisComponent:backToTop")}
                                onPrimary={handleKeepEditing}
                                onSecondary={handleGoBack}
                            />
                        ) : (
                            <div className="card card-body border-0">
                                <div className={'card card-body border-0 bg-primary-subtle text-primary-lighter fw-semibold mb-3'}>
                                    <div className={'row '}>
                                        <div className={"col-2 col-md-auto text-center align-self-center"}>
                                            <i className={"fa-regular fa-circle-info fa-xl"}/>
                                        </div>
                                        <div className={'col-10 col-md-auto ps-0'}>
                                            <span>{t("anamnesisComponent:viewOrEditModel")}</span>
                                        </div>
                                    </div>
                                </div>
                                <Formik
                                    initialValues={{
                                        name: model.name,
                                        questions: model.questions
                                    }}
                                    onSubmit={handleSave}
                                >
                                    {({values, setFieldValue}) => (
                                        <Form>
                                            <div className="form-group pt-2">
                                                <div className="fw-semibold">{t("anamnesisComponent:seeOrEdit")}</div>
                                                <Field
                                                    name="name"
                                                    type="text"
                                                    className="w-100 mb-1 border rounded py-2 form-control"
                                                />
                                                <ErrorMessage name="name" component="div" className="text-danger"/>
                                            </div>

                                            <FieldArray name="questions">
                                                {({remove, push}) => (
                                                    <>
                                                        {values.questions?.map((question, index) => (
                                                            <AnamnesisEditQuestion
                                                                key={index}
                                                                question={question}
                                                                index={index}
                                                                onDelete={() => remove(index)}
                                                                onUpdate={(newQuestionText) => handleUpdateQuestion(index, newQuestionText, setFieldValue)}
                                                            />
                                                        ))}
                                                        <div className="form-group clickable-element pt-2">
                                                            <div
                                                                className="card card-body clickable-element py-2 bg-secondary-subtle"
                                                                onClick={() => push({question: ''})}
                                                            >
                                                                <div className="row d-flex align-items-center clickable-element">
                                                                    <div className="col-10">
                                                                <span className="fw-semibold">
                                                                    {t("anamnesisComponent:addQuestion")}
                                                                </span>
                                                                    </div>
                                                                    <div className="col-2 text-end">
                                                                        <i className="fa-regular fa-circle-plus text-primary"/>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </>
                                                )}
                                            </FieldArray>
                                            <div className="row pt-3">
                                                <div className="col-12">
                                                    <EvaluationSubmitButton
                                                        label={t("anamnesisComponent:save")}
                                                        loadingLabel={t("anamnesisComponent:saving")}
                                                        isSubmitting={submitLoading}
                                                    />
                                                </div>
                                            </div>
                                        </Form>
                                    )}
                                </Formik>
                            </div>
                        )}
                    </div>
                </div>
            }
        </>
    );
};

export default AnamnesisEditModelForm;
