import {useTranslation} from "react-i18next";
import {useState} from "react";
import moment from "moment/moment";
import {formatElapsedTime, getFeedbackIntensity} from "../../utils/workout/Workout";
import Text from "../utils/emoji/Text";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutFeedbackCard = ({feedback, isLast}) => {
    const [expandCard, setExpandCard] = useState(false);
    const {t} = useTranslation();
    useComponentTranslations('workoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const dataInicio = moment({
        day: feedback.workoutStartTime?.date.day,
        month: feedback.workoutStartTime?.date.month - 1,
        year: feedback.workoutStartTime?.date.year,
        hour: feedback.workoutStartTime?.time.hour,
        minute: feedback.workoutStartTime?.time.minute,
        second: feedback.workoutStartTime?.time.second
    });
    const dataFim = moment({
        day: feedback.workoutEndTime?.date.day,
        month: feedback.workoutEndTime?.date.month - 1,
        year: feedback.workoutEndTime?.date.year,
        hour: feedback.workoutEndTime?.time.hour,
        minute: feedback.workoutEndTime?.time.minute,
        second: feedback.workoutEndTime?.time.second
    });
    const handleExpandCard = () => {
        setExpandCard((prevState) => !prevState)
    }
    return (
        <div className={'row justify-content-between d-flex clickable-element'} onClick={handleExpandCard}>
            <div className={'col-2 text-center pt-2 align-self-center'}>
                <i className="text-primary-darker fa-regular fa-circle-check fa-2x "></i>
            </div>
            <div className={'col-9 pe-0 ps-0'}>
                <span className={'d-block fw-semibold text-capitalize'}>
                    {
                        moment({
                            day: feedback.dataExecucao.date.day,
                            month: feedback.dataExecucao.date.month - 1,
                            year: feedback.dataExecucao.date.year
                        }).format("dddd, L").replace("-feira", "")
                    }
                </span>
                <span className={'d-block'}>
                    {
                        expandCard &&
                        <div className={'row justify-content-between d-flex'}>
                            <div className={'col-12 text-md text-muted pt-2'}>
                                {
                                    feedback.feeback ?
                                        <span>{t("workoutComponent:clientComment")}: <Text>{feedback.feeback}</Text></span> :
                                        <span>{t("workoutComponent:clientDidntLeaveAComment")}</span>
                                }
                            </div>
                            <div className={'col-12 text-md pt-2'}>
                                <span className={'d-block fw-semibold'}>{t("workoutComponent:yourComment")}:</span>
                                {
                                    feedback.resposta ?
                                        <span className={'text-md text-muted'}><Text>{feedback.resposta}</Text></span> :
                                        <span className={'text-md text-muted fst-italic'}>{t("workoutComponent:waitingFeedback")}</span>
                                }
                            </div>
                            {
                                <div className={'col-12 pt-2 text-md'}>
                                    <span className={'d-block fw-semibold'}>{t("workoutComponent:intensity")}:</span>
                                    <span
                                        className={'text-md text-muted'}>{t(`workoutComponent:${getFeedbackIntensity(feedback.borgNota)}`)}</span>
                                </div>
                            }
                        </div>
                    }
                    {
                        !expandCard &&
                        <>
                            {
                                feedback.feeback ?
                                    <span><Text short={true} length={55}>{feedback.feeback}</Text></span> :
                                    <span>{t("workoutComponent:clientDidntLeaveAComment")}</span>
                            }
                        </>
                    }
                </span>
            </div>
            <div className={'col-1 text-center ps-0'}>
                <i className={`fa-solid fa-chevron-${expandCard ? 'up' : 'down'}`}></i>
            </div>
            <div className={'col-12'}>
                {
                    expandCard && feedback.workoutStartTime && feedback.workoutEndTime &&
                    <div className={' row justify-content-center d-flex pt-2 mt-3 pb-2'}>
                        <div className={'col-10 bg-secondary-subtle rounded-2 p-2 ps-4 pe-4'}>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold  text-md'}>{t("workoutComponent:trainingStartDate")}:</span>
                                </div>
                                <div className={'col-auto text-end'}>
                                    <span className={"text-md"}>
                                        {moment(dataInicio).format("L HH:mm")}
                                    </span>
                                </div>
                            </div>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold text-md'}>{t("workoutComponent:trainingEndDate")}:</span>
                                </div>
                                <div className={'col-auto text-end'}>
                                    <span className={'text-md '}>
                                        {moment(dataFim).format("L HH:mm")}
                                    </span>
                                </div>
                            </div>
                            <div className={'row justify-content-between'}>
                                <div className={'col-auto'}>
                                    <span className={'fw-semibold'}>{t("workoutComponent:totalWorkoutTime")}:</span>
                                </div>
                                <div className={'col-auto  text-end'}>
                                     <span className={' fw-semibold'}>
                                         {formatElapsedTime(dataFim.diff(dataInicio, 'seconds'))}
                                     </span>
                                </div>
                            </div>
                        </div>
                    </div>
                }
            </div>
            {
                !isLast &&
                <div className={'col-12 ps-0 pe-0'}>
                    <hr/>
                </div>
            }

        </div>
    )
}

export default WorkoutFeedbackCard;