import React, {useCallback, useEffect, useState} from "react";
import _ from "lodash";
import WorkoutPdfExerciseCard from "./WorkoutPdfExerciseCard";
import Text from "../utils/emoji/Text";
import WorkoutSeries from "../workout-session/WorkoutSeries";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutPdfMultipleExercises = ({exerc, showImages}) => {
    const {t} = useTranslation();
    const [exercise] = useState(exerc.exercises[0]);
    const [exercs, setExercs] = useState([]);
    const [distributedSeries, setDistributedSeries] = useState(false);
    const [lastExerc, setLastExerc] = useState(null)
    const [standaloneObsSeries, setStandaloneObsSeries] = useState([]);
    useComponentTranslations('workoutComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const seriesMap = useCallback(() => {
        const newArray = [];
        let exerciseItem = null;
        const generalObservations = [];
        exercise.series.forEach((serie) => {
            if (serie.exercicio) {
                if (exerciseItem) {
                    newArray.push(exerciseItem);
                }
                exerciseItem = {...serie, exercicio: {...serie.exercicio, series: []}};
            } else if (serie.tipo === 5) {
                if (exerciseItem) {
                    exerciseItem.exercicio.series.push({...serie});
                } else {
                    generalObservations.push({...serie});
                }
            } else if (exerciseItem) {
                exerciseItem.exercicio.series.push({...serie});
            }
        });

        if (exerciseItem) {
            newArray.push(exerciseItem);
        }

        const distributed = newArray.some((exerc) => exerc.exercicio.series.length > 0);
        setDistributedSeries(distributed);
        setExercs(newArray);
        setStandaloneObsSeries(generalObservations);
    }, [exercise]);

    useEffect(() => {
        if (exercs.length === 0)
            seriesMap();
        else
            setLastExerc(exercs[exercs.length - 1])
    }, [seriesMap, exercs, setLastExerc])

    return (
        <div className={"row"}>
            <div className={"col-12 "}>
                <div className={"row py-2"}>
                    <div className={"col-auto align-self-center"}>
                        <span><i className={"fa-regular fa-layer-group fa-xl"}></i></span>
                    </div>
                    <div className={"col-auto ps-0"}>
                        <span className={"fw-semibold d-block"} style={{fontSize: "1rem"}}>{t("workoutComponent:combinedExercises")}</span>
                        <span>{t("workoutComponent:combinedExerciseMessages")}</span>
                    </div>
                </div>
                {
                    distributedSeries &&
                    <>
                        {_.map(exercs, (exerc, index) => (
                            <div key={exerc.id} className={"mb-2"}>
                                <WorkoutPdfExerciseCard showImages={showImages} exerc={exerc} index={index} isCombinado={true}/>
                            </div>
                        ))}
                        {
                            standaloneObsSeries.length > 0 &&
                            <div className={`pt-3`}>
                                <span className={'fw-semibold '}>{t("workoutComponent:instructions")}:</span>
                                {standaloneObsSeries.map((obsSerie) => (
                                    <pre
                                        key={obsSerie.id}
                                        className={'mb-1 text-md '}
                                        style={{
                                            lineHeight: 1.2,
                                            height: "100%",
                                            overflow: "hidden"
                                        }}>
                                        <Text enableAccessibility={true}>{obsSerie?.obs?.trim()}</Text>
                                    </pre>
                                ))}
                            </div>
                        }
                    </>
                }
                {
                    !distributedSeries &&
                    <>
                        {
                            _.map(exercs, (exerc, index) => (
                                exerc.exercicio &&
                                <WorkoutPdfExerciseCard
                                    showImages={showImages}
                                    exerc={exerc}
                                    index={index} isCombinado={true}/>
                            ))
                        }
                        {_.map(lastExerc?.exercicio?.series, (serie, index) => (
                            <div key={serie.id}>
                                <WorkoutSeries serie={serie}/>
                                {
                                    lastExerc?.exercicio?.series.length - 1 !== index &&
                                    <hr className={'mb-1 mt-2 '}/>
                                }
                            </div>
                        ))}
                        {
                            standaloneObsSeries.length > 0 &&
                            <div className={`pt-3`}>
                                <span className={'fw-semibold '}>{t("workoutComponent:instructions")}:</span>
                                {standaloneObsSeries.map((obsSerie) => (
                                    <pre
                                        key={obsSerie.id}
                                        className={'mb-1 text-md '}
                                        style={{
                                            lineHeight: 1.2,
                                            height: "100%",
                                            overflow: "hidden"
                                        }}><Text>{obsSerie?.obs?.trim()}</Text></pre>
                                ))}
                            </div>
                        }
                    </>
                }
            </div>
        </div>
    )
}

export default WorkoutPdfMultipleExercises;