import axios from "axios";
import {apiUrl, getToken} from "../api";

export const saveFeedbackAPI = async (id, formData) => {
    const token = getToken();
    if (!token) return;
    return await axios.post(`${apiUrl}/user/feedback/create?id=${id}`,
        formData,
        {
            headers: {
                'Content-Type': 'application/json',
                'authorization': token
            },
            timeout: 20000
        });
}

