import React, {useEffect, useRef, useState} from "react";
import {useTranslation} from "react-i18next";
import AppOffcanvasShell from "../offcanvas/AppOffcanvasShell";
import EmptySet from "../empty-set/EmptySet";
import LoadingBlock from "../loader/LoadingBlock";
import Pagination from "../pagination/Pagination";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import WorkoutPresetCard from "./WorkoutPresetCard";
import WorkoutPresetForm from "./WorkoutPresetForm";
import WorkoutPresetPreviewContent from "./WorkoutPresetPreviewContent";
import useWorkoutPresetSections from "./useWorkoutPresetSections";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const VIEW_LIST = "list";
const VIEW_PREVIEW = "preview";
const VIEW_CREATE = "create";

const WorkoutPresetPickerOffcanvas = ({
    show,
    onHide,
    presets = [],
    loading = false,
    title,
    description,
    onSelectPreset,
    onAddWithoutPreset,
    onCreatePreset,
    selectionLoading = false
}) => {
    const {t} = useTranslation();
    const [view, setView] = useState(VIEW_LIST);
    const [selectedPreset, setSelectedPreset] = useState(null);
    const [isSelectingPreset, setIsSelectingPreset] = useState(false);
    const [hasObservedSelectionLoading, setHasObservedSelectionLoading] = useState(false);
    const selectionLockRef = useRef(false);
    const {
        searchQuery,
        setSearchQuery,
        normalizedQuery,
        filteredUserPresets,
        filteredSystemPresets,
        paginatedUserPresets,
        paginatedSystemPresets,
        userPage,
        setUserPage,
        systemPage,
        setSystemPage,
        itemsPerPage,
        pagesToShow
    } = useWorkoutPresetSections(presets);

    useComponentTranslations("workoutPresetComponent", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    useEffect(() => {
        if (!show) {
            setView(VIEW_LIST);
            setSelectedPreset(null);
            setSearchQuery("");
            setIsSelectingPreset(false);
            setHasObservedSelectionLoading(false);
            selectionLockRef.current = false;
        }
    }, [setSearchQuery, show]);

    useEffect(() => {
        if (!isSelectingPreset) {
            return;
        }

        if (selectionLoading) {
            setHasObservedSelectionLoading(true);
            return;
        }

        if (hasObservedSelectionLoading) {
            setIsSelectingPreset(false);
            setHasObservedSelectionLoading(false);
            selectionLockRef.current = false;
        }
    }, [hasObservedSelectionLoading, isSelectingPreset, selectionLoading]);

    const hasSearchQuery = Boolean(normalizedQuery);
    const showEmptySearchState = hasSearchQuery && filteredUserPresets.length === 0 && filteredSystemPresets.length === 0;
    const showEmptyPresetState = !loading && !hasSearchQuery && filteredUserPresets.length === 0 && filteredSystemPresets.length === 0;
    const selectionDisabled = isSelectingPreset || selectionLoading;

    const handleOpenPreview = (preset) => {
        setSelectedPreset(preset);
        setView(VIEW_PREVIEW);
    };

    const handleReturnToList = () => {
        setView(VIEW_LIST);
        setSelectedPreset(null);
    };

    const handleSelectPreset = (preset) => {
        if (selectionLockRef.current || selectionLoading) {
            return;
        }

        selectionLockRef.current = true;
        setIsSelectingPreset(true);
        onSelectPreset?.(preset);
    };

    const handleAddWithoutPreset = () => {
        if (selectionLockRef.current || selectionLoading) {
            return;
        }

        selectionLockRef.current = true;
        setIsSelectingPreset(true);
        onAddWithoutPreset?.();
    };

    const renderSection = (sectionTitle, filteredItems, paginatedItems, currentPage, onPageChange, isSystem = false) => {
        if (!filteredItems.length) {
            return null;
        }

        return (
            <div>
                <span className="fw-semibold d-block">{sectionTitle}</span>
                <div className="d-grid gap-2 mt-2">
                    {paginatedItems.map((preset) => (
                        <WorkoutPresetCard
                            key={preset.id}
                            preset={preset}
                            isSystem={isSystem}
                            addMode
                            disabled={selectionDisabled}
                            onOpen={handleOpenPreview}
                            onAdd={handleSelectPreset}
                        />
                    ))}
                </div>
                {filteredItems.length > itemsPerPage && (
                    <Pagination
                        className="pt-3"
                        currentPage={currentPage}
                        totalItems={filteredItems.length}
                        itemsPerPage={itemsPerPage}
                        onPageChange={onPageChange}
                        pagesToShow={pagesToShow}
                    />
                )}
            </div>
        );
    };

    const renderList = () => (
        <div className="d-flex flex-column flex-grow-1">
            <div className="flex-grow-1 overflow-y-auto overflow-x-hidden">
                <div className="mb-3">
                    <span className="fw-semibold fs-5 d-block">{title || t("workoutPresetComponent:choosePreset")}</span>
                    <span className="text-secondary">{description || t("workoutPresetComponent:choosePresetDescription")}</span>
                </div>

                <div className="input-group mb-3">
                    <input
                        aria-label={t("workoutPresetComponent:searchPlaceholder")}
                        className="form-control bg-white"
                        onChange={(event) => setSearchQuery(event.target.value)}
                        placeholder={t("workoutPresetComponent:searchPlaceholder")}
                        type="search"
                        value={searchQuery}
                    />
                    <span className="input-group-text bg-white">
                        <i className="fa-regular fa-magnifying-glass"/>
                    </span>
                </div>

                {(onAddWithoutPreset || onCreatePreset) && (
                    <div className="d-grid gap-2 mb-4">
                        {onAddWithoutPreset && (
                            <button
                                type="button"
                                className="btn btn-primary w-100"
                                disabled={selectionDisabled}
                                onClick={handleAddWithoutPreset}
                            >
                                {t("workoutPresetComponent:addWithoutPreset")}
                            </button>
                        )}
                        {onCreatePreset && (
                            <button
                                type="button"
                                className="btn btn-outline-primary w-100"
                                disabled={selectionDisabled}
                                onClick={() => setView(VIEW_CREATE)}
                            >
                                {t("workoutPresetComponent:createNewPreset")}
                            </button>
                        )}
                    </div>
                )}

                <div className="d-grid gap-4">
                    {loading && !presets.length && (
                        <LoadingBlock height="180px"/>
                    )}

                    {showEmptySearchState && (
                        <div className="card card-body border-0">
                            <EmptySet
                                icon="fa-magnifying-glass"
                                message={t("workoutPresetComponent:noSearchResults")}
                            />
                        </div>
                    )}

                    {showEmptyPresetState && (
                        <span className="text-secondary">{t("workoutPresetComponent:noPresets")}</span>
                    )}

                    {renderSection(
                        t("workoutPresetComponent:userPresets"),
                        filteredUserPresets,
                        paginatedUserPresets,
                        userPage,
                        setUserPage
                    )}
                    {renderSection(
                        t("workoutPresetComponent:systemPresets"),
                        filteredSystemPresets,
                        paginatedSystemPresets,
                        systemPage,
                        setSystemPage,
                        true
                    )}
                </div>
            </div>

        </div>
    );

    const renderPreview = (isMobileSheet) => (
        <WorkoutPresetPreviewContent
            preset={selectedPreset}
            isMobileSheet={isMobileSheet}
            primaryLabel={t("workoutPresetComponent:addPreset")}
            secondaryLabel={t("workoutPresetComponent:back")}
            disabled={selectionDisabled}
            onPrimary={() => selectedPreset && handleSelectPreset(selectedPreset)}
            onSecondary={handleReturnToList}
        />
    );

    const renderCreate = () => (
        <div className="flex-grow-1 overflow-y-auto overflow-x-hidden">
            <div className="mb-3">
                <span className="fw-semibold fs-5 d-block">{t("workoutPresetComponent:createNewPreset")}</span>
            </div>
            <WorkoutPresetForm
                initialPresetKey="picker-create"
                loading={loading}
                onCancel={handleReturnToList}
                onSubmit={(payload) => onCreatePreset?.(payload)}
            />
        </div>
    );

    return (
        <AppOffcanvasShell
            show={show}
            onHide={onHide}
            bodyClassName="p-3"
        >
            {({isMobileSheet}) => {
                if (view === VIEW_PREVIEW) {
                    return renderPreview(isMobileSheet);
                }

                if (view === VIEW_CREATE) {
                    return renderCreate();
                }

                return renderList();
            }}
        </AppOffcanvasShell>
    );
};

export default WorkoutPresetPickerOffcanvas;
