import RoundedIcon from "../rounded-icon/RoundedIcon";
import Text from "../utils/emoji/Text";
import {useNavigate} from "react-router-dom";

const WorkoutLibraryItem = ({folder}) => {
    const navigate = useNavigate();

    const handleClick = () => {
        navigate(`/user/workout-library/folder/${folder.id}/${folder.tipo}`)
    }

    return (
        <>
            <div className={'row clickable-element'} onClick={handleClick}>
                <div className={'col-auto  '}>
                    <RoundedIcon icon={"fa-folder"} size={"sm"}/>
                </div>
                <div className={'col-auto   align-self-center ps-0 '}>
                    <span className={"text-default fw-semibold text-break"}>
                        <Text>{folder.name}</Text>
                    </span>
                </div>
            </div>
            <hr className={"text-secondary my-2"}/>
        </>
    )
}
export default WorkoutLibraryItem;