import {apiUrl  , getToken} from "../api";
import axios from "axios";

const version = "v4"
export const getBalanceAPI = async () => {
    const token = getToken();
    if (!token) return;
    return await axios.get(`${apiUrl}/user/${version}/wallet/balance`, {
        headers: {
            'Content-Type': 'application/json',
            'authorization': token
        },
        timeout: 30000
    });
}

