import {ErrorMessage, Field, Form, Formik} from "formik";
import {useMemo, useState} from "react";
import * as Yup from "yup";
import Select from "react-select";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/extra-training/locales/en-us.json";
import esES from "../../pages/extra-training/locales/es-es.json";
import ptPT from "../../pages/extra-training/locales/pt-pt.json";
import ptBR from "../../pages/extra-training/locales/pt-br.json";
import ClientRemoteMultiSelect from "../client/ClientRemoteMultiSelect";
import {
    hasRecipientSelection,
    shouldShowRecipientSelectionError
} from "../../utils/form/recipientSelection";

const YOUTUBE_REGEX = /^((?:https?:)?\/\/)?((?:www|m)\.)?(youtube\.com|youtu\.be)(\/(?:[\w-]+\?v=|embed|shorts\/|v\/)?)([\w-]+)(\S+)?$/;

const ExtraTrainingEditorForm = ({
    initialValues,
    onSubmit,
    loading,
    submitLabel,
    showTrainingFields = true,
    showRecipients = false,
    groupOptions = [],
    enforceCurrentClient = false,
    excludedClientId = null,
    showCloseButton = false,
    closeLabel,
    onClose
}) => {
    const {t} = useTranslation();
    const [hasUnresolvedClientSelections, setHasUnresolvedClientSelections] = useState(false);
    const [hasClientResolveError, setHasClientResolveError] = useState(false);

    useComponentTranslations("extraTrainingUser", {"en-US": enUS, "es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR});

    const today = useMemo(() => {
        const now = new Date();
        const localDate = new Date(now.getTime() - (now.getTimezoneOffset() * 60000));
        return localDate.toISOString().slice(0, 10);
    }, []);

    const validationSchema = useMemo(() => (
        Yup.object({
            executeAt: showTrainingFields
                ? Yup.string().required(t("extraTrainingUser:validation.requiredField"))
                : Yup.string().notRequired(),
            atividade: showTrainingFields
                ? Yup.string().trim().required(t("extraTrainingUser:validation.requiredField"))
                : Yup.string().notRequired(),
            instructions: Yup.string().max(400, t("extraTrainingUser:validation.instructionsMax")),
            url: Yup.string().test(
                "youtube-url",
                t("extraTrainingUser:validation.invalidYoutubeUrl"),
                (value) => !value || YOUTUBE_REGEX.test(value.trim())
            ),
            clients: Yup.array().notRequired(),
            groups: Yup.array().notRequired()
        })
    ), [showTrainingFields, t]);

    return (
        <Formik
            enableReinitialize
            initialValues={initialValues}
            validationSchema={validationSchema}
            validateOnMount
            onSubmit={onSubmit}
        >
            {({values, setFieldValue, setFieldTouched, touched, errors, submitCount, isValid}) => {
                const hasSelection = hasRecipientSelection({
                    clients: values.clients,
                    groups: values.groups,
                    enforceCurrentClient,
                    showRecipients
                });
                const recipientSelectionError = shouldShowRecipientSelectionError({
                    touchedClients: touched.clients,
                    touchedGroups: touched.groups,
                    submitCount,
                    hasRecipientSelection: hasSelection,
                    enforceCurrentClient,
                    showRecipients
                }) ? t("extraTrainingUser:validation.selectAtLeastOneRecipient") : null;
                const isClientSelectionBlocked = hasUnresolvedClientSelections || hasClientResolveError;
                const isSubmitDisabled = loading || !isValid || isClientSelectionBlocked || !hasSelection;

                return (
                    <Form>
                        {showTrainingFields && (
                            <>
                                <div className="form-group">
                                    <label className="fw-semibold">{t("extraTrainingUser:executionDate")}</label>
                                    <Field
                                        name="executeAt"
                                        type="date"
                                        min={today}
                                        className={`form-control ${touched.executeAt && errors.executeAt ? "is-invalid" : ""}`}
                                    />
                                    <ErrorMessage name="executeAt" component="div" className="invalid-feedback"/>
                                </div>
                                <div className="form-group mt-2">
                                    <label className="fw-semibold">{t("extraTrainingUser:activityName")}</label>
                                    <Field name="atividade">
                                        {({field, form, meta}) => (
                                            <input
                                                id={field.name}
                                                name={field.name}
                                                type="text"
                                                className={`form-control ${meta.touched && meta.error ? "is-invalid" : ""}`}
                                                value={field.value ?? ""}
                                                onChange={(event) => form.setFieldValue("atividade", event.target.value.normalize("NFC"))}
                                                onBlur={field.onBlur}
                                            />
                                        )}
                                    </Field>
                                    <ErrorMessage name="atividade" component="div" className="invalid-feedback"/>
                                </div>
                                <div className="form-group mt-2">
                                    <label className="fw-semibold">
                                        {t("extraTrainingUser:instructions")}
                                    </label>
                                    <Field name="instructions">
                                        {({field, form, meta}) => (
                                            <textarea
                                                id={field.name}
                                                name={field.name}
                                                rows={5}
                                                className={`form-control ${meta.touched && meta.error ? "is-invalid" : ""}`}
                                                value={field.value ?? ""}
                                                onChange={(event) => form.setFieldValue("instructions", event.target.value.normalize("NFC"))}
                                                onBlur={field.onBlur}
                                            />
                                        )}
                                    </Field>
                                    <div className="text-end small text-secondary">
                                        {(values.instructions || "").length}/400
                                    </div>
                                    <ErrorMessage name="instructions" component="div" className="invalid-feedback d-block"/>
                                </div>
                                <div className="form-group mt-2">
                                    <label className="fw-semibold">
                                        {t("extraTrainingUser:youtubeUrl")} <span className="small fst-italic">({t("extraTrainingUser:optional")})</span>
                                    </label>
                                    <Field name="url">
                                        {({field, form, meta}) => (
                                            <input
                                                id={field.name}
                                                name={field.name}
                                                type="text"
                                                className={`form-control ${meta.touched && meta.error ? "is-invalid" : ""}`}
                                                value={field.value ?? ""}
                                                onChange={(event) => form.setFieldValue("url", event.target.value.normalize("NFC"))}
                                                onBlur={field.onBlur}
                                            />
                                        )}
                                    </Field>
                                    <ErrorMessage name="url" component="div" className="invalid-feedback"/>
                                </div>
                            </>
                        )}

                        {showRecipients && (
                            <>
                                {showTrainingFields && <hr className="my-3"/>}
                                <div className="fw-semibold mb-2">
                                    {t("extraTrainingUser:sendAlsoTo")} <span className="small fst-italic">({t("extraTrainingUser:optional")})</span>
                                </div>
                                <div className="form-group">
                                    <label className="fw-semibold">{t("extraTrainingUser:clients")}</label>
                                    <ClientRemoteMultiSelect
                                        valueIds={values.clients}
                                        onChangeIds={(nextIds) => {
                                            const normalizedIds = Array.from(new Set((nextIds || [])
                                                .map(Number)
                                                .filter((id) => !Number.isNaN(id))
                                                .filter((id) => excludedClientId == null || id !== Number(excludedClientId))));

                                            setFieldValue("clients", normalizedIds, false);
                                            setFieldTouched("clients", true, false);
                                        }}
                                        onBlur={() => setFieldTouched("clients", true, false)}
                                        onSelectionStateChange={({unresolvedIds, hasResolveError}) => {
                                            setHasUnresolvedClientSelections((unresolvedIds || []).length > 0);
                                            setHasClientResolveError(Boolean(hasResolveError));
                                        }}
                                        searchScope={"active"}
                                        resolveScope={"nonDeleted"}
                                        placeholder={t("extraTrainingUser:select")}
                                        disabled={loading}
                                    />
                                    {isClientSelectionBlocked && (
                                        <div className="form-text text-danger">
                                            {t("extraTrainingUser:validation.loadSelectedClientsBeforeSave")}
                                        </div>
                                    )}
                                </div>
                                <div className="form-group mt-2">
                                    <label className="fw-semibold">{t("extraTrainingUser:groups")}</label>
                                    <Select
                                        isMulti
                                        name="groups"
                                        options={groupOptions}
                                        className="basic-multi-select"
                                        classNamePrefix="select"
                                        placeholder={t("extraTrainingUser:select")}
                                        onChange={(options) => {
                                            const nextGroups = options ? options.map(option => option.value) : [];
                                            setFieldValue("groups", nextGroups, false);
                                            setFieldTouched("groups", true, false);
                                        }}
                                        onBlur={() => setFieldTouched("groups", true, false)}
                                        value={groupOptions.filter(option => values.groups.includes(option.value))}
                                    />
                                    {recipientSelectionError && (
                                        <div className="text-danger small mt-1">
                                            {recipientSelectionError}
                                        </div>
                                    )}
                                </div>
                                {values.groups.length > 0 && (
                                    <div className="alert alert-primary mt-3 mb-0 py-2">
                                        <span className="fw-semibold me-1">{t("extraTrainingUser:groupWarningTitle")}!</span>
                                        <span>{t("extraTrainingUser:groupWarningText")}</span>
                                    </div>
                                )}
                            </>
                        )}

                        <div className={`form-check form-switch ${showTrainingFields || showRecipients ? "mt-3" : ""}`}>
                            <Field
                                id="notificar"
                                name="notificar"
                                type="checkbox"
                                className="form-check-input"
                            />
                            <label htmlFor="notificar" className="form-check-label fw-semibold">
                                {t("extraTrainingUser:sendReminder")}
                            </label>
                        </div>

                        <div className={`d-grid gap-2 ${showTrainingFields || showRecipients ? "mt-3" : ""}`}>
                            <button type="submit" className="btn btn-primary" disabled={isSubmitDisabled}>
                                {submitLabel}
                            </button>
                            {showCloseButton && onClose && (
                                <button type="button" className="btn btn-outline-primary" onClick={onClose}>
                                    {closeLabel}
                                </button>
                            )}
                        </div>
                    </Form>
                );
            }}
        </Formik>
    );
};

export default ExtraTrainingEditorForm;
