import {useEffect, useState} from "react";
import {getExerciseName} from "../../utils/workout/Workout";
import {useTranslation} from "react-i18next";
import _ from "lodash";
import WorkoutSeries from "../workout-session/WorkoutSeries";
import WorkoutPdfImageType from "./WorkoutPdfImageType";

const WorkoutPdfExerciseCard = ({exerc, mainId, exercList, isCombinado, showImages}) => {
    const {i18n} = useTranslation();
    const [exercise, setExercise] = useState([{}]);
    const isReplacement = mainId !== exercise.idExercSession && !isCombinado;

    useEffect(() => {
        if (exercList) {
            setExercise(exercList[0])
        } else {
            setExercise(exerc.exercises ? exerc.exercises[0] : exerc.exercicio ? exerc.exercicio : exerc)
        }
    }, [exerc, exercList]);


    return (
        <>
            {
                (exercList?.length <= 1 || !exercList) &&
                <div className={`row justify-content-between ${isReplacement ? "pb-3" : "py-3"}  `}>
                    {
                        isReplacement &&
                        <span className={"pb-2  text-primary"}><span className={"fw-semibold"}>Ou substitua por:</span></span>
                    }
                    <div className={`col-${exercise.mediaType === 0 ? "7" : "9"}  `}>
                        <div className={"row "}>
                            <div className={"col-12"}>
                                <span className={'d-block fw-bold'} style={{lineHeight: "1.1rem"}}>
                                    {getExerciseName(exercise, i18n)}
                                </span>
                            </div>
                            <div className={"col-12 pt-2"}>
                                {
                                    _.map(exercise.series, (serie) => (
                                        <WorkoutSeries key={serie.id}
                                                       serie={serie}
                                                       seriesLength={exercise.series.length}
                                                       preview={false}
                                        />
                                    ))
                                }
                            </div>
                        </div>
                    </div>
                    {
                        showImages &&
                        <WorkoutPdfImageType exercise={exercise}/>
                    }
                </div>
            }
            {
                exercList && exercList.length > 1 &&
                exercList.map((ex) => (
                    <div className={'col-12 '} key={ex.id}>
                        <WorkoutPdfExerciseCard mainId={mainId} exerc={ex} showImages={showImages}/>
                    </div>
                ))
            }
        </>
    )
}
export default WorkoutPdfExerciseCard;