import {all, takeLatest, call, put} from 'redux-saga/effects';
import {
    contactConverted,
    convertContactToClient,
    deleteAllContacts,
    deleteContact,
    fetchContacts,
    onError,
    removeContact,
    setContacts
} from "./signupLinkReducer";
import {handleError} from "../../utils/error/sagaErrorHandling";
import {convertContactToClientAPI, deleteAllContactsAPI, deleteContactAPI, fetchContactsAPI} from "../../api/signup-link/signupLinkActions";


export function* fetchContactsAsync(action) {
    try {
        const response = yield call(fetchContactsAPI, action.payload)
        yield put(setContacts(response.data))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchContacts() {
    yield takeLatest(fetchContacts, fetchContactsAsync)
}

export function* deleteContactAsync(action) {
    try {
        yield call(deleteContactAPI, action.payload)
        yield put(removeContact(action.payload))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDeleteContact() {
    yield takeLatest(deleteContact, deleteContactAsync)
}

export function* onDeleteAllContactsAsync() {
    try {
        yield call(deleteAllContactsAPI)
        yield put(setContacts(null))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onDeleteAllContacts() {
    yield takeLatest(deleteAllContacts, onDeleteAllContactsAsync)
}

export function* onConvertContactToClientAsync(action) {
    try {
        yield call(convertContactToClientAPI, action.payload)
        yield put(contactConverted(true))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onConvertContactToClient() {
    yield takeLatest(convertContactToClient, onConvertContactToClientAsync)
}


export function* signupLinkSaga() {
    yield all([
        call(onFetchContacts),
        call(onDeleteContact),
        call(onDeleteAllContacts),
        call(onConvertContactToClient)
    ])
}
