import React, {useEffect, useMemo, useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import Page from "../../components/page/Page";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {compareEvaluation} from "../../store/online-evaluation/evaluationOnlineReducer";
import {fetchClient} from "../../store/client/clientReducer";
import {getCompareEvaluationList} from "../../store/online-evaluation/evaluationOnlineSelector";
import moment from "moment";
import {evaluationFields} from "../../utils/onlineEvaluation/evaluationFields";
import ImageCarousel from "../../utils/imagecarousel/ImageCarousel";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {calculateIMC, formatIMC} from "../../utils/physicalEvaluation/imcFormula";
import {calculateAge} from "../../utils/date/dateUtils";
import EvaluationCompareTableComponent from "../../components/evaluation-components/EvaluationCompareTableComponent";
import he from "he";
import {calculateRQC, formatRQC} from "../../utils/physicalEvaluation/rqcFormula";
import {buildOnlineEvaluationsRoute} from "../../utils/client/evaluationRoutes";

const OnlineEvaluationCompare = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, evaluationIds} = useParams();
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const allEvaluationsRaw = useSelector(getCompareEvaluationList);
    const {t} = useTranslation("evaluationOnline");
    useComponentTranslations("evaluationOnline", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const selectedIds = useMemo(
        () => (evaluationIds ? evaluationIds.split(',') : []),
        [evaluationIds]
    );

    const selectedEvaluations = useMemo(
        () => (Array.isArray(allEvaluationsRaw) ? allEvaluationsRaw : []),
        [allEvaluationsRaw]
    );

    const evaluationsWithFormatters = useMemo(() => {
        const noAnswer = "—";

        return selectedEvaluations.map(ev => {
            const rawImc = ev.imc != null
                ? ev.imc
                : calculateIMC(ev.weight, ev.height);

            const decodedGoal = typeof ev.goal === "string"
                ? he.decode(ev.goal)
                : ev.goal;

            const formattedRcq = ev.rqc != null
                ? t(`evaluationOnline:rcqOptions.${ev.rqc}`, {defaultValue: String(ev.rqc)})
                : noAnswer;

            return {
                ...ev,
                imc: rawImc,
                goal: decodedGoal,
                rcq: formattedRcq,
            };
        });
    }, [selectedEvaluations, t]);


    const dynamicFields = useMemo(() => {
        if (evaluationsWithFormatters.length === 0) return [];

        const keys = Object.keys(evaluationsWithFormatters[0]);

        const skip = new Set(["id", "idUser", "idClient", "status", "aiAnalysis",
            "pictureFront", "pictureSide", "pictureBack", "sentDate", "answerDate", "rqc"]);

        return keys
            .filter(key => !skip.has(key))
            .map(key => {
                const base = evaluationFields.find(f => f.id === key);
                return {
                    id: key,
                    label: t(`evaluationOnline:${key}`),
                    type: key.toLowerCase().includes("date") ? "date" : "text",
                    unit: base?.unit,
                }
            });
    }, [evaluationsWithFormatters, t]);

    const noAnswerLabel = "—";
    const dateFieldId = useMemo(() => {
        return dynamicFields.find(f => f.type === 'date')?.id || 'answerDate';
    }, [dynamicFields])

    const [currentEvaluation, setCurrentEvaluation] = useState(null);

    const rcqRaw = calculateRQC(
        currentEvaluation?.waist,
        currentEvaluation?.hip
    );

    const rcqFormatted = rcqRaw != null
        ? formatRQC(rcqRaw, selectedClient?.sexo, t)
        : "";

    const imcRaw = currentEvaluation?.imc != null
        ? currentEvaluation?.imc
        : calculateIMC(currentEvaluation?.weight, currentEvaluation?.height);

    const imcFormatted = imcRaw != null
        ? formatIMC(imcRaw, t)
        : "";

    const photoImages = [
        currentEvaluation?.pictureFront && {id: 'front', url: currentEvaluation.pictureFront},
        currentEvaluation?.pictureSide && {id: 'side', url: currentEvaluation.pictureSide},
        currentEvaluation?.pictureBack && {id: 'back', url: currentEvaluation.pictureBack},
    ].filter(Boolean);

    const initialValues = React.useMemo(() => {
        const values = {
            goal: currentEvaluation?.goal ?? "",
            idade: currentEvaluation?.idade ?? "",
            answerDate: currentEvaluation?.answerDate ?? "",
            height: currentEvaluation?.height ?? "",
            weight: currentEvaluation?.weight ?? "",
            chest: currentEvaluation?.chest ?? "",
            biceps: currentEvaluation?.biceps ?? "",
            forearm: currentEvaluation?.forearm ?? "",
            waist: currentEvaluation?.waist ?? "",
            abs: currentEvaluation?.abs ?? "",
            hip: currentEvaluation?.hip ?? "",
            thigh: currentEvaluation?.thigh ?? "",
        };
        if (selectedClient?.data_nascimento) {
            values.idade = calculateAge(selectedClient.data_nascimento);
        }
        return values;
    }, [currentEvaluation, selectedClient]);

    const fieldMapping = {
        goal: t("evaluationOnline:goal"),
        idade: t("evaluationOnline:age"),
        answerDate: t("evaluationOnline:answered"),
        height: t("evaluationOnline:height"),
        weight: t("evaluationOnline:weight"),
        chest: t("evaluationOnline:chest"),
        biceps: t("evaluationOnline:biceps"),
        forearm: t("evaluationOnline:forearm"),
        waist: t("evaluationOnline:waist"),
        abs: t("evaluationOnline:abs"),
        hip: t("evaluationOnline:hip"),
        thigh: t("evaluationOnline:thigh"),
    };

    const unitMapping = {
        height: "cm",
        weight: "kg",
        chest: "cm",
        biceps: "cm",
        forearm: "cm",
        waist: "cm",
        abs: "cm",
        hip: "cm",
        thigh: "cm",
    };

    const fieldSections = useMemo(
        () => ({
            goal: "evaluationDetails",
            idade: "evaluationDetails", // check this key matches initialValues (maybe "age"?)
            height: "evaluationDetails",
            weight: "evaluationDetails",
            chest: "perimetry",
            biceps: "perimetry",
            forearm: "perimetry",
            waist: "perimetry",
            abs: "perimetry",
            hip: "perimetry",
            thigh: "perimetry",
        }),
        []
    );

    const sections = React.useMemo(() => {
        const grouped = [];
        Object.entries(initialValues).forEach(([id, value]) => {
            if (id === "answerDate") return;
            if (value === undefined || value === null || value === "") return;
            const section = fieldSections[id] || "evaluationDetails";
            let group = grouped.find((g) => g.section === section);
            if (!group) {
                group = {section, fields: []};
                grouped.push(group);
            }
            group.fields.push({id, value});
        });
        return grouped;
    }, [initialValues, fieldSections]);

    const handleGoBackPage = () => {
        navigate(buildOnlineEvaluationsRoute(id, "1"));
    };

    useEffect(() => {
        dispatch(fetchClient(id));
        if (selectedIds.length > 0) {
            dispatch(compareEvaluation({clientId: id, ids: selectedIds.join(",")}));
        }
    }, [dispatch, id, selectedIds]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"}>
                <div className={"row justify-content-center"}>
                    <div className={"col-12"}>
                        <div className={"card card-body border-0"}>
                            {!currentEvaluation &&
                                <>
                                    <div className="col-12 pb-2">
                                        <span className="fw-semibold fs-5 d-block">{t("evaluationOnline:compareTitle")}</span>
                                    </div>
                                    <EvaluationCompareTableComponent
                                        fields={dynamicFields}
                                        data={evaluationsWithFormatters}
                                        noAnswerLabel={noAnswerLabel}
                                        dateKey={dateFieldId}
                                        fieldFormatters={{
                                            imc: raw => formatIMC(raw, t),
                                        }}
                                        showComparison
                                        comparisonLabel={t("evaluationOnline:comparison")}
                                    />
                                </>
                            }
                            {currentEvaluation && (
                                <div>
                                    {sections.map(({section, fields}) => (
                                        <div key={section}>
                                            <span className="fw-semibold fs-5 d-block pb-2">{t(`evaluationOnline:${section}`)}</span>
                                            {fields.map(({id, value}) => {
                                                const rawValue = id === "sentDate"
                                                    ? (value && moment(value).format("L"))
                                                    : value;
                                                const displayValue = typeof rawValue === "string"
                                                    ? he.decode(rawValue)
                                                    : rawValue;
                                                return (
                                                    <div key={id} className="mb-1 row">
                                                        <label htmlFor={id} className="fw-semibold">
                                                            {fieldMapping[id] || id}
                                                        </label>
                                                        <div className="bg-white border-0">
                                                            {displayValue}{unitMapping[id] || ""}
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                            <hr className="border-primary-subtle"/>
                                        </div>
                                    ))}
                                    <span className="fw-semibold  fs-5 pb-2 d-block">{t("evaluationOnline:result")}</span>
                                    <div>
                                        <label className="fw-semibold d-block">{t("evaluationOnline:imc")}</label>
                                        <span>
                                            {imcFormatted}
                                        </span>
                                    </div>
                                    <div>
                                        <label className="fw-semibold d-block">{t("evaluationOnline:rcq")}</label>
                                        <span>{rcqFormatted}</span>
                                    </div>
                                    <div>
                                        <label className="fw-semibold d-block">{t("evaluationOnline:perimeterSum")}</label>
                                        <span>{currentEvaluation?.perimeterSum}cm</span>
                                    </div>
                                    {currentEvaluation?.percentage && (
                                        <div>
                                            <label className={"fw-semibold d-block"}>{t("evaluationOnline:percentage")}</label>
                                            <span>
                                                {currentEvaluation.percentage}%
                                            </span>
                                        </div>
                                    )}
                                    {currentEvaluation?.weightLean && (
                                        <div>
                                            <span className={"fw-semibold d-block"}>{t("evaluationOnline:weightLean")} </span>
                                            <span>
                                                {currentEvaluation.weightLean}Kgs
                                            </span>
                                        </div>
                                    )}
                                    {currentEvaluation?.weightFat && (
                                        <div>
                                            <span className={"fw-semibold d-block"}>{t("evaluationOnline:weightFat")} </span>
                                            <span>
                                                {currentEvaluation.weightFat} Kgs
                                            </span>
                                        </div>
                                    )}
                                    {(currentEvaluation?.pictureFront ||
                                        currentEvaluation?.pictureSide ||
                                        currentEvaluation?.pictureBack) && (
                                        <div className={"text-center pt-3"}>
                                            <div className={"pb-2"}>
                                                <span className={"fw-semibold"}>{t("evaluationOnline:images")}</span>
                                            </div>
                                            <ImageCarousel images={photoImages}/>
                                        </div>
                                    )}
                                </div>
                            )}
                            <button
                                className={`btn ${!currentEvaluation ? "btn-primary" : "btn-outline-primary"} my-2`}
                                onClick={() => setCurrentEvaluation(null)}
                            >
                                {t("evaluationOnline:comparison")}
                            </button>
                            <div className="d-flex flex-column gap-2">
                                {selectedEvaluations.map((evaluation) => (
                                    <button
                                        key={evaluation.id}
                                        className={`btn ${currentEvaluation && currentEvaluation.id === evaluation.id
                                            ? "btn-primary"
                                            : "btn-outline-primary"}`}
                                        onClick={() => {
                                            if (currentEvaluation && currentEvaluation.id === evaluation.id) {
                                                setCurrentEvaluation(null);
                                            } else {
                                                setCurrentEvaluation(evaluation);
                                            }
                                        }}
                                    >
                                        {evaluation.answerDate
                                            ? moment(evaluation.answerDate).format("L")
                                            : t("evaluationOnline:noAnswer")}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </Page>
        </>
    );
};

export default OnlineEvaluationCompare;
