import React, {useState, useMemo, useRef} from 'react';
import {Formik, Form, Field, ErrorMessage} from 'formik';
import InputMask from 'react-input-mask';
import * as Yup from 'yup';
import {getCep} from '../../api/cep/cep';
import LoadingBlock from '../loader/LoadingBlock';
import {useDispatch} from "react-redux";
import {createBuyer} from "../../store/subscription/subscriptionReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const SubscriptionUserAddress = () => {
    const {t} = useTranslation();
    const translationsLoaded = useComponentTranslations('subscriptionComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const [disabledFields, setDisabledFields] = useState({
        street: true,
        neighborhood: true,
        city: true,
        state: true,
    });
    const [loadingCep, setLoadingCep] = useState(false);
    const [cepValid, setCepValid] = useState(false);
    const dispatch = useDispatch();
    const lastCepFetched = useRef('');

    const initialValues = {
        cep: '',
        street: '',
        number: '',
        complement: '',
        neighborhood: '',
        city: '',
        state: ''
    };

    const validationSchema = useMemo(
        () =>
            Yup.object().shape({
                cep: Yup.string()
                    .required(t('subscriptionComponent:subscriptionUserAddress.errors.cepRequired'))
                    .matches(/^\d{5}-\d{3}$/, t('subscriptionComponent:subscriptionUserAddress.errors.invalidCepFormat'))
                    .test('valid-cep', t('subscriptionComponent:subscriptionUserAddress.errors.cepNotFound'), () => cepValid),
                street: Yup.string().required(t('subscriptionComponent:subscriptionUserAddress.errors.streetRequired')),
                number: Yup.string().required(t('subscriptionComponent:subscriptionUserAddress.errors.numberRequired')),
                complement: Yup.string(),
                neighborhood: Yup.string().required(t('subscriptionComponent:subscriptionUserAddress.errors.neighborhoodRequired')),
                city: Yup.string().required(t('subscriptionComponent:subscriptionUserAddress.errors.cityRequired')),
                state: Yup.string().required(t('subscriptionComponent:subscriptionUserAddress.errors.stateRequired'))
            }),
        // eslint-disable-next-line
        [cepValid, t, translationsLoaded]
    );

    const clearAddressFields = (setFieldValue) => {
        setFieldValue('street', '');
        setFieldValue('neighborhood', '');
        setFieldValue('city', '');
        setFieldValue('state', '');
    };

    const fetchAndFillCep = async (
        numericCep,
        setFieldValue,
        setFieldTouched,
        setFieldError
    ) => {
        setFieldTouched('cep', true);
        setLoadingCep(true);
        try {
            const response = await getCep(numericCep);
            const data = response?.data;

            if (!data || data.erro) {
                setCepValid(false);
                clearAddressFields(setFieldValue);
                setDisabledFields({street: true, neighborhood: true, city: true, state: true});
                setFieldError('cep', t('subscriptionComponent:subscriptionUserAddress.errors.cepNotFound'));
                return;
            }

            setCepValid(true);
            setFieldError('cep', undefined);
            setFieldValue('street', data.street || '');
            setFieldValue('neighborhood', data.neighborhood || '');
            setFieldValue('city', data.city || '');
            setFieldValue('state', data.state || '');
            setDisabledFields({
                street: Boolean(data.street),
                neighborhood: Boolean(data.neighborhood),
                city: true,
                state: true,
            });
        } catch (err) {
            console.error(err);
            setCepValid(false);
            clearAddressFields(setFieldValue);
            setDisabledFields({street: true, neighborhood: true, city: true, state: true});
            setFieldError('cep', t('subscriptionComponent:subscriptionUserAddress.errors.cepNotFound'));
        } finally {
            setLoadingCep(false);
        }
    };

    const handleCepChange = async (e, setFieldValue, setFieldTouched, setFieldError) => {
        const masked = e.target.value;
        const numeric = masked.replace(/\D/g, '');

        setFieldValue('cep', masked);

        if (numeric.length < 8) {
            setCepValid(false);
            clearAddressFields(setFieldValue);
            setDisabledFields({ street: true, neighborhood: true, city: true, state: true });
            lastCepFetched.current = '';
            return;
        }

        if (numeric.length === 8 && numeric !== lastCepFetched.current) {
            lastCepFetched.current = numeric;
            await fetchAndFillCep(numeric, setFieldValue, setFieldTouched, setFieldError);
        }
    };

    const handleCepBlur = async (e, setFieldValue, setFieldTouched, setFieldError) => {
        const cepValue = e.target.value.replace(/\D/g, '');

        setFieldTouched('cep', true);

        if (cepValue.length !== 8) {
            setCepValid(false);
            clearAddressFields(setFieldValue);
            setDisabledFields({ street: true, neighborhood: true, city: true, state: true });
            setFieldError('cep', t('subscriptionComponent:subscriptionUserAddress.errors.invalidCepFormat'));
            lastCepFetched.current = ''; // também libera próxima tentativa
            return;
        }

        if (cepValue === lastCepFetched.current && cepValid) return;

        lastCepFetched.current = cepValue;
        await fetchAndFillCep(cepValue, setFieldValue, setFieldTouched, setFieldError);
    };


    const handleSubmit = (values) => {
        dispatch(createBuyer(values));
    };

    if (!translationsLoaded) {
        return null;
    }

    return (
        <Formik
            initialValues={initialValues}
            validationSchema={validationSchema}
            onSubmit={handleSubmit}
            validateOnBlur={true}
            validateOnChange={false}
        >
            {({touched, errors}) => (
                <Form>
                    <div className="form-group">
                        <label htmlFor="cep" className="fw-semibold">
                            {t('subscriptionComponent:subscriptionUserAddress.fields.cep')}
                        </label>
                        <Field name="cep">
                            {({field, form}) => (
                                <InputMask
                                    {...field}
                                    id="cep"
                                    mask="99999-999"
                                    className={`form-control ${form.touched.cep && form.errors.cep ? 'is-invalid' : ''}`}
                                    onChange={(e) =>
                                        handleCepChange(
                                            e,
                                            form.setFieldValue,
                                            form.setFieldTouched,
                                            form.setFieldError
                                        )
                                    }
                                    onBlur={(e) =>
                                        handleCepBlur(
                                            e,
                                            form.setFieldValue,
                                            form.setFieldTouched,
                                            form.setFieldError
                                        )
                                    }
                                />
                            )}
                        </Field>
                        <ErrorMessage name="cep" component="div" className="invalid-feedback"/>
                    </div>

                    {loadingCep && <LoadingBlock height="70px"/>}
                    {
                        !loadingCep &&
                        <>
                            <div className="form-group mt-2">
                                <label htmlFor="street" className="fw-semibold">
                                    {t('subscriptionComponent:subscriptionUserAddress.fields.street')}
                                </label>
                                <Field
                                    id="street"
                                    name="street"
                                    className={`form-control ${touched.street && errors.street ? 'is-invalid' : ''}`}
                                    disabled={!cepValid || disabledFields.street}
                                />
                                <ErrorMessage name="street" component="div" className="invalid-feedback"/>
                            </div>

                            <div className="form-group mt-2">
                                <div className={"row justify-content-between"}>
                                    <div className={"col-6 pe-1"}>
                                        <label htmlFor="number" className="fw-semibold">
                                            {t('subscriptionComponent:subscriptionUserAddress.fields.number')}
                                        </label>
                                        <Field
                                            id="number"
                                            name="number"
                                            className={`form-control ${touched.number && errors.number ? 'is-invalid' : ''}`}
                                            disabled={!cepValid}
                                        />
                                        <ErrorMessage name="number" component="div" className="invalid-feedback"/>
                                    </div>
                                    <div className={"col-6 ps-1"}>
                                        <label htmlFor="complement" className="fw-semibold">
                                            {t('subscriptionComponent:subscriptionUserAddress.fields.complement')}
                                        </label>
                                        <Field
                                            id="complement"
                                            name="complement"
                                            className={`form-control ${touched.complement && errors.complement ? 'is-invalid' : ''}`}
                                            disabled={!cepValid}
                                        />
                                        <ErrorMessage name="complement" component="div" className="invalid-feedback"/>
                                    </div>
                                </div>
                            </div>
                            <div className="form-group mt-2">
                                <label htmlFor="neighborhood" className="fw-semibold">
                                    {t('subscriptionComponent:subscriptionUserAddress.fields.neighborhood')}
                                </label>
                                <Field
                                    id="neighborhood"
                                    name="neighborhood"
                                    className={`form-control ${touched.neighborhood && errors.neighborhood ? 'is-invalid' : ''}`}
                                    disabled={!cepValid || disabledFields.neighborhood}
                                />
                                <ErrorMessage name="neighborhood" component="div" className="invalid-feedback"/>
                            </div>
                            <div className={"row justify-content-between"}>
                                <div className={"col-8 pe-1"}>
                                    <div className="form-group mt-2">
                                        <label htmlFor="city" className="fw-semibold">
                                            {t('subscriptionComponent:subscriptionUserAddress.fields.city')}
                                        </label>
                                        <Field
                                            id="city"
                                            name="city"
                                            className={`form-control ${touched.city && errors.city ? 'is-invalid' : ''}`}
                                            disabled={!cepValid || disabledFields.city}
                                        />
                                        <ErrorMessage name="city" component="div" className="invalid-feedback"/>
                                    </div>
                                </div>
                                <div className={"col-4 ps-1"}>
                                    <div className="form-group mt-2">
                                        <label htmlFor="state" className="fw-semibold">
                                            {t('subscriptionComponent:subscriptionUserAddress.fields.state')}
                                        </label>
                                        <Field
                                            id="state"
                                            name="state"
                                            className={`form-control ${touched.state && errors.state ? 'is-invalid' : ''}`}
                                            disabled={!cepValid || disabledFields.state}
                                        />
                                        <ErrorMessage name="state" component="div" className="invalid-feedback"/>
                                    </div>
                                </div>
                            </div>
                            <button
                                type="submit"
                                className="btn btn-primary mt-3 w-100"
                                disabled={!cepValid}
                            >
                                {t('subscriptionComponent:next')}
                            </button>
                        </>
                    }

                </Form>
            )}
        </Formik>
    );
};

export default SubscriptionUserAddress;
