import Modal from "react-bootstrap/Modal";
import WorkoutExerciseSubSingularListItem from "./WorkoutExerciseSubSingularListItem";
import {useState} from "react";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "../../pages/workout-session/locales/en-us.json";
import ptBR from "../../pages/workout-session/locales/pt-br.json";
import esES from "../../pages/workout-session/locales/es-es.json";
import ptPT from "../../pages/workout-session/locales/pt-pt.json";

const WorkoutExerciseSubSingularList = ({exercsList, setExercise}) => {
    const {t} = useTranslation();
    const [show, setShow] = useState(false);
    useComponentTranslations('workout', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const handleCardClick = (id) => {
        setExercise(exercsList.find(e => e.id === id));
        setShow(false)
    }
    const handleModalClick = () => {
        setShow((prevShow) => !prevShow)
    }
    return (
        <>
            <div style={{borderTop: "solid 1px #dee2e6"}}></div>
            <div
                className={'row d-flex ps-3 pt-2 pb-2  pe-4 small text-primary-darker fw-semibold clickable-element'}
                onClick={handleModalClick}>
                <div className={'col-11'}>
                    <span>{t("workout:subModalTitle")}</span>
                </div>
                <div className={'col-1 '}>
                    <span><i className={'fa-regular fa-chevron-right'}></i></span>
                </div>
            </div>
            <Modal show={show} contentClassName={'modal-gray'} centered onHide={handleModalClick}>
                <Modal.Body   >
                    <div className={'row  d-flex'}>
                        <div className={'col-10'}>
                            <span className={'fw-semibold d-block'} style={{lineHeight: "1.1rem"}}>{t("workout:subModalInstructions")}:</span>
                        </div>
                        <div className={'col-2 text-center clickable-element'} onClick={handleModalClick}>
                            <span><i className={'fa-regular fa-lg fa-times'}></i></span>
                        </div>
                    </div>
                    <div className={'row d-flex '}>
                        {exercsList.map((ex) => (
                            <div className={'col-12 mt-3'} key={ex.id}  >
                                <div className={'card card-body p-0 card-no-border'}>
                                    <WorkoutExerciseSubSingularListItem handleCardClick={handleCardClick} exerc={ex}/>
                                </div>
                            </div>
                        ))}
                    </div>
                </Modal.Body>
            </Modal>
        </>
    )
}
export default WorkoutExerciseSubSingularList;