import {takeLatest, all, call, put} from 'redux-saga/effects';
import {handleError} from "../../utils/error/sagaErrorHandling";
import {
    fetchAllUpdatesByTypeCountAPI,
    fetchUnreadUpdatesByTypeCountAPI,
    fetchUnreadUpdatesCountAPI, resolveAllUpdatesAPI,
    resolveUpdateAPI
} from "../../api/updates/updatesActions";
import {respondClientProgressAPI} from "../../api/client-progress/clientProgressActions";
import {
    setUpdatesCount,
    onError,
    fetchUpdatesCount,
    setUpdateCountByType,
    fetchUpdateCountByType,
    setUpdatesByType,
    fetchAllUpdatesByType,
    resolveUpdateSuccess,
    resolveUpdate,
    respondMyProgressUpdateSuccess,
    respondMyProgressUpdate,
    resolveAllUpdates,
    resolveAllUpdatesSuccess,
    resolveAllUpdatesFailure
} from "./updatesReducer";


export function* fetchUnreadUpdatesCountAsync() {
    try {
        const response = yield call(fetchUnreadUpdatesCountAPI);
        yield put(setUpdatesCount(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchUnreadUpdatesCount() {
    yield takeLatest(fetchUpdatesCount.type, fetchUnreadUpdatesCountAsync);
}

export function* fetchUpdateCountyByTypeAsync() {
    try {
        const response = yield call(fetchUnreadUpdatesByTypeCountAPI);
        yield put(setUpdateCountByType(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchUpdateCountByType() {
    yield takeLatest(fetchUpdateCountByType.type, fetchUpdateCountyByTypeAsync);
}

export function* fetchAllUpdatesByTypeAsync(action) {
    try {
        const response = yield call(fetchAllUpdatesByTypeCountAPI, action.payload);
        yield put(setUpdatesByType(response.data));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchAllUpdatesByType() {
    yield takeLatest(fetchAllUpdatesByType.type, fetchAllUpdatesByTypeAsync);
}

export function* resolveUpdateAsync(action) {
    try {
        yield call(resolveUpdateAPI, action.payload);
        yield put(resolveUpdateSuccess(action.payload));
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onResolveUpdate() {
    yield takeLatest(resolveUpdate.type, resolveUpdateAsync);
}

export function* respondMyProgressUpdateAsync(action) {
    try {
        const {id, formData, progressId, clientId} = action.payload;
        yield call(respondClientProgressAPI, {id: clientId, progressId, formData});
        yield put(respondMyProgressUpdateSuccess(id));
        yield put(fetchUpdatesCount());
        yield put(fetchUpdateCountByType());
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onRespondMyProgressUpdate() {
    yield takeLatest(respondMyProgressUpdate.type, respondMyProgressUpdateAsync);
}

export function* resolveAllUpdatesByTypeAsync(action) {
    try {
        const context = action.payload?.context ?? null;
        const payload = typeof action.payload === "number"
            ? {type: action.payload}
            : action.payload?.payload ?? action.payload;
        const {context: _ignoredContext, payload: _ignoredPayload, ...apiPayload} = payload || {};
        const response = yield call(resolveAllUpdatesAPI, apiPayload);
        yield put(resolveAllUpdatesSuccess({context, updates: response.data}));
    } catch (error) {
        yield put(resolveAllUpdatesFailure({context: action.payload?.context ?? null, error}));
        yield call(handleError, error, onError)
    }
}

export function* onResolveAllUpdatesByType() {
    yield takeLatest(resolveAllUpdates.type, resolveAllUpdatesByTypeAsync);
}

export function* updatesSaga() {
    yield all([
        call(onFetchUnreadUpdatesCount),
        call(onFetchUpdateCountByType),
        call(onFetchAllUpdatesByType),
        call(onResolveUpdate),
        call(onRespondMyProgressUpdate),
        call(onResolveAllUpdatesByType)
    ])
}
