import {put} from 'redux-saga/effects';
import {addToast} from "../../store/toast/toastReducer";
import {buildApiErrorToastPayload, normalizeApiError} from "./errorToastUtils";

export function* handleError(error, onError) {
    yield put(onError(normalizeApiError(error)));

    const toastPayload = buildApiErrorToastPayload(error);
    if (toastPayload?.title || toastPayload?.message) {
        yield put(addToast(toastPayload));
    }
}
