import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {getFileIcon, getFileType} from "../../utils/files/getFileIcon";
import {ModalBody} from "react-bootstrap";
import Modal from "react-bootstrap/Modal";
import {useState} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {deleteFile} from "../../store/files/filesReducer";
import ChangeStatus from "../utils/change-status/ChangeStatus";
import {useDispatch} from "react-redux";
import RoundedIcon from "../rounded-icon/RoundedIcon";

const FileCard = ({file, handleDownload, isDownloading}) => {
    const {t} = useTranslation("filesComponent");
    const navigate = useNavigate();
    const {clientId} = useParams();
    const dispatch = useDispatch();
    const iconClass = getFileIcon(file.url);
    const fileType = getFileType(file.url);
    const [showOptionsFile, setShowOptionsFile] = useState(false);
    const [showDeleteFile, setShowDeleteFile] = useState(false);
    useComponentTranslations('filesComponent', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleDeleteModal = () => {
        setShowDeleteFile(prevState => !prevState)
        handleShowOptions();
    }

    const handleDeleteFile = () => {
        dispatch(deleteFile({id: clientId, fileId: file.id}))
        handleDeleteModal();
    };

    const handleShowOptions = () => {
        setShowOptionsFile(prevState => !prevState)
    }
    const handleOpenFile = async () => {
        if (!file?.url) return;
        try {
            const link = document.createElement("a");
            link.href = file.url;
            link.download = file.nome;
            document.body.appendChild(link);
            link.target = "_blank"
            link.click();
            link.remove();
            window.URL.revokeObjectURL(file.url);
        } catch (err) {
            console.error(err);
        }
    };
    const handleGoEdit = () => {
        navigate(`/user/client/${clientId}/files/edit/${file.id}`)
    }

    return (
        <div className={"row pb-2"}>
            <div className={"col-12"}>
                <div className={"card card-body border clickable-element"}>
                        <div className={`row justify-content-between `}>
                            <div className={"col-2 align-self-center clickable-element"} onClick={handleOpenFile}>
                                <RoundedIcon icon={iconClass} size={"md"}/>
                            </div>
                        <div className={"col-8 align-self-center clickable-element"} onClick={handleOpenFile}>
                            <span className={"fw-semibold"}>
                                {file.nome}
                            </span>
                            <span className={"fw-semibold d-block"}>
                                  {t("filesComponent:type")}: {t(fileType)}
                            </span>
                        </div>
                        <div className={"col-2 align-self-center text-end clickable-element"} onClick={handleShowOptions}>
                            <i className={"fa-solid fa-ellipsis"}/>
                        </div>
                    </div>
                </div>
            </div>
            <Modal show={showOptionsFile} onHide={handleShowOptions} centered>
                <ModalBody>
                    <div className={"row"}>
                        <div className={"col-12"}>
                            <div className={"row justify-content-between pb-3"}>
                                <div className={"col-auto"}>
                                    <span className={"fw-semibold text-start fs-5"}>{t("files:whatYouWant")}</span>
                                </div>
                                <div className={"col-auto cursor-pointer"} onClick={handleShowOptions}>
                                    <i className={"fa-regular fa-times"}/>
                                </div>
                            </div>
                            <div className={"d-grid gap-2"}>
                                <button className={"btn btn-outline-primary w-100"}
                                        onClick={() => handleDownload(file)}
                                        disabled={isDownloading}
                                >
                                    {t("filesComponent:download")}
                                </button>
                                <button className={"btn btn-outline-primary w-100"} onClick={handleGoEdit}>
                                    {t("filesComponent:edit")}
                                </button>
                                <button className={"btn btn-outline-danger w-100"} onClick={handleDeleteModal}>
                                    {t("filesComponent:delete")}
                                </button>
                            </div>
                        </div>
                    </div>
                </ModalBody>
            </Modal>
            <Modal show={showDeleteFile} onHide={handleDeleteModal} centered>
                <ModalBody>
                    <ChangeStatus
                        icon={"fa-regular fa-circle-exclamation"}
                        iconColor={"text-danger"}
                        title={t("filesComponent:areYouSure")}
                        subtitle={t("filesComponent:actionCannotBeUndone")}
                    />
                    <div className={"row p-3 gap-2"}>
                        <button className={"btn btn-danger"} onClick={handleDeleteFile}>
                            {t("filesComponent:yesDelete")}
                        </button>
                        <button className={"btn btn-outline-danger"} onClick={handleDeleteModal}>
                            {t("filesComponent:close")}
                        </button>
                    </div>
                </ModalBody>
            </Modal>

        </div>
    )
}

export default FileCard;
