import {useState} from "react";
import {imageResizer} from "../../utils/imageresizer/imageResizer";
import uploadFile from "../../utils/fileupload/s3FileUpload";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import RoundedIcon from "../rounded-icon/RoundedIcon";

const OnlineEvaluationUpdatePhoto = ({onImageUpload, fieldName, user, selectedClient}) => {
    const [preview, setPreview] = useState(null);
    const [loading, setLoading] = useState(false);
    const {t} = useTranslation();
    useComponentTranslations('evaluationOnlineComponents', {
        "en-US": enUS,
        "pt-BR": ptBR,
        "es-ES": esES,
        "pt-PT": ptPT
    });

    const handleFileChange = async (event) => {
        const file = event.target.files[0];
        if (!file) return;
        setLoading(true);

        try {
            const localPreview = URL.createObjectURL(file);
            setPreview(localPreview);

            const imgResized = await imageResizer(file);
            const imgUrl = await uploadFile(imgResized, user.id, selectedClient.id, 'onlineevaluation');
            onImageUpload(imgUrl);
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const removeImage = () => {
        setPreview(null);
        onImageUpload(null, fieldName);
    };

    return (
        <div className="d-flex flex-column align-items-center">
            {preview ? (
                <div className="position-relative">
                    <img
                        src={preview}
                        alt="Preview"
                        className="img-thumbnail mb-2"
                        style={{maxWidth: "350px", maxHeight: "350px"}}
                    />
                    <button
                        type="button"
                        className="btn btn-sm btn-danger position-absolute top-0 end-0"
                        onClick={removeImage}
                        disabled={loading}
                    >
                        <i className="fa fa-times"/>
                    </button>
                </div>
            ) : (
                <>
                    <RoundedIcon icon={"fa-image"} size={"lg"}/>
                    <div className={"pt-2"}>
                        <span className={"text-center"}>
                            {t("evaluationOnlineComponents:sendApicture")}
                        </span>
                    </div>
                    <label className="btn btn-primary mt-3">
                        <i className="fa-solid fa-upload me-2"/>
                        {t("evaluationOnlineComponents:selectPhoto")}
                        <input
                            type="file"
                            className="d-none"
                            accept="image/*"
                            onChange={handleFileChange}
                            disabled={loading}
                        />
                    </label>
                </>
            )}
        </div>
    );
};

export default OnlineEvaluationUpdatePhoto;
