export const getCategory = (cat) => {
    switch (cat) {
        case 1:
            return `weightlifting`;
        case 2:
            return `aerobic`;
        case 3:
            return `functional`;
        case 4:
            return `stretching`;
        case 5:
            return `homeTraining`;
        case 6:
            return `mobility`;
        case 7:
            return `rubberBand`;
        case 8:
            return `pilates`;
        case 9:
            return `officeExercise`;
        default:
            return cat;
    }
}

export const getMuscle = (cat) => {
    switch (cat) {
        case 1:
            return `chest`;
        case 2:
            return `back`;
        case 3:
            return `biceps`;
        case 4:
            return `triceps`;
        case 5:
            return `lowerBody`;
        case 6:
            return `shoulder`;
        case 7:
            return `abs`;
        case 8:
            return `forearm`;
        case 12:
            return `other`;
        default:
            if (Number(cat)) {
                return ""
            }
            return cat;
    }
}

export const getExerciseName = (hit, language) => {
    if (hit.userId > 0) {
        return hit.nome;
    }
    switch (language) {
        case language.includes("en"):
            return hit.nameUs
        case language.includes("es"):
            return hit.nameEs
        default:
            return hit.nome;
    }
}

export const transformExercise = (exercise) => {

    const {
        id,
        name,
        name_en_US,
        name_es_ES,
        urlMedia,
        urlPoster,
        exerciseGroup = {},
        exerciseCategory = {},
        mediaType,
        idUser,
    } = exercise;

    const transformedGroup = exerciseGroup.idUser > 0 ? exerciseGroup.nome : exerciseGroup.id;
    const transformedCategory = exerciseCategory.userId > 0 ? exerciseCategory.name : exerciseCategory.id;
    return {
        nome: name,
        url_media: urlMedia,
        url_poster: urlPoster,
        group: transformedGroup,
        category: transformedCategory,
        objectID: String(id),
        mediaType: mediaType,
        userId: idUser,
        nameUs: name_en_US,
        nameEs: name_es_ES
    };
}

export const translateExerciseName = (ex, language) => {
    if(ex.idUser > 0)
        return ex.name
    if (language === "pt-BR" || language === "pt-PT") {
        return ex.name
    } else if (language === "es-ES") {
        return ex.name_es_ES
    } else {
        return ex.name_en_US
    }

}