import Page from "../../components/page/Page";
import {useDispatch, useSelector} from "react-redux";
import {
    getCustomLoading, selectCustomModel,
    selectSubmitResult,
    selectSubmitLoading
} from "../../store/custom-evaluation/customEvaluationSelector";
import {useNavigate, useParams} from "react-router-dom";
import CustomModelField from "../../components/custom-evaluation/CustomModelField";
import {FieldArray, Form, Formik} from "formik";
import {useCallback, useEffect, useState} from "react";
import {resetFormSent, saveCustom} from "../../store/custom-evaluation/customEvaluationReducer";
import {useTranslation} from "react-i18next";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import i18n from "i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import ptBR from "./locales/pt-br.json";
import enUS from "./locales/en-us.json";
import {
    buildCustomEditModelRoute,
    buildCustomModelsRoute
} from "../../utils/client/evaluationRoutes";
import EvaluationSubmitButton from "../../components/evaluation-components/EvaluationSubmitButton";
import EvaluationSuccessCard from "../../components/evaluation-components/EvaluationSuccessCard";
import {EVALUATION_FLOWS} from "../../utils/evaluation/flows";
import {isMatchingSubmitSuccess} from "../../utils/evaluation/successFlow";

const CustomEvaluationCreateModel = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id} = useParams();
    const {t} = useTranslation();
    const loadingCustom = useSelector(getCustomLoading);
    const createdModel = useSelector(selectCustomModel);
    const submitResult = useSelector(selectSubmitResult);
    const submitLoading = useSelector(selectSubmitLoading);
    const [showDefaultFields, setShowDefaultFields] = useState(true);
    const showSuccess = isMatchingSubmitSuccess(submitResult, {
        action: "create",
        flow: EVALUATION_FLOWS.CUSTOM_MODEL_CREATE,
        clientId: id
    });
    syncMomentLocale(i18n.language);
    useComponentTranslations('customEvaluation', {"es-ES": esES, "pt-PT": ptPT, "pt-BR": ptBR, "en-US": enUS})

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    const initialValues = {
        modelName: '',
        fields: [
            {question: '', type: 'text', value: ''},
        ],
    };

    const handleGoBackPage = () => {
        navigate(buildCustomModelsRoute(id));
    };

    const handleGoEdit = useCallback(() => {
        dispatch(resetFormSent());
        navigate(buildCustomEditModelRoute(id, createdModel?.id));
    }, [navigate, dispatch, id, createdModel]);

    const handleSubmit = (values) => {
        const typeMapping = {text: 0, number: 1, image: 2};
        const payload = {
            tipo: values.modelName,
            campos: values.fields.map((field) => ({
                campo: field.question,
                tipo: typeMapping[field.type],
            })),
        };
        dispatch(saveCustom(payload, {
            flow: EVALUATION_FLOWS.CUSTOM_MODEL_CREATE,
            clientId: id
        }));
    };

    const handleShowHide = () => {
        setShowDefaultFields(prev => !prev);
    };

    return (
        <Page goBackLink={handleGoBackPage} title={t("customEvaluation:createModel")} loading={loadingCustom}
              pb={"pb-2"}>
            {!showSuccess ? (
                <div className={"card card-body border-0"}>
                    <Formik
                        initialValues={initialValues}
                        enableReinitialize
                        onSubmit={handleSubmit}
                    >
                        {({values, errors, touched, handleChange}) => (
                            <Form>
                                <div className={"mb-2"}>
                                    <label htmlFor="modelName" className={"form-label fw-semibold"}>
                                        {t("customEvaluation:modelName")}
                                    </label>
                                    <input
                                        id="modelName"
                                        name="modelName"
                                        type="text"
                                        className={"form-control"}
                                        value={values.modelName}
                                        onChange={handleChange}
                                    />
                                    {touched.modelName && errors.modelName && (
                                        <div className="text-danger mt-1">{errors.modelName}</div>
                                    )}
                                </div>
                                <div className={"card card-body border-0 bg-secondary-subtle mb-2"}>
                                    <div
                                        className={"d-flex justify-content-between align-items-center"}
                                        style={{cursor: 'pointer'}}
                                        onClick={handleShowHide}
                                    >
                                        <span className={"fw-semibold"}>{t("customEvaluation:patternsFields")}</span>
                                        <i className={`fa-solid fa-chevron-${showDefaultFields ? 'up' : 'down'}`}/>
                                    </div>
                                    {showDefaultFields && (
                                        <div className={"mt-3"}>
                                            <span className={"fw-semibold"}>{t("customEvaluation:theFields")}</span>
                                            <ul className={"mb-2"}>
                                                <li>{t("customEvaluation:age")}</li>
                                                <li>{t("customEvaluation:evaluationDate")}</li>
                                                <li>{t("customEvaluation:nextEvaluationDate")}</li>
                                                <li>{t("customEvaluation:height")}</li>
                                                <li>{t("customEvaluation:weight")}</li>
                                                <li>{t("customEvaluation:gender")}</li>
                                                <li>{t("customEvaluation:observation")}</li>
                                            </ul>
                                            <span className={"fw-semibold"}>
                                            {t("customEvaluation:patternAdd")}
                                        </span>
                                        </div>
                                    )}
                                </div>
                                <FieldArray name="fields">
                                    {({push, remove}) => (
                                        <>
                                            {values.fields.map((_, index) => (
                                                <CustomModelField
                                                    key={index}
                                                    questionName={`fields[${index}].question`}
                                                    typeName={`fields[${index}].type`}
                                                    valueName={`fields[${index}].value`}
                                                    onRemove={() => remove(index)}
                                                />
                                            ))}
                                            <button
                                                type="button"
                                                className={"btn btn-link text-primary my-2 w-100"}
                                                onClick={() => push({question: '', type: 'text', value: ''})}
                                            >
                                                <i className={"fa-regular fa-plus me-1"}/>
                                                <span>{t("customEvaluation:addQuestion")}</span>
                                            </button>
                                        </>
                                    )}
                                </FieldArray>
                                <div className={"mt-2"}>
                                    <EvaluationSubmitButton
                                        label={t("customEvaluation:saveModel")}
                                        loadingLabel={t("customEvaluation:saveModel")}
                                        isSubmitting={submitLoading}
                                    />
                                </div>
                            </Form>
                        )}
                    </Formik>
                </div>
            ) : (
                <div className={"row justify-content-center d-flex "}>
                    <div className={"col-12"}>
                        <EvaluationSuccessCard
                            title={t("customEvaluation:createdSuccessfully")}
                            primaryLabel={t("customEvaluation:showModel")}
                            secondaryLabel={t("customEvaluation:return")}
                            onPrimary={handleGoEdit}
                            onSecondary={handleGoBackPage}
                            primaryDisabled={!createdModel?.id}
                        />
                    </div>
                </div>
            )}
        </Page>
    )
}

export default CustomEvaluationCreateModel;
