import {useEffect, useMemo, useRef, useState} from "react";
import Select from "react-select";
import he from "he";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./remote-multi-select-locales/en-us.json";
import ptBR from "./remote-multi-select-locales/pt-br.json";
import esES from "./remote-multi-select-locales/es-es.json";
import ptPT from "./remote-multi-select-locales/pt-pt.json";
import {
    resolveClientSelectOptionsAPI,
    searchClientSelectOptionsAPI
} from "../../api/client/clientActions";

const DEFAULT_PAGE_SIZE = 20;

const mergeUniqueOptions = (...optionGroups) => {
    const optionMap = new Map();

    optionGroups.flat().forEach((option) => {
        if (!option) {
            return;
        }

        optionMap.set(Number(option.value), option);
    });

    return Array.from(optionMap.values());
};

const normalizeOption = (option) => {
    if (!option) {
        return null;
    }

    const value = Number(option.value ?? option.id);
    if (Number.isNaN(value)) {
        return null;
    }

    return {
        value,
        label: he.decode(option.label || ""),
        secondaryLabel: option.secondaryLabel || option.description || "",
        isPlaceholder: Boolean(option.isPlaceholder)
    };
};

const formatMessage = (message, fallback) => {
    if (typeof message === "function") {
        return message();
    }

    return message || fallback;
};

const ClientRemoteMultiSelect = ({
    valueIds = [],
    onChangeIds,
    searchScope = "active",
    resolveScope = searchScope,
    placeholder,
    disabled = false,
    specialOptions = [],
    noOptionsMessage,
    loadingMessage,
    onBlur,
    onSelectionStateChange,
    pageSize = DEFAULT_PAGE_SIZE,
    className = "basic-multi-select",
    classNamePrefix = "select"
}) => {
    const {t} = useTranslation();
    const [menuIsOpen, setMenuIsOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState("");
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
    const [loadedOptions, setLoadedOptions] = useState([]);
    const [resolvedOptions, setResolvedOptions] = useState([]);
    const [currentPage, setCurrentPage] = useState(0);
    const [totalPages, setTotalPages] = useState(0);
    const [searchLoading, setSearchLoading] = useState(false);
    const [resolveLoading, setResolveLoading] = useState(false);
    const [searchError, setSearchError] = useState(false);
    const [resolveError, setResolveError] = useState(false);
    const [paginationError, setPaginationError] = useState(false);
    const [searchRetryKey, setSearchRetryKey] = useState(0);
    const [resolveRetryKey, setResolveRetryKey] = useState(0);
    const [paginationRetryPage, setPaginationRetryPage] = useState(null);
    const searchRequestRef = useRef(0);
    const resolveRequestRef = useRef(0);

    useComponentTranslations('clientRemoteMultiSelect', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const normalizedSpecialOptions = useMemo(
        () => specialOptions.map(normalizeOption).filter(Boolean),
        [specialOptions]
    );

    useEffect(() => {
        const timeoutId = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm.trim());
        }, 300);

        return () => clearTimeout(timeoutId);
    }, [searchTerm]);

    useEffect(() => {
        if (!valueIds.length) {
            setResolvedOptions([]);
            setResolveError(false);
            return;
        }

        setResolvedOptions((previousOptions) => {
            const currentSelectedOptions = loadedOptions.filter((option) => valueIds.includes(option.value));
            const persistedOptions = previousOptions.filter((option) => valueIds.includes(option.value));
            return mergeUniqueOptions(persistedOptions, currentSelectedOptions);
        });
    }, [loadedOptions, valueIds]);

    useEffect(() => {
        if (!valueIds.length) {
            return;
        }

        const knownIds = new Set(
            mergeUniqueOptions(normalizedSpecialOptions, resolvedOptions, loadedOptions).map((option) => option.value)
        );
        const idsToResolve = valueIds
            .map((id) => Number(id))
            .filter((id) => !Number.isNaN(id) && !knownIds.has(id));

        if (!idsToResolve.length) {
            setResolveError(false);
            return;
        }

        let cancelled = false;
        const requestId = ++resolveRequestRef.current;
        setResolveLoading(true);
        setResolveError(false);

        (async () => {
            try {
                const response = await resolveClientSelectOptionsAPI({
                    ids: idsToResolve,
                    scope: resolveScope
                });

                if (cancelled || requestId !== resolveRequestRef.current) {
                    return;
                }

                const nextOptions = (response?.data || []).map(normalizeOption).filter(Boolean);
                setResolvedOptions((previousOptions) => {
                    const persistedOptions = previousOptions.filter((option) => valueIds.includes(option.value));
                    return mergeUniqueOptions(persistedOptions, nextOptions);
                });
                setResolveError(false);
            } catch (error) {
                if (!cancelled && requestId === resolveRequestRef.current) {
                    setResolveError(true);
                }
            } finally {
                if (!cancelled && requestId === resolveRequestRef.current) {
                    setResolveLoading(false);
                }
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [loadedOptions, normalizedSpecialOptions, resolveRetryKey, resolveScope, resolvedOptions, valueIds]);

    useEffect(() => {
        if (!menuIsOpen) {
            return;
        }

        let cancelled = false;
        const requestId = ++searchRequestRef.current;

        setLoadedOptions([]);
        setCurrentPage(0);
        setTotalPages(0);
        setSearchLoading(true);
        setSearchError(false);
        setPaginationError(false);
        setPaginationRetryPage(null);

        (async () => {
            try {
                const response = await searchClientSelectOptionsAPI({
                    scope: searchScope,
                    search: debouncedSearchTerm,
                    page: 1,
                    pageSize
                });

                if (cancelled || requestId !== searchRequestRef.current) {
                    return;
                }

                const payload = response?.data || {};
                const nextOptions = (payload.items || []).map(normalizeOption).filter(Boolean);

                setLoadedOptions(nextOptions);
                setCurrentPage(payload.page || 1);
                setTotalPages(payload.totalPages || 0);
            } catch (error) {
                if (!cancelled && requestId === searchRequestRef.current) {
                    setLoadedOptions([]);
                    setCurrentPage(0);
                    setTotalPages(0);
                    setSearchError(true);
                }
            } finally {
                if (!cancelled && requestId === searchRequestRef.current) {
                    setSearchLoading(false);
                }
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [debouncedSearchTerm, menuIsOpen, pageSize, searchRetryKey, searchScope]);

    const allOptions = useMemo(
        () => mergeUniqueOptions(normalizedSpecialOptions, resolvedOptions, loadedOptions),
        [loadedOptions, normalizedSpecialOptions, resolvedOptions]
    );

    const unresolvedValueIds = useMemo(() => {
        const knownOptionIds = new Set(allOptions.map((option) => option.value));

        return (valueIds || [])
            .map((value) => Number(value))
            .filter((value) => !Number.isNaN(value) && !knownOptionIds.has(value));
    }, [allOptions, valueIds]);

    const selectedOptions = useMemo(() => (
        (valueIds || [])
            .map((value) => {
                const normalizedValue = Number(value);
                if (Number.isNaN(normalizedValue)) {
                    return null;
                }

                const knownOption = allOptions.find((option) => option.value === normalizedValue);
                if (knownOption) {
                    return knownOption;
                }

                return normalizeOption({
                    value: normalizedValue,
                    label: t("clientRemoteMultiSelect:unresolvedClientOption", {id: normalizedValue}),
                    isPlaceholder: true
                });
            })
            .filter(Boolean)
    ), [allOptions, t, valueIds]);

    useEffect(() => {
        if (!onSelectionStateChange) {
            return;
        }

        onSelectionStateChange({
            unresolvedIds: unresolvedValueIds,
            hasResolveError: resolveError,
            isResolving: resolveLoading
        });
    }, [onSelectionStateChange, resolveError, resolveLoading, unresolvedValueIds]);

    const handleMenuScrollToBottom = async (targetPage = null) => {
        if (searchLoading || !menuIsOpen) {
            return;
        }

        const nextPage = targetPage ?? (currentPage + 1);
        if (!targetPage && currentPage >= totalPages) {
            return;
        }

        const requestId = ++searchRequestRef.current;
        setSearchLoading(true);
        setPaginationError(false);

        try {
            const response = await searchClientSelectOptionsAPI({
                scope: searchScope,
                search: debouncedSearchTerm,
                page: nextPage,
                pageSize
            });

            if (requestId !== searchRequestRef.current) {
                return;
            }

            const payload = response?.data || {};
            const nextOptions = (payload.items || []).map(normalizeOption).filter(Boolean);

            setLoadedOptions((previousOptions) => mergeUniqueOptions(previousOptions, nextOptions));
            setCurrentPage(payload.page || nextPage);
            setTotalPages(payload.totalPages || nextPage);
            setPaginationError(false);
            setPaginationRetryPage(null);
        } catch (error) {
            if (requestId === searchRequestRef.current) {
                setPaginationError(true);
                setPaginationRetryPage(nextPage);
            }
        } finally {
            if (requestId === searchRequestRef.current) {
                setSearchLoading(false);
            }
        }
    };

    const handleSearchRetry = () => {
        if (menuIsOpen) {
            setSearchRetryKey((currentValue) => currentValue + 1);
        }
    };

    const handleResolveRetry = () => {
        setResolveRetryKey((currentValue) => currentValue + 1);
    };

    const handlePaginationRetry = () => {
        if (paginationRetryPage !== null) {
            handleMenuScrollToBottom(paginationRetryPage);
        }
    };

    const resolvedNoOptionsMessage = () => {
        if (searchError) {
            return t("clientRemoteMultiSelect:couldNotLoadClients");
        }

        if (debouncedSearchTerm) {
            return formatMessage(noOptionsMessage, t("clientRemoteMultiSelect:noClientsFoundForSearch"));
        }

        return formatMessage(noOptionsMessage, t("clientRemoteMultiSelect:noClientsFound"));
    };

    return (
        <>
            <Select
                isMulti
                isDisabled={disabled}
                isLoading={searchLoading || resolveLoading}
                options={allOptions}
                value={selectedOptions}
                placeholder={placeholder}
                closeMenuOnSelect={false}
                hideSelectedOptions={false}
                className={className}
                classNamePrefix={classNamePrefix}
                filterOption={() => true}
                noOptionsMessage={resolvedNoOptionsMessage}
                loadingMessage={() => formatMessage(loadingMessage, t("clientRemoteMultiSelect:loading"))}
                onBlur={onBlur}
                onChange={(nextOptions) => {
                    onChangeIds((nextOptions || []).map((option) => option.value));
                }}
                onMenuOpen={() => setMenuIsOpen(true)}
                onMenuClose={() => {
                    setMenuIsOpen(false);
                    setSearchTerm("");
                    setDebouncedSearchTerm("");
                    setLoadedOptions([]);
                    setCurrentPage(0);
                    setTotalPages(0);
                    setSearchError(false);
                    setPaginationError(false);
                    setPaginationRetryPage(null);
                }}
                onInputChange={(nextValue, actionMeta) => {
                    if (actionMeta.action === "input-change") {
                        setSearchTerm(nextValue);
                    }

                    return nextValue;
                }}
                onMenuScrollToBottom={() => handleMenuScrollToBottom()}
                formatOptionLabel={(option, {context}) => {
                    if (context === "value" || option.isPlaceholder || !option.secondaryLabel) {
                        return <span>{option.label}</span>;
                    }

                    return (
                        <div className={"d-flex flex-column"}>
                            <span>{option.label}</span>
                            <small className={"text-secondary"}>{option.secondaryLabel}</small>
                        </div>
                    );
                }}
            />
            {resolveError && (
                <div className={"form-text text-danger d-flex align-items-center gap-2"}>
                    <span>{t("clientRemoteMultiSelect:couldNotLoadSelectedClients")}</span>
                    <button type={"button"} className={"btn btn-link btn-sm p-0"} onClick={handleResolveRetry}>
                        {t("clientRemoteMultiSelect:retry")}
                    </button>
                </div>
            )}
            {menuIsOpen && searchError && (
                <div className={"form-text text-danger d-flex align-items-center gap-2"}>
                    <span>{t("clientRemoteMultiSelect:couldNotLoadClients")}</span>
                    <button type={"button"} className={"btn btn-link btn-sm p-0"} onClick={handleSearchRetry}>
                        {t("clientRemoteMultiSelect:retry")}
                    </button>
                </div>
            )}
            {menuIsOpen && paginationError && (
                <div className={"form-text text-danger d-flex align-items-center gap-2"}>
                    <span>{t("clientRemoteMultiSelect:couldNotLoadMoreClients")}</span>
                    <button type={"button"} className={"btn btn-link btn-sm p-0"} onClick={handlePaginationRetry}>
                        {t("clientRemoteMultiSelect:retry")}
                    </button>
                </div>
            )}
        </>
    );
};

export default ClientRemoteMultiSelect;
