import {useDispatch, useSelector} from "react-redux";
import {useState, useEffect} from "react";
import {fetchYearlyFrequency, setYearlyFrequency} from "../../store/frequency-training/frequencyTrainingReducer";
import {useNavigate, useParams} from "react-router-dom";
import {selectFrequencyTrainingLoading, selectYearlyFrequency} from "../../store/frequency-training/frequencyTrainingSelector";
import Page from "../../components/page/Page";
import {useTranslation} from "react-i18next";
import {syncMomentLocale} from "../../utils/translation/localeUtils";
import "./../../assets/css/calendar.scss";
import RoundedIcon from "../../components/rounded-icon/RoundedIcon";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import LoadingBlock from "../../components/loader/LoadingBlock";

const FrequencyTrainingYear = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const {id} = useParams();
    const {t, i18n} = useTranslation();
    const yearlyFrequency = useSelector(selectYearlyFrequency);
    const loading = useSelector(selectFrequencyTrainingLoading)
    const [totalDays, setTotalDays] = useState(0);
    const [currentDate, setCurrentDate] = useState(new Date());
    const currentYear = new Date().getFullYear();

    syncMomentLocale(i18n.language);
    useComponentTranslations('frequencyTraining', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate(`/user/client/training-frequency/${id}/month`);
    };

    const handleMonthView = (month, year) => {
        if (month && year) {
            navigate(`/user/client/training-frequency/${id}/month/${month}/${year}`);
        } else {
            navigate(`/user/client/training-frequency/${id}/month`);
        }
    };

    const handlePrevYear = () => {
        const prevYear = new Date(currentDate.getFullYear() - 1, 0, 1);
        setCurrentDate(prevYear);
        dispatch(fetchYearlyFrequency({id, year: prevYear.getFullYear()}));
    };

    const handleNextYear = () => {
        const nextYear = new Date(currentDate.getFullYear() + 1, 0, 1);
        setCurrentDate(nextYear);
        dispatch(fetchYearlyFrequency({id, year: nextYear.getFullYear()}));
    };

    useEffect(() => {
        dispatch(fetchYearlyFrequency({id, year: currentDate.getFullYear()}));
        return () => dispatch(setYearlyFrequency(null))
    }, [currentDate, dispatch, id]);

    useEffect(() => {
        if (yearlyFrequency) {
            let totalHighlightedDays = 0;
            Object.values(yearlyFrequency.months).forEach(monthData => {
                const highlightedDaysInMonth = Object.values(monthData.days).filter(isHighlighted => isHighlighted).length;
                totalHighlightedDays += highlightedDaysInMonth;
            });
            setTotalDays(totalHighlightedDays);
        }
    }, [yearlyFrequency]);

    return (
        <Page title={t("frequencyTraining:pageTitle")} goBackLink={handleGoBack} xl={"3"}>
            <div className="card card-body mt-n3 border-0">
                <div className="yearly-view">
                    <div className="calendar-navigation">
                        <div className="row justify-content-between pt-2 pb-4">
                            <div className="col-4 align-self-center">
                                <button onClick={handlePrevYear} className="no-style-btn text-primary">
                                    <i className="fa-regular fa-chevron-left small"></i> {t("frequencyTraining:previous")}
                                </button>
                            </div>
                            <div className="col-4 text-center align-self-center">
                                <span className="d-block fw-bold fs-5 lh-1">{currentDate.getFullYear()}</span>
                            </div>
                            <div className="col-4 align-self-center text-end">
                                {
                                    currentDate.getFullYear() < currentYear &&
                                    <button onClick={handleNextYear} className="no-style-btn text-primary">
                                        {t("frequencyTraining:next")} <i className="fa-regular fa-chevron-right small"></i>
                                    </button>
                                }
                            </div>
                        </div>
                    </div>
                    {
                        !loading ? <div className="row">
                                {Object.entries(yearlyFrequency?.months || {}).map(([monthName, monthData], index) => {
                                    const month = monthData.month - 1;
                                    const year = monthData.year;
                                    const firstDayDate = new Date(year, month, 1);
                                    const firstDayOfWeek = firstDayDate.getDay();

                                    const daysInMonth = new Date(year, month + 1, 0).getDate();

                                    const daysArray = [];

                                    for (let i = 0; i < firstDayOfWeek; i++) {
                                        daysArray.push(null);
                                    }

                                    for (let day = 1; day <= daysInMonth; day++) {
                                        daysArray.push(day);
                                    }

                                    while (daysArray.length % 7 !== 0) {
                                        daysArray.push(null);
                                    }
                                    return (
                                        <div key={index} className="col-4 ">
                                            <div className="fw-semibold small  text-capitalize pb-2 d-block d-md-none">
                                                {t(`frequencyTraining:${monthName.toLocaleLowerCase()}`)}
                                            </div>
                                            <div className="fw-semibold    text-capitalize pb-2 d-none d-md-block">
                                                {t(`frequencyTraining:${monthName.toLocaleLowerCase()}`)}
                                            </div>
                                            <div className="calendar-grid clickable-element  mb-4" onClick={() => handleMonthView(monthData.month, monthData.year)}>
                                                {daysArray.map((day, dayIndex) => {
                                                    if (day === null) {
                                                        return (
                                                            <div
                                                                key={`empty-${dayIndex}`}
                                                                className="calendar-day empty"
                                                            ></div>
                                                        );
                                                    } else {
                                                        const isDayHighlighted = monthData?.days[day];
                                                        return (
                                                            <div
                                                                key={`day-${dayIndex}`}
                                                                className={`calendar-day ${isDayHighlighted ? 'highlighted' : ''}`}
                                                            >
                                                            </div>
                                                        );
                                                    }
                                                })}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div> :
                            <LoadingBlock height={"330px"}/>
                    }
                </div>
            </div>
            {
                totalDays > 0 &&
                <div className={"card card-body border-0 mt-3"}>
                    <div className={'row'}>
                        <div className={'col-auto'}>
                            <RoundedIcon icon={"fa-calendar-check"}/>
                        </div>
                        <div className={"col-auto text-default"}>
                            <span className={'d-block fw-semibold '}>{t("frequencyTraining:yourClientTrained")}</span>
                            <span className={"d-block lh-1"}>
                             <span className={"fw-semibold fs-3 text-primary"}>{totalDays}</span> <span
                                className={"text-primary"}>{totalDays === 1 ? t("frequencyTraining:dayThisYear") : t("frequencyTraining:daysThisYear")}</span>
                        </span>
                        </div>
                    </div>
                </div>
            }
        </Page>
    );
};

export default FrequencyTrainingYear;
