import i18n from "i18next";

export const formatBioIMC = (imc) => {
    if (imc === undefined || imc === null || isNaN(imc)) {
        return "";
    }

    const imcNumber = Number(imc);

    if (isNaN(imcNumber)) {
        return "";
    }

    let category = "";
    if (imcNumber < 18.5) {
        category = i18n.t("bioimpedanceEvaluation:imc.bellow_weight");
    } else if (imcNumber >= 18.5 && imcNumber <= 24.9) {
        category = i18n.t("bioimpedanceEvaluation:imc.normal_weight");
    } else if (imcNumber >= 25 && imcNumber <= 29.9) {
        category = i18n.t("bioimpedanceEvaluation:imc.above_weight");
    } else if (imcNumber >= 30 && imcNumber <= 34.9) {
        category = i18n.t("bioimpedanceEvaluation:imc.obesity_1");
    } else if (imcNumber >= 35 && imcNumber <= 39.9) {
        category = i18n.t("bioimpedanceEvaluation:imc.obesity_2");
    } else if (imcNumber >= 40) {
        category = i18n.t("bioimpedanceEvaluation:imc.morbid_obesity");
    }

    const formattedIMC = imcNumber.toFixed(2).replace(".", ",");

    return `${formattedIMC} ${category}`;
};
