import {createSlice} from "@reduxjs/toolkit";

const INITIAL_STATE = {
    user: null,
    paymentCountry: null,
    banners: null,
    loading: false,
    userLanguageUpdateLoading: false,
    userLanguageUpdateSuccess: false,
    userLanguageUpdateErrorCode: null,
    userProfilePictureUpdateLoading: false,
    userProfilePictureUpdateSuccess: false,
    userProfilePictureUpdateErrorCode: null,
    passwordUpdateLoading: false,
    passwordUpdateSuccess: false,
    passwordUpdateErrorCode: null,
    passwordRecoveryLoading: false,
    passwordRecoverySuccess: false,
    passwordRecoveryErrorCode: null,
    personalInformationUpdateLoading: false,
    personalInformationUpdateSuccess: false,
    personalInformationUpdateErrorCode: null
}

export const slice = createSlice({
    name: "user",
    initialState: INITIAL_STATE,
    reducers: {
        fetchBanners(state) {
            state.loading = true
        },
        setBanners(state, action) {
            state.banners = action.payload
            state.loading = false
        },
        getPaymentCountry(state) {
            state.loading = true
        },
        putPaymentCountry(state, action) {
            state.paymentCountry = action.payload
            state.loading = false
        },
        updateLoginToAc() {
        },
        setPaymentCountry() {
        },
        setPushId() {
        },
        setTimeZone() {
        },
        setDeviceInformation() {
        },
        updateUserLanguage(state) {
            state.userLanguageUpdateLoading = true
            state.userLanguageUpdateSuccess = false
            state.userLanguageUpdateErrorCode = null
        },
        userLanguageUpdated(state, action) {
            if (state.user) {
                state.user.language = action.payload
            }
            state.userLanguageUpdateLoading = false
            state.userLanguageUpdateSuccess = true
            state.userLanguageUpdateErrorCode = null
        },
        userLanguageUpdateFailed(state, action) {
            state.userLanguageUpdateLoading = false
            state.userLanguageUpdateSuccess = false
            state.userLanguageUpdateErrorCode = action.payload?.errorCode || "GENERIC"
        },
        clearUserLanguageUpdateState(state) {
            state.userLanguageUpdateLoading = false
            state.userLanguageUpdateSuccess = false
            state.userLanguageUpdateErrorCode = null
        },
        updateUserProfilePicture(state) {
            state.userProfilePictureUpdateLoading = true
            state.userProfilePictureUpdateSuccess = false
            state.userProfilePictureUpdateErrorCode = null
        },
        userProfilePictureUpdated(state, action) {
            if (state.user) {
                state.user.urlLogo = action.payload
            }
            state.userProfilePictureUpdateLoading = false
            state.userProfilePictureUpdateSuccess = true
            state.userProfilePictureUpdateErrorCode = null
        },
        userProfilePictureUpdateFailed(state, action) {
            state.userProfilePictureUpdateLoading = false
            state.userProfilePictureUpdateSuccess = false
            state.userProfilePictureUpdateErrorCode = action.payload?.errorCode || "GENERIC"
        },
        clearUserProfilePictureUpdateState(state) {
            state.userProfilePictureUpdateLoading = false
            state.userProfilePictureUpdateSuccess = false
            state.userProfilePictureUpdateErrorCode = null
        },
        updateUserPassword(state) {
            state.passwordUpdateLoading = true
            state.passwordUpdateSuccess = false
            state.passwordUpdateErrorCode = null
        },
        userPasswordUpdated(state) {
            state.passwordUpdateLoading = false
            state.passwordUpdateSuccess = true
            state.passwordUpdateErrorCode = null
        },
        userPasswordUpdateFailed(state, action) {
            state.passwordUpdateLoading = false
            state.passwordUpdateSuccess = false
            state.passwordUpdateErrorCode = action.payload?.errorCode || "GENERIC"
        },
        clearUserPasswordUpdateState(state) {
            state.passwordUpdateLoading = false
            state.passwordUpdateSuccess = false
            state.passwordUpdateErrorCode = null
        },
        recoverUserPassword(state) {
            state.passwordRecoveryLoading = true
            state.passwordRecoverySuccess = false
            state.passwordRecoveryErrorCode = null
        },
        userPasswordRecoverySucceeded(state) {
            state.passwordRecoveryLoading = false
            state.passwordRecoverySuccess = true
            state.passwordRecoveryErrorCode = null
        },
        userPasswordRecoveryFailed(state, action) {
            state.passwordRecoveryLoading = false
            state.passwordRecoverySuccess = false
            state.passwordRecoveryErrorCode = action.payload?.errorCode || "GENERIC"
        },
        clearUserPasswordRecoveryState(state) {
            state.passwordRecoveryLoading = false
            state.passwordRecoverySuccess = false
            state.passwordRecoveryErrorCode = null
        },
        updateUserPersonalInformation(state) {
            state.personalInformationUpdateLoading = true
            state.personalInformationUpdateSuccess = false
            state.personalInformationUpdateErrorCode = null
        },
        userPersonalInformationUpdated(state, action) {
            if (state.user) {
                state.user.nome = action.payload.nome
                state.user.sobrenome = action.payload.sobrenome
                state.user.mail = action.payload.mail
                state.user.waId = action.payload.waId
                state.user.registroCref = action.payload.registroCref
                state.user.instagramUser = action.payload.instagramUser
            }
            state.personalInformationUpdateLoading = false
            state.personalInformationUpdateSuccess = true
            state.personalInformationUpdateErrorCode = null
        },
        userPersonalInformationUpdateFailed(state, action) {
            state.personalInformationUpdateLoading = false
            state.personalInformationUpdateSuccess = false
            state.personalInformationUpdateErrorCode = action.payload?.errorCode || "GENERIC"
        },
        clearUserPersonalInformationUpdateState(state) {
            state.personalInformationUpdateLoading = false
            state.personalInformationUpdateSuccess = false
            state.personalInformationUpdateErrorCode = null
        },
        fetchUser(state) {
            state.loading = true;
        },
        setUser(state, action) {
            state.user = action.payload
            state.loading = false
        },
        onError(state) {
            state.loading = false
        }
    }
})

export const {
    setUser,
    fetchUser,
    setDeviceInformation,
    setPushId,
    setTimeZone,
    setPaymentCountry,
    updateUserLanguage,
    userLanguageUpdated,
    userLanguageUpdateFailed,
    clearUserLanguageUpdateState,
    updateLoginToAc,
    updateUserProfilePicture,
    userProfilePictureUpdated,
    userProfilePictureUpdateFailed,
    clearUserProfilePictureUpdateState,
    updateUserPassword,
    userPasswordUpdated,
    userPasswordUpdateFailed,
    clearUserPasswordUpdateState,
    recoverUserPassword,
    userPasswordRecoverySucceeded,
    userPasswordRecoveryFailed,
    clearUserPasswordRecoveryState,
    updateUserPersonalInformation,
    userPersonalInformationUpdated,
    userPersonalInformationUpdateFailed,
    clearUserPersonalInformationUpdateState,
    getPaymentCountry,
    putPaymentCountry,
    fetchBanners,
    setBanners,
    onError
} = slice.actions;
export const userReducer = slice.reducer
