const UNKNOWN_TIME_ZONE = "Etc/Unknown";

export const normalizePersistableUserTimeZone = (timeZone) => {
    if (typeof timeZone !== "string") {
        return null;
    }

    const normalizedTimeZone = timeZone.trim();
    if (!normalizedTimeZone || normalizedTimeZone.toLowerCase() === UNKNOWN_TIME_ZONE.toLowerCase()) {
        return null;
    }

    return normalizedTimeZone;
};

export const getPersistableBrowserTimeZone = () => {
    try {
        return normalizePersistableUserTimeZone(Intl.DateTimeFormat().resolvedOptions().timeZone);
    } catch (error) {
        return null;
    }
};
