import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect} from "react";
import {fetchClient} from "../../store/client/clientReducer";
import {useDispatch, useSelector} from "react-redux";
import {useNavigate, useParams} from "react-router-dom";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import Page from "../../components/page/Page";
import {
    resetFormSent
} from "../../store/physical-evaluation/physicalEvaluationReducer";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {useTranslation} from "react-i18next";
import EvaluationSuccessCard from "../../components/evaluation-components/EvaluationSuccessCard";
import {
    buildClientPhysicalRoute,
    buildPhysicalViewRoute
} from "../../utils/client/evaluationRoutes";
import {
    isSuccessTargetReady,
} from "../../utils/evaluation/successFlow";

const PhysicalEvaluationEnd = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id, physicalId} = useParams();
    const {t} = useTranslation();
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    useComponentTranslations('physicalEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});
    const targetPhysicalId = physicalId ?? null;

    const handleGoBackPage = () => {
        navigate(buildClientPhysicalRoute(id));
    };

    const handleView = () => {
        if (!targetPhysicalId) {
            return;
        }
        navigate(buildPhysicalViewRoute(id, targetPhysicalId));
    };

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(resetFormSent());
    }, [dispatch]);

    return (
        <>
            <AvatarHeader
                showGoBack={handleGoBackPage}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"}>
                <div className={"row justify-content-center d-flex "}>
                    <div className={"col-12"}>
                        <EvaluationSuccessCard
                            title={t("physicalEvaluation:evaluationCompleted")}
                            primaryLabel={t("physicalEvaluation:seeAnswers")}
                            secondaryLabel={t("physicalEvaluation:return")}
                            onPrimary={handleView}
                            onSecondary={handleGoBackPage}
                            primaryDisabled={!isSuccessTargetReady(targetPhysicalId)}
                        />
                    </div>
                </div>
            </Page>
        </>
    )
}

export default PhysicalEvaluationEnd
