import AvatarHeader from "../../components/avatar/AvatarHeader";
import React, {useEffect} from "react";
import LoadingBlock from "../../components/loader/LoadingBlock";
import EmptySet from "../../components/empty-set/EmptySet";
import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {getLoading, getPhysicalList} from "../../store/physical-evaluation/physicalEvaluationSelector";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {fetchClient} from "../../store/client/clientReducer";
import {clearAllPhysical, getAllPhysical} from "../../store/physical-evaluation/physicalEvaluationReducer";
import PhysicalEvaluationDeletedCard from "../../components/physical-evaluation/PhysicalEvaluationDeletedCard";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import {buildClientPhysicalRoute} from "../../utils/client/evaluationRoutes";

const PhysicalEvaluationDeleted = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id} = useParams();
    const { t } = useTranslation();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const physicalList = useSelector(getPhysicalList);
    useComponentTranslations('physicalEvaluation', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleGoBack = () => {
        navigate(buildClientPhysicalRoute(id));
    }

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id])

    useEffect(() => {
        dispatch(clearAllPhysical());
        dispatch(getAllPhysical({clientId: id, status: 1, type:0}));
    }, [dispatch, id]);

    return (
        <>
            <AvatarHeader
                md={"10"} lg={"8"}
                showGoBack={handleGoBack}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"} lg={"8"} md={"10"}>
                <div className={"py-2"}>
                    <div className={"card card-body border-0"}>
                        <span className={"pb-2 fw-semibold"}>{t("physicalEvaluation:deletedEvaluations")}</span>
                        {loading &&
                            <div className={"text-center mt-4"}>
                                <LoadingBlock/>
                            </div>
                        }
                        {!loading && (!physicalList || physicalList.length === 0) &&
                            <EmptySet
                                icon={"fa-regular fa-folder-open"}
                                message={t("physicalEvaluation:emptyDeleted")}
                            />
                        }
                        {!loading && physicalList && physicalList.length > 0 && (
                            <div className={"row justify-content-center d-flex"}>
                                <div className={"col-12"}>
                                    <div className={"px-2"}>
                                        {physicalList.map(physical => {
                                            return (
                                                <PhysicalEvaluationDeletedCard
                                                    key={physical.id}
                                                    title={physical.tipo}
                                                    physical={physical}
                                                />
                                            );
                                        })}
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </Page>
        </>
    )
}

export default PhysicalEvaluationDeleted;
