import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";

const WorkoutPresetCard = ({
    preset,
    isSystem = false,
    addMode = false,
    disabled = false,
    onOpen,
    onAdd
}) => {
    const {t} = useTranslation();

    useComponentTranslations("workoutPresetComponent", {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const handleOpen = () => {
        if (disabled) {
            return;
        }

        onOpen?.(preset);
    };

    const handleAdd = () => {
        if (disabled) {
            return;
        }

        onAdd?.(preset);
    };

    return (
        <div className="position-relative">
            <button
                type="button"
                className={`btn text-start w-100 card card-body border shadow-none ${addMode ? "pe-5" : ""} ${
                    isSystem
                        ? "bg-secondary-subtle border-light-subtle"
                        : "bg-white border-secondary-subtle"
                }`}
                disabled={disabled}
                onClick={handleOpen}
            >
                <span className="d-flex align-items-center gap-3">
                    <span className="flex-grow-1 overflow-hidden">
                        <span className="fw-semibold d-block">{preset.name}</span>
                        <span className="text-primary small fw-semibold d-block mt-1">
                            {t("workoutPresetComponent:viewPreset")}
                        </span>
                    </span>
                    {!addMode && (
                        <span className="text-dark flex-shrink-0">
                            <i className="fa-regular fa-chevron-right"/>
                        </span>
                    )}
                </span>
            </button>
            {addMode && (
                <button
                    type="button"
                    className="btn btn-link text-primary text-decoration-none p-0 position-absolute top-50 end-0 translate-middle-y me-3"
                    aria-label={`${t("workoutPresetComponent:addPreset")} ${preset.name}`}
                    disabled={disabled}
                    onClick={handleAdd}
                >
                    <i className="fa-regular fa-plus"/>
                </button>
            )}
        </div>
    );
};

export default WorkoutPresetCard;
