import Page from "../../components/page/Page";
import {useNavigate, useParams} from "react-router-dom";
import AvatarHeader from "../../components/avatar/AvatarHeader";
import {useDispatch, useSelector} from "react-redux";
import {isClientsLoading, selectSelectedClient} from "../../store/client/clientSelector";
import {chartFields} from "../../utils/onlineEvaluation/chartFields";
import LineChart from "../../components/charts/LineChart";
import {getLoading, getOnlineList} from "../../store/online-evaluation/evaluationOnlineSelector";
import React, {useEffect, useMemo} from "react";
import {getAllOnline} from "../../store/online-evaluation/evaluationOnlineReducer";
import {fetchClient} from "../../store/client/clientReducer";
import {useTranslation} from "react-i18next";
import useComponentTranslations from "../../utils/translation/useComponentTranslations";
import enUS from "./locales/en-us.json";
import ptBR from "./locales/pt-br.json";
import esES from "./locales/es-es.json";
import ptPT from "./locales/pt-pt.json";
import EmptySet from "../../components/empty-set/EmptySet";
import LoadingBlock from "../../components/loader/LoadingBlock";
import {buildOnlineEvaluationsRoute} from "../../utils/client/evaluationRoutes";
import {formatDate as formatDateValue} from "../../utils/translation/localeUtils";

const OnlineEvaluationCharts = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const {id} = useParams();
    const loading = useSelector(getLoading);
    const loadingClient = useSelector(isClientsLoading);
    const selectedClient = useSelector(selectSelectedClient);
    const onlineList = useSelector(getOnlineList);
    const {t, i18n} = useTranslation();
    useComponentTranslations('evaluationOnline', {"en-US": enUS, "pt-BR": ptBR, "es-ES": esES, "pt-PT": ptPT});

    const sortedOnlineList = useMemo(() => {
        if (!onlineList || onlineList.length === 0) return [];
        return [...onlineList].sort((a, b) => {
            const da = new Date(a.sentDate || a.data);
            const db = new Date(b.sentDate || b.data);
            return da - db;
        });
    }, [onlineList]);

    const compositionFields = useMemo(() => {
        if (sortedOnlineList.length < 2) return [];
        return chartFields
            .filter(field => field.category === "composicao")
            .map(field => ({
                ...field,
                label: t(`evaluationOnline:table.${field.labelKey}`)
            }));
    }, [sortedOnlineList, t]);

    const perimetryFields = useMemo(() => {
        if (sortedOnlineList.length < 2) return [];
        return chartFields
            .filter(field => field.category === "perimetria")
            .map(field => ({
                ...field,
                label: t(`evaluationOnline:table.${field.labelKey}`)
            }));
    }, [sortedOnlineList, t]);

    const handleGoBack = () => {
        navigate(buildOnlineEvaluationsRoute(id, "1"));
    };

    const hasNoData = useMemo(() => {
        if (sortedOnlineList.length < 2) return true;
        return sortedOnlineList.every(evaluation => {
            // consider it "no data" if there's no date at all
            if (!evaluation.sentDate && !evaluation.data) return true;
            return chartFields.every(field => {
                const value = evaluation[field.id];
                return value === undefined || value === null || value === 0 || value === "";
            });
        });
    }, [sortedOnlineList]);

    const chartLabels = useMemo(() => {
        if (sortedOnlineList.length === 0) return [];
        return sortedOnlineList.map(evaluation => {
            const date = evaluation.sentDate || evaluation.data;
            return date ? formatDateValue(date, i18n.language) : '';
        });
    }, [i18n.language, sortedOnlineList]);

    const transformedData = useMemo(() => {
        if (sortedOnlineList.length === 0) return {};

        const data = {};
        chartFields.forEach(field => {
            data[field.id] = [];
        });

        sortedOnlineList.forEach(evaluation => {
            chartFields.forEach(field => {
                if (field.id === "percentage") {
                    data[field.id].push(evaluation.percentage ?? 0);
                } else {
                    data[field.id].push(evaluation[field.id] ?? 0);
                }
            });
        });

        return data;
    }, [sortedOnlineList]);

    useEffect(() => {
        dispatch(fetchClient(id));
    }, [dispatch, id]);

    useEffect(() => {
        dispatch(getAllOnline({clientId: id, status: 0}));
    }, [dispatch, id]);

    return (
        <>
            <AvatarHeader
                md={"12"} lg={"12"} xl={"8"}
                showGoBack={handleGoBack}
                className={"pb-4 pt-2"}
                text={`${selectedClient?.nome} ${selectedClient?.sobrenome}`}
                url={selectedClient?.profileUrl}
                loading={loadingClient}
            />
            <Page contentHeader={false} pb={"pb-2"} lg={"12"} md={"12"} xl={"8"}>
                <div className={"row"}>
                    <div className={"col-12"}>
                        {loading || loadingClient ? (
                            <div className="text-center mt-4">
                                <LoadingBlock/>
                            </div>
                        ) : hasNoData ? (
                            <div className={"card card-body border-0"}>
                                <EmptySet
                                    icon={"fa-regular fa-folder-open"}
                                    message={t("evaluationOnline:noCharts")}
                                />
                            </div>
                        ) : (
                            <>
                                <div className={"row"}>
                                    {compositionFields.map(field => (
                                        <div key={field.id} className="col-md-6 mb-4">
                                            <div className="card card-body">
                                                <span className="card-title">{field.label}</span>
                                                <LineChart
                                                    key={field.id}
                                                    dataValues={transformedData[field.id] || []}
                                                    unit={field.unit}
                                                    chartLabels={chartLabels}
                                                />
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <span className="mb-3 fs-5 fw-semibold">{t("evaluationOnline:perimetry")}</span>
                                <div className={"row"}>
                                    {perimetryFields.map(field => (
                                        <div key={field.id} className="col-md-6 mb-4 mt-2">
                                            <div className="card card-body">
                                                <span className="card-title">{field.label}</span>
                                                <LineChart
                                                    key={field.id}
                                                    dataValues={transformedData[field.id] || []}
                                                    unit={field.unit}
                                                    chartLabels={chartLabels}
                                                />
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </>
                        )}
                    </div>
                </div>
            </Page>
        </>
    )
}

export default OnlineEvaluationCharts;
