export function* updateUserPasswordAsync(action) {
    try {
        yield call(updateUserPasswordAPI, action.payload)
        const tokenRefreshed = yield call(refreshUserTokenWithRetry)
        if (!tokenRefreshed) {
            yield put(userPasswordUpdateFailed({errorCode: "TOKEN_REFRESH_FAILED"}))
            yield put(setBadCheckPassword(true))
            return;
        }
        yield put(userPasswordUpdated())
    } catch (error) {
        const errorCode = error?.response?.data?.errorCode || "GENERIC"
        yield put(userPasswordUpdateFailed({errorCode}))
    }
}

export function* onUpdateUserPassword() {
    yield takeLatest(updateUserPassword.type, updateUserPasswordAsync);
}

export function* recoverUserPasswordAsync(action) {
    try {
        yield call(recoverUserPasswordAPI, {email: action.payload.email})
        yield put(userPasswordRecoverySucceeded())
    } catch (error) {
        const errorCode = error?.response?.data?.errorCode || "GENERIC"
        yield put(userPasswordRecoveryFailed({errorCode}))
    }
}

export function* onRecoverUserPassword() {
    yield takeLatest(recoverUserPassword.type, recoverUserPasswordAsync);
}

export function* updateUserPersonalInformationAsync(action) {
    try {
        const payload = action.payload;
        const currentUserEmail = yield select((state) => state.user?.user?.mail);
        const oldEmail = normalizeEmail(currentUserEmail);
        const nextEmail = normalizeEmail(payload.email);
        const shouldRefreshToken = oldEmail !== nextEmail;

        const response = yield call(updateUserPersonalInformationAPI, payload)
        const responseData = response?.data;
        const phoneValue = responseData?.waId || responseData?.whatsapp || payload.whatsapp;

        if (shouldRefreshToken) {
            const tokenRefreshed = yield call(refreshUserTokenWithRetry)
            if (!tokenRefreshed) {
                yield put(userPersonalInformationUpdateFailed({errorCode: "TOKEN_REFRESH_FAILED"}))
                yield put(setBadCheckPassword(true))
                return;
            }
        }

        yield put(userPersonalInformationUpdated({
            nome: decodeHtmlEntities(responseData?.nome || payload.nome),
            sobrenome: decodeHtmlEntities(responseData?.sobrenome || payload.sobrenome),
            mail: responseData?.mail || responseData?.email || payload.email,
            waId: formatPhoneWithPlus(phoneValue),
            registroCref: responseData?.registroCref ?? responseData?.cref ?? payload.cref,
            instagramUser: responseData?.instagramUser || responseData?.instagram || payload.instagram
        }))
    } catch (error) {
        const errorCode = error?.response?.data?.errorCode || "GENERIC"
        yield put(userPersonalInformationUpdateFailed({errorCode}))
    }
}

export function* onUpdateUserPersonalInformation() {
    yield takeLatest(updateUserPersonalInformation.type, updateUserPersonalInformationAsync);
}

export function* fetchUserAsync() {
    try {
        const response = yield call(fetchUserAPI)
        yield put(setUser({
            ...response.data,
            nome: decodeHtmlEntities(response?.data?.nome || ""),
            sobrenome: decodeHtmlEntities(response?.data?.sobrenome || "")
        }))
    } catch (error) {
        yield call(handleError, error, onError)
    }
}

export function* onFetchUser() {
    yield takeLatest(fetchUser.type, fetchUserAsync);
}

