export function* userSaga() {
    yield all([
        call(onFetchUser),
        call(onUpdateTimeZone),
        call(onUpdatePushId),
        call(onFetchUserDeviceInformation),
        call(onSetUserPaymentCountry),
        call(onUpdateLoginToAc),
        call(onFetchUserPaymentCountry),
        call(onFetchBanners),
        call(onUpdateUserLanguage),
        call(onUpdateUserProfilePicture),
        call(onUpdateUserPassword),
        call(onRecoverUserPassword),
        call(onUpdateUserPersonalInformation)
    ])
}
